function mkdir(path)
  os.execute('mkdir "' .. path .. '" >nul 2>nul')
end

function closeFileHandle(file)
  if file == nil then return false end
  local okMethod, closeMethod = pcall(function() return file.close end)
  if okMethod and type(closeMethod) == "function" then
    local okClose = pcall(closeMethod, file)
    if okClose then return true end
  end
  if io ~= nil and type(io.close) == "function" then
    local okClose = pcall(io.close, file)
    if okClose then return true end
  end
  return false
end

function readAll(path)
  local cleanPath = tostring(path or "")
  if cleanPath == "" then return nil end
  local okOpen, f = pcall(function() return io.open(cleanPath, "rb") end)
  if not okOpen or not f or (type(f) ~= "userdata" and type(f) ~= "table") then return nil end
  local okRead, text = pcall(function() return f:read("*a") end)
  closeFileHandle(f)
  if not okRead then return nil end
  return text
end

function safeString(value, fallback)
  local okText, text = pcall(function() return tostring(value == nil and (fallback or "") or value) end)
  if okText and type(text) == "string" then return text end
  if type(fallback) == "string" then return fallback end
  return ""
end

function writeAll(path, text)
  local cleanPath = tostring(path or "")
  if cleanPath == "" then return false end
  if cleanPath == RESULT_FILE or cleanPath == HEARTBEAT_FILE then
    local tempPath = cleanPath .. ".tmp"
    local okOpen, f = pcall(function() return io.open(tempPath, "wb") end)
    if not okOpen or not f or (type(f) ~= "userdata" and type(f) ~= "table") then return false end
    local okWrite = pcall(function() f:write(text or "") end)
    closeFileHandle(f)
    if not okWrite then return false end
    os.remove(cleanPath)
    local okRename, renameResult = pcall(function() return os.rename(tempPath, cleanPath) end)
    if okRename and renameResult ~= false then return true end
    os.remove(tempPath)
    return false
  end
  local okOpen, f = pcall(function() return io.open(cleanPath, "wb") end)
  if not okOpen or not f or (type(f) ~= "userdata" and type(f) ~= "table") then return false end
  local okWrite = pcall(function() f:write(text or "") end)
  closeFileHandle(f)
  return okWrite
end

STATE_ARRAY_CACHE = STATE_ARRAY_CACHE or {}
STATE_WRITE_QUEUE = STATE_WRITE_QUEUE or {}
STATE_WRITE_QUEUE_PENDING = STATE_WRITE_QUEUE_PENDING or {}
STATE_WRITE_QUEUE_MAX = STATE_WRITE_QUEUE_MAX or 4000

function normalizeJsonArrayText(text, maxBytes)
  local value = safeString(text, "[]")
  value = string.gsub(value, "^%s+", "")
  value = string.gsub(value, "%s+$", "")
  value = string.gsub(value, "^\239\187\191", "")
  local limit = math.max(1024, tonumber(maxBytes) or 1048576)
  if value == "" or string.sub(value, 1, 1) ~= "[" or string.sub(value, -1) ~= "]" or #value > limit then
    return "[]"
  end
  return value
end

function stateArrayRecordLooksSafe(record)
  local value = safeString(record, "")
  value = string.gsub(value, "^%s+", "")
  value = string.gsub(value, "%s+$", "")
  if value == "" or string.sub(value, 1, 1) ~= "{" or string.sub(value, -1) ~= "}" then return false end
  if string.sub(value, 1, 2) ~= '{"' then return false end
  if string.find(value, "%z") ~= nil or string.find(value, "[\1-\8\11\12\14-\31]") ~= nil then return false end
  if string.find(value, "{<", 1, true) ~= nil or string.find(value, "<t<", 1, true) ~= nil then return false end
  if string.find(value, '":', 1, true) == nil then return false end
  return true
end

function loadStateArrayCache(path, maxBytes, forceReload)
  local limit = math.max(1024, tonumber(maxBytes) or 1048576)
  local cache = STATE_ARRAY_CACHE[path]
  local nowClock = os.clock()
  if cache ~= nil and not forceReload then
    cache.maxBytes = math.max(tonumber(cache.maxBytes) or 0, limit)
    if cache.dirty or (nowClock - (cache.loadedAt or 0)) <= 0.75 then
      return cache
    end
  end
  local text = normalizeJsonArrayText(readAll(path) or "[]", limit)
  local rows = {}
  for object in text:gmatch("%b{}") do
    if stateArrayRecordLooksSafe(object) then table.insert(rows, object) end
  end
  cache = {
    path = path,
    rows = rows,
    maxBytes = limit,
    approxBytes = #text,
    dirty = false,
    loadedAt = nowClock
  }
  STATE_ARRAY_CACHE[path] = cache
  return cache
end

function queueStateFlushPath(path)
  local cleanPath = tostring(path or "")
  if cleanPath == "" then return false end
  if STATE_WRITE_QUEUE_PENDING[cleanPath] then return true end
  if #(STATE_WRITE_QUEUE or {}) >= STATE_WRITE_QUEUE_MAX then
    local removed = table.remove(STATE_WRITE_QUEUE, 1)
    if removed ~= nil then STATE_WRITE_QUEUE_PENDING[removed] = nil end
  end
  table.insert(STATE_WRITE_QUEUE, cleanPath)
  STATE_WRITE_QUEUE_PENDING[cleanPath] = true
  return true
end

function flushStateArrayCache(path)
  local cleanPath = tostring(path or "")
  if cleanPath == "" then return false end
  local cache = STATE_ARRAY_CACHE[cleanPath]
  if cache == nil then return true end
  local sourceRows = (type(cache.rows) == "table") and cache.rows or {}
  local rows = {}
  for _, row in ipairs(sourceRows) do
    local safeRow = safeString(row, "")
    if stateArrayRecordLooksSafe(safeRow) then table.insert(rows, safeRow) end
  end
  local limit = math.max(1024, tonumber(cache.maxBytes) or 1048576)
  local text = "[" .. table.concat(rows, ",") .. "]"
  while #text > limit and #rows > 1 do
    table.remove(rows, 1)
    text = "[" .. table.concat(rows, ",") .. "]"
  end
  if #text > limit then
    local last = rows[#rows] or "{}"
    rows = { last }
    text = "[" .. last .. "]"
  end
  cache.rows = rows
  cache.approxBytes = #text
  local okWrite = writeAll(cleanPath, text)
  if okWrite then
    cache.dirty = false
    cache.loadedAt = os.clock()
  end
  return okWrite
end

function appendJsonArray(path, recordJson, maxBytes)
  local cleanPath = tostring(path or "")
  if cleanPath == "" then return false end
  local limit = math.max(1024, tonumber(maxBytes) or 1048576)
  local cache = loadStateArrayCache(cleanPath, limit, false)
  if type(cache) ~= "table" then return false end
  local rows = (type(cache.rows) == "table") and cache.rows or {}
  local record = safeString(recordJson, "{}")
  if not stateArrayRecordLooksSafe(record) then return false end
  local nextSize = (tonumber(cache.approxBytes) or 2) + #record + ((#rows > 0) and 1 or 0)
  if nextSize > limit then
    rows = { record }
    cache.approxBytes = #record + 2
  else
    table.insert(rows, record)
    cache.approxBytes = nextSize
  end
  cache.rows = rows
  cache.maxBytes = limit
  cache.dirty = true
  cache.loadedAt = os.clock()
  queueStateFlushPath(cleanPath)
  return true
end

function readTail(path, maxBytes)
  local cleanPath = tostring(path or "")
  if cleanPath == "" then return nil end
  local okOpen, f = pcall(function() return io.open(cleanPath, "rb") end)
  if not okOpen or not f then return nil end
  local function safeSeek(file, mode, offset)
    if file == nil or type(file.seek) ~= "function" then return nil end
    local ok, value = pcall(function() return file:seek(mode, offset) end)
    if ok then return value end
    return nil
  end
  local size = safeSeek(f, "end", 0)
  if size == nil then
    local text = f:read("*a")
    closeFileHandle(f)
    return text
  end
  local limit = math.max(0, tonumber(maxBytes) or 0)
  local start = 0
  if limit > 0 and size > limit then start = size - limit end
  safeSeek(f, "set", start)
  local text = f:read("*a")
  closeFileHandle(f)
  if text == nil then return nil end
  if start > 0 then
    local cut = text:find("[\r\n]")
    if cut ~= nil then text = text:sub(cut + 1) end
  end
  return text
end

function fileSize(path)
  local cleanPath = tostring(path or "")
  if cleanPath == "" then return 0 end
  local okOpen, f = pcall(function() return io.open(cleanPath, "rb") end)
  if not okOpen or not f then return 0 end
  local size = 0
  if type(f.seek) == "function" then
    local ok, value = pcall(function() return f:seek("end", 0) end)
    if ok and value ~= nil then size = value end
  end
  closeFileHandle(f)
  return size
end

function readFromOffset(path, offset, maxBytes)
  local cleanPath = tostring(path or "")
  if cleanPath == "" then return "" end
  local okOpen, f = pcall(function() return io.open(cleanPath, "rb") end)
  if not okOpen or not f then return "" end
  local seekAvailable = type(f.seek) == "function"
  local size = 0
  if seekAvailable then
    local okSize, sizeValue = pcall(function() return f:seek("end", 0) end)
    if okSize and sizeValue ~= nil then size = sizeValue end
  end
  local start = math.max(0, tonumber(offset) or 0)
  if start > size then start = 0 end
  local limit = math.max(1, tonumber(maxBytes) or 65536)
  if size - start > limit then start = size - limit end
  if seekAvailable then pcall(function() f:seek("set", start) end) end
  local text = f:read("*a") or ""
  closeFileHandle(f)
  return text
end

INCREMENTAL_FILE_READ_OFFSETS = INCREMENTAL_FILE_READ_OFFSETS or {}

function readNewBytes(path, maxBytes, primeAtEnd)
  local cleanPath = tostring(path or "")
  if cleanPath == "" then return "" end
  local size = fileSize(cleanPath)
  if size <= 0 then return "" end
  local limit = math.max(1024, tonumber(maxBytes) or 65536)
  local currentOffset = INCREMENTAL_FILE_READ_OFFSETS[cleanPath]
  if currentOffset == nil then
    if primeAtEnd == true then
      INCREMENTAL_FILE_READ_OFFSETS[cleanPath] = size
      return ""
    end
    currentOffset = math.max(0, size - limit)
  end
  currentOffset = math.max(0, tonumber(currentOffset) or 0)
  if currentOffset > size then currentOffset = 0 end
  if (size - currentOffset) <= 0 then return "" end
  if (size - currentOffset) > limit then currentOffset = math.max(0, size - limit) end
  if (currentOffset % 2) ~= 0 then currentOffset = currentOffset + 1 end
  local data = readFromOffset(cleanPath, currentOffset, limit)
  INCREMENTAL_FILE_READ_OFFSETS[cleanPath] = size
  return data or ""
end

LOG_ROTATE_MAX_BYTES = LOG_ROTATE_MAX_BYTES or (512 * 1024)
LOG_LAST_TEXT = LOG_LAST_TEXT or nil
LOG_REPEAT_COUNT = LOG_REPEAT_COUNT or 0

function wallClockSeconds()
  local ok, value = pcall(function() return os.time() end)
  value = tonumber(ok and value or nil)
  if value ~= nil then return value end
  return math.floor(tonumber(os.clock()) or 0)
end

function wallTimeoutSeconds(timeoutMs, fallbackMs, minSeconds, maxSeconds)
  local ms = tonumber(timeoutMs) or tonumber(fallbackMs) or 1000
  local seconds = ms / 1000
  seconds = math.max(tonumber(minSeconds) or 0, math.min(seconds, tonumber(maxSeconds) or seconds))
  return math.max(1, math.ceil(seconds))
end

function wallDeadlineSeconds(timeoutMs, fallbackMs, minSeconds, maxSeconds)
  return wallClockSeconds() + wallTimeoutSeconds(timeoutMs, fallbackMs, minSeconds, maxSeconds)
end

function rotateLogIfNeeded()
  local okOpen, f = pcall(function() return io.open(LOG_FILE, "rb") end)
  if not okOpen or not f then return end
  if type(f.seek) ~= "function" then
    closeFileHandle(f)
    return
  end
  local okSize, sizeValue = pcall(function() return f:seek("end", 0) end)
  local size = (okSize and sizeValue) or 0
  closeFileHandle(f)
  if size < LOG_ROTATE_MAX_BYTES then return end
  pcall(function() os.remove(LOG_FILE .. ".1") end)
  pcall(function() os.rename(LOG_FILE, LOG_FILE .. ".1") end)
end

function appendLogLine(line)
  local ok = pcall(function()
    rotateLogIfNeeded()
    local okOpen, f = pcall(function() return io.open(LOG_FILE, "ab") end)
    if not okOpen or not f then return end
    pcall(function() f:write(os.date("!%Y-%m-%dT%H:%M:%SZ") .. " " .. tostring(line) .. "\n") end)
    closeFileHandle(f)
  end)
  return ok
end

function appendLog(text)
  if touchHeartbeat ~= nil then touchHeartbeat(false) end
  local line = tostring(text)
  if LOG_LAST_TEXT == line then
    LOG_REPEAT_COUNT = (LOG_REPEAT_COUNT or 0) + 1
    if LOG_REPEAT_COUNT == 2 or LOG_REPEAT_COUNT == 5 or LOG_REPEAT_COUNT == 10 or LOG_REPEAT_COUNT == 25 or LOG_REPEAT_COUNT == 50 or (LOG_REPEAT_COUNT % 100) == 0 then
      appendLogLine("previous message repeated " .. tostring(LOG_REPEAT_COUNT) .. " times: " .. line)
    end
    return
  end
  if LOG_LAST_TEXT ~= nil and (LOG_REPEAT_COUNT or 0) > 1 then
    appendLogLine("previous message final repeat count " .. tostring(LOG_REPEAT_COUNT) .. ": " .. tostring(LOG_LAST_TEXT))
  end
  LOG_LAST_TEXT = line
  LOG_REPEAT_COUNT = 1
  appendLogLine(line)
end

ADMIN_VERBOSE_LOGS = ADMIN_VERBOSE_LOGS or false

function appendAdminVerboseLog(text)
  if ADMIN_VERBOSE_LOGS then appendLog(text) end
end

function jsonEscape(value)
  local s = tostring(value or "")
  s = s:gsub("\\", "\\\\")
  s = s:gsub('"', '\\"')
  s = s:gsub("\r", "\\r")
  s = s:gsub("\n", "\\n")
  s = s:gsub("\t", "\\t")
  s = s:gsub("[%z\1-\8\11\12\14-\31]", function(ch)
    return string.format("\\u%04x", string.byte(ch))
  end)
  return s
end

function js(value)
  return '"' .. jsonEscape(value) .. '"'
end

function nowUtc()
  return os.date("!%Y-%m-%dT%H:%M:%SZ")
end

lastHeartbeatTouch = 0

touchHeartbeat = function(force)
  local now = os.time()
  if not force and now == lastHeartbeatTouch then return end
  lastHeartbeatTouch = now
  writeAll(HEARTBEAT_FILE, '{"utc":' .. js(nowUtc()) .. ',"bridge":"ScumNeDjinBridge"}')
end
function bridgeIniSettingValue(text, key)
  local wanted = tostring(key or ""):lower()
  for line in tostring(text or ""):gmatch("[^\r\n]+") do
    local clean = line:gsub("^%s+", ""):gsub("%s+$", "")
    if clean ~= "" and clean:sub(1, 1) ~= ";" and clean:sub(1, 1) ~= "#" then
      local k, v = clean:match("^([%w_]+)%s*=%s*(.-)%s*$")
      if k ~= nil and k:lower() == wanted then return tostring(v or "") end
    end
  end
  return ""
end

function bridgeIniBool(text, key, fallback)
  local value = bridgeIniSettingValue(text, key):lower():gsub("%s+", "")
  if value == "1" or value == "true" or value == "yes" or value == "on" then return true end
  if value == "0" or value == "false" or value == "no" or value == "off" then return false end
  return fallback == true
end

function bridgeGameThreadSchedulerWarning()
  local settings = readAll("UE4SS-settings.ini") or ""
  if settings == "" then return "" end
  local method = bridgeIniSettingValue(settings, "DefaultGameThreadExecutionMethod")
  if method == "" then method = bridgeIniSettingValue(settings, "DefaultExecuteInGameThreadMethod") end
  method = method:lower():gsub("%s+", ""):gsub("_", "")
  if method == "" then method = "processevent" end
  if method == "enginetick" and not bridgeIniBool(settings, "HookEngineTick", false) then
    return "UE4SS game-thread scheduler is EngineTick, but HookEngineTick=0. Game-thread tasks will be queued forever; panel/player commands will timeout. Set HookEngineTick=1 or use a working ProcessEvent scheduler."
  end
  if method == "processevent" and not bridgeIniBool(settings, "HookUObjectProcessEvent", false) then
    return "UE4SS game-thread scheduler is ProcessEvent, but HookUObjectProcessEvent=0. If commands timeout, enable the matching scheduler hook."
  end
  return ""
end

