    LAST_DELIVERY_EVENT_JSON = record
  end
  enqueueStateWrite(ACTION_STATE_FILE, record, 4 * 1024 * 1024)
end

function extractString(text, key)
  local source = tostring(text or "")
  local needle = '"' .. tostring(key or "") .. '"'
  local pos = source:find(needle, 1, true)
  if pos == nil then return nil end
  local colon = source:find(":", pos + #needle, true)
  if colon == nil then return nil end
  local quote = source:find('"', colon + 1, true)
  if quote == nil then return nil end
  local out = ""
  local escaped = false
  local i = quote + 1
  while i <= #source do
    local ch = source:sub(i, i)
    if escaped then
      if ch == '"' or ch == "\\" or ch == "/" then
        out = out .. tostring(ch or "")
      elseif ch == "n" then
        out = out .. "\n"
      elseif ch == "r" then
        out = out .. "\r"
      elseif ch == "t" then
        out = out .. "\t"
      elseif ch == "u" then
        local hex = source:sub(i + 1, i + 4)
        if hex:match("^%x%x%x%x$") then
          local cp = tonumber(hex, 16)
          local consumed = 4
          if cp ~= nil and cp >= 55296 and cp <= 56319 then
            local lowPrefix = source:sub(i + 5, i + 6)
            local lowHex = source:sub(i + 7, i + 10)
            if lowPrefix == "\\u" and lowHex:match("^%x%x%x%x$") then
              local low = tonumber(lowHex, 16)
              if low ~= nil and low >= 56320 and low <= 57343 then
                cp = 65536 + ((cp - 55296) * 1024) + (low - 56320)
                consumed = 10
              end
            end
          end
          out = out .. utf8FromCodepoint(cp)
          i = i + consumed
        else
          out = out .. "u"
        end
      else
        out = out .. tostring(ch or "")
      end
      escaped = false
    elseif ch == "\\" then
      escaped = true
    elseif ch == '"' then
      return out
    else
      out = out .. tostring(ch or "")
    end
    i = i + 1
  end
  return nil
end

function utf8FromCodepoint(codepoint)
  local cp = tonumber(codepoint) or 0
  cp = math.floor(cp)
  if cp < 0 then return "" end
  if cp <= 127 then
    return string.char(cp)
  elseif cp <= 2047 then
    return string.char(192 + math.floor(cp / 64), 128 + (cp % 64))
  elseif cp <= 65535 then
    return string.char(224 + math.floor(cp / 4096), 128 + (math.floor(cp / 64) % 64), 128 + (cp % 64))
  elseif cp <= 1114111 then
    return string.char(240 + math.floor(cp / 262144), 128 + (math.floor(cp / 4096) % 64), 128 + (math.floor(cp / 64) % 64), 128 + (cp % 64))
  end
  return ""
end

function extractNumber(text, key)
  local raw = text:match('"' .. key .. '"%s*:%s*([%-%.%d]+)')
  return tonumber(raw)
end

function extractStringAny(text, keys)
  -- P6: do not rely on a generic ipairs iterator in this parser helper.  The
  -- UE4SS Lua runtime has returned an invalid iterator state from this path,
  -- which made the read-only list_players fallback throw at this function.
  if type(keys) ~= "table" then return nil end
  for index = 1, #keys do
    local key = keys[index]
    local value = extractString(text, key)
    if value ~= nil and value ~= "" then return value end
  end
  return nil
end

function extractNumberAny(text, keys, fallback)
  if type(keys) ~= "table" then return fallback end
  for index = 1, #keys do
    local key = keys[index]
    local value = extractNumber(text, key)
    if value ~= nil then return value end
  end
  return fallback
end

function extractBool(text, key, fallback)
  local source = tostring(text or "")
  local trueStart = source:find('"' .. key .. '"%s*:%s*true')
  local falseStart = source:find('"' .. key .. '"%s*:%s*false')
  if trueStart ~= nil and (falseStart == nil or trueStart < falseStart) then return true end
  if falseStart ~= nil then return false end
  local textValue = extractString(source, key)
  if textValue ~= nil then
    local normalized = tostring(textValue):lower()
    if normalized == "true" or normalized == "1" or normalized == "yes" then return true end
    if normalized == "false" or normalized == "0" or normalized == "no" then return false end
  end
  return fallback
end

function extractBoolAny(text, keys, fallback)
  if type(keys) ~= "table" then return fallback end
  for index = 1, #keys do
    local key = keys[index]
    local value = extractBool(text, key, nil)
    if value ~= nil then return value end
  end
  return fallback
end

DEFAULT_LANGUAGE = "ru"
SUPPORTED_LANGUAGES = { ru = true, en = true }
-- Retains p5-loot-nearby-status-1 behavior; P6 only hardens the parser helper.
BRIDGE_VERSION = "scum-nedjin-bridge-v20260728-post-join-cache-seed-1"
LANGUAGE_STATE_FILE = STATE_DIR .. "\\player-languages.json"
PERMISSION_STATE_FILE = STATE_DIR .. "\\permissions.json"
DEFAULT_LANGUAGE_FILES = {
  ru = [[{
  "helpPrefix": "Команды",
  "helpLanguageHint": "Язык ответов: русский. Сменить язык: /lang en или /lang ru.",
  "hello": "Привет, {name}. Система сервера работает.",
  "playerFallback": "игрок",
  "languageUsage": "Использование: /lang ru или /lang en",
  "languageChanged": "Язык ответов переключён на русский.",
  "languageUnknown": "Неизвестный язык. Доступно: ru, en."
}]],
  en = [[{
  "helpPrefix": "Commands",
  "helpLanguageHint": "Reply language: English. Change language: /lang en or /lang ru.",
  "hello": "Hello, {name}. The server system is working.",
  "playerFallback": "player",
  "languageUsage": "Usage: /lang ru or /lang en",
  "languageChanged": "Reply language switched to English.",
  "languageUnknown": "Unknown language. Available: ru, en."
}]]
}

function normalizeLanguage(value)
  local text = tostring(value or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
  if text == "rus" or text == "russian" or text == "ru-ru" or text == "рус" or text == "русский" then return "ru" end
  if text == "eng" or text == "english" or text == "en-us" or text == "en-gb" then return "en" end
  if SUPPORTED_LANGUAGES[text] == true then return text end
  return ""
end

function ensureLanguageDefaults()
  mkdir(LANG_DIR)
  for lang, text in pairs(DEFAULT_LANGUAGE_FILES) do
    local path = LANG_DIR .. "\\" .. lang .. ".json"
    if readAll(path) == nil then writeAll(path, text) end
  end
end

function configuredDefaultLanguage()
  local config = configText("nedjin")
  local lang = normalizeLanguage(extractStringAny(config, { "DefaultLanguage", "defaultLanguage", "Language", "language" }) or "")
  if lang == "" then lang = DEFAULT_LANGUAGE end
  return lang
end

function playerLanguage(info)
  local defaultLang = configuredDefaultLanguage()
  info = info or {}
  local wantedSteam = tostring(info.steam or info.steamId or "")
  local wantedProfile = tostring(info.userProfileId or info.serverUserProfileId or "")
  local wantedName = tostring(info.name or ""):lower()
  local text = readAll(LANGUAGE_STATE_FILE) or ""
  if text == "" then return defaultLang end
  local found = ""
  for object in text:gmatch("%b{}") do
    local lang = normalizeLanguage(extractString(object, "language") or "")
    if lang ~= "" then
      local steam = tostring(extractString(object, "steamId") or "")
      local profile = tostring(extractString(object, "userProfileId") or "")
      local name = tostring(extractString(object, "name") or ""):lower()
      if (wantedSteam ~= "" and steam == wantedSteam) or
        (wantedProfile ~= "" and profile == wantedProfile) or
        (wantedName ~= "" and name ~= "" and name == wantedName) then
        found = lang
      end
    end
  end
  if found ~= "" then return found end
  return defaultLang
end

function languageMessage(lang, key)
  local normalized = normalizeLanguage(lang)
  if normalized == "" then normalized = configuredDefaultLanguage() end
  local text = readAll(LANG_DIR .. "\\" .. normalized .. ".json") or ""
  local message = extractString(text, key)
  if message ~= nil and message ~= "" then return message end
  if normalized ~= DEFAULT_LANGUAGE then
    message = extractString(readAll(LANG_DIR .. "\\" .. DEFAULT_LANGUAGE .. ".json") or "", key)
    if message ~= nil and message ~= "" then return message end
  end
  return nil
end

function applyVars(message, vars)
  local out = tostring(message or "")
  for key, value in pairs(vars or {}) do
    out = out:gsub("{" .. tostring(key) .. "}", tostring(value or ""))
  end
  return out
end

function tr(info, key, fallback, vars)
  return applyVars(languageMessage(playerLanguage(info), key) or fallback or key, vars)
end

function rememberPlayerLanguage(info, language)
  local lang = normalizeLanguage(language)
  if lang == "" then return false end
  local record = '{"utc":' .. js(nowUtc()) ..
    ',"steamId":' .. js((info or {}).steam or (info or {}).steamId or "") ..
    ',"name":' .. js((info or {}).name or "") ..
    ',"userProfileId":' .. js((info or {}).userProfileId or (info or {}).serverUserProfileId or "") ..
    ',"language":' .. js(lang) .. '}'
  return appendJsonArray(LANGUAGE_STATE_FILE, record, 512 * 1024)
end

function safeGet(obj, key)
  if obj == nil then return nil end
  local ok, value = pcall(function() return obj[key] end)
  if ok then return value end
  return nil
end

function safeCall(obj, method, ...)
  if obj == nil then return false, "object missing" end
  local fn = safeGet(obj, method)
  if fn == nil then return false, method .. " missing" end
  local ok, result = pcall(function(...) return obj[method](obj, ...) end, ...)
  if ok then return true, result end
  return false, tostring(result)
end

function findFirst(names)
  for _, name in ipairs(names) do
    local ok, obj = pcall(function() return FindFirstOf(name) end)
    if ok and obj ~= nil and isValidObject(obj) then return obj, name end
  end
  return nil, nil
end

RUNTIME_SCAN_BUDGET_LOG_AT = RUNTIME_SCAN_BUDGET_LOG_AT or 0

function runtimeBudgetNumber(names, fallback)
  if type(configNumber) == "function" then
    local ok, value = pcall(function() return configNumber("bridge-safety", names, fallback) end)
    if ok and tonumber(value) ~= nil then return tonumber(value) end
  end
  return fallback
end

function runtimeBudgetBool(names, fallback)
  if type(configBool) == "function" then
    local ok, value = pcall(function() return configBool("bridge-safety", names, fallback) end)
    if ok then return value == true end
  end
  return fallback == true
end

function runtimeBudgetLog(message)
  local now = os.time()
  if (now - (tonumber(RUNTIME_SCAN_BUDGET_LOG_AT) or 0)) < 15 then return end
  RUNTIME_SCAN_BUDGET_LOG_AT = now
  appendLog(message)
end

function findAll(names)
  local out = {}
  local seen = {}
  local budgetEnabled = runtimeBudgetBool({ "EnableRuntimeObjectScanBudget", "enableRuntimeObjectScanBudget" }, true)
  local maxObjects = math.max(1, math.floor(runtimeBudgetNumber({ "RuntimeObjectScanMaxObjects", "runtimeObjectScanMaxObjects" }, 256) or 256))
  local maxMs = math.max(1, runtimeBudgetNumber({ "RuntimeObjectScanMaxMilliseconds", "runtimeObjectScanMaxMilliseconds" }, 20) or 20)
  local started = os.clock()

  for _, name in ipairs(names) do
    if budgetEnabled and #out >= maxObjects then
      runtimeBudgetLog("runtime object scan budget hit before class=" .. tostring(name) .. " count=" .. tostring(#out))
      return out
    end
    if budgetEnabled and ((os.clock() - started) * 1000) > maxMs then
      runtimeBudgetLog("runtime object scan time budget hit before class=" .. tostring(name) .. " count=" .. tostring(#out))
      return out
    end
    local ok, arr = pcall(function() return FindAllOf(name) end)
    if ok and arr ~= nil then
      for _, obj in pairs(arr) do
        if budgetEnabled and #out >= maxObjects then
          runtimeBudgetLog("runtime object scan object budget hit class=" .. tostring(name) .. " count=" .. tostring(#out))
          return out
        end
        if budgetEnabled and ((os.clock() - started) * 1000) > maxMs then
          runtimeBudgetLog("runtime object scan time budget hit class=" .. tostring(name) .. " count=" .. tostring(#out))
          return out
        end
        local key = ""
        if obj ~= nil and isValidObject(obj) then
          pcall(function()
            local addr = obj:GetAddress()
            if addr ~= nil and addr ~= 0 then key = tostring(addr) end
          end)
          if key == "" then key = tostring(obj) end
        end
        if obj ~= nil and key ~= "" and not seen[key] then
          seen[key] = true
          table.insert(out, obj)
        end
      end
    end
  end
  return out
end

function scanFeatureEnabled(names, fallback)
  if type(configBool) == "function" then
    return configBool("bridge-safety", names, fallback) == true
  end
  return fallback == true
end

function vehicleRuntimeScanAllowed(allowRentalScoped)
  if scanFeatureEnabled({ "EnableVehicleRuntimeObjectScan", "enableVehicleRuntimeObjectScan" }, false) then return true end
  if allowRentalScoped == true and not scanFeatureEnabled({ "AllowRentalScopedVehicleRuntimeScan", "allowRentalScopedVehicleRuntimeScan" }, true) then
    return false
  end
  if allowRentalScoped == true and type(configBool) == "function" then
    return configBool("vehicle-rental", {
      "EnableRuntimeVehicleTrackAfterSpawn", "enableRuntimeVehicleTrackAfterSpawn",
      "EnableRuntimeVehicleReturnDestroy", "enableRuntimeVehicleReturnDestroy",
      "EnableRuntimeVehicleExpireDestroy", "enableRuntimeVehicleExpireDestroy"
    }, false) == true
  end
  return false
end

function firstProp(obj, keys)
  for _, key in ipairs(keys) do
    local value = safeGet(obj, key)
    if value ~= nil then return value end
  end
  return nil
end

isValidObject = function(obj)
  if obj == nil then return false end
  local ok, valid = pcall(function() return obj:IsValid() end)
  if ok then return valid == true end
  return false
end

function playerRpcChannel(pc)
  if pc == nil then return nil end
  local ok, rpc = pcall(function() return pc:GetPlayerRpcChannel() end)
  if ok and rpc ~= nil and isValidObject(rpc) then return rpc end
  rpc = firstProp(pc, {"PlayerRpcChannel", "_playerRpcChannel", "playerRpcChannel"})
  if rpc ~= nil and isValidObject(rpc) then return rpc end
  if not scanFeatureEnabled({ "AllowPlayerRpcChannelGlobalScan", "allowPlayerRpcChannelGlobalScan" }, false) then return nil end
  local channels = findAll({"PlayerRpcChannel", "ConZPlayerRpcChannel"})
  if #channels == 1 and isValidObject(channels[1]) then return channels[1] end
  return nil
end

function kismetSystemLibrary()
  local kismet = nil
  pcall(function() kismet = StaticFindObject("/Script/Engine.Default__KismetSystemLibrary") end)
  if kismet ~= nil and isValidObject(kismet) then return kismet end
  return findFirst({"KismetSystemLibrary"})
end

function gameplayStatics()
  local statics = nil
  pcall(function() statics = StaticFindObject("/Script/Engine.Default__GameplayStatics") end)
  if statics ~= nil and isValidObject(statics) then return statics end
  pcall(function() statics = StaticFindObject("/Script/Engine.GameplayStatics") end)
  if statics ~= nil and isValidObject(statics) then return statics end
  return findFirst({"GameplayStatics"})
end

function objectKey(obj)
  if obj == nil then return "" end
  local ok, addr = pcall(function() return obj:GetAddress() end)
  if ok and addr ~= nil and addr ~= 0 then return tostring(addr) end
  ok, addr = pcall(function() return tostring(obj) end)
  if ok and addr ~= nil then return tostring(addr) end
  return ""
end

function invalidRuntimeText(text)
  -- UE4SS can surface reflected FString/function-like proxies here.  A
  -- colon call on such a proxy can invoke an unexpected member during a
  -- read-only panel refresh.  Coerce through the Lua standard library and
  -- fail closed instead of allowing that value to escape the bridge loop.
  local okLower, lower = pcall(function() return string.lower(tostring(text or "")) end)
  if not okLower or type(lower) ~= "string" then return true end
  return lower == "" or
    lower == "unknown" or
    lower:find("fstring:", 1, true) ~= nil or
    lower:find("uobject:", 1, true) ~= nil or
    lower:find("uscriptstruct:", 1, true) ~= nil or
    lower:find("userdata:", 1, true) ~= nil or
    lower:find("fname:", 1, true) ~= nil or
    lower:find("function:", 1, true) ~= nil
end

function looksLikeSteamId(text)
  local s = tostring(text or "")
  return s:match("^%d+$") ~= nil and #s >= 15 and #s <= 20
end

function cleanText(text)
  if text == nil then return "" end
  text = tostring(text)
  text = text:gsub("^%s+", ""):gsub("%s+$", "")
  if text == "" then return "" end
  if invalidRuntimeText(text) then return "" end
  if text:match("^0x[%x]+$") then return "" end
  return text
end

function ueString(text)
  local value = tostring(text or "")
  if type(FString) == "function" then
    local ok, fstr = pcall(function() return FString(value) end)
    if ok and fstr ~= nil then return fstr end
  end
  return value
end

function ueName(text)
  local value = tostring(text or "")
  if type(FName) == "function" then
    local ok, fname = pcall(function() return FName(value) end)
    if ok and fname ~= nil then return fname end
  end
  return value
end

function ueText(text)
  local value = tostring(text or "")
  if type(FText) == "function" then
    local ok, ftext = pcall(function() return FText(value) end)
    if ok and ftext ~= nil then return ftext end
  end
  return ueString(value)
end

function valueText(value)
  if value == nil then return "" end
  local kind = type(value)
  if kind == "string" or kind == "number" then return cleanText(value) end
  local ok, text = pcall(function() return tostring(value) end)
  if ok then return cleanText(text) end
  return ""
end

function paramText(param)
  if param == nil then return "" end
  local ok, value = pcall(function()
    if type(param) == "userdata" and param.get ~= nil then return param:get() end
    return param
  end)
  if not ok then value = param end
  local text = valueText(value)
  if text ~= "" then return text end
  ok, text = pcall(function() return value:ToString() end)
  if ok then return cleanText(text) end
  return ""
end

function propText(obj, keys)
  for _, key in ipairs(keys) do
    local text = valueText(safeGet(obj, key))
    if text ~= "" then return text end
  end
  return ""
end

function propNumber(obj, keys)
  for _, key in ipairs(keys) do
    local value = safeGet(obj, key)
    if type(value) == "number" then return value end
  end
  return nil
end

function propBoolean(obj, keys)
  for _, key in ipairs(keys) do
    local value = safeGet(obj, key)
    if type(value) == "boolean" then return value end
  end
  return nil
end

function dbIdText(value)
  if value == nil then return "" end
  local ok, unwrapped = pcall(function()
    if type(value) == "userdata" and value.get ~= nil then return value:get() end
    return value
  end)
  if ok then value = unwrapped end

  local direct = valueText(value)
  if direct:match("^%d+$") then return direct end

  local raw = safeGet(value, "Value") or safeGet(value, "value") or safeGet(value, "_value")
  if type(raw) == "number" then return tostring(math.floor(raw)) end
  raw = valueText(raw)
  if raw:match("^%d+$") then return raw end

  local printed = ""
  pcall(function() printed = tostring(value) end)
  local fromValue = printed:match("Value%s*=%s*(%d+)") or printed:match("Value%s*:%s*(%d+)")
  if fromValue ~= nil then return fromValue end
  return ""
end

RUNTIME_ROOT_CACHE = RUNTIME_ROOT_CACHE or {}

function cachedRuntimeRoot(key)
  local entry = RUNTIME_ROOT_CACHE[key]
  if entry == nil then return nil, nil end
  local obj = entry.object
  if obj ~= nil and isValidObject(obj) then return obj, entry.route end
  RUNTIME_ROOT_CACHE[key] = nil
  return nil, nil
end

function rememberRuntimeRoot(key, obj, route)
  if obj ~= nil and isValidObject(obj) then
    RUNTIME_ROOT_CACHE[key] = { object = obj, route = route or key }
    return obj, route
  end
  RUNTIME_ROOT_CACHE[key] = nil
  return nil, nil
end

function gameModeRoot()
  local cached, route = cachedRuntimeRoot("gameMode")
  if cached ~= nil then return cached, route end
  local gm, gmRoute = findFirst({"BP_ConZGameMode_C", "ConZGameMode", "GameMode"})
  return rememberRuntimeRoot("gameMode", gm, gmRoute)
end

function gameStateRoot()
  local cached, route = cachedRuntimeRoot("gameState")
  if cached ~= nil then return cached, route end
  local gm = gameModeRoot()
  local gs = firstProp(gm, {"GameState"})
  if gs ~= nil and isValidObject(gs) and firstProp(gs, {"PlayerArray"}) ~= nil then
    return rememberRuntimeRoot("gameState", gs, "GameMode.GameState")
  end
  local found, foundRoute = findFirst({"BP_ConZGameState_C", "ConZGameState", "GameState"})
  if found ~= nil and isValidObject(found) and firstProp(found, {"PlayerArray"}) ~= nil then
    return rememberRuntimeRoot("gameState", found, foundRoute)
  end
  return nil, foundRoute
end

function worldRoot()
  local gm = gameModeRoot()
  if gm ~= nil then return gm end
  return gameStateRoot()
end

function worldSettingsRoot()
  local cached, route = cachedRuntimeRoot("worldSettings")
  if cached ~= nil then return cached, route end
  local found, foundRoute = findFirst({ "ConZWorldSettings", "BP_ConZWorldSettings_C", "WorldSettings" })
  if found ~= nil and isValidObject(found) then
    local hasConZManagers = firstProp(found, { "WeatherController2", "RadiationManager", "GlobalEncounterManager", "HuntingManager" }) ~= nil
    if hasConZManagers or tostring(foundRoute or "") == "ConZWorldSettings" then
      return rememberRuntimeRoot("worldSettings", found, foundRoute)
    end
  end
  return nil, foundRoute
end

function weatherControllerRoot()
  local cached, route = cachedRuntimeRoot("weatherController2")
  if cached ~= nil then return cached, route end

  local worldSettings, worldSettingsRoute = worldSettingsRoot()
  local controller = firstProp(worldSettings, { "WeatherController2", "weatherController2" })
  if controller ~= nil and isValidObject(controller) then
    return rememberRuntimeRoot("weatherController2", controller, tostring(worldSettingsRoute or "ConZWorldSettings") .. ".WeatherController2")
  end

  local found, foundRoute = findFirst({ "WeatherController2", "BP_WeatherController2_C", "BP_WeatherController1_C", "BP_WeatherController1_0_C" })
  if found ~= nil and isValidObject(found) then
    return rememberRuntimeRoot("weatherController2", found, "FindFirstOf:" .. tostring(foundRoute or "WeatherController2"))
  end
  return nil, "worldSettingsRoute=" .. tostring(worldSettingsRoute or "") .. "; controller missing"
end

function weatherFieldNumberJson(jsonKey, obj, keys)
  return js(jsonKey) .. ":" .. runtimeValueJson(propNumber(obj, keys))
end

function weatherFieldBooleanJson(jsonKey, obj, keys)
  return js(jsonKey) .. ":" .. runtimeValueJson(propBoolean(obj, keys))
end

function weatherSnapshotJson()
  local started = os.clock()
  local worldSettings, worldSettingsRoute = worldSettingsRoot()
  local controller, controllerRoute = weatherControllerRoot()
  local durationMs = math.floor((os.clock() - started) * 1000)

  if controller == nil or not isValidObject(controller) then
    return '{"available":false' ..
      ',"snapshotUtc":' .. js(nowUtc()) ..
      ',"durationMs":' .. tostring(durationMs) ..
      ',"source":"runtime-readonly"' ..
      ',"worldSettingsRoute":' .. js(worldSettingsRoute or "") ..
      ',"weatherRoute":' .. js(controllerRoute or "") ..
      ',"note":"WeatherController2 runtime object is not available; no admin command or broad scan was executed."}', "weather snapshot unavailable"
  end

  local fields = {
    '"available":true',
    '"snapshotUtc":' .. js(nowUtc()),
    '"durationMs":' .. tostring(durationMs),
    '"source":"runtime-readonly"',
    '"worldSettingsRoute":' .. js(worldSettingsRoute or ""),
    '"weatherRoute":' .. js(controllerRoute or ""),
    '"worldSettings":' .. nativeProbeObjectJson("worldSettings", worldSettings, worldSettingsRoute, {}),
    '"controller":' .. nativeProbeObjectJson("weatherController2", controller, controllerRoute, {}),
    weatherFieldNumberJson("timeOfDay", controller, { "_timeOfDay", "TimeOfDay", "timeOfDay" }),
    weatherFieldNumberJson("timeOfDaySpeed", controller, { "_timeOfDaySpeed", "TimeOfDaySpeed", "timeOfDaySpeed" }),
    weatherFieldNumberJson("sunriseTime", controller, { "_sunriseTime", "SunriseTime", "sunriseTime" }),
    weatherFieldNumberJson("sunsetTime", controller, { "_sunsetTime", "SunsetTime", "sunsetTime" }),
    weatherFieldNumberJson("rainIntensity", controller, { "_rainIntensity", "RainIntensity", "rainIntensity" }),
    weatherFieldNumberJson("snowIntensity", controller, { "_snowIntensity", "SnowIntensity", "snowIntensity" }),
    weatherFieldNumberJson("lightningRate", controller, { "_lightningRate", "LightningRate", "lightningRate" }),
    weatherFieldNumberJson("windIntensity", controller, { "_windIntensity", "WindIntensity", "windIntensity" }),
    weatherFieldNumberJson("windAzimuth", controller, { "_windAzimuth", "WindAzimuth", "windAzimuth" }),
    weatherFieldNumberJson("fogDensity", controller, { "_fogDensity", "FogDensity", "fogDensity" }),
    weatherFieldNumberJson("baseAirTemperature", controller, { "_baseAirTemperature", "BaseAirTemperature", "baseAirTemperature" }),
    weatherFieldNumberJson("airRelativeHumidity", controller, { "_airRelativeHumidity", "AirRelativeHumidity", "airRelativeHumidity" }),
    weatherFieldNumberJson("nighttimeDarkness", controller, { "_nighttimeDarkness", "NighttimeDarkness", "nighttimeDarkness" }),
    weatherFieldNumberJson("cirrostratusCoverage", controller, { "_cirrostratusCoverage", "CirrostratusCoverage", "cirrostratusCoverage" }),
    weatherFieldNumberJson("cumulonimbusCoverage", controller, { "_cumulonimbusCoverage", "CumulonimbusCoverage", "cumulonimbusCoverage" }),
    weatherFieldNumberJson("nimbostratusCoverage", controller, { "_nimbostratusCoverage", "NimbostratusCoverage", "nimbostratusCoverage" }),
    weatherFieldBooleanJson("shouldSimulateInGame", controller, { "_shouldSimulateInGame", "ShouldSimulateInGame", "shouldSimulateInGame" })
  }
  return "{" .. table.concat(fields, ",") .. "}", "weather snapshot"
end

RUNTIME_FOG_SPHERES = RUNTIME_FOG_SPHERES or {}

function fogSphereClassObject(attempts)
  attempts = attempts or {}
  local assetPath = "/Game/ConZ_Files/Blueprints/VolumetricFog/BP_FogSphere"
  local objectPath = assetPath .. ".BP_FogSphere_C"
  local loadCandidates = {
    assetPath,
    objectPath
  }
  for _, candidate in ipairs(loadCandidates) do
    local okLoad, loaded = pcall(function() return LoadAsset(candidate) end)
    table.insert(attempts, "LoadAsset(" .. tostring(candidate) .. ")=" .. (okLoad and (isValidObject(loaded) and ("ok:" .. objectFullName(loaded)) or "nil") or tostring(loaded)))
    if okLoad and loaded ~= nil and isValidObject(loaded) then
      local generated = firstProp(loaded, { "GeneratedClass", "_GeneratedClass" })
      if generated ~= nil and isValidObject(generated) then
        table.insert(attempts, "LoadAsset.generatedClass=" .. objectFullName(generated))
        return generated, "LoadAsset.generatedClass:" .. tostring(candidate), attempts
      end
    end
  end

  local findCandidates = {
    objectPath,
    "BlueprintGeneratedClass " .. objectPath,
    "BlueprintGeneratedClass'" .. objectPath .. "'",
    "Class " .. objectPath,
    "Class'" .. objectPath .. "'",
    "BP_FogSphere_C"
  }
  for _, candidate in ipairs(findCandidates) do
    local okFind, found = pcall(function() return StaticFindObject(candidate) end)
    table.insert(attempts, "StaticFindObject(" .. tostring(candidate) .. ")=" .. (okFind and (isValidObject(found) and ("ok:" .. objectFullName(found)) or "nil") or tostring(found)))
    if okFind and found ~= nil and isValidObject(found) then return found, "StaticFindObject:" .. tostring(candidate), attempts end
  end

  local okFirst, first = pcall(function() return FindFirstOf("BP_FogSphere_C") end)
  table.insert(attempts, "FindFirstOf(BP_FogSphere_C)=" .. (okFirst and (isValidObject(first) and ("ok:" .. objectFullName(first)) or "nil") or tostring(first)))
  if okFirst and first ~= nil and isValidObject(first) then return first, "FindFirstOf:BP_FogSphere_C", attempts end
  return nil, "BP_FogSphere_C class not loaded", attempts
end

function fogSetField(actor, field, value, attempts)
  attempts = attempts or {}
  local okSet, err = pcall(function() actor[field] = value end)
  table.insert(attempts, "set." .. tostring(field) .. "=" .. (okSet and "ok" or tostring(err)))
  return okSet
end

function fogCall(actor, method, attempts, ...)
  attempts = attempts or {}
  local okCall, result = safeCall(actor, method, ...)
  table.insert(attempts, tostring(method) .. "=" .. (okCall and "ok" or tostring(result)))
  return okCall, result
end

function fogSphereClearRuntime()
  local attempts = {}
  local destroyed = 0
  for _, actor in ipairs(RUNTIME_FOG_SPHERES or {}) do
    if actor ~= nil and isValidObject(actor) then
      local okDestroy, result = safeCall(actor, "K2_DestroyActor")
      if not okDestroy then okDestroy, result = safeCall(actor, "Destroy") end
      table.insert(attempts, objectFullName(actor) .. ".destroy=" .. (okDestroy and "ok" or tostring(result)))
      if okDestroy then destroyed = destroyed + 1 end
    end
  end
  RUNTIME_FOG_SPHERES = {}
  return destroyed, attempts
end

function fogSphereRuntimeProbe(text, commandName, requestId)
  local mode = tostring(extractStringAny(text, { "mode", "Mode", "action", "Action" }) or "spawn"):lower()
  if mode == "clear" or mode == "remove" or mode == "cleanup" then
    local destroyed, attempts = fogSphereClearRuntime()
    local data = '{"ok":true,"mode":"clear","destroyed":' .. tostring(destroyed) ..
      ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
    appendActionEvent("radiation_fog_sphere_probe", true, nil, "Runtime fog sphere cleanup complete.", data)
    return true, "runtime fog sphere cleanup complete", data
  end

  local dryRun = extractBoolAny(text, { "dryRun", "dry", "probeOnly" }, true) == true
  local confirm = tostring(extractStringAny(text, { "confirm", "Confirm" }) or "")
  if not dryRun and confirm ~= "SPAWN_FOG_SPHERE" then
    local data = '{"ok":false,"mode":"spawn","dryRun":false,"blocked":true,"message":"Set confirm to SPAWN_FOG_SPHERE or use dryRun:true."}'
    return false, "fog sphere spawn confirmation missing", data
  end

  local x = extractNumberAny(text, { "x", "X", "worldX", "WorldX" }, 0) or 0
  local y = extractNumberAny(text, { "y", "Y", "worldY", "WorldY" }, 0) or 0
  local z = extractNumberAny(text, { "z", "Z", "worldZ", "WorldZ" }, 4000) or 4000
  local yaw = extractNumberAny(text, { "yaw", "Yaw", "rotationYaw", "RotationYaw" }, 0) or 0
  local radius = math.max(1000, math.min(extractNumberAny(text, { "radius", "Radius" }, 1800000) or 1800000, 5000000))
  local density = math.max(0, math.min(extractNumberAny(text, { "density", "Density" }, 0.55) or 0.55, 10))
  local heightFalloff = math.max(0, math.min(extractNumberAny(text, { "densityHeightFalloff", "heightFalloff", "DensityHeightFalloff" }, 0.00035) or 0.00035, 10))
  local netCullDistanceSquared = math.max(radius * radius * 4, 1000000000000)
  local attempts = {}
  local classObject, classRoute = fogSphereClassObject(attempts)
  local world = worldFor({})
  table.insert(attempts, "world=" .. objectFullName(world))

  if classObject == nil or not isValidObject(classObject) then
    local data = '{"ok":false,"mode":"spawn","dryRun":' .. tostring(dryRun) ..
      ',"stage":"resolve-class","message":"BP_FogSphere_C class could not be loaded.","attempts":' .. js(table.concat(attempts, " | ")) .. '}'
    return false, "BP_FogSphere_C class could not be loaded", data
  end
  if world == nil or not isValidObject(world) then
    local data = '{"ok":false,"mode":"spawn","dryRun":' .. tostring(dryRun) ..
      ',"stage":"resolve-world","classRoute":' .. js(classRoute or "") ..
      ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
    return false, "world could not be resolved", data
  end

  if dryRun then
    local data = '{"ok":true,"mode":"spawn","dryRun":true,"classRoute":' .. js(classRoute or "") ..
      ',"classFullName":' .. js(objectFullName(classObject)) ..
      ',"world":' .. js(objectFullName(world)) ..
      ',"x":' .. tostring(x) .. ',"y":' .. tostring(y) .. ',"z":' .. tostring(z) ..
      ',"radius":' .. tostring(radius) .. ',"density":' .. tostring(density) ..
      ',"netCullDistanceSquared":' .. tostring(netCullDistanceSquared) ..
      ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
    return true, "fog sphere dry run complete", data
  end

  local loc = { X = x, Y = y, Z = z }
  local rot = { Pitch = 0, Yaw = yaw, Roll = 0 }
  local okSpawn, actor = safeCall(world, "SpawnActor", classObject, loc, rot)
  table.insert(attempts, "world.SpawnActor(3)=" .. (okSpawn and (isValidObject(actor) and ("ok:" .. objectFullName(actor)) or "nil") or tostring(actor)))
  if not okSpawn or actor == nil or not isValidObject(actor) then
    okSpawn, actor = safeCall(world, "SpawnActor", classObject, loc)
    table.insert(attempts, "world.SpawnActor(2)=" .. (okSpawn and (isValidObject(actor) and ("ok:" .. objectFullName(actor)) or "nil") or tostring(actor)))
  end
  if not okSpawn or actor == nil or not isValidObject(actor) then
    local data = '{"ok":false,"mode":"spawn","dryRun":false,"stage":"spawn","classRoute":' .. js(classRoute or "") ..
      ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
    return false, "BP_FogSphere_C spawn failed", data
  end

  fogSetField(actor, "Radius", radius, attempts)
  fogSetField(actor, "Density", density, attempts)
  fogSetField(actor, "DensityHeightFalloff", heightFalloff, attempts)
  local color = { R = 0.25, G = 0.95, B = 0.25, A = 1.0 }
  fogSetField(actor, "Color", color, attempts)
  fogCall(actor, "SetActorHiddenInGame", attempts, false)
  fogCall(actor, "SetActorEnableCollision", attempts, false)
  fogCall(actor, "SetReplicates", attempts, true)
  fogCall(actor, "SetReplicateMovement", attempts, false)
  fogSetField(actor, "bAlwaysRelevant", true, attempts)
  fogSetField(actor, "bNetLoadOnClient", true, attempts)
  fogSetField(actor, "NetCullDistanceSquared", netCullDistanceSquared, attempts)
  fogSetField(actor, "NetUpdateFrequency", 10, attempts)
  fogSetField(actor, "MinNetUpdateFrequency", 2, attempts)
  fogCall(actor, "UserConstructionScript", attempts)
  fogCall(actor, "SetFogDensity", attempts, density)
  fogCall(actor, "FlushNetDormancy", attempts)
  fogCall(actor, "ForceNetUpdate", attempts)

  local mesh = firstProp(actor, { "StaticMesh1", "StaticMeshComponent_24" })
  if mesh ~= nil and isValidObject(mesh) then
    local meshScale = radius / 160
    fogSetField(mesh, "LDMaxDrawDistance", math.max(radius - 200, 1000), attempts)
    fogSetField(mesh, "CachedMaxDrawDistance", math.max(radius - 200, 1000), attempts)
    fogSetField(mesh, "BoundsScale", math.max(1, radius / 100000), attempts)
    fogCall(mesh, "SetWorldScale3D", attempts, { X = meshScale, Y = meshScale, Z = meshScale })
    fogCall(mesh, "SetHiddenInGame", attempts, false, true)
    fogCall(mesh, "SetVisibility", attempts, true, true)
    fogCall(mesh, "SetIsReplicated", attempts, true)
  else
    table.insert(attempts, "StaticMesh1=nil")
  end

  table.insert(RUNTIME_FOG_SPHERES, actor)
  local data = '{"ok":true,"mode":"spawn","dryRun":false,"classRoute":' .. js(classRoute or "") ..
    ',"actorFullName":' .. js(objectFullName(actor)) ..
    ',"actorClass":' .. js(objectClassFullName(actor)) ..
    ',"world":' .. js(objectFullName(world)) ..
    ',"x":' .. tostring(x) .. ',"y":' .. tostring(y) .. ',"z":' .. tostring(z) ..
    ',"radius":' .. tostring(radius) .. ',"density":' .. tostring(density) ..
    ',"netCullDistanceSquared":' .. tostring(netCullDistanceSquared) ..
    ',"trackedRuntimeFogSpheres":' .. tostring(#RUNTIME_FOG_SPHERES) ..
    ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
  appendActionEvent("radiation_fog_sphere_probe", true, nil, "Runtime BP_FogSphere spawned for visibility test.", data)
  return true, "runtime BP_FogSphere spawned for visibility test", data
end

function vectorOf(actor)
  if actor == nil or not isValidObject(actor) then return 0, 0, 0 end
  local ok, loc = pcall(function() return actor:K2_GetActorLocation() end)
  if not ok or loc == nil then return 0, 0, 0 end
  return tonumber(loc.X or loc.x or 0) or 0, tonumber(loc.Y or loc.y or 0) or 0, tonumber(loc.Z or loc.z or 0) or 0
end

function rotationYawOf(actor)
  if actor == nil or not isValidObject(actor) then return nil end
  for _, method in ipairs({ "K2_GetActorRotation", "GetActorRotation", "GetControlRotation" }) do
    local ok, rot = safeCall(actor, method)
    if ok and rot ~= nil then
      local yaw = tonumber(rot.Yaw or rot.yaw)
      if yaw ~= nil then return yaw end
    end
  end
  return nil
end

function rotationPitchOf(actor)
  if actor == nil or not isValidObject(actor) then return nil end
  for _, method in ipairs({ "GetControlRotation", "K2_GetActorRotation", "GetActorRotation" }) do
    local ok, rot = safeCall(actor, method)
    if ok and rot ~= nil then
      local pitch = tonumber(rot.Pitch or rot.pitch)
      if pitch ~= nil then return pitch end
    end
  end
  return nil
end

function forwardVectorOf(actor)
  if actor == nil or not isValidObject(actor) then return nil, nil end
  for _, method in ipairs({ "GetActorForwardVector", "K2_GetActorForwardVector" }) do
    local ok, vec = safeCall(actor, method)
    if ok and vec ~= nil then
      local x = tonumber(vec.X or vec.x)
      local y = tonumber(vec.Y or vec.y)
      if x ~= nil and y ~= nil then
        local len = math.sqrt(x * x + y * y)
        if len > 0.01 then return x / len, y / len end
      end
    end
  end
  local yaw = rotationYawOf(actor)
  if yaw ~= nil then
    local rad = math.rad(yaw)
    return math.cos(rad), math.sin(rad)
  end
  return nil, nil
end

function ownerController(ps)
  local owner = firstProp(ps, {"Owner", "PlayerController", "Controller", "OwningController"})
  if owner ~= nil and isValidObject(owner) then return owner end
  return nil
end

function pawnFor(pc, ps)
  local pawn = firstProp(pc, {"Pawn", "PawnPrivate", "AcknowledgedPawn", "Character", "Prisoner"})
  if pawn ~= nil and isValidObject(pawn) then return pawn end
  pawn = firstProp(ps, {"Pawn", "PawnPrivate", "Character", "Prisoner"})
  if pawn ~= nil and isValidObject(pawn) then return pawn end
  return nil
end

function objectDbId(obj, methods, props)
  if obj == nil then return "" end
  for _, method in ipairs(methods or {}) do
    local okCall, value = safeCall(obj, method)
    if okCall then
      local text = dbIdText(value)
      if text ~= "" and text ~= "0" then return text end
    end
  end
  for _, prop in ipairs(props or {}) do
    local text = dbIdText(safeGet(obj, prop))
    if text ~= "" and text ~= "0" then return text end
  end
  return ""
end

function controllerInfo(pc, ps, source)
  if ps == nil then ps = firstProp(pc, {"PlayerState", "PlayerStatePrivate"}) end
  local pawn = pawnFor(pc, ps)
  local rpc = playerRpcChannel(pc)
  local name = propText(ps, {"PlayerNamePrivate", "PlayerName"})
  if name == "" then name = propText(pc, {"PlayerName", "Name"}) end
  local steam = propText(ps, {"SteamId", "SteamID", "UniqueId", "UniqueNetId", "PlayerId", "OwnerSteamId"})
  if steam == "" then steam = propText(pc, {"SteamId", "SteamID", "UniqueId", "UniqueNetId", "PlayerId"}) end
  if steam ~= "" and not looksLikeSteamId(steam) then steam = "" end
  local userProfileId = objectDbId(pc, {"GetUserProfileId"}, {"UserProfileId", "ProfileId", "_userProfileId"})
  if userProfileId == "" then userProfileId = objectDbId(ps, {}, {"UserProfileId", "ProfileId", "_userProfileId", "ServerUserProfileId", "_serverUserProfileId"}) end
  if userProfileId == "" then userProfileId = objectDbId(pawn, {}, {"_userId", "UserId", "UserProfileId", "OwnerUserProfileId"}) end
  local serverUserProfileId = objectDbId(pc, {"GetServerUserProfileId"}, {"ServerUserProfileId", "_serverUserProfileId"})
  local ping = propNumber(ps, {"Ping"})
  local score = propNumber(ps, {"Score"})
  local x, y, z = vectorOf(pawn)
  local yaw = rotationYawOf(pawn) or rotationYawOf(pc)
  local pcKey = objectKey(pc)
  local psKey = objectKey(ps)
  local pawnKey = objectKey(pawn)
  local rpcKey = objectKey(rpc)
  return {
    name = name ~= "" and name or "Unknown",
    steam = steam,
    x = x,
    y = y,
    z = z,
    yaw = yaw,
    ping = ping,
    score = score,
    userProfileId = userProfileId,
    serverUserProfileId = serverUserProfileId,
    pc = pc,
    ps = ps,
    pawn = pawn,
    rpc = rpc,
    pcKey = pcKey,
    psKey = psKey,
    pawnKey = pawnKey,
    rpcKey = rpcKey,
    runtimeKey = psKey ~= "" and psKey or (pcKey ~= "" and pcKey or (pawnKey ~= "" and pawnKey or rpcKey)),
    source = source or "runtime"
  }
end

function refreshRuntimePlayerInfo(info)
  if info == nil then return nil end
  local pc = info.pc
  local ps = info.ps
  if (pc == nil or not isValidObject(pc)) and ps ~= nil and isValidObject(ps) then
    pc = ownerController(ps)
  end
  if pc ~= nil and isValidObject(pc) then
    local refreshed = controllerInfo(pc, ps, info.source or "runtime-refresh")
    if tostring(refreshed.steam or "") == "" then refreshed.steam = tostring(info.steam or "") end
    if tostring(refreshed.name or "") == "" or tostring(refreshed.name or "") == "Unknown" then refreshed.name = tostring(info.name or "") end
    if tostring(refreshed.userProfileId or "") == "" then refreshed.userProfileId = tostring(info.userProfileId or "") end
    if tostring(refreshed.serverUserProfileId or "") == "" then refreshed.serverUserProfileId = tostring(info.serverUserProfileId or "") end
    if (refreshed.rpc == nil or not isValidObject(refreshed.rpc)) and info.rpc ~= nil and isValidObject(info.rpc) then
      refreshed.rpc = info.rpc
      refreshed.rpcKey = objectKey(info.rpc)
    end
    if tostring(refreshed.runtimeKey or "") == "" and tostring(refreshed.rpcKey or "") ~= "" then refreshed.runtimeKey = refreshed.rpcKey end
    return refreshed
  end
  if serverLogIndicatesOffline ~= nil and serverLogIndicatesOffline(info) then return nil end
  return nil
end

function addPlayerInfo(infos, seen, info)
  if info == nil then return end
  local hasIdentity = tostring(info.steam or "") ~= "" or
    (tostring(info.name or "") ~= "" and tostring(info.name or "") ~= "Unknown") or
    tostring(info.userProfileId or "") ~= "" or
    tostring(info.serverUserProfileId or "") ~= ""
  local hasLivePawn = tostring(info.pawnKey or "") ~= "" and info.pawn ~= nil and isValidObject(info.pawn)
  local hasLiveLocation = math.abs(tonumber(info.x) or 0) + math.abs(tonumber(info.y) or 0) + math.abs(tonumber(info.z) or 0) > 1
  if not hasIdentity and not (hasLivePawn and hasLiveLocation) then return end

  local key = info.psKey
  if key == "" then key = info.pcKey end
  if key == "" then key = info.pawnKey end
  if key == "" then key = string.lower((info.steam or "") .. "|" .. (info.name or "") .. "|" .. tostring(info.x) .. "|" .. tostring(info.y) .. "|" .. tostring(info.z)) end
  if key == "" or key == "||0|0|0" then return end
  if seen[key] then return end
  seen[key] = true
  table.insert(infos, info)
end

local filterPlayerInfosByPresence

function listPlayerInfosUnchecked(reason)
  local infos = {}
  local seen = {}

  local gs = gameStateRoot()
  local playerArray = firstProp(gs, {"PlayerArray"})
  if playerArray ~= nil then
    local ok, num = pcall(function() return playerArray:GetArrayNum() end)
    if ok and tonumber(num) ~= nil then
      for i = 1, tonumber(num) do
        local ps = nil
        pcall(function() ps = playerArray[i] end)
        if ps ~= nil and isValidObject(ps) then
          addPlayerInfo(infos, seen, controllerInfo(ownerController(ps), ps, reason or "game-state-unchecked"))
        end
      end
    end
  end

  if #infos > 0 then return filterPlayerInfosByPresence(infos) end

  if scanFeatureEnabled({ "AllowControllerFindAllPlayerScan", "allowControllerFindAllPlayerScan" }, false) then
    local controllers = findAll({"BP_ConZPlayerController_C", "ConZPlayerController_C", "ConZPlayerController", "PlayerController", "SCUMPlayerController_C", "SCUMPlayerController"})
    for _, pc in ipairs(controllers) do
      if pc ~= nil and isValidObject(pc) then
        addPlayerInfo(infos, seen, controllerInfo(pc, nil, reason or "controller-scan-unchecked"))
      end
    end
  end

  return filterPlayerInfosByPresence(infos)
end

-- P8: a deliberately narrow cache seed for automatic modules.  Unlike
-- listPlayerInfosUnchecked this function never falls back to FindAllOf: it
-- reads only GameState.PlayerArray and is called only from deferGameStrict.
-- Keep it separate so a future config change cannot silently re-enable a
-- global controller scan on the automatic post-join path.
function refreshPlayerInfoCacheFromGameStatePlayerArrayOnly(reason)
  local infos = {}
  local seen = {}
  local gs = gameStateRoot()
  local playerArray = firstProp(gs, {"PlayerArray"})
  if playerArray ~= nil then
    local ok, num = pcall(function() return playerArray:GetArrayNum() end)
    if ok and tonumber(num) ~= nil then
      for i = 1, tonumber(num) do
        local ps = nil
        pcall(function() ps = playerArray[i] end)
        if ps ~= nil and isValidObject(ps) then
          addPlayerInfo(infos, seen, controllerInfo(ownerController(ps), ps, reason or "post-join-cache-seed"))
        end
      end
    end
  end
  return replacePlayerInfoCache(filterPlayerInfosByPresence(infos))
end

function listPlayerInfos()
  return listPlayerInfosUnchecked("runtime-scan")
end

function cachedPlayerInfos(maxAgeSeconds)
  local infos = PLAYER_INFO_CACHE
  if infos == nil or #(infos or {}) == 0 then return nil end
  local maxAge = math.max(0.25, tonumber(maxAgeSeconds) or 3)
  local age = playerInfoCacheAgeSeconds()
  if age >= 0 and age <= maxAge then return filterPlayerInfosByPresence(infos) end
  return nil
end

function playerInventoryComponent(info)
  if info == nil or info.pawn == nil or not isValidObject(info.pawn) then return nil end
  local inv = firstProp(info.pawn, {
    "PrisonerInventoryComponent",
    "InventoryComponent",
    "Inventory",
    "CharacterInventoryComponent",
    "InventoryUserComponent"
  })
  if inv ~= nil and isValidObject(inv) then return inv end
  return nil
end

function playerHasUsableLocation(info)
  if info == nil then return false end
  local x = tonumber(info.x)
  local y = tonumber(info.y)
  local z = tonumber(info.z)
  if x == nil or y == nil or z == nil then return false end
  if x ~= x or y ~= y or z ~= z then return false end
  return math.abs(x) + math.abs(y) + math.abs(z) > 1
end

function playerInfoHasLiveRuntime(info)
  return info ~= nil and (
    (info.pc ~= nil and isValidObject(info.pc)) or
    (info.rpc ~= nil and isValidObject(info.rpc)) or
    (info.pawn ~= nil and isValidObject(info.pawn))
  )
end

function deliveryReadyInfo(info, options)
  options = options or {}
  local live = refreshRuntimePlayerInfo(info)
  if live == nil and info ~= nil and configBool("bridge-safety", { "AllowCommandResolveSingletonRuntimeScan", "allowCommandResolveSingletonRuntimeScan" }, false) then
    local targetSteam = cleanText(info.steam or info.steamId or "")
    local targetName = cleanText(info.name or "")
    local targetRuntime = cleanText(info.runtimeKey or "")
    if targetSteam ~= "" or targetName ~= "" or targetRuntime ~= "" then
      local resolved = resolvePlayerInfo(targetSteam, targetName, nil, targetRuntime)
      if playerInfoHasLiveRuntime(resolved) then
        live = refreshRuntimePlayerInfo(resolved) or resolved
        if targetSteam ~= "" and cleanText(live.steam) == "" then live.steam = targetSteam end
        if targetName ~= "" and (cleanText(live.name) == "" or cleanText(live.name):lower() == "unknown") then live.name = targetName end
      end
    end
  end
  if live == nil then
    return nil, false, "player is offline or not bound to runtime", "offline"
  end
  if tostring(live.steam or "") == "" and tostring(live.name or "") == "" then
    return live, false, "player identity is not ready", "identity"
  end
  if live.pc == nil or not isValidObject(live.pc) then
    return live, false, "player controller is not ready", "controller"
  end
  if live.pawn == nil or not isValidObject(live.pawn) then
    return live, false, "player pawn is not ready", "pawn"
  end
  if not playerHasUsableLocation(live) then
    local x, y, z = vectorOf(live.pawn)
    live.x, live.y, live.z = x, y, z
    if not playerHasUsableLocation(live) then
      return live, false, "player location is not ready", "location"
    end
  end
  if options.requireInventory ~= false and playerInventoryComponent(live) == nil then
    return live, false, "player inventory is not ready", "inventory"
  end
  return live, true, "ready", "ready"
end

function deliveryReadyMessage(reason)
  if reason == "offline" then return "Игрок оффлайн или ещё не привязан к live runtime." end
  if reason == "identity" then return "Игрок найден, но SteamID/имя ещё не готовы." end
  if reason == "controller" then return "Игрок найден, но controller ещё не готов." end
  if reason == "pawn" then return "Игрок найден, но персонаж ещё не прогрузился." end
  if reason == "location" then return "Игрок найден, но координаты ещё не готовы." end
  if reason == "inventory" then return "Игрок найден, но инвентарь ещё не готов." end
  return "Игрок ещё не готов к безопасной выдаче."
end

local enrichPlayerInfoFromServerLog

function runtimeKeyMatches(info, runtimeKey)
  local wanted = tostring(runtimeKey or "")
  if wanted == "" or info == nil then return false end
  return wanted == tostring(info.runtimeKey or "") or
    wanted == tostring(info.psKey or "") or
    wanted == tostring(info.pcKey or "") or
    wanted == tostring(info.pawnKey or "") or
    wanted == tostring(info.rpcKey or "")
end

function findPlayer(steamId, name, runtimeKey)
  local targetSteam = tostring(steamId or ""):lower()
  local targetName = tostring(name or ""):lower()
  local targetRuntime = tostring(runtimeKey or "")
  local cacheTtl = math.max(10, configNumber("bridge-safety", { "PlayerInfoCacheTtlSeconds", "playerInfoCacheTtlSeconds" }, 90))
  local infos = cachedPlayerInfos(cacheTtl) or {}
  if #infos == 0 and configBool("bridge-safety", { "AllowFindPlayerRuntimeScan", "allowFindPlayerRuntimeScan" }, false) then
    infos = listPlayerInfos()
  end
  if targetRuntime ~= "" then
    for _, info in ipairs(infos) do
      if runtimeKeyMatches(info, targetRuntime) then return info end
    end
  end
  for _, info in ipairs(infos) do
    if targetSteam ~= "" and tostring(info.steam):lower():find(targetSteam, 1, true) then return info end
    if targetName ~= "" and tostring(info.name):lower():find(targetName, 1, true) then return info end
  end
  if targetSteam ~= "" or targetName ~= "" then
    for _, info in ipairs(infos) do
      local enriched = enrichPlayerInfoFromServerLog(info) or info
      if targetSteam ~= "" and tostring(enriched.steam or ""):lower():find(targetSteam, 1, true) then return enriched end
      if targetName ~= "" and tostring(enriched.name or ""):lower():find(targetName, 1, true) then return enriched end
    end
  end
  if (targetRuntime ~= "" or targetSteam ~= "" or targetName ~= "") and configBool("bridge-safety", { "AllowFindPlayerUncheckedScan", "allowFindPlayerUncheckedScan" }, false) then
    local unchecked = listPlayerInfosUnchecked("target-command-scan")
    if unchecked ~= infos then
      if targetRuntime ~= "" then
        for _, info in ipairs(unchecked) do
          if runtimeKeyMatches(info, targetRuntime) then return info end
        end
      end
      for _, info in ipairs(unchecked) do
        if targetSteam ~= "" and tostring(info.steam):lower():find(targetSteam, 1, true) then return info end
        if targetName ~= "" and tostring(info.name):lower():find(targetName, 1, true) then return info end
      end
      for _, info in ipairs(unchecked) do
        local enriched = enrichPlayerInfoFromServerLog(info) or info
        if targetSteam ~= "" and tostring(enriched.steam or ""):lower():find(targetSteam, 1, true) then return enriched end
        if targetName ~= "" and tostring(enriched.name or ""):lower():find(targetName, 1, true) then return enriched end
      end
    end
  end
  if targetRuntime == "" and #infos == 1 then
    local only = enrichPlayerInfoFromServerLog(infos[1]) or infos[1]
    if targetSteam == "" and targetName == "" then return only end
    if targetSteam ~= "" and tostring(only.steam or ""):lower():find(targetSteam, 1, true) then return only end
    if targetName ~= "" and tostring(only.name or ""):lower():find(targetName, 1, true) then return only end
  end
  if targetRuntime == "" and targetSteam == "" and targetName == "" and #infos == 1 then return infos[1] end
  return nil
end

function findPlayerByDbId(dbId)
  local wanted = tostring(dbId or "")
  if wanted == "" or wanted == "0" then return nil end
  local cacheTtl = math.max(10, configNumber("bridge-safety", { "PlayerInfoCacheTtlSeconds", "playerInfoCacheTtlSeconds" }, 90))
  for _, info in ipairs(cachedPlayerInfos(cacheTtl) or {}) do
    if tostring(info.userProfileId or "") == wanted or tostring(info.serverUserProfileId or "") == wanted then return info end
  end
  return nil
end

function splitLines(text)
  local lines = {}
  for line in tostring(text or ""):gmatch("[^\r\n]+") do
    lines[#lines + 1] = line
  end
  return lines
end

SERVER_STATS_STALE_SECONDS = 45

-- The UE4SS callback context can expose a non-table value under `os` after a
-- native scheduler fault.  Player-listing must degrade safely in that case
-- instead of throwing from an otherwise read-only panel refresh.
function bridgeClockLibrary()
  if type(_G) ~= "table" then return nil end
  local library = rawget(_G, "os")
  if type(library) ~= "table" then return nil end
  return library
end

function bridgeClockFunction(name)
  local library = bridgeClockLibrary()
  local fn = library and rawget(library, name) or nil
  if type(fn) == "function" then return fn end
  return nil
end

function bridgeClockTime(value)
  local fn = bridgeClockFunction("time")
  if fn == nil then return nil end
  local ok, result
  if value == nil then
    ok, result = pcall(fn)
  else
    ok, result = pcall(fn, value)
  end
  if ok and type(result) == "number" then return result end
  return nil
end

function bridgeClockDate(format, value)
  local fn = bridgeClockFunction("date")
  if fn == nil then return nil end
  local ok, result = pcall(fn, format, value)
  if ok then return result end
  return nil
end

function bridgeClockDifftime(a, b)
  local fn = bridgeClockFunction("difftime")
  if fn == nil then return nil end
  local ok, result = pcall(fn, a, b)
  if ok and type(result) == "number" then return result end
  return nil
end

function bridgeClockMonotonic()
  local fn = bridgeClockFunction("clock")
  if fn ~= nil then
    local ok, result = pcall(fn)
    if ok and type(result) == "number" then return result end
  end
  return bridgeClockTime() or 0
end

function localUtcOffsetSeconds()
  local now = bridgeClockTime()
  if now == nil then return 0 end
  local utc = bridgeClockDate("!*t", now)
  if type(utc) ~= "table" then return 0 end
  utc.isdst = false
  local utcAsLocal = bridgeClockTime(utc)
  local offset = utcAsLocal ~= nil and bridgeClockDifftime(now, utcAsLocal) or nil
  if offset ~= nil then return offset end
  return 6
end

function serverLogTimestamp(line)
  local year, month, day, hour, minute, second = tostring(line or ""):match("^%[(%d%d%d%d)%.(%d%d)%.(%d%d)%-(%d%d)%.(%d%d)%.(%d%d)")
  if year == nil then return nil end
  local value = bridgeClockTime({
    year = tonumber(year),
    month = tonumber(month),
    day = tonumber(day),
    hour = tonumber(hour),
    min = tonumber(minute),
    sec = tonumber(second)
  })
  if value ~= nil then
    local utcValue = value + localUtcOffsetSeconds()
    local now = bridgeClockTime()
    if now ~= nil and math.abs(now - utcValue) < math.abs(now - value) then return utcValue end
    return value
  end
  return nil
end

serverLogIdentityCacheAt = 0
serverLogIdentityCache = nil
PLAYER_IDENTITY_STATE_FILE = PLAYER_IDENTITY_STATE_FILE or "player-identities.json"
PLAYER_IDENTITY_CACHE = PLAYER_IDENTITY_CACHE or nil
PLAYER_IDENTITY_CACHE_AT = PLAYER_IDENTITY_CACHE_AT or 0
PLAYER_IDENTITY_CACHE_TTL_SECONDS = PLAYER_IDENTITY_CACHE_TTL_SECONDS or 20
PLAYER_IDENTITY_BOOTSTRAP_FILES = PLAYER_IDENTITY_BOOTSTRAP_FILES or {
  PLAYER_IDENTITY_STATE_FILE,
  "bounty-rewards-pending.json",
  "wargm-delivered.json",
  "vip-members.json",
  "welcome-pack-timers.json",
  "daily-pack-timers.json",
  "battlepass-state.json",
  "battlepass-claims.json",
  "welcome-pack-claims.json",
  "daily-pack-claims.json",
  "vehicle-rentals.json",
  "money-transfer.json",
  "money-transfer-cooldowns.json",
  "item-upgrade.json",
  "item-upgrade-cooldowns.json",
  "base-loot-collector.json",
  "base-loot-cooldowns.json",
  "panel-quests-claims.json",
  "zone-robot-schedule-runs.json",
  "character-pack-timers.json",
  "action-log.json"
}

function newPersistentPlayerIdentityCache()
  return { latest = nil, byProfile = {}, bySteam = {}, byName = {}, count = 0 }
end

function mergePersistentPlayerIdentity(cache, steam, profileId, name, source)
  cache = cache or newPersistentPlayerIdentityCache()
  steam = cleanText(steam)
  profileId = cleanText(profileId)
  name = cleanText(name)
  local lowerName = name:lower()
  if not looksLikeSteamId(steam) and profileId == "" and lowerName == "" then return nil end

  local existing = nil
  if profileId ~= "" then existing = cache.byProfile[profileId] end
  if existing == nil and looksLikeSteamId(steam) then existing = cache.bySteam[steam] end
  if existing == nil and lowerName ~= "" then existing = cache.byName[lowerName] end

  local merged = existing or { steam = "", profileId = "", name = "", source = "" }
  if looksLikeSteamId(steam) then merged.steam = steam end
  if profileId ~= "" then merged.profileId = profileId end
  if name ~= "" then merged.name = name end
  if cleanText(source) ~= "" then merged.source = source end

  if not looksLikeSteamId(merged.steam) and merged.profileId == "" and cleanText(merged.name) == "" then return nil end
  if merged.profileId ~= "" then cache.byProfile[merged.profileId] = merged end
  if looksLikeSteamId(merged.steam) then cache.bySteam[merged.steam] = merged end
  local mergedLowerName = cleanText(merged.name):lower()
  if mergedLowerName ~= "" then cache.byName[mergedLowerName] = merged end
  if cache.latest == nil then cache.latest = merged end
  if existing == nil then cache.count = cache.count + 1 end
  return merged
end

function loadPersistentPlayerIdentities(forceReload)
  local now = bridgeClockMonotonic()
  if PLAYER_IDENTITY_CACHE ~= nil and forceReload ~= true and (now - (PLAYER_IDENTITY_CACHE_AT or 0)) < PLAYER_IDENTITY_CACHE_TTL_SECONDS then
    return PLAYER_IDENTITY_CACHE
  end

  local cache = newPersistentPlayerIdentityCache()
  for _, fileName in ipairs(PLAYER_IDENTITY_BOOTSTRAP_FILES or {}) do
    local path = STATE_DIR .. "\\" .. tostring(fileName or "")
    local rows = loadStateArrayCache(path, 512 * 1024, forceReload == true).rows or {}
    for _, object in ipairs(rows) do
      local steam = extractStringAny(object, { "steamId", "SteamId", "steam", "Steam" }) or ""
      local profileId = extractStringAny(object, { "userProfileId", "serverUserProfileId", "profileId", "ProfileId" }) or ""
      local name = extractStringAny(object, { "name", "Name", "playerName", "PlayerName" }) or ""
      mergePersistentPlayerIdentity(cache, steam, profileId, name, tostring(fileName or "state"))
    end
  end
  PLAYER_IDENTITY_CACHE = cache
  PLAYER_IDENTITY_CACHE_AT = now
  return cache
end

function rememberPersistentPlayerIdentity(steam, profileId, name, source)
  steam = cleanText(steam)
  profileId = cleanText(profileId)
  name = cleanText(name)
  if not looksLikeSteamId(steam) or name == "" then return false end
  local cache = loadPersistentPlayerIdentities(false)
  local before = nil
  if profileId ~= "" then before = cache.byProfile[profileId] end
  if before == nil then before = cache.bySteam[steam] end
  local beforeSteam = before ~= nil and cleanText(before.steam) or ""
  local beforeProfileId = before ~= nil and cleanText(before.profileId) or ""
  local beforeName = before ~= nil and cleanText(before.name) or ""
  local merged = mergePersistentPlayerIdentity(cache, steam, profileId, name, source or "runtime")
  if merged == nil then return false end

  local sameAsBefore = before ~= nil and
    beforeSteam == cleanText(merged.steam) and
    beforeProfileId == cleanText(merged.profileId) and
    beforeName == cleanText(merged.name)
  if sameAsBefore then return true end

  appendJsonArray(STATE_DIR .. "\\" .. PLAYER_IDENTITY_STATE_FILE,
    '{"utc":' .. js(nowUtc()) ..
    ',"steamId":' .. js(merged.steam or "") ..
    ',"userProfileId":' .. js(merged.profileId or "") ..
    ',"name":' .. js(merged.name or "") ..
    ',"source":' .. js(source or "runtime") .. '}',
    512 * 1024)
  return true
end

function persistentPlayerIdentityForInfo(info)
  if info == nil then return nil end
  local cache = loadPersistentPlayerIdentities(false)
  local profileId = cleanText(info.userProfileId or info.serverUserProfileId or info.profileId or "")
  local steam = cleanText(info.steam or info.steamId or "")
  local lowerName = cleanText(info.name or ""):lower()
  if profileId ~= "" and cache.byProfile[profileId] ~= nil then return cache.byProfile[profileId] end
  if looksLikeSteamId(steam) and cache.bySteam[steam] ~= nil then return cache.bySteam[steam] end
  if lowerName ~= "" and lowerName ~= "unknown" and cache.byName[lowerName] ~= nil then return cache.byName[lowerName] end
  return nil
end

function rememberServerLogIdentity(cache, steam, profileId, name)
  steam = cleanText(steam)
  name = cleanText(name)
  profileId = cleanText(profileId)
  if not looksLikeSteamId(steam) or name == "" then return end
  local identity = { steam = steam, name = name, profileId = profileId }
  if cache.latest == nil then cache.latest = identity end
  if profileId ~= "" and cache.byProfile[profileId] == nil then cache.byProfile[profileId] = identity end
  if cache.bySteam[steam] == nil then cache.bySteam[steam] = identity end
  local lowerName = name:lower()
  if lowerName ~= "" and cache.byName[lowerName] == nil then cache.byName[lowerName] = identity end
  cache.count = cache.count + 1
  rememberPersistentPlayerIdentity(steam, profileId, name, "server-log")
end

function serverLogIdentities()
  local now = bridgeClockMonotonic()
  local ttl = 30
  if type(configNumber) == "function" then
    ttl = math.max(5, configNumber("bridge-safety", { "ServerLogIdentityCacheSeconds", "serverLogIdentityCacheSeconds" }, ttl))
  end
  if serverLogIdentityCache ~= nil and (now - serverLogIdentityCacheAt) < ttl then return serverLogIdentityCache end
  serverLogIdentityCacheAt = now
  serverLogIdentityCache = { latest = nil, byProfile = {}, bySteam = {}, byName = {}, count = 0 }
  local text = readTail(SERVER_LOG_FILE, 768 * 1024)
  if text == nil then return serverLogIdentityCache end
  local lines = splitLines(text)
  for i = #lines, math.max(1, #lines - 2500), -1 do
    local line = lines[i]
    local steam, profileId, name = line:match("APrisoner::HandlePossessedBy:%s*(%d+),%s*(%d+),%s*([^%s]+)")
    if steam == nil then
      steam, name, profileId = line:match("LogSCUM:%s*'[^']*%s+(%d+):([^%(]+)%((%d+)%)'%s+logged in")
    end
    if steam == nil then
      steam, name = line:match("Login request:.*%?user=(%d+).*%?Name=([^%?%s]+)")
    end
    if steam == nil then
      steam, name = line:match("Join request:.*%?user=(%d+).*%?Name=([^%?%s]+)")
    end
    rememberServerLogIdentity(serverLogIdentityCache, steam, profileId, name)
  end
  return serverLogIdentityCache
end

local serverLogPresenceCacheAt = 0
local serverLogPresenceCache = nil

function rememberServerLogPresence(cache, online, steam, profileId, name, epoch)
  steam = cleanText(steam)
  profileId = cleanText(profileId)
  name = cleanText(name)
  local lowerName = name:lower()
  local identities = serverLogIdentities()
  local identity = nil
  if profileId ~= "" then identity = cache.knownByProfile[profileId] or identities.byProfile[profileId] end
  if identity == nil and looksLikeSteamId(steam) then identity = cache.knownBySteam[steam] or identities.bySteam[steam] end
  if identity == nil and lowerName ~= "" then identity = cache.knownByName[lowerName] or identities.byName[lowerName] end
  if not looksLikeSteamId(steam) and identity ~= nil and looksLikeSteamId(identity.steam) then steam = cleanText(identity.steam) end
  if profileId == "" and identity ~= nil then profileId = cleanText(identity.profileId) end
  if name == "" and identity ~= nil then
    name = cleanText(identity.name)
    lowerName = name:lower()
  end
  if not looksLikeSteamId(steam) and profileId == "" and lowerName == "" then return end
  local merged = {
    steam = looksLikeSteamId(steam) and steam or "",
    profileId = profileId,
    name = name
  }
  if merged.profileId ~= "" then cache.knownByProfile[merged.profileId] = merged end
  if merged.steam ~= "" then cache.knownBySteam[merged.steam] = merged end
  if lowerName ~= "" then cache.knownByName[lowerName] = merged end
  local active = online == true
  local canonical = merged.steam ~= "" and ("steam:" .. merged.steam) or
    (merged.profileId ~= "" and ("profile:" .. merged.profileId) or ("name:" .. lowerName))
  cache.active[canonical] = active and true or nil
  if merged.steam ~= "" then cache.statusBySteam[merged.steam] = active end
  if merged.profileId ~= "" then cache.statusByProfile[merged.profileId] = active end
  if lowerName ~= "" then cache.statusByName[lowerName] = active end
  if active then
    cache.onlineEvents = cache.onlineEvents + 1
  else
    cache.offlineEvents = cache.offlineEvents + 1
  end
  epoch = tonumber(epoch) or 0
  if epoch > 0 then
    cache.lastEventEpoch = math.max(tonumber(cache.lastEventEpoch or 0) or 0, epoch)
    if active then
      cache.lastOnlineEpoch = math.max(tonumber(cache.lastOnlineEpoch or 0) or 0, epoch)
    else
      cache.lastOfflineEpoch = math.max(tonumber(cache.lastOfflineEpoch or 0) or 0, epoch)
    end
  end
end

function serverLogPresenceSnapshot()
  local now = bridgeClockMonotonic()
  local ttl = 15
  if type(configNumber) == "function" then
    ttl = math.max(3, configNumber("bridge-safety", { "ServerLogPresenceCacheSeconds", "serverLogPresenceCacheSeconds" }, ttl))
  end
  if serverLogPresenceCache ~= nil and (now - serverLogPresenceCacheAt) < ttl then return serverLogPresenceCache end
  serverLogPresenceCacheAt = now
  serverLogPresenceCache = {
    knownByProfile = {},
    knownBySteam = {},
    knownByName = {},
    statusByProfile = {},
    statusBySteam = {},
    statusByName = {},
    active = {},
    activeCount = 0,
    onlineEvents = 0,
    offlineEvents = 0,
    lastEventEpoch = 0,
    lastOnlineEpoch = 0,
    lastOfflineEpoch = 0
  }
  local text = readTail(SERVER_LOG_FILE, 1024 * 1024)
  if text == nil then return serverLogPresenceCache end
  local lines = splitLines(text)
  for i = math.max(1, #lines - 3000), #lines do
    local line = tostring(lines[i] or "")
    local epoch = serverLogTimestamp(line) or 0
    local steam, profileId, name = line:match("APrisoner::HandlePossessedBy:%s*(%d+),%s*(%d+),%s*([^%s]+)")
    if steam ~= nil then
      rememberServerLogPresence(serverLogPresenceCache, true, steam, profileId, name, epoch)
    else
      steam, name, profileId = line:match("LogSCUM:%s*'[^']*%s+(%d+):([^%(]+)%((%d+)%)'%s+logged in")
      if steam ~= nil then
        rememberServerLogPresence(serverLogPresenceCache, true, steam, profileId, name, epoch)
      else
        steam, name = line:match("Join succeeded:.*%?user=(%d+).*%?Name=([^%?%s]+)")
        if steam ~= nil then
          rememberServerLogPresence(serverLogPresenceCache, true, steam, "", name, epoch)
        else
          steam, name, profileId = line:match("LogSCUM:%s*'[^']*%s+(%d+):([^%(]+)%((%d+)%)'%s+logged out")
          if steam ~= nil then
            rememberServerLogPresence(serverLogPresenceCache, false, steam, profileId, name, epoch)
          else
            name, profileId = line:match("Prisoner logging out:%s*([^%(]+)%s*%((%d+)%)")
            if name ~= nil then
              rememberServerLogPresence(serverLogPresenceCache, false, "", profileId, name, epoch)
            else
              name = line:match("LogBattlEye:%s*Display:%s*Player%s*#%d+%s+(.+)%s+disconnected")
              if name ~= nil then rememberServerLogPresence(serverLogPresenceCache, false, "", "", name, epoch) end
            end
          end
        end
      end
    end
  end
  for _ in pairs(serverLogPresenceCache.active) do
    serverLogPresenceCache.activeCount = serverLogPresenceCache.activeCount + 1
  end
  return serverLogPresenceCache
end

function serverLogIndicatesOffline(info, presence)
  if info == nil then return false end
  presence = presence or serverLogPresenceSnapshot()
  if presence == nil then return false end
  local steam = cleanText(info.steam)
  if looksLikeSteamId(steam) then
    local status = presence.statusBySteam[steam]
    if status ~= nil then return status == false end
  end
  local profileId = cleanText(info.userProfileId or info.serverUserProfileId or "")
  if profileId ~= "" then
    local status = presence.statusByProfile[profileId]
    if status ~= nil then return status == false end
  end
  local lowerName = cleanText(info.name):lower()
  if lowerName ~= "" and lowerName ~= "unknown" then
    local status = presence.statusByName[lowerName]
    if status ~= nil then return status == false end
  end
  return false
end

filterPlayerInfosByPresence = function(infos)
  if infos == nil or #infos == 0 then return infos or {} end
  local presence = serverLogPresenceSnapshot()
  if presence == nil then return infos end
  local filtered = {}
  for _, info in ipairs(infos) do
    if not serverLogIndicatesOffline(info, presence) then table.insert(filtered, info) end
  end
  return filtered
end

serverLogOnlineCacheAt = 0
serverLogOnlineCache = nil

function serverLogOnlineSnapshot()
  local now = bridgeClockMonotonic()
  local ttl = 15
  if type(configNumber) == "function" then
    ttl = math.max(3, configNumber("bridge-safety", { "ServerLogOnlineCacheSeconds", "serverLogOnlineCacheSeconds" }, ttl))
  end
  if serverLogOnlineCache ~= nil and (now - serverLogOnlineCacheAt) < ttl then return serverLogOnlineCache end
  serverLogOnlineCacheAt = now
  serverLogOnlineCache = {
    playerCount = -1,
    lastLine = "",
    statsIndex = 0,
    statsEpoch = 0,
    statsAgeSeconds = -1,
    statsFresh = false,
    laterJoin = false,
    activePresenceCount = 0,
    offlinePresenceCount = 0
  }
  local text = readTail(SERVER_LOG_FILE, 512 * 1024)
  if text == nil then return serverLogOnlineCache end
  local lines = splitLines(text)
  for i = #lines, math.max(1, #lines - 1200), -1 do
    local line = lines[i]
    local count = line:match("Global Stats:.-|%s*C:%s*%d+%s*%([^%)]*%),%s*P:%s*(%d+)")
    if count ~= nil then
      serverLogOnlineCache.playerCount = tonumber(count) or -1
      serverLogOnlineCache.lastLine = line
      serverLogOnlineCache.statsIndex = i
      serverLogOnlineCache.statsEpoch = serverLogTimestamp(line) or 0
      break
    end
  end
  if tonumber(serverLogOnlineCache.statsEpoch or 0) > 0 then
    local currentEpoch = bridgeClockTime()
    if currentEpoch ~= nil then
      local age = currentEpoch - tonumber(serverLogOnlineCache.statsEpoch or 0)
      serverLogOnlineCache.statsAgeSeconds = age
      serverLogOnlineCache.statsFresh = age >= -300 and age <= SERVER_STATS_STALE_SECONDS
    end
  end
  if tonumber(serverLogOnlineCache.playerCount or -1) == 0 and serverLogOnlineCache.statsIndex > 0 then
    for i = serverLogOnlineCache.statsIndex + 1, #lines do
      local line = tostring(lines[i] or "")
      local lower = line:lower()
      if lower:find("login request:", 1, true) ~= nil or
        lower:find("join request:", 1, true) ~= nil or
        lower:find("join succeeded:", 1, true) ~= nil or
        lower:find("logged in", 1, true) ~= nil or
        lower:find("aprisoner::handlepossessedby", 1, true) ~= nil then
        serverLogOnlineCache.laterJoin = true
        break
      end
    end
  end
  local presence = serverLogPresenceSnapshot()
  serverLogOnlineCache.activePresenceCount = tonumber(presence and presence.activeCount or 0) or 0
  serverLogOnlineCache.offlinePresenceCount = tonumber(presence and presence.offlineEvents or 0) or 0
  serverLogOnlineCache.lastPresenceEpoch = tonumber(presence and presence.lastEventEpoch or 0) or 0
  serverLogOnlineCache.lastOnlineEpoch = tonumber(presence and presence.lastOnlineEpoch or 0) or 0
  serverLogOnlineCache.lastOfflineEpoch = tonumber(presence and presence.lastOfflineEpoch or 0) or 0
  if tonumber(serverLogOnlineCache.playerCount or -1) == 0 then
    if serverLogOnlineCache.activePresenceCount > 0 and
      serverLogOnlineCache.lastOnlineEpoch >= serverLogOnlineCache.lastOfflineEpoch and
      serverLogOnlineCache.lastOnlineEpoch >= tonumber(serverLogOnlineCache.statsEpoch or 0) then
      serverLogOnlineCache.laterJoin = true
    elseif serverLogOnlineCache.statsFresh == true then
      serverLogOnlineCache.laterJoin = serverLogOnlineCache.laterJoin == true
    elseif serverLogOnlineCache.activePresenceCount > 0 then
      serverLogOnlineCache.laterJoin = true
    elseif serverLogOnlineCache.offlinePresenceCount > 0 then
      serverLogOnlineCache.laterJoin = false
    end
  end
  return serverLogOnlineCache
end

function serverLogReportsNoPlayers()
  local snapshot = serverLogOnlineSnapshot()
  local presence = serverLogPresenceSnapshot()
  if presence ~= nil and tonumber(presence.activeCount or 0) > 0 and
    tonumber(presence.lastOnlineEpoch or 0) >= tonumber(presence.lastOfflineEpoch or 0) then
    return false
  end
  if snapshot ~= nil and snapshot.statsFresh == false and tonumber(snapshot.statsAgeSeconds or -1) >= 0 then
    return true
  end
  return snapshot ~= nil and tonumber(snapshot.playerCount or -1) == 0 and snapshot.laterJoin ~= true
end

RUNTIME_SCAN_JOIN_SETTLE_SECONDS = 18

SERVER_LOG_JOIN_CACHE_AT = SERVER_LOG_JOIN_CACHE_AT or 0
SERVER_LOG_JOIN_CACHE_VALUE = SERVER_LOG_JOIN_CACHE_VALUE or 0

function latestServerLogJoinEpoch()
  local now = bridgeClockMonotonic()
  local ttl = 10
  if type(configNumber) == "function" then
    ttl = math.max(3, configNumber("bridge-safety", { "ServerLogJoinCacheSeconds", "serverLogJoinCacheSeconds" }, ttl))
  end
  if (now - (SERVER_LOG_JOIN_CACHE_AT or 0)) < ttl then return SERVER_LOG_JOIN_CACHE_VALUE or 0 end
  SERVER_LOG_JOIN_CACHE_AT = now
  SERVER_LOG_JOIN_CACHE_VALUE = 0
  local text = readTail(SERVER_LOG_FILE, 256 * 1024)
  if text == nil then return 0 end
  local lines = splitLines(text)
  for i = #lines, math.max(1, #lines - 800), -1 do
    local line = tostring(lines[i] or "")
    local lower = line:lower()
    if lower:find("aprisoner::handlepossessedby", 1, true) ~= nil or
      lower:find("logged in at:", 1, true) ~= nil or
      lower:find("join succeeded:", 1, true) ~= nil then
      SERVER_LOG_JOIN_CACHE_VALUE = serverLogTimestamp(line) or 0
      return SERVER_LOG_JOIN_CACHE_VALUE
    end
  end
  return 6
end

runtimeScanAllowed = function()
  if type(configNumber) == "function" then
    RUNTIME_SCAN_JOIN_SETTLE_SECONDS = math.max(0, configNumber("bridge-safety", { "RuntimeScanJoinSettleSeconds", "runtimeScanJoinSettleSeconds" }, RUNTIME_SCAN_JOIN_SETTLE_SECONDS))
  end
  local snapshot = serverLogOnlineSnapshot()
  local ignoreZeroLog = configBool("bridge-safety", { "IgnoreServerLogNoPlayersForRuntimeScan", "ignoreServerLogNoPlayersForRuntimeScan" }, false) == true
  if snapshot ~= nil and tonumber(snapshot.playerCount or -1) == 0 and snapshot.laterJoin ~= true and not ignoreZeroLog then
    return false, "server-log reports zero players", -1
  end
  local joinEpoch = latestServerLogJoinEpoch()
  if joinEpoch > 0 then
    local currentEpoch = bridgeClockTime()
    if currentEpoch ~= nil then
      local age = currentEpoch - joinEpoch
      if age >= 0 and age < RUNTIME_SCAN_JOIN_SETTLE_SECONDS then
        return false, "recent player join; waiting for UE objects to settle", age
      end
    end
  end
  return true, "runtime scan allowed", -1
end

function logPlayerKey(steam, profileId, name)
  steam = cleanText(steam)
  profileId = cleanText(profileId)
  name = cleanText(name)
  if looksLikeSteamId(steam) then return "steam:" .. steam end
  if profileId ~= "" then return "profile:" .. profileId end
  if name ~= "" then return "name:" .. name:lower() end
  return ""
end

function rememberLogPlayer(cache, online, steam, profileId, name, x, y, z)
  steam = cleanText(steam)
  profileId = cleanText(profileId)
  name = cleanText(name)
  local key = logPlayerKey(steam, profileId, name)
  if key == "" and name ~= "" then key = cache.byName[name:lower()] or "" end
  if key == "" and profileId ~= "" then key = cache.byProfile[profileId] or "" end
  if key == "" and looksLikeSteamId(steam) then key = cache.bySteam[steam] or "" end
  if key == "" then return end

  local row = cache.rows[key] or {
    steam = "",
    profileId = "",
    name = "",
    x = 0,
    y = 0,
    z = 0,
    online = false
  }
  if looksLikeSteamId(steam) then row.steam = steam end
  if profileId ~= "" then row.profileId = profileId end
  if name ~= "" then row.name = name end
  if tonumber(x) ~= nil then row.x = tonumber(x) end
  if tonumber(y) ~= nil then row.y = tonumber(y) end
  if tonumber(z) ~= nil then row.z = tonumber(z) end
  row.online = online == true
  cache.rows[key] = row
  if row.steam ~= "" then cache.bySteam[row.steam] = key end
  if row.profileId ~= "" then cache.byProfile[row.profileId] = key end
  if row.name ~= "" then cache.byName[row.name:lower()] = key end
end

function syntheticOnlinePlayerFromIdentity(snapshot, cache)
  if snapshot == nil or snapshot.statsFresh ~= true or tonumber(snapshot.playerCount or -1) ~= 1 then return nil end
  if cache ~= nil then
    for _, row in pairs(cache.rows or {}) do
      if row.online == true then return nil end
    end
  end

  local presence = serverLogPresenceSnapshot()
  if presence ~= nil and tonumber(presence.lastOfflineEpoch or 0) > tonumber(snapshot.statsEpoch or 0) and
    tonumber(presence.lastOfflineEpoch or 0) > tonumber(presence.lastOnlineEpoch or 0) then
    return nil
  end

  if presence ~= nil and tonumber(presence.activeCount or 0) == 1 then
    for _, identity in pairs(presence.knownBySteam or {}) do
      if identity ~= nil and serverLogIdentityActive(identity, presence) then return identity end
    end
    for _, identity in pairs(presence.knownByProfile or {}) do
      if identity ~= nil and serverLogIdentityActive(identity, presence) then return identity end
    end
    for _, identity in pairs(presence.knownByName or {}) do
      if identity ~= nil and serverLogIdentityActive(identity, presence) then return identity end
    end
  end

  local identities = serverLogIdentities()
  if identities ~= nil and tonumber(identities.count or 0) == 1 and identities.latest ~= nil then return identities.latest end

  local persistent = loadPersistentPlayerIdentities(false)
  if persistent ~= nil and tonumber(persistent.count or 0) == 1 and persistent.latest ~= nil then return persistent.latest end
  return nil
end

function serverLogPlayersJson()
  local snapshot = serverLogOnlineSnapshot()
  if snapshot ~= nil and snapshot.statsFresh == true and tonumber(snapshot.playerCount or -1) == 0 and snapshot.laterJoin ~= true then
    local presence = serverLogPresenceSnapshot()
    if presence == nil or tonumber(presence.activeCount or 0) <= 0 or
      tonumber(presence.lastOnlineEpoch or 0) < tonumber(presence.lastOfflineEpoch or 0) then
      return '{"players":[],"count":0,"source":"server-log","runtimeReady":false,"serverStats":{"playerCount":0,"fresh":true,"ageSeconds":' ..
        tostring(tonumber(snapshot.statsAgeSeconds or 0) or 0) .. ',"lastLine":' .. js(snapshot.lastLine or "") .. '}}'
    end
  end

  local cache = { rows = {}, bySteam = {}, byProfile = {}, byName = {} }
  local text = readTail(SERVER_LOG_FILE, 1024 * 1024)
  if text ~= nil then
    local lines = splitLines(text)
    for i = math.max(1, #lines - 3000), #lines do
      local line = tostring(lines[i] or "")
      local steam, profileId, name = line:match("APrisoner::HandlePossessedBy:%s*(%d+),%s*(%d+),%s*([^%s]+)")
      if steam ~= nil then
        rememberLogPlayer(cache, true, steam, profileId, name)
      else
        local x, y, z
        steam, name, profileId, x, y, z = line:match("LogSCUM:%s*'[^']*%s+(%d+):([^%(]+)%((%d+)%)'%s+logged in at:%s*X=([%-%.%d]+)%s+Y=([%-%.%d]+)%s+Z=([%-%.%d]+)")
        if steam ~= nil then
          rememberLogPlayer(cache, true, steam, profileId, name, x, y, z)
        else
          steam, name, profileId = line:match("LogSCUM:%s*'[^']*%s+(%d+):([^%(]+)%((%d+)%)'%s+logged out")
          if steam ~= nil then
            rememberLogPlayer(cache, false, steam, profileId, name)
          else
            name, profileId = line:match("Prisoner logging out:%s*([^%(]+)%s*%((%d+)%)")
            if name ~= nil then
              rememberLogPlayer(cache, false, "", profileId, name)
            else
              name = line:match("LogBattlEye:%s*Display:%s*Player%s*#%d+%s+(.+)%s+disconnected")
              if name ~= nil then rememberLogPlayer(cache, false, "", "", name) end
            end
          end
        end
      end
    end
  end

  local syntheticIdentity = syntheticOnlinePlayerFromIdentity(snapshot, cache)
  if syntheticIdentity ~= nil then
    rememberLogPlayer(cache, true, syntheticIdentity.steam or "", syntheticIdentity.profileId or "", syntheticIdentity.name or "")
    appendLog("playersJson synthesized single online player from identity cache because Global Stats reports P:1")
  end

  local runtimeReady, runtimeReason, runtimeAge = runtimeScanAllowed()
  local parts = {}
  for _, row in pairs(cache.rows) do
    if row.online == true then
      table.insert(parts, '{"name":' .. js(row.name ~= "" and row.name or "Unknown") ..
        ',"steamId":' .. js(row.steam) ..
        ',"online":true' ..
        ',"status":"online"' ..
        ',"source":"server-log"' ..
        ',"x":' .. tostring(tonumber(row.x) or 0) ..
        ',"y":' .. tostring(tonumber(row.y) or 0) ..
        ',"z":' .. tostring(tonumber(row.z) or 0) ..
        ',"userProfileId":' .. js(row.profileId) ..
        ',"serverUserProfileId":' .. js(row.profileId) ..
        ',"runtimeKey":""' ..
        ',"runtimeReady":' .. (runtimeReady and "true" or "false") ..
        '}')
    end
  end
  return '{"players":[' .. table.concat(parts, ",") .. '],"count":' .. tostring(#parts) ..
    ',"source":"server-log","runtimeReady":' .. (runtimeReady and "true" or "false") ..
    ',"runtimeReason":' .. js(runtimeReason or "") ..
    ',"runtimeAgeSeconds":' .. tostring(tonumber(runtimeAge or -1) or -1) ..
    ',"serverStats":{"playerCount":' .. tostring(tonumber(snapshot and snapshot.playerCount or -1) or -1) ..
    ',"fresh":' .. ((snapshot and snapshot.statsFresh) and "true" or "false") ..
    ',"ageSeconds":' .. tostring(tonumber(snapshot and snapshot.statsAgeSeconds or -1) or -1) ..
    ',"lastLine":' .. js((snapshot and snapshot.lastLine) or "") ..
    '}}'
end

function latestServerLogIdentity()
  local cache = serverLogIdentities()
  return cache and cache.latest or nil
end

enrichPlayerInfoFromServerLog = function(info)
  if info == nil then return nil end
  local hasSteam = looksLikeSteamId(info.steam)
  local hasName = not invalidRuntimeText(info.name)
  if hasSteam and hasName then return info end
  local cache = serverLogIdentities()
  if cache == nil then return info end
  local infoProfile = tostring(info.userProfileId or info.serverUserProfileId or "")
  local identity = nil
  if infoProfile ~= "" then identity = cache.byProfile[infoProfile] end
  if identity == nil and hasSteam then identity = cache.bySteam[tostring(info.steam or "")] end
  if identity == nil and hasName then identity = cache.byName[tostring(info.name or ""):lower()] end
  if identity == nil and infoProfile == "" and tonumber(cache.count or 0) == 1 then identity = cache.latest end
  if identity == nil then identity = persistentPlayerIdentityForInfo(info) end
  if identity ~= nil then
    if not hasSteam then info.steam = identity.steam end
    if not hasName then info.name = identity.name end
    if tostring(info.userProfileId or "") == "" and tostring(identity.profileId or "") ~= "" then info.userProfileId = identity.profileId end
    if tostring(info.serverUserProfileId or "") == "" and tostring(identity.profileId or "") ~= "" then info.serverUserProfileId = identity.profileId end
  end
  return info
end

function serverLogIdentityActive(identity, presence)
  if identity == nil then return false end
  presence = presence or serverLogPresenceSnapshot()
  if presence == nil then return false end
  local steam = cleanText(identity.steam)
  if looksLikeSteamId(steam) and presence.statusBySteam[steam] == true then return true end
  local profileId = cleanText(identity.profileId)
  if profileId ~= "" and presence.statusByProfile[profileId] == true then return true end
  local lowerName = cleanText(identity.name):lower()
  if lowerName ~= "" and presence.statusByName[lowerName] == true then return true end
  return false
end

function serverLogIdentityForTarget(steamId, name)
  local cache = serverLogIdentities()
  if cache == nil then return nil end
  local targetSteam = cleanText(steamId)
  local targetName = cleanText(name):lower()
  local identity = nil
  if looksLikeSteamId(targetSteam) then identity = cache.bySteam[targetSteam] end
  if identity == nil and targetName ~= "" then identity = cache.byName[targetName] end
  if identity == nil then return nil end
  if not serverLogIdentityActive(identity) then return nil end
  return identity
end

function applyServerLogIdentity(info, identity)
  if info == nil or identity == nil then return info end
  local steam = cleanText(identity.steam)
  local name = cleanText(identity.name)
  local profileId = cleanText(identity.profileId)
  if looksLikeSteamId(steam) then info.steam = steam end
  if name ~= "" then info.name = name end
  if profileId ~= "" then
    info.userProfileId = profileId
    info.serverUserProfileId = profileId
  end
  return info
end

function resolvePlayerInfoFromServerLogTarget(steamId, name)
  local identity = serverLogIdentityForTarget(steamId, name)
  if identity == nil then return nil end
  local infos = cachedPlayerInfos(math.max(10, configNumber("bridge-safety", { "PlayerInfoCacheTtlSeconds", "playerInfoCacheTtlSeconds" }, 300))) or {}
  if infos == nil or #infos == 0 then return nil end

  local steam = cleanText(identity.steam)
  local profileId = cleanText(identity.profileId)
  local lowerName = cleanText(identity.name):lower()
  for _, info in ipairs(infos) do
    local enriched = enrichPlayerInfoFromServerLog(info) or info
    if (looksLikeSteamId(steam) and cleanText(enriched.steam) == steam) or
      (profileId ~= "" and (cleanText(enriched.userProfileId) == profileId or cleanText(enriched.serverUserProfileId) == profileId)) or
      (lowerName ~= "" and cleanText(enriched.name):lower() == lowerName) then
      return applyServerLogIdentity(enriched, identity)
    end
  end

  local presence = serverLogPresenceSnapshot()
  if #infos == 1 and presence ~= nil and tonumber(presence.activeCount or 0) == 1 then
    return applyServerLogIdentity(enrichPlayerInfoFromServerLog(infos[1]) or infos[1], identity)
  end

  appendLog("player resolve refused ambiguous server-log identity target=" ..
    tostring(steam ~= "" and steam or lowerName) .. " liveControllers=" .. tostring(#infos))
  return nil
end

function resolvePlayerInfo(steamId, name, preferredInfo, runtimeKey)
  local targetSteam = tostring(steamId or ""):lower()
  local targetName = tostring(name or ""):lower()
  local targetRuntime = tostring(runtimeKey or "")
  if preferredInfo ~= nil then
    local originalPreferred = preferredInfo
    local refreshedPreferred = refreshRuntimePlayerInfo(preferredInfo)
    if refreshedPreferred ~= nil then
      refreshedPreferred = enrichPlayerInfoFromServerLog(refreshedPreferred)
      if targetRuntime ~= "" and runtimeKeyMatches(refreshedPreferred, targetRuntime) then return refreshedPreferred end
      if targetSteam == "" and targetName == "" and targetRuntime == "" then return refreshedPreferred end
      if targetSteam ~= "" and tostring(refreshedPreferred.steam or ""):lower():find(targetSteam, 1, true) then return refreshedPreferred end
      if targetName ~= "" and tostring(refreshedPreferred.name or ""):lower():find(targetName, 1, true) then return refreshedPreferred end
    end
    originalPreferred = enrichPlayerInfoFromServerLog(originalPreferred) or originalPreferred
    if not playerInfoHasLiveRuntime(originalPreferred) then
      local liveCandidate = findPlayer(steamId, name, runtimeKey)
      if liveCandidate ~= nil and playerInfoHasLiveRuntime(liveCandidate) then
        liveCandidate = enrichPlayerInfoFromServerLog(liveCandidate) or liveCandidate
        local matches = false
        if targetRuntime ~= "" and runtimeKeyMatches(liveCandidate, targetRuntime) then matches = true end
        if targetSteam ~= "" and tostring(liveCandidate.steam or ""):lower():find(targetSteam, 1, true) then matches = true end
        if targetName ~= "" and tostring(liveCandidate.name or ""):lower():find(targetName, 1, true) then matches = true end
        if targetSteam == "" and targetName == "" and targetRuntime == "" then matches = true end
        if matches then
          if type(mergeRuntimeIntoIdentity) == "function" then
            return mergeRuntimeIntoIdentity(originalPreferred, liveCandidate)
          end
          return liveCandidate
        end
      end
    end
    if originalPreferred ~= nil then
      if tostring(originalPreferred.steam or "") == "" then originalPreferred.steam = tostring(steamId or "") end
      if tostring(originalPreferred.name or "") == "" or tostring(originalPreferred.name or "") == "Unknown" then originalPreferred.name = tostring(name or "") end
      if targetRuntime ~= "" and runtimeKeyMatches(originalPreferred, targetRuntime) then return originalPreferred end
      if targetSteam == "" and targetName == "" and targetRuntime == "" then return originalPreferred end
      if targetSteam ~= "" and tostring(originalPreferred.steam or ""):lower():find(targetSteam, 1, true) then return originalPreferred end
      if targetName ~= "" and tostring(originalPreferred.name or ""):lower():find(targetName, 1, true) then return originalPreferred end
    end
  end
  local found = enrichPlayerInfoFromServerLog(findPlayer(steamId, name, runtimeKey))
  if found ~= nil then return found end

  if configBool("bridge-safety", { "AllowCommandResolveSingletonRuntimeScan", "allowCommandResolveSingletonRuntimeScan" }, false) then
    local fallbackInfos = listPlayerInfosUnchecked("command-resolve-singleton")
    if fallbackInfos ~= nil and #fallbackInfos == 1 and (targetSteam ~= "" or targetName ~= "" or targetRuntime ~= "") then
      local only = enrichPlayerInfoFromServerLog(fallbackInfos[1]) or fallbackInfos[1]
      local rawSteam = cleanText(steamId)
      local rawName = cleanText(name)
      if looksLikeSteamId(rawSteam) and cleanText(only.steam) == "" then only.steam = rawSteam end
      if rawName ~= "" and (cleanText(only.name) == "" or cleanText(only.name):lower() == "unknown") then only.name = rawName end
      if type(replacePlayerInfoCache) == "function" then
        pcall(function() replacePlayerInfoCache({ only }) end)
      end
      appendLog("player resolve used singleton runtime fallback target=" .. tostring(rawSteam ~= "" and rawSteam or rawName))
      return only
    end
  end

  if configBool("bridge-safety", { "AllowResolveSingletonRuntimeScan", "allowResolveSingletonRuntimeScan" }, false) then
    local fallbackInfos = listPlayerInfosUnchecked("resolve-singleton-fallback")
    if fallbackInfos ~= nil and #fallbackInfos == 1 and (targetSteam ~= "" or targetName ~= "" or targetRuntime ~= "") then
      local only = enrichPlayerInfoFromServerLog(fallbackInfos[1]) or fallbackInfos[1]
      local rawSteam = cleanText(steamId)
      local rawName = cleanText(name)
      if looksLikeSteamId(rawSteam) and cleanText(only.steam) == "" then only.steam = rawSteam end
      if rawName ~= "" and (cleanText(only.name) == "" or cleanText(only.name):lower() == "unknown") then only.name = rawName end
      if type(replacePlayerInfoCache) == "function" then
        pcall(function() replacePlayerInfoCache({ only }) end)
      end
      return only
    end
  end

  return resolvePlayerInfoFromServerLogTarget(steamId, name)
end

function findPlayerByContext(context)
  local cached = cachedPlayerByObject(context)
  if cached ~= nil then return enrichPlayerInfoFromServerLog(cached) or cached end
  local key = objectKey(context)
  local infos = cachedPlayerInfos(math.max(10, configNumber("bridge-safety", { "PlayerInfoCacheTtlSeconds", "playerInfoCacheTtlSeconds" }, 300))) or {}
  if key ~= "" then
    for _, info in ipairs(infos) do
      if info.pcKey == key or info.psKey == key or info.pawnKey == key then return enrichPlayerInfoFromServerLog(info) end
      local rpc = playerRpcChannel(info.pc)
      if objectKey(rpc) == key then return enrichPlayerInfoFromServerLog(info) end
    end
  end
  if #infos == 1 then return enrichPlayerInfoFromServerLog(infos[1]) end
  return nil
end

function gameThreadSchedulerStalled()
  local probe = GAME_THREAD_SCHEDULER_SELFTEST
  if probe == nil then return false end
  return probe.ok ~= true and probe.reported == true
end

-- UE4SS exports may be absent or present as sentinel booleans on a given
-- build.  A non-nil check is not enough: calling a boolean from a scheduled
-- callback tears down the loop and can starve the native HTTP bridge.
function schedulerFunction(name)
  local value = nil
  if type(_G) == "table" then value = _G[name] end
  if type(value) == "function" then return value end
  return nil
end

function executeInGameThreadPreferred(fn)
  local executeInGameThread = schedulerFunction("ExecuteInGameThread")
  if executeInGameThread == nil then return false, "ExecuteInGameThread unavailable" end
  local attempts = {}
  if ProcessEventAvailable == true and EGameThreadMethod ~= nil and EGameThreadMethod.ProcessEvent ~= nil then
    table.insert(attempts, { "ProcessEvent", EGameThreadMethod.ProcessEvent })
  end
  if EngineTickAvailable == true and EGameThreadMethod ~= nil and EGameThreadMethod.EngineTick ~= nil then
    table.insert(attempts, { "EngineTick", EGameThreadMethod.EngineTick })
  end
  table.insert(attempts, { "default", nil })
  local lastErr = nil
  for _, attempt in ipairs(attempts) do
    local okThread, err = pcall(function()
      if attempt[2] ~= nil then
        executeInGameThread(fn, attempt[2])
      else
        executeInGameThread(fn)
      end
    end)
    if okThread then return true, attempt[1] end
    lastErr = err
  end
  return false, lastErr
end

function deferGame(delayMs, fn)
  if gameThreadSchedulerStalled() then
    local okNow, err = pcall(fn)
    if not okNow then appendLog("deferred task inline (scheduler stalled): " .. tostring(err)) end
    return okNow
  end
  local executeInGameThreadWithDelay = schedulerFunction("ExecuteInGameThreadWithDelay")
  if executeInGameThreadWithDelay ~= nil then
    local okDelay, err = pcall(function()
      executeInGameThreadWithDelay(delayMs or 50, function()
        local okRun, runErr = pcall(fn)
        if not okRun then appendLog("deferred game-thread task failed: " .. tostring(runErr)) end
      end)
    end)
    if okDelay then return true end
    appendLog("ExecuteInGameThreadWithDelay failed: " .. tostring(err))
  end
  local executeWithDelay = schedulerFunction("ExecuteWithDelay")
  if executeWithDelay ~= nil then
    local okDelay, err = pcall(function()
      executeWithDelay(delayMs or 50, function()
        if schedulerFunction("ExecuteInGameThread") ~= nil then
          local okThread, threadErr = executeInGameThreadPreferred(fn)
          if okThread then return end
          appendLog("ExecuteInGameThread delayed task failed: " .. tostring(threadErr))
        end
        local okRun, runErr = pcall(fn)
        if not okRun then appendLog("deferred delayed task failed inline: " .. tostring(runErr)) end
      end)
    end)
    if okDelay then return true end
    appendLog("ExecuteWithDelay failed: " .. tostring(err))
  end
  if schedulerFunction("ExecuteInGameThread") ~= nil then
    local okThread, err = executeInGameThreadPreferred(fn)
    if okThread then return true end
    appendLog("ExecuteInGameThread defer failed: " .. tostring(err))
  end
  local okNow, err = pcall(fn)
  if not okNow then appendLog("deferred task failed inline: " .. tostring(err)) end
  return okNow
end

-- Strict variant for work that can touch live UE objects.  Lua pcall cannot
-- contain a native UE4SS access violation, therefore an async callback must
-- never fall back to executing that work inline.
function deferGameStrict(delayMs, fn, label, onRejected)
  local taskLabel = tostring(label or "game-thread task")
  local function reject(reason)
    appendLog(taskLabel .. " skipped: " .. tostring(reason or "no safe game-thread scheduler"))
    if type(onRejected) == "function" then
      local okReject, rejectErr = pcall(onRejected, tostring(reason or "scheduler unavailable"))
      if not okReject then appendLog(taskLabel .. " reject handler failed: " .. tostring(rejectErr)) end
    end
    return false
  end
  local function run()
    local okRun, runErr = pcall(fn)
    if not okRun then appendLog(taskLabel .. " failed: " .. tostring(runErr)) end
  end

  if gameThreadSchedulerStalled() then
    return reject("game-thread scheduler stalled; inline execution is forbidden")
  end
  local executeInGameThreadWithDelay = schedulerFunction("ExecuteInGameThreadWithDelay")
  if executeInGameThreadWithDelay ~= nil then
    local okDelay, err = pcall(function()
      executeInGameThreadWithDelay(delayMs or 50, run)
    end)
    if okDelay then return true end
    appendLog(taskLabel .. " ExecuteInGameThreadWithDelay failed: " .. tostring(err))
  end
  local executeWithDelay = schedulerFunction("ExecuteWithDelay")
  if executeWithDelay ~= nil and schedulerFunction("ExecuteInGameThread") ~= nil then
    local okDelay, err = pcall(function()
      executeWithDelay(delayMs or 50, function()
        local okThread, threadErr = executeInGameThreadPreferred(run)
        if not okThread then reject("delayed game-thread dispatch failed: " .. tostring(threadErr)) end
      end)
    end)
    if okDelay then return true end
    appendLog(taskLabel .. " ExecuteWithDelay failed: " .. tostring(err))
  end
  if schedulerFunction("ExecuteInGameThread") ~= nil then
    local okThread, threadErr = executeInGameThreadPreferred(run)
    if okThread then return true end
    return reject("game-thread dispatch failed: " .. tostring(threadErr))
  end
  return reject("ExecuteInGameThread is unavailable")
end

function deferAsync(delayMs, fn)
  local executeWithDelay = schedulerFunction("ExecuteWithDelay")
  if executeWithDelay ~= nil then
    local okDelay, err = pcall(function()
      executeWithDelay(delayMs or 50, function()
        local okRun, runErr = pcall(fn)
        if not okRun then appendLog("deferred async task failed: " .. tostring(runErr)) end
      end)
    end)
    if okDelay then return true end
    appendLog("ExecuteWithDelay async failed: " .. tostring(err))
  end
  return deferGame(delayMs, fn)
end

PLAYERS_JSON_CACHE = PLAYERS_JSON_CACHE or nil
PLAYERS_JSON_CACHE_AT = PLAYERS_JSON_CACHE_AT or 0

function liveRuntimePlayersJson()
  local runtimeReady, runtimeReason, runtimeAge = runtimeScanAllowed()
  if not runtimeReady then return nil, runtimeReason, runtimeAge end

  local cacheTtl = math.max(10, configNumber("bridge-safety", { "PlayerInfoCacheTtlSeconds", "playerInfoCacheTtlSeconds" }, 300))
  local infos = cachedPlayerInfos(cacheTtl)
  if (infos == nil or #infos == 0) and configBool("bridge-safety", { "AllowPlayersJsonRuntimeScan", "allowPlayersJsonRuntimeScan" }, false) then
    if type(refreshPlayerInfoCacheForPanel) == "function" then
      refreshPlayerInfoCacheForPanel("players-json", false)
      infos = cachedPlayerInfos(cacheTtl) or PLAYER_INFO_CACHE or {}
    else
      infos = listPlayerInfos()
    end
  end
  if infos == nil or #infos == 0 then return nil, "runtime returned no live players", runtimeAge end

  local snapshot = serverLogOnlineSnapshot()
  local parts = {}
  for _, info in ipairs(infos) do
    local p = enrichPlayerInfoFromServerLog(info) or info
    local x = tonumber(p.x)
    local y = tonumber(p.y)
    local z = tonumber(p.z)
    local hasLiveLocation = x ~= nil and y ~= nil and z ~= nil and (math.abs(x) + math.abs(y) + math.abs(z)) > 1
    table.insert(parts, '{"name":' .. js(p.name ~= "" and p.name or "Unknown") ..
      ',"steamId":' .. js(p.steam or "") ..
      ',"online":true' ..
      ',"status":"online"' ..
      ',"source":"ue4ss-live"' ..
      ',"positionSource":' .. js(hasLiveLocation and "ue4ss-live" or "runtime-no-location") ..
      ',"x":' .. tostring(x or 0) ..
      ',"y":' .. tostring(y or 0) ..
      ',"z":' .. tostring(z or 0) ..
      ',"userProfileId":' .. js(p.userProfileId or "") ..
      ',"serverUserProfileId":' .. js(p.serverUserProfileId or p.userProfileId or "") ..
      ',"runtimeKey":' .. js(p.runtimeKey or "") ..
      ',"runtimeReady":true' ..
      '}')
  end

  return '{"players":[' .. table.concat(parts, ",") .. '],"count":' .. tostring(#parts) ..
    ',"source":"ue4ss-live","runtimeReady":true' ..
    ',"runtimeReason":' .. js(runtimeReason or "") ..
    ',"runtimeAgeSeconds":' .. tostring(tonumber(runtimeAge or -1) or -1) ..
    ',"serverStats":{"playerCount":' .. tostring(tonumber(snapshot and snapshot.playerCount or -1) or -1) ..
    ',"fresh":' .. ((snapshot and snapshot.statsFresh) and "true" or "false") ..
    ',"ageSeconds":' .. tostring(tonumber(snapshot and snapshot.statsAgeSeconds or -1) or -1) ..
    ',"lastLine":' .. js((snapshot and snapshot.lastLine) or "") ..
    '}}'
end

function playersJson()
  local now = os.clock()
  local cacheSeconds = math.max(3, configNumber("bridge-safety", { "PlayersJsonCacheSeconds", "playersJsonCacheSeconds" }, 15))
  if PLAYERS_JSON_CACHE ~= nil and (now - (tonumber(PLAYERS_JSON_CACHE_AT) or 0)) < cacheSeconds then
    return PLAYERS_JSON_CACHE
  end

  local liveJson, liveReason = liveRuntimePlayersJson()
  if liveJson ~= nil then
    PLAYERS_JSON_CACHE = liveJson
    PLAYERS_JSON_CACHE_AT = now
    return liveJson
  end

  local logJson = serverLogPlayersJson()
  if liveReason ~= nil and (PLAYERS_JSON_FALLBACK_LOG_AT == nil or (now - PLAYERS_JSON_FALLBACK_LOG_AT) > 30) then
    PLAYERS_JSON_FALLBACK_LOG_AT = now
    appendLog("playersJson fallback to server-log: " .. tostring(liveReason))
  end
  PLAYERS_JSON_CACHE = logJson
  PLAYERS_JSON_CACHE_AT = now
  return logJson
end

CURRENT_BRIDGE_RESULT_ID = ""

function resultIdJson(requestId)
  local id = tostring(requestId or CURRENT_BRIDGE_RESULT_ID or "")
  if id == "" then return "" end
  return ',"id":' .. js(id)
end

function ok(command, message, dataJson, requestId)
  return '{"ok":true' .. resultIdJson(requestId) .. ',"source":"ue4ss","command":' .. js(command) .. ',"message":' .. js(message or "ok") .. ',"data":' .. (dataJson or "{}") .. '}'
end

function fail(command, message, requestId)
  return '{"ok":false' .. resultIdJson(requestId) .. ',"source":"ue4ss","command":' .. js(command) .. ',"message":' .. js(message or "failed") .. '}'
end

function failWithData(command, message, dataJson, requestId)
  local data = tostring(dataJson or "{}")
  if data == "" or data:sub(1, 1) ~= "{" then data = "{}" end
  return '{"ok":false' .. resultIdJson(requestId) .. ',"source":"ue4ss","command":' .. js(command) .. ',"message":' .. js(message or "failed") .. ',"data":' .. data .. '}'
end

NATIVE_TRADER_LUA_HOST = NATIVE_TRADER_LUA_HOST or { attempted = false, loaded = false, tick = nil, path = "", lastError = "" }

function nativeTraderEnsureLuaHost()
  local host = NATIVE_TRADER_LUA_HOST or { attempted = false, loaded = false, tick = nil, path = "", lastError = "" }
  NATIVE_TRADER_LUA_HOST = host
  if host.loaded == true and type(host.tick) == "function" then return true end
  if host.attempted == true then return false end
  host.attempted = true
  if package == nil or type(package.loadlib) ~= "function" then
    host.lastError = "package.loadlib is unavailable"
    appendLog("native trader lua host unavailable: " .. host.lastError)
    return false
  end
  local candidates = {
    "ue4ss\\Mods\\SCUMTraderManager\\dlls\\main.dll",
    "Mods\\SCUMTraderManager\\dlls\\main.dll",
    "ue4ss\\Mods\\SCUMTraderManager\\main.dll",
    "Mods\\SCUMTraderManager\\main.dll"
  }
  for _, path in ipairs(candidates) do
    if readAll(path) ~= nil then
      local okLoad, fnOrErr = pcall(function() return package.loadlib(path, "scum_trader_native_tick") end)
      if okLoad and type(fnOrErr) == "function" then
        host.loaded = true
        host.tick = fnOrErr
        host.path = path
        host.lastError = ""
        local okInline, inlineFnOrErr = pcall(function() return package.loadlib(path, "scum_trader_native_tick_inline") end)
        if okInline and type(inlineFnOrErr) == "function" then
          host.inlineTick = inlineFnOrErr
          host.inlineError = ""
        else
          host.inlineTick = nil
          host.inlineError = tostring(inlineFnOrErr or "inline loadlib returned nil")
        end
        appendLog("native trader lua host loaded path=" .. tostring(path))
        return true
      end
      host.lastError = tostring(fnOrErr or "loadlib returned nil")
    end
  end
  if host.lastError == "" then
    host.lastError = "SCUMTraderManager dll not installed"
    appendLog("native trader lua host skipped: " .. tostring(host.lastError))
  else
    appendLog("native trader lua host load failed: " .. tostring(host.lastError))
  end
  return false
end

function nativeTraderTickLuaHost()
  if not nativeTraderEnsureLuaHost() then return false end
  local host = NATIVE_TRADER_LUA_HOST or {}
  if type(host.tick) ~= "function" then return false end
  local okTick, err = pcall(host.tick)
  if not okTick then
    host.loaded = false
    host.tick = nil
    host.lastError = tostring(err)
    appendLog("native trader lua host tick failed: " .. tostring(err))
    return false
  end
  return true
end

function nativeTraderTickLuaInlineHost()
  if not nativeTraderEnsureLuaHost() then return false end
  local host = NATIVE_TRADER_LUA_HOST or {}
  if type(host.inlineTick) ~= "function" then
    appendLog("native trader inline host unavailable: " .. tostring(host.inlineError or "missing export"))
    return false
  end
  local okTick, err = pcall(host.inlineTick)
  if not okTick then
    host.inlineTick = nil
    host.inlineError = tostring(err)
    appendLog("native trader inline host tick failed: " .. tostring(err))
    return false
  end
  return true
end

-- SCUMTraderManager uses one command/result file pair. Serialise async work so
-- concurrent panel probes cannot overwrite each other's command or result.
NATIVE_TRADER_ASYNC_QUEUE = NATIVE_TRADER_ASYNC_QUEUE or {}
NATIVE_TRADER_ASYNC_ACTIVE = NATIVE_TRADER_ASYNC_ACTIVE or nil
NATIVE_TRADER_ASYNC_SEQUENCE = NATIVE_TRADER_ASYNC_SEQUENCE or 0

function nativeTraderCommand(commandName, payloadJson, timeoutMs, requestId)
  if NATIVE_TRADER_ASYNC_ACTIVE ~= nil or #(NATIVE_TRADER_ASYNC_QUEUE or {}) > 0 then
    return false, "SCUMTraderManager занят асинхронной командой; повтори действие через несколько секунд.", "{\"queued\":true}"
  end
  local id = tostring(requestId or "") ~= "" and tostring(requestId) or (tostring(os.time()) .. "-" .. tostring(math.floor(os.clock() * 1000000)))
  local command = tostring(commandName or "")
  if command == "" then return false, "native trader command is empty", "{}" end
  local payload = tostring(payloadJson or "{}")
  if payload == "" or payload:sub(1, 1) ~= "{" or payload:sub(-1) ~= "}" then payload = "{}" end
  mkdir(STATE_DIR)
  os.remove(NATIVE_TRADER_RESULT_FILE)
  local text = '{"id":' .. js(id) .. ',"command":' .. js(command) .. ',"payload":' .. payload .. '}'
  if not writeAll(NATIVE_TRADER_COMMAND_FILE, text) then
    return false, "Не удалось записать команду для SCUMTraderManager C++ mod.", "{}"
  end
  nativeTraderTickLuaHost()
  local deadline = wallDeadlineSeconds(timeoutMs, 3500, 0.5, 15)
  local lastText = ""
  while wallClockSeconds() < deadline do
    nativeTraderTickLuaHost()
    local result = readAll(NATIVE_TRADER_RESULT_FILE)
    if result ~= nil and result ~= "" then
      lastText = result
      local resultId = extractString(result, "id") or ""
      if resultId == id or resultId == "" then
        local resultOk = extractBool(result, "ok", false) == true
        local message = extractString(result, "message") or (resultOk and "SCUMTraderManager command ok" or "SCUMTraderManager command failed")
        os.remove(NATIVE_TRADER_RESULT_FILE)
        return resultOk, message, result
      end
    end
    if Sleep ~= nil then
      Sleep(100)
    else
      local spinUntil = os.clock() + 0.025
      while os.clock() < spinUntil do end
    end
  end
  return false, "SCUMTraderManager C++ mod не ответил за timeout.", '{"id":' .. js(id) .. ',"command":' .. js(command) .. ',"lastResult":' .. js(lastText) .. '}'
end

function nativeHttpCommand(commandName, payloadJson, timeoutMs, requestId)
  local id = tostring(requestId or "") ~= "" and tostring(requestId) or (tostring(os.time()) .. "-" .. tostring(math.floor(os.clock() * 1000000)))
  local command = tostring(commandName or "")
  if command == "" then return false, "native http command is empty", "{}" end
  local payload = tostring(payloadJson or "{}")
  if payload == "" or payload:sub(1, 1) ~= "{" or payload:sub(-1) ~= "}" then payload = "{}" end
  mkdir(STATE_DIR)
  os.remove(NATIVE_HTTP_RESULT_FILE)
  local text = '{"id":' .. js(id) .. ',"command":' .. js(command) .. ',"payload":' .. payload .. '}'
  if not writeAll(NATIVE_HTTP_COMMAND_FILE, text) then
    return false, "Не удалось записать команду для native HTTP bridge.", "{}"
  end
  local deadline = wallDeadlineSeconds(timeoutMs, 2500, 0.2, 20)
  local lastText = ""
  while wallClockSeconds() < deadline do
    local result = readAll(NATIVE_HTTP_RESULT_FILE)
    if result ~= nil and result ~= "" then
      lastText = result
      local resultId = extractString(result, "id") or ""
      if resultId == id or resultId == "" then
        local resultOk = extractBool(result, "ok", false) == true
        local message = extractString(result, "message") or (resultOk and "native HTTP command ok" or "native HTTP command failed")
        os.remove(NATIVE_HTTP_RESULT_FILE)
        return resultOk, message, result
      end
    end
    if Sleep ~= nil then
      Sleep(100)
    else
      local spinUntil = os.clock() + 0.025
      while os.clock() < spinUntil do end
    end
  end
  return false, "native HTTP bridge не ответил за timeout.", '{"id":' .. js(id) .. ',"command":' .. js(command) .. ',"lastResult":' .. js(lastText) .. '}'
end

-- The native HTTP bridge has one command/result file pair.  Never poll it from a
-- game callback: keep one request active and resume through the UE4SS scheduler.
NATIVE_HTTP_ASYNC_QUEUE = NATIVE_HTTP_ASYNC_QUEUE or {}
NATIVE_HTTP_ASYNC_ACTIVE = NATIVE_HTTP_ASYNC_ACTIVE or nil
NATIVE_HTTP_ASYNC_PUMP_SCHEDULED = NATIVE_HTTP_ASYNC_PUMP_SCHEDULED or false
NATIVE_HTTP_ASYNC_SEQUENCE = NATIVE_HTTP_ASYNC_SEQUENCE or 0

function nativeHttpAsyncRequestId(requestId)
  local configured = tostring(requestId or "")
  if configured ~= "" then return configured end
  NATIVE_HTTP_ASYNC_SEQUENCE = (tonumber(NATIVE_HTTP_ASYNC_SEQUENCE) or 0) + 1
  return tostring(os.time()) .. "-http-" .. tostring(NATIVE_HTTP_ASYNC_SEQUENCE)
end

function nativeHttpAsyncInvoke(job, resultOk, message, result)
  if job == nil or type(job.onResult) ~= "function" then return end
  local function runHandler()
    local okHandler, handlerErr = pcall(job.onResult,
      resultOk == true,
      tostring(message or ""),
      tostring(result or "{}"),
      tostring(job.resultCommand or ""),
      tostring(job.nativeCommand or ""))
    if not okHandler then
      appendLog("native HTTP async result handler failed command=" .. tostring((job or {}).nativeCommand or "") .. " err=" .. tostring(handlerErr))
    end
  end
  if type(deferGame) == "function" and deferGame(1, runHandler) then return end
  runHandler()
end

function nativeHttpAsyncFailPending(message)
  local pending = NATIVE_HTTP_ASYNC_QUEUE or {}
  NATIVE_HTTP_ASYNC_QUEUE = {}
  for _, job in ipairs(pending) do
    nativeHttpAsyncInvoke(job, false, message, '{"queued":false,"scheduler":false}')
  end
end

function nativeHttpAsyncSchedule(delayMs)
  if NATIVE_HTTP_ASYNC_PUMP_SCHEDULED == true then return true end
  local delay = math.max(1, math.floor(tonumber(delayMs) or 100))
  NATIVE_HTTP_ASYNC_PUMP_SCHEDULED = true
  local function runPump()
    NATIVE_HTTP_ASYNC_PUMP_SCHEDULED = false
    nativeHttpAsyncPump()
  end
  local scheduled = false
  local lastErr = nil
  local executeWithDelay = schedulerFunction("ExecuteWithDelay")
  if executeWithDelay ~= nil then
    local okDelay, err = pcall(function() executeWithDelay(delay, runPump) end)
    if okDelay then scheduled = true else lastErr = err end
  end
  local executeInGameThreadWithDelay = schedulerFunction("ExecuteInGameThreadWithDelay")
  if not scheduled and executeInGameThreadWithDelay ~= nil then
    local okDelay, err = pcall(function() executeInGameThreadWithDelay(delay, runPump) end)
    if okDelay then scheduled = true else lastErr = err end
  end
  if scheduled then
    return true
  end
  NATIVE_HTTP_ASYNC_PUMP_SCHEDULED = false
  appendLog("native HTTP async scheduler unavailable: " .. tostring(lastErr or "missing ExecuteWithDelay"))
  return false
end

function nativeHttpAsyncComplete(job, resultOk, message, result)
  if job == nil or NATIVE_HTTP_ASYNC_ACTIVE ~= job then return end
  NATIVE_HTTP_ASYNC_ACTIVE = nil
  nativeHttpAsyncInvoke(job, resultOk, message, result)
  if #(NATIVE_HTTP_ASYNC_QUEUE or {}) > 0 and not nativeHttpAsyncSchedule(1) then
    nativeHttpAsyncFailPending("Не удалось запланировать ожидание native HTTP bridge.")
  end
end

function nativeHttpAsyncStartNext()
  if NATIVE_HTTP_ASYNC_ACTIVE ~= nil then return true end
  local job = table.remove(NATIVE_HTTP_ASYNC_QUEUE, 1)
  if job == nil then return true end
  mkdir(STATE_DIR)
  os.remove(NATIVE_HTTP_RESULT_FILE)
  local text = '{"id":' .. js(job.id) .. ',"command":' .. js(job.nativeCommand) .. ',"payload":' .. job.payloadJson .. '}'
  if not writeAll(NATIVE_HTTP_COMMAND_FILE, text) then
    nativeHttpAsyncInvoke(job, false, "Не удалось записать команду для native HTTP bridge.", "{}")
    if #(NATIVE_HTTP_ASYNC_QUEUE or {}) > 0 and not nativeHttpAsyncSchedule(1) then
      nativeHttpAsyncFailPending("Не удалось запланировать ожидание native HTTP bridge.")
    end
    return false
  end
  job.startedAt = wallClockSeconds()
  job.staleResultLogs = 0
  NATIVE_HTTP_ASYNC_ACTIVE = job
  appendLog("native HTTP async start id=" .. tostring(job.id) .. " command=" .. tostring(job.nativeCommand))
  if nativeHttpAsyncSchedule(100) then return true end
  NATIVE_HTTP_ASYNC_ACTIVE = nil
  nativeHttpAsyncInvoke(job, false, "Не удалось запланировать ожидание native HTTP bridge.", '{"scheduler":false}')
  nativeHttpAsyncFailPending("Не удалось запланировать ожидание native HTTP bridge.")
  return false
end

function nativeHttpAsyncPump()
  local job = NATIVE_HTTP_ASYNC_ACTIVE
  if job == nil then
    nativeHttpAsyncStartNext()
    return
  end
  local result = readAll(NATIVE_HTTP_RESULT_FILE)
  if result ~= nil and result ~= "" then
    local resultId = extractString(result, "id") or ""
    if resultId == job.id or resultId == "" then
      local resultOk = extractBool(result, "ok", false) == true
      local message = extractString(result, "message") or (resultOk and "native HTTP command ok" or "native HTTP command failed")
      os.remove(NATIVE_HTTP_RESULT_FILE)
      nativeHttpAsyncComplete(job, resultOk, message, result)
      return
    end
    job.staleResultLogs = tonumber(job.staleResultLogs or 0) or 0
    if job.staleResultLogs < 3 then
      job.staleResultLogs = job.staleResultLogs + 1
      appendLog("native HTTP async ignored stale result expected=" .. tostring(job.id) .. " actual=" .. tostring(resultId))
    end
    os.remove(NATIVE_HTTP_RESULT_FILE)
  end
  local elapsed = os.difftime(wallClockSeconds(), tonumber(job.startedAt) or wallClockSeconds())
  if elapsed >= wallTimeoutSeconds(job.timeoutMs, 2500, 0.2, 20) then
    local timeoutData = '{"id":' .. js(job.id) .. ',"nativeCommand":' .. js(job.nativeCommand) .. ',"timeout":true}'
    appendLog("native HTTP async timeout id=" .. tostring(job.id) .. " command=" .. tostring(job.nativeCommand))
    nativeHttpAsyncComplete(job, false, "native HTTP bridge не ответил за timeout.", timeoutData)
    return
  end
  if not nativeHttpAsyncSchedule(100) then
    nativeHttpAsyncComplete(job, false, "Не удалось запланировать ожидание native HTTP bridge.", '{"scheduler":false}')
  end
end

function nativeHttpCommandAsync(resultCommand, nativeCommand, payloadJson, timeoutMs, requestId, onResult)
  local command = tostring(nativeCommand or "")
  if command == "" then return false, "native HTTP command is empty" end
  local payload = tostring(payloadJson or "{}")
  if payload == "" or payload:sub(1, 1) ~= "{" or payload:sub(-1) ~= "}" then payload = "{}" end
  local job = {
    id = nativeHttpAsyncRequestId(requestId),
    resultCommand = tostring(resultCommand or command),
    nativeCommand = command,
    payloadJson = payload,
    timeoutMs = timeoutMs,
    onResult = onResult
  }
  table.insert(NATIVE_HTTP_ASYNC_QUEUE, job)
  appendLog("native HTTP async queued id=" .. tostring(job.id) .. " command=" .. tostring(command) .. " depth=" .. tostring(#NATIVE_HTTP_ASYNC_QUEUE))
  if NATIVE_HTTP_ASYNC_ACTIVE == nil and not nativeHttpAsyncSchedule(1) then
    for index, queued in ipairs(NATIVE_HTTP_ASYNC_QUEUE) do
      if queued == job then table.remove(NATIVE_HTTP_ASYNC_QUEUE, index) break end
    end
    return false, "Не удалось запланировать native HTTP bridge."
  end
  return true, job.id, "__async__"
end

function nativeVehicleLatestEntityId(vehicleId, timeoutMs, requestId)
  local cleanVehicle = canonicalVehicleId(vehicleId)
  if cleanVehicle == "" then return false, "vehicle id is empty", 0, "{}" end
  local okNative, message, result = nativeHttpCommand("vehicle_latest_entity_id",
    '{"vehicleId":' .. js(cleanVehicle) .. '}',
    timeoutMs or 1500,
    requestId)
  local entityId = math.floor(extractNumber(result or "", "entityId") or 0)
  return okNative, message, entityId, result or "{}"
end

function nativeVehicleWaitNewEntityId(vehicleId, beforeEntityId, timeoutMs, requestId)
  local cleanVehicle = canonicalVehicleId(vehicleId)
  if cleanVehicle == "" then return false, "vehicle id is empty", 0, "{}" end
  local waitMs = math.max(500, math.min(tonumber(timeoutMs) or 12000, 20000))
  local okNative, message, result = nativeHttpCommand("vehicle_wait_new_entity_id",
    '{"vehicleId":' .. js(cleanVehicle) ..
    ',"beforeEntityId":' .. tostring(math.max(0, math.floor(tonumber(beforeEntityId or 0) or 0))) ..
    ',"timeoutMs":' .. tostring(waitMs) .. '}',
    waitMs + 2500,
    requestId)
  local entityId = math.floor(extractNumber(result or "", "entityId") or 0)
  return okNative, message, entityId, result or "{}"
end

function vehicleNativeDbResolveEnabled(options)
  options = options or {}
  if options.skipNativeVehicleDbResolve == true or options.disableNativeVehicleDbResolve == true then return false end
  return configBool("vehicle-rental", {
    "EnableNativeVehicleDbResolve", "enableNativeVehicleDbResolve",
    "EnableVehicleDbResolve", "enableVehicleDbResolve"
  }, true)
end

function nativeVehicleLatestEntityIdAsync(vehicleId, timeoutMs, requestId, onResult)
  local cleanVehicle = canonicalVehicleId(vehicleId)
  if cleanVehicle == "" then return false, "vehicle id is empty" end
  return nativeHttpCommandAsync("vehicle_latest_entity_id", "vehicle_latest_entity_id",
    '{"vehicleId":' .. js(cleanVehicle) .. '}',
    timeoutMs or 1500,
    requestId,
    function(okNative, message, result)
      local entityId = math.max(0, math.floor(extractNumber(result or "", "entityId") or 0))
      if type(onResult) == "function" then onResult(okNative == true, tostring(message or ""), entityId, result or "{}") end
    end)
end

function nativeVehicleWaitNewEntityIdAsync(vehicleId, beforeEntityId, timeoutMs, requestId, onResult)
  local cleanVehicle = canonicalVehicleId(vehicleId)
  if cleanVehicle == "" then return false, "vehicle id is empty" end
  local waitMs = math.max(500, math.min(tonumber(timeoutMs) or 12000, 20000))
  return nativeHttpCommandAsync("vehicle_wait_new_entity_id", "vehicle_wait_new_entity_id",
    '{"vehicleId":' .. js(cleanVehicle) ..
    ',"beforeEntityId":' .. tostring(math.max(0, math.floor(tonumber(beforeEntityId or 0) or 0))) ..
    ',"timeoutMs":' .. tostring(waitMs) .. '}',
    waitMs + 2500,
    requestId,
    function(okNative, message, result)
      local entityId = math.max(0, math.floor(extractNumber(result or "", "entityId") or 0))
      if type(onResult) == "function" then onResult(okNative == true, tostring(message or ""), entityId, result or "{}") end
    end)
end

function nativeTraderCommandInline(commandName, payloadJson, timeoutMs, requestId)
  local id = tostring(requestId or "") ~= "" and tostring(requestId) or (tostring(os.time()) .. "-" .. tostring(math.floor(os.clock() * 1000000)))
  local command = tostring(commandName or "")
  if command == "" then return false, "native trader inline command is empty", "{}" end
  local payload = tostring(payloadJson or "{}")
  if payload == "" or payload:sub(1, 1) ~= "{" or payload:sub(-1) ~= "}" then payload = "{}" end
  mkdir(STATE_DIR)
  os.remove(NATIVE_TRADER_INLINE_RESULT_FILE)
  local text = '{"id":' .. js(id) .. ',"command":' .. js(command) .. ',"inlineGameThread":true,"payload":' .. payload .. '}'
  if not writeAll(NATIVE_TRADER_INLINE_COMMAND_FILE, text) then
    return false, "Не удалось записать inline-команду для SCUMTraderManager C++ mod.", "{}"
  end
  if not nativeTraderTickLuaInlineHost() then
    os.remove(NATIVE_TRADER_INLINE_COMMAND_FILE)
    return false, "SCUMTraderManager inline C++ route недоступен.", '{"id":' .. js(id) .. ',"command":' .. js(command) .. '}'
  end
  local deadline = wallDeadlineSeconds(timeoutMs, 3500, 0.2, 5)
  local lastText = ""
  while wallClockSeconds() < deadline do
    local result = readAll(NATIVE_TRADER_INLINE_RESULT_FILE)
    if result ~= nil and result ~= "" then
      lastText = result
      local resultId = extractString(result, "id") or ""
      if resultId == id or resultId == "" then
        local resultOk = extractBool(result, "ok", false) == true
        local message = extractString(result, "message") or (resultOk and "SCUMTraderManager inline command ok" or "SCUMTraderManager inline command failed")
        os.remove(NATIVE_TRADER_INLINE_RESULT_FILE)
        os.remove(NATIVE_TRADER_INLINE_COMMAND_FILE)
        return resultOk, message, result
      end
    end
    if Sleep ~= nil then
      Sleep(20)
    else
      local spinUntil = os.clock() + 0.01
      while os.clock() < spinUntil do end
    end
  end
  os.remove(NATIVE_TRADER_INLINE_COMMAND_FILE)
  return false, "SCUMTraderManager inline C++ mod не вернул result.", '{"id":' .. js(id) .. ',"command":' .. js(command) .. ',"lastResult":' .. js(lastText) .. '}'
end

function nativeTraderStartCommand(commandName, payloadJson, requestId)
  local id = tostring(requestId or "") ~= "" and tostring(requestId) or (tostring(os.time()) .. "-" .. tostring(math.floor(os.clock() * 1000000)))
  local command = tostring(commandName or "")
  if command == "" then return false, "native trader command is empty" end
  local payload = tostring(payloadJson or "{}")
  if payload == "" or payload:sub(1, 1) ~= "{" or payload:sub(-1) ~= "}" then payload = "{}" end
  mkdir(STATE_DIR)
  os.remove(NATIVE_TRADER_RESULT_FILE)
  local text = '{"id":' .. js(id) .. ',"command":' .. js(command) .. ',"payload":' .. payload .. '}'
  if not writeAll(NATIVE_TRADER_COMMAND_FILE, text) then
    return false, "Не удалось записать команду для SCUMTraderManager C++ mod."
  end
  nativeTraderTickLuaHost()
  return true, id
end

function nativeTraderAsyncInvoke(job, resultOk, message, result)
  if job == nil or type(job.onResult) ~= "function" then return end
  local okHandler, handlerErr = pcall(job.onResult,
    resultOk == true,
    tostring(message or ""),
    tostring(result or "{}"),
    tostring(job.resultCommand or ""),
    tostring(job.nativeCommand or ""))
  if not okHandler then
    appendLog("native result handler failed for " .. tostring(job.resultCommand or "") .. ": " .. tostring(handlerErr))
  end
end

function nativeTraderAsyncComplete(job, resultOk, message, result)
  if job == nil or NATIVE_TRADER_ASYNC_ACTIVE ~= job then return end
  NATIVE_TRADER_ASYNC_ACTIVE = nil
  if job.completed == true then return end
  job.completed = true
  local data = tostring(result or "{}")
  nativeTraderAsyncInvoke(job, resultOk, message, data)
  if resultOk == true then
    writeAll(RESULT_FILE, ok(job.resultCommand, tostring(message or "SCUMTraderManager command ok"), data, job.id))
  else
    writeAll(RESULT_FILE, failWithData(job.resultCommand, tostring(message or "SCUMTraderManager command failed"), data, job.id))
  end
  appendActionEvent("native_trader_cppmod", resultOk == true, nil, tostring(message or ""),
    '{"nativeCommand":' .. js(job.nativeCommand or "") .. ',"id":' .. js(job.id or "") .. ',"nativeResponse":' .. data .. '}')
  if #(NATIVE_TRADER_ASYNC_QUEUE or {}) > 0 then nativeTraderAsyncStartNext() end
end

function nativeTraderAsyncPoll(job)
  if job == nil or NATIVE_TRADER_ASYNC_ACTIVE ~= job or job.completed == true then return end
  nativeTraderTickLuaHost()
  local result = readAll(NATIVE_TRADER_RESULT_FILE)
  if result ~= nil and result ~= "" then
    local resultId = extractString(result, "id") or ""
    if resultId == tostring(job.id or "") or resultId == "" then
      local resultOk = extractBool(result, "ok", false) == true
      local message = extractString(result, "message") or (resultOk and "SCUMTraderManager command ok" or "SCUMTraderManager command failed")
      os.remove(NATIVE_TRADER_RESULT_FILE)
      nativeTraderAsyncComplete(job, resultOk, message, result)
      return
    end
    appendLog("native trader async stale result ignored expected=" .. tostring(job.id or "") .. " actual=" .. tostring(resultId))
    os.remove(NATIVE_TRADER_RESULT_FILE)
  end
  if os.difftime(wallClockSeconds(), tonumber(job.startedAt) or wallClockSeconds()) >= wallTimeoutSeconds(job.timeoutMs, 5000, 0.5, 20) then
    os.remove(NATIVE_TRADER_COMMAND_FILE)
    local message = "SCUMTraderManager C++ mod не ответил за timeout."
    local timeoutData = '{"id":' .. js(job.id or "") .. ',"nativeCommand":' .. js(job.nativeCommand or "") .. ',"timeout":true}'
    nativeTraderAsyncComplete(job, false, message, timeoutData)
    return
  end
  if not deferAsync(250, function() nativeTraderAsyncPoll(job) end) then
    nativeTraderAsyncComplete(job, false, "Не удалось запланировать ожидание ответа SCUMTraderManager C++ mod.",
      '{"id":' .. js(job.id or "") .. ',"scheduler":false}')
  end
end

function nativeTraderAsyncStartNext()
  if NATIVE_TRADER_ASYNC_ACTIVE ~= nil then return true end
  local job = table.remove(NATIVE_TRADER_ASYNC_QUEUE, 1)
  if job == nil then return true end
  NATIVE_TRADER_ASYNC_ACTIVE = job
  local okStart, idOrMessage = nativeTraderStartCommand(job.nativeCommand, job.payloadJson, job.requestId)
  if not okStart then
    nativeTraderAsyncComplete(job, false, tostring(idOrMessage or "Не удалось отправить команду SCUMTraderManager."),
      '{"id":' .. js(job.requestId or "") .. ',"nativeCommand":' .. js(job.nativeCommand or "") .. ',"queued":false}')
    return true
  end
  job.id = tostring(idOrMessage)
  job.startedAt = wallClockSeconds()
  appendActionEvent("native_trader_cppmod_queue", true, nil, "Команда отправлена в SCUMTraderManager C++ mod.",
    '{"nativeCommand":' .. js(job.nativeCommand or "") .. ',"id":' .. js(job.id) .. ',"remaining":' .. tostring(#(NATIVE_TRADER_ASYNC_QUEUE or {})) .. '}')
  if not deferAsync(250, function() nativeTraderAsyncPoll(job) end) then
    nativeTraderAsyncComplete(job, false, "Не удалось запланировать ожидание ответа SCUMTraderManager C++ mod.",
      '{"id":' .. js(job.id or "") .. ',"scheduler":false}')
  end
  return true
end

function nativeTraderCommandAsync(resultCommand, nativeCommand, payloadJson, timeoutMs, requestId, onResult)
  local command = tostring(nativeCommand or "")
  if command == "" then return false, "native trader command is empty", "{}" end
  local payload = tostring(payloadJson or "{}")
  if payload == "" or payload:sub(1, 1) ~= "{" or payload:sub(-1) ~= "}" then payload = "{}" end
  NATIVE_TRADER_ASYNC_SEQUENCE = (tonumber(NATIVE_TRADER_ASYNC_SEQUENCE) or 0) + 1
  local id = tostring(requestId or "")
  if id == "" then id = tostring(os.time()) .. "-trader-async-" .. tostring(NATIVE_TRADER_ASYNC_SEQUENCE) end
  local job = {
    resultCommand = tostring(resultCommand or command),
    nativeCommand = command,
    payloadJson = payload,
    timeoutMs = timeoutMs,
    requestId = id,
    onResult = onResult
  }
  table.insert(NATIVE_TRADER_ASYNC_QUEUE, job)
  appendLog("native trader async queued id=" .. tostring(id) .. " command=" .. tostring(command) .. " depth=" .. tostring(#NATIVE_TRADER_ASYNC_QUEUE))
  if NATIVE_TRADER_ASYNC_ACTIVE == nil then nativeTraderAsyncStartNext() end
  return nil, "Команда SCUMTraderManager поставлена в безопасную очередь.", "__async__"
end

function nativeTraderStatusAsync(requestId, resultCommand)
  return nativeTraderCommandAsync(resultCommand or "native_trader_status", "native_trader_status", "{}", 10000, requestId)
end

function nativeTraderProbeAsync(requestId, resultCommand)
  return nativeTraderCommandAsync(resultCommand or "native_trader_probe", "native_trader_probe", "{}", 10000, requestId)
end

function nativeArmoryRuntimeProbeAsync(requestId, resultCommand)
