end

function preloadNativeTraderLifecycleAssets(attempts, nativeMode)
  attempts = attempts or {}
  nativeMode = tostring(nativeMode or "")
  if not string.find(nativeMode, "preload%-lifecycle", 1, false) then
    table.insert(attempts, "native trader lifecycle preload skipped")
    return
  end
  local paths = {
    "/Game/ConZ_Files/Economy/BP_TradeOutpostManager",
    "/Game/ConZ_Files/Economy/BP_TradeOutpostManager.BP_TradeOutpostManager_C",
    "/Game/ConZ_Files/Economy/OutpostDescriptions/A_0_TradeOutpostDescription",
    "/Game/ConZ_Files/Economy/OutpostDescriptions/A_0_TradeOutpostDescription.A_0_TradeOutpostDescription",
    "/Game/ConZ_Files/Economy/OutpostDescriptions/B_4_TradeOutpostDescription",
    "/Game/ConZ_Files/Economy/OutpostDescriptions/B_4_TradeOutpostDescription.B_4_TradeOutpostDescription",
    "/Game/ConZ_Files/Economy/OutpostDescriptions/C_2_TradeOutpostDescription",
    "/Game/ConZ_Files/Economy/OutpostDescriptions/C_2_TradeOutpostDescription.C_2_TradeOutpostDescription",
    "/Game/ConZ_Files/Economy/OutpostDescriptions/Z_3_TradeOutpostDescription",
    "/Game/ConZ_Files/Economy/OutpostDescriptions/Z_3_TradeOutpostDescription.Z_3_TradeOutpostDescription"
  }
  for _, path in ipairs(paths) do
    local okLoad, loaded = pcall(function() return LoadAsset(path) end)
    table.insert(attempts, "native trader preload LoadAsset(" .. tostring(path) .. ")=" .. (okLoad and (isValidObject(loaded) and "ok" or "nil") or tostring(loaded)))
  end
end

function preloadNativeTraderActorClass(actorClass, entry, attempts)
  attempts = attempts or {}
  local path = tostring(entry and entry.path or "")
  if path == "" then
    table.insert(attempts, "native trader actor preload skipped: no catalog path for " .. tostring(actorClass or ""))
    return
  end
  local okLoad, loaded = pcall(function() return LoadAsset(path) end)
  table.insert(attempts, "native trader actor preload LoadAsset(" .. path .. ")=" .. (okLoad and (isValidObject(loaded) and "ok" or "nil") or tostring(loaded)))
end

function nativeTraderPersonalityKindForActor(actorClass)
  local actor = tostring(actorClass or ""):lower()
  if actor:find("bank", 1, true) then return "" end
  if actor:find("arm", 1, true) or actor:find("weapon", 1, true) or actor:find("gun", 1, true) then return "Armory" end
  if actor:find("doctor", 1, true) or actor:find("physician", 1, true) or actor:find("medic", 1, true) or actor:find("hospital", 1, true) then return "Doctor" end
  if actor:find("mechanic", 1, true) or actor:find("vehicle", 1, true) or actor:find("car", 1, true) then return "Mechanic" end
  if actor:find("harbour", 1, true) or actor:find("harbor", 1, true) or actor:find("fisher", 1, true) or actor:find("boat", 1, true) then return "Boat_Shop" end
  if actor:find("barber", 1, true) then return "Barber" end
  if actor:find("bartender", 1, true) or actor:find("barmen", 1, true) or actor:find("barman", 1, true) or actor:find("saloon", 1, true) or actor:find("bar", 1, true) then return "Barmen" end
  return "TraderPersonality"
end

function nativeTraderNearestOutpostKey(info)
  local x = tonumber(info and info.x) or 0
  local y = tonumber(info and info.y) or 0
  local centers = {
    { key = "C_2", x = -152584.15234375, y = 289693.0 },
    { key = "B_4", x = 570831.0234375, y = -224794.244140625 },
    { key = "Z_3", x = 21713.100341796875, y = -677039.1875 },
    { key = "A_0", x = -621392.3671875, y = -557528.75 }
  }
  local best = centers[1]
  local bestDistance = nil
  for _, center in ipairs(centers) do
    local dx = x - center.x
    local dy = y - center.y
    local distance = dx * dx + dy * dy
    if bestDistance == nil or distance < bestDistance then
      best = center
      bestDistance = distance
    end
  end
  return best.key
end

function nativeTraderPersonalityPathForActor(actorClass, info)
  local kind = nativeTraderPersonalityKindForActor(actorClass)
  if kind == "" then return "" end
  local outpostKey = nativeTraderStockOutpostKeyForActor(actorClass)
  if outpostKey == "" then
    outpostKey = nativeTraderNearestOutpostKey(info)
  end
  local assetName = "Outpost_" .. outpostKey .. "_" .. kind .. "_Personality_01"
  if kind == "TraderPersonality" then
    assetName = "Outpost_" .. outpostKey .. "_TraderPersonality_01"
  end
  return "/Game/ConZ_Files/Economy/TraderPersonalities/Outpost_" .. outpostKey .. "/" .. assetName .. "." .. assetName
end

function nativeTraderStockOutpostKeyForActor(actorClass)
  local kind = nativeTraderPersonalityKindForActor(actorClass)
  if kind ~= "Armory" then return "" end
  if configBool("armory-command", { "ForceArmoryStockPersonality", "forceArmoryStockPersonality", "ForceStockedArmoryPersonality", "forceStockedArmoryPersonality" }, true) ~= true then
    return ""
  end
  return configString("armory-command", { "ArmoryStockOutpostKey", "armoryStockOutpostKey", "StockOutpostKey", "stockOutpostKey" }, "A_0")
end

function nativeTraderEconomyPreparePayload()
  local prepareEconomy = configBool("armory-command", { "PrepareEconomyForLinkedTrader", "prepareEconomyForLinkedTrader" }, true) == true
  local saleDistance = tonumber(configNumber("armory-command", { "EconomyMaxSaleDistance", "economyMaxSaleDistance", "SaleDistance", "saleDistance" }, 10000000) or 10000000) or 10000000
  local relevancyRange = tonumber(configNumber("armory-command", { "TraderPawnRelevancyRange", "traderPawnRelevancyRange", "RelevancyRange", "relevancyRange" }, 10000000) or 10000000) or 10000000
  local updateTime = tonumber(configNumber("armory-command", { "TradeOutpostsUpdateTime", "tradeOutpostsUpdateTime" }, 5) or 5) or 5
  local forceUnlimitedStock = configBool("armory-command", { "ForceUnlimitedStockForArmory", "forceUnlimitedStockForArmory", "ForceUnlimitedStock", "forceUnlimitedStock" }, true) == true
  local forceUnlimitedFunds = configBool("armory-command", { "ForceUnlimitedFundsForArmory", "forceUnlimitedFundsForArmory", "ForceUnlimitedFunds", "forceUnlimitedFunds" }, true) == true
  local registerPendingPersonality = configBool("armory-command", { "RegisterArmoryPendingPersonality", "registerArmoryPendingPersonality", "RegisterPendingPersonality", "registerPendingPersonality" }, false) == true
  return ',"prepareEconomyForLinkedTrader":' .. tostring(prepareEconomy) ..
    ',"saleDistance":' .. tostring(saleDistance) ..
    ',"relevancyRange":' .. tostring(relevancyRange) ..
    ',"tradeOutpostsUpdateTime":' .. tostring(updateTime) ..
    ',"forceUnlimitedStock":' .. tostring(forceUnlimitedStock) ..
    ',"forceUnlimitedFunds":' .. tostring(forceUnlimitedFunds) ..
    ',"registerPendingPersonality":' .. tostring(registerPendingPersonality)
end

function preloadNativeTraderPersonalityAsset(actorClass, info, attempts)
  attempts = attempts or {}
