    table.insert(attempts, "native trader personality preload skipped for " .. tostring(actorClass or ""))
    return ""
  end
  local okLoad, loaded = pcall(function() return LoadAsset(path) end)
  table.insert(attempts, "native trader personality preload LoadAsset(" .. path .. ")=" .. (okLoad and (isValidObject(loaded) and "ok" or "nil") or tostring(loaded)))
  return path
end

function nativeFunctionalTraderForInfo(actorClass, info, entry, attempts, requestId, resultCommand, nativeMode, timeoutMs)
  attempts = attempts or {}
  local cleanActor = actorSummonToken(actorClass)
  local cleanNativeMode = tostring(nativeMode or "")
  if cleanNativeMode == "" and type(actorCatalogIsActualTraderActor) == "function" and actorCatalogIsActualTraderActor(cleanActor, entry) then
    cleanNativeMode = "blocked-until-real-trader-lifecycle"
    table.insert(attempts, "native trader spawn default blocked after 2026-05-30 linked-actor crash/non-functional test")
  end
  preloadNativeTraderLifecycleAssets(attempts, cleanNativeMode)
  preloadNativeTraderActorClass(cleanActor, entry, attempts)
  local personalityPath = preloadNativeTraderPersonalityAsset(cleanActor, info, attempts)
  local stockOutpostKey = nativeTraderStockOutpostKeyForActor(cleanActor)
  local forceStockPersonality = stockOutpostKey ~= ""
  local allowManagerlessStockPersonality = configBool("armory-command", { "AllowManagerlessStockPersonality", "allowManagerlessStockPersonality", "AllowManagerlessStockedArmoryPersonality", "allowManagerlessStockedArmoryPersonality" }, forceStockPersonality) == true
  local allowUnsafeManagerlessSpawnActorMutation = configBool("armory-command", { "AllowUnsafeManagerlessSpawnActorMutation", "allowUnsafeManagerlessSpawnActorMutation", "AllowManagerlessSpawnActorMutation", "allowManagerlessSpawnActorMutation" }, false) == true
  local allowManualSpawnedTraderArrayMutation = configBool("armory-command", { "AllowManualSpawnedTraderArrayMutation", "allowManualSpawnedTraderArrayMutation", "AllowUnsafeSpawnedTraderArrayMutation", "allowUnsafeSpawnedTraderArrayMutation" }, false) == true
  local allowExactManagerLinkedArmoryArrayMutation = configBool("armory-command", { "AllowExactManagerLinkedArmoryArrayMutation", "allowExactManagerLinkedArmoryArrayMutation", "AllowExactStockArmoryArrayMutation", "allowExactStockArmoryArrayMutation" }, false) == true
  local allowExactStockArmoryManagerlessNoArrayCandidate = configBool("armory-command", { "AllowExactStockArmoryManagerlessNoArrayCandidate", "allowExactStockArmoryManagerlessNoArrayCandidate", "AllowExactManagerlessArmoryNoArrayCandidate", "allowExactManagerlessArmoryNoArrayCandidate" }, false) == true
  local fastManagerLookupOnly = configBool("armory-command", { "FastManagerLookupOnly", "fastManagerLookupOnly", "SkipSlowManagerFallbacks", "skipSlowManagerFallbacks" }, true) == true
  local spawnForwardDistance = configNumber("armory-command", { "SpawnForwardDistance", "spawnForwardDistance", "FunctionalTraderForwardDistance", "functionalTraderForwardDistance" },
    configNumber("bridge-safety", { "FunctionalTraderForwardDistance", "functionalTraderForwardDistance" }, 450) or 450) or 450
  local spawnLiftZ = configNumber("armory-command", { "SpawnLiftZ", "spawnLiftZ", "FunctionalTraderLiftZ", "functionalTraderLiftZ" },
    configNumber("bridge-safety", { "FunctionalTraderLiftZ", "functionalTraderLiftZ" }, 90) or 90) or 90
  local payload = '{"actorClass":' .. js(cleanActor) ..
    ',"steamId":' .. js(info and (info.steam or info.steamId) or "") ..
    ',"name":' .. js(info and info.name or "") ..
    ',"runtimeKey":' .. js(info and info.runtimeKey or "") ..
    ',"x":' .. tostring(info and info.x or 0) ..
    ',"y":' .. tostring(info and info.y or 0) ..
    ',"z":' .. tostring(info and info.z or 0) ..
    ',"yaw":' .. tostring(info and info.yaw or 0) ..
    ',"catalogPath":' .. js(tostring(entry and (entry.objectPath or entry.path or entry.packagePath) or "")) ..
    ',"personalityPath":' .. js(tostring(personalityPath or "")) ..
    ',"stockOutpostKey":' .. js(tostring(stockOutpostKey or "")) ..
    ',"forceStockPersonality":' .. tostring(forceStockPersonality) ..
    ',"allowManagerlessStockPersonality":' .. tostring(allowManagerlessStockPersonality) ..
    ',"allowUnsafeManagerlessSpawnActorMutation":' .. tostring(allowUnsafeManagerlessSpawnActorMutation) ..
    ',"allowManualSpawnedTraderArrayMutation":' .. tostring(allowManualSpawnedTraderArrayMutation) ..
    ',"allowExactManagerLinkedArmoryArrayMutation":' .. tostring(allowExactManagerLinkedArmoryArrayMutation) ..
    ',"allowExactStockArmoryManagerlessNoArrayCandidate":' .. tostring(allowExactStockArmoryManagerlessNoArrayCandidate) ..
    ',"fastManagerLookupOnly":' .. tostring(fastManagerLookupOnly) ..
    ',"catalogParentClass":' .. js(tostring(entry and entry.parentClass or "")) ..
    ',"catalogCategory":' .. js(tostring(entry and entry.category or "")) ..
    ',"spawnForwardDistance":' .. tostring(spawnForwardDistance) ..
    ',"spawnLiftZ":' .. tostring(spawnLiftZ) ..
    nativeTraderEconomyPreparePayload() ..
    ',"nativeMode":' .. js(cleanNativeMode) .. '}'
  if tostring(requestId or "") ~= "" then
    table.insert(attempts, "native cppmod spawn_functional_trader queued")
    appendActionEvent("native_functional_trader_queue", true, info, "Функциональный trader отправлен в SCUMTraderManager C++ mod.",
      '{"actorClass":' .. js(cleanActor) .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
    return nativeTraderCommandAsync(resultCommand or "spawn_actor", "spawn_functional_trader", payload, 25000, requestId)
  end
  local okNative, message, data = nativeTraderCommand("spawn_functional_trader", payload, timeoutMs or 1000, requestId)
  table.insert(attempts, "native cppmod spawn_functional_trader=" .. tostring(okNative) .. ":" .. tostring(message))
  appendActionEvent("native_functional_trader", okNative, info, message,
    '{"actorClass":' .. js(cleanActor) .. ',"nativeResponse":' .. (data or "{}") .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
  return okNative, message, data or "{}"
end

adminBypassUntil = 0
adminBypassHooksInstalled = false
adminBypassTokenSeq = 0
adminBypassToken = 0
adminBypassControllerKey = nil
adminBypassRpcKey = nil
adminBypassAllowGlobal = false

function adminBypassContextKey(obj)
  if obj == nil then return "" end
  local key = ""
  pcall(function() key = tostring(objectKey(obj) or "") end)
  if key ~= "" then return key end
  return tostring(obj)
end

function adminBypassClear()
  adminBypassUntil = 0
  adminBypassToken = 0
  adminBypassControllerKey = nil
  adminBypassRpcKey = nil
  adminBypassAllowGlobal = false
end

function adminBypassActive(context, allowGlobal)
  if adminBypassUntil <= 0 then return false end
  if os.clock() > adminBypassUntil then
    adminBypassClear()
    return false
  end
  if context == nil then return allowGlobal == true and adminBypassAllowGlobal == true end
  local key = adminBypassContextKey(context)
  if key == "" then return allowGlobal == true and adminBypassAllowGlobal == true end
  if adminBypassControllerKey ~= nil and key == adminBypassControllerKey then return true end
  if adminBypassRpcKey ~= nil and key == adminBypassRpcKey then return true end
  if adminBypassControllerKey == nil and adminBypassRpcKey == nil then
    return allowGlobal == true and adminBypassAllowGlobal == true
  end
  return false
end

function enableScopedAdminBypass(ms, info, allowGlobal)
  local seconds = math.max(0.05, math.min((tonumber(ms) or 350) / 1000, 2.0))
  adminBypassTokenSeq = (tonumber(adminBypassTokenSeq) or 0) + 1
  adminBypassToken = adminBypassTokenSeq
  adminBypassUntil = os.clock() + seconds
  adminBypassControllerKey = nil
  adminBypassRpcKey = nil
  adminBypassAllowGlobal = allowGlobal == true
  if info ~= nil then
    if info.pc ~= nil and isValidObject(info.pc) then adminBypassControllerKey = adminBypassContextKey(info.pc) end
    if info.rpc ~= nil and isValidObject(info.rpc) then adminBypassRpcKey = adminBypassContextKey(info.rpc) end
  end
  return adminBypassToken
end

function disableScopedAdminBypass(token)
  if token == nil or token == adminBypassToken then adminBypassClear() end
end

function disableScopedAdminBypassIfExpired(expectedUntil, token)
  local expected = tonumber(expectedUntil) or 0
  if expected <= 0 then return end
  if adminBypassUntil <= expected + 0.01 and os.clock() >= expected and (token == nil or token == adminBypassToken) then
    adminBypassClear()
  end
end

function ensureAdminBypassHooks()
  if adminBypassHooksInstalled then return end
  adminBypassHooksInstalled = true
  local function hookBoolReturn(path, label, allowGlobal)
    local function preCallback(context, ...)
      local okActive, active = pcall(adminBypassActive, context, allowGlobal)
      if okActive and active then return true end
      if not okActive then
        appendLog("admin bypass hook " .. tostring(label) .. " callback failed: " .. tostring(active or "unknown"))
      end
      return nil
    end
    local function postCallback(context, ...)
      return nil
    end
    local okHook, preId, postId = pcall(function()
      return RegisterHook(path, preCallback, postCallback)
    end)
    if okHook then
      appendLog("admin bypass hook " .. tostring(label) .. ": ok pre=" .. tostring(preId) .. " post=" .. tostring(postId))
    else
      local errText = tostring(preId or "")
      local reason = "failed " .. (errText:match("([^\r\n]+)") or errText)
      if invalidRuntimeText(preId) or errText:find("no UFunction", 1, true) ~= nil or errText:find("specified name was found", 1, true) ~= nil then
        reason = "skipped missing runtime alias"
      end
      appendLog("admin bypass hook " .. tostring(label) .. ": " .. reason)
    end
  end
  hookBoolReturn("/Script/SCUM.ConZPlayerController:IsUserAdmin", "ConZPlayerController.IsUserAdmin", true)
  hookBoolReturn("/Script/SCUM.MiscStatics:IsUserDeveloper", "MiscStatics.IsUserDeveloper", true)
end

adminOutputHooksInstalled = false
adminOutputHooksAvailable = false
adminCaptureActive = false
adminCaptureBuffer = {}
commandVerb = nil
HOOK_CALLBACK_DEPTH = HOOK_CALLBACK_DEPTH or {}

function guardedHookCallback(label, path, fn)
  local key = tostring(label or "hook") .. ":" .. tostring(path or "")
  local depth = tonumber(HOOK_CALLBACK_DEPTH[key] or 0) or 0
  local maxDepth = math.max(1, math.min(math.floor(configNumber("bridge-safety", { "HookCallbackMaxDepth", "hookCallbackMaxDepth" }, 1) or 1), 5))
  if depth >= maxDepth then
    appendLog("hook callback reentry skipped label=" .. tostring(label) .. " path=" .. tostring(path))
    return nil
  end
  HOOK_CALLBACK_DEPTH[key] = depth + 1
  local okRun, result = pcall(fn)
  HOOK_CALLBACK_DEPTH[key] = depth
  if not okRun then
    appendLog("hook callback failed label=" .. tostring(label) .. " path=" .. tostring(path) .. " err=" .. tostring(result))
    return nil
  end
  return result
end

function ensureAdminOutputHooks()
  if adminOutputHooksInstalled then return adminOutputHooksAvailable == true end
  adminOutputHooksInstalled = true
  adminOutputHooksAvailable = false
  local paths = {
    "/Script/SCUM.ConZPlayerController:ClientShowAdminCommandResult",
    "/Script/ConZ.ConZPlayerController:ClientShowAdminCommandResult",
    "/Script/SCUM.ConZPlayerController:ClientShowCommandResult",
    "/Script/ConZ.ConZPlayerController:ClientShowCommandResult"
  }
  for _, path in ipairs(paths) do
    local okHook, err = pcall(function()
      RegisterHook(path, function(context, ...)
        local hookArgs = {...}
        return guardedHookCallback("admin-output", path, function()
          if not adminCaptureActive then return end
          local args = hookArgs
          for _, arg in ipairs(args) do
            local text = paramText(arg)
            if text ~= "" then
              table.insert(adminCaptureBuffer, text)
              appendLog("admin capture " .. tostring(path) .. ": " .. text:sub(1, 180))
            end
          end
        end)
      end)
    end)
    if okHook then
      adminOutputHooksAvailable = true
      appendLog("admin output hook " .. tostring(path) .. "=ok")
    else
      local errText = tostring(err or "")
      local firstLine = errText:match("([^\r\n]+)") or errText
      local reason = firstLine
      if firstLine:find("no UFunction", 1, true) ~= nil or firstLine:find("specified name was found", 1, true) ~= nil then
        reason = "unavailable in this SCUM build"
      end
      appendLog("admin output hook " .. tostring(path) .. "=" .. tostring(reason):sub(1, 220))
    end
  end
  if not adminOutputHooksAvailable then
    appendLog("admin output capture disabled: no matching command-result UFunctions in this SCUM build")
  end
  return adminOutputHooksAvailable == true
end

function startAdminCapture()
  adminCaptureBuffer = {}
  if not ensureAdminOutputHooks() then
    adminCaptureActive = false
    return false
  end
  adminCaptureActive = true
  return true
end

function stopAdminCapture()
  adminCaptureActive = false
  local messages = adminCaptureBuffer
  adminCaptureBuffer = {}
  return messages
end

function waitForAdminCapture(ms)
  return
end

function numberList(text)
  local out = {}
  for raw in tostring(text or ""):gmatch("[%-]?%d+%.?%d*") do
    local n = tonumber(raw)
    if n ~= nil then table.insert(out, n) end
  end
  return out
end

function rentalDestroyInvalidVehicleRefMessage(message)
  local lower = tostring(message or ""):lower()
  return lower:find("not a valid vehicle alias or id", 1, true) ~= nil
end

function adminMessageIsFailure(message)
  local lower = tostring(message or ""):lower()
  return lower:find("not recognized", 1, true) ~= nil or
    lower:find("unrecognized", 1, true) ~= nil or
    lower:find("not authorized", 1, true) ~= nil or
    lower:find("not authorised", 1, true) ~= nil or
    lower:find("unknown command", 1, true) ~= nil or
    lower:find("cannot spawn", 1, true) ~= nil or
    lower:find("cannot execute", 1, true) ~= nil or
    lower:find("not allowed", 1, true) ~= nil or
    lower:find("command failed", 1, true) ~= nil or
    rentalDestroyInvalidVehicleRefMessage(lower)
end

function verifyAdminCommandMessages(commandText, messages)
  local verb = commandVerb(commandText):lower()
  for _, message in ipairs(messages or {}) do
    if adminMessageIsFailure(message) then return false, tostring(message) end
  end

  if verb == "setattributes" or verb == "setprisonerattributes" then
    local requested = numberList(commandText)
    if #requested < 4 then return false, "SetAttributes request has fewer than four values" end
    local sawAttributes = false
    for _, message in ipairs(messages or {}) do
      local lower = tostring(message or ""):lower()
      if lower:find("prisoner attributes are", 1, true) ~= nil or lower:find("attributes are", 1, true) ~= nil then
        local applied = numberList(message)
        if #applied >= 4 then
          sawAttributes = true
          local matched = true
          for i = 1, 4 do
            if math.abs(applied[i] - requested[i]) > 0.05 then matched = false end
          end
          if matched then
            return true, "SCUM confirmed attributes " .. tostring(applied[1]) .. " " .. tostring(applied[2]) .. " " .. tostring(applied[3]) .. " " .. tostring(applied[4])
          end
          return false, "SCUM applied different attributes: " .. tostring(message)
        end
      end
    end
    if sawAttributes then return false, "SCUM attribute response was unreadable" end
    return nil, "no SCUM attribute confirmation captured"
  end

  if messages ~= nil and #messages > 0 then return true, "SCUM returned command output" end
  return nil, "no SCUM command output captured"
end

function objectFullName(obj)
  if obj == nil then return "" end
  local ok, name = pcall(function() return obj:GetFullName() end)
  if ok and name ~= nil then return tostring(name) end
  return tostring(obj)
end

function makeAdminCommandPaths(verb, roots)
  local out = {}
  local seen = {}
  local cleanVerb = tostring(verb or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if cleanVerb == "" then return out end
  local function add(root)
    root = tostring(root or ""):gsub("/+$", "")
    if root == "" then return end
    local path = root .. "/" .. cleanVerb .. ".Default__" .. cleanVerb .. "_C"
    if not seen[path] then
      seen[path] = true
      table.insert(out, path)
    end
  end
  for _, root in ipairs(roots or {}) do add(root) end
  return out
end

