function firstValidAdminCommandObject(verb)
  local known = {
    SetPrisonerAttributes = {
      "/Game/ConZ_Files/AdminCommands/Developer/Prisoner/SetPrisonerAttributes.Default__SetPrisonerAttributes_C",
      "/Game/ConZ_Files/AdminCommands/Developer/Prisoner/SetAttributes.Default__SetAttributes_C"
    }
  }
  local candidates = known[verb] or adminCommandPathCandidates(verb)
  for _, path in ipairs(candidates) do
    local obj = nil
    pcall(function() obj = StaticFindObject(path) end)
    if obj ~= nil and isValidObject(obj) then return obj end
  end
  for _, className in ipairs({ verb .. "_C", "UAdminCommand_" .. verb, "AdminCommand_" .. verb, verb }) do
    local obj = nil
    pcall(function() obj = FindFirstOf(className) end)
    if obj ~= nil and isValidObject(obj) then
      appendAdminVerboseLog("admin command object found through runtime class " .. tostring(className) .. " for " .. tostring(verb))
      return obj
    end
  end
  appendLog("admin command object not found through safe static paths for " .. tostring(verb))
  return nil
end

function adminCommandArgumentDescriptionsJson(obj)
  local args = firstProp(obj, { "_argumentDescriptions", "ArgumentDescriptions", "argumentDescriptions" })
  if args == nil then return "[]" end
  local rows = {}
  local okNum, num = pcall(function() return args:GetArrayNum() end)
  if okNum and tonumber(num) ~= nil then
    for i = 1, math.min(tonumber(num) or 0, 12) do
      local entry = nil
      pcall(function() entry = args[i] end)
      local name = ""
      local description = ""
      local dataObject = nil
      if entry ~= nil then
        pcall(function() name = tostring(entry.Name or "") end)
        pcall(function() description = tostring(entry.Description or "") end)
        pcall(function() dataObject = entry.Data end)
      end
      table.insert(rows, '{"index":' .. tostring(i) ..
        ',"name":' .. js(name) ..
        ',"description":' .. js(description) ..
        ',"data":' .. adminCommandArgumentDataJson(dataObject) .. '}')
    end
  end
  return "[" .. table.concat(rows, ",") .. "]"
end

function adminCommandValueJson(value)
  if value == nil then return "null" end
  local valueType = type(value)
  if valueType == "boolean" then return tostring(value) end
  if valueType == "number" then return tostring(value) end
  if valueType == "string" then return js(value) end
  local okNum, num = pcall(function() return value:GetArrayNum() end)
  if okNum and tonumber(num) ~= nil then
    local rows = {}
    local count = math.min(tonumber(num) or 0, 16)
    for i = 1, count do
      local entry = nil
      pcall(function() entry = value[i] end)
      table.insert(rows, js(objectFullName(entry)))
    end
    return '{"count":' .. tostring(tonumber(num) or 0) .. ',"items":[' .. table.concat(rows, ",") .. ']}'
  end
  return js(objectFullName(value))
end

function adminCommandFieldJson(obj, label, keys)
  if obj == nil then
    return js(label) .. ':{"present":false,"key":"","value":null}'
  end
  for _, key in ipairs(keys or {}) do
    local value = safeGet(obj, key)
    if value ~= nil then
      return js(label) .. ':{"present":true,"key":' .. js(key) .. ',"value":' .. adminCommandValueJson(value) .. '}'
    end
  end
  return js(label) .. ':{"present":false,"key":"","value":null}'
end

function adminCommandFieldObject(label, obj, keys)
  local field = adminCommandFieldJson(obj, label, keys)
  local prefix = js(label) .. ":"
  if field:sub(1, #prefix) == prefix then
    return field:sub(#prefix + 1)
  end
  return '{"present":false,"key":"","value":null}'
end

function adminCommandArgumentDataJson(dataObject)
  if dataObject == nil or not isValidObject(dataObject) then
    return '{"present":false,"object":"","class":"","fields":{},"completion":null}'
  end
  local completion = nil
  local completionKey = ""
  for _, key in ipairs({ "ArgumentCompletion", "_argumentCompletion", "argumentCompletion" }) do
    completion = safeGet(dataObject, key)
    if completion ~= nil then
      completionKey = key
      break
    end
  end
  local dataFields = {
    '"dataTypeName":' .. adminCommandFieldObject("dataTypeName", dataObject, { "DataTypeName", "_dataTypeName", "dataTypeName" }),
    '"defaultValue":' .. adminCommandFieldObject("defaultValue", dataObject, { "_defaultValue", "DefaultValue", "defaultValue" }),
    '"defaultLocationValue":' .. adminCommandFieldObject("defaultLocationValue", dataObject, { "_defaultLocationValue", "DefaultLocationValue", "defaultLocationValue" }),
    '"caseSensitive":' .. adminCommandFieldObject("caseSensitive", dataObject, { "_caseSensitive", "CaseSensitive", "caseSensitive" }),
    '"argumentCompletion":' .. adminCommandFieldObject("argumentCompletion", dataObject, { "ArgumentCompletion", "_argumentCompletion", "argumentCompletion" })
  }
  local completionJson = "null"
  if completion ~= nil and isValidObject(completion) then
    local completionFields = {
      '"canCompletionValuesBeCached":' .. adminCommandFieldObject("canCompletionValuesBeCached", completion, { "_canCompletionValuesBeCached", "CanCompletionValuesBeCached", "canCompletionValuesBeCached" }),
      '"primaryAssetType":' .. adminCommandFieldObject("primaryAssetType", completion, { "_primaryAssetType", "PrimaryAssetType", "primaryAssetType" }),
      '"primaryAssetsToExclude":' .. adminCommandFieldObject("primaryAssetsToExclude", completion, { "_primaryAssetsToExclude", "PrimaryAssetsToExclude", "primaryAssetsToExclude" }),
      '"completionValues":' .. adminCommandFieldObject("completionValues", completion, { "_completionValues", "CompletionValues", "completionValues" })
    }
    completionJson = '{"present":true' ..
      ',"key":' .. js(completionKey) ..
      ',"object":' .. js(objectFullName(completion)) ..
      ',"class":' .. js(objectClassFullName(completion)) ..
      ',"fields":{' .. table.concat(completionFields, ",") .. '}}'
  end
  return '{"present":true' ..
    ',"object":' .. js(objectFullName(dataObject)) ..
    ',"class":' .. js(objectClassFullName(dataObject)) ..
    ',"fields":{' .. table.concat(dataFields, ",") .. '}' ..
    ',"completion":' .. completionJson .. '}'
end

function adminCommandFieldsJson(obj)
  local fields = {
    adminCommandFieldJson(obj, "verb", { "_verb", "Verb", "verb" }),
    adminCommandFieldJson(obj, "numberOfRequiredArguments", { "_numberOfRequiredArguments", "NumberOfRequiredArguments", "numberOfRequiredArguments" }),
    adminCommandFieldJson(obj, "numberOfRepeatingArguments", { "_numberOfRepeatingArguments", "NumberOfRepeatingArguments", "numberOfRepeatingArguments" }),
    adminCommandFieldJson(obj, "requiredExecutorLevel", { "_requiredExecutorLevel", "RequiredExecutorLevel", "requiredExecutorLevel" }),
    adminCommandFieldJson(obj, "isEnabled", { "_isEnabled", "IsEnabled", "isEnabled" }),
    adminCommandFieldJson(obj, "isEnabledInShippingBuild", { "_isEnabledInShippingBuild", "IsEnabledInShippingBuild", "isEnabledInShippingBuild" }),
    adminCommandFieldJson(obj, "shouldExecuteOnServer", { "_shouldExecuteOnServer", "ShouldExecuteOnServer", "shouldExecuteOnServer" }),
    adminCommandFieldJson(obj, "shouldExecuteOnClient", { "_shouldExecuteOnClient", "ShouldExecuteOnClient", "shouldExecuteOnClient" }),
    adminCommandFieldJson(obj, "shouldDisableSingleplayerAchievementsIfExecuted", { "_shouldDisableSingleplayerAchievementsIfExecuted", "ShouldDisableSingleplayerAchievementsIfExecuted", "shouldDisableSingleplayerAchievementsIfExecuted" }),
    adminCommandFieldJson(obj, "hasCooldown", { "_hasCooldown", "HasCooldown", "hasCooldown" }),
    adminCommandFieldJson(obj, "cooldown", { "_cooldown", "Cooldown", "cooldown" }),
    adminCommandFieldJson(obj, "description", { "_description", "Description", "description" }),
    adminCommandFieldJson(obj, "primaryAssetType", { "_primaryAssetType", "PrimaryAssetType", "primaryAssetType" }),
    adminCommandFieldJson(obj, "primaryAssetsToExclude", { "_primaryAssetsToExclude", "PrimaryAssetsToExclude", "primaryAssetsToExclude" }),
    adminCommandFieldJson(obj, "countArgumentMinValue", { "_countArgumentMinValue", "CountArgumentMinValue", "countArgumentMinValue" }),
    adminCommandFieldJson(obj, "countArgumentMaxValue", { "_countArgumentMaxValue", "CountArgumentMaxValue", "countArgumentMaxValue" }),
    adminCommandFieldJson(obj, "spawnOffset", { "_spawnOffset", "SpawnOffset", "spawnOffset" }),
    adminCommandFieldJson(obj, "isSpawnedActorCapableOfFalling", { "_isSpawnedActorCapableOfFalling", "IsSpawnedActorCapableOfFalling", "isSpawnedActorCapableOfFalling" })
  }
  return "{" .. table.concat(fields, ",") .. "}"
end

function adminCommandProbe(spec)
  local verbs = {}
  local seen = {}
  local text = tostring(spec or "")
  local truncated = false
  for token in text:gmatch("[%w_]+") do
    if token ~= "" and not seen[token] then
      seen[token] = true
      table.insert(verbs, token)
    end
  end
  if #verbs == 0 then
    verbs = {
      "SetGender", "SetHairLength", "SetFacialHairLength",
      "AddBodyEffect", "RemoveBodyEffect", "ListBodyEffects",
      "AddPrisonerBodyEffect", "RemovePrisonerBodyEffect", "DisablePrisonerBodyEffects",
      "SpawnZombie", "SpawnRandomZombie", "SpawnRandomZombie2", "SpawnRazor", "SpawnBrenner", "GetMeshInfo",
      "GetSteamID", "ShowOtherPlayerInfo", "ShowZombiesLocation"
    }
  end
  local maxVerbs = math.max(1, math.min(math.floor(configNumber("bridge-safety", { "AdminCommandProbeMaxVerbs", "adminCommandProbeMaxVerbs" }, 24) or 24), 80))
  if #verbs > maxVerbs then
    while #verbs > maxVerbs do table.remove(verbs) end
    truncated = true
  end
  local allowRuntimeProbe = configBool("bridge-safety", { "AllowAdminCommandRuntimeProbe", "allowAdminCommandRuntimeProbe" }, false) == true

  local rows = {}
  for _, verb in ipairs(verbs) do
    local found = nil
    local foundPath = ""
    local attempts = {}
    for _, path in ipairs(adminCommandPathCandidates(verb)) do
      local obj = nil
      local okFind, err = pcall(function() obj = StaticFindObject(path) end)
      table.insert(attempts, tostring(path) .. "=" .. (okFind and (isValidObject(obj) and "ok" or "nil") or tostring(err)))
      if okFind and obj ~= nil and isValidObject(obj) then
        found = obj
        foundPath = path
        break
      end
    end
    if found == nil and allowRuntimeProbe then
      for _, className in ipairs({ verb .. "_C", "UAdminCommand_" .. verb, "AdminCommand_" .. verb, verb }) do
        local obj = nil
        local okFind, err = pcall(function() obj = FindFirstOf(className) end)
        table.insert(attempts, "FindFirstOf(" .. tostring(className) .. ")=" .. (okFind and (isValidObject(obj) and "ok" or "nil") or tostring(err)))
        if okFind and obj ~= nil and isValidObject(obj) then
          found = obj
          foundPath = "runtime:" .. tostring(className)
          break
        end
      end
    elseif found == nil then
      table.insert(attempts, "runtime FindFirstOf skipped by bridge-safety.AllowAdminCommandRuntimeProbe=false")
    end

    local attemptJson = {}
    for _, attempt in ipairs(attempts) do table.insert(attemptJson, js(attempt)) end
    table.insert(rows,
      '{"verb":' .. js(verb) ..
      ',"found":' .. tostring(found ~= nil) ..
      ',"path":' .. js(foundPath) ..
      ',"object":' .. js(objectFullName(found)) ..
      ',"fields":' .. adminCommandFieldsJson(found) ..
      ',"arguments":' .. adminCommandArgumentDescriptionsJson(found) ..
      ',"attempts":[' .. table.concat(attemptJson, ",") .. ']}')
  end
  return true, "Проверка admin-команд выполнена.", '{"runtimeProbe":' .. tostring(allowRuntimeProbe) .. ',"truncated":' .. tostring(truncated) .. ',"commands":[' .. table.concat(rows, ",") .. ']}'
end

function commandVerb(commandText)
  local text = tostring(commandText or ""):gsub("^%s*#", ""):gsub("^%s+", "")
  return text:match("^([%w_]+)") or ""
end

