    SetBodyType = true,
    SetHairLength = true,
    SetFacialHairLength = true,
    AddPrisonerBodyEffect = true,
    RemovePrisonerBodyEffect = true,
    DisablePrisonerBodyEffects = true,
    ListPrisonerBodyEffects = true,
    AddBodyEffect = true,
    RemoveBodyEffect = true,
    DisableBodyEffects = true,
    ListBodyEffects = true,
    AddBleedingInjury = true,
    AddBurnInjury = true,
    AddRadiationPresence = true,
    SetPrisonerImmortality = true,
    SetPrisonerInfiniteStamina = true,
    SetPrisonerInfiniteOxygen = true,
    SetImmortality = true,
    SetInfiniteStamina = true,
    SetInfiniteOxygen = true,
    SetInfiniteAmmo = true,
    SetSuperJump = true,
    SetStomachVolume = true,
    SetBladderVolume = true,
    SetMetabolismSimulationSpeed = true,
    SetStamina = true,
    SetExhaustion = true,
    SetAIInvisibility = true,
    KnockoutPrisoner = true,
    Knockout = true,
    LeaveCorpse = true,
    Sleep = true,
    ShouldShowOtherPlayerInfo = true,
    ShouldShowOtherPlayerLocations = true,
    ShowOtherPlayerInfo = true,
    ShowOtherPlayerLocations = true,
    ShowZombiesLocation = true,
    ShowAnimalsLocation = true,
    ShowAnimalLocation = true,
    ShowArmedNPCsLocation = true,
    ShowVehicleInfo = true,
    ShowVehicleLocations = true,
    ShowNameplates = true,
    SpawnZombie = true,
    SpawnRandomZombie = true,
    SpawnRandomZombie2 = true,
    SpawnRazor = true,
    SpawnBrenner = true,
    SpawnArmedNPC = true,
    SpawnAnimal = true,
    SpawnRandomAnimal = true,
    SpawnItem2 = true,
    DestroyZombiesWithinRadius = true,
    ScheduleWorldEvent = true,
    ScheduleCargoDrop = true,
    GetMeshInfo = true,
    GetUserID = true,
    GetSteamID = true,
    PlayerInfo = true,
    Location = true,
    ListZombies = true,
    ListVehicles = true,
    ListAnimals = true,
    ListSpawndAnimals = true
  }
  if not patchable[verb] then return nil end
  local obj = firstValidAdminCommandObject(verb)
  if obj == nil then
    appendLog("admin command patch skipped, object not found for " .. tostring(verb))
    return nil
  end

  local restore = {}
  local function setProp(prop, value)
    local okRead, old = pcall(function() return obj[prop] end)
    if not okRead then
      appendLog("admin command patch " .. tostring(verb) .. "." .. tostring(prop) .. " skipped: old value unreadable")
      return
    end
    local okWrite, err = pcall(function() obj[prop] = value end)
    if okWrite then
      appendAdminVerboseLog("admin command patch " .. tostring(verb) .. "." .. tostring(prop) .. "=" .. tostring(value) .. " write=true")
    else
      appendLog("admin command patch " .. tostring(verb) .. "." .. tostring(prop) .. "=" .. tostring(value) .. " write=false err=" .. tostring(err))
    end
    if okWrite then table.insert(restore, { prop = prop, value = old }) end
  end

  setProp("_requiredExecutorLevel", 0)
  setProp("_isEnabled", true)
  setProp("_isEnabledInShippingBuild", true)
  if #restore == 0 then
    appendLog("admin command patch skipped restore unavailable for " .. tostring(verb) .. " object=" .. objectFullName(obj))
    return nil
  end

  ADMIN_COMMAND_PATCH_ACTIVE = ADMIN_COMMAND_PATCH_ACTIVE or {}
  local objKey = tostring(objectKey(obj) or "")
  if objKey == "" then objKey = objectFullName(obj) end
  local patchKey = tostring(verb) .. ":" .. tostring(objKey)
  local active = ADMIN_COMMAND_PATCH_ACTIVE[patchKey]
  if active ~= nil then
    active.refCount = math.max(1, tonumber(active.refCount) or 1) + 1
    appendAdminVerboseLog("admin command patch refcount increased for " .. tostring(verb) .. " count=" .. tostring(active.refCount))
  else
    active = { verb = verb, obj = obj, restore = restore, refCount = 1 }
    ADMIN_COMMAND_PATCH_ACTIVE[patchKey] = active
    appendAdminVerboseLog("admin command patch scoped active for " .. tostring(verb) .. " object=" .. objectFullName(obj) .. " props=" .. tostring(#restore))
  end

  local restored = false
  return function()
    if restored then return end
    restored = true
    local current = ADMIN_COMMAND_PATCH_ACTIVE and ADMIN_COMMAND_PATCH_ACTIVE[patchKey] or nil
    if current == nil then return end
    current.refCount = math.max(0, (tonumber(current.refCount) or 1) - 1)
    if current.refCount > 0 then
      appendAdminVerboseLog("admin command patch restore deferred for " .. tostring(verb) .. " remaining=" .. tostring(current.refCount))
      return
    end
    local currentObj = current.obj or obj
    for i = #(current.restore or {}), 1, -1 do
      local item = current.restore[i]
      local okRestore, errRestore = pcall(function() currentObj[item.prop] = item.value end)
      if okRestore then
        appendAdminVerboseLog("admin command patch restored " .. tostring(verb) .. "." .. tostring(item.prop))
      else
        appendLog("admin command patch restore failed " .. tostring(verb) .. "." .. tostring(item.prop) .. " err=" .. tostring(errRestore))
      end
    end
    ADMIN_COMMAND_PATCH_ACTIVE[patchKey] = nil
  end
end

function adminCommandHasLocationTarget(commandText)
  local text = tostring(commandText or "")
  local after = text:match("[Ll]ocation%s+(.+)$")
  if after == nil then return false end
  after = tostring(after or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if after == "" then return false end
  local first = after:match('^"([^"]+)"') or after:match("^(%S+)")
  if looksLikeSteamId(first) then return true end
  local numbers = 0
  for _ in after:gmatch("[-+]?%d+%.?%d*") do
    numbers = numbers + 1
    if numbers >= 3 then return true end
  end
  return false
end

function adminCommandUsesSharedAdminChannel(verb, commandText)
  if verb == "DestroyEntity" then
    return configBool("bridge-safety", { "DestroyEntityUsesSharedAdminChannel", "destroyEntityUsesSharedAdminChannel" }, true)
  end
  if verb == "DestroyVehicle" then
    return configBool("bridge-safety", { "DestroyVehicleUsesSharedAdminChannel", "destroyVehicleUsesSharedAdminChannel" }, true)
  end
  if verb == "SpawnItem" and adminCommandHasLocationTarget(commandText) then
    return configBool("bridge-safety", { "SpawnItemLocationUsesSharedAdminChannel", "spawnItemLocationUsesSharedAdminChannel" }, true)
  end
  return false
end

function adminExec(commandText, preferredInfo)
  commandText = tostring(commandText or "")
  local normalizedCommandText = commandText:gsub("^%s*#", "")
  local hashedCommandText = "#" .. normalizedCommandText
  local verb = commandVerb(normalizedCommandText)
  if unsupportedClientOverlayAdminCommand(verb) and not configBool("bridge-safety", { "AllowUnsupportedClientOverlayAdminCommands", "allowUnsupportedClientOverlayAdminCommands" }, false) then
    return false, "admin overlay command blocked by bridge-safety.AllowUnsupportedClientOverlayAdminCommands=false"
  end
  local serverScopedAdminVerbs = {
    SpawnItem = true,
    SpawnVehicle = true,
    DestroyVehicle = true,
    ChangeCurrencyBalance = true,
    SetCurrencyBalance = true,
    ChangeFamePoints = true,
    SetFamePoints = true,
    SetAttributes = true,
    SetPrisonerAttributes = true,
    SetSkillLevel = true,
    DestroyEntity = true,
    SendChat = true,
    SendNotification = true,
    Kick = true,
    Ban = true,
    ScheduleWorldEvent = true,
    ScheduleCargoDrop = true,
    Announce = true,
    Broadcast = true,
    SpawnZombie = true,
    SpawnRandomZombie = true,
    SpawnRandomZombie2 = true,
    SpawnRazor = true,
    SpawnBrenner = true,
    SpawnArmedNPC = true,
    SpawnAnimal = true,
    SpawnRandomAnimal = true,
    SpawnItem2 = true,
    DestroyZombiesWithinRadius = true,
    GetMeshInfo = true,
    GetSteamID = true,
    PlayerInfo = true,
    Location = true,
    ListZombies = true,
    ListVehicles = true,
    ListAnimals = true,
    ListSpawndAnimals = true
  }
  local playerBoundAdminVerbs = {
    SpawnItem = true,
    SpawnVehicle = true,
    DestroyVehicle = true,
    ChangeCurrencyBalance = true,
    SetCurrencyBalance = true,
    ChangeFamePoints = true,
    SetFamePoints = true,
    SetAttributes = true,
    SetPrisonerAttributes = true,
    SetSkillLevel = true,
    GrantElevatedStatus = true,
    RevokeElevatedStatus = true,
    SetDeluxeVersion = true,
    SendChat = true,
    SendNotification = true,
    DestroyEntity = true,
    Teleport = true,
    TeleportTo = true,
    TeleportToPlayer = true,
    TeleportToMe = true,
    SetGender = true,
    SetBodyType = true,
    SetHairLength = true,
    SetFacialHairLength = true,
    AddPrisonerBodyEffect = true,
    RemovePrisonerBodyEffect = true,
    DisablePrisonerBodyEffects = true,
    ListPrisonerBodyEffects = true,
    AddBodyEffect = true,
    RemoveBodyEffect = true,
    DisableBodyEffects = true,
    ListBodyEffects = true,
    AddBleedingInjury = true,
    AddBurnInjury = true,
    AddRadiationPresence = true,
    SetPrisonerImmortality = true,
    SetPrisonerInfiniteStamina = true,
    SetPrisonerInfiniteOxygen = true,
    SetImmortality = true,
    SetInfiniteStamina = true,
    SetInfiniteOxygen = true,
    SetInfiniteAmmo = true,
    SetSuperJump = true,
    SetStomachVolume = true,
    SetBladderVolume = true,
    SetMetabolismSimulationSpeed = true,
    SetStamina = true,
    SetExhaustion = true,
    SetAIInvisibility = true,
    KnockoutPrisoner = true,
    Knockout = true,
    LeaveCorpse = true,
    Sleep = true,
    ShouldShowOtherPlayerInfo = true,
    ShouldShowOtherPlayerLocations = true,
    ShowOtherPlayerInfo = true,
    ShowOtherPlayerLocations = true,
    ShowZombiesLocation = true,
    ShowAnimalsLocation = true,
    ShowAnimalLocation = true,
    ShowArmedNPCsLocation = true,
    ShowVehicleInfo = true,
    ShowVehicleLocations = true,
    ShowNameplates = true,
    SpawnZombie = true,
    SpawnRandomZombie = true,
    SpawnRandomZombie2 = true,
    SpawnRazor = true,
    SpawnBrenner = true,
    SpawnArmedNPC = true,
    SpawnAnimal = true,
    SpawnRandomAnimal = true,
    SpawnItem2 = true,
    DestroyZombiesWithinRadius = true,
    GetMeshInfo = true,
    GetUserID = true,
    GetSteamID = true,
    PlayerInfo = true,
    Location = true,
    ListZombies = true,
    ListVehicles = true,
    ListAnimals = true,
    ListSpawndAnimals = true
  }
  -- Most hosted SCUM builds do not echo admin confirmations through hooks we
  -- can block on safely. World-event commands keep the normal route list, but
  -- failed dispatches often echo immediately as red chat text and can be
  -- classified without changing the route that actually sends the command.
  local classifyImmediateFailure = verb == "DestroyVehicle" or verb == "ScheduleWorldEvent" or verb == "ScheduleCargoDrop"
  local requireProof = false
  local info = preferredInfo
  local needsLivePlayer = playerBoundAdminVerbs[verb] == true
  local rpcOnlyPlayerAdminVerbs = {
    ChangeCurrencyBalance = true,
    SetCurrencyBalance = true
  }
  local requiresTrustedRpcAdminRoute = verb == "Announce" or verb == "Broadcast" or rpcOnlyPlayerAdminVerbs[verb] == true
  local usesSharedAdminChannel = adminCommandUsesSharedAdminChannel(verb, normalizedCommandText)
  if usesSharedAdminChannel then needsLivePlayer = false end
  local function hasLiveAdminChannel(candidate)
    return candidate ~= nil and (
      (candidate.pc ~= nil and isValidObject(candidate.pc)) or
      (candidate.rpc ~= nil and isValidObject(candidate.rpc))
    )
  end
  if needsLivePlayer and configBool("bridge-safety", { "RefreshAdminExecLiveTarget", "refreshAdminExecLiveTarget" }, true) then
    local freshInfo = nil
    local freshReason = nil
    if type(targetMessageFreshInfo) == "function" then
      freshInfo, freshReason = targetMessageFreshInfo(info, "admin-exec:" .. tostring(verb or ""))
    elseif info ~= nil then
      freshInfo = refreshRuntimePlayerInfo(info)
      if freshInfo == nil then freshReason = "refresh-runtime-failed" end
    else
      freshReason = "missing-target"
    end
    if hasLiveAdminChannel(freshInfo) then
      info = freshInfo
    else
      appendLog("adminExec skipped stale live target verb=" .. tostring(verb or "") ..
        " reason=" .. tostring(freshReason or "not-live") ..
        " target=" .. tostring((info and (info.steam or info.name or info.runtimeKey)) or ""))
      return false, "target player is not live"
    end
  end
  if not needsLivePlayer and not hasLiveAdminChannel(info) then
    for _, candidate in ipairs(cachedPlayerInfos(8) or {}) do
      if hasLiveAdminChannel(candidate) then
        info = candidate
        break
      end
    end
    if not hasLiveAdminChannel(info) then
      for _, candidate in ipairs(listPlayerInfos() or {}) do
        if hasLiveAdminChannel(candidate) then
          info = candidate
          break
        end
      end
    end
  end
  if needsLivePlayer and not hasLiveAdminChannel(info) then
    local liveInfo = nil
    if info ~= nil then
      liveInfo = findPlayer(info.steam, info.name, info.runtimeKey)
    end
    if hasLiveAdminChannel(liveInfo) then
      if type(mergeRuntimeIntoIdentity) == "function" and info ~= nil then
        info = mergeRuntimeIntoIdentity(info, liveInfo)
      else
        info = liveInfo
      end
    elseif configBool("bridge-safety", { "AllowAdminExecRuntimeScan", "allowAdminExecRuntimeScan" }, false) then
      local runtimeInfos = listPlayerInfos()
      if runtimeInfos ~= nil and #runtimeInfos == 1 and hasLiveAdminChannel(runtimeInfos[1]) then
        if type(mergeRuntimeIntoIdentity) == "function" and info ~= nil then
          info = mergeRuntimeIntoIdentity(info, runtimeInfos[1])
        else
          info = runtimeInfos[1]
        end
      end
    end
  end
  if needsLivePlayer and not hasLiveAdminChannel(info) and configBool("bridge-safety", { "AllowAdminExecAnonymousRuntimeScan", "allowAdminExecAnonymousRuntimeScan" }, false) then info = findPlayer(nil, nil) end
  if needsLivePlayer and not hasLiveAdminChannel(info) and configBool("bridge-safety", { "AllowAdminExecRuntimeScan", "allowAdminExecRuntimeScan" }, false) then
    local controllers = listPlayerInfos()
    for _, candidate in ipairs(controllers) do
      if hasLiveAdminChannel(candidate) then
        info = candidate
        break
      end
    end
  end
  if info == nil then info = preferredInfo or {} end
  if needsLivePlayer and not hasLiveAdminChannel(info) then return false, "no live player rpc/controller" end
  ensureAdminBypassHooks()
  local bypassWindowMs = math.max(50, math.min(math.floor(configNumber("bridge-safety", { "AdminBypassWindowMs", "adminBypassWindowMs" }, 350) or 350), 2000))
  local methods = {}
  local immediateFailureDetail = nil
  local function tryMethod(label, fn)
    local captureMessages = requireProof or classifyImmediateFailure
    local captureStarted = false
    if captureMessages then captureStarted = startAdminCapture() == true end
    local startedAtMs = math.floor(os.clock() * 1000)
    local restoreAdminCommand = patchAdminCommandFor(normalizedCommandText)
    local bypassToken = enableScopedAdminBypass(bypassWindowMs, info, true)
    local okCall, result = pcall(fn)
    disableScopedAdminBypass(bypassToken)
    if restoreAdminCommand ~= nil then
      local okRestore, errRestore = pcall(restoreAdminCommand)
      if not okRestore then appendLog("admin command patch immediate restore failed for " .. tostring(verb) .. ": " .. tostring(errRestore)) end
    end
    local durationMs = math.max(0, math.floor(os.clock() * 1000) - startedAtMs)
    local messages = {}
    if captureMessages and captureStarted then
      waitForAdminCapture(150)
      messages = stopAdminCapture()
    end
    if requireProof then
      local verified, detail = verifyAdminCommandMessages(normalizedCommandText, messages)
      table.insert(methods, label .. "=" .. (okCall and "ok" or tostring(result)) .. ";durationMs=" .. tostring(durationMs) .. ";captured=" .. tostring(#messages) .. ";verified=" .. tostring(verified) .. ";detail=" .. tostring(detail))
      appendAdminVerboseLog("admin route " .. tostring(label) .. " ok=" .. tostring(okCall) .. " durationMs=" .. tostring(durationMs) .. " verified=" .. tostring(verified))
      if okCall and verified == true then return true, detail end
      return false, detail or result
    end
    if classifyImmediateFailure then
      local verified, detail = verifyAdminCommandMessages(normalizedCommandText, messages)
      if verified == false then
        table.insert(methods, label .. "=" .. (okCall and "ok" or tostring(result)) .. ";durationMs=" .. tostring(durationMs) .. ";captured=" .. tostring(#messages) .. ";failure=" .. tostring(detail))
        appendAdminVerboseLog("admin route " .. tostring(label) .. " failed by immediate output: " .. tostring(detail))
        immediateFailureDetail = detail or result
        return false, detail or result
      end
    end
    table.insert(methods, label .. "=" .. (okCall and "ok" or tostring(result)) .. ";durationMs=" .. tostring(durationMs))
    appendAdminVerboseLog("admin route " .. tostring(label) .. " ok=" .. tostring(okCall) .. " durationMs=" .. tostring(durationMs))
    if okCall then
      local miscIsLastResort = label:find("misc.Test_ProcessAdminCommand", 1, true) ~= nil
      local needsRealPlayerRoute = needsLivePlayer or verb == "SpawnVehicle" or
        verb == "ChangeCurrencyBalance" or verb == "SetCurrencyBalance" or
        verb == "ChangeFamePoints" or verb == "SetFamePoints" or
        verb == "SetAttributes" or verb == "SetPrisonerAttributes" or
        verb == "SetDeluxeVersion" or
        verb == "SetGender" or verb == "SetBodyType" or
        verb == "SetSkillLevel" or
        verb == "Kick" or verb == "Ban" or
        verb == "Teleport" or verb == "TeleportTo" or verb == "TeleportToPlayer" or verb == "TeleportToMe"
      if miscIsLastResort and needsRealPlayerRoute then
        appendLog("admin route " .. tostring(label) .. " accepted but not trusted for " .. tostring(verb) .. "; continuing")
        return false, label .. " accepted but not trusted for " .. tostring(verb)
      end
      return true, label
    end
    return false, result
  end

  local function runRoutes(routes)
    local last = nil
    for _, route in ipairs(routes) do
      local okCall, message = tryMethod(route.label, route.fn)
      last = message
      if okCall then return true, message end
      if immediateFailureDetail ~= nil then return false, immediateFailureDetail end
    end
    return false, last
  end

  local rpc = nil
  if info ~= nil and info.rpc ~= nil and isValidObject(info.rpc) then rpc = info.rpc end
  if rpc == nil then rpc = playerRpcChannel(info.pc) end
  if requiresTrustedRpcAdminRoute and rpc == nil then
    return false, "no live admin rpc channel for " .. tostring(verb)
  end
  local hasPlayerController = info ~= nil and info.pc ~= nil and isValidObject(info.pc)
  local misc = nil
  pcall(function() misc = StaticFindObject("/Script/SCUM.Default__MiscStatics") end)

  local routes = {}
  local function addRoute(label, fn)
    table.insert(routes, { label = label, fn = fn })
  end

  if requireProof then
    if rpc ~= nil then addRoute("rpc.Chat_Server_ProcessAdminCommand#bare-fstring", function() rpc:Chat_Server_ProcessAdminCommand(ueString(normalizedCommandText)) end) end
    if rpc ~= nil then addRoute("rpc.Chat_Server_ProcessAdminCommand#bare", function() rpc:Chat_Server_ProcessAdminCommand(normalizedCommandText) end) end
    if misc ~= nil then
      local root = worldRoot() or info.pc
      addRoute("misc.Test_ProcessAdminCommand#hash-fstring", function() misc:Test_ProcessAdminCommand(root, ueString(hashedCommandText)) end)
    end
  else
    local kismet = kismetSystemLibrary()
    local rootForMisc = worldRoot() or gameModeRoot() or info.pc
    local rootForKismet = gameModeRoot() or worldRoot() or info.pc
    local gameModeForConsole = gameModeRoot() or rootForKismet
    local function callRpcAdminBare()
      if rpc == nil then error("rpc channel missing") end
      local okHash = false
      local errHash = nil
      okHash, errHash = pcall(function() rpc:Chat_Server_ProcessAdminCommand(ueString(normalizedCommandText)) end)
      if okHash then return true end
      appendLog("rpc admin bare fstring failed: " .. tostring(errHash))
      rpc:Chat_Server_ProcessAdminCommand(normalizedCommandText)
      return true
    end

    local function callRpcAdminHash()
      if rpc == nil then error("rpc channel missing") end
      local okHash = false
      local errHash = nil
      okHash, errHash = pcall(function() rpc:Chat_Server_ProcessAdminCommand(ueString(hashedCommandText)) end)
      if okHash then return true end
      appendLog("rpc admin hash fstring failed: " .. tostring(errHash))
      rpc:Chat_Server_ProcessAdminCommand(hashedCommandText)
      return true
    end

    local function callPcServerSayHash()
      if not hasPlayerController then error("player controller missing") end
      local okHash = false
      local errHash = nil
      okHash, errHash = pcall(function() info.pc:ServerSay(ueString(hashedCommandText)) end)
      if okHash then return true end
      appendLog("pc ServerSay hash fstring failed: " .. tostring(errHash))
      info.pc:ServerSay(hashedCommandText)
      return true
    end

    local function callKismetConsoleHash()
      if kismet == nil then error("KismetSystemLibrary missing") end
      if rootForKismet == nil then error("Kismet world context missing") end
      local pcArg = hasPlayerController and info.pc or nil
      local okHash = false
      local errHash = nil
      okHash, errHash = pcall(function() kismet:ExecuteConsoleCommand(rootForKismet, ueString(hashedCommandText), pcArg) end)
      if okHash then return true end
      appendLog("Kismet ExecuteConsoleCommand hash fstring failed: " .. tostring(errHash))
      kismet:ExecuteConsoleCommand(rootForKismet, hashedCommandText, pcArg)
      return true
    end

    local function callKismetConsoleNoHash()
      if kismet == nil then error("KismetSystemLibrary missing") end
      if rootForKismet == nil then error("Kismet world context missing") end
      local pcArg = hasPlayerController and info.pc or nil
      local okNoHash = false
      local errNoHash = nil
      okNoHash, errNoHash = pcall(function() kismet:ExecuteConsoleCommand(rootForKismet, ueString(normalizedCommandText), pcArg) end)
      if okNoHash then return true end
      appendLog("Kismet ExecuteConsoleCommand nohash fstring failed: " .. tostring(errNoHash))
      kismet:ExecuteConsoleCommand(rootForKismet, normalizedCommandText, pcArg)
      return true
    end

    local function callProcessConsoleExecHash()
      if gameModeForConsole == nil then error("game mode missing") end
      local pcArg = hasPlayerController and info.pc or nil
      local okHash = false
      local errHash = nil
      okHash, errHash = pcall(function() gameModeForConsole:ProcessConsoleExec(ueString(hashedCommandText), nil, pcArg) end)
      if okHash then return true end
      appendLog("ProcessConsoleExec hash fstring failed: " .. tostring(errHash))
      gameModeForConsole:ProcessConsoleExec(hashedCommandText, nil, pcArg)
      return true
    end

    local function callPcConsoleCommandHash()
      if not hasPlayerController then error("player controller missing") end
      local okHash = false
      local errHash = nil
      okHash, errHash = pcall(function() info.pc:ConsoleCommand(ueString(hashedCommandText), true) end)
      if okHash then return true end
      appendLog("PC ConsoleCommand hash fstring failed: " .. tostring(errHash))
      info.pc:ConsoleCommand(hashedCommandText, true)
      return true
    end

    local function callMiscAdminHash()
      if misc == nil then error("MiscStatics missing") end
      if rootForMisc == nil then error("MiscStatics world context missing") end
      local okHash = false
      local errHash = nil
      okHash, errHash = pcall(function() misc:Test_ProcessAdminCommand(rootForMisc, ueString(hashedCommandText)) end)
      if okHash then return true end
      appendLog("misc admin hash fstring failed: " .. tostring(errHash))
      misc:Test_ProcessAdminCommand(rootForMisc, hashedCommandText)
      return true
    end

    if needsLivePlayer and rpcOnlyPlayerAdminVerbs[verb] == true then
      if rpc ~= nil then addRoute("rpc.Chat_Server_ProcessAdminCommand#bare", callRpcAdminBare) end
    elseif needsLivePlayer then
      if rpc ~= nil then addRoute("rpc.Chat_Server_ProcessAdminCommand#bare", callRpcAdminBare) end
      if rpc ~= nil then addRoute("rpc.Chat_Server_ProcessAdminCommand#hash", callRpcAdminHash) end
      if hasPlayerController then addRoute("pc.ServerSay#hash", callPcServerSayHash) end
      if kismet ~= nil then addRoute("kismet.ExecuteConsoleCommand#hash", callKismetConsoleHash) end
      if kismet ~= nil then addRoute("kismet.ExecuteConsoleCommand#nohash", callKismetConsoleNoHash) end
      if gameModeForConsole ~= nil then addRoute("gameMode.ProcessConsoleExec#hash", callProcessConsoleExecHash) end
      if hasPlayerController then addRoute("pc.ConsoleCommand#hash", callPcConsoleCommandHash) end
      if misc ~= nil then addRoute("misc.Test_ProcessAdminCommand#hash", callMiscAdminHash) end
    else
      if rpc ~= nil then addRoute("rpc.Chat_Server_ProcessAdminCommand#bare", callRpcAdminBare) end
      if rpc ~= nil then addRoute("rpc.Chat_Server_ProcessAdminCommand#hash", callRpcAdminHash) end
      if not requiresTrustedRpcAdminRoute then
        if kismet ~= nil then addRoute("kismet.ExecuteConsoleCommand#nohash", callKismetConsoleNoHash) end
        if kismet ~= nil then addRoute("kismet.ExecuteConsoleCommand#hash", callKismetConsoleHash) end
        if misc ~= nil then addRoute("misc.Test_ProcessAdminCommand#hash", callMiscAdminHash) end
      end
    end
  end

  local okRoute, routeMessage = runRoutes(routes)
  if okRoute then
    appendAdminVerboseLog("admin exec dispatched for " .. tostring(normalizedCommandText) .. "; scoped admin bypass closed immediately after dispatch")
    return true, routeMessage
  end
  disableScopedAdminBypass()
  appendLog("admin exec failed for " .. tostring(commandText) .. " methods: " .. table.concat(methods, " | "))
  return false, routeMessage or "no admin execution route succeeded"
end

vehicleRuntimeKeySet = nil
nearestNewVehicleRef = nil
findVehicleByRuntimeRef = nil

function extractVehicleEntityIdFromText(text)
  local value = tostring(text or "")
  local id = value:match("[Ii][Dd]%s+(%d+)")
  if id == nil then id = value:match("[Vv]ehicle[Ii]d[%s:=]+(%d+)") end
  if id == nil then id = value:match("[Ee]ntity[Ii]d[%s:=]+(%d+)") end
  if id ~= nil and tostring(id) ~= "" and tostring(id) ~= "0" then return tostring(id) end
  return ""
end

function spawnVehicleForInfo(vehicle, info, options)
  options = options or {}
  local cleanVehicle = canonicalVehicleId(vehicle)
  if cleanVehicle == "" then
    appendActionEvent("spawn_vehicle", false, info, "vehicle is missing", '{"vehicleId":""}')
    return false, "vehicle is missing"
  end
  info = info or {}
  local resolvedVehicleInfo = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
  local requireForwardLocation = options.requireForwardLocation == true or options.requirePlayerForwardLocation == true
  if requireForwardLocation or configBool("vehicle-rental", { "RefreshPlayerBeforeVehicleSpawn", "refreshPlayerBeforeVehicleSpawn" }, false) then
    local refreshedVehicleInfo = refreshRuntimePlayerInfo(resolvedVehicleInfo)
    if refreshedVehicleInfo ~= nil then resolvedVehicleInfo = refreshedVehicleInfo end
  end
  local spawnProfile = vehicleSpawnProfile(cleanVehicle)
  if requireForwardLocation then
    local liveVehicleInfo, ready, readyDetail, readyReason = deliveryReadyInfo(resolvedVehicleInfo, { requireInventory = false })
    if not ready then
      appendActionEvent("vehicle_spawn_location_blocked", false, resolvedVehicleInfo, tostring(readyDetail or ""),
        '{"reason":' .. js(readyReason or "") ..
        ',"vehicleId":' .. js(cleanVehicle) ..
        ',"source":' .. js(options.source or "") .. '}')
      return false, "координаты игрока не готовы для безопасного спавна транспорта перед игроком"
    end
    resolvedVehicleInfo = liveVehicleInfo
  end
  if spawnProfile == "aircraft" and not playerHasUsableLocation(resolvedVehicleInfo) then
    local logVehicleInfo = resolvePlayerInfoFromServerLogTarget(info.steam, info.name)
    if logVehicleInfo ~= nil and playerHasUsableLocation(logVehicleInfo) then
      if resolvedVehicleInfo == nil then resolvedVehicleInfo = {} end
      for _, key in ipairs({ "steam", "name", "userProfileId", "serverUserProfileId", "x", "y", "z" }) do
        local value = logVehicleInfo[key]
        if value ~= nil and tostring(value or "") ~= "" then resolvedVehicleInfo[key] = value end
      end
      resolvedVehicleInfo.source = tostring(resolvedVehicleInfo.source or "") .. "+server-log-position"
    end
  end
  if spawnProfile == "aircraft" and not playerHasUsableLocation(resolvedVehicleInfo) then
    local liveVehicleInfo, ready, readyDetail, readyReason = deliveryReadyInfo(resolvedVehicleInfo, { requireInventory = false })
    if not ready then
      appendActionEvent("delivery_readiness", false, resolvedVehicleInfo, tostring(readyDetail or ""),
        '{"reason":' .. js(readyReason or "") .. ',"vehicleId":' .. js(cleanVehicle) .. ',"spawnProfile":"aircraft"}')
      return false, deliveryReadyMessage(readyReason)
    end
    resolvedVehicleInfo = liveVehicleInfo
  end
  local dbResolveEnabled = vehicleNativeDbResolveEnabled(options)
  local beforeVehicleEntityId = 0
  local beforeVehicleDbOk = false
  if dbResolveEnabled then
    local dbOk, dbMessage, dbEntityId, dbData = nativeVehicleLatestEntityId(cleanVehicle, 1500,
      "vehicle-before-" .. tostring(os.time()) .. "-" .. tostring(math.floor(os.clock() * 1000000)))
    beforeVehicleDbOk = dbOk == true
    beforeVehicleEntityId = math.max(0, math.floor(tonumber(dbEntityId or 0) or 0))
    if not beforeVehicleDbOk then
      appendLog("vehicle db latest id read failed vehicle=" .. tostring(cleanVehicle) .. " message=" .. tostring(dbMessage))
      appendActionEvent("vehicle_db_tracking", false, resolvedVehicleInfo, tostring(dbMessage),
        '{"stage":"before-spawn","vehicleId":' .. js(cleanVehicle) .. ',"nativeResponse":' .. tostring(dbData or "{}") .. '}')
    end
  end
  local function resolveSpawnedVehicleDbRef(targetInfo, routeTag, currentRef)
    local runtimeRef = tostring(currentRef or "")
    if runtimeRef ~= "" or not dbResolveEnabled or not beforeVehicleDbOk then return runtimeRef end
    local dbOk, dbMessage, dbEntityId, dbData = nativeVehicleWaitNewEntityId(cleanVehicle, beforeVehicleEntityId, 12000,
      "vehicle-after-" .. tostring(os.time()) .. "-" .. tostring(math.floor(os.clock() * 1000000)))
    local entityId = math.max(0, math.floor(tonumber(dbEntityId or 0) or 0))
    if dbOk and entityId > 0 then
      appendActionEvent("vehicle_db_tracking", true, targetInfo, "vehicle entity id resolved through native DB",
        '{"stage":"after-spawn","vehicleId":' .. js(cleanVehicle) ..
        ',"beforeEntityId":' .. tostring(beforeVehicleEntityId) ..
        ',"entityId":' .. tostring(entityId) ..
        ',"route":' .. js(routeTag or "") ..
        ',"nativeResponse":' .. tostring(dbData or "{}") .. '}')
      return tostring(entityId)
    end
    appendActionEvent("vehicle_db_tracking", false, targetInfo, tostring(dbMessage),
      '{"stage":"after-spawn","vehicleId":' .. js(cleanVehicle) ..
      ',"beforeEntityId":' .. tostring(beforeVehicleEntityId) ..
      ',"route":' .. js(routeTag or "") ..
      ',"nativeResponse":' .. tostring(dbData or "{}") .. '}')
    return ""
  end
  local vehicleSelector = tostring(resolvedVehicleInfo.steam or "")
  if looksLikeSteamId(vehicleSelector) then
    local beforeVehicles = {}
    if configBool("vehicle-rental", { "CaptureVehiclesBeforeSpawn", "captureVehiclesBeforeSpawn" }, false) then
      beforeVehicles = vehicleRuntimeKeySet(cleanVehicle, true)
    end
    local commandText, spawnRoute = vehicleSpawnCommand(cleanVehicle, resolvedVehicleInfo)
    if requireForwardLocation and tostring(spawnRoute or ""):find("forward%-offset", 1) == nil then
      appendActionEvent("vehicle_spawn_location_blocked", false, resolvedVehicleInfo, "unsafe player-location fallback blocked",
        '{"vehicleId":' .. js(cleanVehicle) ..
        ',"command":' .. js(commandText) ..
        ',"spawnRoute":' .. js(spawnRoute or "") ..
        ',"source":' .. js(options.source or "") .. '}')
      return false, "безопасный спавн транспорта перед игроком не подтверждён"
    end
    local sent, message = adminExec(commandText, resolvedVehicleInfo)
    local last = tostring(message or "")
    if sent then
      local entityId = extractVehicleEntityIdFromText(last)
      local runtimeRef = entityId ~= "" and entityId or ""
      runtimeRef = resolveSpawnedVehicleDbRef(resolvedVehicleInfo, spawnRoute, runtimeRef)
      appendActionEvent("spawn_vehicle", true, resolvedVehicleInfo, last .. " command=" .. commandText,
        '{"vehicleId":' .. js(cleanVehicle) .. ',"command":' .. js(commandText) .. ',"spawnRoute":' .. js(spawnRoute or "") .. ',"runtimeRef":' .. js(runtimeRef) .. ',"adminTarget":true}')
      return true, last .. " command=" .. commandText, runtimeRef, beforeVehicles
    end
    appendActionEvent("spawn_vehicle", false, resolvedVehicleInfo, last ~= "" and last or "vehicle admin route failed",
      '{"vehicleId":' .. js(cleanVehicle) .. ',"command":' .. js(commandText) .. ',"spawnRoute":' .. js(spawnRoute or "") .. ',"adminTarget":true}')
    return false, last ~= "" and last or "vehicle admin route failed"
  end
  local liveInfo, ready, readyDetail, readyReason = deliveryReadyInfo(info, { requireInventory = false })
  if not ready then
    appendActionEvent("delivery_readiness", false, info, tostring(readyDetail or ""),
      '{"reason":' .. js(readyReason or "") .. ',"vehicleId":' .. js(cleanVehicle) .. '}')
    return false, deliveryReadyMessage(readyReason)
  end
  info = liveInfo
  if info == nil or info.pc == nil or not isValidObject(info.pc) then
    appendActionEvent("spawn_vehicle", false, info, "Игрок не найден среди реально подключённых.",
      '{"vehicleId":' .. js(cleanVehicle) .. '}')
    return false, "Игрок не найден среди реально подключённых."
  end
  local beforeVehicles = {}
  if configBool("vehicle-rental", { "CaptureVehiclesBeforeSpawn", "captureVehiclesBeforeSpawn" }, false) then
    beforeVehicles = vehicleRuntimeKeySet(cleanVehicle, true)
  end
  local commandText, spawnRoute = vehicleSpawnCommand(cleanVehicle, info)
  if requireForwardLocation and tostring(spawnRoute or ""):find("forward%-offset", 1) == nil then
    appendActionEvent("vehicle_spawn_location_blocked", false, info, "unsafe player-location fallback blocked",
      '{"vehicleId":' .. js(cleanVehicle) ..
      ',"command":' .. js(commandText) ..
      ',"spawnRoute":' .. js(spawnRoute or "") ..
      ',"source":' .. js(options.source or "") .. '}')
    return false, "безопасный спавн транспорта перед игроком не подтверждён"
  end
  local sent, message = adminExec(commandText, info)
  local last = tostring(message or "")
  if sent then
    local entityId = extractVehicleEntityIdFromText(last)
    local runtimeRef = entityId ~= "" and entityId or ""
    runtimeRef = resolveSpawnedVehicleDbRef(info, spawnRoute, runtimeRef)
    appendActionEvent("spawn_vehicle", true, info, last .. " command=" .. commandText,
      '{"vehicleId":' .. js(cleanVehicle) .. ',"command":' .. js(commandText) .. ',"spawnRoute":' .. js(spawnRoute or "") .. ',"runtimeRef":' .. js(runtimeRef) .. '}')
    return true, last .. " command=" .. commandText, runtimeRef, beforeVehicles
  end
  appendActionEvent("spawn_vehicle", false, info, last ~= "" and last or "Маршрут выдачи транспорта не сработал.",
    '{"vehicleId":' .. js(cleanVehicle) .. ',"command":' .. js(commandText) .. ',"spawnRoute":' .. js(spawnRoute or "") .. '}')
  return false, last ~= "" and last or "Маршрут выдачи транспорта не сработал."
end

-- Keep native DB polling out of the game-thread mutation path. The native
-- command bridge has one command/result pair, so both stages use its serial async queue.
function spawnVehicleForInfoAsync(vehicle, info, options, onResult)
  options = options or {}
  local cleanVehicle = canonicalVehicleId(vehicle)
  if cleanVehicle == "" then return false, "vehicle is missing" end
  if type(onResult) ~= "function" then return false, "vehicle async callback is missing" end

  local completed = false
  local function complete(sent, message, runtimeRef, beforeVehicles)
    if completed then return end
    completed = true
    local callbackOk, callbackErr = pcall(onResult,
      sent == true,
      tostring(message or ""),
      tostring(runtimeRef or ""),
      beforeVehicles or {})
    if not callbackOk then
      appendLog("vehicle async result handler failed vehicle=" .. tostring(cleanVehicle) .. " err=" .. tostring(callbackErr))
    end
  end

  local requestBase = "vehicle-async-" .. tostring(os.time()) .. "-" .. tostring(math.floor(os.clock() * 1000000))
  local nativeTrackingEnabled = vehicleNativeDbResolveEnabled(options)
  local function startSpawnAfterNativeBefore(beforeOk, beforeEntityId)
    local function runSpawn()
      local spawnOptions = {}
      for key, value in pairs(options or {}) do spawnOptions[key] = value end
      spawnOptions.skipNativeVehicleDbResolve = true
      local sent, message, runtimeRef, beforeVehicles = spawnVehicleForInfo(cleanVehicle, info, spawnOptions)
      if not sent then
        complete(false, message, "", beforeVehicles)
        return
      end
      if tostring(runtimeRef or "") ~= "" or not nativeTrackingEnabled or beforeOk ~= true then
        complete(true, message, runtimeRef or "", beforeVehicles)
        return
      end
      local queued, queueMessage = nativeVehicleWaitNewEntityIdAsync(cleanVehicle, beforeEntityId, 12000,
        requestBase .. "-after",
        function(dbOk, dbMessage, dbEntityId, dbData)
          local entityId = math.max(0, math.floor(tonumber(dbEntityId or 0) or 0))
          if dbOk and entityId > 0 then
            appendActionEvent("vehicle_db_tracking", true, info, "vehicle entity id resolved through native DB",
              '{"stage":"after-spawn","vehicleId":' .. js(cleanVehicle) ..
              ',"beforeEntityId":' .. tostring(beforeEntityId or 0) ..
              ',"entityId":' .. tostring(entityId) ..
              ',"route":"async","nativeResponse":' .. tostring(dbData or "{}") .. '}')
            complete(true, message, tostring(entityId), beforeVehicles)
            return
          end
          appendActionEvent("vehicle_db_tracking", false, info, tostring(dbMessage or "native vehicle tracking failed"),
            '{"stage":"after-spawn","vehicleId":' .. js(cleanVehicle) ..
            ',"beforeEntityId":' .. tostring(beforeEntityId or 0) ..
            ',"route":"async","nativeResponse":' .. tostring(dbData or "{}") .. '}')
          complete(true, message, "", beforeVehicles)
        end)
      if not queued then
        appendActionEvent("vehicle_db_tracking", false, info, tostring(queueMessage or "native vehicle tracking was not queued"),
          '{"stage":"after-spawn","vehicleId":' .. js(cleanVehicle) .. ',"route":"async-queue"}')
        complete(true, message, "", beforeVehicles)
      end
    end
    if type(deferGame) == "function" and deferGame(1, runSpawn) then return true end
    appendLog("vehicle async spawn scheduler unavailable vehicle=" .. tostring(cleanVehicle))
    return false, "Не удалось запланировать безопасный спавн транспорта."
  end

  if not nativeTrackingEnabled then
    return startSpawnAfterNativeBefore(false, 0)
  end

  local queued, queueMessage = nativeVehicleLatestEntityIdAsync(cleanVehicle, 1500, requestBase .. "-before",
    function(dbOk, dbMessage, dbEntityId, dbData)
      local beforeEntityId = math.max(0, math.floor(tonumber(dbEntityId or 0) or 0))
      if not dbOk then
        appendLog("vehicle async db latest id read failed vehicle=" .. tostring(cleanVehicle) .. " message=" .. tostring(dbMessage))
        appendActionEvent("vehicle_db_tracking", false, info, tostring(dbMessage or "native vehicle tracking failed"),
          '{"stage":"before-spawn","vehicleId":' .. js(cleanVehicle) .. ',"route":"async","nativeResponse":' .. tostring(dbData or "{}") .. '}')
      end
      local scheduled, scheduleMessage = startSpawnAfterNativeBefore(dbOk == true, beforeEntityId)
      if not scheduled then complete(false, scheduleMessage or "Не удалось запланировать безопасный спавн транспорта.", "", {}) end
    end)
  if not queued then return false, tostring(queueMessage or "Не удалось поставить native DB проверку транспорта в очередь.") end
  return true, requestBase, "__async__"
end

function vehicleSpawnAsyncQueueIsStale(queueItem, route)
  if queueItem == nil then return false end
  if queueItem.cancelled == true or MUTATION_QUEUE_CURRENT ~= queueItem then
    appendLog("vehicle async result ignored stale queue id=" .. tostring(queueItem.id or "") ..
      " label=" .. tostring(queueItem.label or "") .. " route=" .. tostring(route or ""))
    return true
  end
  queueItem.startedAt = os.time()
  return false
end

function destroyVehicleRef(vehicleRef, info, reason)
  local ref = tostring(vehicleRef or ""):gsub("^%s+", ""):gsub("%s+$", "")
  local targetInfo = info or {}
  local cleanReason = tostring(reason or "")
  local cleanupScoped = cleanReason == "cleanup-expired"
  if targetInfo ~= nil and not cleanupScoped and (targetInfo.pc == nil or not isValidObject(targetInfo.pc)) then
    targetInfo = resolvePlayerInfo(targetInfo.steam, targetInfo.name, targetInfo, targetInfo.runtimeKey) or targetInfo
  end
  if not cleanupScoped and (targetInfo == nil or targetInfo.pc == nil or not isValidObject(targetInfo.pc)) then
    targetInfo = findPlayer(nil, nil) or targetInfo or {}
  end
  if ref == "" or ref == "0" then
    appendActionEvent("vehicle_destroy", false, targetInfo, "vehicle destroy skipped: missing entity id",
      '{"vehicleRef":"","reason":' .. js(cleanReason) .. '}')
    return false, "missing vehicle entity id"
  end
  if ref:sub(1, 8) == "runtime:" then
    local vehicle = findVehicleByRuntimeRef(ref, true)
    if vehicle ~= nil then
      local okCall, err = safeCall(vehicle, "K2_DestroyActor")
      if not okCall then okCall, err = safeCall(vehicle, "Destroy") end
      appendActionEvent("vehicle_destroy", okCall, targetInfo, okCall and "vehicle destroyed through runtime object" or tostring(err),
        '{"vehicleRef":' .. js(ref) .. ',"reason":' .. js(cleanReason) .. ',"route":"runtime"}')
      return okCall, okCall and "vehicle destroyed through runtime object" or tostring(err)
    end
    appendActionEvent("vehicle_destroy", false, targetInfo, "runtime vehicle object not found",
      '{"vehicleRef":' .. js(ref) .. ',"reason":' .. js(cleanReason) .. ',"route":"runtime"}')
    return false, "runtime vehicle object not found"
  end
  local commandText = "DestroyVehicle " .. ref
  local sent, message = adminExec(commandText, targetInfo)
  appendActionEvent("vehicle_destroy", sent, targetInfo, tostring(message or ""),
    '{"vehicleRef":' .. js(ref) .. ',"reason":' .. js(cleanReason) .. ',"command":' .. js(commandText) .. '}')
  return sent, message
end

CHAT_ASCII_MAP = {
  ["А"] = "A", ["Б"] = "B", ["В"] = "V", ["Г"] = "G", ["Д"] = "D", ["Е"] = "E", ["Ё"] = "Yo", ["Ж"] = "Zh",
  ["З"] = "Z", ["И"] = "I", ["Й"] = "Y", ["К"] = "K", ["Л"] = "L", ["М"] = "M", ["Н"] = "N", ["О"] = "O",
  ["П"] = "P", ["Р"] = "R", ["С"] = "S", ["Т"] = "T", ["У"] = "U", ["Ф"] = "F", ["Х"] = "H", ["Ц"] = "Ts",
  ["Ч"] = "Ch", ["Ш"] = "Sh", ["Щ"] = "Sch", ["Ъ"] = "", ["Ы"] = "Y", ["Ь"] = "", ["Э"] = "E", ["Ю"] = "Yu",
  ["Я"] = "Ya", ["а"] = "a", ["б"] = "b", ["в"] = "v", ["г"] = "g", ["д"] = "d", ["е"] = "e", ["ё"] = "yo",
  ["ж"] = "zh", ["з"] = "z", ["и"] = "i", ["й"] = "y", ["к"] = "k", ["л"] = "l", ["м"] = "m", ["н"] = "n",
  ["о"] = "o", ["п"] = "p", ["р"] = "r", ["с"] = "s", ["т"] = "t", ["у"] = "u", ["ф"] = "f", ["х"] = "h",
  ["ц"] = "ts", ["ч"] = "ch", ["ш"] = "sh", ["щ"] = "sch", ["ъ"] = "", ["ы"] = "y", ["ь"] = "", ["э"] = "e",
  ["ю"] = "yu", ["я"] = "ya"
}

function utf8ContinuationByte(value)
  return value ~= nil and value >= 128 and value <= 191
end

function utf8SafePrefix(text, maxBytes)
  local source = tostring(text or "")
  local limit = math.max(16, tonumber(maxBytes) or 220)
  local out = {}
  local used = 0
  local changed = false
  local i = 1
  while i <= #source do
    local b0 = source:byte(i)
    local len = 0
    if b0 == nil then
      break
    elseif b0 < 128 then
      len = 1
    elseif b0 >= 194 and b0 <= 223 then
      if utf8ContinuationByte(source:byte(i + 1)) then len = 2 end
    elseif b0 >= 224 and b0 <= 239 then
      local b1 = source:byte(i + 1)
      local b2 = source:byte(i + 2)
      if utf8ContinuationByte(b1) and utf8ContinuationByte(b2) and
        not (b0 == 224 and b1 < 160) and not (b0 == 237 and b1 >= 160) then
        len = 3
      end
    elseif b0 >= 240 and b0 <= 244 then
      local b1 = source:byte(i + 1)
      local b2 = source:byte(i + 2)
      local b3 = source:byte(i + 3)
      if utf8ContinuationByte(b1) and utf8ContinuationByte(b2) and utf8ContinuationByte(b3) and
        not (b0 == 240 and b1 < 144) and not (b0 == 244 and b1 >= 144) then
        len = 4
      end
    end
    if len <= 0 then
      changed = true
      i = i + 1
    elseif used + len > limit then
      changed = true
      break
    else
      out[#out + 1] = source:sub(i, i + len - 1)
      used = used + len
      i = i + len
    end
  end
  return table.concat(out), changed
end

function chatSafeText(message)
  local text = tostring(message or "")
  text = text:gsub("[\r\n]+", " ")
  text = text:gsub("[%z\001-\031\127]", "")
  local maxBytes = configNumber("bridge-safety", { "MaxChatMessageBytes", "maxChatMessageBytes" }, 220)
  local sanitized, changed = utf8SafePrefix(text, maxBytes)
  if changed then
    appendLog("chat text utf8-sanitized originalBytes=" .. tostring(#text) .. " finalBytes=" .. tostring(#sanitized))
  end
  text = sanitized
  text = text:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
  return text
end

function broadcast(message)
  message = chatSafeText(message)
  local root = worldRoot()
  local misc = nil
  pcall(function() misc = StaticFindObject("/Script/SCUM.Default__MiscStatics") end)
  if misc ~= nil and root ~= nil then
    local okCall, err = safeCall(misc, "BroadcastChatLine", root, message, 6)
    if okCall then return true, "broadcast through MiscStatics" end
    appendLog("broadcast failed: " .. tostring(err))
  end
  local gm = gameModeRoot()
  if gm ~= nil then
    local okCall, err = safeCall(gm, "SendChatMessageToAll", message)
    if okCall then return true, "broadcast through GameMode SendChatMessageToAll" end
    appendLog("SendChatMessageToAll failed: " .. tostring(err))
    okCall, err = safeCall(gm, "BroadcastChatMessage", message)
    if okCall then return true, "broadcast through GameMode BroadcastChatMessage" end
    appendLog("BroadcastChatMessage failed: " .. tostring(err))
    okCall, err = safeCall(gm, "SendAdminMessage", message)
    if okCall then return true, "broadcast through GameMode SendAdminMessage" end
    appendLog("SendAdminMessage failed: " .. tostring(err))
  end
  return adminExec("#Announce " .. tostring(message or ""))
end

function broadcastGlobalChatOnly(message)
  message = chatSafeText(message)
  local root = worldRoot()
  local misc = nil
  pcall(function() misc = StaticFindObject("/Script/SCUM.Default__MiscStatics") end)
  if misc ~= nil and root ~= nil then
    local okCall, err = safeCall(misc, "BroadcastChatLine", root, ueString(message), 2)
    if okCall then return true, "broadcast through MiscStatics global chat" end
    appendLog("global chat broadcast fstring failed: " .. tostring(err))
    okCall, err = safeCall(misc, "BroadcastChatLine", root, message, 2)
    if okCall then return true, "broadcast through MiscStatics global chat raw" end
    appendLog("global chat broadcast raw failed: " .. tostring(err))
  end
  for _, info in ipairs(cachedPlayerInfos(math.max(10, configNumber("bridge-safety", { "PlayerInfoCacheTtlSeconds", "playerInfoCacheTtlSeconds" }, 300))) or {}) do
    local rpc = playerRpcChannel(info.pc)
    if rpc ~= nil then
      local okCall, err = safeCall(rpc, "Chat_Server_BroadcastChatMessage", ueString(message), 2)
      if okCall then return true, "broadcast through PlayerRpcChannel global chat" end
      appendLog("global chat PlayerRpcChannel fstring failed: " .. tostring(err))
      okCall, err = safeCall(rpc, "Chat_Server_BroadcastChatMessage", message, 2)
      if okCall then return true, "broadcast through PlayerRpcChannel global chat raw" end
      appendLog("global chat PlayerRpcChannel raw failed: " .. tostring(err))
      break
    end
  end
  local gm = gameModeRoot()
  if gm ~= nil then
    local okCall, err = safeCall(gm, "SendChatMessageToAll", message)
    if okCall then return true, "broadcast through GameMode global chat" end
    appendLog("global chat SendChatMessageToAll failed: " .. tostring(err))
    okCall, err = safeCall(gm, "BroadcastChatMessage", message)
    if okCall then return true, "broadcast through GameMode BroadcastChatMessage" end
    appendLog("global chat BroadcastChatMessage failed: " .. tostring(err))
  end
  return false, "Маршрут синего глобального чата не найден; #Announce для kill feed отключён."
end

function recordTargetMessage(info, message, source)
  if source == nil or source == false then return end
  local targetName = info and info.name or ""
  local targetSteam = info and info.steam or ""
  local label = "NeDjin"
  if targetName ~= "" then
    label = label .. " -> " .. targetName
  elseif targetSteam ~= "" then
    label = label .. " -> " .. targetSteam
  end
  enqueueChatEventWrite(message, label, targetSteam, "server", tostring(source))
end

function playerReplyTargetKey(info)
  if info == nil then return "" end
  local steam = cleanText(info.steam or info.steamId or "")
  if looksLikeSteamId(steam) then return "steam:" .. steam end
  if info.pc ~= nil and isValidObject(info.pc) then
    local pcKey = objectKey(info.pc)
    if pcKey ~= "" then return "pc:" .. pcKey end
  end
  local profile = cleanText(info.userProfileId or info.serverUserProfileId or info.profileId or "")
  if profile ~= "" and profile ~= "0" and info.pc ~= nil and isValidObject(info.pc) then return "profile:" .. profile end
  local name = cleanText(info.name or "")
  if name ~= "" and name:lower() ~= "unknown" and info.pc ~= nil and isValidObject(info.pc) then return "name:" .. name:lower() end
  return ""
end

function playerReplyTargetReliable(info)
  return playerReplyTargetKey(info) ~= ""
end

function targetMessageFallbackLog(label, err)
  if configBool("bridge-safety", { "EnableVerboseTargetMessageFallbackLog", "enableVerboseTargetMessageFallbackLog" }, false) then
    appendLog(tostring(label or "target chat fallback") .. ": " .. tostring(err or ""))
  end
end

function isLikelyPlayerControllerObject(obj)
  if obj == nil or not isValidObject(obj) then return false end
  local name = objectFullName(obj)
  if name == "" or name:find("^Function%s") ~= nil then return false end
  local className = ""
  if type(objectClassFullName) == "function" then className = objectClassFullName(obj) end
  if className:find("Function", 1, true) ~= nil then return false end
  if className:find("PlayerController", 1, true) ~= nil or className:find("ConZPlayerController", 1, true) ~= nil then return true end
  if name:find("PlayerController", 1, true) ~= nil or name:find("ConZPlayerController", 1, true) ~= nil then
    return name:find("/Script/", 1, true) == nil and name:find(":", 1, true) == nil
  end
  return false
end

function normalizeNonWhiteChatType(chatType, fallback)
  local kind = math.floor(tonumber(chatType) or tonumber(fallback) or 6)
  if kind < 1 or kind > 7 then kind = 6 end
  return kind
end

function sendTargetMessageViaMiscStatics(info, message, historySource, chatType)
  if info == nil or info.pc == nil or not isValidObject(info.pc) then return false, "live PlayerController missing" end
  if not isLikelyPlayerControllerObject(info.pc) then
    return false, "live PlayerController has unexpected object type: " .. tostring(objectFullName(info.pc))
  end
  local misc = nil
  pcall(function() misc = StaticFindObject("/Script/SCUM.Default__MiscStatics") end)
  if misc == nil then return false, "MiscStatics missing" end
  local kind = normalizeNonWhiteChatType(chatType, 6)
  local okCall, err = safeCall(misc, "SendChatLineToPlayer", info.pc, ueText(message), kind, false)
  if okCall then return targetMessageSent(info, message, historySource, "sent through SendChatLineToPlayer type=" .. tostring(kind)) end
  targetMessageFallbackLog("SendChatLineToPlayer FText target chat failed", err)
  okCall, err = safeCall(misc, "SendChatLineToPlayer", info.pc, message, kind, false)
  if okCall then return targetMessageSent(info, message, historySource, "sent through SendChatLineToPlayer raw type=" .. tostring(kind)) end
  return false, err
end

RCON_SEND_CHAT_DISABLED = RCON_SEND_CHAT_DISABLED or false

function adminCommandQuotedText(value)
  local text = chatSafeText(value)
  text = text:gsub("\\", "\\\\"):gsub('"', '\\"')
  return '"' .. text .. '"'
end

function sendTargetMessageViaAdminSendChat(info, message, chatType, historySource)
  if RCON_SEND_CHAT_DISABLED then return false, "SendChat disabled after runtime failure" end
  if not configBool("bridge-safety", { "EnableRconSendChatTargetMessages", "enableRconSendChatTargetMessages" }, true) then
    return false, "SendChat target route disabled by config"
  end
  local steam = cleanText(info and (info.steam or info.steamId) or "")
  if not looksLikeSteamId(steam) then return false, "target SteamID missing for SendChat" end
  local kind = normalizeNonWhiteChatType(chatType, 6)
  local commandText = "SendChat " .. tostring(kind) .. " " .. adminCommandQuotedText(message) .. " " .. steam
  local sent, route = adminExec(commandText, info)
  if sent then return targetMessageSent(info, message, historySource, "sent through admin SendChat type=" .. tostring(kind)) end
  appendLog("admin SendChat target failed type=" .. tostring(kind) .. " target=" .. tostring(steam) .. " err=" .. tostring(route))
  return false, route
end

function targetMessageChatType(message, historySource)
  local text = tostring(message or "")
  local lower = text:lower()
  if text:find("^%[Лут%]") or text:find("^%[Loot%]") then return 6 end
  if text:find("^%[Скан%]") or text:find("^%[Scan%]") then return 2 end
  if lower:find("not authorized", 1, true) or lower:find("error", 1, true) or lower:find("failed", 1, true) then return 7 end
  if text:find("ошибка", 1, true) or text:find("не удалось", 1, true) or text:find("не найден", 1, true) or
    text:find("не выполн", 1, true) or text:find("отключ", 1, true) or text:find("недоступ", 1, true) or
    text:find("кулдаун", 1, true) or text:find("Подожди", 1, true) or text:find("подожди", 1, true) or
    text:find("Повтори", 1, true) or text:find("повтори", 1, true) then
    return 7
  end
  if text:find("очеред", 1, true) or text:find("провер", 1, true) or text:find("заявка", 1, true) or
    text:find("готовится", 1, true) or text:find("accepted into the queue", 1, true) or
    text:find("queued", 1, true) or text:find("checking", 1, true) or text:find("busy", 1, true) then
    return 6
  end
  if text:find("выдан", 1, true) or text:find("выдача", 1, true) or text:find("начислен", 1, true) or
    text:find("успеш", 1, true) or text:find("получен", 1, true) or text:find("перемещ", 1, true) or
    text:find("accepted", 1, true) or text:find("delivered", 1, true) then
    return 3
  end
  return 6
end

function targetMessageSent(info, message, source, route)
  recordTargetMessage(info, message, source)
  appendLog("target message sent target=" .. tostring((info and (info.steam or info.name)) or "") .. " route=" .. tostring(route))
  return true, route
end

function targetMessageFreshInfo(info, reason)
  if info == nil then return nil, "missing" end
  local steam = cleanText(info.steam or info.steamId or "")
  local name = cleanText(info.name or "")
  local runtimeKey = cleanText(info.runtimeKey or info.psKey or info.pcKey or info.pawnKey or info.rpcKey or "")
  local reasonText = tostring(reason or "")

  if configBool("bridge-safety", { "RefreshPlayerCacheBeforeTargetMessage", "refreshPlayerCacheBeforeTargetMessage" }, true) then
    if reasonText:find("panel", 1, true) == 1 and type(refreshPlayerInfoCacheForPanel) == "function" then
      pcall(function() refreshPlayerInfoCacheForPanel("target-message", false) end)
    elseif type(refreshPlayerInfoCacheForCommand) == "function" then
      pcall(function() refreshPlayerInfoCacheForCommand("target-message") end)
    end
  end

  local candidate = nil
  if steam ~= "" or name ~= "" or runtimeKey ~= "" then
    candidate = findPlayer(steam, name, runtimeKey)
    if candidate == nil and (steam ~= "" or name ~= "") and type(resolvePlayerInfoFromServerLogTarget) == "function" then
      candidate = resolvePlayerInfoFromServerLogTarget(steam, name)
    end
  end
  if candidate == nil then return nil, "not-live" end

  if type(enrichPlayerInfoFromServerLog) == "function" then
    candidate = enrichPlayerInfoFromServerLog(candidate) or candidate
  end
  if steam ~= "" and cleanText(candidate.steam or candidate.steamId or "") == "" then
    candidate.steam = steam
    candidate.steamId = steam
  end
  if name ~= "" and (cleanText(candidate.name or "") == "" or cleanText(candidate.name or ""):lower() == "unknown") then
    candidate.name = name
  end

  local live = refreshRuntimePlayerInfo(candidate) or candidate
  if live == nil or live.pc == nil or not isValidObject(live.pc) then return nil, "no-live-controller" end
  local liveSteam = cleanText(live.steam or live.steamId or "")
  if steam ~= "" and liveSteam ~= "" and liveSteam ~= steam then return nil, "steam-mismatch" end
  return live, "ready"
end

