  { "^%[Скан%] Квадрат ([A-Z0-9]+) пуст%. Стоимость: %$(%d+)%. Источник: live%-координаты%.$", function(a, b) return "[Scan] Sector " .. a .. " is empty. Cost: $" .. b .. ". Source: live coordinates." end },
  { "^%[Скан%] Квадрат ([A-Z0-9]+) пуст%. Стоимость: бесплатно%. Источник: live%-координаты%.$", function(a) return "[Scan] Sector " .. a .. " is empty. Cost: free. Source: live coordinates." end },
  { "^Стартовый набор уже получен%. Осталось (%d+) сек%.$", function(a) return "Starter pack was already claimed. Remaining: " .. a .. " sec." end },
  { "^Стартовый набор не выдан полностью: (.+)$", function(a) return "Starter pack was not fully delivered: " .. a end },
  { "^Ежедневный пак уже получен%. Осталось (%d+) сек%.$", function(a) return "Daily pack was already claimed. Remaining: " .. a .. " sec." end },
  { "^Ежедневный пак не выдан полностью: (.+)$", function(a) return "Daily pack was not fully delivered: " .. a end },
  { "^Battlepass награда (%d+)/(%d+) выдана%.$", function(a, b) return "Battlepass reward " .. a .. "/" .. b .. " delivered." end },
  { "^VIP Battlepass награда (%d+)/(%d+) выдана%.$", function(a, b) return "VIP Battlepass reward " .. a .. "/" .. b .. " delivered." end },
  { "^Battlepass награда не выдана: (.+)$", function(a) return "Battlepass reward was not delivered: " .. a end },
  { "^Battlepass завершён: (%d+)/(%d+)%. Режим: (.+)%.$", function(a, b, c) return "Battlepass completed: " .. a .. "/" .. b .. ". Tier: " .. (c == "обычный" and "regular" or c) .. "." end },
  { "^Battlepass сегодня уже получен%. Текущий прогресс: (%d+)/(%d+)%. Режим: (.+)%.$", function(a, b, c) return "Battlepass already claimed today. Current progress: " .. a .. "/" .. b .. ". Tier: " .. (c == "обычный" and "regular" or c) .. "." end },
  { "^Battlepass день (%d+)/(%d+) ожидает прогрузку%. Выдача через (%d+) сек%. Режим: (.+)%.$", function(a, b, c, d) return "Battlepass day " .. a .. "/" .. b .. " is waiting for character load. Delivery in " .. c .. " sec. Tier: " .. (d == "обычный" and "regular" or d) .. "." end },
  { "^Battlepass день (%d+)/(%d+) поставлен в очередь%. Выдача через (%d+) сек после прогрузки%. Режим: (.+)%.$", function(a, b, c, d) return "Battlepass day " .. a .. "/" .. b .. " queued. Delivery starts " .. c .. " sec after loading. Tier: " .. (d == "обычный" and "regular" or d) .. "." end },
  { "^Battlepass день (%d+)/(%d+) будет выдан автоматически после входа и прогрузки%. Режим: (.+)%.$", function(a, b, c) return "Battlepass day " .. a .. "/" .. b .. " will be delivered automatically after login and character load. Tier: " .. (c == "обычный" and "regular" or c) .. "." end },
  { "^Спавн транспорта сейчас в безопасной паузе%. Повтор будет через (%d+) сек%.$", function(a) return "Vehicle spawn is in a safety delay. Retry in " .. a .. " sec." end },
  { "^Транспорт не выдан: (.+)%. Деньги не списывал%.$", function(a) return "Vehicle was not delivered: " .. a .. ". Money was not charged." end },
  { "^Wargm: выдача уже в очереди%. Повтори через (%d+) сек%.$", function(a) return "Wargm: delivery is already queued. Try again in " .. a .. " sec." end },
  { "^Активные квесты: (.+)$", function(a) return "Active quests: " .. a end },
  { "^Награда этого квеста на кулдауне%. Осталось (%d+) сек%.$", function(a) return "This quest reward is on cooldown. Remaining: " .. a .. " sec." end },
  { "^Этот режим квеста пока доступен только как доска/ручная проверка: (.+)%.$", function(a) return "This quest mode is currently available only as a board/manual check: " .. a .. "." end },
  { "^Квест выполнен: (.+)%.$", function(a) return "Quest completed: " .. a .. "." end },
  { "^Проверка Discord записана в очередь панели для канала '(.+)'%. Для реальной отправки настрой вебхук и нажми проверку в панели%.$", function(a) return "Discord test was written to the panel queue for channel '" .. a .. "'. Configure a webhook and press test in the panel for real delivery." end },
  { "^Возврат после Armory не выполнен: (.+)$", function(a) return "Armory return failed: " .. a end },
  { "^Armory не открыт: (.+)$", function(a) return "Armory was not opened: " .. a end },
  { "^Администратор отправил предмет: (.+) x(%d+)%.$", function(a, b) return "Administrator sent item: " .. a .. " x" .. b .. "." end },
  { "^Администратор удаляет предметы: отправлено (%d+)/(%d+)%.$", function(a, b) return "Administrator is deleting items: sent " .. a .. "/" .. b .. "." end },
  { "^Предмет не удалён: (.+)$", function(a) return "Item was not removed: " .. a end },
  { "^Нет права: (.+)$", function(a) return "Missing permission: " .. a end }
}

function translatePlayerMessageText(info, message)
  local lang = playerLanguage(info)
  if lang ~= "en" then return tostring(message or "") end
  local text = tostring(message or "")
  local exact = PLAYER_MESSAGE_EN[text]
  if exact ~= nil then return exact end
  for _, row in ipairs(PLAYER_MESSAGE_EN_PATTERNS or {}) do
    local pattern = row[1]
    local fn = row[2]
    local values = { text:match(pattern) }
    if #values > 0 then
      local unpackFn = table.unpack or unpack
      local ok, translated = pcall(function() return fn(unpackFn(values)) end)
      if ok and translated ~= nil and translated ~= "" then return tostring(translated) end
    end
  end
  return text
end

function sanitizePlayerFacingMessage(message)
  local text = tostring(message or "")
  if text:find("^Стартовый набор не выдан полностью:") then
    return "Стартовый набор не выдан полностью. Детали записаны в журнал администратора."
  end
  if text:find("^Ежедневный пак не выдан полностью:") then
    return "Ежедневный пак не выдан полностью. Детали записаны в журнал администратора."
  end
  if text:find("^Battlepass награда не выдана:") then
    return "Battlepass награда не выдана. Детали записаны в журнал администратора."
  end
  local lower = text:lower()
  if lower:find("command=#", 1, true) or lower:find("#spawnitem", 1, true) then
    return "Команда обработана. Детали записаны в журнал администратора."
  end
  return text
end

function sendTargetMessageToInfo(info, message, historySource, chatType)
  message = sanitizePlayerFacingMessage(message)
  message = translatePlayerMessageText(info, message)
  message = chatSafeText(message)
  if message == "" then
    appendLog("target message skipped empty after sanitize source=" .. tostring(historySource or "command-reply"))
    return false, "Сообщение пустое после очистки."
  end
  if configBool("bridge-safety", { "DisableInGameTargetMessages", "disableInGameTargetMessages" }, false) then
    recordTargetMessage(info, message, historySource or "command-reply")
    appendLog("target message suppressed by bridge-safety target=" .. tostring((info and (info.steam or info.name)) or "") ..
      " source=" .. tostring(historySource or "command-reply"))
    return false, "target messages disabled by bridge-safety"
  end
  if configBool("bridge-safety", { "RefreshTargetMessageLivePlayer", "refreshTargetMessageLivePlayer" }, true) then
    local freshInfo, freshReason = targetMessageFreshInfo(info, historySource or "command-reply")
    if freshInfo == nil then
      appendLog("target message skipped stale target reason=" .. tostring(freshReason or "") ..
        " target=" .. tostring((info and (info.steam or info.name or info.runtimeKey)) or "") ..
        " source=" .. tostring(historySource or "command-reply"))
      return false, "target player is not live"
    end
    info = freshInfo
  end
  if not playerReplyTargetReliable(info) then
    appendLog("target message skipped unresolved target source=" .. tostring(historySource or "command-reply"))
    return false, "target player unresolved"
  end
  local originalInfo = info
  local refreshed = nil
  if configBool("bridge-safety", { "RefreshPlayerBeforeMessage", "refreshPlayerBeforeMessage" }, false) then
    refreshed = refreshRuntimePlayerInfo(info)
  end
  if refreshed ~= nil then
    info = refreshed
    if (info.rpc == nil or not isValidObject(info.rpc)) and originalInfo ~= nil and originalInfo.rpc ~= nil and isValidObject(originalInfo.rpc) then
      info.rpc = originalInfo.rpc
      info.rpcKey = objectKey(originalInfo.rpc)
    end
  else
    info = originalInfo
  end

  local effectiveChatType = chatType
  if effectiveChatType == nil and configBool("bridge-safety", { "EnableStyledTargetMessages", "enableStyledTargetMessages" }, true) then
    effectiveChatType = targetMessageChatType(message, historySource)
  end

  local triedAdminChat = false
  if configBool("bridge-safety", { "PreferRconSendChatTargetMessages", "preferRconSendChatTargetMessages" }, false) then
    triedAdminChat = true
    local okAdminChat, adminChatErr = sendTargetMessageViaAdminSendChat(info, message, effectiveChatType or 6, historySource)
    if okAdminChat then return true, adminChatErr end
    targetMessageFallbackLog("admin SendChat target chat failed", adminChatErr)
  end

  if configBool("bridge-safety", { "PreferSendChatLineToPlayer", "preferSendChatLineToPlayer" }, true) then
    local okMisc, miscErr = sendTargetMessageViaMiscStatics(info, message, historySource, effectiveChatType)
    if okMisc then return true, miscErr end
    targetMessageFallbackLog("SendChatLineToPlayer target chat failed", miscErr)
  end

  if effectiveChatType ~= nil and not triedAdminChat and configBool("bridge-safety", { "AllowRconSendChatFallbackForTargetMessages", "allowRconSendChatFallbackForTargetMessages" }, false) then
    local okAdminChat, adminChatErr = sendTargetMessageViaAdminSendChat(info, message, effectiveChatType or 6, historySource)
    if okAdminChat then return true, adminChatErr end
    targetMessageFallbackLog("admin SendChat target chat failed", adminChatErr)
  elseif effectiveChatType ~= nil and not triedAdminChat then
    targetMessageFallbackLog("admin SendChat target chat skipped", "fallback disabled by config")
  end

  if info ~= nil and configBool("bridge-safety", { "EnableRpcTargetMessageFallbacks", "enableRpcTargetMessageFallbacks" }, false) then
    local rpc = nil
    if info.rpc ~= nil and isValidObject(info.rpc) then rpc = info.rpc end
    if rpc == nil and info.pc ~= nil and isValidObject(info.pc) then rpc = playerRpcChannel(info.pc) end
    if rpc ~= nil then
      local okCall, err = safeCall(rpc, "Chat_Client_SendMessageToChat", message, info.ps, 4, false)
      if okCall then return targetMessageSent(info, message, historySource, "sent through PlayerRpcChannel chat client") end
      targetMessageFallbackLog("RpcChannel target chat failed", err)
      okCall, err = safeCall(rpc, "Chat_Client_SendMessageToChat", message, 4, false)
      if okCall then return targetMessageSent(info, message, historySource, "sent through PlayerRpcChannel compact chat client") end
      targetMessageFallbackLog("RpcChannel compact target chat failed", err)
    end
  end

  if info == nil or info.pc == nil or not isValidObject(info.pc) or not isLikelyPlayerControllerObject(info.pc) then
    appendLog("target message skipped without live PlayerController target=" .. tostring(playerReplyTargetKey(info)))
    return false, "target chat route unavailable"
  end
  if configBool("bridge-safety", { "RefreshPlayerBeforeMessageFallback", "refreshPlayerBeforeMessageFallback" }, false) then
    info = refreshRuntimePlayerInfo(info)
  end
  if info == nil then return false, "Игрок не найден среди реально подключённых." end
  if info.pc == nil or not isValidObject(info.pc) then return false, "Игрок не найден среди реально подключённых." end

  if not configBool("bridge-safety", { "PreferSendChatLineToPlayer", "preferSendChatLineToPlayer" }, true) then
    local okMisc, miscErr = sendTargetMessageViaMiscStatics(info, message, historySource, effectiveChatType)
    if okMisc then return true, miscErr end
    targetMessageFallbackLog("SendChatLineToPlayer target chat failed", miscErr)
  end

  if configBool("bridge-safety", { "EnablePlayerControllerTargetMessageFallbacks", "enablePlayerControllerTargetMessageFallbacks" }, false) then
    local okCall, err = safeCall(info.pc, "ClientMessage", message, "Event", 5.0)
    if okCall then return targetMessageSent(info, message, historySource, "sent through PlayerController ClientMessage") end
    targetMessageFallbackLog("ClientMessage target chat failed", err)
    okCall, err = safeCall(info.pc, "ClientReceiveChatMessage", message, "Server", 4)
    if okCall then return targetMessageSent(info, message, historySource, "sent through ClientReceiveChatMessage") end
    targetMessageFallbackLog("ClientReceiveChatMessage target chat failed", err)
  end

  local gm = gameModeRoot()
  if gm ~= nil and info.pc ~= nil and configBool("bridge-safety", { "EnableGameModeTargetMessageFallback", "enableGameModeTargetMessageFallback" }, false) then
    local okCall, err = safeCall(gm, "SendChatMessage", message, info.pc)
    if okCall then return targetMessageSent(info, message, historySource, "sent through GameMode SendChatMessage") end
    targetMessageFallbackLog("GameMode target chat failed", err)
  end
  appendLog("target message failed all routes target=" .. tostring(playerReplyTargetKey(info)) ..
    " source=" .. tostring(historySource or "command-reply") ..
    " chatType=" .. tostring(effectiveChatType or "") ..
    " messageBytes=" .. tostring(#message))
  return false, "Сообщение игроку не удалось отправить через доступные маршруты."
end

function targetMessage(steamId, name, message, historySource, runtimeKey)
  local info = nil
  if type(resolvePlayerInfoForPanel) == "function" then
    info = resolvePlayerInfoForPanel(steamId, name, runtimeKey, nil, historySource or "target-message")
  else
    info = findPlayer(steamId, name, runtimeKey)
    if info == nil and not configBool("bridge-safety", { "AllowTargetMessageRuntimeResolve", "allowTargetMessageRuntimeResolve" }, false) then
      info = resolvePlayerInfoFromServerLogTarget(steamId, name)
    elseif info == nil then
      info = resolvePlayerInfo(steamId, name, nil, runtimeKey)
    end
  end
  return sendTargetMessageToInfo(info, message, historySource)
end

function targetMessageResolved(info, message, historySource)
  return sendTargetMessageToInfo(info, message, historySource or "command-reply")
end

function targetMessageResolvedStyled(info, message, chatType, historySource)
  return sendTargetMessageToInfo(info, message, historySource or "command-reply", chatType)
end

function sendTargetMessageLines(info, lines, historySource, chatTypeFn, options)
  historySource = historySource or "command-reply"
  options = options or {}
  local prepared = {}
  if type(lines) == "table" then
    for _, line in ipairs(lines) do
      local text = tostring(line or "")
      if text ~= "" then table.insert(prepared, text) end
    end
  elseif lines ~= nil then
    local text = tostring(lines or "")
    if text ~= "" then table.insert(prepared, text) end
  end
  if #prepared <= 0 then return true, "empty" end

  local function lineChatType(line)
    local forced = options.chatType
    if forced ~= nil then return forced end
    if type(chatTypeFn) == "function" then
      local ok, value = pcall(function() return chatTypeFn(line) end)
      if ok and value ~= nil then return value end
    end
    return nil
  end

  local function sendOne(target, line)
    local chatType = lineChatType(line)
    if chatType ~= nil then
      return targetMessageResolvedStyled(target, line, chatType, historySource)
    end
    return targetMessageResolved(target, line, historySource)
  end

  if #prepared == 1 or not configBool("bridge-safety", { "EnableDeferredMultiLineTargetMessages", "enableDeferredMultiLineTargetMessages" }, true) then
    for index, line in ipairs(prepared) do
      local freshInfo, freshReason = targetMessageFreshInfo(info, historySource)
      if freshInfo == nil then
        appendLog("target message line batch stopped stale target reason=" .. tostring(freshReason or "") ..
          " source=" .. tostring(historySource) .. " index=" .. tostring(index) ..
          " target=" .. tostring((info and (info.steam or info.name or info.runtimeKey)) or ""))
        return false, "target player is not live"
      end
      sendOne(freshInfo, line)
    end
    return true, "sent"
  end

  if type(gameThreadSchedulerStalled) == "function" and gameThreadSchedulerStalled() then
    local compact = tostring(options.compactMessage or prepared[1] or "")
    local maxChars = math.max(80, math.min(math.floor(configNumber("bridge-safety", { "TargetMessageBatchCompactMaxChars", "targetMessageBatchCompactMaxChars" }, 220) or 220), 800))
    if #compact > maxChars then compact = compact:sub(1, maxChars - 3) .. "..." end
    appendLog("target message line batch compacted because game-thread scheduler is stalled target=" ..
      tostring((info and (info.steam or info.name)) or "") .. " source=" .. tostring(historySource) ..
      " lines=" .. tostring(#prepared))
    local compactType = options.compactChatType or lineChatType(compact)
    if compactType ~= nil then
      return targetMessageResolvedStyled(info, compact, compactType, historySource)
    end
    return targetMessageResolved(info, compact, historySource)
  end

  local delayDefault = tonumber(options.delayMs) or configNumber("bridge-safety", { "TargetMessageBatchLineDelayMs", "targetMessageBatchLineDelayMs" }, 140) or 140
  local delayMs = math.max(40, math.min(math.floor(delayDefault), 1000))
  appendLog("target message line batch scheduled target=" .. tostring((info and (info.steam or info.name)) or "") ..
    " source=" .. tostring(historySource) .. " lines=" .. tostring(#prepared) .. " delayMs=" .. tostring(delayMs))

  local function sendLine(index)
    if index > #prepared then return end
    local freshInfo, freshReason = targetMessageFreshInfo(info, historySource)
    if freshInfo == nil then
      appendLog("target message line batch stopped stale target reason=" .. tostring(freshReason or "") ..
        " source=" .. tostring(historySource) .. " index=" .. tostring(index) ..
        " target=" .. tostring((info and (info.steam or info.name or info.runtimeKey)) or ""))
      return
    end
    sendOne(freshInfo, prepared[index])
    if index < #prepared and not deferGame(delayMs, function() sendLine(index + 1) end) then
      appendLog("target message line batch stopped: deferred send failed source=" .. tostring(historySource) ..
        " index=" .. tostring(index + 1))
    end
  end

  if not deferGame(0, function() sendLine(1) end) then
    appendLog("target message line batch failed to start target=" .. tostring((info and (info.steam or info.name)) or "") ..
      " source=" .. tostring(historySource))
    local compact = tostring(options.compactMessage or prepared[1] or "")
    local compactType = options.compactChatType or lineChatType(compact)
    if compactType ~= nil then
      return targetMessageResolvedStyled(info, compact, compactType, historySource)
    end
    return targetMessageResolved(info, compact, historySource)
  end
  return true, "scheduled"
end

function teleportResolved(info, x, y, z)
  info = enrichPlayerInfoFromServerLog(info) or info
  if info == nil then
    appendActionEvent("teleport", false, {}, "Игрок не найден среди реально подключённых.",
      '{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. '}')
    return false, "Игрок не найден среди реально подключённых."
  end
  if info.pawn == nil or not isValidObject(info.pawn) then
    appendActionEvent("teleport", false, info, "target pawn missing",
      '{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. '}')
    return false, "target pawn missing"
  end
  if configBool("bridge-safety", { "EnableDirectTeleport", "enableDirectTeleport", "AllowDirectPawnTeleport", "allowDirectPawnTeleport" }, false) then
    local location = { X = x, Y = y, Z = z }
    local okCall, err = safeCall(info.pawn, "K2_SetActorLocation", location, false, {}, true)
    if okCall then
      appendActionEvent("teleport", true, info, "teleported through pawn actor location",
        '{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. ',"route":"pawn"}')
      return true, "teleported through pawn actor location"
    end
    appendLog("direct teleport failed: " .. tostring(err))
  else
    appendLog("direct pawn teleport skipped by bridge-safety")
  end
  local target = tostring(info.steam or "") ~= "" and info.steam or info.name
  local sent, message = adminExec("#Teleport " .. tostring(x) .. " " .. tostring(y) .. " " .. tostring(z) .. " " .. tostring(target), info)
  appendActionEvent("teleport", sent, info, tostring(message or ""),
    '{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. ',"route":"admin"}')
  return sent, message
end

function teleport(steamId, name, x, y, z, runtimeKey)
  local info = enrichPlayerInfoFromServerLog(findPlayer(steamId, name, runtimeKey))
  if info == nil then
    appendActionEvent("teleport", false, { steam = steamId, name = name }, "Игрок не найден среди реально подключённых.",
      '{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. '}')
    return false, "Игрок не найден среди реально подключённых."
  end
  return teleportResolved(info, x, y, z)
end

function changeMoney(steamId, name, amount, currency, runtimeKey)
  amount = tonumber(amount) or 0
  if amount == 0 then
    appendActionEvent("change_money", true, { steam = steamId, name = name, runtimeKey = runtimeKey }, "Баланс не изменён: сумма 0.", '{"amount":0,"currency":' .. js(currency or "Normal") .. ',"queued":false}')
    return true, "Баланс не изменён: сумма 0."
  end
  local info = findPlayer(steamId, name, runtimeKey)
  if info == nil then info = resolvePlayerInfo(steamId, name, nil, runtimeKey) or { steam = tostring(steamId or ""), name = tostring(name or ""), runtimeKey = tostring(runtimeKey or ""), source = "money-identity" } end
  if tostring(info.steam or "") == "" then info.steam = tostring(steamId or "") end
  if tostring(info.name or "") == "" or tostring(info.name or "") == "Unknown" then info.name = tostring(name or "") end
  if info == nil then
    appendActionEvent("change_money", false, { steam = steamId, name = name }, "Игрок не найден среди реально подключённых.",
      '{"amount":' .. tostring(tonumber(amount) or 0) .. ',"currency":' .. js(currency or "Normal") .. '}')
    return false, "Игрок не найден среди реально подключённых."
  end
  currency = valueText(currency)
  if currency == "" then currency = "Normal" end
  if currency:lower() == "gold" then currency = "Gold" else currency = "Normal" end
  local resolvedInfo = enrichPlayerInfoFromServerLog(info) or info
  local requestedName = valueText(name)
  local selector = valueText(resolvedInfo.steam)
  if selector == "" then selector = valueText(info.steam) end
  if selector == "" or selector == "Unknown" then selector = requestedName end
  if selector == "" or selector == "Unknown" then selector = resolvedInfo.name or "" end
  if selector == "" or selector == "Unknown" then selector = info.name or "" end
  local commandText = "ChangeCurrencyBalance " .. tostring(currency) .. " " .. tostring(amount) .. " " .. tostring(selector)
  local queued, queueIdOrMessage, depth = enqueueMutation("change-money", resolvedInfo, function()
    local liveInfo = resolvePlayerInfo(resolvedInfo.steam, resolvedInfo.name, resolvedInfo, resolvedInfo.runtimeKey) or resolvedInfo
    if configBool("bridge-safety", { "RefreshPlayerBeforeMoneyChange", "refreshPlayerBeforeMoneyChange" }, false) then
      local refreshedMoneyInfo = refreshRuntimePlayerInfo(liveInfo)
      if refreshedMoneyInfo ~= nil then liveInfo = refreshedMoneyInfo end
    end
    local readyInfo, ready, readyDetail, readyReason = deliveryReadyInfo(liveInfo, { requireInventory = false })
    if not ready then
      appendActionEvent("delivery_readiness", false, liveInfo, tostring(readyDetail or ""),
        '{"reason":' .. js(readyReason or "") ..
        ',"action":"change_money","amount":' .. tostring(tonumber(amount) or 0) ..
        ',"currency":' .. js(currency) .. '}')
      appendLog("queued money command skipped readiness target=" .. tostring(selector) .. " reason=" .. tostring(readyReason or ""))
      return
    end
    liveInfo = readyInfo or liveInfo
    local liveSelector = valueText(liveInfo.steam)
    if liveSelector == "" or liveSelector == "Unknown" then liveSelector = valueText(liveInfo.name) end
    if liveSelector == "" or liveSelector == "Unknown" then liveSelector = selector end
    if liveSelector == "" or liveSelector == "Unknown" then
      appendActionEvent("change_money_execute", false, liveInfo, "missing target selector",
        '{"amount":' .. tostring(tonumber(amount) or 0) ..
        ',"currency":' .. js(currency) ..
        ',"selector":""}')
      return
    end
    local liveCommand = "ChangeCurrencyBalance " .. tostring(currency) .. " " .. tostring(amount) .. " " .. tostring(liveSelector)
    local sent, message = adminExec(liveCommand, liveInfo)
    appendActionEvent("change_money_execute", sent, liveInfo, tostring(message or ""),
      '{"amount":' .. tostring(tonumber(amount) or 0) ..
      ',"currency":' .. js(currency) ..
      ',"selector":' .. js(liveSelector) ..
      ',"command":' .. js(liveCommand) .. '}')
    appendLog("queued money command target=" .. tostring(liveSelector) ..
      " amount=" .. tostring(amount) ..
      " currency=" .. tostring(currency) ..
      " sent=" .. tostring(sent) ..
      " route=" .. tostring(message or ""))
  end)
  appendEconomyEvent("balance change requested", resolvedInfo.name, resolvedInfo.steam, amount, currency, queued)
  appendActionEvent("change_money", queued, resolvedInfo, queued and "Изменение баланса поставлено в live-очередь." or tostring(queueIdOrMessage or "Не удалось поставить изменение баланса в live-очередь."),
    '{"amount":' .. tostring(tonumber(amount) or 0) ..
    ',"currency":' .. js(currency) ..
    ',"selector":' .. js(selector) ..
    ',"queueId":' .. (queued and tostring(queueIdOrMessage) or "null") ..
    ',"depth":' .. tostring(depth or 0) ..
    ',"queued":' .. (queued and "true" or "false") .. '}')
  return queued, queued and "Изменение баланса поставлено в live-очередь." or tostring(queueIdOrMessage or "Не удалось поставить изменение баланса в live-очередь.")
end

function setFame(steamId, name, amount, runtimeKey)
  local info = findPlayer(steamId, name, runtimeKey)
  if info == nil then info = resolvePlayerInfo(steamId, name, nil, runtimeKey) or { steam = tostring(steamId or ""), name = tostring(name or ""), runtimeKey = tostring(runtimeKey or ""), source = "fame-identity" } end
  if tostring(info.steam or "") == "" then info.steam = tostring(steamId or "") end
  if tostring(info.name or "") == "" or tostring(info.name or "") == "Unknown" then info.name = tostring(name or "") end
  if info == nil then
    appendActionEvent("set_fame", false, { steam = steamId, name = name }, "Игрок не найден среди реально подключённых.",
      '{"amount":' .. tostring(tonumber(amount) or 0) .. '}')
    return false, "Игрок не найден среди реально подключённых."
  end
  local resolvedInfo = enrichPlayerInfoFromServerLog(info) or info
  local target = resolvedInfo.steam ~= "" and resolvedInfo.steam or resolvedInfo.name
  local commandText = "#SetFamePoints " .. tostring(amount) .. " " .. tostring(target)
  local queued, queueIdOrMessage, depth = enqueueMutation("set-fame", resolvedInfo, function()
    local liveInfo = resolvePlayerInfo(resolvedInfo.steam, resolvedInfo.name, resolvedInfo, resolvedInfo.runtimeKey) or resolvedInfo
    local liveTarget = liveInfo.steam ~= "" and liveInfo.steam or liveInfo.name
    if liveInfo.pc ~= nil and isValidObject(liveInfo.pc) then
      local directOk, directErr = safeCall(liveInfo.pc, "SetFamePoints", tonumber(amount) or 0)
      if directOk then
        appendActionEvent("set_fame_execute", true, liveInfo, "direct ConZPlayerController.SetFamePoints",
          '{"amount":' .. tostring(tonumber(amount) or 0) .. ',"route":"direct-pc"}')
        appendLog("queued fame command target=" .. tostring(liveTarget) ..
          " amount=" .. tostring(amount) ..
          " sent=true route=direct-pc")
        return
      end
      appendLog("direct SetFamePoints failed: " .. tostring(directErr))
    end
    local liveCommand = "#SetFamePoints " .. tostring(amount) .. " " .. tostring(liveTarget)
    local sent, message = adminExec(liveCommand, liveInfo)
    appendActionEvent("set_fame_execute", sent, liveInfo, tostring(message or ""),
      '{"amount":' .. tostring(tonumber(amount) or 0) .. ',"command":' .. js(liveCommand) .. '}')
    appendLog("queued fame command target=" .. tostring(liveTarget) ..
      " amount=" .. tostring(amount) ..
      " sent=" .. tostring(sent) ..
      " route=" .. tostring(message or ""))
  end)
  appendActionEvent("set_fame", queued, resolvedInfo, queued and "Изменение славы поставлено в live-очередь." or tostring(queueIdOrMessage or "Не удалось поставить изменение славы в live-очередь."),
    '{"amount":' .. tostring(tonumber(amount) or 0) ..
    ',"command":' .. js(commandText) ..
    ',"queueId":' .. (queued and tostring(queueIdOrMessage) or "null") ..
    ',"depth":' .. tostring(depth or 0) ..
    ',"queued":' .. (queued and "true" or "false") .. '}')
  return queued, queued and "Изменение славы поставлено в live-очередь." or tostring(queueIdOrMessage or "Не удалось поставить изменение славы в live-очередь.")
end

function fameNumberValue(value)
  if type(value) == "number" then return value end
  if value == nil then return nil end
  local ok, unwrapped = pcall(function()
    if type(value) == "userdata" and value.get ~= nil then return value:get() end
    return value
  end)
  if ok and type(unwrapped) == "number" then return unwrapped end
  if ok and type(unwrapped) == "string" then
    local parsed = tonumber((unwrapped:gsub(",", ".")))
    if parsed ~= nil then return parsed end
  end
  local text = valueText(ok and unwrapped or value)
  if text ~= "" then
    local parsed = tonumber((text:gsub(",", ".")))
    if parsed ~= nil then return parsed end
  end
  return nil
end

function currentFamePointsForInfo(info)
  if info == nil then return nil end
  local objects = {}
  if info.ps ~= nil then table.insert(objects, info.ps) end
  if info.pc ~= nil then table.insert(objects, info.pc) end
  if info.pawn ~= nil then table.insert(objects, info.pawn) end
  local methods = { "GetFamePoints", "GetFame", "GetScore", "GetPlayerScore" }
  local props = {
    "FamePoints", "Fame", "FamePoint", "CurrentFamePoints", "CurrentFame",
    "Score", "PlayerScore", "_famePoints", "_fame", "_score"
  }
  for _, obj in ipairs(objects) do
    if obj ~= nil and isValidObject(obj) then
      for _, method in ipairs(methods) do
        local okCall, value = safeCall(obj, method)
        if okCall then
          local number = fameNumberValue(value)
          if number ~= nil then return number, method end
        end
      end
      for _, prop in ipairs(props) do
        local number = fameNumberValue(safeGet(obj, prop))
        if number ~= nil then return number, prop end
      end
    end
  end
  return nil
end

function changeFamePoints(steamId, name, amount, runtimeKey)
  amount = tonumber(amount) or 0
  if amount == 0 then
    appendActionEvent("change_fame", true, { steam = steamId, name = name, runtimeKey = runtimeKey }, "Слава не изменена: сумма 0.", '{"amount":0,"queued":false}')
    return true, "Слава не изменена: сумма 0."
  end
  local info = findPlayer(steamId, name, runtimeKey)
  if info == nil then info = resolvePlayerInfo(steamId, name, nil, runtimeKey) or { steam = tostring(steamId or ""), name = tostring(name or ""), runtimeKey = tostring(runtimeKey or ""), source = "fame-identity" } end
  if tostring(info.steam or "") == "" then info.steam = tostring(steamId or "") end
  if tostring(info.name or "") == "" or tostring(info.name or "") == "Unknown" then info.name = tostring(name or "") end
  if info == nil then
    appendActionEvent("change_fame", false, { steam = steamId, name = name }, "Игрок не найден среди реально подключённых.",
      '{"amount":' .. tostring(tonumber(amount) or 0) .. '}')
    return false, "Игрок не найден среди реально подключённых."
  end
  local resolvedInfo = enrichPlayerInfoFromServerLog(info) or info
  local selector = valueText(resolvedInfo.steam)
  if selector == "" or selector == "Unknown" then selector = valueText(info.steam) end
  if selector == "" or selector == "Unknown" then selector = valueText(resolvedInfo.name) end
  if selector == "" or selector == "Unknown" then selector = valueText(info.name) end
  local commandText = "#ChangeFamePoints " .. tostring(amount) .. " " .. tostring(selector)
  local queued, queueIdOrMessage, depth = enqueueMutation("change-fame", resolvedInfo, function()
    local liveInfo = resolvePlayerInfo(resolvedInfo.steam, resolvedInfo.name, resolvedInfo, resolvedInfo.runtimeKey) or resolvedInfo
    local readyInfo, ready, readyDetail, readyReason = deliveryReadyInfo(liveInfo, { requireInventory = false })
    if not ready then
      appendActionEvent("delivery_readiness", false, liveInfo, tostring(readyDetail or ""),
        '{"reason":' .. js(readyReason or "") ..
        ',"action":"change_fame","amount":' .. tostring(tonumber(amount) or 0) .. '}')
      appendLog("queued fame command skipped readiness target=" .. tostring(selector) .. " reason=" .. tostring(readyReason or ""))
      return
    end
    liveInfo = readyInfo or liveInfo
    local liveSelector = valueText(liveInfo.steam)
    if liveSelector == "" or liveSelector == "Unknown" then liveSelector = valueText(liveInfo.name) end
    if liveSelector == "" or liveSelector == "Unknown" then liveSelector = selector end
    if liveSelector == "" or liveSelector == "Unknown" then
      appendActionEvent("change_fame_execute", false, liveInfo, "missing target selector",
        '{"amount":' .. tostring(tonumber(amount) or 0) .. ',"selector":""}')
      return
    end
    local liveCommand = "#ChangeFamePoints " .. tostring(amount) .. " " .. tostring(liveSelector)
    local sent, message = adminExec(liveCommand, liveInfo)
    appendActionEvent("change_fame_execute", sent, liveInfo, tostring(message or ""),
      '{"amount":' .. tostring(tonumber(amount) or 0) ..
      ',"selector":' .. js(liveSelector) ..
      ',"command":' .. js(liveCommand) ..
      ',"route":"admin-change-additive"}')
    appendLog("queued fame change command target=" .. tostring(liveSelector) ..
      " amount=" .. tostring(amount) ..
      " sent=" .. tostring(sent) ..
      " route=admin-change-additive message=" .. tostring(message or ""))
    if not sent then
      error("change fame command failed: " .. tostring(message or "unknown"))
    end
  end)
  appendActionEvent("change_fame", queued, resolvedInfo, queued and "Начисление очков славы поставлено в live-очередь." or tostring(queueIdOrMessage or "Не удалось поставить начисление очков славы в live-очередь."),
    '{"amount":' .. tostring(tonumber(amount) or 0) ..
    ',"command":' .. js(commandText) ..
    ',"queueId":' .. (queued and tostring(queueIdOrMessage) or "null") ..
    ',"depth":' .. tostring(depth or 0) ..
    ',"queued":' .. (queued and "true" or "false") .. '}')
  return queued, queued and "Начисление очков славы поставлено в live-очередь." or tostring(queueIdOrMessage or "Не удалось поставить начисление очков славы в live-очередь.")
end

