function canonicalVehicleId(vehicleId)
  local raw = tostring(vehicleId or ""):gsub("^%s+", ""):gsub("%s+$", "")
  raw = raw:gsub("^Vehicle:", "")
  raw = raw:gsub("_C$", "")
  local aliases = {
    bp_kinglet_duster = "BPC_Kinglet_Duster",
    kinglet_duster = "BPC_Kinglet_Duster",
    bp_kinglet_mariner = "BPC_Kinglet_Mariner",
    kinglet_mariner = "BPC_Kinglet_Mariner",
    bp_kinglet_scout = "BPC_Kinglet_Scout",
    kinglet_scout = "BPC_Kinglet_Scout",
    bp_quad_01_a = "BPC_RIS",
    ris = "BPC_RIS",
    bp_cruiser_01 = "BPC_Cruiser",
    cruiser = "BPC_Cruiser",
    bp_tractor_01_a = "BPC_Tractor",
    tractor = "BPC_Tractor",
    bp_sup = "BPC_SUP",
    sup = "BPC_SUP",
    bp_improvised_raft_big = "BPC_BigRaft",
    bigraft = "BPC_BigRaft",
    bp_wheelbarrow_01 = "BP_WheelBarrow_Metal",
    metalwheelbarrow = "BP_WheelBarrow_Metal"
  }
  local mapped = aliases[raw:lower()]
  if mapped ~= nil then return mapped end
  return raw
end

function vehicleSpawnProfile(vehicleId)
  local raw = canonicalVehicleId(vehicleId):lower():gsub("^vehicle:", ""):gsub("_c$", "")
  local token = raw:gsub("^bpc_", ""):gsub("^bp_", "")
  local aircraft = {
    bpc_kinglet_duster = true,
    bp_kinglet_duster = true,
    kinglet_duster = true,
    kingletduster = true,
    bpc_kinglet_mariner = true,
    bp_kinglet_mariner = true,
    kinglet_mariner = true,
    kingletmariner = true,
    bpc_kinglet_scout = true,
    bp_kinglet_scout = true,
    kinglet_scout = true,
    kingletscout = true
  }
  if aircraft[raw] or aircraft[token] then return "aircraft" end
  return "default"
end

function boundedVehicleSpawnNumber(value, fallback, minValue, maxValue)
  local n = tonumber(value)
  if n == nil then n = tonumber(fallback) or 0 end
  if minValue ~= nil and n < minValue then n = minValue end
  if maxValue ~= nil and n > maxValue then n = maxValue end
  return n
end

function vehicleSpawnCommand(cleanVehicle, info)
  local vehicleId = canonicalVehicleId(cleanVehicle)
  local profile = vehicleSpawnProfile(vehicleId)
  if playerHasUsableLocation(info) then
    local forwardDistance = 0
    local sideOffset = 0
    local liftZ = 0
    if profile == "aircraft" then
      local maxForward = configNumber("bridge-safety", { "AircraftVehicleSpawnMaxForwardDistance", "aircraftVehicleSpawnMaxForwardDistance" }, 1200)
      local maxLift = configNumber("bridge-safety", { "AircraftVehicleSpawnMaxLiftZ", "aircraftVehicleSpawnMaxLiftZ" }, 80)
      forwardDistance = boundedVehicleSpawnNumber(configNumber("bridge-safety", {
        "AircraftVehicleSpawnForwardDistance", "aircraftVehicleSpawnForwardDistance",
        "AircraftVehicleSpawnOffsetX", "aircraftVehicleSpawnOffsetX"
      }, 900), 900, 450, maxForward)
      sideOffset = boundedVehicleSpawnNumber(configNumber("bridge-safety", {
        "AircraftVehicleSpawnSideOffset", "aircraftVehicleSpawnSideOffset",
        "AircraftVehicleSpawnOffsetY", "aircraftVehicleSpawnOffsetY"
      }, 0), 0, -500, 500)
      liftZ = boundedVehicleSpawnNumber(configNumber("bridge-safety", { "AircraftVehicleSpawnLiftZ", "aircraftVehicleSpawnLiftZ" }, 60), 60, 0, maxLift)
    else
      local maxForward = configNumber("bridge-safety", { "VehicleSpawnMaxForwardDistance", "vehicleSpawnMaxForwardDistance" }, 1000)
      local maxLift = configNumber("bridge-safety", { "VehicleSpawnMaxLiftZ", "vehicleSpawnMaxLiftZ" }, 80)
      forwardDistance = boundedVehicleSpawnNumber(configNumber("bridge-safety", {
        "VehicleSpawnForwardDistance", "vehicleSpawnForwardDistance",
        "VehicleSpawnOffsetX", "vehicleSpawnOffsetX"
      }, 500), 500, 250, maxForward)
      sideOffset = boundedVehicleSpawnNumber(configNumber("bridge-safety", {
        "VehicleSpawnSideOffset", "vehicleSpawnSideOffset",
        "VehicleSpawnOffsetY", "vehicleSpawnOffsetY"
      }, 0), 0, -300, 300)
      liftZ = boundedVehicleSpawnNumber(configNumber("bridge-safety", { "VehicleSpawnLiftZ", "vehicleSpawnLiftZ" }, 35), 35, 0, maxLift)
    end
    local fx, fy = forwardVectorOf(info.pawn)
    if fx == nil or fy == nil then fx, fy = forwardVectorOf(info.pc) end
    if (fx == nil or fy == nil) and tonumber(info.yaw) ~= nil then
      local rad = math.rad(tonumber(info.yaw) or 0)
      fx, fy = math.cos(rad), math.sin(rad)
    end
    if fx == nil or fy == nil then fx, fy = 1, 0 end
    local rightX, rightY = -fy, fx
    local x = math.floor((tonumber(info.x) or 0) + (fx * forwardDistance) + (rightX * sideOffset) + 0.5)
    local y = math.floor((tonumber(info.y) or 0) + (fy * forwardDistance) + (rightY * sideOffset) + 0.5)
    local z = math.floor((tonumber(info.z) or 0) + liftZ + 0.5)
    return "SpawnVehicle " .. vehicleId .. " 1 Location " .. tostring(x) .. " " .. tostring(y) .. " " .. tostring(z), profile .. "-forward-offset"
  end
  local selector = tostring((info and info.steam) or "")
  if looksLikeSteamId(selector) then
    return "SpawnVehicle " .. vehicleId .. " 1 Location " .. selector, "player-location"
  end
  return "SpawnVehicle " .. vehicleId, "default"
end

function vehicleClassHints(vehicleId, includeGenericFallback)
  local raw = canonicalVehicleId(vehicleId)
  local token = raw:gsub("^BPC_", ""):gsub("^BP_", ""):gsub("_C$", "")
  local genericHints = {
    "VehicleBase",
    "ConZVehicle",
    "ConZVehicleBase",
    "DcxVehicle",
    "DcxWheeledVehicle",
    "DcxWheeledVehicle4W",
    "DcxWheeledVehicleNW",
    "BP_VehicleBase_C",
    "BP_Vehicle_C"
  }
  local hints = {}
  if raw ~= "" then
    table.insert(hints, raw)
    table.insert(hints, raw .. "_C")
  end
  if token ~= "" then
    table.insert(hints, "BPC_" .. token)
    table.insert(hints, "BPC_" .. token .. "_C")
    table.insert(hints, "BP_" .. token)
    table.insert(hints, "BP_" .. token .. "_C")
  end
  if #hints == 0 or includeGenericFallback == true then
    local seen = {}
    for _, hint in ipairs(hints) do seen[hint] = true end
    for _, hint in ipairs(genericHints) do
      if not seen[hint] then
        table.insert(hints, hint)
        seen[hint] = true
      end
    end
  end
  return hints
end

vehicleRuntimeKeySet = function(vehicleId, allowRentalScoped)
  local seen = {}
  if not vehicleRuntimeScanAllowed(allowRentalScoped) then return seen end
  local includeGenericFallback = allowRentalScoped == true and configBool("vehicle-rental", {
    "EnableRuntimeVehicleGenericClassFallback", "enableRuntimeVehicleGenericClassFallback",
    "EnableRuntimeVehicleGenericFallback", "enableRuntimeVehicleGenericFallback"
  }, false)
  for _, vehicle in ipairs(findAll(vehicleClassHints(vehicleId, includeGenericFallback))) do
    local key = objectKey(vehicle)
    if key ~= "" then seen[key] = true end
  end
  return seen
end

function vehicleLooksLike(vehicle, vehicleId)
  local raw = canonicalVehicleId(vehicleId):lower():gsub("^vehicle:", ""):gsub("_c$", "")
  local token = raw:gsub("^bpc_", ""):gsub("^bp_", "")
  if token == "" then return true end
  local full = objectFullName(vehicle):lower()
  return full:find(token, 1, true) ~= nil
end

function nearestNewVehicleRefAt(px, py, pz, vehicleId, beforeKeys, allowGenericFallback, allowRentalScoped)
  px = tonumber(px) or 0
  py = tonumber(py) or 0
  pz = tonumber(pz) or 0
  if not vehicleRuntimeScanAllowed(allowRentalScoped) then return "", nil end
  local includeGenericFallback = allowRentalScoped == true and allowGenericFallback == true and configBool("vehicle-rental", {
    "EnableRuntimeVehicleGenericClassFallback", "enableRuntimeVehicleGenericClassFallback",
    "EnableRuntimeVehicleGenericFallback", "enableRuntimeVehicleGenericFallback"
  }, false)
  local vehicles = findAll(vehicleClassHints(vehicleId, includeGenericFallback))
  local function pick(requireLooksLike)
    local best = nil
    local bestDistance = nil
    for _, vehicle in ipairs(vehicles) do
      local key = objectKey(vehicle)
      if key ~= "" and (beforeKeys == nil or not beforeKeys[key]) and (not requireLooksLike or vehicleLooksLike(vehicle, vehicleId)) then
        local vx, vy, vz = vectorOf(vehicle)
        local dx, dy, dz = vx - px, vy - py, vz - pz
        local distance = math.sqrt(dx * dx + dy * dy + dz * dz)
        if distance <= 50000 and (bestDistance == nil or distance < bestDistance) then
          best = key
          bestDistance = distance
        end
      end
    end
    return best, bestDistance
  end
  local best, bestDistance = pick(true)
  if best == nil and allowGenericFallback == true and beforeKeys ~= nil then
    best, bestDistance = pick(false)
  end
  if best == nil then
    appendLog("vehicle runtime tracking miss vehicle=" .. tostring(vehicleId) .. " candidates=" .. tostring(#vehicles) .. " before=" .. (beforeKeys ~= nil and "yes" or "no"))
    return ""
  end
  appendLog("vehicle runtime tracked ref=runtime:" .. tostring(best) .. " distance=" .. tostring(math.floor((bestDistance or 0) + 0.5)))
  return "runtime:" .. tostring(best)
end

nearestNewVehicleRef = function(info, vehicleId, beforeKeys, allowGenericFallback, allowRentalScoped)
  if info == nil or info.pawn == nil then return "" end
  local px, py, pz = vectorOf(info.pawn)
  return nearestNewVehicleRefAt(px, py, pz, vehicleId, beforeKeys, allowGenericFallback, allowRentalScoped)
end

function resolveRentalDestroyRef(active, info)
  if active == nil then return "" end
  local vehicleId = extractString(active, "vehicleId") or ""
  if vehicleId == "" then return "" end
  if info ~= nil and info.pawn ~= nil then
    local liveRef = nearestNewVehicleRef(info, vehicleId, nil, true, true)
    if liveRef ~= "" then return liveRef end
  end
  local recordedX = extractNumber(active, "x")
  local recordedY = extractNumber(active, "y")
  local recordedZ = extractNumber(active, "z") or 0
  if recordedX ~= nil and recordedY ~= nil then
    local recordedRef = nearestNewVehicleRefAt(recordedX, recordedY, recordedZ, vehicleId, nil, true, true)
    if recordedRef ~= "" then return recordedRef end
  end
  return ""
end

findVehicleByRuntimeRef = function(ref, allowRentalScoped)
  local key = tostring(ref or ""):gsub("^runtime:", "")
  if key == "" then return nil end
  if not vehicleRuntimeScanAllowed(allowRentalScoped) then return nil end
  for _, vehicle in ipairs(findAll(vehicleClassHints(""))) do
    if objectKey(vehicle) == key then return vehicle end
  end
  return nil
end

catalogItemClassPaths = nil

function normalizeItemKey(value)
  local text = tostring(value or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
  text = text:gsub("^.*/", ""):gsub("^.*\\", ""):gsub("^.*%.", ""):gsub("_c$", "")
  return text
end

function ensureCatalogItemClassPaths()
  if catalogItemClassPaths ~= nil then return catalogItemClassPaths end
  catalogItemClassPaths = {}
  local function addCatalogPath(itemId, runtimeId)
    itemId = tostring(itemId or "")
    runtimeId = tostring(runtimeId or "")
    if itemId ~= "" and runtimeId ~= "" and runtimeId:sub(1, 6) == "/Game/" then
      catalogItemClassPaths[itemId:lower()] = runtimeId
      catalogItemClassPaths[normalizeItemKey(itemId)] = runtimeId
      catalogItemClassPaths[normalizeItemKey(runtimeId)] = runtimeId
      return true
    end
    return false
  end
  local text = readAll(ITEM_CATALOG_FILE) or ""
  local loaded = 0
  for object in text:gmatch('%b{}') do
    local itemId = extractString(object, "itemId") or extractString(object, "id") or ""
    local runtimeId = extractString(object, "runtimeId") or extractString(object, "classPath") or extractString(object, "assetPath") or ""
    if addCatalogPath(itemId, runtimeId) then loaded = loaded + 1 end
  end
  if loaded < 10 then
    loaded = 0
    catalogItemClassPaths = {}
    for itemId, runtimeId in text:gmatch('"itemId"%s*:%s*"([^"]+)".-"runtimeId"%s*:%s*"([^"]+)"') do
      if addCatalogPath(itemId, runtimeId) then loaded = loaded + 1 end
    end
  end
  local actorMapLoaded = 0
  local actorText = readAll(ITEM_ACTOR_MAP_FILE) or ""
  for itemId, runtimeId in actorText:gmatch('"([^"]+)"%s*:%s*"(/Game/[^"]+)"') do
    if addCatalogPath(itemId, runtimeId) then actorMapLoaded = actorMapLoaded + 1 end
  end
  if actorMapLoaded > 0 then
    loaded = loaded + actorMapLoaded
    appendLog("nedjincore actor map paths loaded=" .. tostring(actorMapLoaded))
  end
  if loaded < 10 and actorMapLoaded == 0 then
    local fallbackText = readAll("Mods\\NeDjinCore\\data\\es_actor_map.json") or ""
    for itemId, runtimeId in fallbackText:gmatch('"([^"]+)"%s*:%s*"(/Game/[^"]+)"') do
      if addCatalogPath(itemId, runtimeId) then actorMapLoaded = actorMapLoaded + 1 end
    end
    if actorMapLoaded > 0 then
      loaded = loaded + actorMapLoaded
      appendLog("nedjincore bundled actor map paths loaded=" .. tostring(actorMapLoaded))
    end
  end
  appendLog("item catalog class paths loaded=" .. tostring(loaded))
  return catalogItemClassPaths
end

function resolveItemPath(itemId)
  local raw = tostring(itemId or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if raw == "" then return "" end
  if raw:sub(1, 6) == "/Game/" or raw:sub(1, 8) == "/Script/" then return raw end
  local catalog = ensureCatalogItemClassPaths()
  return itemClassPaths[raw:lower()] or catalog[raw:lower()] or catalog[normalizeItemKey(raw)] or raw
end

