function zombieMeshCandidatePaths(requestMeshPath)
  local config = zombieTransformConfig()
  local out = {}
  local seen = {}
  local function add(value)
    value = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if value == "" or seen[value:lower()] then return end
    seen[value:lower()] = true
    table.insert(out, value)
  end
  add(requestMeshPath)
  add(configString("zombie-infection", { "ZombieMeshPath", "MeshPath", "meshPath" }, ""))
  for _, value in ipairs(jsonStringArrayForKey(config, "ZombieMeshCandidates")) do add(value) end
  for _, value in ipairs(jsonStringArrayForKey(config, "zombieMeshCandidates")) do add(value) end
  for _, value in ipairs(zombieMeshDefaultCandidates()) do add(value) end
  return out
end

function assetLoadCandidates(path, includeGeneratedClass)
  local raw = tostring(path or ""):gsub("^%s+", ""):gsub("%s+$", "")
  local objectPaths = {}
  local packagePaths = {}
  local seenObject = {}
  local seenPackage = {}
  local function addObject(value)
    value = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if value == "" or seenObject[value] then return end
    seenObject[value] = true
    table.insert(objectPaths, value)
  end
  local function addPackage(value)
    value = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if value == "" or seenPackage[value] then return end
    seenPackage[value] = true
    table.insert(packagePaths, value)
  end

  if raw == "" then return objectPaths, packagePaths end
  addObject(raw)
  if raw:sub(1, 6) == "/Game/" then
    local packagePath, objectName = raw:match("^(.-)%.([^%.\\/]+)$")
    if packagePath ~= nil and objectName ~= nil then
      addPackage(packagePath)
      addObject(packagePath .. "." .. objectName)
      if includeGeneratedClass then
        addObject(packagePath .. "." .. objectName:gsub("_C$", "") .. "_C")
      end
    else
      local leaf = raw:match("([^/\\]+)$") or raw
      addPackage(raw)
      addObject(raw .. "." .. leaf)
      if includeGeneratedClass then addObject(raw .. "." .. leaf:gsub("_C$", "") .. "_C") end
    end
  end
  return objectPaths, packagePaths
end

function loadZombieAssetFromCandidates(paths, includeGeneratedClass)
  local attempts = {}
  for _, path in ipairs(paths or {}) do
    local objectPaths, packagePaths = assetLoadCandidates(path, includeGeneratedClass == true)
    local loadedObject = nil
    for _, objectPath in ipairs(objectPaths) do
      local okFind, obj = pcall(function() return StaticFindObject(objectPath) end)
      table.insert(attempts, "StaticFindObject(" .. tostring(objectPath) .. ")=" .. (okFind and (isValidObject(obj) and "ok" or "nil") or tostring(obj)))
      if okFind and obj ~= nil and isValidObject(obj) then return obj, objectPath, attempts end
    end
    for _, packagePath in ipairs(packagePaths) do
      local okLoad, obj = pcall(function() return LoadAsset(packagePath) end)
      table.insert(attempts, "LoadAsset(" .. tostring(packagePath) .. ")=" .. (okLoad and (isValidObject(obj) and "ok" or "nil") or tostring(obj)))
      if okLoad and obj ~= nil and isValidObject(obj) then loadedObject = obj end
    end
    for _, objectPath in ipairs(objectPaths) do
      local okFind, obj = pcall(function() return StaticFindObject(objectPath) end)
      table.insert(attempts, "post StaticFindObject(" .. tostring(objectPath) .. ")=" .. (okFind and (isValidObject(obj) and "ok" or "nil") or tostring(obj)))
      if okFind and obj ~= nil and isValidObject(obj) then return obj, objectPath, attempts end
    end
    if loadedObject ~= nil and isValidObject(loadedObject) then return loadedObject, path, attempts end
  end
  return nil, "", attempts
end

function playerMeshComponents(info)
  local out = {}
  local seen = {}
  local function add(component, route)
    if component == nil or not isValidObject(component) then return end
    local key = objectKey(component)
    if key == "" then key = objectFullName(component) end
    if key == "" or seen[key] then return end
    seen[key] = true
    table.insert(out, { component = component, route = route or "unknown" })
  end
  local pawn = (info or {}).pawn
  if pawn == nil or not isValidObject(pawn) then return out end

  local okCall, mesh = safeCall(pawn, "GetMesh")
  if okCall then add(mesh, "pawn.GetMesh") end
  for _, key in ipairs({ "Mesh", "CharacterMesh0", "SkeletalMeshComponent", "SkeletalMesh", "BodyMesh", "MainMesh", "CharacterMesh" }) do
    add(firstProp(pawn, { key }), "pawn." .. key)
  end

  local compClass = nil
  pcall(function() compClass = StaticFindObject("/Script/Engine.SkeletalMeshComponent") end)
  if compClass ~= nil and isValidObject(compClass) then
    local okComponents, components = safeCall(pawn, "GetComponentsByClass", compClass)
    if okComponents and components ~= nil then
      for _, component in pairs(components) do add(component, "pawn.GetComponentsByClass") end
    end
  end

  if #out == 0 then
    if not scanFeatureEnabled({ "AllowSkeletalMeshComponentOwnerScan", "allowSkeletalMeshComponentOwnerScan" }, false) then return out end
    local pawnKey = objectKey(pawn)
    for _, component in ipairs(findAll({ "SkeletalMeshComponent" })) do
      local okOwner, owner = safeCall(component, "GetOwner")
      if okOwner and owner ~= nil and objectKey(owner) == pawnKey then add(component, "owner-scan") end
    end
  end
  return out
end

function componentCurrentMesh(component)
  return firstProp(component, { "SkeletalMesh", "SkinnedAsset", "Mesh", "SkeletalMeshAsset" })
end

function componentHasMesh(component, mesh)
  local current = componentCurrentMesh(component)
  if current == nil or mesh == nil then return false end
  local currentKey = objectKey(current)
  local meshKey = objectKey(mesh)
  if currentKey ~= "" and meshKey ~= "" and currentKey == meshKey then return true end
  return objectFullName(current) ~= "" and objectFullName(current) == objectFullName(mesh)
end

function setZombieMeshOnComponent(component, mesh)
  local attempts = {}
  local applied = false
  local mode = tostring(configString("zombie-infection", { "MeshApplyMode", "meshApplyMode" }, "property")):lower()
  local unsafeRefresh = configBool("zombie-infection", { "UnsafePostMeshRefresh", "unsafePostMeshRefresh" }, false)
  local unsafeFull = mode == "unsafe-full" or mode == "full" or mode == "legacy"
  local propertyFirst = mode == "property" or mode == "direct" or mode == "direct-property"

  if mode == "disabled" or mode == "off" then
    return false, "MeshApplyMode=disabled"
  end

  local function hasMesh()
    if component == nil or not isValidObject(component) then return false end
    return componentHasMesh(component, mesh)
  end

  local function attempt(label, fn)
    if component == nil or not isValidObject(component) then
      table.insert(attempts, label .. "=component-invalid")
      return
    end
    local okRun, result = pcall(fn)
    table.insert(attempts, label .. "=" .. (okRun and (result == false and "false" or "ok") or tostring(result)))
    if hasMesh() then applied = true end
  end

  if propertyFirst then
    attempt("SkeletalMesh=mesh", function() component.SkeletalMesh = mesh return true end)
    if not hasMesh() then attempt("SkinnedAsset=mesh", function() component.SkinnedAsset = mesh return true end) end
    if not hasMesh() then attempt("SetSkeletalMesh(mesh,false)", function() return component:SetSkeletalMesh(mesh, false) end) end
  else
    attempt("SetSkeletalMesh(mesh,false)", function() return component:SetSkeletalMesh(mesh, false) end)
    if not hasMesh() then attempt("SetSkeletalMesh(mesh)", function() return component:SetSkeletalMesh(mesh) end) end
  end

  if unsafeFull then
    if not hasMesh() then attempt("SetSkeletalMesh(mesh,true)", function() return component:SetSkeletalMesh(mesh, true) end) end
    if not hasMesh() then attempt("SetSkeletalMeshAsset(mesh)", function() return component:SetSkeletalMeshAsset(mesh) end) end
    if not hasMesh() then attempt("SetSkinnedAssetAndUpdate(mesh)", function() return component:SetSkinnedAssetAndUpdate(mesh, true) end) end
    if not hasMesh() then attempt("SkeletalMesh=mesh", function() component.SkeletalMesh = mesh return true end) end
    if not hasMesh() then attempt("SkinnedAsset=mesh", function() component.SkinnedAsset = mesh return true end) end
  end

  if unsafeRefresh then
    for _, method in ipairs({ "MarkRenderStateDirty", "RefreshBoneTransforms", "RefreshFollowerComponents", "UpdateBounds", "RecreateRenderState_Concurrent", "ForceUpdateTransform", "UpdateComponentToWorld" }) do
      local okCall, result = safeCall(component, method)
      table.insert(attempts, method .. "=" .. (okCall and "ok" or tostring(result)))
    end
  else
    table.insert(attempts, "postRefresh=skipped")
  end

  return applied or hasMesh(), table.concat(attempts, " | ")
end

function zombieAnimCandidates()
  local config = zombieTransformConfig()
  local out = {}
  local seen = {}
  local function add(value)
    value = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if value == "" or seen[value:lower()] then return end
    seen[value:lower()] = true
    table.insert(out, value)
  end
  add(configString("zombie-infection", { "ZombieAnimBlueprintPath", "AnimBlueprintPath", "AnimationBlueprintPath" }, ""))
  for _, value in ipairs(jsonStringArrayForKey(config, "ZombieAnimBlueprintCandidates")) do add(value) end
  add("/Game/ConZ_Files/Characters/Zombies2/Blueprints/ABP_Zombie.ABP_Zombie_C")
  return out
end

function applyZombieAnimation(component)
  local mode = tostring(configString("zombie-infection", { "MeshApplyMode", "meshApplyMode" }, "property")):lower()
  local unsafeFull = mode == "unsafe-full" or mode == "full" or mode == "legacy"
  if not unsafeFull or configBool("zombie-infection", { "UnsafeAnimBlueprint", "unsafeAnimBlueprint" }, false) == false then
    return false, "disabled-safe-mode"
  end
  if configBool("zombie-infection", { "ApplyZombieAnimation", "applyZombieAnimation" }, false) == false then
    return false, "disabled"
  end
  local animPath = configString("zombie-infection", { "ZombieAnimBlueprintPath", "AnimBlueprintPath", "AnimationBlueprintPath" }, "")
  local animClass, route, attempts = loadZombieAssetFromCandidates(zombieAnimCandidates(), true)
  if animClass == nil then return false, "animation blueprint unresolved: " .. table.concat(attempts or {}, " | ") end
  local logs = {}
  local okCall, result = safeCall(component, "SetAnimInstanceClass", animClass)
  table.insert(logs, "SetAnimInstanceClass=" .. (okCall and "ok" or tostring(result)))
  if not okCall then
    local okSet, setErr = pcall(function() component.AnimClass = animClass end)
    table.insert(logs, "AnimClass=class=" .. (okSet and "ok" or tostring(setErr)))
    okCall = okSet
  end
  safeCall(component, "InitAnim", true)
  safeCall(component, "RefreshBoneTransforms")
  return okCall, table.concat(logs, " | ") .. " route=" .. tostring(route or "")
end

function applyZombieMeshToPlayer(info, requestMeshPath)
  local components = playerMeshComponents(info)
  if #components == 0 then return false, "У игрока не найден SkeletalMeshComponent.", "{}" end
  local mesh, route, loadAttempts = loadZombieAssetFromCandidates(zombieMeshCandidatePaths(requestMeshPath), false)
  if mesh == nil then
    return false, "Модель зомби не загрузилась. Проверь путь mesh в настройках.", '{"loadAttempts":' .. js(table.concat(loadAttempts or {}, " | ")) .. '}'
  end

  local componentMode = tostring(configString("zombie-infection", { "MeshComponentMode", "meshComponentMode" }, "primary")):lower()
  local maxComponents = componentMode == "all" and #components or 1
  local applied = 0
  local componentLogs = {}
  local original = {}
  for index, entry in ipairs(components) do
    if index > maxComponents then break end
    local component = entry.component
    table.insert(original, objectFullName(componentCurrentMesh(component)))
    local okMesh, meshLog = setZombieMeshOnComponent(component, mesh)
    local okAnim, animLog = applyZombieAnimation(component)
    if okMesh then applied = applied + 1 end
    table.insert(componentLogs, tostring(entry.route or "component") .. ": mesh=" .. tostring(okMesh) .. " anim=" .. tostring(okAnim) .. " [" .. tostring(meshLog) .. "] [" .. tostring(animLog) .. "]")
  end

  if applied <= 0 then
    return false, "Компонент найден, но SCUM/UE не принял замену mesh.", '{"meshRoute":' .. js(route) .. ',"componentAttempts":' .. js(table.concat(componentLogs, " || ")) .. '}'
  end

  appendJsonArray(ZOMBIE_TRANSFORM_STATE_FILE,
    '{"utc":' .. js(nowUtc()) ..
    ',"steamId":' .. js((info or {}).steam or "") ..
    ',"name":' .. js((info or {}).name or "") ..
    ',"runtimeKey":' .. js((info or {}).runtimeKey or "") ..
    ',"meshPath":' .. js(route or "") ..
    ',"components":' .. tostring(applied) ..
    ',"original":' .. js(table.concat(original, " | ")) .. '}',
    1024 * 1024)

  return true, "Модель игрока заменена на зомби.", '{"meshRoute":' .. js(route) .. ',"components":' .. tostring(applied) .. ',"componentAttempts":' .. js(table.concat(componentLogs, " || ")) .. '}'
end

function normalizeConZGender(value)
  local raw = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
  local compact = raw:lower():gsub("[#\"']", ""):gsub("^setgender%s+", ""):gsub("[%s_%-%./]+", "")
  if compact == "" or compact == "toggle" or compact == "auto" then return "", nil, "toggle" end
  if compact == "female" or compact == "woman" or compact == "girl" or compact == "f" or compact == "1" or compact == "женский" or compact == "женщина" or compact == "девушка" then
    return "Female", 1, "female"
  end
  if compact == "male" or compact == "man" or compact == "boy" or compact == "m" or compact == "2" or compact == "мужской" or compact == "мужчина" or compact == "парень" then
    return "Male", 2, "male"
  end
  return "", nil, compact
end

function genderNumber(value)
  local n = tonumber(value)
  if n ~= nil then return math.floor(n) end
  local text = tostring(value or "")
  local number = text:match("(%d+)")
  if number ~= nil then return tonumber(number) end
  local lower = text:lower()
  if lower:find("female", 1, true) ~= nil then return 1 end
  if lower:find("male", 1, true) ~= nil then return 2 end
  return nil
end

function playerGenderValue(info)
  local pawn = (info or {}).pawn
  if pawn == nil or not isValidObject(pawn) then return nil, "pawn missing" end
  local okCall, value = safeCall(pawn, "GetGender")
  if okCall then return genderNumber(value), "GetGender=" .. tostring(value) end
  local prop = firstProp(pawn, { "_gender", "Gender", "gender" })
  if prop ~= nil then return genderNumber(prop), "property=" .. tostring(prop) end
  return nil, "gender unavailable"
end

function setPlayerGenderByAdmin(info, requestedGender)
  if info == nil then return false, "Игрок не найден среди реально подключённых.", "{}" end
  local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
  local readyInfo, ready, readyDetail, readyReason = deliveryReadyInfo(live, { requireInventory = false })
  if not ready then
    return false, deliveryReadyMessage(readyReason), '{"ready":false,"reason":' .. js(readyReason or "") .. ',"detail":' .. js(readyDetail or "") .. '}'
  end
  live = readyInfo or live

  local token, targetNumber, normalized = normalizeConZGender(requestedGender)
  local beforeNumber, beforeRoute = playerGenderValue(live)
  if normalized == "toggle" then
    if beforeNumber == 1 then
      token, targetNumber, normalized = "Male", 2, "male"
    else
      token, targetNumber, normalized = "Female", 1, "female"
    end
  end
  if token == "" or targetNumber == nil then
    return false, "Укажи пол для #SetGender: Male/Female или 1/2.", '{"requested":' .. js(requestedGender or "") .. '}'
  end

  local attempts = {}
  local variants = { token, tostring(targetNumber) }
  local sent = false
  local message = ""
  for _, variant in ipairs(variants) do
    local okAdmin, adminMessage = adminExec("SetGender " .. variant, live)
    table.insert(attempts, "#SetGender " .. variant .. "=" .. (okAdmin and "ok" or tostring(adminMessage)))
    sent = okAdmin
    message = tostring(adminMessage or "")
    local afterNumber, afterRoute = playerGenderValue(live)
    if okAdmin and afterNumber == targetNumber and beforeNumber ~= targetNumber then
      appendActionEvent("set_player_gender", true, live, "Пол игрока изменён через #SetGender " .. token,
        '{"mode":"admin-command","command":"#SetGender ' .. tostring(token) .. '","before":' .. js(tostring(beforeNumber or "")) .. ',"after":' .. js(tostring(afterNumber or "")) .. ',"beforeRoute":' .. js(beforeRoute or "") .. ',"afterRoute":' .. js(afterRoute or "") .. '}')
      return true, "Модель/пол игрока изменены штатной командой #SetGender " .. token .. ".", '{"mode":"admin-command","command":"#SetGender ' .. tostring(token) .. '","gender":' .. js(normalized) .. ',"before":' .. js(tostring(beforeNumber or "")) .. ',"after":' .. js(tostring(afterNumber or "")) .. ',"route":' .. js(tostring(message)) .. '}'
    elseif okAdmin and beforeNumber == targetNumber and afterNumber == targetNumber then
      table.insert(attempts, "#SetGender " .. variant .. "=already-target-gender")
    end
  end

  if configBool("bridge-safety", { "AllowDirectPawnSetGenderFallback", "allowDirectPawnSetGenderFallback" }, false) then
    local okDirect, directResult = safeCall(live.pawn, "SetGender", targetNumber)
    table.insert(attempts, "pawn.SetGender(" .. tostring(targetNumber) .. ")=" .. (okDirect and "ok" or tostring(directResult)))
    local afterNumber, afterRoute = playerGenderValue(live)
    if okDirect and afterNumber == targetNumber then
      appendActionEvent("set_player_gender", true, live, "Пол игрока изменён через pawn.SetGender fallback после #SetGender.",
        '{"mode":"direct-fallback","command":"#SetGender ' .. tostring(token) .. '","before":' .. js(tostring(beforeNumber or "")) .. ',"after":' .. js(tostring(afterNumber or "")) .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
      return true, "Модель/пол игрока изменены через SCUM SetGender pipeline.", '{"mode":"direct-fallback","command":"#SetGender ' .. tostring(token) .. '","gender":' .. js(normalized) .. ',"before":' .. js(tostring(beforeNumber or "")) .. ',"after":' .. js(tostring(afterNumber or "")) .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
    end
  end

  appendActionEvent("set_player_gender", false, live, "SetGender не подтвердил изменение модели.",
    '{"command":"#SetGender ' .. tostring(token) .. '","before":' .. js(tostring(beforeNumber or "")) .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
  return false, "SCUM не подтвердил #SetGender: " .. table.concat(attempts, " | "), '{"mode":"admin-command","command":"#SetGender ' .. tostring(token) .. '","sent":' .. (sent and "true" or "false") .. ',"message":' .. js(message) .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
end

function transformPlayerToZombie(steamId, name, runtimeKey, requestMeshPath, messageOverride, announceOverride, whisperOverride, requestGender, requestMode)
  if not zombieTransformEnabled() then return false, "Плагин превращения в зомби выключен.", "{}" end
  local info = resolvePlayerInfo(steamId, name, nil, runtimeKey)
  if info == nil then return false, "Игрок не найден среди реально подключённых.", "{}" end
  local cooldown = math.max(0, configNumber("zombie-infection", { "CooldownSeconds", "cooldownSeconds" }, 60) or 0)
  local waitSeconds = cooldownRemaining("zombie-transforms.json", info, cooldown)
  if waitSeconds > 0 then return false, "Превращение сейчас в паузе. Подожди " .. tostring(waitSeconds) .. " сек.", '{"cooldownSeconds":' .. tostring(waitSeconds) .. '}' end

  local mode = tostring(requestMode or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
  if mode == "" then mode = tostring(configString("zombie-infection", { "TransformMode", "transformMode", "Mode", "mode" }, "mesh")):lower() end
  local okMesh = false
  local meshMessage = ""
  local data = "{}"
  if mode == "setgender" or mode == "set-gender" or mode == "gender" or mode == "scum-setgender" then
    okMesh, meshMessage, data = setPlayerGenderByAdmin(info, requestGender)
  elseif mode == "mesh" or mode == "server-mesh" or mode == "unsafe-mesh" then
    okMesh, meshMessage, data = applyZombieMeshToPlayer(info, requestMeshPath)
  elseif mode == "both" or mode == "suit-and-mesh" then
    local okSuit, suitMessage, suitData = applyZombieSuitToPlayer(info)
    local okServerMesh, serverMeshMessage, serverMeshData = applyZombieMeshToPlayer(info, requestMeshPath)
    okMesh = okSuit
    meshMessage = okSuit and suitMessage or (suitMessage .. " | mesh: " .. tostring(serverMeshMessage))
    data = '{"mode":"both","appearance":' .. tostring(suitData or "{}") .. ',"serverMesh":' .. tostring(serverMeshData or "{}") .. ',"serverMeshOk":' .. (okServerMesh and "true" or "false") .. '}'
  else
    okMesh, meshMessage, data = applyZombieSuitToPlayer(info)
    if not okMesh and configBool("zombie-infection", { "AllowMeshFallback", "allowMeshFallback" }, false) then
      local okFallback, fallbackMessage, fallbackData = applyZombieMeshToPlayer(info, requestMeshPath)
      okMesh = okFallback
      meshMessage = okFallback and fallbackMessage or (meshMessage .. " | mesh fallback: " .. tostring(fallbackMessage))
      data = '{"mode":"scum-appearance","appearanceFailed":' .. tostring(data or "{}") .. ',"meshFallback":' .. tostring(fallbackData or "{}") .. '}'
    end
  end

  appendActionEvent("zombie_transform", okMesh, info, meshMessage, data or "{}")
  if not okMesh then return false, meshMessage, data or "{}" end

  rememberCooldown("zombie-transforms.json", info, cooldown)
  local playerName = tostring(info.name or name or "игрок")
  local playerMessage = tostring(messageOverride or "")
  if playerMessage == "" then playerMessage = configString("zombie-infection", { "PlayerMessage", "playerMessage" }, "Ты превращён в зомби.") end
  local whisper = whisperOverride
  if whisper == nil then whisper = configBool("zombie-infection", { "WhisperToPlayer", "whisperToPlayer" }, true) end
  if whisper ~= false and playerMessage ~= "" then targetMessageResolved(info, applyVars(playerMessage, { player = playerName })) end

  local announce = announceOverride
  if announce == nil then announce = configBool("zombie-infection", { "AnnounceToServer", "announceToServer" }, true) end
  if announce ~= false then
    local announceMessage = configString("zombie-infection", { "AnnounceMessage", "announceMessage" }, "[Зомби] {player} превращён в зомби.")
    if announceMessage ~= "" then broadcast(applyVars(announceMessage, { player = playerName })) end
  end
  return true, meshMessage, data or "{}"
end

function destroySpawnedItem(item)
  if item == nil or not isValidObject(item) then return end
  local okCall = false
  okCall = safeCall(item, "K2_DestroyActor")
  if okCall then return end
  safeCall(item, "Destroy")
end

function actorSummonToken(actorClass)
  local raw = tostring(actorClass or ""):gsub("^%s+", ""):gsub("%s+$", "")
  raw = raw:gsub("^#?%s*[Ss]ummon%s+", "")
  raw = raw:gsub("^BlueprintGeneratedClass%s+", "")
  raw = raw:gsub("^Class%s+", "")
  raw = raw:gsub("^['\"]", ""):gsub("['\"]$", "")
  raw = raw:gsub("^%s+", ""):gsub("%s+$", "")
  if raw == "" then return "" end
  if raw:find("%s") then return "" end
  if raw:find("[^%w_:/%.%-]") then return "" end
  return raw
end

loadedActorCatalogPaths = nil
loadedActorCatalogTexts = nil

function actorCatalogKey(value)
  local raw = tostring(value or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
  raw = raw:gsub("^class'", ""):gsub("'$", "")
  raw = raw:gsub("^blueprintgeneratedclass%s+", ""):gsub("^class%s+", "")
  raw = raw:gsub("^['\"]", ""):gsub("['\"]$", "")
  return raw
end

function actorObjectPathFromPackage(packagePath, className)
  local package = tostring(packagePath or ""):gsub("^%s+", ""):gsub("%s+$", "")
  local name = tostring(className or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if package == "" then return "" end
  if package:find("%.") then return package end
  if name == "" then name = package:match("([^/\\]+)$") or "" end
  if name == "" then return package end
  return package .. "." .. name
end

function actorPackagePathFromObject(objectPath)
  local raw = tostring(objectPath or "")
  if raw == "" then return "" end
  local package = raw:match("^(.+)%.([^%.]+)$")
  return package or raw
end

function loadActorCatalogPaths()
  if loadedActorCatalogPaths == nil then loadedActorCatalogPaths = {} end
  return loadedActorCatalogPaths
end

function actorCatalogTextForFile(path)
  local key = tostring(path or "")
  if key == "" then return "" end
  if loadedActorCatalogTexts == nil then loadedActorCatalogTexts = {} end
  if loadedActorCatalogTexts[key] == nil then
    loadedActorCatalogTexts[key] = readAll(key) or ""
  end
  return loadedActorCatalogTexts[key] or ""
end

function actorCatalogEntryFromText(cleanActor, text)
  text = tostring(text or "")
  if text == "" then return nil end
  local needles = {
    '"actorClass":"' .. cleanActor .. '"',
    '"name":"' .. cleanActor .. '"',
    '"path":"' .. cleanActor .. '"',
    '"packagePath":"' .. cleanActor .. '"'
  }
  local pos = nil
  for _, needle in ipairs(needles) do
    pos = text:find(needle, 1, true)
    if pos ~= nil then break end
  end
  if pos == nil and cleanActor:sub(-2) ~= "_C" then
    pos = text:find('"actorClass":"' .. cleanActor .. '_C"', 1, true)
  end
  if pos == nil then
    appendLog("actor catalog lookup miss " .. tostring(cleanActor))
    return nil
  end
  local left = text:sub(1, pos):match(".*(){") or pos
  local right = text:find("}", pos, true) or math.min(#text, pos + 1200)
  local object = text:sub(left, right)
  local actor = extractStringAny(object, { "actorClass", "className", "assetName", "name", "id" }) or cleanActor
  local objectPath = extractStringAny(object, { "path", "objectPath", "runtimeId", "classPath" }) or ""
  local packagePath = extractStringAny(object, { "packagePath", "package", "assetPath" }) or actorPackagePathFromObject(objectPath)
  local parentClass = extractStringAny(object, { "parentClass", "parent", "nativeParentClass" }) or ""
  local nativeParentName = extractStringAny(object, { "nativeParentName", "nativeParent", "parentName" }) or ""
  local category = extractStringAny(object, { "category", "type", "folder" }) or ""
  local summonableActor = extractBoolAny(object, { "summonableActor", "isActor", "actorDerived" }, nil)
  local summonRoute = extractStringAny(object, { "summonRoute", "spawnRoute", "route" }) or ""
  local summonNote = extractStringAny(object, { "summonNote", "spawnNote", "note" }) or ""
  local entry = {
    actorClass = actor,
    path = objectPath,
    objectPath = objectPath,
    packagePath = packagePath,
    parentClass = parentClass,
    nativeParentName = nativeParentName,
    category = category,
    summonableActor = summonableActor,
    summonRoute = summonRoute,
    summonNote = summonNote
  }
  return entry
end

function cacheActorCatalogEntry(cache, key, entry)
  if entry == nil or entry == false then return end
  cache[key] = entry
  local actor = tostring(entry.actorClass or "")
  local objectPath = tostring(entry.objectPath or "")
  local packagePath = tostring(entry.packagePath or "")
  cache[actorCatalogKey(actor)] = entry
  if actor:sub(-2) == "_C" then cache[actorCatalogKey(actor:gsub("_C$", ""))] = entry end
  if objectPath ~= "" then cache[actorCatalogKey(objectPath)] = entry end
  if packagePath ~= "" then cache[actorCatalogKey(packagePath)] = entry end
end

function actorCatalogLookup(actorClass)
  local cleanActor = actorSummonToken(actorClass)
  if cleanActor == "" then return nil end
  local cache = loadActorCatalogPaths()
  local key = actorCatalogKey(cleanActor)
  if cache[key] ~= nil then return cache[key] end
  local sources = {
    { path = ACTOR_CATALOG_LITE_FILE, label = "lite" },
    { path = ACTOR_CATALOG_FILE, label = "full" }
  }
  local seenSource = {}
  for _, source in ipairs(sources) do
    local sourcePath = tostring(source.path or "")
    if sourcePath ~= "" and not seenSource[sourcePath:lower()] then
      seenSource[sourcePath:lower()] = true
      local entry = actorCatalogEntryFromText(cleanActor, actorCatalogTextForFile(sourcePath))
      if entry ~= nil then
        cacheActorCatalogEntry(cache, key, entry)
        appendLog("actor catalog " .. tostring(source.label or "") .. " lookup " .. tostring(cleanActor) .. " -> " .. tostring(entry.objectPath or ""))
        return entry
      end
    end
  end
  cache[key] = false
  appendLog("actor catalog lookup miss " .. tostring(cleanActor))
  return nil
end

function actorSummonCandidates(actorClass)
  local cleanActor = actorSummonToken(actorClass)
  local candidates = {}
  local seen = {}
  local function add(value)
    value = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if value == "" or seen[value:lower()] then return end
    if value:sub(1, 6) == "/Game/" and not configBool("bridge-safety", { "AllowSummonFullAssetPaths", "allowSummonFullAssetPaths" }, false) then
      return
    end
    if value:find("'", 1, true) ~= nil and not configBool("bridge-safety", { "AllowSummonQuotedClassPaths", "allowSummonQuotedClassPaths" }, false) then
      return
    end
    seen[value:lower()] = true
    table.insert(candidates, value)
  end
  local entry = actorCatalogLookup(cleanActor)
  add(cleanActor)
  if cleanActor:sub(-2) == "_C" then add(cleanActor:gsub("_C$", "")) end
  if entry ~= nil and entry ~= false then
    if entry.actorClass ~= "" then add(entry.actorClass) end
    if entry.actorClass ~= "" and entry.actorClass:sub(-2) == "_C" then add(entry.actorClass:gsub("_C$", "")) end
    local objectPath = tostring(entry.objectPath or "")
    local packagePath = tostring(entry.packagePath or "")
    local shortFromPath = objectPath:match("([^/%.]+)_C$") or objectPath:match("([^/%.]+)$") or packagePath:match("([^/]+)$") or ""
    if shortFromPath ~= "" then add(shortFromPath) end
    if shortFromPath ~= "" and shortFromPath:sub(-2) == "_C" then add(shortFromPath:gsub("_C$", "")) end
    if configBool("bridge-safety", { "AllowSummonFullAssetPaths", "allowSummonFullAssetPaths" }, false) then
      local object = objectPath
      if object == "" then object = actorObjectPathFromPackage(packagePath, entry.actorClass ~= "" and entry.actorClass or cleanActor) end
      local assetObjectPath = object:gsub("_C$", "")
      add(assetObjectPath)
      add(object)
      add(actorObjectPathFromPackage(packagePath, entry.actorClass ~= "" and entry.actorClass or cleanActor))
      add(packagePath)
    end
  elseif cleanActor:sub(1, 6) == "/Game/" then
    local shortName = cleanActor:match("([^/%.]+)_C$") or cleanActor:match("([^/%.]+)$") or ""
    add(shortName)
    if shortName:sub(-2) == "_C" then add(shortName:gsub("_C$", "")) end
  end
  appendLog("actor summon candidates " .. tostring(cleanActor) .. " -> " .. table.concat(candidates, ","))
  return candidates
end

function actorRouteShortClass(actorClass, entry)
  local raw = tostring((entry ~= nil and entry ~= false and entry.actorClass) or actorClass or "")
  raw = raw:gsub("^BlueprintGeneratedClass'", ""):gsub("^Class'", ""):gsub("'$", "")
  raw = raw:match("%.([^%.\\/']+)$") or raw:match("([^/\\']+)$") or raw
  raw = raw:gsub("_C$", "")
  return raw
end

function actorRouteParentName(entry)
  local explicit = tostring((entry ~= nil and entry ~= false and entry.nativeParentName) or ""):lower()
  if explicit ~= "" then return explicit end
  local parent = tostring((entry ~= nil and entry ~= false and entry.parentClass) or ""):lower()
  local name = parent:match("/script/scum%.([%w_]+)") or ""
  if name == "" then name = parent:match("/script/engine%.([%w_]+)") or "" end
  name = name:gsub("u0027.*$", ""):gsub("'.*$", "")
  return name
end

function actorCatalogPlaceableReason(entry)
  if entry == nil or entry == false then return nil end
  local parentName = actorRouteParentName(entry)
  local category = tostring(entry.category or ""):lower()
  if category == "placeables" or category == "placeableactor" or
      parentName:find("placeableactor", 1, true) ~= nil or
      parentName:find("modularbasebuilding", 1, true) ~= nil then
    return "SCUM placeable/base-building создаётся через native placement recipe, а не через Summon/World.SpawnActor"
  end
  return nil
end

function actorCatalogIsMapBuildingActor(entry)
  if entry == nil or entry == false then return false end
  local parentName = actorRouteParentName(entry)
  local category = tostring(entry.category or ""):lower()
  local path = tostring(entry.objectPath or entry.packagePath or ""):lower()
  if parentName == "building" or parentName == "staticmeshactor" then return true end
  if parentName == "actor" and path:find("/models/buildings/", 1, true) ~= nil then return true end
  if category:find("building", 1, true) ~= nil or category:find("house", 1, true) ~= nil then return true end
  return false
end

function actorCatalogPlacementRouteHint(entry)
  if entry == nil or entry == false then return "unknown" end
  local placeableReason = actorCatalogPlaceableReason(entry)
  if placeableReason ~= nil then return placeableReason end
  if actorCatalogIsMapBuildingActor(entry) then
    return "SCUM map-building actor находится в cooked streamed level; Summon даёт временный server actor/ghost без world persistence. Нужен map/streamed-level PAK или source/native world registry route."
  end
  return "нужен родной persistent spawn route для этого actor-типа"
end

function summonTraderRuntimeScanAllowed()
  return configBool("bridge-safety", { "SummonEnableRuntimeScan", "summonEnableRuntimeScan" }, false) == true or
    configBool("bridge-safety", { "AllowSummonTraderRuntimeScan", "allowSummonTraderRuntimeScan", "AllowSummonTradePostRuntimeScan", "allowSummonTradePostRuntimeScan" }, false) == true or
    configBool("bridge-safety", { "AllowProbeRuntimeObjectScan", "allowProbeRuntimeObjectScan" }, false) == true
end

function spawnActorPreferPlainSummon()
  return configBool("bridge-safety", {
    "SpawnActorPreferPlainSummon",
    "spawnActorPreferPlainSummon",
    "WebPanelSpawnActorUsesPlainSummon",
    "webPanelSpawnActorUsesPlainSummon"
  }, true) == true
end

function actorCatalogNonActorReason(entry)
  if entry == nil or entry == false then return nil end
  local placeableReason = actorCatalogPlaceableReason(entry)
  if placeableReason ~= nil then return placeableReason end
  if entry.summonableActor == true then return nil end
  if entry.summonableActor == false then
    local note = tostring(entry.summonNote or "")
    if note ~= "" then return note end
    return "класс не наследуется от AActor"
  end
  local parentName = actorRouteParentName(entry)
  local category = tostring(entry.category or ""):lower()
  local nonActorParents = {
    admincommand = true,
    itemspawnerpreset = true,
    itemspawnerpreset2 = true,
    traderservice = true,
    itementitysetup = true,
    clothesitementitysetup = true,
    fooditementitysetup = true,
    cookedfooditementitysetup = true,
    weaponitementitysetup = true,
    ammunitionitementitysetup = true,
    entitysetup = true,
    dataasset = true,
    userwidget = true,
    blueprintfunctionlibrary = true
  }
  if nonActorParents[parentName] then return "класс каталога не является AActor: " .. tostring(parentName) end
  if parentName:find("component", 1, true) ~= nil then return "компоненты нельзя создавать через Summon: " .. tostring(parentName) end
  if parentName:find("preset", 1, true) ~= nil then return "пресеты спавна не являются Actor: " .. tostring(parentName) end
  if parentName:find("service", 1, true) ~= nil then return "сервисы торговцев не являются Actor: " .. tostring(parentName) end
  if parentName:find("sequence", 1, true) ~= nil then return "последовательности/анимации не являются Actor: " .. tostring(parentName) end
  if parentName:find("description", 1, true) ~= nil then return "описания/данные не являются Actor: " .. tostring(parentName) end
  if category == "lwobjectsetup" or category == "traderservice" or category == "itemspawnerpreset" then
    return "категория каталога не предназначена для Summon: " .. tostring(entry.category or "")
  end
  return nil
end

function nativeAdminSpawnCommandForActor(actorClass)
  local cleanActor = actorSummonToken(actorClass)
  if cleanActor == "" then return "", "" end
  local entry = actorCatalogLookup(cleanActor)
  local shortClass = actorRouteShortClass(cleanActor, entry)
  local key = tostring(shortClass or ""):lower()
  local parentName = actorRouteParentName(entry)
  if key == "bp_razor" or parentName == "razor" then
    return "SpawnRazor", "native-admin:SpawnRazor"
  end
  if key == "bp_brenner" or parentName == "brenner" then
    return "SpawnBrenner", "native-admin:SpawnBrenner"
  end
  return "", ""
end

function preloadActorClassCandidate(candidate)
  local attempts = {}
  local objectPath = tostring(candidate or "")
  objectPath = objectPath:gsub("^BlueprintGeneratedClass'", ""):gsub("^Class'", ""):gsub("'$", "")
  local packagePath = actorPackagePathFromObject(objectPath)
  if packagePath ~= "" and packagePath:sub(1, 6) == "/Game/" then
    local okLoad, loaded = pcall(function() return LoadAsset(packagePath) end)
    table.insert(attempts, "LoadAsset(" .. packagePath .. ")=" .. (okLoad and (isValidObject(loaded) and "ok" or "nil") or tostring(loaded)))
  end
  if objectPath ~= "" and objectPath:sub(1, 6) == "/Game/" then
    local okFind, found = pcall(function() return StaticFindObject(objectPath) end)
    table.insert(attempts, "StaticFindObject(" .. objectPath .. ")=" .. (okFind and (isValidObject(found) and "ok" or "nil") or tostring(found)))
  end
  return attempts
end

function preloadActorCatalogForSummon(actorClass)
  local attempts = {}
  local cleanActor = actorSummonToken(actorClass)
  local entry = actorCatalogLookup(cleanActor)
  if entry == nil or entry == false then return attempts end
  local objectPath = tostring(entry.objectPath or "")
  local packagePath = tostring(entry.packagePath or "")
  local className = tostring(entry.actorClass or "")
  if packagePath == "" then packagePath = actorPackagePathFromObject(objectPath) end
  if objectPath == "" then objectPath = actorObjectPathFromPackage(packagePath, className ~= "" and className or cleanActor) end
  local assetPath = objectPath:gsub("_C$", "")
  local loadCandidates = { packagePath, assetPath }
  local seenLoad = {}
  for _, candidate in ipairs(loadCandidates) do
    candidate = tostring(candidate or "")
    if candidate ~= "" and candidate:sub(1, 6) == "/Game/" and not seenLoad[candidate:lower()] then
      seenLoad[candidate:lower()] = true
      local okLoad, loaded = pcall(function() return LoadAsset(candidate) end)
      table.insert(attempts, "catalog LoadAsset(" .. candidate .. ")=" .. (okLoad and (isValidObject(loaded) and "ok" or "nil") or tostring(loaded)))
    end
  end
  local findCandidates = { objectPath, "BlueprintGeneratedClass'" .. objectPath .. "'", "Class'" .. objectPath .. "'" }
  local seenFind = {}
  for _, candidate in ipairs(findCandidates) do
    candidate = tostring(candidate or "")
    if candidate ~= "" and not seenFind[candidate:lower()] then
      seenFind[candidate:lower()] = true
      local okFind, found = pcall(function() return StaticFindObject(candidate) end)
      table.insert(attempts, "catalog StaticFindObject(" .. candidate .. ")=" .. (okFind and (isValidObject(found) and "ok" or "nil") or tostring(found)))
    end
  end
  return attempts
end
loadedActorClassCache = {}

function actorClassLoadCandidatesForSpawn(actorClass)
  local cleanActor = actorSummonToken(actorClass)
  local classPaths = {}
  local assetPaths = {}
  local seenClass = {}
  local seenAsset = {}
  local function addClass(value) pushUnique(classPaths, seenClass, value) end
  local function addAsset(value) pushUnique(assetPaths, seenAsset, value) end
  local function addObjectPath(objectPath)
    objectPath = tostring(objectPath or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if objectPath == "" then return end
    local hasObjectName = objectPath:find("%.") ~= nil
    local paths, assets = itemClassLoadCandidates(objectPath)
    for _, value in ipairs(paths or {}) do addClass(value) end
    for _, value in ipairs(assets or {}) do addAsset(value) end
    if objectPath:sub(1, 6) == "/Game/" and hasObjectName then
      addClass("BlueprintGeneratedClass'" .. objectPath .. "'")
      addClass("Class'" .. objectPath .. "'")
      addClass("BlueprintGeneratedClass " .. objectPath)
      addAsset(objectPath)
      addAsset(objectPath:gsub("_C$", ""))
    end
  end

  local entry = actorCatalogLookup(cleanActor)
  if cleanActor == "StaticMeshActor" or cleanActor == "/Script/Engine.StaticMeshActor" then
    addClass("/Script/Engine.StaticMeshActor")
    addClass("Class /Script/Engine.StaticMeshActor")
    addClass("UClass /Script/Engine.StaticMeshActor")
    addClass("StaticMeshActor")
  end
  if entry ~= nil and entry ~= false then
    addObjectPath(entry.objectPath)
    addObjectPath(actorObjectPathFromPackage(entry.packagePath, entry.actorClass ~= "" and entry.actorClass or cleanActor))
    addObjectPath(entry.packagePath)
  end
  addObjectPath(cleanActor)
  if cleanActor:sub(-2) ~= "_C" then addClass(cleanActor .. "_C") end
  return classPaths, assetPaths
end

function loadActorClassForSpawn(actorClass)
  local cleanActor = actorSummonToken(actorClass)
  local cacheKey = cleanActor:lower()
  local cached = loadedActorClassCache[cacheKey]
  if cached ~= nil and isValidObject(cached) then return cached, "cached actor class" end

  local classPaths, assetPaths = actorClassLoadCandidatesForSpawn(cleanActor)
  local attempts = {}
  local found = nil
  local function loadedActorClassObject(value)
    if value == nil or not isValidObject(value) then return nil end
    local generated = firstProp(value, { "GeneratedClass", "_GeneratedClass" })
    if generated ~= nil and isValidObject(generated) then return generated end
    return value
  end
  local function remember(result, route)
    result = loadedActorClassObject(result)
    if result ~= nil and isValidObject(result) and cacheKey ~= "" then loadedActorClassCache[cacheKey] = result end
    return result, route, attempts
  end

  for _, classPath in ipairs(classPaths or {}) do
    local okFind, result = pcall(function() return StaticFindObject(classPath) end)
    table.insert(attempts, "StaticFindObject(" .. tostring(classPath) .. ")=" .. (okFind and (isValidObject(result) and "ok" or "nil") or tostring(result)))
    if okFind and result ~= nil and isValidObject(result) then return remember(result, "StaticFindObject:" .. tostring(classPath)) end
  end

  for _, assetPath in ipairs(assetPaths or {}) do
    local okLoad, result = pcall(function() return LoadAsset(assetPath) end)
    table.insert(attempts, "LoadAsset(" .. tostring(assetPath) .. ")=" .. (okLoad and (isValidObject(result) and "ok" or "nil") or tostring(result)))
    if okLoad and result ~= nil and isValidObject(result) then
      found = loadedActorClassObject(result)
      if found ~= nil and isValidObject(found) then
        table.insert(attempts, "LoadAsset.generatedClass=" .. objectFullName(found))
      end
    end
  end

  for _, classPath in ipairs(classPaths or {}) do
    local okFind, result = pcall(function() return StaticFindObject(classPath) end)
    table.insert(attempts, "post StaticFindObject(" .. tostring(classPath) .. ")=" .. (okFind and (isValidObject(result) and "ok" or "nil") or tostring(result)))
    if okFind and result ~= nil and isValidObject(result) then return remember(result, "LoadAsset+StaticFindObject:" .. tostring(classPath)) end
  end

  if found ~= nil and isValidObject(found) then return remember(found, "LoadAsset object fallback") end
  return nil, "класс актора не загрузился", attempts
end

function spawnActorDirectForInfo(info, actorClass, entry)
  local actorClassObject, loadRoute, loadAttempts = loadActorClassForSpawn(actorClass)
  if actorClassObject == nil or not isValidObject(actorClassObject) then
    return false, tostring(loadRoute or "класс актора не найден"), loadAttempts or {}, nil
  end
  local world = worldFor(info)
  if world == nil or not isValidObject(world) then return false, "world unresolved", loadAttempts or {}, nil end
  local loc = actorPlacementLocation(info, entry or actorCatalogLookup(actorClass))
  local rot = { Pitch = 0, Yaw = rotationYawOf((info or {}).pc) or rotationYawOf((info or {}).pawn) or 0, Roll = 0 }
  local attempts = loadAttempts or {}
  local okCall, actor = safeCall(world, "SpawnActor", actorClassObject, loc, rot)
  table.insert(attempts, "world.SpawnActor(3)=" .. (okCall and (isValidObject(actor) and "ok" or "nil") or tostring(actor)))
  if okCall and actor ~= nil and isValidObject(actor) then return true, "world.SpawnActor:" .. tostring(loadRoute or ""), attempts, actor end
  okCall, actor = safeCall(world, "SpawnActor", actorClassObject, loc)
  table.insert(attempts, "world.SpawnActor(2)=" .. (okCall and (isValidObject(actor) and "ok" or "nil") or tostring(actor)))
  if okCall and actor ~= nil and isValidObject(actor) then return true, "world.SpawnActor:" .. tostring(loadRoute or ""), attempts, actor end
  return false, "World.SpawnActor не создал актор", attempts, nil
end

PERSISTENT_ACTOR_RESTORED_SITES = PERSISTENT_ACTOR_RESTORED_SITES or {}
PERSISTENT_ACTOR_RESTORE_RETRY = PERSISTENT_ACTOR_RESTORE_RETRY or {
  startedAt = os.time(),
  attempts = 0,
  lastAt = 0,
  done = false
}

function persistentActorCatalogPath(entry, actorClass)
  if type(entry) == "table" then
    for _, key in ipairs({ "objectPath", "classPath", "assetPath", "path", "generatedClassPath", "blueprintClassPath" }) do
      local value = tostring(entry[key] or "")
      if value ~= "" then return value end
    end
  end
  local cleanActor = actorSummonToken(actorClass)
  if cleanActor == "" then return "" end
  return cleanActor
end

function persistentActorSiteId(actorClass, info, options)
  local explicit = tostring((options or {}).siteId or (options or {}).requestId or "")
  if explicit ~= "" then return explicit end
  local steam = tostring((info or {}).steam or "")
  local clockPart = tostring(math.floor((os.clock() or 0) * 1000000))
  return "actor-" .. actorSummonToken(actorClass) .. "-" .. tostring(os.time()) .. "-" .. clockPart .. (steam ~= "" and ("-" .. steam) or "")
end

function persistentActorPayload(site)
  return '{"siteId":' .. js(site.siteId or "") ..
    ',"actorClass":' .. js(site.actorClass or "") ..
    ',"catalogPath":' .. js(site.catalogPath or "") ..
    ',"visualProxy":' .. ((site.visualProxy == true) and "true" or "false") ..
    ',"staticMeshVisualProxy":' .. ((site.visualProxy == true) and "true" or "false") ..
    ',"originalActorClass":' .. js(site.originalActorClass or "") ..
    ',"sourceActorClass":' .. js(site.sourceActorClass or "") ..
    ',"sourceActorFullName":' .. js(site.sourceActorFullName or "") ..
    ',"sourceObjectPath":' .. js(site.sourceObjectPath or "") ..
    ',"sourceComponentFullName":' .. js(site.sourceComponentFullName or "") ..
    ',"sourceMeshFullName":' .. js(site.sourceMeshFullName or "") ..
    ',"x":' .. tostring(tonumber(site.x) or 0) ..
    ',"y":' .. tostring(tonumber(site.y) or 0) ..
    ',"z":' .. tostring(tonumber(site.z) or 0) ..
    ',"yaw":' .. tostring(tonumber(site.yaw) or 0) ..
    ',"replay":' .. ((site.replay == true) and "true" or "false") ..
    ',"source":' .. js(site.source or "web-panel-server-summon") .. '}'
end

function persistentMeshPackagePath(meshFullName)
  local value = tostring(meshFullName or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if value == "" then return "" end
  value = value:gsub("^StaticMesh%s+", "")
  value = value:gsub("^Package%s+", "")
  value = value:gsub("^Object%s+", "")
  value = value:gsub("^StaticMesh'", ""):gsub("'$", "")
  local path = value:match("(/Game/.+)$") or value
  local packagePath = path
  local dot = packagePath:match("^(.-)%.[^%.:/\\]+$")
  if dot ~= nil and dot ~= "" then packagePath = dot end
  return packagePath
end

function persistentStaticMeshObjectPath(meshFullName)
  local value = tostring(meshFullName or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if value == "" then return "" end
  value = value:gsub("^StaticMesh%s+", "")
  value = value:gsub("^Package%s+", "")
  value = value:gsub("^Object%s+", "")
  value = value:gsub("^StaticMesh'", ""):gsub("'$", "")
  local path = value:match("(/Game/.+)$") or value
  if path == "" then return "" end
  if path:find("%.[^%.:/\\]+$") then return path end
  local leaf = path:match("([^/\\]+)$") or ""
  if leaf == "" then return path end
  return path .. "." .. leaf
end

function preloadPersistentVisualProxyMesh(site, attempts)
  if site == nil or site.visualProxy ~= true then return end
  local meshFullName = tostring(site.sourceMeshFullName or "")
  if meshFullName == "" then return end
  local packagePath = persistentMeshPackagePath(meshFullName)
  if packagePath == "" then return end
  local okLoad, loaded = pcall(function() return LoadAsset(packagePath) end)
  local loadedFull = okLoad and isValidObject(loaded) and objectFullName(loaded) or ""
  table.insert(attempts, "visualMesh.LoadAsset(" .. packagePath .. ")=" .. (okLoad and (loadedFull ~= "" and ("ok:" .. loadedFull) or "nil") or tostring(loaded)))
  local objectPath = persistentStaticMeshObjectPath(meshFullName)
  local okFind, found = pcall(function() return StaticFindObject("StaticMesh " .. objectPath) end)
  table.insert(attempts, "visualMesh.StaticFindObject(" .. objectPath .. ")=" .. (okFind and (isValidObject(found) and ("ok:" .. objectFullName(found)) or "nil") or tostring(found)))
end

function appendPersistentActorSite(site, nativeResult)
  if site == nil then return false end
  local nativeMesh = extractStringAny(nativeResult or "", { "sourceMeshFullName", "meshFullName", "visualMeshFullName" }) or tostring(site.sourceMeshFullName or "")
  local record = '{"utc":' .. js(nowUtc()) ..
    ',"active":true' ..
    ',"siteId":' .. js(site.siteId or "") ..
    ',"actorClass":' .. js(site.actorClass or "") ..
    ',"catalogPath":' .. js(site.catalogPath or "") ..
    ',"visualProxy":' .. ((site.visualProxy == true) and "true" or "false") ..
    ',"originalActorClass":' .. js(site.originalActorClass or "") ..
    ',"sourceActorClass":' .. js(site.sourceActorClass or "") ..
    ',"sourceActorFullName":' .. js(site.sourceActorFullName or "") ..
    ',"sourceObjectPath":' .. js(site.sourceObjectPath or "") ..
    ',"sourceComponentFullName":' .. js(site.sourceComponentFullName or "") ..
    ',"sourceMeshFullName":' .. js(nativeMesh or "") ..
    ',"x":' .. tostring(tonumber(site.x) or 0) ..
    ',"y":' .. tostring(tonumber(site.y) or 0) ..
    ',"z":' .. tostring(tonumber(site.z) or 0) ..
    ',"yaw":' .. tostring(tonumber(site.yaw) or 0) ..
    ',"source":' .. js(site.source or "web-panel-server-summon") ..
    ',"steamId":' .. js(site.steamId or "") ..
    ',"name":' .. js(site.name or "") ..
    ',"actorFullName":' .. js(extractString(nativeResult or "", "actorFullName") or "") ..
    ',"resolvedClass":' .. js(extractString(nativeResult or "", "resolvedClass") or "") ..
    ',"nativeRoute":"native-persistent-server-spawn"}'
  return appendJsonArray(PERSISTENT_ACTOR_SITES_FILE, record, 2 * 1024 * 1024)
end

function persistentActorAlreadyLoaded(actorFullName)
  local full = tostring(actorFullName or "")
  if full == "" then return false, "no saved actorFullName" end
  local candidates = { full }
  local objectPath = full:match("%s(/Game/.+)$") or full:match("(/Game/.+)$")
  if objectPath ~= nil and objectPath ~= "" and objectPath ~= full then table.insert(candidates, objectPath) end
  for _, candidate in ipairs(candidates) do
    local okFind, found = pcall(function() return StaticFindObject(candidate) end)
    if okFind and found ~= nil and isValidObject(found) then
      return true, objectFullName(found)
    end
  end
  return false, "not loaded"
end

function persistentActorRows()
  local candidates = {
    PERSISTENT_ACTOR_SITES_FILE,
    ".\\ScumNeDjin\\state\\persistent-actors.json"
  }
  local seen = {}
  for _, path in ipairs(candidates) do
    local cleanPath = tostring(path or "")
    local key = cleanPath:lower()
    if cleanPath ~= "" and not seen[key] then
      seen[key] = true
      local text = normalizeJsonArrayText(readAll(cleanPath) or "[]", 2 * 1024 * 1024)
      local rows = {}
      for object in text:gmatch("%b{}") do
        if stateArrayRecordLooksSafe(object) then table.insert(rows, object) end
      end
      if #rows > 0 then
        return rows, cleanPath, #text
      end
    end
  end
  return {}, PERSISTENT_ACTOR_SITES_FILE, 0
end

function nativePersistentActorSpawnForInfo(actorClass, info, entry, options)
  options = options or {}
  local cleanActor = actorSummonToken(actorClass)
  if cleanActor == "" then return false, "Класс актора не указан.", "{}" end
  local attempts = {}
  local actorClassObject, loadRoute, loadAttempts = loadActorClassForSpawn(cleanActor)
  for _, attempt in ipairs(loadAttempts or {}) do table.insert(attempts, "preload." .. tostring(attempt)) end
  local allowNativeClassResolve = options.allowNativeClassResolve == true or options.visualProxy == true
  if (actorClassObject == nil or not isValidObject(actorClassObject)) and allowNativeClassResolve ~= true then
    local data = '{"actorClass":' .. js(cleanActor) ..
      ',"route":"native-persistent-server-spawn"' ..
      ',"stage":"preload-class"' ..
      ',"detail":' .. js(loadRoute or "") ..
      ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Persistent server-spawn не создан: класс актора не загрузился. " .. tostring(loadRoute or ""), data)
    return false, "Persistent server-spawn не создан: класс актора не загрузился. " .. tostring(loadRoute or ""), data
  end

  local loc = options.location or actorPlacementLocation(info, entry)
  local yaw = tonumber(options.yaw) or rotationYawOf((info or {}).pc) or rotationYawOf((info or {}).pawn) or 0
  local site = {
    siteId = persistentActorSiteId(cleanActor, info, options),
    actorClass = cleanActor,
    catalogPath = persistentActorCatalogPath(entry, cleanActor),
    x = tonumber(loc.X or loc.x) or 0,
    y = tonumber(loc.Y or loc.y) or 0,
    z = tonumber(loc.Z or loc.z) or 0,
    yaw = yaw,
    source = tostring(options.source or "web-panel-server-summon"),
    steamId = tostring((info or {}).steam or ""),
      name = tostring((info or {}).name or "")
  }
  site.catalogPath = tostring(options.catalogPath or "") ~= "" and tostring(options.catalogPath) or site.catalogPath
  site.visualProxy = options.visualProxy == true
  site.originalActorClass = tostring(options.originalActorClass or "")
  site.sourceActorClass = tostring(options.sourceActorClass or "")
  site.sourceActorFullName = tostring(options.sourceActorFullName or "")
  site.sourceObjectPath = tostring(options.sourceObjectPath or "")
  site.sourceComponentFullName = tostring(options.sourceComponentFullName or "")
  site.sourceMeshFullName = tostring(options.sourceMeshFullName or "")
  preloadPersistentVisualProxyMesh(site, attempts)
  local payload = persistentActorPayload(site)
  local timeoutMs = tonumber(options.timeoutMs) or 12000
  table.insert(attempts, "preloadRoute=" .. tostring(loadRoute or ""))
  table.insert(attempts, "preloadedClass=" .. tostring(actorClassObject ~= nil and objectFullName(actorClassObject) or "native-resolve"))
  table.insert(attempts, "native payload=" .. payload)
  local nativeOk, nativeMessage, nativeResult = nativeTraderCommand("native_actor_spawn_persistent", payload, timeoutMs, tostring(options.requestId or site.siteId))
  local okPersist = false
  if nativeOk and options.persist ~= false and options.replay ~= true then
    okPersist = appendPersistentActorSite(site, nativeResult)
  end
  local data = '{"actorClass":' .. js(cleanActor) ..
    ',"route":"native-persistent-server-spawn"' ..
    ',"siteId":' .. js(site.siteId) ..
    ',"catalogPath":' .. js(site.catalogPath) ..
    ',"visualProxy":' .. ((site.visualProxy == true) and "true" or "false") ..
    ',"originalActorClass":' .. js(site.originalActorClass or "") ..
    ',"sourceActorClass":' .. js(site.sourceActorClass or "") ..
    ',"sourceActorFullName":' .. js(site.sourceActorFullName or "") ..
    ',"sourceObjectPath":' .. js(site.sourceObjectPath or "") ..
    ',"sourceComponentFullName":' .. js(site.sourceComponentFullName or "") ..
    ',"sourceMeshFullName":' .. js(site.sourceMeshFullName or "") ..
    ',"x":' .. tostring(site.x) ..
    ',"y":' .. tostring(site.y) ..
    ',"z":' .. tostring(site.z) ..
    ',"yaw":' .. tostring(site.yaw) ..
    ',"preloadRoute":' .. js(loadRoute or "") ..
    ',"nativeOk":' .. (nativeOk and "true" or "false") ..
    ',"persisted":' .. (okPersist and "true" or "false") ..
    ',"nativeMessage":' .. js(nativeMessage or "") ..
    ',"nativeResult":' .. js(nativeResult or "") ..
    ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
  appendActionEvent("spawn_actor", nativeOk, info,
    nativeOk and ("Серверный persistent actor создан: " .. cleanActor) or ("Persistent server-spawn не создал actor: " .. tostring(nativeMessage or "")),
    data)
  if nativeOk then
    return true, "Серверный persistent actor создан: " .. cleanActor, data
  end
  return false, "Persistent server-spawn не создал actor: " .. tostring(nativeMessage or ""), data
end

function restorePersistentActorSites()
  if configBool("bridge-safety", { "EnablePersistentActorReplay", "enablePersistentActorReplay" }, true) ~= true then
    return true, "persistent actor replay disabled"
  end
  local rows, rowsPath, rowsBytes = persistentActorRows()
  local restored, total = 0, 0
  local attempts = { "rows=" .. tostring(#rows) .. " path=" .. tostring(rowsPath or "") .. " bytes=" .. tostring(rowsBytes or 0) }
  for _, row in ipairs(rows) do
    local active = extractBool(row, "active", true)
    local siteId = extractStringAny(row, { "siteId", "idempotencyKey", "persistentId" }) or ""
    local actorClass = actorSummonToken(extractStringAny(row, { "actorClass", "className", "actor" }) or "")
    local catalogPath = extractStringAny(row, { "catalogPath", "objectPath", "assetPath", "classPath" }) or actorClass
    local actorFullName = extractStringAny(row, { "actorFullName", "spawnedActor", "fullName" }) or ""
    local visualProxy = extractBoolAny(row, { "visualProxy", "staticMeshVisualProxy", "useStaticMeshProxy" }, false) == true
    local originalActorClass = extractStringAny(row, { "originalActorClass", "targetActorClass" }) or ""
    local sourceActorClass = extractStringAny(row, { "sourceActorClass" }) or ""
    local sourceActorFullName = extractStringAny(row, { "sourceActorFullName", "targetActorFullName" }) or ""
    local sourceObjectPath = extractStringAny(row, { "sourceObjectPath", "targetObjectPath" }) or ""
    local sourceComponentFullName = extractStringAny(row, { "sourceComponentFullName", "targetComponentFullName", "componentFullName" }) or ""
    local sourceMeshFullName = extractStringAny(row, { "sourceMeshFullName", "meshFullName", "staticMeshFullName" }) or ""
    local x = extractNumberAny(row, { "x", "X", "worldX", "WorldX" }, nil)
    local y = extractNumberAny(row, { "y", "Y", "worldY", "WorldY" }, nil)
    local z = extractNumberAny(row, { "z", "Z", "worldZ", "WorldZ" }, nil)
    local yaw = extractNumberAny(row, { "yaw", "Yaw", "rotationYaw", "RotationYaw" }, 0) or 0
    if active ~= false and siteId ~= "" and actorClass ~= "" and x ~= nil and y ~= nil and z ~= nil and PERSISTENT_ACTOR_RESTORED_SITES[siteId] ~= true then
      total = total + 1
      local alreadyLoaded, loadedDetail = persistentActorAlreadyLoaded(actorFullName)
      if alreadyLoaded then
        PERSISTENT_ACTOR_RESTORED_SITES[siteId] = true
        restored = restored + 1
        table.insert(attempts, siteId .. "=already-loaded:" .. tostring(loadedDetail or ""))
      else
      local entry = actorCatalogLookup(actorClass)
      local actorClassObject, loadRoute, loadAttempts = loadActorClassForSpawn(actorClass)
      for _, attempt in ipairs(loadAttempts or {}) do
        if #attempts < 40 then table.insert(attempts, siteId .. ".preload." .. tostring(attempt)) end
      end
      if actorClassObject == nil or not isValidObject(actorClassObject) then
        table.insert(attempts, siteId .. " preload failed: " .. tostring(loadRoute or ""))
      else
        local replaySite = {
          siteId = siteId,
          actorClass = actorClass,
          catalogPath = catalogPath ~= "" and catalogPath or persistentActorCatalogPath(entry, actorClass),
          visualProxy = visualProxy,
          originalActorClass = originalActorClass,
          sourceActorClass = sourceActorClass,
          sourceActorFullName = sourceActorFullName,
          sourceObjectPath = sourceObjectPath,
          sourceComponentFullName = sourceComponentFullName,
          sourceMeshFullName = sourceMeshFullName,
          x = x,
          y = y,
          z = z,
          yaw = yaw,
          replay = true,
          source = "persistent-actor-replay"
        }
        preloadPersistentVisualProxyMesh(replaySite, attempts)
        local payload = persistentActorPayload(replaySite)
        local okSpawn, message, result = nativeTraderCommand("native_actor_spawn_persistent", payload, 25000, "restore-" .. siteId)
        table.insert(attempts, siteId .. "=" .. (okSpawn and "ok" or tostring(message)))
        if okSpawn then
          restored = restored + 1
          PERSISTENT_ACTOR_RESTORED_SITES[siteId] = true
        elseif #attempts < 40 then
          table.insert(attempts, siteId .. ".result=" .. tostring(result or ""))
        end
      end
      end
    end
  end
  if total > 0 then
    appendActionEvent("persistent_actor_restore", restored == total, nil,
      "Persistent actor restore: " .. tostring(restored) .. "/" .. tostring(total),
      '{"restored":' .. tostring(restored) ..
        ',"total":' .. tostring(total) ..
        ',"file":' .. js(PERSISTENT_ACTOR_SITES_FILE) ..
        ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
  end
  return restored == total, "restored " .. tostring(restored) .. "/" .. tostring(total)
end

function schedulePersistentActorRestore()
  if configBool("bridge-safety", { "EnablePersistentActorReplay", "enablePersistentActorReplay" }, true) ~= true then return end
  local firstDelay = math.max(15000, configNumber("bridge-safety", { "PersistentActorReplayInitialDelayMs", "persistentActorReplayInitialDelayMs" }, 90000))
  local secondDelay = math.max(firstDelay + 15000, configNumber("bridge-safety", { "PersistentActorReplaySecondDelayMs", "persistentActorReplaySecondDelayMs" }, 180000))
  deferAsync(firstDelay, function()
    restorePersistentActorSites()
  end)
  deferAsync(secondDelay, function()
    restorePersistentActorSites()
  end)
end

function persistentActorRestoreRetryTick()
  if configBool("bridge-safety", { "EnablePersistentActorReplay", "enablePersistentActorReplay" }, true) ~= true then return end
  local state = PERSISTENT_ACTOR_RESTORE_RETRY or {}
  if state.done == true then return end
  local now = os.time()
  local initialSeconds = math.max(15, math.floor((configNumber("bridge-safety", { "PersistentActorReplayInitialDelayMs", "persistentActorReplayInitialDelayMs" }, 90000) or 90000) / 1000))
  local intervalSeconds = math.max(15, math.floor((configNumber("bridge-safety", { "PersistentActorReplayIntervalMs", "persistentActorReplayIntervalMs" }, 45000) or 45000) / 1000))
  local maxAttempts = math.max(1, math.min(math.floor(configNumber("bridge-safety", { "PersistentActorReplayMaxAttempts", "persistentActorReplayMaxAttempts" }, 10) or 10), 30))
  state.startedAt = tonumber(state.startedAt or now) or now
  state.attempts = tonumber(state.attempts or 0) or 0
  state.lastAt = tonumber(state.lastAt or 0) or 0
  if (now - state.startedAt) < initialSeconds then
    PERSISTENT_ACTOR_RESTORE_RETRY = state
    return
  end
  if state.lastAt > 0 and (now - state.lastAt) < intervalSeconds then
    PERSISTENT_ACTOR_RESTORE_RETRY = state
    return
  end
  if state.attempts >= maxAttempts then
    if state.reportedMax ~= true then
      state.reportedMax = true
      appendLog("persistent actor restore retry exhausted attempts=" .. tostring(state.attempts))
    end
    PERSISTENT_ACTOR_RESTORE_RETRY = state
    return
  end
  state.attempts = state.attempts + 1
  state.lastAt = now
  PERSISTENT_ACTOR_RESTORE_RETRY = state
  local okRestore, message = restorePersistentActorSites()
  appendLog("persistent actor restore retry " .. tostring(state.attempts) .. "/" .. tostring(maxAttempts) .. ": " .. tostring(message or ""))
  if okRestore then
    state.done = true
    PERSISTENT_ACTOR_RESTORE_RETRY = state
  end
end

EDITOR_ACTOR_RESTORED_EDITS = EDITOR_ACTOR_RESTORED_EDITS or {}

function jsonObjectFieldText(text, fieldName)
  local source = tostring(text or "")
  local field = tostring(fieldName or "")
  if source == "" or field == "" then return nil end
  local markerStart, markerEnd = source:find('"' .. field .. '"%s*:%s*{')
  if markerStart == nil then return nil end
  local brace = source:find("{", markerEnd - 1, true)
  if brace == nil then return nil end
  local depth = 0
  for index = brace, #source do
    local ch = source:sub(index, index)
    if ch == "{" then
      depth = depth + 1
    elseif ch == "}" then
      depth = depth - 1
      if depth == 0 then return source:sub(brace, index) end
    end
  end
  return nil
end

function vectorFromNativeResult(nativeResult, preferredFields)
  for _, field in ipairs(preferredFields or {}) do
    local objectText = jsonObjectFieldText(nativeResult, field)
    if objectText ~= nil then
      local x = extractNumberAny(objectText, { "x", "X" }, nil)
      local y = extractNumberAny(objectText, { "y", "Y" }, nil)
      local z = extractNumberAny(objectText, { "z", "Z" }, nil)
      if x ~= nil and y ~= nil and z ~= nil then return x, y, z, field end
    end
  end
  return nil, nil, nil, ""
end

function rotatorFromNativeResult(nativeResult, preferredFields)
  for _, field in ipairs(preferredFields or {}) do
    local objectText = jsonObjectFieldText(nativeResult, field)
    if objectText ~= nil then
      local pitch = extractNumberAny(objectText, { "pitch", "Pitch" }, 0) or 0
      local yaw = extractNumberAny(objectText, { "yaw", "Yaw" }, 0) or 0
      local roll = extractNumberAny(objectText, { "roll", "Roll" }, 0) or 0
      return pitch, yaw, roll, field
    end
  end
  return 0, 0, 0, ""
end

function hektorStagedArrayObjects(text, fieldName)
  local source = tostring(text or "")
  local field = tostring(fieldName or "")
  local objects = {}
  if source == "" or field == "" then return objects end
  local markerStart = source:find('"' .. field .. '"%s*:%s*%[')
  if markerStart == nil then return objects end
  local bracket = source:find("[", markerStart, true)
  if bracket == nil then return objects end
  local inString, escaped = false, false
  local arrayDepth, objectDepth = 1, 0
  local objectStart = nil
  local index = bracket + 1
  while index <= #source do
    local ch = source:sub(index, index)
    if inString then
      if escaped then
        escaped = false
      elseif ch == "\\" then
        escaped = true
      elseif ch == '"' then
        inString = false
      end
    else
      if ch == '"' then
        inString = true
      elseif objectDepth > 0 then
        if ch == "{" then
          objectDepth = objectDepth + 1
        elseif ch == "}" then
          objectDepth = objectDepth - 1
          if objectDepth == 0 and objectStart ~= nil then
            table.insert(objects, source:sub(objectStart, index))
            objectStart = nil
          end
        end
      elseif ch == "[" then
        arrayDepth = arrayDepth + 1
      elseif ch == "]" then
        arrayDepth = arrayDepth - 1
        if arrayDepth <= 0 then break end
      elseif ch == "{" and arrayDepth == 1 then
        objectStart = index
        objectDepth = 1
      end
    end
    index = index + 1
  end
  return objects
end

function hektorStagedStableId(value)
  local textValue = tostring(value or "")
  local hash = 5381
  for index = 1, #textValue do
    hash = ((hash * 33) + string.byte(textValue, index)) % 2147483647
  end
  return tostring(math.floor(hash))
end

function hektorStagedObjectField(text, fieldName)
  local source = tostring(text or "")
  local field = tostring(fieldName or "")
  local marker = source:find('"' .. field .. '"%s*:%s*{')
  if marker == nil then return "" end
  local brace = source:find("{", marker, true)
  if brace == nil then return "" end
  local inString = false
  local escaped = false
  local depth = 0
  for index = brace, #source do
    local ch = source:sub(index, index)
    if inString then
      if escaped then
        escaped = false
      elseif ch == "\\" then
        escaped = true
      elseif ch == '"' then
        inString = false
      end
    else
      if ch == '"' then
        inString = true
      elseif ch == "{" then
        depth = depth + 1
      elseif ch == "}" then
        depth = depth - 1
        if depth == 0 then return source:sub(brace, index) end
      end
    end
  end
  return ""
end

function hektorStagedOverlayItemKey(item)
  local operation = tostring(extractString(item, "operation") or extractString(item, "op") or ""):lower()
  local actor = tostring(extractString(item, "actorFullName") or extractString(item, "targetActorFullName") or extractString(item, "sourceActorFullName") or "")
  local mesh = tostring(extractString(item, "sourceMeshFullName") or extractString(item, "meshFullName") or extractString(item, "staticMeshFullName") or "")
  local loc = hektorStagedObjectField(item, "absoluteAfterLocation")
  if loc == "" then loc = hektorStagedObjectField(item, "afterLocation") end
  local rot = hektorStagedObjectField(item, "afterRotation")
  if operation == "move" or operation == "nudge" then
    return "move:" .. actor
  end
  if operation == "hide" or operation == "remove" then
    return "hide:" .. actor
  end
  if operation == "copy" then
    return "copy:" .. hektorStagedStableId(actor .. "|" .. mesh .. "|" .. loc .. "|" .. rot)
  end
  return operation .. ":" .. hektorStagedStableId(actor .. "|" .. mesh .. "|" .. loc .. "|" .. rot)
end

function hektorStagedAcceptedBatch(row)
  local rowStatus = extractString(row, "status") or ""
  local payload = extractString(row, "payload") or ""
  local batch = extractString(payload, "batch") or extractString(payload, "stagedBatch") or extractString(payload, "payload") or ""
  local batchVersion = extractString(batch, "version") or ""
  local acceptedBatch =
    rowStatus == "staged-safe-cdo-visual-proxy-apply" or
    rowStatus == "journal-only" or
    batchVersion:find("20260607%-map%-actor%-only", 1) ~= nil or
    batchVersion:find("20260607%-copy%-preview%-original%-kept", 1) ~= nil or
    batchVersion:find("20260607%-copy%-preview%-single%-draft", 1) ~= nil or
    batchVersion:find("world%-edit", 1) ~= nil
  if acceptedBatch and batch ~= "" and batch:find('"items"%s*:%s*%[', 1) ~= nil then
    return batch, payload, rowStatus
  end
  return "", payload, rowStatus
end

function worldEditPayloadVector(text)
  local objectText = hektorStagedObjectField(text, "absoluteAfterLocation")
  if objectText == "" then objectText = hektorStagedObjectField(text, "targetLocation") end
  if objectText == "" then objectText = hektorStagedObjectField(text, "location") end
  if objectText == "" then objectText = hektorStagedObjectField(text, "afterLocation") end
  local x, y, z
  if objectText ~= "" then
    x = extractNumberAny(objectText, { "x", "X" }, nil)
    y = extractNumberAny(objectText, { "y", "Y" }, nil)
    z = extractNumberAny(objectText, { "z", "Z" }, nil)
  else
    x = extractNumberAny(text, { "x", "X", "worldX", "WorldX" }, nil)
    y = extractNumberAny(text, { "y", "Y", "worldY", "WorldY" }, nil)
    z = extractNumberAny(text, { "z", "Z", "worldZ", "WorldZ" }, nil)
  end
  if x == nil or y == nil or z == nil then return nil end
  return { x = x, y = y, z = z }
end

function worldEditPayloadRotation(text)
  local objectText = hektorStagedObjectField(text, "afterRotation")
  if objectText == "" then objectText = hektorStagedObjectField(text, "rotation") end
  if objectText ~= "" then
    return {
      pitch = extractNumberAny(objectText, { "pitch", "Pitch" }, 0) or 0,
      yaw = extractNumberAny(objectText, { "yaw", "Yaw" }, 0) or 0,
      roll = extractNumberAny(objectText, { "roll", "Roll" }, 0) or 0
    }
  end
  return {
    pitch = extractNumberAny(text, { "pitch", "Pitch" }, 0) or 0,
    yaw = extractNumberAny(text, { "yaw", "Yaw", "rotationYaw", "RotationYaw" }, 0) or 0,
    roll = extractNumberAny(text, { "roll", "Roll" }, 0) or 0
  }
end

function worldEditVectorJson(vector)
  return '{"x":' .. tostring(tonumber((vector or {}).x) or 0) ..
    ',"y":' .. tostring(tonumber((vector or {}).y) or 0) ..
    ',"z":' .. tostring(tonumber((vector or {}).z) or 0) .. '}'
end

function worldEditRotationJson(rotation)
  return '{"pitch":' .. tostring(tonumber((rotation or {}).pitch) or 0) ..
    ',"yaw":' .. tostring(tonumber((rotation or {}).yaw) or 0) ..
    ',"roll":' .. tostring(tonumber((rotation or {}).roll) or 0) .. '}'
end

function worldEditVisualSpawnStage(text, commandName, requestId)
  local meshFullName = extractStringAny(text, { "sourceMeshFullName", "meshFullName", "staticMeshFullName", "mesh", "asset" }) or ""
  if meshFullName == "" then
    local data = '{"ok":false,"stage":"world-edit-visual-spawn","blocked":true,"reason":"missing-sourceMeshFullName","message":"sourceMeshFullName or meshFullName is required."}'
    return false, "World edit visual spawn requires sourceMeshFullName", data
  end
  local location = worldEditPayloadVector(text)
  if location == nil then
    local data = '{"ok":false,"stage":"world-edit-visual-spawn","blocked":true,"reason":"missing-location","message":"x/y/z or location/targetLocation is required."}'
    return false, "World edit visual spawn requires x/y/z location", data
  end
  local rotation = worldEditPayloadRotation(text)
  local label = extractStringAny(text, { "label", "name", "id" }) or ""
  local siteSeed = tostring(commandName or "") .. "|" .. tostring(requestId or "") .. "|" .. meshFullName .. "|" .. worldEditVectorJson(location) .. "|" .. worldEditRotationJson(rotation) .. "|" .. label
  local siteId = "world-edit-visual-" .. hektorStagedStableId(siteSeed)
  local actorFullName = "ScumNeDjinWorldEdit." .. siteId
  local locJson = worldEditVectorJson(location)
  local rotJson = worldEditRotationJson(rotation)
  local item = '{"operation":"copy"' ..
    ',"targetFamily":"stock_map_visual"' ..
    ',"actorFullName":' .. js(actorFullName) ..
    ',"actorClass":"StaticMeshActor"' ..
    ',"sourceMeshFullName":' .. js(meshFullName) ..
    ',"beforeLocation":' .. locJson ..
    ',"afterLocation":' .. locJson ..
    ',"absoluteAfterLocation":' .. locJson ..
    ',"afterRotation":' .. rotJson ..
    ',"label":' .. js(label) ..
    ',"source":"world_edit_visual_spawn"' ..
    '}'
  local batch = '{"version":"20260622-world-edit-visual-spawn-1"' ..
    ',"mode":"client-overlay-visual-spawn"' ..
    ',"commitModel":"clientOverlayJournal"' ..
    ',"count":1' ..
    ',"items":[' .. item .. ']}'
  local payload = '{"batch":' .. js(batch) .. '}'
  local record = '{"utc":' .. js(nowUtc()) ..
    ',"id":' .. js(requestId or "") ..
    ',"command":' .. js(commandName or "world_edit_visual_spawn") ..
    ',"status":"journal-only"' ..
    ',"message":"World edit visual object stored in the client-overlay journal. No SCUM craft/godmod/server SpawnActor route was used."' ..
    ',"apply":{"mode":"client-overlay-journal","applied":0,"gameplayApplied":false,"vanillaVisible":false,"restartPersistent":false,"visibleToOverlayClients":true,"clientApplierRequired":true}' ..
    ',"payload":' .. js(payload) .. '}'
  local saved = appendJsonArray(EDITOR_ACTOR_STAGED_BATCHES_FILE, record, 4 * 1024 * 1024)
  if saved then flushStateArrayCache(EDITOR_ACTOR_STAGED_BATCHES_FILE) end
  local data = '{"ok":' .. tostring(saved == true) ..
    ',"stage":"world-edit-visual-spawn"' ..
    ',"mode":"client-overlay-journal"' ..
    ',"path":' .. js(EDITOR_ACTOR_STAGED_BATCHES_FILE) ..
    ',"siteId":' .. js(siteId) ..
    ',"sourceMeshFullName":' .. js(meshFullName) ..
    ',"location":' .. locJson ..
    ',"rotation":' .. rotJson ..
    ',"serverGameplayApplied":false' ..
    ',"serverVanillaVisible":false' ..
    ',"serverRestartPersistent":false' ..
    ',"visibleToOverlayClients":true' ..
    ',"clientApplierRequired":true' ..
    ',"message":"Stored in overlay journal. Participating clients with ScumNeDjinWorldOverlay will render it locally."}'
  if saved then
    return true, "World edit visual object stored in overlay journal", data
  end
  return false, "World edit visual spawn journal write failed", data
end

