function worldEditCreateEntityLab(text, requestId)
  if not configBool("bridge-safety", { "AllowWorldEditCreateEntityLab", "allowWorldEditCreateEntityLab" }, false) then
    local data = '{"ok":false,"blocked":true,"stage":"world-edit-create-entity-lab","reason":"disabled-by-bridge-safety","message":"AllowWorldEditCreateEntityLab is false."}'
    return false, "World edit CreateEntity lab is disabled by bridge-safety", data
  end
  local entityClass = cleanText(extractStringAny(text, { "entityClass", "entity", "setup", "class" }) or "")
  if entityClass == "" then entityClass = "Refrigerator_ES" end
  if entityClass:match("^[%w_]+_ES$") == nil then
    local data = '{"ok":false,"blocked":true,"stage":"world-edit-create-entity-lab","reason":"invalid-entity-class","entityClass":' .. js(entityClass) .. '}'
    return false, "CreateEntity lab accepts only *_ES entity setup names", data
  end
  if not worldEditServerOnlyEntityAllowlist()[entityClass] then
    local data = '{"ok":false,"blocked":true,"stage":"world-edit-create-entity-lab","reason":"entity-not-whitelisted","entityClass":' .. js(entityClass) .. '}'
    return false, "CreateEntity lab entity is not whitelisted", data
  end

  pcall(function() LoadAsset("/Game/ConZ_Files/AdminCommands/Developer/CreateEntity") end)
  pcall(function() LoadAsset("/Game/ConZ_Files/AdminCommands/Developer/CreateEntity.CreateEntity_C") end)

  local runtimeKey = extractStringAny(text, { "runtimeKey", "targetRuntimeKey", "playerRuntimeKey" }) or ""
  local steamId = extractStringAny(text, { "steamId", "targetSteamId", "playerSteamId" }) or ""
  local name = extractStringAny(text, { "name", "targetName", "playerName" }) or ""
  local info = resolvePlayerInfoForPanel(steamId, name, runtimeKey, nil, "world-edit-create-entity-lab")
  if info == nil then info = findPlayer(steamId, name, runtimeKey) or resolvePlayerInfo(steamId, name, nil, runtimeKey) end
  if info == nil then
    local data = '{"ok":false,"blocked":true,"stage":"world-edit-create-entity-lab","reason":"no-live-player","entityClass":' .. js(entityClass) .. '}'
    return false, "CreateEntity lab requires a live admin/player controller", data
  end
  local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
  local commandText = "CreateEntity " .. entityClass
  local sent, message = adminExec(commandText, live)
  local data = '{"ok":' .. tostring(sent == true) ..
    ',"stage":"world-edit-create-entity-lab"' ..
    ',"entityClass":' .. js(entityClass) ..
    ',"adminCommand":' .. js(commandText) ..
    ',"route":' .. js(message or "") ..
    ',"targetSteamId":' .. js((live or {}).steam or steamId or "") ..
    ',"targetName":' .. js((live or {}).name or name or "") ..
    ',"targetRuntimeKey":' .. js((live or {}).runtimeKey or runtimeKey or "") ..
    ',"serverOnlyCandidate":true' ..
    ',"gameplayVerified":false' ..
    ',"restartPersistent":false' ..
    ',"message":' .. js(sent and "CreateEntity command dispatched; verify in game, DB/entity count, reconnect and restart." or tostring(message or "CreateEntity command failed")) ..
    '}'
  appendActionEvent("world_edit_create_entity_lab", sent, live, tostring(message or ""), data)
  if sent then return true, "CreateEntity lab command dispatched", data end
  return false, tostring(message or "CreateEntity command failed"), data
end

function editorActorOverlayStateJson()
  local cache = loadStateArrayCache(EDITOR_ACTOR_STAGED_BATCHES_FILE, 4 * 1024 * 1024, true)
  local rows = cache.rows or {}
  local latestRow = ""
  local latestPayload = ""
  local latestStatus = ""
  local acceptedRows = 0
  local itemByKey = {}
  local itemOrder = {}
  for index = 1, #rows do
    local row = tostring(rows[index] or "")
    local batch, payload, rowStatus = hektorStagedAcceptedBatch(row)
    if batch ~= "" then
      latestRow = row
      latestPayload = payload
      latestStatus = rowStatus
      acceptedRows = acceptedRows + 1
      for _, item in ipairs(hektorStagedArrayObjects(batch, "items")) do
        local key = hektorStagedOverlayItemKey(item)
        if itemByKey[key] == nil then table.insert(itemOrder, key) end
        itemByKey[key] = item
      end
    end
  end
  local items = {}
  local maxItems = 400
  local firstIndex = math.max(1, #itemOrder - maxItems + 1)
  for index = firstIndex, #itemOrder do
    local item = itemByKey[itemOrder[index]]
    if item ~= nil then table.insert(items, item) end
  end
  local combinedBatch = ""
  if #items > 0 then
    combinedBatch = '{"version":"20260622-world-edit-overlay-journal-1","mode":"client-overlay-aggregate","commitModel":"clientOverlayJournal","count":' .. tostring(#items) .. ',"items":[' .. table.concat(items, ",") .. ']}'
  end
  local stateId = combinedBatch ~= "" and hektorStagedStableId(combinedBatch) or "empty"
  return '{"version":"20260622-overlay-state-aggregate-1"' ..
    ',"mode":"client-overlay-journal"' ..
    ',"path":' .. js(EDITOR_ACTOR_STAGED_BATCHES_FILE) ..
    ',"records":' .. tostring(#rows) ..
    ',"acceptedRecords":' .. tostring(acceptedRows) ..
    ',"stateId":' .. js(stateId) ..
    ',"hasBatch":' .. tostring(combinedBatch ~= "") ..
    ',"count":' .. tostring(#items) ..
    ',"truncated":' .. tostring(#itemOrder > maxItems) ..
    ',"batch":' .. js(combinedBatch) ..
    ',"latestStatus":' .. js(latestStatus) ..
    ',"latestUtc":' .. js(extractString(latestRow, "utc") or "") ..
    ',"payloadCommand":' .. js(extractString(latestPayload, "command") or "") ..
    ',"serverGameplayApplied":false' ..
    ',"serverVanillaVisible":false' ..
    ',"serverRestartPersistent":false' ..
    ',"visibleToOverlayClients":' .. tostring(#items > 0) ..
    ',"clientApplierRequired":true}'
end

function hektorStagedActorBlockReason(actorClass, actorFullName)
  local haystack = tostring((actorClass or "") .. " " .. (actorFullName or "")):lower()
  if haystack == "" then return "missing-actor-class" end
  local blocked = {
    { "default__", "class-default-object" },
    { "/script/coreuobject.class", "class-object" },
    { "/script/scum.trader", "trader-class" },
    { "bp_armsdealer", "trader-blueprint" },
    { "bp_banker", "trader-blueprint" },
    { "bp_barber", "trader-blueprint" },
    { "bp_bartender", "trader-blueprint" },
    { "bp_doctor", "trader-blueprint" },
    { "bp_general_goods", "trader-blueprint" },
    { "bp_harbourmaster", "trader-blueprint" },
    { "bp_mechanic", "trader-blueprint" },
    { "npcinteractionbox", "tradepost-interaction-box" },
    { "tradeoutpost", "tradepost-manager-or-route" },
    { "tradepost", "tradepost-manager-or-route" },
    { "economymanager", "economy-manager" },
    { "/script/scum.prisoner", "player-or-prisoner-class" },
    { "conzplayer", "player-or-prisoner-class" },
    { "playercontroller", "player-controller" },
    { "controller", "controller" },
    { "inventorycomponent", "inventory" },
    { "/script/scum.item", "item-class" },
    { "itementitysetup", "item-setup" },
    { "/script/scum.zombie", "creature" },
    { "/script/scum.sentry", "creature" },
    { "/script/scum.brenner", "creature" },
    { "bp_zombie", "creature-blueprint" },
    { "bp_sentry", "creature-blueprint" },
    { "bp_brenner", "creature-blueprint" },
    { "bp_razor", "creature-blueprint" },
    { "npcguard", "npc-guard" },
    { "guardedzonemanager", "npc-manager" }
  }
  for _, entry in ipairs(blocked) do
    if haystack:find(entry[1], 1, true) ~= nil then return entry[2] end
  end
  return ""
end

function hektorStagedVector(itemJson, fieldName)
  local objectText = jsonObjectFieldText(itemJson, fieldName)
  if objectText == nil then return nil end
  local x = extractNumberAny(objectText, { "x", "X" }, nil)
  local y = extractNumberAny(objectText, { "y", "Y" }, nil)
  local z = extractNumberAny(objectText, { "z", "Z" }, nil)
  if x == nil or y == nil or z == nil then return nil end
  return { X = x, Y = y, Z = z }
end

function hektorStagedYaw(itemJson)
  local objectText = jsonObjectFieldText(itemJson, "afterRotation") or jsonObjectFieldText(itemJson, "beforeRotation")
  if objectText == nil then return 0 end
  return extractNumberAny(objectText, { "yaw", "Yaw" }, 0) or 0
end

function hektorNormalizeYaw(value)
  local yaw = tonumber(value) or 0
  while yaw > 180 do yaw = yaw - 360 end
  while yaw < -180 do yaw = yaw + 360 end
  return yaw
end

function hektorStagedRotation(itemJson, fieldName)
  local objectText = jsonObjectFieldText(itemJson, fieldName)
  if objectText == nil then return nil end
  return {
    Pitch = extractNumberAny(objectText, { "pitch", "Pitch" }, 0) or 0,
    Yaw = extractNumberAny(objectText, { "yaw", "Yaw" }, 0) or 0,
    Roll = extractNumberAny(objectText, { "roll", "Roll" }, 0) or 0
  }
end

function hektorStagedServerBasedTransform(itemJson, actorFullName, requestedLoc, requestedYaw, requestId, index)
  local beforeLoc = hektorStagedVector(itemJson, "beforeLocation")
  local afterLoc = hektorStagedVector(itemJson, "afterLocation")
  local handle = tostring(actorFullName or "")
  if handle == "" or beforeLoc == nil or afterLoc == nil then
    return requestedLoc, requestedYaw, "client-absolute-fallback:missing-handle-or-before-after"
  end
  if configBool("bridge-safety", { "EnableActorEditorStagedServerBaseProbe", "enableActorEditorStagedServerBaseProbe" }, false) ~= true then
    return requestedLoc, requestedYaw, "client-absolute-fallback:server-base-probe-disabled-after-2026-06-05-crash"
  end

  local objectPath = extractStringAny(itemJson, { "objectPath", "targetObjectPath" }) or ""
  local probePayload = '{"actorFullName":' .. js(handle) ..
    ',"objectPath":' .. js(objectPath) ..
    ',"source":"hektor-staged-server-base-probe","dryRun":true}'
  local probeId = tostring(requestId or "hektor-staged") .. "-probe-" .. tostring(index or 0)
  local okProbe, message, result = nativeTraderCommand("native_actor_editor_probe", probePayload, 6000, probeId)
  if not okProbe then
    return requestedLoc, requestedYaw, "client-absolute-fallback:server-base-probe-failed:" .. tostring(message or "")
  end

  local baseX, baseY, baseZ, locField = vectorFromNativeResult(result, { "location", "actualLocation", "beforeLocation", "requestedLocation" })
  if baseX == nil or baseY == nil or baseZ == nil then
    return requestedLoc, requestedYaw, "client-absolute-fallback:server-base-probe-no-location"
  end

  local dx = (tonumber(afterLoc.X) or 0) - (tonumber(beforeLoc.X) or 0)
  local dy = (tonumber(afterLoc.Y) or 0) - (tonumber(beforeLoc.Y) or 0)
  local dz = (tonumber(afterLoc.Z) or 0) - (tonumber(beforeLoc.Z) or 0)
  local loc = { X = baseX + dx, Y = baseY + dy, Z = baseZ + dz }

  local yaw = tonumber(requestedYaw) or 0
  local beforeRot = hektorStagedRotation(itemJson, "beforeRotation")
  local afterRot = hektorStagedRotation(itemJson, "afterRotation")
  local _, serverYaw, _, rotField = rotatorFromNativeResult(result, { "rotation", "actualRotation", "beforeRotation", "requestedRotation" })
  if beforeRot ~= nil and afterRot ~= nil and rotField ~= "" then
    yaw = hektorNormalizeYaw((tonumber(serverYaw) or 0) + hektorNormalizeYaw((tonumber(afterRot.Yaw) or 0) - (tonumber(beforeRot.Yaw) or 0)))
  end

  local detail = "server-base-delta locField=" .. tostring(locField or "") ..
    " dx=" .. tostring(dx) .. " dy=" .. tostring(dy) .. " dz=" .. tostring(dz) ..
    " serverBase=" .. tostring(baseX) .. "," .. tostring(baseY) .. "," .. tostring(baseZ) ..
    " corrected=" .. tostring(loc.X) .. "," .. tostring(loc.Y) .. "," .. tostring(loc.Z)
  return loc, yaw, detail
end

function hektorStagedNativePlaceableRecipe(itemJson, actorClass, actorFullName)
  local explicit = extractStringAny(itemJson, {
    "placeableRecipe",
    "nativePlaceableRecipe",
    "serverRecipe",
    "recipe",
    "recipeName"
  }) or ""
  if explicit ~= "" then return explicit, "explicit" end

  local defaultRecipe = configString("bridge-safety", {
    "ActorEditorNativePlaceableDefaultRecipe",
    "actorEditorNativePlaceableDefaultRecipe"
  }, "CR_Base_Block")
  local doorRecipe = configString("bridge-safety", {
    "ActorEditorNativePlaceableDoorRecipe",
    "actorEditorNativePlaceableDoorRecipe"
  }, defaultRecipe)
  local wallRecipe = configString("bridge-safety", {
    "ActorEditorNativePlaceableWallRecipe",
    "actorEditorNativePlaceableWallRecipe"
  }, defaultRecipe)
  local foundationRecipe = configString("bridge-safety", {
    "ActorEditorNativePlaceableFoundationRecipe",
    "actorEditorNativePlaceableFoundationRecipe"
  }, defaultRecipe)

  local haystack = tostring((actorClass or "") .. " " .. (actorFullName or "")):lower()
  if haystack:find("door", 1, true) ~= nil then return doorRecipe, "door-like" end
  if haystack:find("wall", 1, true) ~= nil or haystack:find("window", 1, true) ~= nil then return wallRecipe, "wall-like" end
  if haystack:find("foundation", 1, true) ~= nil or haystack:find("block", 1, true) ~= nil then return foundationRecipe, "foundation-like" end
  return defaultRecipe, "default"
end

function hektorStagedNativePlaceableCandidate(batchText)
  local items = hektorStagedArrayObjects(batchText, "items")
  local sawMove = false
  for index = #items, 1, -1 do
    local item = items[index]
    local operation = tostring(extractStringAny(item, { "operation", "op" }) or ""):lower()
    if operation == "move" then sawMove = true end
    if operation == "copy" then
      local actorFullName = extractStringAny(item, { "actorFullName", "targetActorFullName", "fullName" }) or ""
      local actorClass = extractStringAny(item, { "actorClass", "actorClassFullName", "targetActorClass", "className" }) or ""
      local loc = hektorStagedVector(item, "absoluteAfterLocation") or hektorStagedVector(item, "afterLocationZeroOrigin") or hektorStagedVector(item, "zeroOriginAfterLocation")
      local yaw = hektorStagedYaw(item)
      local blockReason = hektorStagedActorBlockReason(actorClass, actorFullName)
      if loc == nil then blockReason = blockReason ~= "" and blockReason or "missing-client-zero-origin-location" end
      local recipe, recipeReason = hektorStagedNativePlaceableRecipe(item, actorClass, actorFullName)
      return {
        index = index,
        item = item,
        operation = operation,
        actorFullName = actorFullName,
        actorClass = actorClass,
        location = loc,
        yaw = yaw,
        blockReason = blockReason,
        recipe = recipe,
        recipeReason = recipeReason,
        totalItems = #items
      }
    end
  end
  if sawMove then return { totalItems = #items, blockReason = "move-not-supported-by-native-placeable-commit" } end
  return { totalItems = #items, blockReason = "no-copy-or-move-item" }
end

function hektorStagedNativePlaceableApplyQueued(batchText, commandName, requestId, rawPayload)
  local enabled = configBool("bridge-safety", {
    "EnableActorEditorStagedNativePlaceableApply",
    "enableActorEditorStagedNativePlaceableApply"
  }, true) == true
  local candidate = hektorStagedNativePlaceableCandidate(batchText)
  local command = tostring(commandName or "editor_actor_stage_batch")
  if not enabled then
    local data = '{"enabled":false,"mode":"native-placeable-apply","blocked":true,"blockReason":"disabled"}'
    return false, "Native placeable staged apply disabled.", data
  end
  if candidate.blockReason ~= nil and candidate.blockReason ~= "" then
    local data = '{"enabled":true,"mode":"native-placeable-apply","queued":false,"blocked":true' ..
      ',"items":' .. tostring(candidate.totalItems or 0) ..
      ',"selectedIndex":' .. tostring(candidate.index or 0) ..
      ',"operation":' .. js(candidate.operation or "") ..
      ',"actorClass":' .. js(candidate.actorClass or "") ..
      ',"actorFullName":' .. js(candidate.actorFullName or "") ..
      ',"blockReason":' .. js(candidate.blockReason or "") ..
      ',"message":"Batch cannot be committed through SCUM native placeable lifecycle."}'
    return false, "Actor editor batch blocked before native placeable apply.", data
  end

  local steamId = extractString(rawPayload or "", "steamId")
  local name = extractString(rawPayload or "", "name")
  local runtimeKey = extractStringAny(rawPayload or "", { "runtimeKey", "targetRuntime", "playerRuntimeKey" }) or ""
  local info = resolvePlayerInfo(steamId, name, nil, runtimeKey) or { steam = steamId or "", name = name or "", runtimeKey = runtimeKey or "" }
  local queued, queueIdOrMessage, depth = enqueueMutation("hektor-native-placeable-apply", info, function()
    local live = resolvePlayerInfo(steamId, name, nil, runtimeKey) or resolvePlayerInfo(steamId, name, info, runtimeKey) or info
    local sent, resultMessage, resultData = spawnNativePlaceableForInfo(candidate.recipe, live, {
      requestId = requestId,
      commandName = command,
      location = candidate.location,
      yaw = candidate.yaw,
      source = "hektor-staged-native-placeable",
      stagedOperation = candidate.operation,
      stagedActorFullName = candidate.actorFullName,
      stagedActorClass = candidate.actorClass
    })
    if sent == nil and resultData == "__async__" then return end
    if requestId ~= nil and tostring(requestId) ~= "" then
      if sent then
        writeAll(RESULT_FILE, ok(command, resultMessage, resultData or "{}", requestId))
      else
        writeAll(RESULT_FILE, fail(command, resultMessage, requestId))
      end
    end
  end)
  local data = '{"enabled":true,"mode":"native-placeable-apply","queued":' .. tostring(queued == true) ..
    ',"queueId":' .. js(tostring(queueIdOrMessage or "")) ..
    ',"depth":' .. tostring(depth or 0) ..
    ',"items":' .. tostring(candidate.totalItems or 0) ..
    ',"selectedIndex":' .. tostring(candidate.index or 0) ..
    ',"operation":' .. js(candidate.operation or "") ..
    ',"actorClass":' .. js(candidate.actorClass or "") ..
    ',"actorFullName":' .. js(candidate.actorFullName or "") ..
    ',"recipe":' .. js(candidate.recipe or "") ..
    ',"recipeReason":' .. js(candidate.recipeReason or "") ..
    ',"x":' .. tostring((candidate.location or {}).X or 0) ..
    ',"y":' .. tostring((candidate.location or {}).Y or 0) ..
    ',"z":' .. tostring((candidate.location or {}).Z or 0) ..
    ',"yaw":' .. tostring(candidate.yaw or 0) .. '}'
  if queued then return true, "Actor editor batch queued as SCUM native placeable apply.", data end
  return false, tostring(queueIdOrMessage or "Native placeable apply queue failed."), data
end

function persistentActorSiteExists(siteId)
  local cleanId = tostring(siteId or "")
  if cleanId == "" then return false end
  local rows = persistentActorRows()
  for _, row in ipairs(rows) do
    local active = extractBool(row, "active", true)
    local existing = extractStringAny(row, { "siteId", "idempotencyKey", "persistentId" }) or ""
    if active ~= false and existing == cleanId then return true end
  end
  return false
end

function hektorStagedHideOriginalForMove(item, requestId, index)
  if configBool("bridge-safety", { "ActorEditorStagedMoveHideOriginal", "actorEditorStagedMoveHideOriginal" }, true) ~= true then
    return false, "hide-original disabled", "{}"
  end
  local actorFullName = extractStringAny(item, { "actorFullName", "targetActorFullName", "fullName" }) or ""
  local actorClass = extractStringAny(item, { "actorClass", "actorClassFullName", "targetActorClass", "className" }) or ""
  local objectPath = extractStringAny(item, { "objectPath", "targetObjectPath", "sourceObjectPath" }) or ""
  if actorFullName == "" and objectPath == "" then
    return false, "missing exact actor handle for hide-original", '{"stage":"missing-exact-handle"}'
  end
  local timeoutMs = math.max(3000, math.min(tonumber(configNumber("bridge-safety", { "ActorEditorStagedMoveHideOriginalTimeoutMs", "actorEditorStagedMoveHideOriginalTimeoutMs" }, 9000)) or 9000, 15000))
  local payload = '{"actorFullName":' .. js(actorFullName) ..
    ',"targetActorFullName":' .. js(actorFullName) ..
    ',"objectPath":' .. js(objectPath) ..
    ',"targetObjectPath":' .. js(objectPath) ..
    ',"actorClassFullName":' .. js(actorClass) ..
    ',"targetActorClass":' .. js(actorClass) ..
    ',"confirm":"HIDE_WORLD_ACTOR"' ..
    ',"source":"hektor-staged-move-hide-original"}'
  local okHide, message, data = nativeTraderCommand("native_actor_editor_hide", payload, timeoutMs, tostring(requestId or "hektor-staged") .. "-hide-" .. tostring(index or 0))
  appendActionEvent("hektor_staged_move_hide_original", okHide, nil, tostring(message or ""),
    '{"actorFullName":' .. js(actorFullName) ..
      ',"objectPath":' .. js(objectPath) ..
      ',"actorClass":' .. js(actorClass) ..
      ',"nativeResult":' .. js(data or "") .. '}')
  return okHide, message, data
end

function hektorStagedProxyApply(batchText, requestId)
  local batch = tostring(batchText or "")
  local enabled = configBool("bridge-safety", { "EnableActorEditorStagedProxyApply", "enableActorEditorStagedProxyApply" }, true) == true
  local moveAsCopy = configBool("bridge-safety", { "ActorEditorStagedProxyApplyMoveAsCopy", "actorEditorStagedProxyApplyMoveAsCopy" }, true) == true
  local maxItems = math.max(1, math.min(tonumber(configNumber("bridge-safety", { "ActorEditorStagedProxyApplyMaxItems", "actorEditorStagedProxyApplyMaxItems" }, 4)) or 4, 12))
  local timeoutMs = math.max(3000, math.min(tonumber(configNumber("bridge-safety", { "ActorEditorStagedProxySpawnTimeoutMs", "actorEditorStagedProxySpawnTimeoutMs" }, 25000)) or 25000, 30000))
  local items = hektorStagedArrayObjects(batch, "items")
  local applied, blocked, skipped, existing = 0, 0, 0, 0
  local details = {}
  if not enabled then
    return '{"enabled":false,"applied":0,"blocked":0,"skipped":0,"existing":0,"message":"staged proxy apply disabled"}'
  end
  for index, item in ipairs(items) do
    if index > maxItems then
      skipped = skipped + 1
      table.insert(details, '{"index":' .. tostring(index) .. ',"ok":false,"stage":"max-items","message":"item skipped by ActorEditorStagedProxyApplyMaxItems"}')
    else
      local operation = tostring(extractStringAny(item, { "operation", "op" }) or ""):lower()
      local actorFullName = extractStringAny(item, { "actorFullName", "targetActorFullName", "fullName" }) or ""
      local actorClass = extractStringAny(item, { "actorClass", "actorClassFullName", "targetActorClass", "className" }) or ""
      local objectPath = extractStringAny(item, { "objectPath", "targetObjectPath", "sourceObjectPath" }) or ""
      local componentFullName = extractStringAny(item, { "componentFullName", "targetComponentFullName", "sourceComponentFullName", "traceComponentFullName" }) or ""
      local sourceMeshFullName = extractStringAny(item, { "sourceMeshFullName", "meshFullName", "staticMeshFullName" }) or ""
      local cleanActor = actorSummonToken(actorClass)
      local absoluteLoc = hektorStagedVector(item, "absoluteAfterLocation") or hektorStagedVector(item, "afterLocationZeroOrigin") or hektorStagedVector(item, "zeroOriginAfterLocation")
      local loc = absoluteLoc or hektorStagedVector(item, "afterLocation") or hektorStagedVector(item, "beforeLocation")
      local yaw = hektorStagedYaw(item)
      local locationDetail = absoluteLoc ~= nil and "client-zero-origin" or "client-local-fallback"
      local allowServerBaseProbe = configBool("bridge-safety", { "EnableActorEditorStagedServerBaseProbe", "enableActorEditorStagedServerBaseProbe" }, false) == true
      local visualProxyEnabled = configBool("bridge-safety", { "EnableActorEditorStaticMeshVisualProxy", "enableActorEditorStaticMeshVisualProxy" }, true) == true
      local hasVisualMeshEvidence = componentFullName ~= "" or sourceMeshFullName ~= ""
      local useVisualProxy = visualProxyEnabled and hasVisualMeshEvidence
      local shouldProxy = operation == "copy" or (operation == "move" and moveAsCopy)
      if operation == "hide" or operation == "remove" then
        blocked = blocked + 1
        table.insert(details, '{"index":' .. tostring(index) .. ',"operation":' .. js(operation) .. ',"ok":false,"stage":"hide-original-blocked","message":"hide/remove of stock streamed actors is not applied by staged proxy v1"}')
      elseif not shouldProxy then
        skipped = skipped + 1
        table.insert(details, '{"index":' .. tostring(index) .. ',"operation":' .. js(operation) .. ',"ok":false,"stage":"not-a-proxy-operation"}')
      else
        local blockReason = hektorStagedActorBlockReason(actorClass, actorFullName)
        if cleanActor == "" then blockReason = blockReason ~= "" and blockReason or "bad-actor-class-token" end
        if loc == nil then blockReason = blockReason ~= "" and blockReason or "missing-after-location" end
        if absoluteLoc == nil and not allowServerBaseProbe then blockReason = blockReason ~= "" and blockReason or "missing-client-zero-origin-location" end
        if blockReason ~= "" then
          blocked = blocked + 1
          table.insert(details, '{"index":' .. tostring(index) ..
            ',"operation":' .. js(operation) ..
            ',"ok":false,"stage":"blocked-actor-category"' ..
            ',"actorClass":' .. js(actorClass) ..
            ',"actorFullName":' .. js(actorFullName) ..
            ',"locationMode":' .. js(locationDetail or "") ..
            ',"blockReason":' .. js(blockReason) .. '}')
        else
          if absoluteLoc == nil then
            loc, yaw, locationDetail = hektorStagedServerBasedTransform(item, actorFullName, loc, yaw, requestId, index)
          end
          local proxyActorClass = useVisualProxy and "StaticMeshActor" or cleanActor
          local proxyCatalogPath = useVisualProxy and "/Script/Engine.StaticMeshActor" or nil
          local siteSeed = operation .. "|" .. actorFullName .. "|" .. cleanActor .. "|" .. componentFullName .. "|" .. tostring(useVisualProxy) .. "|" .. tostring(loc.X) .. "|" .. tostring(loc.Y) .. "|" .. tostring(loc.Z) .. "|" .. tostring(yaw)
          local siteId = "hektor-" .. operation .. "-clone-" .. hektorStagedStableId(siteSeed)
          if persistentActorSiteExists(siteId) then
            existing = existing + 1
            local hideOk, hideMessage, hideData = false, "not-requested", "{}"
            if operation == "move" then
              hideOk, hideMessage, hideData = hektorStagedHideOriginalForMove(item, requestId, index)
            end
            table.insert(details, '{"index":' .. tostring(index) ..
              ',"operation":' .. js(operation) ..
              ',"ok":true,"stage":"already-persisted","siteId":' .. js(siteId) ..
              ',"actorClass":' .. js(cleanActor) ..
              ',"proxyActorClass":' .. js(proxyActorClass) ..
              ',"visualProxy":' .. tostring(useVisualProxy == true) ..
              ',"hideOriginalOk":' .. tostring(hideOk == true) ..
              ',"hideOriginalMessage":' .. js(hideMessage or "") ..
              ',"hideOriginalData":' .. js(hideData or "") ..
              ',"locationMode":' .. js(locationDetail or "") .. '}')
          else
            local entry = actorCatalogLookup(proxyActorClass)
            local okSpawn, message, data = nativePersistentActorSpawnForInfo(proxyActorClass, nil, entry, {
              location = loc,
              yaw = yaw,
              siteId = siteId,
              requestId = tostring(requestId or "hektor-staged") .. "-" .. tostring(index),
              source = "hektor-staged-" .. operation .. "-direct-clone",
              timeoutMs = timeoutMs,
              catalogPath = proxyCatalogPath,
              allowNativeClassResolve = useVisualProxy,
              visualProxy = useVisualProxy,
              originalActorClass = cleanActor,
              sourceActorClass = actorClass,
              sourceActorFullName = actorFullName,
              sourceObjectPath = objectPath,
              sourceComponentFullName = componentFullName,
              sourceMeshFullName = sourceMeshFullName
            })
            local hideOk, hideMessage, hideData = false, "not-requested", "{}"
            if okSpawn and operation == "move" then
              hideOk, hideMessage, hideData = hektorStagedHideOriginalForMove(item, requestId, index)
            end
            if okSpawn then applied = applied + 1 else blocked = blocked + 1 end
            table.insert(details, '{"index":' .. tostring(index) ..
              ',"operation":' .. js(operation) ..
              ',"ok":' .. tostring(okSpawn == true) ..
              ',"stage":' .. js(okSpawn and "persistent-direct-clone-spawned" or "persistent-direct-clone-spawn-failed") ..
              ',"siteId":' .. js(siteId) ..
              ',"actorClass":' .. js(cleanActor) ..
              ',"proxyActorClass":' .. js(proxyActorClass) ..
              ',"visualProxy":' .. tostring(useVisualProxy == true) ..
              ',"sourceComponentFullName":' .. js(componentFullName) ..
              ',"sourceMeshFullName":' .. js(sourceMeshFullName) ..
              ',"hideOriginalOk":' .. tostring(hideOk == true) ..
              ',"hideOriginalMessage":' .. js(hideMessage or "") ..
              ',"hideOriginalData":' .. js(hideData or "") ..
              ',"x":' .. tostring(tonumber(loc.X) or 0) ..
              ',"y":' .. tostring(tonumber(loc.Y) or 0) ..
              ',"z":' .. tostring(tonumber(loc.Z) or 0) ..
              ',"yaw":' .. tostring(tonumber(yaw) or 0) ..
              ',"locationMode":' .. js(locationDetail or "") ..
              ',"message":' .. js(message or "") ..
              ',"nativeData":' .. js(data or "") .. '}')
          end
        end
      end
    end
  end
  local data = '{"enabled":true' ..
    ',"mode":"persistent-direct-clone-spawn"' ..
    ',"moveAppliedAsCopy":' .. tostring(moveAsCopy) ..
    ',"items":' .. tostring(#items) ..
    ',"maxItems":' .. tostring(maxItems) ..
    ',"applied":' .. tostring(applied) ..
    ',"existing":' .. tostring(existing) ..
    ',"blocked":' .. tostring(blocked) ..
    ',"skipped":' .. tostring(skipped) ..
    ',"details":[' .. table.concat(details, ",") .. ']}'
  appendActionEvent("hektor_staged_proxy_apply", applied > 0 or existing > 0, nil,
    "Hektor staged direct clone apply: applied=" .. tostring(applied) .. " existing=" .. tostring(existing) .. " blocked=" .. tostring(blocked) .. " skipped=" .. tostring(skipped),
    data)
  return data
end

function editorActorEditSiteId(operation, actorFullName)
  local leaf = tostring(actorFullName or ""):match("([^%.:/\\]+)$") or "actor"
  leaf = leaf:gsub("[^%w_%-]", "_")
  return "editor-" .. tostring(operation or "edit") .. "-" .. leaf .. "-" .. tostring(os.time()) .. "-" .. tostring(math.floor((os.clock() or 0) * 1000000))
end

function appendEditorActorEditRecord(recordJson)
  return appendJsonArray(EDITOR_ACTOR_EDITS_FILE, recordJson, 2 * 1024 * 1024)
end

function rememberEditorActorNativeResult(operation, payloadJson, nativeResult)
  local op = tostring(operation or "")
  local payload = tostring(payloadJson or "{}")
  local result = tostring(nativeResult or "{}")
  if extractBoolAny(payload, { "dryRun", "dry" }, false) == true then return false end
  if extractBoolAny(payload, { "replay", "restore" }, false) == true then return false end
  if extractBoolAny(result, { "ok", "Ok" }, false) ~= true then return false end

  if op == "move" or op == "nudge" then
    local actorFullName = extractStringAny(result, { "actorFullName", "targetActorFullName", "sourceActorFullName" }) or
      extractStringAny(payload, { "actorFullName", "targetActorFullName", "targetFullName", "fullName" }) or ""
    local x, y, z, locField = vectorFromNativeResult(result, { "afterLocation", "actualLocation", "requestedLocation" })
    local pitch, yaw, roll, rotField = rotatorFromNativeResult(result, { "afterRotation", "actualRotation", "requestedRotation" })
    if actorFullName == "" or x == nil or y == nil or z == nil then return false end
    local record = '{"utc":' .. js(nowUtc()) ..
      ',"active":true' ..
      ',"siteId":' .. js(editorActorEditSiteId(op, actorFullName)) ..
      ',"operation":"move"' ..
      ',"sourceOperation":' .. js(op) ..
      ',"actorFullName":' .. js(actorFullName) ..
      ',"x":' .. tostring(x) ..
      ',"y":' .. tostring(y) ..
      ',"z":' .. tostring(z) ..
      ',"pitch":' .. tostring(pitch or 0) ..
      ',"yaw":' .. tostring(yaw or 0) ..
      ',"roll":' .. tostring(roll or 0) ..
      ',"locationField":' .. js(locField or "") ..
      ',"rotationField":' .. js(rotField or "") ..
      ',"source":"hektor-client-target-editor"}'
    local persisted = appendEditorActorEditRecord(record)
    appendActionEvent("actor_editor_persist", persisted, nil, "Actor editor move persisted=" .. tostring(persisted), '{"operation":' .. js(op) .. ',"actorFullName":' .. js(actorFullName) .. '}')
    return persisted
  end

  if op == "hide" or op == "remove" then
    local actorFullName = extractStringAny(result, { "actorFullName", "targetActorFullName" }) or
      extractStringAny(payload, { "actorFullName", "targetActorFullName", "targetFullName", "fullName" }) or ""
    if actorFullName == "" then return false end
    local record = '{"utc":' .. js(nowUtc()) ..
      ',"active":true' ..
      ',"siteId":' .. js(editorActorEditSiteId("hide", actorFullName)) ..
      ',"operation":"hide"' ..
      ',"actorFullName":' .. js(actorFullName) ..
      ',"source":"hektor-client-target-editor"}'
    local persisted = appendEditorActorEditRecord(record)
    appendActionEvent("actor_editor_persist", persisted, nil, "Actor editor hide persisted=" .. tostring(persisted), '{"actorFullName":' .. js(actorFullName) .. '}')
    return persisted
  end

  if op == "copy" then
    local sourceActorFullName = extractStringAny(result, { "sourceActorFullName", "actorFullName" }) or
      extractStringAny(payload, { "actorFullName", "targetActorFullName", "targetFullName", "fullName" }) or ""
    local spawnedActorFullName = extractStringAny(result, { "spawnedActorFullName", "spawnedActor" }) or ""
    local sourceClass = extractStringAny(result, { "sourceClass", "sourceActorClass", "spawnedActorClass" }) or ""
    local spawnedClassLeaf = extractStringAny(result, { "spawnedClassLeaf" }) or ""
    local x, y, z, locField = vectorFromNativeResult(result, { "actualLocation", "requestedLocation" })
    local pitch, yaw, roll, rotField = rotatorFromNativeResult(result, { "actualRotation", "requestedRotation" })
    if sourceActorFullName == "" or x == nil or y == nil or z == nil then return false end
    local record = '{"utc":' .. js(nowUtc()) ..
      ',"active":true' ..
      ',"siteId":' .. js(editorActorEditSiteId("copy", sourceActorFullName)) ..
      ',"operation":"copy"' ..
      ',"sourceActorFullName":' .. js(sourceActorFullName) ..
      ',"spawnedActorFullName":' .. js(spawnedActorFullName) ..
      ',"sourceClass":' .. js(sourceClass) ..
      ',"spawnedClassLeaf":' .. js(spawnedClassLeaf) ..
      ',"x":' .. tostring(x) ..
      ',"y":' .. tostring(y) ..
      ',"z":' .. tostring(z) ..
      ',"pitch":' .. tostring(pitch or 0) ..
      ',"yaw":' .. tostring(yaw or 0) ..
      ',"roll":' .. tostring(roll or 0) ..
      ',"locationField":' .. js(locField or "") ..
      ',"rotationField":' .. js(rotField or "") ..
      ',"source":"hektor-client-target-editor"}'
    local persisted = appendEditorActorEditRecord(record)
    appendActionEvent("actor_editor_persist", persisted, nil, "Actor editor copy persisted=" .. tostring(persisted), '{"sourceActorFullName":' .. js(sourceActorFullName) .. ',"spawnedActorFullName":' .. js(spawnedActorFullName) .. '}')
    return persisted
  end

  return false
end

function restoreEditorActorEdits()
  if configBool("bridge-safety", { "EnableEditorActorReplay", "enableEditorActorReplay" }, true) ~= true then
    return true, "editor actor replay disabled"
  end
  local rows = loadStateArrayCache(EDITOR_ACTOR_EDITS_FILE, 2 * 1024 * 1024, true).rows or {}
  local total = 0
  local restored = 0
  local attempts = {}
  for index, row in ipairs(rows or {}) do
    local active = extractBoolAny(row, { "active", "Active" }, true)
    local operation = tostring(extractStringAny(row, { "operation", "Operation" }) or "")
    local siteId = tostring(extractStringAny(row, { "siteId", "SiteId" }) or ("row-" .. tostring(index)))
    if active ~= false and operation ~= "" and EDITOR_ACTOR_RESTORED_EDITS[siteId] ~= true then
      total = total + 1
      local payload = nil
      local nativeCommand = nil
      if operation == "move" then
        local actorFullName = extractStringAny(row, { "actorFullName", "targetActorFullName" }) or ""
        local x = extractNumberAny(row, { "x", "X" }, nil)
        local y = extractNumberAny(row, { "y", "Y" }, nil)
        local z = extractNumberAny(row, { "z", "Z" }, nil)
        local yaw = extractNumberAny(row, { "yaw", "Yaw" }, 0) or 0
        if actorFullName ~= "" and x ~= nil and y ~= nil and z ~= nil then
          payload = '{"actorFullName":' .. js(actorFullName) ..
            ',"x":' .. tostring(x) ..
            ',"y":' .. tostring(y) ..
            ',"z":' .. tostring(z) ..
            ',"yaw":' .. tostring(yaw) ..
            ',"confirm":"MOVE_WORLD_ACTOR","replay":true,"source":"editor-actor-replay"}'
          nativeCommand = "native_actor_editor_move"
        end
      elseif operation == "hide" or operation == "remove" then
        local actorFullName = extractStringAny(row, { "actorFullName", "targetActorFullName" }) or ""
        if actorFullName ~= "" then
          payload = '{"actorFullName":' .. js(actorFullName) ..
            ',"confirm":"HIDE_WORLD_ACTOR","replay":true,"source":"editor-actor-replay"}'
          nativeCommand = "native_actor_editor_hide"
        end
      elseif operation == "copy" then
        local sourceActorFullName = extractStringAny(row, { "sourceActorFullName", "actorFullName", "targetActorFullName" }) or ""
        local x = extractNumberAny(row, { "x", "X" }, nil)
        local y = extractNumberAny(row, { "y", "Y" }, nil)
        local z = extractNumberAny(row, { "z", "Z" }, nil)
        local yaw = extractNumberAny(row, { "yaw", "Yaw" }, 0) or 0
        if sourceActorFullName ~= "" and x ~= nil and y ~= nil and z ~= nil then
          payload = '{"actorFullName":' .. js(sourceActorFullName) ..
            ',"x":' .. tostring(x) ..
            ',"y":' .. tostring(y) ..
            ',"z":' .. tostring(z) ..
            ',"yaw":' .. tostring(yaw) ..
            ',"confirm":"COPY_WORLD_ACTOR","replay":true,"source":"editor-actor-replay"}'
          nativeCommand = "native_actor_editor_copy"
        end
      end

      if payload ~= nil and nativeCommand ~= nil then
        local okRestore, message, result = nativeTraderCommand(nativeCommand, payload, 9000, "restore-" .. siteId)
        if okRestore then
          EDITOR_ACTOR_RESTORED_EDITS[siteId] = true
          restored = restored + 1
          if #attempts < 60 then table.insert(attempts, siteId .. "=ok") end
        else
          if #attempts < 60 then table.insert(attempts, siteId .. "=" .. tostring(message or "failed") .. " result=" .. tostring(result or "")) end
        end
      else
        if #attempts < 60 then table.insert(attempts, siteId .. "=invalid-row:" .. tostring(operation)) end
      end
    end
  end
  if total > 0 then
    appendActionEvent("actor_editor_restore", restored == total, nil,
      "Actor editor restore: " .. tostring(restored) .. "/" .. tostring(total),
      '{"restored":' .. tostring(restored) ..
        ',"total":' .. tostring(total) ..
        ',"file":' .. js(EDITOR_ACTOR_EDITS_FILE) ..
        ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
  end
  return restored == total, "restored " .. tostring(restored) .. "/" .. tostring(total)
end

function scheduleEditorActorEditRestore()
  if configBool("bridge-safety", { "EnableEditorActorReplay", "enableEditorActorReplay" }, true) ~= true then return end
  deferGame(22000, function()
    restoreEditorActorEdits()
  end)
  deferGame(70000, function()
    restoreEditorActorEdits()
  end)
end

function functionalTraderNormalizeText(value)
  return tostring(value or ""):lower():gsub("_c", "")
end

function functionalTraderRouteTokensForActor(actorClass, entry)
  local tokens = {}
  local seen = {}
  local function add(value)
    local token = functionalTraderNormalizeText(value):gsub("^%s+", ""):gsub("%s+$", "")
    if token == "" or seen[token] then return end
    seen[token] = true
    table.insert(tokens, token)
  end
  local shortClass = actorRouteShortClass(actorClass, entry)
  local hint = traderTypeHint(actorClass, nil)
  if actorCatalogIsTradePostLike(actorClass, entry) then add(shortClass) end
  if actorCatalogIsBankerActor(actorClass, entry) or hint == "banker" then
    add("bp_outpost_bank_open_npc_interactionboxes")
    add("bank_open")
    add("bank")
    return tokens
  end
  if hint == "armorer" then
    add("bp_outpost_armory_npcinteractionbox")
    add("armory")
  elseif hint == "mechanic" then
    add("bp_outpost_carshop_npc_and_vehiclespawner")
    add("carshop")
    add("car_shop")
  elseif hint == "doctor" then
    add("bp_outpost_hospital_npc_interactionboxes")
    add("hospital")
  elseif hint == "harbourmaster" then
    add("bp_fishermantrader_npc_interactionbox")
    add("fishermantrader")
    add("fishingtrader")
  elseif hint == "bartender" then
    add("bp_saloonoutpost_npc_interactionboxes")
    add("saloonoutpost")
    add("saloon")
  elseif hint == "barber" then
    add("bp_barbershop_npc_interactionbox")
    add("barbershop")
    add("barber")
  elseif hint == "generalgoods" then
    add("bp_outpost_trader_npcinteractionbox")
    add("outpost_trader")
  end
  if #tokens == 0 then
    add(shortClass)
    add("bp_outpost_trader_npcinteractionbox")
  end
  return tokens
end

function tradeOutpostManagerClassesForLookup()
  return {
    "BP_TradeOutpostManager_C",
    "TradeOutpostManager",
    "TradeOutpostManager_C",
    "ATradeOutpostManager",
    "BP_TradeOutpostManager"
  }
end

function findAllTradeOutpostManagers()
  return findAll(tradeOutpostManagerClassesForLookup())
end

function tradeOutpostLevelToken(obj)
  local text = objectFullName(obj)
  local token = tostring(text or ""):match("/The_Island/([^%.:]+)%.%1:PersistentLevel")
  if token ~= nil and token ~= "" then return token end
  token = tostring(text or ""):match("/The_Island/([A-Z]_%d_Outpost)")
  if token ~= nil and token ~= "" then return token end
  token = tostring(text or ""):match("([A-Z]_%d_Outpost)")
  if token ~= nil and token ~= "" then return token end
  return ""
end

function functionalTraderSiteState()
  local text = normalizeJsonArrayText(readAll(FUNCTIONAL_TRADER_SITES_FILE) or "[]", 1024 * 1024)
  local rows = {}
  local bySource = {}
  for record in text:gmatch("%b{}") do
    local sourceFullName = extractStringAny(record, { "sourceFullName", "source", "tradePostFullName" }) or ""
    if sourceFullName ~= "" then
      local active = extractBoolAny(record, { "active", "Active" }, true)
      local row = {
        raw = record,
        active = active ~= false,
        actorClass = extractStringAny(record, { "actorClass", "ActorClass" }) or "",
        routeClass = extractStringAny(record, { "routeClass", "RouteClass" }) or "",
        routeMode = extractStringAny(record, { "routeMode", "RouteMode", "mode", "Mode" }) or "",
        sourceFullName = sourceFullName,
        x = extractNumberAny(record, { "x", "X" }, nil),
        y = extractNumberAny(record, { "y", "Y" }, nil),
        z = extractNumberAny(record, { "z", "Z" }, nil),
        yaw = extractNumberAny(record, { "yaw", "Yaw" }, nil)
      }
      table.insert(rows, row)
      bySource[sourceFullName] = row
    end
  end
  return rows, bySource
end

function functionalTraderAssignedTradePostKeys()
  local attempts = {}
  local assigned = {}
  local assignedCount = 0
  local managers = findAllTradeOutpostManagers()
  table.insert(attempts, "TradeOutpostManager.count=" .. tostring(#(managers or {})))
  for _, manager in ipairs(managers or {}) do
    local assignedPosts = firstProp(manager, { "_assignedTradePosts", "AssignedTradePosts" })
    local count, items, method = runtimeArrayCount(assignedPosts, 64)
    table.insert(attempts, objectFullName(manager) .. "._assignedTradePosts.count=" .. tostring(count or 0) .. " via " .. tostring(method or ""))
    for _, post in ipairs(items or {}) do
      local postObj = runtimeCollectionUnwrap(post)
      if postObj ~= nil and isValidObject(postObj) then
        local key = objectKey(postObj)
        if key ~= "" and assigned[key] ~= true then
          assigned[key] = true
          assignedCount = assignedCount + 1
        end
      end
    end
  end
  return assigned, attempts, #(managers or {}), assignedCount
end

function functionalTraderTradePostMatchScore(tradePost, tokens)
  local text = functionalTraderNormalizeText(objectFullName(tradePost) .. " " .. objectClassFullName(tradePost))
  for index, token in ipairs(tokens or {}) do
    local needle = functionalTraderNormalizeText(token)
    if needle ~= "" and text:find(needle, 1, true) ~= nil then return index end
  end
  return nil
end

function findRegisteredTradePostForFunctionalTrader(actorClass, info, entry)
  local attempts = {}
  local tokens = functionalTraderRouteTokensForActor(actorClass, entry)
  table.insert(attempts, "tokens=" .. table.concat(tokens, ","))
  local _, usedBySource = functionalTraderSiteState()
  local assignedKeys, managerAttempts, managerCount, assignedCount = functionalTraderAssignedTradePostKeys()
  for _, attempt in ipairs(managerAttempts or {}) do table.insert(attempts, "manager." .. attempt) end
  local requireAssigned = (tonumber(managerCount) or 0) > 0 and (tonumber(assignedCount) or 0) > 0
  if not requireAssigned then table.insert(attempts, "manager assignment unavailable; using marker TradePost candidates") end
  local candidates = findAll(tradePostClassesForLookup())
  table.insert(attempts, "tradePostCandidates.count=" .. tostring(#(candidates or {})))
  local best = nil
  local bestScore = nil
  local bestRouteClass = ""
  for _, tradePost in ipairs(candidates or {}) do
    local key = objectKey(tradePost)
    if (not requireAssigned) or assignedKeys[key] then
      local matchScore = functionalTraderTradePostMatchScore(tradePost, tokens)
      if matchScore ~= nil then
        local fullName = objectFullName(tradePost)
        local distance = runtimeDistanceToInfo(tradePost, info or {})
        local reusePenalty = usedBySource[fullName] ~= nil and 100000000 or 0
        local score = reusePenalty + (matchScore * 1000000) + math.floor(distance or 0)
        table.insert(attempts, "candidate=" .. fullName .. " score=" .. tostring(score) .. " reused=" .. tostring(usedBySource[fullName] ~= nil))
        if best == nil or score < (bestScore or score + 1) then
          best, bestScore = tradePost, score
          bestRouteClass = tokens[matchScore] or ""
        end
      end
    end
  end
  if best ~= nil then return best, "registered-tradepost:" .. tostring(bestRouteClass), attempts, bestRouteClass end
  return nil, "registered TradePost не найден для " .. table.concat(tokens, ","), attempts, ""
end

FUNCTIONAL_TRADER_RESTORED_SPAWNED_SITES = FUNCTIONAL_TRADER_RESTORED_SPAWNED_SITES or {}

function runtimeShortClassNameFromObject(obj)
  local full = objectClassFullName(obj)
  local short = tostring(full or ""):match("%.([^%.%s]+)$") or tostring(full or ""):match("([^/%s]+)$") or ""
  short = short:gsub("^Default__", "")
  return actorSummonToken(short)
end

function findTradePostManagerForTradePost(tradePost)
  local attempts = {}
  if tradePost == nil or not isValidObject(tradePost) then return nil, "tradepost missing", attempts end
  local tradePostKey = objectKey(tradePost)
  local managers = findAllTradeOutpostManagers()
  table.insert(attempts, "TradeOutpostManager.count=" .. tostring(#(managers or {})))
  local tradePostToken = tradeOutpostLevelToken(tradePost)
  local tokenFallback = nil
  for _, manager in ipairs(managers or {}) do
    if tokenFallback == nil and tradePostToken ~= "" and tradeOutpostLevelToken(manager) == tradePostToken then
      tokenFallback = manager
    end
    local assignedPosts = firstProp(manager, { "_assignedTradePosts", "AssignedTradePosts" })
    local count, items, method = runtimeArrayCount(assignedPosts, 64)
    table.insert(attempts, objectFullName(manager) .. "._assignedTradePosts.count=" .. tostring(count or 0) .. " via " .. tostring(method or ""))
    for _, post in ipairs(items or {}) do
      local postObj = runtimeCollectionUnwrap(post)
      if postObj ~= nil and isValidObject(postObj) and objectKey(postObj) == tradePostKey then
        return manager, "assigned-manager:" .. objectFullName(manager), attempts
      end
    end
  end
  if tokenFallback ~= nil and isValidObject(tokenFallback) then
    return tokenFallback, "level-token-manager:" .. tostring(tradePostToken), attempts
  end
  return nil, "manager not found for " .. objectFullName(tradePost), attempts
end

function findTradePostManagerByFullName(fullName)
  local target = tostring(fullName or "")
  if target == "" then return nil, "manager fullName empty", {} end
  local attempts = {}
  local managers = findAllTradeOutpostManagers()
  table.insert(attempts, "TradeOutpostManager.count=" .. tostring(#(managers or {})))
  for _, manager in ipairs(managers or {}) do
    if objectFullName(manager) == target then return manager, "manager-full-name", attempts end
  end
  return nil, "manager not found by fullName", attempts
end

function findTradePostByFullName(fullName)
  local target = tostring(fullName or "")
  if target == "" then return nil, "tradePost fullName empty", {} end
  local attempts = {}
  local tradePosts = findAll(tradePostClassesForLookup())
  table.insert(attempts, "tradePostCandidates.count=" .. tostring(#(tradePosts or {})))
  for _, tradePost in ipairs(tradePosts or {}) do
    if objectFullName(tradePost) == target then return tradePost, "tradepost-full-name", attempts end
  end
  return nil, "tradePost not found by fullName", attempts
end

function spawnActorDirectAtLocation(actorClass, loc, yaw)
  local actorClassObject, loadRoute, loadAttempts = loadActorClassForSpawn(actorClass)
  local attempts = loadAttempts or {}
  if actorClassObject == nil or not isValidObject(actorClassObject) then
    return false, tostring(loadRoute or "класс актора не загрузился"), attempts, nil
  end
  local world = worldFor({})
  if world == nil or not isValidObject(world) then return false, "world unresolved", attempts, nil end
  local rot = { Pitch = 0, Yaw = tonumber(yaw) or 0, Roll = 0 }
  local okCall, actor = safeCall(world, "SpawnActor", actorClassObject, loc, rot)
  table.insert(attempts, "world.SpawnActorAt(3)=" .. (okCall and (isValidObject(actor) and "ok" or "nil") or tostring(actor)))
  if okCall and actor ~= nil and isValidObject(actor) then return true, "world.SpawnActorAt:" .. tostring(loadRoute or ""), attempts, actor end
  okCall, actor = safeCall(world, "SpawnActor", actorClassObject, loc)
  table.insert(attempts, "world.SpawnActorAt(2)=" .. (okCall and (isValidObject(actor) and "ok" or "nil") or tostring(actor)))
  if okCall and actor ~= nil and isValidObject(actor) then return true, "world.SpawnActorAt:" .. tostring(loadRoute or ""), attempts, actor end
  return false, "World.SpawnActorAt не создал актор", attempts, nil
end

function registerSpawnedTradePostWithManager(spawnedTradePost, manager)
  local attempts = {}
  if spawnedTradePost == nil or not isValidObject(spawnedTradePost) then return false, "spawned tradepost missing", attempts end
  if manager == nil or not isValidObject(manager) then return false, "TradeOutpostManager missing", attempts end
  if not configBool("bridge-safety", { "AllowFunctionalTraderSpawnedTradePostRegistration", "allowFunctionalTraderSpawnedTradePostRegistration" }, false) then
    table.insert(attempts, "spawned TradePost manager registration disabled")
    return false, "bridge-safety disabled spawned TradePost registration", attempts
  end
  local okHidden, errHidden = safeCall(spawnedTradePost, "SetActorHiddenInGame", false)
  table.insert(attempts, "SetActorHiddenInGame=false:" .. (okHidden and "ok" or tostring(errHidden)))
  local okCollision, errCollision = safeCall(spawnedTradePost, "SetActorEnableCollision", true)
  table.insert(attempts, "SetActorEnableCollision=true:" .. (okCollision and "ok" or tostring(errCollision)))
  local okRep, errRep = safeCall(spawnedTradePost, "SetReplicates", true)
  table.insert(attempts, "SetReplicates=true:" .. (okRep and "ok" or tostring(errRep)))
  local okRepMove, errRepMove = safeCall(spawnedTradePost, "SetReplicateMovement", true)
  table.insert(attempts, "SetReplicateMovement=true:" .. (okRepMove and "ok" or tostring(errRepMove)))
  local componentAttempts = forceActorComponentsVisibleAndReplicated(spawnedTradePost)
  for _, attempt in ipairs(componentAttempts or {}) do table.insert(attempts, "component." .. tostring(attempt)) end
  local assignedPosts = firstProp(manager, { "_assignedTradePosts", "AssignedTradePosts" })
  local okAdd, addRoute, addAttempts = addRuntimeArrayObject(assignedPosts, spawnedTradePost)
  table.insert(attempts, "_assignedTradePosts." .. tostring(addRoute) .. "=" .. tostring(okAdd))
  for _, attempt in ipairs(addAttempts or {}) do table.insert(attempts, "_assignedTradePosts." .. tostring(attempt)) end
  local assignedNow, managerDetail, managerAttempts = tradePostOutpostManagerAssigned(spawnedTradePost)
  for _, attempt in ipairs(managerAttempts or {}) do table.insert(attempts, "verify." .. tostring(attempt)) end
  local okDorm, errDorm = safeCall(spawnedTradePost, "FlushNetDormancy")
  table.insert(attempts, "FlushNetDormancy=" .. (okDorm and "ok" or tostring(errDorm)))
  local okForce, errForce = safeCall(spawnedTradePost, "ForceNetUpdate")
  table.insert(attempts, "ForceNetUpdate=" .. (okForce and "ok" or tostring(errForce)))
  return assignedNow, tostring(managerDetail), attempts
end

function rememberFunctionalTraderSpawnedSite(actorClass, spawnedClass, manager, spawnedTradePost, loc, yaw, traderClass, linkedTradePost, spawnedTrader)
  if configBool("bridge-safety", { "EnableFunctionalTraderSitePersistence", "enableFunctionalTraderSitePersistence" }, false) ~= true then return false end
  if spawnedTradePost == nil or not isValidObject(spawnedTradePost) then return false end
  local siteId = tostring(os.time()) .. "-" .. tostring(objectKey(spawnedTrader or spawnedTradePost))
  local record = '{"utc":' .. js(nowUtc()) ..
    ',"siteId":' .. js(siteId) ..
    ',"active":true' ..
    ',"actorClass":' .. js(actorClass or "") ..
    ',"spawnedClass":' .. js(spawnedClass or "") ..
    ',"traderClass":' .. js(traderClass or "") ..
    ',"managerFullName":' .. js(objectFullName(manager)) ..
    ',"spawnedFullName":' .. js(objectFullName(spawnedTradePost)) ..
    ',"linkedTradePostFullName":' .. js(objectFullName(linkedTradePost)) ..
    ',"spawnedTraderFullName":' .. js(objectFullName(spawnedTrader)) ..
    ',"x":' .. tostring(tonumber((loc or {}).X) or 0) ..
    ',"y":' .. tostring(tonumber((loc or {}).Y) or 0) ..
    ',"z":' .. tostring(tonumber((loc or {}).Z) or 0) ..
    ',"yaw":' .. tostring(tonumber(yaw) or 0) .. '}'
  return appendJsonArray(FUNCTIONAL_TRADER_SPAWNED_SITES_FILE, record, 1024 * 1024)
end

function functionalTraderSpawnedSiteState()
  local text = normalizeJsonArrayText(readAll(FUNCTIONAL_TRADER_SPAWNED_SITES_FILE) or "[]", 1024 * 1024)
  local rows = {}
  for record in text:gmatch("%b{}") do
    local spawnedClass = extractStringAny(record, { "spawnedClass", "SpawnedClass", "routeClass", "RouteClass" }) or ""
    if spawnedClass ~= "" then
      table.insert(rows, {
        raw = record,
        siteId = extractStringAny(record, { "siteId", "SiteId", "id", "Id" }) or "",
        active = extractBoolAny(record, { "active", "Active" }, true) ~= false,
        actorClass = extractStringAny(record, { "actorClass", "ActorClass" }) or "",
        spawnedClass = spawnedClass,
        traderClass = extractStringAny(record, { "traderClass", "TraderClass" }) or "",
        managerFullName = extractStringAny(record, { "managerFullName", "ManagerFullName" }) or "",
        linkedTradePostFullName = extractStringAny(record, { "linkedTradePostFullName", "LinkedTradePostFullName", "donorTradePostFullName", "DonorTradePostFullName" }) or "",
        x = extractNumberAny(record, { "x", "X" }, nil),
        y = extractNumberAny(record, { "y", "Y" }, nil),
        z = extractNumberAny(record, { "z", "Z" }, nil),
        yaw = extractNumberAny(record, { "yaw", "Yaw" }, nil)
      })
    end
  end
  return rows
end

function restoreFunctionalTraderSpawnedSites()
  if not configBool("bridge-safety", { "EnableFunctionalTraderSiteRestore", "enableFunctionalTraderSiteRestore" }, false) then return false, "disabled" end
  if configBool("bridge-safety", { "EnableFunctionalTraderSitePersistence", "enableFunctionalTraderSitePersistence" }, false) ~= true then return false, "persistence disabled" end
  local rows = functionalTraderSpawnedSiteState()
  local attempts = {}
  local total = 0
  local restored = 0
  for index, site in ipairs(rows or {}) do
    local siteId = site.siteId ~= "" and site.siteId or ("row-" .. tostring(index))
    if site.active and site.x ~= nil and site.y ~= nil and site.z ~= nil and not FUNCTIONAL_TRADER_RESTORED_SPAWNED_SITES[siteId] then
      total = total + 1
      local loc = { X = site.x, Y = site.y, Z = site.z }
      if tostring(site.traderClass or "") ~= "" and tostring(site.linkedTradePostFullName or "") ~= "" then
        local tradePost, tradePostDetail, tradePostAttempts = findTradePostByFullName(site.linkedTradePostFullName)
        for _, attempt in ipairs(tradePostAttempts or {}) do table.insert(attempts, "site." .. siteId .. ".tradePost." .. tostring(attempt)) end
        if tradePost ~= nil and isValidObject(tradePost) then
          local okLinked, linkedDetail, linkedAttempts = spawnFunctionalLinkedTraderActorAtLocation(site.traderClass, site.actorClass, tradePost, loc, site.yaw, "restore." .. siteId)
          for _, attempt in ipairs(linkedAttempts or {}) do table.insert(attempts, "site." .. siteId .. ".linked." .. tostring(attempt)) end
          if okLinked then
            FUNCTIONAL_TRADER_RESTORED_SPAWNED_SITES[siteId] = true
            restored = restored + 1
          else
            table.insert(attempts, "site." .. siteId .. ".linked failed=" .. tostring(linkedDetail))
          end
        else
          table.insert(attempts, "site." .. siteId .. ".tradePost failed=" .. tostring(tradePostDetail))
        end
      else
        local manager, managerDetail, managerAttempts = findTradePostManagerByFullName(site.managerFullName)
        for _, attempt in ipairs(managerAttempts or {}) do table.insert(attempts, "site." .. siteId .. ".manager." .. tostring(attempt)) end
        if manager ~= nil and isValidObject(manager) then
          local okSpawn, spawnDetail, spawnAttempts, spawned = spawnActorDirectAtLocation(site.spawnedClass, loc, site.yaw)
          for _, attempt in ipairs(spawnAttempts or {}) do table.insert(attempts, "site." .. siteId .. ".spawn." .. tostring(attempt)) end
          if okSpawn and spawned ~= nil and isValidObject(spawned) then
            local okRegister, registerDetail, registerAttempts = registerSpawnedTradePostWithManager(spawned, manager)
            for _, attempt in ipairs(registerAttempts or {}) do table.insert(attempts, "site." .. siteId .. ".register." .. tostring(attempt)) end
            if okRegister then
              FUNCTIONAL_TRADER_RESTORED_SPAWNED_SITES[siteId] = true
              restored = restored + 1
            else
              destroySpawnedItem(spawned)
              table.insert(attempts, "site." .. siteId .. ".register failed=" .. tostring(registerDetail))
            end
          else
            table.insert(attempts, "site." .. siteId .. ".spawn failed=" .. tostring(spawnDetail))
          end
        else
          table.insert(attempts, "site." .. siteId .. ".manager missing=" .. tostring(managerDetail))
        end
      end
    end
  end
  if total > 0 then
    appendActionEvent("functional_trader_spawned_restore", restored == total, nil,
      "Functional spawned trader restore: " .. tostring(restored) .. "/" .. tostring(total),
      '{"restored":' .. tostring(restored) .. ',"total":' .. tostring(total) .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
  end
  return restored == total, "spawned restored " .. tostring(restored) .. "/" .. tostring(total)
end

function spawnFunctionalRegisteredTradePostCloneForInfo(actorClass, info, entry, attempts)
  attempts = attempts or {}
  table.insert(attempts, "functional trader route=spawned-registered-tradepost")
  local donorTradePost, routeDetail, findAttempts = findRegisteredTradePostForFunctionalTrader(actorClass, info, entry)
  for _, attempt in ipairs(findAttempts or {}) do table.insert(attempts, "find." .. tostring(attempt)) end
  if donorTradePost == nil or not isValidObject(donorTradePost) then
    local data = '{"actorClass":' .. js(actorClass) ..
      ',"route":"functional-spawned-registered-tradepost"' ..
      ',"ok":false' ..
      ',"detail":' .. js(routeDetail or "") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader не создан: donor TradePost/economy actor не найден. " .. tostring(routeDetail), data)
    return false, "Functional trader не создан: " .. tostring(routeDetail), data
  end
  local manager, managerDetail, managerAttempts = findTradePostManagerForTradePost(donorTradePost)
  for _, attempt in ipairs(managerAttempts or {}) do table.insert(attempts, "manager." .. tostring(attempt)) end
  if manager == nil or not isValidObject(manager) then
    local data = '{"actorClass":' .. js(actorClass) ..
      ',"route":"functional-spawned-registered-tradepost"' ..
      ',"donor":' .. nativeProbeObjectJson("donorTradePost", donorTradePost, "registered-level-actor", {}) ..
      ',"ok":false' ..
      ',"detail":' .. js(managerDetail or "") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader не создан: donor TradePost не привязан к TradeOutpostManager. " .. tostring(managerDetail), data)
    return false, "Functional trader не создан: " .. tostring(managerDetail), data
  end
  local spawnedClass = runtimeShortClassNameFromObject(donorTradePost)
  if spawnedClass == "" then spawnedClass = actorRouteShortClass(actorClass, entry) end
  if spawnedClass == "" then
    local data = '{"actorClass":' .. js(actorClass) ..
      ',"route":"functional-spawned-registered-tradepost"' ..
      ',"ok":false' ..
      ',"detail":"spawnedClass unresolved"' ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader не создан: не удалось определить класс TradePost donor.", data)
    return false, "Functional trader не создан: TradePost class unresolved", data
  end
  local loc, yaw = functionalTraderTargetLocation(info)
  local okSpawn, spawnDetail, spawnAttempts, spawnedTradePost = spawnActorDirectAtLocation(spawnedClass, loc, yaw)
  for _, attempt in ipairs(spawnAttempts or {}) do table.insert(attempts, "spawn." .. tostring(attempt)) end
  if not okSpawn or spawnedTradePost == nil or not isValidObject(spawnedTradePost) then
    local data = '{"actorClass":' .. js(actorClass) ..
      ',"spawnedClass":' .. js(spawnedClass) ..
      ',"route":"functional-spawned-registered-tradepost"' ..
      ',"ok":false' ..
      ',"detail":' .. js(spawnDetail or "") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader не создан: SpawnActor TradePost не сработал. " .. tostring(spawnDetail), data)
    return false, "Functional trader не создан: " .. tostring(spawnDetail), data
  end
  local okRegister, registerDetail, registerAttempts = registerSpawnedTradePostWithManager(spawnedTradePost, manager)
  for _, attempt in ipairs(registerAttempts or {}) do table.insert(attempts, "register." .. tostring(attempt)) end
  local initOk, initDetail, initAttempts = initializeSummonedTradePostActor(spawnedTradePost, spawnedClass)
  for _, attempt in ipairs(initAttempts or {}) do table.insert(attempts, "init." .. tostring(attempt)) end
  local remembered = false
  if okRegister and initOk then remembered = rememberFunctionalTraderSpawnedSite(actorClass, spawnedClass, manager, spawnedTradePost, loc, yaw) end
  local data = '{"actorClass":' .. js(actorClass) ..
    ',"spawnedClass":' .. js(spawnedClass) ..
    ',"route":"functional-spawned-registered-tradepost"' ..
    ',"routeDetail":' .. js(routeDetail or "") ..
    ',"donor":' .. nativeProbeObjectJson("donorTradePost", donorTradePost, "registered-level-actor", {}) ..
    ',"spawned":' .. nativeProbeObjectJson("spawnedTradePost", spawnedTradePost, "spawned-runtime-actor", {}) ..
    ',"manager":' .. nativeProbeObjectJson("tradeOutpostManager", manager, "registered-manager", {}) ..
    ',"registered":' .. (okRegister and "true" or "false") ..
    ',"initOk":' .. (initOk and "true" or "false") ..
    ',"remembered":' .. (remembered and "true" or "false") ..
    ',"target":{"x":' .. tostring(tonumber(loc.X) or 0) .. ',"y":' .. tostring(tonumber(loc.Y) or 0) .. ',"z":' .. tostring(tonumber(loc.Z) or 0) .. ',"yaw":' .. tostring(tonumber(yaw) or 0) .. '}' ..
    ',"detail":' .. js(tostring(registerDetail or "") .. "; " .. tostring(initDetail or "")) ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
  if okRegister and initOk then
    appendActionEvent("spawn_actor", true, info, "Functional trader создан как новый registered TradePost runtime actor: " .. tostring(spawnedClass), data)
    return true, "Functional trader создан как registered TradePost: " .. tostring(spawnedClass), data
  end
  destroySpawnedItem(spawnedTradePost)
  appendActionEvent("spawn_actor", false, info, "Functional trader route не подтверждён; spawned TradePost удалён: " .. tostring(registerDetail) .. "; " .. tostring(initDetail), data)
  return false, "Functional trader route не подтверждён: " .. tostring(registerDetail) .. "; " .. tostring(initDetail), data
end

function functionalTraderTargetLocation(info)
  local x, y, z = vectorOf((info or {}).pawn)
  local forwardX, forwardY = forwardVectorOf((info or {}).pawn)
  if forwardX == nil or forwardY == nil then forwardX, forwardY = forwardVectorOf((info or {}).pc) end
  if forwardX == nil or forwardY == nil then
    local yawFallback = rotationYawOf((info or {}).pc) or rotationYawOf((info or {}).pawn) or 0
    local radians = math.rad(yawFallback)
    forwardX, forwardY = math.cos(radians), math.sin(radians)
  end
  local distance = math.max(200, math.min(configNumber("bridge-safety", { "FunctionalTraderForwardDistance", "functionalTraderForwardDistance" }, 850), 4000))
  local lift = math.max(0, math.min(configNumber("bridge-safety", { "FunctionalTraderLiftZ", "functionalTraderLiftZ" }, 20), 300))
  local yaw = rotationYawOf((info or {}).pc) or rotationYawOf((info or {}).pawn) or 0
  return { X = x + forwardX * distance, Y = y + forwardY * distance, Z = z + lift }, yaw
end

function functionalTraderLifecycleBlockedForInfo(actorClass, info, attempts, route)
  attempts = attempts or {}
  table.insert(attempts, "functional trader route=blocked-native-lifecycle-required")
  local message = "Functional trader spawn заблокирован: Lua/Summon/World.SpawnActor уже проверены и дают server-side ghost/NPC без товара. Нужен native C++ lifecycle wrapper через TradeOutpostManager/AConZEconomyManager."
  local data = '{"actorClass":' .. js(actorClass or "") ..
    ',"route":' .. js(route or "blocked-native-lifecycle-required") ..
    ',"ok":false' ..
    ',"blocked":true' ..
    ',"requiresNativeLifecycle":true' ..
    ',"luaRoutesKnownBad":true' ..
    ',"proofRequired":"client-visible trader + working trade UI stock/sell + no server frame spike"' ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
  appendActionEvent("spawn_actor", false, info, message, data)
  return false, message, data
end

function moveRuntimeActorToLocation(actor, loc, yaw, attempts, label)
  if actor == nil or not isValidObject(actor) then return false, "actor missing" end
  local prefix = tostring(label or "actor")
  local beforeX, beforeY, beforeZ = vectorOf(actor)
  table.insert(attempts, prefix .. ".before=" .. tostring(beforeX) .. "," .. tostring(beforeY) .. "," .. tostring(beforeZ))
  local okHidden, errHidden = safeCall(actor, "SetActorHiddenInGame", false)
  table.insert(attempts, prefix .. ".SetActorHiddenInGame=false:" .. (okHidden and "ok" or tostring(errHidden)))
  local okCollision, errCollision = safeCall(actor, "SetActorEnableCollision", true)
  table.insert(attempts, prefix .. ".SetActorEnableCollision=true:" .. (okCollision and "ok" or tostring(errCollision)))
  local okRep, errRep = safeCall(actor, "SetReplicates", true)
  table.insert(attempts, prefix .. ".SetReplicates=true:" .. (okRep and "ok" or tostring(errRep)))
  local okRepMove, errRepMove = safeCall(actor, "SetReplicateMovement", true)
  table.insert(attempts, prefix .. ".SetReplicateMovement=true:" .. (okRepMove and "ok" or tostring(errRepMove)))
  local okDorm, errDorm = safeCall(actor, "FlushNetDormancy")
  table.insert(attempts, prefix .. ".FlushNetDormancy=" .. (okDorm and "ok" or tostring(errDorm)))
  local okMove, errMove = safeCall(actor, "K2_SetActorLocation", loc, false, {}, true)
  table.insert(attempts, prefix .. ".K2_SetActorLocation=" .. (okMove and "ok" or tostring(errMove)))
  if not okMove then
    okMove, errMove = safeCall(actor, "SetActorLocation", loc)
    table.insert(attempts, prefix .. ".SetActorLocation=" .. (okMove and "ok" or tostring(errMove)))
  end
  if yaw ~= nil then
    local rot = { Pitch = 0, Yaw = tonumber(yaw) or 0, Roll = 0 }
    local okRot, errRot = safeCall(actor, "K2_SetActorRotation", rot, false)
    table.insert(attempts, prefix .. ".K2_SetActorRotation=" .. (okRot and "ok" or tostring(errRot)))
    if not okRot then
      okRot, errRot = safeCall(actor, "SetActorRotation", rot)
      table.insert(attempts, prefix .. ".SetActorRotation=" .. (okRot and "ok" or tostring(errRot)))
    end
  end
  local okForce, errForce = safeCall(actor, "ForceNetUpdate")
  table.insert(attempts, prefix .. ".ForceNetUpdate=" .. (okForce and "ok" or tostring(errForce)))
  local afterX, afterY, afterZ = vectorOf(actor)
  table.insert(attempts, prefix .. ".after=" .. tostring(afterX) .. "," .. tostring(afterY) .. "," .. tostring(afterZ))
  return okMove, okMove and "moved" or tostring(errMove or "move failed")
end

function tradePostPersonalityForTrader(tradePost, actorClass, targetTrader, attempts)
  attempts = attempts or {}
  if tradePost == nil or not isValidObject(tradePost) then return nil, "tradepost missing" end
  local hint = traderTypeHint(actorClass, targetTrader)
  local markers = firstProp(tradePost, { "_traderMarkers", "TraderMarkers" })
  local markerCount, markerItems, markerMethod = runtimeArrayCount(markers, 16)
  table.insert(attempts, "linkedTradePost._traderMarkers.count=" .. tostring(markerCount or 0) .. " via " .. tostring(markerMethod or ""))
  local fallback = nil
  local fallbackText = ""
  for _, marker in ipairs(markerItems or {}) do
    local personality = tradePostMarkerPersonality(marker)
    if personality ~= nil and isValidObject(personality) then
      local full = objectFullName(personality)
      if fallback == nil then
        fallback, fallbackText = personality, full
      end
      if traderPersonalityMatchesHint(personality, hint) then
        return personality, "tradepost-marker:hint:" .. tostring(hint) .. ":" .. full
      end
    end
  end
  if fallback ~= nil and isValidObject(fallback) then
    return fallback, "tradepost-marker:fallback:" .. tostring(fallbackText)
  end
  return nil, "tradepost marker personality not found"
end

function tradePostMarkerForTrader(tradePost, actorClass, targetTrader, attempts)
  attempts = attempts or {}
  if tradePost == nil or not isValidObject(tradePost) then return nil, nil, "tradepost missing" end
  local hint = traderTypeHint(actorClass, targetTrader)
  local markers = firstProp(tradePost, { "_traderMarkers", "TraderMarkers" })
  local markerCount, markerItems, markerMethod = runtimeArrayCount(markers, 16)
  table.insert(attempts, "markerRoute._traderMarkers.count=" .. tostring(markerCount or 0) .. " via " .. tostring(markerMethod or ""))
  local fallbackMarker = nil
  local fallbackPersonality = nil
  local fallbackText = ""
  for index, marker in ipairs(markerItems or {}) do
    local personality = tradePostMarkerPersonality(marker)
    if personality ~= nil and isValidObject(personality) then
      local full = objectFullName(personality)
      table.insert(attempts, "markerRoute.marker#" .. tostring(index) .. ".personality=" .. full)
      if fallbackMarker == nil then
        fallbackMarker, fallbackPersonality, fallbackText = marker, personality, full
      end
      if traderPersonalityMatchesHint(personality, hint) then
        return marker, personality, "tradepost-marker:hint:" .. tostring(hint) .. ":" .. full
      end
    else
      table.insert(attempts, "markerRoute.marker#" .. tostring(index) .. ".personality=missing")
    end
  end
  if fallbackMarker ~= nil then
    return fallbackMarker, fallbackPersonality, "tradepost-marker:fallback:" .. tostring(fallbackText)
  end
  return nil, nil, "tradepost marker not found"
end

function functionalTraderNumber(value)
  local numberValue = tonumber(value) or 0
  if numberValue ~= numberValue or numberValue == math.huge or numberValue == -math.huge then numberValue = 0 end
  return string.format("%.6f", numberValue)
end

function functionalTraderTransformImportText(loc, yaw)
  local quat = nativeBaseElementQuatFromYaw(yaw)
  local target = loc or { X = 0, Y = 0, Z = 0 }
  return "(Rotation=(X=" .. functionalTraderNumber(quat.X) ..
    ",Y=" .. functionalTraderNumber(quat.Y) ..
    ",Z=" .. functionalTraderNumber(quat.Z) ..
    ",W=" .. functionalTraderNumber(quat.W) ..
    "),Translation=(X=" .. functionalTraderNumber(target.X) ..
    ",Y=" .. functionalTraderNumber(target.Y) ..
    ",Z=" .. functionalTraderNumber(target.Z) ..
    "),Scale3D=(X=1.000000,Y=1.000000,Z=1.000000))"
end

function setRuntimeStructPropertyViaImportText(obj, propertyName, importText)
  if obj == nil or not isValidObject(obj) then return false, "object missing" end
  local prop, propRoute = findRuntimePropertyOnObject(obj, propertyName)
  if prop == nil then
    local okClass, cls = pcall(function() return obj:GetClass() end)
    if okClass and cls ~= nil and isValidObject(cls) then
      prop, propRoute = findRuntimePropertyInClassTree(cls, propertyName)
      if prop == nil then prop, propRoute = findRuntimePropertyByForEach(cls, propertyName) end
    end
  end
  if prop == nil then return false, tostring(propRoute or "property missing") end
  local okPtr, ptr = pcall(function() return prop:ContainerPtrToValuePtr(obj, 0) end)
  if not okPtr or ptr == nil then return false, "value ptr missing " .. tostring(propertyName) .. ": " .. tostring(ptr) end
  local text = tostring(importText or "")
  if text == "" then return false, "import text empty" end
  local okImport, errImport = pcall(function() return prop:ImportText(text, ptr, 0, obj) end)
  if okImport then return true, "ImportText(" .. tostring(propertyName) .. ") via " .. tostring(propRoute) .. "=" .. text end
  return false, tostring(errImport)
end

function functionalTraderTransformOffset(loc, forwardX, forwardY, sideOffset, forwardOffset, liftOffset)
  local x = tonumber((loc or {}).X) or 0
  local y = tonumber((loc or {}).Y) or 0
  local z = tonumber((loc or {}).Z) or 0
  local fx = tonumber(forwardX) or 1
  local fy = tonumber(forwardY) or 0
  local sx = -fy
  local sy = fx
  return {
    X = x + fx * (tonumber(forwardOffset) or 0) + sx * (tonumber(sideOffset) or 0),
    Y = y + fy * (tonumber(forwardOffset) or 0) + sy * (tonumber(sideOffset) or 0),
    Z = z + (tonumber(liftOffset) or 0)
  }
end

function functionalTraderSetMarkerTransform(marker, loc, yaw, attempts)
  attempts = attempts or {}
  table.insert(attempts, "marker.FTransform.ImportText=blocked: UE4SS Lua struct write corrupts FTraderMarker transforms and can crash SCUMServer; requires native C++ wrapper")
  return false, "FTraderMarker FTransform Lua write blocked: requires native C++ wrapper", attempts
end

function nearestRuntimeTraderForMarkerRoute(actorClass, targetLoc, maxDistance)
  local best = nil
  local bestDistance = nil
  local classes = { actorClass, actorSummonToken(actorClass), "Trader", "ATrader" }
  for _, actor in ipairs(findAll(classes)) do
    if actor ~= nil and isValidObject(actor) then
      local x, y, z = vectorOf(actor)
      local dx = (tonumber(x) or 0) - (tonumber((targetLoc or {}).X) or 0)
      local dy = (tonumber(y) or 0) - (tonumber((targetLoc or {}).Y) or 0)
      local dz = (tonumber(z) or 0) - (tonumber((targetLoc or {}).Z) or 0)
      local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
      if dist <= (tonumber(maxDistance) or 5000) and (best == nil or dist < (bestDistance or dist + 1)) then
        best, bestDistance = actor, dist
      end
    end
  end
  return best, bestDistance
end

function scheduleFunctionalTraderMarkerVerification(info, actorClass, tradePostFullName, targetLoc, yaw, personality, requestTag)
  local delayMs = math.max(1500, math.min(math.floor(configNumber("bridge-safety", { "FunctionalTraderMarkerVerifyDelayMs", "functionalTraderMarkerVerifyDelayMs" }, 6500)), 20000))
  deferGame(delayMs, function()
    local live = resolvePlayerInfo((info or {}).steam, (info or {}).name, info, (info or {}).runtimeKey) or info
    local actor, distance = nearestRuntimeTraderForMarkerRoute(actorClass, targetLoc, configNumber("bridge-safety", { "FunctionalTraderMarkerVerifyRadius", "functionalTraderMarkerVerifyRadius" }, 9000))
    local actorPersonality = traderPersonalityObject(actor)
    local tradePost = findTradePostByFullName(tradePostFullName)
    local spawnedTraders = firstProp(tradePost, { "_spawnedTraders", "SpawnedTraders" })
    local spawnedCount = runtimeArrayCount(spawnedTraders, 8)
    local okActor = actor ~= nil and isValidObject(actor)
    local okPersonality = actorPersonality ~= nil and isValidObject(actorPersonality)
    local data = '{"actorClass":' .. js(actorClass or "") ..
      ',"route":"functional-trader-marker-lifecycle-verify"' ..
      ',"requestTag":' .. js(requestTag or "") ..
      ',"actor":' .. nativeProbeObjectJson("trader", actor, "nearest-runtime-after-marker-route", {}) ..
      ',"distance":' .. tostring(math.floor(tonumber(distance) or -1)) ..
      ',"personality":' .. nativeProbeObjectJson("personality", actorPersonality, "_traderPersonalityDataAsset", {}) ..
      ',"expectedPersonality":' .. nativeProbeObjectJson("expectedPersonality", personality, "marker", {}) ..
      ',"tradePost":' .. nativeProbeObjectJson("tradePost", tradePost, "stock-tradepost", {}) ..
      ',"spawnedTradersCount":' .. tostring(spawnedCount or 0) ..
      ',"target":{"x":' .. tostring(tonumber((targetLoc or {}).X) or 0) .. ',"y":' .. tostring(tonumber((targetLoc or {}).Y) or 0) .. ',"z":' .. tostring(tonumber((targetLoc or {}).Z) or 0) .. ',"yaw":' .. tostring(tonumber(yaw) or 0) .. '}}'
    appendActionEvent("functional_trader_marker_verify", okActor and okPersonality, live,
      okActor and okPersonality and "Trader lifecycle spawned runtime NPC near marker target." or "Trader lifecycle did not spawn/confirm runtime NPC near marker target.",
      data)
  end)
  return delayMs
end

function ensureTraderPersonalityDataAsset(actor, personality, attempts)
  attempts = attempts or {}
  if actor == nil or not isValidObject(actor) then return false, "actor missing" end
  if personality == nil or not isValidObject(personality) then return false, "personality missing" end
  local existingPersonality = traderPersonalityObject(actor)
  if existingPersonality ~= nil and isValidObject(existingPersonality) then
    table.insert(attempts, "_traderPersonalityDataAsset already present=" .. objectFullName(existingPersonality))
    return true, "already-present:" .. objectFullName(existingPersonality)
  end
  local okReflect, detailReflect = setRuntimeObjectPropertyViaReflection(actor, "_traderPersonalityDataAsset", personality)
  table.insert(attempts, "_traderPersonalityDataAsset.ImportText=" .. (okReflect and "ok:" or "fail:") .. tostring(detailReflect))
  if not okReflect and configBool("bridge-safety", { "AllowFunctionalTraderWeakObjectDirectSet", "allowFunctionalTraderWeakObjectDirectSet" }, false) then
    local okDirect, errDirect = pcall(function() actor._traderPersonalityDataAsset = personality end)
    table.insert(attempts, "_traderPersonalityDataAsset.direct-set=" .. (okDirect and "ok" or tostring(errDirect)))
    local okDirect2, errDirect2 = pcall(function() actor.TraderPersonalityDataAsset = personality end)
    table.insert(attempts, "TraderPersonalityDataAsset.direct-set=" .. (okDirect2 and "ok" or tostring(errDirect2)))
  end
  local afterPersonality = traderPersonalityObject(actor)
  if afterPersonality ~= nil and isValidObject(afterPersonality) then
    return true, "personality=" .. objectFullName(afterPersonality) .. "; persistentId=" .. tostring(traderPersonalityRuntimeId(afterPersonality))
  end
  return false, "TraderPersonality copy did not stick"
end

function registerFunctionalLinkedTraderWithTradePost(actor, tradePost, forceRegister)
  local attempts = {}
  if actor == nil or not isValidObject(actor) then return false, "trader missing", attempts end
  if tradePost == nil or not isValidObject(tradePost) then return false, "tradepost missing", attempts end
  if forceRegister ~= true and not configBool("bridge-safety", { "AllowFunctionalTraderLinkedActorRegistration", "allowFunctionalTraderLinkedActorRegistration" }, false) then
    table.insert(attempts, "linked trader registration disabled")
    return false, "bridge-safety disabled linked trader registration", attempts
  end
  if forceRegister == true then table.insert(attempts, "linked trader registration forced by proxy route") end
  local okHidden, errHidden = safeCall(actor, "SetActorHiddenInGame", false)
  table.insert(attempts, "SetActorHiddenInGame=false:" .. (okHidden and "ok" or tostring(errHidden)))
  local okCollision, errCollision = safeCall(actor, "SetActorEnableCollision", true)
  table.insert(attempts, "SetActorEnableCollision=true:" .. (okCollision and "ok" or tostring(errCollision)))
  local okRep, errRep = safeCall(actor, "SetReplicates", true)
  table.insert(attempts, "SetReplicates=true:" .. (okRep and "ok" or tostring(errRep)))
  local okRepMove, errRepMove = safeCall(actor, "SetReplicateMovement", true)
  table.insert(attempts, "SetReplicateMovement=true:" .. (okRepMove and "ok" or tostring(errRepMove)))
  local okDormAwake, errDormAwake = safeCall(actor, "SetNetDormancy", 1)
  table.insert(attempts, "SetNetDormancy(DORM_Awake)=" .. (okDormAwake and "ok" or tostring(errDormAwake)))
  local okAlways, errAlways = pcall(function() actor.bAlwaysRelevant = true end)
  table.insert(attempts, "bAlwaysRelevant=true=" .. (okAlways and "ok" or tostring(errAlways)))
  local okOwnerRel, errOwnerRel = pcall(function() actor.bNetUseOwnerRelevancy = false end)
  table.insert(attempts, "bNetUseOwnerRelevancy=false=" .. (okOwnerRel and "ok" or tostring(errOwnerRel)))
  local okOnlyOwner, errOnlyOwner = pcall(function() actor.bOnlyRelevantToOwner = false end)
  table.insert(attempts, "bOnlyRelevantToOwner=false=" .. (okOnlyOwner and "ok" or tostring(errOnlyOwner)))
  local okCull, errCull = pcall(function() actor.NetCullDistanceSquared = 250000000000 end)
  table.insert(attempts, "NetCullDistanceSquared=250000000000=" .. (okCull and "ok" or tostring(errCull)))
  for _, attempt in ipairs(forceActorComponentsVisibleAndReplicated(actor)) do table.insert(attempts, "component." .. tostring(attempt)) end
  local okOutpost, errOutpost = pcall(function() actor._tradeOutpostBuilding = tradePost end)
  table.insert(attempts, "_tradeOutpostBuilding=" .. (okOutpost and "ok" or tostring(errOutpost)))
  local okOutpost2, errOutpost2 = pcall(function() actor.TradeOutpostBuilding = tradePost end)
  table.insert(attempts, "TradeOutpostBuilding=" .. (okOutpost2 and "ok" or tostring(errOutpost2)))
  local okOriginalLocation, errOriginalLocation = pcall(function()
    local x, y, z = vectorOf(actor)
    actor._originalLocation = { X = x, Y = y, Z = z }
  end)
  table.insert(attempts, "_originalLocation=current=" .. (okOriginalLocation and "ok" or tostring(errOriginalLocation)))
  local okRepOutpost, errRepOutpost = safeCall(actor, "OnRep_TradeOutpostBuilding")
  table.insert(attempts, "OnRep_TradeOutpostBuilding=" .. (okRepOutpost and "ok" or tostring(errRepOutpost)))
  local spawnedTraders = firstProp(tradePost, { "_spawnedTraders", "SpawnedTraders" })
  local okTraders, routeTraders, attemptsTraders = addRuntimeArrayObjectUnique(spawnedTraders, actor, 64)
  table.insert(attempts, "_spawnedTraders." .. tostring(routeTraders) .. "=" .. tostring(okTraders))
  for _, attempt in ipairs(attemptsTraders or {}) do table.insert(attempts, "_spawnedTraders." .. tostring(attempt)) end
  local spawnedSedentary = firstProp(tradePost, { "_spawnedSedentaryNPCs", "SpawnedSedentaryNPCs" })
  local okSedentary, routeSedentary, attemptsSedentary = addRuntimeArrayObjectUnique(spawnedSedentary, actor, 64)
  table.insert(attempts, "_spawnedSedentaryNPCs." .. tostring(routeSedentary) .. "=" .. tostring(okSedentary))
  for _, attempt in ipairs(attemptsSedentary or {}) do table.insert(attempts, "_spawnedSedentaryNPCs." .. tostring(attempt)) end
  local assigned = runtimeCollectionUnwrap(firstProp(actor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" }))
  local assignedOk = assigned ~= nil and isValidObject(assigned) and objectKey(assigned) == objectKey(tradePost)
  local okDorm, errDorm = safeCall(actor, "FlushNetDormancy")
  table.insert(attempts, "FlushNetDormancy=" .. (okDorm and "ok" or tostring(errDorm)))
  local okForce, errForce = safeCall(actor, "ForceNetUpdate")
  table.insert(attempts, "ForceNetUpdate=" .. (okForce and "ok" or tostring(errForce)))
  return assignedOk and (okTraders or okSedentary), "linkedTradePost=" .. objectFullName(tradePost), attempts
end

function initializeFunctionalLinkedTraderActor(actor, actorClass, linkedTradePost, loc, yaw, attempts, forceRegister)
  attempts = attempts or {}
  if actor == nil or not isValidObject(actor) then return false, "runtime trader missing", nil end
  if linkedTradePost == nil or not isValidObject(linkedTradePost) then return false, "linked TradePost missing", nil end
  local personality, personalityDetail = tradePostPersonalityForTrader(linkedTradePost, actorClass, actor, attempts)
  table.insert(attempts, "personalityRoute=" .. tostring(personalityDetail))
  if personality == nil or not isValidObject(personality) then
    return false, "linked TradePost marker personality not found: " .. tostring(personalityDetail), nil
  end
  local okPersonality, personalitySetDetail = ensureTraderPersonalityDataAsset(actor, personality, attempts)
  table.insert(attempts, "personalitySet=" .. tostring(okPersonality) .. ":" .. tostring(personalitySetDetail))
  if not okPersonality then
    return false, tostring(personalitySetDetail), personality
  end
  if loc ~= nil then
    local okMove, moveDetail = moveRuntimeActorToLocation(actor, loc, yaw, attempts, "linkedTrader")
    table.insert(attempts, "linkedTrader.moveDetail=" .. tostring(moveDetail))
    if not okMove then return false, "linked trader move failed: " .. tostring(moveDetail), personality end
  end
  local okRegister, registerDetail, registerAttempts = registerFunctionalLinkedTraderWithTradePost(actor, linkedTradePost, forceRegister)
  for _, attempt in ipairs(registerAttempts or {}) do table.insert(attempts, "linkedRegister." .. tostring(attempt)) end
  local afterPersonality = traderPersonalityObject(actor)
  local afterTradePost = runtimeCollectionUnwrap(firstProp(actor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" }))
  local personalityOk = afterPersonality ~= nil and isValidObject(afterPersonality)
  local tradePostOk = afterTradePost ~= nil and isValidObject(afterTradePost) and objectKey(afterTradePost) == objectKey(linkedTradePost)
  if personalityOk and tradePostOk and okRegister then
    return true, "linked trader actor готов; persistentId=" .. tostring(traderPersonalityRuntimeId(afterPersonality)) .. "; " .. tostring(registerDetail), afterPersonality
  end
  return false, "linked trader не подтверждён: personality=" .. tostring(personalityOk) .. ", tradePost=" .. tostring(tradePostOk) .. ", register=" .. tostring(okRegister) .. "; " .. tostring(registerDetail), afterPersonality
end

function spawnFunctionalLinkedTraderActorAtLocation(traderClass, actorClass, linkedTradePost, loc, yaw, label)
  local attempts = {}
  table.insert(attempts, "functional trader route=linked-trader-actor:" .. tostring(label or "spawn"))
  local okSpawn, spawnDetail, spawnAttempts, actor = spawnActorDirectAtLocation(traderClass, loc, yaw)
  for _, attempt in ipairs(spawnAttempts or {}) do table.insert(attempts, "spawn." .. tostring(attempt)) end
  if not okSpawn or actor == nil or not isValidObject(actor) then
    return false, "linked trader actor spawn failed: " .. tostring(spawnDetail), attempts, nil, nil
  end
  local okInit, initDetail, personality = initializeFunctionalLinkedTraderActor(actor, actorClass or traderClass, linkedTradePost, loc, yaw, attempts)
  if okInit then
    return true, initDetail, attempts, actor, personality
  end
  destroySpawnedItem(actor)
  table.insert(attempts, "destroyActorAfterFailedInit=ok")
  return false, "linked trader actor init failed: " .. tostring(initDetail), attempts, nil, personality
end

function summonFunctionalLinkedTraderActor(actorClass, info, attempts)
  attempts = attempts or {}
  local cm, cmSource = ensureCheatManagerForController((info or {}).pc)
  if cm == nil then return false, "CheatManager недоступен: " .. tostring(cmSource), nil, nil end
  local startedAt = os.clock()
  ensureAdminBypassHooks()
  local beforeObjects, beforeObjectCount = runtimeActorSnapshot(actorClass)
  table.insert(attempts, "summon.runtimeBefore.count=" .. tostring(beforeObjectCount or 0))
  local logStart = fileSize(SERVER_LOG_FILE)
  local beforeStats = latestScumGlobalStatsTail()
  local lastError = "Summon failed"
  local usedCandidate = ""
  for _, attempt in ipairs(preloadActorCatalogForSummon(actorClass)) do table.insert(attempts, "summon." .. tostring(attempt)) end
  for _, candidate in ipairs(actorSummonCandidates(actorClass)) do
    for _, attempt in ipairs(preloadActorClassCandidate(candidate)) do table.insert(attempts, "summon." .. tostring(attempt)) end
    local fstringBypass = enableScopedAdminBypass(350, info, false)
    local okFString, errFString = pcall(function() return cm:Summon(ueString(candidate)) end)
    disableScopedAdminBypass(fstringBypass)
    table.insert(attempts, "summon.CheatManager.Summon(" .. tostring(candidate) .. ")#fstring=" .. (okFString and "ok" or tostring(errFString)))
    if okFString then
      usedCandidate = candidate
      break
    end
    lastError = tostring(errFString)
    local plainBypass = enableScopedAdminBypass(350, info, false)
    local okPlain, errPlain = pcall(function() return cm:Summon(candidate) end)
    disableScopedAdminBypass(plainBypass)
    table.insert(attempts, "summon.CheatManager.Summon(" .. tostring(candidate) .. ")#plain=" .. (okPlain and "ok" or tostring(errPlain)))
    if okPlain then
      usedCandidate = candidate
      break
    end
    lastError = tostring(errPlain)
  end
  disableScopedAdminBypass()
  if usedCandidate == "" then
    table.insert(attempts, "summon.failed=" .. tostring(lastError))
    return false, tostring(lastError), nil, nil
  end
  local logText = waitForServerLogGrowth(logStart, 350, 128 * 1024)
  local accepted, logMessage = summonLogAccepted(logText, usedCandidate)
  local afterStats = latestScumGlobalStatsFromText(logText) or latestScumGlobalStatsTail()
  local statsOk, statsDetail = summonStatsIncreased(beforeStats, afterStats)
  local actor, newCount = findNewRuntimeActor(actorClass, beforeObjects or {})
  table.insert(attempts, "summon.candidate=" .. tostring(usedCandidate))
  table.insert(attempts, "summon.log=" .. tostring(logMessage))
  table.insert(attempts, "summon.stats=" .. tostring(statsDetail))
  table.insert(attempts, "summon.statsOk=" .. tostring(statsOk))
  table.insert(attempts, "summon.runtimeNew=" .. tostring(newCount or 0))
  table.insert(attempts, "summon.durationMs=" .. tostring(math.floor((os.clock() - startedAt) * 1000)))
  if actor == nil or not isValidObject(actor) then
    return false, "Summon отправлен, но новый runtime actor не найден точечным FindAllOf: " .. tostring(logMessage), nil, nil
  end
  return true, "CheatManager.Summon:" .. tostring(usedCandidate) .. "; " .. tostring(logMessage), actor, usedCandidate
end

function spawnFunctionalLinkedTraderActorForInfo(actorClass, info, entry, attempts)
  attempts = attempts or {}
  table.insert(attempts, "functional trader route=summon-linked-trader-actor")
  local donorTradePost, routeDetail, findAttempts = findRegisteredTradePostForFunctionalTrader(actorClass, info, entry)
  for _, attempt in ipairs(findAttempts or {}) do table.insert(attempts, "find." .. tostring(attempt)) end
  if donorTradePost == nil or not isValidObject(donorTradePost) then
    local data = '{"actorClass":' .. js(actorClass) ..
      ',"route":"functional-summon-linked-trader-actor"' ..
      ',"ok":false' ..
      ',"detail":' .. js(routeDetail or "") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader actor не создан: donor TradePost/economy marker не найден. " .. tostring(routeDetail), data)
    return false, "Functional trader actor не создан: " .. tostring(routeDetail), data
  end
  local okSummon, summonDetail, traderActor, summonCandidate = summonFunctionalLinkedTraderActor(actorClass, info, attempts)
  if not okSummon or traderActor == nil or not isValidObject(traderActor) then
    local data = '{"actorClass":' .. js(actorClass) ..
      ',"route":"functional-summon-linked-trader-actor"' ..
      ',"routeDetail":' .. js(routeDetail or "") ..
      ',"donorTradePost":' .. nativeProbeObjectJson("donorTradePost", donorTradePost, "registered-level-actor", {}) ..
      ',"ok":false' ..
      ',"detail":' .. js(summonDetail or "") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader actor не создан через Summon: " .. tostring(summonDetail), data)
    return false, "Functional trader actor не создан через Summon: " .. tostring(summonDetail), data
  end
  local targetLoc, targetYaw = functionalTraderTargetLocation(info)
  table.insert(attempts, "target=" .. tostring(targetLoc.X) .. "," .. tostring(targetLoc.Y) .. "," .. tostring(targetLoc.Z) .. ";yaw=" .. tostring(targetYaw))
  local okLinked, linkedDetail, personality = initializeFunctionalLinkedTraderActor(traderActor, actorClass, donorTradePost, targetLoc, targetYaw, attempts)
  local x, y, z = vectorOf(traderActor)
  local yaw = rotationYawOf(traderActor) or rotationYawOf((info or {}).pc) or rotationYawOf((info or {}).pawn) or 0
  local remembered = false
  local allowUnverifiedRuntimeSuccess = configBool("bridge-safety", { "AllowUnverifiedFunctionalTraderRuntimeSuccess", "allowUnverifiedFunctionalTraderRuntimeSuccess" }, false) == true
  if okLinked and allowUnverifiedRuntimeSuccess and traderActor ~= nil and isValidObject(traderActor) and configBool("bridge-safety", { "EnableFunctionalTraderSitePersistence", "enableFunctionalTraderSitePersistence" }, false) == true then
    local routeClass = runtimeShortClassNameFromObject(donorTradePost)
    remembered = rememberFunctionalTraderSpawnedSite(actorClass, routeClass, nil, donorTradePost, { X = x, Y = y, Z = z }, yaw, actorClass, donorTradePost, traderActor)
  end
  local data = '{"actorClass":' .. js(actorClass) ..
    ',"route":"functional-summon-linked-trader-actor"' ..
    ',"routeDetail":' .. js(routeDetail or "") ..
    ',"summonCandidate":' .. js(summonCandidate or "") ..
    ',"donorTradePost":' .. nativeProbeObjectJson("donorTradePost", donorTradePost, "registered-level-actor", {}) ..
    ',"trader":' .. nativeProbeObjectJson("trader", traderActor, "summoned-runtime-actor", {}) ..
    ',"personality":' .. nativeProbeObjectJson("personality", personality, "_traderPersonalityDataAsset", {}) ..
    ',"traderPersistentId":' .. js(traderPersonalityRuntimeId(personality)) ..
    ',"remembered":' .. (remembered and "true" or "false") ..
    ',"clientVerified":false' ..
    ',"unverifiedRuntimeSuccessAllowed":' .. (allowUnverifiedRuntimeSuccess and "true" or "false") ..
    ',"target":{"x":' .. tostring(tonumber(x) or 0) .. ',"y":' .. tostring(tonumber(y) or 0) .. ',"z":' .. tostring(tonumber(z) or 0) .. ',"yaw":' .. tostring(tonumber(yaw) or 0) .. '}' ..
    ',"detail":' .. js(tostring(summonDetail or "") .. "; " .. tostring(linkedDetail or "")) ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
  if okLinked and allowUnverifiedRuntimeSuccess then
    appendActionEvent("spawn_actor", true, info, "Functional trader actor создан через Summon и привязан к существующему TradePost/economy marker: " .. tostring(actorClass), data)
    return true, "Functional trader actor создан через Summon и привязан к TradePost/economy marker: " .. tostring(actorClass), data
  end
  destroySpawnedItem(traderActor)
  if okLinked then
    appendActionEvent("spawn_actor", false, info, "Functional trader actor создан только как server-side ghost; пользователь подтвердил, что клиент его не видит. Actor удалён, успех заблокирован до native lifecycle route: " .. tostring(actorClass), data)
    return false, "Functional trader actor не считается рабочим: server-side init не даёт client-visible/functional trader. Нужен native TradeOutpost/economy lifecycle route.", data
  end
  appendActionEvent("spawn_actor", false, info, "Functional trader actor route не подтверждён: " .. tostring(linkedDetail), data)
  return false, "Functional trader actor route не подтверждён: " .. tostring(linkedDetail), data
end

function moveTradePostChildrenByDelta(tradePost, dx, dy, dz, attempts)
  local moved = 0
  local function moveChild(child, label)
    local obj = runtimeCollectionUnwrap(child)
    if obj == nil or not isValidObject(obj) then return end
    local x, y, z = vectorOf(obj)
    local okChild, childDetail = moveRuntimeActorToLocation(obj, { X = x + dx, Y = y + dy, Z = z + dz }, nil, attempts, label)
    if okChild then moved = moved + 1 end
    table.insert(attempts, tostring(label) .. ".moveDetail=" .. tostring(childDetail))
  end
  for _, spec in ipairs({
    { "_spawnedTraders", "spawnedTrader" },
    { "_spawnedSedentaryNPCs", "spawnedSedentary" }
  }) do
    local collection = firstProp(tradePost, { spec[1] })
    local count, items, method = runtimeArrayCount(collection, 32)
    table.insert(attempts, spec[1] .. ".count=" .. tostring(count or 0) .. " via " .. tostring(method or ""))
    for index, item in ipairs(items or {}) do moveChild(item, spec[2] .. "#" .. tostring(index)) end
  end
  local questBook = firstProp(tradePost, { "_questBook", "QuestBook" })
  if questBook ~= nil and isValidObject(questBook) then moveChild(questBook, "questBook") end
  return moved
end

function relocateRegisteredTradePostActor(tradePost, loc, yaw, attempts, label)
  attempts = attempts or {}
  if tradePost == nil or not isValidObject(tradePost) then return false, "tradepost missing", attempts end
  local beforeX, beforeY, beforeZ = vectorOf(tradePost)
  local okMove, moveDetail = moveRuntimeActorToLocation(tradePost, loc, yaw, attempts, label or "tradePost")
  local afterX, afterY, afterZ = vectorOf(tradePost)
  local dx, dy, dz = (afterX - beforeX), (afterY - beforeY), (afterZ - beforeZ)
  if okMove then
    local movedChildren = moveTradePostChildrenByDelta(tradePost, dx, dy, dz, attempts)
    table.insert(attempts, "childrenMoved=" .. tostring(movedChildren))
  end
  return okMove, tostring(moveDetail) .. " " .. tostring(afterX) .. "," .. tostring(afterY) .. "," .. tostring(afterZ), attempts
end

function applyFunctionalTraderMarkerRoute(actorClass, tradePost, loc, yaw, attempts, label)
  attempts = attempts or {}
  table.insert(attempts, tostring(label or "markerRoute") .. "=blocked: FTraderMarker transform lifecycle route requires native C++ wrapper")
  return false, "FTraderMarker lifecycle route blocked: requires native C++ wrapper", nil, nil, attempts
end

function applyFunctionalTraderMarkerRouteUnsafe(actorClass, tradePost, loc, yaw, attempts, label)
  attempts = attempts or {}
  if tradePost == nil or not isValidObject(tradePost) then return false, "tradepost missing", nil, nil, attempts end
  local marker, personality, markerDetail = tradePostMarkerForTrader(tradePost, actorClass, nil, attempts)
  table.insert(attempts, tostring(label or "markerRoute") .. ".markerDetail=" .. tostring(markerDetail))
  if marker == nil or not isValidObject(marker) then return false, "marker missing: " .. tostring(markerDetail), nil, personality, attempts end
  local okMarker, markerSetDetail = functionalTraderSetMarkerTransform(marker, loc, yaw, attempts)
  table.insert(attempts, tostring(label or "markerRoute") .. ".markerSet=" .. tostring(okMarker) .. ":" .. tostring(markerSetDetail))
  local moveTradePost = configBool("bridge-safety", { "FunctionalTraderMarkerMoveTradePostActor", "functionalTraderMarkerMoveTradePostActor" }, false) == true
  local okMove = true
  local moveDetail = "tradepost move disabled"
  if moveTradePost then
    okMove, moveDetail, attempts = relocateRegisteredTradePostActor(tradePost, loc, yaw, attempts, tostring(label or "markerTradePost"))
  end
  local okRelevancy, errRelevancy = pcall(function()
    tradePost._sedentaryNPCRelevancyDistance = configNumber("bridge-safety", { "FunctionalTraderMarkerRelevancyDistance", "functionalTraderMarkerRelevancyDistance" }, 25000)
  end)
  table.insert(attempts, "tradePost._sedentaryNPCRelevancyDistance=" .. (okRelevancy and "ok" or tostring(errRelevancy)))
  local okHidden, errHidden = safeCall(tradePost, "SetActorHiddenInGame", false)
  table.insert(attempts, "tradePost.SetActorHiddenInGame=false:" .. (okHidden and "ok" or tostring(errHidden)))
  local okCollision, errCollision = safeCall(tradePost, "SetActorEnableCollision", true)
  table.insert(attempts, "tradePost.SetActorEnableCollision=true:" .. (okCollision and "ok" or tostring(errCollision)))
  local okDorm, errDorm = safeCall(tradePost, "FlushNetDormancy")
  table.insert(attempts, "tradePost.FlushNetDormancy=" .. (okDorm and "ok" or tostring(errDorm)))
  local okForce, errForce = safeCall(tradePost, "ForceNetUpdate")
  table.insert(attempts, "tradePost.ForceNetUpdate=" .. (okForce and "ok" or tostring(errForce)))
  return okMarker and okMove, tostring(markerSetDetail) .. "; " .. tostring(moveDetail), marker, personality, attempts
end

function rememberFunctionalTraderSite(actorClass, routeClass, tradePost, loc, yaw, routeMode)
  if configBool("bridge-safety", { "EnableFunctionalTraderSitePersistence", "enableFunctionalTraderSitePersistence" }, false) ~= true then return false end
  if tradePost == nil or not isValidObject(tradePost) then return false end
  local record = '{"utc":' .. js(nowUtc()) ..
    ',"active":true' ..
    ',"actorClass":' .. js(actorClass or "") ..
    ',"routeClass":' .. js(routeClass or "") ..
    ',"routeMode":' .. js(routeMode or "tradepost-relocation") ..
    ',"sourceFullName":' .. js(objectFullName(tradePost)) ..
    ',"x":' .. tostring(tonumber((loc or {}).X) or 0) ..
    ',"y":' .. tostring(tonumber((loc or {}).Y) or 0) ..
    ',"z":' .. tostring(tonumber((loc or {}).Z) or 0) ..
    ',"yaw":' .. tostring(tonumber(yaw) or 0) .. '}'
  return appendJsonArray(FUNCTIONAL_TRADER_SITES_FILE, record, 1024 * 1024)
end

function spawnFunctionalTraderMarkerRouteForInfo(actorClass, info, entry, attempts)
  attempts = attempts or {}
  table.insert(attempts, "functional trader marker lifecycle route blocked after crash: requires native C++ wrapper")
  local data = '{"actorClass":' .. js(actorClass or "") ..
    ',"route":"functional-trader-marker-lifecycle"' ..
    ',"ok":false' ..
    ',"blocked":true' ..
    ',"detail":"FTraderMarker Lua transform write blocked after UE4SS crash; requires native C++ wrapper or real SCUM lifecycle API"' ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
  appendActionEvent("spawn_actor", false, info, "Functional trader marker-route заблокирован: нужен native C++ wrapper, Lua FTransform роняет сервер.", data)
  return false, "Functional trader marker-route заблокирован: нужен native C++ wrapper, Lua FTransform роняет сервер.", data
end

function spawnFunctionalTraderMarkerRouteForInfoUnsafe(actorClass, info, entry, attempts)
  attempts = attempts or {}
  table.insert(attempts, "functional trader route=marker-lifecycle-relocation")
  local tradePost, routeDetail, findAttempts, routeClass = findRegisteredTradePostForFunctionalTrader(actorClass, info, entry)
  for _, attempt in ipairs(findAttempts or {}) do table.insert(attempts, "find." .. tostring(attempt)) end
  if tradePost == nil or not isValidObject(tradePost) then
    local data = '{"actorClass":' .. js(actorClass or "") ..
      ',"route":"functional-trader-marker-lifecycle"' ..
      ',"ok":false' ..
      ',"detail":' .. js(routeDetail or "") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader marker-route не создан: stock TradePost/marker не найден. " .. tostring(routeDetail), data)
    return false, "Functional trader marker-route не создан: " .. tostring(routeDetail), data
  end
  local loc, yaw = functionalTraderTargetLocation(info)
  local okRoute, routeSetDetail, marker, personality, routeAttempts = applyFunctionalTraderMarkerRoute(actorClass, tradePost, loc, yaw, attempts, "functionalMarker")
  attempts = routeAttempts or attempts
  local remembered = false
  if okRoute then remembered = rememberFunctionalTraderSite(actorClass, routeClass, tradePost, loc, yaw, "marker-lifecycle") end
  local verifyDelay = 0
  if okRoute then
    verifyDelay = scheduleFunctionalTraderMarkerVerification(info, actorClass, objectFullName(tradePost), loc, yaw, personality, routeClass)
  end
  local data = '{"actorClass":' .. js(actorClass or "") ..
    ',"route":"functional-trader-marker-lifecycle"' ..
    ',"routeDetail":' .. js(routeDetail or "") ..
    ',"tradePost":' .. nativeProbeObjectJson("tradePost", tradePost, "stock-tradepost", {}) ..
    ',"marker":' .. nativeProbeObjectJson("marker", marker, "FTraderMarker", {}) ..
    ',"personality":' .. nativeProbeObjectJson("personality", personality, "marker.TraderPersonality", {}) ..
    ',"traderPersistentId":' .. js(traderPersonalityRuntimeId(personality)) ..
    ',"target":{"x":' .. tostring(tonumber(loc.X) or 0) .. ',"y":' .. tostring(tonumber(loc.Y) or 0) .. ',"z":' .. tostring(tonumber(loc.Z) or 0) .. ',"yaw":' .. tostring(tonumber(yaw) or 0) .. '}' ..
    ',"remembered":' .. (remembered and "true" or "false") ..
    ',"verifyDelayMs":' .. tostring(verifyDelay or 0) ..
    ',"detail":' .. js(routeSetDetail or "") ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
  if okRoute then
    appendActionEvent("spawn_actor", true, info, "Functional trader marker-route применён: stock TradePost/marker перенесён, native lifecycle должен заспавнить NPC. Проверка запланирована.", data)
    return true, "Functional trader marker-route применён, lifecycle-проверка через " .. tostring(verifyDelay or 0) .. " ms: " .. tostring(actorClass), data
  end
  appendActionEvent("spawn_actor", false, info, "Functional trader marker-route не применён: " .. tostring(routeSetDetail), data)
  return false, "Functional trader marker-route не применён: " .. tostring(routeSetDetail), data
end

function spawnFunctionalRegisteredTradePostForInfo(actorClass, info, entry, attempts)
  attempts = attempts or {}
  table.insert(attempts, "functional trader route=registered-tradepost-relocation")
  local tradePost, routeDetail, findAttempts, routeClass = findRegisteredTradePostForFunctionalTrader(actorClass, info, entry)
  for _, attempt in ipairs(findAttempts or {}) do table.insert(attempts, "find." .. tostring(attempt)) end
  if tradePost == nil or not isValidObject(tradePost) then
    local data = '{"actorClass":' .. js(actorClass) ..
      ',"route":"functional-registered-tradepost"' ..
      ',"ok":false' ..
      ',"detail":' .. js(routeDetail or "") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader не создан: не найден зарегистрированный TradePost/economy actor. " .. tostring(routeDetail), data)
    return false, "Functional trader не создан: " .. tostring(routeDetail), data
  end
  local loc, yaw = functionalTraderTargetLocation(info)
  local okMove, moveDetail, moveAttempts = relocateRegisteredTradePostActor(tradePost, loc, yaw, attempts, "registeredTradePost")
  attempts = moveAttempts or attempts
  local managerAssigned, managerDetail, managerAttempts = tradePostOutpostManagerAssigned(tradePost)
  for _, attempt in ipairs(managerAttempts or {}) do table.insert(attempts, "verify." .. tostring(attempt)) end
  local remembered = false
  if okMove and managerAssigned then remembered = rememberFunctionalTraderSite(actorClass, routeClass, tradePost, loc, yaw) end
  local data = '{"actorClass":' .. js(actorClass) ..
    ',"route":"functional-registered-tradepost"' ..
    ',"routeDetail":' .. js(routeDetail or "") ..
    ',"tradePost":' .. nativeProbeObjectJson("tradePost", tradePost, "registered-level-actor", {}) ..
    ',"managerAssigned":' .. (managerAssigned and "true" or "false") ..
    ',"managerDetail":' .. js(managerDetail or "") ..
    ',"target":{"x":' .. tostring(tonumber(loc.X) or 0) .. ',"y":' .. tostring(tonumber(loc.Y) or 0) .. ',"z":' .. tostring(tonumber(loc.Z) or 0) .. ',"yaw":' .. tostring(tonumber(yaw) or 0) .. '}' ..
    ',"remembered":' .. (remembered and "true" or "false") ..
    ',"detail":' .. js(moveDetail or "") ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
  if okMove and managerAssigned then
    appendActionEvent("spawn_actor", true, info, "Functional trader перенесён через уже зарегистрированный TradePost/economy actor: " .. tostring(actorClass), data)
    return true, "Functional trader перенесён через зарегистрированный TradePost: " .. tostring(actorClass), data
  end
  appendActionEvent("spawn_actor", false, info, "Functional trader route не подтверждён: " .. tostring(moveDetail) .. "; " .. tostring(managerDetail), data)
  return false, "Functional trader route не подтверждён: " .. tostring(moveDetail) .. "; " .. tostring(managerDetail), data
end

FUNCTIONAL_TRADER_PROXY_BY_KEY = FUNCTIONAL_TRADER_PROXY_BY_KEY or {}
FUNCTIONAL_TRADER_PROXY_BY_FULLNAME = FUNCTIONAL_TRADER_PROXY_BY_FULLNAME or {}
FUNCTIONAL_TRADER_PROXY_DONOR_RESTORE = FUNCTIONAL_TRADER_PROXY_DONOR_RESTORE or {}
FUNCTIONAL_TRADER_PROXY_RESTORED_SITES = FUNCTIONAL_TRADER_PROXY_RESTORED_SITES or {}

function functionalTraderProxyIdentityForObject(obj)
  obj = runtimeCollectionUnwrap(obj)
  if obj == nil or not isValidObject(obj) then return "", "" end
  return objectKey(obj), objectFullName(obj)
end

function registerFunctionalTraderProxyRoute(route)
  if route == nil then return false end
  local proxy = route.proxy
  if proxy == nil or not isValidObject(proxy) then return false end
  local key, fullName = functionalTraderProxyIdentityForObject(proxy)
  if key ~= "" then
    route.proxyKey = key
    FUNCTIONAL_TRADER_PROXY_BY_KEY[key] = route
  end
  if fullName ~= "" then
    route.proxyFullName = fullName
    FUNCTIONAL_TRADER_PROXY_BY_FULLNAME[fullName] = route
  end
  return key ~= "" or fullName ~= ""
end

function functionalTraderProxyIsRegisteredProxy(obj)
  local key, fullName = functionalTraderProxyIdentityForObject(obj)
  if key ~= "" and FUNCTIONAL_TRADER_PROXY_BY_KEY[key] ~= nil then return true, "key" end
  if fullName ~= "" and FUNCTIONAL_TRADER_PROXY_BY_FULLNAME[fullName] ~= nil then return true, "fullName" end
  return false, "miss"
end

function functionalTraderProxyRouteForCandidate(obj, source)
  obj = runtimeCollectionUnwrap(obj)
  if obj == nil or not isValidObject(obj) then return nil, tostring(source or "missing") .. ":missing" end
  local key, fullName = functionalTraderProxyIdentityForObject(obj)
  if key ~= "" and FUNCTIONAL_TRADER_PROXY_BY_KEY[key] ~= nil then
    return FUNCTIONAL_TRADER_PROXY_BY_KEY[key], tostring(source or "object") .. ":key"
  end
  if fullName ~= "" and FUNCTIONAL_TRADER_PROXY_BY_FULLNAME[fullName] ~= nil then
    return FUNCTIONAL_TRADER_PROXY_BY_FULLNAME[fullName], tostring(source or "object") .. ":fullName"
  end
  return nil, tostring(source or "object") .. ":miss"
end

function functionalTraderProxyRouteForObject(obj)
  local route, detail = functionalTraderProxyRouteForCandidate(obj, "direct")
  if route ~= nil then return route, detail end
  local attempts = { detail }
  for _, method in ipairs({ "GetOwner", "GetAttachParentActor", "GetOuter" }) do
    local okCall, candidate = safeCall(obj, method)
    table.insert(attempts, tostring(method) .. "=" .. (okCall and objectFullName(candidate) or tostring(candidate)))
    if okCall and candidate ~= nil and isValidObject(candidate) then
      route, detail = functionalTraderProxyRouteForCandidate(candidate, method)
      if route ~= nil then return route, table.concat(attempts, " | ") .. " | " .. tostring(detail) end
    end
  end
  return nil, table.concat(attempts, " | ")
end

function functionalTraderProxyDonorTradePost(route, attempts)
  attempts = attempts or {}
  if route == nil then return nil, "route missing" end
  if route.donorTradePost ~= nil and isValidObject(route.donorTradePost) then return route.donorTradePost, "cached" end
  local fullName = tostring(route.donorTradePostFullName or "")
  if fullName == "" then return nil, "donor fullName missing" end
  local tradePost, detail, findAttempts = findTradePostByFullName(fullName)
  for _, attempt in ipairs(findAttempts or {}) do table.insert(attempts, "donor." .. tostring(attempt)) end
  if tradePost ~= nil and isValidObject(tradePost) then
    route.donorTradePost = tradePost
    return tradePost, tostring(detail or "found")
  end
  return nil, tostring(detail or "not found")
end

function functionalTraderProxyFindStockTrader(route, attempts)
  attempts = attempts or {}
  if route == nil then return nil, "route missing" end
  if route.stockTrader ~= nil and isValidObject(route.stockTrader) then
    local isProxy, proxyDetail = functionalTraderProxyIsRegisteredProxy(route.stockTrader)
    if not isProxy then return route.stockTrader, "cached" end
    table.insert(attempts, "stockTrader.cached.skipProxy=" .. tostring(proxyDetail) .. ":" .. objectFullName(route.stockTrader))
    route.stockTrader = nil
    route.stockTraderFullName = nil
  end
  local tradePost, donorDetail = functionalTraderProxyDonorTradePost(route, attempts)
  table.insert(attempts, "stockTrader.donor=" .. tostring(donorDetail))
  if tradePost == nil or not isValidObject(tradePost) then return nil, "donor tradepost missing" end
  local wantedPersistentId = tostring(route.traderPersistentId or "")
  local fallback = nil
  local fallbackDetail = ""
  local function consider(candidate, label)
    candidate = runtimeCollectionUnwrap(candidate)
    if candidate == nil or not isValidObject(candidate) then return nil end
    if route.proxy ~= nil and isValidObject(route.proxy) and objectKey(candidate) == objectKey(route.proxy) then
      table.insert(attempts, "stockTrader.skipProxy=" .. tostring(label or "candidate"))
      return nil
    end
    local isRegisteredProxy, registeredProxyDetail = functionalTraderProxyIsRegisteredProxy(candidate)
    if isRegisteredProxy then
      table.insert(attempts, "stockTrader.skipRegisteredProxy=" .. tostring(label or "candidate") .. ":" .. tostring(registeredProxyDetail))
      return nil
    end
    if fallback == nil then
      fallback = candidate
      fallbackDetail = tostring(label or "candidate") .. ":" .. objectFullName(candidate)
    end
    local personality = traderPersonalityObject(candidate)
    local persistentId = traderPersonalityRuntimeId(personality)
    if wantedPersistentId ~= "" and persistentId ~= "" and persistentId == wantedPersistentId then
      return candidate, tostring(label or "candidate") .. ":persistentId"
    end
    local ownerTradePost = runtimeCollectionUnwrap(firstProp(candidate, { "_tradeOutpostBuilding", "TradeOutpostBuilding" }))
    if ownerTradePost ~= nil and isValidObject(ownerTradePost) and objectKey(ownerTradePost) == objectKey(tradePost) then
      if traderPersonalityMatchesHint(personality, traderTypeHint(route.actorClass or "", candidate)) then
        return candidate, tostring(label or "candidate") .. ":tradepost+hint"
      end
    end
    return nil
  end
  for _, propName in ipairs({ "_spawnedTraders", "SpawnedTraders", "_spawnedSedentaryNPCs", "SpawnedSedentaryNPCs" }) do
    local collection = firstProp(tradePost, { propName })
    local count, items, method = runtimeArrayCount(collection, 32)
    table.insert(attempts, "stockTrader." .. tostring(propName) .. ".count=" .. tostring(count or 0) .. " via " .. tostring(method or ""))
    local seen = {}
    for index, item in ipairs(items or {}) do
      local key = objectKey(item)
      if key ~= "" then seen[key] = true end
      local found, detail = consider(item, tostring(propName) .. "#" .. tostring(index))
      if found ~= nil then
        route.stockTrader = found
        route.stockTraderFullName = objectFullName(found)
        return found, detail
      end
    end
    if collection ~= nil and tonumber(count) ~= nil and tonumber(count) > 0 then
      local maxZeroIndex = math.min((tonumber(count) or 0) - 1, 31)
      for index = 0, maxZeroIndex do
        local okItem, item = pcall(function() return collection[index] end)
        if okItem then
          item = runtimeCollectionUnwrap(item)
          local key = objectKey(item)
          if key ~= "" and seen[key] ~= true then
            seen[key] = true
            local found, detail = consider(item, tostring(propName) .. "[0:" .. tostring(index) .. "]")
            if found ~= nil then
              route.stockTrader = found
              route.stockTraderFullName = objectFullName(found)
              return found, detail
            end
          end
        end
      end
    end
  end
  if fallback ~= nil and isValidObject(fallback) then
    route.stockTrader = fallback
    route.stockTraderFullName = objectFullName(fallback)
    return fallback, "fallback:" .. tostring(fallbackDetail)
  end
  return nil, "no spawned stock ATrader on donor TradePost"
end

function rememberFunctionalTraderProxySite(route)
  if configBool("bridge-safety", { "EnableFunctionalTraderProxyPersistence", "enableFunctionalTraderProxyPersistence" }, false) ~= true then return false end
  if route == nil or route.proxy == nil or not isValidObject(route.proxy) then return false end
  local siteId = tostring(os.time()) .. "-" .. tostring(route.proxyKey or objectKey(route.proxy))
  route.siteId = siteId
  local record = '{"utc":' .. js(nowUtc()) ..
    ',"siteId":' .. js(siteId) ..
    ',"active":true' ..
    ',"actorClass":' .. js(route.actorClass or "") ..
    ',"proxyFullName":' .. js(objectFullName(route.proxy)) ..
    ',"donorTradePostFullName":' .. js(route.donorTradePostFullName or "") ..
    ',"traderPersistentId":' .. js(route.traderPersistentId or "") ..
    ',"x":' .. tostring(tonumber(route.x) or 0) ..
    ',"y":' .. tostring(tonumber(route.y) or 0) ..
    ',"z":' .. tostring(tonumber(route.z) or 0) ..
    ',"yaw":' .. tostring(tonumber(route.yaw) or 0) .. '}'
  return appendJsonArray(FUNCTIONAL_TRADER_PROXY_FILE, record, 1024 * 1024)
end

function functionalTraderProxyState()
  local text = normalizeJsonArrayText(readAll(FUNCTIONAL_TRADER_PROXY_FILE) or "[]", 1024 * 1024)
  local rows = {}
  for record in text:gmatch("%b{}") do
    local actorClass = extractStringAny(record, { "actorClass", "ActorClass" }) or ""
    local donorFullName = extractStringAny(record, { "donorTradePostFullName", "tradePostFullName", "sourceFullName" }) or ""
    if actorClass ~= "" and donorFullName ~= "" then
      table.insert(rows, {
        raw = record,
        siteId = extractStringAny(record, { "siteId", "SiteId", "id", "Id" }) or "",
        active = extractBoolAny(record, { "active", "Active" }, true) ~= false,
        actorClass = actorClass,
        donorTradePostFullName = donorFullName,
        traderPersistentId = extractStringAny(record, { "traderPersistentId", "TraderPersistentId" }) or "",
        x = extractNumberAny(record, { "x", "X" }, nil),
        y = extractNumberAny(record, { "y", "Y" }, nil),
        z = extractNumberAny(record, { "z", "Z" }, nil),
        yaw = extractNumberAny(record, { "yaw", "Yaw" }, 0)
      })
    end
  end
  return rows
end

function linkFunctionalTraderProxyVisualToTradePost(proxy, tradePost, attempts)
  attempts = attempts or {}
  if proxy == nil or not isValidObject(proxy) then return false, "proxy missing" end
  if tradePost == nil or not isValidObject(tradePost) then return false, "tradePost missing" end
  if configBool("bridge-safety", { "FunctionalTraderProxyLinkVisualToTradePost", "functionalTraderProxyLinkVisualToTradePost" }, true) ~= true then
    table.insert(attempts, "proxy visual link disabled")
    return true, "disabled"
  end
  local okOutpost, errOutpost = pcall(function() proxy._tradeOutpostBuilding = tradePost end)
  table.insert(attempts, "proxy._tradeOutpostBuilding=" .. (okOutpost and "ok" or tostring(errOutpost)))
  local okOutpost2, errOutpost2 = pcall(function() proxy.TradeOutpostBuilding = tradePost end)
  table.insert(attempts, "proxy.TradeOutpostBuilding=" .. (okOutpost2 and "ok" or tostring(errOutpost2)))
  local okOriginal, errOriginal = pcall(function()
    local x, y, z = vectorOf(proxy)
    proxy._originalLocation = { X = x, Y = y, Z = z }
  end)
  table.insert(attempts, "proxy._originalLocation=current=" .. (okOriginal and "ok" or tostring(errOriginal)))
  local okRepOutpost, errRepOutpost = safeCall(proxy, "OnRep_TradeOutpostBuilding")
  table.insert(attempts, "proxy.OnRep_TradeOutpostBuilding=" .. (okRepOutpost and "ok" or tostring(errRepOutpost)))
  local okForce, errForce = safeCall(proxy, "ForceNetUpdate")
  table.insert(attempts, "proxy.ForceNetUpdate=" .. (okForce and "ok" or tostring(errForce)))
  return okOutpost or okOutpost2 or okRepOutpost, "visual linked to " .. objectFullName(tradePost)
end

function functionalTraderProxyPrepareInteraction(route, interactable, attempts)
  attempts = attempts or {}
  if route == nil then return false, "route missing" end
  local tradePost, donorDetail = functionalTraderProxyDonorTradePost(route, attempts)
  table.insert(attempts, "proxyInteract.donor=" .. tostring(donorDetail))
  if tradePost == nil or not isValidObject(tradePost) then return false, "donor tradepost missing" end
  if configBool("bridge-safety", { "FunctionalTraderProxyMoveDonorForInteraction", "functionalTraderProxyMoveDonorForInteraction" }, true) ~= true then
    return true, "donor move disabled"
  end
  local anchor = route.proxy
  if anchor == nil or not isValidObject(anchor) then anchor = interactable end
  if anchor == nil or not isValidObject(anchor) then return false, "proxy anchor missing" end
  local x, y, z = vectorOf(anchor)
  local yaw = rotationYawOf(anchor) or tonumber(route.yaw) or 0
  local donorKey = objectKey(tradePost)
  if donorKey == "" then return false, "donor key missing" end
  local restore = FUNCTIONAL_TRADER_PROXY_DONOR_RESTORE[donorKey]
  if restore == nil then
    local ox, oy, oz = vectorOf(tradePost)
    restore = {
      tradePost = tradePost,
      x = ox,
      y = oy,
      z = oz,
      yaw = rotationYawOf(tradePost) or 0
    }
    FUNCTIONAL_TRADER_PROXY_DONOR_RESTORE[donorKey] = restore
  else
    restore.tradePost = tradePost
  end
  local target = { X = x, Y = y, Z = z }
  local okMove, moveDetail = moveRuntimeActorToLocation(tradePost, target, yaw, attempts, "proxyDonor")
  table.insert(attempts, "proxyInteract.moveDonor=" .. tostring(okMove) .. ":" .. tostring(moveDetail))
  local token = tostring(os.clock()) .. ":" .. tostring(objectKey(anchor))
  restore.token = token
  local delayMs = math.max(250, math.min(math.floor(configNumber("bridge-safety", { "FunctionalTraderProxyRestoreDelayMs", "functionalTraderProxyRestoreDelayMs" }, 3500)), 30000))
  deferGame(delayMs, function()
    local current = FUNCTIONAL_TRADER_PROXY_DONOR_RESTORE[donorKey]
    if current == nil or current.token ~= token then return end
    local restoreTradePost = current.tradePost
    if restoreTradePost ~= nil and isValidObject(restoreTradePost) then
      local restoreAttempts = {}
      local okRestore, restoreDetail = moveRuntimeActorToLocation(restoreTradePost, { X = current.x, Y = current.y, Z = current.z }, current.yaw, restoreAttempts, "proxyDonorRestore")
      appendLog("functional trader proxy donor restore " .. tostring(okRestore) .. " " .. tostring(restoreDetail) .. " attempts=" .. table.concat(restoreAttempts, " | "))
    end
    FUNCTIONAL_TRADER_PROXY_DONOR_RESTORE[donorKey] = nil
  end)
  return okMove, tostring(moveDetail)
end

function spawnFunctionalTraderProxyForInfo(actorClass, info, entry, attempts)
  attempts = attempts or {}
  table.insert(attempts, "functional trader route=proxy-rpc-redirect")
  local donorTradePost, routeDetail, findAttempts = findRegisteredTradePostForFunctionalTrader(actorClass, info, entry)
  for _, attempt in ipairs(findAttempts or {}) do table.insert(attempts, "find." .. tostring(attempt)) end
  if donorTradePost == nil or not isValidObject(donorTradePost) then
    local data = '{"actorClass":' .. js(actorClass or "") ..
      ',"route":"functional-trader-proxy-redirect"' ..
      ',"ok":false' ..
      ',"detail":' .. js(routeDetail or "") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader proxy не создан: stock TradePost/economy marker не найден. " .. tostring(routeDetail), data)
    return false, "Functional trader proxy не создан: " .. tostring(routeDetail), data
  end
  local personality, personalityDetail = tradePostPersonalityForTrader(donorTradePost, actorClass, nil, attempts)
  table.insert(attempts, "proxy.personality=" .. tostring(personalityDetail))
  local targetLoc, targetYaw = functionalTraderTargetLocation(info)
  local okSummon, summonDetail, proxyActor, summonCandidate = summonFunctionalLinkedTraderActor(actorClass, info, attempts)
  if not okSummon or proxyActor == nil or not isValidObject(proxyActor) then
    local data = '{"actorClass":' .. js(actorClass or "") ..
      ',"route":"functional-trader-proxy-redirect"' ..
      ',"ok":false' ..
      ',"routeDetail":' .. js(routeDetail or "") ..
      ',"donorTradePost":' .. nativeProbeObjectJson("donorTradePost", donorTradePost, "stock-tradepost", {}) ..
      ',"detail":' .. js(summonDetail or "") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader proxy не создан через Summon: " .. tostring(summonDetail), data)
    return false, "Functional trader proxy не создан через Summon: " .. tostring(summonDetail), data
  end
  local okVisualInit, visualDetail, visualPersonality = false, "visual init disabled", personality
  if configBool("bridge-safety", { "FunctionalTraderProxyInitializeVisualActor", "functionalTraderProxyInitializeVisualActor" }, true) == true then
    okVisualInit, visualDetail, visualPersonality = initializeFunctionalLinkedTraderActor(proxyActor, actorClass, donorTradePost, targetLoc, targetYaw, attempts, true)
    table.insert(attempts, "proxy.visualInit=" .. tostring(okVisualInit) .. ":" .. tostring(visualDetail))
    if visualPersonality ~= nil and isValidObject(visualPersonality) then personality = visualPersonality end
  else
    local okMove, moveDetail = moveRuntimeActorToLocation(proxyActor, targetLoc, targetYaw, attempts, "proxyTrader")
    okVisualInit = okMove
    visualDetail = tostring(moveDetail)
    table.insert(attempts, "proxy.visualInit=legacy-move-only:" .. tostring(moveDetail))
  end
  local okLink, linkDetail = linkFunctionalTraderProxyVisualToTradePost(proxyActor, donorTradePost, attempts)
  local x, y, z = vectorOf(proxyActor)
  local yaw = rotationYawOf(proxyActor) or targetYaw or 0
  local route = {
    actorClass = actorClass,
    proxy = proxyActor,
    proxyFullName = objectFullName(proxyActor),
    donorTradePost = donorTradePost,
    donorTradePostFullName = objectFullName(donorTradePost),
    personality = personality,
    personalityFullName = objectFullName(personality),
    traderPersistentId = traderPersonalityRuntimeId(personality),
    x = x,
    y = y,
    z = z,
    yaw = yaw,
    routeDetail = routeDetail,
    summonCandidate = summonCandidate
  }
  local registered = registerFunctionalTraderProxyRoute(route)
  local remembered = false
  if registered then remembered = rememberFunctionalTraderProxySite(route) end
  local data = '{"actorClass":' .. js(actorClass or "") ..
    ',"route":"functional-trader-proxy-redirect"' ..
    ',"ok":' .. ((registered and okVisualInit and okLink) and "true" or "false") ..
    ',"registered":' .. (registered and "true" or "false") ..
    ',"visualInitialized":' .. (okVisualInit and "true" or "false") ..
    ',"visualLinked":' .. (okLink and "true" or "false") ..
    ',"summonCandidate":' .. js(summonCandidate or "") ..
    ',"donorTradePost":' .. nativeProbeObjectJson("donorTradePost", donorTradePost, "stock-tradepost", {}) ..
    ',"proxy":' .. nativeProbeObjectJson("proxy", proxyActor, "summoned-proxy-actor", {}) ..
    ',"personality":' .. nativeProbeObjectJson("personality", personality, "stock-marker", {}) ..
    ',"traderPersistentId":' .. js(route.traderPersistentId or "") ..
    ',"target":{"x":' .. tostring(tonumber(x) or 0) .. ',"y":' .. tostring(tonumber(y) or 0) .. ',"z":' .. tostring(tonumber(z) or 0) .. ',"yaw":' .. tostring(tonumber(yaw) or 0) .. '}' ..
    ',"remembered":' .. (remembered and "true" or "false") ..
    ',"detail":' .. js(tostring(summonDetail or "") .. "; visual=" .. tostring(visualDetail or "") .. "; link=" .. tostring(linkDetail or "")) ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
  if registered and okVisualInit and okLink then
    appendActionEvent("spawn_actor", true, info, "Functional trader proxy создан как видимый Trader actor: interaction/trade RPC будут перенаправлены на stock TradePost/economy marker.", data)
    return true, "Functional trader proxy создан как видимый Trader actor и привязан к stock TradePost redirect: " .. tostring(actorClass), data, proxyActor
  end
  destroySpawnedItem(proxyActor)
  appendActionEvent("spawn_actor", false, info, "Functional trader proxy не подтверждён; actor удалён: visual=" .. tostring(visualDetail) .. ", link=" .. tostring(linkDetail) .. ", registered=" .. tostring(registered), data)
  return false, "Functional trader proxy не подтверждён: " .. tostring(visualDetail), data
end

function restoreFunctionalTraderProxySites()
  if configBool("bridge-safety", { "EnableFunctionalTraderProxyRestore", "enableFunctionalTraderProxyRestore" }, false) ~= true then return false, "disabled" end
  if configBool("bridge-safety", { "EnableFunctionalTraderProxyPersistence", "enableFunctionalTraderProxyPersistence" }, false) ~= true then return false, "persistence disabled" end
  local rows = functionalTraderProxyState()
  local total = 0
  local restored = 0
  local attempts = {}
  for index, site in ipairs(rows or {}) do
    local siteId = site.siteId ~= "" and site.siteId or ("row-" .. tostring(index))
    if site.active and site.x ~= nil and site.y ~= nil and site.z ~= nil and not FUNCTIONAL_TRADER_PROXY_RESTORED_SITES[siteId] then
      total = total + 1
      local tradePost, tradePostDetail, tradePostAttempts = findTradePostByFullName(site.donorTradePostFullName)
      for _, attempt in ipairs(tradePostAttempts or {}) do table.insert(attempts, "site." .. siteId .. ".tradePost." .. tostring(attempt)) end
      if tradePost ~= nil and isValidObject(tradePost) then
        local okSpawn, spawnDetail, spawnAttempts, proxyActor = spawnActorDirectAtLocation(site.actorClass, { X = site.x, Y = site.y, Z = site.z }, site.yaw)
        for _, attempt in ipairs(spawnAttempts or {}) do table.insert(attempts, "site." .. siteId .. ".spawn." .. tostring(attempt)) end
        if okSpawn and proxyActor ~= nil and isValidObject(proxyActor) then
          local route = {
            actorClass = site.actorClass,
            proxy = proxyActor,
            donorTradePost = tradePost,
            donorTradePostFullName = objectFullName(tradePost),
            traderPersistentId = site.traderPersistentId or "",
            x = site.x,
            y = site.y,
            z = site.z,
            yaw = site.yaw
          }
          local linkOk, linkDetail = linkFunctionalTraderProxyVisualToTradePost(proxyActor, tradePost, attempts)
          local registered = registerFunctionalTraderProxyRoute(route)
          table.insert(attempts, "site." .. siteId .. ".register=" .. tostring(registered) .. " link=" .. tostring(linkOk) .. ":" .. tostring(linkDetail))
          if registered then
            FUNCTIONAL_TRADER_PROXY_RESTORED_SITES[siteId] = true
            restored = restored + 1
          else
            destroySpawnedItem(proxyActor)
          end
        else
          table.insert(attempts, "site." .. siteId .. ".spawn failed=" .. tostring(spawnDetail))
        end
      else
        table.insert(attempts, "site." .. siteId .. ".tradePost failed=" .. tostring(tradePostDetail))
      end
    end
  end
  if total > 0 then
    appendActionEvent("functional_trader_proxy_restore", restored == total, nil,
      "Functional trader proxy restore: " .. tostring(restored) .. "/" .. tostring(total),
      '{"restored":' .. tostring(restored) .. ',"total":' .. tostring(total) .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
  end
  return restored == total, "proxy restored " .. tostring(restored) .. "/" .. tostring(total)
end

function restoreFunctionalTraderSites()
  if not configBool("bridge-safety", { "EnableFunctionalTraderSiteRestore", "enableFunctionalTraderSiteRestore" }, false) then return false, "disabled" end
  if configBool("bridge-safety", { "EnableFunctionalTraderSitePersistence", "enableFunctionalTraderSitePersistence" }, false) ~= true then return false, "persistence disabled" end
  local rows = functionalTraderSiteState()
  local attempts = {}
  local total = 0
  local restored = 0
  for _, site in ipairs(rows or {}) do
    if site.active and site.x ~= nil and site.y ~= nil and site.z ~= nil then
      total = total + 1
      local tradePost = findTradePostByFullName(site.sourceFullName)
      if tradePost ~= nil and isValidObject(tradePost) then
        local loc = { X = site.x, Y = site.y, Z = site.z }
        local okMove, detail = false, ""
        if tostring(site.routeMode or "") == "marker-lifecycle" then
          okMove, detail, _, _, attempts = applyFunctionalTraderMarkerRoute(site.actorClass, tradePost, loc, site.yaw, attempts, "restoreMarker")
        else
          okMove, detail = relocateRegisteredTradePostActor(tradePost, loc, site.yaw, attempts, "restoreTradePost")
        end
        table.insert(attempts, "restore " .. tostring(site.actorClass) .. " mode=" .. tostring(site.routeMode or "") .. "=" .. (okMove and "ok" or tostring(detail)))
        if okMove then
          restored = restored + 1
          if tostring(site.routeMode or "") == "marker-lifecycle" then
            scheduleFunctionalTraderMarkerVerification(nil, site.actorClass, objectFullName(tradePost), loc, site.yaw, nil, "restore")
          end
        end
      else
        table.insert(attempts, "restore missing " .. tostring(site.sourceFullName))
      end
    end
  end
  if total > 0 then
    appendActionEvent("functional_trader_restore", restored == total, nil,
      "Functional trader restore: " .. tostring(restored) .. "/" .. tostring(total),
      '{"restored":' .. tostring(restored) .. ',"total":' .. tostring(total) .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
  end
  return restored == total, "restored " .. tostring(restored) .. "/" .. tostring(total)
end

function scheduleFunctionalTraderSiteRestore()
  if not configBool("bridge-safety", { "EnableFunctionalTraderSiteRestore", "enableFunctionalTraderSiteRestore" }, false) then return end
  deferGame(15000, function()
    restoreFunctionalTraderSites()
    restoreFunctionalTraderSpawnedSites()
    restoreFunctionalTraderProxySites()
  end)
  deferGame(60000, function()
    restoreFunctionalTraderSites()
    restoreFunctionalTraderSpawnedSites()
    restoreFunctionalTraderProxySites()
  end)
end

function spawnFunctionalTraderDirectForInfo(actorClass, info, entry, attempts)
  attempts = attempts or {}
  table.insert(attempts, "functional trader route=direct-world-spawn")
  local directOk, directDetail, directAttempts, directActor = spawnActorDirectForInfo(info, actorClass, entry)
  for _, attempt in ipairs(directAttempts or {}) do table.insert(attempts, "direct." .. tostring(attempt)) end
  if not directOk or directActor == nil or not isValidObject(directActor) then
    local data = '{"actorClass":' .. js(actorClass) ..
      ',"route":"functional-trader-direct"' ..
      ',"directOk":false' ..
      ',"directDetail":' .. js(directDetail or "") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, info, "Functional trader direct-spawn не создал actor: " .. tostring(directDetail), data)
    return false, "Functional trader direct-spawn не создал actor: " .. tostring(directDetail), data
  end

  local initOk, initDetail, initAttempts = initializeSummonedTraderActor(directActor, actorClass)
  for _, attempt in ipairs(initAttempts or {}) do table.insert(attempts, "init." .. tostring(attempt)) end
  local personality = traderPersonalityObject(directActor)
  local tradePost = firstProp(directActor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" })
  local okRep, errRep = safeCall(directActor, "ForceNetUpdate")
  table.insert(attempts, "ForceNetUpdate=" .. (okRep and "ok" or tostring(errRep)))
  local data = '{"actorClass":' .. js(actorClass) ..
    ',"route":"functional-trader-direct"' ..
    ',"directDetail":' .. js(directDetail or "") ..
    ',"actor":' .. nativeProbeObjectJson("trader", directActor, "direct-world-spawn", {}) ..
    ',"personality":' .. nativeProbeObjectJson("personality", personality, "_traderPersonalityDataAsset", {}) ..
    ',"tradePost":' .. nativeProbeObjectJson("tradePost", tradePost, "_tradeOutpostBuilding", {}) ..
    ',"traderPersistentId":' .. js(traderPersonalityRuntimeId(personality)) ..
    ',"initialized":' .. (initOk and "true" or "false") ..
    ',"detail":' .. js(initDetail or "") ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
  local allowUnverifiedRuntimeSuccess = configBool("bridge-safety", { "AllowUnverifiedFunctionalTraderRuntimeSuccess", "allowUnverifiedFunctionalTraderRuntimeSuccess" }, false) == true
  if initOk and personality ~= nil and isValidObject(personality) and allowUnverifiedRuntimeSuccess then
    appendActionEvent("spawn_actor", true, info, "Functional trader создан и получил TraderPersonality/tradepost: " .. tostring(actorClass), data)
    return true, "Functional trader создан и получил TraderPersonality/tradepost: " .. tostring(actorClass), data
  end

  local okDestroy, errDestroy = safeCall(directActor, "K2_DestroyActor")
  if not okDestroy then okDestroy, errDestroy = safeCall(directActor, "Destroy") end
  local destroyData = data:gsub("}$", ',"clientVerified":false,"unverifiedRuntimeSuccessAllowed":' .. (allowUnverifiedRuntimeSuccess and "true" or "false") .. ',"destroyAttempt":' .. js(okDestroy and "ok" or tostring(errDestroy)) .. '}')
  if initOk and personality ~= nil and isValidObject(personality) then
    appendActionEvent("spawn_actor", false, info,
      "Functional trader direct-spawn дал только server-side ghost; actor удалён, успех заблокирован до native lifecycle route: " .. tostring(actorClass),
      destroyData)
    return false, "Functional trader direct-spawn не считается рабочим: TraderPersonality/tradepost на server-side actor не делает его видимым/функциональным клиенту.", destroyData
  end
  appendActionEvent("spawn_actor", false, info,
    "Functional trader actor создан, но не инициализирован; actor удалён, чтобы не оставлять NPC-куклу: " .. tostring(initDetail),
    destroyData)
  return false, "Functional trader actor создан, но не инициализирован; actor удалён: " .. tostring(initDetail), destroyData
end

