function summonLogAccepted(logText, candidate)
  logText = tostring(logText or "")
  local rawCandidate = tostring(candidate or "")
  local normalizedCandidate = rawCandidate:gsub("^BlueprintGeneratedClass'", ""):gsub("^Blueprint'", ""):gsub("^Class'", ""):gsub("'$", "")
  local candidateShort = normalizedCandidate:match("%.([^%.\\/']+)$") or normalizedCandidate:match("([^/\\']+)$") or normalizedCandidate
  local function mentionsCandidate()
    return logText:find(rawCandidate, 1, true) ~= nil or
      (normalizedCandidate ~= "" and logText:find(normalizedCandidate, 1, true) ~= nil) or
      (candidateShort ~= "" and logText:find(candidateShort, 1, true) ~= nil)
  end
  if logText:find("Path should start with a '/'", 1, true) and mentionsCandidate() then
    return false, "SCUM отказал Summon: Path should start with / для " .. tostring(candidate)
  end
  if logText:find("Failed to summon", 1, true) and mentionsCandidate() then
    return false, "SCUM отказал Summon: Failed to summon " .. tostring(candidate)
  end
  if logText:find("LogCheatManager: Fabricate", 1, true) and mentionsCandidate() then
    if logText:find("Failed to summon", 1, true) ~= nil then
      return false, "SCUM отказал Summon после Fabricate: " .. tostring(candidate)
    end
    return true, "fabricate accepted"
  end
  return false, "SCUM не подтвердил Summon в логе для " .. tostring(candidate)
end

function summonLogMessageIsHardFailure(message)
  local text = tostring(message or "")
  return text:find("SCUM отказал", 1, true) ~= nil or
    text:find("Failed to summon", 1, true) ~= nil or
    text:find("Path should start", 1, true) ~= nil
end

function waitForSummonLogVerdict(offset, candidate, timeoutMs, maxBytes)
  local lastMessage = "SCUM не написал результат Summon для " .. tostring(candidate)
  local text = readFromOffset(SERVER_LOG_FILE, offset, maxBytes or 256 * 1024) or ""
  if text ~= "" then
    local accepted, message = summonLogAccepted(text, candidate)
    return accepted, tostring(message or lastMessage), text
  end
  return false, lastMessage, ""
end

function waitForServerLogGrowth(offset, timeoutMs, maxBytes)
  -- Never busy-wait in a UE4SS callback. Deferred callers perform later verification.
  return readFromOffset(SERVER_LOG_FILE, offset, maxBytes or 256 * 1024) or ""
end

function parseScumGlobalStatsLine(line)
  local text = tostring(line or "")
  if text:find("Global Stats", 1, true) == nil then return nil end
  local stats = { line = text }
  for key, value in text:gmatch("([A-Z][A-Z]?)%s*:%s*(-?%d+)") do
    stats[key] = tonumber(value) or 0
  end
  if stats.C == nil and stats.P == nil and stats.Z == nil and stats.R == nil then return nil end
  return stats
end

function latestScumGlobalStatsFromText(text)
  local latest = nil
  for line in tostring(text or ""):gmatch("[^\r\n]+") do
    local stats = parseScumGlobalStatsLine(line)
    if stats ~= nil then latest = stats end
  end
  return latest
end

SCUM_GLOBAL_STATS_CACHE_AT = SCUM_GLOBAL_STATS_CACHE_AT or 0
SCUM_GLOBAL_STATS_CACHE = SCUM_GLOBAL_STATS_CACHE or nil

function latestScumGlobalStatsTail()
  local nowClock = os.clock()
  local ttl = 5
  if type(configNumber) == "function" then
    ttl = math.max(1, configNumber("bridge-safety", { "GlobalStatsCacheSeconds", "globalStatsCacheSeconds" }, ttl))
  end
  if SCUM_GLOBAL_STATS_CACHE ~= nil and (nowClock - (SCUM_GLOBAL_STATS_CACHE_AT or 0)) < ttl then return SCUM_GLOBAL_STATS_CACHE end
  SCUM_GLOBAL_STATS_CACHE_AT = nowClock
  SCUM_GLOBAL_STATS_CACHE = latestScumGlobalStatsFromText(readTail(SERVER_LOG_FILE, 128 * 1024) or "")
  return SCUM_GLOBAL_STATS_CACHE
end

function scumGlobalStatsJson(stats)
  if stats == nil then return "null" end
  local fields = {}
  for _, key in ipairs({ "C", "P", "Z", "R", "S", "A", "V", "IV", "NO" }) do
    if stats[key] ~= nil then table.insert(fields, '"' .. key .. '":' .. tostring(tonumber(stats[key]) or 0)) end
  end
  table.insert(fields, '"line":' .. js(stats.line or ""))
  return "{" .. table.concat(fields, ",") .. "}"
end

function nativeSpawnVerificationSpec(commandName)
  local verb = tostring(commandName or ""):gsub("^%s*#", "")
  if verb == "SpawnRazor" then return { keys = { "R" }, note = "Razor counter R must increase" } end
  if verb == "SpawnBrenner" then return { keys = { "C" }, note = "Brenner has no dedicated Global Stats field; total creature counter C must increase" } end
  if verb == "SpawnZombie" or verb == "SpawnRandomZombie" or verb == "SpawnRandomZombie2" then return { keys = { "Z" }, note = "Zombie counter Z must increase" } end
  if verb == "SpawnAnimal" or verb == "SpawnRandomAnimal" then return { keys = { "A" }, note = "Animal counter A must increase" } end
  if verb == "SpawnArmedNPC" then return { keys = { "C" }, note = "Armed NPC affects total creature counter C" } end
  return { keys = { "C", "Z", "R", "A", "S" }, note = "Any relevant live actor counter must increase" }
end

function nativeSpawnCommandSeen(logText, commandName)
  local verb = tostring(commandName or ""):gsub("^%s*#", "")
  local text = tostring(logText or "")
  return text:find("Command: '" .. verb .. "'", 1, true) ~= nil or
    text:find('Command: "' .. verb .. '"', 1, true) ~= nil or
    text:find("Command: '#" .. verb .. "'", 1, true) ~= nil or
    text:find('Command: "#' .. verb .. '"', 1, true) ~= nil
end

function nativeSpawnStatsIncreased(beforeStats, afterStats, commandName)
  if beforeStats == nil then return false, "нет базовой строки Global Stats перед командой" end
  if afterStats == nil then return false, "нет новой строки Global Stats после команды" end
  local spec = nativeSpawnVerificationSpec(commandName)
  for _, key in ipairs(spec.keys or {}) do
    local before = tonumber(beforeStats[key])
    local after = tonumber(afterStats[key])
    if before ~= nil and after ~= nil and after > before then
      return true, tostring(key) .. " " .. tostring(before) .. " -> " .. tostring(after)
    end
  end
  local parts = {}
  for _, key in ipairs(spec.keys or {}) do
    table.insert(parts, tostring(key) .. " " .. tostring(tonumber(beforeStats[key]) or 0) .. " -> " .. tostring(tonumber(afterStats[key]) or 0))
  end
  return false, table.concat(parts, ", ")
end

function summonStatsVerificationKeys()
  return { "NO", "IV", "C", "Z", "R", "A", "S", "V" }
end

function summonStatsIncreased(beforeStats, afterStats)
  if beforeStats == nil then return false, "нет базовой строки Global Stats перед Summon" end
  if afterStats == nil then return false, "нет новой строки Global Stats после Summon" end
  local parts = {}
  for _, key in ipairs(summonStatsVerificationKeys()) do
    local before = tonumber(beforeStats[key])
    local after = tonumber(afterStats[key])
    if before ~= nil and after ~= nil then
      table.insert(parts, tostring(key) .. " " .. tostring(before) .. " -> " .. tostring(after))
      if after > before then return true, tostring(key) .. " " .. tostring(before) .. " -> " .. tostring(after) end
    end
  end
  return false, table.concat(parts, ", ")
end

function waitForSummonStatsVerdict(offset, beforeStats, timeoutMs, maxBytes)
  local detail = "нет новой строки Global Stats после Summon"
  local text = readFromOffset(SERVER_LOG_FILE, offset or 0, maxBytes or 512 * 1024) or ""
  local stats = latestScumGlobalStatsFromText(text)
  if stats ~= nil then
    local increased, statDetail = summonStatsIncreased(beforeStats, stats)
    return increased, tostring(statDetail or detail), stats
  end
  return false, detail, nil
end

function finishNativeAdminSpawnVerification(args)
  args = args or {}
  local logText = readFromOffset(SERVER_LOG_FILE, args.logOffset or 0, 512 * 1024) or ""
  local afterStats = latestScumGlobalStatsFromText(logText) or latestScumGlobalStatsTail()
  local commandSeen = nativeSpawnCommandSeen(logText, args.nativeCommand)
  local increased, statDetail = nativeSpawnStatsIncreased(args.beforeStats, afterStats, args.nativeCommand)
  local okVerified = commandSeen and increased
  local attemptsText = tostring(args.attemptsText or "")
  if commandSeen then attemptsText = attemptsText .. " | native log command seen" else attemptsText = attemptsText .. " | native log command missing" end
  attemptsText = attemptsText .. " | stats " .. tostring(statDetail or "")
  local data = '{"actorClass":' .. js(args.actorClass or "") ..
    ',"route":' .. js(args.nativeRoute or "") ..
    ',"adminCommand":' .. js("#" .. tostring(args.nativeCommand or "")) ..
    ',"verified":' .. (okVerified and "true" or "false") ..
    ',"commandSeen":' .. (commandSeen and "true" or "false") ..
    ',"statsDetail":' .. js(statDetail or "") ..
    ',"beforeStats":' .. scumGlobalStatsJson(args.beforeStats) ..
    ',"afterStats":' .. scumGlobalStatsJson(afterStats) .. '}'
  appendActionEvent("spawn_actor_native_verify", okVerified, args.live,
    okVerified and ("Родная SCUM-команда подтверждена: " .. tostring(args.actorClass or "")) or
      ("Родная SCUM-команда не подтверждена: " .. tostring(statDetail or "")),
    '{"actorClass":' .. js(args.actorClass or "") ..
      ',"route":' .. js(args.nativeRoute or "") ..
      ',"adminCommand":' .. js("#" .. tostring(args.nativeCommand or "")) ..
      ',"verified":' .. (okVerified and "true" or "false") ..
      ',"attempts":' .. js(attemptsText) ..
      ',"beforeStats":' .. scumGlobalStatsJson(args.beforeStats) ..
      ',"afterStats":' .. scumGlobalStatsJson(afterStats) .. '}')
  if tostring(args.requestId or "") ~= "" then
    if okVerified then
      writeAll(RESULT_FILE, ok(args.resultCommand or "spawn_actor",
        "Актор создан рядом с игроком через родную SCUM-команду и подтверждён логом: " .. tostring(args.actorClass or ""),
        data, args.requestId))
    else
      writeAll(RESULT_FILE, fail(args.resultCommand or "spawn_actor",
        "SCUM-команда отправлена, но появление актора не подтверждено по логу: " .. tostring(statDetail or ""), args.requestId))
    end
  end
  return okVerified, statDetail
end

function ensureCheatManagerForController(pc)
  if pc == nil or not isValidObject(pc) then return nil, "player controller is not ready" end
  local cm = firstProp(pc, { "CheatManager", "cheatManager" })
  if cm ~= nil and isValidObject(cm) then return cm, "existing" end
  local cmClass = nil
  pcall(function() cmClass = StaticFindObject("/Script/Engine.CheatManager") end)
  if cmClass == nil or not isValidObject(cmClass) then
    local found = findFirst({ "CheatManager" })
    if found ~= nil and isValidObject(found) then cmClass = found end
  end
  if cmClass == nil or not isValidObject(cmClass) then return nil, "CheatManager class not found" end
  if StaticConstructObject == nil then return nil, "StaticConstructObject is not available" end
  local okConstruct, constructed = pcall(function() return StaticConstructObject(cmClass, pc) end)
  if not okConstruct or constructed == nil or not isValidObject(constructed) then
    return nil, "CheatManager construct failed: " .. tostring(constructed)
  end
  pcall(function() pc.CheatManager = constructed end)
  cm = firstProp(pc, { "CheatManager", "cheatManager" })
  if cm ~= nil and isValidObject(cm) then return cm, "constructed" end
  return constructed, "constructed-unassigned"
end

function actorFindRuntimeClassNames(actorClass)
  local names = {}
  local seen = {}
  local function add(value)
    value = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if value == "" then return end
    value = value:gsub("^BlueprintGeneratedClass'", ""):gsub("^Class'", ""):gsub("'$", "")
    value = value:match("%.([^%.\\/']+)$") or value:match("([^/\\']+)$") or value
    if value == "" or seen[value:lower()] then return end
    seen[value:lower()] = true
    table.insert(names, value)
  end
  local entry = actorCatalogLookup(actorClass)
  add(actorClass)
  if entry ~= nil and entry ~= false then add(entry.actorClass) end
  for _, candidate in ipairs(actorSummonCandidates(actorClass)) do add(candidate) end
  return names
end

function runtimeActorSnapshot(actorClass)
  local set = {}
  local count = 0
  for _, className in ipairs(actorFindRuntimeClassNames(actorClass)) do
    local okFind, arr = pcall(function() return FindAllOf(className) end)
    if okFind and arr ~= nil then
      for _, obj in pairs(arr) do
        if obj ~= nil and isValidObject(obj) then
          local key = objectKey(obj)
          if key ~= "" and set[key] == nil then
            set[key] = true
            count = count + 1
          end
        end
      end
    end
  end
  return set, count
end

function findNewRuntimeActor(actorClass, beforeSet)
  beforeSet = beforeSet or {}
  local lastActor = nil
  local foundCount = 0
  for _, className in ipairs(actorFindRuntimeClassNames(actorClass)) do
    local okFind, arr = pcall(function() return FindAllOf(className) end)
    if okFind and arr ~= nil then
      for _, obj in pairs(arr) do
        if obj ~= nil and isValidObject(obj) then
          local key = objectKey(obj)
          if key ~= "" and beforeSet[key] ~= true then
            lastActor = obj
            foundCount = foundCount + 1
          end
        end
      end
    end
  end
  return lastActor, foundCount
end

function actorCatalogNeedsRuntimePlacement(entry)
  if entry == nil or entry == false then return false end
  local category = tostring(entry.category or ""):lower()
  local parentName = actorRouteParentName(entry)
  local selfManagedCategories = {
    character = true,
    zombie = true,
    animal = true,
    armednpc = true,
    vehicle = true,
    item = true,
    ammunition_class = true,
    fakeitems = true
  }
  if selfManagedCategories[category] then return false end
  if parentName == "actor" or parentName == "building" or parentName == "staticmeshactor" then return true end
  if parentName:find("door", 1, true) ~= nil then return true end
  if category:find("building", 1, true) ~= nil or category:find("house", 1, true) ~= nil or category:find("door", 1, true) ~= nil then return true end
  return false
end

function actorPlacementLocation(info, entry)
  local x, y, z = vectorOf((info or {}).pawn)
  local forwardX, forwardY = forwardVectorOf((info or {}).pawn)
  if forwardX == nil or forwardY == nil then forwardX, forwardY = forwardVectorOf((info or {}).pc) end
  if forwardX == nil or forwardY == nil then
    local yaw = rotationYawOf((info or {}).pc) or rotationYawOf((info or {}).pawn) or 0
    local radians = math.rad(yaw)
    forwardX, forwardY = math.cos(radians), math.sin(radians)
  end
  local needsPlacement = actorCatalogNeedsRuntimePlacement(entry)
  local defaultDistance = needsPlacement and 900 or 240
  local defaultLift = needsPlacement and 120 or 70
  local distance = math.max(100, math.min(configNumber("bridge-safety", { "SummonActorForwardDistance", "summonActorForwardDistance" }, defaultDistance), 3000))
  local lift = math.max(0, math.min(configNumber("bridge-safety", { "SummonActorLiftZ", "summonActorLiftZ" }, defaultLift), 600))
  return { X = x + forwardX * distance, Y = y + forwardY * distance, Z = z + lift }
end

function forceActorComponentsVisibleAndReplicated(actor)
  local attempts = {}
  local function touch(component, label)
    if component == nil or not isValidObject(component) then return end
    local okHidden, errHidden = safeCall(component, "SetHiddenInGame", false, true)
    table.insert(attempts, tostring(label) .. ".SetHiddenInGame(false,true)=" .. (okHidden and "ok" or tostring(errHidden)))
    local okVisible, errVisible = safeCall(component, "SetVisibility", true, true)
    table.insert(attempts, tostring(label) .. ".SetVisibility(true,true)=" .. (okVisible and "ok" or tostring(errVisible)))
    local okRep, errRep = safeCall(component, "SetIsReplicated", true)
    table.insert(attempts, tostring(label) .. ".SetIsReplicated(true)=" .. (okRep and "ok" or tostring(errRep)))
    local okTick, errTick = safeCall(component, "SetComponentTickEnabled", true)
    table.insert(attempts, tostring(label) .. ".SetComponentTickEnabled(true)=" .. (okTick and "ok" or tostring(errTick)))
  end
  local okRoot, root = safeCall(actor, "K2_GetRootComponent")
  if okRoot and root ~= nil and isValidObject(root) then touch(root, "root") end
  for _, classPath in ipairs({ "/Script/Engine.SkeletalMeshComponent", "/Script/Engine.StaticMeshComponent", "/Script/Engine.PrimitiveComponent", "/Script/Engine.SceneComponent" }) do
    local cls = nil
    pcall(function() cls = StaticFindObject(classPath) end)
    if cls ~= nil and isValidObject(cls) then
      local okComponents, components = safeCall(actor, "K2_GetComponentsByClass", cls)
      table.insert(attempts, "K2_GetComponentsByClass(" .. tostring(classPath) .. ")=" .. (okComponents and "ok" or tostring(components)))
      if okComponents and components ~= nil then
        local count = 0
        for _, component in pairs(components) do
          if component ~= nil and isValidObject(component) then
            count = count + 1
            if count <= 24 then touch(component, tostring(classPath):match("([^/]+)$") .. "#" .. tostring(count)) end
          end
        end
        table.insert(attempts, tostring(classPath) .. ".count=" .. tostring(count))
      end
    else
      table.insert(attempts, "StaticFindObject(" .. tostring(classPath) .. ")=nil")
    end
  end
  return attempts
end

function placeSummonedRuntimeActor(actor, info, entry)
  local attempts = {}
  if actor == nil or not isValidObject(actor) then return false, "runtime actor not found", attempts end
  local loc = actorPlacementLocation(info, entry)
  local beforeX, beforeY, beforeZ = vectorOf(actor)
  table.insert(attempts, "beforeLocation=" .. tostring(beforeX) .. "," .. tostring(beforeY) .. "," .. tostring(beforeZ))
  local okHidden, errHidden = safeCall(actor, "SetActorHiddenInGame", false)
  table.insert(attempts, "SetActorHiddenInGame(false)=" .. (okHidden and "ok" or tostring(errHidden)))
  local okCollision, errCollision = safeCall(actor, "SetActorEnableCollision", true)
  table.insert(attempts, "SetActorEnableCollision(true)=" .. (okCollision and "ok" or tostring(errCollision)))
  local okRep, errRep = safeCall(actor, "SetReplicates", true)
  table.insert(attempts, "SetReplicates(true)=" .. (okRep and "ok" or tostring(errRep)))
  local okRepMove, errRepMove = safeCall(actor, "SetReplicateMovement", true)
  table.insert(attempts, "SetReplicateMovement(true)=" .. (okRepMove and "ok" or tostring(errRepMove)))
  local okDorm, errDorm = safeCall(actor, "SetNetDormancy", 1)
  table.insert(attempts, "SetNetDormancy(DORM_Awake)=" .. (okDorm and "ok" or tostring(errDorm)))
  local okAlways, errAlways = pcall(function() actor.bAlwaysRelevant = true end)
  table.insert(attempts, "bAlwaysRelevant=true=" .. (okAlways and "ok" or tostring(errAlways)))
  local okOwnerRel, errOwnerRel = pcall(function() actor.bNetUseOwnerRelevancy = false end)
  table.insert(attempts, "bNetUseOwnerRelevancy=false=" .. (okOwnerRel and "ok" or tostring(errOwnerRel)))
  local okOnlyOwner, errOnlyOwner = pcall(function() actor.bOnlyRelevantToOwner = false end)
  table.insert(attempts, "bOnlyRelevantToOwner=false=" .. (okOnlyOwner and "ok" or tostring(errOnlyOwner)))
  local okLoadClient, errLoadClient = pcall(function() actor.bNetLoadOnClient = true end)
  table.insert(attempts, "bNetLoadOnClient=true=" .. (okLoadClient and "ok" or tostring(errLoadClient)))
  local okNetTemporary, errNetTemporary = pcall(function() actor.bNetTemporary = false end)
  table.insert(attempts, "bNetTemporary=false=" .. (okNetTemporary and "ok" or tostring(errNetTemporary)))
  local okRemoteRole, errRemoteRole = pcall(function() actor.RemoteRole = 1 end)
  table.insert(attempts, "RemoteRole=ROLE_SimulatedProxy=" .. (okRemoteRole and "ok" or tostring(errRemoteRole)))
  local okFrequency, errFrequency = pcall(function() actor.NetUpdateFrequency = 30 end)
  table.insert(attempts, "NetUpdateFrequency=30=" .. (okFrequency and "ok" or tostring(errFrequency)))
  local okMinFrequency, errMinFrequency = pcall(function() actor.MinNetUpdateFrequency = 10 end)
  table.insert(attempts, "MinNetUpdateFrequency=10=" .. (okMinFrequency and "ok" or tostring(errMinFrequency)))
  local okPriority, errPriority = pcall(function() actor.NetPriority = 3 end)
  table.insert(attempts, "NetPriority=3=" .. (okPriority and "ok" or tostring(errPriority)))
  local okCull, errCull = pcall(function() actor.NetCullDistanceSquared = 250000000000 end)
  table.insert(attempts, "NetCullDistanceSquared=250000000000=" .. (okCull and "ok" or tostring(errCull)))
  for _, attempt in ipairs(forceActorComponentsVisibleAndReplicated(actor)) do table.insert(attempts, attempt) end
  local okMove, errMove = safeCall(actor, "K2_SetActorLocation", loc, false, {}, true)
  table.insert(attempts, "K2_SetActorLocation=" .. (okMove and "ok" or tostring(errMove)))
  if not okMove then
    okMove, errMove = safeCall(actor, "SetActorLocation", loc)
    table.insert(attempts, "SetActorLocation=" .. (okMove and "ok" or tostring(errMove)))
  end
  if not okMove then
    local currentX, currentY, currentZ = vectorOf(actor)
    local deltaX = math.abs((tonumber(currentX) or 0) - (tonumber(loc.X) or 0))
    local deltaY = math.abs((tonumber(currentY) or 0) - (tonumber(loc.Y) or 0))
    local deltaZ = math.abs((tonumber(currentZ) or 0) - (tonumber(loc.Z) or 0))
    if deltaX <= 250 and deltaY <= 250 and deltaZ <= 400 then
      okMove = true
      errMove = "actor already near placement target"
      table.insert(attempts, "placement-distance-ok=" .. tostring(math.floor(deltaX)) .. "," .. tostring(math.floor(deltaY)) .. "," .. tostring(math.floor(deltaZ)))
    end
  end
  local okFlush, errFlush = safeCall(actor, "FlushNetDormancy")
  table.insert(attempts, "FlushNetDormancy=" .. (okFlush and "ok" or tostring(errFlush)))
  local okForce, errForce = safeCall(actor, "ForceNetUpdate")
  table.insert(attempts, "ForceNetUpdate=" .. (okForce and "ok" or tostring(errForce)))
  local afterX, afterY, afterZ = vectorOf(actor)
  table.insert(attempts, "afterLocation=" .. tostring(afterX) .. "," .. tostring(afterY) .. "," .. tostring(afterZ))
  if okMove then return true, "placed " .. tostring(afterX) .. "," .. tostring(afterY) .. "," .. tostring(afterZ) .. " target " .. tostring(loc.X) .. "," .. tostring(loc.Y) .. "," .. tostring(loc.Z), attempts end
  return false, tostring(errMove or "actor move failed"), attempts
end

function summonActorWithCheatManager(cm, actorClass, info)
  local attempts = {}
  local logStart = fileSize(SERVER_LOG_FILE)
  local beforeStats = latestScumGlobalStatsTail()
  local lastError = "Summon failed"
  local entry = actorCatalogLookup(actorClass)
  local runtimeScanEnabled = configBool("bridge-safety", { "SummonEnableRuntimeScan", "summonEnableRuntimeScan" }, false) == true
  if actorCatalogIsTraderLike(actorClass, entry) or actorCatalogIsTradePostLike(actorClass, entry) then
    runtimeScanEnabled = summonTraderRuntimeScanAllowed()
  end
  local beforeObjects, beforeObjectCount = nil, 0
  if runtimeScanEnabled then
    beforeObjects, beforeObjectCount = runtimeActorSnapshot(actorClass)
    table.insert(attempts, "runtime before count=" .. tostring(beforeObjectCount or 0))
  else
    table.insert(attempts, "runtime scan disabled")
  end
  for _, attempt in ipairs(preloadActorCatalogForSummon(actorClass)) do table.insert(attempts, attempt) end
  for _, candidate in ipairs(actorSummonCandidates(actorClass)) do
    for _, attempt in ipairs(preloadActorClassCandidate(candidate)) do table.insert(attempts, attempt) end
    local fstringBypass = enableScopedAdminBypass(350, info, false)
    local okFString, errFString = pcall(function() return cm:Summon(ueString(candidate)) end)
    disableScopedAdminBypass(fstringBypass)
    table.insert(attempts, "CheatManager.Summon(" .. tostring(candidate) .. ")#fstring=" .. (okFString and "ok" or tostring(errFString)))
    if okFString then
      return true, "CheatManager.Summon#fstring:" .. tostring(candidate), attempts,
        { candidate = candidate, logOffset = logStart, beforeStats = beforeStats, beforeObjects = beforeObjects, beforeObjectCount = beforeObjectCount, runtimeScan = runtimeScanEnabled }
    else
      lastError = tostring(errFString)
    end
    local plainBypass = enableScopedAdminBypass(350, info, false)
    local okPlain, errPlain = pcall(function() return cm:Summon(candidate) end)
    disableScopedAdminBypass(plainBypass)
    table.insert(attempts, "CheatManager.Summon(" .. tostring(candidate) .. ")#plain=" .. (okPlain and "ok" or tostring(errPlain)))
    if okPlain then
      return true, "CheatManager.Summon#plain:" .. tostring(candidate), attempts,
        { candidate = candidate, logOffset = logStart, beforeStats = beforeStats, beforeObjects = beforeObjects, beforeObjectCount = beforeObjectCount, runtimeScan = runtimeScanEnabled }
    else
      lastError = tostring(errPlain)
    end
  end
  return false, lastError, attempts, { verified = false, beforeStats = beforeStats, beforeObjects = beforeObjects, runtimeScan = runtimeScanEnabled, statsDetail = lastError }
end

function finishSummonActorVerification(args)
  args = args or {}
  local entry = actorCatalogLookup(args.actorClass or "")
  local logText = readFromOffset(SERVER_LOG_FILE, args.logOffset or 0, 512 * 1024) or ""
  local accepted, logMessage = summonLogAccepted(logText, args.candidate or args.actorClass or "")
  local afterStats = latestScumGlobalStatsFromText(logText) or latestScumGlobalStatsTail()
  local statsOk, statsDetail = summonStatsIncreased(args.beforeStats, afterStats)
  local runtimeActor = nil
  local newRuntimeCount = 0
  if args.directActor ~= nil and isValidObject(args.directActor) then
    runtimeActor = args.directActor
    newRuntimeCount = 1
  elseif args.runtimeScan == true then
    runtimeActor, newRuntimeCount = findNewRuntimeActor(args.actorClass or "", args.beforeObjects or {})
  end
  local needsPlacement = actorCatalogNeedsRuntimePlacement(entry)
  local actualTraderLike = actorCatalogIsActualTraderActor(args.actorClass or "", entry)
  local tradePostLike = actorCatalogIsTradePostLike(args.actorClass or "", entry)
  local bankerLike = actorCatalogIsBankerActor(args.actorClass or "", entry)
  local traderOrTradePost = actualTraderLike or tradePostLike or bankerLike
  local placeOk, placeDetail, placeAttempts = false, "", {}
  if runtimeActor ~= nil and isValidObject(runtimeActor) then
    if needsPlacement or configBool("bridge-safety", { "SummonRepositionAllActors", "summonRepositionAllActors" }, false) then
      placeOk, placeDetail, placeAttempts = placeSummonedRuntimeActor(runtimeActor, args.live, entry)
    else
      placeOk, placeDetail = true, "runtime actor found"
    end
  end
  local runtimeOk = runtimeActor ~= nil and isValidObject(runtimeActor)
  local traderInitOk, traderInitDetail, traderInitAttempts = true, "not-trader", {}
  if runtimeOk then
    if tradePostLike then
      traderInitOk, traderInitDetail, traderInitAttempts = initializeSummonedTradePostActor(runtimeActor, args.actorClass or "")
    elseif bankerLike then
      traderInitOk, traderInitDetail, traderInitAttempts = initializeSummonedBankerActor(runtimeActor, args.actorClass or "")
    elseif actualTraderLike then
      traderInitOk, traderInitDetail, traderInitAttempts = initializeSummonedTraderActor(runtimeActor, args.actorClass or "")
    end
  elseif traderOrTradePost then
    traderInitOk = false
    traderInitDetail = "trader/tradepost требует runtime+economy проверки; runtime scan отключён safety-флагами или актор не найден"
  end
  local placementRuntimeOnlyBlocked = needsPlacement and
    not actualTraderLike and
    not tradePostLike
  local directOk = args.directSpawnOk == true and runtimeOk and not placementRuntimeOnlyBlocked
  local summonOk = accepted and statsOk and not placementRuntimeOnlyBlocked and not traderOrTradePost
  local runtimeSpawnOk = runtimeOk and (not needsPlacement or (placeOk and not placementRuntimeOnlyBlocked))
  local okVerified = (summonOk or directOk or runtimeSpawnOk) and (not needsPlacement or (runtimeOk and placeOk)) and traderInitOk
  if traderOrTradePost then okVerified = runtimeOk and traderInitOk end
  local cleanupAttempts = {}
  if not okVerified and runtimeOk and (needsPlacement or traderOrTradePost) then
    local cleanupTarget = objectFullName(runtimeActor)
    local okDestroy, errDestroy = safeCall(runtimeActor, "K2_DestroyActor")
    table.insert(cleanupAttempts, "K2_DestroyActor(" .. tostring(cleanupTarget) .. ")=" .. (okDestroy and "ok" or tostring(errDestroy)))
    if not okDestroy then
      okDestroy, errDestroy = safeCall(runtimeActor, "Destroy")
      table.insert(cleanupAttempts, "Destroy(" .. tostring(cleanupTarget) .. ")=" .. (okDestroy and "ok" or tostring(errDestroy)))
    end
  end
  local attemptsText = tostring(args.attemptsText or "")
  if #placeAttempts > 0 then attemptsText = attemptsText .. " | placement " .. table.concat(placeAttempts, " | ") end
  if #traderInitAttempts > 0 then attemptsText = attemptsText .. " | traderInit " .. table.concat(traderInitAttempts, " | ") end
  if #cleanupAttempts > 0 then attemptsText = attemptsText .. " | cleanup " .. table.concat(cleanupAttempts, " | ") end
  if placementRuntimeOnlyBlocked then
    attemptsText = attemptsText .. " | placement-runtime-only-blocked=true (map/building/placeable needs native persistent route, not UObject existence)"
  end
  attemptsText = attemptsText .. " | log=" .. tostring(logMessage or "") .. " | stats=" .. tostring(statsDetail or "") .. " | runtimeNew=" .. tostring(newRuntimeCount or 0) .. " | direct=" .. tostring(args.directSpawnDetail or "") .. " | place=" .. tostring(placeDetail or "") .. " | trader=" .. tostring(traderInitDetail or "")
  local data = '{"actorClass":' .. js(args.actorClass or "") ..
    ',"route":' .. js(args.route or "") ..
    ',"candidate":' .. js(args.candidate or "") ..
    ',"verified":' .. (okVerified and "true" or "false") ..
    ',"fabricateLog":' .. (accepted and "true" or "false") ..
    ',"statsConfirmed":' .. (statsOk and "true" or "false") ..
    ',"runtimeConfirmed":' .. (runtimeOk and "true" or "false") ..
    ',"directSpawnConfirmed":' .. (directOk and "true" or "false") ..
    ',"needsPlacement":' .. (needsPlacement and "true" or "false") ..
    ',"placementRuntimeOnlyBlocked":' .. (placementRuntimeOnlyBlocked and "true" or "false") ..
    ',"placementConfirmed":' .. (placeOk and "true" or "false") ..
    ',"traderInitialized":' .. (traderInitOk and "true" or "false") ..
    ',"runtimeActor":' .. js(objectFullName(runtimeActor)) ..
    ',"statsDetail":' .. js(statsDetail or "") ..
    ',"placementDetail":' .. js(placeDetail or "") ..
    ',"traderDetail":' .. js(traderInitDetail or "") ..
    ',"beforeStats":' .. scumGlobalStatsJson(args.beforeStats) ..
    ',"afterStats":' .. scumGlobalStatsJson(afterStats) .. '}'
  local verifyMessage = okVerified and
    (needsPlacement and ("Актор создан и поставлен перед игроком: " .. tostring(args.actorClass or "")) or ("Summon подтверждён логом/stats: " .. tostring(args.actorClass or ""))) or
    (placementRuntimeOnlyBlocked and ("Placement/map-building runtime-only spawn заблокирован как ghost-route: " .. tostring(args.actorClass or "")) or
      ("Summon не подтверждён runtime/видимостью: " .. tostring(args.actorClass or "")))
  appendActionEvent("spawn_actor_verify", okVerified, args.live,
    verifyMessage,
    '{"actorClass":' .. js(args.actorClass or "") ..
      ',"route":' .. js(args.route or "") ..
      ',"attempts":' .. js(attemptsText) ..
      ',"verified":' .. (okVerified and "true" or "false") ..
      ',"placementRuntimeOnlyBlocked":' .. (placementRuntimeOnlyBlocked and "true" or "false") ..
      ',"runtimeActor":' .. js(objectFullName(runtimeActor)) .. '}')
  if tostring(args.requestId or "") ~= "" then
    if okVerified then
      writeAll(RESULT_FILE, ok(args.resultCommand or "spawn_actor",
        needsPlacement and ("Актор создан, найден в runtime и поставлен перед игроком: " .. tostring(args.actorClass or "")) or
          ("Актор создан через Summon и подтверждён логом/stats: " .. tostring(args.actorClass or "")),
        data, args.requestId))
    else
      local failureMessage = placementRuntimeOnlyBlocked and
        ("Placement/map-building actor не считается рабочим по runtime-only проверке; это ghost-route без native persistence/client visibility: " .. tostring(args.actorClass or "")) or
        (traderOrTradePost and
          ("Trader/tradepost не подтверждён как функциональный/persistent: " .. tostring(traderInitDetail or "") .. "; " .. tostring(logMessage or "") .. "; " .. tostring(statsDetail or "")) or
          ("Summon отправлен, но видимый runtime actor не подтверждён: " .. tostring(logMessage or "") .. "; " .. tostring(statsDetail or "") .. "; " .. tostring(placeDetail or "")))
      writeAll(RESULT_FILE, fail(args.resultCommand or "spawn_actor",
        failureMessage, args.requestId))
    end
  end
  return okVerified, data
end

function spawnActorForInfo(actorClass, info, asyncResult)
  local cleanActor = actorSummonToken(actorClass)
  if cleanActor == "" then return false, "Класс актора не указан или содержит недопустимые символы.", "{}" end
  local live, ready, readyMessage, readyReason = deliveryReadyInfo(info, { requireInventory = false })
  if not ready then return false, deliveryReadyMessage(readyReason) .. " (" .. tostring(readyMessage or "") .. ")", "{}" end
  local attempts = {}
  local entry = actorCatalogLookup(cleanActor)
  local plainSummonMode = spawnActorPreferPlainSummon()
  local nonActorReason = actorCatalogNonActorReason(entry)
  if nonActorReason ~= nil and plainSummonMode and entry ~= nil and entry ~= false and entry.summonableActor == true then
    table.insert(attempts, "plain summon mode overrides catalog placement warning: " .. tostring(nonActorReason))
    nonActorReason = nil
  end
  if nonActorReason ~= nil then
    table.insert(attempts, "actor route=blocked-non-actor reason=" .. tostring(nonActorReason))
    appendActionEvent("spawn_actor", false, live, tostring(nonActorReason),
      '{"actorClass":' .. js(cleanActor) ..
        ',"route":"blocked-non-actor"' ..
        ',"parentClass":' .. js(tostring(entry and entry.parentClass or "")) ..
        ',"category":' .. js(tostring(entry and entry.category or "")) ..
        ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}')
    return false, "Это не Actor-класс для Summon: " .. tostring(nonActorReason),
      '{"actorClass":' .. js(cleanActor) ..
        ',"route":"blocked-non-actor"' ..
        ',"parentClass":' .. js(tostring(entry and entry.parentClass or "")) ..
        ',"category":' .. js(tostring(entry and entry.category or "")) .. '}'
  end
  if configBool("bridge-safety", {
    "SpawnActorUsePersistentNativeServerSpawn",
    "spawnActorUsePersistentNativeServerSpawn",
    "WebPanelSpawnActorUsePersistentNativeServerSpawn",
    "webPanelSpawnActorUsePersistentNativeServerSpawn"
  }, true) == true then
    table.insert(attempts, "actor route=native-persistent-server-spawn default")
    local nativeOk, nativeMessage, nativeData = nativePersistentActorSpawnForInfo(cleanActor, live, entry, {
      requestId = tostring((asyncResult or {}).requestId or ""),
      commandName = tostring((asyncResult or {}).commandName or "spawn_actor"),
      persist = true,
      timeoutMs = 12000,
      source = "web-panel-spawn-actor"
    })
    if nativeOk or configBool("bridge-safety", {
      "PersistentNativeServerSpawnFallbackToSummon",
      "persistentNativeServerSpawnFallbackToSummon",
      "SpawnActorPersistentFallbackToSummon",
      "spawnActorPersistentFallbackToSummon"
    }, false) ~= true then
      return nativeOk, nativeMessage, nativeData
    end
    table.insert(attempts, "native persistent server-spawn failed; fallback enabled: " .. tostring(nativeMessage))
  end
  local nativeCommand, nativeRoute = nativeAdminSpawnCommandForActor(cleanActor)
  if nativeCommand ~= "" then
    table.insert(attempts, "actor route=" .. tostring(nativeRoute) .. " command=redacted")
    local logOffset = fileSize(SERVER_LOG_FILE)
    local beforeStats = latestScumGlobalStatsTail()
    local okAdmin, adminMessage = adminExec(nativeCommand, live)
    table.insert(attempts, "native admin command=" .. (okAdmin and "ok" or tostring(adminMessage)))
    appendActionEvent("spawn_actor", okAdmin, live, okAdmin and ("Родная SCUM-команда отправлена, ждём подтверждение логом: " .. cleanActor) or tostring(adminMessage),
      '{"actorClass":' .. js(cleanActor) ..
        ',"route":' .. js(nativeRoute or "") ..
        ',"adminCommand":' .. js("#" .. tostring(nativeCommand)) ..
        ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}')
    if okAdmin then
      local requestId = tostring((asyncResult or {}).requestId or "")
      if requestId ~= "" and deferGame(9000, function()
        finishNativeAdminSpawnVerification({
          actorClass = cleanActor,
          nativeCommand = nativeCommand,
          nativeRoute = nativeRoute,
          live = live,
          logOffset = logOffset,
          beforeStats = beforeStats,
          attemptsText = table.concat(attempts or {}, " | "),
          requestId = requestId,
          resultCommand = (asyncResult or {}).commandName or "spawn_actor"
        })
      end) then
        return nil, "Ожидаю подтверждение родной SCUM-команды по Global Stats.", "__async__"
      end
      local verified, statDetail = finishNativeAdminSpawnVerification({
        actorClass = cleanActor,
        nativeCommand = nativeCommand,
        nativeRoute = nativeRoute,
        live = live,
        logOffset = logOffset,
        beforeStats = beforeStats,
        attemptsText = table.concat(attempts or {}, " | ")
      })
      if verified then
        return true, "Актор создан рядом с игроком через родную SCUM-команду и подтверждён логом: " .. cleanActor,
          '{"actorClass":' .. js(cleanActor) .. ',"route":' .. js(nativeRoute or "") .. ',"adminCommand":' .. js("#" .. tostring(nativeCommand)) .. ',"verified":true}'
      end
      return false, "SCUM-команда отправлена, но появление актора не подтверждено по логу: " .. tostring(statDetail or ""),
        '{"actorClass":' .. js(cleanActor) .. ',"route":' .. js(nativeRoute or "") .. ',"adminCommand":' .. js("#" .. tostring(nativeCommand)) .. ',"verified":false}'
    end
  end
  local needsPlacement = actorCatalogNeedsRuntimePlacement(entry)
  local placeableBlockedFromDirect = actorCatalogPlaceableReason(entry) ~= nil
  local actualTraderLike = actorCatalogIsActualTraderActor(cleanActor, entry)
  local tradePostLike = actorCatalogIsTradePostLike(cleanActor, entry)
  local bankerLike = actorCatalogIsBankerActor(cleanActor, entry)
  local traderLike = actualTraderLike or tradePostLike or bankerLike
  if plainSummonMode and traderLike then
    table.insert(attempts, "plain summon mode enabled; skipping functional trader/native lifecycle routes")
  end
  if not plainSummonMode and traderLike and configBool("bridge-safety", { "AllowFunctionalTraderProxyRoute", "allowFunctionalTraderProxyRoute" }, false) == true then
    return spawnFunctionalTraderProxyForInfo(cleanActor, live, entry, attempts)
  end
  if not plainSummonMode and traderLike and configBool("bridge-safety", { "AllowNativeTraderCppModRoute", "allowNativeTraderCppModRoute" }, true) == true then
    local nativeOk, nativeMessage, nativeData = nativeFunctionalTraderForInfo(cleanActor, live, entry, attempts, (asyncResult or {}).requestId)
    if nativeOk or configBool("bridge-safety", { "AllowExperimentalFunctionalTraderRuntimeRoutes", "allowExperimentalFunctionalTraderRuntimeRoutes" }, false) ~= true then
      return nativeOk, nativeMessage, nativeData
    end
    table.insert(attempts, "native cppmod route failed; experimental Lua fallback allowed: " .. tostring(nativeMessage))
  end
  if not plainSummonMode and traderLike and configBool("bridge-safety", { "AllowExperimentalFunctionalTraderRuntimeRoutes", "allowExperimentalFunctionalTraderRuntimeRoutes" }, false) ~= true then
    return functionalTraderLifecycleBlockedForInfo(cleanActor, live, attempts, "blocked-native-lifecycle-required")
  end
  if not plainSummonMode and actualTraderLike and configBool("bridge-safety", { "AllowFunctionalTraderMarkerLifecycleRoute", "allowFunctionalTraderMarkerLifecycleRoute" }, false) == true then
    local markerOk, markerMessage, markerData = spawnFunctionalTraderMarkerRouteForInfo(cleanActor, live, entry, attempts)
    if markerOk or configBool("bridge-safety", { "AllowFunctionalTraderMarkerFallbackToLinkedActor", "allowFunctionalTraderMarkerFallbackToLinkedActor" }, false) ~= true then
      return markerOk, markerMessage, markerData
    end
    table.insert(attempts, "marker lifecycle route failed; fallback to linked actor route: " .. tostring(markerMessage))
  end
  if not plainSummonMode and actualTraderLike and configBool("bridge-safety", { "AllowFunctionalTraderLinkedActorRegistration", "allowFunctionalTraderLinkedActorRegistration" }, false) == true then
    local linkedOk, linkedMessage, linkedData = spawnFunctionalLinkedTraderActorForInfo(cleanActor, live, entry, attempts)
    if linkedOk or configBool("bridge-safety", { "AllowFunctionalTraderLinkedFallbackToTradePostClone", "allowFunctionalTraderLinkedFallbackToTradePostClone" }, false) ~= true then
      return linkedOk, linkedMessage, linkedData
    end
    table.insert(attempts, "linked trader actor route failed; fallback to TradePost route: " .. tostring(linkedMessage))
  end
  if not plainSummonMode and traderLike and configBool("bridge-safety", { "AllowFunctionalTraderSpawnedTradePostRegistration", "allowFunctionalTraderSpawnedTradePostRegistration" }, false) == true then
    local cloneOk, cloneMessage, cloneData = spawnFunctionalRegisteredTradePostCloneForInfo(cleanActor, live, entry, attempts)
    if cloneOk or configBool("bridge-safety", { "AllowFunctionalTraderCloneFallbackToRelocation", "allowFunctionalTraderCloneFallbackToRelocation" }, false) ~= true then
      return cloneOk, cloneMessage, cloneData
    end
    table.insert(attempts, "spawned TradePost route failed; fallback to registered relocation: " .. tostring(cloneMessage))
  end
  if not plainSummonMode and traderLike and configBool("bridge-safety", { "AllowFunctionalTraderRegisteredTradePostRelocation", "allowFunctionalTraderRegisteredTradePostRelocation" }, false) == true then
    return spawnFunctionalRegisteredTradePostForInfo(cleanActor, live, entry, attempts)
  end
  if not plainSummonMode and actualTraderLike and configBool("bridge-safety", { "AllowFunctionalTraderDirectSpawn", "allowFunctionalTraderDirectSpawn" }, false) == true then
    return spawnFunctionalTraderDirectForInfo(cleanActor, live, entry, attempts)
  end
  if not plainSummonMode and bankerLike and configBool("bridge-safety", { "AllowFunctionalBankerDirectSpawn", "allowFunctionalBankerDirectSpawn" }, false) == true then
    return spawnFunctionalBankerDirectForInfo(cleanActor, live, entry, attempts)
  end
  local allowTraderSummonFallback = configBool("bridge-safety", { "AllowSummonTraderActorFallback", "allowSummonTraderActorFallback" }, false) == true
  local allowTradePostSummonFallback = configBool("bridge-safety", { "AllowSummonTradePostActorFallback", "allowSummonTradePostActorFallback" }, false) == true
  if actualTraderLike and not allowTraderSummonFallback and not plainSummonMode then
    table.insert(attempts, "trader/tradepost Summon fallback disabled by bridge-safety")
    local message = "Summon для ATrader NPC заблокирован: SCUM economy требует ATradePost + TraderPersonality marker; иначе получается NPC без товара/ошибка trader item not found. Используй BP_*_NPCInteractionBox_C."
    local data = '{"actorClass":' .. js(cleanActor) ..
      ',"route":"blocked-atrader-summon-fallback"' ..
      ',"recommendedRoute":"spawn TradePost/NPCInteractionBox actor"' ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, live, message, data)
    return false, message, data
  end
  if tradePostLike and not allowTradePostSummonFallback and not plainSummonMode then
    table.insert(attempts, "tradepost Summon fallback disabled by bridge-safety")
    local message = "Summon для ATradePost/NPCInteractionBox заблокирован bridge-safety.AllowSummonTradePostActorFallback=false."
    local data = '{"actorClass":' .. js(cleanActor) ..
      ',"route":"blocked-tradepost-summon-fallback"' ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, live, message, data)
    return false, message, data
  end
  if traderLike and not summonTraderRuntimeScanAllowed() and not plainSummonMode then
    table.insert(attempts, "trader/tradepost runtime verification scan disabled by bridge-safety")
    local message = "Summon для trader/tradepost заблокирован в safe-mode: без runtime+economy проверки он создаёт NPC/interaction box без товара или с ошибкой trader/item not found и может давать ping-spike. Для maintenance-пробы включай AllowSummonTraderRuntimeScan=true кратко и выключай обратно."
    local data = '{"actorClass":' .. js(cleanActor) ..
      ',"route":"blocked-trader-runtime-verification-safety"' ..
      ',"requiresRuntimeEconomyVerification":true' ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, live, message, data)
    return false, message, data
  end
  local useDirectPlacement = needsPlacement and not placeableBlockedFromDirect and not traderLike and
    configBool("bridge-safety", { "AllowDirectActorSpawn", "allowDirectActorSpawn" }, false) == true and
    configBool("bridge-safety", { "SummonUseDirectWorldSpawnForMapActors", "summonUseDirectWorldSpawnForMapActors", "SummonUseDirectWorldSpawnForPlacementActors", "summonUseDirectWorldSpawnForPlacementActors" }, false) == true
  if needsPlacement and placeableBlockedFromDirect then
    table.insert(attempts, "direct world-spawn skipped for SCUM placeable/base-building; use native_placeable_spawn")
  elseif needsPlacement and traderLike then
    table.insert(attempts, "direct world-spawn skipped for trader/tradepost; requires economy/tradepost init")
  elseif needsPlacement and not useDirectPlacement then
    table.insert(attempts, "direct world-spawn disabled by bridge-safety")
  end
  local allowPlacementSummonFallback = configBool("bridge-safety", { "AllowSummonPlacementActorFallback", "allowSummonPlacementActorFallback" }, false) == true
  if needsPlacement and not traderLike and not useDirectPlacement and not allowPlacementSummonFallback and not plainSummonMode then
    local routeHint = actorCatalogPlacementRouteHint(entry)
    local routeName = actorCatalogIsMapBuildingActor(entry) and "blocked-map-building-runtime-summon" or "blocked-placement-summon-fallback"
    local message = "Summon для map/building placement-актора заблокирован: SCUM создаёт невидимый collision-only ghost; " .. tostring(routeHint)
    local data = '{"actorClass":' .. js(cleanActor) ..
      ',"route":' .. js(routeName) ..
      ',"needsPlacement":true' ..
      ',"directWorldSpawn":false' ..
      ',"routeHint":' .. js(routeHint) ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("spawn_actor", false, live, message, data)
    return false, message, data
  end
  if useDirectPlacement then
    table.insert(attempts, "actor route=direct-world-spawn placement")
    local directLogOffset = fileSize(SERVER_LOG_FILE)
    local directBeforeStats = latestScumGlobalStatsTail()
    local directOk, directDetail, directAttempts, directActor = spawnActorDirectForInfo(live, cleanActor, entry)
    for _, attempt in ipairs(directAttempts or {}) do table.insert(attempts, attempt) end
    local verified, directData = finishSummonActorVerification({
      actorClass = cleanActor,
      route = "direct-world-spawn:placement",
      candidate = cleanActor,
      live = live,
      logOffset = directLogOffset,
      beforeStats = directBeforeStats,
      attemptsText = table.concat(attempts or {}, " | "),
      directActor = directActor,
      directSpawnOk = directOk,
      directSpawnDetail = directDetail
    })
    appendActionEvent("spawn_actor", verified, live,
      verified and ("Актор создан прямым world-spawn и поставлен перед игроком: " .. cleanActor) or
        ("Direct world-spawn для placement-актора не подтвердился: " .. tostring(directDetail)),
      '{"actorClass":' .. js(cleanActor) ..
        ',"route":"direct-world-spawn:placement"' ..
        ',"verified":' .. (verified and "true" or "false") ..
        ',"directDetail":' .. js(directDetail or "") ..
        ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}')
    if verified then
      return true, "Актор создан прямым world-spawn и поставлен перед игроком: " .. cleanActor, directData or "{}"
    end
    table.insert(attempts, "direct world-spawn placement failed=" .. tostring(directDetail))
    if needsPlacement and not traderLike and not allowPlacementSummonFallback then
      return false, "Direct world-spawn для placement-актора не подтвердился; fallback в Summon заблокирован, чтобы не оставлять невидимый collision-only ghost: " .. tostring(directDetail), directData or "{}"
    end
    if configBool("bridge-safety", { "SummonFallbackToCheatManagerAfterDirectSpawnFailure", "summonFallbackToCheatManagerAfterDirectSpawnFailure" }, true) == false then
      return false, "Актор не создан прямым world-spawn: " .. tostring(directDetail), directData or "{}"
    end
  end
  local cm, cmSource = ensureCheatManagerForController(live.pc)
  if cm == nil then
    appendActionEvent("spawn_actor", false, live, tostring(cmSource), '{"actorClass":' .. js(cleanActor) .. '}')
    return false, "CheatManager недоступен: " .. tostring(cmSource), "{}"
  end
  ensureAdminBypassHooks()
  table.insert(attempts, "actor route=CheatManager.Summon only")
  local okSummonCall, summonSent, summonRouteOrError, summonAttempts, summonVerify = pcall(summonActorWithCheatManager, cm, cleanActor, live)
  if not okSummonCall then
    local summonErr = tostring(summonSent)
    summonSent = false
    summonRouteOrError = summonErr
    summonAttempts = { "summonActorWithCheatManager error=" .. tostring(summonRouteOrError) }
    summonVerify = nil
  end
  for _, attempt in ipairs(summonAttempts or {}) do table.insert(attempts, attempt) end
  local sent = summonSent
  local routeOrError = summonRouteOrError
  appendActionEvent("spawn_actor", sent, live, sent and ("Summon отправлен, ждём runtime-подтверждение: " .. cleanActor) or tostring(routeOrError),
    '{"actorClass":' .. js(cleanActor) ..
      ',"cheatManager":' .. js(cmSource or "") ..
      ',"route":' .. js(sent and routeOrError or "") ..
      ',"beforeStats":' .. scumGlobalStatsJson(summonVerify and summonVerify.beforeStats or nil) ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}')
  if sent then
    if plainSummonMode then
      local data = '{"actorClass":' .. js(cleanActor) ..
        ',"route":' .. js(routeOrError or "") ..
        ',"cheatManager":' .. js(cmSource or "") ..
        ',"plainSummon":true' ..
        ',"runtimeScan":' .. (((summonVerify or {}).runtimeScan == true) and "true" or "false") ..
        ',"verified":false' ..
        ',"note":"plain web-panel Summon; no functional trader/economy lifecycle verification was attempted"}'
      appendActionEvent("spawn_actor", true, live, "Summon отправлен через веб-панель: " .. cleanActor, data)
      return true, "Summon отправлен через веб-панель: " .. cleanActor, data
    end
    local requestId = tostring((asyncResult or {}).requestId or "")
    local verifyDelayMs = math.max(800, math.min(math.floor(configNumber("bridge-safety", { "SummonVerifyDelayMs", "summonVerifyDelayMs" }, 2600) or 2600), 12000))
    if requestId ~= "" and deferGame(verifyDelayMs, function()
      finishSummonActorVerification({
        actorClass = cleanActor,
        route = routeOrError,
        candidate = (summonVerify or {}).candidate or cleanActor,
        live = live,
        logOffset = (summonVerify or {}).logOffset or fileSize(SERVER_LOG_FILE),
        beforeStats = (summonVerify or {}).beforeStats,
        beforeObjects = (summonVerify or {}).beforeObjects,
        runtimeScan = (summonVerify or {}).runtimeScan == true,
        attemptsText = table.concat(attempts or {}, " | "),
        requestId = requestId,
        resultCommand = (asyncResult or {}).commandName or "spawn_actor"
      })
    end) then
      return nil, "Summon отправлен, ожидаю runtime actor/видимость без busy-wait.", "__async__"
    end
    return true, "Summon отправлен, runtime-проверка недоступна: " .. cleanActor,
      '{"actorClass":' .. js(cleanActor) ..
        ',"route":' .. js(routeOrError or "") ..
        ',"cheatManager":' .. js(cmSource or "") ..
        ',"verified":false,"pendingVerify":true}'
  end
  return false, "Актор не создан: " .. tostring(routeOrError), '{"actorClass":' .. js(cleanActor) .. '}'
end

function itemAdminCommandId(itemId)
  local raw = tostring(itemId or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^Item:", "")
  if raw:sub(1, 6) == "/Game/" then
    local objectName = raw:match("%.([^%.\\/]+)$") or raw:match("([^/\\]+)$") or raw
    raw = objectName:gsub("_C$", "")
  end
  return raw:gsub("[^%w_:/%.%-]", "")
end

function adminSpawnItemCommandForInfo(info, itemId, quantity, options)
  local safeItem = itemAdminCommandId(itemId)
  quantity = math.max(1, math.min(tonumber(quantity) or 1, 100))
  if safeItem == "" then return nil, safeItem, "unsafe item id" end
  options = options or {}
  local modifiers = {}
  local function appendNumberArg(name, value)
    local number = tonumber(value or 0) or 0
    if number > 0 then table.insert(modifiers, tostring(name) .. " " .. tostring(number)) end
  end
  local function appendTextArg(name, value)
    local text = trimText(value or "")
    if text ~= "" then table.insert(modifiers, tostring(name) .. " " .. text:gsub("[^%w_%-]", "")) end
  end
  appendNumberArg("weight", options.weight or options.Weight)
  appendNumberArg("health", options.health or options.Health)
  appendNumberArg("uses", options.uses or options.Uses)
  appendNumberArg("dirtiness", options.dirtiness or options.Dirtiness)
  appendNumberArg("ammocount", options.ammoCount or options.AmmoCount)
  appendNumberArg("cashvalue", options.cashValue or options.CashValue)
  appendTextArg("keycardsector", options.keyCardSector or options.KeyCardSector)
  local commandText = "SpawnItem " .. safeItem .. " " .. tostring(quantity)
  local targetSteam = tostring((info or {}).steam or "")
  if looksLikeSteamId(targetSteam) then commandText = commandText .. " Location " .. targetSteam end
  if #modifiers > 0 then commandText = commandText .. " " .. table.concat(modifiers, " ") end
  return commandText, safeItem, ""
end

function itemRuntimeClassHints(itemId, classPath, assetPath)
  local hints = {}
  local seen = {}
  local function add(value)
    value = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if value == "" then return end
    if value:sub(1, 6) == "/Game/" then
      local objectName = value:match("%.([^%.\\/]+)$") or value:match("([^/\\]+)$") or value
      local assetName = objectName:gsub("_C$", "")
      pushUnique(hints, seen, objectName)
      pushUnique(hints, seen, assetName)
      pushUnique(hints, seen, assetName .. "_C")
      return
    end
    value = value:gsub("^Item:", "")
    pushUnique(hints, seen, value)
    pushUnique(hints, seen, value:gsub("_C$", "") .. "_C")
    pushUnique(hints, seen, "BP_" .. value:gsub("_C$", ""))
    pushUnique(hints, seen, "BP_" .. value:gsub("_C$", "") .. "_C")
  end
  add(itemId)
  add(resolveItemPath(itemId))
  add(classPath)
  add(assetPath)
  pushUnique(hints, seen, "Item")
  pushUnique(hints, seen, "ItemBase")
  pushUnique(hints, seen, "InventoryItem")
  pushUnique(hints, seen, "ConZItem")
  pushUnique(hints, seen, "BP_ItemBase_C")
  return hints
end

function objectEntityIdText(obj)
  local id = objectDbId(obj,
    {"GetEntityId", "GetEntityID", "GetDatabaseId", "GetDatabaseID", "GetDBId", "GetItemEntityId", "GetItemEntityID"},
    {"EntityId", "EntityID", "entityId", "_entityId", "DatabaseId", "DatabaseID", "DBId", "_databaseId", "ItemEntityId", "ItemEntityID"})
  if id ~= "" then return id end
  local printed = ""
  pcall(function() printed = tostring(obj) end)
  id = printed:match("EntityId%s*=%s*(%d+)") or printed:match("EntityID%s*=%s*(%d+)") or printed:match("DatabaseId%s*=%s*(%d+)")
  return tostring(id or "")
end

function findInventoryItemObject(entityId, itemId, classPath, assetPath)
  local wanted = tostring(entityId or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if wanted == "" then return nil, "entity id is missing" end
  if not scanFeatureEnabled({ "AllowInventoryRuntimeObjectScan", "allowInventoryRuntimeObjectScan" }, false) then
    return nil, "item runtime object scan disabled by bridge-safety"
  end
  local runtimeKey = wanted:gsub("^runtime:", "")
  local hints = itemRuntimeClassHints(itemId, classPath, assetPath)
  local scanned = 0
  for _, item in ipairs(findAll(hints)) do
    scanned = scanned + 1
    if objectKey(item) == runtimeKey then
      return item, "runtime key match"
    end
    local objectId = objectEntityIdText(item)
    if objectId ~= "" and objectId == wanted then
      return item, "entity id match"
    end
  end
  return nil, "item runtime object not found; scanned " .. tostring(scanned)
end

function itemObjectNameText(obj)
  if obj == nil then return "" end
  local parts = {}
  local okName, name = pcall(function() return obj:GetName() end)
  if okName and name ~= nil then table.insert(parts, tostring(name)) end
  local okFull, full = pcall(function() return obj:GetFullName() end)
  if okFull and full ~= nil then table.insert(parts, tostring(full)) end
  local okClass, cls = pcall(function() return obj:GetClass() end)
  if okClass and cls ~= nil then table.insert(parts, objectFullName(cls)) end
  table.insert(parts, tostring(obj))
  return table.concat(parts, " ")
end

function itemObjectMatchesHints(obj, itemId, classPath, assetPath)
  local hints = itemRuntimeClassHints(itemId, classPath, assetPath)
  local text = itemObjectNameText(obj):lower()
  if text == "" then return false end
  for _, hint in ipairs(hints) do
    local key = normalizeItemKey(hint)
    if key ~= "" and text:find(key, 1, true) ~= nil then return true end
    local lower = tostring(hint or ""):lower()
    if lower ~= "" and text:find(lower, 1, true) ~= nil then return true end
  end
  return false
end

function itemInHandsObject(info, itemId, classPath, assetPath)
  if info == nil or info.pawn == nil or not isValidObject(info.pawn) then return nil, "pawn missing" end
  local candidates = {}
  for _, method in ipairs({ "GetItemInHands", "GetItemInHandsOnServer", "GetHeldItem", "GetCurrentItemInHands" }) do
    local okCall, value = safeCall(info.pawn, method)
    if okCall and value ~= nil and isValidObject(value) then table.insert(candidates, { value = value, route = "pawn." .. method }) end
  end
  for _, prop in ipairs({ "ItemInHands", "_itemInHands", "CurrentItemInHands", "HeldItem", "EquippedItem" }) do
    local value = firstProp(info.pawn, { prop })
    if value ~= nil and isValidObject(value) then table.insert(candidates, { value = value, route = "pawn." .. prop }) end
  end
  local inv = playerInventoryComponent(info)
  if inv ~= nil and isValidObject(inv) then
    for _, method in ipairs({ "GetItemInHands", "GetItemInHandsOnServer", "GetHeldItem", "GetCurrentItemInHands" }) do
      local okCall, value = safeCall(inv, method)
      if okCall and value ~= nil and isValidObject(value) then table.insert(candidates, { value = value, route = "inventory." .. method }) end
    end
    for _, prop in ipairs({ "ItemInHands", "_itemInHands", "CurrentItemInHands", "HeldItem", "EquippedItem" }) do
      local value = firstProp(inv, { prop })
      if value ~= nil and isValidObject(value) then table.insert(candidates, { value = value, route = "inventory." .. prop }) end
    end
  end
  for _, candidate in ipairs(candidates) do
    if itemObjectMatchesHints(candidate.value, itemId, classPath, assetPath) then
      return candidate.value, candidate.route
    end
  end
  if #candidates == 1 and tostring(itemId or "") == "" and tostring(classPath or "") == "" and tostring(assetPath or "") == "" then
    return candidates[1].value, candidates[1].route .. " single"
  end
  return nil, "item in hands did not match hints; candidates=" .. tostring(#candidates)
end

function cleanEntityIdText(value)
  local text = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
  local id = text:match("^(%d+)$") or text:match("entity[:=](%d+)") or text:match("(%d+)")
  return tostring(id or "")
end

function destroyInventoryEntityByAdmin(entityId, info)
  local id = cleanEntityIdText(entityId)
  if id == "" or id == "0" then return false, "EntityID предмета невалидный." end
  local commandObject = firstValidAdminCommandObject("DestroyEntity")
  local sent, message = adminExec("DestroyEntity " .. id, info)
  if sent then return true, "DestroyEntity " .. id .. " отправлен через " .. tostring(message or "admin route") end
  if commandObject == nil then
    return false, "DestroyEntity не отправлен: объект admin-команды не найден, admin route ответил: " .. tostring(message or "")
  end
  return false, tostring(message or "DestroyEntity не отправлен")
end

function destroyInventoryItemObject(item, info)
  if item == nil or not isValidObject(item) then return false, "item object is not valid" end
  local attempts = {}
  local inv = playerInventoryComponent(info)
  if inv ~= nil and isValidObject(inv) then
    for _, method in ipairs({"Server_DestroyItem", "DestroyItem", "Server_RemoveItem", "RemoveItem", "RemoveItemFromInventory", "Server_DropItem", "DropItem"}) do
      local okCall, result = safeCall(inv, method, item)
      table.insert(attempts, "inventory." .. method .. "=" .. (okCall and "ok" or tostring(result)))
      if okCall and result ~= false then return true, "removed through inventory " .. method end
    end
  end
  for _, method in ipairs({"Server_DestroyItem", "DestroyItem", "Server_DropItem", "DropItem", "K2_DestroyActor", "Destroy"}) do
    local okCall, result = safeCall(item, method)
    table.insert(attempts, "item." .. method .. "=" .. (okCall and "ok" or tostring(result)))
    if okCall and result ~= false then return true, "removed through item " .. method end
  end
  return false, table.concat(attempts, " | ")
end

function destroyInventoryEntitySmart(entityId, live, itemId, classPath, assetPath)
  local cleanEntityId = cleanEntityIdText(entityId)
  if cleanEntityId == "" then return false, "EntityID предмета не указан.", "none" end
  local preferLive = configBool("bridge-safety", { "PreferLiveInventoryDelete", "preferLiveInventoryDelete" }, false)
  if not preferLive then
    local adminRemoved, adminMessage = destroyInventoryEntityByAdmin(cleanEntityId, live)
    if adminRemoved then
      return true, tostring(adminMessage), "DestroyEntity"
    end
  end
  local item, findRoute = findInventoryItemObject(cleanEntityId, itemId, classPath, assetPath)
  if item == nil then
    item, findRoute = itemInHandsObject(live, itemId, classPath, assetPath)
  end
  if item ~= nil then
    local removed, message = destroyInventoryItemObject(item, live)
    if removed then
      return true, tostring(message), "live:" .. tostring(findRoute or "")
    end
    local adminRemoved, adminMessage = destroyInventoryEntityByAdmin(cleanEntityId, live)
    if adminRemoved then
      return true, tostring(adminMessage), "DestroyEntity-after-live"
    end
    return false, tostring(message) .. " | " .. tostring(adminMessage), "live-failed:" .. tostring(findRoute or "")
  end
  if preferLive then
    local adminRemoved, adminMessage = destroyInventoryEntityByAdmin(cleanEntityId, live)
    if adminRemoved then
      return true, tostring(adminMessage), "DestroyEntity"
    end
    return false, tostring(adminMessage or "") .. " | " .. tostring(findRoute or ""), "not-found"
  end
  return false, "DestroyEntity не сработал, live fallback тоже не нашёл предмет. " .. tostring(findRoute or ""), "not-found"
end

function deleteInventoryItem(steamId, name, runtimeKey, entityId, itemId, classPath, assetPath)
  local info = findPlayer(steamId, name, runtimeKey)
  if info == nil then return false, "Игрок не найден среди реально подключённых." end
  local cleanEntityId = cleanEntityIdText(entityId)
  if cleanEntityId == "" then return false, "EntityID предмета не указан." end
  local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
  local removed, message, route = destroyInventoryEntitySmart(cleanEntityId, live, itemId, classPath, assetPath)
  appendActionEvent("delete_inventory_item", removed, live, tostring(message),
    '{"entityId":' .. js(cleanEntityId) .. ',"itemId":' .. js(itemId or "") .. ',"route":' .. js(route or "") .. ',"queued":false}')
  targetMessage(live.steam, live.name, removed and "Предмет удалён администратором." or ("Предмет не удалён: " .. tostring(message)), "inventory", live.runtimeKey)
  return removed, tostring(message or (removed and "Предмет удалён." or "Предмет не удалён."))
end

function parseEntityIdsText(value)
  local ids = {}
  local seen = {}
  local text = tostring(value or "")
  for id in text:gmatch("%d+") do
    id = tostring(id or "")
    if id ~= "" and id ~= "0" and seen[id] == nil then
      seen[id] = true
      table.insert(ids, id)
      if #ids >= 80 then break end
    end
  end
  return ids
end

function destroyInventoryEntitiesBatch(steamId, name, runtimeKey, entitiesText)
  local ids = parseEntityIdsText(entitiesText)
  if #ids == 0 then return false, "EntityID list is empty." end
  local info = findPlayer(steamId, name, runtimeKey)
  if info == nil or info.pc == nil or not isValidObject(info.pc) then
    return false, "Live player is required for fast inventory cleanup."
  end
  info = enrichPlayerInfoFromServerLog(info) or info
  local maxPerBatch = math.max(1, math.min(tonumber(configNumber("bridge-safety", { "InventoryDeleteBatchSize", "inventoryDeleteBatchSize" }, 24)) or 24, 40))
  local requestedCount = #ids
  if #ids > maxPerBatch then
    local trimmed = {}
    for i = 1, maxPerBatch do trimmed[i] = ids[i] end
    ids = trimmed
  end
  local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
  if live == nil then
    appendActionEvent("delete_inventory_batch", false, info, "Fast cleanup skipped: live player disappeared.",
      '{"requested":' .. tostring(requestedCount) .. ',"sent":0,"queued":false}')
    return false, "Fast cleanup skipped: live player disappeared.", '{"requested":' .. tostring(requestedCount) .. ',"sent":0,"queued":false}'
  end
  local sentCount = 0
  local failed = {}
  local routes = {}
  for _, id in ipairs(ids) do
    local sent, message, route = destroyInventoryEntitySmart(id, live, "", "", "")
    if sent then
      sentCount = sentCount + 1
      table.insert(routes, tostring(id) .. ":" .. tostring(route or ""))
    else
      table.insert(failed, tostring(id) .. ":" .. tostring(message or "failed"))
    end
  end
  appendActionEvent("delete_inventory_batch", sentCount == #ids, live,
    "Inventory batch removed " .. tostring(sentCount) .. "/" .. tostring(#ids),
    '{"requested":' .. tostring(requestedCount) .. ',"batchSize":' .. tostring(#ids) .. ',"sent":' .. tostring(sentCount) .. ',"failed":' .. js(table.concat(failed, " | ")) .. ',"routes":' .. js(table.concat(routes, " | ")) .. ',"queued":false}')
  if live ~= nil and tostring(live.steam or live.name or "") ~= "" then
    targetMessage(live.steam, live.name, "Администратор удаляет предметы: отправлено " .. tostring(sentCount) .. "/" .. tostring(#ids) .. ".", "inventory", live.runtimeKey)
  end
  return sentCount == #ids, "Inventory batch removed " .. tostring(sentCount) .. "/" .. tostring(#ids),
    '{"requested":' .. tostring(requestedCount) .. ',"batchSize":' .. tostring(#ids) .. ',"sent":' .. tostring(sentCount) .. ',"failed":' .. js(table.concat(failed, " | ")) .. ',"routes":' .. js(table.concat(routes, " | ")) .. ',"queued":false}'
end

function deliverItemThroughAdminSpawn(info, itemId, quantity)
  itemId = tostring(itemId or ""):gsub("^%s+", ""):gsub("%s+$", "")
  quantity = math.max(1, math.min(tonumber(quantity) or 1, 100))
  local commandText, safeItem, errorText = adminSpawnItemCommandForInfo(info, itemId, quantity)
  if commandText == nil then return 0, quantity, itemId, {"admin SpawnItem skipped: " .. tostring(errorText or "unsafe item id")} end
  local sent, message = adminExec(commandText, info)
  if sent then
    return quantity, quantity, safeItem, {"admin SpawnItem dispatched: " .. tostring(message or "")}
  end
  return 0, quantity, safeItem, {"admin SpawnItem failed: " .. tostring(message or "")}
end

function deliveryBatchDelayMs(explicitDelayMs)
  local value = tonumber(explicitDelayMs)
  if value == nil then
    value = configNumber("bridge-safety", { "ItemBatchInterItemDelayMs", "itemBatchInterItemDelayMs" }, nil)
  end
  if value == nil then
    value = configNumber("welcome-pack", { "InterItemDelayMs", "interItemDelayMs" }, 2500)
  end
  return math.max(250, math.min(math.floor(tonumber(value) or 1000), 10000))
end

function finishDeliverItemsBatch(info, items, results, failures, okItems, deliveredQuantity, hasAdminTarget, messageOk)
  local allOk = okItems == #items
  local data = '{"requested":' .. tostring(#items) ..
    ',"delivered":' .. tostring(okItems) ..
    ',"deliveredQuantity":' .. tostring(deliveredQuantity) ..
    ',"allOk":' .. (allOk and "true" or "false") ..
    ',"adminTarget":' .. (hasAdminTarget and "true" or "false") ..
    ',"sequential":true' ..
    ',"results":[' .. table.concat(results, ",") .. ']}'
  local okMessage = tostring(messageOk or "batch delivery dispatched sequentially through safe admin route")
  appendLog("deliver_items_batch sequential target=" .. tostring((info or {}).steam or (info or {}).name or "") .. " requested=" .. tostring(#items) .. " okItems=" .. tostring(okItems) .. " adminTarget=" .. tostring(hasAdminTarget))
  appendActionEvent("deliver_items_batch", allOk, info, allOk and okMessage or table.concat(failures, " || "), data)
  return allOk, allOk and okMessage or ("batch delivery incomplete: " .. table.concat(failures, " || ")), data
end

function deliverItemsBatchAsync(steamId, name, itemsSpec, preferredInfo, runtimeKey, explicitDelayMs, done)
  local info = resolvePlayerInfo(steamId, name, preferredInfo, runtimeKey)
  if info == nil then info = { steam = tostring(steamId or ""), name = tostring(name or ""), source = "delivery-identity" } end
  if tostring(info.steam or "") == "" then info.steam = tostring(steamId or "") end
  if tostring(info.name or "") == "" or tostring(info.name or "") == "Unknown" then info.name = tostring(name or "") end
  local items = parseItemsSpec(itemsSpec)
  local function complete(allOk, message, data)
    if type(done) == "function" then
      local okDone, errDone = pcall(done, allOk, message, data)
      if not okDone then appendLog("deliver_items_batch async completion failed: " .. tostring(errDone)) end
    end
  end
  if #items == 0 then
    complete(false, "items for delivery are not configured", "{}")
    return true
  end
  local refreshedInfo = refreshRuntimePlayerInfo(info)
  if refreshedInfo ~= nil then info = refreshedInfo end
  local hasAdminTarget = looksLikeSteamId(tostring(info.steam or ""))
  local hasDirectTarget = info.pawn ~= nil and isValidObject(info.pawn)
  if not (hasAdminTarget or hasDirectTarget) then
    local allOk, message, data = deliverItemsBatch(steamId, name, itemsSpec, info, runtimeKey)
    complete(allOk, message, data)
    return true
  end

  local delayMs = deliveryBatchDelayMs(explicitDelayMs)
  local results = {}
  local failures = {}
  local okItems = 0
  local deliveredQuantity = 0
  local index = 1

  local function finish()
    local allOk, message, data = finishDeliverItemsBatch(info, items, results, failures, okItems, deliveredQuantity, hasAdminTarget)
    complete(allOk, message, data)
  end

  local function runOne()
    local okStep, errStep = pcall(function()
      local item = items[index]
      if item == nil then
        finish()
        return
      end
      local live = resolvePlayerInfo(steamId, name, info, runtimeKey) or info
      local okCount, requested, path, details = deliverItemTypeForInfo(live, item.itemId, item.quantity)
      details = details or {}
      local itemOk = okCount == requested
      if itemOk then okItems = okItems + 1 end
      if not itemOk then table.insert(failures, tostring(item.itemId) .. ": " .. table.concat(details, " || ")) end
      deliveredQuantity = deliveredQuantity + okCount
      local itemData = '{"itemId":' .. js(item.itemId) ..
        ',"quantity":' .. tostring(requested) ..
        ',"delivered":' .. tostring(okCount) ..
        ',"ok":' .. (itemOk and "true" or "false") ..
        ',"path":' .. js(path) ..
        ',"delayMs":' .. tostring(delayMs) ..
        ',"message":' .. js(table.concat(details, " || ")) .. '}'
      table.insert(results, itemData)
      appendActionEvent("deliver_items_batch_item", itemOk, live, table.concat(details, " || "), itemData)
      index = index + 1
      if index <= #items then
        if not deferGame(delayMs, runOne) then
          appendLog("deliver_items_batch sequential delay fallback ran inline")
        end
      else
        finish()
      end
    end)
    if not okStep then
      table.insert(failures, "batch step error: " .. tostring(errStep))
      finish()
    end
  end

  if not deferGame(0, runOne) then
    complete(false, "failed to start sequential item delivery", "{}")
  end
  return true
end

function deliverItemTypeForInfo(info, itemId, quantity)
  itemId = tostring(itemId or ""):gsub("^%s+", ""):gsub("%s+$", "")
  quantity = math.max(1, math.min(tonumber(quantity) or 1, 100))
  if itemId == "" then return 0, quantity, "", {"ID предмета не указан"} end
  if not itemIdLooksLikeScumAsset(itemId) then
    return 0, quantity, itemId, {"ID предмета похож на внешний ID товара, а не на SCUM asset"}
  end
  if itemLooksLikeWeapon(itemId) then
    return deliverItemThroughAdminSpawn(info, itemId, quantity)
  end
  if not directInventorySpawnEnabled() then
    return deliverItemThroughAdminSpawn(info, itemId, quantity)
  end
  if itemId:sub(1, 6) ~= "/Game/" and itemId:sub(1, 8) ~= "/Script/" then
    local adminCount, adminRequested, adminPath, adminDetails = deliverItemThroughAdminSpawn(info, itemId, quantity)
    if adminCount == adminRequested then return adminCount, adminRequested, adminPath, adminDetails end
    local directAllowed = shouldUseDirectItemRoute(itemId)
    if not directAllowed then return adminCount, adminRequested, adminPath, adminDetails end
  end
  if not shouldUseDirectItemRoute(itemId) then
    return 0, quantity, itemId, {"безопасная direct-выдача для этого предмета ещё не подтверждена; SpawnItem fallback отключён"}
  end
  local path = resolveItemPath(itemId)
  local okCount = 0
  local details = {}
  local itemClass, loadRoute = loadItemClass(path)
  if itemClass == nil then
    table.insert(details, "загрузка не удалась: " .. tostring(loadRoute))
    return okCount, quantity, path, details
  end
  for i = 1, quantity do
    local delivered = false
    local attemptDetails = {}
    for attempt = 1, 3 do
      local liveInfo = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
      local actor, spawnRoute = spawnItemActor(liveInfo, itemClass)
      if actor == nil then
        table.insert(attemptDetails, "attempt " .. tostring(attempt) .. " spawn failed: " .. tostring(spawnRoute))
        break
      end
      local placed, placeRoute = placeItemForPlayer(liveInfo, actor)
      if placed then
        okCount = okCount + 1
        table.insert(details, loadRoute .. " -> " .. spawnRoute .. " -> " .. placeRoute .. (attempt > 1 and (" after retry " .. tostring(attempt)) or ""))
        delivered = true
        break
      end
      okCount = okCount + 1
      table.insert(details, loadRoute .. " -> " .. spawnRoute .. " -> создан рядом с игроком; инвентарь не принял предмет: " .. tostring(placeRoute))
      delivered = true
      break
    end
    if not delivered then
      table.insert(details, table.concat(attemptDetails, " || "))
    end
  end
  return okCount, quantity, path, details
end

function deliverItemsForInfo(preferredInfo, steamId, name, itemId, quantity, runtimeKey)
  local info = resolvePlayerInfo(steamId, name, preferredInfo, runtimeKey)
  if info == nil then info = { steam = tostring(steamId or ""), name = tostring(name or ""), source = "delivery-identity" } end
  if tostring(info.steam or "") == "" then info.steam = tostring(steamId or "") end
  if tostring(info.name or "") == "" or tostring(info.name or "") == "Unknown" then info.name = tostring(name or "") end
  local refreshedInfo = refreshRuntimePlayerInfo(info)
  if refreshedInfo ~= nil then info = refreshedInfo end
  local hasAdminTarget = looksLikeSteamId(tostring(info.steam or ""))
  local hasDirectTarget = info.pawn ~= nil and isValidObject(info.pawn)
  if hasAdminTarget or hasDirectTarget then
    local okCount, requested, path, details = deliverItemTypeForInfo(info, itemId, quantity)
    details = details or {}
    appendLog("deliver_items routed item=" .. tostring(itemId) .. " path=" .. tostring(path) .. " qty=" .. tostring(requested) .. " ok=" .. tostring(okCount) .. " adminTarget=" .. tostring(hasAdminTarget) .. " directTarget=" .. tostring(hasDirectTarget) .. " details=" .. table.concat(details, " || "))
    appendActionEvent("deliver_item", okCount == requested, info, table.concat(details, " || "),
      '{"itemId":' .. js(itemId) .. ',"quantity":' .. tostring(requested) .. ',"delivered":' .. tostring(okCount) .. ',"path":' .. js(path) .. ',"adminTarget":' .. (hasAdminTarget and "true" or "false") .. '}')
    if okCount == requested then return true, "item delivery dispatched through safe admin route" end
    return false, "item delivery incomplete: " .. tostring(okCount) .. "/" .. tostring(requested) .. ". " .. table.concat(details, " || ")
  end
  local liveInfo, ready, readyDetail, readyReason = deliveryReadyInfo(info, { requireInventory = false })
  if info ~= nil and not ready then
    appendActionEvent("delivery_readiness", false, info, tostring(readyDetail or ""),
      '{"reason":' .. js(readyReason or "") .. ',"itemId":' .. js(itemId or "") .. '}')
    return false, deliveryReadyMessage(readyReason), '{"ready":false,"reason":' .. js(readyReason or "") .. '}'
  end
  if liveInfo ~= nil then info = liveInfo end
  if info == nil then return false, "Игрок не найден среди реально подключённых." end
  local okCount, requested, path, details = deliverItemTypeForInfo(info, itemId, quantity)
  details = details or {}
  appendLog("deliver_items direct item=" .. tostring(itemId) .. " path=" .. tostring(path) .. " qty=" .. tostring(requested) .. " ok=" .. tostring(okCount) .. " details=" .. table.concat(details, " || "))
  appendActionEvent("deliver_item", okCount == requested, info, table.concat(details, " || "),
    '{"itemId":' .. js(itemId) .. ',"quantity":' .. tostring(requested) .. ',"delivered":' .. tostring(okCount) .. ',"path":' .. js(path) .. '}')
  if okCount == requested then return true, "Предмет выдан через безопасный маршрут." end
  return false, "Предмет выдан не полностью: " .. tostring(okCount) .. "/" .. tostring(requested) .. ". " .. table.concat(details, " || ")
end

function deliverItems(steamId, name, itemId, quantity, runtimeKey)
  return deliverItemsForInfo(nil, steamId, name, itemId, quantity, runtimeKey)
end

function addInventoryItemForInfo(preferredInfo, steamId, name, itemId, quantity, runtimeKey)
  local info = resolvePlayerInfo(steamId, name, preferredInfo, runtimeKey)
  local liveInfo, ready, readyDetail, readyReason = deliveryReadyInfo(info, { requireInventory = false })
  if info ~= nil and not ready then
    appendActionEvent("add_inventory_item", false, info, tostring(readyDetail or ""),
      '{"reason":' .. js(readyReason or "") .. ',"itemId":' .. js(itemId or "") .. '}')
    return false, deliveryReadyMessage(readyReason), '{"ready":false,"reason":' .. js(readyReason or "") .. '}'
  end
  if liveInfo ~= nil then info = liveInfo end
  if info == nil then return false, "Игрок не найден среди реально подключённых.", "{}" end

  itemId = tostring(itemId or ""):gsub("^%s+", ""):gsub("%s+$", "")
  quantity = math.max(1, math.min(tonumber(quantity) or 1, 20))
  if itemId == "" then return false, "ID предмета не указан.", "{}" end

  if not directInventorySpawnEnabled() then
    local okCount, requested, safeItem, details = deliverItemThroughAdminSpawn(info, itemId, quantity)
    local data = directInventorySpawnBlockedData(itemId, quantity)
    appendActionEvent("add_inventory_item", okCount == requested, info, table.concat(details or {}, " || "), data)
    if okCount == requested then
      return true, "Direct-вставка в инвентарь отключена защитой; предмет безопасно создан через SCUM SpawnItem рядом/на игроке: " .. tostring(safeItem) .. " x" .. tostring(requested) .. ".", data
    end
    return false, "Direct-вставка в инвентарь отключена защитой, а безопасный SpawnItem не сработал: " .. table.concat(details or {}, " || "), data
  end

  local allowWeapons = configBool("bridge-safety", { "AllowWeaponInventoryInsert", "allowWeaponInventoryInsert" }, false)
  if itemLooksLikeWeapon(itemId) and not allowWeapons then
    return false, "Оружие в инвентарь direct-методом заблокировано защитой. Для оружия используй обычную выдачу рядом с игроком или включи AllowWeaponInventoryInsert в bridge-safety.", '{"itemId":' .. js(itemId) .. ',"blocked":"weapon"}'
  end

  local path = resolveItemPath(itemId)
  local itemClass, loadRoute = loadItemClass(path)
  if itemClass == nil then
    return false, "Класс предмета не загрузился: " .. tostring(loadRoute), '{"itemId":' .. js(itemId) .. ',"path":' .. js(path) .. '}'
  end

  local placed = 0
  local fallbackSpawned = 0
  local details = {}
  for i = 1, quantity do
    local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
    local actor, spawnRoute = spawnItemActor(live, itemClass)
    if actor == nil then
      table.insert(details, "spawn failed: " .. tostring(spawnRoute))
      break
    end

    local okPlace, placeRoute = placeItemForPlayer(live, actor)
    if okPlace then
      placed = placed + 1
      table.insert(details, loadRoute .. " -> " .. tostring(spawnRoute) .. " -> " .. tostring(placeRoute))
    else
      local allowFallback = configBool("bridge-safety", { "AllowInventoryInsertSpawnFallback", "allowInventoryInsertSpawnFallback" }, true)
      if allowFallback then
        placed = placed + 1
        fallbackSpawned = fallbackSpawned + 1
        table.insert(details, loadRoute .. " -> " .. tostring(spawnRoute) .. " -> инвентарь не принял; предмет оставлен рядом с игроком: " .. tostring(placeRoute))
      else
        destroySpawnedItem(actor)
        table.insert(details, loadRoute .. " -> " .. tostring(spawnRoute) .. " -> inventory insert failed: " .. tostring(placeRoute))
        break
      end
    end
  end

  local data = '{"itemId":' .. js(itemId) ..
    ',"quantity":' .. tostring(quantity) ..
    ',"placed":' .. tostring(placed) ..
    ',"fallbackSpawned":' .. tostring(fallbackSpawned) ..
    ',"path":' .. js(path) .. '}'
  appendLog("add_inventory_item item=" .. tostring(itemId) .. " path=" .. tostring(path) ..
    " qty=" .. tostring(quantity) .. " placed=" .. tostring(placed) ..
    " details=" .. table.concat(details, " || "))
  appendActionEvent("add_inventory_item", placed == quantity, info, table.concat(details, " || "), data)
  if placed == quantity then
    local msg = "Предмет положен в инвентарь: " .. tostring(placed) .. "/" .. tostring(quantity) .. "."
    if fallbackSpawned > 0 then
      msg = "Инвентарь не принял предмет сразу; предмет создан рядом с игроком: " .. tostring(fallbackSpawned) .. "/" .. tostring(quantity) .. "."
    end
    targetMessage(info.steam, info.name, "Администратор отправил предмет: " .. tostring(itemId) .. " x" .. tostring(quantity) .. ".", "inventory", info.runtimeKey)
    return true, msg, data
  end
  return false, "Предмет положен не полностью: " .. tostring(placed) .. "/" .. tostring(quantity) .. ". " .. table.concat(details, " || "), data
end

function equipItemForInfo(preferredInfo, steamId, name, itemId, quantity, runtimeKey)
  local info = resolvePlayerInfo(steamId, name, preferredInfo, runtimeKey)
  local liveInfo, ready, readyDetail, readyReason = deliveryReadyInfo(info, { requireInventory = false })
  if info ~= nil and not ready then
    appendActionEvent("delivery_readiness", false, info, tostring(readyDetail or ""),
      '{"reason":' .. js(readyReason or "") .. ',"itemId":' .. js(itemId or "") .. ',"equip":true}')
    return false, deliveryReadyMessage(readyReason), '{"ready":false,"reason":' .. js(readyReason or "") .. '}'
  end
  if liveInfo ~= nil then info = liveInfo end
  if info == nil then return false, "Игрок не найден среди реально подключённых.", "{}" end
  if (info.pawn == nil or not isValidObject(info.pawn)) and not looksLikeSteamId(tostring(info.steam or "")) then
    return false, "Игрок подключён, но персонаж ещё не готов.", "{}"
  end
  itemId = tostring(itemId or ""):gsub("^%s+", ""):gsub("%s+$", "")
  quantity = math.max(1, math.min(tonumber(quantity) or 1, 10))
  if itemId == "" then return false, "ID предмета не указан.", "{}" end

  if not directInventorySpawnEnabled() then
    return false, "Экипировка через direct-инвентарь отключена защитой, потому что этот путь может уронить SCUMServer. Используй обычную выдачу предмета через SpawnItem, затем экипируй вручную в игре.", directInventorySpawnBlockedData(itemId, quantity)
  end

  if info.pawn == nil or not isValidObject(info.pawn) then
    return false, "Игрок найден, но персонаж ещё не готов для экипировки в руки.", "{}"
  end

  local path = resolveItemPath(itemId)
  local itemClass, loadRoute = loadItemClass(path)
  if itemClass == nil then
    return false, "Класс предмета не загрузился: " .. tostring(loadRoute), '{"itemId":' .. js(itemId) .. ',"path":' .. js(path) .. '}'
  end

  local equipped = 0
  local placed = 0
  local details = {}
  for i = 1, quantity do
    local liveInfo = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
    local actor, spawnRoute = spawnItemActor(liveInfo, itemClass)
    if actor == nil then
      table.insert(details, "spawn failed: " .. tostring(spawnRoute))
      break
    end

    local okEquip, equipRoute = equipItemForPlayer(liveInfo, actor)
    if okEquip then
      equipped = equipped + 1
      table.insert(details, loadRoute .. " -> " .. spawnRoute .. " -> " .. equipRoute)
    else
      if tostring(equipRoute or ""):find("item was placed in inventory", 1, true) ~= nil then
        placed = placed + 1
        table.insert(details, loadRoute .. " -> " .. spawnRoute .. " -> " .. tostring(equipRoute))
      else
        destroySpawnedItem(actor)
        table.insert(details, loadRoute .. " -> " .. spawnRoute .. " -> equip failed: " .. tostring(equipRoute))
      end
    end
  end

  local data = '{"itemId":' .. js(itemId) .. ',"quantity":' .. tostring(quantity) ..
    ',"equipped":' .. tostring(equipped) .. ',"placed":' .. tostring(placed) ..
    ',"path":' .. js(path) .. '}'
  appendLog("equip_item item=" .. tostring(itemId) .. " path=" .. tostring(path) ..
    " qty=" .. tostring(quantity) .. " equipped=" .. tostring(equipped) ..
    " placed=" .. tostring(placed) .. " details=" .. table.concat(details, " || "))
  appendActionEvent("equip_item", equipped == quantity, info, table.concat(details, " || "), data)
  if equipped == quantity then return true, "Предмет экипирован в руки.", data end
  return false, "Предмет не экипирован: " .. table.concat(details, " || "), data
end

function parseItemsSpec(spec)
  local items = {}
  for token in tostring(spec or ""):gmatch("[^;]+") do
    local sep = token:find("|", 1, true)
    if sep ~= nil then
      local itemId = token:sub(1, sep - 1):gsub("^%s+", ""):gsub("%s+$", "")
      local quantity = tonumber(token:sub(sep + 1)) or 1
      if itemIdLooksLikeScumAsset(itemId) then table.insert(items, { itemId = itemId, quantity = math.max(1, math.min(quantity, 100)) }) end
    end
  end
  return items
end

function prewarmItems(itemsSpec)
  local items = parseItemsSpec(itemsSpec)
  if #items == 0 then return false, "Предметы для проверки не указаны.", '{"items":[],"count":0}' end
  local rows = {}
  local loaded = 0
  local failed = 0
  local maxItems = math.min(#items, 100)
  for i = 1, maxItems do
    local item = items[i]
    local itemId = item.itemId or ""
    local path = resolveItemPath(itemId)
    local itemClass, route = loadItemClass(path)
    local okLoad = itemClass ~= nil
    if okLoad then loaded = loaded + 1 else failed = failed + 1 end
    table.insert(rows, '{"itemId":' .. js(itemId) ..
      ',"path":' .. js(path) ..
      ',"ok":' .. (okLoad and "true" or "false") ..
      ',"route":' .. js(route or "") .. '}')
  end
  local data = '{"count":' .. tostring(maxItems) ..
    ',"loaded":' .. tostring(loaded) ..
    ',"failed":' .. tostring(failed) ..
    ',"truncated":' .. ((#items > maxItems) and "true" or "false") ..
    ',"items":[' .. table.concat(rows, ",") .. ']}'
  appendLog("prewarm_items loaded=" .. tostring(loaded) .. " failed=" .. tostring(failed) .. " count=" .. tostring(maxItems))
  appendActionEvent("items_prewarm", failed == 0, nil, "loaded=" .. tostring(loaded) .. " failed=" .. tostring(failed), data)
  if failed == 0 then return true, "Классы предметов проверены и предзагружены.", data end
  return false, "Часть предметов не загрузилась: " .. tostring(failed) .. "/" .. tostring(maxItems), data
end

function numberField(text, key, fallback)
  local value = tostring(text or ""):match('"' .. key .. '"%s*:%s*(-?%d+%.?%d*)')
  return tonumber(value) or fallback
end

function itemsSpecFromConfigArray(configText, names)
  local text = tostring(configText or "")
  local raw = nil
  for _, key in ipairs(names or { "Items", "items" }) do
    raw = text:match('"' .. tostring(key) .. '"%s*:%s*(%b[])')
    if raw ~= nil then break end
  end
  if raw == nil then return "" end
  local parts = {}
  for object in raw:gmatch("%b{}") do
    local itemId = extractString(object, "ItemId") or extractString(object, "itemId") or ""
    local quantity = numberField(object, "Quantity", numberField(object, "quantity", 1))
    quantity = math.max(1, math.min(tonumber(quantity) or 1, 100))
    if itemIdLooksLikeScumAsset(itemId) then table.insert(parts, itemId .. "|" .. tostring(quantity)) end
  end
  return table.concat(parts, ";")
end

function itemsSpecFromConfig(configText)
  return itemsSpecFromConfigArray(configText, { "Items", "items" })
end

function vipItemsSpecFromConfig(configText)
  return itemsSpecFromConfigArray(configText, { "VipItems", "vipItems", "VIPItems", "vip_items" })
end

function welcomeItemsSpec()
  local configured = itemsSpecFromConfig(configText("welcome-pack"))
  if configured ~= "" then return configured end
  return DEFAULT_WELCOME_ITEMS_SPEC
end

function welcomeRentalVehicles()
  local text = configText("welcome-pack")
  local defaultMinutes = math.max(1, math.floor(configNumber("welcome-pack", { "RentalVehicleMinutes", "rentalVehicleMinutes", "WelcomeVehicleMinutes", "welcomeVehicleMinutes" }, 1440)))
  local defaultPenalty = math.max(0, math.floor(configNumber("welcome-pack", { "RentalVehicleSalePenalty", "rentalVehicleSalePenalty", "WelcomeVehicleSalePenalty", "welcomeVehicleSalePenalty", "DefaultMissingVehiclePenalty", "defaultMissingVehiclePenalty" },
    configNumber("vehicle-rental", { "DefaultMissingVehiclePenalty", "defaultMissingVehiclePenalty", "MissingVehiclePenalty", "missingVehiclePenalty", "SoldVehiclePenalty", "soldVehiclePenalty" }, 0))))
  local raw = text:match('"RentalVehicles"%s*:%s*(%b[])') or
    text:match('"WelcomeVehicles"%s*:%s*(%b[])') or
    text:match('"welcomeVehicles"%s*:%s*(%b[])') or
    text:match('"StarterVehicles"%s*:%s*(%b[])') or
    text:match('"starterVehicles"%s*:%s*(%b[])') or ""
  local rows = {}
  for object in raw:gmatch("%b{}") do
    if extractBoolAny(object, { "Enabled", "enabled" }, true) ~= false then
      local asset = extractStringAny(object, { "AssetName", "assetName", "VehicleAsset", "vehicleAsset", "VehicleId", "vehicleId", "ItemId", "itemId" }) or ""
      asset = canonicalVehicleId(asset)
      if asset ~= "" then
        local display = extractStringAny(object, { "DisplayName", "displayName", "Name", "name" }) or asset
        local alias = extractStringAny(object, { "Alias", "alias", "Command", "command" }) or ("welcome-" .. tostring(#rows + 1))
        local minutes = math.max(1, math.floor(extractNumberAny(object, { "Minutes", "minutes", "RentalMinutes", "rentalMinutes", "DefaultMinutes", "defaultMinutes" }, defaultMinutes) or defaultMinutes))
        local penalty = math.max(0, math.floor(extractNumberAny(object, { "MissingVehiclePenalty", "missingVehiclePenalty", "SoldVehiclePenalty", "soldVehiclePenalty", "SalePenalty", "salePenalty" }, defaultPenalty) or defaultPenalty))
        local message = extractStringAny(object, { "SuccessMessage", "successMessage", "Message", "message" }) or
          ("Транспорт стартового набора " .. tostring(display) .. " выдан на 24 часа.")
        table.insert(rows, {
          alias = alias,
          display = display,
          asset = asset,
          minutes = minutes,
          penalty = penalty,
          message = message
        })
      end
    end
  end
  return rows
end

function deliverWelcomeRentalVehiclesAsync(info, queueItem, onComplete)
  local vehicles = welcomeRentalVehicles()
  if type(onComplete) ~= "function" then return false, "welcome vehicle callback is missing" end
  local completed = false
  local function finish(allOk, message)
    if completed then return end
    completed = true
    local function invoke()
      local callbackOk, callbackErr = pcall(onComplete, allOk == true, tostring(message or ""))
      if not callbackOk then appendLog("welcome vehicle result handler failed: " .. tostring(callbackErr)) end
    end
    if type(deferGame) == "function" and deferGame(1, invoke) then return end
    invoke()
  end
  if #vehicles == 0 then
    finish(true, "")
    return true
  end
  local okCount = 0
  local messages = {}
  local index = 1
  local function runNext()
    if index > #vehicles then
      finish(okCount == #vehicles, "Транспорт стартпака: " .. table.concat(messages, "; "))
      return
    end
    local vehicle = vehicles[index]
    local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
    local spawnX, spawnY, spawnZ = vectorOf(live.pawn)
    local scheduled, scheduleMessage = spawnVehicleForInfoAsync(vehicle.asset, live, {
      requireForwardLocation = true,
      source = "welcome-pack-rental"
    }, function(sent, result, destroyRef, beforeVehicles)
      if vehicleSpawnAsyncQueueIsStale(queueItem, "welcome-pack-rental") then
        finish(false, "Транспорт стартпака отменён: очередь выдачи уже завершилась.")
        return
      end
      local currentLive = resolvePlayerInfo(live.steam, live.name, live, live.runtimeKey) or live
      if sent then
        okCount = okCount + 1
        local startedAt = os.time()
        local expiresAt = startedAt + vehicle.minutes * 60
        local extraFields = ',"source":"welcome-pack","freeWelcomeRental":true'
        if tostring(destroyRef or "") ~= "" then
          completeRentalCreation(currentLive, vehicle.alias, vehicle.display, vehicle.asset, vehicle.minutes, 0, 0, 0, destroyRef or "", startedAt, expiresAt, false, extraFields, vehicle.penalty, vehicle.message)
        else
          appendActiveRentalRecord(currentLive, vehicle.alias, vehicle.display, vehicle.asset, vehicle.minutes, startedAt, expiresAt, 0, 0, 0, "", extraFields .. ',"pendingVerify":true', vehicle.penalty)
          scheduleRentalCreationVerification(currentLive, vehicle.alias, {
            asset = vehicle.asset,
            display = vehicle.display,
            initial = 0,
            price = 0,
            extraFields = extraFields,
            missingPenalty = vehicle.penalty,
            messageOverride = vehicle.message
          }, vehicle.minutes, 0, beforeVehicles or {}, spawnX, spawnY, spawnZ)
        end
        table.insert(messages, tostring(vehicle.display) .. " на " .. tostring(vehicle.minutes) .. " мин.")
      else
        table.insert(messages, tostring(vehicle.display) .. ": " .. tostring(result or "не выдан"))
      end
      index = index + 1
      runNext()
    end)
    if not scheduled then
      table.insert(messages, tostring(vehicle.display) .. ": " .. tostring(scheduleMessage or "не поставлен в безопасную очередь"))
      index = index + 1
      runNext()
    end
  end
  runNext()
  return true
end

function dailyPackItemsSpec()
  local configured = itemsSpecFromConfig(configText("daily-pack"))
  if configured ~= "" then return configured end
  return "Apple_2|2;CannedGoulash|1;Emergency_bandage_Big|1"
end

DAILY_REWARDS_PENDING = DAILY_REWARDS_PENDING or {}
DAILY_REWARDS_IN_FLIGHT = DAILY_REWARDS_IN_FLIGHT or {}
DAILY_REWARDS_LAST_QUEUE_SCAN_AT = DAILY_REWARDS_LAST_QUEUE_SCAN_AT or 0

function dailyRewardsTodayKey()
  return os.date("!%Y-%m-%d", os.time())
end

function dailyRewardsMaxDays()
  return math.max(1, math.min(math.floor(configNumber("battlepass", { "MaxDays", "maxDays" }, 30) or 30), 365))
end

function dailyRewardsDelaySeconds()
  return math.max(60, math.floor(configNumber("battlepass", { "DelayAfterJoinSeconds", "delayAfterJoinSeconds", "JoinDelaySeconds", "joinDelaySeconds" }, 60) or 60))
end

function dailyRewardsStableKey(info)
  if info == nil then return "" end
  if looksLikeSteamId(tostring(info.steam or info.steamId or "")) then return "steam:" .. tostring(info.steam or info.steamId) end
  local profile = cleanText(info.userProfileId or info.serverUserProfileId or info.profileId or "")
  if profile ~= "" and profile ~= "0" then return "profile:" .. profile end
  local name = cleanText(info.name or "")
  if name ~= "" and name:lower() ~= "unknown" then return "name:" .. name:lower() end
  return ""
end

function dailyRewardsSnapshot(info)
  info = info or {}
  return {
    steam = tostring(info.steam or info.steamId or ""),
    name = tostring(info.name or ""),
    userProfileId = tostring(info.userProfileId or ""),
    serverUserProfileId = tostring(info.serverUserProfileId or ""),
    runtimeKey = tostring(info.runtimeKey or "")
  }
end

function dailyRewardsCurrentState(info)
  local latest = nil
  for _, object in ipairs(stateObjects("daily-rewards-state.json")) do
    if samePlayerRecord(info, object) then latest = object end
  end
  for _, object in ipairs(stateObjects("battlepass-state.json")) do
    if samePlayerRecord(info, object) then latest = object end
  end
  return {
    day = math.max(0, math.floor(extractNumberAny(latest or "", { "Day", "day", "lastRewardDay", "LastRewardDay" }, 0) or 0)),
    lastDate = extractStringAny(latest or "", { "LastDate", "lastDate", "date", "Date" }) or "",
    lastAt = extractNumberAny(latest or "", { "at", "At" }, 0) or 0
  }
end

function dailyRewardsStateRecord(info, day, dateKey, status, message)
  return '{"utc":' .. js(nowUtc()) ..
    ',"at":' .. tostring(os.time()) ..
    ',"steamId":' .. js(info.steam or info.steamId or "") ..
    ',"name":' .. js(info.name or "") ..
    ',"userProfileId":' .. js(info.userProfileId or info.serverUserProfileId or "") ..
    ',"runtimeKey":' .. js(info.runtimeKey or "") ..
    ',"day":' .. tostring(math.max(0, math.floor(tonumber(day) or 0))) ..
    ',"lastDate":' .. js(dateKey or dailyRewardsTodayKey()) ..
    ',"status":' .. js(status or "claimed") ..
    ',"message":' .. js(message or "") .. '}'
end

function dailyRewardsSaveState(info, day, dateKey, status, message)
  local rows = {}
  local replaced = false
  local record = dailyRewardsStateRecord(info, day, dateKey, status, message)
  for _, object in ipairs(stateObjects("battlepass-state.json")) do
    if samePlayerRecord(info, object) then
      if not replaced then table.insert(rows, record) end
      replaced = true
    else
      table.insert(rows, object)
    end
  end
  if not replaced then table.insert(rows, record) end
  return writeStateObjects("battlepass-state.json", rows)
end

function dailyRewardsObjects(keyName)
  local text = configText("battlepass")
  local rows = jsonArrayObjects(text, keyName or "Rewards")
  if #rows == 0 and keyName == nil then rows = jsonArrayObjects(text, "rewards") end
  return rows
end

function dailyRewardFromObject(object)
  local itemsSpec = extractStringAny(object, { "ItemsSpec", "itemsSpec", "ItemsText", "itemsText" }) or ""
  if itemsSpec == "" then itemsSpec = itemsSpecFromConfigArray(object, { "Items", "items" }) end
  return {
    enabled = extractBoolAny(object, { "Enabled", "enabled" }, true) ~= false,
    day = math.max(1, math.floor(extractNumberAny(object, { "Day", "day" }, 1) or 1)),
    money = math.floor(extractNumberAny(object, { "MoneyAmount", "moneyAmount", "Money", "money" }, 0) or 0),
    gold = math.floor(extractNumberAny(object, { "GoldAmount", "goldAmount", "Gold", "gold" }, 0) or 0),
    fame = math.floor(extractNumberAny(object, { "FameAmount", "fameAmount", "Fame", "fame" }, 0) or 0),
    itemsSpec = itemsSpec,
    message = extractStringAny(object, { "Message", "message", "SuccessMessage", "successMessage" }) or ""
  }
end

function dailyRewardsVipEnabledForInfo(info)
  if not vipActiveForInfo(info) then return false end
  local object = jsonObjectForKey(configText("battlepass"), "VipSettings") or jsonObjectForKey(configText("battlepass"), "vipSettings") or ""
  if object ~= "" and extractBoolAny(object, { "Enabled", "enabled" }, true) == false then return false end
  local required = extractStringAny(object, { "RequiredPermission", "requiredPermission" }) or "vip.active"
  return hasPermission(info, required)
end

function dailyRewardForDay(day, info)
  local wanted = math.max(1, math.floor(tonumber(day) or 1))
  if dailyRewardsVipEnabledForInfo(info) then
    local vipRows = dailyRewardsObjects("VipRewards")
    if #vipRows == 0 then vipRows = dailyRewardsObjects("vipRewards") end
    for _, object in ipairs(vipRows) do
      local reward = dailyRewardFromObject(object)
      if reward.day == wanted then
        reward.vip = true
        local vipSettings = jsonObjectForKey(configText("battlepass"), "VipSettings") or jsonObjectForKey(configText("battlepass"), "vipSettings") or ""
        if reward.message == "" then reward.message = extractStringAny(vipSettings, { "SuccessMessage", "successMessage" }) or "" end
        return reward
      end
    end
  end
  for _, object in ipairs(dailyRewardsObjects("Rewards")) do
    local reward = dailyRewardFromObject(object)
    if reward.day == wanted then return reward end
  end
  return nil
end

function dailyRewardsFormatMessage(template, info, day, maxDays, reward)
  local text = tostring(template or "")
  if text == "" then text = configString("battlepass", { "SuccessMessage", "successMessage" }, "Battlepass награда {day}/{maxDays} выдана.") end
  text = text:gsub("{day}", tostring(day or 0))
  text = text:gsub("{maxDays}", tostring(maxDays or dailyRewardsMaxDays()))
  text = text:gsub("{money}", tostring((reward or {}).money or 0))
  text = text:gsub("{gold}", tostring((reward or {}).gold or 0))
  text = text:gsub("{fame}", tostring((reward or {}).fame or 0))
  text = text:gsub("{player}", tostring((info or {}).name or ""))
  return text
end

function dailyRewardsAppendClaim(info, day, dateKey, okRun, message, reward)
  appendJsonArray(STATE_DIR .. "\\battlepass-claims.json",
    '{"utc":' .. js(nowUtc()) ..
    ',"at":' .. tostring(os.time()) ..
    ',"steamId":' .. js(info.steam or info.steamId or "") ..
    ',"name":' .. js(info.name or "") ..
    ',"userProfileId":' .. js(info.userProfileId or info.serverUserProfileId or "") ..
    ',"runtimeKey":' .. js(info.runtimeKey or "") ..
    ',"day":' .. tostring(day or 0) ..
    ',"date":' .. js(dateKey or dailyRewardsTodayKey()) ..
    ',"ok":' .. (okRun and "true" or "false") ..
    ',"money":' .. tostring((reward or {}).money or 0) ..
    ',"gold":' .. tostring((reward or {}).gold or 0) ..
    ',"fame":' .. tostring((reward or {}).fame or 0) ..
    ',"itemsSpec":' .. js((reward or {}).itemsSpec or "") ..
    ',"message":' .. js(message or "") .. '}',
    1024 * 1024)
end

function dailyRewardsMaybeQueueInfo(info, reason)
  if not moduleEnabled("battlepass", false) then return false end
  info = enrichPlayerInfoFromServerLog(info) or info
  local required = configString("battlepass", { "RequiredPermission", "requiredPermission" }, "")
  if not hasPermission(info, required) then return false end
  local key = dailyRewardsStableKey(info)
  if key == "" then return false end
  if DAILY_REWARDS_PENDING[key] ~= nil or DAILY_REWARDS_IN_FLIGHT[key] ~= nil then return false end
  local today = dailyRewardsTodayKey()
  local state = dailyRewardsCurrentState(info)
  local maxDays = dailyRewardsMaxDays()
  if state.lastDate == today or state.day >= maxDays then return false end
  local now = os.time()
  local delay = dailyRewardsDelaySeconds()
  DAILY_REWARDS_PENDING[key] = {
    info = dailyRewardsSnapshot(info),
    dueAt = now + delay,
    expiresAt = now + delay + math.max(180, configNumber("battlepass", { "RetryWindowSeconds", "retryWindowSeconds" }, 300) or 300),
    reason = tostring(reason or "runtime-cache")
  }
  appendActionEvent("battlepass_queue", true, info,
    "Battlepass reward scheduled after join delay.",
    '{"delaySeconds":' .. tostring(delay) .. ',"reason":' .. js(reason or "") .. ',"key":' .. js(key) .. '}')
  return true
end

function dailyRewardsQueueForInfos(infos, reason)
  if not moduleEnabled("battlepass", false) then return 0 end
  local queued = 0
  for _, info in ipairs(infos or {}) do
    if dailyRewardsMaybeQueueInfo(info, reason) then queued = queued + 1 end
  end
  return queued
end

function dailyRewardsFinishGrant(queueItem, key, info, day, dateKey, okRun, message, reward)
  if okRun then
    dailyRewardsSaveState(info, day, dateKey, "claimed", message)
  end
  dailyRewardsAppendClaim(info, day, dateKey, okRun, message, reward)
  local playerMessage = okRun and dailyRewardsFormatMessage((reward or {}).message, info, day, dailyRewardsMaxDays(), reward) or "Battlepass награда не выдана. Детали записаны в журнал администратора."
  targetMessage(info.steam, info.name, playerMessage, "battlepass", info.runtimeKey)
  DAILY_REWARDS_IN_FLIGHT[key] = nil
  finishMutationQueueAsync(queueItem, okRun, okRun and "Battlepass completed." or tostring(message or "Battlepass failed."))
end

function dailyRewardsGrantNow(key, pending)
  local saved = pending and pending.info or {}
  local live = resolvePlayerInfo(saved.steam, saved.name, saved, saved.runtimeKey)
  if live == nil or not playerInfoHasLiveRuntime(live) then
    local now = os.time()
    if pending ~= nil and now < (tonumber(pending.expiresAt) or 0) then
      pending.dueAt = now + 20
      return false, "retry"
    end
    appendActionEvent("battlepass", false, saved, "Player is not live after join delay.", '{"stage":"resolve-live","key":' .. js(key or "") .. '}')
    return false, "expired"
  end
  live = enrichPlayerInfoFromServerLog(live) or live
  local readyInfo, ready, readyDetail, readyReason = deliveryReadyInfo(live, { requireInventory = false })
  if not ready then
    local now = os.time()
    local message = "Battlepass reward deferred: player is not ready (" .. tostring(readyReason or "unknown") .. ")."
    if pending ~= nil and now < (tonumber(pending.expiresAt) or 0) then
      pending.dueAt = now + 20
      appendActionEvent("battlepass_queue", false, live, message,
        '{"retry":true,"stage":"delivery-readiness","reason":' .. js(readyReason or "") ..
        ',"detail":' .. js(readyDetail or "") .. ',"key":' .. js(key or "") .. '}')
      return false, "retry"
    end
    appendActionEvent("battlepass", false, live, message,
      '{"stage":"delivery-readiness","reason":' .. js(readyReason or "") ..
      ',"detail":' .. js(readyDetail or "") .. ',"key":' .. js(key or "") .. '}')
    return false, "expired"
  end
  live = readyInfo or live
  local today = dailyRewardsTodayKey()
  local state = dailyRewardsCurrentState(live)
  local maxDays = dailyRewardsMaxDays()
  if state.lastDate == today or state.day >= maxDays then return true, "already-done" end
  local nextDay = math.min(state.day + 1, maxDays)
  local reward = dailyRewardForDay(nextDay, live)
  if reward == nil or reward.enabled == false then
    local message = "Battlepass reward day has no enabled reward; progress advanced."
    dailyRewardsSaveState(live, nextDay, today, "empty", message)
    dailyRewardsAppendClaim(live, nextDay, today, true, message, reward or {})
    appendActionEvent("battlepass", true, live, message, '{"day":' .. tostring(nextDay) .. ',"empty":true}')
    return true, "empty"
  end

  DAILY_REWARDS_IN_FLIGHT[key] = true
  local queued, queueMessage = enqueueMutation("battlepass", live, function(queueItem)
    local current = resolvePlayerInfo(live.steam, live.name, live, live.runtimeKey) or live
    local currentReady, isCurrentReady, currentReadyDetail, currentReadyReason = deliveryReadyInfo(current, { requireInventory = false })
    if not isCurrentReady then
      local now = os.time()
      local message = "Battlepass reward deferred in mutation queue: player is not ready (" .. tostring(currentReadyReason or "unknown") .. ")."
      DAILY_REWARDS_IN_FLIGHT[key] = nil
      if pending ~= nil and now < (tonumber(pending.expiresAt) or 0) then
        pending.dueAt = now + 20
        DAILY_REWARDS_PENDING[key] = pending
        appendActionEvent("battlepass_queue", false, current, message,
          '{"retry":true,"stage":"delivery-readiness","phase":"mutation-callback","reason":' .. js(currentReadyReason or "") ..
          ',"detail":' .. js(currentReadyDetail or "") .. ',"key":' .. js(key or "") .. '}')
      else
        appendActionEvent("battlepass", false, current, message,
          '{"stage":"delivery-readiness","phase":"mutation-callback","reason":' .. js(currentReadyReason or "") ..
          ',"detail":' .. js(currentReadyDetail or "") .. ',"key":' .. js(key or "") .. '}')
      end
      if queueItem ~= nil then
        finishMutationQueueAsync(queueItem, false, message)
        return "__mutation_async__"
      end
      error(message)
    end
    current = currentReady or current
    appendLog("battlepass grant start steam=" .. tostring(current.steam or "") ..
      " name=" .. tostring(current.name or "") ..
      " runtimeKey=" .. tostring(current.runtimeKey or "") ..
      " day=" .. tostring(nextDay) ..
      " money=" .. tostring(reward.money or 0) ..
      " gold=" .. tostring(reward.gold or 0) ..
      " fame=" .. tostring(reward.fame or 0) ..
      " items=" .. tostring(reward.itemsSpec or ""))
    local okRun = true
    local messages = {}
    if reward.money ~= 0 then
      local okMoney, moneyMessage = changeMoney(current.steam, current.name, reward.money, "Normal", current.runtimeKey)
      okRun = okRun and okMoney
      table.insert(messages, tostring(moneyMessage or "money"))
    end
    if reward.gold ~= 0 then
      local okGold, goldMessage = changeMoney(current.steam, current.name, reward.gold, "Gold", current.runtimeKey)
      okRun = okRun and okGold
      table.insert(messages, tostring(goldMessage or "gold"))
    end
    if reward.fame ~= 0 then
      local okFame, fameMessage = changeFamePoints(current.steam, current.name, reward.fame, current.runtimeKey)
      okRun = okRun and okFame
      table.insert(messages, tostring(fameMessage or "fame"))
    end
    local itemsSpec = tostring(reward.itemsSpec or "")
    if itemsSpec ~= "" then
      deliverItemsBatchAsync(current.steam, current.name, itemsSpec, current, current.runtimeKey,
        configNumber("battlepass", { "InterItemDelayMs", "interItemDelayMs" }, 1500),
        function(itemsOk, itemsMessage)
          table.insert(messages, tostring(itemsMessage or "items"))
          dailyRewardsFinishGrant(queueItem, key, current, nextDay, today, okRun and itemsOk ~= false, table.concat(messages, " | "), reward)
        end)
      return "__mutation_async__"
    end
    local message = table.concat(messages, " | ")
    if okRun then dailyRewardsSaveState(current, nextDay, today, "claimed", message) end
    dailyRewardsAppendClaim(current, nextDay, today, okRun, message, reward)
    targetMessage(current.steam, current.name,
      okRun and dailyRewardsFormatMessage(reward.message, current, nextDay, maxDays, reward) or "Battlepass награда не выдана. Детали записаны в журнал администратора.",
      "battlepass", current.runtimeKey)
    DAILY_REWARDS_IN_FLIGHT[key] = nil
  end)
  if not queued then
    DAILY_REWARDS_IN_FLIGHT[key] = nil
    if pending ~= nil and os.time() < (tonumber(pending.expiresAt) or 0) then
      pending.dueAt = os.time() + 30
      appendActionEvent("battlepass_queue", false, live, tostring(queueMessage), '{"retry":true,"key":' .. js(key or "") .. '}')
      return false, "retry"
    end
    appendActionEvent("battlepass_queue", false, live, tostring(queueMessage), '{"retry":false,"key":' .. js(key or "") .. '}')
    return false, "queue-failed"
  end
  appendActionEvent("battlepass_queue", true, live, "Battlepass reward queued for delivery.", '{"day":' .. tostring(nextDay) .. ',"key":' .. js(key or "") .. '}')
  return true, "queued"
end

function drainDailyRewards()
  if not moduleEnabled("battlepass", false) then return end
  local nowClock = os.clock()
  if (nowClock - (tonumber(DAILY_REWARDS_LAST_QUEUE_SCAN_AT) or 0)) > 15 then
    DAILY_REWARDS_LAST_QUEUE_SCAN_AT = nowClock
    dailyRewardsQueueForInfos(PLAYER_INFO_CACHE or {}, "battlepass-loop")
  end
  local now = os.time()
  for key, pending in pairs(DAILY_REWARDS_PENDING or {}) do
    if now >= (tonumber(pending.dueAt) or 0) and DAILY_REWARDS_IN_FLIGHT[key] == nil then
      local okGrant, result = dailyRewardsGrantNow(key, pending)
      if result ~= "retry" then
        DAILY_REWARDS_PENDING[key] = nil
      end
    end
  end
end

function dailyRewardsStatusText(info)
  if not moduleEnabled("battlepass", false) then
    return "Battlepass сейчас отключён."
  end
  local live = enrichPlayerInfoFromServerLog(info) or info or {}
  local required = configString("battlepass", { "RequiredPermission", "requiredPermission" }, "")
  if not hasPermission(live, required) then
    return permissionDeniedText(required)
  end
  local state = dailyRewardsCurrentState(live)
  local maxDays = dailyRewardsMaxDays()
  local today = dailyRewardsTodayKey()
  local tier = dailyRewardsVipEnabledForInfo(live) and "VIP" or "обычный"
  local key = dailyRewardsStableKey(live)
  local nextDay = math.min(math.max(1, state.day + 1), maxDays)
  if state.day >= maxDays then
    return "Battlepass завершён: " .. tostring(state.day) .. "/" .. tostring(maxDays) .. ". Режим: " .. tier .. "."
  end
  if state.lastDate == today then
    return "Battlepass сегодня уже получен. Текущий прогресс: " .. tostring(state.day) .. "/" .. tostring(maxDays) .. ". Режим: " .. tier .. "."
  end
  local pending = key ~= "" and DAILY_REWARDS_PENDING[key] or nil
  if pending ~= nil then
    local left = math.max(0, math.ceil((tonumber(pending.dueAt) or os.time()) - os.time()))
    return "Battlepass день " .. tostring(nextDay) .. "/" .. tostring(maxDays) .. " ожидает прогрузку. Выдача через " .. tostring(left) .. " сек. Режим: " .. tier .. "."
  end
  if key == "" then
    return "Battlepass не может определить игрока. Перезайди на сервер или подожди обновления списка игроков."
  end
  local queued = dailyRewardsMaybeQueueInfo(live, "manual-status-command")
  if queued then
    return "Battlepass день " .. tostring(nextDay) .. "/" .. tostring(maxDays) .. " поставлен в очередь. Выдача через " .. tostring(dailyRewardsDelaySeconds()) .. " сек после прогрузки. Режим: " .. tier .. "."
  end
  return "Battlepass день " .. tostring(nextDay) .. "/" .. tostring(maxDays) .. " будет выдан автоматически после входа и прогрузки. Режим: " .. tier .. "."
end

function deliverItemsBatch(steamId, name, itemsSpec, preferredInfo, runtimeKey)
  local info = resolvePlayerInfo(steamId, name, preferredInfo, runtimeKey)
  if info == nil then info = { steam = tostring(steamId or ""), name = tostring(name or ""), source = "delivery-identity" } end
  if tostring(info.steam or "") == "" then info.steam = tostring(steamId or "") end
  if tostring(info.name or "") == "" or tostring(info.name or "") == "Unknown" then info.name = tostring(name or "") end
  local items = parseItemsSpec(itemsSpec)
  if #items == 0 then return false, "items for delivery are not configured", "{}" end
  local refreshedInfo = refreshRuntimePlayerInfo(info)
  if refreshedInfo ~= nil then info = refreshedInfo end
  local hasAdminTarget = looksLikeSteamId(tostring(info.steam or ""))
  local hasDirectTarget = info.pawn ~= nil and isValidObject(info.pawn)
  if hasAdminTarget or hasDirectTarget then
    local results = {}
    local failures = {}
    local okItems = 0
    local deliveredQuantity = 0
    for _, item in ipairs(items) do
      local okCount, requested, path, details = deliverItemTypeForInfo(info, item.itemId, item.quantity)
      details = details or {}
      local itemOk = okCount == requested
      if itemOk then okItems = okItems + 1 end
      if not itemOk then table.insert(failures, tostring(item.itemId) .. ": " .. table.concat(details, " || ")) end
      deliveredQuantity = deliveredQuantity + okCount
      table.insert(results, '{"itemId":' .. js(item.itemId) ..
        ',"quantity":' .. tostring(requested) ..
        ',"delivered":' .. tostring(okCount) ..
        ',"ok":' .. (itemOk and "true" or "false") ..
        ',"path":' .. js(path) ..
        ',"message":' .. js(table.concat(details, " || ")) .. '}')
    end
    local allOk = okItems == #items
    local data = '{"requested":' .. tostring(#items) ..
      ',"delivered":' .. tostring(okItems) ..
      ',"deliveredQuantity":' .. tostring(deliveredQuantity) ..
      ',"allOk":' .. (allOk and "true" or "false") ..
      ',"adminTarget":' .. (hasAdminTarget and "true" or "false") ..
      ',"results":[' .. table.concat(results, ",") .. ']}'
    appendLog("deliver_items_batch routed target=" .. tostring(info.steam or info.name or "") .. " requested=" .. tostring(#items) .. " okItems=" .. tostring(okItems) .. " adminTarget=" .. tostring(hasAdminTarget))
    appendActionEvent("deliver_items_batch", allOk, info, allOk and "batch delivery dispatched through safe admin route" or table.concat(failures, " || "), data)
    return allOk, allOk and "batch delivery dispatched through safe admin route" or ("batch delivery incomplete: " .. table.concat(failures, " || ")), data
  end
  local liveInfo, ready, readyDetail, readyReason = deliveryReadyInfo(info, { requireInventory = true })
  if info ~= nil and not ready then
    appendActionEvent("delivery_readiness", false, info, tostring(readyDetail or ""),
      '{"reason":' .. js(readyReason or "") .. ',"itemsSpec":' .. js(itemsSpec or "") .. '}')
    return false, deliveryReadyMessage(readyReason), '{"ready":false,"reason":' .. js(readyReason or "") .. '}'
  end
  if liveInfo ~= nil then info = liveInfo end
  if info == nil then return false, "Игрок не найден среди реально подключённых.", "{}" end
  if info.pawn == nil or not isValidObject(info.pawn) then
    return false, "Игрок подключён, но персонаж и инвентарь ещё не готовы.", "{}"
  end
  local items = parseItemsSpec(itemsSpec)
  if #items == 0 then return false, "Предметы для выдачи не настроены.", "{}" end
  local results = {}
  local failures = {}
  local okItems = 0
  local deliveredQuantity = 0
  for _, item in ipairs(items) do
    local okCount, requested, path, details = deliverItemTypeForInfo(info, item.itemId, item.quantity)
    details = details or {}
    local itemOk = okCount == requested
    if itemOk then okItems = okItems + 1 end
    if not itemOk then table.insert(failures, tostring(item.itemId) .. ": " .. table.concat(details, " || ")) end
    deliveredQuantity = deliveredQuantity + okCount
    table.insert(results, '{"itemId":' .. js(item.itemId) ..
      ',"quantity":' .. tostring(requested) ..
      ',"delivered":' .. tostring(okCount) ..
      ',"ok":' .. (itemOk and "true" or "false") ..
      ',"path":' .. js(path) ..
      ',"message":' .. js(table.concat(details, " || ")) .. '}')
  end
  local allOk = okItems == #items
  local data = '{"requested":' .. tostring(#items) ..
    ',"delivered":' .. tostring(okItems) ..
    ',"deliveredQuantity":' .. tostring(deliveredQuantity) ..
    ',"allOk":' .. (allOk and "true" or "false") ..
    ',"results":[' .. table.concat(results, ",") .. ']}'
  appendLog("deliver_items_batch target=" .. tostring(steamId or name or "") .. " requested=" .. tostring(#items) .. " okItems=" .. tostring(okItems))
  appendActionEvent("deliver_items_batch", allOk, info, allOk and "Пакет предметов выдан через безопасный маршрут." or table.concat(failures, " || "), data)
  return allOk, allOk and "Пакет предметов выдан через безопасный маршрут." or ("Пакет предметов выдан не полностью: " .. table.concat(failures, " || ")), data
end

function clearInventoryNow(info)
  local attempts = {}
  local successes = {}
  table.insert(attempts, "admin.ClearInventory=disabled; SCUM build reports this command as Unrecognized")
  local inv = playerInventoryComponent(info)
  if inv ~= nil and isValidObject(inv) then
    for _, method in ipairs({"Server_ClearInventory", "ClearInventory", "Server_DropAllItems", "DropAllItems", "RemoveAllItems", "DestroyAllItems", "DeleteAllItems"}) do
      local okCall, result = safeCall(inv, method)
      table.insert(attempts, "inventory." .. method .. "=" .. (okCall and "ok" or tostring(result)))
      if okCall and result ~= false then table.insert(successes, "inventory " .. method) end
    end
  end
  if info ~= nil and info.pawn ~= nil and isValidObject(info.pawn) then
    for _, method in ipairs({"Server_ClearInventory", "ClearInventory", "Server_DropAllItems", "DropAllItems", "RemoveAllItems", "DestroyAllItems", "Server_DropItemFromHands", "DropItemFromHands"}) do
      local okCall, result = safeCall(info.pawn, method)
      table.insert(attempts, "pawn." .. method .. "=" .. (okCall and "ok" or tostring(result)))
      if okCall and result ~= false then table.insert(successes, "pawn " .. method) end
    end
    local okCall, result = safeCall(info.pawn, "RemoveItemFromHands", 0)
    table.insert(attempts, "pawn.RemoveItemFromHands=" .. (okCall and "ok" or tostring(result)))
    if okCall and result ~= false then table.insert(successes, "pawn RemoveItemFromHands") end
  end
  if #successes > 0 then
    return true, "Очистка инвентаря отправлена через live runtime: " .. table.concat(successes, ", ")
  end
  appendLog("clear inventory failed: " .. table.concat(attempts, " | "))
  return false, "Безопасный общий маршрут очистки не найден. Используй очистку через панель: она удаляет предметы по EntityID по одному. Детали: " .. table.concat(attempts, " | ")
end

function clearInventory(steamId, name, runtimeKey)
  local info = findPlayer(steamId, name, runtimeKey)
  if info == nil then return false, "Игрок не найден среди реально подключённых." end
  local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
  local okClear, message = clearInventoryNow(live)
  appendActionEvent("clear_inventory", okClear, live, tostring(message), '{"queued":false}')
  targetMessage(live.steam, live.name, okClear and "Команда очистки инвентаря отправлена. Обнови инвентарь для проверки." or ("Инвентарь не очищен: " .. tostring(message)), "inventory", live.runtimeKey)
  return okClear, tostring(message or "")
end

function setAttributes(steamId, name, strength, constitution, dexterity, intelligence, suppressActionLog, runtimeKey)
  local info = findPlayer(steamId, name, runtimeKey)
  if info == nil then
    if not suppressActionLog then
      appendActionEvent("set_attributes", false, { steam = steamId, name = name }, "Игрок не найден среди реально подключённых.", "{}")
    end
    return false, "Игрок не найден среди реально подключённых."
  end
  local liveInfo, ready, readyDetail, readyReason = deliveryReadyInfo(info, { requireInventory = false })
  if not ready then
    if not suppressActionLog then
      appendActionEvent("delivery_readiness", false, info, tostring(readyDetail or ""),
        '{"reason":' .. js(readyReason or "") .. ',"action":"set_attributes"}')
    end
    return false, deliveryReadyMessage(readyReason)
  end
  info = liveInfo
  strength = tonumber(strength) or 0
  constitution = tonumber(constitution) or 0
  dexterity = tonumber(dexterity) or 0
  intelligence = tonumber(intelligence) or 0
  local commandText = "SetAttributes " .. strength .. " " .. constitution .. " " .. dexterity .. " " .. intelligence
  local sent, message = adminExec(commandText, info)
  local resultMessage = sent and ("Атрибуты отправлены через live-маршрут игрока: " .. tostring(message or "")) or tostring(message or "")
  if not suppressActionLog then
    appendActionEvent("set_attributes", sent, info, resultMessage,
      '{"strength":' .. tostring(strength) .. ',"constitution":' .. tostring(constitution) .. ',"dexterity":' .. tostring(dexterity) .. ',"intelligence":' .. tostring(intelligence) .. ',"accepted":' .. (sent and "true" or "false") .. ',"verified":false}')
  end
  if sent then return true, resultMessage end
  return false, resultMessage ~= "" and resultMessage or "Маршрут изменения атрибутов не сработал."
end

function normalizeSkillCommandName(skill)
  local raw = valueText(skill):gsub("^%s+", ""):gsub("%s+$", "")
  if raw == "" then return "" end
  local compact = raw:lower():gsub("[\"']", ""):gsub("[%s_%-%./]+", "")
  local aliases = {
    brawling = "Brawling",
    boxing = "Brawling",
    melee = "\"Melee Weapons\"",
    meleeweapon = "\"Melee Weapons\"",
    meleeweapons = "\"Melee Weapons\"",
    resistance = "Resistance",
    cooking = "Cooking",
    tactics = "Tactics",
    aviation = "Aviation",
    farming = "Farming",
    motorcycling = "Motorcycling",
    motorcycle = "Motorcycling",
    motorcycles = "Motorcycling",
    awareness = "Awareness",
    perception = "Awareness",
    rifles = "Rifles",
    rifle = "Rifles",
    sniping = "Sniping",
    camouflage = "Camouflage",
    survival = "Survival",
    handgun = "Handgun",
    handguns = "Handgun",
    running = "Running",
    endurance = "Endurance",
    thievery = "Thievery",
    archery = "Archery",
    driving = "Driving",
    engineering = "Engineering",
    demolition = "Demolition",
    medical = "Medical",
    stealth = "Stealth",
    brawl = "Brawling",
    meleecombat = "\"Melee Weapons\"",
    pistol = "Handgun",
    pistols = "Handgun",
    handgunweapon = "Handgun",
    handgunweapons = "Handgun",
    throwing = "Throwing"
  }
  return aliases[compact] or ""
end

function setSkill(steamId, name, skill, level, experience, runtimeKey)
  local info = findPlayer(steamId, name, runtimeKey)
  if info == nil then
    appendActionEvent("set_skill", false, { steam = steamId, name = name }, "Игрок не найден среди реально подключённых.",
      '{"skill":' .. js(skill or "") .. ',"level":' .. tostring(tonumber(level) or 0) .. '}')
    return false, "Игрок не найден среди реально подключённых."
  end
  local liveInfo, ready, readyDetail, readyReason = deliveryReadyInfo(info, { requireInventory = false })
  if not ready then
    appendActionEvent("delivery_readiness", false, info, tostring(readyDetail or ""),
      '{"reason":' .. js(readyReason or "") .. ',"action":"set_skill","skill":' .. js(skill or "") .. '}')
    return false, deliveryReadyMessage(readyReason)
  end
  info = liveInfo
  skill = normalizeSkillCommandName(skill)
  if skill == "" then
    appendActionEvent("set_skill", false, info, "Навык не поддерживается текущим списком SCUM.", '{"skill":' .. js(skill or "") .. ',"level":' .. tostring(tonumber(level) or 0) .. '}')
    return false, "Навык не поддерживается текущим списком SCUM."
  end
  level = tonumber(level) or 0
  experience = tonumber(experience) or 0
  local commandText = "SetSkillLevel " .. skill .. " " .. tostring(level)
  if experience > 0 then commandText = commandText .. " " .. tostring(experience) end
  local sent, message = adminExec(commandText, info)
  appendActionEvent("set_skill", sent, info, tostring(message or ""),
    '{"skill":' .. js(skill) .. ',"level":' .. tostring(level) .. ',"experience":' .. tostring(experience) .. '}')
  if sent then return true, message end
  local finalMessage = tostring(message or "")
  return false, finalMessage ~= "" and finalMessage or "Маршрут изменения навыка не сработал."
end

