function runtimeValueJson(value)
  if value == nil then return "null" end
  local valueType = type(value)
  if valueType == "boolean" then return value and "true" or "false" end
  if valueType == "number" then return tostring(value) end
  if valueType == "string" then return js(value) end
  if valueType == "userdata" and isValidObject(value) then
    return nativeProbeObjectJson("object", value, "property", {})
  end
  return js(tostring(value))
end

function runtimeUint32Hex(value)
  local numberValue = tonumber(value)
  if numberValue == nil then return nil end
  if numberValue < 0 then numberValue = numberValue + 4294967296 end
  numberValue = math.floor(numberValue) % 4294967296
  return string.format("%08X", numberValue)
end

function runtimeGuidString(value)
  value = runtimeCollectionUnwrap(value)
  if value == nil then return "" end
  local text = ""
  if type(value) == "string" then
    text = value
  else
    local okToString, toStringValue = pcall(function()
      if value.ToString ~= nil then return value:ToString() end
      return nil
    end)
    if okToString and toStringValue ~= nil then text = tostring(toStringValue) end
  end
  text = tostring(text or ""):gsub("[{}%-]", ""):upper()
  if text:match("^[0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F]$") then
    return text
  end
  local a = runtimeUint32Hex(safeGet(value, "A") or safeGet(value, "a"))
  local b = runtimeUint32Hex(safeGet(value, "B") or safeGet(value, "b"))
  local c = runtimeUint32Hex(safeGet(value, "C") or safeGet(value, "c"))
  local d = runtimeUint32Hex(safeGet(value, "D") or safeGet(value, "d"))
  if a ~= nil and b ~= nil and c ~= nil and d ~= nil then return a .. b .. c .. d end
  return ""
end

function runtimePropJson(obj, propName)
  local okGet, value = pcall(function() return obj[propName] end)
  if okGet then
    return '"' .. tostring(propName) .. '":' .. runtimeValueJson(value)
  end
  return '"' .. tostring(propName) .. '":{"error":' .. js(tostring(value)) .. '}'
end

function runtimeCollectionUnwrap(value)
  if value == nil then return nil end
  local ok, unwrapped = pcall(function()
    if type(value) == "userdata" and value.get ~= nil then return value:get() end
    return value
  end)
  if ok then return unwrapped end
  return value
end

function runtimeStructHintJson(value)
  if value == nil then return nil end
  local keys = {
    "TraderPersonality",
    "Personality",
    "SedentaryNPCClass",
    "SpawnTransform",
    "PurchasedTradeablesSpawnTransform",
    "DepotSpawnTransform",
    "ShouldRaycastSpawnPosition",
    "MarkerType",
    "Transform"
  }
  local fields = {}
  for _, key in ipairs(keys) do
    local okGet, prop = pcall(function() return value[key] end)
    if okGet and prop ~= nil then
      local unwrapped = runtimeCollectionUnwrap(prop)
      local valueJson = runtimeValueJson(unwrapped)
      if (key == "TraderPersonality" or key == "Personality") and unwrapped ~= nil and isValidObject(unwrapped) then
        valueJson = nativeProbeObjectExtraJson("object", unwrapped, "property", '"traderPersistentId":' .. js(traderPersonalityRuntimeId(unwrapped)))
      end
      table.insert(fields, '"' .. tostring(key) .. '":' .. valueJson)
    end
  end
  if #fields == 0 then return nil end
  return '{"kind":"struct","type":' .. js(tostring(value)) .. ',"fields":{' .. table.concat(fields, ",") .. '}}'
end

function runtimeCollectionItemJson(item)
  if type(item) == "table" and item.__runtimeMapEntry == true then
    return '{"key":' .. runtimeValueJson(item.key) .. ',"value":' .. runtimeValueJson(item.value) .. '}'
  end
  if item ~= nil and isValidObject(item) then
    local className = objectClassFullName(item)
    local fullName = objectFullName(item)
    if className:find("ScriptStruct", 1, true) ~= nil or fullName:find("ScriptStruct ", 1, true) ~= nil then
      local structJson = runtimeStructHintJson(item)
      if structJson ~= nil then return structJson end
    end
    return nativeProbeObjectJson("item", item, "collection", {})
  end
  local structJson = runtimeStructHintJson(item)
  if structJson ~= nil then return structJson end
  return runtimeValueJson(item)
end

function runtimeArrayCount(value, maxItems)
  if value == nil then return 0, {}, "nil" end
  local limit = math.max(0, math.min(tonumber(maxItems) or 8, 64))
  local items = {}
  local knownCount = nil
  local method = ""
  local isArray = false

  local okArrayNum, arrayNum = pcall(function() return value:GetArrayNum() end)
  if okArrayNum and tonumber(arrayNum) ~= nil then
    knownCount = tonumber(arrayNum) or 0
    method = "GetArrayNum"
    isArray = true
  end

  if knownCount == nil then
    local okLen, len = pcall(function() return #value end)
    if okLen and tonumber(len) ~= nil then
      knownCount = tonumber(len) or 0
      method = "__len"
    end
  end

  local iterated = 0
  local okEach = pcall(function()
    value:ForEach(function(first, second)
      iterated = iterated + 1
      if #items < limit then
        local firstValue = runtimeCollectionUnwrap(first)
        local secondValue = runtimeCollectionUnwrap(second)
        if second ~= nil and not isArray then
          table.insert(items, { __runtimeMapEntry = true, key = firstValue, value = secondValue })
        elseif second ~= nil then
          table.insert(items, secondValue)
        else
          table.insert(items, firstValue)
        end
      end
      if #items >= limit then return true end
      return false
    end)
  end)
  if okEach then
    if knownCount == nil then knownCount = iterated end
    if method == "" then method = "ForEach" else method = method .. "+ForEach" end
    return knownCount, items, method
  end

  if isArray and knownCount ~= nil then
    local maxIndex = math.min(knownCount, limit)
    for i = 1, maxIndex do
      local okItem, item = pcall(function() return value[i] end)
      if okItem then table.insert(items, runtimeCollectionUnwrap(item)) end
    end
    return knownCount, items, method .. "+index"
  end

  local pairCount = 0
  local okPairs = pcall(function()
    for key, item in pairs(value) do
      pairCount = pairCount + 1
      if #items < limit then
        if type(key) == "number" then
          table.insert(items, runtimeCollectionUnwrap(item))
        else
          table.insert(items, { __runtimeMapEntry = true, key = runtimeCollectionUnwrap(key), value = runtimeCollectionUnwrap(item) })
        end
      end
    end
  end)
  if okPairs then
    if knownCount == nil then knownCount = pairCount end
    if method == "" then method = "pairs" else method = method .. "+pairs" end
    return knownCount, items, method
  end

  return knownCount or -1, {}, method ~= "" and method or "unreadable"
end

function runtimeCollectionJson(obj, propName, maxItems)
  local okGet, value = pcall(function() return obj[propName] end)
  if not okGet or value == nil then return '"' .. tostring(propName) .. '":{"present":false}' end
  local count, items, method = runtimeArrayCount(value, maxItems or 8)
  local itemJson = {}
  for _, item in ipairs(items or {}) do table.insert(itemJson, runtimeCollectionItemJson(item)) end
  return '"' .. tostring(propName) .. '":{"present":true,"count":' .. tostring(count) .. ',"readMethod":' .. js(method or "") .. ',"items":[' .. table.concat(itemJson, ",") .. ']}'
end

function runtimeMeshComponentJson(label, component)
  if component == nil or not isValidObject(component) then
    return '{"label":' .. js(label) .. ',"present":false}'
  end
  local mesh = nil
  local okMesh, meshResult = safeCall(component, "GetStaticMesh")
  if okMesh and meshResult ~= nil and isValidObject(meshResult) then mesh = meshResult end
  local okVisible, visible = safeCall(component, "IsVisible")
  local okHidden, hidden = safeCall(component, "IsHidden")
  local okCollision, collision = safeCall(component, "GetCollisionEnabled")
  return '{"label":' .. js(label) ..
    ',"present":true' ..
    ',"component":' .. nativeProbeObjectJson("component", component, label, {}) ..
    ',"mesh":' .. nativeProbeObjectJson("mesh", mesh, okMesh and "GetStaticMesh" or tostring(meshResult), {}) ..
    ',"visible":' .. (okVisible and runtimeValueJson(visible) or "null") ..
    ',"hidden":' .. (okHidden and runtimeValueJson(hidden) or "null") ..
    ',"collision":' .. (okCollision and runtimeValueJson(collision) or "null") .. '}'
end

function runtimeDistanceToInfo(actor, info)
  if actor == nil or not isValidObject(actor) then return 0 end
  local ax, ay, az = vectorOf(actor)
  local px, py, pz = vectorOf((info or {}).pawn)
  local dx = (tonumber(ax) or 0) - (tonumber(px) or 0)
  local dy = (tonumber(ay) or 0) - (tonumber(py) or 0)
  local dz = (tonumber(az) or 0) - (tonumber(pz) or 0)
  return math.sqrt(dx * dx + dy * dy + dz * dz)
end

function placeableRuntimeActorJson(actor, info)
  local x, y, z = vectorOf(actor)
  local fields = {
    runtimePropJson(actor, "_id"),
    runtimePropJson(actor, "_craftingRecipe"),
    runtimePropJson(actor, "_productClass"),
    runtimePropJson(actor, "_craftingProcess"),
    runtimePropJson(actor, "_statusFlags"),
    runtimePropJson(actor, "_placementState"),
    runtimePropJson(actor, "_replicatedLocation"),
    runtimePropJson(actor, "_replicatedPlacedLocation"),
    runtimePropJson(actor, "_replicatedRotation")
  }
  local meshes = {
    runtimeMeshComponentJson("_staticMeshComponent_Main", firstProp(actor, { "_staticMeshComponent_Main", "StaticMeshComponent_Main" })),
    runtimeMeshComponentJson("_staticMeshComponent_Outline", firstProp(actor, { "_staticMeshComponent_Outline", "StaticMeshComponent_Outline" })),
    runtimeMeshComponentJson("_staticMeshComponent_Depth", firstProp(actor, { "_staticMeshComponent_Depth", "StaticMeshComponent_Depth" })),
    runtimeMeshComponentJson("_queryStaticMeshComponent", firstProp(actor, { "_queryStaticMeshComponent", "QueryStaticMeshComponent" }))
  }
  return '{"actor":' .. nativeProbeObjectJson("placeable", actor, "runtime", {}) ..
    ',"distance":' .. tostring(math.floor(runtimeDistanceToInfo(actor, info))) ..
    ',"location":{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. '}' ..
    ',"fields":{' .. table.concat(fields, ",") .. '}' ..
    ',"meshes":[' .. table.concat(meshes, ",") .. ']}'
end

function debugPlaceableRuntimeProbe(steamId, name, runtimeKey, maxCount)
  local info = resolvePlayerInfo(steamId, name, nil, runtimeKey) or findPlayer(steamId, name, runtimeKey)
  if not scanFeatureEnabled({ "AllowProbeRuntimeObjectScan", "allowProbeRuntimeObjectScan" }, false) then
    local baseManager = nil
    local gameMode = gameModeRoot()
    local okBase, baseResult = safeCall(gameMode, "GetBaseManager")
    if okBase and baseResult ~= nil and isValidObject(baseResult) then baseManager = baseResult end
    local data = '{"player":' .. nativeProbePlayerJson(info) ..
      ',"baseManager":' .. nativeProbeObjectJson("baseManager", baseManager, okBase and "GameMode.GetBaseManager" or tostring(baseResult), {}) ..
      ',"placeableCount":null' ..
      ',"skipped":true' ..
      ',"note":"Runtime placeable scan отключён bridge-safety.AllowProbeRuntimeObjectScan=false, чтобы не давать 400ms+/5s ping spikes на живом сервере."}'
    appendActionEvent("debug_placeable_runtime_probe", true, info, "Placeable runtime-probe пропущен безопасно: runtime scan отключён.", data)
    return true, "Placeable runtime-probe пропущен безопасно: runtime scan отключён.", data
  end
  local actors = collectNativePlaceableActors()
  table.sort(actors, function(a, b) return runtimeDistanceToInfo(a, info) < runtimeDistanceToInfo(b, info) end)
  local rows = {}
  local limit = math.max(1, math.min(tonumber(maxCount) or 12, 40))
  for i, actor in ipairs(actors or {}) do
    if i > limit then break end
    table.insert(rows, placeableRuntimeActorJson(actor, info))
  end
  local baseCount = 0
  local baseManager = nil
  local gameMode = gameModeRoot()
  local okBase, baseResult = safeCall(gameMode, "GetBaseManager")
  if okBase and baseResult ~= nil and isValidObject(baseResult) then baseManager = baseResult end
  if baseManager ~= nil and isValidObject(baseManager) then
    local bases = firstProp(baseManager, { "_bases", "Bases" })
    baseCount = select(1, runtimeArrayCount(bases, 4))
  end
  local data = '{"player":' .. nativeProbePlayerJson(info) ..
    ',"baseManager":' .. nativeProbeObjectJson("baseManager", baseManager, okBase and "GameMode.GetBaseManager" or tostring(baseResult), {}) ..
    ',"baseManagerBaseCount":' .. tostring(baseCount) ..
    ',"placeableCount":' .. tostring(#(actors or {})) ..
    ',"placeables":[' .. table.concat(rows, ",") .. ']' ..
    ',"note":"Если _craftingRecipe/_productClass есть, но main mesh nil или state не Placed, это blueprint/placeable ghost, не готовый persistent base_element."}'
  appendActionEvent("debug_placeable_runtime_probe", true, info, "Placeable runtime-probe выполнен.", data)
  return true, "Placeable runtime-probe выполнен.", data
end

function actorKeyLooksTradePost(actorClass, entry)
  local parentName = actorRouteParentName(entry or actorCatalogLookup(actorClass))
  local key = tostring(actorRouteShortClass(actorClass, entry)):lower()
  local path = tostring((entry ~= nil and entry ~= false and (entry.objectPath or entry.packagePath or entry.path)) or ""):lower()
  if parentName == "tradepost" then return true end
  if key:find("interactionbox", 1, true) ~= nil or key:find("interactionboxes", 1, true) ~= nil then return true end
  if key:find("interractionbox", 1, true) ~= nil or key:find("interractionboxes", 1, true) ~= nil then return true end
  if key:find("npc_interaction", 1, true) ~= nil or key:find("npcinteraction", 1, true) ~= nil then return true end
  if path:find("/models/buildings/outpost/", 1, true) ~= nil and (path:find("npc", 1, true) ~= nil or path:find("trader", 1, true) ~= nil) then return true end
  return false
end

function actorCatalogIsActualTraderActor(actorClass, entry)
  local parentName = actorRouteParentName(entry or actorCatalogLookup(actorClass))
  local key = tostring(actorRouteShortClass(actorClass, entry)):lower()
  if actorKeyLooksTradePost(actorClass, entry) then return false end
  if parentName == "tradepost" then return false end
  if parentName == "banker" or key:find("bp_banker", 1, true) ~= nil then return false end
  if parentName == "trader" or parentName == "doctor" or parentName == "mechanic" then return true end
  return key == "bp_master_trader" or key:find("bp_armsdealer", 1, true) ~= nil or
    key:find("bp_barber", 1, true) ~= nil or
    key:find("bp_bartender", 1, true) ~= nil or key:find("bp_doctor", 1, true) ~= nil or
    key:find("bp_mechanic", 1, true) ~= nil or key:find("bp_general_goods", 1, true) ~= nil or
    key:find("bp_harbourmaster", 1, true) ~= nil
end

function actorCatalogIsBankerActor(actorClass, entry)
  local parentName = actorRouteParentName(entry or actorCatalogLookup(actorClass))
  local key = tostring(actorRouteShortClass(actorClass, entry)):lower()
  if actorKeyLooksTradePost(actorClass, entry) then return false end
  return parentName == "banker" or key:find("bp_banker", 1, true) ~= nil
end

function actorCatalogIsTraderLike(actorClass, entry)
  return actorCatalogIsActualTraderActor(actorClass, entry) or actorCatalogIsBankerActor(actorClass, entry)
end

function actorCatalogIsTradePostLike(actorClass, entry)
  return actorKeyLooksTradePost(actorClass, entry)
end

