function traderTypeHint(actorClass, trader)
  local text = tostring(actorClass or "") .. " " .. objectFullName(trader) .. " " .. objectClassFullName(trader)
  text = text:lower()
  if text:find("arms", 1, true) or text:find("armory", 1, true) then return "armorer" end
  if text:find("general", 1, true) or text:find("goods", 1, true) then return "generalgoods" end
  if text:find("mechanic", 1, true) then return "mechanic" end
  if text:find("doctor", 1, true) then return "doctor" end
  if text:find("harbour", 1, true) or text:find("fisher", 1, true) then return "harbourmaster" end
  if text:find("bartender", 1, true) or text:find("saloon", 1, true) then return "bartender" end
  if text:find("barber", 1, true) then return "barber" end
  if text:find("banker", 1, true) then return "banker" end
  return ""
end

function traderPersonalityMatchesHint(personality, hint)
  if personality == nil or not isValidObject(personality) then return false end
  if tostring(hint or "") == "" then return true end
  local fullNameText = objectFullName(personality):lower()
  local text = fullNameText
  local okName, humanName = pcall(function() return personality.HumanReadableTraderName end)
  if okName then text = text .. " " .. tostring(humanName or ""):lower() end
  local okType, traderType = pcall(function() return personality.TraderType end)
  if okType then text = text .. " " .. tostring(traderType or ""):lower() end
  local compactText = text:gsub("[^%w]", "")
  local rawHint = tostring(hint):lower()
  local aliases = { rawHint }
  if rawHint == "armorer" then aliases = { "armorer", "armory", "armsdealer", "arms", "weapon" } end
  if rawHint == "generalgoods" then
    local leaf = fullNameText:match("/([^/%s]+)$") or fullNameText
    local compactLeaf = leaf:gsub("[^%w]", "")
    return compactLeaf:find("traderpersonality", 1, true) ~= nil and
      compactLeaf:find("doctor", 1, true) == nil and
      compactLeaf:find("armory", 1, true) == nil and
      compactLeaf:find("mechanic", 1, true) == nil and
      compactLeaf:find("barber", 1, true) == nil and
      compactLeaf:find("barmen", 1, true) == nil and
      compactLeaf:find("boat", 1, true) == nil
  end
  if rawHint == "harbourmaster" then aliases = { "harbourmaster", "harbour", "fisher", "boat" } end
  if rawHint == "bartender" then aliases = { "bartender", "barmen", "saloon" } end
  for _, alias in ipairs(aliases) do
    local needle = tostring(alias or ""):lower()
    if needle ~= "" and text:find(needle, 1, true) ~= nil then return true end
    local compactNeedle = needle:gsub("[^%w]", "")
    if compactNeedle ~= "" and compactText:find(compactNeedle, 1, true) ~= nil then return true end
  end
  return false
end

function findTraderPersonalityDonor(actorClass, targetTrader)
  local hint = traderTypeHint(actorClass, targetTrader)
  local targetKey = objectKey(targetTrader)
  local best = nil
  local bestPersonality = nil
  local fallBack = nil
  local fallBackPersonality = nil
  for _, trader in ipairs(findAll({ "Trader", "Doctor", "Mechanic", "BP_ArmsDealer_01_C", "BP_General_Goods_01_C", "BP_Harbourmaster_01_C", "BP_Bartender_01_C", "BP_Barber_01_C", "BP_Doctor_01_C", "BP_Mechanic_C" })) do
    if objectKey(trader) ~= targetKey then
      local personality = traderPersonalityObject(trader)
      if personality ~= nil and isValidObject(personality) then
        if fallBack == nil then fallBack, fallBackPersonality = trader, personality end
        if traderPersonalityMatchesHint(personality, hint) then
          best, bestPersonality = trader, personality
          break
        end
      end
    end
  end
  if best ~= nil then return best, bestPersonality, "hint:" .. tostring(hint) end
  return fallBack, fallBackPersonality, "fallback:any-trader-personality"
end

function tradePostClassesForLookup()
  return {
    "TradePost",
    "BP_BarberShop_NPC_InteractionBox_C",
    "BP_Outpost_Trader_NPCInteractionBox_C",
    "BP_Outpost_Armory_NPCInteractionBox_C",
    "BP_FishermanTrader_NPC_InteractionBox_C",
    "BP_Outpost_Hospital_NPC_InteractionBoxes_C",
    "BP_Outpost_CarShop_NPC_and_VehicleSpawner_C",
    "BP_SaloonOutpost_NPC_InteractionBoxes_C",
    "BP_Outpost_Bank_open_NPC_InteractionBoxes_C"
  }
end

function tradePostMarkerPersonality(marker)
  local personality = runtimeCollectionUnwrap(firstProp(marker, { "TraderPersonality", "Personality" }))
  if personality ~= nil and isValidObject(personality) then return personality end
  return nil
end

function findTraderPersonalityFromTradePostMarker(actorClass, targetTrader)
  local hint = traderTypeHint(actorClass, targetTrader)
  local bestPost, bestPersonality, bestDistance = nil, nil, nil
  local fallbackPost, fallbackPersonality, fallbackDistance = nil, nil, nil
  for _, tradePost in ipairs(findAll(tradePostClassesForLookup())) do
    local markers = firstProp(tradePost, { "_traderMarkers", "TraderMarkers" })
    local _, items = runtimeArrayCount(markers, 16)
    for _, marker in ipairs(items or {}) do
      local personality = tradePostMarkerPersonality(marker)
      if personality ~= nil and isValidObject(personality) then
        local distance = runtimeDistanceToInfo(tradePost, { pawn = targetTrader })
        if fallbackPost == nil or distance < (fallbackDistance or distance + 1) then
          fallbackPost, fallbackPersonality, fallbackDistance = tradePost, personality, distance
        end
        if traderPersonalityMatchesHint(personality, hint) and (bestPost == nil or distance < (bestDistance or distance + 1)) then
          bestPost, bestPersonality, bestDistance = tradePost, personality, distance
        end
      end
    end
  end
  if bestPost ~= nil then return bestPost, bestPersonality, "tradepost-marker:hint:" .. tostring(hint) end
  if fallbackPost ~= nil then return fallbackPost, fallbackPersonality, "tradepost-marker:fallback" end
  return nil, nil, "tradepost-marker:not-found"
end

function objectImportTextValue(obj)
  if obj == nil or not isValidObject(obj) then return "" end
  local okPath, path = pcall(function() return obj:GetPathName() end)
  if okPath and path ~= nil and tostring(path) ~= "" then return tostring(path) end
  local full = objectFullName(obj)
  local objectPath = tostring(full or ""):match("%S+%s+(.+)$")
  return tostring(objectPath or full or "")
end

function findRuntimePropertyInClassTree(cls, propertyName)
  local current = cls
  local depth = 0
  while current ~= nil and isValidObject(current) and depth < 24 do
    local okReflection, reflection = pcall(function() return current:Reflection() end)
    if okReflection and reflection ~= nil then
      local okProp, prop = pcall(function() return reflection:GetProperty(propertyName) end)
      if okProp and prop ~= nil then
        local okValid, valid = pcall(function() return prop:IsValid() end)
        if not okValid or valid == true then return prop, "class-tree:" .. objectFullName(current) end
      end
    end
    local okSuper, super = pcall(function() return current:GetSuperStruct() end)
    if not okSuper or super == nil or not isValidObject(super) then break end
    current = super
    depth = depth + 1
  end
  return nil, "property missing " .. tostring(propertyName)
end

function runtimePropertyName(property)
  if property == nil then return "" end
  local okFName, fname = pcall(function() return property:GetFName() end)
  if okFName and fname ~= nil then
    local okName, name = pcall(function() return fname:ToString() end)
    if okName and name ~= nil and tostring(name) ~= "" then return tostring(name) end
    if type(fname) ~= "userdata" and tostring(fname) ~= "" then return tostring(fname) end
  end
  local okFull, full = pcall(function() return property:GetFullName() end)
  if okFull and full ~= nil then
    local name = tostring(full):match("([^%s%.:]+)$")
    if name ~= nil and name ~= "" then return name end
  end
  return ""
end

function runtimePropertyOffset(property)
  if property == nil then return "" end
  local okOffset, offset = pcall(function() return property:GetOffset_Internal() end)
  if okOffset and tonumber(offset) ~= nil then return string.format("0x%X", tonumber(offset)) end
  return ""
end

function findRuntimePropertyByForEach(cls, propertyName)
  local current = cls
  local depth = 0
  local errors = {}
  while current ~= nil and isValidObject(current) and depth < 24 do
    local found = nil
    local okForEach, errForEach = pcall(function()
      if current.ForEachProperty == nil then return end
      current:ForEachProperty(function(property)
        if runtimePropertyName(property) == tostring(propertyName) then
          found = property
          return true
        end
      end)
    end)
    if okForEach and found ~= nil then
      local okValid, valid = pcall(function() return found:IsValid() end)
      if not okValid or valid == true then
        local offset = runtimePropertyOffset(found)
        local route = "class-foreach:" .. objectFullName(current)
        if offset ~= "" then route = route .. "@" .. offset end
        return found, route
      end
    elseif not okForEach then
      table.insert(errors, objectFullName(current) .. ":" .. tostring(errForEach))
    end
    local okSuper, super = pcall(function() return current:GetSuperStruct() end)
    if not okSuper or super == nil or not isValidObject(super) then break end
    current = super
    depth = depth + 1
  end
  if #errors > 0 then return nil, "ForEachProperty missing " .. tostring(propertyName) .. ": " .. table.concat(errors, " | ") end
  return nil, "ForEachProperty missing " .. tostring(propertyName)
end

function findRuntimePropertyOnObject(obj, propertyName)
  if obj == nil or not isValidObject(obj) then return nil, "object missing" end
  local okReflection, reflection = pcall(function() return obj:Reflection() end)
  if okReflection and reflection ~= nil then
    local okProp, prop = pcall(function() return reflection:GetProperty(propertyName) end)
    if okProp and prop ~= nil then
      local okValid, valid = pcall(function() return prop:IsValid() end)
      if not okValid or valid == true then return prop, "object-reflection:" .. objectFullName(obj) end
    end
  end
  return nil, "object reflection property missing " .. tostring(propertyName)
end

function setRuntimeObjectPropertyViaReflection(obj, propertyName, value)
  if obj == nil or not isValidObject(obj) then return false, "object missing" end
  if value == nil or not isValidObject(value) then return false, "value missing" end
  local okClass, cls = pcall(function() return obj:GetClass() end)
  if not okClass or cls == nil or not isValidObject(cls) then return false, "class missing: " .. tostring(cls) end
  local prop, propRoute = findRuntimePropertyOnObject(obj, propertyName)
  if prop == nil then prop, propRoute = findRuntimePropertyInClassTree(cls, propertyName) end
  if prop == nil then prop, propRoute = findRuntimePropertyByForEach(cls, propertyName) end
  if prop == nil then return false, tostring(propRoute or "property missing") end
  local okPtr, ptr = pcall(function() return prop:ContainerPtrToValuePtr(obj, 0) end)
  if not okPtr or ptr == nil then return false, "value ptr missing " .. tostring(propertyName) .. ": " .. tostring(ptr) end
  local text = objectImportTextValue(value)
  if text == "" then return false, "import text empty" end
  local okImport, errImport = pcall(function() return prop:ImportText(text, ptr, 0, obj) end)
  if okImport then return true, "ImportText(" .. tostring(propertyName) .. ") via " .. tostring(propRoute) .. "=" .. text end
  return false, tostring(errImport)
end

function addRuntimeArrayObject(arrayObject, value)
  local attempts = {}
  if arrayObject == nil then return false, "array missing", attempts end
  local beforeCount = nil
  local okCount, count = pcall(function() return arrayObject:GetArrayNum() end)
  if okCount and tonumber(count) ~= nil then beforeCount = tonumber(count) end
  if beforeCount ~= nil then
    local okIndex, errIndex = pcall(function() arrayObject[beforeCount + 1] = value end)
    table.insert(attempts, "index[" .. tostring(beforeCount + 1) .. "]=" .. (okIndex and "ok" or tostring(errIndex)))
    if okIndex then
      local okAfter, afterCount = pcall(function() return arrayObject:GetArrayNum() end)
      if okAfter and tonumber(afterCount) ~= nil and tonumber(afterCount) > beforeCount then
        return true, "index-resize", attempts
      end
    end
  end
  for _, method in ipairs({ "AddUnique", "Add", "Emplace", "Push" }) do
    local okAdd, errAdd = safeCall(arrayObject, method, value)
    table.insert(attempts, tostring(method) .. "=" .. (okAdd and "ok" or tostring(errAdd)))
    if okAdd then return true, method, attempts end
  end
  return false, "no add method accepted", attempts
end

function runtimeArrayContainsObject(arrayObject, value, maxItems)
  if arrayObject == nil or value == nil or not isValidObject(value) then return false, "missing" end
  local valueKey = objectKey(value)
  if valueKey == "" then return false, "value key missing" end
  local count, items, method = runtimeArrayCount(arrayObject, maxItems or 64)
  for _, item in ipairs(items or {}) do
    local obj = runtimeCollectionUnwrap(item)
    if obj ~= nil and isValidObject(obj) and objectKey(obj) == valueKey then
      return true, "present count=" .. tostring(count or 0) .. " via " .. tostring(method or "")
    end
  end
  return false, "absent count=" .. tostring(count or 0) .. " via " .. tostring(method or "")
end

function addRuntimeArrayObjectUnique(arrayObject, value, maxItems)
  local attempts = {}
  local present, presentDetail = runtimeArrayContainsObject(arrayObject, value, maxItems)
  table.insert(attempts, "contains=" .. tostring(present) .. ":" .. tostring(presentDetail))
  if present then return true, "already-present", attempts end
  local okAdd, route, addAttempts = addRuntimeArrayObject(arrayObject, value)
  for _, attempt in ipairs(addAttempts or {}) do table.insert(attempts, tostring(attempt)) end
  return okAdd, route, attempts
end

function registerSummonedTraderWithTradePost(actor, tradePost)
  local attempts = {}
  if actor == nil or not isValidObject(actor) then return false, "trader missing", attempts end
  if tradePost == nil or not isValidObject(tradePost) then return false, "tradepost missing", attempts end
  if not configBool("bridge-safety", { "AllowUnsafeTraderRuntimeRegistration", "allowUnsafeTraderRuntimeRegistration" }, false) then
    table.insert(attempts, "unsafe direct _tradeOutpostBuilding/_spawnedTraders mutation blocked")
    return false, "unsafe runtime trader registration blocked; use registered TradePost relocation route", attempts
  end
  local okOutpost, errOutpost = pcall(function() actor._tradeOutpostBuilding = tradePost end)
  table.insert(attempts, "_tradeOutpostBuilding=" .. (okOutpost and "ok" or tostring(errOutpost)))
  local okOutpost2, errOutpost2 = pcall(function() actor.TradeOutpostBuilding = tradePost end)
  table.insert(attempts, "TradeOutpostBuilding=" .. (okOutpost2 and "ok" or tostring(errOutpost2)))
  local okOriginalLocation, errOriginalLocation = pcall(function()
    local x, y, z = vectorOf(actor)
    actor._originalLocation = { X = x, Y = y, Z = z }
  end)
  table.insert(attempts, "_originalLocation=current=" .. (okOriginalLocation and "ok" or tostring(errOriginalLocation)))
  local okRepOutpost, errRepOutpost = safeCall(actor, "OnRep_TradeOutpostBuilding")
  table.insert(attempts, "OnRep_TradeOutpostBuilding=" .. (okRepOutpost and "ok" or tostring(errRepOutpost)))
  local spawnedTraders = firstProp(tradePost, { "_spawnedTraders", "SpawnedTraders" })
  local okTraders, routeTraders, attemptsTraders = addRuntimeArrayObject(spawnedTraders, actor)
  table.insert(attempts, "_spawnedTraders." .. tostring(routeTraders) .. "=" .. tostring(okTraders))
  for _, attempt in ipairs(attemptsTraders or {}) do table.insert(attempts, "_spawnedTraders." .. attempt) end
  local spawnedSedentary = firstProp(tradePost, { "_spawnedSedentaryNPCs", "SpawnedSedentaryNPCs" })
  local okSedentary, routeSedentary, attemptsSedentary = addRuntimeArrayObject(spawnedSedentary, actor)
  table.insert(attempts, "_spawnedSedentaryNPCs." .. tostring(routeSedentary) .. "=" .. tostring(okSedentary))
  for _, attempt in ipairs(attemptsSedentary or {}) do table.insert(attempts, "_spawnedSedentaryNPCs." .. attempt) end
  local assigned = firstProp(actor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" })
  local assignedOk = assigned ~= nil and isValidObject(assigned) and objectKey(assigned) == objectKey(tradePost)
  local okRep, errRep = safeCall(actor, "ForceNetUpdate")
  table.insert(attempts, "ForceNetUpdate=" .. (okRep and "ok" or tostring(errRep)))
  return assignedOk or okTraders or okSedentary, "tradepost=" .. objectFullName(tradePost), attempts
end

function bankerMinigameClass(actor)
  local value = runtimeCollectionUnwrap(firstProp(actor, { "_bankMinigameClass", "BankMinigameClass", "bankMinigameClass" }))
  if value == nil then return nil end
  if type(value) ~= "userdata" then return value end
  if isValidObject(value) then return value end
  return nil
end

function tradePostHasBankerMarker(tradePost)
  local markers = firstProp(tradePost, { "_sedentaryNPCMarkers", "SedentaryNPCMarkers" })
  local _, items = runtimeArrayCount(markers, 16)
  for _, marker in ipairs(items or {}) do
    local npcClass = runtimeCollectionUnwrap(firstProp(marker, { "SedentaryNPCClass" }))
    local text = (objectFullName(npcClass) .. " " .. tostring(npcClass or "")):lower()
    if text:find("banker", 1, true) ~= nil or text:find("bp_banker", 1, true) ~= nil then return true end
  end
  return false
end

function findBankTradePostForBanker(targetActor)
  local best, bestDistance = nil, nil
  local fallback, fallbackDistance = nil, nil
  for _, tradePost in ipairs(findAll(tradePostClassesForLookup())) do
    local full = objectFullName(tradePost):lower()
    local distance = runtimeDistanceToInfo(tradePost, { pawn = targetActor })
    if fallback == nil or distance < (fallbackDistance or distance + 1) then
      fallback, fallbackDistance = tradePost, distance
    end
    if full:find("bank", 1, true) ~= nil or tradePostHasBankerMarker(tradePost) then
      if best == nil or distance < (bestDistance or distance + 1) then
        best, bestDistance = tradePost, distance
      end
    end
  end
  if best ~= nil then return best, "bank-tradepost" end
  return fallback, fallback ~= nil and "fallback-nearest-tradepost" or "not-found"
end

function findBankerDonor(targetActor)
  local targetKey = objectKey(targetActor)
  for _, banker in ipairs(findAll({ "Banker", "BP_Banker01_C" })) do
    if objectKey(banker) ~= targetKey then
      local minigameClass = bankerMinigameClass(banker)
      if minigameClass ~= nil then return banker, minigameClass, "runtime-banker" end
    end
  end
  return nil, nil, "not-found"
end

function registerSummonedSedentaryWithTradePost(actor, tradePost)
  local attempts = {}
  if actor == nil or not isValidObject(actor) then return false, "sedentary npc missing", attempts end
  if tradePost == nil or not isValidObject(tradePost) then return false, "tradepost missing", attempts end
  if not configBool("bridge-safety", { "AllowUnsafeTraderRuntimeRegistration", "allowUnsafeTraderRuntimeRegistration" }, false) then
    table.insert(attempts, "unsafe direct _tradeOutpostBuilding/_spawnedSedentaryNPCs mutation blocked")
    return false, "unsafe runtime sedentary registration blocked; use registered TradePost relocation route", attempts
  end
  local okOutpost, errOutpost = pcall(function() actor._tradeOutpostBuilding = tradePost end)
  table.insert(attempts, "_tradeOutpostBuilding=" .. (okOutpost and "ok" or tostring(errOutpost)))
  local okOutpost2, errOutpost2 = pcall(function() actor.TradeOutpostBuilding = tradePost end)
  table.insert(attempts, "TradeOutpostBuilding=" .. (okOutpost2 and "ok" or tostring(errOutpost2)))
  local okOriginalLocation, errOriginalLocation = pcall(function()
    local x, y, z = vectorOf(actor)
    actor._originalLocation = { X = x, Y = y, Z = z }
  end)
  table.insert(attempts, "_originalLocation=current=" .. (okOriginalLocation and "ok" or tostring(errOriginalLocation)))
  local okRepOutpost, errRepOutpost = safeCall(actor, "OnRep_TradeOutpostBuilding")
  table.insert(attempts, "OnRep_TradeOutpostBuilding=" .. (okRepOutpost and "ok" or tostring(errRepOutpost)))
  local spawnedSedentary = firstProp(tradePost, { "_spawnedSedentaryNPCs", "SpawnedSedentaryNPCs" })
  local okSedentary, routeSedentary, attemptsSedentary = addRuntimeArrayObject(spawnedSedentary, actor)
  table.insert(attempts, "_spawnedSedentaryNPCs." .. tostring(routeSedentary) .. "=" .. tostring(okSedentary))
  for _, attempt in ipairs(attemptsSedentary or {}) do table.insert(attempts, "_spawnedSedentaryNPCs." .. attempt) end
  local assigned = firstProp(actor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" })
  local assignedOk = assigned ~= nil and isValidObject(assigned) and objectKey(assigned) == objectKey(tradePost)
  local okRep, errRep = safeCall(actor, "ForceNetUpdate")
  table.insert(attempts, "ForceNetUpdate=" .. (okRep and "ok" or tostring(errRep)))
  return assignedOk or okSedentary, "tradepost=" .. objectFullName(tradePost), attempts
end

function tradePostOutpostManagerAssigned(actor)
  local attempts = {}
  if actor == nil or not isValidObject(actor) then return false, "tradepost missing", attempts end
  local actorKey = objectKey(actor)
  local managers = findAllTradeOutpostManagers()
  table.insert(attempts, "TradeOutpostManager.count=" .. tostring(#(managers or {})))
  for _, manager in ipairs(managers or {}) do
    local assignedPosts = firstProp(manager, { "_assignedTradePosts", "AssignedTradePosts" })
    local count, items, method = runtimeArrayCount(assignedPosts, 48)
    table.insert(attempts, objectFullName(manager) .. "._assignedTradePosts.count=" .. tostring(count or 0) .. " via " .. tostring(method or ""))
    for _, post in ipairs(items or {}) do
      local postObj = runtimeCollectionUnwrap(post)
      if postObj ~= nil and isValidObject(postObj) and objectKey(postObj) == actorKey then
        return true, "assigned to " .. objectFullName(manager), attempts
      end
    end
  end
  return false, "not assigned to any TradeOutpostManager", attempts
end

function initializeSummonedTradePostActor(actor, actorClass)
  local attempts = {}
  if actor == nil or not isValidObject(actor) then return false, "runtime tradepost missing", attempts end
  local entry = actorCatalogLookup(actorClass)
  if not actorCatalogIsTradePostLike(actorClass, entry) then return true, "not-tradepost", attempts end
  local markers = firstProp(actor, { "_traderMarkers", "TraderMarkers" })
  local markerCount, markerItems = runtimeArrayCount(markers, 8)
  table.insert(attempts, "_traderMarkers.count=" .. tostring(markerCount or 0))
  local personalityCount = 0
  local npcClassCount = 0
  for _, marker in ipairs(markerItems or {}) do
    local personality = tradePostMarkerPersonality(marker)
    if personality ~= nil and isValidObject(personality) then personalityCount = personalityCount + 1 end
    local npcClass = runtimeCollectionUnwrap(firstProp(marker, { "SedentaryNPCClass" }))
    if npcClass ~= nil and tostring(npcClass) ~= "" then npcClassCount = npcClassCount + 1 end
  end
  table.insert(attempts, "_traderMarkers.personalities=" .. tostring(personalityCount))
  table.insert(attempts, "_traderMarkers.npcClasses=" .. tostring(npcClassCount))
  local spawnedTraders = firstProp(actor, { "_spawnedTraders", "SpawnedTraders" })
  local spawnedCount = runtimeArrayCount(spawnedTraders, 8)
  table.insert(attempts, "_spawnedTraders.count=" .. tostring(spawnedCount or 0))
  local spawnedSedentary = firstProp(actor, { "_spawnedSedentaryNPCs", "SpawnedSedentaryNPCs" })
  local spawnedSedentaryCount = runtimeArrayCount(spawnedSedentary, 8)
  table.insert(attempts, "_spawnedSedentaryNPCs.count=" .. tostring(spawnedSedentaryCount or 0))
  local okRep, errRep = safeCall(actor, "SetReplicates", true)
  table.insert(attempts, "SetReplicates=" .. (okRep and "ok" or tostring(errRep)))
  local okForce, errForce = safeCall(actor, "ForceNetUpdate")
  table.insert(attempts, "ForceNetUpdate=" .. (okForce and "ok" or tostring(errForce)))
  local managerAssigned, managerDetail, managerAttempts = tradePostOutpostManagerAssigned(actor)
  for _, attempt in ipairs(managerAttempts or {}) do table.insert(attempts, "manager." .. attempt) end
  if (markerCount or 0) <= 0 then
    return false, "TradePost создан, но у него нет _traderMarkers; это не полноценный outpost/trader actor.", attempts
  end
  if personalityCount <= 0 then
    return false, "TradePost создан, но маркеры не содержат TraderPersonality; экономика SCUM не сможет привязать товары.", attempts
  end
  if not managerAssigned then
    return false, "TradePost actor имеет marker data, но не назначен в TradeOutpostManager/economy; такой spawned trader не будет функциональным или persistent: " .. tostring(managerDetail), attempts
  end
  return true, "TradePost actor создан с native marker data и найден в TradeOutpostManager; spawnedTraders=" .. tostring(spawnedCount or 0) .. ", personalities=" .. tostring(personalityCount), attempts
end

function initializeSummonedTraderActor(actor, actorClass)
  local attempts = {}
  if actor == nil or not isValidObject(actor) then return false, "runtime trader missing", attempts end
  local entry = actorCatalogLookup(actorClass)
  if not actorCatalogIsActualTraderActor(actorClass, entry) then return true, "not-trader", attempts end
  local existingPersonality = traderPersonalityObject(actor)
  if existingPersonality ~= nil and isValidObject(existingPersonality) then
    table.insert(attempts, "personality already present=" .. objectFullName(existingPersonality))
  end
  local donor = nil
  local personality = existingPersonality
  local route = personality ~= nil and isValidObject(personality) and "existing-personality" or ""
  if personality == nil or not isValidObject(personality) then
    local markerPost, markerPersonality, markerRoute = findTraderPersonalityFromTradePostMarker(actorClass, actor)
    if markerPersonality ~= nil and isValidObject(markerPersonality) then
      donor, personality, route = markerPost, markerPersonality, markerRoute
    end
  end
  local tradePost = firstProp(actor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" }) or firstProp(donor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" })
  if personality == nil or not isValidObject(personality) then
    donor, personality, route = findTraderPersonalityDonor(actorClass, actor)
    tradePost = firstProp(actor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" }) or firstProp(donor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" })
  end
  if tradePost == nil or not isValidObject(tradePost) then
    local markerPost, markerPersonality, markerRoute = findTraderPersonalityFromTradePostMarker(actorClass, actor)
    if markerPost ~= nil and isValidObject(markerPost) and markerPersonality ~= nil and isValidObject(markerPersonality) then
      tradePost, donor, personality, route = markerPost, markerPost, markerPersonality, markerRoute
      table.insert(attempts, "tradepost recovered from marker route=" .. tostring(markerRoute))
    end
  end
  if personality == nil or not isValidObject(personality) then
    table.insert(attempts, "no donor personality found")
    return false, "у созданного торговца нет TraderPersonality, а donor не найден", attempts
  end
  if existingPersonality == nil or not isValidObject(existingPersonality) then
    local okReflect, detailReflect = setRuntimeObjectPropertyViaReflection(actor, "_traderPersonalityDataAsset", personality)
    table.insert(attempts, "_traderPersonalityDataAsset.ImportText=" .. (okReflect and "ok:" or "fail:") .. tostring(detailReflect))
    table.insert(attempts, "_traderPersonalityDataAsset.direct-set=skipped-weakobjectproperty")
    table.insert(attempts, "TraderPersonalityDataAsset.direct-set=skipped-weakobjectproperty")
    if not okReflect then
      return false, "WeakObjectProperty _traderPersonalityDataAsset не установлен через reflection; direct-set отключён как unsafe для UE4SS", attempts
    end
  end
  local registered, registerDetail, registerAttempts = registerSummonedTraderWithTradePost(actor, tradePost)
  for _, attempt in ipairs(registerAttempts or {}) do table.insert(attempts, "tradepost." .. attempt) end
  local okRep, errRep = safeCall(actor, "SetReplicates", true)
  table.insert(attempts, "SetReplicates=" .. (okRep and "ok" or tostring(errRep)))
  local okForce, errForce = safeCall(actor, "ForceNetUpdate")
  table.insert(attempts, "ForceNetUpdate=" .. (okForce and "ok" or tostring(errForce)))
  local afterPersonality = traderPersonalityObject(actor)
  if afterPersonality ~= nil and isValidObject(afterPersonality) then
    if registered then
      return true, "TraderPersonality/tradepost registered from " .. objectFullName(donor) .. " via " .. tostring(route) .. "; persistentId=" .. tostring(traderPersonalityRuntimeId(afterPersonality)) .. "; " .. tostring(registerDetail), attempts
    end
    return false, "TraderPersonality есть, но tradepost registration не сработал: persistentId=" .. tostring(traderPersonalityRuntimeId(afterPersonality)) .. "; " .. tostring(registerDetail), attempts
  end
  return false, "TraderPersonality copy did not stick", attempts
end

function initializeSummonedBankerActor(actor, actorClass)
  local attempts = {}
  if actor == nil or not isValidObject(actor) then return false, "runtime banker missing", attempts end
  local entry = actorCatalogLookup(actorClass)
  if not actorCatalogIsBankerActor(actorClass, entry) then return true, "not-banker", attempts end
  local minigameClass = bankerMinigameClass(actor)
  if minigameClass ~= nil then
    table.insert(attempts, "_bankMinigameClass already present=" .. objectFullName(minigameClass))
  else
    local donor, donorMinigame, donorRoute = findBankerDonor(actor)
    table.insert(attempts, "banker donor=" .. tostring(donorRoute))
    if donorMinigame ~= nil then
      local okReflect, detailReflect = setRuntimeObjectPropertyViaReflection(actor, "_bankMinigameClass", donorMinigame)
      table.insert(attempts, "_bankMinigameClass.ImportText=" .. (okReflect and "ok:" or "fail:") .. tostring(detailReflect))
      table.insert(attempts, "_bankMinigameClass.direct-set=skipped-reflection-only")
      if not okReflect then
        return false, "ClassProperty _bankMinigameClass не установлен через reflection; direct-set отключён как unsafe", attempts
      end
      minigameClass = bankerMinigameClass(actor)
    end
  end
  local tradePost = firstProp(actor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" })
  if tradePost == nil or not isValidObject(tradePost) then
    local route = ""
    tradePost, route = findBankTradePostForBanker(actor)
    table.insert(attempts, "tradepost lookup=" .. tostring(route))
  end
  local registered, registerDetail, registerAttempts = registerSummonedSedentaryWithTradePost(actor, tradePost)
  for _, attempt in ipairs(registerAttempts or {}) do table.insert(attempts, "tradepost." .. attempt) end
  local okRep, errRep = safeCall(actor, "SetReplicates", true)
  table.insert(attempts, "SetReplicates=" .. (okRep and "ok" or tostring(errRep)))
  local okForce, errForce = safeCall(actor, "ForceNetUpdate")
  table.insert(attempts, "ForceNetUpdate=" .. (okForce and "ok" or tostring(errForce)))
  local afterMinigame = bankerMinigameClass(actor)
  if afterMinigame == nil then
    return false, "Banker создан, но _bankMinigameClass не найден; банковская UI-логика не запустится.", attempts
  end
  if not registered then
    return false, "Banker имеет bank minigame, но не привязан к TradeOutpostBuilding: " .. tostring(registerDetail), attempts
  end
  return true, "Banker зарегистрирован как SedentaryNPC у bank/outpost; minigame=" .. objectFullName(afterMinigame) .. "; " .. tostring(registerDetail), attempts
end

function traderRuntimeActorJson(trader, info)
  local x, y, z = vectorOf(trader)
  local personality = traderPersonalityObject(trader)
  local fields = {
    runtimePropJson(trader, "_traderPersonalityDataAsset"),
    runtimePropJson(trader, "_assignedTradePost"),
    runtimePropJson(trader, "_bankMinigameClass"),
    runtimePropJson(trader, "_servicedVehicle")
  }
  return '{"actor":' .. nativeProbeObjectJson("trader", trader, "runtime", {}) ..
    ',"distance":' .. tostring(math.floor(runtimeDistanceToInfo(trader, info))) ..
    ',"location":{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. '}' ..
    ',"traderPersistentId":' .. js(traderPersonalityRuntimeId(personality)) ..
    ',"personality":' .. nativeProbeObjectJson("personality", personality, "_traderPersonalityDataAsset", {}) ..
    ',"fields":{' .. table.concat(fields, ",") .. '}}'
end

function tradePostRuntimeJson(tradePost, info)
  local x, y, z = vectorOf(tradePost)
  return '{"actor":' .. nativeProbeObjectJson("tradePost", tradePost, "runtime", {}) ..
    ',"distance":' .. tostring(math.floor(runtimeDistanceToInfo(tradePost, info))) ..
    ',"location":{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. '}' ..
    ',"collections":{' ..
      runtimeCollectionJson(tradePost, "_traderMarkers", 6) .. ',' ..
      runtimeCollectionJson(tradePost, "_locationMarkers", 6) .. ',' ..
      runtimeCollectionJson(tradePost, "_spawnedTraders", 8) .. ',' ..
      runtimeCollectionJson(tradePost, "_spawnedDepots", 6) ..
    '}}'
end

function tradeOutpostManagerRuntimeJson(manager)
  local description = runtimeCollectionUnwrap(firstProp(manager, { "_outpostDescription", "OutpostDescription" }))
  return '{"manager":' .. nativeProbeObjectJson("tradeOutpostManager", manager, "runtime", {}) ..
    ',"outpostDescription":' .. nativeProbeObjectJson("outpostDescription", description, "_outpostDescription", {}) ..
    ',"outpostPersistentId":' .. js(tradeOutpostDescriptionRuntimeId(description)) ..
    ',"startingProsperityLevel":' .. runtimeValueJson(firstProp(manager, { "_startingProsperityLevel", "StartingProsperityLevel" })) ..
    ',"collections":{' ..
      runtimeCollectionJson(manager, "_assignedTradePosts", 12) .. ',' ..
      runtimeCollectionJson(manager, "_otherAssignedTradeOutpostBuildings", 12) ..
    '}}'
end

function debugTraderRuntimeProbe(steamId, name, runtimeKey, maxCount)
  local info = resolvePlayerInfo(steamId, name, nil, runtimeKey) or findPlayer(steamId, name, runtimeKey)
  if not scanFeatureEnabled({ "AllowProbeRuntimeObjectScan", "allowProbeRuntimeObjectScan" }, false) then
    local economyManager, economyRoute = findFirst({ "BP_EconomyManager_C", "BP_ConZEconomyManager_C", "ConZEconomyManager", "ConZEconomyManager_C" })
    local data = '{"player":' .. nativeProbePlayerJson(info) ..
      ',"economyManager":' .. nativeProbeObjectJson("economyManager", economyManager, economyRoute or "", {}) ..
      ',"traderCount":null' ..
      ',"tradePostCount":null' ..
      ',"tradeOutpostManagerCount":null' ..
      ',"skipped":true' ..
      ',"note":"Runtime trader scan отключён bridge-safety.AllowProbeRuntimeObjectScan=false, чтобы не стопорить game thread; для анализа включать только в maintenance-окне."}'
    appendActionEvent("debug_trader_runtime_probe", true, info, "Trader runtime-probe пропущен безопасно: runtime scan отключён.", data)
    return true, "Trader runtime-probe пропущен безопасно: runtime scan отключён.", data
  end
  local traders = findAll({ "Trader", "Doctor", "Mechanic", "Banker", "BP_Banker01_C", "BP_Barber_01_C", "BP_Bartender_01_C", "BP_ArmsDealer_01_C", "BP_General_Goods_01_C", "BP_Harbourmaster_01_C", "BP_Doctor_01_C", "BP_Mechanic_C" })
  table.sort(traders, function(a, b) return runtimeDistanceToInfo(a, info) < runtimeDistanceToInfo(b, info) end)
  local tradePosts = findAll(tradePostClassesForLookup())
  table.sort(tradePosts, function(a, b) return runtimeDistanceToInfo(a, info) < runtimeDistanceToInfo(b, info) end)
  local tradeOutpostManagers = findAllTradeOutpostManagers()
  local limit = math.max(1, math.min(tonumber(maxCount) or 12, 40))
  local traderRows = {}
  for i, trader in ipairs(traders or {}) do
    if i > limit then break end
    table.insert(traderRows, traderRuntimeActorJson(trader, info))
  end
  local tradePostRows = {}
  for i, tradePost in ipairs(tradePosts or {}) do
    if i > limit then break end
    table.insert(tradePostRows, tradePostRuntimeJson(tradePost, info))
  end
  local managerRows = {}
  for i, manager in ipairs(tradeOutpostManagers or {}) do
    if i > limit then break end
    table.insert(managerRows, tradeOutpostManagerRuntimeJson(manager))
  end
  local economyManager, economyRoute = findFirst({ "BP_EconomyManager_C", "BP_ConZEconomyManager_C", "ConZEconomyManager", "ConZEconomyManager_C" })
  local data = '{"player":' .. nativeProbePlayerJson(info) ..
    ',"economyManager":' .. nativeProbeObjectJson("economyManager", economyManager, economyRoute or "", {}) ..
    ',"traderCount":' .. tostring(#(traders or {})) ..
    ',"tradePostCount":' .. tostring(#(tradePosts or {})) ..
    ',"tradeOutpostManagerCount":' .. tostring(#(tradeOutpostManagers or {})) ..
    ',"traders":[' .. table.concat(traderRows, ",") .. ']' ..
    ',"tradePosts":[' .. table.concat(tradePostRows, ",") .. ']' ..
    ',"tradeOutpostManagers":[' .. table.concat(managerRows, ",") .. ']' ..
    ',"note":"Функциональный торговец должен иметь _traderPersonalityDataAsset и быть связан с economy/tradepost данными; один Summon создаёт только NPC-куклу."}'
  appendActionEvent("debug_trader_runtime_probe", true, info, "Trader runtime-probe выполнен.", data)
  return true, "Trader runtime-probe выполнен.", data
end

function nativeProbeCollectionJson(label, obj)
  if obj == nil then return '{"label":' .. js(label) .. ',"present":false}' end
  return '{"label":' .. js(label) ..
    ',"present":true' ..
    ',"kind":' .. js(type(obj)) .. '}'
end

function nativeProbeLoadCandidates(spec, defaultRoot, defaultName)
  local raw = tostring(spec or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if raw == "" then raw = tostring(defaultName or "") end
  local candidates = {}
  local seen = {}
  local function add(value)
    value = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if value == "" then return end
    if seen[value:lower()] then return end
    seen[value:lower()] = true
    table.insert(candidates, value)
  end
  local function objectPathFromPackage(packagePath, name)
    if packagePath == "" then return "" end
    local objectName = tostring(name or "") ~= "" and tostring(name) or (packagePath:match("([^/]+)$") or "")
    return packagePath .. "." .. objectName
  end
  local root = tostring(defaultRoot or ""):gsub("/$", "")
  if raw:sub(1, 6) == "/Game/" then
    local packagePath = raw:gsub("%.[^%.\\/]+$", "")
    local objectName = raw:match("%.([^%.\\/]+)$") or raw:match("([^/]+)$") or tostring(defaultName or "")
    if raw:find("%.[^%.\\/]+$") then add(raw) end
    add(objectPathFromPackage(packagePath, objectName))
  else
    raw = raw:gsub("%.uasset$", ""):gsub("^BlueprintGeneratedClass'", ""):gsub("^Class'", ""):gsub("'$", "")
    local name = raw:match("([^/%.]+)$") or raw
    local packagePath = root ~= "" and (root .. "/" .. name) or raw
    add(objectPathFromPackage(packagePath, name))
    if name:sub(-2) ~= "_C" then add(objectPathFromPackage(packagePath, name .. "_C")) end
  end
  return candidates
end

function nativeProbeLoadObject(spec, defaultRoot, defaultName, allowLoadAsset)
  local attempts = {}
  local candidates = nativeProbeLoadCandidates(spec, defaultRoot, defaultName)
  for _, candidate in ipairs(candidates) do
    local okFind, found = pcall(function() return StaticFindObject(candidate) end)
    table.insert(attempts, "StaticFindObject(" .. tostring(candidate) .. ")=" .. (okFind and (isValidObject(found) and "ok" or "nil") or tostring(found)))
    if okFind and found ~= nil and isValidObject(found) then return found, "StaticFindObject:" .. tostring(candidate), attempts, candidates end
  end

  if allowLoadAsset == true then
    local loadedPackages = {}
    for _, candidate in ipairs(candidates or {}) do
      local packagePath = nativePlaceablePackagePath(candidate)
      local loadValues = { packagePath, candidate }
      for _, loadValue in ipairs(loadValues) do
        if loadValue ~= "" and loadValue:sub(1, 6) == "/Game/" and not loadedPackages[loadValue:lower()] then
          loadedPackages[loadValue:lower()] = true
          local okLoad, loaded = pcall(function() return LoadAsset(loadValue) end)
          table.insert(attempts, "LoadAsset(" .. tostring(loadValue) .. ")=" .. (okLoad and (isValidObject(loaded) and "ok" or "nil") or tostring(loaded)))
          if okLoad and loaded ~= nil and isValidObject(loaded) then
            for _, retryCandidate in ipairs(candidates or {}) do
              local okFind, found = pcall(function() return StaticFindObject(retryCandidate) end)
              table.insert(attempts, "post StaticFindObject(" .. tostring(retryCandidate) .. ")=" .. (okFind and (isValidObject(found) and "ok" or "nil") or tostring(found)))
              if okFind and found ~= nil and isValidObject(found) then return found, "LoadAsset+StaticFindObject:" .. tostring(retryCandidate), attempts, candidates end
            end
            return loaded, "LoadAsset:" .. tostring(loadValue), attempts, candidates
          end
        end
      end
      if packagePath ~= "" and packagePath:sub(1, 6) == "/Game/" and not loadedPackages[(packagePath .. "_C"):lower()] then
        loadedPackages[(packagePath .. "_C"):lower()] = true
        local generatedClassPath = packagePath .. "_C"
        local okLoad, loaded = pcall(function() return LoadAsset(generatedClassPath) end)
        table.insert(attempts, "LoadAsset(" .. tostring(generatedClassPath) .. ")=" .. (okLoad and (isValidObject(loaded) and "ok" or "nil") or tostring(loaded)))
        if okLoad and loaded ~= nil and isValidObject(loaded) then
          for _, retryCandidate in ipairs(candidates or {}) do
            local okFind, found = pcall(function() return StaticFindObject(retryCandidate) end)
            table.insert(attempts, "post StaticFindObject(" .. tostring(retryCandidate) .. ")=" .. (okFind and (isValidObject(found) and "ok" or "nil") or tostring(found)))
            if okFind and found ~= nil and isValidObject(found) then return found, "LoadAsset+StaticFindObject:" .. tostring(retryCandidate), attempts, candidates end
          end
          return loaded, "LoadAsset:" .. tostring(generatedClassPath), attempts, candidates
        end
      end
    end
  end

  return nil, "not-loaded-static-only", attempts, candidates
end

