function nativeBaseElementQuatFromYaw(yaw)
  local halfRadians = math.rad((tonumber(yaw) or 0) * 0.5)
  return { X = 0, Y = 0, Z = math.sin(halfRadians), W = math.cos(halfRadians) }
end

function nativeBaseElementTransform(location, yaw)
  local loc = location or { X = 0, Y = 0, Z = 0 }
  return {
    Rotation = nativeBaseElementQuatFromYaw(yaw),
    Translation = { X = tonumber(loc.X) or 0, Y = tonumber(loc.Y) or 0, Z = tonumber(loc.Z) or 0 },
    Scale3D = { X = 1, Y = 1, Z = 1 }
  }
end

function nativeBaseElementData(baseId, baseName, location, ownerUserProfileId, isOwnedByPlayer)
  local loc = location or { X = 0, Y = 0, Z = 0 }
  local size = math.max(100, math.min(configNumber("bridge-safety", { "NativeBaseElementDefaultBaseSize", "nativeBaseElementDefaultBaseSize" }, 1200), 10000))
  return {
    BaseId = tonumber(baseId) or 0,
    BaseName = tostring(baseName or ("NedjinBase_" .. tostring(baseId or 0))),
    BaseSize = { X = size, Y = size },
    BaseLocation = { X = tonumber(loc.X) or 0, Y = tonumber(loc.Y) or 0, Z = tonumber(loc.Z) or 0 },
    BaseOwnerPlayerId = tonumber(ownerUserProfileId) or 0,
    IsOwnedByPlayer = isOwnedByPlayer == true,
    BaseBoundsMin = { X = (tonumber(loc.X) or 0) - size * 0.5, Y = (tonumber(loc.Y) or 0) - size * 0.5 },
    BaseBoundsMax = { X = (tonumber(loc.X) or 0) + size * 0.5, Y = (tonumber(loc.Y) or 0) + size * 0.5 }
  }
end

function nativeBaseElementSpawnParams(quality)
  return {
    Quality = tonumber(quality) or 1.0,
    OverrideColor0 = 0,
    OverrideColor1 = 0,
    ShelterId = { Value = 0 },
    EntityId = { Value = 0 },
    OverridePattern0 = 255,
    OverridePattern1 = 255
  }
end

function nativeBaseElementNextIds()
  local now = os.time()
  local baseId = tonumber(now) or 1
  local elementId = baseId * 1000 + math.random(100, 999)
  return baseId, elementId
end

function nativeBaseElementSpawnDataJson(args, attempts, okSpawn, spawnMessage)
  local afterBaseCount, afterBaseMethod, baseManager = nativePlaceableBaseCount()
  local target = (args or {}).targetLocation or { X = 0, Y = 0, Z = 0 }
  return '{"element":' .. js((args or {}).elementSpec or "") ..
    ',"route":' .. js((args or {}).route or "") ..
    ',"baseId":' .. tostring((args or {}).baseId or 0) ..
    ',"elementId":' .. tostring((args or {}).elementId or 0) ..
    ',"ownerUserProfileId":' .. tostring((args or {}).ownerUserProfileId or 0) ..
    ',"creatorPrisonerId":' .. tostring((args or {}).creatorPrisonerId or 0) ..
    ',"beforeBaseCount":' .. tostring((args or {}).beforeBaseCount or 0) ..
    ',"afterBaseCount":' .. tostring(afterBaseCount or 0) ..
    ',"afterBaseReadMethod":' .. js(afterBaseMethod or "") ..
    ',"baseManager":' .. nativeProbeObjectJson("baseManager", baseManager, "GameMode.GetBaseManager", {}) ..
    ',"baseSnapshot":' .. nativePlaceableBaseSnapshotJson(8) ..
    ',"spawnCalled":' .. tostring(okSpawn == true) ..
    ',"spawnMessage":' .. js(spawnMessage or "") ..
    ',"target":{"x":' .. tostring(target.X or 0) .. ',"y":' .. tostring(target.Y or 0) .. ',"z":' .. tostring(target.Z or 0) .. '}' ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
end

function spawnNativeBaseElementForInfo(elementSpec, info, options)
  local absoluteLocation = (options or {}).location
  local live = info
  if absoluteLocation == nil then
    local ready, readyMessage, readyReason
    live, ready, readyMessage, readyReason = deliveryReadyInfo(info, { requireInventory = false })
    if not ready then return false, deliveryReadyMessage(readyReason) .. " (" .. tostring(readyMessage or "") .. ")", "{}" end
  else
    live = live or {}
  end
  local attempts = {}
  local baseManager, baseRoute = nativePlaceableBaseManager()
  table.insert(attempts, "baseManager=" .. tostring(baseRoute))
  if baseManager == nil or not isValidObject(baseManager) then
    return false, "BaseManager недоступен: " .. tostring(baseRoute), '{"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
  end
  local elementClass, routeName, loadAttempts, candidates = loadNativeBaseElementClass(elementSpec ~= "" and elementSpec or "BP_Base_Cabin")
  for _, attempt in ipairs(loadAttempts or {}) do table.insert(attempts, attempt) end
  if elementClass == nil or not isValidObject(elementClass) then
    return false, "BaseElement class не найден/не загружен: " .. tostring(routeName), '{"element":' .. js(elementSpec or "") .. ',"candidates":' .. stringArrayJson(candidates or {}) .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
  end
  if configBool("bridge-safety", { "AllowNativeBaseElementMulticastProbe", "allowNativeBaseElementMulticastProbe" }, false) ~= true then
    table.insert(attempts, "NetMulticast_SpawnBaseElement=blocked-by-bridge-safety")
    local message = "Native BaseElement multicast заблокирован: Lua table marshaling FTransform/FConZBaseData в SCUM портит координаты и может уронить сервер. Нужен native C++ wrapper или DB+restart route."
    local data = '{"element":' .. js(elementSpec or "") ..
      ',"route":' .. js(routeName or "") ..
      ',"blocked":true' ..
      ',"requires":"native-cpp-wrapper-or-db-restart-route"' ..
      ',"candidates":' .. stringArrayJson(candidates or {}) ..
      ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
    appendActionEvent("native_base_element_spawn", false, info, message, data)
    return false, message, data
  end

  local targetLocation = absoluteLocation or nativePlaceableTargetLocation(live, (options or {}).forwardDistance, (options or {}).liftZ)
  local targetYaw = tonumber((options or {}).yaw) or rotationYawOf(live.pc) or rotationYawOf(live.pawn) or 0
  local baseId, elementId = nativeBaseElementNextIds()
  baseId = tonumber((options or {}).baseId) or baseId
  elementId = tonumber((options or {}).elementId) or elementId
  local ownerUserProfileId = tonumber((options or {}).ownerProfileId) or tonumber(live.serverUserProfileId or live.userProfileId or live.dbId or 1) or 1
  local creatorPrisonerId = tonumber((options or {}).prisonerId) or tonumber(live.prisonerId or live.serverPrisonerId or 1) or 1
  local beforeBaseCount, beforeBaseMethod = nativePlaceableBaseCount()
  table.insert(attempts, "beforeBaseCount=" .. tostring(beforeBaseCount) .. " via " .. tostring(beforeBaseMethod))

  local transform = nativeBaseElementTransform(targetLocation, targetYaw)
  local baseData = nativeBaseElementData(baseId, "NedjinBase_" .. tostring(baseId), targetLocation, ownerUserProfileId, true)
  local params = nativeBaseElementSpawnParams((options or {}).quality)
  local dataVersion = math.max(1, math.floor(tonumber((options or {}).dataVersion) or configNumber("bridge-safety", { "NativeBaseElementDataVersion", "nativeBaseElementDataVersion" }, 1)))
  local okSpawn, spawnResult = pcall(function()
    return baseManager:NetMulticast_SpawnBaseElement(
      dataVersion,
      transform,
      baseData,
      elementClass,
      elementId,
      ownerUserProfileId,
      creatorPrisonerId,
      true,
      params)
  end)
  table.insert(attempts, "NetMulticast_SpawnBaseElement=" .. (okSpawn and "ok" or tostring(spawnResult)))
  local args = {
    elementSpec = elementSpec ~= "" and elementSpec or "BP_Base_Cabin",
    route = routeName,
    baseId = baseId,
    elementId = elementId,
    ownerUserProfileId = ownerUserProfileId,
    creatorPrisonerId = creatorPrisonerId,
    beforeBaseCount = beforeBaseCount,
    targetLocation = targetLocation
  }
  local afterBaseCount = select(1, nativePlaceableBaseCount())
  local verified = okSpawn and ((tonumber(afterBaseCount) or 0) > (tonumber(beforeBaseCount) or 0))
  local message = verified and
    "BaseElement создан через ConZBaseManager.NetMulticast_SpawnBaseElement; проверяй видимость клиентом, persistence ещё не подтверждён." or
    (okSpawn and "NetMulticast_SpawnBaseElement вызван, но BaseManager._bases не увеличился; это не подтверждённый persistent spawn." or ("NetMulticast_SpawnBaseElement не сработал: " .. tostring(spawnResult)))
  local data = nativeBaseElementSpawnDataJson(args, attempts, okSpawn, message)
  appendActionEvent("native_base_element_spawn", verified, live, message, data)
  return verified, message, data
end

function nativePlaceableRecipeLoadCandidates(recipeSpec)
  return nativeProbeLoadCandidates(
    recipeSpec,
    "/Game/ConZ_Files/Items/Crafting/Recipes/Placeables",
    "CR_Base_Block")
end

function nativePlaceablePackagePath(objectPath)
  local rawPath = tostring(objectPath or "")
  if rawPath == "" then return "" end
  local packagePath = rawPath:match("^(.+)%.([^%.\\/]+)$")
  return packagePath or rawPath
end

function loadNativePlaceableRecipe(recipeSpec)
  local attempts = {}
  local candidates = nativePlaceableRecipeLoadCandidates(recipeSpec)
  local function tryFind(candidate, label)
    local okFind, found = pcall(function() return StaticFindObject(candidate) end)
    table.insert(attempts, tostring(label or "StaticFindObject") .. "(" .. tostring(candidate) .. ")=" .. (okFind and (isValidObject(found) and "ok" or "nil") or tostring(found)))
    if okFind and found ~= nil and isValidObject(found) then return found end
    return nil
  end

  for _, candidate in ipairs(candidates or {}) do
    local found = tryFind(candidate, "StaticFindObject")
    if found ~= nil then return found, "StaticFindObject:" .. tostring(candidate), attempts, candidates end
  end

  if configBool("bridge-safety", { "AllowNativePlaceableRecipeLoadAsset", "allowNativePlaceableRecipeLoadAsset" }, true) ~= true then
    return nil, "recipe not loaded and LoadAsset disabled", attempts, candidates
  end

  local loadedPackages = {}
  for _, candidate in ipairs(candidates or {}) do
    local packagePath = nativePlaceablePackagePath(candidate)
    if packagePath ~= "" and packagePath:sub(1, 6) == "/Game/" and not loadedPackages[packagePath:lower()] then
      loadedPackages[packagePath:lower()] = true
      local okLoad, loaded = pcall(function() return LoadAsset(packagePath) end)
      table.insert(attempts, "LoadAsset(" .. tostring(packagePath) .. ")=" .. (okLoad and (isValidObject(loaded) and "ok" or "nil") or tostring(loaded)))
      if okLoad and loaded ~= nil and isValidObject(loaded) then
        for _, retryCandidate in ipairs(candidates or {}) do
          local found = tryFind(retryCandidate, "post StaticFindObject")
          if found ~= nil then return found, "LoadAsset+StaticFindObject:" .. tostring(retryCandidate), attempts, candidates end
        end
        return loaded, "LoadAsset:" .. tostring(packagePath), attempts, candidates
      end
    end
  end

  return nil, "placeable recipe not found", attempts, candidates
end

function nativePlaceableTargetLocation(info, forwardDistance, liftZ)
  local pawn = (info or {}).pawn
  local controller = (info or {}).pc
  local locX, locY, locZ = vectorOf(pawn)
  local forwardX, forwardY = forwardVectorOf(pawn)
  if forwardX == nil or forwardY == nil then forwardX, forwardY = forwardVectorOf(controller) end
  if forwardX == nil or forwardY == nil then
    local yaw = rotationYawOf(controller) or rotationYawOf(pawn) or 0
    local radians = math.rad(yaw)
    forwardX, forwardY = math.cos(radians), math.sin(radians)
  end
  local distance = math.max(100, math.min(tonumber(forwardDistance) or configNumber("bridge-safety", { "NativePlaceableForwardDistance", "nativePlaceableForwardDistance" }, 450), 3000))
  local lift = math.max(-200, math.min(tonumber(liftZ) or configNumber("bridge-safety", { "NativePlaceableLiftZ", "nativePlaceableLiftZ" }, 0), 800))
  return { X = locX + forwardX * distance, Y = locY + forwardY * distance, Z = locZ + lift }
end

function nativePlaceableRotation(info, yawOverride)
  local yaw = tonumber(yawOverride)
  if yaw == nil then yaw = rotationYawOf((info or {}).pc) or rotationYawOf((info or {}).pawn) or 0 end
  return { Pitch = 0, Yaw = yaw, Roll = 0 }
end

function collectNativePlaceableActors()
  local out = {}
  local seen = {}
  for _, className in ipairs({
    "PlaceableActorBase",
    "PlaceableActorBaseBuilding",
    "PlaceableActorModularBaseBuilding",
    "PlaceableActorModularBaseBuildingFoundation",
    "PlaceableActorFortifications",
    "PlaceableActorItems",
    "PlaceableActorGarden"
  }) do
    local okFind, actors = pcall(function() return FindAllOf(className) end)
    if okFind and actors ~= nil then
      for _, actor in pairs(actors) do
        if actor ~= nil and isValidObject(actor) then
          local key = objectKey(actor)
          if key ~= "" and not seen[key] then
            seen[key] = true
            table.insert(out, actor)
          end
        end
      end
    end
  end
  return out, seen
end

function nearestNativePlaceableActor(targetLocation, beforeKeys)
  local actors = collectNativePlaceableActors()
  local bestActor = nil
  local bestDistance = nil
  local bestKey = ""
  for _, actor in ipairs(actors or {}) do
    local key = objectKey(actor)
    local isNew = key ~= "" and (beforeKeys == nil or beforeKeys[key] ~= true)
    local locX, locY, locZ = vectorOf(actor)
    local deltaX = locX - tonumber((targetLocation or {}).X or 0)
    local deltaY = locY - tonumber((targetLocation or {}).Y or 0)
    local deltaZ = locZ - tonumber((targetLocation or {}).Z or 0)
    local distanceSquared = deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ
    if isNew and (bestDistance == nil or distanceSquared < bestDistance) then
      bestActor = actor
      bestDistance = distanceSquared
      bestKey = key
    end
  end
  if bestActor ~= nil then return bestActor, bestKey, math.sqrt(bestDistance or 0) end
  return nil, "", 0
end

function nativePlaceableBaseManager()
  local gameMode = gameModeRoot()
  local okBase, baseResult = safeCall(gameMode, "GetBaseManager")
  if okBase and baseResult ~= nil and isValidObject(baseResult) then return baseResult, "GameMode.GetBaseManager" end
  return nil, okBase and "GameMode.GetBaseManager:nil" or tostring(baseResult)
end

function nativePlaceableBaseCount()
  local baseManager, route = nativePlaceableBaseManager()
  if baseManager == nil or not isValidObject(baseManager) then return 0, route or "base-manager-missing", nil end
  local bases = firstProp(baseManager, { "_bases", "Bases" })
  local count, _, method = runtimeArrayCount(bases, 0)
  return tonumber(count) or 0, tostring(method or ""), baseManager
end

function nativePlaceableBaseSnapshotJson(maxItems)
  local baseManager, route = nativePlaceableBaseManager()
  if baseManager == nil or not isValidObject(baseManager) then
    return '{"baseManager":' .. nativeProbeObjectJson("baseManager", baseManager, route or "base-manager-missing", {}) .. ',"bases":{"present":false,"count":0,"readMethod":"missing","items":[]}}'
  end
  local bases = firstProp(baseManager, { "_bases", "Bases" })
  local count, items, method = runtimeArrayCount(bases, maxItems or 6)
  local itemJson = {}
  for _, item in ipairs(items or {}) do table.insert(itemJson, runtimeCollectionItemJson(item)) end
  local baseClass = firstProp(baseManager, { "_baseClass", "BaseClass" })
  local baseElementClass = firstProp(baseManager, { "_baseElementClass", "BaseElementClass" })
  return '{"baseManager":' .. nativeProbeObjectJson("baseManager", baseManager, route or "GameMode.GetBaseManager", {}) ..
    ',"baseClass":' .. runtimeValueJson(baseClass) ..
    ',"baseElementActorClass":' .. runtimeValueJson(baseElementClass) ..
    ',"bases":{"present":true,"count":' .. tostring(count or 0) ..
    ',"readMethod":' .. js(method or "") ..
    ',"items":[' .. table.concat(itemJson, ",") .. ']}}'
end

function nativePlaceableActorStateJson(placeableActor)
  if placeableActor == nil or not isValidObject(placeableActor) then
    return '{"present":false}'
  end
  local idValue = firstProp(placeableActor, { "_id", "Id", "ID" })
  local craftingRecipe = firstProp(placeableActor, { "_craftingRecipe", "CraftingRecipe" })
  local productClass = firstProp(placeableActor, { "_productClass", "ProductClass" })
  local statusFlags = firstProp(placeableActor, { "_statusFlags", "StatusFlags" })
  local placementState = firstProp(placeableActor, { "_placementState", "PlacementState" })
  local placementSubState = firstProp(placeableActor, { "_placementSubState", "PlacementSubState" })
  local stateFlags = firstProp(placeableActor, { "_stateFlags", "StateFlags" })
  local craftingProcess = firstProp(placeableActor, { "_craftingProcess", "CraftingProcess" })
  local mainMesh = firstProp(placeableActor, { "_staticMeshComponent_Main", "StaticMeshComponent_Main", "MainStaticMeshComponent" })
  local queryMesh = firstProp(placeableActor, { "_queryStaticMeshComponent", "QueryStaticMeshComponent" })
  local boxCollision = firstProp(placeableActor, { "_boxCollisionComponent", "BoxCollisionComponent" })
  local locX, locY, locZ = vectorOf(placeableActor)
  return '{"present":true' ..
    ',"object":' .. nativeProbeObjectJson("placeable", placeableActor, "runtime", {}) ..
    ',"id":' .. runtimeValueJson(idValue) ..
    ',"craftingRecipe":' .. runtimeValueJson(craftingRecipe) ..
    ',"productClass":' .. runtimeValueJson(productClass) ..
    ',"statusFlags":' .. runtimeValueJson(statusFlags) ..
    ',"placementState":' .. runtimeValueJson(placementState) ..
    ',"placementSubState":' .. runtimeValueJson(placementSubState) ..
    ',"stateFlags":' .. runtimeValueJson(stateFlags) ..
    ',"craftingProcess":' .. runtimeValueJson(craftingProcess) ..
    ',"mainMesh":' .. runtimeMeshComponentJson("mainMesh", mainMesh) ..
    ',"queryMesh":' .. runtimeMeshComponentJson("queryMesh", queryMesh) ..
    ',"boxCollision":' .. runtimeValueJson(boxCollision) ..
    ',"location":{"x":' .. tostring(locX or 0) .. ',"y":' .. tostring(locY or 0) .. ',"z":' .. tostring(locZ or 0) .. '}}'
end

function nativePlaceableRuntimeText(value)
  if value == nil then return "" end
  local valueType = type(value)
  if valueType == "number" or valueType == "boolean" or valueType == "string" then return tostring(value) end
  local okToString, toStringValue = pcall(function()
    if value.ToString ~= nil then return value:ToString() end
    return nil
  end)
  if okToString and toStringValue ~= nil then return tostring(toStringValue) end
  return tostring(value)
end

function nativePlaceableEnumLooksPlaced(value)
  local text = nativePlaceableRuntimeText(value)
  local numberValue = tonumber(text)
  if numberValue == 2 then return true end
  local lower = text:lower()
  return lower:find("placed", 1, true) ~= nil and lower:find("placing", 1, true) == nil
end

function nativePlaceableActorLooksPlaced(placeableActor)
  if placeableActor == nil or not isValidObject(placeableActor) then
    return false, "placeable-invalid"
  end
  local placementState = firstProp(placeableActor, { "_placementState", "PlacementState" })
  local placementSubState = firstProp(placeableActor, { "_placementSubState", "PlacementSubState" })
  local idValue = firstProp(placeableActor, { "_id", "Id", "ID" })
  local productClass = firstProp(placeableActor, { "_productClass", "ProductClass" })
  local mainMesh = firstProp(placeableActor, { "_staticMeshComponent_Main", "StaticMeshComponent_Main", "MainStaticMeshComponent" })
  local placedByState = nativePlaceableEnumLooksPlaced(placementState) or nativePlaceableEnumLooksPlaced(placementSubState)
  local hasProduct = productClass ~= nil
  local hasMainMesh = mainMesh ~= nil and isValidObject(mainMesh)
  local message = "placementState=" .. nativePlaceableRuntimeText(placementState) ..
    " placementSubState=" .. nativePlaceableRuntimeText(placementSubState) ..
    " id=" .. nativePlaceableRuntimeText(idValue) ..
    " productClass=" .. nativePlaceableRuntimeText(productClass) ..
    " mainMeshValid=" .. tostring(hasMainMesh)
  return placedByState and hasProduct, message
end

function nativePlaceableInteractionData(targetLocation, placeableActor)
  local location = targetLocation or { X = 0, Y = 0, Z = 0 }
  return {
    ModifierPressed = true,
    IntegerData = 0,
    PointerData = placeableActor,
    BoolData = true,
    InteractionLocation = location,
    InteractionNormal = { X = 0, Y = 0, Z = 1 },
    VectorData = location,
    BaseElementId = 0
  }
end

function nativePlaceableGrantElevatedForFill(live, attempts)
  if configBool("bridge-safety", { "NativePlaceableGodModeGrantElevated", "nativePlaceableGodModeGrantElevated" }, true) ~= true then
    table.insert(attempts, "GrantElevatedStatus=disabled")
    return false
  end
  local steamId = cleanText((live or {}).steam or (live or {}).steamId or "")
  if steamId == "" then
    table.insert(attempts, "GrantElevatedStatus=steamId-missing")
    return false
  end
  local okGrant, grantRoute = adminExec("GrantElevatedStatus " .. steamId, live)
  table.insert(attempts, "GrantElevatedStatus=" .. (okGrant and "ok:" or "failed:") .. tostring(grantRoute))
  if okGrant then
    local revokeDelayMs = math.max(2000, math.min(math.floor(configNumber("bridge-safety", { "NativePlaceableGodModeRevokeDelayMs", "nativePlaceableGodModeRevokeDelayMs" }, 8000) or 8000), 30000))
    deferGame(revokeDelayMs, function()
      local okRevoke, revokeRoute = adminExec("RevokeElevatedStatus " .. steamId, live)
      appendActionEvent("native_placeable_godmode_revoke", okRevoke, live,
        okRevoke and "ElevatedStatus снят после native GodModeFill." or ("Не удалось снять ElevatedStatus: " .. tostring(revokeRoute)),
        '{"steamId":' .. js(steamId) .. ',"delayMs":' .. tostring(revokeDelayMs) .. ',"route":' .. js(tostring(revokeRoute or "")) .. '}')
    end)
  end
  return okGrant
end

