function nativePlaceableCppGodModeFill(args, rpc)
  local live = (args or {}).live
  local placeableActor = (args or {}).placeableActor
  local targetLocation = (args or {}).targetLocation or { X = 0, Y = 0, Z = 0 }
  local requestId = tostring((args or {}).requestId or "")
  local dispatchAll = configBool("bridge-safety", { "NativePlaceableGodModeFillDispatchAllRoutes", "nativePlaceableGodModeFillDispatchAllRoutes" }, false) == true
  local payload = '{"rpcFullName":' .. js(objectFullName(rpc)) ..
    ',"controllerFullName":' .. js(objectFullName((live or {}).pc)) ..
    ',"pawnFullName":' .. js(objectFullName((live or {}).pawn)) ..
    ',"placeableFullName":' .. js(objectFullName(placeableActor)) ..
    ',"placeableClass":' .. js(objectClassFullName(placeableActor)) ..
    ',"verifiedPlaceable":true' ..
    ',"dispatchAllRoutes":' .. tostring(dispatchAll) ..
    ',"x":' .. tostring(targetLocation.X or 0) ..
    ',"y":' .. tostring(targetLocation.Y or 0) ..
    ',"z":' .. tostring(targetLocation.Z or 0) ..
    ',"source":"native-placeable-lifecycle"}'
  local timeoutMs = math.max(1000, math.min(math.floor(configNumber("bridge-safety", { "NativePlaceableCppGodModeFillTimeoutMs", "nativePlaceableCppGodModeFillTimeoutMs" }, 4500) or 4500), 8000))
  local nativeId = requestId ~= "" and (requestId .. "-godmode-fill") or nil
  return nativeTraderCommandInline("native_placeable_godmode_fill", payload, timeoutMs, nativeId)
end

function nativePlaceableTryGodModeFill(args)
  local live = (args or {}).live
  local placeableActor = (args or {}).placeableActor
  local targetLocation = (args or {}).targetLocation or { X = 0, Y = 0, Z = 0 }
  local attempts = (args or {}).attempts or {}
  if placeableActor == nil or not isValidObject(placeableActor) then
    table.insert(attempts, "GodModeFill=placeable-invalid")
    return false, "PlaceableActor уже недоступен до GodModeFill.", attempts
  end
  local rpc = (live or {}).rpc
  if rpc == nil or not isValidObject(rpc) then rpc = playerRpcChannel((live or {}).pc) end
  if rpc == nil or not isValidObject(rpc) then
    table.insert(attempts, "GodModeFill=rpc-missing")
    return false, "PlayerRpcChannel недоступен для GodModeFill.", attempts
  end
  if (live or {}).pc == nil or not isValidObject((live or {}).pc) then
    table.insert(attempts, "GodModeFill=controller-missing")
    return false, "PlayerController недоступен для GodModeFill.", attempts
  end

  if configBool("bridge-safety", { "NativePlaceableUseCppGodModeFill", "nativePlaceableUseCppGodModeFill" }, true) == true then
    local okNative, nativeMessage, nativeData = nativePlaceableCppGodModeFill(args, rpc)
    table.insert(attempts, "C++ GodModeFill=" .. tostring(okNative) .. ":" .. tostring(nativeMessage))
    table.insert(attempts, "C++ GodModeFill response=" .. (tostring(nativeData or "")):sub(1, 700))
    if okNative then
      return true, "GodModeFill interaction отправлен через C++ inline PlayerRpcChannel/Prisoner ABI route.", attempts
    end
    if configBool("bridge-safety", { "NativePlaceableAllowLuaGodModeFillFallback", "nativePlaceableAllowLuaGodModeFillFallback" }, false) ~= true then
      return false, "C++ GodModeFill не сработал, Lua fallback отключён: " .. tostring(nativeMessage) .. " " .. (tostring(nativeData or "")):sub(1, 700), attempts
    end
  end

  local interactionData = nativePlaceableInteractionData(targetLocation, placeableActor)
  local dispatchAll = configBool("bridge-safety", { "NativePlaceableGodModeFillDispatchAllRoutes", "nativePlaceableGodModeFillDispatchAllRoutes" }, false) == true
  local anyAccepted = false
  local acceptedRoute = ""
  local lastError = nil
  local routes = {}
  if (live or {}).pawn ~= nil and isValidObject((live or {}).pawn) then
    table.insert(routes, {
      label = "Prisoner.InteractWithObjectOnServer#GodModeFill(23)",
      fn = function() return live.pawn:InteractWithObjectOnServer(placeableActor, 23, interactionData) end
    })
    table.insert(routes, {
      label = "Prisoner.InteractWithObjectOnServer#GodModeFill(string)",
      fn = function() return live.pawn:InteractWithObjectOnServer(placeableActor, "GodModeFill", interactionData) end
    })
  else
    table.insert(attempts, "GodModeFill=pawn-missing")
  end
  table.insert(routes, {
    label = "Rpc.InteractWithObjectOnServer#GodModeFill(23)",
    fn = function() return rpc:InteractWithObjectOnServer(placeableActor, live.pc, 23, interactionData) end
  })
  table.insert(routes, {
    label = "Rpc.InteractWithObjectOnServer#GodModeFill(string)",
    fn = function() return rpc:InteractWithObjectOnServer(placeableActor, live.pc, "GodModeFill", interactionData) end
  })

  for _, route in ipairs(routes) do
    local okCall, result = pcall(route.fn)
    table.insert(attempts, tostring(route.label) .. "=" .. (okCall and "ok" or tostring(result)))
    if okCall then
      anyAccepted = true
      if acceptedRoute == "" then acceptedRoute = tostring(route.label) end
      if not dispatchAll then break end
    else
      lastError = result
    end
  end
  if anyAccepted then return true, "GodModeFill interaction отправлен через " .. acceptedRoute .. ".", attempts end
  return false, "SCUM не принял GodModeFill interaction: " .. tostring(lastError), attempts
end

function nativePlaceableCompletionDataJson(args, attempts, okVerified, verifyMessage)
  local placeableActor = (args or {}).placeableActor
  local targetLocation = (args or {}).targetLocation or { X = 0, Y = 0, Z = 0 }
  local beforeBaseCount = tonumber((args or {}).beforeBaseCount) or 0
  local afterBaseCount, afterBaseMethod, baseManager = nativePlaceableBaseCount()
  local stillValid = placeableActor ~= nil and isValidObject(placeableActor)
  local placeableLooksPlaced, placeablePlacedMessage = nativePlaceableActorLooksPlaced(placeableActor)
  local locX, locY, locZ = vectorOf(placeableActor)
  return '{"recipe":' .. js((args or {}).recipeSpec or "") ..
    ',"route":' .. js((args or {}).route or "") ..
    ',"placeableKey":' .. js((args or {}).placeableKey or "") ..
    ',"placeable":' .. js(objectFullName(placeableActor)) ..
    ',"placeableStillValid":' .. tostring(stillValid) ..
    ',"placeableState":' .. nativePlaceableActorStateJson(placeableActor) ..
    ',"baseManager":' .. nativeProbeObjectJson("baseManager", baseManager, "GameMode.GetBaseManager", {}) ..
    ',"baseSnapshot":' .. nativePlaceableBaseSnapshotJson(6) ..
    ',"beforeBaseCount":' .. tostring(beforeBaseCount) ..
    ',"afterBaseCount":' .. tostring(afterBaseCount or 0) ..
    ',"afterBaseReadMethod":' .. js(afterBaseMethod or "") ..
    ',"verificationAttempt":' .. tostring((args or {}).completionVerifyAttempt or 1) ..
    ',"verificationMaxAttempts":' .. tostring((args or {}).completionVerifyMaxAttempts or 1) ..
    ',"placeableLooksPlaced":' .. tostring(placeableLooksPlaced == true) ..
    ',"placeablePlacedMessage":' .. js(placeablePlacedMessage or "") ..
    ',"runtimeVerified":' .. tostring(okVerified == true) ..
    ',"verifyMessage":' .. js(verifyMessage or "") ..
    ',"location":{"x":' .. tostring(locX) .. ',"y":' .. tostring(locY) .. ',"z":' .. tostring(locZ) .. '}' ..
    ',"target":{"x":' .. tostring(targetLocation.X or 0) .. ',"y":' .. tostring(targetLocation.Y or 0) .. ',"z":' .. tostring(targetLocation.Z or 0) .. '}' ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
end

function finishNativePlaceableCompletionVerification(args)
  local live = (args or {}).live
  local requestId = tostring((args or {}).requestId or "")
  local resultCommand = tostring((args or {}).resultCommand or "native_placeable_spawn")
  local attempts = (args or {}).attempts or {}
  local beforeBaseCount = tonumber((args or {}).beforeBaseCount) or 0
  local afterBaseCount = select(1, nativePlaceableBaseCount())
  local okVerified = (tonumber(afterBaseCount) or 0) > beforeBaseCount
  local verifyAttempt = math.max(1, tonumber((args or {}).completionVerifyAttempt) or 1)
  local maxAttempts = math.max(1, math.min(math.floor(configNumber("bridge-safety", { "NativePlaceableGodModeVerifyAttempts", "nativePlaceableGodModeVerifyAttempts" }, 6) or 6), 20))
  local retryDelayMs = math.max(500, math.min(math.floor(configNumber("bridge-safety", { "NativePlaceableGodModeVerifyRetryDelayMs", "nativePlaceableGodModeVerifyRetryDelayMs" }, 1800) or 1800), 12000))
  args.completionVerifyAttempt = verifyAttempt
  args.completionVerifyMaxAttempts = maxAttempts
  local placeableLooksPlaced, placeablePlacedMessage = nativePlaceableActorLooksPlaced((args or {}).placeableActor)
  local message = ""
  if okVerified then
    message = "SCUM подтвердил готовый runtime base после Server_Place + GodModeFill."
  elseif verifyAttempt < maxAttempts then
    message = "GodModeFill отправлен, runtime base ещё не подтвердился; повторяю проверку " .. tostring(verifyAttempt + 1) .. "/" .. tostring(maxAttempts) .. ". " .. tostring(placeablePlacedMessage or "")
    local data = nativePlaceableCompletionDataJson(args, attempts, false, message)
    appendActionEvent("native_placeable_spawn_verify_pending", true, live, message, data)
    args.completionVerifyAttempt = verifyAttempt + 1
    if deferGame(retryDelayMs, function() finishNativePlaceableCompletionVerification(args) end) then
      return nil, message, "__async__"
    end
    args.completionVerifyAttempt = verifyAttempt
  else
    message = "GodModeFill отправлен, но готовый runtime base не подтвердился после " .. tostring(maxAttempts) .. " проверок; это всё ещё похоже на blueprint/placeable, не finished base_element. " .. tostring(placeablePlacedMessage or "")
    if placeableLooksPlaced then
      message = message .. " PlaceableActor выглядит Placed, но BaseManager._bases не вырос — не считаю это persistent house без подтверждения runtime base."
    end
  end
  local data = nativePlaceableCompletionDataJson(args, attempts, okVerified, message)
  appendActionEvent("native_placeable_spawn_verify", okVerified, live, message, data)
  if requestId ~= "" then
    if okVerified then writeAll(RESULT_FILE, ok(resultCommand, message, data, requestId)) else writeAll(RESULT_FILE, fail(resultCommand, message, requestId)) end
  end
  return okVerified, message, data
end

function dispatchNativePlaceableGodModeFill(args)
  local live = (args or {}).live
  local requestId = tostring((args or {}).requestId or "")
  local resultCommand = tostring((args or {}).resultCommand or "native_placeable_spawn")
  local attempts = (args or {}).attempts or {}
  local okFill, fillMessage = nativePlaceableTryGodModeFill(args)
  local data = nativePlaceableCompletionDataJson(args, attempts, false, fillMessage)
  appendActionEvent("native_placeable_godmode_fill", okFill, live, fillMessage, data)
  if not okFill then
    if requestId ~= "" then writeAll(RESULT_FILE, fail(resultCommand, fillMessage, requestId)) end
    return false, fillMessage, data
  end
  local verifyDelayMs = math.max(500, math.min(math.floor(configNumber("bridge-safety", { "NativePlaceableGodModeVerifyDelayMs", "nativePlaceableGodModeVerifyDelayMs" }, 2500) or 2500), 12000))
  if requestId ~= "" and deferGame(verifyDelayMs, function() finishNativePlaceableCompletionVerification(args) end) then
    return nil, "GodModeFill отправлен, ожидаю runtime base verification.", "__async__"
  end
  return finishNativePlaceableCompletionVerification(args)
end

function finishNativePlaceablePlacement(args)
  local live = (args or {}).live
  local requestId = tostring((args or {}).requestId or "")
  local resultCommand = tostring((args or {}).resultCommand or "native_placeable_spawn")
  local targetLocation = (args or {}).targetLocation or { X = 0, Y = 0, Z = 0 }
  local targetRotation = (args or {}).targetRotation or { Pitch = 0, Yaw = 0, Roll = 0 }
  local attempts = (args or {}).attempts or {}
  local placeableActor, placeableKey, distance = nearestNativePlaceableActor(targetLocation, (args or {}).beforeKeys)
  table.insert(attempts, "nearestPlaceable=" .. tostring(objectFullName(placeableActor)) .. " distance=" .. tostring(math.floor(tonumber(distance) or 0)))
  if placeableActor == nil or not isValidObject(placeableActor) then
    local message = "SCUM не создал PlaceableActor после Server_InitiateCraftedPlacement."
    appendActionEvent("native_placeable_spawn", false, live, message,
      '{"recipe":' .. js((args or {}).recipeSpec or "") .. ',"route":' .. js((args or {}).route or "") .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
    if requestId ~= "" then writeAll(RESULT_FILE, fail(resultCommand, message, requestId)) end
    return false, message, "{}"
  end

  local okPlace = false
  local placeResult = nil
  if configBool("bridge-safety", { "NativePlaceableUseCppServerPlace", "nativePlaceableUseCppServerPlace" }, true) == true then
    local okNativePlace, nativePlaceMessage, nativePlaceData = nativePlaceableCppServerPlace(args, placeableActor)
    table.insert(attempts, "C++ Server_Place=" .. tostring(okNativePlace) .. ":" .. tostring(nativePlaceMessage))
    table.insert(attempts, "C++ Server_Place response=" .. (tostring(nativePlaceData or "")):sub(1, 700))
    okPlace = okNativePlace == true
    placeResult = okPlace and tostring(nativePlaceMessage or "native ok") or ("C++ Server_Place failed: " .. tostring(nativePlaceMessage) .. " " .. (tostring(nativePlaceData or "")):sub(1, 700))
    if not okPlace and configBool("bridge-safety", { "NativePlaceableAllowLuaServerPlaceFallback", "nativePlaceableAllowLuaServerPlaceFallback" }, false) == true then
      local okLuaPlace, luaPlaceResult = safeCall(placeableActor, "Server_Place", targetLocation, targetRotation)
      table.insert(attempts, "Lua Server_Place fallback=" .. (okLuaPlace and "ok" or tostring(luaPlaceResult)))
      okPlace = okLuaPlace
      placeResult = luaPlaceResult
    end
  else
    local okLuaPlace, luaPlaceResult = safeCall(placeableActor, "Server_Place", targetLocation, targetRotation)
    table.insert(attempts, "Lua Server_Place=" .. (okLuaPlace and "ok" or tostring(luaPlaceResult)))
    okPlace = okLuaPlace
    placeResult = luaPlaceResult
  end
  local okForce, forceResult = safeCall(placeableActor, "ForceNetUpdate")
  table.insert(attempts, "ForceNetUpdate=" .. (okForce and "ok" or tostring(forceResult)))
  local locX, locY, locZ = vectorOf(placeableActor)
  local data = '{"recipe":' .. js((args or {}).recipeSpec or "") ..
    ',"route":' .. js((args or {}).route or "") ..
    ',"placeableKey":' .. js(placeableKey) ..
    ',"placeable":' .. js(objectFullName(placeableActor)) ..
    ',"placeableState":' .. nativePlaceableActorStateJson(placeableActor) ..
    ',"location":{"x":' .. tostring(locX) .. ',"y":' .. tostring(locY) .. ',"z":' .. tostring(locZ) .. '}' ..
    ',"target":{"x":' .. tostring(targetLocation.X or 0) .. ',"y":' .. tostring(targetLocation.Y or 0) .. ',"z":' .. tostring(targetLocation.Z or 0) .. '}' ..
    ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}'
  local message = okPlace and "SCUM native placement выполнен через Server_InitiateCraftedPlacement + Server_Place." or ("Server_Place не сработал: " .. tostring(placeResult))
  appendActionEvent("native_placeable_spawn", okPlace, live, message, data)
  if okPlace and configBool("bridge-safety", { "NativePlaceableAutoCompleteGodModeFill", "nativePlaceableAutoCompleteGodModeFill" }, true) == true then
    local beforeBaseCount, beforeBaseMethod = nativePlaceableBaseCount()
    table.insert(attempts, "beforeBaseCount=" .. tostring(beforeBaseCount) .. " via " .. tostring(beforeBaseMethod))
    nativePlaceableGrantElevatedForFill(live, attempts)
    local completionArgs = {
      live = live,
      requestId = requestId,
      resultCommand = resultCommand,
      recipeSpec = (args or {}).recipeSpec or "",
      route = (args or {}).route or "",
      attempts = attempts,
      placeableActor = placeableActor,
      placeableKey = placeableKey,
      beforeBaseCount = beforeBaseCount,
      targetLocation = targetLocation,
      targetRotation = targetRotation
    }
    local fillDelayMs = math.max(0, math.min(math.floor(configNumber("bridge-safety", { "NativePlaceableGodModeFillDelayMs", "nativePlaceableGodModeFillDelayMs" }, 650) or 650), 5000))
    if requestId ~= "" and deferGame(fillDelayMs, function() dispatchNativePlaceableGodModeFill(completionArgs) end) then
      appendActionEvent("native_placeable_spawn", true, live, "Placeable поставлен, GodModeFill completion поставлен в очередь.",
        '{"recipe":' .. js((args or {}).recipeSpec or "") .. ',"placeableKey":' .. js(placeableKey) .. ',"fillDelayMs":' .. tostring(fillDelayMs) .. ',"attempts":' .. js(table.concat(attempts, " | ")) .. '}')
      return nil, "Placeable поставлен, GodModeFill completion поставлен в очередь.", "__async__"
    end
    return dispatchNativePlaceableGodModeFill(completionArgs)
  end
  if requestId ~= "" then
    if okPlace then writeAll(RESULT_FILE, ok(resultCommand, message, data, requestId)) else writeAll(RESULT_FILE, fail(resultCommand, message, requestId)) end
  end
  return okPlace, message, data
end

function spawnNativePlaceableForInfo(recipeSpec, info, options)
  local live, ready, readyMessage, readyReason = deliveryReadyInfo(info, { requireInventory = false })
  if not ready then return false, deliveryReadyMessage(readyReason) .. " (" .. tostring(readyMessage or "") .. ")", "{}" end

  local recipe, routeName, attempts, candidates = loadNativePlaceableRecipe(recipeSpec ~= "" and recipeSpec or "CR_Base_Block")
  if recipe == nil or not isValidObject(recipe) then
    return false, "Рецепт placeable не найден/не загружен: " .. tostring(routeName), '{"recipe":' .. js(recipeSpec or "") .. ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. ',"candidates":' .. stringArrayJson(candidates or {}) .. '}'
  end

  local beforeActors, beforeKeys = collectNativePlaceableActors()
  local targetLocation = (options or {}).location or nativePlaceableTargetLocation(live, (options or {}).forwardDistance, (options or {}).liftZ)
  local targetRotation = nativePlaceableRotation(live, (options or {}).yaw)
  table.insert(attempts, "beforePlaceables=" .. tostring(#(beforeActors or {})))
  local okInitiate, initiateResult = safeCall(live.pawn, "Server_InitiateCraftedPlacement", recipe, targetLocation)
  table.insert(attempts, "Prisoner.Server_InitiateCraftedPlacement=" .. (okInitiate and "ok" or tostring(initiateResult)))
  if not okInitiate then
    return false, "Server_InitiateCraftedPlacement не сработал: " .. tostring(initiateResult), '{"recipe":' .. js(recipeSpec or "") .. ',"route":' .. js(routeName or "") .. ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
  end

  local requestId = tostring((options or {}).requestId or "")
  local delayMs = math.max(250, math.min(math.floor(tonumber((options or {}).delayMs) or configNumber("bridge-safety", { "NativePlaceableFinishDelayMs", "nativePlaceableFinishDelayMs" }, 1200)), 8000))
  local args = {
    live = live,
    requestId = requestId,
    resultCommand = tostring((options or {}).commandName or "native_placeable_spawn"),
    recipeSpec = recipeSpec ~= "" and recipeSpec or "CR_Base_Block",
    route = routeName,
    attempts = attempts,
    beforeKeys = beforeKeys,
    targetLocation = targetLocation,
    targetRotation = targetRotation
  }
  if requestId ~= "" and deferGame(delayMs, function() finishNativePlaceablePlacement(args) end) then
    appendActionEvent("native_placeable_spawn", true, live, "SCUM native placement начат, ожидаю PlaceableActor.",
      '{"recipe":' .. js(args.recipeSpec) .. ',"route":' .. js(routeName or "") .. ',"delayMs":' .. tostring(delayMs) .. ',"target":{"x":' .. tostring(targetLocation.X or 0) .. ',"y":' .. tostring(targetLocation.Y or 0) .. ',"z":' .. tostring(targetLocation.Z or 0) .. '}}')
    return nil, "SCUM native placement начат, ожидаю PlaceableActor.", "__async__"
  end

  return finishNativePlaceablePlacement(args)
end

function nativeProbePlayerJson(info)
  if info == nil then return "null" end
  local x, y, z = vectorOf(info.pawn)
  return '{"name":' .. js(info.name or "") ..
    ',"steamId":' .. js(info.steam or "") ..
    ',"runtimeKey":' .. js(info.runtimeKey or "") ..
    ',"userProfileId":' .. js(info.userProfileId or info.serverUserProfileId or "") ..
    ',"pawn":' .. js(objectFullName(info.pawn)) ..
    ',"controller":' .. js(objectFullName(info.pc)) ..
    ',"location":{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. '}' ..
    ',"yaw":' .. tostring(rotationYawOf(info.pc) or rotationYawOf(info.pawn) or 0) .. '}'
end

local function hektorJsonNumberField(key, value)
  local number = tonumber(value)
  if number == nil then return nil end
  return '"' .. tostring(key) .. '":' .. tostring(number)
end

local function hektorJsonBoolField(key, value)
  if value == nil then return nil end
  return '"' .. tostring(key) .. '":' .. tostring(value == true)
end

function hektorEditorPayload(text, runtimeKey, defaultConfirm)
  local steamId = extractStringAny(text, { "steamId", "targetSteamId", "SteamId", "TargetSteamId" }) or ""
  local name = extractStringAny(text, { "name", "targetName", "Name", "TargetName" }) or ""
  local targetRuntime = extractStringAny(text, { "runtimeKey", "targetRuntimeKey", "RuntimeKey", "TargetRuntimeKey" }) or runtimeKey or ""
  local info = resolvePlayerInfo(steamId, name, nil, targetRuntime) or findPlayer(steamId, name, targetRuntime)
  if info == nil then
    return nil, "Игрок не найден для Hektor editor route.", nil
  end

  local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
  local x, y, z = vectorOf(live.pawn)
  if (x == 0 and y == 0 and z == 0) and (live.x ~= nil or live.y ~= nil or live.z ~= nil) then
    x = tonumber(live.x) or x
    y = tonumber(live.y) or y
    z = tonumber(live.z) or z
  end

  local yaw = rotationYawOf(live.pc) or rotationYawOf(live.pawn) or tonumber(live.yaw) or 0
  local pitch = rotationPitchOf(live.pc) or rotationPitchOf(live.pawn) or tonumber(live.pitch) or 0
  local forwardX, forwardY = forwardVectorOf(live.pawn)
  if forwardX == nil or forwardY == nil then forwardX, forwardY = forwardVectorOf(live.pc) end
  if forwardX == nil or forwardY == nil then
    local rad = math.rad(yaw)
    forwardX, forwardY = math.cos(rad), math.sin(rad)
  end
  local pitchRad = math.rad(pitch or 0)
  local forwardZ = math.sin(pitchRad)

  local fields = {
    '"playerName":' .. js(live.name or name or ""),
    '"steamId":' .. js(live.steam or steamId or ""),
    '"runtimeKey":' .. js(live.runtimeKey or targetRuntime or ""),
    '"userProfileId":' .. js(live.userProfileId or live.serverUserProfileId or ""),
    '"pawnFullName":' .. js(objectFullName(live.pawn)),
    '"controllerFullName":' .. js(objectFullName(live.pc)),
    '"x":' .. tostring(x or 0),
    '"y":' .. tostring(y or 0),
    '"z":' .. tostring(z or 0),
    '"forwardX":' .. tostring(forwardX or 1),
    '"forwardY":' .. tostring(forwardY or 0),
    '"forwardZ":' .. tostring(forwardZ or 0),
    '"yaw":' .. tostring(yaw or 0),
    '"pitch":' .. tostring(pitch or 0)
  }

  for _, key in ipairs({
    "radiusCm", "selectionRadiusCm", "minDistanceCm", "minForwardDot",
    "maxLevels", "maxActorSlots", "dx", "dy", "dz", "upCm",
    "forwardCm", "rightCm", "yawDelta", "pitchDelta", "rollDelta",
    "traceDistanceCm", "maxTraceDistanceCm", "traceRadiusCm", "sphereRadiusCm",
    "aimToleranceCm", "traceToleranceCm", "rayToleranceCm", "aimTolerancePerMeter",
    "traceTolerancePerMeter", "eyeOffsetZ", "traceChannel", "lastTraceChannel", "maxTraceChannel"
  }) do
    local value = extractNumberAny(text, { key, key:sub(1, 1):upper() .. key:sub(2) }, nil)
    local field = hektorJsonNumberField(key, value)
    if field ~= nil then table.insert(fields, field) end
  end

  local hasExplicitEditorTarget = false
  for _, key in ipairs({ "actorFullName", "targetActorFullName", "objectPath", "targetObjectPath", "fullName" }) do
    local value = extractStringAny(text, { key, key:sub(1, 1):upper() .. key:sub(2) }) or ""
    if value ~= "" then
      hasExplicitEditorTarget = true
      table.insert(fields, '"' .. key .. '":' .. js(value))
    end
  end

  if not hasExplicitEditorTarget and type(editorActorLatestTargetForInfo) == "function" then
    local cachedTarget = editorActorLatestTargetForInfo(live)
    if cachedTarget ~= nil and tostring(cachedTarget.actorFullName or "") ~= "" then
      table.insert(fields, '"actorFullName":' .. js(cachedTarget.actorFullName or ""))
      table.insert(fields, '"targetActorFullName":' .. js(cachedTarget.actorFullName or ""))
      table.insert(fields, '"actorTargetSource":' .. js(cachedTarget.source or "server-cache"))
      table.insert(fields, '"actorTargetAgeSeconds":' .. tostring(math.max(0, math.floor((os.clock() - (tonumber(cachedTarget.clock) or os.clock())) + 0.5))))
      if tostring(cachedTarget.actorClassFullName or "") ~= "" then
        table.insert(fields, '"actorClassFullName":' .. js(cachedTarget.actorClassFullName or ""))
      end
    end
  end

  for _, key in ipairs({ "allowBehind", "dryRun", "dry", "allowLargeMove" }) do
    local value = extractBoolAny(text, { key, key:sub(1, 1):upper() .. key:sub(2) }, nil)
    local field = hektorJsonBoolField(key, value)
    if field ~= nil then table.insert(fields, field) end
  end

  local confirm = extractStringAny(text, { "confirm", "Confirm" }) or ""
  if tostring(defaultConfirm or "") ~= "" and confirm == "" then confirm = tostring(defaultConfirm) end
  if confirm ~= "" then table.insert(fields, '"confirm":' .. js(confirm)) end

  return "{" .. table.concat(fields, ",") .. "}", "Hektor editor payload ready.", live
end

function debugScumNativeProbe(steamId, name, runtimeKey, recipeSpec, deepProbe)
  local started = os.clock()
  local hasTarget = tostring(steamId or "") ~= "" or tostring(name or "") ~= "" or tostring(runtimeKey or "") ~= ""
  local deep = deepProbe == true
  local info = nil
  if hasTarget then
    info = resolvePlayerInfo(steamId, name, nil, runtimeKey) or findPlayer(steamId, name, runtimeKey)
  end
  local gameMode, gameModeRoute = gameModeRoot()
  local gameState, gameStateRoute = nil, ""
  if deep then
    gameState, gameStateRoute = findFirst({ "BP_ConZGameState_C", "ConZGameState", "GameState" })
  end
  local baseManager = nil
  local baseManagerRoute = ""
  local okBase, baseResult = safeCall(gameMode, "GetBaseManager")
  if okBase and baseResult ~= nil and isValidObject(baseResult) then
    baseManager = baseResult
    baseManagerRoute = "GameMode.GetBaseManager"
  end
  if baseManager == nil or not isValidObject(baseManager) then
    if deep then
      local found, foundRoute = findFirst({ "BP_ConZBaseManager_C", "ConZBaseManager", "ConZBaseManager_C" })
      baseManager = found
      baseManagerRoute = "FindFirstOf:" .. tostring(foundRoute or "")
    else
      baseManagerRoute = "GameMode.GetBaseManager:missing"
    end
  end
  local economyManager, economyRoute = nil, ""
  local traderManagingComponent, traderManagingRoute = nil, ""
  local tradePost, tradePostRoute = nil, ""
  local trader, traderRoute = nil, ""
  if deep then
    economyManager, economyRoute = findFirst({ "BP_EconomyManager_C", "BP_ConZEconomyManager_C", "ConZEconomyManager", "ConZEconomyManager_C" })
    traderManagingComponent, traderManagingRoute = findFirst({ "TraderManagingComponent", "UTraderManagingComponent" })
    traderManagingRoute = "FindFirstOf:" .. tostring(traderManagingRoute or "")
    tradePost, tradePostRoute = findFirst({ "TradePost", "BP_TradePost_C", "ATradePost" })
    trader, traderRoute = findFirst({ "Trader", "BP_Banker01_C", "BP_Banker_01_C", "ATrader" })
  end
  local recipes = {
    nativeProbeRecipeJson(recipeSpec ~= "" and recipeSpec or "CR_Base_Block")
  }
  if deep then
    table.insert(recipes, nativeProbeRecipeJson("CR_Base_Flag_01"))
    table.insert(recipes, nativeProbeRecipeJson("CR_Base_Modular_Foundation_Twig"))
    table.insert(recipes, nativeProbeRecipeJson("CR_Base_Modular_Wall_Twig"))
  end
  local elements = {}
  if deep then
    table.insert(elements, nativeProbeBaseElementJson("BP_Base_Block"))
    table.insert(elements, nativeProbeBaseElementJson("BP_Base_Flag"))
    table.insert(elements, nativeProbeBaseElementJson("BP_Base_Cabin"))
    table.insert(elements, nativeProbeBaseElementJson("BP_Base_Cabin_02"))
    table.insert(elements, nativeProbeBaseElementJson("BP_Base_Modular_Foundation_Twig"))
    table.insert(elements, nativeProbeBaseElementJson("BP_Base_Modular_Wall_Twig"))
  end
  local durationMs = math.floor((os.clock() - started) * 1000)
  local data = '{"version":' .. js(BRIDGE_VERSION or "") ..
    ',"durationMs":' .. tostring(durationMs) ..
    ',"player":' .. nativeProbePlayerJson(info) ..
    ',"gameMode":' .. nativeProbeObjectJson("gameMode", gameMode, gameModeRoute, {}) ..
    ',"gameState":' .. nativeProbeObjectJson("gameState", gameState, gameStateRoute, {}) ..
    ',"baseManager":' .. nativeProbeObjectJson("baseManager", baseManager, baseManagerRoute, {}) ..
    ',"baseSnapshot":' .. nativePlaceableBaseSnapshotJson(6) ..
    ',"economyManager":' .. nativeProbeObjectJson("economyManager", economyManager, economyRoute, {}) ..
    ',"traderManagingComponent":' .. nativeProbeObjectJson("traderManagingComponent", traderManagingComponent, traderManagingRoute, {}) ..
    ',"tradePost":' .. nativeProbeObjectJson("tradePost", tradePost, tradePostRoute, {}) ..
    ',"trader":' .. nativeProbeObjectJson("trader", trader, traderRoute, {}) ..
    ',"economyReflection":' .. traderReflectionProbeJson("economyManager", economyManager, economyRoute) ..
    ',"traderManagingReflection":' .. traderReflectionProbeJson("traderManagingComponent", traderManagingComponent, traderManagingRoute) ..
    ',"tradePostReflection":' .. traderReflectionProbeJson("tradePost", tradePost, tradePostRoute) ..
    ',"traderReflection":' .. traderReflectionProbeJson("trader", trader, traderRoute) ..
    ',"recipes":[' .. table.concat(recipes, ",") .. ']' ..
    ',"baseElements":[' .. table.concat(elements, ",") .. ']' ..
    ',"deep":' .. tostring(deep) ..
    ',"note":"static-only safe probe; default path avoids player scans, optional deep=true enables broader lookup"}'
  appendActionEvent("debug_scum_native_probe", true, info, "Нативный SCUM-probe выполнен без спавна.", data)
  return true, "Нативный SCUM-probe выполнен без спавна.", data
end

function cfcoreProbeFind(label, candidates)
  local attempts = {}
  for _, candidate in ipairs(candidates or {}) do
    local found = nil
    local okFind, errFind = pcall(function() found = StaticFindObject(candidate) end)
    table.insert(attempts, "StaticFindObject(" .. tostring(candidate) .. ")=" .. (okFind and (isValidObject(found) and "ok" or "nil") or tostring(errFind)))
    if okFind and found ~= nil and isValidObject(found) then
      return found, "StaticFindObject:" .. tostring(candidate), attempts
    end
  end
  for _, candidate in ipairs(candidates or {}) do
    local simple = tostring(candidate or ""):match("([^%.%/]+)$") or tostring(candidate or "")
    simple = simple:gsub("^Default__", "")
    if simple ~= "" then
      local found = nil
      local okFind, errFind = pcall(function() found = FindFirstOf(simple) end)
      table.insert(attempts, "FindFirstOf(" .. tostring(simple) .. ")=" .. (okFind and (isValidObject(found) and "ok" or "nil") or tostring(errFind)))
      if okFind and found ~= nil and isValidObject(found) then
        return found, "FindFirstOf:" .. tostring(simple), attempts
      end
    end
  end
  return nil, "", attempts
end

function cfcoreMaskedValue(obj, key)
  local value = safeGet(obj, key)
  if value == nil then return "" end
  if tostring(key or ""):lower():find("apikey", 1, true) ~= nil then
    local text = tostring(value or "")
    if text == "" then return "" end
    return "<redacted:" .. tostring(#text) .. ">"
  end
  return tostring(value)
end

function cfcoreMethodsJson(obj)
  local methods = {
    "Initialize",
    "GetInstalledMods",
    "GetSystemInstalledMods",
    "SynchronizeWithServer",
    "AssureServerModsUpdated",
    "AssureClientModsUpdated",
    "ApiGetMods",
    "ApiGetFiles",
    "CreateMod",
    "CreateModFile",
    "CreateCookedModFile"
  }
  local rows = {}
  for _, name in ipairs(methods) do
    table.insert(rows, js(name) .. ":" .. tostring(safeGet(obj, name) ~= nil))
  end
  return "{" .. table.concat(rows, ",") .. "}"
end

function cfcoreStaticProbeJson(label, candidates)
  local attempts = {}
  local foundRoute = ""
  for _, candidate in ipairs(candidates or {}) do
    local okProbe, obj = pcall(function() return StaticFindObject(candidate) end)
    local present = okProbe and obj ~= nil
    table.insert(attempts, '{"candidate":' .. js(candidate) ..
      ',"ok":' .. tostring(okProbe == true) ..
      ',"present":' .. tostring(present == true) .. '}')
    if present and foundRoute == "" then
      foundRoute = candidate
    end
  end
  return '{"label":' .. js(label or "") ..
    ',"found":' .. tostring(foundRoute ~= "") ..
    ',"route":' .. js(foundRoute) ..
    ',"attempts":[' .. table.concat(attempts, ",") .. ']}'
end

function cfcoreStatusProbeJson()
  local started = os.clock()
  local subsystemJson = cfcoreStaticProbeJson("cfcoreSubsystem", {
    "/Script/cfcore.CFCoreSubsystem",
    "/Script/cfcore.Default__CFCoreSubsystem"
  })
  local bpLibraryJson = cfcoreStaticProbeJson("cfcoreBpLibrary", {
    "/Script/cfcore.CFCoreBPLibrary",
    "/Script/cfcore.Default__CFCoreBPLibrary"
  })
  local editorSettingsJson = cfcoreStaticProbeJson("cfcoreEditorSettings", {
    "/Script/cfcore.CFCoreEditorSettings",
    "/Script/cfcore.Default__CFCoreEditorSettings"
  })
  local data = '{"version":' .. js(BRIDGE_VERSION or "") ..
    ',"durationMs":' .. tostring(math.floor((os.clock() - started) * 1000)) ..
    ',"safeProbe":true' ..
    ',"mutationCalls":false' ..
    ',"subsystem":' .. subsystemJson ..
    ',"bpLibrary":' .. bpLibraryJson ..
    ',"editorSettings":' .. editorSettingsJson ..
    ',"note":"lightweight read-only CFCore status probe; no object scans, Initialize, InstallMod, AssureServerModsUpdated or download calls were invoked"}'
  return data
end

function managedStaticObjectProbeJson()
  local started = os.clock()
  local groups = {
    {
      domain = "admin-command-dispatch",
      className = "SpawnItem",
      candidates = {
        "/Script/SCUM.SpawnItem",
        "/Script/SCUM.Default__SpawnItem",
        "/Script/SCUM.AdminCommand_SpawnItem",
        "/Script/SCUM.Default__AdminCommand_SpawnItem",
        "SpawnItem",
        "Default__SpawnItem"
      }
    },
    {
      domain = "admin-command-dispatch",
      className = "SpawnVehicle",
      candidates = {
        "/Script/SCUM.SpawnVehicle",
        "/Script/SCUM.Default__SpawnVehicle",
        "/Script/SCUM.AdminCommand_SpawnVehicle",
        "/Script/SCUM.Default__AdminCommand_SpawnVehicle",
        "SpawnVehicle",
        "Default__SpawnVehicle"
      }
    },
    {
      domain = "admin-command-dispatch",
      className = "ScheduleWorldEvent",
      candidates = {
        "/Script/SCUM.ScheduleWorldEvent",
        "/Script/SCUM.Default__ScheduleWorldEvent",
        "/Script/SCUM.AdminCommand_ScheduleWorldEvent",
        "/Script/SCUM.Default__AdminCommand_ScheduleWorldEvent",
        "ScheduleWorldEvent",
        "Default__ScheduleWorldEvent"
      }
    },
    {
      domain = "inventory-loot-chests",
      className = "ChestInventoryComponent",
      candidates = {
        "/Script/SCUM.ChestInventoryComponent",
        "/Script/SCUM.Default__ChestInventoryComponent",
        "ChestInventoryComponent",
        "Default__ChestInventoryComponent"
      }
    },
    {
      domain = "inventory-loot-chests",
      className = "BP_Base_Improvised_Wooden_Chest",
      candidates = {
        "/Game/ConZ_Files/Blueprints/BaseBuilding/Items/BP_Base_Improvised_Wooden_Chest.BP_Base_Improvised_Wooden_Chest_C",
        "/Game/ConZ_Files/Blueprints/BaseBuilding/Items/BP_Base_Improvised_Wooden_Chest.Default__BP_Base_Improvised_Wooden_Chest_C",
        "BP_Base_Improvised_Wooden_Chest_C",
        "Default__BP_Base_Improvised_Wooden_Chest_C"
      }
    }
  }
  local groupRows = {}
  local foundGroups = 0
  local attemptTotal = 0
  for _, group in ipairs(groups) do
    local attempts = {}
    local found = false
    local foundRoute = ""
    local foundFullName = ""
    for _, candidate in ipairs(group.candidates or {}) do
      local obj = nil
      local okFind, errFind = pcall(function() obj = StaticFindObject(candidate) end)
      local present = okFind and obj ~= nil and isValidObject(obj)
      attemptTotal = attemptTotal + 1
      table.insert(attempts, '{"candidate":' .. js(candidate) ..
        ',"ok":' .. tostring(okFind == true) ..
        ',"present":' .. tostring(present == true) ..
        ',"error":' .. js((okFind == true) and "" or tostring(errFind or "")) .. '}')
      if present and not found then
        found = true
        foundRoute = candidate
        foundFullName = objectFullName(obj)
      end
    end
    if found then foundGroups = foundGroups + 1 end
    table.insert(groupRows, '{"domain":' .. js(group.domain) ..
      ',"className":' .. js(group.className) ..
      ',"found":' .. tostring(found == true) ..
      ',"route":' .. js(foundRoute) ..
      ',"fullName":' .. js(foundFullName) ..
      ',"attempts":[' .. table.concat(attempts, ",") .. ']}')
  end
  return '{"schema":"scum-nedjin-managed-static-object-probe-v1"' ..
    ',"version":' .. js(BRIDGE_VERSION or "") ..
    ',"utc":' .. js(nowUtc()) ..
    ',"durationMs":' .. tostring(math.floor((os.clock() - started) * 1000)) ..
    ',"policy":{"readOnly":true,"staticDumpSelected":true,"staticFindOnly":true,"runtimeObjectScan":false,"findAllOf":false,"loadAsset":false,"ueMutation":false,"scumDbWrite":false,"commandDispatch":false}' ..
    ',"groupsTotal":' .. tostring(#groups) ..
    ',"groupsFound":' .. tostring(foundGroups) ..
    ',"attemptsTotal":' .. tostring(attemptTotal) ..
    ',"groups":[' .. table.concat(groupRows, ",") .. ']}'
end

-- These commands never need a UE object.  Keep them outside
-- deferGameStrict so an API/browser refresh cannot enqueue a GameThread task.
-- `list_players` deliberately fails closed: the native HTTP layer then uses
-- its existing SCUM.log fallback rather than running live player reflection.
function routeReadOnlyCommand(text)
  local id = extractString(text, "id") or ""
  local command = extractString(text, "command") or ""
  if command ~= "list_players" and command ~= "bridge_version" and command ~= "debug_bridge_version" then
    return nil
  end

  CURRENT_BRIDGE_RESULT_ID = id
  appendLog("command " .. command .. " id=" .. id .. " mode=direct-readonly")
  if command == "bridge_version" or command == "debug_bridge_version" then
    return ok(command, "bridge version", '{"version":' .. js(BRIDGE_VERSION or "") .. '}', id)
  end
  return fail(command, "Live player enumeration is disabled for runtime stability; use the server-log fallback.", id)
end

function route(text)
  local id = extractString(text, "id") or ""
  CURRENT_BRIDGE_RESULT_ID = id
  local command = extractString(text, "command") or ""
  local runtimeKey = extractString(text, "runtimeKey") or ""
  appendLog("command " .. command .. " id=" .. id)

  if command == "list_players" then
    -- Panel refresh is a read-only operation.  Do not turn it into a live
    -- PlayerArray reflection scan: the log snapshot keeps the panel usable
    -- without dereferencing transient UE objects on every refresh.
    local playersOk, payload = pcall(serverLogPlayersJson)
    if not playersOk or type(payload) ~= "string" then
      appendLog("list_players server-log snapshot failed: " .. tostring(payload))
      payload = '{"players":[],"count":0,"source":"server-log","runtimeReady":false,"runtimeReason":"list-player snapshot unavailable"}'
    end
    return ok(command, "players listed", payload)
  end

  if command == "bridge_version" or command == "debug_bridge_version" then
    return ok(command, "bridge version", '{"version":' .. js(BRIDGE_VERSION or "") .. '}')
  end

  if command == "managed_static_object_probe" or command == "debug_managed_static_object_probe" then
    return ok(command, "managed static object probe", managedStaticObjectProbeJson(), id)
  end

  if command == "cfcore_status_probe" or command == "debug_cfcore_status_probe" then
    return ok(command, "CFCore status probe", cfcoreStatusProbeJson(), id)
  end

  if command == "cfcore_native_status_probe" or command == "debug_cfcore_native_status_probe" then
    local sent, message, data = nativeTraderCommandAsync(command, "cfcore_native_status_probe", text, 10000, id)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "cfcore_editor_settings_probe" or command == "debug_cfcore_editor_settings_probe" then
    local sent, message, data = nativeTraderCommandAsync(command, "cfcore_editor_settings_probe", text, 10000, id)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "cfcore_configure_server_runtime" or command == "debug_cfcore_configure_server_runtime" then
    local sent, message, data = nativeTraderCommandAsync(command, "cfcore_configure_server_runtime", text, 15000, id)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "cfcore_api_mods_summary_probe" or command == "debug_cfcore_api_mods_summary_probe" then
    local sent, message, data = nativeTraderCommandAsync(command, "cfcore_api_mods_summary_probe", text, 45000, id)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "cfcore_api_files_summary_probe" or command == "debug_cfcore_api_files_summary_probe" then
    local sent, message, data = nativeTraderCommandAsync(command, "cfcore_api_files_summary_probe", text, 45000, id)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "cfcore_server_mod_sync_probe" or command == "debug_cfcore_server_mod_sync_probe" then
    local sent, message, data = nativeTraderCommandAsync(command, "cfcore_server_mod_sync_probe", text, 15000, id)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "cfcore_client_file_sync_probe" or command == "debug_cfcore_client_file_sync_probe" then
    local sent, message, data = nativeTraderCommandAsync(command, "cfcore_client_file_sync_probe", text, 45000, id)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "scum_mod_manager_probe" or command == "debug_scum_mod_manager_probe" then
    local sent, message, data = nativeTraderCommandAsync(command, "scum_mod_manager_probe", text, 10000, id)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "weather_snapshot" or command == "runtime_weather_snapshot" then
    local data, message = weatherSnapshotJson()
    return ok(command, message, data, id)
  end

  if command == "radiation_fog_sphere_probe" or command == "fog_sphere_runtime_probe" or command == "runtime_fog_sphere_probe" then
    local sent, message, data = fogSphereRuntimeProbe(text, command, id)
    if sent then return ok(command, message, data or "{}", id) end
    return failWithData(command, message or "fog sphere runtime probe failed", data or "{}", id)
  end

  if command == "editor_actor_overlay_state" or command == "hektor_overlay_state" then
    return ok(command, "actor editor overlay state", editorActorOverlayStateJson(), id)
  end

  if command == "persistent_actor_replay_now" or command == "editor_actor_persistent_replay_now" then
    local okRestore, message = restorePersistentActorSites()
    local rows, rowsPath, rowsBytes = persistentActorRows()
    local data = '{"ok":' .. tostring(okRestore == true) ..
      ',"rows":' .. tostring(#rows) ..
      ',"path":' .. js(rowsPath or "") ..
      ',"bytes":' .. tostring(rowsBytes or 0) ..
      ',"message":' .. js(message or "") .. '}'
    if okRestore then return ok(command, message or "persistent actor replay complete", data, id) end
    return failWithData(command, message or "persistent actor replay failed", data, id)
  end

  if command == "native_trader_status" or command == "native_trader_ping" or command == "debug_native_trader_status" then
    local sent, message, data = nativeTraderStatusAsync(id, command)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "native_trader_probe" or command == "debug_native_trader_probe" then
    local sent, message, data = nativeTraderProbeAsync(id, command)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "native_actor_editor_probe" or command == "editor_actor_probe" then
    if configBool("bridge-safety", { "AllowUnsafeActorEditorProbe", "allowUnsafeActorEditorProbe" }, false) ~= true then
      local data = '{"ok":false,"blocked":true,"stage":"actor-editor-probe-disabled","route":"native_actor_editor_probe","message":"Blocked after the 2026-06-05 streamed actor exact-probe SCUMServer crash. Do not read map actor transforms on the dedicated server through this route."}'
      return failWithData(command, "Actor editor server probe blocked after live crash", data, id)
    end
    local sent, message, data = nativeTraderCommandAsync(command, "native_actor_editor_probe", text, 6000, id)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "native_actor_editor_target_probe" or command == "editor_actor_target_probe" or command == "hektor_target_probe" or command == "server_actor_editor_target_probe" then
    local data = '{"ok":false,"blocked":true,"stage":"hektor-target-probe-disabled","route":"native_actor_editor_target_probe","message":"Blocked after live SCUMServer crash in native 0.1.99. Do not call reflected prisoner target getters on the dedicated server."}'
    return failWithData(command, "Actor editor target probe blocked after live crash", data, id)
  end

  if command == "native_actor_editor_select" or command == "editor_actor_select" then
    local data = '{"ok":false,"blocked":true,"stage":"server-target-selection-disabled","route":"native_actor_editor_select","message":"Server-side actor selection is disabled. Use client event-target capture and pass exact actorFullName/objectPath to move/nudge/copy/hide."}'
    return failWithData(command, "Actor editor server selection disabled", data, id)
  end

  if command == "native_actor_editor_trace_select" or command == "editor_actor_trace_select" then
    local data = '{"ok":false,"blocked":true,"stage":"server-target-selection-disabled","route":"native_actor_editor_trace_select","message":"Server-side trace selection is disabled. Use client event-target capture and pass exact actorFullName/objectPath to move/nudge/copy/hide."}'
    return failWithData(command, "Actor editor trace selection disabled", data, id)
  end

  if command == "hektor_select_actor" or command == "hektor_actor_select" or command == "server_actor_editor_select" then
    local data = '{"ok":false,"blocked":true,"stage":"server-target-selection-disabled","route":"hektor_select_actor","message":"Hektor select must happen on the admin client through event-target capture; server-side selection is disabled."}'
    return failWithData(command, "Hektor server selection disabled", data, id)
  end

  if command == "hektor_trace_select_actor" or command == "hektor_actor_trace_select" or command == "server_actor_editor_trace_select" then
    local data = '{"ok":false,"blocked":true,"stage":"server-target-selection-disabled","route":"hektor_trace_select_actor","message":"Hektor trace select is disabled after live crashes. Use client event-target capture instead."}'
    return failWithData(command, "Hektor trace selection disabled", data, id)
  end

  if command == "world_edit_visual_spawn" or command == "editor_actor_visual_spawn" or command == "hektor_visual_spawn" then
    local saved, message, data = worldEditVisualSpawnStage(text, command, id)
    if saved then return ok(command, message, data or "{}", id) end
    return failWithData(command, message or "World edit visual spawn failed", data or "{}", id)
  end

  if command == "world_edit_create_entity_lab" or command == "world_edit_server_only_create_entity" then
    local sent, message, data = worldEditCreateEntityLab(text, id)
    if sent then return ok(command, message, data or "{}", id) end
    return failWithData(command, message or "World edit CreateEntity lab failed", data or "{}", id)
  end

  if command == "editor_actor_stage_batch" or command == "hektor_stage_batch" then
    local batchText = extractStringAny(text, { "batch", "stagedBatch", "payload" }) or text
    local directCloneEnabled = configBool("bridge-safety", { "EnableActorEditorStagedDirectCloneApply", "enableActorEditorStagedDirectCloneApply" }, false) == true
    local nativePlaceableEnabled = configBool("bridge-safety", { "EnableActorEditorStagedNativePlaceableApply", "enableActorEditorStagedNativePlaceableApply" }, false) == true
    local proxyEnabled = configBool("bridge-safety", { "EnableActorEditorStagedProxyApply", "enableActorEditorStagedProxyApply" }, false) == true
    if directCloneEnabled then
      local record = '{"utc":' .. js(nowUtc()) ..
        ',"id":' .. js(id) ..
        ',"command":' .. js(command) ..
        ',"status":"staged-direct-clone-blocked-after-hang"' ..
        ',"message":"Direct clone apply was requested but is blocked after the 2026-06-06 SCUMServer hang finding."' ..
        ',"apply":{"mode":"blocked","applied":0,"gameplayApplied":false,"blockReason":"direct-clone-disabled-after-hang"}' ..
        ',"payload":' .. js(text) .. '}'
      local saved = appendJsonArray(EDITOR_ACTOR_STAGED_BATCHES_FILE, record, 4 * 1024 * 1024)
      local data = '{"ok":false' ..
        ',"stage":"staged-direct-clone-blocked-after-hang"' ..
        ',"mode":"blocked"' ..
        ',"path":' .. js(EDITOR_ACTOR_STAGED_BATCHES_FILE) ..
        ',"saved":' .. tostring(saved == true) ..
        ',"applied":0' ..
        ',"gameplayApplied":false' ..
        ',"vanillaVisible":false' ..
        ',"restartPersistent":false' ..
        ',"blockReason":"direct-clone-disabled-after-hang"' ..
        ',"message":"Actor editor direct clone apply is blocked after the 2026-06-06 SCUMServer hang. Use familyCommitAdapter routes only."}'
      return failWithData(command, "Actor editor direct clone apply blocked after SCUMServer hang", data, id)
    end
    if nativePlaceableEnabled then
      local queueMessage = "Actor editor native-placeable/craft route is retired for world-edit. It is standard SCUM base building, not arbitrary map/building placement. Store the batch in the client overlay journal instead."
      local queueData = '{"enabled":true,"mode":"native-placeable-retired","blocked":true,"gameplayApplied":false,"vanillaVisible":false,"restartPersistent":false,"blockReason":"craft-godmod-is-not-world-edit","requiresClientOverlay":true}'
      local record = '{"utc":' .. js(nowUtc()) ..
        ',"id":' .. js(id) ..
        ',"command":' .. js(command) ..
        ',"status":"staged-native-placeable-retired-blocked"' ..
        ',"message":' .. js(queueMessage or "") ..
        ',"apply":' .. tostring(queueData or "{}") ..
        ',"payload":' .. js(text) .. '}'
      local saved = appendJsonArray(EDITOR_ACTOR_STAGED_BATCHES_FILE, record, 4 * 1024 * 1024)
      local data = '{"ok":false' ..
        ',"stage":"staged-native-placeable-retired-blocked"' ..
        ',"path":' .. js(EDITOR_ACTOR_STAGED_BATCHES_FILE) ..
        ',"saved":' .. tostring(saved == true) ..
        ',"apply":' .. tostring(queueData or "{}") ..
        ',"message":' .. js(queueMessage or "Actor editor batch blocked before native placeable apply.") .. '}'
      return failWithData(command, queueMessage or "Actor editor batch blocked before native placeable apply.", data, id)
    end
    if proxyEnabled then
      local safeCdoProxyEnabled = configBool("bridge-safety", { "EnableActorEditorStagedSafeCdoVisualProxyApply", "enableActorEditorStagedSafeCdoVisualProxyApply" }, false) == true
      if safeCdoProxyEnabled then
        local proxyData = hektorStagedProxyApply(batchText, id)
        local applied = tonumber(tostring(proxyData or ""):match('"applied"%s*:%s*(%d+)') or "0") or 0
        local existing = tonumber(tostring(proxyData or ""):match('"existing"%s*:%s*(%d+)') or "0") or 0
        local gameplayApplied = (applied + existing) > 0
        local proxySummary = '{"mode":"persistent-cdo-visual-proxy"' ..
          ',"applied":' .. tostring(applied) ..
          ',"existing":' .. tostring(existing) ..
          ',"gameplayApplied":' .. tostring(gameplayApplied) ..
          ',"vanillaVisible":' .. tostring(gameplayApplied) ..
          ',"restartPersistent":' .. tostring(gameplayApplied) ..
          ',"detailsStoredIn":"action-log-and-persistent-actors"}'
        local record = '{"utc":' .. js(nowUtc()) ..
          ',"id":' .. js(id) ..
          ',"command":' .. js(command) ..
          ',"status":"staged-safe-cdo-visual-proxy-apply"' ..
          ',"message":"Staged actor batch applied through native CDO-pre-spawn StaticMeshActor visual proxy route."' ..
          ',"apply":' .. proxySummary ..
          ',"payload":' .. js(text) .. '}'
        local saved = appendJsonArray(EDITOR_ACTOR_STAGED_BATCHES_FILE, record, 4 * 1024 * 1024)
        if saved then flushStateArrayCache(EDITOR_ACTOR_STAGED_BATCHES_FILE) end
        local data = '{"ok":' .. tostring(gameplayApplied) ..
          ',"stage":"staged-safe-cdo-visual-proxy-apply"' ..
          ',"mode":"persistent-cdo-visual-proxy"' ..
          ',"path":' .. js(EDITOR_ACTOR_STAGED_BATCHES_FILE) ..
          ',"saved":' .. tostring(saved == true) ..
          ',"applied":' .. tostring(applied) ..
          ',"existing":' .. tostring(existing) ..
          ',"gameplayApplied":' .. tostring(gameplayApplied) ..
          ',"vanillaVisible":' .. tostring(gameplayApplied) ..
          ',"restartPersistent":' .. tostring(gameplayApplied) ..
          ',"apply":' .. proxySummary ..
          ',"message":"Actor editor batch used the native CDO-pre-spawn StaticMeshActor visual proxy route. Copy preview keeps the original actor visible; move records are still represented as persistent visual copy when enabled."}'
        if gameplayApplied then return ok(command, "Actor editor staged visual proxy applied", data, id) end
        return failWithData(command, "Actor editor staged visual proxy apply failed", data, id)
      end
      local data = '{"ok":false' ..
        ',"stage":"staged-proxy-blocked-after-hang"' ..
        ',"mode":"blocked"' ..
        ',"applied":0' ..
        ',"gameplayApplied":false' ..
        ',"vanillaVisible":false' ..
        ',"restartPersistent":false' ..
        ',"blockReason":"generic-staticmesh-proxy-disabled-after-hang"' ..
        ',"message":"Generic StaticMeshActor proxy apply is blocked after the 2026-06-06 SCUMServer hang. Use familyCommitAdapter routes only."}'
      return failWithData(command, "Actor editor proxy apply blocked after SCUMServer hang", data, id)
    end
    local record = '{"utc":' .. js(nowUtc()) ..
      ',"id":' .. js(id) ..
      ',"command":' .. js(command) ..
      ',"status":"journal-only"' ..
      ',"message":"Batch stored as intent only. No gameplay apply route is enabled without a proven SCUM persistence family."' ..
      ',"apply":{"mode":"journal-only","applied":0,"gameplayApplied":false,"vanillaVisible":false,"restartPersistent":false}' ..
      ',"payload":' .. js(text) .. '}'
    local saved = appendJsonArray(EDITOR_ACTOR_STAGED_BATCHES_FILE, record, 4 * 1024 * 1024)
    local data = '{"ok":' .. tostring(saved) ..
      ',"stage":"journal-only"' ..
      ',"mode":"journal-only"' ..
      ',"path":' .. js(EDITOR_ACTOR_STAGED_BATCHES_FILE) ..
      ',"applied":0' ..
      ',"gameplayApplied":false' ..
      ',"vanillaVisible":false' ..
      ',"restartPersistent":false' ..
      ',"selectedCanBeAnyActor":true' ..
      ',"requiresFamilyCommitAdapter":true' ..
      ',"message":"Actor editor batch stored as journal-only intent. No server gameplay apply was attempted."}'
    if saved then return ok(command, "Actor editor batch stored as journal-only intent", data, id) end
    return failWithData(command, "Actor editor batch stage failed", data, id)
  end

  if command == "native_actor_editor_move" or command == "editor_actor_move" or
    command == "native_actor_editor_nudge" or command == "editor_actor_nudge" or
    command == "hektor_nudge_actor" or command == "hektor_actor_nudge" or command == "server_actor_editor_nudge" or
    command == "native_actor_editor_copy" or command == "editor_actor_copy" or
    command == "hektor_copy_actor" or command == "hektor_actor_copy" or command == "server_actor_editor_copy" or
    command == "native_actor_editor_hide" or command == "editor_actor_hide" or
    command == "native_actor_editor_remove" or command == "editor_actor_remove" or
    command == "hektor_hide_actor" or command == "hektor_remove_actor" or command == "hektor_actor_hide" or command == "server_actor_editor_hide" then
    if configBool("bridge-safety", { "EnableActorEditorServerMutation", "enableActorEditorServerMutation" }, false) ~= true then
      local data = '{"ok":false,"blocked":true,"stage":"actor-editor-server-mutation-disabled","route":"hektor-server-actor-editor","message":"Actor editor server mutation is disabled after the 2026-06-05 14:31Z SCUMServer crash. Do not move/copy/hide streamed map actors until a safe SCUM lifecycle route is proven offline."}'
      return failWithData(command, "Actor editor server mutation disabled after crash", data, id)
    end
  end

  if command == "native_actor_editor_move" or command == "editor_actor_move" then
    local payload = actorEditorAugmentPayloadWithServerTarget(text, runtimeKey)
    local sent, message, data = nativeTraderCommandAsync(command, "native_actor_editor_move", payload, 8000, id, function(okNative, _, nativeResult)
      if okNative then rememberEditorActorNativeResult("move", payload, nativeResult) end
    end)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "native_actor_editor_nudge" or command == "editor_actor_nudge" then
    local payload = actorEditorAugmentPayloadWithServerTarget(text, runtimeKey)
    local sent, message, data = nativeTraderCommandAsync(command, "native_actor_editor_nudge", payload, 9000, id, function(okNative, _, nativeResult)
      if okNative then rememberEditorActorNativeResult("nudge", payload, nativeResult) end
    end)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

  if command == "hektor_nudge_actor" or command == "hektor_actor_nudge" or command == "server_actor_editor_nudge" then
    local payload, payloadMessage = hektorEditorPayload(text, runtimeKey, "MOVE_WORLD_ACTOR")
    if payload == nil then return fail(command, payloadMessage or "Hektor editor payload failed.", id) end
    payload = actorEditorAugmentPayloadWithServerTarget(payload, runtimeKey)
    local sent, message, data = nativeTraderCommandAsync(command, "native_actor_editor_nudge", payload, 10000, id, function(okNative, _, nativeResult)
      if okNative then rememberEditorActorNativeResult("nudge", payload, nativeResult) end
    end)
    if sent then return ok(command, message, data or "{}", id) end
    if sent == nil and data == "__async__" then return nil end
    return fail(command, message, id)
  end

