    if queued then
      return ok(command, "Команда плагина поставлена в очередь.", '{"queued":true,"queueId":' .. tostring(queueIdOrMessage) .. ',"depth":' .. tostring(depth or 0) .. ',"message":' .. js(message) .. '}')
