  if command == "admin_exec" then
    local commandText = extractString(text, "commandText") or extractString(text, "command") or ""
    local requestId = id
    local waitForExecution = tostring(requestId or "") ~= "" and extractBoolAny(text, { "waitForExecution", "WaitForExecution", "sync", "Sync" }, false) == true
    local steamId = extractString(text, "steamId")
    local name = extractString(text, "name")
    local hasPanelTarget = tostring(steamId or "") ~= "" or tostring(name or "") ~= "" or tostring(runtimeKey or "") ~= ""
    local verb = commandVerb(commandText)
    if not hasPanelTarget and type(refreshPlayerInfoCacheForPanel) == "function" then
      refreshPlayerInfoCacheForPanel("admin-exec-bare", false)
    end
    local info = nil
    if hasPanelTarget then
      local resolveMessage = nil
      info, resolveMessage = resolveLivePlayerInfoForPanel(steamId, name, runtimeKey, nil, "admin-exec", {
        requireLocation = adminCommandHasLocationTarget(commandText) or verb == "SpawnVehicle" or verb == "SpawnItem" or verb == "SpawnItem2",
        requirePawn = adminCommandHasLocationTarget(commandText) or verb == "SpawnVehicle" or verb == "SpawnItem" or verb == "SpawnItem2"
      })
      if info == nil then return fail(command, tostring(resolveMessage or "Игрок не найден среди реально подключённых."), requestId) end
    else
      info = resolvePlayerInfoForPanel(steamId, name, runtimeKey, nil, "admin-exec")
      if info == nil then info = findPlayer(nil, nil) end
    end
    local batchEntities = commandText:match("^%s*ScumNeDjinDestroyEntities%s+(.+)$")
    if batchEntities ~= nil then
      local sent, message, dataJson = destroyInventoryEntitiesBatch(extractString(text, "steamId"), extractString(text, "name"), runtimeKey, batchEntities)
      if sent then return ok(command, message, dataJson or "{}") end
      return fail(command, message)
    end
    local canRunWithoutLivePlayer = {
      SpawnItem = true,
      SpawnVehicle = true,
      DestroyVehicle = true,
      ChangeCurrencyBalance = true,
      SetCurrencyBalance = true,
      ChangeFamePoints = true,
      SetFamePoints = true,
      SetAttributes = true,
      SetPrisonerAttributes = true,
      SetSkillLevel = true,
      DestroyEntity = true,
      Kick = true,
      Ban = true,
      ScheduleWorldEvent = true,
      ScheduleCargoDrop = true,
      Announce = true,
      Broadcast = true,
      ListPlayers = true,
      ListSpawnedVehicles = true,
      ListSpawnedAnimals = true,
      ListMutedPlayers = true
    }
    if info == nil then info = { steam = extractString(text, "steamId") or "", name = extractString(text, "name") or "", runtimeKey = runtimeKey or "" } end
    -- Панельная консоль должна принимать любые SCUM admin-команды. Конкретный
    -- маршрут и необходимость PlayerController определит adminExec ниже.
    info = enrichPlayerInfoFromServerLog(info) or info
    local queued, queueIdOrMessage, depth = enqueueMutation("admin-exec", info, function(queueItem)
      local liveInfo = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
      local sent, message = adminExec(commandText, liveInfo)
      local effectiveQueueId = (queueItem ~= nil and queueItem.id) or queueIdOrMessage or 0
      local resultData = '{"adminCommand":' .. js(commandText) ..
        ',"queued":true,"queueId":' .. tostring(effectiveQueueId) ..
        ',"depth":' .. tostring(#(MUTATION_QUEUE or {})) ..
        ',"executed":' .. tostring(sent == true) ..
        ',"route":' .. js(message or "") .. '}'
      appendActionEvent("admin_exec_execute", sent, liveInfo, tostring(message or ""),
        resultData)
      if waitForExecution then
        if sent then
          writeAll(RESULT_FILE, ok(command, "Admin-команда отправлена в игру.", resultData, requestId))
        else
          writeAll(RESULT_FILE, failWithData(command, tostring(message or "Admin-команда не была отправлена в игру."), resultData, requestId))
        end
      end
    end)
    if queued then
      local queuedData = '{"adminCommand":' .. js(commandText) ..
        ',"queued":true,"queueId":' .. tostring(queueIdOrMessage) ..
        ',"depth":' .. tostring(depth or 0) ..
        ',"waitForExecution":' .. tostring(waitForExecution == true) .. '}'
      if waitForExecution then return nil end
      return ok(command, "Admin-команда поставлена в live-очередь.", queuedData)
    end
    return fail(command, tostring(queueIdOrMessage or "Не удалось поставить admin-команду в live-очередь."))
  end

