    local rawMessage = extractString(text, "message") or ""
    local statsUpdated, statsReason = applyServerKillFeedStats(rawMessage)
    local sent, message = broadcastServerKillFeed(rawMessage)
    if sent then return ok(command, message, '{"statsUpdated":' .. tostring(statsUpdated == true) .. ',"statsReason":' .. js(statsReason or "") .. '}') end
    if tostring(message or ""):find("filtered:", 1, true) == 1 or tostring(message or "") == "duplicate" then
      return ok(command, "Killfeed event skipped: " .. tostring(message or ""), '{"filtered":true,"statsUpdated":' .. tostring(statsUpdated == true) .. ',"statsReason":' .. js(statsReason or "") .. '}')
    end
    return fail(command, message)
  end

  if command == "chat_target" then
    if type(refreshPlayerInfoCacheForPanel) == "function" then
      refreshPlayerInfoCacheForPanel("chat-target", false)
    end
    local info, resolveMessage = resolveLivePlayerInfoForPanel(extractString(text, "targetSteamId"), extractString(text, "targetName"), extractString(text, "targetRuntimeKey") or runtimeKey, nil, "chat-target")
    if info == nil then return fail(command, tostring(resolveMessage or "Игрок не найден среди реально подключённых."), id) end
    local sent, message = sendTargetMessageToInfo(info, extractString(text, "message") or "", "panel-chat")
    appendActionEvent("panel_chat_target", sent == true, info,
      sent and "Сообщение отправлено игроку." or tostring(message or "Сообщение игроку не отправлено."),
      '{"source":"panel-chat","route":' .. js(message or "") .. '}')
    if sent then return ok(command, message, "{}") end
    return fail(command, message)
  end

  if command == "teleport_player" then
    local info, resolveMessage = resolveLivePlayerInfoForPanel(extractString(text, "steamId"), extractString(text, "name"), runtimeKey, nil, "teleport-player", { requirePawn = true })
    if info == nil then return fail(command, tostring(resolveMessage or "Игрок не найден среди реально подключённых."), id) end
    local sent, message = teleportResolved(info, extractNumber(text, "x") or 0, extractNumber(text, "y") or 0, extractNumber(text, "z") or 0)
    if sent then return ok(command, message, "{}") end
    return fail(command, message)
  end

  if command == "spawn_vehicle" then
    local requestId = id
    local vehicle = extractString(text, "vehicleId") or ""
    local minutes = math.max(0, math.floor(extractNumber(text, "minutes") or extractNumber(text, "rentalMinutes") or extractNumber(text, "lifetimeMinutes") or 0))
    local rentalAlias = extractString(text, "alias") or extractString(text, "Alias") or (minutes > 0 and "panel" or "")
    local rentalDisplayName = extractString(text, "displayName") or extractString(text, "DisplayName") or tostring(vehicle)
    local rentalSource = extractString(text, "source") or extractString(text, "Source") or (minutes > 0 and "panel-spawn" or "")
    local rentalMessage = extractString(text, "messageOverride") or extractString(text, "SuccessMessage") or extractString(text, "successMessage") or ""
    local rentalMissingPenalty = extractNumberAny(text, { "missingVehiclePenalty", "MissingVehiclePenalty", "soldVehiclePenalty", "SoldVehiclePenalty", "salePenalty", "SalePenalty" }, nil)
    local steamId = extractString(text, "steamId")
    local name = extractString(text, "name")
    local info, resolveMessage = resolveLivePlayerInfoForPanel(steamId, name, runtimeKey, nil, "spawn-vehicle", { requireLocation = true, requirePawn = true })
    if info == nil then return fail(command, tostring(resolveMessage or "Игрок не найден среди реально подключённых."), requestId) end
    if type(vehicleRentalSpawnCooldownRemaining) == "function" then
      local waitSeconds = vehicleRentalSpawnCooldownRemaining(info)
      if waitSeconds > 0 then
        return fail(command, "Спавн транспорта сейчас в безопасной паузе. Подожди " .. tostring(waitSeconds) .. " сек.", requestId)
      end
    end
    local queued, queueIdOrMessage, depth = enqueueMutation("spawn-vehicle", info, function(queueItem)
      local live, liveMessage = resolveLivePlayerInfoForPanel(steamId, name, runtimeKey, info, "spawn-vehicle-execute", { requireLocation = true, requirePawn = true })
      if live == nil then
        writeAll(RESULT_FILE, fail(command, tostring(liveMessage or "Игрок не найден среди реально подключённых."), requestId))
        return
      end
      local scheduled, scheduleMessage = spawnVehicleForInfoAsync(vehicle, live, {
        requireForwardLocation = minutes > 0,
        source = minutes > 0 and "panel-timed-vehicle" or "panel-spawn-vehicle"
      }, function(sent, message, runtimeRef, beforeVehicles)
        if vehicleSpawnAsyncQueueIsStale(queueItem, "panel-spawn-vehicle") then return end
        if not sent then
          writeAll(RESULT_FILE, fail(command, message, requestId))
          finishMutationQueueAsync(queueItem, false, tostring(message or "Транспорт не выдан."))
          return
        end
        local expiresAt = 0
        if minutes > 0 then
          local startedAt = os.time()
          expiresAt = startedAt + minutes * 60
          local extraFields = ',"manualGrant":true,"source":' .. js(rentalSource ~= "" and rentalSource or "panel-spawn")
          if rentalSource == "welcome-pack" then extraFields = extraFields .. ',"freeWelcomeRental":true' end
          appendActiveRentalRecord(live, rentalAlias ~= "" and rentalAlias or "panel", rentalDisplayName ~= "" and rentalDisplayName or tostring(vehicle), tostring(vehicle), minutes, startedAt, expiresAt, 0, 0, 0, runtimeRef or "",
            extraFields, rentalMissingPenalty)
          appendActionEvent("spawn_vehicle_timed", true, live, "Транспорт выдан с автоудалением по времени.",
            '{"vehicleId":' .. js(vehicle) .. ',"minutes":' .. tostring(minutes) .. ',"runtimeRef":' .. js(runtimeRef or "") .. ',"source":' .. js(rentalSource) .. ',"missingVehiclePenalty":' .. tostring(tonumber(rentalMissingPenalty or 0) or 0) .. '}')
          if rentalMessage ~= "" then
            targetMessage(live.steam, live.name, rentalMessage, "vehicle-rental", live.runtimeKey)
          end
        end
        if tostring(runtimeRef or "") ~= "" then
          writeAll(RESULT_FILE, ok(command, message, '{"vehicleId":' .. js(vehicle) .. ',"runtimeRef":' .. js(runtimeRef or "") .. ',"verified":true,"minutes":' .. tostring(minutes) .. ',"expiresAt":' .. tostring(expiresAt) .. '}', requestId))
          finishMutationQueueAsync(queueItem, true, "Транспорт из панели подтверждён.")
          return
        end
        appendActionEvent("spawn_vehicle_pending_verify", true, live, "spawn command accepted; native vehicle tracking is pending",
          '{"vehicleId":' .. js(vehicle) .. '}')
        writeAll(RESULT_FILE, ok(command, message, '{"vehicleId":' .. js(vehicle) .. ',"runtimeRef":"","verified":false,"route":"admin-command","minutes":' .. tostring(minutes) .. ',"expiresAt":' .. tostring(expiresAt) .. '}', requestId))
        finishMutationQueueAsync(queueItem, true, "Команда транспорта из панели отправлена без подтверждённого EntityID.")
      end)
      if not scheduled then
        writeAll(RESULT_FILE, fail(command, tostring(scheduleMessage or "Не удалось запланировать безопасный спавн транспорта."), requestId))
        return
      end
      return "__mutation_async__"
    end)
    if queued and type(reserveVehicleRentalSpawnCooldown) == "function" then reserveVehicleRentalSpawnCooldown(info) end
    if not queued then return fail(command, tostring(queueIdOrMessage or "Не удалось поставить выдачу транспорта в live-очередь."), requestId) end
    appendActionEvent("spawn_vehicle", true, info, "Выдача транспорта поставлена в live-очередь.",
      '{"vehicleId":' .. js(vehicle) .. ',"queueId":' .. tostring(queueIdOrMessage or 0) .. ',"depth":' .. tostring(depth or 0) .. '}')
    return nil
  end

  if command == "zombie_transform" or command == "zombie_infect" then
    return fail(command, "Zombie/model-swap route removed from the public release.", id)
