    local meshPath = extractStringAny(text, { "meshPath", "MeshPath", "ZombieMeshPath" }) or ""
    local gender = extractStringAny(text, { "gender", "Gender", "modelGender", "ModelGender", "playerModel", "PlayerModel" }) or ""
    local transformMode = extractStringAny(text, { "transformMode", "TransformMode", "mode", "Mode" }) or ""
    local message = extractStringAny(text, { "message", "Message", "playerMessage", "PlayerMessage" }) or ""
    local announce = extractBoolAny(text, { "announce", "Announce" }, nil)
    local whisper = extractBoolAny(text, { "whisper", "Whisper" }, nil)
    appendLog("zombie_transform payload gender=" .. tostring(gender) .. " transformMode=" .. tostring(transformMode) .. " meshPath=" .. tostring(meshPath))
    local info = resolvePlayerInfo(steamId, name, nil, runtimeKey) or { steam = steamId or "", name = name or "", runtimeKey = runtimeKey or "" }
    local queued, queueIdOrMessage, depth = enqueueMutation("zombie-transform", info, function()
      local okRun, sent, resultMessage, data = pcall(function()
        return transformPlayerToZombie(steamId, name, runtimeKey, meshPath, message, announce, whisper, gender, transformMode)
      end)
      if okRun and sent then
        writeAll(RESULT_FILE, ok("zombie_transform", resultMessage, data or "{}", requestId))
      elseif okRun then
        writeAll(RESULT_FILE, fail("zombie_transform", resultMessage, requestId))
      else
        writeAll(RESULT_FILE, fail("zombie_transform", tostring(sent), requestId))
      end
    end)
    if not queued then return fail(command, tostring(queueIdOrMessage or "Не удалось поставить превращение в live-очередь."), requestId) end
    appendActionEvent("zombie_transform_queue", true, info, "Превращение поставлено в live-очередь.",
      '{"queueId":' .. tostring(queueIdOrMessage or 0) .. ',"depth":' .. tostring(depth or 0) .. ',"meshPath":' .. js(meshPath) .. ',"gender":' .. js(gender) .. ',"mode":' .. js(transformMode) .. '}')
    return nil
  end

