    local liftZ = extractNumberAny(text, { "liftZ", "zOffset", "LiftZ", "ZOffset" }, nil)
    local yaw = extractNumberAny(text, { "yaw", "Yaw", "rotationYaw", "RotationYaw" }, nil)
    local x = extractNumberAny(text, { "x", "X", "locationX", "LocationX", "worldX", "WorldX" }, nil)
    local y = extractNumberAny(text, { "y", "Y", "locationY", "LocationY", "worldY", "WorldY" }, nil)
    local z = extractNumberAny(text, { "z", "Z", "locationZ", "LocationZ", "worldZ", "WorldZ" }, nil)
    local absoluteLocation = nil
    if x ~= nil and y ~= nil and z ~= nil then absoluteLocation = { X = x, Y = y, Z = z } end
    local info = resolvePlayerInfo(steamId, name, nil, runtimeKey) or { steam = steamId or "", name = name or "", runtimeKey = runtimeKey or "" }
    local queued, queueIdOrMessage, depth = enqueueMutation("native-placeable-spawn", info, function()
