    end)
    if not queued then return fail(command, tostring(queueIdOrMessage or "Не удалось поставить пакет предметов в live-очередь."), requestId) end
    appendActionEvent("deliver_items_batch", true, info, "Пакет предметов поставлен в live-очередь.",
      '{"queueId":' .. tostring(queueIdOrMessage or 0) .. ',"depth":' .. tostring(depth or 0) .. '}')
    return nil
  end

  if command == "change_money" then
    local amount = extractNumber(text, "amount") or 0
    local info, resolveMessage = resolveLivePlayerInfoForPanel(extractString(text, "steamId"), extractString(text, "name"), runtimeKey, nil, "change-money", { requirePawn = true, requireSteam = true })
    if info == nil then return fail(command, tostring(resolveMessage or "Игрок не найден среди реально подключённых."), id) end
    local sent, message = changeMoney(info.steam, info.name, amount, extractString(text, "currency"), info.runtimeKey)
    if sent then return ok(command, message, '{"amount":' .. tostring(amount) .. '}') end
    return fail(command, message)
  end

  if command == "set_fame" then
    local amount = extractNumber(text, "amount") or 0
    local info, resolveMessage = resolveLivePlayerInfoForPanel(extractString(text, "steamId"), extractString(text, "name"), runtimeKey, nil, "set-fame", { requirePawn = true, requireSteam = true })
    if info == nil then return fail(command, tostring(resolveMessage or "Игрок не найден среди реально подключённых."), id) end
    local sent, message = setFame(info.steam, info.name, amount, info.runtimeKey)
    if sent then return ok(command, message, '{"amount":' .. tostring(amount) .. '}') end
    return fail(command, message)
  end

  if command == "change_fame" then
    local amount = extractNumber(text, "amount") or 0
    local info, resolveMessage = resolveLivePlayerInfoForPanel(extractString(text, "steamId"), extractString(text, "name"), runtimeKey, nil, "change-fame", { requirePawn = true, requireSteam = true })
    if info == nil then return fail(command, tostring(resolveMessage or "Игрок не найден среди реально подключённых."), id) end
    local sent, message = changeFamePoints(info.steam, info.name, amount, info.runtimeKey)
    if sent then return ok(command, message, '{"amount":' .. tostring(amount) .. '}') end
    return fail(command, message)
  end

  if command == "clear_inventory" then
    local info, resolveMessage = resolveLivePlayerInfoForPanel(extractString(text, "steamId"), extractString(text, "name"), runtimeKey, nil, "clear-inventory", { requirePawn = true, requireSteam = true })
    if info == nil then return fail(command, tostring(resolveMessage or "Игрок не найден среди реально подключённых."), id) end
    local sent, message = clearInventory(info.steam, info.name, info.runtimeKey)
    if sent then return ok(command, message, "{}") end
    return fail(command, message)
  end

  if command == "delete_inventory_item" then
    local deleteInfo, deleteResolveMessage = resolveLivePlayerInfoForPanel(extractString(text, "steamId"), extractString(text, "name"), runtimeKey, nil, "delete-inventory-item", { requirePawn = true, requireSteam = true })
    if deleteInfo == nil then return fail(command, tostring(deleteResolveMessage or "Игрок не найден среди реально подключённых."), id) end
    local sent, message = deleteInventoryItem(
      deleteInfo.steam,
      deleteInfo.name,
      deleteInfo.runtimeKey,
      extractStringAny(text, { "entityId", "itemEntityId", "runtimeId" }) or "",
      extractStringAny(text, { "itemId", "ItemId" }) or "",
      extractStringAny(text, { "itemClass", "classPath" }) or "",
      extractStringAny(text, { "itemEntitySetup", "assetPath" }) or "")
    if sent then return ok(command, message, "{}") end
    return fail(command, message)
  end

  if command == "add_inventory_item" then
    local requestId = id
    local itemId = extractStringAny(text, { "itemId", "ItemId" }) or ""
    local quantity = extractNumber(text, "quantity") or extractNumber(text, "Quantity") or 1
    local steamId = extractString(text, "steamId")
    local name = extractString(text, "name")
    local info, resolveMessage = resolveLivePlayerInfoForPanel(steamId, name, runtimeKey, nil, "add-inventory-item", { requireLocation = true, requirePawn = true, requireSteam = true })
    if info == nil then return fail(command, tostring(resolveMessage or "Игрок не найден среди реально подключённых."), requestId) end
    if configBool("bridge-safety", { "BlockInventoryInsertDuringSkillBatch", "blockInventoryInsertDuringSkillBatch" }, true) == true and skillBatchHasPlayer(info) then
      local message = "Игроку сейчас выдаются навыки. Дождись окончания очереди перед добавлением предмета в инвентарь."
      appendActionEvent("add_inventory_item", false, info, message,
        '{"itemId":' .. js(itemId) .. ',"quantity":' .. tostring(quantity) .. ',"reason":"skill-batch-active"}')
      return fail(command, message, requestId)
    end
    local queued, queueIdOrMessage, depth = enqueueMutation("add-inventory-item", info, function()
      local okAdd, sent, message, data = pcall(function()
        local live, liveMessage = resolveLivePlayerInfoForPanel(steamId, name, runtimeKey, info, "add-inventory-item-execute", { requireLocation = true, requirePawn = true, requireSteam = true })
        if live == nil then return false, tostring(liveMessage or "Игрок не найден среди реально подключённых."), "{}" end
        return addInventoryItemForInfo(live, live.steam, live.name, itemId, quantity, live.runtimeKey)
      end)
      if okAdd and sent then
        writeAll(RESULT_FILE, ok(command, message, data or "{}", requestId))
      elseif okAdd then
        writeAll(RESULT_FILE, fail(command, message, requestId))
      else
        writeAll(RESULT_FILE, fail(command, tostring(sent), requestId))
      end
    end)
    if not queued then return fail(command, tostring(queueIdOrMessage or "Не удалось поставить добавление предмета в инвентарь в live-очередь."), requestId) end
    appendActionEvent("add_inventory_item", true, info, "Добавление предмета в инвентарь поставлено в live-очередь.",
      '{"itemId":' .. js(itemId) .. ',"quantity":' .. tostring(quantity) .. ',"queueId":' .. tostring(queueIdOrMessage or 0) .. ',"depth":' .. tostring(depth or 0) .. '}')
    return nil
  end

  if command == "set_attributes" then
    local attrInfo, attrResolveMessage = resolveLivePlayerInfoForPanel(extractString(text, "steamId"), extractString(text, "name"), runtimeKey, nil, "set-attributes", { requirePawn = true, requireSteam = true })
    if attrInfo == nil then return fail(command, tostring(attrResolveMessage or "Игрок не найден среди реально подключённых."), id) end
    local sent, message = setAttributes(
      attrInfo.steam,
      attrInfo.name,
      extractNumber(text, "strength") or extractNumber(text, "Strength") or 0,
      extractNumber(text, "constitution") or extractNumber(text, "Constitution") or 0,
      extractNumber(text, "dexterity") or extractNumber(text, "Dexterity") or 0,
      extractNumber(text, "intelligence") or extractNumber(text, "Intelligence") or 0,
      extractBool(text, "suppressActionLog", false),
      attrInfo.runtimeKey)
    if sent then return ok(command, message, "{}") end
    return fail(command, message)
  end

  if command == "set_skill" then
    local requestedSkill = extractString(text, "skill") or extractString(text, "skillName") or ""
    local level = extractNumber(text, "level") or extractNumber(text, "skillLevel") or 0
    local experience = extractNumber(text, "experience") or extractNumber(text, "skillExperience") or 0
    local skillInfo, skillResolveMessage = resolveLivePlayerInfoForPanel(extractString(text, "steamId"), extractString(text, "name"), runtimeKey, nil, "set-skill", { requirePawn = true, requireSteam = true })
    if skillInfo == nil then return fail(command, tostring(skillResolveMessage or "Игрок не найден среди реально подключённых."), id) end
    if allSkillsKeyword(requestedSkill) or extractBoolAny(text, { "allSkills", "AllSkills", "giveAllSkills", "GiveAllSkills" }, false) == true then
      if level <= 0 then level = 4 end
      local sent, message = setAllSkills(skillInfo.steam, skillInfo.name, level, experience, skillInfo.runtimeKey)
      if sent then return ok(command, message, "{}") end
      return fail(command, message)
    end
    local sent, message = setSkill(skillInfo.steam, skillInfo.name, requestedSkill, level, experience, skillInfo.runtimeKey)
    if sent then return ok(command, message, "{}") end
    return fail(command, message)
  end

  if command == "apply_character_pack" then
    local packInfo, packResolveMessage = resolveLivePlayerInfoForPanel(extractString(text, "steamId"), extractString(text, "name"), runtimeKey, nil, "apply-character-pack", { requirePawn = true, requireSteam = true })
    if packInfo == nil then return fail(command, tostring(packResolveMessage or "Игрок не найден среди реально подключённых."), id) end
    local sent, message, data = applyCharacterPackForInfo(packInfo, extractString(text, "pack") or extractString(text, "packName") or "fullstats")
    if sent then return ok(command, message, data or "{}") end
    return fail(command, message)
  end

  return fail(command, "Неизвестная команда bridge.")
end

