function configText(key)
  local safeKey = tostring(key or ""):gsub("[^%w%-%_]", "")
  if safeKey == "" then return "" end
  local paths = {
    CONFIG_OVERLAY_DIR .. "\\" .. safeKey .. ".json",
    LEGACY_CONFIG_OVERLAY_DIR .. "\\" .. safeKey .. ".json",
    CONFIG_DIR .. "\\" .. safeKey .. ".json",
    LEGACY_CONFIG_DIR .. "\\" .. safeKey .. ".json"
  }
  for _, path in ipairs(paths) do
    local liveText = readAll(path .. ".live")
    if liveText ~= nil and tostring(liveText):match("^%s*[%{%[]") ~= nil then return liveText end
    local text = readAll(path)
    if text ~= nil and tostring(text):match("^%s*[%{%[]") ~= nil then return text end
  end
  return ""
end

function configNumber(key, names, fallback)
  local text = configText(key)
  for _, name in ipairs(names) do
    local value = numberField(text, name, nil)
    if value ~= nil then return value end
  end
  return fallback
end

function luaPatternEscape(text)
  return tostring(text or ""):gsub("([^%w])", "%%%1")
end

function configBool(key, names, fallback)
  local text = configText(key)
  local bestStart = nil
  local bestRaw = nil
  for _, name in ipairs(names) do
    local safeName = luaPatternEscape(name)
    local trueStart, _, trueRaw = text:find('"' .. safeName .. '"%s*:%s*(true)')
    if trueStart ~= nil and (bestStart == nil or trueStart < bestStart) then
      bestStart = trueStart
      bestRaw = trueRaw
    end
    local falseStart, _, falseRaw = text:find('"' .. safeName .. '"%s*:%s*(false)')
    if falseStart ~= nil and (bestStart == nil or falseStart < bestStart) then
      bestStart = falseStart
      bestRaw = falseRaw
    end
  end
  if bestRaw == "true" then return true end
  if bestRaw == "false" then return false end
  return fallback
end

function configString(key, names, fallback)
  local text = configText(key)
  local value = extractStringAny(text, names)
  if value ~= nil then return value end
  return fallback or ""
end

VIP_STATE_FILE = "vip-members.json"
VIP_DEFAULT_PERMISSIONS = { "vip.active", "welcome-pack.vip", "sethome.vip", "daily-pack.vip", "battlepass.vip", "sector-scan.vip", "vehicle-rental.vip", "base-loot.vip" }

function vipTrim(value)
  return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

function vipConfig()
  return configText("vip-system")
end

function vipConfigPath()
  return CONFIG_DIR .. "\\vip-system.json"
end

function vipModuleEnabled()
  return configBool("vip-system", { "Enabled", "enabled" }, true) ~= false
end

function vipEpochFromText(value)
  if value == nil then return nil end
  local text = vipTrim(value)
  if text == "" then return nil end
  local numeric = tonumber(text)
  if numeric ~= nil then return math.floor(numeric) end
  local y, mo, d, h, mi, s = text:match("^(%d%d%d%d)%-(%d%d)%-(%d%d)[T%s]+(%d%d):(%d%d):?(%d*)")
  if y ~= nil then
    return os.time({
      year = tonumber(y),
      month = tonumber(mo),
      day = tonumber(d),
      hour = tonumber(h) or 0,
      min = tonumber(mi) or 0,
      sec = tonumber(s) or 0
    })
  end
  y, mo, d = text:match("^(%d%d%d%d)%-(%d%d)%-(%d%d)$")
  if y ~= nil then
    return os.time({ year = tonumber(y), month = tonumber(mo), day = tonumber(d), hour = 23, min = 59, sec = 59 })
  end
  return nil
end

function vipEpochField(object, names)
  for _, key in ipairs(names or {}) do
    local numberValue = extractNumber(object, key)
    if numberValue ~= nil then return math.floor(numberValue) end
    local stringValue = extractString(object, key)
    local epoch = vipEpochFromText(stringValue)
    if epoch ~= nil then return epoch end
  end
  return nil
end

function vipObjectMatchesInfo(info, object)
  if info == nil then return false end
  local steam = vipTrim((info or {}).steam or (info or {}).steamId)
  local profile = vipTrim((info or {}).userProfileId or (info or {}).serverUserProfileId)
  local name = vipTrim((info or {}).name)
  local objectSteam = vipTrim(extractStringAny(object, { "SteamId", "steamId", "SteamID", "steamID", "Steam", "steam" }))
  local objectProfile = vipTrim(extractStringAny(object, { "UserProfileId", "userProfileId", "ProfileId", "profileId" }))
  local objectName = vipTrim(extractStringAny(object, { "Name", "name", "PlayerName", "playerName" }))
  if steam ~= "" and objectSteam ~= "" then return steam == objectSteam end
  if profile ~= "" and objectProfile ~= "" then return profile == objectProfile end
  if steam ~= "" or objectSteam ~= "" or profile ~= "" or objectProfile ~= "" then return false end
  return name ~= "" and objectName ~= "" and name:lower() == objectName:lower()
end

function vipObjectActive(object, now)
  if object == nil then return false end
  if extractBoolAny(object, { "Enabled", "enabled", "Active", "active" }, true) == false then return false end
  local status = vipTrim(extractStringAny(object, { "Status", "status" }) or ""):lower()
  if status == "revoked" or status == "disabled" or status == "cancelled" or status == "expired" then return false end
  local startsAt = vipEpochField(object, { "StartsAt", "startsAt", "StartedAt", "startedAt", "StartsAtUtc", "startsAtUtc" }) or 0
  local expiresAt = vipEpochField(object, { "ExpiresAt", "expiresAt", "ExpiresAtUtc", "expiresAtUtc", "Until", "until" })
  if expiresAt == nil then return false end
  now = tonumber(now or os.time()) or os.time()
  return startsAt <= now and expiresAt > now
end

function vipActiveRecordForInfo(info)
  if not vipModuleEnabled() then return nil end
  local now = os.time()
  local best = nil
  local bestExpires = 0
  local function consider(object, source)
    if vipObjectMatchesInfo(info, object) and vipObjectActive(object, now) then
      local expiresAt = vipEpochField(object, { "ExpiresAt", "expiresAt", "ExpiresAtUtc", "expiresAtUtc", "Until", "until" }) or 0
      if expiresAt > bestExpires then
        bestExpires = expiresAt
        best = { object = object, source = source, expiresAt = expiresAt }
      end
    end
  end
  for _, object in ipairs(jsonArrayObjects(vipConfig(), "Members")) do consider(object, "config") end
  for _, object in ipairs(jsonArrayObjects(vipConfig(), "members")) do consider(object, "config") end
  return best
end

function vipActiveForInfo(info)
  return vipActiveRecordForInfo(info) ~= nil
end

function vipFeatureObject(feature)
  local features = jsonObjectForKey(vipConfig(), "Features") or jsonObjectForKey(vipConfig(), "features") or ""
  for _, key in ipairs({ feature, feature:sub(1, 1):lower() .. feature:sub(2), feature:gsub("([A-Z])", "-%1"):lower():gsub("^-", "") }) do
    local object = jsonObjectForKey(features, key)
    if object ~= nil then return object end
  end
  return nil
end

function vipFeatureEnabledForInfo(info, feature)
  if not vipActiveForInfo(info) then return false end
  local object = vipFeatureObject(feature)
  if object == nil then return false end
  return extractBoolAny(object, { "Enabled", "enabled" }, true) ~= false
end

function vipFeatureNumberForInfo(info, feature, names, fallback)
  if not vipFeatureEnabledForInfo(info, feature) then return fallback end
  local object = vipFeatureObject(feature) or ""
  return extractNumberAny(object, names, fallback)
end

function vipFeatureBoolForInfo(info, feature, names, fallback)
  if not vipFeatureEnabledForInfo(info, feature) then return fallback end
  local object = vipFeatureObject(feature) or ""
  return extractBoolAny(object, names, fallback)
end

function vipFeatureItemsSpecForInfo(info, feature)
  if not vipFeatureEnabledForInfo(info, feature) then return "" end
  local object = vipFeatureObject(feature) or ""
  local spec = extractStringAny(object, { "ItemsSpec", "itemsSpec", "ExtraItemsSpec", "extraItemsSpec" }) or ""
  if spec ~= "" then return spec end
  return itemsSpecFromConfig(object)
end

function combineItemsSpec(left, right)
  left = vipTrim(left)
  right = vipTrim(right)
  if left == "" then return right end
  if right == "" then return left end
  return left .. ";" .. right
end

function packVipSettingsObject(moduleKey)
  local text = configText(moduleKey)
  return jsonObjectForKey(text, "VipSettings") or jsonObjectForKey(text, "vipSettings") or nil
end

function packVipEnabledForInfo(info, moduleKey, feature)
  if not vipActiveForInfo(info) then return false end
  local object = packVipSettingsObject(moduleKey)
  if object ~= nil then
    if extractBoolAny(object, { "Enabled", "enabled" }, true) == false then return false end
    local required = extractStringAny(object, { "RequiredPermission", "requiredPermission" }) or "vip.active"
    if required ~= "" and not hasPermission(info, required) then return false end
    return true
  end
  return vipFeatureEnabledForInfo(info, feature)
end

function packVipCooldownHoursForInfo(info, moduleKey, feature, fallback)
  local object = packVipSettingsObject(moduleKey)
  if object ~= nil then
    if not packVipEnabledForInfo(info, moduleKey, feature) then return fallback end
    return extractNumberAny(object, { "CooldownHours", "cooldownHours" }, fallback)
  end
  return vipFeatureNumberForInfo(info, feature, { "CooldownHours", "cooldownHours" }, fallback) or fallback
end

function packVipItemsSpecForInfo(info, moduleKey, feature)
  if not packVipEnabledForInfo(info, moduleKey, feature) then return "" end
  local localSpec = vipItemsSpecFromConfig(configText(moduleKey))
  local featureSpec = vipFeatureItemsSpecForInfo(info, feature)
  return combineItemsSpec(localSpec, featureSpec)
end

function grantPackVipBonuses(info, moduleKey, feature, runtimeKey)
  if not packVipEnabledForInfo(info, moduleKey, feature) then return true, "" end
  local object = packVipSettingsObject(moduleKey) or ""
  local money = math.floor(extractNumberAny(object, { "MoneyAmount", "moneyAmount", "Money", "money" }, 0) or 0)
  local gold = math.floor(extractNumberAny(object, { "GoldAmount", "goldAmount", "Gold", "gold" }, 0) or 0)
  local fame = extractNumberAny(object, { "FameAmount", "fameAmount", "Fame", "fame" }, 0) or 0
  if money <= 0 and gold <= 0 and fame <= 0 then return true, "" end
  local live = resolvePlayerInfo(info and info.steam or "", info and info.name or "", info, runtimeKey) or info
  local selector = valueText(live and live.steam or "")
  if selector == "" or selector == "Unknown" then selector = valueText(info and info.steam or "") end
  if selector == "" or selector == "Unknown" then selector = valueText(live and live.name or "") end
  if selector == "" or selector == "Unknown" then selector = valueText(info and info.name or "") end
  if selector == "" or selector == "Unknown" then
    appendActionEvent("pack_vip_bonus", false, live or info, "missing target selector",
      '{"module":' .. js(moduleKey) .. ',"money":' .. tostring(money) .. ',"gold":' .. tostring(gold) .. ',"fame":' .. tostring(fame) .. '}')
    return false, "VIP bonus target selector missing"
  end
  local messages = {}
  local ok = true
  local function runBonus(label, amount, command)
    local sent, message = adminExec(command, live or info)
    ok = ok and sent
    table.insert(messages, tostring(label) .. "=" .. tostring(amount) .. ": " .. tostring(message))
    appendActionEvent("pack_vip_bonus_execute", sent, live or info, tostring(message or ""),
      '{"module":' .. js(moduleKey) ..
      ',"label":' .. js(label) ..
      ',"amount":' .. tostring(tonumber(amount) or 0) ..
      ',"selector":' .. js(selector) ..
      ',"command":' .. js(command) .. '}')
    appendLog("pack vip bonus command module=" .. tostring(moduleKey) ..
      " label=" .. tostring(label) ..
      " amount=" .. tostring(amount) ..
      " selector=" .. tostring(selector) ..
      " sent=" .. tostring(sent) ..
      " route=" .. tostring(message or ""))
  end
  if money > 0 then
    runBonus("money", money, "ChangeCurrencyBalance Normal " .. tostring(money) .. " " .. tostring(selector))
  end
  if gold > 0 then
    runBonus("gold", gold, "ChangeCurrencyBalance Gold " .. tostring(gold) .. " " .. tostring(selector))
  end
  if fame > 0 then
    runBonus("fame", fame, "#ChangeFamePoints " .. tostring(fame) .. " " .. tostring(selector))
  end
  appendActionEvent("pack_vip_bonus", ok, info, table.concat(messages, " || "),
    '{"module":' .. js(moduleKey) .. ',"money":' .. tostring(money) .. ',"gold":' .. tostring(gold) .. ',"fame":' .. tostring(fame) .. '}')
  return ok, table.concat(messages, " || ")
end

function vipProvidesPermission(info, required)
  local permission = vipTrim(required):lower()
  if permission == "" then return true end
  local active = vipActiveRecordForInfo(info)
  if active == nil then return false end
  local activeObject = active.object or ""
  local memberPermissions = jsonStringArrayForKey(activeObject, "Permissions")
  if #memberPermissions == 0 then memberPermissions = jsonStringArrayForKey(activeObject, "permissions") end
  if permissionListHas(memberPermissions, permission) then return true end
  local tier = vipTrim(extractStringAny(activeObject, { "Tier", "tier" }) or "vip")
  local tierPermissionsRoot = jsonObjectForKey(vipConfig(), "TierPermissions") or jsonObjectForKey(vipConfig(), "tierPermissions") or ""
  if tier ~= "" then
    local tierPermissions = jsonStringArrayForKey(tierPermissionsRoot, tier)
    if #tierPermissions == 0 then tierPermissions = jsonStringArrayForKey(tierPermissionsRoot, tier:lower()) end
    if #tierPermissions == 0 then
      local tierObject = jsonObjectForKey(tierPermissionsRoot, tier) or jsonObjectForKey(tierPermissionsRoot, tier:lower()) or ""
      tierPermissions = jsonStringArrayForKey(tierObject, "Permissions")
      if #tierPermissions == 0 then tierPermissions = jsonStringArrayForKey(tierObject, "permissions") end
    end
    if permissionListHas(tierPermissions, permission) then return true end
  end
  local configured = jsonStringArrayForKey(vipConfig(), "BasePermissions")
  if #configured == 0 then configured = jsonStringArrayForKey(vipConfig(), "basePermissions") end
  if #configured == 0 then configured = VIP_DEFAULT_PERMISSIONS end
  if permissionListHas(configured, permission) then return true end
  if permission == "welcome-pack.vip" and vipFeatureEnabledForInfo(info, "WelcomePack") then return true end
  if permission == "sethome.vip" and vipFeatureEnabledForInfo(info, "HomeSystem") then return true end
  if permission == "daily-pack.vip" and vipFeatureEnabledForInfo(info, "DailyPack") then return true end
  if permission == "battlepass.vip" and vipFeatureEnabledForInfo(info, "Battlepass") then return true end
  if permission == "sector-scan.vip" and vipFeatureEnabledForInfo(info, "SectorScan") then return true end
  if permission == "vehicle-rental.vip" and vipFeatureEnabledForInfo(info, "VehicleRental") then return true end
  return false
end

function epochUtcText(epoch)
  return os.date("!%Y-%m-%dT%H:%M:%SZ", math.floor(tonumber(epoch or os.time()) or os.time()))
end

function vipHumanUtcText(epoch)
  return os.date("!%d.%m.%Y %H:%M UTC", math.floor(tonumber(epoch or os.time()) or os.time()))
end

function replaceJsonArrayForKey(text, key, replacement)
  local source = tostring(text or "")
  local needle = '"' .. tostring(key or "") .. '"'
  local pos = source:find(needle, 1, true)
  if pos == nil then return nil end
  local colon = source:find(":", pos + #needle, true)
  if colon == nil then return nil end
  local start = source:find("[", colon + 1, true)
  if start == nil then return nil end
  local depth, inString, escaped = 0, false, false
  for i = start, #source do
    local ch = source:sub(i, i)
    if inString then
      if escaped then
        escaped = false
      elseif ch == "\\" then
        escaped = true
      elseif ch == '"' then
        inString = false
      end
    else
      if ch == '"' then
        inString = true
      elseif ch == "[" then
        depth = depth + 1
      elseif ch == "]" then
        depth = depth - 1
        if depth == 0 then
          return source:sub(1, start - 1) .. tostring(replacement or "[]") .. source:sub(i + 1)
        end
      end
    end
  end
  return nil
end

function vipMemberRecordJson(info, expiresAt, tier, source, note, existingObject)
  local target = info or {}
  local steam = vipTrim(target.steam or target.steamId)
  local name = vipTrim(target.name)
  local profile = vipTrim(target.userProfileId or target.serverUserProfileId or target.profileId)
  local permissions = jsonArrayForKey(existingObject or "", "Permissions") or jsonArrayForKey(existingObject or "", "permissions") or "[]"
  local cleanTier = vipTrim(tier)
  if cleanTier == "" then cleanTier = configString("vip-system", { "DefaultTier", "defaultTier" }, "vip") end
  return '{"Enabled":true' ..
    ',"SteamId":' .. js(steam) ..
    ',"Name":' .. js(name) ..
    ',"UserProfileId":' .. js(profile) ..
    ',"Tier":' .. js(cleanTier) ..
    ',"ExpiresAt":' .. tostring(math.floor(tonumber(expiresAt or 0) or 0)) ..
    ',"ExpiresAtUtc":' .. js(epochUtcText(expiresAt)) ..
    ',"Permissions":' .. permissions ..
    ',"Source":' .. js(source or "manual") ..
    ',"Note":' .. js(note or "") ..
    '}'
end

function upsertVipPanelMember(info, expiresAt, tier, source, note)
  local path = vipConfigPath()
  local text = readAll(path) or ""
  if vipTrim(text) == "" then
    text = '{"Enabled":true,"DefaultTier":"vip","DefaultDurationDays":30,"ExtendExisting":true,"BasePermissions":["vip.active","welcome-pack.vip","sethome.vip","daily-pack.vip","battlepass.vip","sector-scan.vip","vehicle-rental.vip","base-loot.vip"],"Members":[],"Features":{"WelcomePack":{"Enabled":true,"Items":[]},"DailyPack":{"Enabled":true,"CooldownHours":12,"Items":[]},"Battlepass":{"Enabled":true},"HomeSystem":{"Enabled":true,"MaxHomes":5},"SectorScan":{"Enabled":true,"Free":true,"CooldownSeconds":30},"VehicleRental":{"Enabled":true,"DiscountPercent":25,"DefaultMinutes":30,"MaxMinutes":180,"SpawnCooldownSeconds":60},"BaseLootCollector":{"Enabled":true,"RadiusCm":7000,"CooldownSeconds":60,"MaxItemsPerRun":150}}}'
  end
  local rows = {}
  local existingObject = nil
  for _, key in ipairs({ "Members", "members" }) do
    for _, object in ipairs(jsonArrayObjects(text, key)) do
      if vipObjectMatchesInfo(info, object) then
        existingObject = existingObject or object
      else
        table.insert(rows, object)
      end
    end
  end
  table.insert(rows, vipMemberRecordJson(info, expiresAt, tier, source, note, existingObject))
  local nextText = replaceJsonArrayForKey(text, "Members", "[" .. table.concat(rows, ",") .. "]")
  if nextText == nil then nextText = replaceJsonArrayForKey(text, "members", "[" .. table.concat(rows, ",") .. "]") end
  if nextText == nil then
    local trimmed = text:gsub("%s+$", "")
    if trimmed:sub(-1) == "}" then
      nextText = trimmed:sub(1, -2) .. ',"Members":[' .. table.concat(rows, ",") .. ']}'
    else
      return false, "VIP config is not a JSON object."
    end
  end
  local okWrite = writeAll(path, nextText)
  if okWrite then
    appendJsonArray(STATE_DIR .. "\\" .. VIP_STATE_FILE,
      '{"utc":' .. js(nowUtc()) ..
      ',"steamId":' .. js((info or {}).steam or (info or {}).steamId or "") ..
      ',"name":' .. js((info or {}).name or "") ..
      ',"tier":' .. js(vipTrim(tier) ~= "" and tier or configString("vip-system", { "DefaultTier", "defaultTier" }, "vip")) ..
      ',"source":' .. js(source or "manual") ..
      ',"note":' .. js(note or "") ..
      ',"expiresAt":' .. tostring(math.floor(tonumber(expiresAt or 0) or 0)) ..
      ',"expiresAtUtc":' .. js(epochUtcText(expiresAt)) ..
      ',"status":"synced-to-panel-members"}',
      1024 * 1024)
  end
  return okWrite, okWrite and "" or "Не удалось обновить список VIP в панели."
end

function grantVipPrivilege(info, days, tier, source, note)
  if not vipModuleEnabled() then return false, "VIP-модуль выключен." end
  local target = info or {}
  local steam = vipTrim(target.steam or target.steamId)
  local name = vipTrim(target.name)
  if steam == "" and name == "" then return false, "VIP не выдан: не найден SteamID или имя игрока." end
  local durationDays = math.floor(tonumber(days or 0) or 0)
  if durationDays <= 0 then durationDays = math.floor(configNumber("vip-system", { "DefaultDurationDays", "defaultDurationDays" }, 30)) end
  durationDays = math.max(1, math.min(durationDays, 3650))
  local now = os.time()
  local startAt = now
  if configBool("vip-system", { "ExtendExisting", "extendExisting" }, true) ~= false then
    local active = vipActiveRecordForInfo(target)
    if active ~= nil and tonumber(active.expiresAt or 0) > startAt then startAt = active.expiresAt end
  end
  local expiresAt = startAt + durationDays * 86400
  local cleanTier = vipTrim(tier)
  if cleanTier == "" then cleanTier = configString("vip-system", { "DefaultTier", "defaultTier" }, "vip") end
  local saved, saveMessage = upsertVipPanelMember(target, expiresAt, cleanTier, source, note)
  if not saved then return false, saveMessage end
  appendActionEvent("vip_grant", true, target, "VIP " .. cleanTier .. " granted for " .. tostring(durationDays) .. " days.",
    '{"tier":' .. js(cleanTier) .. ',"days":' .. tostring(durationDays) .. ',"expiresAt":' .. tostring(expiresAt) .. ',"source":' .. js(source or "manual") .. '}')
  return true, "VIP " .. cleanTier .. " активирован до " .. vipHumanUtcText(expiresAt) .. "."
end

function vipStatusText(info)
  local active = vipActiveRecordForInfo(info)
  if active == nil then return "VIP сейчас не активен." end
  local object = active.object or ""
  local tier = extractStringAny(object, { "Tier", "tier" }) or "vip"
  local left = math.max(0, math.ceil((active.expiresAt - os.time()) / 86400))
  return "VIP " .. tostring(tier) .. " активен до " .. vipHumanUtcText(active.expiresAt) .. " (осталось " .. tostring(left) .. " дн.)."
end

DEFAULT_PERMISSION_STATE = [[{
  "Groups": {
    "default": { "Title": "Игрок", "Rank": 0, "ParentGroup": "", "Permissions": [] },
    "vip": { "Title": "VIP", "Rank": 10, "ParentGroup": "default", "Permissions": [ "sethome.vip" ] },
    "admin": { "Title": "Админ", "Rank": 100, "ParentGroup": "vip", "Permissions": [ "*" ] }
  },
  "Users": {}
}]]

function ensurePermissionDefaults()
  if readAll(PERMISSION_STATE_FILE) == nil then writeAll(PERMISSION_STATE_FILE, DEFAULT_PERMISSION_STATE) end
end

function jsonObjectForKey(text, key)
  text = tostring(text or "")
  local needle = '"' .. tostring(key or "") .. '"'
  local pos = text:find(needle, 1, true)
  if pos == nil then return nil end
  local colon = text:find(":", pos + #needle, true)
  if colon == nil then return nil end
  local start = text:find("{", colon + 1, true)
  if start == nil then return nil end
  local depth, inString, escaped = 0, false, false
  for i = start, #text do
    local ch = text:sub(i, i)
    if inString then
      if escaped then
        escaped = false
      elseif ch == "\\" then
        escaped = true
      elseif ch == '"' then
        inString = false
      end
    else
      if ch == '"' then
        inString = true
      elseif ch == "{" then
        depth = depth + 1
      elseif ch == "}" then
        depth = depth - 1
        if depth == 0 then return text:sub(start, i) end
      end
    end
  end
  return nil
end

function jsonArrayForKey(text, key)
  text = tostring(text or "")
  local needle = '"' .. tostring(key or "") .. '"'
  local pos = text:find(needle, 1, true)
  if pos == nil then return nil end
  local colon = text:find(":", pos + #needle, true)
  if colon == nil then return nil end
  local start = text:find("[", colon + 1, true)
  if start == nil then return nil end
  local depth, inString, escaped = 0, false, false
  for i = start, #text do
    local ch = text:sub(i, i)
    if inString then
      if escaped then
        escaped = false
      elseif ch == "\\" then
        escaped = true
      elseif ch == '"' then
        inString = false
      end
    else
      if ch == '"' then
        inString = true
      elseif ch == "[" then
        depth = depth + 1
      elseif ch == "]" then
        depth = depth - 1
        if depth == 0 then return text:sub(start, i) end
      end
    end
  end
  return nil
end

function jsonStringArrayForKey(text, key)
  local arrayText = jsonArrayForKey(text, key) or "[]"
  local out = {}
  for value in arrayText:gmatch('"(.-)"') do
    value = value:gsub('\\"', '"'):gsub("\\\\", "\\"):gsub("\\n", "\n"):gsub("\\r", "\r"):gsub("\\t", "\t")
    table.insert(out, value)
  end
  return out
end

function jsonObjectsInArrayForKey(text, key)
  local arrayText = jsonArrayForKey(text, key)
  local out = {}
  if arrayText == nil then return out end
  local inString, escaped = false, false
  local objectDepth, arrayDepth = 0, 0
  local objectStart = nil
  for i = 2, math.max(1, #arrayText - 1) do
    local ch = arrayText:sub(i, i)
    if inString then
      if escaped then
        escaped = false
      elseif ch == "\\" then
        escaped = true
      elseif ch == '"' then
        inString = false
      end
    else
      if ch == '"' then
        inString = true
      elseif ch == "{" then
        if objectDepth == 0 and arrayDepth == 0 then objectStart = i end
        objectDepth = objectDepth + 1
      elseif ch == "}" then
        if objectDepth > 0 then
          objectDepth = objectDepth - 1
          if objectDepth == 0 and arrayDepth == 0 and objectStart ~= nil then
            table.insert(out, arrayText:sub(objectStart, i))
            objectStart = nil
          end
        end
      elseif ch == "[" and objectDepth > 0 then
        arrayDepth = arrayDepth + 1
      elseif ch == "]" and objectDepth > 0 and arrayDepth > 0 then
        arrayDepth = arrayDepth - 1
      end
    end
  end
  return out
end

function jsonTopLevelStringArrayForKey(text, key)
  local arrayText = jsonArrayForKey(text, key)
  local out = {}
  if arrayText == nil then return out end
  local inString, escaped = false, false
  local objectDepth, arrayDepth = 0, 0
  local stringStart = nil
  for i = 2, math.max(1, #arrayText - 1) do
    local ch = arrayText:sub(i, i)
    if inString then
      if escaped then
        escaped = false
      elseif ch == "\\" then
        escaped = true
      elseif ch == '"' then
        if objectDepth == 0 and arrayDepth == 0 and stringStart ~= nil then
          local value = arrayText:sub(stringStart, i - 1)
          value = value:gsub('\\"', '"'):gsub("\\\\", "\\"):gsub("\\n", "\n"):gsub("\\r", "\r"):gsub("\\t", "\t")
          table.insert(out, value)
        end
        stringStart = nil
        inString = false
      end
    else
      if ch == '"' then
        inString = true
        if objectDepth == 0 and arrayDepth == 0 then stringStart = i + 1 end
      elseif ch == "{" then
        objectDepth = objectDepth + 1
      elseif ch == "}" and objectDepth > 0 then
        objectDepth = objectDepth - 1
      elseif ch == "[" then
        arrayDepth = arrayDepth + 1
      elseif ch == "]" and arrayDepth > 0 then
        arrayDepth = arrayDepth - 1
      end
    end
  end
  return out
end

function permissionMatches(granted, required)
  granted = tostring(granted or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
  required = tostring(required or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
  if required == "" then return true end
  if granted == "*" or granted == required then return true end
  if granted:sub(-2) == ".*" then
    local prefix = granted:sub(1, -3)
    return required == prefix or required:sub(1, #prefix + 1) == prefix .. "."
  end
  return false
end

function permissionListHas(list, required)
  for _, granted in ipairs(list or {}) do
    if permissionMatches(granted, required) then return true end
  end
  return false
end

function groupHasPermission(text, groupName, required, visited)
  local group = tostring(groupName or "")
  if group == "" then return false end
  visited = visited or {}
  if visited[group] then return false end
  visited[group] = true
  local groups = jsonObjectForKey(text, "Groups") or ""
  local object = jsonObjectForKey(groups, group)
  if object == nil then return false end
  if permissionListHas(jsonStringArrayForKey(object, "Permissions"), required) then return true end
  local parent = extractStringAny(object, { "ParentGroup", "parentGroup", "parent" }) or ""
  return groupHasPermission(text, parent, required, visited)
end

function userPermissionObject(text, info)
  local users = jsonObjectForKey(text, "Users") or ""
  local steam = tostring((info or {}).steam or (info or {}).steamId or "")
  local profile = tostring((info or {}).userProfileId or (info or {}).serverUserProfileId or "")
  local name = tostring((info or {}).name or "")
  if steam ~= "" then
    local object = jsonObjectForKey(users, steam)
    if object ~= nil then return object end
  end
  if profile ~= "" then
    local object = jsonObjectForKey(users, profile)
    if object ~= nil then return object end
  end
  if name ~= "" then
    local object = jsonObjectForKey(users, name)
    if object ~= nil then return object end
  end
  return nil
end

function hasPermission(info, required)
  local permission = tostring(required or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if permission == "" then return true end
  local text = readAll(PERMISSION_STATE_FILE) or DEFAULT_PERMISSION_STATE
  local userObject = userPermissionObject(text, info)
  if userObject ~= nil and permissionListHas(jsonStringArrayForKey(userObject, "Permissions"), permission) then return true end
  local group = userObject ~= nil and (extractStringAny(userObject, { "Group", "group" }) or "default") or "default"
  if groupHasPermission(text, group, permission, {}) then return true end
  return vipProvidesPermission(info, permission)
end

function permissionDeniedText(permission)
  return "Нет права для этой команды: " .. tostring(permission or "")
end

function samePlayerRecord(info, object)
  local steam = extractString(object, "steamId") or ""
  local name = extractString(object, "name") or ""
  local profileId = extractString(object, "userProfileId") or extractString(object, "profileId") or ""
  local infoProfileId = tostring(info.userProfileId or info.serverUserProfileId or "")
  local infoSteam = tostring(info.steam or info.steamId or "")
  local infoName = tostring(info.name or "")
  if infoSteam ~= "" and steam ~= "" then return steam == infoSteam end
  if infoProfileId ~= "" and profileId ~= "" then return profileId == infoProfileId end
  if infoSteam ~= "" or steam ~= "" or infoProfileId ~= "" or profileId ~= "" then return false end
  return infoName ~= "" and name ~= "" and name == infoName
end

function stateObjects(fileName)
  local cache = loadStateArrayCache(STATE_DIR .. "\\" .. tostring(fileName or ""), 4 * 1024 * 1024, false)
  local rows = {}
  for index, object in ipairs(cache.rows or {}) do rows[index] = object end
  return rows
end

function writeStateObjects(fileName, rows)
  local path = STATE_DIR .. "\\" .. tostring(fileName or "")
  local cleanRows = {}
  for _, object in ipairs(rows or {}) do
    if stateArrayRecordLooksSafe(object) then table.insert(cleanRows, object) end
  end
  local text = "[" .. table.concat(cleanRows, ",") .. "]"
  local ok = writeAll(path, text)
  if ok then
    STATE_ARRAY_CACHE[path] = {
      path = path,
      rows = cleanRows,
      maxBytes = 4 * 1024 * 1024,
      approxBytes = #text,
      dirty = false,
      loadedAt = os.clock()
    }
  end
  return ok
end

function latestStateNumber(fileName, info, field)
  local value = nil
  for _, object in ipairs(stateObjects(fileName)) do
    if samePlayerRecord(info, object) then value = extractNumber(object, field) end
  end
  return value
end

function rememberCooldown(fileName, info, seconds)
  local now = os.time()
  local cooldownSeconds = math.max(0, tonumber(seconds or 0) or 0)
  local extra = ""
  if cooldownSeconds > 0 then
    extra = ',"cooldownHours":' .. tostring(math.floor(cooldownSeconds / 3600)) ..
      ',"expiresAtUtc":' .. js(os.date("!%Y-%m-%dT%H:%M:%SZ", now + cooldownSeconds))
  end
  appendJsonArray(STATE_DIR .. "\\" .. fileName, '{"utc":' .. js(nowUtc()) .. ',"at":' .. tostring(now) .. ',"steamId":' .. js(info.steam or "") .. ',"name":' .. js(info.name or "") .. ',"userProfileId":' .. js(info.userProfileId or info.serverUserProfileId or "") .. extra .. '}', 1024 * 1024)
end

function cooldownRemaining(fileName, info, seconds)
  if tonumber(seconds or 0) <= 0 then return 0 end
  local last = latestStateNumber(fileName, info, "at")
  if last == nil then return 0 end
  local left = math.ceil((tonumber(last) + tonumber(seconds)) - os.time())
  return left > 0 and left or 0
end

function characterConfig()
  local text = configText("character-packs")
  if text == nil or text:gsub("%s+", "") == "" then
    return '{"Enabled":true,"DefaultAttributes":{"Strength":8,"Constitution":8,"Dexterity":8,"Intelligence":8},"SkillPresets":[{"Name":"rifles-core","Skill":"rifles","Level":3},{"Name":"medical-core","Skill":"medical","Level":3},{"Name":"driving-core","Skill":"driving","Level":3}],"Packs":[{"Name":"fullstats","Aliases":["full"],"Enabled":true,"CooldownHours":0,"SuccessMessage":"Атрибуты персонажа обновлены.","Actions":[{"Type":"PlayerCommand","Value":"SetAttributes 8 8 8 8","StopOnFailure":true}]}]}'
  end
  return text
end

function characterModuleEnabled()
  return extractBoolAny(characterConfig(), { "Enabled", "enabled" }, true) ~= false
end

function characterPackObjects()
  local raw = characterConfig():match('"Packs"%s*:%s*(%b[])') or characterConfig():match('"packs"%s*:%s*(%b[])') or ""
  local rows = {}
  for object in raw:gmatch("%b{}") do table.insert(rows, object) end
  if #rows == 0 then
    table.insert(rows, '{"Name":"fullstats","Aliases":["full"],"Enabled":true,"CooldownHours":0,"SuccessMessage":"Атрибуты персонажа обновлены.","Actions":[{"Type":"PlayerCommand","Value":"SetAttributes 8 8 8 8","StopOnFailure":true}]}')
  end
  return rows
end

function characterSkillPresetObjects()
  local raw = characterConfig():match('"SkillPresets"%s*:%s*(%b[])') or characterConfig():match('"skillPresets"%s*:%s*(%b[])') or ""
  local rows = {}
  for object in raw:gmatch("%b{}") do table.insert(rows, object) end
  return rows
end

function characterNameMatches(object, wanted)
  wanted = tostring(wanted or ""):lower()
  if wanted == "" then return false end
  local name = (extractStringAny(object, { "Name", "name" }) or ""):lower()
  if name == wanted then return true end
  local aliases = object:match('"Aliases"%s*:%s*(%b[])') or object:match('"aliases"%s*:%s*(%b[])') or ""
  for alias in aliases:gmatch('"(.-)"') do
    if tostring(alias or ""):lower() == wanted then return true end
  end
  return false
end

function findCharacterPack(name)
  local wanted = tostring(name or "fullstats")
  if wanted == "" then wanted = "fullstats" end
  for _, object in ipairs(characterPackObjects()) do
    if characterNameMatches(object, wanted) then return object end
  end
  return nil
end

function findCharacterSkillPreset(name)
  local wanted = tostring(name or ""):lower()
  if wanted == "" then return nil end
  for _, object in ipairs(characterSkillPresetObjects()) do
    local presetName = (extractStringAny(object, { "Name", "name", "Skill", "skill" }) or ""):lower()
    if presetName == wanted then return object end
  end
  return nil
end

characterPackListText = function()
  if not characterModuleEnabled() then return "Пакеты персонажа сейчас отключены." end
  local packs = {}
  for _, object in ipairs(characterPackObjects()) do
    local name = extractStringAny(object, { "Name", "name" }) or ""
    if name ~= "" and extractBoolAny(object, { "Enabled", "enabled" }, true) ~= false then table.insert(packs, name) end
  end
  table.sort(packs)
  local presets = {}
  for _, object in ipairs(characterSkillPresetObjects()) do
    local name = extractStringAny(object, { "Name", "name" }) or ""
    if name ~= "" then table.insert(presets, name) end
  end
  table.sort(presets)
  local text = #packs > 0 and ("Пакеты персонажа: " .. table.concat(packs, ", ")) or "Пакетов персонажа нет."
  if #presets > 0 then text = text .. " Пресеты навыков: " .. table.concat(presets, ", ") end
  return text .. " Наборы персонажа применяются администратором через веб-панель."
end

function characterPackCooldownRemaining(info, packName, cooldownHours)
  local seconds = math.max(0, tonumber(cooldownHours or 0) or 0) * 3600
  if seconds <= 0 then return 0 end
  local wanted = tostring(packName or ""):lower()
  local latest = 0
  for _, object in ipairs(stateObjects("character-pack-timers.json")) do
    local samePack = (extractString(object, "pack") or ""):lower() == wanted
    local samePlayer = false
    local steam = extractString(object, "steamId") or ""
    local name = extractString(object, "name") or ""
    if info.steam ~= "" and steam ~= "" and steam == info.steam then samePlayer = true end
    if not samePlayer and info.name ~= "" and name ~= "" and name:lower() == info.name:lower() then samePlayer = true end
    if samePack and samePlayer then latest = math.max(latest, extractNumber(object, "at") or 0) end
  end
  if latest <= 0 then return 0 end
  return math.max(0, math.ceil((latest + seconds) - os.time()))
end

function rememberCharacterPack(info, packName, cooldownHours)
  local seconds = math.max(0, tonumber(cooldownHours or 0) or 0) * 3600
  local extra = ""
  if seconds > 0 then extra = ',"expiresAt":' .. tostring(os.time() + seconds) end
  appendJsonArray(STATE_DIR .. "\\character-pack-timers.json", '{"utc":' .. js(nowUtc()) .. ',"at":' .. tostring(os.time()) .. ',"steamId":' .. js(info.steam) .. ',"name":' .. js(info.name) .. ',"pack":' .. js(packName) .. ',"cooldownHours":' .. tostring(tonumber(cooldownHours or 0) or 0) .. extra .. '}', 512 * 1024)
end

function expandCharacterActionValue(value, info)
  local target = info.steam ~= "" and info.steam or info.name
  local expanded = tostring(value or "")
  expanded = expanded:gsub("{steamId}", info.steam or "")
  expanded = expanded:gsub("{SteamId}", info.steam or "")
  expanded = expanded:gsub("{steamID}", info.steam or "")
  expanded = expanded:gsub("{name}", info.name or "")
  expanded = expanded:gsub("{Name}", info.name or "")
  expanded = expanded:gsub("{player}", target or "")
  expanded = expanded:gsub("{Player}", target or "")
  expanded = expanded:gsub("{target}", target or "")
  expanded = expanded:gsub("{Target}", target or "")
  return expanded
end

function executeCharacterAction(info, actionType, actionValue)
  local expanded = expandCharacterActionValue(actionValue, info)
  local parts = splitWords(expanded:gsub("^%s*#", ""))
  local verb = (parts[1] or ""):lower()
  if verb == "setattributes" or verb == "setprisonerattributes" then
    local nums = {}
    for i = 2, #parts do
      local n = tonumber(parts[i])
      if n ~= nil then table.insert(nums, n) end
    end
    if #nums >= 4 then return setAttributes(info.steam, info.name, nums[1], nums[2], nums[3], nums[4], false, info.runtimeKey) end
  end
  if verb == "setskilllevel" then
    local skill = ""
    local level = nil
    local experience = 0
    for i = 2, #parts do
      local n = tonumber(parts[i])
      if n ~= nil and i > 2 then
        level = n
        skill = parts[i - 1] or ""
        experience = tonumber(parts[i + 1]) or 0
        break
      end
    end
    if skill ~= "" and level ~= nil then return setSkill(info.steam, info.name, skill, level, experience, info.runtimeKey) end
  end
  local sent, message = adminExec(expanded, info)
  return sent, message
end

function applyCharacterSkillPreset(info, object)
  local name = extractStringAny(object, { "Name", "name", "Skill", "skill" }) or "skill"
  local skill = extractStringAny(object, { "Skill", "skill", "Name", "name" }) or ""
  local level = extractNumberAny(object, { "Level", "level" }, 1)
  local experience = extractNumberAny(object, { "Experience", "experience" }, 0)
  if skill == "" then return false, "skill preset has no skill", "{}" end
  local sent, message = setSkill(info.steam, info.name, skill, level, experience, info.runtimeKey)
  appendJsonArray(STATE_DIR .. "\\character-packs.json", '{"utc":' .. js(nowUtc()) .. ',"steamId":' .. js(info.steam) .. ',"name":' .. js(info.name) .. ',"pack":' .. js(name) .. ',"type":"skill-preset","skill":' .. js(skill) .. ',"level":' .. tostring(level) .. ',"ok":' .. (sent and "true" or "false") .. ',"message":' .. js(message) .. '}', 1024 * 1024)
  if sent then return true, "Пресет навыка применён: " .. name, '{"pack":' .. js(name) .. ',"type":"skill-preset","skill":' .. js(skill) .. ',"level":' .. tostring(level) .. '}' end
  return false, message, "{}"
end

applyCharacterPackForInfo = function(info, packName)
  if info == nil then return false, "Игрок не найден среди реально подключённых.", "{}" end
  if not characterModuleEnabled() then return false, "Пресеты персонажа отключены.", "{}" end
  packName = tostring(packName or "fullstats")
  if packName == "" then packName = "fullstats" end
  local object = findCharacterPack(packName)
  if object == nil then
    local preset = findCharacterSkillPreset(packName)
    if preset ~= nil then return applyCharacterSkillPreset(info, preset) end
    return false, "Пресет персонажа не найден: " .. packName, "{}"
  end
  if extractBoolAny(object, { "Enabled", "enabled" }, true) == false then return false, "Пресет персонажа отключён: " .. packName, "{}" end

  local name = extractStringAny(object, { "Name", "name" }) or packName
  local cooldownHours = extractNumberAny(object, { "CooldownHours", "cooldownHours" }, 0)
  local remaining = characterPackCooldownRemaining(info, name, cooldownHours)
  if remaining > 0 then return false, "Кулдаун пресета персонажа активен. Осталось секунд: " .. tostring(remaining), "{}" end

  local results = {}
  local okCount = 0
  local failCount = 0
  local actionsRaw = object:match('"Actions"%s*:%s*(%b[])') or object:match('"actions"%s*:%s*(%b[])') or ""
  for action in actionsRaw:gmatch("%b{}") do
    local actionType = extractStringAny(action, { "Type", "type" }) or "PlayerCommand"
    local actionValue = extractStringAny(action, { "Value", "value" }) or ""
    if actionValue ~= "" then
      local sent, message = executeCharacterAction(info, actionType, actionValue)
      table.insert(results, '{"ok":' .. (sent and "true" or "false") .. ',"type":' .. js(actionType) .. ',"value":' .. js(actionValue) .. ',"message":' .. js(message) .. '}')
      if sent then okCount = okCount + 1 else failCount = failCount + 1 end
      if not sent and extractBoolAny(action, { "StopOnFailure", "stopOnFailure" }, true) ~= false then break end
    end
  end

  if actionsRaw == "" and (object:find('"Strength"%s*:') or object:find('"strength"%s*:')) then
    local sent, message = setAttributes(info.steam, info.name,
      extractNumberAny(object, { "Strength", "strength" }, 8),
      extractNumberAny(object, { "Constitution", "constitution" }, 8),
      extractNumberAny(object, { "Dexterity", "dexterity" }, 8),
      extractNumberAny(object, { "Intelligence", "intelligence" }, 8),
      false,
      info.runtimeKey)
    table.insert(results, '{"ok":' .. (sent and "true" or "false") .. ',"type":"Attributes","message":' .. js(message) .. '}')
    if sent then okCount = okCount + 1 else failCount = failCount + 1 end
  end

  local skillsRaw = object:match('"Skills"%s*:%s*(%b[])') or object:match('"skills"%s*:%s*(%b[])') or ""
  for skillObject in skillsRaw:gmatch("%b{}") do
    local skill = extractStringAny(skillObject, { "Skill", "skill", "Name", "name" }) or ""
    local level = extractNumberAny(skillObject, { "Level", "level" }, 0)
    if skill ~= "" and level > 0 then
      local sent, message = setSkill(info.steam, info.name, skill, level, 0, info.runtimeKey)
      table.insert(results, '{"ok":' .. (sent and "true" or "false") .. ',"type":"Skill","skill":' .. js(skill) .. ',"level":' .. tostring(level) .. ',"message":' .. js(message) .. '}')
      if sent then okCount = okCount + 1 else failCount = failCount + 1 end
    end
  end

  if okCount > 0 and failCount == 0 then rememberCharacterPack(info, name, cooldownHours) end
  local data = '{"pack":' .. js(name) .. ',"okActions":' .. tostring(okCount) .. ',"failedActions":' .. tostring(failCount) .. ',"results":[' .. table.concat(results, ",") .. ']}'
  appendJsonArray(STATE_DIR .. "\\character-packs.json", '{"utc":' .. js(nowUtc()) .. ',"steamId":' .. js(info.steam) .. ',"name":' .. js(info.name) .. ',"pack":' .. js(name) .. ',"okActions":' .. tostring(okCount) .. ',"failedActions":' .. tostring(failCount) .. ',"results":[' .. table.concat(results, ",") .. ']}', 1024 * 1024)
  if okCount > 0 and failCount == 0 then return true, extractStringAny(object, { "SuccessMessage", "successMessage" }) or ("Пакет персонажа применён: " .. name), data end
  if okCount > 0 then return false, "Пресет персонажа выполнен частично: " .. name, data end
  return false, "Пресет персонажа не выполнил ни одного действия: " .. name, data
end

applyCharacterPack = function(steamId, name, packName, runtimeKey)
  local info = findPlayer(steamId, name, runtimeKey)
  return applyCharacterPackForInfo(info, packName)
end

function distance2d(ax, ay, bx, by)
  local dx = (tonumber(ax) or 0) - (tonumber(bx) or 0)
  local dy = (tonumber(ay) or 0) - (tonumber(by) or 0)
  return math.sqrt(dx * dx + dy * dy)
end

function observePlayerArrival(action, info, x, y, z, timeoutSeconds, radius, onArrived, onFailed)
  local deadline = os.time() + math.max(1, tonumber(timeoutSeconds or 30) or 30)
  local maxDistance = math.max(100, tonumber(radius or 1500) or 1500)
  local function tick()
    local cached = findPlayer(info.steam, info.name, info.runtimeKey) or info
    local live = refreshRuntimePlayerInfo(cached) or enrichPlayerInfoFromServerLog(cached) or cached
    if live == nil then
      appendActionEvent(action .. "_arrival", false, info, "Игрок вышел до подтверждения прибытия.",
        '{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. ',"radius":' .. tostring(maxDistance) .. '}')
      if onFailed ~= nil then onFailed("Игрок вышел до подтверждения прибытия.") end
      return
    end
    local distance = distance2d(live.x, live.y, x, y)
    if distance <= maxDistance then
      appendActionEvent(action .. "_arrival", true, live, "Прибытие подтверждено live-позицией.",
        '{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) ..
        ',"distance":' .. tostring(math.floor(distance + 0.5)) ..
        ',"radius":' .. tostring(maxDistance) .. '}')
      if onArrived ~= nil then onArrived(live, distance) end
      return
    end
    if os.time() >= deadline then
      appendActionEvent(action .. "_arrival", false, live, "Прибытие не подтверждено live-позицией.",
        '{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) ..
        ',"distance":' .. tostring(math.floor(distance + 0.5)) ..
        ',"radius":' .. tostring(maxDistance) .. '}')
      if onFailed ~= nil then onFailed("Прибытие не подтверждено: расстояние до точки " .. tostring(math.floor(distance + 0.5)) .. ".") end
      return
    end
    deferGame(1000, tick)
  end
  tick()
end

function configuredFastTravelRoutes()
  local text = configText("fast-travel")
  local raw = text:match('"Outposts"%s*:%s*(%b[])') or text:match('"outposts"%s*:%s*(%b[])')
  local routes = {}
  if raw ~= nil then
    for object in raw:gmatch("%b{}") do
      local alias = (extractString(object, "CommandAlias") or extractString(object, "commandAlias") or ""):lower()
      local display = extractString(object, "DisplayName") or extractString(object, "displayName") or alias
      local point = object:match('"ArrivalPoint"%s*:%s*%[(.-)%]') or object:match('"arrivalPoint"%s*:%s*%[(.-)%]')
      if alias ~= "" and point ~= nil then
        local values = {}
        for num in point:gmatch("-?%d+%.?%d*") do table.insert(values, tonumber(num)) end
        if #values >= 3 then
          routes[alias] = {
            name = display,
            x = values[1],
            y = values[2],
            z = values[3],
            price = numberField(object, "Price", numberField(object, "price", nil))
          }
        end
      end
    end
  end
  for alias, route in pairs(fastTravelRoutes) do
    if routes[alias] == nil then routes[alias] = route end
  end
  return routes
end

function configuredRentalVehicles(includeVip)
  local text = configText("vehicle-rental")
  local defaultMinutes = math.max(1, configNumber("vehicle-rental", { "DefaultRentalMinutes", "defaultRentalMinutes", "DefaultMinutes", "defaultMinutes" }, 10))
  local minMinutes = math.max(1, configNumber("vehicle-rental", { "MinRentalMinutes", "minRentalMinutes", "MinMinutes", "minMinutes" }, 10))
  local maxMinutes = math.max(minMinutes, configNumber("vehicle-rental", { "MaxRentalMinutes", "maxRentalMinutes", "MaxMinutes", "maxMinutes" }, 60))
  local defaultPenalty = math.max(0, configNumber("vehicle-rental", { "DefaultMissingVehiclePenalty", "defaultMissingVehiclePenalty", "MissingVehiclePenalty", "missingVehiclePenalty", "SoldVehiclePenalty", "soldVehiclePenalty" }, 0))
  local vehicles = {
    rager = { display = "Rager", asset = "BPC_Rager", initial = 5000, price = 15000, defaultMinutes = defaultMinutes, minMinutes = minMinutes, maxMinutes = maxMinutes, penalty = defaultPenalty },
    wolfswagen = { display = "WolfsWagen", asset = "BPC_WolfsWagen", initial = 4000, price = 12000, defaultMinutes = defaultMinutes, minMinutes = minMinutes, maxMinutes = maxMinutes, penalty = defaultPenalty },
    laika = { display = "Laika", asset = "BPC_Laika", initial = 4000, price = 8000, defaultMinutes = defaultMinutes, minMinutes = minMinutes, maxMinutes = maxMinutes, penalty = defaultPenalty }
  }
  local function removeRentalVehicleDuplicates(alias, asset)
    local cleanAlias = tostring(alias or ""):lower()
    local cleanAsset = tostring(asset or ""):lower()
    if cleanAlias == "" or cleanAsset == "" then return end
    for existingAlias, vehicle in pairs(vehicles) do
      if tostring(existingAlias or "") ~= cleanAlias and tostring(vehicle and vehicle.asset or ""):lower() == cleanAsset then
        vehicles[existingAlias] = nil
      end
    end
  end
  local function addRentalVehiclesFromArray(raw, vipOnly)
    if raw == nil then return end
    for object in raw:gmatch("%b{}") do
      local alias = (extractString(object, "Alias") or extractString(object, "alias") or ""):lower()
      local asset = extractString(object, "AssetName") or extractString(object, "assetName") or ""
      if alias ~= "" and asset ~= "" then
        removeRentalVehicleDuplicates(alias, asset)
        vehicles[alias] = {
          display = extractString(object, "DisplayName") or extractString(object, "displayName") or alias,
          asset = asset,
          initial = numberField(object, "InitialCharge", numberField(object, "initialCharge", 0)),
          price = numberField(object, "PricePer10Minutes", numberField(object, "pricePer10Minutes", 0)),
          defaultMinutes = math.max(1, numberField(object, "DefaultMinutes", numberField(object, "defaultMinutes", defaultMinutes))),
          minMinutes = math.max(1, numberField(object, "MinMinutes", numberField(object, "minMinutes", minMinutes))),
          maxMinutes = math.max(1, numberField(object, "MaxMinutes", numberField(object, "maxMinutes", maxMinutes))),
          penalty = math.max(0, numberField(object, "MissingVehiclePenalty", numberField(object, "missingVehiclePenalty", numberField(object, "SoldVehiclePenalty", numberField(object, "soldVehiclePenalty", defaultPenalty))))),
          vipOnly = vipOnly == true
        }
        if vehicles[alias].maxMinutes < vehicles[alias].minMinutes then vehicles[alias].maxMinutes = vehicles[alias].minMinutes end
      end
    end
  end
  local raw = text:match('"Vehicles"%s*:%s*(%b[])') or text:match('"vehicles"%s*:%s*(%b[])')
  addRentalVehiclesFromArray(raw, false)
  if includeVip == true then
    local rawVip = text:match('"VipVehicles"%s*:%s*(%b[])') or text:match('"vipVehicles"%s*:%s*(%b[])') or text:match('"VIPVehicles"%s*:%s*(%b[])')
    addRentalVehiclesFromArray(rawVip, true)
  end
  return vehicles
end

function availableRentalVehiclesForInfo(info)
  return configuredRentalVehicles(vipFeatureEnabledForInfo(info, "VehicleRental"))
end

function moneyLabel(amount)
  local value = math.max(0, math.floor(tonumber(amount or 0) or 0))
  return "$" .. tostring(value)
end

function rentPerMinute(vehicle)
  return math.max(0, math.floor(((vehicle and tonumber(vehicle.price or 0)) or 0) / 10))
end

function vipRentalVehicleForInfo(info, vehicle)
  if vehicle == nil then return nil end
  local copy = {}
  for key, value in pairs(vehicle) do copy[key] = value end
  if not vipFeatureEnabledForInfo(info, "VehicleRental") then return copy end
  local discount = math.max(0, math.min(100, vipFeatureNumberForInfo(info, "VehicleRental", { "DiscountPercent", "discountPercent" }, 0) or 0))
  if discount > 0 then
    local factor = (100 - discount) / 100
    copy.initial = math.max(0, math.floor((tonumber(copy.initial or 0) or 0) * factor + 0.5))
    copy.price = math.max(0, math.floor((tonumber(copy.price or 0) or 0) * factor + 0.5))
  end
  local defaultMinutes = vipFeatureNumberForInfo(info, "VehicleRental", { "DefaultMinutes", "defaultMinutes", "DefaultRentalMinutes", "defaultRentalMinutes" }, nil)
  local maxMinutes = vipFeatureNumberForInfo(info, "VehicleRental", { "MaxMinutes", "maxMinutes", "MaxRentalMinutes", "maxRentalMinutes" }, nil)
  if defaultMinutes ~= nil then copy.defaultMinutes = math.max(1, math.floor(defaultMinutes)) end
  if maxMinutes ~= nil then copy.maxMinutes = math.max(tonumber(copy.minMinutes or 1) or 1, math.floor(maxMinutes)) end
  if (tonumber(copy.defaultMinutes or 0) or 0) > (tonumber(copy.maxMinutes or 0) or 0) then copy.defaultMinutes = copy.maxMinutes end
  copy.vip = true
  return copy
end

VEHICLE_RENTAL_GLOBAL_NEXT_AT = VEHICLE_RENTAL_GLOBAL_NEXT_AT or 0
VEHICLE_RENTAL_PLAYER_NEXT_AT = VEHICLE_RENTAL_PLAYER_NEXT_AT or {}

function rentalCooldownKey(info)
  if info == nil then return "" end
  local steam = cleanText(info.steam or info.steamId or "")
  if steam ~= "" then return "steam:" .. steam end
  local profile = cleanText(info.userProfileId or info.serverUserProfileId or "")
  if profile ~= "" and profile ~= "0" then return "profile:" .. profile end
  local name = cleanText(info.name or ""):lower()
  if name ~= "" and name ~= "unknown" then return "name:" .. name end
  return ""
end

function vehicleRentalSpawnCooldownRemaining(info)
  local now = os.time()
  local waitGlobal = math.max(0, math.floor((tonumber(VEHICLE_RENTAL_GLOBAL_NEXT_AT or 0) or 0) - now))
  local key = rentalCooldownKey(info)
  local waitPlayer = 0
  if key ~= "" then waitPlayer = math.max(0, math.floor((tonumber(VEHICLE_RENTAL_PLAYER_NEXT_AT[key] or 0) or 0) - now)) end
  if waitPlayer >= waitGlobal and waitPlayer > 0 then return waitPlayer, "player" end
  if waitGlobal > 0 then return waitGlobal, "global" end
  return 0, ""
end

function reserveVehicleRentalSpawnCooldown(info)
  local now = os.time()
  local globalSeconds = math.max(0, configNumber("vehicle-rental", { "GlobalSpawnCooldownSeconds", "globalSpawnCooldownSeconds" }, 60))
  local playerSeconds = math.max(0, configNumber("vehicle-rental", { "PlayerSpawnCooldownSeconds", "playerSpawnCooldownSeconds" }, 180))
  if vipFeatureEnabledForInfo(info, "VehicleRental") then
    globalSeconds = math.max(0, vipFeatureNumberForInfo(info, "VehicleRental", { "GlobalSpawnCooldownSeconds", "globalSpawnCooldownSeconds", "SpawnCooldownSeconds", "spawnCooldownSeconds" }, globalSeconds) or globalSeconds)
    playerSeconds = math.max(0, vipFeatureNumberForInfo(info, "VehicleRental", { "PlayerSpawnCooldownSeconds", "playerSpawnCooldownSeconds", "SpawnCooldownSeconds", "spawnCooldownSeconds" }, playerSeconds) or playerSeconds)
  end
  VEHICLE_RENTAL_GLOBAL_NEXT_AT = math.max(tonumber(VEHICLE_RENTAL_GLOBAL_NEXT_AT or 0) or 0, now + globalSeconds)
  local key = rentalCooldownKey(info)
  if key ~= "" then
    VEHICLE_RENTAL_PLAYER_NEXT_AT[key] = math.max(tonumber(VEHICLE_RENTAL_PLAYER_NEXT_AT[key] or 0) or 0, now + playerSeconds)
  end
end

WARGM_VEHICLE_PLAYER_NEXT_AT = WARGM_VEHICLE_PLAYER_NEXT_AT or {}

function wargmVehicleSpawnCooldownRemaining(info)
  local now = os.time()
  local waitGlobal = math.max(0, math.floor((tonumber(WARGM_VEHICLE_GLOBAL_NEXT_AT or 0) or 0) - now))
  local key = rentalCooldownKey(info)
  local waitPlayer = 0
  if key ~= "" then waitPlayer = math.max(0, math.floor((tonumber(WARGM_VEHICLE_PLAYER_NEXT_AT[key] or 0) or 0) - now)) end
  if waitPlayer >= waitGlobal and waitPlayer > 0 then return waitPlayer, "player" end
  if waitGlobal > 0 then return waitGlobal, "global" end
  return 0, ""
end

function reserveWargmVehicleSpawnCooldown(info)
  local now = os.time()
  local globalSeconds = math.max(0, configNumber("wargm-shop", { "VehicleGlobalSpawnCooldownSeconds", "vehicleGlobalSpawnCooldownSeconds" }, 20))
  local playerSeconds = math.max(0, configNumber("wargm-shop", { "VehiclePlayerSpawnCooldownSeconds", "vehiclePlayerSpawnCooldownSeconds" }, 60))
  WARGM_VEHICLE_GLOBAL_NEXT_AT = math.max(tonumber(WARGM_VEHICLE_GLOBAL_NEXT_AT or 0) or 0, now + globalSeconds)
  local key = rentalCooldownKey(info)
  if key ~= "" then
    WARGM_VEHICLE_PLAYER_NEXT_AT[key] = math.max(tonumber(WARGM_VEHICLE_PLAYER_NEXT_AT[key] or 0) or 0, now + playerSeconds)
  end
end

function sendRentHelp(info, current)
  local lines = { "Аренда транспорта:" }
  local labels = {}
  for alias, vehicle in pairs(availableRentalVehiclesForInfo(info)) do
    table.insert(labels, { alias = alias, vehicle = vehicle })
  end
  table.sort(labels, function(a, b)
    local ad = tostring((a.vehicle and a.vehicle.display) or a.alias or "")
    local bd = tostring((b.vehicle and b.vehicle.display) or b.alias or "")
    if ad == bd then return tostring(a.alias or "") < tostring(b.alias or "") end
    return ad < bd
  end)
  for _, row in ipairs(labels) do
    local vehicle = vipRentalVehicleForInfo(info, row.vehicle or {}) or {}
    local alias = tostring(row.alias or "")
    local display = tostring(vehicle.display or alias)
    local minMinutes = math.max(1, tonumber(vehicle.minMinutes or 10) or 10)
    local maxMinutes = math.max(minMinutes, tonumber(vehicle.maxMinutes or 60) or 60)
    local penalty = math.max(0, math.floor(tonumber(vehicle.penalty or 0) or 0))
    local vipMark = vehicle.vipOnly and " | VIP транспорт" or (vehicle.vip and " | VIP условия" or "")
    table.insert(lines, commandUsage("rent", " " .. alias .. " [мин]") .. " - " .. display .. " | " .. moneyLabel(vehicle.initial) .. " сразу, " .. moneyLabel(rentPerMinute(vehicle)) .. "/мин после 10 | срок " .. tostring(minMinutes) .. "-" .. tostring(maxMinutes) .. " мин" .. vipMark .. (penalty > 0 and (" | штраф " .. moneyLabel(penalty)) or ""))
  end
  table.insert(lines, "Команды: " .. commandUsage("rent", " time") .. ", " .. commandUsage("rent", " extend <мин>") .. ", " .. commandUsage("rent", " return") .. ".")
  if current ~= nil then
    local left = math.max(0, (extractNumber(current, "expiresAt") or 0) - os.time())
    table.insert(lines, "Активно: " .. (extractString(current, "displayName") or extractString(current, "vehicleId") or "transport") .. ", осталось " .. tostring(math.ceil(left / 60)) .. " мин.")
  end
  sendTargetMessageLines(info, lines, "rent", nil, { compactMessage = "Аренда транспорта: " .. commandUsage("rent", " list") .. ", " .. commandUsage("rent", " <type> <minutes>") .. ", " .. commandUsage("rent", " return") .. "." })
end

function sendRentStatus(info, current)
  if current == nil then
    targetMessageResolved(info, "У тебя нет активной аренды.")
    return
  end
  local left = math.max(0, (extractNumber(current, "expiresAt") or 0) - os.time())
  local chargeableMinutes, totalCostSoFar, additionalCharge, outstanding, alreadyPaid = rentalTaxBreakdown(current, os.time())
  sendTargetMessageLines(info, {
    "Аренда: " .. (extractString(current, "displayName") or extractString(current, "vehicleId") or "transport") .. " | осталось " .. tostring(math.ceil(left / 60)) .. " мин | использовано " .. tostring(chargeableMinutes) .. " мин.",
    "Оплачено: " .. moneyLabel(alreadyPaid) .. " | стоимость сейчас: " .. moneyLabel(totalCostSoFar) .. " | доплата при возврате: " .. moneyLabel(outstanding) .. ". Команды: " .. commandUsage("rent", " extend <мин>") .. ", " .. commandUsage("rent", " return") .. "."
  }, "rent-status")
end

function fastTravelFareForInfo(info, route)
  if route == nil then return 0 end
  local routeFare = tonumber(route.price)
  if routeFare ~= nil and routeFare > 0 then return math.max(0, math.floor(routeFare)) end
  local fixedFare = configNumber("fast-travel", { "FixedFare", "fixedFare", "TravelCost", "travelCost", "Amount", "amount" }, nil)
  if fixedFare ~= nil and tonumber(fixedFare) ~= nil and tonumber(fixedFare) > 0 then
    return math.max(0, math.floor(tonumber(fixedFare) or 0))
  end
  local rate = configNumber("fast-travel", { "RatePerMeter", "ratePerMeter" }, 0.5)
  local x = tonumber(info and info.x)
  local y = tonumber(info and info.y)
  if x == nil or y == nil then return 0 end
  return math.max(0, math.floor(distance2d(x, y, route.x, route.y) * rate + 0.5))
end

FAST_TRAVEL_PENDING = FAST_TRAVEL_PENDING or {}
FAST_TRAVEL_GLOBAL_PENDING = FAST_TRAVEL_GLOBAL_PENDING or false
HOME_TELEPORT_PENDING = HOME_TELEPORT_PENDING or {}

function transientPlayerKey(info)
  if info == nil then return "unknown" end
  local steam = tostring(info.steam or "")
  if steam ~= "" then return "steam:" .. steam end
  local runtimeKey = tostring(info.runtimeKey or "")
  if runtimeKey ~= "" then return "runtime:" .. runtimeKey end
  local name = tostring(info.name or "")
  if name ~= "" then return "name:" .. name:lower() end
  return "unknown"
end

function safeFastTravelZ(route)
  local z = tonumber(route and route.z) or 0
  if not configBool("bridge-safety", { "EnableDirectTeleport", "enableDirectTeleport", "AllowDirectPawnTeleport", "allowDirectPawnTeleport" }, false) then
    return z
  end
  local minZ = configNumber("fast-travel", { "MinArrivalZ", "minArrivalZ", "SafeArrivalZ", "safeArrivalZ" }, 12000)
  if z < minZ then return minZ end
  return z
end

function rentalRecordKeyFromObject(object)
  local steam = extractString(object, "steamId") or ""
  if steam ~= "" then return "steam:" .. steam end
  local name = extractString(object, "name") or ""
  if name ~= "" then return "name:" .. name:lower() end
  return ""
end

function rentalStatus(object)
  local status = (extractString(object, "status") or ""):lower()
  if status ~= "" then return status end
  if extractBool(object, "returned", false) then return "returned" end
  return "active"
end

function rentalClosed(object)
  local status = rentalStatus(object)
  return status == "returned" or status == "expired" or status == "expired_untracked" or status == "sold_or_missing" or status == "missing_vehicle" or status == "cancelled" or status == "failed"
end

function rentalPendingDestroy(object)
  local status = rentalStatus(object)
  return status == "expire_pending" or status == "expired_pending" or status == "pending_destroy"
end

function rentalWarningMinutes()
  local text = configText("vehicle-rental")
  local raw = text:match('"WarningMinutesBeforeExpiry"%s*:%s*(%b[])') or
    text:match('"warningMinutesBeforeExpiry"%s*:%s*(%b[])') or
    text:match('"WarningsBeforeExpiry"%s*:%s*(%b[])') or
    text:match('"warningsBeforeExpiry"%s*:%s*(%b[])') or ""
  local rows = {}
  local seen = {}
  for _, value in ipairs(numberList(raw)) do
    local minutes = math.floor(tonumber(value) or 0)
    if minutes > 0 and not seen[minutes] then
      seen[minutes] = true
      table.insert(rows, minutes)
    end
  end
  if #rows == 0 then rows = { 5, 1 } end
  table.sort(rows, function(a, b) return a < b end)
  return rows
end

function rentalWarningKey(object, minutes)
  return tostring(rentalRecordKeyFromObject(object)) ..
    "|alias:" .. tostring(extractString(object, "alias") or "") ..
    "|vehicle:" .. tostring(extractString(object, "vehicleId") or "") ..
    "|started:" .. tostring(extractNumber(object, "startedAt") or 0) ..
    "|expires:" .. tostring(extractNumber(object, "expiresAt") or 0) ..
    "|m:" .. tostring(minutes or 0)
end

function latestRentalWarningKeys()
  local sent = {}
  for _, object in ipairs(stateObjects("vehicle-rental-warnings.json")) do
    local key = extractString(object, "warningKey") or ""
    if key ~= "" and extractBool(object, "sent", false) then sent[key] = true end
  end
  return sent
end

function resolveRentalNoticePlayer(steam, name, runtimeKey, reason)
  local live = findPlayer(steam, name, runtimeKey)
  if live ~= nil and playerInfoHasLiveAdminChannel(live) then return live, "cache" end

  if configBool("bridge-safety", { "EnableRentalNoticePlayerRefresh", "enableRentalNoticePlayerRefresh" }, true) then
    local okRefresh, refreshErr = pcall(refreshPlayerInfoCache)
    if not okRefresh then
      appendLog("rental notice player refresh failed reason=" .. tostring(reason or "") .. " err=" .. tostring(refreshErr))
    end
    live = findPlayer(steam, name, runtimeKey)
    if live ~= nil and playerInfoHasLiveAdminChannel(live) then return live, "safe-refresh" end
  end

  return live, "not-resolved"
end

function sendRentalNoticeMessage(steam, name, runtimeKey, message, historySource, reason)
  local live, resolveRoute = resolveRentalNoticePlayer(steam, name, runtimeKey, reason)
  if live == nil or not playerInfoHasLiveAdminChannel(live) then
    return false, "player_not_resolved:" .. tostring(resolveRoute or "")
  end
  local sent, route = sendTargetMessageToInfo(live, message, historySource)
  return sent, tostring(resolveRoute or "") .. " -> " .. tostring(route or "")
end

function sendRentalExpiryWarningIfNeeded(object, sentKeys)
  if object == nil or rentalClosed(object) or rentalPendingDestroy(object) then return false end
  local expiresAt = extractNumber(object, "expiresAt") or 0
  local now = os.time()
  if expiresAt <= now then return false end
  local left = math.max(0, expiresAt - now)
  local dueMinutes = nil
  local dueKey = ""
  for _, minutes in ipairs(rentalWarningMinutes()) do
    local key = rentalWarningKey(object, minutes)
    if left <= minutes * 60 and not (sentKeys or {})[key] then
      dueMinutes = minutes
      dueKey = key
      break
    end
  end
  if dueMinutes == nil then return false end

  local steam = extractString(object, "steamId") or ""
  local name = extractString(object, "name") or ""
  local displayName = extractString(object, "displayName") or extractString(object, "vehicleId") or "транспорта"
  local leftMinutes = math.max(1, math.ceil(left / 60))
  local sent, route = sendRentalNoticeMessage(steam, name, extractString(object, "runtimeKey") or "",
    "Внимание: до конца аренды " .. tostring(displayName) .. " осталось примерно " .. tostring(leftMinutes) ..
    " мин. Используй " .. commandUsage("rent", " extend <мин>") .. " или " .. commandUsage("rent", " return") .. ".",
    "vehicle-rental-warning", "warning")

  appendActionEvent("vehicle_rental_warning", sent, { steam = steam, name = name }, tostring(route or ""),
    '{"warningKey":' .. js(dueKey) ..
    ',"warningMinutes":' .. tostring(dueMinutes) ..
    ',"leftSeconds":' .. tostring(left) ..
    ',"displayName":' .. js(displayName) .. '}')

  if sent then
    appendJsonArray(STATE_DIR .. "\\vehicle-rental-warnings.json",
      '{"utc":' .. js(nowUtc()) ..
      ',"warningKey":' .. js(dueKey) ..
      ',"sent":true' ..
      ',"steamId":' .. js(steam) ..
      ',"name":' .. js(name) ..
      ',"warningMinutes":' .. tostring(dueMinutes) ..
      ',"leftSeconds":' .. tostring(left) ..
      ',"displayName":' .. js(displayName) ..
      ',"expiresAt":' .. tostring(expiresAt) .. '}',
      512 * 1024)
    if sentKeys ~= nil then sentKeys[dueKey] = true end
  end
  return sent
end

function rentalDestroyRetryDelay(attempts)
  local n = math.max(1, tonumber(attempts) or 1)
  local delay = 60
  for _ = 2, math.min(n, 6) do delay = delay * 2 end
  if delay > 3600 then delay = 3600 end
  return delay
end

RENTAL_DESTROY_RESOLVE_NEXT_AT = RENTAL_DESTROY_RESOLVE_NEXT_AT or 0

function rentalRuntimeDestroyResolveAllowed()
  if not configBool("vehicle-rental", { "EnableRuntimeVehicleExpireDestroy", "enableRuntimeVehicleExpireDestroy" }, true) then
    return false, "runtime vehicle lookup disabled"
  end
  local now = os.time()
  local nextAt = tonumber(RENTAL_DESTROY_RESOLVE_NEXT_AT or 0) or 0
  if nextAt > now then
    return false, "runtime vehicle lookup cooldown"
  end
  local cooldown = math.max(5, configNumber("vehicle-rental", { "RuntimeDestroyResolveCooldownSeconds", "runtimeDestroyResolveCooldownSeconds" }, 45))
  RENTAL_DESTROY_RESOLVE_NEXT_AT = now + cooldown
  return true, ""
end

function rentalDestroyMaxAttempts()
  return math.max(1, math.floor(configNumber("vehicle-rental", { "ExpireDestroyMaxAttempts", "expireDestroyMaxAttempts", "DestroyMaxAttempts", "destroyMaxAttempts" }, 6)))
end

function vehicleDestroyRefFromRental(object)
  local ref = extractString(object, "destroyRef") or extractString(object, "entityId") or extractString(object, "vehicleEntityId") or ""
  if ref == "" then
    local numeric = extractNumber(object, "entityId") or extractNumber(object, "vehicleEntityId") or extractNumber(object, "destroyRef")
    if numeric ~= nil and numeric > 0 then ref = tostring(math.floor(numeric)) end
  end
  return tostring(ref or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

function rentalTaxRecordKey(object, reason)
  local steam = extractString(object, "steamId") or ""
  local alias = (extractString(object, "alias") or extractString(object, "vehicleId") or ""):lower()
  local startedAt = extractNumber(object, "startedAt") or 0
  local destroyRef = vehicleDestroyRefFromRental(object)
  return tostring(steam) .. "|" .. tostring(alias) .. "|" .. tostring(startedAt) .. "|" .. tostring(destroyRef) .. "|" .. tostring(reason or "usage")
end

function latestRentalPendingTaxesByKey()
  local latest = {}
  for _, object in ipairs(stateObjects("vehicle-rental-pending-taxes.json")) do
    local key = extractString(object, "taxKey") or ""
    if key ~= "" then latest[key] = object end
  end
  return latest
end

function rentalTaxBreakdown(object, endTime)
  local alias = (extractString(object, "alias") or ""):lower()
  local configured = configuredRentalVehicles(true)[alias]
  local startedAt = extractNumber(object, "startedAt") or os.time()
  local effectiveEnd = math.max(startedAt, tonumber(endTime) or os.time())
  local chargeableMinutes = math.max(0, math.ceil((effectiveEnd - startedAt) / 60))
  local initialCharge = extractNumber(object, "initialCharge") or (configured and configured.initial) or 0
  local pricePer10Minutes = extractNumber(object, "pricePer10Minutes") or (configured and configured.price) or 0
  local pricePerMinute = math.max(0, math.floor(pricePer10Minutes / 10))
  if chargeableMinutes <= 10 then
    return chargeableMinutes, initialCharge, 0, 0, math.max(0, initialCharge), 0, pricePerMinute
  end
  local minutesAfter10 = chargeableMinutes - 10
  local additionalCharge = math.max(0, minutesAfter10 * pricePerMinute)
  local totalCostSoFar = initialCharge + additionalCharge
  local alreadyPaid = math.max(0, extractNumber(object, "totalCharge") or initialCharge)
  local outstanding = math.max(0, totalCostSoFar - alreadyPaid)
  return chargeableMinutes, totalCostSoFar, additionalCharge, outstanding, alreadyPaid, minutesAfter10, pricePerMinute
end

SCUM_VEHICLE_DESTRUCTION_LOG_LAST_FILE = SCUM_VEHICLE_DESTRUCTION_LOG_LAST_FILE or ""
SCUM_VEHICLE_DESTRUCTION_LOG_LAST_LOOKUP_AT = SCUM_VEHICLE_DESTRUCTION_LOG_LAST_LOOKUP_AT or 0

function latestScumVehicleDestructionLogPath()
  local nowClock = os.clock()
  local ttl = math.max(5, configNumber("bridge-safety", { "VehicleDestructionLogPathCacheSeconds", "vehicleDestructionLogPathCacheSeconds" }, 30))
  if SCUM_VEHICLE_DESTRUCTION_LOG_LAST_FILE ~= "" and (nowClock - (SCUM_VEHICLE_DESTRUCTION_LOG_LAST_LOOKUP_AT or 0)) < ttl then
    return SCUM_VEHICLE_DESTRUCTION_LOG_LAST_FILE
  end
  SCUM_VEHICLE_DESTRUCTION_LOG_LAST_LOOKUP_AT = nowClock
  local command = 'dir /b /o-d "' .. SCUM_SAVE_LOG_DIR .. '\\vehicle_destruction_*.log" 2>nul'
  local pipe = nil
  local okPipe = pcall(function() pipe = io.popen(command, "r") end)
  if not okPipe or pipe == nil then return SCUM_VEHICLE_DESTRUCTION_LOG_LAST_FILE end
  local name = cleanText(pipe:read("*l") or "")
  pipe:close()
  if name == "" then return SCUM_VEHICLE_DESTRUCTION_LOG_LAST_FILE end
  local path = SCUM_SAVE_LOG_DIR .. "\\" .. name
  SCUM_VEHICLE_DESTRUCTION_LOG_LAST_FILE = path
  return path
end

function vehicleDestructionLogStatusForRef(vehicleRef, maxBytes)
  local ref = tostring(vehicleRef or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if ref == "" or ref:find("^%d+$") == nil then return false, "", "" end
  local path = latestScumVehicleDestructionLogPath()
  if path == nil or path == "" then return false, "", "" end
  local raw = readTail(path, math.max(65536, tonumber(maxBytes) or 131072)) or ""
  if raw == "" then return false, "", "" end
  local decoded = decodeUtf16Le(raw)
  local foundStatus = ""
  local foundLine = ""
  for line in tostring(decoded or ""):gmatch("[^\r\n]+") do
    local compact = cleanText(line):gsub("%s+", " ")
    if compact:find("VehicleId: " .. ref, 1, true) ~= nil or compact:find("VehicleId:" .. ref, 1, true) ~= nil then
      if compact:find("[Failed to spawn]", 1, true) ~= nil then
        foundStatus = "failed_spawn"
        foundLine = compact
      elseif compact:find("[Disappeared]", 1, true) ~= nil then
        foundStatus = "disappeared"
        foundLine = compact
      end
    end
  end
  if foundStatus ~= "" then return true, foundStatus, foundLine end
  return false, "", ""
end

function rentalVehicleRefAlreadyGone(vehicleRef)
  local okGone, status, line = vehicleDestructionLogStatusForRef(vehicleRef, configNumber("bridge-safety", { "VehicleDestructionLogReadMaxBytes", "vehicleDestructionLogReadMaxBytes" }, 131072))
  if not okGone then return false, "", "" end
  if status == "failed_spawn" then
    return true, "vehicle already absent from vehicle_destruction log: failed to spawn", line
  end
  if status == "disappeared" then
    return true, "vehicle already disappeared in vehicle_destruction log", line
  end
  return true, "vehicle already absent from vehicle_destruction log", line
end

function rentalPositiveMissingVehicleProof(message)
  local lower = tostring(message or ""):lower()
  return lower:find("sold", 1, true) ~= nil or
    lower:find("already absent", 1, true) ~= nil or
    lower:find("already disappeared", 1, true) ~= nil or
    lower:find("vehicle_destruction", 1, true) ~= nil or
    lower:find("absent from db", 1, true) ~= nil or
    lower:find("removed from db", 1, true) ~= nil
end

function rentalAlreadyGoneVehicleProof(message)
  local lower = tostring(message or ""):lower()
  return lower:find("already absent", 1, true) ~= nil or
    lower:find("already disappeared", 1, true) ~= nil or
    lower:find("vehicle_destruction", 1, true) ~= nil
end

function rentalMissingVehicleLikely(destroyAttempted, destroyOk, destroyMessage)
  if destroyOk then return false end
  if not destroyAttempted then return false end
  local lower = tostring(destroyMessage or ""):lower()
  if rentalPositiveMissingVehicleProof(lower) then return true end
  if lower:find("missing vehicle entity id", 1, true) ~= nil or
    lower:find("missing entity id", 1, true) ~= nil or
    lower:find("runtime vehicle object not found", 1, true) ~= nil or
    lower:find("runtime vehicle lookup", 1, true) ~= nil or
    lower:find("lookup deferred", 1, true) ~= nil or
    lower:find("destroy skipped", 1, true) ~= nil or
    lower:find("not found", 1, true) ~= nil then
    return false
  end
  return false
end

function rentalMissingVehiclePenaltyAmount(object)
  local alias = (extractString(object, "alias") or ""):lower()
  local configured = configuredRentalVehicles(true)[alias]
  local amount = extractNumber(object, "missingVehiclePenalty") or extractNumber(object, "soldVehiclePenalty")
  if amount == nil and configured ~= nil then amount = tonumber(configured.penalty or 0) end
  if amount == nil then
    amount = configNumber("vehicle-rental", { "DefaultMissingVehiclePenalty", "defaultMissingVehiclePenalty", "MissingVehiclePenalty", "missingVehiclePenalty", "SoldVehiclePenalty", "soldVehiclePenalty" }, 0)
  end
  return math.max(0, tonumber(amount) or 0)
end

function chargeRentalMissingVehiclePenalty(info, object, reason)
  if not configBool("vehicle-rental", { "ChargePenaltyOnMissingVehicle", "chargePenaltyOnMissingVehicle" }, true) then
    return true, "Штраф за потерянный транспорт отключён.", 0, ""
  end
  local amount = rentalMissingVehiclePenaltyAmount(object)
  if amount <= 0 then return true, "", 0, "" end
  local resolvedLive = info ~= nil and resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or nil
  local live = resolvedLive or info
  if resolvedLive ~= nil and playerInfoHasLiveRuntime(resolvedLive) and (resolvedLive.steam or "") ~= "" then
    local charged, chargeMessage = changeMoney(resolvedLive.steam, resolvedLive.name, -amount, "Normal", resolvedLive.runtimeKey)
    appendActionEvent("vehicle_rental_missing_penalty", charged, resolvedLive,
      charged and "Штраф за потерянный/проданный транспорт поставлен в live-очередь." or tostring(chargeMessage),
      '{"reason":' .. js(reason or "missing-vehicle") .. ',"amount":' .. tostring(amount) .. '}')
    if charged then return true, chargeMessage, amount, "" end
  end
  local taxKey = appendRentalPendingTax(live or info, object, "missing-vehicle-penalty", amount, 0, 0, 0, 0, "Штраф за потерянный или проданный арендованный транспорт.")
  appendActionEvent("vehicle_rental_missing_penalty", true, live or info or {}, "Штраф за потерянный транспорт записан в ожидание.",
    '{"reason":' .. js(reason or "missing-vehicle") .. ',"amount":' .. tostring(amount) .. ',"taxKey":' .. js(taxKey or "") .. '}')
  return true, "Штраф записан в ожидание.", amount, taxKey
end

function appendRentalPendingTax(info, object, reason, amount, chargeableMinutes, minutesAfter10, totalCostSoFar, pricePerMinute, message)
  local taxKey = rentalTaxRecordKey(object, reason)
  local latest = latestRentalPendingTaxesByKey()[taxKey]
  if latest ~= nil then
    local latestStatus = (extractString(latest, "status") or ""):lower()
    if latestStatus == "pending" or latestStatus == "paid" then
      return taxKey, latestStatus
    end
  end
  local target = info or {}
  appendJsonArray(STATE_DIR .. "\\vehicle-rental-pending-taxes.json",
    '{"utc":' .. js(nowUtc()) ..
    ',"taxKey":' .. js(taxKey) ..
    ',"steamId":' .. js(extractString(object, "steamId") or target.steam or "") ..
    ',"name":' .. js(extractString(object, "name") or target.name or "") ..
    ',"alias":' .. js(extractString(object, "alias") or "") ..
    ',"displayName":' .. js(extractString(object, "displayName") or extractString(object, "vehicleId") or "vehicle") ..
    ',"vehicleId":' .. js(extractString(object, "vehicleId") or "") ..
    ',"startedAt":' .. tostring(extractNumber(object, "startedAt") or 0) ..
    ',"expiresAt":' .. tostring(extractNumber(object, "expiresAt") or 0) ..
    ',"destroyRef":' .. js(vehicleDestroyRefFromRental(object)) ..
    ',"status":"pending"' ..
    ',"reason":' .. js(reason or "usage") ..
    ',"amount":' .. tostring(math.max(0, tonumber(amount) or 0)) ..
    ',"chargeableMinutes":' .. tostring(chargeableMinutes or 0) ..
    ',"minutesAfter10":' .. tostring(minutesAfter10 or 0) ..
    ',"pricePerMinute":' .. tostring(pricePerMinute or 0) ..
    ',"totalCostSoFar":' .. tostring(totalCostSoFar or 0) ..
    ',"message":' .. js(message or "") .. '}',
    1024 * 1024)
  return taxKey, "pending"
end

function markRentalPendingTaxPaid(info, object, taxKey, amount, message)
  local target = info or {}
  appendJsonArray(STATE_DIR .. "\\vehicle-rental-pending-taxes.json",
    '{"utc":' .. js(nowUtc()) ..
    ',"taxKey":' .. js(taxKey or "") ..
    ',"steamId":' .. js(extractString(object, "steamId") or target.steam or "") ..
    ',"name":' .. js(extractString(object, "name") or target.name or "") ..
    ',"alias":' .. js(extractString(object, "alias") or "") ..
    ',"displayName":' .. js(extractString(object, "displayName") or extractString(object, "vehicleId") or "vehicle") ..
    ',"vehicleId":' .. js(extractString(object, "vehicleId") or "") ..
    ',"status":"paid"' ..
    ',"amount":' .. tostring(math.max(0, tonumber(amount) or 0)) ..
    ',"message":' .. js(message or "") .. '}',
    1024 * 1024)
end

function collectRentalPendingTaxes(info, notifyIfInsufficient)
  if info == nil then return 0, 0, true end
  local latest = latestRentalPendingTaxesByKey()
  local rows = {}
  for _, object in pairs(latest) do
    if samePlayerRecord(info, object) and (extractString(object, "status") or ""):lower() == "pending" then
      table.insert(rows, object)
    end
  end
  table.sort(rows, function(a, b)
    return tostring(extractString(a, "utc") or "") < tostring(extractString(b, "utc") or "")
  end)
  local chargedCount, chargedAmount = 0, 0
  for _, object in ipairs(rows) do
    local amount = math.max(0, extractNumber(object, "amount") or 0)
    if amount > 0 then
      local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
      local charged, chargeMessage = changeMoney(live.steam, live.name, -amount, "Normal", live.runtimeKey)
      if charged then
        markRentalPendingTaxPaid(live, object, extractString(object, "taxKey") or "", amount, chargeMessage)
        chargedCount = chargedCount + 1
        chargedAmount = chargedAmount + amount
        appendActionEvent("vehicle_rental_pending_tax", true, live, "Отложенная доплата поставлена в live-очередь.",
          '{"taxKey":' .. js(extractString(object, "taxKey") or "") .. ',"amount":' .. tostring(amount) .. '}')
      else
        appendActionEvent("vehicle_rental_pending_tax", false, live, tostring(chargeMessage),
          '{"taxKey":' .. js(extractString(object, "taxKey") or "") .. ',"amount":' .. tostring(amount) .. '}')
        if notifyIfInsufficient then
          targetMessage(live.steam, live.name,
            "У тебя есть долг по прошлой аренде: " .. tostring(amount) .. ". Сумма будет списана автоматически, когда игрок будет доступен для live-команды.",
            "vehicle-rental", live.runtimeKey)
        end
        return chargedCount, chargedAmount, false
      end
    end
  end
  return chargedCount, chargedAmount, true
end

function finalizeRentalUsageCharge(info, object, reason, endTime)
  local chargeableMinutes, totalCostSoFar, additionalCharge, outstanding, alreadyPaid, minutesAfter10, pricePerMinute = rentalTaxBreakdown(object, endTime)
  if outstanding <= 0 then
    return true, "", 0, chargeableMinutes, minutesAfter10, totalCostSoFar, alreadyPaid, pricePerMinute, ""
  end
  local live = info ~= nil and (resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info) or nil
  if live ~= nil and (live.steam or "") ~= "" then
    local charged, chargeMessage = changeMoney(live.steam, live.name, -outstanding, "Normal", live.runtimeKey)
    appendActionEvent("vehicle_rental_usage_charge", charged, live,
      charged and "Доплата аренды поставлена в live-очередь." or tostring(chargeMessage),
      '{"reason":' .. js(reason or "usage") ..
      ',"amount":' .. tostring(outstanding) ..
      ',"chargeableMinutes":' .. tostring(chargeableMinutes) ..
      ',"minutesAfter10":' .. tostring(minutesAfter10) ..
      ',"pricePerMinute":' .. tostring(pricePerMinute) ..
      ',"totalCostSoFar":' .. tostring(totalCostSoFar) ..
      ',"alreadyPaid":' .. tostring(alreadyPaid) .. '}')
    if charged then
      return true, chargeMessage, outstanding, chargeableMinutes, minutesAfter10, totalCostSoFar, alreadyPaid, pricePerMinute, ""
    end
  end
  local taxKey = ""
  taxKey = appendRentalPendingTax(live or info, object, reason, outstanding, chargeableMinutes, minutesAfter10, totalCostSoFar, pricePerMinute, "Доплата перенесена в ожидание.")
  appendActionEvent("vehicle_rental_usage_charge", false, live or info or {}, "Доплата аренды перенесена в ожидание.",
    '{"reason":' .. js(reason or "usage") ..
    ',"amount":' .. tostring(outstanding) ..
    ',"taxKey":' .. js(taxKey or "") ..
    ',"chargeableMinutes":' .. tostring(chargeableMinutes) ..
    ',"minutesAfter10":' .. tostring(minutesAfter10) ..
    ',"pricePerMinute":' .. tostring(pricePerMinute) ..
    ',"totalCostSoFar":' .. tostring(totalCostSoFar) ..
    ',"alreadyPaid":' .. tostring(alreadyPaid) .. '}')
  return false, "Доплата перенесена в ожидание.", outstanding, chargeableMinutes, minutesAfter10, totalCostSoFar, alreadyPaid, pricePerMinute, taxKey
end

function finalizeRentalUsageChargeForUntrackedReturn(info, object, reason, endTime)
  if configBool("vehicle-rental", { "ChargeUntrackedReturnUsage", "chargeUntrackedReturnUsage" }, false) then
    return finalizeRentalUsageCharge(info, object, reason, endTime)
  end
  local chargeableMinutes, totalCostSoFar, additionalCharge, outstanding, alreadyPaid, minutesAfter10, pricePerMinute = rentalTaxBreakdown(object, endTime)
  appendActionEvent("vehicle_rental_usage_charge", true, info or {}, "Доплата не начислена: транспорт не подтверждён для удаления.",
    '{"reason":' .. js(reason or "rent-return-untracked") ..
    ',"skippedUntrackedReturn":true' ..
    ',"calculatedOutstanding":' .. tostring(outstanding) ..
    ',"chargeableMinutes":' .. tostring(chargeableMinutes) ..
    ',"minutesAfter10":' .. tostring(minutesAfter10) ..
    ',"pricePerMinute":' .. tostring(pricePerMinute) ..
    ',"totalCostSoFar":' .. tostring(totalCostSoFar) ..
    ',"alreadyPaid":' .. tostring(alreadyPaid) .. '}')
  return true, "Доплата не начислена: транспорт не подтверждён для удаления.", 0, chargeableMinutes, minutesAfter10, totalCostSoFar, alreadyPaid, pricePerMinute, ""
end

function rentalCleanupStaleDestroySkipSeconds()
  return math.max(0, math.floor(configNumber("vehicle-rental", {
    "CleanupStaleDestroySkipAfterSeconds", "cleanupStaleDestroySkipAfterSeconds",
    "StaleDestroySkipAfterSeconds", "staleDestroySkipAfterSeconds"
  }, 1800) or 1800))
end

function rentalCleanupShouldSkipStaleDestroy(object, source, destroyRef)
  if tostring(source or "") ~= "cleanup-expired" then return false, "" end
  local ref = tostring(destroyRef or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if ref == "" or ref:sub(1, 8) == "runtime:" then return false, "" end
  local expiresAt = extractNumber(object, "expiresAt") or 0
  local skipAfter = rentalCleanupStaleDestroySkipSeconds()
  if expiresAt > 0 and skipAfter > 0 and os.time() > (expiresAt + skipAfter) then
    return true, "stale numeric vehicle destroy skipped after " .. tostring(skipAfter) .. " seconds"
  end
  return false, ""
end

function expireRentalObject(object, steam, name, info, source)
  steam = steam or extractString(object, "steamId") or ""
  name = name or extractString(object, "name") or ""
  local targetInfo = info or { steam = steam, name = name }
  local expiresAt = extractNumber(object, "expiresAt") or 0
  local displayName = extractString(object, "displayName") or extractString(object, "vehicleId") or "vehicle"
  local destroyRef = vehicleDestroyRefFromRental(object)
  local destroyResolveDeferred = false
  local destroyResolveAttempted = false
  local destroyResolveMessage = ""
  if destroyRef == "" then
    local canResolve, resolveReason = rentalRuntimeDestroyResolveAllowed()
    if canResolve then
      destroyResolveAttempted = true
      destroyRef = resolveRentalDestroyRef(object, targetInfo)
    else
      destroyResolveDeferred = true
      destroyResolveMessage = tostring(resolveReason or "runtime vehicle lookup deferred")
    end
  end
  local destroyAttempted = destroyRef ~= ""
  local destroyOk = false
  local destroyMessage = ""
  local destroyAttempts = math.max(0, extractNumber(object, "destroyAttempts") or 0)
  local alreadyGone = false
  local alreadyGoneLine = ""
  local destroySkippedStale = false
  if destroyAttempted and tostring(destroyRef or ""):sub(1, 8) ~= "runtime:" then
    local skipStale, staleMessage = rentalCleanupShouldSkipStaleDestroy(object, source, destroyRef)
    if skipStale then
      destroySkippedStale = true
      destroyMessage = staleMessage
      appendActionEvent("vehicle_destroy", true, targetInfo, destroyMessage,
        '{"reason":' .. js(source or "expired") .. ',"displayName":' .. js(displayName) .. ',"destroyRef":' .. js(destroyRef) .. ',"route":"cleanup-stale-skip"}')
    end
  end
  if destroyAttempted and tostring(destroyRef or ""):sub(1, 8) ~= "runtime:" then
    if not destroySkippedStale then
      alreadyGone, destroyMessage, alreadyGoneLine = rentalVehicleRefAlreadyGone(destroyRef)
      if alreadyGone then
        appendActionEvent("vehicle_destroy", true, targetInfo, destroyMessage .. "; vehicle_destruction proof triggers missing-vehicle penalty",
          '{"reason":' .. js(source or "expired") .. ',"displayName":' .. js(displayName) .. ',"destroyRef":' .. js(destroyRef) .. ',"vehicleDestructionLogLine":' .. js(alreadyGoneLine or "") .. '}')
      end
    end
  end
  if destroyAttempted and not alreadyGone and not destroySkippedStale then
    destroyAttempts = destroyAttempts + 1
    destroyOk, destroyMessage = destroyVehicleRef(destroyRef, targetInfo, source or "expired")
  elseif alreadyGone then
    destroyAttempts = destroyAttempts + 1
  elseif destroySkippedStale then
    destroyAttempts = destroyAttempts + 1
  elseif destroyResolveAttempted then
    destroyAttempts = destroyAttempts + 1
    destroyMessage = "runtime vehicle lookup did not find entity"
  elseif destroyResolveDeferred then
    destroyMessage = destroyResolveMessage ~= "" and destroyResolveMessage or "runtime vehicle lookup deferred"
    appendActionEvent("vehicle_destroy", false, targetInfo, "vehicle destroy deferred: " .. destroyMessage,
      '{"reason":' .. js(source or "expired") .. ',"displayName":' .. js(displayName) .. '}')
  else
    destroyMessage = "missing vehicle entity id"
    appendActionEvent("vehicle_destroy", false, targetInfo, "vehicle destroy skipped: missing entity id",
      '{"reason":' .. js(source or "expired") .. ',"displayName":' .. js(displayName) .. '}')
  end
  local status = "expired"
  local nextRetryAt = 0
  local missingVehicle = rentalMissingVehicleLikely(destroyAttempted, destroyOk, destroyMessage)
  local positiveMissingVehicle = rentalPositiveMissingVehicleProof(destroyMessage)
  if destroyResolveDeferred then
    status = "expire_pending"
    nextRetryAt = os.time() + rentalDestroyRetryDelay(destroyAttempts + 1)
    missingVehicle = false
  elseif not destroyAttempted and not destroyOk then
    missingVehicle = false
    if destroyAttempts < rentalDestroyMaxAttempts() and (extractString(object, "vehicleId") or "") ~= "" then
      status = "expire_pending"
      nextRetryAt = os.time() + rentalDestroyRetryDelay(destroyAttempts + 1)
    else
      status = "expired_untracked"
    end
  elseif destroySkippedStale then
    status = "expired_untracked"
    missingVehicle = false
  elseif alreadyGone then
    status = "expired_untracked"
  elseif missingVehicle then
    if positiveMissingVehicle then
      status = "expired_untracked"
    elseif destroyAttempts < rentalDestroyMaxAttempts() and (extractString(object, "vehicleId") or "") ~= "" then
      status = "expire_pending"
      nextRetryAt = os.time() + rentalDestroyRetryDelay(destroyAttempts)
      missingVehicle = false
    else
      status = "expired_untracked"
    end
  elseif destroyAttempted and not destroyOk then
    status = "expire_pending"
    nextRetryAt = os.time() + rentalDestroyRetryDelay(destroyAttempts)
  end
  local usageChargeQueued = false
  local usageChargeMessage = ""
  local usageChargeAmount = 0
  local chargeableMinutes, minutesAfter10, totalCostSoFar, alreadyPaid, pricePerMinute = 0, 0, 0, 0, 0
  local usageTaxKey = ""
  local penaltyQueued = false
  local penaltyMessage = ""
  local penaltyAmount = 0
  local penaltyTaxKey = ""
  if status == "expired" or status == "expired_untracked" then
    usageChargeQueued, usageChargeMessage, usageChargeAmount, chargeableMinutes, minutesAfter10, totalCostSoFar, alreadyPaid, pricePerMinute, usageTaxKey =
      finalizeRentalUsageCharge(targetInfo, object, source or "expired", expiresAt > 0 and expiresAt or os.time())
    if missingVehicle then
      penaltyQueued, penaltyMessage, penaltyAmount, penaltyTaxKey =
        chargeRentalMissingVehiclePenalty(targetInfo, object, source or "expired-missing-vehicle")
    end
  end
  appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
    '{"utc":' .. js(nowUtc()) ..
    ',"steamId":' .. js(steam) ..
    ',"name":' .. js(name) ..
    ',"alias":' .. js(extractString(object, "alias") or "") ..
    ',"x":' .. tostring(extractNumber(object, "x") or tonumber(targetInfo.x) or 0) ..
    ',"y":' .. tostring(extractNumber(object, "y") or tonumber(targetInfo.y) or 0) ..
    ',"z":' .. tostring(extractNumber(object, "z") or tonumber(targetInfo.z) or 0) ..
    ',"status":' .. js(status) ..
    ',"expiresAt":' .. tostring(expiresAt) ..
    ',"displayName":' .. js(displayName) ..
    ',"vehicleId":' .. js(extractString(object, "vehicleId") or "") ..
    ',"minutes":' .. tostring(extractNumber(object, "minutes") or 0) ..
    ',"startedAt":' .. tostring(extractNumber(object, "startedAt") or 0) ..
    ',"initialCharge":' .. tostring(extractNumber(object, "initialCharge") or 0) ..
    ',"pricePer10Minutes":' .. tostring(extractNumber(object, "pricePer10Minutes") or 0) ..
    ',"totalCharge":' .. tostring(extractNumber(object, "totalCharge") or 0) ..
    ',"missingVehiclePenalty":' .. tostring(rentalMissingVehiclePenaltyAmount(object)) ..
    ',"destroyRef":' .. js(destroyRef) ..
    ',"destroyAttempted":' .. (destroyAttempted and "true" or "false") ..
    ',"destroyOk":' .. (destroyOk and "true" or "false") ..
    ',"destroyAttempts":' .. tostring(destroyAttempts) ..
    ',"nextRetryAt":' .. tostring(nextRetryAt) ..
    ',"destroyMessage":' .. js(destroyMessage) ..
    ',"destroyAlreadyGone":' .. (alreadyGone and "true" or "false") ..
    ',"usageChargeQueued":' .. (usageChargeQueued and "true" or "false") ..
    ',"usageChargeAmount":' .. tostring(usageChargeAmount) ..
    ',"chargeableMinutes":' .. tostring(chargeableMinutes) ..
    ',"minutesAfter10":' .. tostring(minutesAfter10) ..
    ',"pricePerMinute":' .. tostring(pricePerMinute) ..
    ',"usageTotalCost":' .. tostring(totalCostSoFar) ..
    ',"usageAlreadyPaid":' .. tostring(alreadyPaid) ..
    ',"usageTaxKey":' .. js(usageTaxKey or "") ..
    ',"usageChargeMessage":' .. js(usageChargeMessage) ..
    ',"missingVehicle":' .. (missingVehicle and "true" or "false") ..
    ',"missingVehiclePenaltyQueued":' .. (penaltyQueued and "true" or "false") ..
    ',"missingVehiclePenaltyAmount":' .. tostring(penaltyAmount) ..
    ',"missingVehiclePenaltyTaxKey":' .. js(penaltyTaxKey or "") ..
    ',"missingVehiclePenaltyMessage":' .. js(penaltyMessage or "") .. '}',
    1024 * 1024)
  return destroyAttempted, destroyOk, destroyMessage
end

function latestActiveRental(info)
  local latest = {}
  for _, object in ipairs(stateObjects("vehicle-rentals.json")) do
    local key = rentalRecordKeyFromObject(object)
    if key ~= "" then latest[key] = object end
  end

  local keys = {}
  if info.steam ~= "" then table.insert(keys, "steam:" .. info.steam) end
  if info.name ~= "" then table.insert(keys, "name:" .. tostring(info.name):lower()) end
  for _, key in ipairs(keys) do
    local object = latest[key]
    if object ~= nil and not rentalClosed(object) then
      if rentalPendingDestroy(object) then
        -- Cleanup retries must continue, but a pending destroy/verification row is
        -- no longer an active rental for player commands or new rental blocking.
      else
      local expiresAt = extractNumber(object, "expiresAt") or 0
      if expiresAt > 0 and expiresAt <= os.time() then
        expireRentalObject(object, info.steam, info.name, info, "latest-active-expired")
      else
        return object
      end
      end
    end
  end
  return nil
end

function latestReturnableRental(info)
  if info == nil then return nil end
  local latest = {}
  local lastDetailed = {}
  for _, object in ipairs(stateObjects("vehicle-rentals.json")) do
    if samePlayerRecord(info, object) then
      local key = rentalRecordKeyFromObject(object)
      if key ~= "" then
        latest[key] = object
        if (extractString(object, "vehicleId") or "") ~= "" then
          lastDetailed[key] = object
        end
      end
    end
  end
  local keys = {}
  if info.steam ~= "" then table.insert(keys, "steam:" .. info.steam) end
  if info.name ~= "" then table.insert(keys, "name:" .. tostring(info.name):lower()) end
  for _, key in ipairs(keys) do
    local object = latest[key]
    if object ~= nil then
      if not rentalClosed(object) then return object, rentalStatus(object) end
      local status = rentalStatus(object)
      if status == "expired_untracked" or status == "missing_vehicle" or status == "sold_or_missing" then
        local detailed = lastDetailed[key]
        if detailed ~= nil then return detailed, status end
      end
    end
  end
  return nil
end

function appendActiveRentalRecord(info, alias, displayName, vehicleId, minutes, startedAt, expiresAt, initialCharge, pricePer10Minutes, totalCharge, destroyRef, extraFields, missingPenaltyOverride)
  local tracked = tostring(destroyRef or "") ~= ""
  local configured = configuredRentalVehicles(true)[(tostring(alias or "")):lower()]
  local missingPenalty = tonumber(missingPenaltyOverride)
  if missingPenalty == nil then
    missingPenalty = configured ~= nil and tonumber(configured.penalty or 0) or configNumber("vehicle-rental", { "DefaultMissingVehiclePenalty", "defaultMissingVehiclePenalty", "MissingVehiclePenalty", "missingVehiclePenalty", "SoldVehiclePenalty", "soldVehiclePenalty" }, 0)
  end
  appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
    '{"utc":' .. js(nowUtc()) ..
    ',"steamId":' .. js(info.steam or "") ..
    ',"name":' .. js(info.name or "") ..
    ',"x":' .. tostring(tonumber(info.x) or 0) ..
    ',"y":' .. tostring(tonumber(info.y) or 0) ..
    ',"z":' .. tostring(tonumber(info.z) or 0) ..
    ',"alias":' .. js(alias or "") ..
    ',"status":"active"' ..
    tostring(extraFields or "") ..
    ',"displayName":' .. js(displayName or vehicleId or "vehicle") ..
    ',"vehicleId":' .. js(vehicleId or "") ..
    ',"minutes":' .. tostring(minutes or 0) ..
    ',"startedAt":' .. tostring(startedAt or os.time()) ..
    ',"expiresAt":' .. tostring(expiresAt or 0) ..
    ',"initialCharge":' .. tostring(initialCharge or 0) ..
    ',"pricePer10Minutes":' .. tostring(pricePer10Minutes or 0) ..
    ',"totalCharge":' .. tostring(totalCharge or 0) ..
    ',"missingVehiclePenalty":' .. tostring(math.max(0, tonumber(missingPenalty) or 0)) ..
    ',"destroyRef":' .. js(destroyRef or "") ..
    ',"destroyTracked":' .. (tracked and "true" or "false") .. '}',
    1024 * 1024)
end

function rentalPenaltyNoticeText(alias, missingPenaltyOverride)
  local configured = configuredRentalVehicles(true)[(tostring(alias or "")):lower()]
  local missingPenalty = tonumber(missingPenaltyOverride)
  if missingPenalty == nil then
    missingPenalty = configured ~= nil and tonumber(configured.penalty or 0) or configNumber("vehicle-rental", { "DefaultMissingVehiclePenalty", "defaultMissingVehiclePenalty", "MissingVehiclePenalty", "missingVehiclePenalty", "SoldVehiclePenalty", "soldVehiclePenalty" }, 0)
  end
  local amount = math.max(0, tonumber(missingPenalty) or 0)
  if amount > 0 then
    local label = type(moneyLabel) == "function" and moneyLabel(amount) or tostring(amount)
    return "Если транспорт будет уничтожен, сломан или исчезнет по vehicle_destruction, будет начислен штраф: " .. tostring(label) .. "."
  end
  return "Если транспорт будет уничтожен, сломан или исчезнет по vehicle_destruction, аренда будет закрыта как потерянная."
end

RENTAL_TRACK_REFRESH_PENDING = RENTAL_TRACK_REFRESH_PENDING or {}

function completeRentalCreation(info, alias, displayName, vehicleId, minutes, initialCharge, pricePer10Minutes, totalCharge, destroyRef, startedAt, expiresAt, verifiedAfterDelay, extraFields, missingPenaltyOverride, messageOverride)
  local tracked = tostring(destroyRef or "") ~= ""
  local fields = (verifiedAfterDelay and ',"verifiedAfterDelay":true' or "") .. tostring(extraFields or "")
  appendActiveRentalRecord(info, alias, displayName, vehicleId, minutes, startedAt or os.time(), expiresAt or (os.time() + (tonumber(minutes) or 0) * 60), initialCharge, pricePer10Minutes, totalCharge, destroyRef, fields, missingPenaltyOverride)
  appendActionEvent("vehicle_rental_created", tracked, info, tracked and "rental created with runtime vehicle tracking" or "rental spawn accepted but vehicle tracking missing",
    '{"alias":' .. js(alias or "") ..
    ',"vehicleId":' .. js(vehicleId or "") ..
    ',"minutes":' .. tostring(minutes or 0) ..
    ',"charge":' .. tostring(totalCharge or 0) ..
    ',"destroyRef":' .. js(destroyRef or "") ..
    ',"destroyTracked":' .. (tracked and "true" or "false") ..
    ',"verifiedAfterDelay":' .. (verifiedAfterDelay and "true" or "false") .. '}')
  local text = tostring(messageOverride or "")
  if text == "" then
    text = "Ты арендовал " .. tostring(displayName or vehicleId or "vehicle") .. " на " .. tostring(minutes or 0) .. " мин. Списано: " .. tostring(totalCharge or 0) .. "."
  end
  local penaltyNotice = rentalPenaltyNoticeText(alias, missingPenaltyOverride)
  local lowerText = text:lower()
  if penaltyNotice ~= "" and lowerText:find("штраф", 1, true) == nil and lowerText:find("vehicle_destruction", 1, true) == nil then
    text = text .. " " .. penaltyNotice
  end
  targetMessage(info.steam, info.name, text, "vehicle-rental", info.runtimeKey)
end

function scheduleRentalCreationVerification(info, alias, option, minutes, rentalCharge, beforeVehicles, spawnX, spawnY, spawnZ)
  if info == nil or option == nil then return end
  local steamId = tostring(info.steam or "")
  local name = tostring(info.name or "")
  local runtimeKey = tostring(info.runtimeKey or "")
  local vehicleId = tostring(option.asset or "")
  local displayName = tostring(option.display or vehicleId)
  local initialCharge = tonumber(option.initial or 0) or 0
  local pricePer10Minutes = tonumber(option.price or 0) or 0
  local extraFields = tostring(option.extraFields or "")
  local missingPenaltyOverride = tonumber(option.missingPenalty or option.missingVehiclePenalty or option.penaltyOverride)
  local messageOverride = tostring(option.messageOverride or "")
  local startedAt = os.time()
  local expiresAt = startedAt + (tonumber(minutes or 0) or 0) * 60
  if not configBool("vehicle-rental", { "EnableRuntimeVehicleTrackAfterSpawn", "enableRuntimeVehicleTrackAfterSpawn" }, false) then
    deferGame(900, function()
      local live = resolvePlayerInfo(steamId, name, info, runtimeKey) or info
      local charged = true
      local chargeMessage = ""
      if tonumber(rentalCharge or 0) > 0 then
        charged, chargeMessage = changeMoney(live.steam, live.name, -rentalCharge, "Normal", live.runtimeKey)
      end
      if not charged then
        appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
          '{"utc":' .. js(nowUtc()) ..
          ',"steamId":' .. js(live.steam or steamId) ..
          ',"name":' .. js(live.name or name) ..
          ',"alias":' .. js(alias or "") ..
          ',"status":"active","chargePending":true,"chargeQueued":false' ..
          ',"displayName":' .. js(displayName) ..
          ',"vehicleId":' .. js(vehicleId) ..
          ',"minutes":' .. tostring(minutes or 0) ..
          ',"startedAt":' .. tostring(startedAt) ..
          ',"expiresAt":' .. tostring(expiresAt) ..
          ',"initialCharge":' .. tostring(initialCharge) ..
          ',"pricePer10Minutes":' .. tostring(pricePer10Minutes) ..
          ',"totalCharge":0' ..
          ',"destroyRef":""' ..
          ',"destroyTracked":false' ..
          ',"reason":' .. js("spawn accepted; charge queue failed: " .. tostring(chargeMessage or "")) .. '}',
          1024 * 1024)
        appendActionEvent("vehicle_rental_charge_pending", false, live, tostring(chargeMessage or "charge queue failed"),
          '{"alias":' .. js(alias or "") .. ',"vehicleId":' .. js(vehicleId) .. ',"charge":' .. tostring(rentalCharge or 0) .. '}')
        return
      end
      completeRentalCreation(live, alias, displayName, vehicleId, minutes, initialCharge, pricePer10Minutes, rentalCharge, "", startedAt, expiresAt, true, extraFields, missingPenaltyOverride, messageOverride)
      appendActionEvent("vehicle_rental_tracking_safe_skip", true, live, "spawn accepted; runtime vehicle scan skipped for stability",
        '{"alias":' .. js(alias or "") .. ',"vehicleId":' .. js(vehicleId) .. ',"charge":' .. tostring(rentalCharge or 0) .. '}')
    end)
    return
  end
  local function completeWithRef(live, ref, verifiedAfterDelay)
    if ref ~= "" then
      local charged, chargeMessage = true, ""
      if tonumber(rentalCharge or 0) > 0 then
        charged, chargeMessage = changeMoney(live.steam, live.name, -rentalCharge, "Normal", live.runtimeKey)
      end
      if not charged then
        destroyVehicleRef(ref, live, "rental-charge-failed")
        appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
          '{"utc":' .. js(nowUtc()) ..
          ',"steamId":' .. js(live.steam or steamId) ..
          ',"name":' .. js(live.name or name) ..
          ',"alias":' .. js(alias or "") ..
          ',"status":"failed"' ..
          ',"displayName":' .. js(displayName) ..
          ',"vehicleId":' .. js(vehicleId) ..
          ',"minutes":' .. tostring(minutes or 0) ..
          ',"startedAt":' .. tostring(startedAt) ..
          ',"expiresAt":' .. tostring(expiresAt) ..
          ',"totalCharge":' .. tostring(rentalCharge or 0) ..
          ',"destroyRef":' .. js(ref) ..
          ',"reason":"charge not confirmed after verified spawn"}',
          1024 * 1024)
        appendActionEvent("vehicle_rental_charge_failed", false, live, tostring(chargeMessage),
          '{"alias":' .. js(alias or "") .. ',"vehicleId":' .. js(vehicleId) .. ',"charge":' .. tostring(rentalCharge or 0) .. ',"destroyRef":' .. js(ref) .. ',"stage":"after-spawn-verified"}')
        targetMessage(live.steam, live.name, "Транспорт появился, но оплату не удалось подтвердить. Аренда отменена, транспорт удалён.", "vehicle-rental", live.runtimeKey)
        return
      end
      completeRentalCreation(live, alias, displayName, vehicleId, minutes, initialCharge, pricePer10Minutes, rentalCharge, ref, startedAt, expiresAt, true, extraFields, missingPenaltyOverride, messageOverride)
      return
    end
    return false
  end
  local function failUnverified(live, reason)
    local charged, chargeMessage = true, ""
    if tonumber(rentalCharge or 0) > 0 then
      charged, chargeMessage = changeMoney(live.steam, live.name, -rentalCharge, "Normal", live.runtimeKey)
    end
    if not charged then
      appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
        '{"utc":' .. js(nowUtc()) ..
        ',"steamId":' .. js(live.steam or steamId) ..
        ',"name":' .. js(live.name or name) ..
        ',"alias":' .. js(alias or "") ..
        ',"status":"failed"' ..
        ',"displayName":' .. js(displayName) ..
        ',"vehicleId":' .. js(vehicleId) ..
        ',"minutes":' .. tostring(minutes or 0) ..
        ',"startedAt":' .. tostring(startedAt) ..
        ',"expiresAt":' .. tostring(expiresAt) ..
        ',"totalCharge":' .. tostring(rentalCharge or 0) ..
        ',"charged":false' ..
        ',"refundQueued":false' ..
        ',"reason":' .. js("charge not confirmed after accepted spawn: " .. tostring(reason or "")) .. '}',
        1024 * 1024)
      appendActionEvent("vehicle_rental_charge_failed", false, live, tostring(chargeMessage),
        '{"alias":' .. js(alias or "") .. ',"vehicleId":' .. js(vehicleId) .. ',"charge":' .. tostring(rentalCharge or 0) .. ',"stage":"accepted-spawn-untracked"}')
      targetMessage(live.steam, live.name, "Транспорт отправлен, но оплату не удалось подтвердить. Деньги не списывал.", "vehicle-rental", live.runtimeKey)
      do return end
    end
    completeRentalCreation(live, alias, displayName, vehicleId, minutes, initialCharge, pricePer10Minutes, rentalCharge, "", startedAt, expiresAt, true, extraFields, missingPenaltyOverride, messageOverride)
    appendActionEvent("vehicle_rental_tracking_pending", true, live, "spawn command accepted; rental active while runtime tracking is pending",
      '{"alias":' .. js(alias or "") .. ',"vehicleId":' .. js(vehicleId) .. ',"reason":' .. js(reason or "spawn not verified immediately") .. '}')
    if type(scheduleRentalTrackingRefresh) == "function" then
      scheduleRentalTrackingRefresh(live, alias, vehicleId, beforeVehicles, 1)
    end
    do return end
    appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
      '{"utc":' .. js(nowUtc()) ..
      ',"steamId":' .. js(live.steam or steamId) ..
      ',"name":' .. js(live.name or name) ..
      ',"alias":' .. js(alias or "") ..
      ',"status":"failed"' ..
      ',"displayName":' .. js(displayName) ..
      ',"vehicleId":' .. js(vehicleId) ..
      ',"minutes":' .. tostring(minutes or 0) ..
      ',"startedAt":' .. tostring(startedAt) ..
      ',"expiresAt":' .. tostring(expiresAt) ..
      ',"totalCharge":' .. tostring(rentalCharge or 0) ..
      ',"charged":false' ..
      ',"refundQueued":false' ..
      ',"reason":' .. js(reason or "spawn not verified") .. '}',
      1024 * 1024)
    appendActionEvent("vehicle_rental_spawn_unverified", false, live, "spawn command accepted but runtime vehicle was not found; no charge was made",
      '{"alias":' .. js(alias or "") .. ',"vehicleId":' .. js(vehicleId) .. ',"charged":false,"chargeRefunded":0,"reason":' .. js(reason or "spawn not verified") .. '}')
    targetMessage(live.steam, live.name, "Транспорт не подтверждён после выдачи. Деньги не списывал, попробуй ещё раз или выбери другой транспорт.", "vehicle-rental", live.runtimeKey)
  end
  deferGame(2200, function()
    local live = resolvePlayerInfo(steamId, name, info, runtimeKey) or info
    local ref = nearestNewVehicleRefAt(spawnX, spawnY, spawnZ, vehicleId, beforeVehicles, true, true)
    if completeWithRef(live, ref, true) ~= false then return end
    failUnverified(live, "spawn accepted but runtime tracking delayed")
    do return end
    if steamId ~= "" then
      local fallbackBefore = vehicleRuntimeKeySet(vehicleId, true)
      local fallbackCommand = "SpawnVehicle " .. vehicleId .. " 1 Location " .. steamId
      local sentFallback, fallbackMessage = adminExec(fallbackCommand, live)
      appendActionEvent("vehicle_rental_spawn_location_fallback", sentFallback, live, tostring(fallbackMessage or ""),
        '{"alias":' .. js(alias or "") .. ',"vehicleId":' .. js(vehicleId) .. ',"command":' .. js(fallbackCommand) .. '}')
      if sentFallback then
        deferGame(2400, function()
          local liveAfter = resolvePlayerInfo(steamId, name, live, runtimeKey) or live
          local fallbackRef = nearestNewVehicleRefAt(spawnX, spawnY, spawnZ, vehicleId, fallbackBefore, true, true)
          if completeWithRef(liveAfter, fallbackRef, true) ~= false then return end
          failUnverified(liveAfter, "spawn location fallback not verified")
        end)
        return
      end
    end
    failUnverified(live, "spawn not verified")
  end)
end

function scheduleRentalTrackingRefresh(info, alias, vehicleId, beforeVehicles, attempt)
  if info == nil or tostring(vehicleId or "") == "" then return end
  local steamId = tostring(info.steam or "")
  local name = tostring(info.name or "")
  local runtimeKey = tostring(info.runtimeKey or "")
  local refreshKey = tostring(steamId) .. "|" .. tostring(alias or "") .. "|" .. tostring(vehicleId or "")
  if RENTAL_TRACK_REFRESH_PENDING[refreshKey] then return end
  RENTAL_TRACK_REFRESH_PENDING[refreshKey] = true
  local tries = math.max(1, tonumber(attempt) or 1)
  local delayMs = 900 + math.min(tries, 4) * 350
  deferGame(delayMs, function()
    local live = resolvePlayerInfo(steamId, name, info, runtimeKey) or info
    local active = latestActiveRental(live)
    if active == nil then
      RENTAL_TRACK_REFRESH_PENDING[refreshKey] = nil
      return
    end
    local currentRef = vehicleDestroyRefFromRental(active)
    if currentRef ~= "" then
      RENTAL_TRACK_REFRESH_PENDING[refreshKey] = nil
      return
    end
    local ref = nearestNewVehicleRef(live, vehicleId, beforeVehicles, true, true)
    if ref == "" then
      RENTAL_TRACK_REFRESH_PENDING[refreshKey] = nil
      if tries < 4 then
        scheduleRentalTrackingRefresh(live, alias, vehicleId, beforeVehicles, tries + 1)
        return
      end
      appendActionEvent("vehicle_rental_tracking", false, live, "runtime vehicle tracking still not found",
        '{"alias":' .. js(alias or "") .. ',"vehicleId":' .. js(vehicleId or "") .. ',"attempt":' .. tostring(tries) .. '}')
      return
    end
    appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
      '{"utc":' .. js(nowUtc()) ..
      ',"steamId":' .. js(extractString(active, "steamId") or steamId) ..
      ',"name":' .. js(extractString(active, "name") or name) ..
      ',"alias":' .. js(extractString(active, "alias") or alias or "") ..
      ',"status":"active","trackingRefreshedAt":' .. tostring(os.time()) ..
      ',"displayName":' .. js(extractString(active, "displayName") or extractString(active, "vehicleId") or vehicleId) ..
      ',"vehicleId":' .. js(extractString(active, "vehicleId") or vehicleId) ..
      ',"x":' .. tostring(tonumber(live.x) or 0) ..
      ',"y":' .. tostring(tonumber(live.y) or 0) ..
      ',"z":' .. tostring(tonumber(live.z) or 0) ..
      ',"minutes":' .. tostring(extractNumber(active, "minutes") or 0) ..
      ',"startedAt":' .. tostring(extractNumber(active, "startedAt") or os.time()) ..
      ',"expiresAt":' .. tostring(extractNumber(active, "expiresAt") or 0) ..
      ',"initialCharge":' .. tostring(extractNumber(active, "initialCharge") or 0) ..
      ',"pricePer10Minutes":' .. tostring(extractNumber(active, "pricePer10Minutes") or 0) ..
      ',"totalCharge":' .. tostring(extractNumber(active, "totalCharge") or extractNumber(active, "initialCharge") or 0) ..
      ',"trackingRefreshAttempt":' .. tostring(tries) ..
      ',"destroyRef":' .. js(ref) ..
      ',"destroyTracked":true}',
      1024 * 1024)
    appendActionEvent("vehicle_rental_tracking", true, live, "runtime vehicle tracking refreshed",
      '{"alias":' .. js(alias or "") .. ',"vehicleId":' .. js(vehicleId or "") .. ',"destroyRef":' .. js(ref) .. ',"attempt":' .. tostring(tries) .. '}')
    RENTAL_TRACK_REFRESH_PENDING[refreshKey] = nil
  end)
end

cleanupExpiredRentals = function()
  local latest = {}
  for _, object in ipairs(stateObjects("vehicle-rentals.json")) do
    local key = rentalRecordKeyFromObject(object)
      if key ~= "" then latest[key] = object end
  end
  local processed = 0
  local warningsSent = 0
  local now = os.time()
  local dueRentals = {}
  local maxWarningsPerRun = math.max(1, configNumber("vehicle-rental", { "WarningMaxPerRun", "warningMaxPerRun" }, 5))
  local warningKeys = latestRentalWarningKeys()
  for key, object in pairs(latest) do
    if not rentalClosed(object) then
      local expiresAt = extractNumber(object, "expiresAt") or 0
      local retryAt = extractNumber(object, "nextRetryAt") or 0
      local dueActive = expiresAt > 0 and expiresAt <= now and not rentalPendingDestroy(object)
      local dueRetry = rentalPendingDestroy(object) and (retryAt <= 0 or retryAt <= now)
      if dueActive or dueRetry then
        local initialCharge = extractNumber(object, "initialCharge") or 0
        local totalCharge = extractNumber(object, "totalCharge") or 0
        table.insert(dueRentals, {
          key = key,
          object = object,
          dueRetry = dueRetry,
          paidRank = (initialCharge > 0 or totalCharge > 0) and 0 or 1,
          expiresAt = expiresAt,
          retryAt = retryAt
        })
      elseif warningsSent < maxWarningsPerRun and sendRentalExpiryWarningIfNeeded(object, warningKeys) then
        warningsSent = warningsSent + 1
      end
    end
  end
  table.sort(dueRentals, function(a, b)
    if a.dueRetry ~= b.dueRetry then return not a.dueRetry end
    if a.paidRank ~= b.paidRank then return a.paidRank < b.paidRank end
    if a.expiresAt ~= b.expiresAt then return a.expiresAt > b.expiresAt end
    if a.retryAt ~= b.retryAt then return a.retryAt < b.retryAt end
    return tostring(a.key or "") < tostring(b.key or "")
  end)
  local maxPerRun = math.max(1, configNumber("vehicle-rental", { "CleanupMaxPerRun", "cleanupMaxPerRun" }, 1))
  for _, due in ipairs(dueRentals) do
    local object = due.object
    processed = (processed or 0) + 1
    local steam = extractString(object, "steamId") or ""
    local name = extractString(object, "name") or ""
    local attempted, destroyed = expireRentalObject(object, steam, name, { steam = steam, name = name }, "cleanup-expired")
    local suffix = attempted and (destroyed and " Транспорт удалён." or " Удаление транспорта не подтверждено, будет повторная попытка.") or " Нет entityId для удаления, смотри журнал действий."
    local noticeSent, noticeRoute = sendRentalNoticeMessage(steam, name, extractString(object, "runtimeKey") or "",
      "Срок аренды транспорта истёк. Запись отмечена в панели." .. suffix, "vehicle-rental", "expired")
    appendActionEvent("vehicle_rental_expired_notice", noticeSent, { steam = steam, name = name }, tostring(noticeRoute or ""),
      '{"displayName":' .. js(extractString(object, "displayName") or extractString(object, "vehicleId") or "") ..
      ',"attemptedDestroy":' .. (attempted and "true" or "false") ..
      ',"destroyed":' .. (destroyed and "true" or "false") .. '}')
    if processed >= maxPerRun then return end
  end
end

MUTATION_QUEUE = MUTATION_QUEUE or {}
MUTATION_QUEUE_BUSY = MUTATION_QUEUE_BUSY or false
MUTATION_QUEUE_CURRENT = MUTATION_QUEUE_CURRENT or nil
MUTATION_QUEUE_NEXT_AT = MUTATION_QUEUE_NEXT_AT or 0
MUTATION_QUEUE_SEQ = MUTATION_QUEUE_SEQ or 0
MUTATION_QUEUE_MAX = MUTATION_QUEUE_MAX or 120
MUTATION_QUEUE_SPACING_MS = MUTATION_QUEUE_SPACING_MS or 0
MUTATION_QUEUE_PLAYER_MAX = MUTATION_QUEUE_PLAYER_MAX or 2
MUTATION_QUEUE_TIMEOUT_SECONDS = MUTATION_QUEUE_TIMEOUT_SECONDS or 45
MUTATION_QUEUE_REENTRANT_DEPTH = MUTATION_QUEUE_REENTRANT_DEPTH or 0

function refreshMutationQueueLimits()
  MUTATION_QUEUE_MAX = math.max(10, math.min(math.floor(configNumber("bridge-safety", { "MutationQueueMax", "mutationQueueMax" }, MUTATION_QUEUE_MAX or 120) or 120), 500))
  MUTATION_QUEUE_SPACING_MS = math.max(0, math.min(math.floor(configNumber("bridge-safety", { "MutationQueueSpacingMs", "mutationQueueSpacingMs" }, MUTATION_QUEUE_SPACING_MS or 0) or 0), 5000))
  MUTATION_QUEUE_PLAYER_MAX = math.max(1, math.min(math.floor(configNumber("bridge-safety", { "MutationQueuePlayerMax", "mutationQueuePlayerMax" }, MUTATION_QUEUE_PLAYER_MAX or 2) or 2), 20))
  MUTATION_QUEUE_TIMEOUT_SECONDS = math.max(15, math.min(math.floor(configNumber("bridge-safety", { "MutationQueueTimeoutSeconds", "mutationQueueTimeoutSeconds" }, MUTATION_QUEUE_TIMEOUT_SECONDS or 45) or 45), 300))
end

function mutationQueueCurrentAgeSeconds()
  local item = MUTATION_QUEUE_CURRENT
  if item == nil then return 0 end
  local started = tonumber(item.startedAt) or tonumber(item.queuedAt) or os.time()
  return math.max(0, os.time() - started)
end

function mutationQueueDepth()
  local depth = #MUTATION_QUEUE
  if MUTATION_QUEUE_BUSY then depth = depth + 1 end
  return depth
end

function mutationQueueSpacingForItem(item)
  local label = tostring((item or {}).label or "")
  if label == "spawn-actor" then
    return math.max(0, math.min(math.floor(configNumber("bridge-safety", { "SummonActorQueueSpacingMs", "summonActorQueueSpacingMs" }, 2500) or 2500), 15000))
  end
  if label == "base-loot-collector" then
    return math.max(0, math.min(math.floor(configNumber("bridge-safety", { "BaseLootQueueSpacingMs", "baseLootQueueSpacingMs" }, 750) or 750), 10000))
  end
  return tonumber(MUTATION_QUEUE_SPACING_MS) or 0
end

function mutationPlayerKey(info)
  if info == nil then return "" end
  if type(playerStateKey) == "function" then
    local key = playerStateKey(info)
    if tostring(key or "") ~= "" then return tostring(key) end
  end
  local steam = tostring(info.steam or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if steam ~= "" then return "steam:" .. steam end
  local name = tostring(info.name or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if name ~= "" and name ~= "Unknown" then return "name:" .. name:lower() end
  local runtimeKey = tostring(info.runtimeKey or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if runtimeKey ~= "" then return "runtime:" .. runtimeKey end
  return ""
end

function mutationQueuePlayerDepth(info)
  local key = mutationPlayerKey(info)
  if key == "" then return 0 end
  local depth = 0
  if MUTATION_QUEUE_CURRENT ~= nil and mutationPlayerKey(MUTATION_QUEUE_CURRENT.info) == key then
    depth = depth + 1
  end
  for _, item in ipairs(MUTATION_QUEUE or {}) do
    if mutationPlayerKey(item.info) == key then depth = depth + 1 end
  end
  return depth
end

function mutationQueueEntryJson(item)
  if item == nil then return "null" end
  local age = 0
  if item == MUTATION_QUEUE_CURRENT then age = mutationQueueCurrentAgeSeconds() end
  return '{"id":' .. tostring(item.id or 0) ..
    ',"label":' .. js(item.label or "") ..
    ',"queuedAt":' .. tostring(item.queuedAt or 0) ..
    ',"startedAt":' .. tostring(item.startedAt or 0) ..
    ',"ageSeconds":' .. tostring(age) ..
    ',"cancelled":' .. ((item.cancelled == true) and "true" or "false") ..
    ',"target":' .. js((item.info and (item.info.name or item.info.steam)) or "") .. '}'
end

function mutationQueueStatusJson()
  refreshMutationQueueLimits()
  local nowMs = math.floor(os.clock() * 1000)
  local nextDelay = math.max(0, (tonumber(MUTATION_QUEUE_NEXT_AT) or 0) - nowMs)
  local preview = {}
  local limit = math.min(#(MUTATION_QUEUE or {}), 20)
  for i = 1, limit do table.insert(preview, mutationQueueEntryJson(MUTATION_QUEUE[i])) end
  local playerCommands = ""
  if type(playerCommandQueueStatusJson) == "function" then
    playerCommands = ',"playerCommands":' .. playerCommandQueueStatusJson()
  end
  return '{"available":true' ..
    ',"depth":' .. tostring(mutationQueueDepth()) ..
    ',"pending":' .. tostring(#(MUTATION_QUEUE or {})) ..
    ',"busy":' .. ((MUTATION_QUEUE_BUSY and "true") or "false") ..
    ',"current":' .. mutationQueueEntryJson(MUTATION_QUEUE_CURRENT) ..
    ',"max":' .. tostring(MUTATION_QUEUE_MAX or 0) ..
    ',"perPlayerMax":' .. tostring(MUTATION_QUEUE_PLAYER_MAX or 0) ..
    ',"spacingMs":' .. tostring(MUTATION_QUEUE_SPACING_MS or 0) ..
    ',"timeoutSeconds":' .. tostring(MUTATION_QUEUE_TIMEOUT_SECONDS or 0) ..
    ',"currentAgeSeconds":' .. tostring(mutationQueueCurrentAgeSeconds()) ..
    ',"nextDelayMs":' .. tostring(nextDelay) ..
    ',"sequence":' .. tostring(MUTATION_QUEUE_SEQ or 0) ..
    ',"lastAction":' .. tostring(LAST_ACTION_EVENT_JSON or "null") ..
    ',"lastDelivery":' .. tostring(LAST_DELIVERY_EVENT_JSON or "null") ..
    ',"pendingPreview":[' .. table.concat(preview, ",") .. ']' ..
    playerCommands ..
    '}'
end

function finishMutationQueueAsync(item, okRun, message)
  if item == nil then return end
  if item.cancelled == true or MUTATION_QUEUE_CURRENT ~= item then
    appendLog("mutation async finish ignored id=" .. tostring(item.id) .. " label=" .. tostring(item.label))
    return
  end
  MUTATION_QUEUE_BUSY = false
  MUTATION_QUEUE_CURRENT = nil
  MUTATION_QUEUE_REENTRANT_DEPTH = 0
  MUTATION_QUEUE_NEXT_AT = math.floor(os.clock() * 1000) + mutationQueueSpacingForItem(item)
  appendActionEvent("mutation_queue", okRun ~= false, item.info,
    tostring(message or ((okRun ~= false) and "Асинхронное действие выполнено" or "Асинхронное действие завершилось ошибкой")),
    '{"label":' .. js(item.label or "") .. ',"id":' .. tostring(item.id or 0) .. ',"remaining":' .. tostring(#(MUTATION_QUEUE or {})) .. ',"async":true}')
  appendLog("mutation async done id=" .. tostring(item.id) .. " label=" .. tostring(item.label) .. " ok=" .. tostring(okRun ~= false) .. " depth=" .. tostring(#(MUTATION_QUEUE or {})))
  if #(MUTATION_QUEUE or {}) > 0 and type(drainMutationQueue) == "function" then
    local okNext, nextErr = pcall(drainMutationQueue)
    if not okNext then appendLog("mutation async next drain failed: " .. tostring(nextErr)) end
  end
end

function enqueueMutation(label, info, fn)
  refreshMutationQueueLimits()
  if type(fn) ~= "function" then
    return false, "Внутренняя ошибка очереди: действие не задано.", #MUTATION_QUEUE
  end
  if (MUTATION_QUEUE_REENTRANT_DEPTH or 0) > 0 then
    appendActionEvent("mutation_queue", true, info, "Вложенное действие выполняется внутри текущей очереди", '{"label":' .. js(label or "") .. ',"inline":true}')
    local okRun, err = pcall(fn, nil)
    if okRun then
      appendActionEvent("mutation_queue", true, info, "Вложенное действие выполнено", '{"label":' .. js(label or "") .. ',"inline":true}')
      appendLog("mutation inline done label=" .. tostring(label or "mutation"))
      return true, 0, mutationQueueDepth()
    end
    appendActionEvent("mutation_queue", false, info, "Ошибка вложенного действия: " .. tostring(err), '{"label":' .. js(label or "") .. ',"inline":true}')
    appendLog("mutation inline error label=" .. tostring(label or "mutation") .. " err=" .. tostring(err))
    return false, "Ошибка вложенного игрового действия: " .. tostring(err), mutationQueueDepth()
  end
  if #MUTATION_QUEUE >= MUTATION_QUEUE_MAX then
    appendActionEvent("mutation_queue", false, info, "Очередь игровых действий переполнена", '{"label":' .. js(label or "") .. ',"depth":' .. tostring(#MUTATION_QUEUE) .. '}')
    return false, "Очередь игровых действий переполнена. Повтори команду чуть позже.", #MUTATION_QUEUE
  end
  local playerDepth = mutationQueuePlayerDepth(info)
  if playerDepth >= MUTATION_QUEUE_PLAYER_MAX then
    appendActionEvent("mutation_queue", false, info, "У игрока уже есть активные действия в очереди", '{"label":' .. js(label or "") .. ',"playerDepth":' .. tostring(playerDepth) .. '}')
    return false, "Твои выдачи уже обрабатываются. Подожди очередь и повтори чуть позже.", mutationQueueDepth()
  end
  MUTATION_QUEUE_SEQ = MUTATION_QUEUE_SEQ + 1
  table.insert(MUTATION_QUEUE, { id = MUTATION_QUEUE_SEQ, label = tostring(label or "mutation"), info = info, fn = fn, queuedAt = os.time() })
  appendActionEvent("mutation_queue", true, info, "Действие поставлено в очередь", '{"label":' .. js(label or "") .. ',"id":' .. tostring(MUTATION_QUEUE_SEQ) .. ',"depth":' .. tostring(#MUTATION_QUEUE) .. '}')
  appendLog("mutation queued id=" .. tostring(MUTATION_QUEUE_SEQ) .. " label=" .. tostring(label or "mutation") .. " depth=" .. tostring(#MUTATION_QUEUE))
  if type(drainMutationQueue) == "function" and not MUTATION_QUEUE_BUSY then
    local insidePlayerCommand = PLAYER_COMMAND_QUEUE_BUSY == true or PLAYER_COMMAND_QUEUE_CURRENT ~= nil
    -- Never re-enter the UE4SS game thread from a player-command callback.
    -- The independent loop pump drains this item after the callback returns.
    if insidePlayerCommand then
      appendLog("mutation drain left for loop pump after player command label=" .. tostring(label or "mutation") .. " id=" .. tostring(MUTATION_QUEUE_SEQ))
    else
      local okDrain, drainErr = pcall(drainMutationQueue)
      if not okDrain then appendLog("mutation immediate drain failed: " .. tostring(drainErr)) end
    end
  end
  return true, MUTATION_QUEUE_SEQ, #MUTATION_QUEUE
end

function drainMutationQueue()
  local nowMs = math.floor(os.clock() * 1000)
  refreshMutationQueueLimits()
  if MUTATION_QUEUE_BUSY then
    local current = MUTATION_QUEUE_CURRENT
    local ageSeconds = mutationQueueCurrentAgeSeconds()
    if current ~= nil and ageSeconds >= (tonumber(MUTATION_QUEUE_TIMEOUT_SECONDS) or 45) then
      current.cancelled = true
      appendActionEvent("mutation_queue", false, current.info, "Действие live-очереди превысило лимит времени и снято, чтобы очередь не зависла.",
        '{"label":' .. js(current.label or "") .. ',"id":' .. tostring(current.id or 0) .. ',"ageSeconds":' .. tostring(ageSeconds) .. ',"timeoutSeconds":' .. tostring(MUTATION_QUEUE_TIMEOUT_SECONDS or 0) .. '}')
      appendLog("mutation timeout id=" .. tostring(current.id) .. " label=" .. tostring(current.label) .. " ageSeconds=" .. tostring(ageSeconds) .. " depth=" .. tostring(#MUTATION_QUEUE))
      MUTATION_QUEUE_BUSY = false
      MUTATION_QUEUE_CURRENT = nil
      MUTATION_QUEUE_REENTRANT_DEPTH = 0
      MUTATION_QUEUE_NEXT_AT = nowMs + mutationQueueSpacingForItem(current)
    else
      return
    end
  end
  if nowMs < (tonumber(MUTATION_QUEUE_NEXT_AT) or 0) then return end
  local item = table.remove(MUTATION_QUEUE, 1)
  if item == nil then return end
  MUTATION_QUEUE_BUSY = true
  MUTATION_QUEUE_CURRENT = item
  item.startedAt = os.time()
  item.cancelled = false
  appendLog("mutation start id=" .. tostring(item.id) .. " label=" .. tostring(item.label) .. " depth=" .. tostring(#MUTATION_QUEUE))

  local function runItem()
    if item.cancelled == true or MUTATION_QUEUE_CURRENT ~= item then
      appendLog("mutation stale start ignored id=" .. tostring(item.id) .. " label=" .. tostring(item.label))
      return
    end
    MUTATION_QUEUE_REENTRANT_DEPTH = (MUTATION_QUEUE_REENTRANT_DEPTH or 0) + 1
    local okRun, err = pcall(item.fn, item)
    MUTATION_QUEUE_REENTRANT_DEPTH = math.max(0, (MUTATION_QUEUE_REENTRANT_DEPTH or 1) - 1)
    if item.cancelled == true or MUTATION_QUEUE_CURRENT ~= item then
      appendLog("mutation stale finish ignored id=" .. tostring(item.id) .. " label=" .. tostring(item.label))
      return
    end
    if okRun and err == "__mutation_async__" then
      appendLog("mutation async pending id=" .. tostring(item.id) .. " label=" .. tostring(item.label))
      return
    end
    MUTATION_QUEUE_BUSY = false
    MUTATION_QUEUE_CURRENT = nil
    MUTATION_QUEUE_NEXT_AT = math.floor(os.clock() * 1000) + mutationQueueSpacingForItem(item)
    if #(MUTATION_QUEUE or {}) > 0 and type(drainMutationQueue) == "function" then
      local okNext, nextErr = pcall(drainMutationQueue)
      if not okNext then appendLog("mutation immediate next drain failed: " .. tostring(nextErr)) end
    end
    if okRun then
      appendActionEvent("mutation_queue", true, item.info, "Действие выполнено", '{"label":' .. js(item.label) .. ',"id":' .. tostring(item.id) .. ',"remaining":' .. tostring(#MUTATION_QUEUE) .. '}')
      appendLog("mutation done id=" .. tostring(item.id) .. " label=" .. tostring(item.label) .. " depth=" .. tostring(#MUTATION_QUEUE))
    else
      appendActionEvent("mutation_queue", false, item.info, "Ошибка действия: " .. tostring(err), '{"label":' .. js(item.label) .. ',"id":' .. tostring(item.id) .. ',"remaining":' .. tostring(#MUTATION_QUEUE) .. '}')
      appendLog("mutation error id=" .. tostring(item.id) .. " label=" .. tostring(item.label) .. " err=" .. tostring(err))
    end
  end

  if deferGame(0, runItem) then return end

  local executeInGameThread = schedulerFunction("ExecuteInGameThread")
  if executeInGameThread ~= nil then
    local okThread, err = pcall(function() executeInGameThread(runItem) end)
    if okThread then return end
    appendLog("mutation ExecuteInGameThread failed, running inline: " .. tostring(err))
  end

  runItem()
end

splitWords = function(text)
  local words = {}
  for word in tostring(text or ""):gmatch("%S+") do table.insert(words, word) end
  return words
end

SCHEDULED_EVENT_RUN_CACHE = SCHEDULED_EVENT_RUN_CACHE or {}
SCHEDULED_EVENT_STARTUP_DONE = SCHEDULED_EVENT_STARTUP_DONE or false
SCHEDULED_EVENT_BOOT_ID = SCHEDULED_EVENT_BOOT_ID or tostring(os.time())

function trimText(value)
  return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

function jsonArrayObjects(text, key)
  local array = tostring(text or ""):match('"' .. tostring(key or "") .. '"%s*:%s*(%b[])')
  local rows = {}
  if array == nil then return rows end
  for object in array:gmatch("%b{}") do table.insert(rows, object) end
  return rows
end

function splitCsv(text)
  local rows = {}
  for part in tostring(text or ""):gmatch("[^,;]+") do
    local value = trimText(part)
    if value ~= "" then table.insert(rows, value) end
  end
  return rows
end

function scheduledEventRunSeen(runKey)
  local key = tostring(runKey or "")
  if key == "" then return true end
  if SCHEDULED_EVENT_RUN_CACHE[key] then return true end
  for _, object in ipairs(stateObjects("scheduled-events-runs.json")) do
    if (extractString(object, "runKey") or "") == key then
      SCHEDULED_EVENT_RUN_CACHE[key] = true
      return true
    end
  end
  return false
end

function markScheduledEventRun(runKey, jobName, mode, reason)
  local key = tostring(runKey or "")
  if key == "" then return end
  SCHEDULED_EVENT_RUN_CACHE[key] = true
  appendJsonArray(STATE_DIR .. "\\scheduled-events-runs.json",
    '{"utc":' .. js(nowUtc()) ..
    ',"at":' .. tostring(os.time()) ..
    ',"runKey":' .. js(key) ..
    ',"job":' .. js(jobName or "") ..
    ',"mode":' .. js(mode or "") ..
    ',"reason":' .. js(reason or "") .. '}',
    512 * 1024)
end

function scheduledPointFromObject(object)
  return {
    name = extractStringAny(object, { "Name", "name" }) or "",
    group = (extractStringAny(object, { "Group", "group" }) or ""):lower(),
    x = extractNumberAny(object, { "X", "x" }, 0) or 0,
    y = extractNumberAny(object, { "Y", "y" }, 0) or 0,
    z = extractNumberAny(object, { "Z", "z" }, 50) or 50,
    radius = extractNumberAny(object, { "Radius", "radius" }, 0) or 0
  }
end

function scheduledItemSetFromObject(object)
  return {
    name = extractStringAny(object, { "Name", "name" }) or "",
    weight = extractNumberAny(object, { "Weight", "weight" }, 1) or 1,
    itemsText = extractStringAny(object, { "ItemsText", "itemsText", "ItemsSpec", "itemsSpec" }) or itemsSpecFromConfig(object)
  }
end

function pickScheduledPoint(points, group)
  local selected = pickScheduledPoints(points, group, 1)
  return selected[1]
end

function pickScheduledPoints(points, group, count)
  local wanted = tostring(group or ""):lower()
  local candidates = {}
  for _, point in ipairs(points or {}) do
    if wanted == "" or tostring(point.group or "") == wanted then table.insert(candidates, point) end
  end
  if #candidates == 0 then return {} end
  local wantedCount = math.max(1, math.min(tonumber(count) or 1, #candidates))
  local firstIndex = (os.time() % #candidates) + 1
  local selected = {}
  for offset = 0, wantedCount - 1 do
    local index = ((firstIndex - 1 + offset) % #candidates) + 1
    table.insert(selected, candidates[index])
  end
  return selected
end

function findScheduledItemSet(itemSets, name)
  local wanted = tostring(name or ""):lower()
  local fallback = nil
  for _, itemSet in ipairs(itemSets or {}) do
    if fallback == nil then fallback = itemSet end
    if wanted ~= "" and tostring(itemSet.name or ""):lower() == wanted then return itemSet end
  end
  return fallback
end

function schedulerLiveAdminInfo()
  local infos = listPlayerInfos()
  for _, info in ipairs(infos or {}) do
    if info ~= nil and ((info.pc ~= nil and isValidObject(info.pc)) or (info.rpc ~= nil and isValidObject(info.rpc))) then
      return info
    end
  end
  return nil
end

function scheduledLivePlayerRef(info)
  local steam = cleanText((info or {}).steam or (info or {}).steamId or "")
  if looksLikeSteamId(steam) then return steam end
  local name = cleanText((info or {}).name or "")
  if name == "" or name:lower() == "unknown" then return "" end
  if name:find("[\r\n\"\\]") ~= nil then return "" end
  return '"' .. name .. '"'
end

function scumCoordText(value)
  local n = tonumber(value)
  if n == nil then n = 0 end
  local text = string.format("%.3f", n)
  text = text:gsub("0+$", ""):gsub("%.$", "")
  if text == "-0" then text = "0" end
  return text
end

function cargoDropWorldEventCommandForInfo(info)
  local resolved = info or {}
  if not playerHasUsableLocation(resolved) then
    local refreshed = refreshRuntimePlayerInfo(resolved)
    if refreshed ~= nil and playerHasUsableLocation(refreshed) then resolved = refreshed end
  end
  if not playerHasUsableLocation(resolved) then
    local logInfo = resolvePlayerInfoFromServerLogTarget((resolved or {}).steam, (resolved or {}).name)
    if logInfo ~= nil and playerHasUsableLocation(logInfo) then
      for _, key in ipairs({ "steam", "name", "userProfileId", "serverUserProfileId", "runtimeKey", "x", "y", "z" }) do
        local value = logInfo[key]
        if value ~= nil and tostring(value or "") ~= "" then resolved[key] = value end
      end
    end
  end
  if not playerHasUsableLocation(resolved) then return "", resolved, "нет live-координат игрока" end
  return "ScheduleWorldEvent BP_CargoDropEvent X=" .. scumCoordText(resolved.x) ..
    " Y=" .. scumCoordText(resolved.y) ..
    " Z=" .. scumCoordText(resolved.z), resolved, "ok"
end

function scheduledTemplateKey(template)
  local text = trimText(template):gsub("^#", "")
  text = text:lower():gsub("%s+", " ")
  return trimText(text)
end

function scheduledIsLegacyCargoDropTemplate(template)
  local key = scheduledTemplateKey(template)
  return key == "scheduleworldevent cargodrop {x} {y} {z}" or
    key == "scheduleworldevent bp_cargodropevent {x} {y} {z}"
end

function scheduledWorldEventClass(job)
  local raw = extractStringAny(job, { "WorldEventClass", "worldEventClass", "EventClass", "eventClass" }) or "BP_CargoDropEvent"
  raw = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if raw == "" then return "BP_CargoDropEvent" end
  if raw:find("[^%w_%.%-]") ~= nil then return "" end
  return raw
end

function scheduledTemplateNeedsPlayer(template)
  local lower = tostring(template or ""):lower()
  return lower:find("{player}", 1, true) ~= nil or
    lower:find("{adminplayer}", 1, true) ~= nil or
    lower:find("{playersteam}", 1, true) ~= nil or
    lower:find("{adminsteam}", 1, true) ~= nil or
    lower:find("{playername}", 1, true) ~= nil or
    lower:find("{adminname}", 1, true) ~= nil
end

function expandScheduledTemplate(template, point, itemSetName, liveInfo, worldEventClass)
  local playerRef = scheduledLivePlayerRef(liveInfo)
  local playerSteam = cleanText((liveInfo or {}).steam or (liveInfo or {}).steamId or "")
  local playerName = cleanText((liveInfo or {}).name or "")
  local profile = cleanText((liveInfo or {}).userProfileId or (liveInfo or {}).serverUserProfileId or (liveInfo or {}).profileId or "")
  local values = {
    X = point ~= nil and tostring(point.x or 0) or "0",
    Y = point ~= nil and tostring(point.y or 0) or "0",
    Z = point ~= nil and tostring(point.z or 50) or "50",
    Radius = point ~= nil and tostring(point.radius or 0) or "0",
    Point = point ~= nil and tostring(point.name or "") or "",
    PointGroup = point ~= nil and tostring(point.group or "") or "",
    ItemSet = tostring(itemSetName or ""),
    WorldEventClass = tostring(worldEventClass or ""),
    EventClass = tostring(worldEventClass or ""),
    Player = playerRef,
    AdminPlayer = playerRef,
    PlayerSteam = playerSteam,
    AdminSteam = playerSteam,
    PlayerName = playerName,
    AdminName = playerName,
    Profile = profile,
    ProfileId = profile
  }
  return tostring(template or ""):gsub("{([A-Za-z_]+)}", function(key)
    return values[key] or ("{" .. key .. "}")
  end)
end

function normalizeScheduledCommand(command)
  local text = trimText(command)
  if text == "" then return "" end
  return text:gsub("^%s*#", "")
end

function runScheduledCommand(jobName, mode, commandText, point, itemSetName, liveOverride, worldEventClass)
  local live = liveOverride or schedulerLiveAdminInfo()
  local command = normalizeScheduledCommand(expandScheduledTemplate(commandText, point, itemSetName, live, worldEventClass))
  if command == "" then return false, "Команда расписания пустая." end
  local sent, message = adminExec(command, live)
  appendActionEvent("scheduled_event_command", sent, live,
    sent and ("Планировщик выполнил команду: " .. command) or ("Планировщик не выполнил команду: " .. tostring(message)),
    '{"job":' .. js(jobName or "") .. ',"mode":' .. js(mode or "") .. ',"command":' .. js(command) .. ',"point":' .. js(point and point.name or "") .. '}')
  if sent then return true, tostring(message or "ok") end
  return false, tostring(message or "admin route failed")
end

function runScheduledSpawnItems(job, jobName, points, itemSets)
  local point = pickScheduledPoint(points, extractStringAny(job, { "PointGroup", "pointGroup" }) or "")
  if point == nil then return false, "Не найдена точка для задания." end
  local setName = extractStringAny(job, { "ItemSet", "itemSet" }) or ""
  local itemSet = findScheduledItemSet(itemSets, setName)
  if itemSet == nil or tostring(itemSet.itemsText or "") == "" then return false, "Не найден набор предметов." end
  local items = parseItemsSpec(itemSet.itemsText)
  if #items == 0 then return false, "Набор предметов пустой." end
  local maxItems = math.max(1, math.min(extractNumberAny(job, { "MaxItemsPerRun", "maxItemsPerRun" }, 30) or 30, 100))
  local okCount = 0
  local failCount = 0
  local live = schedulerLiveAdminInfo()
  for index, item in ipairs(items) do
    if index > maxItems then break end
    local safeItem = itemAdminCommandId(item.itemId)
    local qty = math.max(1, math.min(tonumber(item.quantity) or 1, 100))
    if safeItem == "" then
      failCount = failCount + 1
    else
      local command = "SpawnItem " .. safeItem .. " " .. tostring(qty) .. " Location " .. tostring(point.x) .. " " .. tostring(point.y) .. " " .. tostring(point.z)
      local sent = adminExec(command, live)
      if sent then okCount = okCount + 1 else failCount = failCount + 1 end
    end
  end
  local success = okCount > 0 and failCount == 0
  appendActionEvent("scheduled_event_spawn_items", success, live,
    "Планировщик: выдано строк набора " .. tostring(okCount) .. ", ошибок " .. tostring(failCount) .. ".",
    '{"job":' .. js(jobName or "") .. ',"itemSet":' .. js(itemSet.name or setName) .. ',"point":' .. js(point.name or "") .. ',"ok":' .. tostring(okCount) .. ',"failed":' .. tostring(failCount) .. '}')
  local announcement = extractStringAny(job, { "Announcement", "announcement" }) or ""
  if announcement ~= "" and okCount > 0 then broadcast(expandScheduledTemplate(announcement, point, itemSet.name or setName)) end
  return okCount > 0, "items=" .. tostring(okCount) .. " failed=" .. tostring(failCount)
end

function executeScheduledJob(job, jobName, mode, points, itemSets, reason)
  local normalizedMode = tostring(mode or "Command"):lower()
  local okRun = false
  local message = ""
  if normalizedMode == "spawnitems" or normalizedMode == "items" then
    okRun, message = runScheduledSpawnItems(job, jobName, points, itemSets)
  elseif normalizedMode == "airdrop" then
    local pointGroup = extractStringAny(job, { "PointGroup", "pointGroup" }) or ""
    local pointCount = math.max(1, math.min(extractNumberAny(job, { "PointCount", "pointCount", "DropCount", "dropCount" }, 1) or 1, 10))
    local selectedPoints = pickScheduledPoints(points, pointGroup, pointCount)
    local command = extractStringAny(job, { "CommandTemplate", "commandTemplate" }) or ""
    if command == "" or scheduledIsLegacyCargoDropTemplate(command) then
      command = "ScheduleWorldEvent BP_CargoDropEvent X={X} Y={Y} Z={Z}"
    end
    if #selectedPoints == 0 then
      okRun, message = false, "Не найдена точка для задания."
    else
      local successCount = 0
      local messages = {}
      for _, point in ipairs(selectedPoints) do
        local pointOk, pointMessage = runScheduledCommand(jobName, mode, command, point, "", nil, "BP_CargoDropEvent")
        if pointOk then successCount = successCount + 1 end
        table.insert(messages, tostring(point.name or "?") .. "=" .. tostring(pointMessage or ""))
      end
      okRun = successCount == #selectedPoints
      message = "drops=" .. tostring(successCount) .. "/" .. tostring(#selectedPoints) .. " " .. table.concat(messages, "; ")
    end
    local announcement = extractStringAny(job, { "Announcement", "announcement" }) or ""
    if okRun and announcement ~= "" then
      local announcePoint = selectedPoints[1]
      broadcast(expandScheduledTemplate(announcement, announcePoint, "", nil, "BP_CargoDropEvent"))
    end
  elseif normalizedMode == "worldevent" or normalizedMode == "world-event" or normalizedMode == "event" then
    local eventClass = scheduledWorldEventClass(job)
    if eventClass == "" then
      okRun, message = false, "Класс world event задан небезопасно."
    else
      local pointGroup = extractStringAny(job, { "PointGroup", "pointGroup" }) or ""
      local pointCount = math.max(1, math.min(extractNumberAny(job, { "PointCount", "pointCount" }, 1) or 1, 10))
      local selectedPoints = pickScheduledPoints(points, pointGroup, pointCount)
      local command = extractStringAny(job, { "CommandTemplate", "commandTemplate" }) or ""
      if command == "" then command = "ScheduleWorldEvent {WorldEventClass} X={X} Y={Y} Z={Z}" end
      if #selectedPoints == 0 then
        okRun, message = false, "Не найдена точка для задания."
      else
        local successCount = 0
        local messages = {}
        for _, point in ipairs(selectedPoints) do
          local pointOk, pointMessage = runScheduledCommand(jobName, mode, command, point, "", nil, eventClass)
          if pointOk then successCount = successCount + 1 end
          table.insert(messages, tostring(point.name or "?") .. "=" .. tostring(pointMessage or ""))
        end
        okRun = successCount == #selectedPoints
        message = "worldEvents=" .. tostring(successCount) .. "/" .. tostring(#selectedPoints) .. " " .. table.concat(messages, "; ")
      end
      local announcement = extractStringAny(job, { "Announcement", "announcement" }) or ""
      if okRun and announcement ~= "" then
        local announcePoint = selectedPoints[1]
        broadcast(expandScheduledTemplate(announcement, announcePoint, "", nil, eventClass))
      end
    end
  else
    local command = extractStringAny(job, { "CommandTemplate", "commandTemplate" }) or ""
    okRun, message = runScheduledCommand(jobName, mode, command, nil, "", nil, scheduledWorldEventClass(job))
    local announcement = extractStringAny(job, { "Announcement", "announcement" }) or ""
    if okRun and announcement ~= "" then broadcast(expandScheduledTemplate(announcement, nil, "", nil, scheduledWorldEventClass(job))) end
  end
  appendLog("scheduled event executed job=" .. tostring(jobName) ..
    " ok=" .. tostring(okRun) ..
    " reason=" .. tostring(reason or "") ..
    " message=" .. tostring(message))
  return okRun, message
end

function scheduledEventsConfigSnapshot()
  local text = configText("scheduled-events")
  local jobs = {}
  local points = {}
  local itemSets = {}
  if text ~= "" then
    jobs = jsonArrayObjects(text, "Jobs")
    for _, object in ipairs(jsonArrayObjects(text, "Points")) do table.insert(points, scheduledPointFromObject(object)) end
    for _, object in ipairs(jsonArrayObjects(text, "ItemSets")) do table.insert(itemSets, scheduledItemSetFromObject(object)) end
  end
  return text, jobs, points, itemSets
end

function scheduledEventsRunNow(text, command, requestId)
  local rawIndex = extractNumberAny(text, { "index", "Index", "jobIndex", "JobIndex" }, nil)
  if rawIndex == nil then return fail(command, "Индекс задания планировщика не задан.", requestId) end
  local force = extractBoolAny(text, { "force", "Force" }, false) == true
  local _, jobs, points, itemSets = scheduledEventsConfigSnapshot()
  local luaIndex = math.floor(tonumber(rawIndex) or -1) + 1
  if luaIndex < 1 or luaIndex > #jobs then
    local oneBased = math.floor(tonumber(rawIndex) or -1)
    if oneBased >= 1 and oneBased <= #jobs then luaIndex = oneBased end
  end
  if luaIndex < 1 or luaIndex > #jobs then
    return failWithData(command, "Задание планировщика не найдено.",
      '{"index":' .. tostring(rawIndex) .. ',"jobs":' .. tostring(#jobs) .. '}', requestId)
  end
  if not force and configBool("scheduled-events", { "Enabled", "enabled" }, false) == false then
    return fail(command, "Планировщик заданий отключён.", requestId)
  end
  local job = jobs[luaIndex]
  local jobName = extractStringAny(job, { "Name", "name" }) or ("job-" .. tostring(luaIndex))
  local mode = extractStringAny(job, { "Mode", "mode" }) or "Command"
  if not force and extractBoolAny(job, { "Enabled", "enabled" }, true) == false then
    return failWithData(command, "Задание планировщика отключено.",
      '{"index":' .. tostring(luaIndex - 1) .. ',"job":' .. js(jobName) .. ',"mode":' .. js(mode) .. '}', requestId)
  end
  local queued, queueIdOrMessage, depth = enqueueMutation("scheduled-events-manual", nil, function()
    local okRun, message = executeScheduledJob(job, jobName, mode, points, itemSets, "manual")
    local data = '{"index":' .. tostring(luaIndex - 1) ..
      ',"job":' .. js(jobName) ..
      ',"mode":' .. js(mode) ..
      ',"manual":true' ..
      ',"force":' .. tostring(force) ..
      ',"message":' .. js(message or "") .. '}'
    if okRun then
      writeAll(RESULT_FILE, ok(command, message or "Задание планировщика выполнено.", data, requestId))
    else
      writeAll(RESULT_FILE, failWithData(command, message or "Задание планировщика не выполнено.", data, requestId))
    end
  end)
  if not queued then return fail(command, tostring(queueIdOrMessage or "Не удалось поставить задание планировщика в live-очередь."), requestId) end
  appendActionEvent("scheduled_event_manual_queued", true, nil, "Задание планировщика поставлено в ручную очередь.",
    '{"index":' .. tostring(luaIndex - 1) ..
    ',"job":' .. js(jobName) ..
    ',"mode":' .. js(mode) ..
    ',"queueId":' .. tostring(queueIdOrMessage or 0) ..
    ',"depth":' .. tostring(depth or 0) ..
    ',"force":' .. tostring(force) .. '}')
  return nil
end

function shouldRunScheduledJob(job, index, now)
  if extractBoolAny(job, { "Enabled", "enabled" }, true) == false then return false end
  local name = extractStringAny(job, { "Name", "name" }) or ("job-" .. tostring(index))
  local mode = extractStringAny(job, { "Mode", "mode" }) or "Command"
  if not SCHEDULED_EVENT_STARTUP_DONE and extractBoolAny(job, { "RunOnStartup", "runOnStartup" }, false) == true then
    local key = "startup|" .. SCHEDULED_EVENT_BOOT_ID .. "|" .. tostring(index) .. "|" .. name
    if not scheduledEventRunSeen(key) then return true, key, name, mode, "startup" end
  end
  local times = splitCsv(extractStringAny(job, { "ScheduleTimes", "scheduleTimes" }) or "")
  if #times > 0 then
    local current = os.date("%H:%M", now)
    local day = os.date("%Y-%m-%d", now)
    for _, timeValue in ipairs(times) do
      if timeValue == current then
        local key = "time|" .. day .. "|" .. current .. "|" .. tostring(index) .. "|" .. name
        if not scheduledEventRunSeen(key) then return true, key, name, mode, "time " .. current end
      end
    end
    return false
  end
  local intervalMinutes = extractNumberAny(job, { "IntervalMinutes", "intervalMinutes" }, 0) or 0
  if intervalMinutes > 0 then
    local bucket = math.floor(now / math.max(60, intervalMinutes * 60))
    local key = "interval|" .. tostring(bucket) .. "|" .. tostring(index) .. "|" .. name
    if not scheduledEventRunSeen(key) then return true, key, name, mode, "interval " .. tostring(intervalMinutes) .. "m" end
  end
  return false
end

function drainScheduledEvents()
  local text, jobs, points, itemSets = scheduledEventsConfigSnapshot()
  if text == "" then return end
  if configBool("scheduled-events", { "Enabled", "enabled" }, false) == false then return end
  if #jobs == 0 then return end
  local maxRuns = math.max(1, math.min(configNumber("scheduled-events", { "MaxRunsPerTick", "maxRunsPerTick" }, 1) or 1, 5))
  local now = os.time()
  local queuedThisTick = 0
  for index, job in ipairs(jobs) do
    if queuedThisTick >= maxRuns then break end
    local shouldRun, runKey, jobName, mode, reason = shouldRunScheduledJob(job, index, now)
    if shouldRun then
      local queued, queueIdOrMessage = enqueueMutation("scheduled-events", nil, function()
        executeScheduledJob(job, jobName, mode, points, itemSets, reason)
      end)
      if queued then
        queuedThisTick = queuedThisTick + 1
        markScheduledEventRun(runKey, jobName, mode, reason)
        appendActionEvent("scheduled_event_queued", true, nil, "Задание расписания поставлено в очередь.",
          '{"job":' .. js(jobName or "") .. ',"mode":' .. js(mode or "") .. ',"reason":' .. js(reason or "") .. ',"queueId":' .. tostring(queueIdOrMessage or 0) .. '}')
      else
        appendActionEvent("scheduled_event_queued", false, nil, tostring(queueIdOrMessage or "Не удалось поставить задание расписания в очередь."),
          '{"job":' .. js(jobName or "") .. ',"mode":' .. js(mode or "") .. ',"reason":' .. js(reason or "") .. '}')
      end
    end
  end
  SCHEDULED_EVENT_STARTUP_DONE = true
end

function zoneRobotRunSeen(key)
  local wanted = tostring(key or "")
  if wanted == "" then return true end
  for _, object in ipairs(stateObjects("zone-robot-schedule-runs.json")) do
    if (extractStringAny(object, { "key", "Key" }) or "") == wanted then return true end
  end
  return false
end

function markZoneRobotRun(key, name, phase, reason)
  if tostring(key or "") == "" then return false end
  return appendJsonArray(STATE_DIR .. "\\zone-robot-schedule-runs.json",
    '{"utc":' .. js(nowUtc()) ..
    ',"key":' .. js(key) ..
    ',"name":' .. js(name or "") ..
    ',"phase":' .. js(phase or "") ..
    ',"reason":' .. js(reason or "") .. '}',
    1024 * 1024)
end

function zoneRobotCommandText(rule, phase)
  local templateKeys = phase == "off" and { "CommandTemplateOff", "commandTemplateOff" } or { "CommandTemplateOn", "commandTemplateOn" }
  local template = extractStringAny(rule, templateKeys) or ""
  if template == "" then return "" end
  local zone = extractStringAny(rule, { "Zone", "zone", "Point", "point" }) or ""
  local name = extractStringAny(rule, { "Name", "name" }) or zone
  return applyVars(template, {
    Zone = zone,
    zone = zone,
    Name = name,
    name = name,
    Phase = phase,
    phase = phase
  })
end

function shouldRunZoneRobotRule(rule, index, now)
  if extractBoolAny(rule, { "Enabled", "enabled" }, true) == false then return false end
  local name = extractStringAny(rule, { "Name", "name" }) or ("zone-rule-" .. tostring(index))
  local day = os.date("%Y-%m-%d", now)
  local current = os.date("%H:%M", now)
  local checks = {
    { phase = "on", times = splitCsv(extractStringAny(rule, { "ScheduleTimesOn", "scheduleTimesOn", "TimesOn", "timesOn" }) or "") },
    { phase = "off", times = splitCsv(extractStringAny(rule, { "ScheduleTimesOff", "scheduleTimesOff", "TimesOff", "timesOff" }) or "") }
  }
  for _, check in ipairs(checks) do
    for _, timeValue in ipairs(check.times) do
      if timeValue == current then
        local key = "time|" .. day .. "|" .. current .. "|" .. check.phase .. "|" .. tostring(index) .. "|" .. name
        if not zoneRobotRunSeen(key) then return true, key, name, check.phase, "time " .. current end
      end
    end
  end
  return false
end

function runZoneRobotRule(rule, index, runKey, name, phase, reason)
  local command = normalizeScheduledCommand(zoneRobotCommandText(rule, phase))
  if command == "" then
    markZoneRobotRun(runKey, name, phase, reason .. " empty-command")
    appendActionEvent("zone_robot_schedule", false, nil, "Пустая команда расписания зоны.",
      '{"name":' .. js(name or "") .. ',"phase":' .. js(phase or "") .. '}')
    return false
  end
  local queued, queueIdOrMessage = enqueueMutation("zone-robot-schedule", nil, function()
    local live = schedulerLiveAdminInfo()
    local okRun, message = adminExec(command, live)
    appendActionEvent("zone_robot_schedule", okRun, live,
      okRun and ("Зонная команда выполнена: " .. tostring(name) .. " " .. tostring(phase)) or ("Зонная команда не выполнена: " .. tostring(message or "")),
      '{"name":' .. js(name or "") .. ',"phase":' .. js(phase or "") .. ',"command":' .. js(command) .. ',"reason":' .. js(reason or "") .. '}')
    if okRun then
      local announcement = phase == "off" and
        (extractStringAny(rule, { "AnnouncementOff", "announcementOff" }) or "") or
        (extractStringAny(rule, { "AnnouncementOn", "announcementOn" }) or "")
      if announcement ~= "" then
        local zone = extractStringAny(rule, { "Zone", "zone", "Point", "point" }) or ""
        broadcast(applyVars(announcement, { Zone = zone, zone = zone, Name = name, name = name, Phase = phase, phase = phase }))
      end
    end
  end)
  if queued then
    markZoneRobotRun(runKey, name, phase, reason)
    return true
  end
  appendActionEvent("zone_robot_schedule", false, nil, tostring(queueIdOrMessage or "Не удалось поставить зонную команду в очередь."),
    '{"name":' .. js(name or "") .. ',"phase":' .. js(phase or "") .. ',"command":' .. js(command) .. '}')
  return false
end

function drainZoneRobotSchedule()
  if not moduleEnabled("zone-robot-schedule", false) then return end
  local rules = moduleArrayObjects("zone-robot-schedule", "Rules")
  if #rules == 0 then return end
  local maxRuns = math.max(1, math.min(configNumber("zone-robot-schedule", { "MaxRunsPerTick", "maxRunsPerTick" }, 1) or 1, 5))
  local now = os.time()
  local queued = 0
  for index, rule in ipairs(rules) do
    if queued >= maxRuns then break end
    local shouldRun, runKey, name, phase, reason = shouldRunZoneRobotRule(rule, index, now)
    if shouldRun and runZoneRobotRule(rule, index, runKey, name, phase, reason) then
      queued = queued + 1
    end
  end
end

function sectorFromCoordinates(x, y)
  local minX, maxX = -900000, 600000
  local minY, maxY = -900000, 600000
  local sectorRows = { "D", "C", "B", "A", "Z" }
  local sectorColumns = { "0", "1", "2", "3", "4" }
  local cellX = (maxX - minX) / 5
  local cellY = (maxY - minY) / 5
  local col = math.floor(((x - minX) / cellX))
  local row = math.floor(((maxY - y) / cellY))
  if col < 0 then col = 0 elseif col > 4 then col = 4 end
  if row < 0 then row = 0 elseif row > 4 then row = 4 end
  return sectorRows[row + 1] .. sectorColumns[col + 1]
end

function normalizeSectorCode(value)
  local text = tostring(value or ""):upper():gsub("[^A-Z0-9]", "")
  if #text ~= 2 then return "" end
  local row = text:sub(1, 1)
  local col = text:sub(2, 2)
  if row ~= "D" and row ~= "C" and row ~= "B" and row ~= "A" and row ~= "Z" then return "" end
  if col ~= "4" and col ~= "3" and col ~= "2" and col ~= "1" and col ~= "0" then return "" end
  return row .. col
end

function sectorHelpText()
  return "Формат: " .. commandUsage("scan", " B2") .. " или " .. commandUsage("scan", " C0") .. ". Доступные строки: D, C, B, A, Z; колонки: 0, 1, 2, 3, 4."
end

SECTOR_SCAN_PLAYERS_CACHE = nil
SECTOR_SCAN_PLAYERS_CACHE_AT = 0
SECTOR_SCAN_LAST_CACHE_HIT = false

function sectorScanPlayerInfos(maxAgeSeconds, includeInfo)
  local maxAge = math.max(1, tonumber(maxAgeSeconds) or 8)
  local cacheSeconds = math.max(0, configNumber("sector-scan", { "ScanRuntimeCacheSeconds", "scanRuntimeCacheSeconds" }, 3))
  local now = os.clock()
  SECTOR_SCAN_LAST_CACHE_HIT = false
  if SECTOR_SCAN_PLAYERS_CACHE ~= nil and cacheSeconds > 0 and (now - (tonumber(SECTOR_SCAN_PLAYERS_CACHE_AT) or 0)) <= cacheSeconds then
    SECTOR_SCAN_LAST_CACHE_HIT = true
    local cached = {}
    local seenCached = {}
    local function addCached(info)
      if info == nil then return end
      local x = tonumber(info.x)
      local y = tonumber(info.y)
      if x == nil or y == nil or x ~= x or y ~= y or (math.abs(x) + math.abs(y)) <= 1 then return end
      local key = playerStateKey(info)
      if key == "" then key = tostring(info.runtimeKey or "") end
      if key == "" then key = tostring(info.name or "") .. "|" .. tostring(info.x or "") .. "|" .. tostring(info.y or "") end
      if key == "" or seenCached[key] then return end
      seenCached[key] = true
      table.insert(cached, info)
    end
    for _, cachedInfo in ipairs(SECTOR_SCAN_PLAYERS_CACHE or {}) do addCached(cachedInfo) end
    addCached(includeInfo)
    return cached
  end
  local infos = cachedPlayerInfos(maxAge) or {}
  if #infos == 0 then
    local okRefresh, err = pcall(refreshPlayerInfoCache)
    if not okRefresh then appendLog("sector scan player refresh failed: " .. tostring(err)) end
    infos = cachedPlayerInfos(maxAge) or {}
  end

  local result = {}
  local seen = {}
  local function add(info)
    if info == nil then return end
    local live = refreshRuntimePlayerInfo(info)
    if live == nil then return end
    live = enrichPlayerInfoFromServerLog(live) or live
    local x = tonumber(live.x)
    local y = tonumber(live.y)
    if x == nil or y == nil or x ~= x or y ~= y or (math.abs(x) + math.abs(y)) <= 1 then return end
    local key = playerStateKey(live)
    if key == "" then key = tostring(live.runtimeKey or "") end
    if key == "" then key = tostring(live.name or "") .. "|" .. tostring(live.x or "") .. "|" .. tostring(live.y or "") end
    if key == "" or seen[key] then return end
    seen[key] = true
    table.insert(result, live)
  end

  for _, info in ipairs(infos or {}) do add(info) end
  add(includeInfo)
  SECTOR_SCAN_PLAYERS_CACHE = result
  SECTOR_SCAN_PLAYERS_CACHE_AT = now
  return result
end

function appendHome(info, label)
  local nameLabel = tostring(label or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if nameLabel == "" then nameLabel = "home" end
  local targetInfo = info or {}
  local homeInfo = targetInfo
  local okRefresh, refreshed = pcall(function() return refreshRuntimePlayerInfo(targetInfo) end)
  if okRefresh and refreshed ~= nil then homeInfo = refreshed end
  if not playerHasUsableLocation(homeInfo) then
    local steam = homeInfo.steam or homeInfo.steamId or targetInfo.steam or targetInfo.steamId
    local name = homeInfo.name or targetInfo.name
    local runtimeKey = homeInfo.runtimeKey or targetInfo.runtimeKey
    local okResolve, resolved = pcall(function() return resolvePlayerInfo(steam, name, homeInfo, runtimeKey) end)
    if okResolve and resolved ~= nil then
      homeInfo = resolved
      local okRefreshResolved, refreshedResolved = pcall(function() return refreshRuntimePlayerInfo(resolved) end)
      if okRefreshResolved and refreshedResolved ~= nil then homeInfo = refreshedResolved end
    end
  end
  if not playerHasUsableLocation(homeInfo) then
    appendLog("sethome skipped: live location missing label=" .. nameLabel .. " target=" .. tostring((targetInfo.steam or targetInfo.steamId or targetInfo.name or "")))
    return false
  end
  local x = tonumber(homeInfo.x)
  local y = tonumber(homeInfo.y)
  local z = tonumber(homeInfo.z)
  local record = '{"utc":' .. js(nowUtc()) ..
    ',"label":' .. js(nameLabel) ..
    ',"steamId":' .. js(homeInfo.steam or homeInfo.steamId or "") ..
    ',"name":' .. js(homeInfo.name or "") ..
    ',"userProfileId":' .. js(homeInfo.userProfileId or homeInfo.serverUserProfileId or "") ..
    ',"x":' .. tostring(x) ..
    ',"y":' .. tostring(y) ..
    ',"z":' .. tostring(z) .. '}'
  local rows = {}
  local replaced = false
  local wantedLabel = nameLabel:lower()
  for _, object in ipairs(stateObjects("homes.json")) do
    local homeLabel = tostring(extractString(object, "label") or "home"):lower()
    if samePlayerRecord(homeInfo, object) and homeLabel == wantedLabel then
      if not replaced then
        table.insert(rows, record)
        replaced = true
      end
    else
      table.insert(rows, object)
    end
  end
  if not replaced then table.insert(rows, record) end
  return writeStateObjects("homes.json", rows)
end

function homesForInfo(info)
  local homes = {}
  for _, object in ipairs(stateObjects("homes.json")) do
    if samePlayerRecord(info, object) then
      local label = extractString(object, "label") or "home"
      homes[label:lower()] = {
        label = label,
        x = extractNumber(object, "x") or 0,
        y = extractNumber(object, "y") or 0,
        z = extractNumber(object, "z") or 0
      }
    end
  end
  local rows = {}
  for _, home in pairs(homes) do table.insert(rows, home) end
  table.sort(rows, function(a, b) return tostring(a.label):lower() < tostring(b.label):lower() end)
  return rows
end

function homeByLabel(info, label)
  local wanted = tostring(label or ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
  local homes = homesForInfo(info)
  if wanted == "" then
    if #homes == 1 then return homes[1] end
    return nil
  end
  for _, home in ipairs(homes) do
    if tostring(home.label):lower() == wanted then return home end
  end
  return nil
end

function homeListText(info)
  local homes = homesForInfo(info)
  if #homes == 0 then return "У тебя ещё нет установленных домов." end
  local lines = {}
  for _, home in ipairs(homes) do table.insert(lines, "- " .. tostring(home.label)) end
  return "Дома: " .. table.concat(lines, ", ")
end

function deleteHomes(info, label)
  local path = STATE_DIR .. "\\homes.json"
  local text = readAll(path) or "[]"
  local kept = {}
  local removed = 0
  local wanted = tostring(label or ""):lower()
  for object in text:gmatch("%b{}") do
    local steam = extractString(object, "steamId") or ""
    local name = extractString(object, "name") or ""
    local homeLabel = extractString(object, "label") or "home"
    local samePlayer = (info.steam ~= "" and steam == info.steam) or (info.name ~= "" and name == info.name)
    local sameLabel = wanted == "" or tostring(homeLabel):lower() == wanted
    if samePlayer and sameLabel then
      removed = removed + 1
    else
      table.insert(kept, object)
    end
  end
  writeAll(path, "[" .. table.concat(kept, ",") .. "]")
  return removed
end

pmReplies = {}

function playerReplyKey(info)
  if info == nil then return "" end
  if tostring(info.steam or "") ~= "" then return tostring(info.steam) end
  return tostring(info.name or "")
end

function recordPmReply(left, right)
  local leftKey = playerReplyKey(left)
  local rightKey = playerReplyKey(right)
  if leftKey ~= "" and right ~= nil then pmReplies[leftKey] = { steam = right.steam or "", name = right.name or "" } end
  if rightKey ~= "" and left ~= nil then pmReplies[rightKey] = { steam = left.steam or "", name = left.name or "" } end
end

function privateMessageCooldownRemaining(info)
  if not configBool("private-messages", { "UseCooldown", "useCooldown" }, true) then return 0 end
  local seconds = configNumber("private-messages", { "CooldownTimeSeconds", "cooldownTimeSeconds" }, 3)
  return cooldownRemaining("private-message-cooldowns.json", info, seconds)
end

function rememberPrivateMessageCooldown(info)
  if configBool("private-messages", { "UseCooldown", "useCooldown" }, true) then
    rememberCooldown("private-message-cooldowns.json", info, configNumber("private-messages", { "CooldownTimeSeconds", "cooldownTimeSeconds" }, 3))
  end
end

function privateMessageHistory(info, maxCount)
  local text = readAll(STATE_DIR .. "\\private-messages.json") or "[]"
  local rows = {}
  local keyName = tostring(info.name or "")
  for object in text:gmatch("%b{}") do
    local fromName = extractString(object, "from") or ""
    local toName = extractString(object, "to") or ""
    if fromName == keyName or toName == keyName then
      table.insert(rows, (extractString(object, "utc") or "") .. " " .. fromName .. " -> " .. toName .. ": " .. (extractString(object, "message") or ""))
    end
  end
  local count = math.min(#rows, tonumber(maxCount) or 5)
  if count <= 0 then return "История личных сообщений пуста." end
  local start = #rows - count + 1
  local out = {}
  for i = start, #rows do table.insert(out, rows[i]) end
  return table.concat(out, " | ")
end

function identityKey(steamId, name, dbId)
  steamId = tostring(steamId or "")
  dbId = tostring(dbId or "")
  name = tostring(name or "")
  if steamId ~= "" then return "steam:" .. steamId end
  if dbId ~= "" and dbId ~= "0" then return "db:" .. dbId end
  if name ~= "" then return "name:" .. name:lower() end
  return ""
end

function bountyNameIsRuntimeFallback(name)
  local text = cleanText(name)
  if text == "" then return true end
  local lower = text:lower()
  return lower == "unknown" or lower:match("^user#%d+$") ~= nil
end

function bountyKnownIdentityByProfile(dbId)
  dbId = tostring(dbId or "")
  if dbId == "" or dbId == "0" then return nil end
  local best = nil
  for _, object in ipairs(stateObjects("bounty-hunt.json")) do
    local profile = extractString(object, "userProfileId") or extractString(object, "profileId") or ""
    if profile == dbId then
      local steam = extractString(object, "steamId") or ""
      local name = extractString(object, "name") or ""
      if looksLikeSteamId(steam) or not bountyNameIsRuntimeFallback(name) then
        best = { steam = steam, name = name, dbId = dbId }
      end
    end
  end
  return best
end

function bountyServerLogIdentity(steamId, name, dbId)
  local cache = serverLogIdentities()
  if cache == nil then return nil end
  local identity = nil
  local profile = cleanText(dbId)
  local steam = cleanText(steamId)
  local cleanName = cleanText(name)
  if profile ~= "" and profile ~= "0" then identity = cache.byProfile[profile] end
  if identity == nil and looksLikeSteamId(steam) then identity = cache.bySteam[steam] end
  if identity == nil and not bountyNameIsRuntimeFallback(cleanName) then identity = cache.byName[cleanName:lower()] end
  if identity == nil then return nil end
  return {
    steam = cleanText(identity.steam),
    name = cleanText(identity.name),
    dbId = cleanText(identity.profileId) ~= "" and cleanText(identity.profileId) or profile
  }
end

function identityFromDbId(fallbackDbId)
  local dbId = tostring(fallbackDbId or "")
  if dbId == "" or dbId == "0" then return nil end
  local identity = bountyServerLogIdentity("", "", dbId)
  if identity ~= nil then
    return identity
  end
  identity = bountyKnownIdentityByProfile(dbId)
  if identity ~= nil then return identity end
  return { steam = "", name = "user#" .. dbId, dbId = dbId }
end

function identityFromInfo(info, fallbackDbId)
  if info == nil then
    return identityFromDbId(fallbackDbId) or { steam = "", name = "Unknown", dbId = tostring(fallbackDbId or "") }
  end
  info = enrichPlayerInfoFromServerLog(info) or info
  local dbId = tostring(info.userProfileId or "")
  if dbId == "" then dbId = tostring(info.serverUserProfileId or "") end
  if dbId == "" then dbId = tostring(info.profileId or info.ProfileId or "") end
  if dbId == "" then dbId = tostring(fallbackDbId or "") end
  local name = cleanText(info.name or info.Name or info.playerName or info.ProfileName or "")
  local steam = cleanText(info.steam or info.steamId or info.SteamId or info.UserId or "")
  local identity = bountyServerLogIdentity(steam, name, dbId) or identityFromDbId(dbId)
  if bountyNameIsRuntimeFallback(name) and identity ~= nil and not bountyNameIsRuntimeFallback(identity.name) then name = tostring(identity.name or name) end
  if steam == "" and identity ~= nil then steam = tostring(identity.steam or "") end
  if dbId == "" and identity ~= nil then dbId = tostring(identity.dbId or "") end
  return {
    steam = steam,
    name = name,
    dbId = dbId
  }
end

function bountyStats()
  local stats = {}
  for _, object in ipairs(stateObjects("bounty-hunt.json")) do
    local kind = extractString(object, "kind") or "stat"
    if kind == "stat" then
      local steam = extractString(object, "steamId") or ""
      local name = extractString(object, "name") or ""
      local dbId = extractString(object, "userProfileId") or ""
      if steam == "" or bountyNameIsRuntimeFallback(name) then
        local resolved = bountyServerLogIdentity(steam, name, dbId) or bountyKnownIdentityByProfile(dbId)
        if resolved ~= nil then
          if steam == "" then steam = tostring(resolved.steam or "") end
          if bountyNameIsRuntimeFallback(name) and not bountyNameIsRuntimeFallback(resolved.name) then name = tostring(resolved.name or name) end
          if dbId == "" then dbId = tostring(resolved.dbId or "") end
        end
      end
      local key = identityKey(steam, name, dbId)
      if key ~= "" then
        stats[key] = {
          steam = steam,
          name = name ~= "" and name or "Unknown",
          dbId = dbId,
          current = math.max(0, extractNumber(object, "currentStreak") or 0),
          best = math.max(0, extractNumber(object, "bestStreak") or 0),
          kills = math.max(0, extractNumber(object, "kills") or 0),
          deaths = math.max(0, extractNumber(object, "deaths") or 0),
          updatedAt = extractString(object, "updatedAtUtc") or extractString(object, "utc") or ""
        }
      end
    end
  end
  return stats
end

function bountyEntry(stats, identity)
  local key = identityKey(identity.steam, identity.name, identity.dbId)
  if key == "" then return nil, "" end
  local entry = stats[key]
  if entry == nil then
    local initialName = not bountyNameIsRuntimeFallback(identity.name) and identity.name or "Unknown"
    entry = { steam = identity.steam or "", name = initialName, dbId = identity.dbId or "", current = 0, best = 0, kills = 0, deaths = 0, updatedAt = "" }
    stats[key] = entry
  end
  if identity.steam ~= "" then entry.steam = identity.steam end
  if identity.name ~= "" and not bountyNameIsRuntimeFallback(identity.name) then entry.name = identity.name end
  if identity.dbId ~= "" then entry.dbId = identity.dbId end
  return entry, key
end

function appendBountySnapshot(entry)
  appendJsonArray(STATE_DIR .. "\\bounty-hunt.json", '{"kind":"stat","updatedAtUtc":' .. js(nowUtc()) ..
    ',"steamId":' .. js(entry.steam or "") ..
    ',"name":' .. js(entry.name or "") ..
    ',"userProfileId":' .. js(entry.dbId or "") ..
    ',"currentStreak":' .. tostring(entry.current or 0) ..
    ',"bestStreak":' .. tostring(entry.best or 0) ..
    ',"kills":' .. tostring(entry.kills or 0) ..
    ',"deaths":' .. tostring(entry.deaths or 0) .. '}', 2 * 1024 * 1024)
end

function bountyRewardAmountForStreak(streak)
  local current = math.max(0, tonumber(streak or 0) or 0)
  local startStreak = math.max(1, configNumber("bounty-hunt", { "LeaderKillRewardStartStreak", "leaderKillRewardStartStreak", "BroadcastThreshold", "broadcastThreshold" }, 3))
  local baseAmount = math.max(0, configNumber("bounty-hunt", { "LeaderKillRewardAmount", "leaderKillRewardAmount" }, 0))
  local stepAmount = math.max(0, configNumber("bounty-hunt", { "LeaderKillRewardStepAmount", "leaderKillRewardStepAmount" }, baseAmount))
  if current < startStreak or baseAmount <= 0 then return 0 end
  return baseAmount + math.max(0, current - startStreak) * stepAmount
end

BOUNTY_PENDING_RETRY_AT = BOUNTY_PENDING_RETRY_AT or {}
BOUNTY_PENDING_DRAIN_AT = BOUNTY_PENDING_DRAIN_AT or 0

function bountyRewardKey(info, amount, currency, victimName, victimPreviousStreak)
  local target = info or {}
  local steam = cleanText(target.steam or target.steamId or "")
  local profile = cleanText(target.userProfileId or target.serverUserProfileId or target.profileId or "")
  local name = cleanText(target.name or "")
  if steam ~= "" then
    return "steam:" .. steam .. "|amount:" .. tostring(amount or 0) .. "|currency:" .. tostring(currency or "") .. "|victim:" .. tostring(victimName or "") .. "|streak:" .. tostring(victimPreviousStreak or 0)
  end
  if profile ~= "" and profile ~= "0" then
    return "profile:" .. profile .. "|amount:" .. tostring(amount or 0) .. "|currency:" .. tostring(currency or "") .. "|victim:" .. tostring(victimName or "") .. "|streak:" .. tostring(victimPreviousStreak or 0)
  end
  return "name:" .. name:lower() .. "|amount:" .. tostring(amount or 0) .. "|currency:" .. tostring(currency or "") .. "|victim:" .. tostring(victimName or "") .. "|streak:" .. tostring(victimPreviousStreak or 0)
end

function latestPendingBountyRewardsByKey()
  local latest = {}
  for _, object in ipairs(stateObjects("bounty-rewards-pending.json")) do
    local key = extractString(object, "rewardKey") or ""
    if key ~= "" then latest[key] = object end
  end
  return latest
end

function appendPendingBountyReward(info, amount, currency, victimName, victimPreviousStreak, reason)
  local target = info or {}
  local key = bountyRewardKey(target, amount, currency, victimName, victimPreviousStreak)
  if key == "" then return "", "missing-key" end
  local latest = latestPendingBountyRewardsByKey()[key]
  if latest ~= nil then
    local status = (extractString(latest, "status") or ""):lower()
    if status == "pending" or status == "paid" then return key, status end
  end
  appendJsonArray(STATE_DIR .. "\\bounty-rewards-pending.json",
    '{"utc":' .. js(nowUtc()) ..
    ',"rewardKey":' .. js(key) ..
    ',"steamId":' .. js(cleanText(target.steam or target.steamId or "")) ..
    ',"name":' .. js(cleanText(target.name or "")) ..
    ',"userProfileId":' .. js(cleanText(target.userProfileId or target.serverUserProfileId or target.profileId or "")) ..
    ',"amount":' .. tostring(math.max(0, tonumber(amount) or 0)) ..
    ',"currency":' .. js(currency or "Normal") ..
    ',"victim":' .. js(victimName or "") ..
    ',"victimPreviousStreak":' .. tostring(tonumber(victimPreviousStreak or 0) or 0) ..
    ',"status":"pending"' ..
    ',"reason":' .. js(reason or "") .. '}',
    1024 * 1024)
  return key, "pending"
end

function markPendingBountyRewardPaid(info, object, message)
  local target = info or {}
  appendJsonArray(STATE_DIR .. "\\bounty-rewards-pending.json",
    '{"utc":' .. js(nowUtc()) ..
    ',"rewardKey":' .. js(extractString(object, "rewardKey") or "") ..
    ',"steamId":' .. js(cleanText(target.steam or target.steamId or extractString(object, "steamId") or "")) ..
    ',"name":' .. js(cleanText(target.name or extractString(object, "name") or "")) ..
    ',"userProfileId":' .. js(cleanText(target.userProfileId or target.serverUserProfileId or target.profileId or extractString(object, "userProfileId") or "")) ..
    ',"amount":' .. tostring(math.max(0, extractNumber(object, "amount") or 0)) ..
    ',"currency":' .. js(extractString(object, "currency") or "Normal") ..
    ',"victim":' .. js(extractString(object, "victim") or "") ..
    ',"victimPreviousStreak":' .. tostring(extractNumber(object, "victimPreviousStreak") or 0) ..
    ',"status":"paid"' ..
    ',"message":' .. js(message or "") .. '}',
    1024 * 1024)
end

function bountyRewardCommandTarget(info)
  local target = valueText((info or {}).steam)
  if target == "" or target == "Unknown" then target = valueText((info or {}).steamId) end
  if target == "" or target == "Unknown" then target = valueText((info or {}).name) end
  return target
end

function executeBountyRewardNow(info, amount, currency, victimName, victimPreviousStreak, source)
  local live = resolvePlayerInfo((info or {}).steam, (info or {}).name, info, (info or {}).runtimeKey) or info or {}
  live = refreshRuntimePlayerInfo(live) or live
  live = enrichPlayerInfoFromServerLog(live) or live
  local selector = bountyRewardCommandTarget(live)
  if selector == "" or selector == "Unknown" then
    return false, "missing target selector", live
  end
  currency = valueText(currency)
  if currency == "" then currency = "Normal" end
  if currency:lower() == "gold" then currency = "Gold" else currency = "Normal" end
  amount = math.max(0, tonumber(amount) or 0)
  if amount <= 0 then return true, "reward amount is zero", live end
  local commandText = "ChangeCurrencyBalance " .. tostring(currency) .. " " .. tostring(amount) .. " " .. tostring(selector)
  local sent, message = adminExec(commandText, live)
  appendActionEvent("bounty_reward_execute", sent, live, tostring(message or ""),
    '{"amount":' .. tostring(amount) ..
    ',"currency":' .. js(currency) ..
    ',"selector":' .. js(selector) ..
    ',"command":' .. js(commandText) ..
    ',"source":' .. js(source or "bounty-hunt") .. '}')
  if sent then
    appendEconomyEvent("bounty reward paid", live.name, live.steam, amount, currency, true)
    targetMessage(live.steam, live.name, "Награда за остановку bounty: " .. tostring(amount) .. " " .. currency .. ".", "bounty-hunt", live.runtimeKey)
    if configBool("bounty-hunt", { "BroadcastLeaderKillReward", "broadcastLeaderKillReward" }, true) then
      broadcast("[Bounty] " .. tostring(live.name or selector) .. " получил " .. tostring(amount) .. " " .. currency .. " за убийство лидера " .. tostring(victimName or "") .. ".")
    end
  end
  return sent, tostring(message or ""), live
end

function queueBountyReward(info, amount, currency, victimName, victimPreviousStreak, source)
  local target = info or {}
  amount = math.max(0, tonumber(amount) or 0)
  if amount <= 0 then return true, "Награда bounty отключена." end
  local queued, queueIdOrMessage, depth = enqueueMutation("bounty-reward", target, function()
    local sent, message, live = executeBountyRewardNow(target, amount, currency, victimName, victimPreviousStreak, source)
    if sent then
      appendActionEvent("bounty_reward", true, live,
        "Награда bounty отправлена live-командой.",
        '{"amount":' .. tostring(amount) ..
        ',"currency":' .. js(currency) ..
        ',"victim":' .. js(victimName or "") ..
        ',"victimPreviousStreak":' .. tostring(victimPreviousStreak or 0) .. '}')
    else
      local pendingKey, pendingStatus = appendPendingBountyReward(live or target, amount, currency, victimName, victimPreviousStreak, message)
      appendActionEvent("bounty_reward", false, live or target,
        "Награда bounty перенесена в ожидание live-доступа.",
        '{"amount":' .. tostring(amount) ..
        ',"currency":' .. js(currency) ..
        ',"victim":' .. js(victimName or "") ..
        ',"victimPreviousStreak":' .. tostring(victimPreviousStreak or 0) ..
        ',"pendingKey":' .. js(pendingKey or "") ..
        ',"pendingStatus":' .. js(pendingStatus or "") .. '}')
    end
  end)
  if queued then return true, "Награда bounty поставлена в live-очередь.", queueIdOrMessage, depth end
  local pendingKey, pendingStatus = appendPendingBountyReward(target, amount, currency, victimName, victimPreviousStreak, tostring(queueIdOrMessage or "queue failed"))
  appendActionEvent("bounty_reward", false, target,
    "Очередь занята, награда bounty перенесена в ожидание.",
    '{"amount":' .. tostring(amount) ..
    ',"currency":' .. js(currency) ..
    ',"victim":' .. js(victimName or "") ..
    ',"victimPreviousStreak":' .. tostring(victimPreviousStreak or 0) ..
    ',"pendingKey":' .. js(pendingKey or "") ..
    ',"pendingStatus":' .. js(pendingStatus or "") .. '}')
  return false, tostring(queueIdOrMessage or "Не удалось поставить bounty-награду в очередь."), nil, depth
end

function drainPendingBountyRewardsForInfo(info, limit)
  if info == nil then return 0 end
  local maxCount = math.max(1, tonumber(limit) or 1)
  local latest = latestPendingBountyRewardsByKey()
  local drained = 0
  for _, object in pairs(latest) do
    if drained >= maxCount then break end
    if (extractString(object, "status") or ""):lower() == "pending" and samePlayerRecord(info, object) then
      local key = extractString(object, "rewardKey") or ""
      local now = os.time()
      if key == "" or tonumber(BOUNTY_PENDING_RETRY_AT[key] or 0) <= now then
        local amount = math.max(0, extractNumber(object, "amount") or 0)
        local currency = extractString(object, "currency") or "Normal"
        local victimName = extractString(object, "victim") or ""
        local victimPreviousStreak = extractNumber(object, "victimPreviousStreak") or 0
        local queued = enqueueMutation("bounty-reward-pending", info, function()
          local sent, message, live = executeBountyRewardNow(info, amount, currency, victimName, victimPreviousStreak, "bounty-pending")
          if sent then
            markPendingBountyRewardPaid(live or info, object, message)
            appendActionEvent("bounty_reward_pending", true, live or info,
              "Отложенная bounty-награда отправлена.",
              '{"pendingKey":' .. js(key) .. ',"amount":' .. tostring(amount) .. ',"currency":' .. js(currency) .. '}')
          else
            BOUNTY_PENDING_RETRY_AT[key] = os.time() + 60
            appendActionEvent("bounty_reward_pending", false, live or info,
              tostring(message or "live route unavailable"),
              '{"pendingKey":' .. js(key) .. ',"amount":' .. tostring(amount) .. ',"currency":' .. js(currency) .. '}')
          end
        end)
        if queued then
          drained = drained + 1
          BOUNTY_PENDING_RETRY_AT[key] = now + 60
        end
      end
    end
  end
  return drained
end

function drainPendingBountyRewardsForInfos(infos, limit)
  if (os.clock() - (tonumber(BOUNTY_PENDING_DRAIN_AT) or 0)) < 10 then return 0 end
  BOUNTY_PENDING_DRAIN_AT = os.clock()
  local drained = 0
  local maxCount = math.max(1, tonumber(limit) or 2)
  for _, info in ipairs(infos or {}) do
    if drained >= maxCount then break end
    drained = drained + drainPendingBountyRewardsForInfo(info, maxCount - drained)
  end
  return drained
end

function killLocationJson(x, y, z)
  x = tonumber(x)
  y = tonumber(y)
  z = tonumber(z)
  if x == nil or y == nil or z == nil then return "null" end
  return '{"x":' .. tostring(x) .. ',"y":' .. tostring(y) .. ',"z":' .. tostring(z) .. '}'
end

function normalizeKillDistanceMeters(distance)
  local value = tonumber(distance or 0) or 0
  if value > 5000 then value = value / 100 end
  return value
end

function killWeaponLooksMelee(weapon, cause)
  local text = (tostring(weapon or "") .. " " .. tostring(cause or "")):lower()
  if text:find("melee", 1, true) ~= nil then return true end
  local tokens = {
    "sword", "knife", "axe", "spear", "katana", "machete", "cleaver",
    "bayonet", "bat", "crowbar", "wrench", "shovel", "pitchfork",
    "club", "hammer", "kunai", "nail"
  }
  for _, token in ipairs(tokens) do
    if text:find(token, 1, true) ~= nil then return true end
  end
  return false
end

function displayKillDistanceMeters(distance, weapon, cause)
  local value = normalizeKillDistanceMeters(distance)
  if value > 3 and killWeaponLooksMelee(weapon, cause) then return 1 end
  return value
end

function appendKillEvent(killer, victim, meta, victimPreviousStreak)
  meta = meta or {}
  local killerX = tonumber(meta.killerX or meta.killerLocationX or meta.killer_x)
  local killerY = tonumber(meta.killerY or meta.killerLocationY or meta.killer_y)
  local killerZ = tonumber(meta.killerZ or meta.killerLocationZ or meta.killer_z)
  local victimX = tonumber(meta.victimX or meta.victimLocationX or meta.victim_x)
  local victimY = tonumber(meta.victimY or meta.victimLocationY or meta.victim_y)
  local victimZ = tonumber(meta.victimZ or meta.victimLocationZ or meta.victim_z)
  local weapon = tostring(meta.weapon or "")
  local distance = displayKillDistanceMeters(meta.distance or 0, weapon, meta.cause or meta.deathType)
  if distance <= 0 and killerX ~= nil and killerY ~= nil and killerZ ~= nil and victimX ~= nil and victimY ~= nil and victimZ ~= nil then
    local dx = killerX - victimX
    local dy = killerY - victimY
    local dz = killerZ - victimZ
    distance = displayKillDistanceMeters(math.sqrt(dx * dx + dy * dy + dz * dz) / 100, weapon, meta.cause or meta.deathType)
  end
  local message = tostring(killer.name or "Unknown") .. " убил " .. tostring(victim.name or "Unknown")
  if weapon ~= "" then message = message .. " (" .. weapon .. ")" end
  if distance > 0 then message = message .. " с " .. tostring(math.floor(distance + 0.5)) .. " м" end
  if killFeedNameLooksRuntimeFallback(killer.name) or killFeedNameLooksRuntimeFallback(victim.name) then
    appendLog("kill feed record skipped runtime fallback killer=" .. tostring(killer.name or "") ..
      " victim=" .. tostring(victim.name or "") ..
      " source=" .. tostring(meta.source or ""))
    return message
  end
  local record = '{"type":"kill","timestampUtc":' .. js(nowUtc()) ..
    ',"message":' .. js(message) ..
    ',"killerName":' .. js(killer.name or "") ..
    ',"killerSteamId":' .. js(killer.steam or "") ..
    ',"killerUserProfileId":' .. js(killer.dbId or "") ..
    ',"victimName":' .. js(victim.name or "") ..
    ',"victimSteamId":' .. js(victim.steam or "") ..
    ',"victimUserProfileId":' .. js(victim.dbId or "") ..
    ',"weapon":' .. js(weapon) ..
    ',"distance":' .. tostring(distance) ..
    ',"killerLocation":' .. killLocationJson(killerX, killerY, killerZ) ..
    ',"victimLocation":' .. killLocationJson(victimX, victimY, victimZ) ..
    ',"victimPreviousStreak":' .. tostring(victimPreviousStreak or 0) ..
    ',"source":' .. js(meta.source or "ue4ss-kill-registry") .. '}'
  appendJsonArray(STATE_DIR .. "\\kill-feed.json", record, 2 * 1024 * 1024)
  appendJsonArray(STATE_DIR .. "\\server-kill-feed.json", record, 2 * 1024 * 1024)
  return message
end

function serverKillFeedEnabled()
  return configBool("server-kill-feed", { "Enabled", "enabled" }, true) ~= false
end

function serverKillFeedPrefix()
  local prefix = extractStringAny(configText("server-kill-feed"), { "Prefix", "prefix" }) or "WILD"
  prefix = tostring(prefix or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if prefix == "" then prefix = "WILD" end
  if prefix:sub(1, 1) == "[" then return prefix end
  return "[" .. prefix .. "]"
end

function serverKillFeedShowWeapon()
  return configBool("server-kill-feed", { "IncludeWeapon", "includeWeapon", "ShowWeapon", "showWeapon" }, true) == true
end

function serverKillFeedShowDistance()
  return configBool("server-kill-feed", { "IncludeDistance", "includeDistance", "ShowDistance", "showDistance" }, true) == true
end

SERVER_KILL_FEED_BROADCAST_DEDUP = SERVER_KILL_FEED_BROADCAST_DEDUP or {}
SERVER_KILL_FEED_STATS_DEDUP = SERVER_KILL_FEED_STATS_DEDUP or {}

function stripKillFeedPrefix(message)
  return cleanText(message or ""):gsub("^%[[^%]]+%]%s*", "")
end

function killFeedNameLooksRuntimeFallback(name)
  local text = cleanText(name or ""):lower()
  return text:match("^user#%d+$") ~= nil
end

function killFeedMessageHasRuntimeFallback(message)
  return tostring(message or ""):lower():find("user#%d+") ~= nil
end

function normalizeDetailedKillFeedBody(body)
  local value = tostring(body or "")
  if value:find("KillerLoc", 1, true) == nil and value:find("VictimLoc", 1, true) == nil and value:find("Distance:", 1, true) == nil then
    return value
  end
  local distanceRaw = value:match("[Dd]istance%s*:%s*([%-%d%.,]+)%s*m?")
  local prefix, detail = value:match("^(.-)%s*%((.*[Kk]iller[Ll]oc.*)%)%s*$")
  if prefix == nil then
    prefix, detail = value:match("^(.-)%s*%((.*[Dd]istance%s*:.*)%)%s*$")
  end
  if prefix == nil then return value end
  local cause = tostring(detail or ""):match("%[([^%]]+)%]") or ""
  local weapon = cleanKillWeapon(detail or "")
  local normalized = cleanText(prefix)
  if weapon ~= "" and serverKillFeedShowWeapon() then normalized = normalized .. " (" .. weapon .. ")" end
  local distanceNumber = displayKillDistanceMeters(killLogNumber(distanceRaw) or 0, weapon, cause)
  if distanceNumber > 0 and serverKillFeedShowDistance() then
    normalized = normalized .. " с " .. tostring(math.floor(distanceNumber + 0.5)) .. " м"
  end
  return normalized
end

function killFeedBodyHasVisibleDetails(body)
  local value = tostring(body or "")
  if value:find("%b()") ~= nil then return true end
  if value:match("%sс%s%d+%sм") ~= nil then return true end
  return false
end

function killFeedMessageLooksTechnical(message)
  local text = tostring(message or "")
  if text == "" then return true, "empty" end
  if killFeedMessageHasRuntimeFallback(text) then return true, "runtime-user-fallback" end
  if text:find("%c") ~= nil then return true, "control-char" end
  if text:find("\\u", 1, true) ~= nil or text:find("\\U", 1, true) ~= nil then return true, "unicode-escape" end
  if text:find("KillerLoc", 1, true) ~= nil or text:find("VictimLoc", 1, true) ~= nil then return true, "debug-location" end
  if text:find("Distance:", 1, true) ~= nil and text:find("[Projectile]", 1, true) ~= nil then return true, "debug-projectile" end
  if text:find(" убил ", 1, true) == nil and text:find(" погиб", 1, true) == nil then return true, "not-killfeed" end
  return false, ""
end

function normalizeServerKillFeedMessage(message)
  local body = normalizeDetailedKillFeedBody(stripKillFeedPrefix(message))
  if (serverKillFeedShowWeapon() or serverKillFeedShowDistance()) and
      body:find(" убил ", 1, true) ~= nil and
      not killFeedBodyHasVisibleDetails(body) then
    return "", "filtered:missing-kill-details"
  end
  local technical, reason = killFeedMessageLooksTechnical(body)
  if technical then return "", "filtered:" .. tostring(reason or "technical") end
  if not serverKillFeedShowWeapon() then
    body = body:gsub("%s*%([^%)]*%)", "")
  end
  if not serverKillFeedShowDistance() then
    body = body:gsub("%s+с%s+%d+%s+м%s*$", "")
  end
  body = cleanText(body)
  if body == "" then return "", "filtered:empty-after-clean" end
  return serverKillFeedPrefix() .. " " .. body, ""
end

function serverKillFeedDedupKey(message)
  local body = stripKillFeedPrefix(message):lower()
  body = body:gsub("%s*%([^%)]*%)", "")
  body = body:gsub("%s+с%s+%d+%s+м%s*$", "")
  body = body:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
  return body
end

function shouldSkipServerKillFeedBroadcast(message)
  local key = serverKillFeedDedupKey(message)
  if key == "" then return false end
  local now = os.time()
  local duplicateWindow = math.max(1, configNumber("server-kill-feed", { "DuplicateWindowSeconds", "duplicateWindowSeconds" }, 8))
  for oldKey, seenAt in pairs(SERVER_KILL_FEED_BROADCAST_DEDUP) do
    if (now - seenAt) > (duplicateWindow * 4) then SERVER_KILL_FEED_BROADCAST_DEDUP[oldKey] = nil end
  end
  local last = SERVER_KILL_FEED_BROADCAST_DEDUP[key]
  if last ~= nil and (now - last) <= duplicateWindow then return true end
  SERVER_KILL_FEED_BROADCAST_DEDUP[key] = now
  return false
end

function shouldSkipServerKillFeedStats(message)
  local key = serverKillFeedDedupKey(message)
  if key == "" then return true end
  local now = os.time()
  local duplicateWindow = math.max(1, configNumber("server-kill-feed", { "DuplicateWindowSeconds", "duplicateWindowSeconds" }, 8))
  for oldKey, seenAt in pairs(SERVER_KILL_FEED_STATS_DEDUP) do
    if (now - seenAt) > (duplicateWindow * 4) then SERVER_KILL_FEED_STATS_DEDUP[oldKey] = nil end
  end
  local last = SERVER_KILL_FEED_STATS_DEDUP[key]
  if last ~= nil and (now - last) <= duplicateWindow then return true end
  SERVER_KILL_FEED_STATS_DEDUP[key] = now
  return false
end

function resolveKillFeedIdentityByName(name)
  name = cleanText(name)
  if name == "" then return nil end
  if findCachedPlayerByExactName ~= nil then
    local cached = findCachedPlayerByExactName(name)
    if cached ~= nil then return cached end
  end
  local resolved = resolvePlayerInfoFromServerLogTarget("", name)
  if resolved ~= nil then return resolved end
  local cache = serverLogIdentities()
  local identity = cache and cache.byName and cache.byName[name:lower()] or nil
  if identity ~= nil then
    local profileId = cleanText(identity.profileId)
    return {
      steam = cleanText(identity.steam),
      name = cleanText(identity.name) ~= "" and cleanText(identity.name) or name,
      userProfileId = profileId,
      serverUserProfileId = profileId
    }
  end
  return { steam = "", name = name, userProfileId = "", serverUserProfileId = "" }
end

function applyServerKillFeedStats(message)
  local normalized, reason = normalizeServerKillFeedMessage(message)
  if normalized == "" then return false, reason ~= "" and reason or "filtered" end
  local body = stripKillFeedPrefix(normalized)
  if body == "" then return false, "empty" end

  local killerName, victimName = body:match("^(.-)%s+убил%s+(.+)$")
  if killerName ~= nil and victimName ~= nil then
    killerName = cleanText(killerName)
    victimName = cleanText(victimName)
    if killerName == "" or victimName == "" then return false, "empty-kill-name" end
    if shouldSkipServerKillFeedStats(body) then return false, "duplicate" end
    local killerInfo = resolveKillFeedIdentityByName(killerName)
    local victimInfo = resolveKillFeedIdentityByName(victimName)
    if killerInfo == nil or victimInfo == nil then
      appendLog("server kill feed stats skipped identity killer=" .. tostring(killerName) .. " victim=" .. tostring(victimName))
      return false, "identity-not-found"
    end
    local updated = handleKillEvent(killerInfo, victimInfo, { source = "server-kill-feed", skipKillFeed = true })
    appendLog("server kill feed stats kill updated=" .. tostring(updated) ..
      " killer=" .. tostring(killerName) .. " victim=" .. tostring(victimName))
    return updated == true, updated and "updated" or "stats-failed"
  end

  local deadName = body:match("^(.-)%s+погиб$")
  if deadName ~= nil then
    deadName = cleanText(deadName)
    if deadName == "" then return false, "empty-death-name" end
    if shouldSkipServerKillFeedStats(body) then return false, "duplicate" end
    local victimInfo = resolveKillFeedIdentityByName(deadName)
    if victimInfo == nil then
      appendLog("server kill feed death stats skipped identity victim=" .. tostring(deadName))
      return false, "identity-not-found"
    end
    local updated = handleDeathEvent(victimInfo, { source = "server-kill-feed", skipKillFeed = true })
    appendLog("server kill feed stats death updated=" .. tostring(updated) ..
      " victim=" .. tostring(deadName))
    return updated == true, updated and "updated" or "stats-failed"
  end

  return false, "not-stat-event"
end

function killFeedRecordLooksTechnical(recordText)
  local text = tostring(recordText or "")
  if killFeedMessageHasRuntimeFallback(text) then return true end
  if text:find('"source":"savefile-kill-log"', 1, true) ~= nil or
    text:find('"killerLocation"', 1, true) ~= nil or
    text:find('"victimLocation"', 1, true) ~= nil then
    return false
  end
  return text:find("KillerLoc", 1, true) ~= nil or
    text:find("VictimLoc", 1, true) ~= nil or
    text:find("\\u00", 1, true) ~= nil or
    text:find("\\u001", 1, true) ~= nil or
    text:find("\\u000", 1, true) ~= nil
end

function sanitizeKillFeedStateFile(path)
  local text = readAll(path)
  if text == nil or text == "" or not killFeedRecordLooksTechnical(text) then return end
  local kept = {}
  local removed = 0
  for objectText in tostring(text):gmatch("%b{}") do
    if killFeedRecordLooksTechnical(objectText) then
      removed = removed + 1
    else
      table.insert(kept, objectText)
    end
  end
  if removed > 0 then
    writeAll(path, "[" .. table.concat(kept, ",") .. "]")
    appendLog("server kill feed state sanitized path=" .. tostring(path or "") .. " removed=" .. tostring(removed))
  end
end

function sanitizeKillFeedStateFiles()
  sanitizeKillFeedStateFile(STATE_DIR .. "\\kill-feed.json")
  sanitizeKillFeedStateFile(STATE_DIR .. "\\server-kill-feed.json")
end

function broadcastServerKillFeed(message)
  local normalized, reason = normalizeServerKillFeedMessage(message)
  if normalized == "" then
    sanitizeKillFeedStateFiles()
    appendLog("server kill feed broadcast skipped reason=" .. tostring(reason or "filtered") ..
      " message=" .. tostring(message or ""))
    return false, reason ~= "" and reason or "filtered"
  end
  if shouldSkipServerKillFeedBroadcast(normalized) then
    appendLog("server kill feed broadcast skipped duplicate message=" .. tostring(normalized or ""))
    return false, "duplicate"
  end
  local sent, route = broadcastGlobalChatOnly(normalized)
  appendLog("server kill feed broadcast sent=" .. tostring(sent) ..
    " route=" .. tostring(route or "") ..
    " message=" .. tostring(normalized or ""))
  appendChatEvent(normalized, "Kill feed", "", "global", "server-kill-feed")
  appendActionEvent("server_kill_feed_broadcast", sent, nil, tostring(route or ""),
    '{"message":' .. js(normalized) .. ',"route":' .. js(route or "") .. ',"channel":"global"}')
  return sent, route
end

function appendDeathEvent(victim, meta)
  meta = meta or {}
  local victimX = tonumber(meta.victimX or meta.victimLocationX or meta.victim_x)
  local victimY = tonumber(meta.victimY or meta.victimLocationY or meta.victim_y)
  local victimZ = tonumber(meta.victimZ or meta.victimLocationZ or meta.victim_z)
  local message = tostring(victim.name or "Unknown") .. " погиб"
  if killFeedNameLooksRuntimeFallback(victim.name) then
    appendLog("death feed record skipped runtime fallback victim=" .. tostring(victim.name or "") ..
      " source=" .. tostring(meta.source or ""))
    return message
  end
  local record = '{"type":"death","timestampUtc":' .. js(nowUtc()) ..
    ',"message":' .. js(message) ..
    ',"victimName":' .. js(victim.name or "") ..
    ',"victimSteamId":' .. js(victim.steam or "") ..
    ',"victimUserProfileId":' .. js(victim.dbId or "") ..
    ',"victimLocation":' .. killLocationJson(victimX, victimY, victimZ) ..
    ',"source":' .. js(meta.source or "ue4ss-death") .. '}'
  appendJsonArray(STATE_DIR .. "\\kill-feed.json", record, 2 * 1024 * 1024)
  appendJsonArray(STATE_DIR .. "\\server-kill-feed.json", record, 2 * 1024 * 1024)
  return message
end

function handleDeathEvent(victimInfo, meta)
  meta = meta or {}
  if victimInfo ~= nil and not playerHasUsableLocation(victimInfo) then
    local refreshedVictim = refreshRuntimePlayerInfo(victimInfo)
    if refreshedVictim ~= nil and playerHasUsableLocation(refreshedVictim) then
      victimInfo = refreshedVictim
    else
      local logVictim = resolvePlayerInfoFromServerLogTarget(victimInfo.steam, victimInfo.name)
      if logVictim ~= nil and playerHasUsableLocation(logVictim) then victimInfo = logVictim end
    end
  end
  if victimInfo ~= nil then
    meta.victimX = meta.victimX or victimInfo.x
    meta.victimY = meta.victimY or victimInfo.y
    meta.victimZ = meta.victimZ or victimInfo.z
  end
  local victim = identityFromInfo(victimInfo, meta.victimDbId or "")
  local victimKey = identityKey(victim.steam, victim.name, victim.dbId)
  if victimKey == "" then return false end
  appendLog("death event victim=" .. tostring(victim.name or "") ..
    " steam=" .. tostring(victim.steam or "") ..
    " dbId=" .. tostring(victim.dbId or "") ..
    " source=" .. tostring(meta.source or ""))

  local stats = bountyStats()
  local victimEntry = bountyEntry(stats, victim)
  if victimEntry ~= nil then
    victimEntry.deaths = (victimEntry.deaths or 0) + 1
    victimEntry.current = 0
    appendBountySnapshot(victimEntry)
  end

  if not meta.skipKillFeed then
    local deathMessage = appendDeathEvent(victimEntry or victim, meta)
    if serverKillFeedEnabled() then
      broadcastServerKillFeed(serverKillFeedPrefix() .. " " .. deathMessage)
    end
  end
  return true
end

function handleKillEvent(killerInfo, victimInfo, meta)
  meta = meta or {}
  if killerInfo ~= nil then
    meta.killerX = meta.killerX or killerInfo.x
    meta.killerY = meta.killerY or killerInfo.y
    meta.killerZ = meta.killerZ or killerInfo.z
  end
  if victimInfo ~= nil then
    meta.victimX = meta.victimX or victimInfo.x
    meta.victimY = meta.victimY or victimInfo.y
    meta.victimZ = meta.victimZ or victimInfo.z
  end
  local killer = identityFromInfo(killerInfo, meta and meta.killerDbId or "")
  local victim = identityFromInfo(victimInfo, meta and meta.victimDbId or "")
  local killerKey = identityKey(killer.steam, killer.name, killer.dbId)
  local victimKey = identityKey(victim.steam, victim.name, victim.dbId)
  if victimKey ~= "" and (killerKey == "" or killerKey == victimKey) then return handleDeathEvent(victimInfo, meta) end
  if killerKey == "" or victimKey == "" then return false end
  appendLog("kill event killer=" .. tostring(killer.name or "") ..
    " victim=" .. tostring(victim.name or "") ..
    " killerDbId=" .. tostring(killer.dbId or "") ..
    " victimDbId=" .. tostring(victim.dbId or "") ..
    " source=" .. tostring(meta and meta.source or ""))

  local stats = bountyStats()
  local killerEntry = bountyEntry(stats, killer)
  local victimEntry = bountyEntry(stats, victim)
  if killerEntry == nil or victimEntry == nil then return false end

  local victimPreviousStreak = victimEntry.current or 0
  killerEntry.kills = (killerEntry.kills or 0) + 1
  killerEntry.current = (killerEntry.current or 0) + 1
  killerEntry.best = math.max(killerEntry.best or 0, killerEntry.current)
  victimEntry.deaths = (victimEntry.deaths or 0) + 1
  victimEntry.current = 0

  appendBountySnapshot(killerEntry)
  appendBountySnapshot(victimEntry)
  appendJsonArray(STATE_DIR .. "\\bounty-hunt-events.json", '{"utc":' .. js(nowUtc()) .. ',"killer":' .. js(killerEntry.name) .. ',"victim":' .. js(victimEntry.name) .. ',"killerSteamId":' .. js(killerEntry.steam) .. ',"victimSteamId":' .. js(victimEntry.steam) .. ',"victimPreviousStreak":' .. tostring(victimPreviousStreak) .. '}', 1024 * 1024)

  if not meta.skipKillFeed then
    local killMessage = appendKillEvent(killerEntry, victimEntry, meta, victimPreviousStreak)
    if serverKillFeedEnabled() then
      broadcastServerKillFeed(serverKillFeedPrefix() .. " " .. killMessage)
    end
  end

  local broadcastThreshold = configNumber("bounty-hunt", { "BroadcastThreshold", "broadcastThreshold" }, 3)
  local heroThreshold = configNumber("bounty-hunt", { "HeroThreshold", "heroThreshold" }, 5)
  if killerEntry.current >= broadcastThreshold then
    broadcast("[Bounty] " .. killerEntry.name .. " на серии " .. tostring(killerEntry.current) .. " убийств.")
  end
  if killerEntry.current == heroThreshold then
    broadcast("[Bounty] " .. killerEntry.name .. " стал целью сервера. Остановите его.")
  end
  if victimPreviousStreak >= broadcastThreshold then
    broadcast("[Bounty] " .. killerEntry.name .. " остановил серию " .. victimEntry.name .. " (" .. tostring(victimPreviousStreak) .. ").")
  end

  local rewardAmount = bountyRewardAmountForStreak(victimPreviousStreak)
  local rewardMode = extractStringAny(configText("bounty-hunt"), { "LeaderKillRewardMode", "leaderKillRewardMode" }) or "None"
  if rewardAmount > 0 and rewardMode:lower() ~= "none" and killerInfo ~= nil then
    local currency = rewardMode:lower() == "gold" and "Gold" or "Normal"
    local rewardTarget = {
      steam = tostring(killerEntry.steam or killer.steam or killerInfo.steam or ""),
      steamId = tostring(killerEntry.steam or killer.steam or killerInfo.steamId or ""),
      name = tostring(killerEntry.name or killer.name or killerInfo.name or ""),
      userProfileId = tostring(killerEntry.dbId or killer.dbId or killerInfo.userProfileId or killerInfo.serverUserProfileId or ""),
      serverUserProfileId = tostring(killerEntry.dbId or killer.dbId or killerInfo.serverUserProfileId or ""),
      runtimeKey = tostring(killerInfo.runtimeKey or "")
    }
    queueBountyReward(rewardTarget, rewardAmount, currency, victimEntry.name or victim.name or "", victimPreviousStreak, "bounty-kill")
  end
  return true
end

commandKey = nil

function formatBountyStats(info, command)
  return table.concat(bountyStatsLines(info, command), " | ")
end

function bountyStatsLines(info, command)
  local key = commandKey(command)
  local stats = bountyStats()
  local selfIdentity = identityFromInfo(info, "")
  local selfEntry = stats[identityKey(selfIdentity.steam, selfIdentity.name, selfIdentity.dbId)]

  if key == "streak" then
    if selfEntry == nil then
      return {
        "Твоя статистика:",
        "Текущая серия: 0",
        "Лучшая серия: 0",
        "Убийств: 0",
        "Смертей: 0"
      }
    end
    return {
      "Твоя статистика:",
      "Текущая серия: " .. tostring(selfEntry.current or 0),
      "Лучшая серия: " .. tostring(selfEntry.best or 0),
      "Убийств: " .. tostring(selfEntry.kills or 0),
      "Смертей: " .. tostring(selfEntry.deaths or 0)
    }
  end

  local rows = {}
  for _, entry in pairs(stats) do
    if key == "bounty" then
      if (entry.current or 0) >= configNumber("bounty-hunt", { "BroadcastThreshold", "broadcastThreshold" }, 3) then table.insert(rows, entry) end
    else
      if (entry.best or 0) > 0 or (entry.kills or 0) > 0 then table.insert(rows, entry) end
    end
  end
  table.sort(rows, function(a, b)
    if key == "bounty" then
      if (a.current or 0) ~= (b.current or 0) then return (a.current or 0) > (b.current or 0) end
    else
      if (a.best or 0) ~= (b.best or 0) then return (a.best or 0) > (b.best or 0) end
      if (a.kills or 0) ~= (b.kills or 0) then return (a.kills or 0) > (b.kills or 0) end
    end
    return tostring(a.name or "") < tostring(b.name or "")
  end)
  local maxRows = math.max(1, configNumber("bounty-hunt", { "MaxBoardEntries", "maxBoardEntries" }, 5))
  if #rows == 0 then
    return { key == "bounty" and "Сейчас нет активных целей с наградой." or "Топ охотников пока пуст." }
  end
  local out = { key == "bounty" and "Активные bounty:" or "Топ охотников:" }
  for i = 1, math.min(#rows, maxRows) do
    local entry = rows[i]
    local displayName = tostring(entry.name or "")
    if key == "bounty" then
      local rewardAmount = bountyRewardAmountForStreak(entry.current or 0)
      local rewardMode = extractStringAny(configText("bounty-hunt"), { "LeaderKillRewardMode", "leaderKillRewardMode" }) or "None"
      if rewardAmount > 0 and tostring(rewardMode or ""):lower() ~= "none" then
        local currency = tostring(rewardMode or ""):lower() == "gold" and "золото" or "деньги"
        displayName = displayName .. ", награда: " .. tostring(rewardAmount) .. " " .. currency
      end
    end
    if key == "bounty" then
      table.insert(out, tostring(i) .. ". " .. displayName .. " - серия: " .. tostring(entry.current or 0))
    else
      table.insert(out, tostring(i) .. ". " .. displayName ..
        " - лучшая: " .. tostring(entry.best or 0) ..
        ", убийств: " .. tostring(entry.kills or 0) ..
        ", смертей: " .. tostring(entry.deaths or 0))
    end
  end
  return out
end

function sendBountyStats(info, command)
  for _, line in ipairs(bountyStatsLines(info, command)) do
    targetMessageResolved(info, line)
  end
end

function wargmOperationIdValue(object)
  local keys = { "operationId", "OperationId", "id", "Id", "orderId", "OrderId", "purchaseId", "PurchaseId" }
  for _, key in ipairs(keys) do
    local value = extractString(object, key) or ""
    if value ~= "" then return value end
    local numberValue = extractNumber(object, key)
    if numberValue ~= nil then return tostring(math.floor(numberValue)) end
  end
  return ""
end

WARGM_RETRY_PENDING_FILE = "wargm-retry-pending.json"
WARGM_PENDING_OBJECT_ID_KEYS = { "wargmItemId", "WargmItemId", "wargm_item_id", "wargmObjectId", "WargmObjectId", "wargm_object_id", "objectId", "ObjectId", "object_id", "productId", "ProductId", "product_id", "goodsId", "GoodsId", "goods_id", "goodId", "GoodId", "good_id", "shopItemId", "ShopItemId", "shop_item_id", "offerItemId", "OfferItemId", "offer_item_id", "itemId", "ItemId", "item_id", "item", "Item" }
WARGM_RULE_OBJECT_ID_KEYS = { "MatchItemId", "matchItemId", "MatchObjectId", "matchObjectId", "MatchProductId", "matchProductId", "MatchGoodsId", "matchGoodsId", "MatchShopItemId", "matchShopItemId" }
WARGM_OFFER_ID_KEYS = { "offerId", "OfferId", "offer_id", "offer", "Offer", "MatchOfferId", "matchOfferId" }
WARGM_TITLE_KEYS = { "offerTitle", "OfferTitle", "title", "Title", "name", "Name" }

function wargmFieldValue(object, keys)
  for _, key in ipairs(keys or {}) do
    local value = extractString(object, key) or ""
    if value ~= "" then return tostring(value) end
    local numberValue = extractNumber(object, key)
    if numberValue ~= nil then return tostring(math.floor(numberValue)) end
  end
  return ""
end

function wargmNormalizedMatchValue(value)
  return trimText(tostring(value or "")):lower()
end

function wargmRuleForPending(object)
  local objectId = wargmNormalizedMatchValue(wargmFieldValue(object, WARGM_PENDING_OBJECT_ID_KEYS))
  local offerId = wargmNormalizedMatchValue(wargmFieldValue(object, WARGM_OFFER_ID_KEYS))
  local title = tostring(wargmFieldValue(object, WARGM_TITLE_KEYS) or "")
  local lowerTitle = title:lower()
  local config = configText("wargm-shop")
  local rules = jsonArrayObjects(config, "Rules")
  if #rules == 0 then rules = jsonArrayObjects(config, "rules") end
  for _, rule in ipairs(rules) do
    if extractBoolAny(rule, { "Enabled", "enabled" }, true) ~= false then
      local matchItemId = wargmNormalizedMatchValue(wargmFieldValue(rule, WARGM_RULE_OBJECT_ID_KEYS))
      local matchOfferId = wargmNormalizedMatchValue(wargmFieldValue(rule, { "MatchOfferId", "matchOfferId" }))
      local matchTitle = tostring(extractStringAny(rule, { "MatchTitleContains", "matchTitleContains", "TitleContains", "titleContains" }) or "")
      local checks = 0
      local matched = true
      local reasons = {}
      if matchItemId ~= "" then
        checks = checks + 1
        local ok = objectId ~= "" and matchItemId == objectId
        matched = matched and ok
        if ok then table.insert(reasons, "object:" .. matchItemId) end
      end
      if matchOfferId ~= "" then
        checks = checks + 1
        local ok = offerId ~= "" and matchOfferId == offerId
        matched = matched and ok
        if ok then table.insert(reasons, "offer:" .. matchOfferId) end
      end
      if matchTitle ~= "" then
        checks = checks + 1
        local ok = title ~= "" and (lowerTitle:find(matchTitle:lower(), 1, true) ~= nil or title:find(matchTitle, 1, true) ~= nil)
        matched = matched and ok
        if ok then table.insert(reasons, "title:" .. matchTitle) end
      end
      if checks > 0 and matched then
        return rule, table.concat(reasons, "+")
      end
    end
  end
  return nil, ""
end

function wargmOperationKey(object, index)
  local operationId = wargmOperationIdValue(object)
  local steam = extractString(object, "steamId") or ""
  local mode = (extractString(object, "mode") or extractString(object, "DeliveryMode") or extractString(object, "deliveryMode") or "item"):lower():gsub("[%s_%-%.\"]+", "")
  local offerId = extractString(object, "offerId") or extractString(object, "OfferId") or extractString(object, "offer_id") or extractString(object, "offer") or ""
  local itemId = extractString(object, "itemId") or extractString(object, "ItemId") or extractString(object, "item") or extractString(object, "Item") or ""
  local vehicleId = extractString(object, "vehicleId") or extractString(object, "VehicleId") or ""
  local skill = extractString(object, "skill") or extractString(object, "skillName") or extractString(object, "SkillName") or ""
  local title = extractString(object, "title") or extractString(object, "Title") or extractString(object, "name") or extractString(object, "Name") or ""
  local amount = extractNumber(object, "amount") or extractNumber(object, "Amount") or extractNumber(object, "money") or extractNumber(object, "Money") or extractNumber(object, "gold") or extractNumber(object, "Gold") or extractNumber(object, "fame") or extractNumber(object, "Fame") or 0
  local quantity = extractNumber(object, "quantity") or extractNumber(object, "Quantity") or extractNumber(object, "buy_count") or extractNumber(object, "set_count") or 1
  local itemsSpec = extractString(object, "itemsSpec") or extractString(object, "ItemsSpec") or itemsSpecFromConfig(object)
  local base = operationId ~= "" and ("operation:" .. operationId) or ("pending:" .. tostring(index or 0))
  return base ..
    "|steam:" .. steam ..
    "|offer:" .. offerId ..
    "|mode:" .. mode ..
    "|item:" .. itemId ..
    "|vehicle:" .. vehicleId ..
    "|skill:" .. skill ..
    "|amount:" .. tostring(amount) ..
    "|qty:" .. tostring(quantity) ..
    "|title:" .. title ..
    "|items:" .. itemsSpec
end

WARGM_OPERATION_ID_KEY_PREFIXES = { "operationId:", "operation-id:" }

function addWargmOperationIdKeys(keys, operationId)
  if keys == nil then return end
  local id = tostring(operationId or "")
  if id == "" then return end
  for _, prefix in ipairs(WARGM_OPERATION_ID_KEY_PREFIXES) do
    keys[prefix .. id] = true
  end
end

function hasWargmOperationIdKey(keys, operationId)
  if keys == nil then return false end
  local id = tostring(operationId or "")
  if id == "" then return false end
  for _, prefix in ipairs(WARGM_OPERATION_ID_KEY_PREFIXES) do
    if keys[prefix .. id] == true then return true end
  end
  return false
end

function deliveredWargmKeys()
  local keys = {}
  local function addFromObject(object, index)
    local key = extractString(object, "key") or ""
    if key ~= "" then keys[key] = true end
    local operationId = wargmOperationIdValue(object)
    addWargmOperationIdKeys(keys, operationId)
    local fullKey = wargmOperationKey(object, index)
    if fullKey ~= "" then keys[fullKey] = true end
  end
  for index, object in ipairs(stateObjects("wargm-delivered.json")) do
    addFromObject(object, index)
  end
  for index, object in ipairs(stateObjects("wargm-confirmed.json")) do
    addFromObject(object, index)
  end
  return keys
end

function isoUtcTimestamp(value)
  local year, month, day, hour, minute, second = tostring(value or ""):match("(%d%d%d%d)%-(%d%d)%-(%d%d)T(%d%d):(%d%d):(%d%d)")
  if year == nil then return nil end
  local ok, epoch = pcall(function()
    return os.time({
      year = tonumber(year),
      month = tonumber(month),
      day = tonumber(day),
      hour = tonumber(hour),
      min = tonumber(minute),
      sec = tonumber(second)
    })
  end)
  if ok and epoch ~= nil then return epoch + localUtcOffsetSeconds() end
  return nil
end

function recentWargmDeliveredCount(steamId, sinceEpoch)
  local steam = tostring(steamId or "")
  local since = tonumber(sinceEpoch or 0) or 0
  if steam == "" or since <= 0 then return 0 end
  local count = 0
  for _, object in ipairs(stateObjects("wargm-delivered.json")) do
    local rowSteam = wargmObjectPlayerSteam(object)
    local rowEpoch = isoUtcTimestamp(extractStringAny(object, { "utc", "timestampUtc" }) or "")
    if rowSteam == steam and rowEpoch ~= nil and rowEpoch >= since then
      count = count + 1
    end
  end
  return count
end

function wargmObjectPlayerSteam(object)
  return extractStringAny(object, { "steamId", "SteamId", "steam_id", "steam", "Steam" }) or ""
end

function wargmOperationSettled(deliveredKeys, object, index)
  deliveredKeys = deliveredKeys or deliveredWargmKeys()
  local opKey = wargmOperationKey(object, index)
  if deliveredKeys[opKey] then return true end
  local operationId = wargmOperationIdValue(object)
  return hasWargmOperationIdKey(deliveredKeys, operationId)
end

function wargmSameOperation(leftObject, leftIndex, rightObject, rightIndex)
  local leftOperationId = wargmOperationIdValue(leftObject)
  local rightOperationId = wargmOperationIdValue(rightObject)
  if leftOperationId ~= "" and rightOperationId ~= "" then return leftOperationId == rightOperationId end
  return wargmOperationKey(leftObject, leftIndex) == wargmOperationKey(rightObject, rightIndex)
end

function wargmPendingObjects()
  local rows = {}
  local seen = {}
  for index, object in ipairs(stateObjects("wargm-pending.json")) do
    table.insert(rows, object)
    local opKey = wargmOperationKey(object, index)
    if opKey ~= "" then seen[opKey] = true end
    local operationId = wargmOperationIdValue(object)
    addWargmOperationIdKeys(seen, operationId)
  end
  for index, object in ipairs(stateObjects(WARGM_RETRY_PENDING_FILE)) do
    local opKey = wargmOperationKey(object, index)
    local operationId = wargmOperationIdValue(object)
    local exists = (opKey ~= "" and seen[opKey]) or hasWargmOperationIdKey(seen, operationId)
    if not exists then
      table.insert(rows, object)
      if opKey ~= "" then seen[opKey] = true end
      addWargmOperationIdKeys(seen, operationId)
    end
  end
  return rows
end

function rememberWargmRetryPending(object, opKey)
  if not stateArrayRecordLooksSafe(object) then return false end
  local rows = {}
  local found = false
  local operationId = wargmOperationIdValue(object)
  for index, current in ipairs(stateObjects(WARGM_RETRY_PENDING_FILE)) do
    local same = false
    local currentOperationId = wargmOperationIdValue(current)
    if operationId ~= "" and currentOperationId ~= "" then
      same = operationId == currentOperationId
    else
      same = wargmOperationKey(current, index) == tostring(opKey or "")
    end
    if same then
      if not found then table.insert(rows, object) end
      found = true
    else
      table.insert(rows, current)
    end
  end
  if not found then table.insert(rows, object) end
  return writeStateObjects(WARGM_RETRY_PENDING_FILE, rows)
end

function forgetWargmRetryPending(opKey, operationId)
  local rows = {}
  local removed = 0
  local targetKey = tostring(opKey or "")
  local targetOperationId = tostring(operationId or "")
  for index, object in ipairs(stateObjects(WARGM_RETRY_PENDING_FILE)) do
    local same = false
    local currentOperationId = wargmOperationIdValue(object)
    if targetOperationId ~= "" and currentOperationId ~= "" then
      same = currentOperationId == targetOperationId
    elseif targetKey ~= "" then
      same = wargmOperationKey(object, index) == targetKey
    end
    if same then
      removed = removed + 1
    else
      table.insert(rows, object)
    end
  end
  if removed > 0 then writeStateObjects(WARGM_RETRY_PENDING_FILE, rows) end
  return removed
end

function pruneWargmPending(deliveredKeys)
  deliveredKeys = deliveredKeys or deliveredWargmKeys()
  local kept = {}
  local removed = 0
  for index, object in ipairs(stateObjects("wargm-pending.json")) do
    local settled = wargmOperationSettled(deliveredKeys, object, index)
    if settled then
      removed = removed + 1
    else
      table.insert(kept, object)
    end
  end
  if removed > 0 then
    writeStateObjects("wargm-pending.json", kept)
    appendJsonArray(STATE_DIR .. "\\wargm-shop.json", '{"utc":' .. js(nowUtc()) .. ',"status":"pending-pruned","removed":' .. tostring(removed) .. ',"remaining":' .. tostring(#kept) .. '}', 1024 * 1024)
  end
  local retryKept = {}
  local retryRemoved = 0
  for index, object in ipairs(stateObjects(WARGM_RETRY_PENDING_FILE)) do
    local settled = wargmOperationSettled(deliveredKeys, object, index)
    if settled then
      retryRemoved = retryRemoved + 1
    else
      table.insert(retryKept, object)
    end
  end
  if retryRemoved > 0 then
    writeStateObjects(WARGM_RETRY_PENDING_FILE, retryKept)
    appendJsonArray(STATE_DIR .. "\\wargm-shop.json", '{"utc":' .. js(nowUtc()) .. ',"status":"retry-pending-pruned","removed":' .. tostring(retryRemoved) .. ',"remaining":' .. tostring(#retryKept) .. '}', 1024 * 1024)
  end
  return removed + retryRemoved
end

function wargmRetrySecondsRemaining(opKey)
  local now = os.time()
  local remaining = 0
  for _, object in ipairs(stateObjects("wargm-attempts.json")) do
    if (extractString(object, "key") or "") == tostring(opKey or "") then
      local retryAfter = extractNumber(object, "retryAfter") or 0
      if retryAfter > now and (retryAfter - now) > remaining then remaining = retryAfter - now end
    end
  end
  return remaining
end

function requestWargmSync(info)
  info = info or {}
  local request = '{"utc":' .. js(nowUtc()) ..
    ',"steamId":' .. js(info.steam or info.steamId or "") ..
    ',"name":' .. js(info.name or "") ..
    ',"runtimeKey":' .. js(info.runtimeKey or "") ..
    ',"source":"player-command"}'
  local saved = writeAll(STATE_DIR .. "\\wargm-sync-request.json", request)
  appendJsonArray(STATE_DIR .. "\\wargm-shop.json", '{"utc":' .. js(nowUtc()) ..
    ',"status":"sync-requested","steamId":' .. js(info.steam or info.steamId or "") ..
    ',"name":' .. js(info.name or "") ..
    ',"saved":' .. (saved and "true" or "false") .. '}', 1024 * 1024)
  appendLog("wargm sync requested steam=" .. tostring(info.steam or info.steamId or "") .. " name=" .. tostring(info.name or "") .. " saved=" .. tostring(saved))
  return saved
end

function requestWargmConfirm(info, operationId)
  info = info or {}
  local request = '{"utc":' .. js(nowUtc()) ..
    ',"steamId":' .. js(info.steam or info.steamId or "") ..
    ',"name":' .. js(info.name or "") ..
    ',"operationId":' .. js(operationId or "") ..
    ',"source":"player-command"}'
  local saved = writeAll(STATE_DIR .. "\\wargm-confirm-request.json", request)
  appendJsonArray(STATE_DIR .. "\\wargm-shop.json", '{"utc":' .. js(nowUtc()) ..
    ',"status":"confirm-requested","operationId":' .. js(operationId or "") ..
    ',"steamId":' .. js(info.steam or info.steamId or "") ..
    ',"name":' .. js(info.name or "") ..
    ',"saved":' .. (saved and "true" or "false") .. '}', 1024 * 1024)
  appendLog("wargm confirm requested operationId=" .. tostring(operationId or "") .. " saved=" .. tostring(saved))
  return saved
end

function requestGameStoresClaim(info)
  info = info or {}
  local at = os.time()
  local request = '{"utc":' .. js(nowUtc()) ..
    ',"at":' .. tostring(at) ..
    ',"steamId":' .. js(info.steam or info.steamId or "") ..
    ',"name":' .. js(info.name or "") ..
    ',"runtimeKey":' .. js(info.runtimeKey or "") ..
    ',"source":"player-command"}'
  local saved = writeAll(STATE_DIR .. "\\gamestores-claim-request.json", request)
  appendJsonArray(STATE_DIR .. "\\gamestores-shop.json", '{"utc":' .. js(nowUtc()) ..
    ',"at":' .. tostring(at) ..
    ',"status":"claim-requested","steamId":' .. js(info.steam or info.steamId or "") ..
    ',"name":' .. js(info.name or "") ..
    ',"saved":' .. (saved and "true" or "false") .. '}', 1024 * 1024)
  appendLog("gamestores claim requested steam=" .. tostring(info.steam or info.steamId or "") .. " name=" .. tostring(info.name or "") .. " saved=" .. tostring(saved))
  return saved, at
end

function recentGameStoresClaimMessage(info, sinceEpoch)
  local since = tonumber(sinceEpoch or 0) or 0
  if since <= 0 then return "" end
  local bestEpoch = 0
  local bestStatus = ""
  local bestMessage = ""
  for _, object in ipairs(stateObjects("gamestores-shop.json")) do
    local status = extractString(object, "status") or ""
    if (status == "claim-finished" or status == "claim-empty" or status == "claim-failed") and samePlayerRecord(info, object) then
      local epoch = extractNumber(object, "at") or isoUtcTimestamp(extractStringAny(object, { "utc", "timestampUtc" }) or "") or 0
      if epoch >= since and epoch >= bestEpoch then
        bestEpoch = epoch
        bestStatus = status
        bestMessage = extractString(object, "message") or ""
      end
    end
  end
  if bestStatus == "" then return "" end
  if bestStatus == "claim-finished" then return bestMessage ~= "" and ("GameStores: " .. bestMessage) or "GameStores: покупка выдана." end
  if bestStatus == "claim-empty" then return bestMessage ~= "" and ("GameStores: " .. bestMessage .. " Если купил только что, повтори /pay через несколько секунд.") or "GameStores: покупок для выдачи не найдено. Если купил только что, повтори /pay через несколько секунд." end
  return bestMessage ~= "" and ("GameStores: " .. bestMessage) or "GameStores: проверка покупки не выполнена."
end

welcomeClaimsInFlight = {}
dailyPackClaimsInFlight = {}

BASE_LOOT_STATE_FILE = "base-loot-collector.json"
BASE_LOOT_COOLDOWN_FILE = "base-loot-cooldowns.json"

function baseLootConfig()
  return configText("base-loot-collector")
end

function baseLootNumber(names, fallback)
  return configNumber("base-loot-collector", names, fallback)
end

function baseLootBool(names, fallback)
  return configBool("base-loot-collector", names, fallback)
end

function baseLootString(names, fallback)
  return configString("base-loot-collector", names, fallback or "")
end

function baseLootSplitTokens(text)
  local out = {}
  local seen = {}
  for part in tostring(text or ""):gmatch("[^,;\r\n]+") do
    local token = tostring(part or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if token ~= "" then
      local key = token:lower()
      if not seen[key] then
        seen[key] = true
        table.insert(out, token)
      end
    end
  end
  return out
end

function baseLootConfigTokens(names, fallback)
  return baseLootSplitTokens(baseLootString(names, fallback or ""))
end

function baseLootVipSettings()
  return jsonObjectForKey(baseLootConfig(), "VipSettings") or jsonObjectForKey(baseLootConfig(), "vipSettings") or nil
end

function baseLootVipActive(info)
  if not vipActiveForInfo(info) then return false end
  local settings = baseLootVipSettings()
  if settings ~= nil then
    if extractBoolAny(settings, { "Enabled", "enabled" }, true) == false then return false end
    local required = extractStringAny(settings, { "RequiredPermission", "requiredPermission" }) or "base-loot.vip"
    return hasPermission(info, required)
  end
  return vipFeatureEnabledForInfo(info, "BaseLootCollector")
end

function baseLootVipNumber(info, names, fallback)
  local settings = baseLootVipSettings()
  if settings ~= nil and baseLootVipActive(info) then
    local value = extractNumberAny(settings, names, nil)
    if value ~= nil then return value end
  end
  return vipFeatureNumberForInfo(info, "BaseLootCollector", names, fallback) or fallback
end

function baseLootParams(info)
  local radius = math.max(500, math.min(math.floor(baseLootNumber({ "RadiusCm", "radiusCm" }, 5000) or 5000), 20000))
  local cooldown = math.max(0, math.floor(baseLootNumber({ "CooldownSeconds", "cooldownSeconds" }, 120) or 120))
  local maxItems = math.max(1, math.min(math.floor(baseLootNumber({ "MaxItemsPerRun", "maxItemsPerRun" }, 80) or 80), 500))
  if baseLootVipActive(info) then
    radius = math.max(radius, math.min(math.floor(baseLootVipNumber(info, { "RadiusCm", "radiusCm" }, radius) or radius), 30000))
    local vipCooldown = math.max(0, math.floor(baseLootVipNumber(info, { "CooldownSeconds", "cooldownSeconds" }, cooldown) or cooldown))
    cooldown = math.min(cooldown, vipCooldown)
    maxItems = math.max(maxItems, math.min(math.floor(baseLootVipNumber(info, { "MaxItemsPerRun", "maxItemsPerRun" }, maxItems) or maxItems), 1000))
  end
  -- SCUM exposes a dedicated flag-influence radius (5000 cm in the current
  -- build). Keep membership separate from the small legacy collection radius
  -- so the bounded overlap can cover the whole owned flag area.
  local flagZoneShape = tostring(baseLootString({ "FlagZoneShape", "flagZoneShape" }, "square") or "square"):lower()
  if flagZoneShape ~= "square" and flagZoneShape ~= "circle" then flagZoneShape = "square" end
  local flagZoneHalfExtentCm = math.max(500, math.min(math.floor(baseLootNumber({ "FlagZoneHalfExtentCm", "flagZoneHalfExtentCm" }, 5000) or 5000), 20000))
  local flagLookupRadiusCm = flagZoneHalfExtentCm
  if flagZoneShape == "square" then
    -- Native lookup is circular; query the square's circumscribed circle and
    -- apply the exact X/Y square boundary locally below.
    flagLookupRadiusCm = math.ceil(flagZoneHalfExtentCm * 1.414214)
  end
  local collectWholeFlagZone = baseLootBool({ "CollectWholeFlagZone", "collectWholeFlagZone" }, true) ~= false
  local overlapRadiusCm = collectWholeFlagZone and flagLookupRadiusCm or radius
  local maxScannedItems = math.max(10, math.min(math.floor(baseLootNumber({ "MaxScannedItems", "maxScannedItems" }, 5000) or 5000), 5000))
  local occupancyScanLimit = math.max(0, math.min(math.floor(baseLootNumber({ "InventoryLocationOccupancyScanLimit", "inventoryLocationOccupancyScanLimit" }, 700) or 700), 5000))
  local combinedScanDefault = math.max(maxScannedItems, occupancyScanLimit)
  return {
    radius = radius,
    flagZoneShape = flagZoneShape,
    flagZoneHalfExtentCm = flagZoneHalfExtentCm,
    flagLookupRadiusCm = flagLookupRadiusCm,
    collectWholeFlagZone = collectWholeFlagZone,
    overlapRadiusCm = overlapRadiusCm,
    cooldown = cooldown,
    maxItems = maxItems,
    maxChests = math.max(1, math.min(math.floor(baseLootNumber({ "MaxChestsPerRun", "maxChestsPerRun" }, 40) or 40), 250)),
    maxScannedItems = maxScannedItems,
    maxScannedChests = math.max(10, math.min(math.floor(baseLootNumber({ "MaxScannedChests", "maxScannedChests" }, 160) or 160), 1000)),
    chestItemFallbackScanLimit = math.max(10, math.min(math.floor(baseLootNumber({ "ChestItemFallbackScanLimit", "chestItemFallbackScanLimit" }, 700) or 700), 5000)),
    combinedItemScanLimit = math.max(10, math.min(math.floor(baseLootNumber({ "CombinedItemScanLimit", "combinedItemScanLimit" }, combinedScanDefault) or combinedScanDefault), 5000)),
    -- No FindAllOf fallback exists: an unavailable/unproven overlap route
    -- fails closed instead of freezing the GameThread with a world scan.
    sphereOverlapEnabled = baseLootBool({ "EnableSphereOverlapScan", "enableSphereOverlapScan" }, false) == true,
    sphereOverlapObjectTypes = baseLootConfigTokens({ "SphereOverlapObjectTypes", "sphereOverlapObjectTypes" }, ""),
    sphereOverlapMaxActors = math.max(64, math.min(math.floor(baseLootNumber({ "SphereOverlapMaxActors", "sphereOverlapMaxActors" }, math.max(128, math.min(maxItems + 160, 512))) or math.max(128, math.min(maxItems + 160, 512))), 1000)),
    sphereOverlapWorkBudgetMs = math.max(1, math.min(math.floor(baseLootNumber({ "SphereOverlapWorkBudgetMs", "sphereOverlapWorkBudgetMs" }, 120) or 120), 1500)),
    scanWorkBudgetMs = math.max(0, math.min(math.floor(baseLootNumber({ "ScanWorkBudgetMs", "scanWorkBudgetMs" }, 0) or 0), 500)),
    chestScanWorkBudgetMs = math.max(0, math.min(math.floor(baseLootNumber({ "ChestScanWorkBudgetMs", "chestScanWorkBudgetMs" }, 0) or 0), 500)),
    moveWorkBudgetMs = math.max(20, math.min(math.floor(baseLootNumber({ "MoveWorkBudgetMs", "moveWorkBudgetMs" }, 90) or 90), 1500)),
    singleItemMoveBudgetMs = math.max(5, math.min(math.floor(baseLootNumber({ "SingleItemMoveBudgetMs", "singleItemMoveBudgetMs" }, 30) or 30), 500)),
    batchItemsPerTick = math.max(1, math.min(math.floor(baseLootNumber({ "BatchItemsPerTick", "batchItemsPerTick" }, 4) or 4), 50)),
    batchDelayMs = math.max(25, math.min(math.floor(baseLootNumber({ "BatchDelayMs", "batchDelayMs" }, 200) or 200), 5000)),
    collectAllOnSingleCommand = baseLootBool({ "CollectAllOnSingleCommand", "collectAllOnSingleCommand" }, true) ~= false,
    limitedCooldownSeconds = math.max(3, math.min(math.floor(baseLootNumber({ "LimitedCooldownSeconds", "limitedCooldownSeconds" }, 10) or 10), 120)),
    activeTimeoutSeconds = math.max(5, math.min(math.floor(baseLootNumber({ "ActiveTimeoutSeconds", "activeTimeoutSeconds" }, 25) or 25), 300)),
    requireOnFloor = baseLootBool({ "RequireOnFloorPresence", "requireOnFloorPresence" }, true) ~= false,
    nameContains = baseLootBool({ "NameContains", "nameContains" }, true) ~= false,
    defaultChest = baseLootString({ "DefaultChestName", "defaultChestName" }, "Loot"),
    chestScanClasses = baseLootConfigTokens({ "ChestScanClasses", "chestScanClasses" },
      "ChestItem;Improved_Wooden_Chest_ES_C;Improved_Wooden_Chest_ES;Improved_Wooden_Chest_C;Improved_Wooden_Chest;Improvised_Metal_Chest_ES_C;Improvised_Metal_Chest_ES;Improvised_Metal_Chest_C;Improvised_Metal_Chest;Improvised_Wooden_Chest_ES_C;Improvised_Wooden_Chest_ES;Improvised_Wooden_Chest_C;Improvised_Wooden_Chest"),
    chestClassTokens = baseLootConfigTokens({ "ChestClassTokens", "chestClassTokens" },
      "ChestItem;Improved_Wooden_Chest_ES;Improved_Wooden_Chest;Improvised_Metal_Chest_ES;Improvised_Metal_Chest;Improvised_Wooden_Chest_ES;Improvised_Wooden_Chest"),
    fallbackToDefaultChest = baseLootBool({ "FallbackToDefaultChest", "fallbackToDefaultChest" }, true) ~= false,
    preferChestItemScanOnly = baseLootBool({ "PreferChestItemScanOnly", "preferChestItemScanOnly" }, false) == true,
    itemBlockedTokens = baseLootConfigTokens({ "ItemBlockedTokens", "itemBlockedTokens", "ExcludedItemTokens", "excludedItemTokens" },
      "chest;vehicle;prisoner;baseflag;conzbase;inventorycomponent;bonfire;campfire;fireplace;trap;shelter;flag;tent;torch;lantern;sign;barrel;placeable;basebuilding;base_building;kitchenstove;kitchen_stove;refrigerator;work_drillpress;drillpress;work_lathe_machine;lathe_machine;workbench;work_bench;battery_charger;traderdepot"),
    dryRun = baseLootBool({ "DryRun", "dryRun" }, false) == true,
    relocateBeforeMove = baseLootBool({ "RelocateBeforeMove", "relocateBeforeMove" }, false) == true,
    allowUnsafeDropAroundFallback = baseLootBool({ "AllowUnsafeDropAroundFallback", "allowUnsafeDropAroundFallback" }, false) == true,
    controlledRelocate = baseLootBool({ "ControlledRelocate", "controlledRelocate" }, true) ~= false,
    controlledRelocateDelayMs = math.max(250, math.min(math.floor(baseLootNumber({ "ControlledRelocateDelayMs", "controlledRelocateDelayMs" }, 1200) or 1200), 5000)),
    controlledRelocateMaxPerRun = math.max(1, math.min(math.floor(baseLootNumber({ "ControlledRelocateMaxPerRun", "controlledRelocateMaxPerRun" }, 25) or 25), 500)),
    relocateIfFartherThanCm = math.max(100, math.min(math.floor(baseLootNumber({ "RelocateIfFartherThanCm", "relocateIfFartherThanCm" }, 650) or 650), 5000)),
    relocateZOffset = math.max(-200, math.min(math.floor(baseLootNumber({ "RelocateZOffset", "relocateZOffset" }, 50) or 50), 500)),
    controlledRelocateAttempts = math.max(1, math.min(math.floor(baseLootNumber({ "ControlledRelocateAttempts", "controlledRelocateAttempts" }, 3) or 3), 5)),
    relocateVerticalToleranceCm = math.max(50, math.min(math.floor(baseLootNumber({ "RelocateVerticalToleranceCm", "relocateVerticalToleranceCm" }, 350) or 350), 1000)),
    inventoryGridRows = math.max(1, math.min(math.floor(baseLootNumber({ "InventoryGridRows", "inventoryGridRows" }, 16) or 16), 64)),
    inventoryGridColumns = math.max(1, math.min(math.floor(baseLootNumber({ "InventoryGridColumns", "inventoryGridColumns" }, 16) or 16), 64)),
    inventoryLocationMaxAttempts = math.max(1, math.min(math.floor(baseLootNumber({ "InventoryLocationMaxAttempts", "inventoryLocationMaxAttempts" }, 48) or 48), 512)),
    inventoryLocationOccupancyScanLimit = occupancyScanLimit,
    inventoryLocationOccupancyBatch = baseLootBool({ "InventoryLocationOccupancyBatch", "inventoryLocationOccupancyBatch" }, true) ~= false,
    inventoryLocationIncludeLegacyAuto = baseLootBool({ "InventoryLocationIncludeLegacyAuto", "inventoryLocationIncludeLegacyAuto" }, true) ~= false,
    openChestBeforeMove = baseLootBool({ "OpenChestBeforeMove", "openChestBeforeMove" }, false) == true,
    pickupFloorBeforeChestMove = baseLootBool({ "PickupFloorBeforeChestMove", "pickupFloorBeforeChestMove" }, false) == true
  }
end

function baseLootStageLog(stage, info, extra)
  appendLog("base-loot stage=" .. tostring(stage or "") ..
    " player=" .. tostring((info or {}).name or (info or {}).steam or "") ..
    " steam=" .. tostring(((info or {}).steam or "") ~= "" and "set" or "missing") ..
    " runtimeKey=" .. tostring((info or {}).runtimeKey or "") ..
    " x=" .. tostring(math.floor(tonumber((info or {}).x) or 0)) ..
    " y=" .. tostring(math.floor(tonumber((info or {}).y) or 0)) ..
    (extra ~= nil and (" " .. tostring(extra)) or ""))
end

function baseLootResolveLiveForRun(info, mode)
  if info == nil then return nil, "[Лут] Игрок не найден в live runtime." end
  local live = info
  if baseLootBool({ "RefreshLivePlayerBeforeRun", "refreshLivePlayerBeforeRun" }, false) == true then
    local okResolve, resolved = pcall(function()
      return resolvePlayerInfo((info or {}).steam, (info or {}).name, info, (info or {}).runtimeKey)
    end)
    if okResolve and resolved ~= nil then live = resolved end
  end
  local steam = cleanText((live or {}).steam or (live or {}).steamId or "")
  if steam ~= "" then
    live.steam = steam
    live.steamId = steam
  end
  if not playerHasUsableLocation(live) then
    appendActionEvent("base_loot_collector", false, live, "player location not ready",
      '{"stage":"preflight","reason":"location","mode":' .. js(mode or "") .. '}')
    return nil, "[Лут] Сервер ещё не видит твои координаты. Повтори через несколько секунд."
  end
  if tostring(mode or "") ~= "chests" then
    if live.pawn == nil and baseLootBool({ "RequirePawnForCollect", "requirePawnForCollect" }, true) ~= false then
      appendActionEvent("base_loot_collector", false, live, "player pawn missing before collect",
        '{"stage":"preflight","reason":"pawn","mode":' .. js(mode or "") .. '}')
      return nil, "[Лут] Персонаж ещё не готов для безопасного сбора. Повтори через несколько секунд."
    end
  end
  return live, nil
end

function baseLootShellQuote(value)
  local text = tostring(value or "")
  return '"' .. text:gsub('"', '""') .. '"'
end

function baseLootSqlQuote(value)
  return "'" .. tostring(value or ""):gsub("'", "''") .. "'"
end

function baseLootPathHasSlash(value)
  local text = tostring(value or "")
  return text:find("\\", 1, true) ~= nil or text:find("/", 1, true) ~= nil
end

function baseLootPathIsAbsolute(value)
  local text = tostring(value or "")
  return text:match("^%a:[\\/]") ~= nil or text:match("^[\\/][\\/]") ~= nil or text:match("^/") ~= nil
end

function baseLootFileExists(path)
  local text = tostring(path or "")
  if text == "" then return false end
  local okOpen, file = pcall(function() return io.open(text, "rb") end)
  if okOpen and file then
    pcall(function() file:close() end)
    return true
  end
  return false
end

function baseLootResolveSqliteExe()
  local configured = baseLootString({ "SqliteExe", "sqliteExe" }, "")
  configured = tostring(configured or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if configured == "" then return "" end
  if baseLootPathIsAbsolute(configured) or baseLootPathHasSlash(configured) then
    return configured
  end
  local candidates = {
    ".\\ScumNeDjin\\tools\\" .. configured,
    ".\\ScumNeDjin\\" .. configured,
    ".\\" .. configured
  }
  for _, candidate in ipairs(candidates) do
    if baseLootFileExists(candidate) then return candidate end
  end
  return configured
end

function baseLootResolveDatabasePath()
  local configured = baseLootString({ "DatabasePath", "databasePath", "DbPath", "dbPath" }, "..\\..\\Saved\\SaveFiles\\SCUM.db")
  configured = tostring(configured or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if configured == "" then return "" end
  if baseLootPathIsAbsolute(configured) or baseLootFileExists(configured) then return configured end
  local candidates = {
    configured,
    "..\\..\\Saved\\SaveFiles\\SCUM.db",
    ".\\Saved\\SaveFiles\\SCUM.db"
  }
  for _, candidate in ipairs(candidates) do
    if baseLootFileExists(candidate) then return candidate end
  end
  return configured
end

function baseLootSqliteCommand(sql)
  local exe = baseLootResolveSqliteExe()
  local db = baseLootResolveDatabasePath()
  if exe == "" or db == "" then return nil, "sqlite path missing" end
  return baseLootShellQuote(exe) .. " -readonly -noheader -separator \"|\" " .. baseLootShellQuote(db) .. " " .. baseLootShellQuote(sql)
end

function baseLootSql(sql)
  local command, commandError = baseLootSqliteCommand(sql)
  if command == nil then return false, tostring(commandError or "sqlite command missing") end
  local okOpen, handle = pcall(function() return io.popen(command .. " 2>&1", "r") end)
  if not okOpen or handle == nil then return false, "sqlite popen failed" end
  local okRead, output = pcall(function() return handle:read("*a") end)
  pcall(function() handle:close() end)
  if not okRead then return false, tostring(output or "sqlite read failed") end
  output = tostring(output or ""):gsub("\r", ""):gsub("%s+$", "")
  local lower = output:lower()
  if lower:find("error:", 1, true) ~= nil or
      lower:find("not recognized", 1, true) ~= nil or
      lower:find("not found", 1, true) ~= nil or
      lower:find("cannot open", 1, true) ~= nil or
      lower:find("unable to open", 1, true) ~= nil then
    return false, output
  end
  return true, output
end

function baseLootNativeAccess(info, flag)
  local baseId = tonumber((flag or {}).baseId)
  if baseId == nil then return false, "flag id missing", false, "{}" end
  local profile = tostring((info or {}).userProfileId or (info or {}).serverUserProfileId or (info or {}).profileId or "")
  local profileId = tonumber(profile) or 0
  local steam = tostring((info or {}).steam or (info or {}).steamId or "")
  local payload = '{"baseId":' .. tostring(math.floor(baseId)) ..
    ',"profileId":' .. tostring(math.floor(profileId)) ..
    ',"steamId":' .. js(steam) ..
    ',"allowFlagOwnerWithoutSquad":' .. (baseLootBool({ "AllowFlagOwnerWithoutSquad", "allowFlagOwnerWithoutSquad" }, true) ~= false and "true" or "false") ..
    '}'
  appendLog("base-loot native access request baseId=" .. tostring(math.floor(baseId)) ..
    " profileId=" .. tostring(math.floor(profileId)) ..
    " steam=" .. tostring(steam ~= "" and "set" or "missing"))
  local okNative, message, result = nativeHttpCommand(
    "base_loot_access",
    payload,
    math.max(300, math.min(math.floor(baseLootNumber({ "DbCheckTimeoutMs", "dbCheckTimeoutMs" }, 1200) or 1200), 2500)),
    "base-loot-" .. tostring(math.floor(baseId)) .. "-" .. tostring(profileId > 0 and profileId or steam))
  result = tostring(result or "{}")
  if not okNative then
    return false, tostring(message or "native SQLite access check failed"), true, result
  end
  local allowed = extractBool(result, "allowed", false) == true
  if allowed then return true, tostring(message or "base loot access allowed"), false, result end
  local reason = extractString(result, "reason") or tostring(message or "base loot access denied")
  if reason == "db_error" or extractBool(result, "dbAvailable", true) == false then
    return false, tostring(message or reason), true, result
  end
  return false, reason, false, result
end

function baseLootProfileId(info)
  local profile = tostring((info or {}).userProfileId or (info or {}).serverUserProfileId or (info or {}).profileId or "")
  if profile ~= "" and profile ~= "0" and tonumber(profile) ~= nil then return math.floor(tonumber(profile)) end
  local steam = tostring((info or {}).steam or (info or {}).steamId or "")
  if steam == "" or not looksLikeSteamId(steam) then return nil, "missing steam id" end
  local okSql, output = baseLootSql("select id from user_profile where user_id=" .. baseLootSqlQuote(steam) .. " order by id desc limit 1;")
  if not okSql then return nil, output end
  local id = tonumber(tostring(output or ""):match("(%d+)"))
  if id == nil then return nil, "profile not found" end
  return math.floor(id)
end

function baseLootBaseIdFromKey(key)
  local value = key
  if type(value) == "table" then value = value.Value or value.value or value.Id or value.id end
  return tonumber(value)
end

function baseLootAddFlag(flags, actor, baseId, radius)
  if actor == nil or not isValidObject(actor) then return end
  local x, y, z = vectorOf(actor)
  if x == 0 and y == 0 then return end
  table.insert(flags, {
    actor = actor,
    baseId = tonumber(baseId),
    x = x,
    y = y,
    z = z,
    radius = math.max(500, tonumber(radius or 0) or 0)
  })
end

function baseLootManagerRadius(manager, fallback)
  local radius = nil
  pcall(function() radius = tonumber(manager._flagInfluenceRadius or manager.FlagInfluenceRadius or manager.flagInfluenceRadius) end)
  return radius or fallback
end

function baseLootCollectFlags(radius)
  local flags = {}
  for _, manager in ipairs(findAll({ "ConZBaseManager", "ConZBaseManager_C", "BP_ConZBaseManager_C" })) do
    local managerRadius = baseLootManagerRadius(manager, radius)
    local bases = nil
    pcall(function() bases = manager._bases or manager.Bases or manager.bases end)
    if bases ~= nil then
      local iterated = false
      pcall(function()
        bases:ForEach(function(key, value)
          iterated = true
          baseLootAddFlag(flags, value, baseLootBaseIdFromKey(key), managerRadius)
        end)
      end)
      if not iterated then
        pcall(function()
          for key, value in pairs(bases) do
            baseLootAddFlag(flags, value, baseLootBaseIdFromKey(key), managerRadius)
          end
        end)
      end
    end
  end
  if #flags == 0 then
    for _, actor in ipairs(findAll({ "ConZBase", "ConZBase_C", "BP_ConZBase_C", "BP_ConZBaseFlag_C", "ConZBaseFlag" })) do
      baseLootAddFlag(flags, actor, nil, radius)
    end
  end
  return flags
end

function baseLootCurrentPosition(info)
  local x = tonumber((info or {}).x)
  local y = tonumber((info or {}).y)
  local z = tonumber((info or {}).z)
  if x ~= nil and y ~= nil then return x, y, z or 0 end
  if baseLootBool({ "AllowPawnLocationFallback", "allowPawnLocationFallback" }, false) == true and info ~= nil and info.pawn ~= nil then
    return vectorOf(info.pawn)
  end
  return 0, 0, 0
end

function baseLootNativeNearestFlag(info, radius)
  local px, py, pz = baseLootCurrentPosition(info)
  if px == 0 and py == 0 then return nil, "player coordinates missing" end
  local limit = math.max(500, math.floor(tonumber(radius) or 5000))
  local payload = '{"x":' .. tostring(px) ..
    ',"y":' .. tostring(py) ..
    ',"z":' .. tostring(pz or 0) ..
    ',"radiusCm":' .. tostring(limit) ..
    '}'
  appendLog("base-loot native nearest flag request player=" .. tostring((info or {}).name or (info or {}).steam or "") ..
    " x=" .. tostring(math.floor(px)) ..
    " y=" .. tostring(math.floor(py)) ..
    " radius=" .. tostring(limit))
  local okNative, message, result = nativeHttpCommand(
    "base_loot_nearest_flag",
    payload,
    math.max(300, math.min(math.floor(baseLootNumber({ "DbCheckTimeoutMs", "dbCheckTimeoutMs" }, 1200) or 1200), 2500)),
    "base-loot-nearest-" .. tostring(math.floor(px)) .. "-" .. tostring(math.floor(py)))
  result = tostring(result or "{}")
  if not okNative then return nil, tostring(message or "native nearest flag lookup failed"), true, result end
  if extractBool(result, "found", false) ~= true then
    return nil, extractString(result, "reason") or tostring(message or "nearest flag not found"), false, result
  end
  if extractBool(result, "withinRadius", false) ~= true then
    return nil, extractString(result, "reason") or tostring(message or "nearest flag outside radius"), false, result
  end
  local baseId = extractNumber(result, "baseId")
  if baseId == nil or baseId <= 0 then return nil, "nearest flag base id missing", false, result end
  return {
    actor = nil,
    baseId = math.floor(baseId),
    elementId = math.floor(extractNumber(result, "elementId") or 0),
    ownerProfileId = math.floor(extractNumber(result, "ownerProfileId") or 0),
    x = extractNumber(result, "x") or px,
    y = extractNumber(result, "y") or py,
    z = extractNumber(result, "z") or 0,
    radius = limit,
    distance = extractNumber(result, "distanceCm") or 0,
    source = "native-db-nearest-flag"
  }, tostring(message or "nearest flag resolved"), false, result
end

function baseLootNativeNearestFlagAsync(info, radius, onResult)
  local px, py, pz = baseLootCurrentPosition(info)
  if px == 0 and py == 0 then
    if type(onResult) == "function" then onResult(nil, "player coordinates missing", false, "{}") end
    return false, "player coordinates missing"
  end
  local limit = math.max(500, math.floor(tonumber(radius) or 5000))
  local payload = '{"x":' .. tostring(px) ..
    ',"y":' .. tostring(py) ..
    ',"z":' .. tostring(pz or 0) ..
    ',"radiusCm":' .. tostring(limit) ..
    '}'
  appendLog("base-loot native nearest flag async request player=" .. tostring((info or {}).name or (info or {}).steam or "") ..
    " x=" .. tostring(math.floor(px)) ..
    " y=" .. tostring(math.floor(py)) ..
    " radius=" .. tostring(limit))
  local queued, queueMessage = nativeHttpCommandAsync(
    "base_loot_nearest_flag",
    "base_loot_nearest_flag",
    payload,
    math.max(300, math.min(math.floor(baseLootNumber({ "DbCheckTimeoutMs", "dbCheckTimeoutMs" }, 1200) or 1200), 2500)),
    "base-loot-nearest-" .. tostring(math.floor(px)) .. "-" .. tostring(math.floor(py)),
    function(okNative, message, result)
      result = tostring(result or "{}")
      if not okNative then
        if type(onResult) == "function" then onResult(nil, tostring(message or "native nearest flag lookup failed"), true, result) end
        return
      end
      if extractBool(result, "found", false) ~= true then
        if type(onResult) == "function" then onResult(nil, extractString(result, "reason") or tostring(message or "nearest flag not found"), false, result) end
        return
      end
      if extractBool(result, "withinRadius", false) ~= true then
        if type(onResult) == "function" then onResult(nil, extractString(result, "reason") or tostring(message or "nearest flag outside radius"), false, result) end
        return
      end
      local baseId = extractNumber(result, "baseId")
      if baseId == nil or baseId <= 0 then
        if type(onResult) == "function" then onResult(nil, "nearest flag base id missing", false, result) end
        return
      end
      local flag = {
        actor = nil,
        baseId = math.floor(baseId),
        elementId = math.floor(extractNumber(result, "elementId") or 0),
        ownerProfileId = math.floor(extractNumber(result, "ownerProfileId") or 0),
        x = extractNumber(result, "x") or px,
        y = extractNumber(result, "y") or py,
        z = extractNumber(result, "z") or 0,
        radius = limit,
        distance = extractNumber(result, "distanceCm") or 0,
        source = "native-db-nearest-flag"
      }
      if type(onResult) == "function" then onResult(flag, tostring(message or "nearest flag resolved"), false, result) end
    end)
  if not queued then
    if type(onResult) == "function" then onResult(nil, tostring(queueMessage or "native HTTP bridge queue failed"), true, "{}") end
    return false, tostring(queueMessage or "native HTTP bridge queue failed")
  end
  return true
end

function baseLootPointInArea(x, y, flag, shape, extentCm, label)
  local fx = tonumber((flag or {}).x)
  local fy = tonumber((flag or {}).y)
  x = tonumber(x)
  y = tonumber(y)
  if x == nil or y == nil then return false, "point coordinates missing" end
  if fx == nil or fy == nil then return false, "flag coordinates missing" end
  local half = math.max(500, math.floor(tonumber(extentCm) or 5000))
  shape = tostring(shape or "square"):lower()
  local dx = math.abs(x - fx)
  local dy = math.abs(y - fy)
  local distance = math.sqrt((dx * dx) + (dy * dy))
  local inside = false
  if shape == "circle" then
    inside = distance <= half
  else
    shape = "square"
    inside = dx <= half and dy <= half
  end
  return inside, tostring(label or "area") .. " shape=" .. shape ..
    " half=" .. tostring(half) ..
    " dx=" .. tostring(math.floor(dx)) ..
    " dy=" .. tostring(math.floor(dy)) ..
    " distance=" .. tostring(math.floor(distance))
end

function baseLootPointInFlagZone(x, y, flag, params)
  return baseLootPointInArea(x, y, flag,
    (params or {}).flagZoneShape or "square",
    (params or {}).flagZoneHalfExtentCm or 5000,
    "flag-zone")
end

function baseLootPointInCollectionArea(x, y, flag, params)
  if (params or {}).collectWholeFlagZone ~= false then
    return baseLootPointInFlagZone(x, y, flag, params)
  end
  return baseLootPointInArea(x, y, flag, "circle", (params or {}).radius or 5000, "collection-radius")
end

function baseLootFlagZoneContains(info, flag, params)
  local px, py = baseLootCurrentPosition(info)
  if px == 0 and py == 0 then return false, "player coordinates missing" end
  return baseLootPointInFlagZone(px, py, flag, params)
end

function baseLootFinalizeCurrentFlag(info, dbFlag, params)
  if dbFlag == nil then return nil, "nearest flag missing" end
  local inside, zoneDetail = baseLootFlagZoneContains(info, dbFlag, params)
  if not inside then return nil, "outside flag zone " .. tostring(zoneDetail or "") end
  dbFlag.radius = tonumber((params or {}).radius) or tonumber(dbFlag.radius) or 0
  dbFlag.zoneShape = tostring((params or {}).flagZoneShape or "square")
  dbFlag.zoneHalfExtentCm = tonumber((params or {}).flagZoneHalfExtentCm) or 5000
  dbFlag.zoneLookupRadiusCm = tonumber((params or {}).flagLookupRadiusCm) or dbFlag.zoneHalfExtentCm
  return dbFlag, zoneDetail
end

function baseLootCurrentFlag(info, params)
  local px, py = baseLootCurrentPosition(info)
  if px == 0 and py == 0 then return nil end
  local lookupRadius = math.max(500, math.floor(tonumber((params or {}).flagLookupRadiusCm) or tonumber((params or {}).radius) or 5000))
  local dbFlag, dbMessage, dbProblem, dbResult = baseLootNativeNearestFlag(info, lookupRadius)
  if dbFlag ~= nil then
    local flag, zoneDetail = baseLootFinalizeCurrentFlag(info, dbFlag, params)
    if flag ~= nil then
      appendLog("base-loot nearest flag native baseId=" .. tostring(flag.baseId) ..
        " distance=" .. tostring(math.floor(tonumber(flag.distance) or 0)) ..
        " lookupRadius=" .. tostring(lookupRadius) ..
        " " .. tostring(zoneDetail or "") ..
        " message=" .. tostring(dbMessage or ""))
      return flag, tonumber(flag.distance) or 0
    end
    appendLog("base-loot nearest flag rejected by exact zone check baseId=" .. tostring(dbFlag.baseId) ..
      " lookupRadius=" .. tostring(lookupRadius) .. " " .. tostring(zoneDetail or ""))
    return nil, zoneDetail
  end
  appendLog("base-loot native nearest flag unavailable message=" .. tostring(dbMessage or "") ..
    " dbProblem=" .. tostring(dbProblem == true) ..
    " result=" .. tostring(dbResult or "{}"):sub(1, 320))
  if baseLootBool({ "AllowRuntimeFlagFallback", "allowRuntimeFlagFallback" }, false) == true then
    appendLog("base-loot ignored AllowRuntimeFlagFallback=true; global flag traversal is disabled for safe overlap collection")
  end
  return nil
end

function baseLootCurrentFlagAsync(info, params, onResult)
  local px, py = baseLootCurrentPosition(info)
  if px == 0 and py == 0 then
    if type(onResult) == "function" then onResult(nil, "player coordinates missing", false, "{}") end
    return false
  end
  local lookupRadius = math.max(500, math.floor(tonumber((params or {}).flagLookupRadiusCm) or tonumber((params or {}).radius) or 5000))
  local queued, queueMessage = baseLootNativeNearestFlagAsync(info, lookupRadius, function(dbFlag, dbMessage, dbProblem, dbResult)
    if dbFlag ~= nil then
      local flag, zoneDetail = baseLootFinalizeCurrentFlag(info, dbFlag, params)
      if flag ~= nil then
        appendLog("base-loot nearest flag native async baseId=" .. tostring(flag.baseId) ..
          " distance=" .. tostring(math.floor(tonumber(flag.distance) or 0)) ..
          " lookupRadius=" .. tostring(lookupRadius) ..
          " " .. tostring(zoneDetail or "") ..
          " message=" .. tostring(dbMessage or ""))
        if type(onResult) == "function" then onResult(flag, dbMessage, false, dbResult) end
        return
      end
      appendLog("base-loot nearest flag async rejected by exact zone check baseId=" .. tostring(dbFlag.baseId) ..
        " lookupRadius=" .. tostring(lookupRadius) .. " " .. tostring(zoneDetail or ""))
      if type(onResult) == "function" then onResult(nil, zoneDetail, false, dbResult) end
      return
    end
    appendLog("base-loot native nearest flag async unavailable message=" .. tostring(dbMessage or "") ..
      " dbProblem=" .. tostring(dbProblem == true) ..
      " result=" .. tostring(dbResult or "{}"):sub(1, 320))
    if baseLootBool({ "AllowRuntimeFlagFallback", "allowRuntimeFlagFallback" }, false) == true then
      appendLog("base-loot ignored AllowRuntimeFlagFallback=true; global flag traversal is disabled for safe overlap collection")
    end
    if type(onResult) == "function" then onResult(nil, dbMessage, dbProblem == true, dbResult) end
  end)
  return queued == true
end

function baseLootAccessForFlag(info, flag)
  if baseLootBool({ "RequireSquadOwnedFlag", "requireSquadOwnedFlag" }, true) == false then return true end
  if baseLootBool({ "AllowAdminsBypass", "allowAdminsBypass" }, false) == true and hasPermission(info, "*") then return true end
  local baseId = tonumber((flag or {}).baseId)
  if baseId == nil then
    appendLog("base-loot access denied before DB check: flag id missing")
    return false, "flag id missing"
  end
  local nativeOk, nativeMessage, nativeDbProblem = baseLootNativeAccess(info, flag)
  if nativeOk then return true end
  if baseLootBool({ "AllowSqliteExeFallback", "allowSqliteExeFallback" }, false) ~= true then
    return false, nativeMessage, nativeDbProblem
  end
  local profileId, profileMessage = baseLootProfileId(info)
  if profileId == nil then return false, tostring(profileMessage or "profile id missing"), true end
  local ownerExpr = "coalesce(" ..
    "nullif(b.owner_user_profile_id,-1)," ..
    "nullif(b.user_profile_id,-1)," ..
    "(select e.owner_profile_id from base_element_flag f join base_element e on e.element_id=f.element_id where e.base_id=b.id and e.owner_profile_id is not null and e.owner_profile_id > 0 limit 1)," ..
    "(select e2.owner_profile_id from base_element e2 where e2.base_id=b.id and e2.owner_profile_id is not null and e2.owner_profile_id > 0 order by e2.element_id limit 1))"
  local ownerSql = "select " .. ownerExpr .. " from base b where b.id=" .. tostring(math.floor(baseId)) .. " limit 1;"
  local okOwner, ownerOutput = baseLootSql(ownerSql)
  if not okOwner then return false, ownerOutput, true end
  local ownerProfile = tostring(ownerOutput or ""):match("[^\r\n|]+") or ""
  if ownerProfile == "" then return false, "base owner not found" end
  ownerProfile = tostring(ownerProfile or "")
  local ownerSquadSql = "select squad_id from squad_member where user_profile_id=" .. tostring(tonumber(ownerProfile) or 0) .. " limit 1;"
  local playerSquadSql = "select squad_id from squad_member where user_profile_id=" .. tostring(profileId) .. " limit 1;"
  local okOwnerSquad, ownerSquadOutput = baseLootSql(ownerSquadSql)
  if not okOwnerSquad then return false, ownerSquadOutput, true end
  local okPlayerSquad, playerSquadOutput = baseLootSql(playerSquadSql)
  if not okPlayerSquad then return false, playerSquadOutput, true end
  local ownerSquad = tostring(ownerSquadOutput or ""):match("[^\r\n|]+") or ""
  local playerSquad = tostring(playerSquadOutput or ""):match("[^\r\n|]+") or ""
  ownerSquad = tostring(ownerSquad or "")
  playerSquad = tostring(playerSquad or "")
  if ownerProfile ~= "" and tonumber(ownerProfile) == tonumber(profileId) and baseLootBool({ "AllowFlagOwnerWithoutSquad", "allowFlagOwnerWithoutSquad" }, true) ~= false then
    return true
  end
  if ownerSquad ~= "" and playerSquad ~= "" and ownerSquad == playerSquad then return true end
  return false, "not squad member"
end

function baseLootNativeAccessAsync(info, flag, onResult)
  local baseId = tonumber((flag or {}).baseId)
  if baseId == nil then
    if type(onResult) == "function" then onResult(false, "flag id missing", false, "{}") end
    return false, "flag id missing"
  end
  local profile = tostring((info or {}).userProfileId or (info or {}).serverUserProfileId or (info or {}).profileId or "")
  local profileId = tonumber(profile) or 0
  local steam = tostring((info or {}).steam or (info or {}).steamId or "")
  local payload = '{"baseId":' .. tostring(math.floor(baseId)) ..
    ',"profileId":' .. tostring(math.floor(profileId)) ..
    ',"steamId":' .. js(steam) ..
    ',"allowFlagOwnerWithoutSquad":' .. (baseLootBool({ "AllowFlagOwnerWithoutSquad", "allowFlagOwnerWithoutSquad" }, true) ~= false and "true" or "false") ..
    '}'
  appendLog("base-loot native access async request baseId=" .. tostring(math.floor(baseId)) ..
    " profileId=" .. tostring(math.floor(profileId)) ..
    " steam=" .. tostring(steam ~= "" and "set" or "missing"))
  local queued, queueMessage = nativeHttpCommandAsync(
    "base_loot_access",
    "base_loot_access",
    payload,
    math.max(300, math.min(math.floor(baseLootNumber({ "DbCheckTimeoutMs", "dbCheckTimeoutMs" }, 1200) or 1200), 2500)),
    "base-loot-" .. tostring(math.floor(baseId)) .. "-" .. tostring(profileId > 0 and profileId or steam),
    function(okNative, message, result)
      result = tostring(result or "{}")
      if not okNative then
        if type(onResult) == "function" then onResult(false, tostring(message or "native SQLite access check failed"), true, result) end
        return
      end
      local allowed = extractBool(result, "allowed", false) == true
      if allowed then
        if type(onResult) == "function" then onResult(true, tostring(message or "base loot access allowed"), false, result) end
        return
      end
      local reason = extractString(result, "reason") or tostring(message or "base loot access denied")
      local dbProblem = reason == "db_error" or extractBool(result, "dbAvailable", true) == false
      if type(onResult) == "function" then onResult(false, tostring(message or reason), dbProblem, result) end
    end)
  if not queued then
    if type(onResult) == "function" then onResult(false, tostring(queueMessage or "native HTTP bridge queue failed"), true, "{}") end
    return false, tostring(queueMessage or "native HTTP bridge queue failed")
  end
  return true
end

function baseLootAccessForFlagAsync(info, flag, onResult)
  if baseLootBool({ "RequireSquadOwnedFlag", "requireSquadOwnedFlag" }, true) == false then
    if type(onResult) == "function" then onResult(true, "squad ownership check disabled", false, "{}") end
    return true
  end
  if baseLootBool({ "AllowAdminsBypass", "allowAdminsBypass" }, false) == true and hasPermission(info, "*") then
    if type(onResult) == "function" then onResult(true, "admin bypass", false, "{}") end
    return true
  end
  local baseId = tonumber((flag or {}).baseId)
  if baseId == nil then
    appendLog("base-loot async access denied before DB check: flag id missing")
    if type(onResult) == "function" then onResult(false, "flag id missing", false, "{}") end
    return false
  end
  return baseLootNativeAccessAsync(info, flag, function(nativeOk, nativeMessage, nativeDbProblem, nativeResult)
    if nativeOk then
      if type(onResult) == "function" then onResult(true, nativeMessage, false, nativeResult) end
      return
    end
    if baseLootBool({ "AllowSqliteExeFallback", "allowSqliteExeFallback" }, false) == true then
      -- io.popen is intentionally not allowed in an asynchronous player-command route.
      local message = "legacy sqlite3.exe fallback disabled for безопасный /loot; native SQLite bridge required"
      appendLog("base-loot async legacy SQLite fallback blocked baseId=" .. tostring(math.floor(baseId)))
      if type(onResult) == "function" then onResult(false, message, true, nativeResult) end
      return
    end
    if type(onResult) == "function" then onResult(false, nativeMessage, nativeDbProblem == true, nativeResult) end
  end)
end

function baseLootCleanNameText(text)
  local value = tostring(text or "")
  value = value:gsub("^%s+", ""):gsub("%s+$", "")
  value = value:gsub("^FString%s*:%s*", "")
  value = value:gsub("^FName%s*:%s*", "")
  value = value:gsub("^FText%s*:%s*", "")
  value = value:gsub("^Text%s*:%s*", "")
  value = value:gsub("^%s+", ""):gsub("%s+$", "")
  if value:sub(1, 1) == '"' and value:sub(-1) == '"' and #value >= 2 then
    value = value:sub(2, -2)
  end
  value = value:gsub("^%s+", ""):gsub("%s+$", "")
  local lower = value:lower()
  if value == "" or lower == "nil" then return "" end
  if lower:match("^userdata:") or lower:match("^table:") or lower:match("^function:") or lower:match("^uobject%s*:") then
    return ""
  end
  return value
end

function baseLootValueString(value)
  if value == nil then return "" end
  if type(value) == "string" or type(value) == "number" then return baseLootCleanNameText(value) end
  local attempts = {
    function()
      if (type(value) == "userdata" or type(value) == "table") and value.ToString ~= nil then
        return value:ToString()
      end
      return nil
    end,
    function()
      if (type(value) == "userdata" or type(value) == "table") and value.toString ~= nil then
        return value:toString()
      end
      return nil
    end,
    function() return tostring(value) end
  }
  for _, attempt in ipairs(attempts) do
    local okToString, text = pcall(attempt)
    if okToString then
      local cleaned = baseLootCleanNameText(text)
      if cleaned ~= "" then return cleaned end
    end
  end
  return ""
end

function baseLootReadPropertyText(obj, keys)
  if obj == nil then return "", "" end
  if type(objectGetAny) == "function" then
    local raw, key, route = objectGetAny(obj, keys or {})
    local text = baseLootValueString(raw)
    if text ~= "" then return text, tostring(key or "") .. ":" .. tostring(route or "") end
  end
  for _, key in ipairs(keys or {}) do
    local raw = safeGet(obj, key)
    local text = baseLootValueString(raw)
    if text ~= "" then return text, tostring(key or "") .. ":index" end
  end
  return "", ""
end

function baseLootReadObjectProperty(obj, keys)
  if obj == nil then return nil, "", "" end
  if type(objectGetAny) == "function" then
    local raw, key, route = objectGetAny(obj, keys or {})
    if raw ~= nil then return raw, tostring(key or ""), tostring(route or "") end
  end
  for _, key in ipairs(keys or {}) do
    local raw = safeGet(obj, key)
    if raw ~= nil then return raw, tostring(key or ""), "index" end
  end
  return nil, "", ""
end

function baseLootNameTextFromObject(obj)
  return baseLootReadPropertyText(obj, {
    "_name", "Name", "name", "_Name",
    "DisplayName", "displayName", "_displayName",
    "Value", "value", "Text", "text"
  })
end

function baseLootNameableComponent(actor)
  local componentKeys = { "_nameableItemComponent", "NameableItemComponent", "nameableItemComponent", "_NameableItemComponent" }
  local comp, key, route = baseLootReadObjectProperty(actor, componentKeys)
  if comp ~= nil and isValidObject(comp) then return comp, key, route end
  if type(baseLootComponentByClass) == "function" then
    comp = baseLootComponentByClass(actor, "/Script/SCUM.NameableItemComponent")
    if comp ~= nil and isValidObject(comp) then return comp, "NameableItemComponent", "GetComponentByClass" end
  end
  return nil, key or "", route or ""
end

function baseLootNameableName(actor)
  if actor == nil then return "" end
  local value, valueRoute = "", ""
  local comp, compKey, compRoute = baseLootNameableComponent(actor)
  if comp ~= nil and isValidObject(comp) then
    value, valueRoute = baseLootReadPropertyText(comp, { "_name", "Name", "name" })
    if value == "" then
      local data = baseLootReadObjectProperty(comp, { "_nameData", "NameData", "nameData" })
      value, valueRoute = baseLootNameTextFromObject(data)
    end
    if value == "" then
      local state = baseLootReadObjectProperty(comp, { "_state", "State", "state", "_componentState", "ComponentState", "componentState" })
      value, valueRoute = baseLootNameTextFromObject(state)
    end
    if value == "" then value, valueRoute = baseLootNameTextFromObject(comp) end
  end
  if value ~= "" and value ~= "nil" then return value end
  value, valueRoute = baseLootNameTextFromObject(actor)
  if value ~= "" and value ~= "nil" then return value end
  local classText = (objectClassFullName(actor) .. " " .. objectFullName(actor)):lower()
  if classText:find("chest", 1, true) ~= nil then
    appendLog("base-loot nameable fallback actor=" .. tostring(objectFullName(actor)) ..
      " compKey=" .. tostring(compKey or "") ..
      " compRoute=" .. tostring(compRoute or "") ..
      " valueRoute=" .. tostring(valueRoute or ""))
  end
  pcall(function()
    local n = actor:GetName()
    if n ~= nil then value = baseLootValueString(n) end
  end)
  if value ~= "" and value ~= "nil" then return value end
  local full = objectFullName(actor)
  return full:gsub("^.+[%./:]", "")
end

function baseLootObjectKey(obj)
  if obj == nil then return "" end
  local key = ""
  pcall(function()
    local addr = obj:GetAddress()
    if addr ~= nil and addr ~= 0 then key = tostring(addr) end
  end)
  if key == "" then key = objectFullName(obj) end
  return key
end

function baseLootStartTimer()
  return {
    wall = wallClockSeconds(),
    cpu = tonumber(os.clock()) or 0
  }
end

function baseLootElapsedMs(started)
  if type(started) == "table" then
    local wallStarted = tonumber(started.wall) or wallClockSeconds()
    local cpuStarted = tonumber(started.cpu) or (tonumber(os.clock()) or 0)
    local wallMs = math.floor(((wallClockSeconds() - wallStarted) * 1000) + 0.5)
    local cpuMs = math.floor((((tonumber(os.clock()) or cpuStarted) - cpuStarted) * 1000) + 0.5)
    return math.max(0, wallMs, cpuMs)
  end
  return math.floor((((tonumber(os.clock()) or 0) - (tonumber(started) or (tonumber(os.clock()) or 0))) * 1000) + 0.5)
end

function baseLootBudgetExceeded(started, budgetMs)
  local budget = tonumber(budgetMs) or 0
  return budget > 0 and baseLootElapsedMs(started) >= budget
end

function baseLootMarkLimited(params, key)
  if type(params) ~= "table" then return end
  params._limited = true
  if key ~= nil and key ~= "" then params[key] = true end
end

function baseLootLimitedSuffix(params)
  if type(params) ~= "table" or params._limited ~= true then return "" end
  return " Обработана безопасная часть, повтори через " .. tostring(tonumber(params.limitedCooldownSeconds) or 10) .. " сек."
end

function baseLootFindAllExact(names, maxObjects, label, maxWorkMs)
  local out = {}
  local seen = {}
  local limit = math.max(1, math.floor(tonumber(maxObjects) or 256))
  local totalRaw = 0
  local totalMs = 0
  local failed = {}
  local overallStarted = baseLootStartTimer()
  local budgetMs = math.max(0, math.floor(tonumber(maxWorkMs) or 0))
  for _, name in ipairs(names or {}) do
    local clean = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if clean ~= "" then
      local started = baseLootStartTimer()
      local okFind, arr = pcall(function() return FindAllOf(clean) end)
      local elapsedMs = baseLootElapsedMs(started)
      totalMs = totalMs + elapsedMs
      local rawCount = 0
      if okFind and arr ~= nil then
        for _, obj in pairs(arr) do
          rawCount = rawCount + 1
          if obj ~= nil and isValidObject(obj) then
            local key = baseLootObjectKey(obj)
            if key ~= "" and not seen[key] then
              seen[key] = true
              table.insert(out, obj)
              if #out >= limit then
                if elapsedMs > 50 or totalMs > 150 then
                  appendLog("base-loot scoped FindAllOf label=" .. tostring(label or "") ..
                    " class=" .. clean .. " raw=" .. tostring(rawCount) ..
                    " added=" .. tostring(#out) .. " ms=" .. tostring(elapsedMs) ..
                    " totalMs=" .. tostring(totalMs) .. " limited=true")
                end
                return out
              end
            end
          end
          if budgetMs > 0 and rawCount % 32 == 0 and baseLootBudgetExceeded(overallStarted, budgetMs) then
            appendLog("base-loot scoped FindAllOf label=" .. tostring(label or "") ..
              " class=" .. clean .. " raw=" .. tostring(rawCount) ..
              " added=" .. tostring(#out) ..
              " totalMs=" .. tostring(baseLootElapsedMs(overallStarted)) ..
              " budgetMs=" .. tostring(budgetMs) .. " limited=true")
            return out
          end
        end
      elseif not okFind then
        table.insert(failed, clean .. ":" .. tostring(arr or "error"))
      end
      totalRaw = totalRaw + rawCount
      if elapsedMs > 50 then
        appendLog("base-loot scoped FindAllOf label=" .. tostring(label or "") ..
          " class=" .. clean .. " raw=" .. tostring(rawCount) ..
          " added=" .. tostring(#out) .. " ms=" .. tostring(elapsedMs))
      end
      if budgetMs > 0 and baseLootBudgetExceeded(overallStarted, budgetMs) then
        appendLog("base-loot scoped FindAllOf label=" .. tostring(label or "") ..
          " classes stopped after=" .. clean ..
          " totalMs=" .. tostring(baseLootElapsedMs(overallStarted)) ..
          " budgetMs=" .. tostring(budgetMs) .. " limited=true")
        break
      end
    end
  end
  if #out == 0 or #failed > 0 then
    appendLog("base-loot scoped FindAllOf summary label=" .. tostring(label or "") ..
      " classes=" .. table.concat(names or {}, ",") ..
      " raw=" .. tostring(totalRaw) ..
      " added=" .. tostring(#out) ..
      " totalMs=" .. tostring(totalMs) ..
      " failed=" .. table.concat(failed, " || "))
  end
  return out
end

function baseLootChestBlockedReason(actor)
  if actor == nil or not isValidObject(actor) then return "invalid" end
  local haystack = (baseLootClassName(actor) .. " " .. objectClassFullName(actor) .. " " .. objectFullName(actor)):lower()
  for _, blocked in ipairs({ "vehicle", "prisoner", "baseflag", "conzbase", "tool_box", "toolbox" }) do
    if haystack:find(blocked, 1, true) ~= nil then return "blocked-" .. blocked end
  end
  return ""
end

function baseLootChestInventoryForActor(actor)
  if actor == nil or not isValidObject(actor) then return nil end
  local inv = firstProp(actor, {
    "_inventory", "Inventory", "inventory", "_Inventory",
    "ChestInventory", "chestInventory",
    "_inventoryComponent", "InventoryComponent", "inventoryComponent",
    "_gridInventoryComponent", "GridInventoryComponent", "gridInventoryComponent",
    "_itemInventory", "ItemInventory", "itemInventory"
  })
  if inv ~= nil and isValidObject(inv) then return inv end
  inv = baseLootComponentByClass(actor, "/Script/SCUM.ChestInventoryComponent")
  if inv ~= nil and isValidObject(inv) then return inv end
  inv = baseLootComponentByClass(actor, "/Script/SCUM.GridInventoryComponent")
  if inv ~= nil and isValidObject(inv) then return inv end
  inv = baseLootComponentByClass(actor, "/Script/SCUM.InventoryComponent")
  if inv ~= nil and isValidObject(inv) then return inv end
  return nil
end

function baseLootActorLooksLikeConfiguredChest(actor, params)
  if actor == nil or not isValidObject(actor) then return false end
  if baseLootChestBlockedReason(actor) ~= "" then return false end
  local haystack = (baseLootClassName(actor) .. " " .. objectClassFullName(actor) .. " " .. objectFullName(actor)):lower()
  local name = baseLootNameableName(actor):lower()
  local defaultChest = tostring((params or {}).defaultChest or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
  if defaultChest ~= "" then
    if name == defaultChest then return true end
    if (params or {}).nameContains ~= false and name:find(defaultChest, 1, true) ~= nil then return true end
  end
  for _, token in ipairs((params or {}).chestClassTokens or {}) do
    local lower = tostring(token or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
    if lower ~= "" then
      if haystack:find(lower, 1, true) ~= nil then return true end
      local noSuffix = lower:gsub("_c$", "")
      if noSuffix ~= "" and haystack:find(noSuffix, 1, true) ~= nil then return true end
    end
  end
  return false
end

function baseLootAddChestCandidate(out, seen, inv, owner, flag, params, source)
  if inv == nil or not isValidObject(inv) then return false, "inventory-missing" end
  if owner == nil or not isValidObject(owner) then return false, "owner-missing" end
  local blockedReason = baseLootChestBlockedReason(owner)
  if blockedReason ~= "" then return false, blockedReason end
  local key = baseLootObjectKey(owner)
  if key == "" then return false, "key-missing" end
  if seen[key] then return false, "duplicate" end
  seen[key] = true
  local x, y, z = vectorOf(owner)
  if (x == 0 and y == 0) then
    local ix, iy, iz = vectorOf(inv)
    if ix ~= 0 or iy ~= 0 then
      x, y, z = ix, iy, iz
    end
  end
  if x == 0 and y == 0 then return false, "zero-location" end
  local insideCollection, areaDetail = baseLootPointInCollectionArea(x, y, flag, params)
  if not insideCollection then return false, "outside-collection-area:" .. tostring(areaDetail or "") end
  local nameableComponent = nil
  pcall(function() nameableComponent = baseLootNameableComponent(owner) end)
  local chestAddress = baseLootObjectKey(owner)
  local componentAddress = nameableComponent ~= nil and baseLootObjectKey(nameableComponent) or ""
  table.insert(out, {
    inv = inv,
    actor = owner,
    owner = owner,
    name = baseLootNameableName(owner),
    x = x,
    y = y,
    z = z,
    source = tostring(source or "unknown"),
    chestFullName = objectFullName(owner),
    chestClass = objectClassFullName(owner),
    chestAddress = chestAddress,
    componentFullName = nameableComponent ~= nil and objectFullName(nameableComponent) or "",
    componentClass = nameableComponent ~= nil and objectClassFullName(nameableComponent) or "",
    componentAddress = componentAddress
  })
  return true, "ok"
end

function baseLootFirstReflectedPropertyProbe(chest, timeoutMs)
  if chest == nil then return false, "missing chest", "{}" end
  local payload = '{"chestFullName":' .. js(tostring(chest.chestFullName or "")) ..
    ',"chestClass":' .. js(tostring(chest.chestClass or "")) ..
    ',"chestAddress":' .. js(tostring(chest.chestAddress or "")) ..
    ',"componentFullName":' .. js(tostring(chest.componentFullName or "")) ..
    ',"componentClass":' .. js(tostring(chest.componentClass or "")) ..
    ',"componentAddress":' .. js(tostring(chest.componentAddress or "")) .. '}'
  return nativeTraderCommandInline(
    "base_loot_first_reflected_property_probe",
    payload,
    math.max(400, math.min(math.floor(tonumber(timeoutMs) or 1200), 3000)),
    "base-loot-first-reflected-property-probe")
end

function baseLootOverlapObjectTypes(params)
  local out, seen = {}, {}
  for _, token in ipairs((params or {}).sphereOverlapObjectTypes or {}) do
    local trimmed = tostring(token or ""):gsub("^%s+", ""):gsub("%s+$", "")
    local value = tonumber(trimmed)
    if value ~= nil then
      value = math.floor(value)
      if value >= 0 and value <= 31 and not seen[value] then
        seen[value] = true
        table.insert(out, value)
      end
    end
  end
  if #out == 0 then return nil, "SphereOverlapObjectTypes is empty" end
  return out, nil
end

function baseLootOverlapWorld(live)
  local world = nil
  local okPawn, pawnWorld = safeCall((live or {}).pawn, "GetWorld")
  if okPawn and pawnWorld ~= nil and isValidObject(pawnWorld) then world = pawnWorld end
  if world == nil then
    local okPc, pcWorld = safeCall((live or {}).pc, "GetWorld")
    if okPc and pcWorld ~= nil and isValidObject(pcWorld) then world = pcWorld end
  end
  return world
end

-- The normal /loot path has exactly one actor lookup: a bounded sphere around
-- the already-authorized native-DB flag. It never falls back to FindAllOf.
function baseLootOverlapItemActors(live, flag, params)
  if (params or {}).sphereOverlapEnabled ~= true then
    return { ok = false, error = "SphereOverlap scan disabled", actors = {} }
  end
  if flag == nil or tonumber(flag.x) == nil or tonumber(flag.y) == nil then
    return { ok = false, error = "flag location missing", actors = {} }
  end
  local objectTypes, typeError = baseLootOverlapObjectTypes(params)
  if objectTypes == nil then return { ok = false, error = typeError, actors = {} } end
  local world = baseLootOverlapWorld(live)
  if world == nil or not isValidObject(world) then
    return { ok = false, error = "live pawn world unavailable", actors = {} }
  end
  local kismet, itemClass = nil, nil
  pcall(function() kismet = StaticFindObject("/Script/Engine.Default__KismetSystemLibrary") end)
  pcall(function() itemClass = StaticFindObject("/Script/SCUM.Item") end)
  if kismet == nil or not isValidObject(kismet) then
    return { ok = false, error = "KismetSystemLibrary unavailable", actors = {} }
  end
  if itemClass == nil or not isValidObject(itemClass) then
    return { ok = false, error = "SCUM Item class unavailable", actors = {} }
  end
  local flagZ = tonumber(flag.z) or 0
  local _, _, pawnZ = vectorOf((live or {}).pawn)
  local centerZ = pawnZ
  if centerZ == 0 then centerZ = flagZ end
  local center = { X = tonumber(flag.x) or 0, Y = tonumber(flag.y) or 0, Z = centerZ }
  local radius = math.max(500, math.min(math.floor(tonumber((params or {}).overlapRadiusCm) or tonumber((params or {}).radius) or 0), 30000))
  local maxActors = math.max(64, math.min(math.floor(tonumber((params or {}).sphereOverlapMaxActors) or 256), 1000))
  local outActors = {}
  local started = baseLootStartTimer()
  local call = { pcall(function()
    return kismet:SphereOverlapActors(world, center, radius, objectTypes, itemClass, {}, outActors)
  end) }
  local elapsedMs = baseLootElapsedMs(started)
  if call[1] ~= true then
    appendLog("base-loot overlap failed ms=" .. tostring(elapsedMs) .. " error=" .. tostring(call[2] or "unknown"))
    return { ok = false, error = "SphereOverlapActors call failed", actors = {}, elapsedMs = elapsedMs }
  end
  local actors, seen = {}, {}
  local rawCount = 0
  local limited = false
  local carriers = {}
  local function unwrapOverlapValue(value)
    local candidate = runtimeCollectionUnwrap(value)
    if type(candidate) == "table" and candidate.__runtimeMapEntry == true then
      candidate = runtimeCollectionUnwrap(candidate.value)
    end
    return candidate
  end
  local function addActor(value)
    local actor = unwrapOverlapValue(value)
    if actor == nil or not isValidObject(actor) then return false end
    local key = baseLootObjectKey(actor)
    if key == "" or seen[key] then return false end
    seen[key] = true
    table.insert(actors, actor)
    return true
  end
  local function scanCarrier(carrier, label, allowNested)
    if carrier == nil or #actors >= maxActors then return end
    local count, items, method = runtimeArrayCount(carrier, maxActors)
    local numericCount = tonumber(count) or 0
    if numericCount > 0 then rawCount = rawCount + numericCount end
    if numericCount > #(items or {}) then limited = true end
    local added, nested = 0, ""
    for _, entry in ipairs(items or {}) do
      if #actors >= maxActors then limited = true; break end
      if addActor(entry) then
        added = added + 1
      elseif allowNested then
        local child = unwrapOverlapValue(entry)
        if child ~= nil and (type(child) == "table" or type(child) == "userdata") then
          local childCount, childItems, childMethod = runtimeArrayCount(child, math.max(1, maxActors - #actors))
          local childNumericCount = tonumber(childCount) or 0
          if childNumericCount > 0 then rawCount = rawCount + childNumericCount end
          if childNumericCount > #(childItems or {}) then limited = true end
          local childAdded = 0
          for _, childEntry in ipairs(childItems or {}) do
            if #actors >= maxActors then limited = true; break end
            if addActor(childEntry) then childAdded = childAdded + 1 end
          end
          nested = tostring(childMethod or "") .. ":" .. tostring(childNumericCount) .. ":" .. tostring(childAdded)
        end
      end
    end
    table.insert(carriers, tostring(label or "") .. ":" .. tostring(method or "") .. ":" .. tostring(numericCount) .. ":" .. tostring(added) .. ":" .. nested)
  end
  scanCarrier(outActors, "out", true)
  for index = 2, #call do
    local carrier = call[index]
    local carrierType = type(carrier)
    if carrierType == "table" or carrierType == "userdata" then
      scanCarrier(carrier, "ret" .. tostring(index), true)
    end
  end
  elapsedMs = baseLootElapsedMs(started)
  if elapsedMs >= math.max(1, tonumber((params or {}).sphereOverlapWorkBudgetMs) or 120) then limited = true end
  if limited then baseLootMarkLimited(params, "_overlapLimited") end
  appendLog("base-loot overlap result raw=" .. tostring(rawCount) ..
    " actors=" .. tostring(#actors) ..
    " radius=" .. tostring(radius) ..
    " centerZ=" .. tostring(centerZ) ..
    " flagZ=" .. tostring(flagZ) ..
    " pawnZ=" .. tostring(pawnZ) ..
    " ms=" .. tostring(elapsedMs) ..
    " limited=" .. tostring(limited) ..
    " carriers=" .. table.concat(carriers, "|") ..
    " objectTypes=" .. table.concat(objectTypes, ","))
  return { ok = true, actors = actors, rawCount = rawCount, elapsedMs = elapsedMs, limited = limited, radius = radius }
end

function baseLootChests(flag, params, overlap)
  local out, seen, scanned = {}, {}, 0
  local started = baseLootStartTimer()
  local reject = {}
  local samples = {}
  local function remember(reason, obj)
    local key = tostring(reason or "rejected")
    reject[key] = (reject[key] or 0) + 1
    if obj ~= nil and #samples < 8 then
      table.insert(samples, tostring(key) .. ":" .. baseLootClassName(obj) .. ":" .. objectFullName(obj))
    end
  end
  if overlap == nil or overlap.ok ~= true then
    remember("overlap-unavailable:" .. tostring((overlap or {}).error or "unknown"), nil)
  else
    for _, obj in ipairs(overlap.actors or {}) do
      scanned = scanned + 1
      if baseLootActorLooksLikeConfiguredChest(obj, params) then
        local inv = baseLootChestInventoryForActor(obj)
        local added, reason = baseLootAddChestCandidate(out, seen, inv, obj, flag, params, "sphere-overlap.Item")
        if not added then remember(reason, obj or inv) end
      else
        remember("not-configured-chest", obj)
      end
      if #out >= (tonumber(params.maxChests) or 1) then break end
      if scanned % 16 == 0 and baseLootBudgetExceeded(started, params.chestScanWorkBudgetMs) then
        baseLootMarkLimited(params, "_chestScanLimited")
        appendLog("base-loot chest overlap budget hit scanned=" .. tostring(scanned) ..
          " found=" .. tostring(#out) ..
          " ms=" .. tostring(baseLootElapsedMs(started)) ..
          " budgetMs=" .. tostring(params.chestScanWorkBudgetMs or 0))
        break
      end
    end
  end
  if type(params) == "table" then params._chestScanMs = baseLootElapsedMs(started) end
  if #out == 0 then
    local parts = {}
    for key, value in pairs(reject) do table.insert(parts, tostring(key) .. "=" .. tostring(value)) end
    table.sort(parts)
    appendLog("base-loot chest overlap produced no candidates scanned=" .. tostring(scanned) ..
      " rejects=" .. table.concat(parts, ",") ..
      " limited=" .. tostring((params or {})._chestScanLimited == true or (params or {})._overlapLimited == true) ..
      " ms=" .. tostring((params or {})._chestScanMs or 0) ..
      " samples=" .. table.concat(samples, " || "))
  end
  return out, scanned
end

function baseLootTokens(text)
  local out = {}
  for _, token in ipairs(baseLootSplitTokens(text)) do table.insert(out, token:lower()) end
  return out
end

BASE_LOOT_ACTIVE = BASE_LOOT_ACTIVE or {}

function baseLootActiveBusy(activeKey, params)
  local key = tostring(activeKey or "global")
  local value = BASE_LOOT_ACTIVE[key]
  if value == nil then return false end
  local timeout = math.max(5, tonumber((params or {}).activeTimeoutSeconds) or 25)
  local started = tonumber(value)
  if started ~= nil and started > 0 and (os.time() - started) > timeout then
    BASE_LOOT_ACTIVE[key] = nil
    appendLog("base-loot active lock expired key=" .. key .. " ageSeconds=" .. tostring(os.time() - started))
    return false
  end
  return true
end

function baseLootMarkActive(activeKey)
  BASE_LOOT_ACTIVE[tostring(activeKey or "global")] = os.time()
end

function baseLootClearActive(activeKey)
  BASE_LOOT_ACTIVE[tostring(activeKey or "global")] = nil
end

function baseLootDistanceToChest(item, chest)
  if item == nil or chest == nil then return nil end
  local ix = tonumber(item.x)
  local iy = tonumber(item.y)
  local cx = tonumber(chest.x)
  local cy = tonumber(chest.y)
  if ix == nil or iy == nil or cx == nil or cy == nil then return nil end
  return distance2d(ix, iy, cx, cy)
end

function baseLootChestOwner(chest)
  if chest == nil then return nil end
  if chest.owner ~= nil and isValidObject(chest.owner) then return chest.owner end
  if chest.actor ~= nil and isValidObject(chest.actor) then return chest.actor end
  return nil
end

function baseLootPickNearestChest(matches, item)
  if matches == nil or #matches == 0 then return nil end
  if item == nil then return matches[1] end
  local best, bestDistance = nil, nil
  for _, chest in ipairs(matches) do
    local d = baseLootDistanceToChest(item, chest)
    if d ~= nil and (bestDistance == nil or d < bestDistance) then
      best = chest
      bestDistance = d
    end
  end
  return best or matches[1]
end

function baseLootChestForName(chests, wanted, contains, item)
  local target = tostring(wanted or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
  if target == "" and #chests > 0 then return baseLootPickNearestChest(chests, item) end
  local exact = {}
  for _, chest in ipairs(chests or {}) do
    if tostring(chest.name or ""):lower() == target then table.insert(exact, chest) end
  end
  if #exact > 0 then return baseLootPickNearestChest(exact, item) end
  if contains then
    local partial = {}
    for _, chest in ipairs(chests or {}) do
      if tostring(chest.name or ""):lower():find(target, 1, true) ~= nil then table.insert(partial, chest) end
    end
    if #partial > 0 then return baseLootPickNearestChest(partial, item) end
  end
  return nil
end

function baseLootRuleChestName(haystack, params)
  local lower = tostring(haystack or ""):lower()
  for _, rule in ipairs(moduleArrayObjects("base-loot-collector", "Rules")) do
    if extractBoolAny(rule, { "Enabled", "enabled" }, true) ~= false then
      local chest = extractStringAny(rule, { "ChestName", "chestName", "TargetChest", "targetChest" }) or ""
      local tokens = baseLootTokens(extractStringAny(rule, { "MatchContains", "matchContains", "Contains", "contains" }) or "")
      for _, token in ipairs(tokens) do
        if lower:find(token, 1, true) ~= nil then return chest ~= "" and chest or params.defaultChest end
      end
    end
  end
  return params.defaultChest
end

function baseLootClassName(obj)
  if obj == nil then return "" end
  local okName, name = pcall(function() return obj:GetClass():GetFName():ToString() end)
  if okName and type(name) == "string" then return name end
  local okClass, cls = pcall(function() return obj:GetClass() end)
  if okClass and cls ~= nil then
    local okFull, full = pcall(function() return cls:GetFullName() end)
    if okFull and type(full) == "string" then return full end
  end
  return objectClassFullName(obj)
end

function baseLootPresence(item)
  if item == nil or not isValidObject(item) then return nil end
  local presence = nil
  pcall(function()
    presence = item._serverPresence or item.ServerPresence or item.serverPresence or item._itemPresence or item.ItemPresence or item.itemPresence
  end)
  if presence ~= nil and isValidObject(presence) then return presence end
  return nil
end

function baseLootPresenceClassText(item)
  local presence = baseLootPresence(item)
  if presence == nil then return "" end
  return (baseLootClassName(presence) .. " " .. objectClassFullName(presence) .. " " .. objectFullName(presence)):lower()
end

function baseLootItemBlockedReason(item, params)
  if item == nil or not isValidObject(item) then return "invalid" end
  local haystack = (baseLootClassName(item) .. " " ..
    objectClassFullName(item) .. " " ..
    baseLootNameableName(item)):lower()
  for _, token in ipairs((params or {}).itemBlockedTokens or {}) do
    local blocked = tostring(token or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
    if blocked ~= "" and haystack:find(blocked, 1, true) ~= nil then
      return "blocked-" .. blocked:gsub("[^%w_%-]+", "_")
    end
  end
  return ""
end

function baseLootVectorFields(vec)
  if vec == nil then return nil, nil, nil end
  local x, y, z = nil, nil, nil
  pcall(function()
    x = tonumber(vec.X or vec.x)
    y = tonumber(vec.Y or vec.y or 0) or 0
    z = tonumber(vec.Z or vec.z or 0) or 0
  end)
  if x == nil then return nil, nil, nil end
  return x, y, z
end

function baseLootPresenceLocation(item)
  local presence = baseLootPresence(item)
  if presence == nil then return nil, nil, nil end
  local data, location = nil, nil
  pcall(function() data = presence.Data or presence.data end)
  pcall(function()
    if data ~= nil then location = data.Location or data.location end
  end)
  return baseLootVectorFields(location)
end

function baseLootLooseLocation(item)
  local ax, ay, az = vectorOf(item)
  local px, py, pz = baseLootPresenceLocation(item)
  if ax ~= nil and ay ~= nil and ((ax * ax + ay * ay) > 1.0) then return ax, ay, az or 0, "actor" end
  if px ~= nil and py ~= nil and ((px * px + py * py) > 1.0) then return px, py, pz or 0, "presence" end
  return ax or px or 0, ay or py or 0, az or pz or 0, "weak"
end

function baseLootItemLooksLoose(item, params)
  if item == nil or not isValidObject(item) then return false, "invalid" end
  local blockedReason = baseLootItemBlockedReason(item, params)
  if blockedReason ~= "" then return false, blockedReason end
  local ptext = baseLootPresenceClassText(item)
  if params.requireOnFloor then
    if ptext == "" then return false, "presence-missing" end
    if ptext:find("onthefloor", 1, true) == nil and ptext:find("on_the_floor", 1, true) == nil and ptext:find("floor", 1, true) == nil then return false, "presence-not-floor:" .. ptext end
  elseif ptext ~= "" then
    for _, blockedPresence in ipairs({ "intheinventory", "in_the_inventory", "container", "inventory", "equipped", "hand" }) do
      if ptext:find(blockedPresence, 1, true) ~= nil then return false, "presence-blocked:" .. blockedPresence end
    end
  end
  return true, "ok"
end

function baseLootChestOccupancyIndexes(chests, params)
  if (params or {}).inventoryLocationOccupancyBatch == false then return nil, nil, 0 end
  local byInv, byOwner = {}, {}
  local indexed = 0
  for _, chest in ipairs(chests or {}) do
    if chest ~= nil then
      chest.occupiedLocationValues = chest.occupiedLocationValues or {}
      local invKey = baseLootObjectKey(chest.inv)
      if invKey ~= "" then byInv[invKey] = chest; indexed = indexed + 1 end
      local ownerKey = baseLootObjectKey(baseLootChestOwner(chest))
      if ownerKey ~= "" then byOwner[ownerKey] = chest end
    end
  end
  return byInv, byOwner, indexed
end

function baseLootRecordChestOccupancy(actor, byInv, byOwner)
  if actor == nil or (byInv == nil and byOwner == nil) then return false end
  local inv, owner = baseLootItemInventoryOwner(actor)
  local chest = nil
  if inv ~= nil and isValidObject(inv) and byInv ~= nil then
    chest = byInv[baseLootObjectKey(inv)]
  end
  if chest == nil and owner ~= nil and isValidObject(owner) and byOwner ~= nil then
    chest = byOwner[baseLootObjectKey(owner)]
  end
  if chest == nil then return false end
  chest.occupiedLocationValues = chest.occupiedLocationValues or {}
  local value = baseLootInventoryLocationValue(actor)
  if tonumber(value) ~= nil then
    chest.occupiedLocationValues[math.floor(tonumber(value))] = true
  end
  return true
end

function baseLootScanItems(flag, params, chests, overlap)
  local out, seen, scanned = {}, {}, 0
  local reject = {}
  local samples = {}
  local started = baseLootStartTimer()
  local occupancyMatched = 0
  local byInv, byOwner, indexedChests = baseLootChestOccupancyIndexes(chests, params)
  local maxScan = math.max(10, math.min(math.floor(tonumber((params or {}).sphereOverlapMaxActors or (params or {}).combinedItemScanLimit or (params or {}).maxScannedItems) or 256), 1000))
  if overlap == nil or overlap.ok ~= true then
    reject["overlap-unavailable"] = 1
  else
    for _, item in ipairs(overlap.actors or {}) do
      scanned = scanned + 1
      if scanned > maxScan then
        baseLootMarkLimited(params, "_itemScanLimited")
        break
      end
      if baseLootRecordChestOccupancy(item, byInv, byOwner) then occupancyMatched = occupancyMatched + 1 end
      local looksLoose, reason = baseLootItemLooksLoose(item, params)
      if looksLoose then
        local key = baseLootObjectKey(item)
        if key ~= "" and not seen[key] then
          seen[key] = true
          local x, y, z, locSource = baseLootLooseLocation(item)
          if x ~= 0 or y ~= 0 then
            local insideCollection = baseLootPointInCollectionArea(x, y, flag, params)
            if insideCollection then
              table.insert(out, {
                actor = item,
                x = x,
                y = y,
                z = z,
                locSource = locSource,
                haystack = baseLootClassName(item) .. " " .. objectClassFullName(item) .. " " .. objectFullName(item)
              })
            else
              reject["outside-collection-area"] = (reject["outside-collection-area"] or 0) + 1
            end
          else
            reject["zero-location"] = (reject["zero-location"] or 0) + 1
          end
        end
      else
        local key = tostring(reason or "rejected")
        local colon = key:find(":", 1, true)
        if colon ~= nil then key = key:sub(1, colon - 1) end
        reject[key] = (reject[key] or 0) + 1
        if #samples < 8 then
          local sx, sy, _, source = baseLootLooseLocation(item)
          table.insert(samples, baseLootClassName(item) .. "|presence=" .. tostring(baseLootPresenceClassText(item)) ..
            "|reason=" .. tostring(reason or "") .. "|loc=" .. tostring(source or "") ..
            "(" .. tostring(math.floor(tonumber(sx) or 0)) .. "," .. tostring(math.floor(tonumber(sy) or 0)) .. ")")
        end
      end
      if scanned % 32 == 0 and baseLootBudgetExceeded(started, (params or {}).scanWorkBudgetMs) then
        baseLootMarkLimited(params, "_itemScanLimited")
        appendLog("base-loot item overlap budget hit scanned=" .. tostring(scanned) ..
          " candidates=" .. tostring(#out) ..
          " occupancyMatched=" .. tostring(occupancyMatched) ..
          " ms=" .. tostring(baseLootElapsedMs(started)) ..
          " budgetMs=" .. tostring((params or {}).scanWorkBudgetMs or 0))
        break
      end
    end
  end
  if type(params) == "table" then params._itemScanMs = baseLootElapsedMs(started) end
  local parts = {}
  local blockedRejects = 0
  for key, value in pairs(reject) do
    table.insert(parts, tostring(key) .. "=" .. tostring(value))
    if tostring(key):find("blocked", 1, true) ~= nil then blockedRejects = blockedRejects + (tonumber(value) or 0) end
  end
  table.sort(parts)
  if #out == 0 and scanned > 0 then
    appendLog("base-loot item overlap produced no movable loose items scanned=" .. tostring(scanned) ..
      " rejects=" .. table.concat(parts, ",") ..
      " occupancyMatched=" .. tostring(occupancyMatched) ..
      " indexedChests=" .. tostring(indexedChests or 0) ..
      " limited=" .. tostring((params or {})._itemScanLimited == true) ..
      " ms=" .. tostring((params or {})._itemScanMs or 0) ..
      " samples=" .. table.concat(samples, " || "))
  elseif blockedRejects > 0 then
    appendLog("base-loot item overlap result scanned=" .. tostring(scanned) ..
      " candidates=" .. tostring(#out) ..
      " blocked=" .. tostring(blockedRejects) ..
      " occupancyMatched=" .. tostring(occupancyMatched) ..
      " indexedChests=" .. tostring(indexedChests or 0) ..
      " limited=" .. tostring((params or {})._itemScanLimited == true) ..
      " ms=" .. tostring((params or {})._itemScanMs or 0) ..
      " rejects=" .. table.concat(parts, ",") ..
      " samples=" .. table.concat(samples, " || "))
  elseif occupancyMatched > 0 then
    appendLog("base-loot item overlap result scanned=" .. tostring(scanned) ..
      " candidates=" .. tostring(#out) ..
      " occupancyMatched=" .. tostring(occupancyMatched) ..
      " indexedChests=" .. tostring(indexedChests or 0) ..
      " limited=" .. tostring((params or {})._itemScanLimited == true) ..
      " ms=" .. tostring((params or {})._itemScanMs or 0))
  end
  return out, scanned
end

function baseLootItems(flag, params, overlap)
  return baseLootScanItems(flag, params, nil, overlap)
end

function baseLootSameObject(a, b)
  if a == nil or b == nil then return false end
  local ak = baseLootObjectKey(a)
  local bk = baseLootObjectKey(b)
  if ak ~= "" and bk ~= "" and ak == bk then return true end
  local af = objectFullName(a)
  local bf = objectFullName(b)
  return af ~= "" and bf ~= "" and af == bf
end

function baseLootInventoryUserOwner(component)
  if component == nil or not isValidObject(component) then return nil end
  local owner = nil
  pcall(function() owner = component:GetOwner() end)
  if owner ~= nil and isValidObject(owner) then return owner end
  pcall(function() owner = component:GetOuter() end)
  if owner ~= nil and isValidObject(owner) then return owner end
  owner = firstProp(component, { "Owner", "_owner", "Outer", "_outer" })
  if owner ~= nil and isValidObject(owner) then return owner end
  return nil
end

function baseLootComponentByClass(owner, classPath)
  if owner == nil or not isValidObject(owner) then return nil end
  local cls = nil
  pcall(function() cls = StaticFindObject(classPath) end)
  if cls == nil or not isValidObject(cls) then return nil end
  local ok, component = safeCall(owner, "GetComponentByClass", cls)
  if ok and component ~= nil and isValidObject(component) then return component end
  return nil
end

function baseLootInventoryUsers(info)
  local out, seen = {}, {}
  local function add(component, route)
    if component == nil or not isValidObject(component) then return end
    local key = baseLootObjectKey(component)
    if key == "" or seen[key] then return end
    seen[key] = true
    table.insert(out, {
      component = component,
      route = tostring(route or "unknown"),
      owner = baseLootInventoryUserOwner(component)
    })
  end
  local globalScanRequested = baseLootBool({ "AllowGlobalInventoryUserScan", "allowGlobalInventoryUserScan" }, false) == true
  local roots = {
    { "pc", (info or {}).pc },
    { "pawn", (info or {}).pawn },
    { "ps", (info or {}).ps },
    { "rpc", (info or {}).rpc }
  }
  local propNames = {
    "InventoryUserComponent", "_inventoryUserComponent", "inventoryUserComponent",
    "InventoryUser", "_inventoryUser", "inventoryUser", "UserInventoryComponent",
    "_userInventoryComponent", "PlayerInventoryUserComponent", "_playerInventoryUserComponent"
  }
  for _, root in ipairs(roots) do
    local label, obj = root[1], root[2]
    if obj ~= nil and isValidObject(obj) then
      local direct = firstProp(obj, propNames)
      add(direct, label .. ".prop")
      add(baseLootComponentByClass(obj, "/Script/SCUM.InventoryUserComponent"), label .. ".GetComponentByClass")
    end
  end
  if globalScanRequested then appendLog("base-loot ignored AllowGlobalInventoryUserScan=true; only direct player inventory roots are safe") end
  if #out > 0 then
    local sample = {}
    for i = 1, math.min(#out, 4) do
      table.insert(sample, tostring(out[i].route) .. " owner=" .. tostring(objectFullName(out[i].owner)))
    end
    appendLog("base-loot IUC candidates=" .. tostring(#out) .. " globalFindAll=disabled " .. table.concat(sample, " || "))
  else
    appendLog("base-loot IUC candidates=0 globalFindAll=disabled")
  end
  return out
end

function baseLootItemInventoryOwner(item)
  local presence = baseLootPresence(item)
  local inv, owner = nil, nil
  if presence ~= nil then
    pcall(function()
      inv = presence._inventory or presence.Inventory or presence.inventory or presence._Inventory
    end)
  end
  if inv == nil then
    pcall(function()
      inv = item._inventory or item.Inventory or item.inventory or item._Inventory
    end)
  end
  if inv ~= nil and isValidObject(inv) then
    pcall(function() owner = inv:GetOwner() end)
    if owner ~= nil and isValidObject(owner) then return inv, owner end
  end
  return inv, owner
end

function baseLootVerifyItemInChest(item, chest)
  if item == nil or not isValidObject(item) then return false, "item invalid after move" end
  local chestOwner = baseLootChestOwner(chest)
  if chest == nil or chest.inv == nil or chestOwner == nil then return false, "target chest invalid" end
  local inv, owner = baseLootItemInventoryOwner(item)
  if inv ~= nil and isValidObject(inv) and baseLootSameObject(inv, chest.inv) then return true, "inventory matched target chest" end
  if owner ~= nil and isValidObject(owner) and baseLootSameObject(owner, chestOwner) then return true, "inventory owner matched target chest" end
  local ptext = baseLootPresenceClassText(item)
  return false,
    "presence=" .. tostring(ptext) ..
    " inv=" .. tostring(objectFullName(inv)) ..
    " owner=" .. tostring(objectFullName(owner)) ..
    " target=" .. tostring(objectFullName(chestOwner))
end

function baseLootInventoryLocationValue(item)
  local presence = baseLootPresence(item)
  if presence == nil or not isValidObject(presence) then return nil end
  local location = nil
  pcall(function()
    location = presence._location or presence.Location or presence.location
  end)
  if location == nil then return nil end
  if type(location) == "number" then return math.floor(location) end
  local value = nil
  pcall(function()
    value = location.Value or location.value
  end)
  if tonumber(value) ~= nil then return math.floor(tonumber(value)) end
  return nil
end

function baseLootLocationValueText(value)
  local number = tonumber(value)
  if number == nil then return "nil" end
  return tostring(math.floor(number)) .. "/0x" .. string.format("%08X", math.floor(number) % 4294967296)
end

function baseLootGridLocationValue(row, column)
  return (math.max(0, math.floor(tonumber(row) or 0)) * 1024) +
    (math.max(0, math.floor(tonumber(column) or 0)) * 4)
end

function baseLootPositiveNumberProp(obj, names)
  if obj == nil or not isValidObject(obj) then return nil end
  for _, name in ipairs(names or {}) do
    local value = nil
    pcall(function() value = obj[name] end)
    local number = tonumber(value)
    if number ~= nil and number > 0 then return math.floor(number) end
  end
  return nil
end

function baseLootChestGridDimensions(chest, params)
  local rows = tonumber((params or {}).inventoryGridRows) or 16
  local columns = tonumber((params or {}).inventoryGridColumns) or 16
  local rowNames = { "numRows", "NumRows", "_numRows", "Rows", "rows", "_rows" }
  local columnNames = { "numColumns", "NumColumns", "_numColumns", "Columns", "columns", "_columns" }
  local setupNames = {
    "Setup", "_setup", "setup",
    "InventorySetup", "_inventorySetup", "inventorySetup",
    "GridInventorySetup", "_gridInventorySetup", "gridInventorySetup",
    "EntityGridInventoryComponentSetup", "_entityGridInventoryComponentSetup"
  }
  local function readFrom(obj)
    if obj == nil or not isValidObject(obj) then return end
    rows = baseLootPositiveNumberProp(obj, rowNames) or rows
    columns = baseLootPositiveNumberProp(obj, columnNames) or columns
    local setup = firstProp(obj, setupNames)
    if setup ~= nil and isValidObject(setup) then
      rows = baseLootPositiveNumberProp(setup, rowNames) or rows
      columns = baseLootPositiveNumberProp(setup, columnNames) or columns
    end
  end
  readFrom((chest or {}).inv)
  readFrom((chest or {}).actor)
  rows = math.max(1, math.min(math.floor(rows), 64))
  columns = math.max(1, math.min(math.floor(columns), 64))
  return rows, columns
end

function baseLootChestOccupiedLocationValues(chest, params)
  if chest == nil then return {} end
  if type(chest.occupiedLocationValues) == "table" then return chest.occupiedLocationValues end
  -- The bounded overlap pass records local occupancy before this function is
  -- used. Leave unknown locations empty instead of starting a global Item scan.
  chest.occupiedLocationValues = {}
  if (params or {}).inventoryLocationOccupancyBatch == false then
    appendLog("base-loot chest occupancy global fallback disabled chest=" .. tostring(chest.name or ""))
  end
  return chest.occupiedLocationValues
end

function baseLootGridCandidateLocations(chest, params)
  local rows, columns = baseLootChestGridDimensions(chest, params)
  local maxAttempts = math.max(1, math.min(math.floor(tonumber((params or {}).inventoryLocationMaxAttempts) or 96), 512))
  local occupied = baseLootChestOccupiedLocationValues(chest, params)
  local out = {}
  local seen = {}
  local function add(value, label)
    local number = tonumber(value)
    if number == nil then return end
    number = math.floor(number)
    if seen[number] then return end
    seen[number] = true
    if occupied[number] == true and label ~= "legacy-auto" and label ~= "auto" then return end
    table.insert(out, { value = number, label = tostring(label or "grid") })
  end
  if (params or {}).inventoryLocationIncludeLegacyAuto == true then
    add(1073741824, "auto")
  end
  for row = 0, rows - 1 do
    for column = 0, columns - 1 do
      add(baseLootGridLocationValue(row, column), "grid")
      if #out >= maxAttempts then break end
    end
    if #out >= maxAttempts then break end
  end
  return out, rows, columns
end

function baseLootPresenceLooksFloor(item)
  local ptext = baseLootPresenceClassText(item)
  return ptext:find("onthefloor", 1, true) ~= nil or
    ptext:find("on_the_floor", 1, true) ~= nil or
    ptext:find("floor", 1, true) ~= nil
end

function baseLootPresenceLooksInventory(item)
  local ptext = baseLootPresenceClassText(item)
  return ptext:find("intheinventory", 1, true) ~= nil or
    ptext:find("in_the_inventory", 1, true) ~= nil or
    ptext:find("inventory", 1, true) ~= nil
end

function baseLootProbeInventoryLocations(chests, looseItems, params, live, flag, scannedChests, scannedItems, overlap)
  local samples = {}
  local chestItemCount = 0
  local scanned = 0
  local maxScan = math.max(10, math.min(math.floor(tonumber((params or {}).sphereOverlapMaxActors or (params or {}).maxScannedItems) or 256), 1000))
  for _, actor in ipairs((overlap or {}).actors or {}) do
    scanned = scanned + 1
    if scanned > maxScan then break end
    local inv, owner = baseLootItemInventoryOwner(actor)
    if inv ~= nil and isValidObject(inv) then
      for _, chest in ipairs(chests or {}) do
        if chest ~= nil and ((chest.inv ~= nil and baseLootSameObject(inv, chest.inv)) or (owner ~= nil and baseLootSameObject(owner, chest.actor))) then
          chestItemCount = chestItemCount + 1
          if #samples < 16 then
            local value = baseLootInventoryLocationValue(actor)
            table.insert(samples,
              tostring(baseLootClassName(actor)) ..
              "@chest=" .. tostring(chest.name or "") ..
              "@loc=" .. baseLootLocationValueText(value) ..
              "@presence=" .. tostring(baseLootPresenceClassText(actor)) ..
              "@owner=" .. tostring(objectFullName(owner)))
          end
          break
        end
      end
    end
  end
  local looseSample = {}
  for i = 1, math.min(#(looseItems or {}), 10) do
    local item = looseItems[i]
    table.insert(looseSample,
      tostring(baseLootClassName(item.actor)) ..
      "@loc=" .. tostring(math.floor(tonumber(item.x) or 0)) .. "," .. tostring(math.floor(tonumber(item.y) or 0)) ..
      "@presence=" .. tostring(baseLootPresenceClassText(item.actor)))
  end
  local data = '{"chests":' .. tostring(#(chests or {})) ..
    ',"scannedChests":' .. tostring(scannedChests or 0) ..
    ',"loose":' .. tostring(#(looseItems or {})) ..
    ',"scannedLoose":' .. tostring(scannedItems or 0) ..
    ',"inventoryItemsInChests":' .. tostring(chestItemCount) ..
    ',"scannedInventoryProbe":' .. tostring(scanned) ..
    ',"scanSource":"sphere-overlap"' ..
    ',"baseId":' .. js((flag or {}).baseId or "") ..
    ',"samples":' .. js(table.concat(samples, " || ")) ..
    ',"looseSamples":' .. js(table.concat(looseSample, " || ")) .. '}'
  appendLog("base-loot probe player=" .. tostring((live or {}).name or "") ..
    " baseId=" .. tostring((flag or {}).baseId or "") ..
    " chests=" .. tostring(#(chests or {})) ..
    " loose=" .. tostring(#(looseItems or {})) ..
    " inChest=" .. tostring(chestItemCount) ..
    " samples=" .. table.concat(samples, " || ") ..
    " looseSamples=" .. table.concat(looseSample, " || "))
  appendActionEvent("base_loot_probe", true, live, "base loot inventory location probe", data)
  return true, "[Лут] Probe: сундуки " .. tostring(#(chests or {})) ..
    ", лут " .. tostring(#(looseItems or {})) ..
    ", предметов внутри найденных сундуков " .. tostring(chestItemCount) ..
    ". Подробности в nedjin.log."
end

BASE_LOOT_OPEN_HANDLE = BASE_LOOT_OPEN_HANDLE or 41000

function baseLootNextOpenHandle()
  BASE_LOOT_OPEN_HANDLE = (tonumber(BASE_LOOT_OPEN_HANDLE) or 41000) + 1
  if BASE_LOOT_OPEN_HANDLE > 65000 then BASE_LOOT_OPEN_HANDLE = 41001 end
  return BASE_LOOT_OPEN_HANDLE
end

function baseLootCloseInventoryHandle(inventoryUser, chest, openHandle, route)
  if inventoryUser == nil or chest == nil or chest.inv == nil or openHandle == nil then
    return false, "close skipped"
  end
  local okClose, closeResult = pcall(function()
    return inventoryUser:Server_CloseInventory(chest.inv, openHandle)
  end)
  if okClose then
    appendLog("base-loot close inventory ok chest=" .. tostring(chest.name or "") ..
      " handle=" .. tostring(openHandle) ..
      " route=" .. tostring(route or "iuc"))
    return true, closeResult
  end
  appendLog("base-loot close inventory failed chest=" .. tostring(chest.name or "") ..
    " handle=" .. tostring(openHandle) ..
    " route=" .. tostring(route or "iuc") ..
    " error=" .. safeString(closeResult, "close failed"))
  return false, closeResult
end

function baseLootTryMoveWithInventoryUsersDirect(inventoryUsers, chest, item, params)
  if inventoryUsers == nil or #inventoryUsers == 0 then return false, "InventoryUserComponent missing" end
  if chest == nil or chest.inv == nil then return false, "target chest missing" end
  if item == nil or item.actor == nil then return false, "item missing" end
  local lastError = ""
  local started = baseLootStartTimer()
  local locations, rows, columns = baseLootGridCandidateLocations(chest, params)
  local attempted = 0
  for _, candidate in ipairs(inventoryUsers) do
    local inventoryUser = candidate.component
    if inventoryUser ~= nil and isValidObject(inventoryUser) then
      local openMessage = ""
      local openedHandle = nil
      if (params or {}).openChestBeforeMove ~= false then
        local openHandle = baseLootNextOpenHandle()
        local okOpen, openResult = pcall(function()
          return inventoryUser:Server_OpenInventory(chest.inv, openHandle)
        end)
        if okOpen then
          openedHandle = openHandle
          openMessage = " open=" .. tostring(openHandle)
        else
          openMessage = " open failed: " .. safeString(openResult, "open failed")
          appendLog("base-loot open inventory failed chest=" .. tostring(chest.name or "") ..
            " route=" .. tostring(candidate.route or "iuc") ..
            " error=" .. safeString(openResult, "open failed"))
        end
      end
      for _, location in ipairs(locations) do
        if attempted > 0 and baseLootBudgetExceeded(started, (params or {}).singleItemMoveBudgetMs) then
          baseLootCloseInventoryHandle(inventoryUser, chest, openedHandle, candidate.route)
          return false, (lastError ~= "" and lastError or "move not verified") ..
            "; item move budget reached attempts=" .. tostring(attempted) ..
            " budgetMs=" .. tostring((params or {}).singleItemMoveBudgetMs or 0)
        end
        attempted = attempted + 1
        local locationValue = tonumber(location.value) or 0
        local okMove, result = pcall(function()
          return inventoryUser:Server_InventoryComponent_AddOrMoveEntry(chest.inv, item.actor, { Value = locationValue })
        end)
        if okMove then
          local verified, verifyMessage = baseLootVerifyItemInChest(item.actor, chest)
          if verified then
            if type(chest.occupiedLocationValues) == "table" then chest.occupiedLocationValues[math.floor(locationValue)] = true end
            baseLootCloseInventoryHandle(inventoryUser, chest, openedHandle, candidate.route)
            return true, tostring(candidate.route or "iuc") .. tostring(openMessage or "") ..
              " loc=" .. baseLootLocationValueText(locationValue) ..
              " " .. tostring(location.label or "") .. ": " .. tostring(verifyMessage)
          end
          lastError = tostring(candidate.route or "iuc") .. tostring(openMessage or "") ..
            " loc=" .. baseLootLocationValueText(locationValue) ..
            " " .. tostring(location.label or "") .. " unverified: " .. tostring(verifyMessage)
        else
          lastError = tostring(candidate.route or "iuc") .. tostring(openMessage or "") ..
            " loc=" .. baseLootLocationValueText(locationValue) ..
            " " .. tostring(location.label or "") .. " failed: " .. safeString(result, "move failed")
        end
      end
      baseLootCloseInventoryHandle(inventoryUser, chest, openedHandle, candidate.route)
    end
  end
  return false, (lastError ~= "" and lastError or "move not verified") ..
    " attempts=" .. tostring(attempted) ..
    " grid=" .. tostring(rows or "?") .. "x" .. tostring(columns or "?")
end

function baseLootCharacterInventoryComponent(info)
  local inv = playerInventoryComponent(info)
  if inv ~= nil and isValidObject(inv) then
    local classText = (baseLootClassName(inv) .. " " .. objectClassFullName(inv) .. " " .. objectFullName(inv)):lower()
    if classText:find("characterinventorycomponent", 1, true) ~= nil or
        classText:find("prisonerinventorycomponent", 1, true) ~= nil then
      return inv, "playerInventoryComponent"
    end
  end
  local roots = {
    { "pawn", (info or {}).pawn },
    { "pc", (info or {}).pc },
    { "ps", (info or {}).ps }
  }
  local propNames = {
    "PrisonerInventoryComponent", "_prisonerInventoryComponent", "prisonerInventoryComponent",
    "CharacterInventoryComponent", "_characterInventoryComponent", "characterInventoryComponent",
    "InventoryComponent", "_inventoryComponent", "inventoryComponent",
    "Inventory", "_inventory", "inventory"
  }
  for _, root in ipairs(roots) do
    local obj = root[2]
    if obj ~= nil and isValidObject(obj) then
      local candidate = firstProp(obj, propNames)
      if candidate ~= nil and isValidObject(candidate) then
        local classText = (baseLootClassName(candidate) .. " " .. objectClassFullName(candidate) .. " " .. objectFullName(candidate)):lower()
        if classText:find("characterinventorycomponent", 1, true) ~= nil or
            classText:find("prisonerinventorycomponent", 1, true) ~= nil then
          return candidate, tostring(root[1]) .. ".prop"
        end
      end
      candidate = baseLootComponentByClass(obj, "/Script/SCUM.PrisonerInventoryComponent")
      if candidate ~= nil and isValidObject(candidate) then return candidate, tostring(root[1]) .. ".PrisonerInventoryComponent" end
      candidate = baseLootComponentByClass(obj, "/Script/SCUM.CharacterInventoryComponent")
      if candidate ~= nil and isValidObject(candidate) then return candidate, tostring(root[1]) .. ".CharacterInventoryComponent" end
    end
  end
  return nil, "character inventory missing"
end

function baseLootPickupItemWithInventoryUsers(inventoryUsers, item, info)
  if inventoryUsers == nil or #inventoryUsers == 0 then return false, "InventoryUserComponent missing" end
  if item == nil or item.actor == nil or not isValidObject(item.actor) then return false, "item missing" end
  local characterInventory, inventoryRoute = baseLootCharacterInventoryComponent(info)
  if characterInventory == nil or not isValidObject(characterInventory) then
    return false, tostring(inventoryRoute or "character inventory missing")
  end
  local lastError = ""
  for _, candidate in ipairs(inventoryUsers) do
    local inventoryUser = candidate.component
    if inventoryUser ~= nil and isValidObject(inventoryUser) then
      for _, method in ipairs({
        "Server_CharacterInventoryComponent_PickupItem",
        "Server_CharacterInventoryComponent_PickupOrDropItem"
      }) do
        local okPickup, result = safeCall(inventoryUser, method, characterInventory, item.actor)
        if okPickup then
          local inv, owner = baseLootItemInventoryOwner(item.actor)
          if inv ~= nil and isValidObject(inv) and baseLootPresenceLooksInventory(item.actor) then
            return true, tostring(candidate.route or "iuc") .. "." .. method ..
              " via " .. tostring(inventoryRoute or "") ..
              " inv=" .. tostring(objectFullName(inv)) ..
              " owner=" .. tostring(objectFullName(owner))
          end
          if not baseLootPresenceLooksFloor(item.actor) then
            return true, tostring(candidate.route or "iuc") .. "." .. method ..
              " changed presence=" .. tostring(baseLootPresenceClassText(item.actor))
          end
          lastError = tostring(candidate.route or "iuc") .. "." .. method ..
            " unverified: presence still floor"
        else
          lastError = tostring(candidate.route or "iuc") .. "." .. method ..
            " failed: " .. safeString(result, "pickup failed")
        end
      end
    end
  end
  return false, lastError ~= "" and lastError or "pickup not verified"
end

function baseLootTryMoveWithInventoryUsers(inventoryUsers, chest, item, params, info)
  if item ~= nil and item.actor ~= nil and (params or {}).pickupFloorBeforeChestMove == true and baseLootPresenceLooksFloor(item.actor) then
    local okPickup, pickupMessage = baseLootPickupItemWithInventoryUsers(inventoryUsers, item, info)
    if okPickup then
      local okMove, moveMessage = baseLootTryMoveWithInventoryUsersDirect(inventoryUsers, chest, item, params)
      if okMove then return true, "pickup: " .. tostring(pickupMessage or "") .. "; " .. tostring(moveMessage or "") end
      local restored, restoreMessage = baseLootControlledRelocateItem(item, chest, info, params)
      return false, "pickup ok but chest move failed: " .. tostring(moveMessage or "") ..
        "; restore=" .. tostring(restored == true) .. " " .. tostring(restoreMessage or "")
    end
    local okDirect, directMessage = baseLootTryMoveWithInventoryUsersDirect(inventoryUsers, chest, item, params)
    if okDirect then return true, directMessage end
    return false, "pickup failed: " .. tostring(pickupMessage or "") .. "; direct=" .. tostring(directMessage or "")
  end
  return baseLootTryMoveWithInventoryUsersDirect(inventoryUsers, chest, item, params)
end

function baseLootDropAround(itemActor, chestOwner, pawn, route)
  local fn = safeGet(itemActor, "DropAround")
  local okDrop, result = safeCall(itemActor, "DropAround", chestOwner, pawn)
  if not okDrop or result ~= true then
    appendLog("base-loot DropAround rejected route=" .. tostring(route or "") ..
      " callOk=" .. tostring(okDrop) ..
      " resultType=" .. tostring(type(result)) ..
      " result=" .. tostring(result) ..
      " methodType=" .. tostring(type(fn)) ..
      " itemValid=" .. tostring(isValidObject(itemActor)) ..
      " itemClass=" .. tostring(baseLootClassName(itemActor)) ..
      " chestValid=" .. tostring(isValidObject(chestOwner)) ..
      " chestClass=" .. tostring(baseLootClassName(chestOwner)) ..
      " pawnValid=" .. tostring(isValidObject(pawn)) ..
      " pawnClass=" .. tostring(baseLootClassName(pawn)))
  end
  return okDrop, result
end

function baseLootRelocateItemNearChest(item, chest, info, params)
  if params.allowUnsafeDropAroundFallback ~= true then
    return false, "DropAround fallback disabled; inventory move was not confirmed"
  end
  if params.relocateBeforeMove ~= true then return false, "relocate disabled" end
  if item == nil or item.actor == nil or not isValidObject(item.actor) then return false, "item missing" end
  local chestOwner = baseLootChestOwner(chest)
  if chestOwner == nil then return false, "target chest actor missing" end
  local pawn = (info or {}).pawn
  if pawn == nil or not isValidObject(pawn) then return false, "player pawn missing" end

  local beforeX, beforeY = baseLootLooseLocation(item.actor)
  local chestX, chestY = vectorOf(chestOwner)
  local beforeDistance = distance2d(beforeX or 0, beforeY or 0, chestX or 0, chestY or 0)
  local okDrop, result = baseLootDropAround(item.actor, chestOwner, pawn, "unsafe-relocate")
  if not okDrop or result ~= true then
    local message = "DropAround failed: " .. tostring(result)
    appendLog("base-loot unsafe relocate failed item=" .. tostring(item.haystack or "") ..
      " chest=" .. tostring(chest.name or "") .. " error=" .. message)
    return false, message
  end
  local verified, verifyMessage = baseLootVerifyItemNearChest(item, chest, params)
  local afterX, afterY = baseLootLooseLocation(item.actor)
  local afterDistance = distance2d(afterX or 0, afterY or 0, chestX or 0, chestY or 0)
  appendLog("base-loot relocated item=" .. tostring(item.haystack or "") ..
    " chest=" .. tostring(chest.name or "") ..
    " beforeCm=" .. tostring(math.floor(tonumber(beforeDistance) or 0)) ..
    " afterCm=" .. tostring(math.floor(tonumber(afterDistance) or 0)) ..
    " verified=" .. tostring(verified == true) ..
    " result=" .. tostring(result) ..
    " verify=" .. tostring(verifyMessage or ""))
  if not verified then
    return false, "DropAround not verified: " .. tostring(verifyMessage or "")
  end
  return true, "DropAround beforeCm=" .. tostring(math.floor(tonumber(beforeDistance) or 0)) ..
    " afterCm=" .. tostring(math.floor(tonumber(afterDistance) or 0))
end

function baseLootRefreshItemLocation(item)
  if item == nil or item.actor == nil or not isValidObject(item.actor) then return item end
  local x, y, z, source = baseLootLooseLocation(item.actor)
  item.x = x or item.x
  item.y = y or item.y
  item.z = z or item.z
  item.locSource = source or item.locSource
  return item
end

function baseLootNearChestLimit(params)
  local configured = tonumber((params or {}).relocateIfFartherThanCm) or 650
  return math.max(100, math.min(math.floor(configured), 5000))
end

function baseLootNearChestVerticalLimit(params)
  local configured = tonumber((params or {}).relocateVerticalToleranceCm) or 350
  return math.max(50, math.min(math.floor(configured), 1000))
end

function baseLootVerifyItemNearChest(item, chest, params)
  if item == nil or item.actor == nil or not isValidObject(item.actor) then
    return false, "item missing"
  end
  local chestOwner = baseLootChestOwner(chest)
  if chestOwner == nil then return false, "target chest actor missing" end
  if not baseLootPresenceLooksFloor(item.actor) then
    return false, "item is not on the floor"
  end
  local itemX, itemY, itemZ = baseLootLooseLocation(item.actor)
  local chestX, chestY, chestZ = vectorOf(chestOwner)
  if itemX == nil or itemY == nil or itemZ == nil or chestX == nil or chestY == nil or chestZ == nil then
    return false, "fresh item or chest location missing"
  end
  item.x, item.y, item.z = itemX, itemY, itemZ
  local horizontalDistance = distance2d(itemX, itemY, chestX, chestY)
  local horizontalLimit = baseLootNearChestLimit(params)
  local verticalDistance = math.abs((tonumber(itemZ) or 0) - (tonumber(chestZ) or 0))
  local verticalLimit = baseLootNearChestVerticalLimit(params)
  if horizontalDistance == nil then return false, "horizontal distance unavailable" end
  if horizontalDistance > horizontalLimit then
    return false, "item horizontal=" .. tostring(math.floor(horizontalDistance)) .. "cm; limit=" .. tostring(horizontalLimit)
  end
  if verticalDistance > verticalLimit then
    return false, "item vertical=" .. tostring(math.floor(verticalDistance)) .. "cm; limit=" .. tostring(verticalLimit) ..
      " horizontal=" .. tostring(math.floor(horizontalDistance)) .. "cm"
  end
  return true, "floor near chest horizontal=" .. tostring(math.floor(horizontalDistance)) .. "cm; limit=" .. tostring(horizontalLimit) ..
    " vertical=" .. tostring(math.floor(verticalDistance)) .. "cm; verticalLimit=" .. tostring(verticalLimit)
end

function baseLootForceItemReplication(itemActor)
  if itemActor == nil or not isValidObject(itemActor) then return false, "item invalid" end
  local flushOk, flushResult = safeCall(itemActor, "FlushNetDormancy")
  local forceOk, forceResult = safeCall(itemActor, "ForceNetUpdate")
  local message = "FlushNetDormancy=" .. tostring(flushOk == true) .. ":" .. tostring(flushResult) ..
    "; ForceNetUpdate=" .. tostring(forceOk == true) .. ":" .. tostring(forceResult)
  return flushOk == true or forceOk == true, message
end

function baseLootControlledRelocateItem(item, chest, info, params)
  params = params or {}
  if params.controlledRelocate ~= true then return false, "controlled relocate disabled" end
  if item == nil or item.actor == nil or not isValidObject(item.actor) then return false, "item missing" end
  local chestOwner = baseLootChestOwner(chest)
  if chestOwner == nil then return false, "target chest actor missing" end
  local pawn = (info or {}).pawn
  if pawn == nil or not isValidObject(pawn) then return false, "player pawn missing" end
  local beforeDistance = baseLootDistanceToChest(item, chest)
  local alreadyNear, alreadyMessage = baseLootVerifyItemNearChest(item, chest, params)
  if alreadyNear then
    appendLog("base-loot controlled relocate already-near item=" .. tostring(item.haystack or "") ..
      " chest=" .. tostring(chest.name or "") ..
      " beforeCm=" .. tostring(math.floor(tonumber(beforeDistance) or 0)) ..
      " verify=" .. tostring(alreadyMessage or ""))
    return true, tostring(alreadyMessage or "already near chest")
  end

  local maxAttempts = math.max(1, tonumber(params.controlledRelocateAttempts) or 3)
  local attempt, dropResult, dropSucceeded = 0, nil, false
  local successRoute, verifyMessage = "", ""
  local replicationOk, replicationMessage = false, ""
  for currentAttempt = 1, maxAttempts do
    attempt = currentAttempt
    local okDrop, result = baseLootDropAround(item.actor, chestOwner, pawn, "controlled-relocate")
    dropResult = result
    local attemptReplicationOk, attemptReplicationMessage = baseLootForceItemReplication(item.actor)
    replicationOk = replicationOk or attemptReplicationOk == true
    replicationMessage = tostring(attemptReplicationMessage or "")
    baseLootRefreshItemLocation(item)
    local verified, attemptVerifyMessage = baseLootVerifyItemNearChest(item, chest, params)
    verifyMessage = tostring(attemptVerifyMessage or "")
    if verified then
      dropSucceeded = true
      successRoute = (okDrop and result == true) and "return-and-verify" or "verify-after-return"
      break
    end
    if currentAttempt < maxAttempts then
      appendLog("base-loot controlled relocate retry item=" .. tostring(item.haystack or "") ..
        " chest=" .. tostring(chest.name or "") ..
        " attempt=" .. tostring(currentAttempt) .. "/" .. tostring(maxAttempts) ..
        " callOk=" .. tostring(okDrop == true) ..
        " result=" .. tostring(result) ..
        " verify=" .. tostring(attemptVerifyMessage or ""))
    end
  end
  if not dropSucceeded then
    local message = "DropAround not verified after " .. tostring(attempt) .. " attempt(s): " ..
      tostring(dropResult) .. "; " .. tostring(verifyMessage or "")
    appendLog("base-loot controlled relocate failed item=" .. tostring(item.haystack or "") ..
      " chest=" .. tostring(chest.name or "") ..
      " beforeCm=" .. tostring(math.floor(tonumber(beforeDistance) or 0)) ..
      " error=" .. message)
    return false, message
  end
  baseLootRefreshItemLocation(item)
  local verified, finalVerifyMessage = baseLootVerifyItemNearChest(item, chest, params)
  verifyMessage = tostring(finalVerifyMessage or verifyMessage or "")
  local afterDistance = baseLootDistanceToChest(item, chest)
  appendLog("base-loot controlled relocate item=" .. tostring(item.haystack or "") ..
    " chest=" .. tostring(chest.name or "") ..
    " beforeCm=" .. tostring(math.floor(tonumber(beforeDistance) or 0)) ..
    " afterCm=" .. tostring(math.floor(tonumber(afterDistance) or 0)) ..
    " verified=" .. tostring(verified == true) ..
    " successRoute=" .. tostring(successRoute or "") ..
    " attempts=" .. tostring(attempt) .. "/" .. tostring(maxAttempts) ..
    " replicationOk=" .. tostring(replicationOk == true) ..
    " replication=" .. tostring(replicationMessage or "") ..
    " delayMs=" .. tostring(params.controlledRelocateDelayMs or 1200) ..
    " result=" .. tostring(dropResult) ..
    " verify=" .. tostring(verifyMessage or ""))
  if not verified then
    return false, "DropAround not verified: " .. tostring(verifyMessage or "")
  end
  return true, "controlled relocate beforeCm=" .. tostring(math.floor(tonumber(beforeDistance) or 0)) ..
    " afterCm=" .. tostring(math.floor(tonumber(afterDistance) or 0)) ..
    " attempts=" .. tostring(attempt) .. " route=" .. tostring(successRoute or "")
end

function baseLootMoveItem(inventoryUsers, chest, item, params, info)
  if params.dryRun then return true, "dry-run" end
  appendLog("base-loot move begin item=" .. tostring(item and item.haystack or "") ..
    " chest=" .. tostring(chest and chest.name or "") ..
    " pickupBefore=" .. tostring((params or {}).pickupFloorBeforeChestMove == true) ..
    " directOpen=" .. tostring((params or {}).openChestBeforeMove == true) ..
    " controlledRelocate=" .. tostring((params or {}).controlledRelocate == true))
  local okMove, moveMessage = baseLootTryMoveWithInventoryUsers(inventoryUsers, chest, item, params, info)
  if okMove then return true, moveMessage end

  local relocateMessage = "DropAround fallback disabled"
  if params.allowUnsafeDropAroundFallback == true then
    local relocated = false
    relocated, relocateMessage = baseLootRelocateItemNearChest(item, chest, info, params)
    if relocated then
      okMove, moveMessage = baseLootTryMoveWithInventoryUsers(inventoryUsers, chest, item, params, info)
      if okMove then return true, "relocated: " .. tostring(moveMessage or "") end
    end
  end

  appendLog("base-loot move not verified item=" .. tostring(item and item.haystack or "") ..
    " chest=" .. tostring(chest and chest.name or "") ..
    " itemChestCm=" .. tostring(math.floor(tonumber(baseLootDistanceToChest(item, chest)) or 0)) ..
    " moveError=" .. tostring(moveMessage or "") ..
    " relocate=" .. tostring(relocateMessage or ""))
  return false, tostring(moveMessage or "move not verified") .. "; " .. tostring(relocateMessage or "relocate not attempted")
end

function baseLootActiveKey(info, flag)
  local baseId = tostring((flag or {}).baseId or "")
  if baseId ~= "" and baseId ~= "nil" then return "base:" .. baseId end
  local steam = tostring((info or {}).steam or "")
  if steam ~= "" then return "steam:" .. steam end
  return "global"
end

function baseLootNearbyChestMessage(count, final)
  local total = math.max(0, math.floor(tonumber(count) or 0))
  if total <= 0 then return "[Лут] Вещи лежат рядом с сундуком." end
  if final == true then return "[Лут] Вещи лежат рядом с сундуком: " .. tostring(total) .. "." end
  return "[Лут] Вещи перенесены рядом с сундуком: " .. tostring(total) .. "."
end

function baseLootMixedChestMessage(moved, nearby, final)
  local movedCount = math.max(0, math.floor(tonumber(moved) or 0))
  local nearbyCount = math.max(0, math.floor(tonumber(nearby) or 0))
  if movedCount <= 0 then return baseLootNearbyChestMessage(nearbyCount, final) end
  if nearbyCount <= 0 then return nil end
  if final == true then
    return "[Лут] В сундук сложено: " .. tostring(movedCount) .. ". Рядом с сундуком осталось: " .. tostring(nearbyCount) .. "."
  end
  return "[Лут] В сундук сложено: " .. tostring(movedCount) .. ". Рядом с сундуком: " .. tostring(nearbyCount) .. "."
end

function baseLootMessageLooksTechnical(message)
  local text = tostring(message or "")
  if text == "" then return false end
  local haystack = text:lower()
  local markers = {
    "findallof.",
    "inventoryusercomponent",
    "uobject:",
    "persistentlevel.",
    "/game/conz_files/",
    "itempresence_",
    "uitempresence",
    " unverified:",
    " inv=uobject"
  }
  for _, marker in ipairs(markers) do
    if haystack:find(marker, 1, true) ~= nil then return true end
  end
  return false
end

function baseLootPlayerMessage(message, nearbyCount, final)
  local text = tostring(message or "")
  if not baseLootMessageLooksTechnical(text) then return text end
  appendLog("base-loot sanitized technical player message: " .. text)
  local count = math.max(0, math.floor(tonumber(nearbyCount) or 0))
  if count > 0 then return baseLootNearbyChestMessage(count, final ~= false) end
  return "[Лут] Не удалось перенести вещи. Детали записаны в журнал администратора."
end

function baseLootFinishRelocatedBatch(activeKey, live, staged, params, flag, scannedItems, scannedChests)
  local moved, nearby, failed = 0, 0, 0
  local firstError = ""
  local inventoryUsers = baseLootInventoryUsers(live)
  for _, row in ipairs(staged or {}) do
    local item = row.item
    local chest = row.chest
    baseLootRefreshItemLocation(item)
    local okMove, moveMessage = baseLootTryMoveWithInventoryUsers(inventoryUsers, chest, item, params, live)
    if okMove then
      moved = moved + 1
    else
      local nearChest, verifyMessage = baseLootVerifyItemNearChest(item, chest, params)
      if nearChest then
        nearby = nearby + 1
        appendLog("base-loot delayed move remains-near-chest item=" .. tostring(item and item.haystack or "") ..
          " chest=" .. tostring(chest and chest.name or "") ..
          " verify=" .. tostring(verifyMessage or ""))
      else
        failed = failed + 1
        if firstError == "" then firstError = tostring(moveMessage or "") .. "; " .. tostring(verifyMessage or "") end
        appendLog("base-loot delayed move not verified item=" .. tostring(item and item.haystack or "") ..
          " chest=" .. tostring(chest and chest.name or "") ..
          " itemChestCm=" .. tostring(math.floor(tonumber(baseLootDistanceToChest(item, chest)) or 0)) ..
          " error=" .. tostring(moveMessage or "") ..
          " verify=" .. tostring(verifyMessage or ""))
      end
    end
  end
  baseLootClearActive(activeKey)
  local message = nil
  if nearby > 0 then
    message = baseLootMixedChestMessage(moved, nearby, true)
  end
  if message == nil and moved > 0 then
    message = applyVars(baseLootString({ "SuccessMessage", "successMessage" }, "[Лут] Перемещено: {Moved}. Пропущено: {Skipped}."), {
    Moved = tostring(moved),
    moved = tostring(moved),
    Skipped = "0",
    skipped = "0",
    Failed = tostring(failed),
    failed = tostring(failed),
    Chests = tostring(scannedChests or 0),
    chests = tostring(scannedChests or 0),
    Scanned = tostring(scannedItems or 0),
    scanned = tostring(scannedItems or 0)
    })
  end
  if message == nil and failed > 0 then message = "[Лут] Не удалось подтвердить перенос вещей. Детали записаны в журнал администратора." end
  if message == nil then message = baseLootString({ "EmptyMessage", "emptyMessage" }, "[Лут] Подходящего лута рядом с флагом не найдено.") end
  message = baseLootPlayerMessage(message, nearby + failed, true)
  targetMessageResolved(live, message)
  appendJsonArray(STATE_DIR .. "\\" .. BASE_LOOT_STATE_FILE,
    '{"utc":' .. js(nowUtc()) ..
    ',"steamId":' .. js((live or {}).steam or "") ..
    ',"name":' .. js((live or {}).name or "") ..
    ',"baseId":' .. js((flag or {}).baseId or "") ..
    ',"radius":' .. tostring((params or {}).radius or 0) ..
    ',"moved":' .. tostring(moved) ..
    ',"skipped":0' ..
    ',"failed":' .. tostring(failed) ..
    ',"nearby":' .. tostring(nearby) ..
    ',"staged":' .. tostring(#(staged or {})) ..
    ',"phase":"delayed-controlled-relocate"' ..
    ',"scannedItems":' .. tostring(scannedItems or 0) ..
    ',"scannedChests":' .. tostring(scannedChests or 0) ..
    ',"dryRun":false' ..
    ',"error":' .. js(firstError) .. '}',
    1024 * 1024)
  appendActionEvent("base_loot_collector", moved > 0 or nearby > 0, live, message,
    '{"moved":' .. tostring(moved) .. ',"skipped":0,"failed":' .. tostring(failed) .. ',"nearby":' .. tostring(nearby) ..
    ',"staged":' .. tostring(#(staged or {})) ..
    ',"phase":"delayed-controlled-relocate","baseId":' .. js((flag or {}).baseId or "") ..
    ',"error":' .. js(firstError) .. '}')
end

function baseLootResolveChestForItem(chests, item, params)
  local chestName = baseLootRuleChestName((item or {}).haystack, params)
  local chest = baseLootChestForName(chests, chestName, (params or {}).nameContains, item)
  if chest == nil and (params or {}).fallbackToDefaultChest and tostring(chestName or ""):lower() ~= tostring((params or {}).defaultChest or ""):lower() then
    chest = baseLootChestForName(chests, (params or {}).defaultChest, (params or {}).nameContains, item)
  end
  return chest, chestName
end

function baseLootJobLimit(job)
  local params = (job or {}).params or {}
  if params.collectAllOnSingleCommand == true then return #(job.items or {}) end
  return math.max(1, tonumber(params.maxItems) or 80)
end

function baseLootJobLogNoChest(job, chestName, item)
  job.noChestLogs = tonumber(job.noChestLogs or 0) or 0
  if job.noChestLogs >= 5 then return end
  job.noChestLogs = job.noChestLogs + 1
  local names = {}
  for _, knownChest in ipairs(job.chests or {}) do table.insert(names, tostring(knownChest.name or "")) end
  appendLog("base-loot no chest match wanted=" .. tostring(chestName or "") ..
    " default=" .. tostring((job.params or {}).defaultChest or "") ..
    " chests=[" .. table.concat(names, "|") .. "] item=" .. tostring((item or {}).haystack or ""))
end

function baseLootJobMoveOne(job, item)
  if job == nil then return end
  local limit = baseLootJobLimit(job)
  if ((job.moved or 0) + (job.staged or 0) + (job.failed or 0)) >= limit then
    job.skipped = (job.skipped or 0) + 1
    return
  end
  local chest, chestName = baseLootResolveChestForItem(job.chests or {}, item, job.params or {})
  if chest == nil then
    job.skipped = (job.skipped or 0) + 1
    baseLootJobLogNoChest(job, chestName, item)
    return
  end
  local params = job.params or {}
  local alreadyNear, alreadyMessage = baseLootVerifyItemNearChest(item, chest, params)
  if alreadyNear then
    job.nearby = (job.nearby or 0) + 1
    appendLog("base-loot async item already near chest item=" .. tostring((item or {}).haystack or "") ..
      " chest=" .. tostring((chest or {}).name or "") ..
      " verify=" .. tostring(alreadyMessage or ""))
    return
  end
  local okMove, moveMessage = baseLootMoveItem(job.inventoryUsers or {}, chest, item, params, job.live)
  if okMove then
    job.moved = (job.moved or 0) + 1
    return
  end
  local canStage = params.controlledRelocate == true and (job.staged or 0) < (tonumber(params.controlledRelocateMaxPerRun) or 25)
  local relocated, relocateMessage = false, "controlled relocate not attempted"
  if canStage then
    relocated, relocateMessage = baseLootControlledRelocateItem(item, chest, job.live, params)
  end
  if relocated then
    job.staged = (job.staged or 0) + 1
    table.insert(job.stagedRows, { item = item, chest = chest, originalError = tostring(moveMessage or ""), relocateMessage = tostring(relocateMessage or "") })
    return
  end
  job.failed = (job.failed or 0) + 1
  if tostring(job.firstError or "") == "" then
    job.firstError = tostring(moveMessage or "") .. "; " .. tostring(relocateMessage or "")
  end
end

function baseLootJobMessage(job, finalPhase)
  local moved = tonumber((job or {}).moved) or 0
  local skipped = tonumber((job or {}).skipped) or 0
  local failed = tonumber((job or {}).failed) or 0
  local nearby = tonumber((job or {}).nearby) or 0
  if nearby > 0 then
    return baseLootMixedChestMessage(moved, nearby, true) or baseLootNearbyChestMessage(nearby, true)
  end
  if moved > 0 or ((job or {}).params or {}).dryRun then
    return applyVars(baseLootString({ "SuccessMessage", "successMessage" }, "[Лут] Перемещено: {Moved}. Пропущено: {Skipped}."), {
      Moved = tostring(moved),
      moved = tostring(moved),
      Skipped = tostring(skipped),
      skipped = tostring(skipped),
      Failed = tostring(failed),
      failed = tostring(failed),
      Chests = tostring(#((job or {}).chests or {})),
      chests = tostring(#((job or {}).chests or {})),
      Scanned = tostring((job or {}).scannedItems or 0),
      scanned = tostring((job or {}).scannedItems or 0)
    })
  end
  if failed > 0 then return "[Лут] Не удалось перенести вещи. Детали записаны в журнал администратора." end
  return baseLootString({ "EmptyMessage", "emptyMessage" }, "[Лут] Подходящего лута рядом с флагом не найдено.")
end

function baseLootFinishAsyncJob(job)
  if job == nil then return end
  baseLootClearActive(job.activeKey)
  rememberCooldown(BASE_LOOT_COOLDOWN_FILE, job.live or {}, (job.params or {}).cooldown)
  local okAny = (tonumber(job.moved) or 0) > 0 or (tonumber(job.nearby) or 0) > 0 or ((job.params or {}).dryRun == true)
  local message = baseLootJobMessage(job, "final")
  message = baseLootPlayerMessage(message, (tonumber(job.nearby) or 0) + (tonumber(job.failed) or 0), true)
  targetMessageResolved(job.live, message)
  appendJsonArray(STATE_DIR .. "\\" .. BASE_LOOT_STATE_FILE,
    '{"utc":' .. js(nowUtc()) ..
    ',"steamId":' .. js((job.live or {}).steam or "") ..
    ',"name":' .. js((job.live or {}).name or "") ..
    ',"baseId":' .. js((job.flag or {}).baseId or "") ..
    ',"radius":' .. tostring((job.params or {}).radius or 0) ..
    ',"moved":' .. tostring(job.moved or 0) ..
    ',"skipped":' .. tostring(job.skipped or 0) ..
    ',"failed":' .. tostring(job.failed or 0) ..
    ',"nearby":' .. tostring(job.nearby or 0) ..
    ',"staged":' .. tostring(job.staged or 0) ..
    ',"phase":"async-complete"' ..
    ',"scannedItems":' .. tostring(job.scannedItems or 0) ..
    ',"scannedChests":' .. tostring(job.scannedChests or 0) ..
    ',"itemScanMs":' .. tostring((job.params or {})._itemScanMs or 0) ..
    ',"chestScanMs":' .. tostring((job.params or {})._chestScanMs or 0) ..
    ',"dryRun":' .. tostring((job.params or {}).dryRun == true) ..
    ',"error":' .. js(job.firstError or "") .. '}',
    1024 * 1024)
  appendActionEvent("base_loot_collector", okAny, job.live, message,
    '{"moved":' .. tostring(job.moved or 0) ..
    ',"skipped":' .. tostring(job.skipped or 0) ..
    ',"failed":' .. tostring(job.failed or 0) ..
    ',"nearby":' .. tostring(job.nearby or 0) ..
    ',"staged":' .. tostring(job.staged or 0) ..
    ',"phase":"async-complete","baseId":' .. js((job.flag or {}).baseId or "") ..
    ',"error":' .. js(job.firstError or "") .. '}')
  if job.queueItem ~= nil then
    finishMutationQueueAsync(job.queueItem, okAny, "Сбор лута базы завершён.")
  end
end

function baseLootRunAsyncStaged(job)
  if job == nil then return end
  if job.queueItem ~= nil then job.queueItem.startedAt = os.time() end
  baseLootMarkActive(job.activeKey)
  local stagedRows = job.stagedRows or {}
  local stagedIndex = math.max(1, math.floor(tonumber(job.stagedIndex) or 1))
  local inventoryUsers = baseLootInventoryUsers(job.live)
  local started = baseLootStartTimer()
  local processed = 0
  local batch = math.max(1, tonumber((job.params or {}).batchItemsPerTick) or 1)
  local budget = math.max(20, tonumber((job.params or {}).moveWorkBudgetMs) or 90)
  while stagedIndex <= #stagedRows do
    if processed >= batch then break end
    if processed > 0 and baseLootBudgetExceeded(started, budget) then break end
    local row = stagedRows[stagedIndex]
    stagedIndex = stagedIndex + 1
    job.stagedIndex = stagedIndex
    processed = processed + 1
    local item = row.item
    local chest = row.chest
    baseLootRefreshItemLocation(item)
    local okMove, moveMessage = baseLootTryMoveWithInventoryUsers(inventoryUsers, chest, item, job.params or {}, job.live)
    if okMove then
      job.moved = (job.moved or 0) + 1
    else
      local nearChest, verifyMessage = baseLootVerifyItemNearChest(item, chest, job.params or {})
      if nearChest then
        job.nearby = (job.nearby or 0) + 1
        appendLog("base-loot async delayed move remains-near-chest item=" .. tostring(item and item.haystack or "") ..
          " chest=" .. tostring(chest and chest.name or "") ..
          " verify=" .. tostring(verifyMessage or ""))
      else
        job.failed = (job.failed or 0) + 1
        if tostring(job.firstError or "") == "" then
          job.firstError = tostring(moveMessage or "") .. "; " .. tostring(verifyMessage or "")
        end
        appendLog("base-loot async delayed move not verified item=" .. tostring(item and item.haystack or "") ..
          " chest=" .. tostring(chest and chest.name or "") ..
          " itemChestCm=" .. tostring(math.floor(tonumber(baseLootDistanceToChest(item, chest)) or 0)) ..
          " error=" .. tostring(moveMessage or "") ..
          " verify=" .. tostring(verifyMessage or ""))
      end
    end
  end
  if stagedIndex <= #stagedRows then
    if deferGame((job.params or {}).batchDelayMs or 200, function()
      baseLootRunAsyncStaged(job)
    end) then return end
    job.failed = (job.failed or 0) + math.max(0, #stagedRows - stagedIndex + 1)
    if tostring(job.firstError or "") == "" then job.firstError = "async controlled relocate step was not scheduled" end
  end
  baseLootFinishAsyncJob(job)
end

function baseLootScheduleAsyncStep(job, delayMs)
  if job == nil then return false end
  return deferGame(delayMs or (job.params or {}).batchDelayMs or 200, function()
    baseLootRunAsyncStep(job)
  end)
end

function baseLootRunAsyncStep(job)
  if job == nil then return end
  if job.queueItem ~= nil then job.queueItem.startedAt = os.time() end
  baseLootMarkActive(job.activeKey)
  appendLog("base-loot async step begin index=" .. tostring(job.index or 1) ..
    " items=" .. tostring(#(job.items or {})) ..
    " moved=" .. tostring(job.moved or 0) ..
    " staged=" .. tostring(job.staged or 0) ..
    " failed=" .. tostring(job.failed or 0))
  if gameThreadSchedulerStalled() and #(job.items or {}) > (tonumber((job.params or {}).batchItemsPerTick) or 4) then
    baseLootClearActive(job.activeKey)
    local message = "[Лут] Игровой scheduler недоступен, безопасный фоновый сбор невозможен."
    targetMessageResolved(job.live, message)
    appendLog("base-loot async stopped because scheduler is stalled items=" .. tostring(#(job.items or {})))
    if job.queueItem ~= nil then finishMutationQueueAsync(job.queueItem, false, message) end
    return
  end
  local started = baseLootStartTimer()
  local processed = 0
  local batch = math.max(1, tonumber((job.params or {}).batchItemsPerTick) or 4)
  local budget = math.max(20, tonumber((job.params or {}).moveWorkBudgetMs) or 90)
  while (job.index or 1) <= #(job.items or {}) do
    if processed >= batch then break end
    if processed > 0 and baseLootBudgetExceeded(started, budget) then break end
    local item = job.items[job.index]
    job.index = (job.index or 1) + 1
    processed = processed + 1
    baseLootJobMoveOne(job, item)
  end
  if (job.index or 1) <= #(job.items or {}) then
    if not baseLootScheduleAsyncStep(job, (job.params or {}).batchDelayMs) then
      job.failed = (job.failed or 0) + math.max(0, #(job.items or {}) - (job.index or 1) + 1)
      if tostring(job.firstError or "") == "" then job.firstError = "async base loot step was not scheduled" end
      baseLootFinishAsyncJob(job)
    end
    return
  end
  if #(job.stagedRows or {}) > 0 then
    if not deferGame((job.params or {}).controlledRelocateDelayMs or 1200, function()
      baseLootRunAsyncStaged(job)
    end) then
      job.failed = (job.failed or 0) + #(job.stagedRows or {})
      if tostring(job.firstError or "") == "" then job.firstError = "async controlled relocate delayed task was not scheduled" end
      baseLootFinishAsyncJob(job)
    end
    return
  end
  baseLootFinishAsyncJob(job)
end

function baseLootStartAsyncJob(queueItem, live, flag, params, chests, scannedChests, inventoryUsers, items, scannedItems, activeKey)
  local job = {
    queueItem = queueItem,
    live = live,
    flag = flag,
    params = params,
    chests = chests or {},
    scannedChests = scannedChests or 0,
    inventoryUsers = inventoryUsers or {},
    items = items or {},
    scannedItems = scannedItems or 0,
    activeKey = activeKey,
    index = 1,
    moved = 0,
    skipped = 0,
    failed = 0,
    staged = 0,
    nearby = 0,
    stagedRows = {},
    firstError = "",
    noChestLogs = 0
  }
  targetMessageResolved(live, "[Лут] Сбор запущен. Найдено предметов: " .. tostring(#(items or {})) .. ". Я сам завершу задачу.")
  if not baseLootScheduleAsyncStep(job, 1) then
    baseLootClearActive(activeKey)
    return false, "[Лут] Не удалось запустить фоновый сбор."
  end
  return "__mutation_async__"
end

function baseLootNativeGateIsStale(queueItem)
  if queueItem == nil then return false end
  if queueItem.cancelled == true or MUTATION_QUEUE_CURRENT ~= queueItem then
    appendLog("base-loot native gate ignored stale queue id=" .. tostring(queueItem.id or "") .. " label=" .. tostring(queueItem.label or ""))
    return true
  end
  queueItem.startedAt = os.time()
  return false
end

function baseLootFinishNativeGate(queueItem, live, okRun, message)
  if baseLootNativeGateIsStale(queueItem) then return end
  local text = tostring(message or ((okRun == true) and "Готово." or "Не выполнено."))
  targetMessageResolved(live, text)
  if queueItem ~= nil then finishMutationQueueAsync(queueItem, okRun == true, text) end
end

function baseLootResumeAfterNativeGate(info, mode, queueItem, live, flag, params)
  if baseLootNativeGateIsStale(queueItem) then return end
  local okCall, okRun, message = pcall(function()
    return baseLootRun(info, mode, queueItem, { live = live, flag = flag, params = params })
  end)
  if not okCall then
    appendLog("base-loot async gate resume failed mode=" .. tostring(mode or "") ..
      " player=" .. tostring((live or {}).name or (live or {}).steam or "") ..
      " err=" .. tostring(okRun))
    appendActionEvent("base_loot_collector", false, live, "base loot async gate failed",
      '{"stage":"native-gate-resume","mode":' .. js(mode or "") .. ',"error":' .. js(tostring(okRun or "")) .. '}')
    baseLootFinishNativeGate(queueItem, live, false, "[Лут] Сбор не завершился безопасно. Повтори команду через несколько секунд.")
    return
  end
  if okRun == "__mutation_async__" then return end
  baseLootFinishNativeGate(queueItem, live, okRun == true, message)
end

function baseLootStartNativeGate(info, mode, queueItem, live, params)
  local started = baseLootCurrentFlagAsync(live, params, function(flag, nearestMessage, nearestDbProblem, nearestResult)
    if baseLootNativeGateIsStale(queueItem) then return end
    if flag == nil then
      local message = baseLootString({ "NoFlagMessage", "noFlagMessage" }, "[Лут] Встань внутри зоны своего флага.")
      appendActionEvent("base_loot_collector", false, live, message,
        '{"stage":"nearest-flag","radius":' .. tostring(params.radius) ..
        ',"dbProblem":' .. ((nearestDbProblem == true) and "true" or "false") ..
        ',"reason":' .. js(tostring(nearestMessage or "")) ..
        ',"nativeResponse":' .. js(tostring(nearestResult or "{}")) .. '}')
      baseLootFinishNativeGate(queueItem, live, false, message)
      return
    end
    baseLootStageLog("nearest-flag-ok", live, "baseId=" .. tostring((flag or {}).baseId or "") ..
      " distance=" .. tostring(math.floor(tonumber((flag or {}).distance) or 0)) ..
      " zone=" .. tostring((flag or {}).zoneShape or "") ..
      " half=" .. tostring((flag or {}).zoneHalfExtentCm or ""))
    baseLootStageLog("access-start", live, "baseId=" .. tostring((flag or {}).baseId or ""))
    baseLootAccessForFlagAsync(live, flag, function(accessOk, accessMessage, dbProblem, accessResult)
      if baseLootNativeGateIsStale(queueItem) then return end
      if not accessOk then
        local message = nil
        if dbProblem then
          message = baseLootString({ "DbUnavailableMessage", "dbUnavailableMessage" }, "[Лут] Проверка владельца флага недоступна: настрой SQLite в панели.") .. " (" .. tostring(accessMessage or "") .. ")"
        else
          message = baseLootString({ "AccessDeniedMessage", "accessDeniedMessage" }, "[Лут] Сбор доступен только участникам отряда владельца флага.")
        end
        appendActionEvent("base_loot_collector", false, live, message,
          '{"stage":"access","dbProblem":' .. ((dbProblem == true) and "true" or "false") ..
          ',"baseId":' .. js((flag or {}).baseId or "") ..
          ',"reason":' .. js(tostring(accessMessage or "")) ..
          ',"nativeResponse":' .. js(tostring(accessResult or "{}")) .. '}')
        baseLootFinishNativeGate(queueItem, live, false, message)
        return
      end
      baseLootStageLog("access-ok", live, "baseId=" .. tostring((flag or {}).baseId or ""))
      baseLootResumeAfterNativeGate(info, mode, queueItem, live, flag, params)
    end)
  end)
  if not started then
    appendLog("base-loot native gate did not queue player=" .. tostring((live or {}).name or (live or {}).steam or ""))
  end
  return started
end

function baseLootRun(info, mode, queueItem, asyncGate)
  baseLootStageLog("enter", info, "mode=" .. tostring(mode or ""))
  local params = (asyncGate and asyncGate.params) or baseLootParams(info)
  baseLootStageLog("params", info, "radius=" .. tostring(params.radius) ..
    " flagZone=" .. tostring(params.flagZoneShape or "") ..
    " half=" .. tostring(params.flagZoneHalfExtentCm or "") ..
    " lookupRadius=" .. tostring(params.flagLookupRadiusCm or "") ..
    " maxItems=" .. tostring(params.maxItems))
  local live = asyncGate and asyncGate.live or nil
  local flag = asyncGate and asyncGate.flag or nil
  if asyncGate == nil then
    local preflightMessage = nil
    live, preflightMessage = baseLootResolveLiveForRun(info, mode)
    if live == nil then
      return false, tostring(preflightMessage or "[Лут] Игрок не готов для безопасного сбора.")
    end
    baseLootStageLog("preflight-ok", live, "mode=" .. tostring(mode or ""))
    baseLootStageLog("nearest-flag-start", live, "radius=" .. tostring(params.radius) ..
      " lookupRadius=" .. tostring(params.flagLookupRadiusCm or params.radius))
    baseLootStartNativeGate(info, mode, queueItem, live, params)
    return "__mutation_async__"
  end

  local activeKey = baseLootActiveKey(live, flag)
  if baseLootActiveBusy(activeKey, params) then
    return false, "[Лут] Предыдущий сбор у этого флага ещё завершается. Подожди несколько секунд."
  end
  baseLootMarkActive(activeKey)

  -- Resolve the bounded actor set once. Chests, loose items and the optional
  -- probe below consume this same set; normal /loot cannot issue a second
  -- world-wide item enumeration.
  baseLootStageLog("overlap-start", live, "baseId=" .. tostring((flag or {}).baseId or ""))
  local okOverlap, overlap = pcall(function() return baseLootOverlapItemActors(live, flag, params) end)
  if not okOverlap or overlap == nil or overlap.ok ~= true then
    baseLootClearActive(activeKey)
    local detail = okOverlap and tostring((overlap or {}).error or "unavailable") or tostring(overlap or "error")
    local message = "[Лут] Безопасное локальное сканирование недоступно. Повтори позже."
    appendLog("base-loot overlap unavailable baseId=" .. tostring((flag or {}).baseId or "") .. " error=" .. detail)
    appendActionEvent("base_loot_collector", false, live, message,
      '{"stage":"overlap","baseId":' .. js((flag or {}).baseId or "") .. ',"error":' .. js(detail) .. '}')
    return false, message
  end
  baseLootStageLog("overlap-ok", live, "actors=" .. tostring(#(overlap.actors or {})) ..
    " raw=" .. tostring(overlap.rawCount or 0) ..
    " ms=" .. tostring(overlap.elapsedMs or 0) ..
    " limited=" .. tostring(overlap.limited == true))

  baseLootStageLog("chests-start", live, "baseId=" .. tostring((flag or {}).baseId or ""))
  local okChests, chests, scannedChests = pcall(function() return baseLootChests(flag, params, overlap) end)
  if not okChests then
    baseLootClearActive(activeKey)
    local message = "[Лут] Скан сундуков не выполнен. Повтори позже."
    appendLog("base-loot chest scan error baseId=" .. tostring((flag or {}).baseId or "") .. " err=" .. tostring(chests))
    appendActionEvent("base_loot_collector", false, live, message,
      '{"stage":"chests","baseId":' .. js((flag or {}).baseId or "") .. ',"error":' .. js(tostring(chests or "")) .. '}')
    return false, message
  end
  chests = chests or {}
  baseLootStageLog("chests-ok", live, "found=" .. tostring(#chests) .. " scanned=" .. tostring(scannedChests or 0))
  if tostring(mode or "") == "chests" then
    local names = {}
    for _, chest in ipairs(chests) do table.insert(names, chest.name ~= "" and chest.name or "Chest") end
    if #chests > 0 and baseLootBool({ "FirstReflectedPropertyProbeEnabled", "firstReflectedPropertyProbeEnabled" }, false) == true then
      local okProbe, probeMessage, probeData = baseLootFirstReflectedPropertyProbe(chests[1], baseLootNumber({ "FirstReflectedPropertyProbeTimeoutMs", "firstReflectedPropertyProbeTimeoutMs" }, 1200))
      appendLog("base-loot first reflected property probe ok=" .. tostring(okProbe) ..
        " message=" .. tostring(probeMessage or "") ..
        " data=" .. tostring(probeData or "{}"):sub(1, 1200))
      appendActionEvent("base_loot_first_reflected_property_probe", okProbe == true, live, tostring(probeMessage or ""),
        tostring(probeData or "{}"))
    end
    local suffix = (params._chestScanLimited == true) and " Скан ограничен для стабильности, повтори позже." or ""
    local message = "[Лут] Сундуки в радиусе: " .. tostring(#chests) .. "/" .. tostring(scannedChests) .. ". " .. table.concat(names, ", ") .. suffix
    appendLog("base-loot chests result player=" .. tostring((live or {}).name or "") ..
      " baseId=" .. tostring((flag or {}).baseId or "") ..
      " chests=" .. tostring(#chests) ..
      " scanned=" .. tostring(scannedChests or 0) ..
      " limited=" .. tostring(params._chestScanLimited == true) ..
      " ms=" .. tostring(params._chestScanMs or 0) ..
      " names=" .. table.concat(names, "|"))
    appendActionEvent("base_loot_chests", #chests > 0, live, message,
      '{"chests":' .. tostring(#chests) .. ',"scannedChests":' .. tostring(scannedChests or 0) ..
      ',"baseId":' .. js((flag or {}).baseId or "") ..
      ',"limited":' .. ((params._chestScanLimited == true) and "true" or "false") ..
      ',"names":' .. js(table.concat(names, "|")) .. '}')
    baseLootClearActive(activeKey)
    return true, message
  end
  if tostring(mode or "") == "probe" then
    local okItems, items, scannedItems = pcall(function() return baseLootItems(flag, params, overlap) end)
    if not okItems then
      baseLootClearActive(activeKey)
      local message = "[Лут] Probe не выполнен. Повтори позже."
      appendLog("base-loot probe item scan error baseId=" .. tostring((flag or {}).baseId or "") .. " err=" .. tostring(items))
      return false, message
    end
    local okProbe, probeMessage = baseLootProbeInventoryLocations(chests, items, params, live, flag, scannedChests, scannedItems, overlap)
    baseLootClearActive(activeKey)
    return okProbe, probeMessage
  end
  if #chests == 0 then
    local message = "[Лут] В радиусе флага не найдено сундуков."
    appendActionEvent("base_loot_collector", false, live, message,
      '{"stage":"chests","chests":0,"scannedChests":' .. tostring(scannedChests or 0) ..
      ',"baseId":' .. js((flag or {}).baseId or "") .. '}')
    baseLootClearActive(activeKey)
    return false, message
  end

  baseLootStageLog("inventory-users-start", live, "baseId=" .. tostring((flag or {}).baseId or ""))
  local inventoryUsers = baseLootInventoryUsers(live)
  baseLootStageLog("inventory-users-ok", live, "count=" .. tostring(#(inventoryUsers or {})))
  baseLootStageLog("items-start", live, "baseId=" .. tostring((flag or {}).baseId or ""))
  local okItems, items, scannedItems = pcall(function() return baseLootScanItems(flag, params, chests, overlap) end)
  if not okItems then
    baseLootClearActive(activeKey)
    local message = "[Лут] Скан лута не выполнен. Повтори позже."
    appendLog("base-loot item scan error baseId=" .. tostring((flag or {}).baseId or "") .. " err=" .. tostring(items))
    appendActionEvent("base_loot_collector", false, live, message,
      '{"stage":"items","baseId":' .. js((flag or {}).baseId or "") .. ',"error":' .. js(tostring(items or "")) .. '}')
    return false, message
  end
  items = items or {}
  baseLootStageLog("items-ok", live, "found=" .. tostring(#items) .. " scanned=" .. tostring(scannedItems or 0))
  if queueItem ~= nil then
    return baseLootStartAsyncJob(queueItem, live, flag, params, chests, scannedChests, inventoryUsers, items, scannedItems, activeKey)
  end
  local moved, skipped, failed, staged = 0, 0, 0, 0
  local stagedRows = {}
  local firstError = ""
  local noChestLogs = 0
  local moveStarted = baseLootStartTimer()
  local processedItems = 0
  for _, item in ipairs(items) do
    processedItems = processedItems + 1
    if processedItems > 1 and baseLootBudgetExceeded(moveStarted, params.moveWorkBudgetMs) then
      skipped = skipped + math.max(0, #items - processedItems + 1)
      baseLootMarkLimited(params, "_moveWorkLimited")
      appendLog("base-loot move budget hit processed=" .. tostring(processedItems - 1) ..
        " totalItems=" .. tostring(#items) ..
        " moved=" .. tostring(moved) ..
        " staged=" .. tostring(staged) ..
        " failed=" .. tostring(failed) ..
        " ms=" .. tostring(baseLootElapsedMs(moveStarted)) ..
        " budgetMs=" .. tostring(params.moveWorkBudgetMs or 0))
      break
    end
    if (moved + staged + failed) >= params.maxItems then
      skipped = skipped + 1
    else
      local chestName = baseLootRuleChestName(item.haystack, params)
      local chest = baseLootChestForName(chests, chestName, params.nameContains, item)
      if chest == nil and params.fallbackToDefaultChest and tostring(chestName or ""):lower() ~= tostring(params.defaultChest or ""):lower() then
        chest = baseLootChestForName(chests, params.defaultChest, params.nameContains, item)
      end
      if chest == nil then
        skipped = skipped + 1
        if noChestLogs < 5 then
          noChestLogs = noChestLogs + 1
          local names = {}
          for _, knownChest in ipairs(chests or {}) do table.insert(names, tostring(knownChest.name or "")) end
          appendLog("base-loot no chest match wanted=" .. tostring(chestName or "") ..
            " default=" .. tostring(params.defaultChest or "") ..
            " chests=[" .. table.concat(names, "|") .. "] item=" .. tostring(item.haystack or ""))
        end
      else
        local alreadyNear, alreadyMessage = baseLootVerifyItemNearChest(item, chest, params)
        if alreadyNear then
          skipped = skipped + 1
          appendLog("base-loot sync item already near chest item=" .. tostring(item.haystack or "") ..
            " chest=" .. tostring(chest.name or "") ..
            " verify=" .. tostring(alreadyMessage or ""))
        else
          local okMove, moveMessage = baseLootMoveItem(inventoryUsers, chest, item, params, live)
          if okMove then
            moved = moved + 1
          else
            local canStage = params.controlledRelocate == true and staged < params.controlledRelocateMaxPerRun
            local relocated, relocateMessage = false, "controlled relocate not attempted"
            if canStage then
              relocated, relocateMessage = baseLootControlledRelocateItem(item, chest, live, params)
            end
            if relocated then
              staged = staged + 1
              table.insert(stagedRows, { item = item, chest = chest, originalError = tostring(moveMessage or ""), relocateMessage = tostring(relocateMessage or "") })
            else
              failed = failed + 1
              if firstError == "" then firstError = tostring(moveMessage or "") .. "; " .. tostring(relocateMessage or "") end
            end
          end
        end
      end
    end
  end

  local cooldownSeconds = (params._limited == true) and (params.limitedCooldownSeconds or 10) or params.cooldown
  rememberCooldown(BASE_LOOT_COOLDOWN_FILE, live, cooldownSeconds)
  local scheduledRelocate = false
  local preparedNearChest = staged
  if staged > 0 then
    scheduledRelocate = deferGame(params.controlledRelocateDelayMs, function()
      baseLootFinishRelocatedBatch(activeKey, live, stagedRows, params, flag, scannedItems, scannedChests)
    end)
    if not scheduledRelocate then
      baseLootClearActive(activeKey)
      failed = failed + staged
      staged = 0
      if firstError == "" then firstError = "controlled relocate delayed task was not scheduled" end
    end
  else
    baseLootClearActive(activeKey)
  end
  local okAny = moved > 0 or staged > 0 or preparedNearChest > 0 or params.dryRun
  local message = ""
  if staged > 0 then
    message = baseLootMixedChestMessage(moved, staged, false) or baseLootNearbyChestMessage(staged, false)
  elseif preparedNearChest > 0 and failed > 0 then
    message = baseLootMixedChestMessage(moved, preparedNearChest, true) or baseLootNearbyChestMessage(preparedNearChest, true)
  elseif okAny then
    message = applyVars(baseLootString({ "SuccessMessage", "successMessage" }, "[Лут] Перемещено: {Moved}. Пропущено: {Skipped}."), {
      Moved = tostring(moved),
      moved = tostring(moved),
      Skipped = tostring(skipped),
      skipped = tostring(skipped),
      Failed = tostring(failed),
      failed = tostring(failed),
      Chests = tostring(#chests),
      chests = tostring(#chests),
      Scanned = tostring(scannedItems),
      scanned = tostring(scannedItems)
    })
  else
    message = failed > 0 and "[Лут] Не удалось перенести вещи. Детали записаны в журнал администратора." or baseLootString({ "EmptyMessage", "emptyMessage" }, "[Лут] Подходящего лута рядом с флагом не найдено.")
  end
  local nearbyFallbackCount = staged > 0 and staged or (preparedNearChest > 0 and preparedNearChest or failed)
  message = baseLootPlayerMessage(message, nearbyFallbackCount, staged <= 0)
  message = message .. baseLootLimitedSuffix(params)
  appendJsonArray(STATE_DIR .. "\\" .. BASE_LOOT_STATE_FILE,
    '{"utc":' .. js(nowUtc()) ..
    ',"steamId":' .. js((live or {}).steam or "") ..
    ',"name":' .. js((live or {}).name or "") ..
    ',"baseId":' .. js((flag or {}).baseId or "") ..
    ',"radius":' .. tostring(params.radius) ..
    ',"moved":' .. tostring(moved) ..
    ',"skipped":' .. tostring(skipped) ..
    ',"failed":' .. tostring(failed) ..
    ',"staged":' .. tostring(staged) ..
    ',"phase":' .. js(staged > 0 and "controlled-relocate-start" or "direct") ..
    ',"scannedItems":' .. tostring(scannedItems or 0) ..
    ',"scannedChests":' .. tostring(scannedChests or 0) ..
    ',"limited":' .. ((params._limited == true) and "true" or "false") ..
    ',"itemScanMs":' .. tostring(params._itemScanMs or 0) ..
    ',"chestScanMs":' .. tostring(params._chestScanMs or 0) ..
    ',"dryRun":' .. tostring(params.dryRun) ..
    ',"error":' .. js(firstError) .. '}',
    1024 * 1024)
  appendActionEvent("base_loot_collector", okAny, live, message,
    '{"moved":' .. tostring(moved) .. ',"skipped":' .. tostring(skipped) .. ',"failed":' .. tostring(failed) ..
    ',"staged":' .. tostring(staged) ..
    ',"phase":' .. js(staged > 0 and "controlled-relocate-start" or "direct") ..
    ',"baseId":' .. js((flag or {}).baseId or "") ..
    ',"limited":' .. ((params._limited == true) and "true" or "false") ..
    ',"error":' .. js(firstError) .. '}')
  return okAny, message
end

function handleBaseLootCommand(info, words)
  if not moduleEnabled("base-loot-collector", false) then
    targetMessageResolved(info, "Сбор лута базы сейчас отключён.")
    return true
  end
  local required = baseLootString({ "RequiredPermission", "requiredPermission" }, "")
  if not hasPermission(info, required) then
    targetMessageResolved(info, permissionDeniedText(required))
    return true
  end
  local sub = tostring(words[2] or ""):lower()
  if sub == "help" or sub == "?" then
    targetMessageResolved(info, "Формат: " .. commandUsage("baseloot") .. " - собрать лут у своего флага; " .. commandUsage("baseloot", " chests") .. " - показать сундуки; " .. commandUsage("baseloot", " status") .. " - настройки.")
    return true
  end
  local params = baseLootParams(info)
  if sub == "status" then
    local cooldown = cooldownRemaining(BASE_LOOT_COOLDOWN_FILE, info, params.cooldown)
    targetMessageResolved(info, "[Лут] Радиус " .. tostring(params.radius) .. " см, лимит " .. tostring(params.maxItems) .. ", кулдаун " .. tostring(cooldown) .. " сек.")
    return true
  end
  local cooldown = cooldownRemaining(BASE_LOOT_COOLDOWN_FILE, info, params.cooldown)
  if cooldown > 0 then
    targetMessageResolved(info, "Сбор лута на кулдауне. Подожди " .. tostring(cooldown) .. " сек.")
    return true
  end
  local mode = sub == "chests" and "chests" or (sub == "probe" and "probe" or "collect")
  local queued, queueIdOrMessage = enqueueMutation("base-loot-collector", info, function(queueItem)
    local okCall, okRun, message = pcall(function()
      return baseLootRun(info, mode, queueItem)
    end)
    if not okCall then
      appendLog("base-loot run pcall failed mode=" .. tostring(mode or "") ..
        " player=" .. tostring((info or {}).name or (info or {}).steam or "") ..
        " err=" .. tostring(okRun))
      appendActionEvent("base_loot_collector", false, info, "base loot run failed",
        '{"stage":"pcall","mode":' .. js(mode or "") .. ',"error":' .. js(tostring(okRun or "")) .. '}')
      targetMessageResolved(info, "[Лут] Сбор не завершился безопасно. Повтори команду через несколько секунд.")
      return
    end
    if okRun == "__mutation_async__" then return "__mutation_async__" end
    targetMessageResolved(info, tostring(message or (okRun and "Готово." or "Не выполнено.")))
  end)
  targetMessageResolved(info, queued and "[Лут] Заявка поставлена в очередь." or tostring(queueIdOrMessage))
  return true
end

function playerStateKey(info)
  if info == nil then return "" end
  if tostring(info.steam or "") ~= "" then return "steam:" .. tostring(info.steam) end
  if tostring(info.userProfileId or info.serverUserProfileId or "") ~= "" then return "profile:" .. tostring(info.userProfileId or info.serverUserProfileId) end
  if tostring(info.name or "") ~= "" then return "name:" .. tostring(info.name):lower() end
  return ""
end

function playerCommandSelector(info)
  local steam = valueText((info or {}).steam or (info or {}).steamId or "")
  if looksLikeSteamId(steam) then return steam end
  local name = valueText((info or {}).name or "")
  if name ~= "" and name ~= "Unknown" then return name end
  return ""
end

function displayPlayerName(info, fallback)
  local name = valueText((info or {}).name or "")
  if name ~= "" and name ~= "Unknown" then return name end
  local steam = valueText((info or {}).steam or (info or {}).steamId or "")
  if steam ~= "" then return steam end
  return tostring(fallback or "игрок")
end

function moduleArrayObjects(moduleKey, arrayKey)
  local text = configText(moduleKey)
  if text == nil or text == "" then return {} end
  local rows = jsonArrayObjects(text, arrayKey)
  if #rows == 0 then rows = jsonArrayObjects(text, arrayKey:sub(1, 1):lower() .. arrayKey:sub(2)) end
  return rows
end

function moneyTransferFindTarget(selector)
  local target = trimText(selector)
  if target == "" then return nil end
  local live = nil
  if looksLikeSteamId(target) then live = findPlayer(target, nil) end
  if live == nil then live = findPlayer(nil, target) end
  if live == nil then live = resolvePlayerInfo(looksLikeSteamId(target) and target or nil, looksLikeSteamId(target) and nil or target, nil, nil) end
  return live
end

function moneyTransferDailySpent(info)
  local today = os.date("!%Y-%m-%d")
  local steam = valueText((info or {}).steam or "")
  local name = valueText((info or {}).name or "")
  local total = 0
  for _, object in ipairs(stateObjects("money-transfer.json")) do
    if extractStringAny(object, { "date", "Date" }) == today then
      local senderSteam = extractStringAny(object, { "senderSteam", "SenderSteam", "steamId", "SteamId" }) or ""
      local senderName = extractStringAny(object, { "senderName", "SenderName", "name", "Name" }) or ""
      if (steam ~= "" and senderSteam == steam) or (steam == "" and name ~= "" and senderName == name) then
        total = total + math.max(0, extractNumberAny(object, { "amount", "Amount" }, 0) or 0)
      end
    end
  end
  return total
end

function handleMoneyTransferCommand(info, words)
  if not moduleEnabled("money-transfer", true) then
    targetMessageResolved(info, "Переводы денег сейчас отключены.")
    return true
  end
  local required = configString("money-transfer", { "RequiredPermission", "requiredPermission" }, "")
  if not hasPermission(info, required) then
    targetMessageResolved(info, permissionDeniedText(required))
    return true
  end
  local targetText = trimText(words[2] or "")
  local amount = math.floor(tonumber(words[3] or "") or 0)
  if targetText == "" or amount <= 0 then
    local usage = configString("money-transfer", { "UsageMessage", "usageMessage" }, "")
    if usage == "" or usage == "Формат: /sendmoney <ник|SteamID> <сумма>." then
      usage = "Формат: " .. commandUsage("moneytransfer", " <ник|SteamID> <сумма>.")
    end
    targetMessageResolved(info, usage)
    return true
  end
  local minAmount = math.max(1, math.floor(configNumber("money-transfer", { "MinAmount", "minAmount" }, 1) or 1))
  local maxAmount = math.max(minAmount, math.floor(configNumber("money-transfer", { "MaxAmount", "maxAmount" }, 100000) or 100000))
  if amount < minAmount or amount > maxAmount then
    targetMessageResolved(info, "Сумма перевода должна быть от " .. tostring(minAmount) .. " до " .. tostring(maxAmount) .. ".")
    return true
  end
  local cooldown = cooldownRemaining("money-transfer-cooldowns.json", info, configNumber("money-transfer", { "CooldownSeconds", "cooldownSeconds" }, 30))
  if cooldown > 0 then
    targetMessageResolved(info, "Перевод денег на кулдауне. Подожди " .. tostring(cooldown) .. " сек.")
    return true
  end
  local dailyLimit = math.max(0, math.floor(configNumber("money-transfer", { "DailyLimit", "dailyLimit" }, 0) or 0))
  if dailyLimit > 0 and moneyTransferDailySpent(info) + amount > dailyLimit then
    targetMessageResolved(info, "Дневной лимит переводов исчерпан. Лимит: " .. tostring(dailyLimit) .. ".")
    return true
  end
  local target = moneyTransferFindTarget(targetText)
  if target == nil and configBool("money-transfer", { "RequireBothOnline", "requireBothOnline" }, true) then
    targetMessageResolved(info, "Получатель не найден онлайн.")
    return true
  end
  if target == nil then
    target = looksLikeSteamId(targetText) and { steam = targetText, name = targetText } or { name = targetText }
  end
  local senderKey = playerStateKey(info)
  local targetKey = playerStateKey(target)
  if configBool("money-transfer", { "AllowSelfTransfer", "allowSelfTransfer" }, false) ~= true and senderKey ~= "" and senderKey == targetKey then
    targetMessageResolved(info, "Нельзя перевести деньги самому себе.")
    return true
  end
  local feePercent = math.max(0, configNumber("money-transfer", { "FeePercent", "feePercent" }, 0) or 0)
  local feeFixed = math.max(0, math.floor(configNumber("money-transfer", { "FeeFixed", "feeFixed" }, 0) or 0))
  local fee = math.floor(amount * feePercent / 100 + feeFixed)
  local debit = amount + fee
  local currency = configString("money-transfer", { "Currency", "currency" }, "Normal")
  if currency:lower() == "gold" then currency = "Gold" else currency = "Normal" end
  local senderSelector = playerCommandSelector(info)
  local targetSelector = playerCommandSelector(target)
  if senderSelector == "" or targetSelector == "" then
    targetMessageResolved(info, "Перевод не выполнен: не удалось определить SteamID/ник отправителя или получателя.")
    return true
  end
  local senderName = displayPlayerName(info, "отправитель")
  local targetName = displayPlayerName(target, targetText)
  local queued, queueIdOrMessage = enqueueMutation("money-transfer", info, function()
    local liveSender = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
    local liveTarget = resolvePlayerInfo(target.steam, target.name, target, target.runtimeKey) or target
    local liveSenderSelector = playerCommandSelector(liveSender)
    local liveTargetSelector = playerCommandSelector(liveTarget)
    if liveSenderSelector == "" or liveTargetSelector == "" then
      appendActionEvent("money_transfer", false, liveSender, "missing selector", '{"target":' .. js(targetName) .. ',"amount":' .. tostring(amount) .. '}')
      return
    end
    local debitCommand = "ChangeCurrencyBalance " .. currency .. " -" .. tostring(debit) .. " " .. liveSenderSelector
    local okDebit, debitMessage = adminExec(debitCommand, liveSender)
    if not okDebit then
      appendActionEvent("money_transfer", false, liveSender, "debit failed: " .. tostring(debitMessage or ""), '{"target":' .. js(targetName) .. ',"amount":' .. tostring(amount) .. ',"debit":' .. tostring(debit) .. '}')
      targetMessageResolved(liveSender, "Перевод не выполнен: списание не прошло.")
      return
    end
    local creditCommand = "ChangeCurrencyBalance " .. currency .. " " .. tostring(amount) .. " " .. liveTargetSelector
    local okCredit, creditMessage = adminExec(creditCommand, liveTarget)
    if not okCredit then
      adminExec("ChangeCurrencyBalance " .. currency .. " " .. tostring(debit) .. " " .. liveSenderSelector, liveSender)
      appendActionEvent("money_transfer", false, liveSender, "credit failed, refund requested: " .. tostring(creditMessage or ""), '{"target":' .. js(targetName) .. ',"amount":' .. tostring(amount) .. ',"debit":' .. tostring(debit) .. '}')
      targetMessageResolved(liveSender, "Перевод не выполнен: зачисление не прошло, возврат отправлен.")
      return
    end
    rememberCooldown("money-transfer-cooldowns.json", liveSender)
    appendJsonArray(STATE_DIR .. "\\money-transfer.json",
      '{"utc":' .. js(nowUtc()) ..
      ',"date":' .. js(os.date("!%Y-%m-%d")) ..
      ',"senderSteam":' .. js(valueText(liveSender.steam or "")) ..
      ',"senderName":' .. js(displayPlayerName(liveSender, "")) ..
      ',"targetSteam":' .. js(valueText(liveTarget.steam or "")) ..
      ',"targetName":' .. js(displayPlayerName(liveTarget, "")) ..
      ',"amount":' .. tostring(amount) ..
      ',"fee":' .. tostring(fee) ..
      ',"currency":' .. js(currency) .. '}',
      1024 * 1024)
    local successText = applyVars(configString("money-transfer", { "SuccessMessage", "successMessage" }, "Перевод отправлен: ${amount} игроку {target}."), { amount = tostring(amount), target = targetName, sender = senderName })
    local receivedText = applyVars(configString("money-transfer", { "ReceivedMessage", "receivedMessage" }, "Получен перевод ${amount} от {sender}."), { amount = tostring(amount), target = targetName, sender = senderName })
    targetMessageResolved(liveSender, successText .. (fee > 0 and (" Комиссия: " .. tostring(fee) .. ".") or ""))
    targetMessageResolved(liveTarget, receivedText)
    appendActionEvent("money_transfer", true, liveSender, "transfer ok", '{"target":' .. js(targetName) .. ',"amount":' .. tostring(amount) .. ',"fee":' .. tostring(fee) .. ',"currency":' .. js(currency) .. '}')
  end)
  targetMessageResolved(info, queued and "Перевод поставлен в очередь." or tostring(queueIdOrMessage))
  return true
end

function itemUpgradeRuleByAlias(alias)
  local wanted = tostring(alias or ""):lower()
  for _, object in ipairs(moduleArrayObjects("item-upgrade", "Rules")) do
    if extractBoolAny(object, { "Enabled", "enabled" }, true) ~= false then
      local ruleAlias = tostring(extractStringAny(object, { "Alias", "alias" }) or ""):lower()
      local display = tostring(extractStringAny(object, { "DisplayName", "displayName", "Name", "name" }) or ""):lower()
      if wanted == "" or wanted == ruleAlias or wanted == display then return object end
    end
  end
  return nil
end

function itemUpgradeListText()
  local rows = {}
  for _, object in ipairs(moduleArrayObjects("item-upgrade", "Rules")) do
    if extractBoolAny(object, { "Enabled", "enabled" }, true) ~= false then
      local alias = extractStringAny(object, { "Alias", "alias" }) or ""
      local title = extractStringAny(object, { "DisplayName", "displayName", "Name", "name" }) or alias
      local source = extractStringAny(object, { "SourceItemId", "sourceItemId" }) or ""
      local result = extractStringAny(object, { "ResultItemId", "resultItemId" }) or ""
      local cost = extractNumberAny(object, { "CostMoney", "costMoney" }, 0) or 0
      local weight = extractNumberAny(object, { "Weight", "weight", "SpawnWeight", "spawnWeight", "ResultWeight", "resultWeight", "TargetWeight", "targetWeight" }, 0) or 0
      local modText = weight > 0 and (", weight " .. tostring(weight)) or ""
      table.insert(rows, commandUsage("itemupgrade", " " .. tostring(alias)) .. " - " .. tostring(title) .. " (" .. tostring(source) .. " -> " .. tostring(result) .. modText .. ", $" .. tostring(cost) .. ")")
    end
  end
  if #rows == 0 then return "Апгрейды пока не настроены." end
  return "Апгрейды: " .. table.concat(rows, " | ")
end

function itemUpgradeSpawnOptions(rule)
  rule = rule or {}
  return {
    weight = extractNumberAny(rule, { "Weight", "weight", "SpawnWeight", "spawnWeight", "ResultWeight", "resultWeight", "TargetWeight", "targetWeight" }, 0) or 0,
    health = extractNumberAny(rule, { "Health", "health", "ResultHealth", "resultHealth" }, 0) or 0,
    uses = extractNumberAny(rule, { "Uses", "uses", "ResultUses", "resultUses" }, 0) or 0,
    dirtiness = extractNumberAny(rule, { "Dirtiness", "dirtiness" }, 0) or 0,
    ammoCount = extractNumberAny(rule, { "AmmoCount", "ammoCount", "Ammo", "ammo" }, 0) or 0,
    cashValue = extractNumberAny(rule, { "CashValue", "cashValue" }, 0) or 0,
    keyCardSector = extractStringAny(rule, { "KeyCardSector", "keyCardSector" }) or ""
  }
end

function itemUpgradeHasSpawnModifier(options)
  options = options or {}
  return (tonumber(options.weight or 0) or 0) > 0 or
    (tonumber(options.health or 0) or 0) > 0 or
    (tonumber(options.uses or 0) or 0) > 0 or
    (tonumber(options.dirtiness or 0) or 0) > 0 or
    (tonumber(options.ammoCount or 0) or 0) > 0 or
    (tonumber(options.cashValue or 0) or 0) > 0 or
    trimText(options.keyCardSector or "") ~= ""
end

function handleItemUpgradeCommand(info, words)
  if not moduleEnabled("item-upgrade", false) then
    targetMessageResolved(info, "Апгрейд предметов сейчас отключён.")
    return true
  end
  local required = configString("item-upgrade", { "RequiredPermission", "requiredPermission" }, "")
  if not hasPermission(info, required) then
    targetMessageResolved(info, permissionDeniedText(required))
    return true
  end
  if configBool("item-upgrade", { "AllowReplacement", "allowReplacement" }, false) ~= true then
    targetMessageResolved(info, "Апгрейд предметов заблокирован защитой. Админ должен включить AllowReplacement в панели.")
    return true
  end
  local alias = trimText(words[2] or "")
  if alias == "" or alias == "list" then
    targetMessageResolved(info, itemUpgradeListText())
    return true
  end
  local rule = itemUpgradeRuleByAlias(alias)
  if rule == nil then
    targetMessageResolved(info, "Апгрейд не найден. " .. itemUpgradeListText())
    return true
  end
  local cooldown = cooldownRemaining("item-upgrade-cooldowns.json", info, configNumber("item-upgrade", { "CooldownSeconds", "cooldownSeconds" }, 60))
  if cooldown > 0 then
    targetMessageResolved(info, "Апгрейд на кулдауне. Подожди " .. tostring(cooldown) .. " сек.")
    return true
  end
  local sourceItem = extractStringAny(rule, { "SourceItemId", "sourceItemId" }) or ""
  local resultItem = extractStringAny(rule, { "ResultItemId", "resultItemId" }) or ""
  if sourceItem == "" or resultItem == "" then
    targetMessageResolved(info, "Апгрейд настроен неверно: SourceItemId/ResultItemId пустой.")
    return true
  end
  local spawnOptions = itemUpgradeSpawnOptions(rule)
  local hasSpawnModifier = itemUpgradeHasSpawnModifier(spawnOptions)
  if normalizeItemKey(sourceItem) == normalizeItemKey(resultItem) and
      not hasSpawnModifier and
      configBool("item-upgrade", { "AllowSameItemId", "allowSameItemId" }, false) ~= true then
    targetMessageResolved(info, "ResultItemId совпадает с SourceItemId, но параметры нового предмета не заданы. Укажите Weight/Health/Uses или отдельный ResultItemId.")
    return true
  end
  local costItem = extractStringAny(rule, { "RequiredCostItemId", "requiredCostItemId" }) or ""
  local costItemQty = math.floor(extractNumberAny(rule, { "RequiredCostItemQuantity", "requiredCostItemQuantity" }, 0) or 0)
  if costItem ~= "" and costItemQty > 0 then
    targetMessageResolved(info, "Предмет-стоимость пока не удаляется автоматически из инвентаря. Используйте денежную цену или отдельный проверенный режим.")
    return true
  end
  local queued, queueIdOrMessage = enqueueMutation("item-upgrade", info, function()
    local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
    local liveReady, ready, readyMessage = deliveryReadyInfo(live, { requireInventory = false })
    if not ready then
      targetMessageResolved(live, "Апгрейд не выполнен: персонаж ещё не готов. " .. tostring(readyMessage or ""))
      return
    end
    live = liveReady or live
    local held, heldRoute = itemInHandsObject(live, sourceItem, "", "")
    if held == nil then
      targetMessageResolved(live, "Апгрейд не выполнен: нужный предмет должен быть в руках. Ожидался " .. tostring(sourceItem) .. ".")
      appendActionEvent("item_upgrade", false, live, "source item not in hands: " .. tostring(heldRoute), '{"source":' .. js(sourceItem) .. ',"result":' .. js(resultItem) .. '}')
      return
    end
    local selector = playerCommandSelector(live)
    if selector == "" then
      targetMessageResolved(live, "Апгрейд не выполнен: не удалось определить игрока.")
      return
    end
    local money = math.max(0, math.floor(extractNumberAny(rule, { "CostMoney", "costMoney" }, 0) or 0))
    local gold = math.max(0, math.floor(extractNumberAny(rule, { "CostGold", "costGold" }, 0) or 0))
    local fame = math.floor(extractNumberAny(rule, { "CostFame", "costFame" }, 0) or 0)
    if money > 0 then
      local okMoney, moneyMessage = adminExec("ChangeCurrencyBalance Normal -" .. tostring(money) .. " " .. selector, live)
      if not okMoney then
        targetMessageResolved(live, "Апгрейд не выполнен: не удалось списать деньги.")
        appendActionEvent("item_upgrade", false, live, "money charge failed: " .. tostring(moneyMessage or ""), '{"source":' .. js(sourceItem) .. ',"result":' .. js(resultItem) .. '}')
        return
      end
    end
    if gold > 0 then
      local okGold, goldMessage = adminExec("ChangeCurrencyBalance Gold -" .. tostring(gold) .. " " .. selector, live)
      if not okGold then
        if money > 0 then adminExec("ChangeCurrencyBalance Normal " .. tostring(money) .. " " .. selector, live) end
        targetMessageResolved(live, "Апгрейд не выполнен: не удалось списать золото, возврат денег отправлен.")
        appendActionEvent("item_upgrade", false, live, "gold charge failed: " .. tostring(goldMessage or ""), '{"source":' .. js(sourceItem) .. ',"result":' .. js(resultItem) .. '}')
        return
      end
    end
    if fame > 0 then adminExec("ChangeFamePoints -" .. tostring(fame) .. " " .. selector, live) end
    local removed, removeMessage = destroyInventoryItemObject(held, live)
    if not removed then
      if money > 0 then adminExec("ChangeCurrencyBalance Normal " .. tostring(money) .. " " .. selector, live) end
      if gold > 0 then adminExec("ChangeCurrencyBalance Gold " .. tostring(gold) .. " " .. selector, live) end
      if fame > 0 then adminExec("ChangeFamePoints " .. tostring(fame) .. " " .. selector, live) end
      targetMessageResolved(live, "Апгрейд не выполнен: предмет не удалён, возврат валюты отправлен.")
      appendActionEvent("item_upgrade", false, live, "source remove failed: " .. tostring(removeMessage or ""), '{"source":' .. js(sourceItem) .. ',"result":' .. js(resultItem) .. '}')
      return
    end
    local commandText, safeItem, errorText = adminSpawnItemCommandForInfo(live, resultItem, 1, spawnOptions)
    if commandText == nil then
      targetMessageResolved(live, "Апгрейд удалил исходный предмет, но новый предмет не выдан: " .. tostring(errorText or "bad item id"))
      appendActionEvent("item_upgrade", false, live, "result spawn command invalid", '{"source":' .. js(sourceItem) .. ',"result":' .. js(resultItem) .. '}')
      return
    end
    local spawned, spawnMessage = adminExec(commandText, live)
    rememberCooldown("item-upgrade-cooldowns.json", live)
    appendJsonArray(STATE_DIR .. "\\item-upgrade.json",
      '{"utc":' .. js(nowUtc()) .. ',"steamId":' .. js(live.steam or "") .. ',"name":' .. js(live.name or "") .. ',"alias":' .. js(alias) .. ',"source":' .. js(sourceItem) .. ',"result":' .. js(resultItem) .. ',"weight":' .. tostring(spawnOptions.weight or 0) .. ',"health":' .. tostring(spawnOptions.health or 0) .. ',"spawned":' .. tostring(spawned) .. '}',
      1024 * 1024)
    local text = applyVars(extractStringAny(rule, { "SuccessMessage", "successMessage" }) or configString("item-upgrade", { "SuccessMessage", "successMessage" }, "Апгрейд выполнен: {source} -> {result}."), { source = sourceItem, result = resultItem })
    targetMessageResolved(live, spawned and text or ("Исходный предмет удалён, но выдача результата не подтверждена: " .. tostring(spawnMessage or "")))
    appendActionEvent("item_upgrade", spawned, live, tostring(spawnMessage or ""), '{"source":' .. js(sourceItem) .. ',"result":' .. js(resultItem) .. ',"safeItem":' .. js(safeItem or "") .. ',"weight":' .. tostring(spawnOptions.weight or 0) .. ',"health":' .. tostring(spawnOptions.health or 0) .. '}')
  end)
  targetMessageResolved(info, queued and "Апгрейд поставлен в очередь." or tostring(queueIdOrMessage))
  return true
end

function panelQuestObjects()
  local rows = {}
  for _, object in ipairs(moduleArrayObjects("panel-quests", "Quests")) do
    if extractBoolAny(object, { "Enabled", "enabled" }, true) ~= false then table.insert(rows, object) end
  end
  return rows
end

function panelQuestByAlias(alias)
  local wanted = tostring(alias or ""):lower()
  for _, object in ipairs(panelQuestObjects()) do
    local key = tostring(extractStringAny(object, { "Alias", "alias" }) or ""):lower()
    local title = tostring(extractStringAny(object, { "Title", "title", "Name", "name" }) or ""):lower()
    if wanted == key or wanted == title then return object end
  end
  return nil
end

function panelQuestClaimRemaining(info, alias)
  local hours = configNumber("panel-quests", { "ClaimCooldownHours", "claimCooldownHours" }, 24)
  if tonumber(hours or 0) <= 0 then return 0 end
  local now = os.time()
  local key = tostring(alias or ""):lower()
  local steam = valueText((info or {}).steam or "")
  local name = valueText((info or {}).name or "")
  local last = 0
  for _, object in ipairs(stateObjects("panel-quests-claims.json")) do
    local rowKey = tostring(extractStringAny(object, { "alias", "Alias" }) or ""):lower()
    local rowSteam = extractStringAny(object, { "steamId", "SteamId" }) or ""
    local rowName = extractStringAny(object, { "name", "Name" }) or ""
    if rowKey == key and ((steam ~= "" and rowSteam == steam) or (steam == "" and name ~= "" and rowName == name)) then
      last = math.max(last, extractNumberAny(object, { "at", "At" }, 0) or 0)
    end
  end
  local left = math.ceil((last + hours * 3600) - now)
  return left > 0 and left or 0
end

function grantConfiguredRewards(info, object, source)
  local okAll = true
  local messages = {}
  local money = math.floor(extractNumberAny(object, { "RewardMoney", "rewardMoney", "Money", "money" }, 0) or 0)
  local gold = math.floor(extractNumberAny(object, { "RewardGold", "rewardGold", "Gold", "gold" }, 0) or 0)
  local fame = math.floor(extractNumberAny(object, { "RewardFame", "rewardFame", "Fame", "fame" }, 0) or 0)
  if money ~= 0 then
    local ok, msg = changeMoney(info.steam, info.name, money, "Normal", info.runtimeKey)
    okAll = okAll and ok
    table.insert(messages, "money=" .. tostring(ok) .. ":" .. tostring(msg or ""))
  end
  if gold ~= 0 then
    local ok, msg = changeMoney(info.steam, info.name, gold, "Gold", info.runtimeKey)
    okAll = okAll and ok
    table.insert(messages, "gold=" .. tostring(ok) .. ":" .. tostring(msg or ""))
  end
  if fame ~= 0 then
    local ok, msg = setFame(info.steam, info.name, fame, info.runtimeKey)
    okAll = okAll and ok
    table.insert(messages, "fame=" .. tostring(ok) .. ":" .. tostring(msg or ""))
  end
  local itemsText = extractStringAny(object, { "RewardItemsText", "rewardItemsText", "ItemsText", "itemsText" }) or ""
  local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
  for _, item in ipairs(parseItemsSpec(itemsText)) do
    local commandText = adminSpawnItemCommandForInfo(live, item.itemId, item.quantity)
    local ok, msg = false, "bad item"
    if commandText ~= nil then ok, msg = adminExec(commandText, live) end
    okAll = okAll and ok
    table.insert(messages, "item=" .. tostring(item.itemId) .. "x" .. tostring(item.quantity) .. ":" .. tostring(ok) .. ":" .. tostring(msg or ""))
  end
  appendActionEvent(source or "configured_reward", okAll, info, table.concat(messages, " | "), '{"source":' .. js(source or "") .. '}')
  return okAll, table.concat(messages, " | ")
end

function handlePanelQuestCommand(info, words)
  if not moduleEnabled("panel-quests", false) then
    targetMessageResolved(info, "Квесты сервера сейчас отключены.")
    return true
  end
  local required = configString("panel-quests", { "RequiredPermission", "requiredPermission" }, "")
  if not hasPermission(info, required) then
    targetMessageResolved(info, permissionDeniedText(required))
    return true
  end
  local sub = tostring(words[2] or ""):lower()
  if sub == "" or sub == "list" then
    local labels = {}
    for _, quest in ipairs(panelQuestObjects()) do
      local alias = extractStringAny(quest, { "Alias", "alias" }) or ""
      local title = extractStringAny(quest, { "Title", "title", "Name", "name" }) or alias
      table.insert(labels, tostring(alias) .. "=" .. tostring(title))
    end
    targetMessageResolved(info, applyVars(configString("panel-quests", { "ListMessage", "listMessage" }, "Активные квесты: {quests}"), { quests = (#labels > 0 and table.concat(labels, ", ") or "нет") }))
    return true
  end
  if sub ~= "claim" then
    targetMessageResolved(info, "Формат: " .. commandUsage("quest", " list") .. " или " .. commandUsage("quest", " claim <код>") .. ".")
    return true
  end
  local alias = trimText(words[3] or "")
  local quest = panelQuestByAlias(alias)
  if quest == nil then
    targetMessageResolved(info, "Квест не найден. Используй " .. commandUsage("quest", " list") .. ".")
    return true
  end
  local remaining = panelQuestClaimRemaining(info, alias)
  if remaining > 0 then
    targetMessageResolved(info, "Награда этого квеста на кулдауне. Осталось " .. tostring(remaining) .. " сек.")
    return true
  end
  local mode = tostring(extractStringAny(quest, { "Mode", "mode" }) or "Claim"):lower()
  if mode == "turninhands" or mode == "turnin" then
    local targetItem = extractStringAny(quest, { "TargetItemId", "targetItemId" }) or ""
    local targetCount = math.max(1, math.floor(extractNumberAny(quest, { "TargetCount", "targetCount" }, 1) or 1))
    if targetItem == "" or targetCount > 1 then
      targetMessageResolved(info, "Автосдача квеста поддерживает только 1 предмет в руках. Для больших сборов используйте ручную проверку админом.")
      return true
    end
  elseif mode ~= "claim" and mode ~= "manual" then
    targetMessageResolved(info, "Этот режим квеста пока доступен только как доска/ручная проверка: " .. tostring(mode) .. ".")
    return true
  end
  local queued, queueIdOrMessage = enqueueMutation("panel-quest", info, function()
    local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
    if mode == "turninhands" or mode == "turnin" then
      local targetItem = extractStringAny(quest, { "TargetItemId", "targetItemId" }) or ""
      local held = itemInHandsObject(live, targetItem, "", "")
      if held == nil then
        targetMessageResolved(live, "Квест не сдан: нужный предмет должен быть в руках.")
        return
      end
      local removed = destroyInventoryItemObject(held, live)
      if not removed then
        targetMessageResolved(live, "Квест не сдан: предмет не удалось удалить.")
        return
      end
    end
    local okReward, rewardMessage = grantConfiguredRewards(live, quest, "panel_quest")
    appendJsonArray(STATE_DIR .. "\\panel-quests-claims.json",
      '{"utc":' .. js(nowUtc()) .. ',"at":' .. tostring(os.time()) .. ',"steamId":' .. js(live.steam or "") .. ',"name":' .. js(live.name or "") .. ',"alias":' .. js(alias) .. ',"rewardOk":' .. tostring(okReward) .. '}',
      1024 * 1024)
    local title = extractStringAny(quest, { "Title", "title", "Name", "name" }) or alias
    targetMessageResolved(live, applyVars(extractStringAny(quest, { "SuccessMessage", "successMessage" }) or "Квест выполнен: {title}.", { title = title, player = displayPlayerName(live, "") }))
    if okReward and configBool("panel-quests", { "AnnounceOnClaim", "announceOnClaim" }, true) then
      local announcement = extractStringAny(quest, { "Announcement", "announcement" }) or ""
      if announcement ~= "" then broadcast(applyVars(announcement, { title = title, player = displayPlayerName(live, "") })) end
    end
    appendActionEvent("panel_quest", okReward, live, tostring(rewardMessage or ""), '{"alias":' .. js(alias) .. ',"mode":' .. js(mode) .. '}')
  end)
  targetMessageResolved(info, queued and "Квест поставлен в очередь на выдачу награды." or tostring(queueIdOrMessage))
  return true
end

