function copyPlayerCommandAliases(source)
  local out = {}
  for key, aliases in pairs(source or {}) do
    out[key] = {}
    for _, alias in ipairs(aliases or {}) do
      table.insert(out[key], alias)
    end
  end
  return out
end

function normalizePlayerCommandAlias(value, prefix)
  local text = tostring(value or ""):lower():gsub("^%s+", ""):gsub("%s+$", ""):gsub("%s+", "")
  if text == "" then return "" end
  local first = text:sub(1, 1)
  if first == "/" or first == "!" then
    local body = text:sub(2):gsub("^[!/]+", "")
    if body == "" then return "" end
    return first .. body
  end
  text = text:gsub("^[!/]+", "")
  if text == "" then return "" end
  return tostring(prefix or "/") .. text
end

function addPlayerCommandAlias(out, value, includeBang)
  local direct = normalizePlayerCommandAlias(value, "/")
  if direct == "" then return end
  table.insert(out, direct)
  if includeBang ~= false and direct:sub(1, 1) == "/" then
    table.insert(out, "!" .. direct:sub(2))
  end
end

function dedupePlayerCommandAliases(aliases)
  local out = {}
  local seen = {}
  for _, alias in ipairs(aliases or {}) do
    local clean = normalizePlayerCommandAlias(alias, "/")
    if clean ~= "" and seen[clean] ~= true then
      seen[clean] = true
      table.insert(out, clean)
    end
  end
  return out
end

function playerCommandConfigHasKey(text, key)
  return tostring(text or ""):match('"' .. tostring(key or "") .. '"%s*:') ~= nil
end

function configuredPlayerCommandAliases(text, fields, includeBang)
  local out = {}
  local present = false
  for _, field in ipairs(fields or {}) do
    if playerCommandConfigHasKey(text, field) then
      present = true
      for _, alias in ipairs(jsonStringArrayForKey(text, field)) do
        addPlayerCommandAlias(out, alias, includeBang)
      end
      local stringValue = extractString(text, field)
      if stringValue ~= nil and stringValue ~= "" then
        for token in tostring(stringValue):gmatch("[^,%s;]+") do
          addPlayerCommandAlias(out, token, includeBang)
        end
      end
    end
  end
  return present, dedupePlayerCommandAliases(out)
end

function loadPlayerCommandAliases()
  local aliases = copyPlayerCommandAliases(DEFAULT_PLAYER_COMMAND_ALIASES)
  local text = configText("command-aliases")
  if text == "" or configBool("command-aliases", { "Enabled", "enabled" }, true) == false then
    return aliases
  end
  local includeBang = configBool("command-aliases", { "IncludeBangAliases", "includeBangAliases" }, true) ~= false
  local changed = 0
  for _, key in ipairs(PLAYER_COMMAND_ALIAS_ORDER) do
    local present, configured = configuredPlayerCommandAliases(text, PLAYER_COMMAND_ALIAS_CONFIG_FIELDS[key], includeBang)
    if present and #configured > 0 then
      aliases[key] = configured
      changed = changed + 1
    end
  end
  if changed > 0 and type(appendLog) == "function" then
    appendLog("player command aliases loaded customKeys=" .. tostring(changed))
  end
  return aliases
end

-- A manually edited legacy config can bypass the panel's save validation. Keep
-- command dispatch deterministic: the first command in the published order owns
-- the alias and every later conflicting claim is dropped and logged once at load.
function enforceUniquePlayerCommandAliases(aliases)
  local claimed = {}
  local conflicts = {}
  for _, key in ipairs(PLAYER_COMMAND_ALIAS_ORDER or {}) do
    local filtered = {}
    local seen = {}
    for _, alias in ipairs((aliases or {})[key] or {}) do
      local clean = normalizePlayerCommandAlias(alias, "/")
      if clean ~= "" and seen[clean] ~= true then
        local owner = claimed[clean]
        if owner == nil then
          claimed[clean] = key
          seen[clean] = true
          table.insert(filtered, clean)
        elseif owner ~= key then
          table.insert(conflicts, clean .. ":" .. owner .. ">" .. key)
        end
      end
    end
    aliases[key] = filtered
  end
  if #conflicts > 0 then
    appendLogLine("command alias conflicts ignored " .. table.concat(conflicts, ","))
  end
  return aliases
end

playerCommandAliases = enforceUniquePlayerCommandAliases(loadPlayerCommandAliases())

function commandMatches(command, key)
  local aliases = playerCommandAliases[key] or {}
  for _, alias in ipairs(aliases) do
    if command == alias then return true end
  end
  return false
end

commandKey = function(command)
  for _, key in ipairs(PLAYER_COMMAND_ALIAS_ORDER or {}) do
    local aliases = playerCommandAliases[key] or {}
    for _, alias in ipairs(aliases) do
      if command == alias then return key end
    end
  end
  for key, aliases in pairs(playerCommandAliases) do
    for _, alias in ipairs(aliases) do
      if command == alias then return key end
    end
  end
  return ""
end

function primaryPlayerCommandAlias(key)
  local aliases = playerCommandAliases[key] or {}
  for _, alias in ipairs(aliases) do
    if tostring(alias or ""):sub(1, 1) == "/" then return alias end
  end
  if aliases[1] ~= nil then return tostring(aliases[1]) end
  local defaults = DEFAULT_PLAYER_COMMAND_ALIASES[key] or {}
  for _, alias in ipairs(defaults) do
    if tostring(alias or ""):sub(1, 1) == "/" then return alias end
  end
  return "/" .. tostring(key or "command")
end

function commandUsage(key, suffix)
  return primaryPlayerCommandAlias(key) .. tostring(suffix or "")
end

function playerCommandLooksLikeAdminCommand(message)
  local text = tostring(message or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if text == "" then return false end
  if text:sub(1, 1) == "#" then return true end
  local first = tostring((splitWords(text)[1] or "")):gsub("^[!/]+", "")
  if first == "" then return false end
  local adminVerbs = {
    announce = true,
    ban = true,
    change_currency_balance = true,
    changecurrencybalance = true,
    changefamepoints = true,
    destroyentity = true,
    destroyvehicle = true,
    grant_elevated_status = true,
    grantelevatedstatus = true,
    kick = true,
    location = true,
    playerinfo = true,
    revoke_elevated_status = true,
    revokeelevatedstatus = true,
    schedulecargodrop = true,
    scheduleworldevent = true,
    sendchat = true,
    sendnotification = true,
    setattributes = true,
    setcurrencybalance = true,
    setdeluxeversion = true,
    set_deluxe_version = true,
    setfamepoints = true,
    setgender = true,
    setskilllevel = true,
    spawnanimal = true,
    spawnarmednpc = true,
    spawnitem = true,
    spawnitem2 = true,
    spawnrandomanimal = true,
    spawnrandomzombie = true,
    spawnvehicle = true,
    spawnzombie = true,
    teleport = true,
    teleportto = true,
    teleporttome = true,
    teleporttoplayer = true
  }
  local normalized = first:lower():gsub("[_%-%s]+", "")
  return adminVerbs[first:lower()] == true or adminVerbs[normalized] == true
end

function moduleEnabled(key, fallback)
  return configBool(key, { "Enabled", "enabled" }, fallback ~= false) ~= false
end

function playerCompactCommandSummary(info, mode)
  local commands = { commandUsage("help"), commandUsage("info") }
  local function addCommand(enabled, key, suffix)
    if enabled and #commands < 7 then
      table.insert(commands, commandUsage(key, suffix))
    end
  end

  addCommand(moduleEnabled("sector-scan", true) and hasPermission(info, configString("sector-scan", { "RequiredPermission", "requiredPermission" }, "")), "scan", " <B2>")
  addCommand(moduleEnabled("fast-travel", true), "travel")
  addCommand(moduleEnabled("base-loot-collector", false) and hasPermission(info, configString("base-loot-collector", { "RequiredPermission", "requiredPermission" }, "")), "baseloot")
  addCommand(moduleEnabled("vehicle-rental", true), "rent")
  addCommand(moduleEnabled("daily-pack", true) and hasPermission(info, configString("daily-pack", { "RequiredPermission", "requiredPermission" }, "")), "dailypack")
  addCommand(moduleEnabled("battlepass", false) and hasPermission(info, configString("battlepass", { "RequiredPermission", "requiredPermission" }, "")), "battlepass")
  addCommand(moduleEnabled("gamestores-shop", false), "gamestores")
  addCommand(moduleEnabled("wargm-shop", false), "wargm")

  if tostring(mode or "") == "info" then
    return "SCUM NEDJIN INFO: " .. table.concat(commands, ", ") .. "."
  end
  return "SCUM NEDJIN: " .. table.concat(commands, ", ") .. "."
end

function playerHelpText(info)
  return table.concat(playerHelpLines(info), " | ")
end

function playerHelpLines(info)
  local english = playerLanguage(info) == "en"
  local lines = {}
  local function add(ru, en)
    table.insert(lines, english and (en or ru) or ru)
  end
  local function section(ruTitle, enTitle, ruCommands, enCommands)
    add("============= [" .. tostring(ruTitle or "") .. "] =============", "============= [" .. tostring(enTitle or ruTitle or "") .. "] =============")
    add(tostring(ruCommands or ""), tostring(enCommands or ruCommands or ""))
  end

  add("============= SCUM NEDJIN =============", "============= SCUM NEDJIN =============")
  section("Основные", "Basics",
    commandUsage("help") .. ", " .. commandUsage("info") .. ", " .. commandUsage("hello") .. ", " .. commandUsage("language", " ru|en"),
    commandUsage("help") .. ", " .. commandUsage("info") .. ", " .. commandUsage("hello") .. ", " .. commandUsage("language", " ru|en"))

  if moduleEnabled("home-system", true) then
    section("Дом", "Home",
      commandUsage("sethome", " <name>") .. ", " .. commandUsage("home", " <name>") .. ", " .. commandUsage("homes") .. ", " .. commandUsage("delhome", " <name>"),
      commandUsage("sethome", " <name>") .. ", " .. commandUsage("home", " <name>") .. ", " .. commandUsage("homes") .. ", " .. commandUsage("delhome", " <name>"))
  end

  if moduleEnabled("private-messages", true) and
    (not configBool("private-messages", { "UsePermission", "usePermission" }, false) or hasPermission(info, configString("private-messages", { "AllowPermission", "allowPermission" }, "pm.use"))) then
    section("Сообщения", "Messages",
      commandUsage("pm", " <ник> <текст>") .. ", " .. commandUsage("reply", " <текст>"),
      commandUsage("pm", " <name> <text>") .. ", " .. commandUsage("reply", " <text>"))
  end

  local services = {}
  local economy = {}
  local events = {}
  if moduleEnabled("sector-scan", true) and hasPermission(info, configString("sector-scan", { "RequiredPermission", "requiredPermission" }, "")) then
    table.insert(services, commandUsage("scan", " <B2>"))
  end
  if moduleEnabled("fast-travel", true) then
    table.insert(services, commandUsage("travel"))
  end
  if moduleEnabled("base-loot-collector", false) and hasPermission(info, configString("base-loot-collector", { "RequiredPermission", "requiredPermission" }, "")) then
    table.insert(services, commandUsage("baseloot"))
    table.insert(services, commandUsage("baseloot", " chests"))
  end
  if moduleEnabled("vehicle-rental", true) then
    table.insert(services, commandUsage("rent"))
    table.insert(services, commandUsage("rent", " return"))
  end
  if moduleEnabled("welcome-pack", true) and hasPermission(info, configString("welcome-pack", { "RequiredPermission", "requiredPermission" }, "")) then
    table.insert(services, commandUsage("welcomepack"))
  end
  if moduleEnabled("daily-pack", true) and hasPermission(info, configString("daily-pack", { "RequiredPermission", "requiredPermission" }, "")) then
    table.insert(services, commandUsage("dailypack"))
  end
  if moduleEnabled("battlepass", false) and hasPermission(info, configString("battlepass", { "RequiredPermission", "requiredPermission" }, "")) then
    table.insert(services, commandUsage("battlepass"))
  end
  if moduleEnabled("dlc", false) and hasPermission(info, configString("dlc", { "RequiredPermission", "requiredPermission" }, "")) then
    table.insert(services, commandUsage("dlc"))
  end
  if moduleEnabled("gamestores-shop", false) then
    table.insert(economy, commandUsage("gamestores"))
  end
  if moduleEnabled("money-transfer", true) and hasPermission(info, configString("money-transfer", { "RequiredPermission", "requiredPermission" }, "")) then
    table.insert(economy, english and commandUsage("moneytransfer", " <name|SteamID> <amount>") or commandUsage("moneytransfer", " <ник|SteamID> <сумма>"))
  end
  if moduleEnabled("item-upgrade", false) and hasPermission(info, configString("item-upgrade", { "RequiredPermission", "requiredPermission" }, "")) then
    table.insert(economy, commandUsage("itemupgrade", " list"))
    table.insert(economy, english and commandUsage("itemupgrade", " <code>") or commandUsage("itemupgrade", " <код>"))
  end
  if moduleEnabled("panel-quests", false) and hasPermission(info, configString("panel-quests", { "RequiredPermission", "requiredPermission" }, "")) then
    table.insert(events, commandUsage("quest", " list"))
    table.insert(events, english and commandUsage("quest", " claim <code>") or commandUsage("quest", " claim <код>"))
  end
  if moduleEnabled("bounty-hunt", true) then
    table.insert(events, commandUsage("streak"))
    table.insert(events, commandUsage("bounty"))
    table.insert(events, commandUsage("huntertop"))
  end
  if moduleEnabled("wargm-shop", false) then
    table.insert(economy, commandUsage("wargm"))
  end

  if #services > 0 then
    section("Сервисы", "Services", table.concat(services, ", "), table.concat(services, ", "))
  end
  if #economy > 0 then
    section("Экономика", "Economy", table.concat(economy, ", "), table.concat(economy, ", "))
  end
  if #events > 0 then
    section("События", "Events", table.concat(events, ", "), table.concat(events, ", "))
  end
  section("Язык", "Language", "Русский: " .. commandUsage("language", " ru") .. " | English: " .. commandUsage("language", " en"), "Russian: " .. commandUsage("language", " ru") .. " | English: " .. commandUsage("language", " en"))
  return lines
end

function playerHelpChatType(line)
  local text = tostring(line or "")
  if text:find("SCUM NEDJIN", 1, true) then return 4 end
  if text:find("/", 1, true) then return 3 end
  if text:find("Основные", 1, true) or text:find("Basics", 1, true) then return 6 end
  if text:find("Дом", 1, true) or text:find("Home", 1, true) then return 3 end
  if text:find("Сообщения", 1, true) or text:find("Messages", 1, true) then return 3 end
  if text:find("Сервисы", 1, true) or text:find("Services", 1, true) then return 2 end
  if text:find("Экономика", 1, true) or text:find("Economy", 1, true) then return 4 end
  if text:find("События", 1, true) or text:find("Events", 1, true) then return 6 end
  if text:find("Язык", 1, true) or text:find("Language", 1, true) then return 2 end
  return 3
end

function configuredPlayerChatResponseLines(configKey, info)
  -- The panel stores ordinary JSON only. It is never parsed as a command or
  -- template; the existing deferred sender is the sole player-chat route.
  if configBool(configKey, { "Enabled", "enabled" }, true) ~= true then return nil end
  if configBool(configKey, { "UseCustomText", "useCustomText" }, false) ~= true then return nil end
  local english = playerLanguage(info) == "en"
  local text = ""
  if english then text = configString(configKey, { "EnglishText", "englishText" }, "") end
  if tostring(text or "") == "" then text = configString(configKey, { "Text", "text" }, "") end
  if tostring(text or "") == "" then return nil end
  local maxLines = math.max(1, math.min(math.floor(configNumber(configKey, { "MaxLines", "maxLines" }, 24) or 24), 40))
  -- Keep the panel preview and the actual player-chat payload aligned. The
  -- downstream chat sender also protects its own configured limit, so this
  -- per-help cap may only make messages shorter, never wider.
  local bridgeMaxBytes = math.max(16, math.floor(configNumber("bridge-safety", { "MaxChatMessageBytes", "maxChatMessageBytes" }, 220) or 220))
  local maxLineBytes = configNumber(configKey, { "MaxLineBytes", "maxLineBytes" }, bridgeMaxBytes) or bridgeMaxBytes
  maxLineBytes = math.max(16, math.min(math.floor(maxLineBytes), bridgeMaxBytes))
  local lines = {}
  for _, line in ipairs(splitLines(text)) do
    local clean = tostring(line or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if clean ~= "" then
      local safeLine, trimmed = utf8SafePrefix(clean, maxLineBytes)
      if trimmed then
        appendLog("custom " .. tostring(configKey or "chat-response") .. " line truncated to byte limit=" .. tostring(maxLineBytes))
      end
      if safeLine ~= "" then table.insert(lines, safeLine) end
      if #lines >= maxLines then break end
    end
  end
  if #lines <= 0 then return nil end
  appendLog("custom " .. tostring(configKey or "chat-response") .. " response selected player=" .. tostring((info or {}).name or (info or {}).steam or "") ..
    " language=" .. tostring(english and "en" or "ru") .. " lines=" .. tostring(#lines))
  return lines
end

function configuredPlayerHelpLines(info)
  return configuredPlayerChatResponseLines("help-response", info)
end

function configuredPlayerInfoLines(info)
  return configuredPlayerChatResponseLines("info-response", info)
end

function sendPlayerHelp(info)
  local customLines = configuredPlayerHelpLines(info)
  local lines = customLines or playerHelpLines(info)
  local delayMs = configNumber("bridge-safety", { "HelpMessageLineDelayMs", "helpMessageLineDelayMs" }, 140)
  if customLines ~= nil then
    delayMs = configNumber("help-response", { "LineDelayMs", "lineDelayMs" }, delayMs)
  end
  if configBool("bridge-safety", { "EnableDeferredHelpMessages", "enableDeferredHelpMessages" }, true) then
    sendTargetMessageLines(info, lines, "help", function(line)
      if configBool("bridge-safety", { "EnableStructuredHelpChat", "enableStructuredHelpChat" }, true) then
        return playerHelpChatType(line)
      end
      return nil
    end, {
      delayMs = delayMs,
      compactMessage = playerCompactCommandSummary(info, "help"),
      compactChatType = 6
    })
    return
  end
  sendTargetMessageLines(info, lines, "help", function(line)
    if configBool("bridge-safety", { "EnableStructuredHelpChat", "enableStructuredHelpChat" }, true) then
      return playerHelpChatType(line)
    end
    return nil
  end)
end

