ARMORY_COMMAND_PENDING = ARMORY_COMMAND_PENDING or {}
ARMORY_COMMAND_TRADERS = ARMORY_COMMAND_TRADERS or {}

function armoryCommandActorClass()
  return actorSummonToken(configString("armory-command", { "TraderActorClass", "traderActorClass", "ActorClass", "actorClass" }, "BP_ArmsDealer_01_C"))
end

function armoryCommandStockTargetClasses()
  local classes = {}
  local seen = {}
  local function add(value)
    local clean = actorSummonToken(value)
    if clean ~= "" and seen[clean] ~= true then
      seen[clean] = true
      table.insert(classes, clean)
    end
  end
  add(configString("armory-command", { "StockTraderClass", "stockTraderClass" }, "BP_ArmsDealer_01_C"))
  add(configString("armory-command", { "StockTradePostClass", "stockTradePostClass", "TradePostClass", "tradePostClass" }, "BP_Outpost_Armory_NPCInteractionBox_C"))
  add(armoryCommandActorClass())
  return classes
end

function armoryCommandLooksArmoryTarget(actor)
  if actor == nil or not isValidObject(actor) then return false end
  local text = objectFullName(actor):lower()
  if text:find("armory", 1, true) or text:find("armsdealer", 1, true) or text:find("arms_dealer", 1, true) then
    return true
  end
  if type(traderPersonalityObject) == "function" then
    local personality = traderPersonalityObject(actor)
    local personalityText = objectFullName(personality):lower()
    if personalityText:find("armory", 1, true) or personalityText:find("armsdealer", 1, true) or personalityText:find("arms_dealer", 1, true) then
      return true
    end
  end
  return false
end

function armoryCommandTargetKind(actor)
  if actor == nil or not isValidObject(actor) then return "unknown" end
  local text = (objectClassFullName(actor) .. " " .. objectFullName(actor)):lower()
  if text:find("armsdealer", 1, true) or text:find("arms_dealer", 1, true) or text:find("bp_armsdealer_01", 1, true) then
    return "trader"
  end
  if text:find("armory_npcinteractionbox", 1, true) or text:find("bp_outpost_armory", 1, true) then
    return "tradepost"
  end
  return "unknown"
end

function armoryCommandDispatchableTraderCheck(actor, attempts)
  attempts = attempts or {}
  if actor == nil or not isValidObject(actor) then return false, "actor-invalid" end
  local kind = armoryCommandTargetKind(actor)
  if kind ~= "trader" then return false, "not-trader:" .. tostring(kind) end

  local personality = nil
  if type(traderPersonalityObject) == "function" then
    personality = traderPersonalityObject(actor)
  end
  local personalityText = objectFullName(personality)
  local requirePersonality = configBool("armory-command", { "RequireTraderPersonalityForTradeBuy", "requireTraderPersonalityForTradeBuy" }, true) == true
  if requirePersonality and (personality == nil or not isValidObject(personality)) then
    return false, "personality-missing"
  end

  local requireArmory = configBool("armory-command", { "RequireArmoryPersonalityForTradeBuy", "requireArmoryPersonalityForTradeBuy" }, true) == true
  if requireArmory then
    local matches = false
    if personality ~= nil and isValidObject(personality) then
      if type(traderPersonalityMatchesHint) == "function" and traderPersonalityMatchesHint(personality, "armorer") then
        matches = true
      end
      local lower = personalityText:lower()
      if lower:find("armory", 1, true) or lower:find("armsdealer", 1, true) or lower:find("arms_dealer", 1, true) then
        matches = true
      end
    end
    if not matches then
      return false, "personality-not-armory:" .. tostring(personalityText)
    end
  end

  local tradePost = runtimeCollectionUnwrap(firstProp(actor, { "_tradeOutpostBuilding", "TradeOutpostBuilding", "tradeOutpostBuilding" }))
  local managerDetail = "tradepost-missing"
  local manager = nil
  if tradePost ~= nil and isValidObject(tradePost) and type(findTradePostManagerForTradePost) == "function" then
    manager, managerDetail = findTradePostManagerForTradePost(tradePost)
  elseif tradePost ~= nil and isValidObject(tradePost) then
    managerDetail = "tradepost-present-manager-check-missing"
  end
  if configBool("armory-command", { "RequireTraderManagerLinkForTradeBuy", "requireTraderManagerLinkForTradeBuy" }, false) == true then
    if manager == nil or not isValidObject(manager) or tostring(managerDetail or ""):find("assigned%-manager", 1, false) == nil then
      local allowManagerlessArmory = configBool("armory-command", { "AllowManagerlessArmoryTraderTradeBuy", "allowManagerlessArmoryTraderTradeBuy" }, false) == true
      if not allowManagerlessArmory then
        return false, "manager-link-missing:" .. tostring(managerDetail)
      end
      return true, "dispatchable-trader personality=" .. tostring(personalityText) .. " manager-soft-missing=" .. tostring(managerDetail)
    end
  end

  return true, "dispatchable-trader personality=" .. tostring(personalityText) .. " manager=" .. tostring(managerDetail)
end

function armoryCommandTargetRegistrationScore(actor, attempts)
  attempts = attempts or {}
  local kind = armoryCommandTargetKind(actor)
  local tradePost = nil
  if kind == "trader" then
    tradePost = runtimeCollectionUnwrap(firstProp(actor, { "_tradeOutpostBuilding", "TradeOutpostBuilding" }))
  elseif kind == "tradepost" then
    tradePost = actor
  end
  if tradePost == nil or not isValidObject(tradePost) then
    return kind == "trader" and 55 or 80, "tradepost-missing"
  end
  if type(findTradePostManagerForTradePost) ~= "function" then
    return 25, "manager-check-missing"
  end
  local manager, detail, managerAttempts = findTradePostManagerForTradePost(tradePost)
  if #attempts < 40 then
    table.insert(attempts, "targetManager=" .. tostring(detail or "") .. " manager=" .. objectFullName(manager))
    for _, attempt in ipairs(managerAttempts or {}) do
      if #attempts < 40 then table.insert(attempts, "targetManager." .. tostring(attempt)) end
    end
  end
  if manager ~= nil and isValidObject(manager) and tostring(detail or ""):find("assigned%-manager", 1, false) ~= nil then
    return kind == "trader" and 0 or 8, tostring(detail or "assigned")
  end
  if manager ~= nil and isValidObject(manager) then
    return kind == "trader" and 22 or 30, tostring(detail or "manager-token")
  end
  return kind == "trader" and 45 or 65, tostring(detail or "manager-missing")
end

function armoryCommandFindStockTargetAnyDistance(live, attempts)
  attempts = attempts or {}
  local allowTradePost = configBool("armory-command", { "AllowTradePostTarget", "allowTradePostTarget" }, false) == true
  local requireDispatchable = configBool("armory-command", { "RequireDispatchableTraderTarget", "requireDispatchableTraderTarget" }, true) == true
  local classes = armoryCommandStockTargetClasses()
  local best, bestDistance, bestKind, bestScore = nil, nil, "", nil
  local scanned = 0
  local notes = {}
  for _, actor in ipairs(findAll(classes)) do
    if actor ~= nil and isValidObject(actor) then
      scanned = scanned + 1
      local distance = runtimeDistanceToInfo(actor, live or {})
      local looksArmory = armoryCommandLooksArmoryTarget(actor)
      local kind = armoryCommandTargetKind(actor)
      if #notes < 10 then
        table.insert(notes, tostring(math.floor(distance or 0)) .. ":" .. tostring(kind) .. ":" .. tostring(looksArmory) .. ":" .. objectFullName(actor))
      end
      if looksArmory and (kind ~= "tradepost" or allowTradePost) then
        local dispatchable, dispatchDetail = true, "not-required"
        if requireDispatchable then
          dispatchable, dispatchDetail = armoryCommandDispatchableTraderCheck(actor, attempts)
        end
        if #notes < 14 then
          table.insert(notes, "dispatchable=" .. tostring(dispatchable) .. ":" .. tostring(dispatchDetail) .. ":" .. objectFullName(actor))
        end
        if dispatchable then
        local personalityScore = 12
        if kind == "trader" and type(traderPersonalityObject) == "function" then
          local personality = traderPersonalityObject(actor)
          if personality ~= nil and isValidObject(personality) then
            personalityScore = 3
            if type(traderPersonalityMatchesHint) == "function" and traderPersonalityMatchesHint(personality, "armorer") then
              personalityScore = 0
            end
          end
        elseif kind == "tradepost" then
          personalityScore = 8
        end
        local registrationScore, registrationDetail = armoryCommandTargetRegistrationScore(actor, attempts)
        local kindScore = kind == "trader" and 0 or (kind == "tradepost" and 80 or 120)
        local score = kindScore + personalityScore + registrationScore
        if #notes < 14 then
          table.insert(notes, "score=" .. tostring(score) .. ":" .. tostring(kind) .. ":" .. tostring(registrationDetail or "") .. ":" .. objectFullName(actor))
        end
        if best == nil or score < (bestScore or score + 1) or (score == bestScore and distance < (bestDistance or distance + 1)) then
          best = actor
          bestDistance = distance
          bestKind = kind
          bestScore = score
        end
        end
      end
    end
  end
  table.insert(attempts, "stockTargetScanAnywhere classes=" .. table.concat(classes, ",") .. " scanned=" .. tostring(scanned) .. " allowTradePost=" .. tostring(allowTradePost) .. " requireDispatchable=" .. tostring(requireDispatchable))
  if #notes > 0 then table.insert(attempts, "stockTargetCandidates=" .. table.concat(notes, " ; ")) end
  if best ~= nil then
    table.insert(attempts, "stockTargetSelected kind=" .. tostring(bestKind) .. " score=" .. tostring(bestScore or "") .. " distance=" .. tostring(math.floor(bestDistance or 0)) .. " target=" .. objectFullName(best))
  end
  return best, bestDistance, bestKind, bestScore
end

function armoryCommandFindNearbyStockTarget(live, attempts)
  return armoryCommandFindStockTargetAnyDistance(live, attempts)
end

function armoryCommandPrepareAnywhereRuntime(live, attempts)
  attempts = attempts or {}
  if configBool("armory-command", { "PrepareNativeAnywhere", "prepareNativeAnywhere" }, true) ~= true then
    table.insert(attempts, "armory native prepare disabled")
    return true, "disabled", "{}"
  end
  local saleDistance = configNumber("armory-command", { "EconomyMaxSaleDistance", "economyMaxSaleDistance", "MaxSaleDistance", "maxSaleDistance" }, 2000) or 2000
  local relevancyRange = configNumber("armory-command", { "TraderPawnRelevancyRange", "traderPawnRelevancyRange", "PawnRelevancyRange", "pawnRelevancyRange" }, 3000) or 3000
  local netCullDistance = configNumber("armory-command", { "TraderNetCullDistance", "traderNetCullDistance", "NetCullDistance", "netCullDistance" }, 15000) or 15000
  local updateTime = configNumber("armory-command", { "TradeOutpostsUpdateTime", "tradeOutpostsUpdateTime" }, 60) or 60
  local forceUnlimitedStock = configBool("armory-command", { "ForceUnlimitedStockForArmory", "forceUnlimitedStockForArmory", "ForceUnlimitedStock", "forceUnlimitedStock" }, true) == true
  local forceUnlimitedFunds = configBool("armory-command", { "ForceUnlimitedFundsForArmory", "forceUnlimitedFundsForArmory", "ForceUnlimitedFunds", "forceUnlimitedFunds" }, true) == true
  local payload = '{"actorClass":' .. js(armoryCommandActorClass()) ..
    ',"steamId":' .. js((live or {}).steam or (live or {}).steamId or "") ..
    ',"name":' .. js((live or {}).name or "") ..
    ',"runtimeKey":' .. js((live or {}).runtimeKey or "") ..
    ',"x":' .. tostring((live or {}).x or 0) ..
    ',"y":' .. tostring((live or {}).y or 0) ..
    ',"z":' .. tostring((live or {}).z or 0) ..
    ',"saleDistance":' .. tostring(saleDistance) ..
    ',"relevancyRange":' .. tostring(relevancyRange) ..
    ',"netCullDistance":' .. tostring(netCullDistance) ..
    ',"tradeOutpostsUpdateTime":' .. tostring(updateTime) ..
    ',"forceUnlimitedStock":' .. tostring(forceUnlimitedStock) ..
    ',"forceUnlimitedFunds":' .. tostring(forceUnlimitedFunds) .. '}'
  local timeoutMs = configNumber("armory-command", { "NativePrepareTimeoutMs", "nativePrepareTimeoutMs" }, 5000) or 5000
  local okNative, message, data = nativeTraderCommand("armory_anywhere_prepare", payload, timeoutMs)
  table.insert(attempts, "armory_anywhere_prepare=" .. tostring(okNative) .. ":" .. tostring(message))
  appendActionEvent("armory_prepare", okNative, live, message,
    '{"nativeResponse":' .. tostring(data or "{}") .. ',"payload":' .. payload .. '}')
  return okNative, message, data or "{}"
end

function armoryCommandActorEntry(actorClass)
  local cleanActor = actorSummonToken(actorClass)
  local entry = actorCatalogLookup(cleanActor)
  if entry ~= nil and entry ~= false then return entry end
  return {
    actorClass = "BP_ArmsDealer_01_C",
    path = "/Game/ConZ_Files/Characters/NPCs/Vendors/Arms_Dealer/Arms_Dealer_01/BP_ArmsDealer_01.BP_ArmsDealer_01_C",
    objectPath = "/Game/ConZ_Files/Characters/NPCs/Vendors/Arms_Dealer/Arms_Dealer_01/BP_ArmsDealer_01.BP_ArmsDealer_01_C",
    parentClass = "ATrader",
    category = "NPC"
  }
end

ARMORY_STREAMING_LAST_AT = ARMORY_STREAMING_LAST_AT or {}

function armoryCommandStreamingLevelNames(live, forcedKey)
  local key = tostring(forcedKey or "")
  if key == "" then key = nativeTraderNearestOutpostKey(live) end
  key = key:gsub("^%s+", ""):gsub("%s+$", "")
  if key == "" then key = "A_0" end
  local level = key .. "_Outpost"
  return {
    level,
    "/Game/ConZ_Files/Maps/The_Island/" .. level,
    "/Game/ConZ_Files/Maps/The_Island/" .. level .. "." .. level
  }, key
end

function armoryCommandStreamingCommands(live, forcedKey)
  local configured = configString("armory-command", { "OutpostStreamingCommands", "outpostStreamingCommands", "StreamingCommands", "streamingCommands" }, "")
  if configured ~= "" then
    local out = {}
    for command in configured:gmatch("[^;]+") do
      command = tostring(command or ""):gsub("^%s+", ""):gsub("%s+$", "")
      if command ~= "" then table.insert(out, command) end
    end
    if #out > 0 then return out end
  end
  local levels = armoryCommandStreamingLevelNames(live, forcedKey)
  return {
    "StreamLevelIn " .. levels[1],
    "StreamLevelIn " .. levels[2],
    "StreamLevelIn " .. levels[3]
  }
end

function armoryCommandLoadOutpostLevelDirect(live, attempts, forcedKey)
  attempts = attempts or {}
  if configBool("armory-command", { "AllowDangerousOutpostStreamingLoad", "allowDangerousOutpostStreamingLoad" }, false) ~= true then
    table.insert(attempts, "stream.direct disabled: GameplayStatics.LoadStreamLevel crashed SCUMServer through UE4SS on 2026-05-31")
    return false
  end
  local statics = gameplayStatics()
  local root = gameModeRoot() or worldRoot() or (live or {}).pc
  if statics == nil or not isValidObject(statics) or root == nil or not isValidObject(root) then
    table.insert(attempts, "stream.direct=skipped:gameplaystatics-or-root-missing")
    return false
  end

  local levels, key = armoryCommandStreamingLevelNames(live, forcedKey)
  local anyOk = false
  for _, levelName in ipairs(levels) do
    local arg = ueName(levelName)
    local okLoad, errLoad = safeCall(statics, "LoadStreamLevel", root, arg, true, true, {})
    table.insert(attempts, "stream.direct.LoadStreamLevel(" .. tostring(levelName) .. ")=" .. (okLoad and "ok" or tostring(errLoad)))
    if okLoad then anyOk = true end

    local okGet, streaming = safeCall(statics, "GetStreamingLevel", root, arg)
    if not okGet or streaming == nil or not isValidObject(streaming) then
      okGet, streaming = safeCall(statics, "GetStreamingLevel", root, tostring(levelName))
    end
    table.insert(attempts, "stream.direct.GetStreamingLevel(" .. tostring(levelName) .. ")=" .. (okGet and (isValidObject(streaming) and objectFullName(streaming) or "nil") or tostring(streaming)))
    if okGet and streaming ~= nil and isValidObject(streaming) then
      local okLoaded, errLoaded = safeCall(streaming, "SetShouldBeLoaded", true)
      table.insert(attempts, "stream.direct.SetShouldBeLoaded(" .. tostring(key) .. ")=" .. (okLoaded and "ok" or tostring(errLoaded)))
      local okVisible, errVisible = safeCall(streaming, "SetShouldBeVisible", true)
      table.insert(attempts, "stream.direct.SetShouldBeVisible(" .. tostring(key) .. ")=" .. (okVisible and "ok" or tostring(errVisible)))
      local okPriority, errPriority = safeCall(streaming, "SetPriority", 1000)
      table.insert(attempts, "stream.direct.SetPriority(" .. tostring(key) .. ")=" .. (okPriority and "ok" or tostring(errPriority)))
      anyOk = true
    end
  end

  local okFlush, errFlush = safeCall(statics, "FlushLevelStreaming", root)
  table.insert(attempts, "stream.direct.FlushLevelStreaming=" .. (okFlush and "ok" or tostring(errFlush)))
  return anyOk
end

function armoryCommandExecuteConsole(commandText, live, attempts)
  attempts = attempts or {}
  local text = tostring(commandText or "")
  if text == "" then return false end
  local kismet = kismetSystemLibrary()
  local root = gameModeRoot() or worldRoot() or (live or {}).pc
  if kismet == nil or not isValidObject(kismet) or root == nil or not isValidObject(root) then
    table.insert(attempts, "stream.console(" .. text .. ")=skipped:kismet-or-root-missing")
    return false
  end
  local pcArg = (live or {}).pc
  local okCall, err = safeCall(kismet, "ExecuteConsoleCommand", root, ueString(text), pcArg)
  if okCall then
    table.insert(attempts, "stream.console(" .. text .. ")=ok:ftext")
    return true
  end
  local firstErr = tostring(err)
  okCall, err = safeCall(kismet, "ExecuteConsoleCommand", root, text, pcArg)
  table.insert(attempts, "stream.console(" .. text .. ")=" .. (okCall and "ok:raw" or (firstErr .. " | " .. tostring(err))))
  return okCall
end

function armoryCommandTryLoadOutpostLevel(live, attempts)
  attempts = attempts or {}
  if configBool("armory-command", { "TryLoadOutpostLevel", "tryLoadOutpostLevel", "TryLoadOutpostLevels", "tryLoadOutpostLevels" }, true) ~= true then
    table.insert(attempts, "stream load disabled")
    return false
  end
  local key = nativeTraderNearestOutpostKey(live)
  local throttleSeconds = math.max(0, math.min(math.floor(configNumber("armory-command", { "OutpostStreamingThrottleSeconds", "outpostStreamingThrottleSeconds" }, 30) or 30), 300))
  local now = os.time()
  if throttleSeconds > 0 and ARMORY_STREAMING_LAST_AT[key] ~= nil and (now - ARMORY_STREAMING_LAST_AT[key]) < throttleSeconds then
    table.insert(attempts, "stream load throttled key=" .. tostring(key))
    return false
  end
  ARMORY_STREAMING_LAST_AT[key] = now
  local anyOk = armoryCommandLoadOutpostLevelDirect(live, attempts, key)
  if configBool("armory-command", { "AllowOutpostStreamingConsoleCommands", "allowOutpostStreamingConsoleCommands" }, false) == true then
    for _, commandText in ipairs(armoryCommandStreamingCommands(live, key)) do
      if armoryCommandExecuteConsole(commandText, live, attempts) then anyOk = true end
    end
  else
    table.insert(attempts, "stream.console fallback disabled")
  end
  return anyOk
end

function armoryCommandSummonAndLinkTraderRuntime(live, attempts)
  attempts = attempts or {}
  local actorClass = armoryCommandActorClass()
  local entry = armoryCommandActorEntry(actorClass)
  local cleanActor = actorSummonToken(actorClass)
  preloadNativeTraderLifecycleAssets(attempts, "summon-existing-link")
  preloadNativeTraderActorClass(cleanActor, entry, attempts)
  local personalityPath = preloadNativeTraderPersonalityAsset(cleanActor, live, attempts)
  local stockOutpostKey = nativeTraderStockOutpostKeyForActor(cleanActor)
  local forceStockPersonality = stockOutpostKey ~= ""
  local requireManagerLinked = configBool("armory-command", { "RequireLinkedTraderManagerForReady", "requireLinkedTraderManagerForReady", "RequireManagerLinked", "requireManagerLinked" }, true) == true
  local allowManagerlessLinked = configBool("armory-command", { "AllowManagerlessLinkedTrader", "allowManagerlessLinkedTrader", "AllowManagerlessArmoryLinkedTrader", "allowManagerlessArmoryLinkedTrader" }, false) == true
  if requireManagerLinked then allowManagerlessLinked = false end
  local allowUnsafeManagerlessSpawnActorMutation = configBool("armory-command", { "AllowUnsafeManagerlessSpawnActorMutation", "allowUnsafeManagerlessSpawnActorMutation", "AllowManagerlessSpawnActorMutation", "allowManagerlessSpawnActorMutation" }, false) == true
  local allowManualSpawnedTraderArrayMutation = configBool("armory-command", { "AllowManualSpawnedTraderArrayMutation", "allowManualSpawnedTraderArrayMutation", "AllowUnsafeSpawnedTraderArrayMutation", "allowUnsafeSpawnedTraderArrayMutation" }, false) == true
  local allowExactManagerLinkedArmoryArrayMutation = configBool("armory-command", { "AllowExactManagerLinkedArmoryArrayMutation", "allowExactManagerLinkedArmoryArrayMutation", "AllowExactStockArmoryArrayMutation", "allowExactStockArmoryArrayMutation" }, false) == true
  local fastManagerLookupOnly = configBool("armory-command", { "FastManagerLookupOnly", "fastManagerLookupOnly", "SkipSlowManagerFallbacks", "skipSlowManagerFallbacks" }, true) == true
  local okSummon, summonDetail, traderActor, summonCandidate = summonFunctionalLinkedTraderActor(cleanActor, live, attempts)
  armoryCommandAddAttempt(attempts, "summonExisting=" .. tostring(okSummon) .. ":" .. tostring(summonDetail) .. " actor=" .. objectFullName(traderActor))
  if not okSummon or traderActor == nil or not isValidObject(traderActor) then
    return false, "Summon оружейника не сработал: " .. tostring(summonDetail), "{}", nil
  end

  local maxLinkDistance = math.max(500, math.min(math.floor(configNumber("armory-command", { "SummonedTraderMaxLinkDistance", "summonedTraderMaxLinkDistance", "MaxLinkDistance", "maxLinkDistance" }, 12000) or 12000), 100000))
  local timeoutMs = math.max(1000, math.min(math.floor(configNumber("armory-command", { "NativeLinkExistingTimeoutMs", "nativeLinkExistingTimeoutMs" }, 9000) or 9000), 20000))
  local payload = '{"actorClass":' .. js(cleanActor) ..
    ',"traderFullName":' .. js(objectFullName(traderActor)) ..
    ',"summonCandidate":' .. js(tostring(summonCandidate or "")) ..
    ',"steamId":' .. js((live or {}).steam or (live or {}).steamId or "") ..
    ',"name":' .. js((live or {}).name or "") ..
    ',"runtimeKey":' .. js((live or {}).runtimeKey or "") ..
    ',"x":' .. tostring((live or {}).x or 0) ..
    ',"y":' .. tostring((live or {}).y or 0) ..
    ',"z":' .. tostring((live or {}).z or 0) ..
    ',"yaw":' .. tostring((live or {}).yaw or rotationYawOf((live or {}).pawn) or rotationYawOf((live or {}).pc) or 0) ..
    ',"personalityPath":' .. js(tostring(personalityPath or "")) ..
    ',"stockOutpostKey":' .. js(tostring(stockOutpostKey or "")) ..
    ',"forceStockPersonality":' .. tostring(forceStockPersonality) ..
    ',"requireManagerLinked":' .. tostring(requireManagerLinked) ..
    ',"allowManagerlessLinkedTrader":' .. tostring(allowManagerlessLinked) ..
    ',"allowUnsafeManagerlessSpawnActorMutation":' .. tostring(allowUnsafeManagerlessSpawnActorMutation) ..
    ',"allowManualSpawnedTraderArrayMutation":' .. tostring(allowManualSpawnedTraderArrayMutation) ..
    ',"allowExactManagerLinkedArmoryArrayMutation":' .. tostring(allowExactManagerLinkedArmoryArrayMutation) ..
    ',"fastManagerLookupOnly":' .. tostring(fastManagerLookupOnly) ..
    nativeTraderEconomyPreparePayload() ..
    ',"maxLinkDistance":' .. tostring(maxLinkDistance) .. '}'
  local okLink, linkMessage, linkData = nativeTraderCommand("link_existing_summoned_trader", payload, timeoutMs)
  armoryCommandAddAttempt(attempts, "nativeLinkExisting=" .. tostring(okLink) .. ":" .. tostring(linkMessage))
  appendActionEvent("armory_summon_link_existing", okLink, live, tostring(linkMessage or ""),
    '{"payload":' .. payload .. ',"nativeResponse":' .. tostring(linkData or "{}") .. ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}')
  if okLink then
    return true, linkMessage or "summoned linked", linkData or "{}", traderActor
  end

  if configBool("armory-command", { "DestroyUnlinkedSummonedTrader", "destroyUnlinkedSummonedTrader" }, true) == true then
    destroySpawnedItem(traderActor)
    armoryCommandAddAttempt(attempts, "destroyUnlinkedSummonedTrader=sent")
  end
  return false, "Summon создал NPC, но native link не подтвердился: " .. tostring(linkMessage), linkData or "{}", nil
end

function armoryCommandSpawnLinkedTraderRuntime(live, attempts)
  attempts = attempts or {}
  if configBool("armory-command", { "UseSummonExistingTraderLink", "useSummonExistingTraderLink", "UseSummonLinkedExisting", "useSummonLinkedExisting" }, true) == true then
    return armoryCommandSummonAndLinkTraderRuntime(live, attempts)
  end
  local actorClass = armoryCommandActorClass()
  local entry = armoryCommandActorEntry(actorClass)
  local timeoutMs = math.max(1000, math.min(math.floor(configNumber("armory-command", { "NativeSpawnTimeoutMs", "nativeSpawnTimeoutMs" }, 30000) or 30000), 30000))
  local nativeMode = configString("armory-command", { "NativeLinkedTraderMode", "nativeLinkedTraderMode" }, "linked-actor-require-manager-preload-lifecycle")
  local okNative, message, data = nativeFunctionalTraderForInfo(actorClass, live, entry, attempts, nil, nil, nativeMode, timeoutMs)
  local route = extractString(data or "", "route") or ""
  local spawnedFullName = extractString(data or "", "spawnedTrader") or ""
  local managerLinked = extractBool(data or "", "managerLinked", false) == true
  local exactNoArrayCandidate = extractBool(data or "", "exactStockArmoryManagerlessNoArrayCandidate", false) == true
  local allowManagerlessLinked = configBool("armory-command", { "AllowManagerlessLinkedTrader", "allowManagerlessLinkedTrader", "AllowManagerlessArmoryLinkedTrader", "allowManagerlessArmoryLinkedTrader" }, false) == true
  local allowExactNoArrayCandidate = configBool("armory-command", { "AllowExactStockArmoryManagerlessNoArrayCandidate", "allowExactStockArmoryManagerlessNoArrayCandidate", "AllowExactManagerlessArmoryNoArrayCandidate", "allowExactManagerlessArmoryNoArrayCandidate" }, false) == true
  local markerFallback = route == "spawn-linked-trader-actor-marker-fallback" and allowManagerlessLinked
  local stockPersonalityFallback = route == "spawn-linked-trader-actor-stock-personality-fallback" and allowManagerlessLinked
  local stockArmoryNoArrayCandidate = route == "spawn-linked-trader-actor-exact-stock-managerless-no-arrays" and exactNoArrayCandidate and allowExactNoArrayCandidate
  table.insert(attempts, "armory linked native route=" .. tostring(route) .. " managerLinked=" .. tostring(managerLinked) .. " markerFallback=" .. tostring(markerFallback) .. " stockPersonalityFallback=" .. tostring(stockPersonalityFallback) .. " stockArmoryNoArrayCandidate=" .. tostring(stockArmoryNoArrayCandidate) .. " spawned=" .. tostring(spawnedFullName))
  if not okNative then return false, message, data or "{}", nil end
  if route ~= "spawn-linked-trader-actor-exact" and not markerFallback and not stockPersonalityFallback and not stockArmoryNoArrayCandidate then
    return false, "Native Armory trader создан неподдержанным route; TradeBuy не отправляю.", data or "{}", nil
  end
  if not managerLinked and not markerFallback and not stockPersonalityFallback and not stockArmoryNoArrayCandidate then
    return false, "Native Armory trader не привязан к живому TradeOutpostManager; TradeBuy не отправляю.", data or "{}", nil
  end
  local traderActor = findRuntimeActorByFullName(spawnedFullName, actorClass)
  if traderActor == nil or not isValidObject(traderActor) then
    armoryCommandAddAttempt(attempts, "native linked trader accepted without Lua post-scan actor resolve; spawned=" .. tostring(spawnedFullName))
    return true, message, data or "{}", nil
  end
  return true, message, data or "{}", traderActor
end

