function armoryCommandRegisterLinkedTraderProxyRoute(traderActor, nativeData, actorClass, attempts)
  attempts = attempts or {}
  if traderActor == nil or not isValidObject(traderActor) then
    armoryCommandAddAttempt(attempts, "linkedProxyRegister skipped: trader-invalid")
    return false
  end
  if type(registerFunctionalTraderProxyRoute) ~= "function" then
    armoryCommandAddAttempt(attempts, "linkedProxyRegister skipped: proxy registry missing")
    return false
  end

  local dataText = tostring(nativeData or "")
  local donorFullName = extractString(dataText, "donorTradePost") or extractString(dataText, "linkedTradePost") or ""
  local donorTradePost = nil
  local donorDetail = ""
  if donorFullName ~= "" and type(findTradePostByFullName) == "function" then
    local findAttempts = {}
    donorTradePost, donorDetail, findAttempts = findTradePostByFullName(donorFullName)
    for _, attempt in ipairs(findAttempts or {}) do
      armoryCommandAddAttempt(attempts, "linkedProxyRegister.donor." .. tostring(attempt))
    end
  end

  if donorTradePost == nil or not isValidObject(donorTradePost) then
    donorTradePost = runtimeCollectionUnwrap(firstProp(traderActor, { "_tradeOutpostBuilding", "TradeOutpostBuilding", "tradeOutpostBuilding" }))
    donorDetail = "from-trader-tradeOutpostBuilding"
    donorFullName = objectFullName(donorTradePost)
  end
  if donorTradePost == nil or not isValidObject(donorTradePost) then
    armoryCommandAddAttempt(attempts, "linkedProxyRegister failed: donor missing detail=" .. tostring(donorDetail))
    return false
  end

  local personality = nil
  if type(traderPersonalityObject) == "function" then personality = traderPersonalityObject(traderActor) end
  local persistentId = extractString(dataText, "markerPersonalityGuid") or extractString(dataText, "traderPersonalityAfterGuid") or ""
  if persistentId == "" and type(traderPersonalityRuntimeId) == "function" then
    persistentId = traderPersonalityRuntimeId(personality)
  end
  local x, y, z = vectorOf(traderActor)
  local route = {
    actorClass = actorClass or armoryCommandActorClass(),
    proxy = traderActor,
    proxyFullName = objectFullName(traderActor),
    donorTradePost = donorTradePost,
    donorTradePostFullName = donorFullName ~= "" and donorFullName or objectFullName(donorTradePost),
    personality = personality,
    personalityFullName = objectFullName(personality),
    traderPersistentId = persistentId,
    x = x,
    y = y,
    z = z,
    yaw = rotationYawOf(traderActor) or 0,
    routeDetail = "armory-native-linked-trader"
  }
  local registered = registerFunctionalTraderProxyRoute(route)
  armoryCommandAddAttempt(attempts, "linkedProxyRegister=" .. tostring(registered) ..
    " proxy=" .. objectFullName(traderActor) ..
    " donor=" .. objectFullName(donorTradePost) ..
    " persistentId=" .. tostring(persistentId))
  appendActionEvent("armory_linked_proxy_register", registered, nil,
    registered and "Native linked Armory trader registered for trade/proxy trace." or "Native linked Armory trader proxy registration failed.",
    '{"actorClass":' .. js(actorClass or armoryCommandActorClass()) ..
    ',"registered":' .. tostring(registered == true) ..
    ',"proxy":' .. nativeProbeObjectJson("proxy", traderActor, "armory-native-linked", {}) ..
    ',"donorTradePost":' .. nativeProbeObjectJson("donorTradePost", donorTradePost, "armory-native-linked", {}) ..
    ',"personality":' .. nativeProbeObjectJson("personality", personality, "armory-native-linked", {}) ..
    ',"traderPersistentId":' .. js(tostring(persistentId or "")) ..
    ',"nativeResponse":' .. tostring(nativeData or "{}") .. '}')
  return registered
end

function armoryCommandSpawnProxyTraderRuntime(live, attempts)
