function armoryCommandAddAttempt(attempts, text)
  attempts = attempts or {}
  if #attempts < 90 then table.insert(attempts, tostring(text or "")) end
end

function findRuntimeActorByFullName(fullName, actorClass)
  local target = tostring(fullName or "")
  if target == "" then return nil end
  for _, className in ipairs(actorFindRuntimeClassNames(actorClass or "")) do
    local okFind, arr = pcall(function() return FindAllOf(className) end)
    if okFind and arr ~= nil then
      for _, obj in pairs(arr) do
        if obj ~= nil and isValidObject(obj) and objectFullName(obj) == target then return obj end
      end
    end
  end
  return nil
end

function armoryCommandFindTradePostByFullName(fullName)
  local target = tostring(fullName or "")
  if target == "" then return nil end
  local classes = {}
  local seen = {}
  local function add(value)
    for _, className in ipairs(actorFindRuntimeClassNames(value or "")) do
      local key = tostring(className or ""):lower()
      if key ~= "" and seen[key] ~= true then
        seen[key] = true
        table.insert(classes, className)
      end
    end
  end
  add(configString("armory-command", { "StockTradePostClass", "stockTradePostClass", "TradePostClass", "tradePostClass" }, "BP_Outpost_Armory_NPCInteractionBox_C"))
  add("BP_Outpost_Armory_NPCInteractionBox_C")
  for _, className in ipairs(classes) do
    local okFind, arr = pcall(function() return FindAllOf(className) end)
    if okFind and arr ~= nil then
      for _, obj in pairs(arr) do
        if obj ~= nil and isValidObject(obj) and objectFullName(obj) == target then return obj end
      end
    end
  end
  return nil
end

function armoryCommandStockOutpostKey()
  return tostring(configString("armory-command", { "ArmoryStockOutpostKey", "armoryStockOutpostKey", "StockOutpostKey", "stockOutpostKey" }, "A_0") or "A_0")
end

function armoryCommandStockTradePostFullNameForKey(key)
  local clean = tostring(key or "A_0"):upper():gsub("%s+", "")
  local map = {
    A_0 = "BP_Outpost_Armory_NPCInteractionBox_C /Game/ConZ_Files/Maps/The_Island/A_0_Outpost.A_0_Outpost:PersistentLevel.BP_Outpost_Armory_NPCInteractionBox_2",
    B_4 = "BP_Outpost_Armory_NPCInteractionBox_C /Game/ConZ_Files/Maps/The_Island/B_4_Outpost.B_4_Outpost:PersistentLevel.BP_Outpost_Armory_NPCInteractionBox_2",
    C_2 = "BP_Outpost_Armory_NPCInteractionBox_C /Game/ConZ_Files/Maps/The_Island/C_2_Outpost.C_2_Outpost:PersistentLevel.BP_Outpost_Armory_NPCInteractionBox_2",
    Z_3 = "BP_Outpost_Armory_NPCInteractionBox_C /Game/ConZ_Files/Maps/The_Island/Z_3_Outpost.Z_3_Outpost:PersistentLevel.BP_Outpost_Armory_NPCInteractionBox_2"
  }
  return map[clean] or map.A_0
end

function armoryCommandFindStockArmoryTradePost(attempts)
  attempts = attempts or {}
  local key = armoryCommandStockOutpostKey()
  local expectedFullName = armoryCommandStockTradePostFullNameForKey(key)
  local direct = armoryCommandFindTradePostByFullName(expectedFullName)
  if direct ~= nil and isValidObject(direct) then
    armoryCommandAddAttempt(attempts, "stockArmoryTradePost direct=" .. objectFullName(direct))
    return direct, "direct:" .. tostring(key), key, expectedFullName
  end

  local classes = {}
  local seen = {}
  local function add(value)
    for _, className in ipairs(actorFindRuntimeClassNames(value or "")) do
      local classKey = tostring(className or ""):lower()
      if classKey ~= "" and seen[classKey] ~= true then
        seen[classKey] = true
        table.insert(classes, className)
      end
    end
  end
  add(configString("armory-command", { "StockTradePostClass", "stockTradePostClass", "TradePostClass", "tradePostClass" }, "BP_Outpost_Armory_NPCInteractionBox_C"))
  add("BP_Outpost_Armory_NPCInteractionBox_C")

  local needle = "/" .. tostring(key):upper() .. "_Outpost."
  local fallback = nil
  local scanned = 0
  for _, className in ipairs(classes) do
    local okFind, arr = pcall(function() return FindAllOf(className) end)
    if okFind and arr ~= nil then
      for _, obj in pairs(arr) do
        if obj ~= nil and isValidObject(obj) and armoryCommandTargetKind(obj) == "tradepost" then
          scanned = scanned + 1
          local full = objectFullName(obj)
          if fallback == nil then fallback = obj end
          if full:find(needle, 1, true) ~= nil then
            armoryCommandAddAttempt(attempts, "stockArmoryTradePost scan=" .. full .. " scanned=" .. tostring(scanned))
            return obj, "scan:" .. tostring(className), key, expectedFullName
          end
        end
      end
    else
      armoryCommandAddAttempt(attempts, "stockArmoryTradePost scan " .. tostring(className) .. "=failed:" .. tostring(arr))
    end
  end
  if fallback ~= nil and isValidObject(fallback) then
    armoryCommandAddAttempt(attempts, "stockArmoryTradePost fallback=" .. objectFullName(fallback) .. " scanned=" .. tostring(scanned))
    return fallback, "fallback-any-armory-tradepost", key, expectedFullName
  end
  armoryCommandAddAttempt(attempts, "stockArmoryTradePost missing key=" .. tostring(key) .. " expected=" .. tostring(expectedFullName) .. " scanned=" .. tostring(scanned))
  return nil, "stock-armory-tradepost-not-found", key, expectedFullName
end

function armoryCommandSpawnRegisteredTradePostRuntime(live, attempts)
  attempts = attempts or {}
  local actorClass = armoryCommandActorClass()
  local entry = armoryCommandActorEntry(actorClass)
  local timeoutMs = math.max(1000, math.min(math.floor(configNumber("armory-command", { "NativeSpawnTimeoutMs", "nativeSpawnTimeoutMs" }, 30000) or 30000), 30000))
  local okNative, message, data = nativeFunctionalTraderForInfo(actorClass, live, entry, attempts, nil, nil, "registered-tradepost-anywhere", timeoutMs)
  local route = extractString(data or "", "route") or ""
  local spawnedFullName = extractString(data or "", "spawnedTradePost") or ""
  local donorPolicy = extractString(data or "", "donorDistancePolicy") or ""
  armoryCommandAddAttempt(attempts, "armory registered native route=" .. tostring(route) .. " donorPolicy=" .. tostring(donorPolicy) .. " spawnedTradePost=" .. tostring(spawnedFullName))
  if not okNative then return false, message, data or "{}", nil end
  if route ~= "clone-existing-registered-tradepost-native-site" then
    return false, "Native Armory route вернул неожиданный режим; TradeBuy не отправляю.", data or "{}", nil
  end
  local tradePost = armoryCommandFindTradePostByFullName(spawnedFullName)
  if tradePost == nil or not isValidObject(tradePost) then
    return false, "Native Armory TradePost создан, но Lua не нашёл spawned TradePost для ожидания штатного торговца.", data or "{}", nil
  end
  return true, message, data or "{}", tradePost
end

function armoryCommandTraderFromRegisteredTradePost(tradePost, attempts)
  attempts = attempts or {}
  if tradePost == nil or not isValidObject(tradePost) then
    armoryCommandAddAttempt(attempts, "registeredTradePost=invalid")
    return nil, "tradepost-invalid"
  end
  local candidate = nil
  local candidateDetail = ""
  local spawnedTraders = firstProp(tradePost, { "_spawnedTraders", "SpawnedTraders", "spawnedTraders" })
  local count, items, method = runtimeArrayCount(spawnedTraders, 8)
  armoryCommandAddAttempt(attempts, "registeredTradePost.spawnedTraders count=" .. tostring(count) .. " method=" .. tostring(method))
  for _, item in ipairs(items or {}) do
    local trader = runtimeCollectionUnwrap(item)
    if trader ~= nil and isValidObject(trader) and armoryCommandTargetKind(trader) == "trader" then
      local personality = traderPersonalityObject(trader)
      if personality ~= nil and isValidObject(personality) then
        return trader, "spawnedTraders:" .. tostring(method) .. ":" .. objectFullName(personality)
      end
      if candidate == nil then
        candidate = trader
        candidateDetail = "spawnedTraders-without-personality:" .. objectFullName(trader)
      end
    end
  end

  local tradePostKey = objectKey(tradePost)
  local scanned = 0
  for _, actor in ipairs(findAll({ armoryCommandActorClass(), "BP_ArmsDealer_01_C" })) do
    if actor ~= nil and isValidObject(actor) and armoryCommandTargetKind(actor) == "trader" then
      scanned = scanned + 1
      local owner = runtimeCollectionUnwrap(firstProp(actor, { "_tradeOutpostBuilding", "TradeOutpostBuilding", "tradeOutpostBuilding" }))
      if owner ~= nil and isValidObject(owner) and objectKey(owner) == tradePostKey then
        local personality = traderPersonalityObject(actor)
        if personality ~= nil and isValidObject(personality) then
          armoryCommandAddAttempt(attempts, "registeredTradePost.traderScan scanned=" .. tostring(scanned) .. " matched=" .. objectFullName(actor))
          return actor, "scan-linked-trader:" .. objectFullName(personality)
        end
        if candidate == nil then
          candidate = actor
          candidateDetail = "scan-linked-trader-without-personality:" .. objectFullName(actor)
        end
      end
    end
  end
  armoryCommandAddAttempt(attempts, "registeredTradePost.traderScan scanned=" .. tostring(scanned) .. " candidate=" .. tostring(candidateDetail))
  return nil, candidateDetail ~= "" and candidateDetail or "trader-not-spawned-yet"
end

function armoryCommandInteractionData(traderActor)
  local x, y, z = vectorOf(traderActor)
  local location = { X = x, Y = y, Z = z }
  return {
    ModifierPressed = false,
    IntegerData = 0,
    PointerData = traderActor,
    BoolData = true,
    TextData = ueText(""),
    InteractionLocation = location,
    InteractionNormal = { X = 0, Y = 0, Z = 1 },
    VectorData = location,
    BaseElementId = 0
  }
end

function armoryCommandPrepareActorForTradeBuy(actor, attempts)
  attempts = attempts or {}
  if configBool("armory-command", { "AllowLuaArmoryPostSpawnReplicationPrep", "allowLuaArmoryPostSpawnReplicationPrep" }, false) ~= true then
    table.insert(attempts, "TradeBuy replication prep skipped: disabled-after-preinit-actor-warning")
    return false
  end
  if actor == nil or not isValidObject(actor) then
    table.insert(attempts, "TradeBuy replication prep skipped: actor-invalid")
    return false
  end
  local steps = {}
  local function step(label, fn)
    local ok, result = pcall(fn)
    table.insert(steps, tostring(label) .. "=" .. (ok and "ok" or tostring(result)))
    return ok
  end
  step("SetReplicates(true)", function()
    if actor.SetReplicates ~= nil then return actor:SetReplicates(true) end
    error("missing")
  end)
  step("SetReplicateMovement(true)", function()
    if actor.SetReplicateMovement ~= nil then return actor:SetReplicateMovement(true) end
    error("missing")
  end)
  step("SetActorHiddenInGame(false)", function()
    if actor.SetActorHiddenInGame ~= nil then return actor:SetActorHiddenInGame(false) end
    error("missing")
  end)
  step("SetActorEnableCollision(true)", function()
    if actor.SetActorEnableCollision ~= nil then return actor:SetActorEnableCollision(true) end
    error("missing")
  end)
  step("SetNetDormancy(DORM_Awake)", function()
    local ok, err = safeCall(actor, "SetNetDormancy", 1)
    if not ok then error(err) end
    return true
  end)
  step("FlushNetDormancy()", function()
    local ok, err = safeCall(actor, "FlushNetDormancy")
    if not ok then error(err) end
    return true
  end)
  step("bAlwaysRelevant=true", function() actor.bAlwaysRelevant = true; return true end)
  step("bOnlyRelevantToOwner=false", function() actor.bOnlyRelevantToOwner = false; return true end)
  step("bNetUseOwnerRelevancy=false", function() actor.bNetUseOwnerRelevancy = false; return true end)
  step("NetCullDistanceSquared=4000000000000", function() actor.NetCullDistanceSquared = 4000000000000; return true end)
  step("OnRep_TradeOutpostBuilding()", function()
    local ok, err = safeCall(actor, "OnRep_TradeOutpostBuilding")
    if not ok then error(err) end
    return true
  end)
  if type(forceActorComponentsVisibleAndReplicated) == "function" then
    local componentAttempts = forceActorComponentsVisibleAndReplicated(actor)
    for index, attempt in ipairs(componentAttempts or {}) do
      if index > 14 then break end
      table.insert(steps, "component." .. tostring(attempt))
    end
  end
  step("ForceNetUpdate()", function()
    if actor.ForceNetUpdate ~= nil then return actor:ForceNetUpdate() end
    error("missing")
  end)
  if #attempts < 90 then
    table.insert(attempts, "TradeBuy replication prep target=" .. objectFullName(actor) .. " " .. table.concat(steps, "; "))
  end
  return true
end

function armoryCommandDispatchInteractionNative(live, traderActor, attempts, options)
  attempts = attempts or {}
  options = options or {}
  if traderActor == nil or not isValidObject(traderActor) then
    table.insert(attempts, "native TradeBuy=trader-invalid")
    return false, "Armory trader actor недоступен для native TradeBuy.", attempts
  end
  local pawn = (live or {}).pawn
  if pawn == nil or not isValidObject(pawn) then
    table.insert(attempts, "native TradeBuy=pawn-missing")
    return false, "Armory не открыт: сервер не видит live pawn игрока.", attempts
  end
  if options.skipDispatchableCheck ~= true and configBool("armory-command", { "RequireDispatchableTraderTarget", "requireDispatchableTraderTarget" }, true) == true then
    local dispatchable, dispatchDetail = armoryCommandDispatchableTraderCheck(traderActor, attempts)
    table.insert(attempts, "native TradeBuy target dispatchable=" .. tostring(dispatchable) .. ":" .. tostring(dispatchDetail))
    if not dispatchable then
      return false, "Armory trader actor не прошёл проверку функционального оружейника: " .. tostring(dispatchDetail), attempts
    end
  end

  local x, y, z = vectorOf(traderActor)
  local payload = "{" ..
    '"pawnFullName":' .. js(objectFullName(pawn)) ..
    ',"controllerFullName":' .. js(objectFullName((live or {}).pc)) ..
    ',"rpcFullName":' .. js(objectFullName((live or {}).rpc)) ..
    ',"targetFullName":' .. js(objectFullName(traderActor)) ..
    ',"targetClass":' .. js(objectClassFullName(traderActor)) ..
    ',"targetKind":' .. js(armoryCommandTargetKind(traderActor)) ..
    ',"targetX":' .. tostring(tonumber(x) or 0) ..
    ',"targetY":' .. tostring(tonumber(y) or 0) ..
    ',"targetZ":' .. tostring(tonumber(z) or 0) ..
    ',"route":"native-inline-armory-tradebuy"' ..
    ',"inlineGameThread":true' ..
    "}"
  local timeoutMs = math.max(1000, math.min(math.floor(configNumber("armory-command", { "NativeTradeBuyTimeoutMs", "nativeTradeBuyTimeoutMs" }, 3500) or 3500), 10000))
  local skipPlayerRpcServer = false
  if configBool("armory-command", { "UseNativeTargetInteractDispatch", "useNativeTargetInteractDispatch" }, false) == true then
    local okTarget, targetMessage, targetData = nativeTraderCommandInline("armory_target_interact", payload, timeoutMs)
    table.insert(attempts, "native inline armory_target_interact=" .. tostring(okTarget) .. ":" .. tostring(targetMessage))
    appendActionEvent("armory_native_target_interact", okTarget, live, targetMessage,
      '{"payload":' .. payload .. ',"nativeResponse":' .. tostring(targetData or "{}") .. '}')
    if okTarget then
      return true, "Native target Interact отправлен через IInteractableInterface.Interact.", attempts
    end
    if configBool("armory-command", { "AllowNativeServerTradeBuyFallback", "allowNativeServerTradeBuyFallback" }, false) ~= true then
      return false, "SCUM не принял native target Interact: " .. tostring(targetMessage), attempts
    end
  end
  if options.preferPrisonerServer == true or configBool("armory-command", { "UseNativePrisonerServerTradeBuyDispatch", "useNativePrisonerServerTradeBuyDispatch" }, false) == true then
    local okPrisonerServer, prisonerServerMessage, prisonerServerData = nativeTraderCommandInline("armory_prisoner_server_tradebuy", payload, timeoutMs)
    table.insert(attempts, "native inline armory_prisoner_server_tradebuy=" .. tostring(okPrisonerServer) .. ":" .. tostring(prisonerServerMessage))
    appendActionEvent("armory_native_prisoner_server_tradebuy", okPrisonerServer, live, prisonerServerMessage,
      '{"payload":' .. payload .. ',"nativeResponse":' .. tostring(prisonerServerData or "{}") .. '}')
    if okPrisonerServer then
      return true, "Native prisoner server TradeBuy interaction отправлен через Prisoner.InteractWithObjectOnServer.", attempts
    end
    if configBool("armory-command", { "AllowPlayerRpcServerTradeBuyFallback", "allowPlayerRpcServerTradeBuyFallback" }, false) ~= true then
      skipPlayerRpcServer = true
      if configBool("armory-command", { "AllowNativeClientTradeBuyFallback", "allowNativeClientTradeBuyFallback" }, false) ~= true then
        return false, "SCUM не принял native prisoner server TradeBuy interaction: " .. tostring(prisonerServerMessage), attempts
      end
    end
  end
  if configBool("armory-command", { "UseNativeServerTradeBuyDispatch", "useNativeServerTradeBuyDispatch" }, false) == true then
    if skipPlayerRpcServer then
      table.insert(attempts, "native inline armory_server_tradebuy skipped: AllowPlayerRpcServerTradeBuyFallback=false")
    else
      local okServer, serverMessage, serverData = nativeTraderCommandInline("armory_server_tradebuy", payload, timeoutMs)
      table.insert(attempts, "native inline armory_server_tradebuy=" .. tostring(okServer) .. ":" .. tostring(serverMessage))
      appendActionEvent("armory_native_server_tradebuy", okServer, live, serverMessage,
        '{"payload":' .. payload .. ',"nativeResponse":' .. tostring(serverData or "{}") .. '}')
      if okServer then
        return true, "Native server TradeBuy interaction отправлен через PlayerRpcChannel.InteractWithObjectOnServer.", attempts
      end
      if configBool("armory-command", { "AllowNativeClientTradeBuyFallback", "allowNativeClientTradeBuyFallback" }, false) ~= true then
        return false, "SCUM не принял native server TradeBuy interaction: " .. tostring(serverMessage), attempts
      end
    end
  end
  if configBool("armory-command", { "AllowNativeClientTradeBuyFallback", "allowNativeClientTradeBuyFallback" }, false) ~= true then
    table.insert(attempts, "native inline armory_open_tradebuy skipped: AllowNativeClientTradeBuyFallback=false")
    return false, "Native client TradeBuy fallback отключён: Prisoner.Client_Interact опасен в live route.", attempts
  end
  local okNative, message, data = nativeTraderCommandInline("armory_open_tradebuy", payload, timeoutMs)
  table.insert(attempts, "native inline armory_open_tradebuy=" .. tostring(okNative) .. ":" .. tostring(message))
  appendActionEvent("armory_native_tradebuy", okNative, live, message,
    '{"payload":' .. payload .. ',"nativeResponse":' .. tostring(data or "{}") .. '}')
  if okNative then
    return true, "Native TradeBuy interaction отправлен через Prisoner.Client_Interact.", attempts
  end
  return false, "SCUM не принял native TradeBuy interaction: " .. tostring(message), attempts
end

function armoryCommandDispatchInteraction(live, traderActor, attempts, options)
  attempts = attempts or {}
  options = options or {}
  if traderActor == nil or not isValidObject(traderActor) then
    table.insert(attempts, "TradeBuy=trader-invalid")
    return false, "Armory trader actor недоступен для TradeBuy.", attempts
  end
  if configBool("armory-command", { "RequireDispatchableTraderTarget", "requireDispatchableTraderTarget" }, true) == true then
    local dispatchable, dispatchDetail = armoryCommandDispatchableTraderCheck(traderActor, attempts)
    table.insert(attempts, "TradeBuy target dispatchable=" .. tostring(dispatchable) .. ":" .. tostring(dispatchDetail))
    if not dispatchable then
      return false, "Armory trader actor не прошёл проверку функционального оружейника: " .. tostring(dispatchDetail), attempts
    end
  end
  if configBool("armory-command", { "UseNativeTradeBuyDispatch", "useNativeTradeBuyDispatch" }, true) == true then
    return armoryCommandDispatchInteractionNative(live, traderActor, attempts, options)
  end
  if configBool("armory-command", { "AllowLuaTradeBuyDispatch", "allowLuaTradeBuyDispatch" }, false) ~= true then
    table.insert(attempts, "Lua TradeBuy dispatch blocked: AllowLuaTradeBuyDispatch=false")
    return false, "Lua TradeBuy отключён: используется только безопасный native route.", attempts
  end
  local rpc = (live or {}).rpc
  if rpc == nil or not isValidObject(rpc) then rpc = playerRpcChannel((live or {}).pc) end
  local interactionData = armoryCommandInteractionData(traderActor)
  local dispatchAll = configBool("armory-command", { "DispatchAllInteractionRoutes", "dispatchAllInteractionRoutes" }, true) == true
  local clientFirst = options.clientFirst == true or configBool("armory-command", { "DispatchClientInteractFirst", "dispatchClientInteractFirst" }, true) == true
  local numericOnly = options.numericOnly == true or configBool("armory-command", { "UseNumericTradeBuyOnly", "useNumericTradeBuyOnly" }, true) == true
  local skipTargetInteract = options.skipTargetInteract == true or configBool("armory-command", { "SkipTargetInteractForProxy", "skipTargetInteractForProxy" }, false) == true
  local allowClient = configBool("armory-command", { "AllowClientTradeBuyDispatch", "allowClientTradeBuyDispatch" }, true) == true
  local allowServer = configBool("armory-command", { "AllowServerTradeBuyDispatch", "allowServerTradeBuyDispatch" }, false) == true
  local clientOnly = options.clientOnly == true or configBool("armory-command", { "ClientOnlyTradeBuyDispatch", "clientOnlyTradeBuyDispatch" }, true) == true
  local allowTargetServer = configBool("armory-command", { "AllowTargetInteractTradeBuyDispatch", "allowTargetInteractTradeBuyDispatch" }, false) == true
  local allowPlayerRpcServer = configBool("armory-command", { "AllowPlayerRpcServerTradeBuyDispatch", "allowPlayerRpcServerTradeBuyDispatch" }, true) == true
  local allowPrisonerServer = configBool("armory-command", { "AllowPrisonerServerTradeBuyDispatch", "allowPrisonerServerTradeBuyDispatch" }, false) == true
  if not allowClient and not allowServer then
    table.insert(attempts, "TradeBuy dispatch disabled: both client and server routes disabled")
    return false, "TradeBuy dispatch отключён конфигом.", attempts
  end
  local routes = {}

  local function addClientRoutes()
    if not allowClient then
      table.insert(attempts, "Prisoner.Client_Interact skipped: AllowClientTradeBuyDispatch=false")
    elseif (live or {}).pawn ~= nil and isValidObject((live or {}).pawn) then
      table.insert(routes, { kind = "client", label = "Prisoner.Client_Interact#TradeBuy(238)", fn = function() return live.pawn:Client_Interact(traderActor, 238, interactionData) end })
      if not numericOnly then
        table.insert(routes, { kind = "client", label = "Prisoner.Client_Interact#TradeBuy(string)", fn = function() return live.pawn:Client_Interact(traderActor, "TradeBuy", interactionData) end })
      end
    else
      table.insert(attempts, "TradeBuy=pawn-missing-for-client")
    end
  end

  if clientFirst then addClientRoutes() end

  if clientOnly then
    table.insert(attempts, "server TradeBuy routes skipped: ClientOnlyTradeBuyDispatch=true")
  elseif not allowServer then
    table.insert(attempts, "server TradeBuy routes disabled by AllowServerTradeBuyDispatch=false after SCUMServer crash on direct TradeBuy")
  else
    if skipTargetInteract or not allowTargetServer then
      table.insert(attempts, "Trader.Interact direct target skipped")
    elseif (live or {}).pc ~= nil and isValidObject((live or {}).pc) then
      table.insert(routes, { kind = "server", label = "Trader.Interact#TradeBuy(238)", fn = function() return traderActor:Interact(live.pc, 238, interactionData) end })
      if not numericOnly then
        table.insert(routes, { kind = "server", label = "Trader.Interact#TradeBuy(string)", fn = function() return traderActor:Interact(live.pc, "TradeBuy", interactionData) end })
      end
    else
      table.insert(attempts, "TradeBuy=controller-missing-for-target-interact")
    end
    if not allowPlayerRpcServer then
      table.insert(attempts, "Rpc.InteractWithObjectOnServer skipped by AllowPlayerRpcServerTradeBuyDispatch=false")
    elseif rpc ~= nil and isValidObject(rpc) and (live or {}).pc ~= nil and isValidObject((live or {}).pc) then
      table.insert(routes, { kind = "server", label = "Rpc.InteractWithObjectOnServer#TradeBuy(238)", fn = function() return rpc:InteractWithObjectOnServer(traderActor, live.pc, 238, interactionData) end })
      if not numericOnly then
        table.insert(routes, { kind = "server", label = "Rpc.InteractWithObjectOnServer#TradeBuy(string)", fn = function() return rpc:InteractWithObjectOnServer(traderActor, live.pc, "TradeBuy", interactionData) end })
      end
    else
      table.insert(attempts, "TradeBuy=rpc-or-controller-missing")
    end
    if not allowPrisonerServer then
      table.insert(attempts, "Prisoner.InteractWithObjectOnServer skipped by AllowPrisonerServerTradeBuyDispatch=false")
    elseif (live or {}).pawn ~= nil and isValidObject((live or {}).pawn) then
      table.insert(routes, { kind = "server", label = "Prisoner.InteractWithObjectOnServer#TradeBuy(238)", fn = function() return live.pawn:InteractWithObjectOnServer(traderActor, 238, interactionData) end })
      if not numericOnly then
        table.insert(routes, { kind = "server", label = "Prisoner.InteractWithObjectOnServer#TradeBuy(string)", fn = function() return live.pawn:InteractWithObjectOnServer(traderActor, "TradeBuy", interactionData) end })
      end
    else
      table.insert(attempts, "TradeBuy=pawn-missing")
    end
  end
  if not clientFirst then addClientRoutes() end

  local anyAccepted = false
  local acceptedRoute = ""
  local acceptedRoutes = {}
  local serverAccepted = false
  local lastError = ""
  for _, route in ipairs(routes) do
    if not dispatchAll and serverAccepted and route.kind == "server" then
      table.insert(attempts, tostring(route.label) .. "=skipped:server-already-accepted")
    else
      appendLog("armory TradeBuy dispatch attempt route=" .. tostring(route.label) ..
        " kind=" .. tostring(route.kind or "") ..
        " target=" .. objectFullName(traderActor))
      local okCall, result = pcall(route.fn)
      table.insert(attempts, tostring(route.label) .. "=" .. (okCall and "ok" or tostring(result)))
      appendLog("armory TradeBuy dispatch result route=" .. tostring(route.label) ..
        " ok=" .. tostring(okCall) ..
        " result=" .. tostring(okCall and "ok" or result))
      if okCall then
        anyAccepted = true
        if route.kind == "server" then serverAccepted = true end
        table.insert(acceptedRoutes, tostring(route.label))
        if acceptedRoute == "" then acceptedRoute = tostring(route.label) end
        if not dispatchAll then break end
      else
        lastError = tostring(result)
      end
    end
  end
  if anyAccepted then
    return true, "TradeBuy interaction отправлен через " .. table.concat(acceptedRoutes, " + ") .. ".", attempts
  end
  return false, "SCUM не принял TradeBuy interaction: " .. tostring(lastError), attempts
end

function armoryCommandRoute()
  return tostring(configString("armory-command", { "Route", "route" }, "")):lower():gsub("^%s+", ""):gsub("%s+$", "")
end

function armoryCommandUsesStockTeleport()
  local route = armoryCommandRoute()
  if route == "stock-armory-teleport" or route == "real-a0-armory" or route == "real-stock-armory" then return true end
  return configBool("armory-command", { "UseStockArmoryTeleportFallback", "useStockArmoryTeleportFallback" }, false) == true
end

function armoryCommandUsesOriginalArmoryMenu()
  local route = armoryCommandRoute()
  return route == "open-original-armory-menu" or
    route == "remote-stock-armory-menu" or
    route == "stock-armory-menu" or
    route == "original-armory-menu"
end

function armoryCommandStockTeleportDestination()
  return {
    x = configNumber("armory-command", { "ArmoryTeleportX", "armoryTeleportX" }, -616470),
    y = configNumber("armory-command", { "ArmoryTeleportY", "armoryTeleportY" }, -548860),
    z = configNumber("armory-command", { "ArmoryTeleportZ", "armoryTeleportZ" }, 2450)
  }
end

function armoryRememberReturn(info)
  if info == nil or not playerHasUsableLocation(info) then return false end
  local record = '{"utc":' .. js(nowUtc()) ..
    ',"at":' .. tostring(os.time()) ..
    ',"steamId":' .. js(info.steam or info.steamId or "") ..
    ',"name":' .. js(info.name or "") ..
    ',"userProfileId":' .. js(info.userProfileId or info.serverUserProfileId or "") ..
    ',"x":' .. tostring(tonumber(info.x) or 0) ..
    ',"y":' .. tostring(tonumber(info.y) or 0) ..
    ',"z":' .. tostring(tonumber(info.z) or 0) .. '}'
  return appendJsonArray(STATE_DIR .. "\\armory-return.json", record, 512 * 1024)
end

function armoryLatestReturn(info)
  local latest = nil
  for _, object in ipairs(stateObjects("armory-return.json")) do
    if samePlayerRecord(info, object) then
      latest = {
        x = extractNumber(object, "x") or 0,
        y = extractNumber(object, "y") or 0,
        z = extractNumber(object, "z") or 0,
        at = extractNumber(object, "at") or 0
      }
    end
  end
  return latest
end

function armoryCommandTeleportToStockArmory(info)
  local live = resolvePlayerInfo((info or {}).steam, (info or {}).name, info, (info or {}).runtimeKey) or info
  if live == nil or not playerInfoHasLiveRuntime(live) then
    targetMessageResolved(info, "Armory не открыт: сервер ещё не видит твой live-персонаж. Подожди несколько секунд и повтори /armory.")
    return false, "live runtime missing"
  end
  local returnSaved = false
  if playerHasUsableLocation(live) then returnSaved = armoryRememberReturn(live) == true end
  local dest = armoryCommandStockTeleportDestination()
  targetMessageResolved(live, "Переношу к настоящему A_0 Armory. Это штатный оружейник с реальным ассортиментом; нажми F у торговца.")
  local sent, result = teleportResolved(live, dest.x, dest.y, dest.z)
  appendActionEvent("armory_open", sent == true, live, tostring(result or ""),
    '{"route":"stock-armory-teleport","x":' .. tostring(dest.x) ..
    ',"y":' .. tostring(dest.y) ..
    ',"z":' .. tostring(dest.z) ..
    ',"returnSaved":' .. tostring(returnSaved == true) ..
    ',"spawn":false,"tradeBuyDispatched":false}')
  if sent then
    targetMessageResolved(live, "Armory готовится через реального оружейника. После покупок используй /armoryback для возврата.")
    return true, "stock-armory-teleport"
  end
  targetMessageResolved(live, "Armory не открыт: не удалось переместить к реальному оружейнику. Детали записаны в action-log.")
  return false, tostring(result or "teleport failed")
end

function armoryCommandOpenOriginalArmoryMenu(live)
  local attempts = {
    "armory route=open-original-armory-menu",
    "no-chat-shop=true",
    "teleport=false",
    "spawn=false",
    "target stock BP_ArmsDealer_01_C resolved from original Armory TradePost _spawnedTraders"
  }
  local tradePost, detail, key, expectedFullName = armoryCommandFindStockArmoryTradePost(attempts)
  targetMessageResolved(live, "Открываю штатное меню " .. tostring(key or "A_0") .. " Armory без телепорта и без spawn NPC...")
  if tradePost == nil or not isValidObject(tradePost) then
    local data = '{"route":"open-original-armory-menu"' ..
      ',"stockOutpostKey":' .. js(tostring(key or "")) ..
      ',"expectedTradePost":' .. js(tostring(expectedFullName or "")) ..
      ',"tradePostResolved":false' ..
      ',"tradeBuyDispatched":false' ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("armory_open", false, live,
      "Original Armory TradePost was not found; server TradeBuy was not dispatched.",
      data)
    targetMessageResolved(live, "Armory не открыт: оригинальный Armory interaction box не найден в runtime. Причина записана в action-log.")
    return false, tostring(detail or "tradepost missing")
  end

  armoryCommandAddAttempt(attempts, "stockArmoryTradePost target=" .. objectFullName(tradePost) .. " detail=" .. tostring(detail or ""))
  local traderActor, traderDetail = armoryCommandTraderFromRegisteredTradePost(tradePost, attempts)
  armoryCommandAddAttempt(attempts, "stockArmoryTrader detail=" .. tostring(traderDetail or "") .. " target=" .. objectFullName(traderActor))
  if traderActor == nil or not isValidObject(traderActor) then
    local data = '{"route":"open-original-armory-menu"' ..
      ',"stockOutpostKey":' .. js(tostring(key or "")) ..
      ',"expectedTradePost":' .. js(tostring(expectedFullName or "")) ..
      ',"targetTradePost":' .. js(objectFullName(tradePost)) ..
      ',"targetTraderResolved":false' ..
      ',"tradePostResolved":true' ..
      ',"tradeBuyDispatched":false' ..
      ',"traderDetail":' .. js(tostring(traderDetail or "")) ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("armory_open", false, live,
      "Original Armory trader actor was not found in stock TradePost spawned traders; no interaction was dispatched.",
      data)
    targetMessageResolved(live, "Armory не открыт: оригинальный оружейник не найден в _spawnedTraders штатного Armory. Причина записана в action-log.")
    return false, tostring(traderDetail or "stock trader missing")
  end

  local tradeBuyDispatched, tradeBuyMessage = armoryCommandDispatchInteractionNative(live, traderActor, attempts, { skipDispatchableCheck = true })
  armoryCommandAddAttempt(attempts, "originalMenuTradeBuyDispatch=" .. tostring(tradeBuyDispatched) .. ":" .. tostring(tradeBuyMessage))
  local x, y, z = vectorOf(traderActor)
  local data = '{"route":"open-original-armory-menu"' ..
    ',"stockOutpostKey":' .. js(tostring(key or "")) ..
    ',"expectedTradePost":' .. js(tostring(expectedFullName or "")) ..
    ',"sourceTradePost":' .. js(objectFullName(tradePost)) ..
    ',"targetTrader":' .. js(objectFullName(traderActor)) ..
    ',"targetClass":' .. js(objectClassFullName(traderActor)) ..
    ',"targetKind":' .. js(armoryCommandTargetKind(traderActor)) ..
    ',"targetX":' .. tostring(tonumber(x) or 0) ..
    ',"targetY":' .. tostring(tonumber(y) or 0) ..
    ',"targetZ":' .. tostring(tonumber(z) or 0) ..
    ',"tradePostResolved":true' ..
    ',"targetTraderResolved":true' ..
    ',"traderDetail":' .. js(tostring(traderDetail or "")) ..
    ',"tradeBuyDispatched":' .. tostring(tradeBuyDispatched == true) ..
    ',"tradeBuyMessage":' .. js(tostring(tradeBuyMessage or "")) ..
    ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
  appendActionEvent("armory_open", tradeBuyDispatched == true, live,
    tradeBuyDispatched and "Original Armory trader TradeBuy dispatch was sent." or "Original Armory trader TradeBuy dispatch failed.",
    data)
  if tradeBuyDispatched then
    targetMessageResolved(live, "Запрос на штатное меню Armory отправлен. Если окно не появилось, я проверю native-response в action-log.")
    return true, tostring(tradeBuyMessage or "server tradebuy sent")
  end
  targetMessageResolved(live, "Armory не открыт: SCUM не принял TradeBuy на оригинального оружейника. Причина записана в action-log.")
  return false, tostring(tradeBuyMessage or "server tradebuy failed")
end

function armoryCommandReturnForInfo(info)
  local live = resolvePlayerInfo((info or {}).steam, (info or {}).name, info, (info or {}).runtimeKey) or info
  if live == nil or not playerInfoHasLiveRuntime(live) then
    targetMessageResolved(info, "Возврат невозможен: сервер ещё не видит твой live-персонаж.")
    return false, "live runtime missing"
  end
  local saved = armoryLatestReturn(live)
  if saved == nil then
    targetMessageResolved(live, "Нет сохранённой точки возврата после /armory.")
    return false, "no return point"
  end
  local sent, result = teleportResolved(live, saved.x, saved.y, saved.z)
  appendActionEvent("armory_return", sent == true, live, tostring(result or ""),
    '{"route":"stock-armory-teleport-return","x":' .. tostring(saved.x) ..
    ',"y":' .. tostring(saved.y) ..
    ',"z":' .. tostring(saved.z) ..
    ',"savedAt":' .. tostring(saved.at or 0) .. '}')
  targetMessageResolved(live, sent and "Возвращаю на точку, где ты вызвал /armory." or ("Возврат не сработал: " .. tostring(result or "")))
  return sent == true, tostring(result or "")
end

function armoryCommandResolveLiveSpawnInfo(info)
  local live = resolvePlayerInfo((info or {}).steam, (info or {}).name, info, (info or {}).runtimeKey)
  if live == nil or not playerInfoHasLiveRuntime(live) then
    return nil, false, "live-runtime-missing"
  end
  if serverLogIndicatesOffline(live) then
    return live, false, "server-log-offline"
  end
  live = refreshRuntimePlayerInfo(live) or live
  if live == nil or not playerInfoHasLiveRuntime(live) then
    return live, false, "live-runtime-stale"
  end
  if not playerHasUsableLocation(live) then
    return live, false, "live-location-missing"
  end
  return live, true, "ok"
end

function armoryCommandOpenForInfo(info)
  if not moduleEnabled("armory-command", true) then
    targetMessageResolved(info, "Armory сейчас отключён.")
    return false, "disabled"
  end
  if configBool("armory-command", { "DiagnosticSafeMode", "diagnosticSafeMode", "SafeTraceMode", "safeTraceMode" }, false) == true then
    appendActionEvent("armory_open", false, info,
      "Armory diagnostic safe mode: no prepare/spawn/TradeBuy dispatch.",
      '{"route":"diagnostic-safe-mode","prepare":false,"spawn":false,"tradeBuy":false}')
    targetMessageResolved(info, "Armory пока в безопасном режиме трассировки: штатный трейдер изучается, опасный TradeBuy не отправляю.")
    return false, "diagnostic-safe-mode"
  end
  local requiredPermission = configString("armory-command", { "RequiredPermission", "requiredPermission" }, "")
  if not hasPermission(info, requiredPermission) then
    targetMessageResolved(info, permissionDeniedText(requiredPermission))
    return false, "permission denied"
  end
  local live, liveReady, liveReason = armoryCommandResolveLiveSpawnInfo(info)
  if live == nil or not liveReady then
    appendActionEvent("armory_open", false, info,
      "Armory live spawn info is not ready.",
      '{"route":"spawn-functional-linked-armory-npc","stage":"resolve-live-spawn-info","reason":' .. js(tostring(liveReason or "")) .. '}')
    targetMessageResolved(info, "Armory не открыт: сервер ещё не видит твой live-персонаж. Подожди несколько секунд и повтори /armory.")
    return false, "live runtime missing"
  end
  if armoryCommandUsesStockTeleport() then
    return armoryCommandTeleportToStockArmory(live)
  end
  local key = playerStateKey(live)
  if key ~= "" and ARMORY_COMMAND_PENDING[key] == true then
    targetMessageResolved(live, "Armory уже открывается. Подожди пару секунд.")
    return false, "pending"
  end
  if key ~= "" then ARMORY_COMMAND_PENDING[key] = true end

  local function finish(success, message)
    if key ~= "" then ARMORY_COMMAND_PENDING[key] = nil end
    return success, message
  end

  if armoryCommandUsesOriginalArmoryMenu() then
    local okOriginal, originalMessage = armoryCommandOpenOriginalArmoryMenu(live)
    return finish(okOriginal, originalMessage)
  end

  local actorClass = armoryCommandActorClass()
  local attempts = {
    "armory route=spawn-functional-linked-armory-npc",
    "no-chat-shop=true",
    "forced-tradebuy=false",
    "manual-client-interact=true",
    "spawn real BP_ArmsDealer_01_C linked to stock Armory TradePost/manager"
  }
  targetMessageResolved(live, "Готовлю функционального оружейника через штатный SCUM trader lifecycle...")

  local maxRetries = math.max(0, math.min(math.floor(configNumber("armory-command", { "SpawnRetryCount", "spawnRetryCount", "LinkedTraderRetryCount", "linkedTraderRetryCount" }, 2) or 2), 5))
  local pinWarmupMs = math.max(500, math.min(math.floor(configNumber("armory-command", { "OutpostPinWarmupMs", "outpostPinWarmupMs", "StreamingWarmupDelayMs", "streamingWarmupDelayMs" }, 6500) or 6500), 30000))
  local replicationDelayMs = math.max(0, math.min(math.floor(configNumber("armory-command", { "LinkedTraderReplicationDelayMs", "linkedTraderReplicationDelayMs", "ReplicationDelayMs", "replicationDelayMs" }, 2500) or 2500), 15000))

  local function completeSuccess(current, spawnMessage, spawnData, traderActor)
    local traderResolved = traderActor ~= nil and isValidObject(traderActor)
    local spawnedTraderFullName = traderResolved and objectFullName(traderActor) or tostring(extractString(spawnData or "", "spawnedTrader") or "")
    local nativeLinkResultOnly = configBool("armory-command", { "UseNativeLinkResultOnly", "useNativeLinkResultOnly", "SkipLuaArmoryPostLinkRuntimeScans", "skipLuaArmoryPostLinkRuntimeScans" }, true) == true
    local requireManagerReady = configBool("armory-command", { "RequireLinkedTraderManagerForReady", "requireLinkedTraderManagerForReady", "RequireManagerLinked", "requireManagerLinked" }, true) == true
    local managerLinked = extractBool(spawnData or "", "managerLinked", false) == true
    local lifecycleLinkOk = extractBool(spawnData or "", "lifecycleLinkOk", false) == true
    local managerlessMarkerLinkOk = extractBool(spawnData or "", "managerlessMarkerLinkOk", false) == true
    local prepareOk, prepareMessage, prepareData = true, "skipped:native-link-result-only", "{}"
    if nativeLinkResultOnly then
      armoryCommandAddAttempt(attempts, "prepareAnywhereAfterSpawn skipped: native-link-result-only")
      armoryCommandAddAttempt(attempts, "TradeBuy replication prep skipped: native-link-result-only")
    else
      prepareOk, prepareMessage, prepareData = armoryCommandPrepareAnywhereRuntime(current, attempts)
      armoryCommandAddAttempt(attempts, "prepareAnywhereAfterSpawn=" .. tostring(prepareOk) .. ":" .. tostring(prepareMessage))
      if traderResolved then
        armoryCommandPrepareActorForTradeBuy(traderActor, attempts)
      else
        armoryCommandAddAttempt(attempts, "TradeBuy replication prep skipped: Lua actor resolve missing")
      end
    end
    local proxyRegistered = false
    if traderResolved and configBool("armory-command", { "AllowArmoryLinkedProxyRegister", "allowArmoryLinkedProxyRegister" }, false) == true then
      proxyRegistered = armoryCommandRegisterLinkedTraderProxyRoute(traderActor, spawnData, actorClass, attempts)
    else
      armoryCommandAddAttempt(attempts, "linkedProxyRegister skipped: disabled-no-postscan")
    end
    local verifyOk, verifyMessage, verifyData = true, "native-link-result-only", spawnData or "{}"
    if traderResolved and configBool("armory-command", { "AllowArmoryLinkedVerifyRuntime", "allowArmoryLinkedVerifyRuntime" }, false) == true then
      verifyOk, verifyMessage, verifyData = armoryCommandVerifyLinkedTraderRuntime(traderActor, spawnData, attempts)
    else
      armoryCommandAddAttempt(attempts, "linkedVerify skipped: disabled-no-postscan")
    end
    local distance = traderResolved and runtimeDistanceToInfo(traderActor, current) or -1
    if requireManagerReady and not managerLinked then
      if configBool("armory-command", { "DestroyManagerlessArmoryTrader", "destroyManagerlessArmoryTrader" }, true) == true then
        if traderResolved then
          destroySpawnedItem(traderActor)
          armoryCommandAddAttempt(attempts, "destroyManagerlessArmoryTrader=sent")
        else
          armoryCommandAddAttempt(attempts, "destroyManagerlessArmoryTrader skipped: Lua actor resolve missing")
        end
      end
      local failData = '{"actorClass":' .. js(actorClass) ..
        ',"route":"spawn-functional-linked-armory-npc"' ..
        ',"spawnedTrader":' .. js(spawnedTraderFullName) ..
        ',"targetDistance":' .. tostring(math.floor(tonumber(distance) or -1)) ..
        ',"managerLinked":false' ..
        ',"lifecycleLinkOk":' .. tostring(lifecycleLinkOk == true) ..
        ',"managerlessMarkerLinkOk":' .. tostring(managerlessMarkerLinkOk == true) ..
        ',"proxyRegistered":' .. tostring(proxyRegistered == true) ..
        ',"prepareOk":' .. tostring(prepareOk == true) ..
        ',"prepareResponse":' .. tostring(prepareData or "{}") ..
        ',"verifyOk":' .. tostring(verifyOk == true) ..
        ',"verifyMessage":' .. js(tostring(verifyMessage or "")) ..
        ',"manualClientInteract":true' ..
        ',"tradeBuyDispatched":false' ..
        ',"nativeResponse":' .. tostring(spawnData or "{}") ..
        ',"verifyResponse":' .. tostring(verifyData or "{}") ..
        ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
      appendActionEvent("armory_open", false, current,
        "Armory linked trader rejected: live TradeOutpostManager/economy lifecycle was not found.",
        failData)
      targetMessageResolved(current, "Armory не открыт: stock TradeOutpostManager/economy не найден, поэтому такой оружейник будет без ассортимента. Сломанный NPC удалён; опасный TradeBuy не отправлял.")
      finish(false, "manager missing")
      return
    end
    if not verifyOk then
      local failData = '{"actorClass":' .. js(actorClass) ..
        ',"route":"spawn-functional-linked-armory-npc"' ..
        ',"spawnedTrader":' .. js(spawnedTraderFullName) ..
        ',"targetDistance":' .. tostring(math.floor(tonumber(distance) or -1)) ..
        ',"proxyRegistered":' .. tostring(proxyRegistered == true) ..
        ',"prepareOk":' .. tostring(prepareOk == true) ..
        ',"prepareResponse":' .. tostring(prepareData or "{}") ..
        ',"verifyOk":false' ..
        ',"verifyMessage":' .. js(tostring(verifyMessage or "")) ..
        ',"manualClientInteract":true' ..
        ',"tradeBuyDispatched":false' ..
        ',"nativeResponse":' .. tostring(spawnData or "{}") ..
        ',"verifyResponse":' .. tostring(verifyData or "{}") ..
        ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
      appendActionEvent("armory_open", false, current,
        "Armory linked trader spawned but graph verification failed; unsafe TradeBuy was not dispatched.",
        failData)
      targetMessageResolved(current, "Armory не открыт: оружейник создан, но связь с TradePost/economy не подтверждена. Опасный TradeBuy не отправлял.")
      finish(false, tostring(verifyMessage or "verify failed"))
      return
    end
    local tradeBuyDispatched = false
    local tradeBuyMessage = "skipped"
    if traderResolved and configBool("armory-command", { "OpenTradeMenuAfterLinkedSpawn", "openTradeMenuAfterLinkedSpawn", "UseNativeTargetInteractDispatch", "useNativeTargetInteractDispatch", "UseNativeServerTradeBuyDispatch", "useNativeServerTradeBuyDispatch", "UseNativeTradeBuyDispatch", "useNativeTradeBuyDispatch" }, false) == true then
      tradeBuyDispatched, tradeBuyMessage = armoryCommandDispatchInteractionNative(current, traderActor, attempts, {})
      armoryCommandAddAttempt(attempts, "linkedSpawnTradeBuyDispatch=" .. tostring(tradeBuyDispatched) .. ":" .. tostring(tradeBuyMessage))
    else
      armoryCommandAddAttempt(attempts, traderResolved and "linkedSpawnTradeBuyDispatch skipped: disabled" or "linkedSpawnTradeBuyDispatch skipped: Lua actor resolve missing")
    end
    local data = '{"actorClass":' .. js(actorClass) ..
      ',"route":"spawn-functional-linked-armory-npc"' ..
      ',"spawnedTrader":' .. js(spawnedTraderFullName) ..
      ',"targetDistance":' .. tostring(math.floor(tonumber(distance) or -1)) ..
      ',"proxyRegistered":' .. tostring(proxyRegistered == true) ..
      ',"prepareOk":' .. tostring(prepareOk == true) ..
      ',"prepareResponse":' .. tostring(prepareData or "{}") ..
      ',"verifyOk":true' ..
      ',"verifyResponse":' .. tostring(verifyData or "{}") ..
      ',"manualClientInteract":true' ..
      ',"tradeBuyDispatched":' .. tostring(tradeBuyDispatched == true) ..
      ',"tradeBuyMessage":' .. js(tostring(tradeBuyMessage or "")) ..
      ',"nativeResponse":' .. tostring(spawnData or "{}") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("armory_open", true, current,
      tradeBuyDispatched and "Armory linked trader spawned and server TradeBuy dispatch was sent." or "Armory linked trader spawned; player must open it through normal F-interact.",
      data)
    local function tellReady()
      if tradeBuyDispatched then
        targetMessageResolved(current, "Оружейник появился рядом, серверный TradeBuy отправлен. Если меню не открылось автоматически, подойди и нажми F.")
      else
        targetMessageResolved(current, "Оружейник появился рядом. Подойди к нему и нажми F: меню Armory должно открыться штатно.")
      end
    end
    if replicationDelayMs > 0 then
      targetMessageResolved(current, "Оружейник создан, жду репликацию клиенту...")
      if deferGame(replicationDelayMs, tellReady) then
        finish(true, spawnMessage or "spawned")
        return
      end
    end
    tellReady()
    finish(true, spawnMessage or "spawned")
  end

  local trySpawn
  trySpawn = function(retriesLeft, stage)
    local current, currentReady, currentReason = armoryCommandResolveLiveSpawnInfo(live)
    if current == nil or not currentReady then
      appendActionEvent("armory_open", false, live,
        "Armory retry stopped because player live spawn info is no longer usable.",
        '{"route":"spawn-functional-linked-armory-npc","stage":"resolve-live-spawn-info-retry","reason":' .. js(tostring(currentReason or "")) .. ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}')
      targetMessageResolved(info, "Armory не открыт: live-персонаж пропал из runtime. Повтори /armory после входа в игру.")
      finish(false, "live runtime missing")
      return
    end

    armoryCommandAddAttempt(attempts, "spawn attempt stage=" .. tostring(stage or "initial") .. " retriesLeft=" .. tostring(retriesLeft or 0))
    local spawnOk, spawnMessage, spawnData, spawnedTrader = armoryCommandSpawnLinkedTraderRuntime(current, attempts)
    armoryCommandAddAttempt(attempts, "linkedSpawn=" .. tostring(spawnOk) .. ":" .. tostring(spawnMessage) .. " trader=" .. objectFullName(spawnedTrader))
    if spawnOk then
      completeSuccess(current, spawnMessage, spawnData, spawnedTrader)
      return
    end

    if (tonumber(retriesLeft) or 0) > 0 then
      targetMessageResolved(current, "Поднимаю stock Armory outpost lifecycle и повторю spawn...")
      local pinOk, pinMessage = armoryCommandPinOutpostRuntime(attempts, "armory-spawn-retry-" .. tostring(retriesLeft))
      armoryCommandAddAttempt(attempts, "pinBeforeRetry=" .. tostring(pinOk) .. ":" .. tostring(pinMessage))
      if deferGame(pinWarmupMs, function() trySpawn((tonumber(retriesLeft) or 0) - 1, "after-outpost-pin") end) then
        return
      end
      trySpawn((tonumber(retriesLeft) or 0) - 1, "after-outpost-pin-immediate")
      return
    end

    local data = '{"actorClass":' .. js(actorClass) ..
      ',"route":"spawn-functional-linked-armory-npc"' ..
      ',"ok":false' ..
      ',"lastSpawnMessage":' .. js(tostring(spawnMessage or "")) ..
      ',"lastNativeResponse":' .. tostring(spawnData or "{}") ..
      ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
    appendActionEvent("armory_open", false, current,
      "Armory linked trader spawn failed; unsafe TradeBuy was not dispatched.",
      data)
    targetMessageResolved(current, "Armory не открыт: функциональный оружейник не создан. Опасный TradeBuy не отправлял; причина записана в action-log.")
    finish(false, tostring(spawnMessage or "spawn failed"))
  end

  if configBool("armory-command", { "PinOutpostRuntimeBeforeFirstSpawn", "pinOutpostRuntimeBeforeFirstSpawn" }, false) == true then
    armoryCommandPinOutpostRuntime(attempts, "armory-before-first-spawn")
    if deferGame(pinWarmupMs, function() trySpawn(maxRetries, "after-initial-pin") end) then
      return true, "queued"
    end
  end
  trySpawn(maxRetries, "initial")
  return true, "queued"
end

EDITOR_ACTOR_COMMAND_PENDING = EDITOR_ACTOR_COMMAND_PENDING or {}
EDITOR_ACTOR_TARGET_CACHE = EDITOR_ACTOR_TARGET_CACHE or {}
EDITOR_ACTOR_TARGET_HOOK_STATUS = EDITOR_ACTOR_TARGET_HOOK_STATUS or {}
EDITOR_ACTOR_TARGET_HOOK_FAILURES = EDITOR_ACTOR_TARGET_HOOK_FAILURES or {}
EDITOR_ACTOR_TARGET_TRACE_COUNT = EDITOR_ACTOR_TARGET_TRACE_COUNT or 0

function editorActorTargetCacheTtlSeconds()
  return math.max(2, math.min(configNumber("actor-editor", { "TargetCacheTtlSeconds", "targetCacheTtlSeconds" }, 35), 300))
end

function editorActorCacheKeys(info, contextObj)
  local keys = {}
  local seen = {}
  local function add(key)
    key = tostring(key or "")
    if key == "" or key == "unknown" or seen[key] then return end
    seen[key] = true
    table.insert(keys, key)
  end
  local function addValue(prefix, value)
    value = tostring(value or "")
    if value == "" or value == "unknown" then return end
    add(tostring(prefix or "") .. value)
  end
  if info ~= nil then
    add(transientPlayerKey(info))
    addValue("steam:", info.steam or info.steamId)
    addValue("runtime:", info.runtimeKey)
    addValue("name:", tostring(info.name or ""):lower())
    addValue("profile:", info.userProfileId or info.serverUserProfileId)
    addValue("pc:", info.pcKey or objectKey(info.pc))
    addValue("pawn:", info.pawnKey or objectKey(info.pawn))
    addValue("rpc:", info.rpcKey or objectKey(info.rpc))
    addValue("ps:", info.psKey or objectKey(info.ps))
  end
  if contextObj ~= nil and isValidObject(contextObj) then
    addValue("obj:", objectKey(contextObj))
    addValue("db:", chatObjectDbId(contextObj))
  end
  return keys
end

function editorActorLuaBlockReason(target)
  if target == nil or not isValidObject(target) then return "target-missing" end
  local full = objectFullName(target)
  local className = objectClassFullName(target)
  local haystack = (full .. " " .. className):lower()
  if haystack == "" then return "target-name-missing" end
  if haystack:find("default__", 1, true) ~= nil then return "class-default-object" end
  if haystack:find("^class%s") ~= nil or haystack:find("/script/coreuobject.class", 1, true) ~= nil then return "class-object" end
  local blocked = {
    {"/script/scum.trader", "trader-class"},
    {"bp_armsdealer", "trader-blueprint"},
    {"bp_banker", "trader-blueprint"},
    {"bp_barber", "trader-blueprint"},
    {"bp_bartender", "trader-blueprint"},
    {"bp_doctor", "trader-blueprint"},
    {"bp_general_goods", "trader-blueprint"},
    {"bp_harbourmaster", "trader-blueprint"},
    {"bp_mechanic", "trader-blueprint"},
    {"npcinteractionbox", "tradepost-interaction-box"},
    {"tradeoutpost", "tradepost-manager-or-route"},
    {"tradepost", "tradepost-manager-or-route"},
    {"economymanager", "economy-manager"},
    {"/script/scum.prisoner", "player-or-prisoner-class"},
    {"conzplayer", "player-or-prisoner-class"},
    {"playercontroller", "player-controller"},
    {"controller", "controller"},
    {"inventorycomponent", "inventory"},
    {"/script/scum.item", "item-class"},
    {"itementitysetup", "item-setup"},
    {"/script/scum.zombie", "creature"},
    {"/script/scum.sentry", "creature"},
    {"/script/scum.brenner", "creature"},
    {"bp_zombie", "creature-blueprint"},
    {"bp_sentry", "creature-blueprint"},
    {"bp_brenner", "creature-blueprint"},
    {"bp_razor", "creature-blueprint"},
    {"npcguard", "npc-guard"},
    {"guardedzonemanager", "npc-manager"},
    {"levelscriptactor", "level-script-actor"},
    {"worldsettings", "world-settings"},
    {"gamemode", "game-mode"},
    {"gamestate", "game-state"},
    {"playerstart", "player-start"},
    {"navigation", "navigation"},
    {"navmesh", "navigation"},
    {"volume", "volume-or-trigger"},
    {"trigger", "volume-or-trigger"},
    {"blockingvolume", "volume-or-trigger"},
    {"camera", "camera"},
    {"lightmass", "lighting"},
    {"skylight", "lighting"},
    {"directionallight", "lighting"},
    {"pointlight", "lighting"},
    {"spotlight", "lighting"},
    {"reflectioncapture", "reflection-capture"},
    {"postprocess", "post-process"},
    {"audio", "audio"},
    {"sound", "audio"},
    {"foliage", "foliage"},
    {"landscape", "landscape"},
    {"waterbody", "water"}
  }
  for _, row in ipairs(blocked) do
    if haystack:find(row[1], 1, true) ~= nil then return row[2] end
  end
  return ""
end

function editorActorInfoFromHookContext(contextObj, playerContextObj, source)
  local info = directPlayerInfoFromObject(playerContextObj, source or "actor-editor-target")
  if info == nil then info = findPlayerByLinkedObject(playerContextObj) end
  if info == nil then info = cachedPlayerByObject(playerContextObj) end
  if info == nil then info = directPlayerInfoFromObject(contextObj, source or "actor-editor-context") end
  if info == nil then info = findPlayerByLinkedObject(contextObj) end
  if info == nil then info = cachedPlayerByObject(contextObj) end
  return enrichPlayerInfoFromServerLog(info) or info
end

function editorActorRememberTarget(info, source, target, contextObj, interactionTypeText)
  local blockReason = editorActorLuaBlockReason(target)
  if blockReason ~= "" then return false, blockReason end
  local fullName = objectFullName(target)
  if fullName == "" then return false, "target-fullname-missing" end
  local keys = editorActorCacheKeys(info, contextObj)
  if #keys == 0 then return false, "player-key-missing" end
  local record = {
    actorFullName = fullName,
    actorClassFullName = objectClassFullName(target),
    actorKey = objectKey(target),
    source = tostring(source or "target-hook"),
    interactionType = tostring(interactionTypeText or ""),
    utc = nowUtc(),
    clock = os.clock()
  }
  local changed = false
  for _, key in ipairs(keys) do
    local old = EDITOR_ACTOR_TARGET_CACHE[key]
    if old == nil or tostring(old.actorFullName or "") ~= fullName then changed = true end
    EDITOR_ACTOR_TARGET_CACHE[key] = record
  end
  if changed then
    appendLog("actor-editor target cached source=" .. tostring(source or "") ..
      " player=" .. tostring((info or {}).name or (info or {}).steam or "") ..
      " target=" .. fullName ..
      " class=" .. tostring(record.actorClassFullName or "") ..
      " key=" .. tostring(record.actorKey or ""))
  end
  if changed and configBool("bridge-safety", { "EnableActorEditorTargetTrace", "enableActorEditorTargetTrace" }, false) == true then
    local maxCount = math.max(1, math.min(math.floor(configNumber("bridge-safety", { "ActorEditorTargetTraceMaxPerBoot", "actorEditorTargetTraceMaxPerBoot" }, 80) or 80), 500))
    if (EDITOR_ACTOR_TARGET_TRACE_COUNT or 0) < maxCount then
      EDITOR_ACTOR_TARGET_TRACE_COUNT = (EDITOR_ACTOR_TARGET_TRACE_COUNT or 0) + 1
      appendActionEvent("actor_editor_target_cache", true, info,
        "ED target captured: " .. editorActorLabelFromResult('{"actorFullName":' .. js(fullName) .. '}'),
        '{"source":' .. js(source or "") ..
          ',"interactionType":' .. js(interactionTypeText or "") ..
          ',"actorFullName":' .. js(fullName) ..
          ',"actorClassFullName":' .. js(record.actorClassFullName or "") ..
          ',"keys":' .. js(table.concat(keys, ",")) .. '}')
    end
  end
  return true, "cached"
end

function editorActorLatestTargetForInfo(info)
  local keys = editorActorCacheKeys(info, nil)
  local ttl = editorActorTargetCacheTtlSeconds()
  local best = nil
  for _, key in ipairs(keys) do
    local record = EDITOR_ACTOR_TARGET_CACHE[key]
    if record ~= nil then
      local age = os.clock() - (tonumber(record.clock) or 0)
      if age <= ttl then
        if best == nil or (tonumber(record.clock) or 0) > (tonumber(best.clock) or 0) then
          best = record
        end
      else
        EDITOR_ACTOR_TARGET_CACHE[key] = nil
      end
    end
  end
  return best
end

function editorActorLatestAnyTarget(preferFullName)
  local ttl = editorActorTargetCacheTtlSeconds()
  local best = nil
  local preferred = nil
  local wantedFull = tostring(preferFullName or "")
  for key, record in pairs(EDITOR_ACTOR_TARGET_CACHE or {}) do
    local age = os.clock() - (tonumber((record or {}).clock) or 0)
    if age <= ttl and tostring((record or {}).actorKey or "") ~= "" then
      if best == nil or (tonumber(record.clock) or 0) > (tonumber(best.clock) or 0) then
        best = record
      end
      if wantedFull ~= "" and tostring(record.actorFullName or "") == wantedFull then
        if preferred == nil or (tonumber(record.clock) or 0) > (tonumber(preferred.clock) or 0) then
          preferred = record
        end
      end
    elseif record ~= nil then
      EDITOR_ACTOR_TARGET_CACHE[key] = nil
    end
  end
  return preferred or best
end

function appendJsonObjectFields(text, fields)
  if fields == nil or #fields == 0 then return text end
  local payload = tostring(text or "")
  local extra = table.concat(fields, ",")
  if payload:match("^%s*{") and payload:match("}%s*$") then
    return payload:gsub("}%s*$", "," .. extra .. "}")
  end
  return "{" .. extra .. ',"rawPayload":' .. js(payload) .. "}"
end

function editorActorServerPointerFields(record, sourceLabel)
  if record == nil or tostring(record.actorKey or "") == "" then return {} end
  local age = math.max(0, math.floor((os.clock() - (tonumber(record.clock) or os.clock())) + 0.5))
  return {
    '"serverActorAddress":' .. js(record.actorKey or ""),
    '"serverActorFullName":' .. js(record.actorFullName or ""),
    '"serverActorClassFullName":' .. js(record.actorClassFullName or ""),
    '"serverActorTargetSource":' .. js((sourceLabel or "server-target-cache") .. ":" .. tostring(record.source or "")),
    '"serverActorTargetAgeSeconds":' .. tostring(age)
  }
end

function actorEditorAugmentPayloadWithServerTarget(text, runtimeKey)
  if configBool("actor-editor", { "EnableServerPointerPayload", "enableServerPointerPayload" }, true) ~= true then
    return text, nil
  end
  if tostring(extractStringAny(text, { "serverActorAddress", "serverActorKey", "actorAddress", "actorPointerAddress" }) or "") ~= "" then
    return text, nil
  end

  local steamId = extractStringAny(text, { "steamId", "targetSteamId", "SteamId", "TargetSteamId" }) or ""
  local name = extractStringAny(text, { "name", "targetName", "playerName", "Name", "TargetName" }) or ""
  local targetRuntime = extractStringAny(text, { "runtimeKey", "targetRuntimeKey", "RuntimeKey", "TargetRuntimeKey" }) or runtimeKey or ""
  local clientFullName = extractStringAny(text, { "actorFullName", "targetActorFullName", "targetFullName", "fullName" }) or ""
  local info = nil
  if steamId ~= "" or name ~= "" or tostring(targetRuntime or "") ~= "" then
    info = resolvePlayerInfo(steamId, name, nil, targetRuntime) or findPlayer(steamId, name, targetRuntime)
  end

  local target = nil
  local sourceLabel = "latest"
  if info ~= nil then
    local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
    target = editorActorLatestTargetForInfo(live)
    sourceLabel = "player"
  end
  if target == nil then
    target = editorActorLatestAnyTarget(clientFullName)
  end
  if target == nil or tostring(target.actorKey or "") == "" then
    if configBool("bridge-safety", { "EnableActorEditorServerPointerPayloadTrace", "enableActorEditorServerPointerPayloadTrace" }, true) == true then
      appendLog("actor-editor server pointer payload missing runtimeKey=" .. tostring(targetRuntime or "") ..
        " steam=" .. tostring(steamId or "") ..
        " name=" .. tostring(name or "") ..
        " clientFullName=" .. tostring(clientFullName or ""))
    end
    return text, "server-target-cache-missing"
  end

  local fields = editorActorServerPointerFields(target, sourceLabel)
  if clientFullName ~= "" then
    table.insert(fields, '"clientActorFullName":' .. js(clientFullName))
  end
  if configBool("bridge-safety", { "EnableActorEditorServerPointerPayloadTrace", "enableActorEditorServerPointerPayloadTrace" }, true) == true then
    appendLog("actor-editor server pointer payload attached key=" .. tostring(target.actorKey or "") ..
      " source=" .. tostring(sourceLabel or "") .. ":" .. tostring(target.source or "") ..
      " ageSeconds=" .. tostring(math.max(0, math.floor((os.clock() - (tonumber(target.clock) or os.clock())) + 0.5))) ..
      " clientFullName=" .. tostring(clientFullName or ""))
  end
  return appendJsonObjectFields(text, fields), "server-target-cache"
end

function editorActorRememberTargetFromHook(path, kind, context, targetParam, playerContextParam, interactionTypeParam)
  local contextObj = unwrapHookParam(context)
  local targetObj = unwrapHookParam(targetParam)
  local playerContextObj = unwrapHookParam(playerContextParam)
  if kind == "hovered" then
    targetObj = contextObj
  end
  if playerContextObj == nil or not isValidObject(playerContextObj) then
    playerContextObj = contextObj
  end
  local info = editorActorInfoFromHookContext(contextObj, playerContextObj, "actor-editor-target-" .. tostring(kind or "hook"))
  local interactionText = ""
  if interactionTypeParam ~= nil then interactionText = interactionTypeTextForHook(interactionTypeParam) end
  local okCache, detail = editorActorRememberTarget(info, tostring(kind or "hook") .. ":" .. tostring(path or ""), targetObj, playerContextObj, interactionText)
  if not okCache and configBool("bridge-safety", { "EnableActorEditorTargetFailureTrace", "enableActorEditorTargetFailureTrace" }, false) == true then
    appendLog("actor-editor target cache skipped kind=" .. tostring(kind or "") ..
      " path=" .. tostring(path or "") ..
      " reason=" .. tostring(detail or ""))
  end
end

function editorActorCommandKey(info)
  local key = playerCommandQueueKey(info)
  if key ~= "" then return key end
  return transientPlayerKey(info)
end

function editorActorLabelFromResult(nativeResult)
  local fullName = extractStringAny(nativeResult or "", {
    "actorFullName", "sourceActorFullName", "spawnedActorFullName", "targetActorFullName"
  }) or ""
  if fullName == "" then return "actor" end
  local value = fullName:gsub("^%s+", ""):gsub("%s+$", "")
  local space = value:find(" ")
  if space ~= nil then value = value:sub(space + 1) end
  local last = 0
  for pos in value:gmatch("()[%./:]") do last = pos end
  if last > 0 and last < #value then value = value:sub(last + 1) end
  if #value > 48 then value = value:sub(1, 48) end
  return value ~= "" and value or "actor"
end

function editorActorHelpText()
  return "ED: наведи/взаимодействуй с объектом, затем /ed f|b|l|r|up|down|yl|yr|copy|hide. /ed target покажет текущую серверную цель."
end

function editorActorNumber(words, index, fallback, minValue, maxValue)
  local value = tonumber(words[index] or "")
  if value == nil then value = tonumber(fallback) or 0 end
  if minValue ~= nil and value < minValue then value = minValue end
  if maxValue ~= nil and value > maxValue then value = maxValue end
  return value
end

function editorActorSeedJson(info, extraFields)
  local fields = {
    '"steamId":' .. js((info or {}).steam or (info or {}).steamId or ""),
    '"name":' .. js((info or {}).name or ""),
    '"runtimeKey":' .. js((info or {}).runtimeKey or ""),
    '"traceDistanceCm":' .. tostring(configNumber("actor-editor", { "TraceDistanceCm", "traceDistanceCm" }, 5500)),
    '"traceRadiusCm":' .. tostring(configNumber("actor-editor", { "TraceRadiusCm", "traceRadiusCm" }, 55)),
    '"aimToleranceCm":' .. tostring(configNumber("actor-editor", { "AimToleranceCm", "aimToleranceCm" }, 260)),
    '"aimTolerancePerMeter":' .. tostring(configNumber("actor-editor", { "AimTolerancePerMeter", "aimTolerancePerMeter" }, 1.5)),
    '"eyeOffsetZ":' .. tostring(configNumber("actor-editor", { "EyeOffsetZ", "eyeOffsetZ" }, 120))
  }
  for _, field in ipairs(extraFields or {}) do
    if field ~= nil and tostring(field) ~= "" then table.insert(fields, tostring(field)) end
  end
  return "{" .. table.concat(fields, ",") .. "}"
end

function editorActorSendNative(info, action, nativeCommand, seedJson, confirm, timeoutMs, successText)
  local live = resolvePlayerInfo((info or {}).steam, (info or {}).name, info, (info or {}).runtimeKey) or info
  if live == nil or not playerInfoHasLiveRuntime(live) then
    targetMessageResolved(info, "ED: сервер ещё не видит твой live-персонаж. Подожди пару секунд и повтори.")
    return false
  end

  local pendingKey = editorActorCommandKey(live)
  if pendingKey ~= "" and EDITOR_ACTOR_COMMAND_PENDING[pendingKey] == true then
    targetMessageResolved(live, "ED: предыдущая команда ещё выполняется.")
    return true
  end

  local payload, payloadMessage = hektorEditorPayload(seedJson, live.runtimeKey, confirm or "")
  if payload == nil then
    targetMessageResolved(live, "ED: " .. tostring(payloadMessage or "не удалось собрать payload."))
    return false
  end
  payload = actorEditorAugmentPayloadWithServerTarget(payload, live.runtimeKey)
  local resolvedActorFullName = extractStringAny(payload, { "actorFullName", "targetActorFullName", "targetFullName", "fullName", "objectPath", "targetObjectPath" }) or ""
  local resolvedActorAddress = extractStringAny(payload, { "serverActorAddress", "serverActorKey", "actorAddress", "actorPointerAddress" }) or ""
  if resolvedActorFullName == "" and resolvedActorAddress == "" then
    targetMessageResolved(live, "ED: цель ещё не захвачена сервером. Наведись на объект, дождись обычной подсказки взаимодействия или нажми F/ESC без действия, затем повтори /ed target.")
    return false
  end

  if pendingKey ~= "" then EDITOR_ACTOR_COMMAND_PENDING[pendingKey] = true end
  local requestId = "ed-" .. tostring(action or "cmd") .. "-" .. tostring(os.time()) .. "-" .. tostring(math.floor(os.clock() * 1000000))
  local sent, message, data = nativeTraderCommandAsync("editor_actor_" .. tostring(action or "cmd"), nativeCommand, payload, timeoutMs or 10000, requestId, function(okNative, nativeMessage, nativeResult)
    if pendingKey ~= "" then EDITOR_ACTOR_COMMAND_PENDING[pendingKey] = nil end
    if okNative then
      if action == "nudge" then rememberEditorActorNativeResult("nudge", payload, nativeResult) end
      if action == "copy" then rememberEditorActorNativeResult("copy", payload, nativeResult) end
      if action == "hide" then rememberEditorActorNativeResult("hide", payload, nativeResult) end
      targetMessageResolved(live, tostring(successText or "ED: готово.") .. " [" .. editorActorLabelFromResult(nativeResult) .. "]")
    else
      targetMessageResolved(live, "ED: не выполнено: " .. tostring(nativeMessage or "native failed"))
    end
  end)
  if sent == nil and data == "__async__" then
    targetMessageResolved(live, "ED: команда отправлена серверному editor bridge.")
    return true
  end
  if pendingKey ~= "" then EDITOR_ACTOR_COMMAND_PENDING[pendingKey] = nil end
  if sent then
    targetMessageResolved(live, tostring(successText or "ED: готово.") .. " [" .. editorActorLabelFromResult(data) .. "]")
    return true
  end
  targetMessageResolved(live, "ED: " .. tostring(message or "команда не отправлена."))
  return false
end

function handleEditorActorCommand(info, words)
  if not moduleEnabled("actor-editor", true) then
    targetMessageResolved(info, "ED: actor editor сейчас отключён.")
    return true
  end
  local requiredPermission = configString("actor-editor", { "RequiredPermission", "requiredPermission" }, "")
  if not hasPermission(info, requiredPermission) then
    targetMessageResolved(info, permissionDeniedText(requiredPermission))
    return true
  end

  local sub = tostring(words[2] or "help"):lower()
  if sub == "" or sub == "help" or sub == "h" or sub == "?" then
    targetMessageResolved(info, editorActorHelpText())
    return true
  end

  local defaultStep = configNumber("actor-editor", { "DefaultStepCm", "defaultStepCm" }, 50)
  local defaultYaw = configNumber("actor-editor", { "DefaultYawStepDeg", "defaultYawStepDeg" }, 10)
  if sub == "probe" or sub == "target" or sub == "aim" then
    local cachedTarget = editorActorLatestTargetForInfo(info)
    if cachedTarget == nil or tostring(cachedTarget.actorFullName or "") == "" then
      targetMessageResolved(info, "ED: цель ещё не поймана сервером. Наведись на объект с обычной подсказкой взаимодействия и повтори /ed target.")
    else
      local age = math.max(0, math.floor((os.clock() - (tonumber(cachedTarget.clock) or os.clock())) + 0.5))
      targetMessageResolved(info, "ED target: " .. editorActorLabelFromResult('{"actorFullName":' .. js(cachedTarget.actorFullName or "") .. '}') .. " | " .. tostring(cachedTarget.source or "") .. " | " .. tostring(age) .. "s")
    end
    return true
  end

  if sub == "select" or sub == "sel" or sub == "s" then
    targetMessageResolved(info, "ED: server select disabled. Aim in the admin client and let event-target hooks capture exact actorFullName.")
    return true
  end

  if sub == "f" or sub == "forward" or sub == "forw" then
    local step = editorActorNumber(words, 3, defaultStep, 1, 500)
    local seed = editorActorSeedJson(info, { '"forwardCm":' .. tostring(step) })
    return editorActorSendNative(info, "nudge", "native_actor_editor_nudge", seed, "MOVE_WORLD_ACTOR", 10000, "ED: сдвинул вперёд")
  end
  if sub == "b" or sub == "back" or sub == "backward" then
    local step = editorActorNumber(words, 3, defaultStep, 1, 500)
    local seed = editorActorSeedJson(info, { '"forwardCm":' .. tostring(-step) })
    return editorActorSendNative(info, "nudge", "native_actor_editor_nudge", seed, "MOVE_WORLD_ACTOR", 10000, "ED: сдвинул назад")
  end
  if sub == "l" or sub == "left" then
    local step = editorActorNumber(words, 3, defaultStep, 1, 500)
    local seed = editorActorSeedJson(info, { '"rightCm":' .. tostring(-step) })
    return editorActorSendNative(info, "nudge", "native_actor_editor_nudge", seed, "MOVE_WORLD_ACTOR", 10000, "ED: сдвинул влево")
  end
  if sub == "r" or sub == "right" then
    local step = editorActorNumber(words, 3, defaultStep, 1, 500)
    local seed = editorActorSeedJson(info, { '"rightCm":' .. tostring(step) })
    return editorActorSendNative(info, "nudge", "native_actor_editor_nudge", seed, "MOVE_WORLD_ACTOR", 10000, "ED: сдвинул вправо")
  end
  if sub == "up" or sub == "u" then
    local step = editorActorNumber(words, 3, defaultStep, 1, 500)
    local seed = editorActorSeedJson(info, { '"upCm":' .. tostring(step) })
    return editorActorSendNative(info, "nudge", "native_actor_editor_nudge", seed, "MOVE_WORLD_ACTOR", 10000, "ED: поднял")
  end
  if sub == "down" or sub == "dn" or sub == "d" then
    local step = editorActorNumber(words, 3, defaultStep, 1, 500)
    local seed = editorActorSeedJson(info, { '"upCm":' .. tostring(-step) })
    return editorActorSendNative(info, "nudge", "native_actor_editor_nudge", seed, "MOVE_WORLD_ACTOR", 10000, "ED: опустил")
  end
  if sub == "yl" or sub == "yawleft" or sub == "rotl" or sub == "rl" then
    local step = editorActorNumber(words, 3, defaultYaw, 1, 90)
    local seed = editorActorSeedJson(info, { '"yawDelta":' .. tostring(-step) })
    return editorActorSendNative(info, "nudge", "native_actor_editor_nudge", seed, "MOVE_WORLD_ACTOR", 10000, "ED: повернул влево")
  end
  if sub == "yr" or sub == "yawright" or sub == "rotr" or sub == "rr" then
    local step = editorActorNumber(words, 3, defaultYaw, 1, 90)
    local seed = editorActorSeedJson(info, { '"yawDelta":' .. tostring(step) })
    return editorActorSendNative(info, "nudge", "native_actor_editor_nudge", seed, "MOVE_WORLD_ACTOR", 10000, "ED: повернул вправо")
  end
  if sub == "copy" or sub == "c" or sub == "clone" then
    local step = tonumber(words[3] or "")
    local extra = {}
    if step ~= nil then table.insert(extra, '"rightCm":' .. tostring(math.max(-500, math.min(500, step)))) end
    local seed = editorActorSeedJson(info, extra)
    return editorActorSendNative(info, "copy", "native_actor_editor_copy", seed, "COPY_WORLD_ACTOR", 12000, "ED: копия создана")
  end
  if sub == "hide" or sub == "remove" or sub == "del" or sub == "delete" then
    local seed = editorActorSeedJson(info, {})
    return editorActorSendNative(info, "hide", "native_actor_editor_hide", seed, "HIDE_WORLD_ACTOR", 10000, "ED: объект скрыт")
  end

  targetMessageResolved(info, editorActorHelpText())
  return true
end

DLC_UNLOCK_IN_FLIGHT = DLC_UNLOCK_IN_FLIGHT or {}

function dlcConfig()
  return configText("dlc")
end

function dlcModuleEnabled()
  return extractBoolAny(dlcConfig(), { "Enabled", "enabled" }, false) == true
end

function dlcAddCommand(out, seen, commandText, info, version)
  local command = tostring(commandText or ""):gsub("^%s+", ""):gsub("%s+$", "")
  if command == "" then return end
  command = command:gsub("^%s*#", "")
  command = command:gsub("{version}", tostring(version or ""))
  command = command:gsub("{Version}", tostring(version or ""))
  command = command:gsub("{steamId}", tostring((info and (info.steam or info.steamId)) or ""))
  command = command:gsub("{SteamId}", tostring((info and (info.steam or info.steamId)) or ""))
  command = command:gsub("{SteamID}", tostring((info and (info.steam or info.steamId)) or ""))
  command = command:gsub("{name}", tostring((info and info.name) or ""))
  command = command:gsub("{Name}", tostring((info and info.name) or ""))
  command = command:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
  if command == "" or seen[command] == true then return end
  seen[command] = true
  table.insert(out, command)
end

function dlcConfiguredVersions(text)
  local out = {}
  local seen = {}
  for _, key in ipairs({ "Versions", "versions", "DeluxeVersions", "deluxeVersions" }) do
    local arrayText = jsonArrayForKey(text, key) or ""
    for raw in arrayText:gmatch("%-?%d+") do
      local version = tonumber(raw)
      if version ~= nil and version > 0 and seen[version] ~= true then
        seen[version] = true
        table.insert(out, version)
      end
    end
  end
  table.sort(out)
  return out
end

function dlcAddCommandFromObject(out, seen, object, info, replacement, maxCommands)
  if #out >= maxCommands then return end
  if extractBoolAny(object, { "Enabled", "enabled", "Active", "active" }, true) == false then return end
  local commandText = extractStringAny(object, { "Command", "command", "CommandText", "commandText", "Value", "value", "Template", "template" })
  dlcAddCommand(out, seen, commandText, info, replacement or "")
end

function dlcAddCommandsFromTextBlock(out, seen, textBlock, info, replacement, maxCommands)
  for raw in tostring(textBlock or ""):gmatch("[^\r\n;]+") do
    dlcAddCommand(out, seen, raw, info, replacement or "")
    if #out >= maxCommands then return end
  end
end

function dlcConfiguredCommands(info)
  local text = dlcConfig()
  local out = {}
  local seen = {}
  local maxCommands = math.max(1, math.min(128, configNumber("dlc", { "MaxCommands", "maxCommands" }, 64)))
  for _, key in ipairs({ "Commands", "commands", "AdminCommands", "adminCommands" }) do
    for _, object in ipairs(jsonObjectsInArrayForKey(text, key)) do
      dlcAddCommandFromObject(out, seen, object, info, "", maxCommands)
      if #out >= maxCommands then return out end
    end
    for _, commandText in ipairs(jsonTopLevelStringArrayForKey(text, key)) do
      dlcAddCommand(out, seen, commandText, info, "")
      if #out >= maxCommands then return out end
    end
  end
  dlcAddCommandsFromTextBlock(out, seen, configString("dlc", { "CommandsText", "commandsText", "AdminCommandsText", "adminCommandsText" }, ""), info, "", maxCommands)
  if #out > 0 then return out end
  local template = configString("dlc", { "CommandTemplate", "commandTemplate" }, "SetDeluxeVersion {version}")
  local versions = dlcConfiguredVersions(text)
  if #versions == 0 then versions = { 1, 2, 3 } end
  for _, version in ipairs(versions) do
    dlcAddCommand(out, seen, template, info, version)
    if #out >= maxCommands then return out end
  end
  return out
end

function handleDlcCommand(info, words)
  if not dlcModuleEnabled() then
    targetMessageResolved(info, "DLC unlock is disabled.")
    return true
  end
  local requiredPermission = configString("dlc", { "RequiredPermission", "requiredPermission" }, "")
  if not hasPermission(info, requiredPermission) then
    targetMessageResolved(info, permissionDeniedText(requiredPermission))
    return true
  end
  info = enrichCommandPlayerIdentity(info) or info
  if not playerCommandHasResolvedSteam(info) then
    targetMessageResolved(info, "Server is still resolving your SteamID. Try again in 10 seconds.")
    return true
  end
  local cooldownHours = math.max(0, configNumber("dlc", { "CooldownHours", "cooldownHours" }, 0))
  local remaining = cooldownRemaining("dlc-claims.json", info, cooldownHours * 3600)
  if remaining > 0 then
    targetMessageResolved(info, "DLC command cooldown is active. Try again in " .. tostring(remaining) .. " seconds.")
    return true
  end
  if configBool("dlc", { "OncePerPlayer", "oncePerPlayer" }, false) == true and latestStateNumber("dlc-claims.json", info, "at") ~= nil then
    targetMessageResolved(info, "DLC unlock was already applied for this player.")
    return true
  end
  local commands = dlcConfiguredCommands(info)
  if #commands == 0 then
    targetMessageResolved(info, "DLC unlock has no commands configured.")
    return true
  end
  local claimKey = playerStateKey(info)
  if claimKey ~= "" and DLC_UNLOCK_IN_FLIGHT[claimKey] == true then
    targetMessageResolved(info, "DLC unlock is already being processed.")
    return true
  end
  if claimKey ~= "" then DLC_UNLOCK_IN_FLIGHT[claimKey] = true end
  targetMessageResolved(info, configString("dlc", { "QueuedMessage", "queuedMessage" }, "DLC unlock queued."))
  local steamId = info.steam
  local name = info.name
  local runtimeKey = info.runtimeKey
  deferGame(100, function()
    local queued, queueResult = enqueueMutation("dlc-unlock", info, function(queueItem)
      local live = resolvePlayerInfo(steamId, name, info, runtimeKey) or info
      local delayMs = math.max(0, configNumber("dlc", { "CommandDelayMs", "commandDelayMs", "InterCommandDelayMs", "interCommandDelayMs" }, 1200))
      local stopOnFailure = configBool("dlc", { "StopOnFailure", "stopOnFailure" }, true) ~= false
      local results = {}
      local okCount = 0
      local failCount = 0
      local index = 1
      local function finishDlc()
        local allOk = okCount > 0 and failCount == 0
        local message = allOk and configString("dlc", { "SuccessMessage", "successMessage" }, "DLC unlock applied.") or "DLC unlock was not completed."
        local data = '{"commands":' .. tostring(#commands) .. ',"ok":' .. tostring(okCount) .. ',"failed":' .. tostring(failCount) .. ',"results":[' .. table.concat(results, ",") .. ']}'
        appendJsonArray(STATE_DIR .. "\\dlc-claims.json", '{"utc":' .. js(nowUtc()) .. ',"at":' .. tostring(os.time()) .. ',"steamId":' .. js(steamId or "") .. ',"name":' .. js(name or "") .. ',"ok":' .. (allOk and "true" or "false") .. ',"data":' .. data .. '}', 1024 * 1024)
        appendActionEvent("dlc_unlock", allOk, live, message, data)
        targetMessage(steamId, name, message, "dlc", runtimeKey)
        if claimKey ~= "" then DLC_UNLOCK_IN_FLIGHT[claimKey] = nil end
        finishMutationQueueAsync(queueItem, allOk, message)
      end
      local function runNextDlcCommand()
        if index > #commands then
          finishDlc()
          return
        end
        local commandText = commands[index]
        local sent, message = adminExec(commandText, live)
        table.insert(results, '{"index":' .. tostring(index) .. ',"command":' .. js(commandText) .. ',"ok":' .. (sent and "true" or "false") .. ',"message":' .. js(message or "") .. '}')
        appendActionEvent("dlc_command", sent, live, tostring(message or ""), '{"index":' .. tostring(index) .. ',"command":' .. js(commandText) .. '}')
        if sent then okCount = okCount + 1 else failCount = failCount + 1 end
        index = index + 1
        if not sent and stopOnFailure then
          finishDlc()
          return
        end
        if delayMs > 0 then
          deferGame(delayMs, runNextDlcCommand)
        else
          runNextDlcCommand()
        end
      end
      runNextDlcCommand()
      return "__mutation_async__"
    end)
    if not queued then
      if claimKey ~= "" then DLC_UNLOCK_IN_FLIGHT[claimKey] = nil end
      targetMessage(steamId, name, tostring(queueResult), "dlc", runtimeKey)
    end
  end)
  return true
end

handlePlayerCommand = function(info, message)
  info = enrichPlayerInfoFromServerLog(info) or info
  if type(drainPendingBountyRewardsForInfo) == "function" then
    drainPendingBountyRewardsForInfo(info, 1)
  end
  message = tostring(message or ""):gsub("^[%c%s]+", "")
  local words = splitWords(message)
  local command = (words[1] or ""):lower()
  if command == "" then return false end

  if commandMatches(command, "help") then
    sendPlayerHelp(info)
    return true
  end

  if commandMatches(command, "info") then
    sendPlayerInfo(info)
    return true
  end

  if commandMatches(command, "hello") then
    local name = tostring((info or {}).name or "")
    if name == "" then name = tr(info, "playerFallback", "игрок") end
    targetMessageResolved(info, tr(info, "hello", "Привет, {name}. Система сервера работает.", { name = name }))
    return true
  end

  if commandMatches(command, "language") then
    local requested = normalizeLanguage(words[2] or "")
    if requested == "" then
      local text = playerLanguage(info) == "en"
        and ("Usage: " .. commandUsage("language", " ru") .. " or " .. commandUsage("language", " en"))
        or ("Использование: " .. commandUsage("language", " ru") .. " или " .. commandUsage("language", " en"))
      targetMessageResolved(info, text)
      return true
    end
    if SUPPORTED_LANGUAGES[requested] ~= true then
      targetMessageResolved(info, tr(info, "languageUnknown", "Неизвестный язык. Доступно: ru, en."))
      return true
    end
    rememberPlayerLanguage(info, requested)
    targetMessageResolved(info, applyVars(languageMessage(requested, "languageChanged") or "Language changed.", {}))
    return true
  end

  if commandMatches(command, "ed") then
    return handleEditorActorCommand(info, words)
  end

  if commandMatches(command, "gamestores") then
    if not moduleEnabled("gamestores-shop", false) then
      targetMessageResolved(info, "Магазин GameStores сейчас отключён.")
      return true
    end
    GAMESTORES_COMMAND_NEXT_AT = GAMESTORES_COMMAND_NEXT_AT or {}
    local key = playerStateKey(info)
    local now = os.time()
    local nextAt = key ~= "" and (GAMESTORES_COMMAND_NEXT_AT[key] or 0) or 0
    if nextAt > now then
      targetMessageResolved(info, "GameStores: предыдущая проверка ещё обрабатывается. Повтори через " .. tostring(nextAt - now) .. " сек.")
      return true
    end
    local cooldownSeconds = math.max(1, configNumber("gamestores-shop", { "ClaimCooldownSeconds", "claimCooldownSeconds" }, 10))
    if key ~= "" then GAMESTORES_COMMAND_NEXT_AT[key] = now + cooldownSeconds end
    local requested, startedAt = requestGameStoresClaim(info)
    if not requested then
      targetMessageResolved(info, "GameStores: не удалось поставить проверку покупок. Повтори через несколько секунд.")
      return true
    end
    targetMessageResolved(info, "GameStores: проверяю покупки. Если покупка есть, выдача начнётся через несколько секунд.")
    deferGame(12000, function()
      local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
      local message = recentGameStoresClaimMessage(live, (startedAt or now) - 2)
      if message ~= "" then
        targetMessageResolved(live, message)
      else
        targetMessageResolved(live, "GameStores: проверка отправлена. Если покупка только что оплачена, повтори /pay через несколько секунд.")
      end
    end)
    return true
  end

  if commandMatches(command, "moneytransfer") then
    return handleMoneyTransferCommand(info, words)
  end

  if commandMatches(command, "battlepass") then
    targetMessageResolved(info, dailyRewardsStatusText(info), "battlepass")
    return true
  end

  if commandMatches(command, "dlc") then
    return handleDlcCommand(info, words)
  end

  if commandMatches(command, "itemupgrade") then
    return handleItemUpgradeCommand(info, words)
  end

  if commandMatches(command, "quest") then
    return handlePanelQuestCommand(info, words)
  end

  if commandMatches(command, "baseloot") then
    return handleBaseLootCommand(info, words)
  end

  if commandMatches(command, "sethome") then
    if not moduleEnabled("home-system", true) then
      targetMessageResolved(info, "Система домов сейчас отключена.")
      return true
    end
    local label = table.concat(words, " ", 2)
    if label == "" then
      targetMessageResolved(info, "Использование: " .. commandUsage("sethome", " <name>"))
      return true
    end
    local homes = homesForInfo(info)
    local already = homeByLabel(info, label) ~= nil
    local limit = configNumber("home-system", { "DefaultMaxHomes", "defaultMaxHomes" }, 2)
    local vipPermission = configString("home-system", { "VipPermission", "vipPermission" }, "")
    if vipPermission ~= "" and hasPermission(info, vipPermission) then
      limit = configNumber("home-system", { "VipMaxHomes", "vipMaxHomes" }, limit)
    end
    local vipLimit = vipFeatureNumberForInfo(info, "HomeSystem", { "MaxHomes", "maxHomes", "VipMaxHomes", "vipMaxHomes" }, nil)
    if vipLimit ~= nil then limit = math.max(1, math.floor(vipLimit)) end
    if not already and #homes >= limit then
      targetMessageResolved(info, "Достигнут лимит. Тебе доступно только " .. tostring(limit) .. " домов.")
      return true
    end
    if appendHome(info, label) then
      targetMessageResolved(info, "Дом '" .. label .. "' успешно установлен.")
    else
      targetMessageResolved(info, "Не удалось сохранить дом.")
    end
    return true
  end

  if commandMatches(command, "home") then
    if not moduleEnabled("home-system", true) then
      targetMessageResolved(info, "Система домов сейчас отключена.")
      return true
    end
    local label = table.concat(words, " ", 2)
    local cooldown = cooldownRemaining("home-cooldowns.json", info, configNumber("home-system", { "TeleportCooldownMinutes", "teleportCooldownMinutes", "cooldownMinutes" }, 0) * 60)
    if cooldown > 0 then
      targetMessageResolved(info, "Кулдаун ещё активен. Повтори через " .. tostring(cooldown) .. " сек.")
      return true
    end
    local home = homeByLabel(info, label)
    if home == nil then
      targetMessageResolved(info, label == "" and ("Укажи дом: " .. commandUsage("home", " <name>") .. ". " .. homeListText(info)) or ("Дом '" .. label .. "' не найден."))
      return true
    end
    local pendingKey = transientPlayerKey(info)
    if HOME_TELEPORT_PENDING[pendingKey] then
      targetMessageResolved(info, "Телепорт уже готовится. Дождись завершения предыдущей заявки.")
      return true
    end
    HOME_TELEPORT_PENDING[pendingKey] = true
    local delayMs = math.max(0, configNumber("home-system", { "TeleportDelaySeconds", "teleportDelaySeconds" }, 0)) * 1000
    local startX, startY = info.x, info.y
    targetMessageResolved(info, delayMs > 0 and ("Телепорт к дому '" .. home.label .. "' через " .. tostring(delayMs / 1000) .. " сек. Не двигайся!") or ("Телепорт к дому '" .. home.label .. "'."))
    deferGame(delayMs, function()
      local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
      if live == nil then HOME_TELEPORT_PENDING[pendingKey] = nil; return end
      local cancelDistance = configNumber("home-system", { "CancelMoveDistance", "cancelMoveDistance" }, 150)
      if delayMs > 0 and distance2d(startX, startY, live.x, live.y) > cancelDistance then
        HOME_TELEPORT_PENDING[pendingKey] = nil
        targetMessageResolved(live, "Телепорт отменён: ты сдвинулся с места.")
        return
      end
      local sent, result = teleportResolved(live, home.x, home.y, home.z)
      if not sent then
        HOME_TELEPORT_PENDING[pendingKey] = nil
        targetMessageResolved(live, "Не удалось телепортировать: " .. tostring(result))
        return
      end
      local confirmSeconds = configNumber("home-system", { "TeleportConfirmationSeconds", "teleportConfirmationSeconds", "TravelConfirmationSeconds", "travelConfirmationSeconds" }, 30)
      local arrivalRadius = configNumber("home-system", { "SuccessArrivalDistance", "successArrivalDistance", "ArrivalRadius", "arrivalRadius" }, 1500)
      observePlayerArrival("home", live, home.x, home.y, home.z, confirmSeconds, arrivalRadius, function(arrivalInfo)
        HOME_TELEPORT_PENDING[pendingKey] = nil
        rememberCooldown("home-cooldowns.json", arrivalInfo or live)
        targetMessageResolved(arrivalInfo or live, "Ты прибыл домой: " .. home.label)
      end, function(reason)
        HOME_TELEPORT_PENDING[pendingKey] = nil
        targetMessageResolved(live, "Телепорт отправлен, но прибытие не подтверждено: " .. tostring(reason))
      end)
    end)
    return true
  end

  if commandMatches(command, "homes") then
    if not moduleEnabled("home-system", true) then
      targetMessageResolved(info, "Система домов сейчас отключена.")
      return true
    end
    targetMessageResolved(info, homeListText(info))
    return true
  end

  if commandMatches(command, "delhome") then
    if not moduleEnabled("home-system", true) then
      targetMessageResolved(info, "Система домов сейчас отключена.")
      return true
    end
    local label = table.concat(words, " ", 2)
    local removed = deleteHomes(info, label)
    targetMessageResolved(info, removed > 0 and ("Удалено точек дома: " .. tostring(removed)) or "Подходящих точек дома не найдено.")
    return true
  end

  if commandMatches(command, "pm") then
    if not moduleEnabled("private-messages", true) then
      targetMessageResolved(info, "Личные сообщения сейчас отключены.")
      return true
    end
    local pmPermission = configString("private-messages", { "AllowPermission", "allowPermission" }, "pm.use")
    if configBool("private-messages", { "UsePermission", "usePermission" }, false) and not hasPermission(info, pmPermission) then
      targetMessageResolved(info, permissionDeniedText(pmPermission))
      return true
    end
    local target = words[2] or ""
    local body = table.concat(words, " ", 3)
    if target == "" or body == "" then
      targetMessageResolved(info, "Формат: " .. commandUsage("pm", " name message"))
      return true
    end
    local cooldown = privateMessageCooldownRemaining(info)
    if cooldown > 0 then
      targetMessageResolved(info, "Личные сообщения на кулдауне. Подожди " .. tostring(cooldown) .. " сек.")
      return true
    end
    local other = findPlayer(nil, target)
    if other == nil then
      targetMessageResolved(info, "Игрок для " .. commandUsage("pm") .. " не найден.")
      return true
    end
    targetMessageResolved(other, "[PM] " .. (info.name or "Игрок") .. ": " .. body)
    targetMessageResolved(info, "[PM -> " .. (other.name or target) .. "] " .. body)
    recordPmReply(info, other)
    rememberPrivateMessageCooldown(info)
    appendJsonArray(STATE_DIR .. "\\private-messages.json", '{"utc":' .. js(nowUtc()) .. ',"from":' .. js(info.name) .. ',"to":' .. js(other.name) .. ',"message":' .. js(body) .. '}', 1024 * 1024)
    return true
  end

  if commandMatches(command, "reply") then
    if not moduleEnabled("private-messages", true) then
      targetMessageResolved(info, "Личные сообщения сейчас отключены.")
      return true
    end
    local pmPermission = configString("private-messages", { "AllowPermission", "allowPermission" }, "pm.use")
    if configBool("private-messages", { "UsePermission", "usePermission" }, false) and not hasPermission(info, pmPermission) then
      targetMessageResolved(info, permissionDeniedText(pmPermission))
      return true
    end
    local body = table.concat(words, " ", 2)
    local reply = pmReplies[playerReplyKey(info)]
    if body == "" then
      targetMessageResolved(info, "Формат: " .. commandUsage("reply", " message"))
      return true
    end
    if reply == nil then
      targetMessageResolved(info, "Некому ответить. Сначала используй " .. commandUsage("pm") .. ".")
      return true
    end
    local cooldown = privateMessageCooldownRemaining(info)
    if cooldown > 0 then
      targetMessageResolved(info, "Личные сообщения на кулдауне. Подожди " .. tostring(cooldown) .. " сек.")
      return true
    end
    local other = findPlayer(reply.steam, reply.name)
    if other == nil then
      targetMessageResolved(info, "Игрок для ответа не найден.")
      return true
    end
    targetMessageResolved(other, "[PM] " .. (info.name or "Игрок") .. ": " .. body)
    targetMessageResolved(info, "[PM -> " .. (other.name or reply.name or "") .. "] " .. body)
    recordPmReply(info, other)
    rememberPrivateMessageCooldown(info)
    appendJsonArray(STATE_DIR .. "\\private-messages.json", '{"utc":' .. js(nowUtc()) .. ',"from":' .. js(info.name) .. ',"to":' .. js(other.name) .. ',"message":' .. js(body) .. '}', 1024 * 1024)
    return true
  end

  if commandMatches(command, "pmhistory") then
    if not moduleEnabled("private-messages", true) then
      targetMessageResolved(info, "Личные сообщения сейчас отключены.")
      return true
    end
    local pmPermission = configString("private-messages", { "AllowPermission", "allowPermission" }, "pm.use")
    if configBool("private-messages", { "UsePermission", "usePermission" }, false) and not hasPermission(info, pmPermission) then
      targetMessageResolved(info, permissionDeniedText(pmPermission))
      return true
    end
    targetMessageResolved(info, privateMessageHistory(info, tonumber(words[2]) or 5))
    return true
  end

  if commandMatches(command, "scan") then
    if not moduleEnabled("sector-scan", true) then
      targetMessageResolved(info, "Сканирование квадрата сейчас отключено.")
      return true
    end
    local requiredPermission = configString("sector-scan", { "RequiredPermission", "requiredPermission" }, "")
    if not hasPermission(info, requiredPermission) then
      targetMessageResolved(info, permissionDeniedText(requiredPermission))
      return true
    end
    local scanCooldownSeconds = configNumber("sector-scan", { "CooldownSeconds", "cooldownSeconds" }, 120)
    scanCooldownSeconds = vipFeatureNumberForInfo(info, "SectorScan", { "CooldownSeconds", "cooldownSeconds" }, scanCooldownSeconds) or scanCooldownSeconds
    local cooldown = cooldownRemaining("sector-scan-cooldowns.json", info, scanCooldownSeconds)
    if cooldown > 0 then
      targetMessageResolved(info, "Сканирование ещё на кулдауне. Подожди " .. tostring(cooldown) .. " сек.")
      return true
    end
    local liveInfo = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
    local requesterSector = ""
    do
      local sx = tonumber(liveInfo.x)
      local sy = tonumber(liveInfo.y)
      if sx ~= nil and sy ~= nil then requesterSector = sectorFromCoordinates(sx, sy):upper() end
    end
    local requested = normalizeSectorCode(words[2] or "")
    if tostring(words[2] or "") ~= "" and requested == "" then
      targetMessageResolved(info, sectorHelpText())
      return true
    end
    local wanted = requested
    if wanted == "" then
      local x = tonumber(liveInfo.x)
      local y = tonumber(liveInfo.y)
      if x == nil or y == nil then
        targetMessageResolved(info, "Скан не выполнен: не удалось определить твой текущий квадрат. Укажи сектор вручную, например " .. commandUsage("scan", " B2") .. ".")
        return true
      end
      wanted = requesterSector ~= "" and requesterSector or sectorFromCoordinates(x, y):upper()
    end
    local maxPositionAge = configNumber("sector-scan", { "PositionMaxAgeSeconds", "positionMaxAgeSeconds", "FreshPositionSeconds", "freshPositionSeconds" }, 8)
    local scanStartedAt = os.clock()
    local scanInfos = sectorScanPlayerInfos(maxPositionAge, liveInfo)
    local scanDurationMs = math.floor(math.max(0, os.clock() - scanStartedAt) * 1000 + 0.5)
    if scanDurationMs >= 50 or SECTOR_SCAN_LAST_CACHE_HIT then
      appendLog("sector scan runtime players=" .. tostring(#scanInfos) .. " durationMs=" .. tostring(scanDurationMs) .. " cacheHit=" .. tostring(SECTOR_SCAN_LAST_CACHE_HIT == true))
    end
    if #scanInfos == 0 then
      targetMessageResolved(info, "Скан не выполнен: нет свежих live-координат игроков. Повтори через несколько секунд.")
      return true
    end
    local cost = configNumber("sector-scan", { "ScanCost", "scanCost", "price" }, 1000)
    if vipFeatureEnabledForInfo(info, "SectorScan") then
      if vipFeatureBoolForInfo(info, "SectorScan", { "Free", "free" }, false) then
        cost = 0
      else
        cost = vipFeatureNumberForInfo(info, "SectorScan", { "ScanCost", "scanCost", "Price", "price" }, cost) or cost
      end
    end
    if cost > 0 then
      local charged, chargeMessage = changeMoney(liveInfo.steam, liveInfo.name, -cost, "Normal", liveInfo.runtimeKey)
      if not charged then
        targetMessageResolved(info, "Скан не выполнен: " .. tostring(chargeMessage))
        return true
      end
    end
    local count = 0
    local names = {}
    local includeNames = configBool("sector-scan", { "IncludePlayerNames", "includePlayerNames" }, true)
    local includeSelf = configBool("sector-scan", { "IncludeSelf", "includeSelf" }, true)
    local maxNames = configNumber("sector-scan", { "MaxListedNames", "maxListedNames" }, 5)
    for _, p in ipairs(scanInfos) do
      local px = tonumber(p.x)
      local py = tonumber(p.y)
      local same = (tostring(liveInfo.steam or "") ~= "" and tostring(p.steam or "") == tostring(liveInfo.steam or "")) or
        (tostring(liveInfo.runtimeKey or "") ~= "" and tostring(p.runtimeKey or "") == tostring(liveInfo.runtimeKey or "")) or
        (tostring(liveInfo.name or "") ~= "" and tostring(p.name or "") == tostring(liveInfo.name or ""))
      if px ~= nil and py ~= nil and sectorFromCoordinates(px, py):upper() == wanted and (includeSelf or not same) then
        count = count + 1
        if includeNames and #names < maxNames then
          local display = tostring(p.name or "")
          if display == "" then display = tostring(p.steam or "") end
          if display ~= "" then table.insert(names, display) end
        end
      end
    end
    rememberCooldown("sector-scan-cooldowns.json", liveInfo)
    local suffix = #names > 0 and (" " .. table.concat(names, ", ")) or ""
    local costText = cost > 0 and (" Стоимость: $" .. tostring(cost) .. ".") or " Стоимость: бесплатно."
    local sourceText = " Источник: live-координаты."
    local selfSectorText = requesterSector ~= "" and requesterSector ~= wanted and (" Твой текущий квадрат по live-координатам: " .. requesterSector .. ".") or ""
    appendActionEvent("sector_scan", true, liveInfo, "sector=" .. wanted .. " count=" .. tostring(count),
      '{"sector":' .. js(wanted) .. ',"requesterSector":' .. js(requesterSector) .. ',"includeSelf":' .. (includeSelf and "true" or "false") .. ',"count":' .. tostring(count) .. ',"names":' .. stringArrayJson(names) .. ',"playersChecked":' .. tostring(#scanInfos) .. ',"positionMaxAgeSeconds":' .. tostring(maxPositionAge) .. ',"scanDurationMs":' .. tostring(scanDurationMs) .. ',"scanCacheHit":' .. tostring(SECTOR_SCAN_LAST_CACHE_HIT == true) .. '}')
    targetMessageResolved(info, count > 0 and ("[Скан] Квадрат " .. wanted .. ": найдено " .. tostring(count) .. "." .. costText .. sourceText .. selfSectorText .. suffix) or ("[Скан] Квадрат " .. wanted .. " пуст." .. costText .. sourceText .. selfSectorText))
    return true
  end

  if commandMatches(command, "armoryback") then
      local queued, queueIdOrMessage, depth = enqueueMutation("armory-return", info, function()
        local okRun, okReturn, resultMessage = pcall(function()
          local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
          return armoryCommandReturnForInfo(live)
        end)
        if not okRun then
          appendActionEvent("armory_return", false, info, "Armory return exception: " .. tostring(okReturn),
            '{"error":' .. js(tostring(okReturn or "")) .. '}')
          targetMessageResolved(info, "Возврат после Armory не выполнен: внутренняя ошибка записана в action-log.")
        elseif not okReturn then
          appendLog("armory return did not complete: " .. tostring(resultMessage or ""))
        end
      end)
      if not queued then
        targetMessageResolved(info, "Возврат после Armory не выполнен: очередь игровых действий занята. Повтори через несколько секунд.")
        appendActionEvent("armory_return_queue", false, info, tostring(queueIdOrMessage or "queue failed"),
          '{"depth":' .. tostring(depth or 0) .. '}')
      else
        appendActionEvent("armory_return_queue", true, info, "Возврат после Armory поставлен в live-очередь.",
          '{"queueId":' .. tostring(queueIdOrMessage or 0) .. ',"depth":' .. tostring(depth or 0) .. '}')
      end
      return true
  end

  if commandMatches(command, "armory") then
      if not moduleEnabled("armory-command", true) then
        targetMessageResolved(info, "Armory сейчас отключён.")
        return true
      end
      local queued, queueIdOrMessage, depth = enqueueMutation("armory-open", info, function()
        local okRun, okOpen, resultMessage = pcall(function()
          local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
          return armoryCommandOpenForInfo(live)
        end)
        if not okRun then
          local pendingKey = playerStateKey(info)
          if pendingKey ~= "" then ARMORY_COMMAND_PENDING[pendingKey] = nil end
          appendActionEvent("armory_open", false, info, "Armory exception: " .. tostring(okOpen),
            '{"error":' .. js(tostring(okOpen or "")) .. '}')
          targetMessageResolved(info, "Armory не открыт: внутренняя ошибка записана в action-log.")
        elseif not okOpen and tostring(resultMessage or "") ~= "pending" then
          appendLog("armory command did not open: " .. tostring(resultMessage or ""))
        end
      end)
      if not queued then
        targetMessageResolved(info, "Armory не открыт: очередь игровых действий занята. Повтори через несколько секунд.")
        appendActionEvent("armory_open_queue", false, info, tostring(queueIdOrMessage or "queue failed"),
          '{"depth":' .. tostring(depth or 0) .. '}')
      else
        appendActionEvent("armory_open_queue", true, info, "Armory поставлен в live-очередь.",
          '{"queueId":' .. tostring(queueIdOrMessage or 0) .. ',"depth":' .. tostring(depth or 0) .. '}')
      end
      return true
  end

  if commandMatches(command, "travel") then
    if not moduleEnabled("fast-travel", true) then
      targetMessageResolved(info, "Быстрое перемещение сейчас отключено.")
      return true
    end
    local alias = (words[2] or ""):lower()
    local routes = configuredFastTravelRoutes()
    if alias == "" then
      local labels = {}
      for key, route in pairs(routes) do
        local fare = fastTravelFareForInfo(info, route)
        table.insert(labels, { key = key, text = commandUsage("travel", " " .. key) .. " - " .. tostring(route.name) .. " - цена: " .. tostring(fare) })
      end
      table.sort(labels, function(a, b) return tostring(a.key) < tostring(b.key) end)
      local lines = { "Маршруты быстрого перемещения:" }
      for _, row in ipairs(labels) do table.insert(lines, row.text) end
      table.insert(lines, "Использование: " .. commandUsage("travel", " <код>") .. ". Цена считается до выбранной точки.")
      sendTargetMessageLines(info, lines, "travel", nil, { compactMessage = "Маршруты быстрого перемещения: " .. commandUsage("travel", " <код>") .. ". Цена считается до выбранной точки." })
      return true
    end
    local route = routes[alias]
    if route == nil then
      targetMessageResolved(info, "Маршрут не найден. Используй " .. commandUsage("travel") .. " чтобы увидеть список.")
      return true
    end
    local cooldown = cooldownRemaining("fast-travel-cooldowns.json", info, configNumber("fast-travel", { "TransferCooldownMinutes", "transferCooldownMinutes", "cooldownMinutes" }, 60) * 60)
    if cooldown > 0 then
      targetMessageResolved(info, "Кулдаун быстрого перемещения активен. Осталось " .. tostring(cooldown) .. " сек.")
      return true
    end
    local fare = fastTravelFareForInfo(info, route)
    local targetZ = safeFastTravelZ(route)
    local pendingKey = transientPlayerKey(info)
    if FAST_TRAVEL_GLOBAL_PENDING then
      targetMessageResolved(info, "Очередь перемещения занята. Повтори команду через несколько секунд.")
      return true
    end
    if FAST_TRAVEL_PENDING[pendingKey] then
      targetMessageResolved(info, "Перемещение уже готовится. Дождись завершения предыдущей заявки.")
      return true
    end
    FAST_TRAVEL_GLOBAL_PENDING = true
    FAST_TRAVEL_PENDING[pendingKey] = true
    local delayMs = math.max(0, configNumber("fast-travel", { "TeleportDelaySeconds", "teleportDelaySeconds", "delaySeconds" }, 5)) * 1000
    local startX, startY = info.x, info.y
    targetMessageResolved(info, "Подготовка перемещения в '" .. route.name .. "' за $" .. tostring(fare) .. " через " .. tostring(delayMs / 1000) .. " сек. Не двигайся.")
    deferGame(delayMs, function()
      local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
      if live == nil then FAST_TRAVEL_PENDING[pendingKey] = nil; FAST_TRAVEL_GLOBAL_PENDING = false; return end
      local cancelDistance = configNumber("fast-travel", { "CancelMoveDistance", "cancelMoveDistance" }, 150)
      if delayMs > 0 and distance2d(startX, startY, live.x, live.y) > cancelDistance then
        FAST_TRAVEL_PENDING[pendingKey] = nil
        FAST_TRAVEL_GLOBAL_PENDING = false
        targetMessageResolved(live, "Быстрое перемещение отменено: ты сдвинулся с места.")
        return
      end
      local sent, result = teleportResolved(live, route.x, route.y, targetZ)
      if not sent then
        FAST_TRAVEL_PENDING[pendingKey] = nil
        FAST_TRAVEL_GLOBAL_PENDING = false
        targetMessageResolved(live, "Не удалось выполнить быстрое перемещение: " .. tostring(result))
        return
      end
      local confirmSeconds = configNumber("fast-travel", { "TravelConfirmationSeconds", "travelConfirmationSeconds" }, 90)
      local arrivalRadius = configNumber("fast-travel", { "SuccessArrivalDistance", "successArrivalDistance", "ArrivalRadius", "arrivalRadius" }, 1500)
      observePlayerArrival("fast_travel", live, route.x, route.y, targetZ, confirmSeconds, arrivalRadius, function(arrivalInfo)
        FAST_TRAVEL_PENDING[pendingKey] = nil
        FAST_TRAVEL_GLOBAL_PENDING = false
        live = arrivalInfo or live
        local charged, chargeMessage = true, ""
        if fare > 0 then charged, chargeMessage = changeMoney(live.steam, live.name, -fare, "Normal", live.runtimeKey) end
        rememberCooldown("fast-travel-cooldowns.json", live)
        appendJsonArray(STATE_DIR .. "\\fast-travel-trips.json", '{"utc":' .. js(nowUtc()) .. ',"steamId":' .. js(live.steam) .. ',"name":' .. js(live.name) .. ',"route":' .. js(route.name) .. ',"fare":' .. tostring(fare) .. ',"charged":' .. (charged and "true" or "false") .. '}', 1024 * 1024)
        if charged then
          targetMessageResolved(live, "Быстрое перемещение выполнено. Списано: $" .. tostring(fare) .. ".")
        else
          targetMessageResolved(live, "Ты прибыл, но списание не подтверждено: " .. tostring(chargeMessage))
        end
      end, function(reason)
        FAST_TRAVEL_PENDING[pendingKey] = nil
        FAST_TRAVEL_GLOBAL_PENDING = false
        targetMessageResolved(live, "Перемещение отправлено, но прибытие не подтверждено. Деньги не списаны: " .. tostring(reason))
      end)
    end)
    return true
  end

  if commandMatches(command, "rent") then
    if not moduleEnabled("vehicle-rental", true) then
      targetMessageResolved(info, "Аренда транспорта сейчас отключена.")
      return true
    end
    local sub = (words[2] or ""):lower()
    if sub == "" or sub == "list" then
      sendRentHelp(info, latestActiveRental(info))
      return true
    end
    info = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
    if not playerInfoHasLiveRuntime(info) then
      targetMessageResolved(info, "Аренда не запущена: сервер ещё не привязал твоего персонажа к live runtime. Подожди 10 секунд и повтори " .. commandUsage("rent") .. ".")
      return true
    end
    info = enrichPlayerInfoFromServerLog(info) or info
    if not looksLikeSteamId(cleanText(info.steam or "")) then
      targetMessageResolved(info, "Аренда не запущена: сервер пока не определил твой SteamID. Подожди 10 секунд и повтори " .. commandUsage("rent") .. ".")
      return true
    end
    collectRentalPendingTaxes(info, false)
    local current = latestActiveRental(info)
    if sub == "status" or sub == "time" then
      sendRentStatus(info, current)
      return true
    end
    if sub == "extend" then
      if current == nil then
        targetMessageResolved(info, "У тебя нет активной аренды.")
        return true
      end
      local minutes = math.floor(tonumber(words[3]) or 0)
      if minutes < 1 then
        targetMessageResolved(info, "Использование: " .. commandUsage("rent", " extend <минуты>") .. ". Продление считает только время, доплата спишется при возврате или по окончании.")
        return true
      end
      local queued, queueResult = enqueueMutation("vehicle-rental-extend", info, function()
        local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey)
        if live == nil then return end
        local active = latestActiveRental(live)
        if active == nil then
          targetMessage(info.steam, info.name, "Продление не выполнено: активная аренда не найдена.", "vehicle-rental", info.runtimeKey)
          return
        end
        local alias = (extractString(active, "alias") or ""):lower()
        local configured = vipRentalVehicleForInfo(live or info, (availableRentalVehiclesForInfo(live or info)[alias] or configuredRentalVehicles(true)[alias] or configuredRentalVehicles(false)[alias]))
        local price = extractNumber(active, "pricePer10Minutes") or (configured and configured.price) or 0
        local previousMinutes = extractNumber(active, "minutes") or 0
        local newMinutes = previousMinutes + minutes
        local maxTotalMinutes = (configured and configured.maxMinutes) or configNumber("vehicle-rental", { "MaxRentalMinutes", "maxRentalMinutes", "MaxMinutes", "maxMinutes" }, 120)
        if newMinutes > maxTotalMinutes then
          targetMessage(info.steam, info.name, "Нельзя продлить аренду: общий срок не может превышать " .. tostring(maxTotalMinutes) .. " минут.", "vehicle-rental", info.runtimeKey)
          return
        end
        local previousExpiresAt = extractNumber(active, "expiresAt") or os.time()
        local newExpiresAt = math.max(previousExpiresAt, os.time()) + minutes * 60
        local displayName = extractString(active, "displayName") or (configured and configured.display) or extractString(active, "vehicleId") or "vehicle"
        local totalCharge = extractNumber(active, "totalCharge") or extractNumber(active, "initialCharge") or 0
        local destroyRef = vehicleDestroyRefFromRental(active)
        appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json", '{"utc":' .. js(nowUtc()) .. ',"steamId":' .. js(live.steam) .. ',"name":' .. js(live.name) .. ',"alias":' .. js(alias) .. ',"status":"active","displayName":' .. js(displayName) .. ',"vehicleId":' .. js(extractString(active, "vehicleId") or "") .. ',"minutes":' .. tostring(newMinutes) .. ',"startedAt":' .. tostring(extractNumber(active, "startedAt") or os.time()) .. ',"extendedAt":' .. tostring(os.time()) .. ',"extensionMinutes":' .. tostring(minutes) .. ',"expiresAt":' .. tostring(newExpiresAt) .. ',"initialCharge":' .. tostring(extractNumber(active, "initialCharge") or 0) .. ',"pricePer10Minutes":' .. tostring(price) .. ',"extensionCharge":0,"totalCharge":' .. tostring(totalCharge) .. ',"destroyRef":' .. js(destroyRef) .. ',"destroyTracked":' .. (destroyRef ~= "" and "true" or "false") .. '}', 1024 * 1024)
        targetMessage(info.steam, info.name, "Аренда " .. displayName .. " продлена на " .. tostring(minutes) .. " мин. Доплата будет рассчитана при возврате или по окончании.", "vehicle-rental", info.runtimeKey)
      end)
      targetMessageResolved(info, queued and "Продление аренды принято в очередь. Подожди, обновляю срок аренды." or tostring(queueResult))
      return true
    end
    if sub == "return" then
      if current == nil then
        current = latestReturnableRental(info)
      end
      if current == nil then
        targetMessageResolved(info, "У тебя нет активной аренды.")
      else
        local queued, queueResult = enqueueMutation("vehicle-rental-return", info, function()
          local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey)
          local active = latestActiveRental(live or info)
          if active == nil then active = latestReturnableRental(live or info) end
          if active == nil then
            targetMessage(info.steam, info.name, "Возврат не выполнен: активная аренда не найдена.", "vehicle-rental", info.runtimeKey)
            return
          end
          local allowRuntimeReturnDestroy = configBool("vehicle-rental", { "EnableRuntimeVehicleReturnDestroy", "enableRuntimeVehicleReturnDestroy", "AllowRuntimeVehicleReturnDestroy", "allowRuntimeVehicleReturnDestroy" }, true)
          local destroyRef = vehicleDestroyRefFromRental(active)
          if destroyRef == "" and allowRuntimeReturnDestroy then
            destroyRef = resolveRentalDestroyRef(active, live or info)
            if destroyRef ~= "" then
              appendActionEvent("vehicle_rental_return_resolved_ref", true, live or info, "runtime vehicle found near player for return",
                '{"destroyRef":' .. js(destroyRef) .. ',"vehicleId":' .. js(extractString(active, "vehicleId") or "") .. '}')
            end
          end
          local destroyAttempted = destroyRef ~= ""
          local destroyOk = false
          local destroyMessage = ""
          local alreadyGone = false
          local alreadyGoneLine = ""
          if destroyAttempted and allowRuntimeReturnDestroy and tostring(destroyRef or ""):sub(1, 8) ~= "runtime:" then
            alreadyGone, destroyMessage, alreadyGoneLine = rentalVehicleRefAlreadyGone(destroyRef)
            if alreadyGone then
              appendActionEvent("vehicle_destroy", true, live or info, destroyMessage .. "; vehicle_destruction proof triggers missing-vehicle penalty",
                '{"reason":"rent-return","displayName":' .. js(extractString(active, "displayName") or "") .. ',"destroyRef":' .. js(destroyRef) .. ',"vehicleDestructionLogLine":' .. js(alreadyGoneLine or "") .. '}')
            end
          end
          if destroyAttempted and allowRuntimeReturnDestroy and not alreadyGone then
            destroyOk, destroyMessage = destroyVehicleRef(destroyRef, live or info, "rent-return")
          else
            if not alreadyGone then
              destroyAttempted = false
              destroyMessage = allowRuntimeReturnDestroy and "missing vehicle entity id" or "runtime vehicle destroy skipped for stability"
              appendActionEvent("vehicle_destroy", false, live or info, destroyMessage,
                '{"reason":"rent-return","displayName":' .. js(extractString(active, "displayName") or "") .. ',"runtimeDestroyEnabled":' .. (allowRuntimeReturnDestroy and "true" or "false") .. '}')
            end
          end
          if not destroyOk and allowRuntimeReturnDestroy and rentalDestroyInvalidVehicleRefMessage(destroyMessage) and tostring(destroyRef or ""):sub(1, 8) ~= "runtime:" then
            local fallbackRef = resolveRentalDestroyRef(active, live or info)
            if fallbackRef ~= "" and fallbackRef ~= destroyRef then
              appendActionEvent("vehicle_rental_return_resolved_ref", true, live or info, "saved vehicle id is invalid; runtime vehicle fallback found near player",
                '{"oldDestroyRef":' .. js(destroyRef) .. ',"destroyRef":' .. js(fallbackRef) .. ',"vehicleId":' .. js(extractString(active, "vehicleId") or "") .. '}')
              destroyRef = fallbackRef
              destroyAttempted = true
              destroyOk, destroyMessage = destroyVehicleRef(destroyRef, live or info, "rent-return-runtime-fallback")
            end
          end
          if not destroyOk then
            if not allowRuntimeReturnDestroy then
              local usageChargeQueued, usageChargeMessage, usageChargeAmount, chargeableMinutes, minutesAfter10, totalCostSoFar, alreadyPaid, pricePerMinute, usageTaxKey =
                finalizeRentalUsageChargeForUntrackedReturn(live or info, active, "rent-return-untracked", os.time())
              appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
                '{"utc":' .. js(nowUtc()) ..
                ',"steamId":' .. js(info.steam) ..
                ',"name":' .. js(info.name) ..
                ',"status":"returned","returned":"true","returnedAt":' .. tostring(os.time()) ..
                ',"displayName":' .. js(extractString(active, "displayName") or "") ..
                ',"vehicleId":' .. js(extractString(active, "vehicleId") or "") ..
                ',"destroyRef":' .. js(destroyRef) ..
                ',"destroyAttempted":false' ..
                ',"destroyOk":false' ..
                ',"destroySkippedForStability":true' ..
                ',"destroyMessage":' .. js(destroyMessage) ..
                ',"usageChargeQueued":' .. (usageChargeQueued and "true" or "false") ..
                ',"usageChargeAmount":' .. tostring(usageChargeAmount) ..
                ',"chargeableMinutes":' .. tostring(chargeableMinutes) ..
                ',"minutesAfter10":' .. tostring(minutesAfter10) ..
                ',"pricePerMinute":' .. tostring(pricePerMinute) ..
                ',"usageTotalCost":' .. tostring(totalCostSoFar) ..
                ',"usageAlreadyPaid":' .. tostring(alreadyPaid) ..
                ',"usageTaxKey":' .. js(usageTaxKey or "") ..
                ',"usageChargeMessage":' .. js(usageChargeMessage) .. '}',
                1024 * 1024)
              if usageChargeAmount > 0 then
                targetMessage(info.steam, info.name, "Аренда возвращена. Запись закрыта безопасно, без тяжёлого поиска транспорта. Доплата: " .. tostring(usageChargeAmount) .. ".", "vehicle-rental", info.runtimeKey)
              else
                targetMessage(info.steam, info.name, "Аренда возвращена. Запись закрыта безопасно, без тяжёлого поиска транспорта.", "vehicle-rental", info.runtimeKey)
              end
              return
            end
            local missingVehicle = rentalMissingVehicleLikely(destroyAttempted, destroyOk, destroyMessage)
            if missingVehicle then
              local usageChargeQueued, usageChargeMessage, usageChargeAmount, chargeableMinutes, minutesAfter10, totalCostSoFar, alreadyPaid, pricePerMinute, usageTaxKey =
                finalizeRentalUsageCharge(live or info, active, "rent-return-missing-vehicle", os.time())
              local penaltyQueued, penaltyMessage, penaltyAmount, penaltyTaxKey =
                chargeRentalMissingVehiclePenalty(live or info, active, "rent-return-missing-vehicle")
              appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
                '{"utc":' .. js(nowUtc()) ..
                ',"steamId":' .. js(info.steam) ..
                ',"name":' .. js(info.name) ..
                ',"alias":' .. js(extractString(active, "alias") or "") ..
                ',"status":"sold_or_missing","returnAttemptedAt":' .. tostring(os.time()) ..
                ',"displayName":' .. js(extractString(active, "displayName") or "") ..
                ',"vehicleId":' .. js(extractString(active, "vehicleId") or "") ..
                ',"minutes":' .. tostring(extractNumber(active, "minutes") or 0) ..
                ',"startedAt":' .. tostring(extractNumber(active, "startedAt") or os.time()) ..
                ',"expiresAt":' .. tostring(extractNumber(active, "expiresAt") or 0) ..
                ',"initialCharge":' .. tostring(extractNumber(active, "initialCharge") or 0) ..
                ',"pricePer10Minutes":' .. tostring(extractNumber(active, "pricePer10Minutes") or 0) ..
                ',"totalCharge":' .. tostring(extractNumber(active, "totalCharge") or extractNumber(active, "initialCharge") or 0) ..
                ',"destroyRef":' .. js(destroyRef) ..
                ',"destroyAttempted":' .. (destroyAttempted and "true" or "false") ..
                ',"destroyOk":false' ..
                ',"destroyMessage":' .. js(destroyMessage) ..
                ',"missingVehicle":true' ..
                ',"usageChargeQueued":' .. (usageChargeQueued and "true" or "false") ..
                ',"usageChargeAmount":' .. tostring(usageChargeAmount) ..
                ',"chargeableMinutes":' .. tostring(chargeableMinutes) ..
                ',"minutesAfter10":' .. tostring(minutesAfter10) ..
                ',"pricePerMinute":' .. tostring(pricePerMinute) ..
                ',"usageTotalCost":' .. tostring(totalCostSoFar) ..
                ',"usageAlreadyPaid":' .. tostring(alreadyPaid) ..
                ',"usageTaxKey":' .. js(usageTaxKey or "") ..
                ',"usageChargeMessage":' .. js(usageChargeMessage) ..
                ',"missingVehiclePenaltyQueued":' .. (penaltyQueued and "true" or "false") ..
                ',"missingVehiclePenaltyAmount":' .. tostring(penaltyAmount) ..
                ',"missingVehiclePenaltyTaxKey":' .. js(penaltyTaxKey or "") ..
                ',"missingVehiclePenaltyMessage":' .. js(penaltyMessage or "") .. '}',
                1024 * 1024)
              targetMessage(info.steam, info.name, "Арендованный транспорт не найден. Если он продан или потерян, аренда закрыта, штраф: " .. tostring(penaltyAmount) .. ".", "vehicle-rental", info.runtimeKey)
            else
              local usageChargeQueued, usageChargeMessage, usageChargeAmount, chargeableMinutes, minutesAfter10, totalCostSoFar, alreadyPaid, pricePerMinute, usageTaxKey =
                finalizeRentalUsageChargeForUntrackedReturn(live or info, active, "rent-return-untracked", os.time())
              appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
                '{"utc":' .. js(nowUtc()) ..
                ',"steamId":' .. js(info.steam) ..
                ',"name":' .. js(info.name) ..
                ',"alias":' .. js(extractString(active, "alias") or "") ..
                ',"status":"returned_untracked","returned":"true","returnedAt":' .. tostring(os.time()) ..
                ',"displayName":' .. js(extractString(active, "displayName") or "") ..
                ',"vehicleId":' .. js(extractString(active, "vehicleId") or "") ..
                ',"minutes":' .. tostring(extractNumber(active, "minutes") or 0) ..
                ',"startedAt":' .. tostring(extractNumber(active, "startedAt") or os.time()) ..
                ',"expiresAt":' .. tostring(extractNumber(active, "expiresAt") or 0) ..
                ',"initialCharge":' .. tostring(extractNumber(active, "initialCharge") or 0) ..
                ',"pricePer10Minutes":' .. tostring(extractNumber(active, "pricePer10Minutes") or 0) ..
                ',"totalCharge":' .. tostring(extractNumber(active, "totalCharge") or extractNumber(active, "initialCharge") or 0) ..
                ',"destroyRef":' .. js(destroyRef) ..
                ',"destroyAttempted":' .. (destroyAttempted and "true" or "false") ..
                ',"destroyOk":false' ..
                ',"destroyUnresolved":true' ..
                ',"destroyMessage":' .. js(destroyMessage) ..
                ',"missingVehicle":false' ..
                ',"missingVehiclePenaltyQueued":false' ..
                ',"missingVehiclePenaltyAmount":0' ..
                ',"usageChargeQueued":' .. (usageChargeQueued and "true" or "false") ..
                ',"usageChargeAmount":' .. tostring(usageChargeAmount) ..
                ',"chargeableMinutes":' .. tostring(chargeableMinutes) ..
                ',"minutesAfter10":' .. tostring(minutesAfter10) ..
                ',"pricePerMinute":' .. tostring(pricePerMinute) ..
                ',"usageTotalCost":' .. tostring(totalCostSoFar) ..
                ',"usageAlreadyPaid":' .. tostring(alreadyPaid) ..
                ',"usageTaxKey":' .. js(usageTaxKey or "") ..
                ',"usageChargeMessage":' .. js(usageChargeMessage) .. '}',
                1024 * 1024)
              if usageChargeAmount > 0 then
                targetMessage(info.steam, info.name, "Аренда закрыта без штрафа: транспорт не удалось подтвердить для удаления. Доплата: " .. tostring(usageChargeAmount) .. ".", "vehicle-rental", info.runtimeKey)
              else
                targetMessage(info.steam, info.name, "Аренда закрыта без штрафа: транспорт не удалось подтвердить для удаления.", "vehicle-rental", info.runtimeKey)
              end
            end
            return
          end
          local usageChargeQueued, usageChargeMessage, usageChargeAmount, chargeableMinutes, minutesAfter10, totalCostSoFar, alreadyPaid, pricePerMinute, usageTaxKey =
            finalizeRentalUsageCharge(live or info, active, "rent-return", os.time())
          appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
            '{"utc":' .. js(nowUtc()) ..
            ',"steamId":' .. js(info.steam) ..
            ',"name":' .. js(info.name) ..
            ',"status":"returned","returned":"true","returnedAt":' .. tostring(os.time()) ..
            ',"displayName":' .. js(extractString(active, "displayName") or "") ..
            ',"vehicleId":' .. js(extractString(active, "vehicleId") or "") ..
            ',"destroyRef":' .. js(destroyRef) ..
            ',"destroyAttempted":true' ..
            ',"destroyOk":true' ..
            ',"destroyMessage":' .. js(destroyMessage) ..
            ',"usageChargeQueued":' .. (usageChargeQueued and "true" or "false") ..
            ',"usageChargeAmount":' .. tostring(usageChargeAmount) ..
            ',"chargeableMinutes":' .. tostring(chargeableMinutes) ..
            ',"minutesAfter10":' .. tostring(minutesAfter10) ..
            ',"pricePerMinute":' .. tostring(pricePerMinute) ..
            ',"usageTotalCost":' .. tostring(totalCostSoFar) ..
            ',"usageAlreadyPaid":' .. tostring(alreadyPaid) ..
            ',"usageTaxKey":' .. js(usageTaxKey or "") ..
            ',"usageChargeMessage":' .. js(usageChargeMessage) .. '}',
            1024 * 1024)
          if usageChargeAmount > 0 then
            if usageChargeQueued then
              targetMessage(info.steam, info.name,
                "Аренда возвращена. Транспорт удалён. Использовано " .. tostring(chargeableMinutes) .. " мин., доплата " .. tostring(usageChargeAmount) .. " поставлена в очередь.",
                "vehicle-rental", info.runtimeKey)
            else
              targetMessage(info.steam, info.name,
                "Аренда возвращена. Транспорт удалён. Использовано " .. tostring(chargeableMinutes) .. " мин., доплата " .. tostring(usageChargeAmount) .. " перенесена в ожидание.",
                "vehicle-rental", info.runtimeKey)
            end
          else
            targetMessage(info.steam, info.name, "Аренда возвращена. Транспорт удалён, запись сохранена в панели.", "vehicle-rental", info.runtimeKey)
          end
        end)
        targetMessageResolved(info, queued and "Возврат аренды принят в очередь. Подожди, удаляю транспорт и обновляю запись." or tostring(queueResult))
      end
      return true
    end
    if current ~= nil then
      targetMessageResolved(info, "У тебя уже есть активная аренда. Используй " .. commandUsage("rent", " time") .. ", " .. commandUsage("rent", " extend <minutes>") .. " или " .. commandUsage("rent", " return") .. ".")
      return true
    end
    local vehicles = availableRentalVehiclesForInfo(info)
    local option = vehicles[sub]
    if option == nil and sub == "wolfswaggen" then option = vehicles["wolfswagen"] end
    if option == nil and sub == "wolfswagen" then option = vehicles["wolfswaggen"] end
    if option == nil then
      targetMessageResolved(info, "Неизвестный тип транспорта. Используй " .. commandUsage("rent", " list") .. ".")
      return true
    end
    option = vipRentalVehicleForInfo(info, option) or option
    local minMinutes = math.max(1, tonumber(option.minMinutes or 10) or 10)
    local maxMinutes = math.max(minMinutes, tonumber(option.maxMinutes or 60) or 60)
    local defaultMinutes = math.max(minMinutes, tonumber(option.defaultMinutes or minMinutes) or minMinutes)
    if defaultMinutes > maxMinutes then defaultMinutes = maxMinutes end
    local minutes = math.floor(tonumber(words[3]) or defaultMinutes)
    if minutes < minMinutes then minutes = minMinutes end
    if minutes > maxMinutes then minutes = maxMinutes end
    local waitSeconds = vehicleRentalSpawnCooldownRemaining(info)
    if waitSeconds > 0 then
      targetMessageResolved(info, "Аренда транспорта сейчас в безопасной паузе. Подожди " .. tostring(waitSeconds) .. " сек., чтобы сервер не лагал.")
      return true
    end
    local rentalCharge = math.max(0, option.initial)
    local queued, queueResult = enqueueMutation("vehicle-rental-create", info, function(queueItem)
      local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey)
      if live == nil or not playerInfoHasLiveRuntime(live) or not looksLikeSteamId(cleanText(live.steam or "")) then
        targetMessage(info.steam, info.name, "Аренда не выполнена: игрок ещё не готов в live runtime. Повтори команду через несколько секунд.", "vehicle-rental", info.runtimeKey)
        return
      end
      if latestActiveRental(live) ~= nil then
        targetMessage(info.steam, info.name, "Аренда не создана: у тебя уже есть активная аренда.", "vehicle-rental", info.runtimeKey)
        return
      end
      local spawnX, spawnY, spawnZ = vectorOf(live.pawn)
      local scheduled, scheduleMessage = spawnVehicleForInfoAsync(option.asset, live, {
        requireForwardLocation = true,
        source = "vehicle-rental"
      }, function(sent, result, destroyRef, beforeVehicles)
        if vehicleSpawnAsyncQueueIsStale(queueItem, "vehicle-rental-create") then return end
        local currentLive = resolvePlayerInfo(live.steam, live.name, live, live.runtimeKey) or live
        if sent then
          local startedAt = os.time()
          local expiresAt = startedAt + minutes * 60
          local tracked = tostring(destroyRef or "") ~= ""
          if tracked then
            local charged, chargeMessage = true, ""
            if rentalCharge > 0 then
              charged, chargeMessage = changeMoney(currentLive.steam, currentLive.name, -rentalCharge, "Normal", currentLive.runtimeKey)
            end
            if not charged then
              destroyVehicleRef(destroyRef, currentLive, "rental-charge-failed")
              appendActionEvent("vehicle_rental_charge_failed", false, currentLive, tostring(chargeMessage),
                '{"alias":' .. js(sub) .. ',"vehicleId":' .. js(option.asset) .. ',"charge":' .. tostring(rentalCharge) .. ',"destroyRef":' .. js(destroyRef) .. ',"stage":"after-spawn-tracked"}')
              appendJsonArray(STATE_DIR .. "\\vehicle-rentals.json",
                '{"utc":' .. js(nowUtc()) ..
                ',"steamId":' .. js(currentLive.steam or "") ..
                ',"name":' .. js(currentLive.name or "") ..
                ',"alias":' .. js(sub) ..
                ',"status":"failed"' ..
                ',"displayName":' .. js(option.display) ..
                ',"vehicleId":' .. js(option.asset) ..
                ',"minutes":' .. tostring(minutes) ..
                ',"startedAt":' .. tostring(startedAt) ..
                ',"expiresAt":' .. tostring(expiresAt) ..
                ',"totalCharge":' .. tostring(rentalCharge) ..
                ',"destroyRef":' .. js(destroyRef) ..
                ',"reason":"charge not confirmed after tracked spawn"}',
                1024 * 1024)
              targetMessage(info.steam, info.name, "Транспорт появился, но оплату не удалось подтвердить. Аренда отменена, транспорт удалён.", "vehicle-rental", info.runtimeKey)
              finishMutationQueueAsync(queueItem, false, "Оплата аренды не подтверждена.")
              return
            end
            completeRentalCreation(currentLive, sub, option.display, option.asset, minutes, option.initial, option.price, rentalCharge, destroyRef, startedAt, expiresAt, false)
            finishMutationQueueAsync(queueItem, true, "Аренда подтверждена через native DB.")
            return
          end
          appendActiveRentalRecord(currentLive, sub, option.display, option.asset, minutes, startedAt, expiresAt, option.initial, option.price, 0, "", ',"pendingVerify":true,"chargePending":true')
          appendActionEvent("vehicle_rental_spawn_pending_verify", true, currentLive, "spawn command accepted; waiting for runtime vehicle confirmation",
            '{"alias":' .. js(sub) .. ',"vehicleId":' .. js(option.asset) .. ',"minutes":' .. tostring(minutes) .. ',"chargePending":' .. tostring(rentalCharge) .. '}')
          targetMessage(info.steam, info.name, "Команда аренды отправлена. Проверяю, что транспорт реально появился рядом с тобой.", "vehicle-rental", info.runtimeKey)
          scheduleRentalCreationVerification(currentLive, sub, option, minutes, rentalCharge, beforeVehicles, spawnX, spawnY, spawnZ)
          finishMutationQueueAsync(queueItem, true, "Аренда принята, runtime-подтверждение запущено.")
          return
        end
        appendActionEvent("vehicle_rental_spawn_failed", false, currentLive, tostring(result),
          '{"alias":' .. js(sub) .. ',"vehicleId":' .. js(option.asset) .. ',"charged":false,"chargeRefunded":0}')
        targetMessage(info.steam, info.name, "Транспорт не выдан: " .. tostring(result) .. ". Деньги не списывал.", "vehicle-rental", info.runtimeKey)
        finishMutationQueueAsync(queueItem, false, tostring(result or "Транспорт не выдан."))
      end)
      if not scheduled then
        appendActionEvent("vehicle_rental_spawn_failed", false, live, tostring(scheduleMessage),
          '{"alias":' .. js(sub) .. ',"vehicleId":' .. js(option.asset) .. ',"charged":false,"route":"async-schedule"}')
        targetMessage(info.steam, info.name, "Транспорт не выдан: " .. tostring(scheduleMessage) .. ". Деньги не списывал.", "vehicle-rental", info.runtimeKey)
        return
      end
      return "__mutation_async__"
    end)
    if queued then reserveVehicleRentalSpawnCooldown(info) end
    targetMessageResolved(info, queued and "Заявка на аренду принята в очередь. Подожди, проверяю транспорт рядом с тобой." or tostring(queueResult))
    return true
  end

  if commandMatches(command, "invdel") then
    local entityId = words[2] or ""
    local itemId = words[3] or ""
    if entityId == "" then
      targetMessageResolved(info, "Использование: /invdel <EntityID>. Лучше удалять предмет кнопкой в панели.")
      return true
    end
    local queued, queueResult = deleteInventoryItem(info.steam, info.name, info.runtimeKey, entityId, itemId, "", "")
    targetMessageResolved(info, queued and "Удаление предмета принято в очередь." or tostring(queueResult))
    return true
  end

  if commandMatches(command, "welcomepack") then
    if not moduleEnabled("welcome-pack", true) then
      targetMessageResolved(info, "Стартовый набор сейчас отключён.")
      return true
    end
    local requiredPermission = configString("welcome-pack", { "RequiredPermission", "requiredPermission" }, "")
    if not hasPermission(info, requiredPermission) then
      targetMessageResolved(info, permissionDeniedText(requiredPermission))
      return true
    end
    local cooldownHours = math.max(0, configNumber("welcome-pack", { "CooldownHours", "cooldownHours" }, 30000))
    cooldownHours = packVipCooldownHoursForInfo(info, "welcome-pack", "WelcomePack", cooldownHours) or cooldownHours
    local cooldownSeconds = math.max(0, cooldownHours) * 3600
    local remaining = cooldownRemaining("welcome-pack-timers.json", info, cooldownSeconds)
    if remaining > 0 then
      targetMessageResolved(info, "Стартовый набор уже получен. Осталось " .. tostring(remaining) .. " сек.")
      return true
    end
    local claimKey = playerStateKey(info)
    if claimKey ~= "" and welcomeClaimsInFlight[claimKey] then
      targetMessageResolved(info, "Стартовый набор уже выдаётся. Дождись окончания текущей выдачи.")
      return true
    end
    if claimKey ~= "" then welcomeClaimsInFlight[claimKey] = true end
    targetMessageResolved(info, "Стартовый набор принят в очередь, выдаю предметы.")
    local steamId = info.steam
    local name = info.name
    local itemsSpec = combineItemsSpec(welcomeItemsSpec(), packVipItemsSpecForInfo(info, "welcome-pack", "WelcomePack"))
    deferGame(100, function()
      local queued, queueResult = enqueueMutation("welcome-pack", info, function(queueItem)
        local live = resolvePlayerInfo(steamId, name, info, info.runtimeKey) or info
        local function finishWelcome(allOk, message)
          if allOk then
            rememberCooldown("welcome-pack-timers.json", info, cooldownSeconds)
          end
          appendJsonArray(STATE_DIR .. "\\welcome-pack-claims.json", '{"utc":' .. js(nowUtc()) .. ',"steamId":' .. js(steamId or "") .. ',"name":' .. js(name or "") .. ',"ok":' .. (allOk and "true" or "false") .. ',"message":' .. js(tostring(message or "")) .. '}', 1024 * 1024)
          local successMessage = extractStringAny(configText("welcome-pack"), { "SuccessMessage", "successMessage" }) or "Стартовый набор выдан."
          targetMessage(steamId, name, allOk and successMessage or "Стартовый набор не выдан полностью. Детали записаны в журнал администратора.", "command-reply", info.runtimeKey)
          if claimKey ~= "" then welcomeClaimsInFlight[claimKey] = nil end
          finishMutationQueueAsync(queueItem, allOk, "Стартовый набор завершён.")
        end
        local function afterItems(delivered, deliverMessage)
          if not delivered then
            finishWelcome(false, deliverMessage)
            return
          end
          local okRun, bonusOk, bonusMessage = pcall(grantPackVipBonuses, live, "welcome-pack", "WelcomePack", live.runtimeKey or info.runtimeKey)
          if not okRun then
            finishWelcome(false, tostring(bonusOk))
            return
          end
          if bonusMessage ~= "" then deliverMessage = tostring(deliverMessage or "") .. " | " .. tostring(bonusMessage) end
          if not bonusOk then
            finishWelcome(false, deliverMessage)
            return
          end
          local started, startMessage = deliverWelcomeRentalVehiclesAsync(live, queueItem, function(vehicleOk, vehicleMessage)
            local finalMessage = tostring(deliverMessage or "")
            if vehicleMessage ~= "" then finalMessage = finalMessage .. " | " .. tostring(vehicleMessage) end
            finishWelcome(vehicleOk == true, finalMessage)
          end)
          if not started then
            finishWelcome(false, tostring(startMessage or "Транспорт стартпака не поставлен в безопасную очередь."))
          end
        end
        local okStart, startErr = pcall(function()
          if tostring(itemsSpec or "") ~= "" then
            deliverItemsBatchAsync(steamId, name, itemsSpec, live, live.runtimeKey or info.runtimeKey,
              configNumber("welcome-pack", { "InterItemDelayMs", "interItemDelayMs" }, 2500), afterItems)
          else
            afterItems(true, "")
          end
        end)
        if not okStart then
          finishWelcome(false, tostring(startErr))
          return nil
        end
        return "__mutation_async__"
      end)
      if not queued then
        if claimKey ~= "" then welcomeClaimsInFlight[claimKey] = nil end
        targetMessage(steamId, name, tostring(queueResult), "command-reply", info.runtimeKey)
      end
    end)
    return true
  end

  if commandMatches(command, "dailypack") then
    if not moduleEnabled("daily-pack", true) then
      targetMessageResolved(info, "Ежедневный пак сейчас отключён.")
      return true
    end
    local requiredPermission = configString("daily-pack", { "RequiredPermission", "requiredPermission" }, "")
    if not hasPermission(info, requiredPermission) then
      targetMessageResolved(info, permissionDeniedText(requiredPermission))
      return true
    end
    local cooldownHours = math.max(0, configNumber("daily-pack", { "CooldownHours", "cooldownHours" }, 24))
    cooldownHours = packVipCooldownHoursForInfo(info, "daily-pack", "DailyPack", cooldownHours) or cooldownHours
    local cooldownSeconds = math.max(0, cooldownHours) * 3600
    local remaining = cooldownRemaining("daily-pack-timers.json", info, cooldownSeconds)
    if remaining > 0 then
      targetMessageResolved(info, "Ежедневный пак уже получен. Осталось " .. tostring(remaining) .. " сек.")
      return true
    end
    local claimKey = playerStateKey(info)
    if claimKey ~= "" and dailyPackClaimsInFlight[claimKey] then
      targetMessageResolved(info, "Ежедневный пак уже выдаётся. Дождись окончания текущей выдачи.")
      return true
    end
    if claimKey ~= "" then dailyPackClaimsInFlight[claimKey] = true end
    targetMessageResolved(info, "Ежедневный пак принят в очередь, выдаю предметы.")
    local steamId = info.steam
    local name = info.name
    local itemsSpec = combineItemsSpec(dailyPackItemsSpec(), packVipItemsSpecForInfo(info, "daily-pack", "DailyPack"))
    deferGame(100, function()
      local queued, queueResult = enqueueMutation("daily-pack", info, function(queueItem)
        local live = resolvePlayerInfo(steamId, name, info, info.runtimeKey) or info
        local function finishDaily(allOk, message)
          if allOk then
            rememberCooldown("daily-pack-timers.json", info, cooldownSeconds)
          end
          appendJsonArray(STATE_DIR .. "\\daily-pack-claims.json", '{"utc":' .. js(nowUtc()) .. ',"steamId":' .. js(steamId or "") .. ',"name":' .. js(name or "") .. ',"ok":' .. (allOk and "true" or "false") .. ',"message":' .. js(tostring(message or "")) .. '}', 1024 * 1024)
          local successMessage = extractStringAny(configText("daily-pack"), { "SuccessMessage", "successMessage" }) or "Ежедневный пак выдан."
          targetMessage(steamId, name, allOk and successMessage or "Ежедневный пак не выдан полностью. Детали записаны в журнал администратора.", "command-reply", info.runtimeKey)
          if claimKey ~= "" then dailyPackClaimsInFlight[claimKey] = nil end
          finishMutationQueueAsync(queueItem, allOk, "Ежедневный пак завершён.")
        end
        local function afterItems(delivered, deliverMessage)
          local okRun, allOk, message = pcall(function()
            if delivered then
              local bonusOk, bonusMessage = grantPackVipBonuses(live, "daily-pack", "DailyPack", live.runtimeKey or info.runtimeKey)
              if bonusMessage ~= "" then deliverMessage = tostring(deliverMessage or "") .. " | " .. tostring(bonusMessage) end
              if not bonusOk then return false, deliverMessage end
            end
            return delivered, deliverMessage
          end)
          if not okRun then
            finishDaily(false, tostring(allOk))
          else
            finishDaily(allOk, message)
          end
        end
        local okStart, startErr = pcall(function()
          deliverItemsBatchAsync(steamId, name, itemsSpec, live, live.runtimeKey or info.runtimeKey,
            configNumber("daily-pack", { "InterItemDelayMs", "interItemDelayMs" }, 2500), afterItems)
        end)
        if not okStart then
          finishDaily(false, tostring(startErr))
          return nil
        end
        return "__mutation_async__"
      end)
      if not queued then
        if claimKey ~= "" then dailyPackClaimsInFlight[claimKey] = nil end
        targetMessage(steamId, name, tostring(queueResult), "command-reply", info.runtimeKey)
      end
    end)
    return true
  end

  if commandMatches(command, "vip") then
    if not moduleEnabled("vip-system", true) then
      targetMessageResolved(info, "VIP-модуль сейчас отключён.")
      return true
    end
    if not vipActiveForInfo(info) then
      targetMessageResolved(info, "Команда /vip доступна только активным VIP-игрокам.")
      return true
    end
    targetMessageResolved(info, vipStatusText(info))
    return true
  end

  if commandMatches(command, "discordtest") then
    if not moduleEnabled("discord-log", false) then
      targetMessageResolved(info, "Журнал Discord сейчас отключён.")
      return true
    end
    local route = (words[2] or "system"):lower()
    local note = table.concat(words, " ", 3)
    if note == "" then note = "Проверка Discord от " .. tostring(info.name ~= "" and info.name or info.steam) end
    appendJsonArray(STATE_DIR .. "\\discord-log.json", '{"utc":' .. js(nowUtc()) .. ',"route":' .. js(route) .. ',"message":' .. js(note) .. ',"player":' .. js(info.name) .. ',"steamId":' .. js(info.steam) .. ',"ok":true}', 1024 * 1024)
    targetMessageResolved(info, "Проверка Discord записана в очередь панели для канала '" .. route .. "'. Для реальной отправки настрой вебхук и нажми проверку в панели.")
    return true
  end

  if commandMatches(command, "wargm") then
    if not moduleEnabled("wargm-shop", false) then
      targetMessageResolved(info, "Магазин Wargm сейчас отключён.")
      return true
    end
    WARGM_COMMAND_NEXT_AT = WARGM_COMMAND_NEXT_AT or {}
    local wargmKey = playerStateKey(info)
    local now = os.time()
    local nextAt = tonumber(WARGM_COMMAND_NEXT_AT[wargmKey] or 0) or 0
    if wargmKey ~= "" and nextAt > now then
      targetMessageResolved(info, "Wargm: выдача уже в очереди. Повтори через " .. tostring(nextAt - now) .. " сек.")
      return true
    end
    if wargmKey ~= "" then WARGM_COMMAND_NEXT_AT[wargmKey] = now + 60 end
    local wargmCommandStartedAt = os.time()
    local syncRequested = requestWargmSync(info)
    targetMessageResolved(info, syncRequested and "Wargm: проверяю покупки. Если покупка есть, выдача начнётся через несколько секунд." or "Wargm: не удалось поставить проверку Wargm API, пробую локальную очередь.")
    local allowLuaClaimAfterSync = configBool("wargm-shop", { "EnableLuaWargmClaimFallback", "enableLuaWargmClaimFallback", "EnableLuaClaimFallback", "enableLuaClaimFallback" }, false) == true
    if syncRequested and not allowLuaClaimAfterSync then
      deferGame(12000, function()
        local recentBackendDelivered = recentWargmDeliveredCount(info.steam or info.steamId, wargmCommandStartedAt - 2)
        local message = "Wargm: проверка Wargm API запущена. Если покупка найдена, выдача сработает автоматически; если товар только что куплен, повтори /wargm через 10 сек."
        if recentBackendDelivered > 0 then
          message = "Wargm: выдано операций: " .. tostring(recentBackendDelivered) .. "."
        end
        targetMessage(info.steam, info.name, message, "wargm-shop", info.runtimeKey)
        if wargmKey ~= "" then WARGM_COMMAND_NEXT_AT[wargmKey] = os.time() + 10 end
      end)
      return true
    end
    deferGame(12000, function()
    local queued, queueResult = enqueueMutation("wargm-claim", info, function()
      local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
      local pending = wargmPendingObjects()
      local deliveredKeys = deliveredWargmKeys()
      local delivered = 0
      local skipped = 0
      local retryWaiting = 0
      local retryWaitMax = 0
      local confirmOperationId = ""
      for index, object in ipairs(pending) do
        local steam = wargmObjectPlayerSteam(object)
        local deliveryObject, matchedRule = wargmRuleForPending(object)
        if deliveryObject == nil then deliveryObject = object end
        local mode = (extractString(deliveryObject, "mode") or extractString(deliveryObject, "DeliveryMode") or extractString(deliveryObject, "deliveryMode") or "item"):lower():gsub("[%s_%-%.\"]+", "")
        local opKey = wargmOperationKey(object, index)
        local operationIdForState = wargmOperationIdValue(object)
        local alreadyDelivered = wargmOperationSettled(deliveredKeys, object, index)
        if steam ~= "" and steam == live.steam and not alreadyDelivered then
          local retryRemaining = wargmRetrySecondsRemaining(opKey)
          if retryRemaining > 0 then
            skipped = skipped + 1
            retryWaiting = retryWaiting + 1
            if retryRemaining > retryWaitMax then retryWaitMax = retryRemaining end
            rememberWargmRetryPending(object, opKey)
            appendJsonArray(STATE_DIR .. "\\wargm-shop.json", '{"utc":' .. js(nowUtc()) .. ',"key":' .. js(opKey) .. ',"steamId":' .. js(live.steam or "") .. ',"name":' .. js(live.name or "") .. ',"status":"retry-wait","seconds":' .. tostring(retryRemaining) .. '}', 1024 * 1024)
          else
          local okDelivery = false
          local deliveryMessage = ""
          appendJsonArray(STATE_DIR .. "\\wargm-attempts.json", '{"utc":' .. js(nowUtc()) .. ',"key":' .. js(opKey) .. ',"steamId":' .. js(live.steam or "") .. ',"name":' .. js(live.name or "") .. ',"mode":' .. js(mode) .. ',"matchedRule":' .. js(matchedRule or "") .. ',"status":"delivering"}', 1024 * 1024)
          if mode == "money" or mode == "currency" or mode == "balance" or mode == "gold" then
            local amount = extractNumber(deliveryObject, "amount") or extractNumber(deliveryObject, "Amount") or extractNumber(deliveryObject, "money") or extractNumber(deliveryObject, "Money") or extractNumber(deliveryObject, "gold") or extractNumber(deliveryObject, "Gold") or 0
            if amount ~= 0 then
              local okMoney, moneyMessage = changeMoney(live.steam, live.name, amount, mode == "gold" and "Gold" or "Normal", live.runtimeKey)
              deliveryMessage = tostring(moneyMessage or "")
              if okMoney then okDelivery = true end
            end
          elseif mode == "fame" or mode == "famepoint" or mode == "famepoints" or mode == "changefame" or mode == "changefamepoints" then
            local amount = extractNumber(deliveryObject, "amount") or extractNumber(deliveryObject, "Amount") or extractNumber(deliveryObject, "fame") or extractNumber(deliveryObject, "Fame") or extractNumber(deliveryObject, "famePoints") or extractNumber(deliveryObject, "FamePoints") or 0
            if amount ~= 0 then
              local okFame, fameMessage = changeFamePoints(live.steam, live.name, amount, live.runtimeKey)
              deliveryMessage = tostring(fameMessage or "")
              if okFame then okDelivery = true end
            end
          elseif mode == "setfame" or mode == "setfamepoints" then
            local amount = extractNumber(deliveryObject, "amount") or extractNumber(deliveryObject, "Amount") or extractNumber(deliveryObject, "fame") or extractNumber(deliveryObject, "Fame") or extractNumber(deliveryObject, "famePoints") or extractNumber(deliveryObject, "FamePoints") or 0
            if amount ~= 0 then
              local okFame, fameMessage = setFame(live.steam, live.name, amount, live.runtimeKey)
              deliveryMessage = tostring(fameMessage or "")
              if okFame then okDelivery = true end
            end
          elseif mode == "vip" or mode == "vipprivilege" or mode == "vipprivileges" or mode == "subscription" then
            local days = extractNumber(deliveryObject, "durationDays") or extractNumber(deliveryObject, "DurationDays") or extractNumber(deliveryObject, "days") or extractNumber(deliveryObject, "Days") or extractNumber(deliveryObject, "amount") or extractNumber(deliveryObject, "Amount") or 0
            local tier = extractStringAny(deliveryObject, { "Tier", "tier", "VipTier", "vipTier" }) or "vip"
            local okVip, vipMessage = grantVipPrivilege(live, days, tier, "wargm", "operation=" .. tostring(operationIdForState or ""))
            deliveryMessage = tostring(vipMessage or "")
            if okVip then okDelivery = true end
          elseif mode == "vehicle" or mode == "spawnvehicle" then
            local vehicleId = extractString(deliveryObject, "vehicleId") or extractString(deliveryObject, "VehicleId") or extractString(deliveryObject, "vehicleAsset") or extractString(deliveryObject, "VehicleAsset") or ""
            if vehicleId ~= "" then
              local waitSeconds = wargmVehicleSpawnCooldownRemaining(live)
              if waitSeconds > 0 then
                deliveryMessage = "Спавн транспорта сейчас в безопасной паузе. Повтор будет через " .. tostring(waitSeconds) .. " сек."
              else
                -- A Wargm vehicle purchase does not create a timed rental, so it has no
                -- later need for an EntityID. Avoid a synchronous native DB wait here.
                local okVehicle, vehicleMessage = spawnVehicleForInfo(vehicleId, live, {
                  skipNativeVehicleDbResolve = true,
                  source = "wargm-vehicle"
                })
                deliveryMessage = tostring(vehicleMessage or "")
                if okVehicle then
                  okDelivery = true
                  reserveWargmVehicleSpawnCooldown(live)
                end
              end
            end
          elseif mode == "cargodrop" or mode == "cargodropplayer" or mode == "airdrop" or mode == "scheduledcargodrop" then
            local commandText, dropInfo, dropReason = cargoDropWorldEventCommandForInfo(live)
            if commandText == "" then
              deliveryMessage = "Cargo drop Wargm не запущен: " .. tostring(dropReason or "нет координат") .. ". Покупка не отмечена выданной."
            else
              local okDrop, dropMessage = adminExec(commandText, dropInfo or live)
              deliveryMessage = tostring(dropMessage or "")
              if okDrop then okDelivery = true end
            end
          elseif mode == "allskills" or mode == "allskill" or mode == "skills" or mode == "skillpack" or mode == "skillspack" then
            local level = extractNumber(deliveryObject, "level") or extractNumber(deliveryObject, "skillLevel") or extractNumber(deliveryObject, "SkillLevel") or 4
            local experience = extractNumber(deliveryObject, "experience") or extractNumber(deliveryObject, "skillExperience") or extractNumber(deliveryObject, "SkillExperience") or 0
            local okSkills, skillsMessage = setAllSkills(live.steam, live.name, level, experience, live.runtimeKey)
            deliveryMessage = tostring(skillsMessage or "")
            if okSkills then okDelivery = true end
          elseif mode == "skill" or mode == "setskill" then
            local skill = extractString(deliveryObject, "skill") or extractString(deliveryObject, "skillName") or extractString(deliveryObject, "SkillName") or ""
            local level = extractNumber(deliveryObject, "level") or extractNumber(deliveryObject, "skillLevel") or extractNumber(deliveryObject, "SkillLevel") or 0
            local experience = extractNumber(deliveryObject, "experience") or extractNumber(deliveryObject, "skillExperience") or extractNumber(deliveryObject, "SkillExperience") or 0
            if extractBoolAny(deliveryObject, { "allSkills", "AllSkills", "giveAllSkills", "GiveAllSkills" }, false) == true or allSkillsKeyword(skill) then
              if level <= 0 then level = 4 end
              local okSkill, skillMessage = setAllSkills(live.steam, live.name, level, experience, live.runtimeKey)
              deliveryMessage = tostring(skillMessage or "")
              if okSkill then okDelivery = true end
            elseif skill ~= "" then
              local okSkill, skillMessage = setSkill(live.steam, live.name, skill, level, experience, live.runtimeKey)
              deliveryMessage = tostring(skillMessage or "")
              if okSkill then okDelivery = true end
            end
          elseif mode == "attributes" or mode == "attribute" or mode == "stats" then
            local okAttributes, attributesMessage = setAttributes(live.steam, live.name,
              extractNumber(deliveryObject, "strength") or extractNumber(deliveryObject, "Strength") or 0,
              extractNumber(deliveryObject, "constitution") or extractNumber(deliveryObject, "Constitution") or 0,
              extractNumber(deliveryObject, "dexterity") or extractNumber(deliveryObject, "Dexterity") or 0,
              extractNumber(deliveryObject, "intelligence") or extractNumber(deliveryObject, "Intelligence") or 0,
              false,
              live.runtimeKey)
            deliveryMessage = tostring(attributesMessage or "")
            if okAttributes then okDelivery = true end
          elseif mode == "command" or mode == "admincommand" or mode == "playercommand" or mode == "servercommand" then
            local commandTemplate = extractString(deliveryObject, "command") or extractString(deliveryObject, "commandTemplate") or extractString(deliveryObject, "CommandTemplate") or ""
            commandTemplate = commandTemplate:gsub("{steamId}", live.steam or ""):gsub("{name}", live.name or "")
            if commandTemplate ~= "" then
              local okCommand, commandMessage = adminExec(commandTemplate, live)
              deliveryMessage = tostring(commandMessage or "")
              if okCommand then okDelivery = true end
            end
          else
            local itemsSpec = extractString(deliveryObject, "itemsSpec") or extractString(deliveryObject, "ItemsSpec") or itemsSpecFromConfig(deliveryObject)
            local itemId = extractString(deliveryObject, "itemId") or extractString(deliveryObject, "ItemId") or ""
            local qty = extractNumber(deliveryObject, "quantity") or extractNumber(deliveryObject, "Quantity") or 1
            if itemId ~= "" and not itemIdLooksLikeScumAsset(itemId) then
              deliveryMessage = "Wargm: внешний ID товара " .. tostring(itemId) .. " не является SCUM asset. Настрой правило ItemId/Items в модуле."
              itemId = ""
            end
            if itemsSpec ~= "" or itemId ~= "" then
              local spec = itemsSpec ~= "" and itemsSpec or (itemId .. "|" .. tostring(qty))
              local okItems, itemsMessage = deliverItemsBatch(live.steam, live.name, spec, live, live.runtimeKey)
              deliveryMessage = tostring(itemsMessage or "")
              if okItems then okDelivery = true end
            elseif deliveryMessage == "" then
              deliveryMessage = "Wargm: для товара не настроен SCUM asset или Items."
            end
          end
          if okDelivery then
            delivered = delivered + 1
            deliveredKeys[opKey] = true
            local operationId = operationIdForState
            addWargmOperationIdKeys(deliveredKeys, operationId)
            local offerId = extractString(object, "offerId") or extractString(object, "OfferId") or ""
            local title = extractString(object, "title") or extractString(object, "Title") or ""
            local deliveryItemId = extractString(deliveryObject, "itemId") or extractString(deliveryObject, "ItemId") or extractString(deliveryObject, "item") or ""
            local deliveryItemsSpec = extractString(deliveryObject, "itemsSpec") or extractString(deliveryObject, "ItemsSpec") or itemsSpecFromConfig(deliveryObject)
            local deliveryQuantity = extractNumber(deliveryObject, "quantity") or extractNumber(deliveryObject, "Quantity") or 1
            appendJsonArray(STATE_DIR .. "\\wargm-delivered.json", '{"utc":' .. js(nowUtc()) .. ',"key":' .. js(opKey) .. ',"operationId":' .. js(operationId) .. ',"offerId":' .. js(offerId) .. ',"title":' .. js(title) .. ',"steamId":' .. js(live.steam) .. ',"name":' .. js(live.name) .. ',"mode":' .. js(mode) .. ',"itemId":' .. js(deliveryItemId) .. ',"itemsSpec":' .. js(deliveryItemsSpec) .. ',"quantity":' .. tostring(deliveryQuantity) .. ',"status":"delivered"}', 1024 * 1024)
            appendJsonArray(STATE_DIR .. "\\wargm-shop.json", '{"utc":' .. js(nowUtc()) .. ',"key":' .. js(opKey) .. ',"operationId":' .. js(operationId) .. ',"offerId":' .. js(offerId) .. ',"title":' .. js(title) .. ',"steamId":' .. js(live.steam) .. ',"name":' .. js(live.name) .. ',"mode":' .. js(mode) .. ',"itemId":' .. js(deliveryItemId) .. ',"itemsSpec":' .. js(deliveryItemsSpec) .. ',"quantity":' .. tostring(deliveryQuantity) .. ',"status":"delivered"}', 1024 * 1024)
            forgetWargmRetryPending(opKey, operationId)
            if operationId ~= "" then confirmOperationId = operationId end
          else
            rememberWargmRetryPending(object, opKey)
            appendJsonArray(STATE_DIR .. "\\wargm-attempts.json", '{"utc":' .. js(nowUtc()) .. ',"key":' .. js(opKey) .. ',"steamId":' .. js(live.steam or "") .. ',"name":' .. js(live.name or "") .. ',"mode":' .. js(mode) .. ',"status":"retry","retryAfter":' .. tostring(os.time() + 60) .. ',"message":' .. js(deliveryMessage or "delivery failed") .. '}', 1024 * 1024)
            appendJsonArray(STATE_DIR .. "\\wargm-shop.json", '{"utc":' .. js(nowUtc()) .. ',"key":' .. js(opKey) .. ',"steamId":' .. js(live.steam or "") .. ',"name":' .. js(live.name or "") .. ',"mode":' .. js(mode) .. ',"status":"retry","message":' .. js(deliveryMessage or "delivery failed") .. '}', 1024 * 1024)
          end
          end
        elseif steam ~= "" and steam == live.steam and alreadyDelivered then
          skipped = skipped + 1
          forgetWargmRetryPending(opKey, operationIdForState)
        end
      end
      if delivered > 0 or skipped > 0 then pruneWargmPending(deliveredKeys) end
      if delivered > 0 then requestWargmConfirm(live, confirmOperationId) end
      local recentBackendDelivered = recentWargmDeliveredCount(live.steam, wargmCommandStartedAt - 2)
      local emptyMessage = syncRequested
        and "Wargm: проверка Wargm API запущена. Если покупка найдена, выдача сработает автоматически; если товар только что куплен, повтори /wargm через 10 сек."
        or "Wargm: новых pending-покупок для твоего SteamID нет. Ручная выдача доступна в панели."
      if recentBackendDelivered > 0 then
        emptyMessage = "Wargm: выдано операций: " .. tostring(recentBackendDelivered) .. "."
      elseif retryWaiting > 0 then
        emptyMessage = "Wargm: покупка найдена, выдача ждёт безопасную паузу. Повтори /wargm через " .. tostring(math.ceil(retryWaitMax)) .. " сек."
      elseif skipped > 0 then
        emptyMessage = "Wargm: новых pending-покупок нет. Уже выданных пропущено: " .. tostring(skipped) .. "."
      end
      targetMessage(info.steam, info.name, delivered > 0 and ("Wargm: выдано операций: " .. tostring(delivered) .. ". Уже выданных пропущено: " .. tostring(skipped) .. ".") or emptyMessage, "wargm-shop", info.runtimeKey)
    end)
    if not queued then
      if wargmKey ~= "" then WARGM_COMMAND_NEXT_AT[wargmKey] = os.time() + 10 end
      targetMessageResolved(info, tostring(queueResult))
    end
    end)
    return true
  end

  if commandMatches(command, "streak") or commandMatches(command, "bounty") or commandMatches(command, "huntertop") then
    if not moduleEnabled("bounty-hunt", true) then
      targetMessageResolved(info, "Охота за наградой сейчас отключена.")
      return true
    end
    sendBountyStats(info, command)
    return true
  end

  return false
end

function playerCommandShouldRunImmediately(message)
  local command = (splitWords(message)[1] or ""):lower()
  local key = commandKey(command)
  return key == "help" or key == "hello" or key == "homes" or key == "delhome" or
    key == "sethome" or key == "pm" or key == "reply" or key == "pmhistory" or
    key == "streak" or key == "bounty" or key == "huntertop" or
    key == "welcomepack" or key == "dailypack" or key == "vip" or key == "wargm"
end

function runInlineChatPlayerCommand(info, commandMessage, path, source)
  local commandName = (splitWords(commandMessage)[1] or ""):lower()
  if info == nil then return false end
  local started = os.clock()
  appendLog("inline chat player command start command=" .. tostring(commandName) ..
    " source=" .. tostring(source or "") ..
    " path=" .. tostring(path or "") ..
    " player=" .. tostring(info.name or info.steam or ""))
  local okRun, handledOrErr = pcall(function() return handlePlayerCommand(info, commandMessage) end)
  local durationMs = math.floor((os.clock() - started) * 1000)
  if okRun then
    appendLog("inline chat player command done command=" .. tostring(commandName) ..
      " handled=" .. tostring(handledOrErr) ..
      " durationMs=" .. tostring(durationMs) ..
      " player=" .. tostring(info.name or info.steam or ""))
    appendActionEvent("player_command", handledOrErr == true, info, "handled=" .. tostring(handledOrErr),
      '{"command":' .. js(commandName) ..
      ',"durationMs":' .. tostring(durationMs) ..
      ',"handled":' .. (handledOrErr and "true" or "false") ..
      ',"queued":false,"inlineChat":true,"source":' .. js(source or "") .. '}')
    return handledOrErr == true
  end
  appendLog("inline chat player command failed command=" .. tostring(commandName) .. " err=" .. tostring(handledOrErr))
  appendActionEvent("player_command", false, info, tostring(handledOrErr),
    '{"command":' .. js(commandName) ..
    ',"durationMs":' .. tostring(durationMs) ..
    ',"handled":false,"queued":false,"inlineChat":true,"source":' .. js(source or "") .. '}')
  targetMessagePlayerCommandFailure(info, commandName, "Команда завершилась с ошибкой. Администратор увидит детали в журнале.")
  return false
end

function playerCommandRequiresLiveRefresh(commandName)
  local key = commandKey(tostring(commandName or ""):lower())
  return key == "home" or key == "sethome" or key == "scan" or key == "travel" or key == "ed" or key == "baseloot" or
    key == "help" or key == "hello" or key == "language"
end

PLAYER_COMMAND_QUEUE = PLAYER_COMMAND_QUEUE or {}
PLAYER_COMMAND_QUEUE_BUSY = PLAYER_COMMAND_QUEUE_BUSY or false
PLAYER_COMMAND_QUEUE_CURRENT = PLAYER_COMMAND_QUEUE_CURRENT or nil
PLAYER_COMMAND_QUEUE_SEQ = PLAYER_COMMAND_QUEUE_SEQ or 0
PLAYER_COMMAND_QUEUE_MAX = PLAYER_COMMAND_QUEUE_MAX or 160
PLAYER_COMMAND_QUEUE_MAX_PER_PLAYER = PLAYER_COMMAND_QUEUE_MAX_PER_PLAYER or 8
PLAYER_COMMAND_QUEUE_TIMEOUT_SECONDS = PLAYER_COMMAND_QUEUE_TIMEOUT_SECONDS or 25

function playerCommandQueueKey(info)
  if info == nil then return "" end
  if tostring(info.steam or "") ~= "" then return "steam:" .. tostring(info.steam) end
  if tostring(info.userProfileId or info.serverUserProfileId or "") ~= "" then return "profile:" .. tostring(info.userProfileId or info.serverUserProfileId) end
  if tostring(info.runtimeKey or "") ~= "" then return "runtime:" .. tostring(info.runtimeKey) end
  local name = tostring(info.name or "")
  if name ~= "" and name:lower() ~= "unknown" then return "name:" .. name:lower() end
  return ""
end

function playerCommandRequiresResolvedSteam(commandName)
  local key = commandKey(tostring(commandName or ""):lower())
  return key == "rent" or key == "armory" or key == "starter" or key == "welcomepack" or key == "dailypack" or key == "wargm" or
    key == "travel" or key == "home" or key == "sethome" or key == "delhome" or key == "dlc" or
    key == "scan" or key == "invdel" or key == "vip" or key == "baseloot"
end

CHAT_COMMAND_PLAYER_REFRESH_AT = CHAT_COMMAND_PLAYER_REFRESH_AT or 0

function enrichCommandPlayerIdentity(info)
  if info == nil then return nil end
  local steam = cleanText(info.steam or info.steamId or "")
  if looksLikeSteamId(steam) then
    info.steam = steam
    info.steamId = steam
    rememberPersistentPlayerIdentity(steam, info.userProfileId or info.serverUserProfileId or info.profileId or "", info.name or "", "command-input")
    return info
  end

  local okLog, fromLog = pcall(function()
    if enrichPlayerInfoFromServerLog ~= nil then return enrichPlayerInfoFromServerLog(info) end
    return info
  end)
  if okLog and fromLog ~= nil then info = fromLog end
  steam = cleanText(info.steam or info.steamId or "")
  if looksLikeSteamId(steam) then
    info.steam = steam
    info.steamId = steam
    rememberPersistentPlayerIdentity(steam, info.userProfileId or info.serverUserProfileId or info.profileId or "", info.name or "", "command-log")
    return info
  end

  local remembered = persistentPlayerIdentityForInfo(info)
  if remembered ~= nil then
    info = applyServerLogIdentity(info, remembered) or info
    steam = cleanText(info.steam or info.steamId or "")
    if looksLikeSteamId(steam) then
      info.steam = steam
      info.steamId = steam
      local source = tostring(info.source or "")
      if source:find("command-identity-state", 1, true) == nil then
        info.source = (source ~= "" and (source .. "+") or "") .. "command-identity-state"
      end
      return info
    end
  end

  local maxAge = math.max(10, configNumber("bridge-safety", { "PlayerInfoCacheTtlSeconds", "playerInfoCacheTtlSeconds" }, 90))
  local infos = cachedPlayerInfos(maxAge)
  if infos == nil or #(infos or {}) == 0 then
    pcall(refreshPlayerInfoCache)
    infos = PLAYER_INFO_CACHE or {}
  end

  local profile = cleanText(info.userProfileId or info.serverUserProfileId or info.profileId or "")
  local runtimeKey = cleanText(info.runtimeKey or info.rpcKey or info.pcKey or info.psKey or info.pawnKey or "")
  local name = cleanText(info.name or "")
  local lowerName = name:lower()

  for _, candidate in ipairs(infos or {}) do
    local candidateProfile = cleanText(candidate.userProfileId or candidate.serverUserProfileId or candidate.profileId or "")
    local profileMatches = profile ~= "" and profile ~= "0" and candidateProfile ~= "" and candidateProfile ~= "0" and profile == candidateProfile
    local runtimeMatches = runtimeKey ~= "" and runtimeKeyMatches(candidate, runtimeKey)
    local candidateName = cleanText(candidate.name or "")
    local nameMatches = lowerName ~= "" and lowerName ~= "unknown" and candidateName ~= "" and candidateName:lower() == lowerName

    if profileMatches or runtimeMatches or nameMatches then
      local okCandidateLog, candidateFromLog = pcall(function()
        if enrichPlayerInfoFromServerLog ~= nil then return enrichPlayerInfoFromServerLog(candidate) end
        return candidate
      end)
      if okCandidateLog and candidateFromLog ~= nil then candidate = candidateFromLog end

      local candidateSteam = cleanText(candidate.steam or candidate.steamId or "")
      if looksLikeSteamId(candidateSteam) then
        info = mergeRuntimeIntoIdentity(info, candidate)
        info.steam = candidateSteam
        info.steamId = candidateSteam
        if cleanText(info.name or "") == "" or cleanText(info.name or ""):lower() == "unknown" then
          info.name = candidateName
        end
        if cleanText(info.userProfileId or "") == "" then info.userProfileId = candidateProfile end
        if cleanText(info.serverUserProfileId or "") == "" then info.serverUserProfileId = candidateProfile end
        local source = tostring(info.source or "")
        if source:find("command-live-cache", 1, true) == nil then
          info.source = (source ~= "" and (source .. "+") or "") .. "command-live-cache"
        end
        rememberPersistentPlayerIdentity(candidateSteam, info.userProfileId or info.serverUserProfileId or candidateProfile or "", info.name or candidateName or "", "command-live-cache")
        return info
      end
    end
  end

  return info
end

function playerCommandHasResolvedSteam(info)
  info = enrichCommandPlayerIdentity(info)
  return info ~= nil and looksLikeSteamId(cleanText(info.steam or info.steamId or ""))
end

function playerCommandIdentityReady(info, commandName)
  if info == nil then return false end
  if playerCommandRequiresResolvedSteam(commandName) then return playerCommandHasResolvedSteam(info) end
  return playerInfoHasIdentity(info)
end

function refreshPlayerInfoCacheForCommand(commandName)
  local cooldown = math.max(1, configNumber("bridge-safety", { "CommandResolveRefreshCooldownSeconds", "commandResolveRefreshCooldownSeconds" }, 3))
  local now = os.clock()
  if (now - (CHAT_COMMAND_PLAYER_REFRESH_AT or 0)) < cooldown then return false end
  CHAT_COMMAND_PLAYER_REFRESH_AT = now
  local okRefresh, refreshErr = pcall(refreshPlayerInfoCache)
  if not okRefresh then
    appendLog("command player cache refresh failed command=" .. tostring(commandName or "") .. " err=" .. tostring(refreshErr))
    return false
  end
  local count = #(PLAYER_INFO_CACHE or {})
  local bypassedJoinSettle = false
  if count == 0 and configBool("bridge-safety", { "AllowCommandRuntimeScanDuringJoinSettle", "allowCommandRuntimeScanDuringJoinSettle" }, true) then
    local okBypass, bypassErr = pcall(function()
      count = replacePlayerInfoCache(listPlayerInfosUnchecked("command-runtime-scan") or {})
    end)
    if okBypass then
      bypassedJoinSettle = true
    else
      appendLog("command player cache bypass refresh failed command=" .. tostring(commandName or "") .. " err=" .. tostring(bypassErr))
    end
  end
  appendLog("command player cache refreshed command=" .. tostring(commandName or "") .. " players=" .. tostring(count) .. " bypassJoinSettle=" .. tostring(bypassedJoinSettle))
  return true
end

PANEL_PLAYER_REFRESH_AT = PANEL_PLAYER_REFRESH_AT or 0

function playerInfoHasLiveAdminChannel(info)
  return info ~= nil and (
    (info.pc ~= nil and isValidObject(info.pc)) or
    (info.rpc ~= nil and isValidObject(info.rpc))
  )
end

function refreshPlayerInfoCacheForPanel(reason, force)
  local cooldown = math.max(1, configNumber("bridge-safety", { "PanelResolveRefreshCooldownSeconds", "panelResolveRefreshCooldownSeconds" }, 2))
  local now = os.clock()
  if force ~= true and (now - (PANEL_PLAYER_REFRESH_AT or 0)) < cooldown then return false end
  PANEL_PLAYER_REFRESH_AT = now

  local count = #(PLAYER_INFO_CACHE or {})
  local usedUnchecked = false
  local okRefresh, refreshErr = pcall(function()
    local refreshed = refreshPlayerInfoCache()
    if tonumber(refreshed) ~= nil then count = tonumber(refreshed) end
  end)
  if not okRefresh then
    appendLog("panel player cache refresh failed reason=" .. tostring(reason or "") .. " err=" .. tostring(refreshErr))
  else
    count = #(PLAYER_INFO_CACHE or {})
  end

  if (force == true or count == 0) and configBool("bridge-safety", { "AllowPanelRuntimeScanDuringJoinSettle", "allowPanelRuntimeScanDuringJoinSettle" }, true) then
    local okBypass, bypassErr = pcall(function()
      count = refreshPlayerInfoCacheUnchecked("panel-" .. tostring(reason or "resolve"))
    end)
    if okBypass then
      usedUnchecked = true
    else
      appendLog("panel unchecked player cache refresh failed reason=" .. tostring(reason or "") .. " err=" .. tostring(bypassErr))
    end
  end

  PLAYERS_JSON_CACHE = nil
  PLAYERS_JSON_CACHE_AT = 0
  appendLog("panel player cache refreshed reason=" .. tostring(reason or "") ..
    " players=" .. tostring(count or 0) .. " unchecked=" .. tostring(usedUnchecked))
  return true
end

function resolvePlayerInfoForPanel(steamId, name, runtimeKey, preferredInfo, reason)
  local info = findPlayer(steamId, name, runtimeKey) or resolvePlayerInfo(steamId, name, preferredInfo, runtimeKey)
  if playerInfoHasLiveAdminChannel(info) then return info end

  refreshPlayerInfoCacheForPanel(reason or "resolve", true)
  local refreshed = findPlayer(steamId, name, runtimeKey) or resolvePlayerInfo(steamId, name, info or preferredInfo, runtimeKey)
  if refreshed ~= nil then return refreshed end
  return info
end

function panelLivePlayerResolveMessage(code)
  if code == "missing" then return "Игрок не найден среди реально подключённых." end
  if code == "runtime" then return "Игрок найден только в старой записи панели, live runtime не подтверждён. Обнови список игроков и повтори." end
  if code == "admin-channel" then return "Игрок ещё не готов для команд панели: нет live controller/RPC." end
  if code == "pawn" then return "Игрок ещё не готов для команд панели: персонаж не прогрузился." end
  if code == "location" then return "Игрок ещё не готов для команд панели: live-координаты не подтверждены." end
  if code == "steam" then return "Игрок ещё не готов для команд панели: SteamID не подтверждён." end
  return "Игрок ещё не готов для безопасной команды панели."
end

function panelLivePlayerReady(info, options)
  options = options or {}
  if info == nil then return nil, false, panelLivePlayerResolveMessage("missing"), "missing" end

  local live = refreshRuntimePlayerInfo(info) or info
  if not playerInfoHasLiveRuntime(live) then
    return live, false, panelLivePlayerResolveMessage("runtime"), "runtime"
  end
  if options.requireAdminChannel ~= false and not playerInfoHasLiveAdminChannel(live) then
    return live, false, panelLivePlayerResolveMessage("admin-channel"), "admin-channel"
  end
  if options.requirePawn == true and (live.pawn == nil or not isValidObject(live.pawn)) then
    return live, false, panelLivePlayerResolveMessage("pawn"), "pawn"
  end
  if options.requireLocation == true then
    if not playerHasUsableLocation(live) and live.pawn ~= nil and isValidObject(live.pawn) then
      local x, y, z = vectorOf(live.pawn)
      live.x, live.y, live.z = x, y, z
    end
    if not playerHasUsableLocation(live) then
      return live, false, panelLivePlayerResolveMessage("location"), "location"
    end
  end
  if options.requireSteam == true and not looksLikeSteamId(cleanText(live.steam or live.steamId or "")) then
    return live, false, panelLivePlayerResolveMessage("steam"), "steam"
  end
  return live, true, "ready", "ready"
end

function resolveLivePlayerInfoForPanel(steamId, name, runtimeKey, preferredInfo, reason, options)
  if configBool("bridge-safety", { "EnableStrictPanelPlayerResolve", "enableStrictPanelPlayerResolve" }, true) == false then
    return resolvePlayerInfoForPanel(steamId, name, runtimeKey, preferredInfo, reason), nil, "disabled"
  end
  local info = resolvePlayerInfoForPanel(steamId, name, runtimeKey, preferredInfo, reason)
  local live, ready, message, code = panelLivePlayerReady(info, options or {})
  if ready then return live, nil, code end

  local targetInfo = live or info or {
    steam = tostring(steamId or ""),
    name = tostring(name or ""),
    runtimeKey = tostring(runtimeKey or "")
  }
  appendActionEvent("panel_player_resolve", false, targetInfo, tostring(message or ""),
    '{"reason":' .. js(reason or "panel") ..
    ',"code":' .. js(code or "") ..
    ',"requireLocation":' .. tostring(((options or {}).requireLocation == true)) ..
    ',"requireSteam":' .. tostring(((options or {}).requireSteam == true)) .. '}')
  appendLog("panel live player resolve failed reason=" .. tostring(reason or "panel") ..
    " code=" .. tostring(code or "") ..
    " target=" .. tostring((targetInfo and (targetInfo.steam or targetInfo.name or targetInfo.runtimeKey)) or ""))
  return nil, message, code
end

function targetMessagePlayerCommandFailure(info, commandName, message)
  if playerCommandRequiresResolvedSteam(commandName) and not playerCommandHasResolvedSteam(info) then
    appendLog("player command reply skipped unresolved steam command=" .. tostring(commandName or "") .. " targetKey=" .. tostring(playerReplyTargetKey(info)))
    return false
  end
  if not playerReplyTargetReliable(info) then
    appendLog("player command reply skipped unresolved target command=" .. tostring(commandName or ""))
    return false
  end
  targetMessageResolved(info, tostring(message or "Команда не поставлена в очередь."))
  return true
end

function playerCommandPendingFor(key)
  local count = 0
  for _, item in ipairs(PLAYER_COMMAND_QUEUE or {}) do
    if tostring(item.key or "") == key then count = count + 1 end
  end
  if PLAYER_COMMAND_QUEUE_CURRENT ~= nil and tostring(PLAYER_COMMAND_QUEUE_CURRENT.key or "") == key then count = count + 1 end
  return count
end

function playerCommandPendingForCommand(key, commandName)
  local count = 0
  for _, item in ipairs(PLAYER_COMMAND_QUEUE or {}) do
    if tostring(item.key or "") == key and tostring(item.commandName or "") == tostring(commandName or "") then count = count + 1 end
  end
  if PLAYER_COMMAND_QUEUE_CURRENT ~= nil and tostring(PLAYER_COMMAND_QUEUE_CURRENT.key or "") == key and tostring(PLAYER_COMMAND_QUEUE_CURRENT.commandName or "") == tostring(commandName or "") then
    count = count + 1
  end
  return count
end

function playerCommandQueueStatusJson()
  local preview = {}
  local limit = math.min(#(PLAYER_COMMAND_QUEUE or {}), 20)
  for i = 1, limit do
    local item = PLAYER_COMMAND_QUEUE[i]
    table.insert(preview, '{"id":' .. tostring(item.id or 0) ..
      ',"command":' .. js(item.commandName or "") ..
      ',"target":' .. js((item.info and (item.info.name or item.info.steam)) or "") ..
      ',"queuedAt":' .. tostring(item.queuedAt or 0) .. '}')
  end
  local current = "null"
  if PLAYER_COMMAND_QUEUE_CURRENT ~= nil then
    local age = math.max(0, os.time() - (tonumber(PLAYER_COMMAND_QUEUE_CURRENT.startedAt or PLAYER_COMMAND_QUEUE_CURRENT.queuedAt) or os.time()))
    current = '{"id":' .. tostring(PLAYER_COMMAND_QUEUE_CURRENT.id or 0) ..
      ',"command":' .. js(PLAYER_COMMAND_QUEUE_CURRENT.commandName or "") ..
      ',"target":' .. js((PLAYER_COMMAND_QUEUE_CURRENT.info and (PLAYER_COMMAND_QUEUE_CURRENT.info.name or PLAYER_COMMAND_QUEUE_CURRENT.info.steam)) or "") ..
      ',"queuedAt":' .. tostring(PLAYER_COMMAND_QUEUE_CURRENT.queuedAt or 0) ..
      ',"startedAt":' .. tostring(PLAYER_COMMAND_QUEUE_CURRENT.startedAt or 0) ..
      ',"ageSeconds":' .. tostring(age) .. '}'
  end
  return '{"available":true' ..
    ',"depth":' .. tostring(#(PLAYER_COMMAND_QUEUE or {}) + (PLAYER_COMMAND_QUEUE_BUSY and 1 or 0)) ..
    ',"pending":' .. tostring(#(PLAYER_COMMAND_QUEUE or {})) ..
    ',"busy":' .. (PLAYER_COMMAND_QUEUE_BUSY and "true" or "false") ..
    ',"current":' .. current ..
    ',"max":' .. tostring(PLAYER_COMMAND_QUEUE_MAX or 0) ..
    ',"maxPerPlayer":' .. tostring(PLAYER_COMMAND_QUEUE_MAX_PER_PLAYER or 0) ..
    ',"timeoutSeconds":' .. tostring(PLAYER_COMMAND_QUEUE_TIMEOUT_SECONDS or 0) ..
    ',"sequence":' .. tostring(PLAYER_COMMAND_QUEUE_SEQ or 0) ..
    ',"pendingPreview":[' .. table.concat(preview, ",") .. ']}'
end

function enqueuePlayerCommand(info, message, sourcePath, quiet)
  info = enrichCommandPlayerIdentity(info)
  local key = playerCommandQueueKey(info)
  if key == "" then return false, "Не удалось определить игрока для команды.", 0 end
  if not playerReplyTargetReliable(info) then return false, "Не удалось определить игрока для команды.", 0 end
  message = tostring(message or ""):gsub("^[%c%s]+", "")
  local commandName = (splitWords(message)[1] or ""):lower()
  local allowedCommandKey = commandKey(commandName)
  if allowedCommandKey == "" or playerCommandLooksLikeAdminCommand(message) then
    if not quiet then
      appendActionEvent("player_command_queue", false, info, "Команда не поставлена в очередь: неизвестная или админская команда",
        '{"command":' .. js(commandName) .. ',"source":' .. js(sourcePath or "") .. '}')
    end
    return false, "Команда недоступна игрокам.", 0
  end
  if playerCommandRequiresResolvedSteam(commandName) and not playerCommandHasResolvedSteam(info) then
    if not quiet then
      appendActionEvent("player_command_queue", false, info, "Команда не поставлена в очередь: SteamID игрока ещё не определён",
        '{"command":' .. js(commandName) .. ',"source":' .. js(sourcePath or "") .. '}')
    end
    return false, "Сервер ещё определяет твоего игрока. Подожди 10 секунд и повтори команду.", 0
  end
  if #PLAYER_COMMAND_QUEUE >= PLAYER_COMMAND_QUEUE_MAX then
    if not quiet then appendActionEvent("player_command_queue", false, info, "Очередь команд игроков переполнена", '{"depth":' .. tostring(#PLAYER_COMMAND_QUEUE) .. '}') end
    return false, "Очередь команд сервера переполнена. Повтори чуть позже.", #PLAYER_COMMAND_QUEUE
  end
  local perPlayer = playerCommandPendingFor(key)
  if perPlayer >= PLAYER_COMMAND_QUEUE_MAX_PER_PLAYER then
    if not quiet then appendActionEvent("player_command_queue", false, info, "Очередь команд игрока переполнена", '{"perPlayer":' .. tostring(perPlayer) .. '}') end
    return false, "У тебя уже много команд в обработке. Дождись ответа сервера.", perPlayer
  end
  if playerCommandPendingForCommand(key, commandName) > 0 then
    if not quiet then
      appendActionEvent("player_command_queue", false, info, "Такая команда игрока уже обрабатывается",
        '{"command":' .. js(commandName) .. ',"depth":' .. tostring(#PLAYER_COMMAND_QUEUE) .. '}')
    end
    return false, "Эта команда уже обрабатывается. Дождись ответа сервера.", #PLAYER_COMMAND_QUEUE
  end
  PLAYER_COMMAND_QUEUE_SEQ = PLAYER_COMMAND_QUEUE_SEQ + 1
  table.insert(PLAYER_COMMAND_QUEUE, {
    id = PLAYER_COMMAND_QUEUE_SEQ,
    key = key,
    info = info,
    message = message,
    commandName = commandName,
    sourcePath = sourcePath,
    queuedAt = os.time()
  })
  if not quiet then
    appendActionEvent("player_command_queue", true, info, "Команда игрока поставлена в очередь",
      '{"id":' .. tostring(PLAYER_COMMAND_QUEUE_SEQ) .. ',"command":' .. js(commandName) .. ',"depth":' .. tostring(#PLAYER_COMMAND_QUEUE) .. '}')
    appendLog("player command queued id=" .. tostring(PLAYER_COMMAND_QUEUE_SEQ) .. " command=" .. tostring(commandName) .. " player=" .. tostring(info.name or info.steam or "") .. " depth=" .. tostring(#PLAYER_COMMAND_QUEUE))
  end
  return true, PLAYER_COMMAND_QUEUE_SEQ, #PLAYER_COMMAND_QUEUE
end

function drainPlayerCommandQueue()
  if PLAYER_COMMAND_QUEUE_BUSY then
    local current = PLAYER_COMMAND_QUEUE_CURRENT
    local timeoutSeconds = math.max(10, tonumber(PLAYER_COMMAND_QUEUE_TIMEOUT_SECONDS) or 25)
    local age = current ~= nil and (os.time() - (tonumber(current.startedAt or current.queuedAt) or os.time())) or 0
    if current ~= nil and age >= timeoutSeconds then
      current.cancelled = true
      appendLog("queued player command timeout id=" .. tostring(current.id) ..
        " command=" .. tostring(current.commandName or "") ..
        " ageSeconds=" .. tostring(age) ..
        " player=" .. tostring((current.info and (current.info.name or current.info.steam)) or ""))
      appendActionEvent("player_command", false, current.info, "Команда снята с очереди по таймауту",
        '{"id":' .. tostring(current.id or 0) ..
        ',"command":' .. js(current.commandName or "") ..
        ',"ageSeconds":' .. tostring(age) ..
        ',"timeoutSeconds":' .. tostring(timeoutSeconds) ..
        ',"handled":false,"queued":true,"timeout":true}')
      local timeoutInfo = current.info
      deferGame(0, function()
        targetMessageResolved(timeoutInfo, "Команда слишком долго обрабатывалась и снята с очереди. Повтори позже или выбери другое действие.")
      end)
      PLAYER_COMMAND_QUEUE_BUSY = false
      PLAYER_COMMAND_QUEUE_CURRENT = nil
    else
      return
    end
  end
  local item = table.remove(PLAYER_COMMAND_QUEUE, 1)
  if item == nil then return end
  PLAYER_COMMAND_QUEUE_BUSY = true
  PLAYER_COMMAND_QUEUE_CURRENT = item
  item.startedAt = os.time()
  local started = os.clock()
  local function finish(okRun, handledOrErr)
    if item.cancelled then
      appendLog("queued player command late finish ignored id=" .. tostring(item.id) .. " command=" .. tostring(item.commandName or ""))
      return
    end
    if PLAYER_COMMAND_QUEUE_CURRENT ~= item then
      appendLog("queued player command stale finish ignored id=" .. tostring(item.id) .. " command=" .. tostring(item.commandName or ""))
      return
    end
    local durationMs = math.floor((os.clock() - started) * 1000)
    PLAYER_COMMAND_QUEUE_BUSY = false
    PLAYER_COMMAND_QUEUE_CURRENT = nil
    if not okRun then
      appendLog("queued player command failed id=" .. tostring(item.id) .. " err=" .. tostring(handledOrErr))
      appendActionEvent("player_command", false, item.info, tostring(handledOrErr),
        '{"id":' .. tostring(item.id) .. ',"command":' .. js(item.commandName or "") .. ',"durationMs":' .. tostring(durationMs) .. ',"handled":false,"queued":true}')
      targetMessageResolved(item.info, "Команда завершилась с ошибкой. Администратор увидит детали в журнале.")
      return
    end
    appendLog("queued player command id=" .. tostring(item.id) ..
      " command=" .. tostring(item.commandName or "") ..
      " handled=" .. tostring(handledOrErr) ..
      " durationMs=" .. tostring(durationMs) ..
      " player=" .. tostring((item.info and (item.info.name or item.info.steam)) or ""))
    appendActionEvent("player_command", handledOrErr == true, item.info, "handled=" .. tostring(handledOrErr),
      '{"id":' .. tostring(item.id) .. ',"command":' .. js(item.commandName or "") .. ',"durationMs":' .. tostring(durationMs) .. ',"handled":' .. (handledOrErr and "true" or "false") .. ',"queued":true}')
  end
  local function runItem()
    appendLog("queued player command start id=" .. tostring(item.id) ..
      " command=" .. tostring(item.commandName or "") ..
      " player=" .. tostring((item.info and (item.info.name or item.info.steam)) or ""))
    local queuedInfo = item.info
    local live = queuedInfo
    if queuedInfo ~= nil and playerCommandRequiresLiveRefresh(item.commandName) then
      live = resolvePlayerInfo(queuedInfo.steam, queuedInfo.name, queuedInfo, queuedInfo.runtimeKey) or queuedInfo
    end
    if live == nil or not playerReplyTargetReliable(live) then
      finish(false, "Игрок вышел до обработки команды.")
      return
    end
    item.info = live
    local okRun, handledOrErr = pcall(function() return handlePlayerCommand(live, item.message) end)
    finish(okRun, handledOrErr)
  end
  if deferGame(0, runItem) then return end

  local executeInGameThread = schedulerFunction("ExecuteInGameThread")
  if executeInGameThread ~= nil then
    local okThread, err = pcall(function() executeInGameThread(runItem) end)
    if okThread then return end
    appendLog("player command ExecuteInGameThread failed, running inline: " .. tostring(err))
  end
  runItem()
end

chatHookStatus = {}
chatHookFailures = {}
CHAT_EVENT_DEDUP = CHAT_EVENT_DEDUP or {}
CHAT_STATE_DEDUP = CHAT_STATE_DEDUP or {}
CHAT_EVENT_WRITE_QUEUE = CHAT_EVENT_WRITE_QUEUE or {}
CHAT_EVENT_WRITE_QUEUE_MAX = CHAT_EVENT_WRITE_QUEUE_MAX or 2000

function enqueueStateWrite(path, recordJson, maxBytes)
  return appendJsonArray(path or "", recordJson or "{}", maxBytes)
end

function drainStateWriteQueue(limit)
  local max = math.max(1, tonumber(limit) or 20)
  local count = 0
  while count < max do
    local path = table.remove(STATE_WRITE_QUEUE, 1)
    if path == nil then return end
    STATE_WRITE_QUEUE_PENDING[path] = nil
    if not flushStateArrayCache(path) then queueStateFlushPath(path) end
    count = count + 1
  end
end

function normalizeChatChannelName(channel, message, path)
  local raw = cleanText(channel or ""):lower()
  local source = tostring(path or ""):lower()
  local text = cleanText(message or "")
  local first = text:sub(1, 1)
  if raw == "0" then return "local" end
  if raw == "1" then return "squad" end
  if raw == "2" then return "global" end
  if raw == "3" then return "admin" end
  if raw == "4" then return "command" end
  if raw:find("local", 1, true) or raw:find("proximity", 1, true) or raw:find("vicinity", 1, true) then return "local" end
  if raw:find("squad", 1, true) or raw:find("team", 1, true) or raw:find("clan", 1, true) or raw:find("party", 1, true) then return "squad" end
  if raw:find("admin", 1, true) or raw:find("moderator", 1, true) then return "admin" end
  if raw:find("command", 1, true) or source:find("processadmincommand", 1, true) or source:find("command-reply", 1, true) or first == "/" or first == "!" or first == "#" then return "command" end
  if raw:find("global", 1, true) or raw:find("world", 1, true) then return "global" end
  if raw == "" or raw == "chat" or raw == "server" then return "global" end
  return raw
end

function chatStateDedupeText(value)
  return cleanText(value or ""):gsub("%s+", " "):lower()
end

function shouldQueueChatStateEvent(message, name, steam, channel)
  local text = chatStateDedupeText(message)
  if text == "" then return false end
  local duplicateWindow = 15
  if type(configNumber) == "function" then
    duplicateWindow = math.max(1, math.min(300, configNumber("bridge-safety", { "ChatDuplicateWindowSeconds", "chatDuplicateWindowSeconds" }, duplicateWindow)))
  end
  local nowClock = os.clock()
  for key, seenAt in pairs(CHAT_STATE_DEDUP) do
    if (nowClock - (tonumber(seenAt) or 0)) > (duplicateWindow * 2) then CHAT_STATE_DEDUP[key] = nil end
  end
  local actor = chatStateDedupeText(steam)
  if actor == "" then actor = chatStateDedupeText(name) end
  local key = normalizeChatChannelName(channel, message, "") .. "|" .. actor .. "|" .. text
  local last = CHAT_STATE_DEDUP[key]
  if last ~= nil and (nowClock - last) < duplicateWindow then return false end
  CHAT_STATE_DEDUP[key] = nowClock
  return true
end

function enqueueChatEventWriteAt(message, name, steam, channel, path, timestampUtc)
  if not shouldQueueChatStateEvent(message, name, steam, channel) then return false end
  if #(CHAT_EVENT_WRITE_QUEUE or {}) >= CHAT_EVENT_WRITE_QUEUE_MAX then
    table.remove(CHAT_EVENT_WRITE_QUEUE, 1)
  end
  table.insert(CHAT_EVENT_WRITE_QUEUE, {
    message = message,
    name = name,
    steam = steam,
    channel = normalizeChatChannelName(channel, message, path),
    path = path,
    timestampUtc = cleanText(timestampUtc or nowUtc())
  })
  return true
end

function enqueueChatEventWrite(message, name, steam, channel, path)
  enqueueChatEventWriteAt(message, name, steam, channel, path, nowUtc())
end

function drainChatEventWriteQueue(limit)
  local max = math.max(1, tonumber(limit) or 40)
  local count = 0
  while count < max do
    local item = table.remove(CHAT_EVENT_WRITE_QUEUE, 1)
    if item == nil then return end
    enqueueStateWrite(CHAT_STATE_FILE,
      '{"type":"chat","timestampUtc":' .. js(item.timestampUtc or nowUtc()) ..
      ',"message":' .. js(item.message or "") ..
      ',"name":' .. js(item.name or "") ..
      ',"steamId":' .. js(item.steam or "") ..
      ',"channel":' .. js(item.channel or "") ..
      ',"source":' .. js(item.path or "ue4ss") .. '}',
      2 * 1024 * 1024)
    count = count + 1
  end
end

SCUM_CHAT_LOG_SEEN = SCUM_CHAT_LOG_SEEN or {}
SCUM_CHAT_LOG_LAST_FILE = SCUM_CHAT_LOG_LAST_FILE or ""
SCUM_CHAT_LOG_IMPORT_LOGGED = SCUM_CHAT_LOG_IMPORT_LOGGED or false
SCUM_CHAT_LOG_PRIMED = SCUM_CHAT_LOG_PRIMED or {}

function utf8FromCodepoint(cp)
  cp = tonumber(cp) or 0
  if cp <= 0 then return "" end
  if cp < 0x80 then return string.char(cp) end
  if cp < 0x800 then
    return string.char(0xC0 + math.floor(cp / 0x40), 0x80 + (cp % 0x40))
  end
  if cp < 0x10000 then
    return string.char(0xE0 + math.floor(cp / 0x1000), 0x80 + (math.floor(cp / 0x40) % 0x40), 0x80 + (cp % 0x40))
  end
  return string.char(0xF0 + math.floor(cp / 0x40000), 0x80 + (math.floor(cp / 0x1000) % 0x40), 0x80 + (math.floor(cp / 0x40) % 0x40), 0x80 + (cp % 0x40))
end

function decodeUtf16Le(text)
  local s = tostring(text or "")
  if s == "" then return "" end
  if not s:find("\0", 1, true) then return s end
  local out = {}
  local i = 1
  if s:byte(1) == 0xFF and s:byte(2) == 0xFE then i = 3 end
  while i < #s do
    local lo = s:byte(i) or 0
    local hi = s:byte(i + 1) or 0
    local cp = lo + hi * 256
    i = i + 2
    if cp >= 0xD800 and cp <= 0xDBFF and i < #s then
      local lo2 = s:byte(i) or 0
      local hi2 = s:byte(i + 1) or 0
      local cp2 = lo2 + hi2 * 256
      if cp2 >= 0xDC00 and cp2 <= 0xDFFF then
        cp = 0x10000 + ((cp - 0xD800) * 0x400) + (cp2 - 0xDC00)
        i = i + 2
      end
    end
    table.insert(out, utf8FromCodepoint(cp))
  end
  return table.concat(out)
end

SCUM_CHAT_LOG_LAST_LOOKUP_AT = SCUM_CHAT_LOG_LAST_LOOKUP_AT or 0

function latestScumChatLogPath()
  local nowClock = os.clock()
  local ttl = 30
  if type(configNumber) == "function" then
    ttl = math.max(5, configNumber("bridge-safety", { "ChatLogPathCacheSeconds", "chatLogPathCacheSeconds" }, ttl))
  end
  if SCUM_CHAT_LOG_LAST_FILE ~= "" and (nowClock - (SCUM_CHAT_LOG_LAST_LOOKUP_AT or 0)) < ttl then
    return SCUM_CHAT_LOG_LAST_FILE
  end
  SCUM_CHAT_LOG_LAST_LOOKUP_AT = nowClock
  local command = 'dir /b /o-d "' .. SCUM_SAVE_LOG_DIR .. '\\chat_*.log" 2>nul'
  local pipe = nil
  local okPipe = pcall(function() pipe = io.popen(command, "r") end)
  if not okPipe or pipe == nil then return SCUM_CHAT_LOG_LAST_FILE end
  local name = cleanText(pipe:read("*l") or "")
  pipe:close()
  if name == "" then return SCUM_CHAT_LOG_LAST_FILE end
  local path = SCUM_SAVE_LOG_DIR .. "\\" .. name
  SCUM_CHAT_LOG_LAST_FILE = path
  return path
end

function scumChatTimestampUtc(stamp)
  local y, mo, d, h, mi, se = tostring(stamp or ""):match("^(%d%d%d%d)%.(%d%d)%.(%d%d)%-(%d%d)%.(%d%d)%.(%d%d)$")
  if y == nil then return nowUtc() end
  return y .. "-" .. mo .. "-" .. d .. "T" .. h .. ":" .. mi .. ":" .. se .. "Z"
end

function parseScumChatLogLine(line)
  local value = cleanText(line)
  if value == "" or value:find("Game version", 1, true) ~= nil then return nil end
  local stamp, identity, body = value:match("^(%d%d%d%d%.%d%d%.%d%d%-%d%d%.%d%d%.%d%d):%s*'([^']+)'%s*'([^']*)'")
  if stamp == nil then return nil end
  local steam, name, profile = identity:match("^(%d+):(.-)%((%d+)%)$")
  if steam == nil then return nil end
  local channel, message = body:match("^([^:]+):%s*(.*)$")
  channel = cleanText(channel or "")
  message = cleanText(message or "")
  if message == "" then return nil end
  local commandMessage = chatCommandText(message)
  local first = message:gsub("^[%c%s]+", ""):sub(1, 1)
  if commandMessage ~= "" or first == "#" then return nil end
  local lower = channel:lower()
  if lower == "local" or lower == "squad" or lower == "global" or lower == "admin" then
    return {
      timestampUtc = scumChatTimestampUtc(stamp),
      steam = steam,
      name = cleanText(name or ""),
      profile = cleanText(profile or ""),
      channel = lower,
      message = message
    }
  end
  return nil
end

function importScumChatLog()
  local path = latestScumChatLogPath()
  if path == nil or path == "" then return end
  local maxBytes = 64 * 1024
  local primeAtEnd = true
  if type(configNumber) == "function" then
    maxBytes = math.max(8192, configNumber("bridge-safety", { "ChatLogReadMaxBytes", "chatLogReadMaxBytes" }, maxBytes))
  end
  if type(configBool) == "function" then
    primeAtEnd = configBool("bridge-safety", { "PrimeSaveFileLogImportsAtEnd", "primeSaveFileLogImportsAtEnd" }, true)
  end
  local firstRead = SCUM_CHAT_LOG_PRIMED[path] ~= true
  local raw = readNewBytes(path, maxBytes, firstRead and primeAtEnd)
  if firstRead then
    SCUM_CHAT_LOG_PRIMED[path] = true
    if raw == nil or raw == "" then
      appendLog("scum chat log import primed at end path=" .. tostring(path))
      return
    end
  end
  if raw == nil or raw == "" then return end
  local decoded = decodeUtf16Le(raw)
  local imported = 0
  for line in tostring(decoded):gmatch("[^\r\n]+") do
    local event = parseScumChatLogLine(line)
    if event ~= nil then
      local key = event.timestampUtc .. "|" .. event.steam .. "|" .. event.channel .. "|" .. event.message
      if not SCUM_CHAT_LOG_SEEN[key] then
        SCUM_CHAT_LOG_SEEN[key] = os.clock()
        enqueueChatEventWriteAt(event.message, event.name, event.steam, event.channel, "scum-chat-log", event.timestampUtc)
        imported = imported + 1
      end
    end
  end
  local nowClock = os.clock()
  for key, seenAt in pairs(SCUM_CHAT_LOG_SEEN) do
    if (nowClock - (tonumber(seenAt) or 0)) > 900 then SCUM_CHAT_LOG_SEEN[key] = nil end
  end
  if imported > 0 and not SCUM_CHAT_LOG_IMPORT_LOGGED then
    SCUM_CHAT_LOG_IMPORT_LOGGED = true
    appendLog("scum chat log import active path=" .. tostring(path) .. " imported=" .. tostring(imported))
  end
end

SCUM_KILL_LOG_SEEN = SCUM_KILL_LOG_SEEN or {}
SCUM_KILL_LOG_LAST_FILE = SCUM_KILL_LOG_LAST_FILE or ""
SCUM_KILL_LOG_IMPORT_LOGGED = SCUM_KILL_LOG_IMPORT_LOGGED or false

SCUM_KILL_LOG_LAST_LOOKUP_AT = SCUM_KILL_LOG_LAST_LOOKUP_AT or 0

function latestScumKillLogPath()
  local nowClock = os.clock()
  local ttl = 30
  if type(configNumber) == "function" then
    ttl = math.max(5, configNumber("bridge-safety", { "KillLogPathCacheSeconds", "killLogPathCacheSeconds" }, ttl))
  end
  if SCUM_KILL_LOG_LAST_FILE ~= "" and (nowClock - (SCUM_KILL_LOG_LAST_LOOKUP_AT or 0)) < ttl then
    return SCUM_KILL_LOG_LAST_FILE
  end
  SCUM_KILL_LOG_LAST_LOOKUP_AT = nowClock
  local command = 'dir /b /o-d "' .. SCUM_SAVE_LOG_DIR .. '\\kill_*.log" 2>nul'
  local pipe = nil
  local okPipe = pcall(function() pipe = io.popen(command, "r") end)
  if not okPipe or pipe == nil then return SCUM_KILL_LOG_LAST_FILE end
  local name = cleanText(pipe:read("*l") or "")
  pipe:close()
  if name == "" then return SCUM_KILL_LOG_LAST_FILE end
  local path = SCUM_SAVE_LOG_DIR .. "\\" .. name
  SCUM_KILL_LOG_LAST_FILE = path
  return path
end

function killLogNumber(value)
  local text = tostring(value or ""):gsub(",", "."):gsub("[^%-%d%.]", "")
  return tonumber(text)
end

function cleanKillWeapon(rawWeapon)
  local weapon = cleanText(rawWeapon or "")
  weapon = weapon:gsub("%s*S:?%s*%[[%s%S]*$", "")
  weapon = weapon:gsub("%s*C%s*$", "")
  weapon = weapon:gsub("%s*%[[^%]]+%]%s*", " ")
  weapon = cleanText(weapon)
  weapon = weapon:gsub("_C$", "")
  return weapon
end

function killDeathTypeLabel(cause, killerId, killerName)
  local raw = cleanText(cause or "")
  local lower = raw:lower()
  if lower == "projectile" then return "пуля/снаряд" end
  if lower == "melee" then return "ближний бой" end
  if lower == "explosion" then return "взрыв" end
  if lower == "vehicle" then return "транспорт" end
  if lower == "fall" then return "падение" end
  if lower == "suicide" then return "самоубийство" end
  if tostring(killerId or "") == "NPC" then return "NPC" end
  if tostring(killerName or ""):find("BP_", 1, true) ~= nil then return "NPC" end
  return raw ~= "" and raw or "неизвестно"
end

function jsonLogUnescape(value)
  local text = tostring(value or "")
  text = text:gsub('\\"', '"')
  text = text:gsub("\\/", "/")
  text = text:gsub("\\\\", "\\")
  text = text:gsub("\\r", " ")
  text = text:gsub("\\n", " ")
  text = text:gsub("\\t", " ")
  return cleanText(text)
end

function jsonLogObject(block, key)
  return tostring(block or ""):match('"' .. tostring(key or "") .. '"%s*:%s*(%b{})')
end

function jsonLogScalar(block, key)
  local quoted = tostring(block or ""):match('"' .. tostring(key or "") .. '"%s*:%s*"([^"]*)"')
  if quoted ~= nil then return jsonLogUnescape(quoted) end
  local bare = tostring(block or ""):match('"' .. tostring(key or "") .. '"%s*:%s*([^,%}%]]+)')
  if bare ~= nil then return cleanText(bare:gsub('^"', ''):gsub('"$', '')) end
  return ""
end

function parseScumKillLogJsonLine(value)
  local stamp, json = tostring(value or ""):match("^(%d%d%d%d%.%d%d%.%d%d%-%d%d%.%d%d%.%d%d):%s*(%b{})")
  if stamp == nil or json == nil or json:find('"Killer"', 1, true) == nil or json:find('"Victim"', 1, true) == nil then return nil end

  local killerBlock = jsonLogObject(json, "Killer")
  local victimBlock = jsonLogObject(json, "Victim")
  if killerBlock == nil or victimBlock == nil then return nil end

  local killerLoc = jsonLogObject(killerBlock, "ServerLocation") or ""
  local victimLoc = jsonLogObject(victimBlock, "ServerLocation") or ""
  local killerName = jsonLogScalar(killerBlock, "ProfileName")
  local victimName = jsonLogScalar(victimBlock, "ProfileName")
  local killerId = jsonLogScalar(killerBlock, "UserId")
  local victimId = jsonLogScalar(victimBlock, "UserId")
  local weaponRaw = jsonLogScalar(json, "Weapon")
  local cause = tostring(weaponRaw or ""):match("%[([^%]]+)%]") or ""
  local weapon = cleanKillWeapon(weaponRaw)

  local killerX = killLogNumber(jsonLogScalar(killerLoc, "X"))
  local killerY = killLogNumber(jsonLogScalar(killerLoc, "Y"))
  local killerZ = killLogNumber(jsonLogScalar(killerLoc, "Z"))
  local victimX = killLogNumber(jsonLogScalar(victimLoc, "X"))
  local victimY = killLogNumber(jsonLogScalar(victimLoc, "Y"))
  local victimZ = killLogNumber(jsonLogScalar(victimLoc, "Z"))
  local distanceNumber = 0
  if killerX ~= nil and killerY ~= nil and victimX ~= nil and victimY ~= nil then
    local dx = killerX - victimX
    local dy = killerY - victimY
    distanceNumber = math.sqrt(dx * dx + dy * dy) / 100
  end

  if victimName == "" then return nil end
  local killerSteam = looksLikeSteamId(killerId) and killerId or ""
  local victimSteam = looksLikeSteamId(victimId) and victimId or ""
  local isSelf = victimSteam ~= "" and killerSteam ~= "" and victimSteam == killerSteam
  local isPve = killerSteam == "" or tostring(killerId or "") == "NPC"
  local message = ""
  if isSelf then
    message = victimName .. " погиб"
  elseif isPve then
    message = victimName .. " погиб от " .. (killerName ~= "" and killerName or "NPC")
  else
    message = (killerName ~= "" and killerName or "Unknown") .. " убил " .. victimName
  end
  if weapon ~= "" and serverKillFeedShowWeapon() then message = message .. " (" .. weapon .. ")" end
  if distanceNumber ~= nil and distanceNumber > 0 and serverKillFeedShowDistance() then
    message = message .. " с " .. tostring(math.floor(distanceNumber + 0.5)) .. " м"
  end

  return {
    timestampUtc = scumChatTimestampUtc(stamp),
    message = message,
    killerName = killerName,
    killerSteamId = killerSteam,
    killerUserId = killerId,
    victimName = victimName,
    victimSteamId = victimSteam,
    weapon = weapon,
    weaponRaw = cleanText(weaponRaw),
    cause = cleanText(cause),
    deathType = killDeathTypeLabel(cause, killerId, killerName),
    distance = distanceNumber,
    killerX = killerX,
    killerY = killerY,
    killerZ = killerZ,
    victimX = victimX,
    victimY = victimY,
    victimZ = victimZ,
    raw = value,
    isPve = isPve,
    isSelf = isSelf
  }
end

function parseScumKillLogLine(line)
  local value = cleanText(line)
  if value == "" or value:find("Game version", 1, true) ~= nil then return nil end
  if value:find('{"Killer"', 1, true) ~= nil then
    local parsedJson = parseScumKillLogJsonLine(value)
    if parsedJson ~= nil then return parsedJson end
  end
  if value:find("Died:", 1, true) == nil or value:find("Killer:", 1, true) == nil then return nil end

  local stamp, victimName, victimId, killerName, killerId, weaponRaw, tail =
    value:match("^(%d%d%d%d%.%d%d%.%d%d%-%d%d%.%d%d%.%d%d):%s*Died:%s*(.-)%s*%(([^%)]+)%),%s*Killer:%s*(.-)%s*%(([^%)]+)%)%s*Weapon:%s*(.-)%s*S:%[(.+)%]$")
  if stamp == nil then
    stamp, victimName, victimId, killerName, killerId, weaponRaw, tail =
      value:match("^(%d%d%d%d%.%d%d%.%d%d%-%d%d%.%d%d%.%d%d):%s*Died:%s*(.-)%s*%(([^%)]+)%),%s*Killer:%s*(.-)%s*%(([^%)]+)%)%s*Weapon:%s*(.-)%s*S%[(.+)%]$")
  end
  if stamp == nil then return nil end

  local killerX, killerY, killerZ = tail:match("KillerLoc%s*:%s*([%-%.%d]+)%s*,%s*([%-%.%d]+)%s*,%s*([%-%.%d]+)")
  if killerX == nil then
    killerX, killerY, killerZ = tail:match("KillerLocation%s*:%s*([%-%.%d]+)%s*,%s*([%-%.%d]+)%s*,%s*([%-%.%d]+)")
  end
  local victimX, victimY, victimZ = tail:match("VictimLoc%s*:%s*([%-%.%d]+)%s*,%s*([%-%.%d]+)%s*,%s*([%-%.%d]+)")
  if victimX == nil then
    victimX, victimY, victimZ = tail:match("VictimLocation%s*:%s*([%-%.%d]+)%s*,%s*([%-%.%d]+)%s*,%s*([%-%.%d]+)")
  end
  local distance = tail:match("Distance%s*:%s*([%-%.%d]+)")

  local cause = tostring(weaponRaw or ""):match("%[([^%]]+)%]") or ""
  local weapon = cleanKillWeapon(weaponRaw)
  victimName = cleanText(victimName)
  killerName = cleanText(killerName)
  victimId = cleanText(victimId)
  killerId = cleanText(killerId)

  if victimName == "" then return nil end
  local killerSteam = looksLikeSteamId(killerId) and killerId or ""
  local victimSteam = looksLikeSteamId(victimId) and victimId or ""
  local isSelf = victimSteam ~= "" and killerSteam ~= "" and victimSteam == killerSteam
  local isPve = killerSteam == "" or tostring(killerId or "") == "NPC"
  local message = ""
  if isSelf then
    message = victimName .. " погиб"
  elseif isPve then
    message = victimName .. " погиб от " .. (killerName ~= "" and killerName or "NPC")
  else
    message = (killerName ~= "" and killerName or "Unknown") .. " убил " .. victimName
  end
  if weapon ~= "" and serverKillFeedShowWeapon() then message = message .. " (" .. weapon .. ")" end
  local distanceNumber = displayKillDistanceMeters(killLogNumber(distance) or 0, weapon, cause)
  if distanceNumber ~= nil and distanceNumber > 0 and serverKillFeedShowDistance() then
    message = message .. " с " .. tostring(math.floor(distanceNumber + 0.5)) .. " м"
  end

  return {
    timestampUtc = scumChatTimestampUtc(stamp),
    message = message,
    killerName = killerName,
    killerSteamId = killerSteam,
    killerUserId = killerId,
    victimName = victimName,
    victimSteamId = victimSteam,
    weapon = weapon,
    weaponRaw = cleanText(weaponRaw),
    cause = cleanText(cause),
    deathType = killDeathTypeLabel(cause, killerId, killerName),
    distance = distanceNumber,
    killerX = killLogNumber(killerX),
    killerY = killLogNumber(killerY),
    killerZ = killLogNumber(killerZ),
    victimX = killLogNumber(victimX),
    victimY = killLogNumber(victimY),
    victimZ = killLogNumber(victimZ),
    raw = value,
    isPve = isPve,
    isSelf = isSelf
  }
end

function appendSavefileKillEvent(event, path)
  if event == nil then return false end
  local distance = tonumber(event.distance or 0) or 0
  local broadcastMessage = serverKillFeedPrefix() .. " " .. tostring(event.message or "")
  local record = '{"type":"kill","timestampUtc":' .. js(event.timestampUtc or nowUtc()) ..
    ',"message":' .. js(event.message or "") ..
    ',"broadcastMessage":' .. js(broadcastMessage) ..
    ',"killerName":' .. js(event.killerName or "") ..
    ',"killerSteamId":' .. js(event.killerSteamId or "") ..
    ',"killerUserId":' .. js(event.killerUserId or "") ..
    ',"victimName":' .. js(event.victimName or "") ..
    ',"victimSteamId":' .. js(event.victimSteamId or "") ..
    ',"weapon":' .. js(event.weapon or "") ..
    ',"weaponRaw":' .. js(event.weaponRaw or "") ..
    ',"cause":' .. js(event.cause or "") ..
    ',"deathType":' .. js(event.deathType or "") ..
    ',"distance":' .. tostring(distance) ..
    ',"distanceMeters":' .. tostring(distance) ..
    ',"killerLocation":' .. killLocationJson(event.killerX, event.killerY, event.killerZ) ..
    ',"victimLocation":' .. killLocationJson(event.victimX, event.victimY, event.victimZ) ..
    ',"source":"savefile-kill-log"' ..
    ',"logFile":' .. js(tostring(path or ""):match("([^\\]+)$") or tostring(path or "")) ..
    ',"raw":' .. js(event.raw or "") .. '}'
  appendJsonArray(STATE_DIR .. "\\kill-feed.json", record, 2 * 1024 * 1024)
  appendJsonArray(STATE_DIR .. "\\server-kill-feed.json", record, 2 * 1024 * 1024)
  return true
end

function updateStatsFromSavefileKill(event)
  if event == nil then return false, "empty" end
  local statBody = ""
  if event.isSelf or event.isPve or tostring(event.killerSteamId or "") == "" then
    statBody = tostring(event.victimName or "") .. " погиб"
  else
    statBody = tostring(event.killerName or "") .. " убил " .. tostring(event.victimName or "")
  end
  if shouldSkipServerKillFeedStats(statBody) then return false, "duplicate" end

  local victimInfo = resolveKillFeedIdentityByName(event.victimName or "")
  if event.isSelf or event.isPve or tostring(event.killerSteamId or "") == "" then
    if victimInfo == nil then return false, "victim-not-found" end
    return handleDeathEvent(victimInfo, {
      source = "savefile-kill-log",
      skipKillFeed = true,
      victimX = event.victimX,
      victimY = event.victimY,
      victimZ = event.victimZ,
      weapon = event.weapon,
      cause = event.cause,
      distance = event.distance
    }), "death"
  end
  local killerInfo = resolveKillFeedIdentityByName(event.killerName or "")
  if killerInfo == nil or victimInfo == nil then return false, "identity-not-found" end
  return handleKillEvent(killerInfo, victimInfo, {
    source = "savefile-kill-log",
    skipKillFeed = true,
    killerX = event.killerX,
    killerY = event.killerY,
    killerZ = event.killerZ,
    victimX = event.victimX,
    victimY = event.victimY,
    victimZ = event.victimZ,
    weapon = event.weapon,
    cause = event.cause,
    distance = event.distance
  }), "kill"
end

SCUM_KILL_LOG_PRIMED = SCUM_KILL_LOG_PRIMED or {}

function importScumKillLog()
  if configBool("server-kill-feed", { "ImportSaveFileKillLog", "importSaveFileKillLog" }, true) == false then return end
  local path = latestScumKillLogPath()
  if path == nil or path == "" then return end
  local maxBytes = 64 * 1024
  local primeAtEnd = true
  if type(configNumber) == "function" then
    maxBytes = math.max(8192, configNumber("bridge-safety", { "KillLogReadMaxBytes", "killLogReadMaxBytes" }, maxBytes))
  end
  if type(configBool) == "function" then
    primeAtEnd = configBool("bridge-safety", { "PrimeSaveFileLogImportsAtEnd", "primeSaveFileLogImportsAtEnd" }, true)
  end
  local firstRead = SCUM_KILL_LOG_PRIMED[path] ~= true
  local raw = readNewBytes(path, maxBytes, firstRead and primeAtEnd)
  if firstRead then
    SCUM_KILL_LOG_PRIMED[path] = true
    if raw == nil or raw == "" then
      appendLog("scum kill log import primed at end path=" .. tostring(path))
      return
    end
  end
  if raw == nil or raw == "" then return end
  local decoded = decodeUtf16Le(raw)
  local imported = 0
  for line in tostring(decoded):gmatch("[^\r\n]+") do
    local event = parseScumKillLogLine(line)
    if event ~= nil then
      local key = tostring(event.timestampUtc or "") .. "|" .. tostring(event.victimSteamId or event.victimName or "") ..
        "|" .. tostring(event.killerSteamId or event.killerUserId or event.killerName or "") .. "|" ..
        tostring(event.weapon or "") .. "|" .. tostring(event.distance or "")
      if key ~= "" and not SCUM_KILL_LOG_SEEN[key] then
        SCUM_KILL_LOG_SEEN[key] = os.clock()
        appendSavefileKillEvent(event, path)
        updateStatsFromSavefileKill(event)
        imported = imported + 1
      end
    end
  end
  local nowClock = os.clock()
  for key, seenAt in pairs(SCUM_KILL_LOG_SEEN) do
    if (nowClock - (tonumber(seenAt) or 0)) > 3600 then SCUM_KILL_LOG_SEEN[key] = nil end
  end
  if imported > 0 and not SCUM_KILL_LOG_IMPORT_LOGGED then
    SCUM_KILL_LOG_IMPORT_LOGGED = true
    appendLog("scum kill log import active path=" .. tostring(path) .. " imported=" .. tostring(imported))
  end
end

function chatIdentityKey(info, context)
  if info ~= nil then
    if tostring(info.steam or "") ~= "" then return "steam:" .. tostring(info.steam) end
    if tostring(info.userProfileId or info.serverUserProfileId or "") ~= "" then return "profile:" .. tostring(info.userProfileId or info.serverUserProfileId) end
    if tostring(info.name or "") ~= "" then return "name:" .. tostring(info.name):lower() end
    if tostring(info.runtimeKey or "") ~= "" then return "runtime:" .. tostring(info.runtimeKey) end
  end
  local key = objectKey(context)
  if key ~= "" then return "context:" .. key end
  return "unknown"
end

function playerInfoHasIdentity(info)
  if info == nil then return false end
  if looksLikeSteamId(tostring(info.steam or info.steamId or "")) then return true end
  local profile = cleanText(info.userProfileId or info.serverUserProfileId or info.profileId or "")
  if profile ~= "" and profile ~= "0" then return true end
  local runtimeKey = cleanText(info.runtimeKey or info.rpcKey or info.pcKey or info.psKey or info.pawnKey or "")
  if runtimeKey ~= "" then return true end
  local name = cleanText(info.name or "")
  if name ~= "" and name:lower() ~= "unknown" then return true end
  return false
end

function mergeRuntimeIntoIdentity(identity, runtimeInfo)
  if identity == nil then return runtimeInfo end
  if runtimeInfo == nil then return identity end
  local keys = {
    "steam", "name", "userProfileId", "serverUserProfileId",
    "pc", "ps", "pawn", "rpc",
    "pcKey", "psKey", "pawnKey", "rpcKey", "runtimeKey",
    "x", "y", "z", "ping", "score"
  }
  for _, key in ipairs(keys) do
    local current = identity[key]
    local incoming = runtimeInfo[key]
    local currentText = tostring(current or "")
    local incomingText = tostring(incoming or "")
    if incoming ~= nil and incomingText ~= "" and (current == nil or currentText == "" or currentText == "Unknown") then
      identity[key] = incoming
    end
  end
  local source = tostring(identity.source or "")
  local runtimeSource = tostring(runtimeInfo.source or "")
  if runtimeSource ~= "" and source:find(runtimeSource, 1, true) == nil then
    identity.source = (source ~= "" and (source .. "+") or "") .. runtimeSource
  end
  return identity
end

function attachChatRuntime(info, context, runtimeInfo)
  info = mergeRuntimeIntoIdentity(info, runtimeInfo)
  if info == nil then return nil end
  local contextObj = unwrapHookParam(context)
  if contextObj ~= nil and isValidObject(contextObj) then
    local className = objectClassFullName(contextObj) .. " " .. objectFullName(contextObj)
    if className:find("PlayerRpcChannel", 1, true) ~= nil or className:find("RpcChannel", 1, true) ~= nil then
      info.rpc = contextObj
      info.rpcKey = objectKey(contextObj)
      if tostring(info.runtimeKey or "") == "" then info.runtimeKey = info.rpcKey end
      local source = tostring(info.source or "")
      if source:find("chat-rpc", 1, true) == nil then
        info.source = (source ~= "" and (source .. "+") or "") .. "chat-rpc"
      end
    end
  end
  return info
end

function shouldAcceptChatEvent(info, context, message)
  local now = os.clock()
  for key, seenAt in pairs(CHAT_EVENT_DEDUP) do
    if (now - seenAt) > 4 then CHAT_EVENT_DEDUP[key] = nil end
  end
  local key = chatIdentityKey(info, context) .. "|" .. cleanText(message)
  local last = CHAT_EVENT_DEDUP[key]
  if last ~= nil and (now - last) < 1.25 then return false end
  CHAT_EVENT_DEDUP[key] = now
  return true
end

function commandTextFromHook(path, message)
  local commandMessage = chatCommandText(message)
  if commandMessage ~= "" then return commandMessage end
  if tostring(path or ""):find("ProcessAdminCommand", 1, true) == nil then return "" end
  local value = cleanText(message)
  if value == "" or value:sub(1, 1) == "#" then return "" end
  local synthetic = "/" .. value
  if commandKey((splitWords(synthetic)[1] or ""):lower()) ~= "" then return synthetic end
  return ""
end

function commandHookFallbackPlayer()
  local infos = PLAYER_INFO_CACHE or {}
  if #infos == 1 then return infos[1] end

  local snapshot = serverLogOnlineSnapshot()
  local presence = serverLogPresenceSnapshot()
  if presence == nil or tonumber(presence.activeCount or 0) ~= 1 then return nil end
  if snapshot ~= nil and tonumber(snapshot.playerCount or -1) > 1 then return nil end

  for key in pairs(presence.active or {}) do
    local steam = tostring(key or ""):match("^steam:(%d+)$") or ""
    if steam ~= "" then
      local identity = presence.knownBySteam[steam] or {}
      return {
        steam = steam,
        name = cleanText(identity.name or ""),
        userProfileId = cleanText(identity.profileId or ""),
        serverUserProfileId = cleanText(identity.profileId or ""),
        online = true,
        status = "online",
        source = "server-log"
      }
    end
    local profile = tostring(key or ""):match("^profile:(%d+)$") or ""
    if profile ~= "" then
      local identity = presence.knownByProfile[profile] or {}
      return {
        steam = cleanText(identity.steam or ""),
        name = cleanText(identity.name or ""),
        userProfileId = profile,
        serverUserProfileId = profile,
        online = true,
        status = "online",
        source = "server-log"
      }
    end
    local name = tostring(key or ""):match("^name:(.+)$") or ""
    if name ~= "" then
      local identity = presence.knownByName[name] or {}
      return {
        steam = cleanText(identity.steam or ""),
        name = cleanText(identity.name or name),
        userProfileId = cleanText(identity.profileId or ""),
        serverUserProfileId = cleanText(identity.profileId or ""),
        online = true,
        status = "online",
        source = "server-log"
      }
    end
  end
  return nil
end

function chatSenderNameFromText(text)
  local value = cleanText(text)
  if value == "" then return "" end
  value = value:gsub("^%[[^%]]+%]%s*", "")
  local sender = value:match("^([^:]{1,96}):%s*[/!]")
  if sender == nil then sender = value:match("^([^:]{1,96}):%s*#") end
  sender = cleanText(sender or "")
  if sender:lower() == "global" or sender:lower() == "local" or sender:lower() == "squad" then return "" end
  return sender
end

function findCachedPlayerByExactName(name)
  local wanted = cleanText(name):lower()
  if wanted == "" then return nil end
  local cacheTtl = math.max(10, configNumber("bridge-safety", { "PlayerInfoCacheTtlSeconds", "playerInfoCacheTtlSeconds" }, 90))
  for _, info in ipairs(cachedPlayerInfos(cacheTtl) or {}) do
    local candidateName = cleanText(info.name or ""):lower()
    if candidateName ~= "" and candidateName == wanted then return enrichPlayerInfoFromServerLog(info) or info end
  end
  return nil
end

function resolveCommandPlayerFromChatText(message)
  local sender = chatSenderNameFromText(message)
  if sender == "" then return nil end
  local cached = findCachedPlayerByExactName(sender)
  if cached ~= nil then return cached end
  return resolvePlayerInfoFromServerLogTarget("", sender)
end

function resolveCommandHookPlayer(context, args, message, commandName)
  local runtimeInfo = enrichCommandPlayerIdentity(findPlayerByChatContextCached(context, args, message))
  if playerCommandIdentityReady(runtimeInfo, commandName) then return attachChatRuntime(runtimeInfo, context, nil) end

  local textInfo = enrichCommandPlayerIdentity(resolveCommandPlayerFromChatText(message))
  if playerCommandIdentityReady(textInfo, commandName) then return attachChatRuntime(textInfo, context, runtimeInfo) end
  runtimeInfo = enrichCommandPlayerIdentity(mergeRuntimeIntoIdentity(textInfo, runtimeInfo))

  local needsRuntimeRefresh = runtimeInfo == nil or not playerCommandIdentityReady(runtimeInfo, commandName)
  if needsRuntimeRefresh or (playerCommandRequiresResolvedSteam(commandName) and configBool("bridge-safety", { "AllowCommandRuntimeScan", "allowCommandRuntimeScan" }, false)) then
    refreshPlayerInfoCacheForCommand(commandName)
    local refreshedInfo = enrichCommandPlayerIdentity(findPlayerByChatContextCached(context, args, message))
    if playerCommandIdentityReady(refreshedInfo, commandName) then return attachChatRuntime(refreshedInfo, context, runtimeInfo) end
    local rescannedInfo = enrichCommandPlayerIdentity(findPlayerByChatContext(context, args, message))
    if playerCommandIdentityReady(rescannedInfo, commandName) then return attachChatRuntime(rescannedInfo, context, runtimeInfo) end
    runtimeInfo = enrichCommandPlayerIdentity(mergeRuntimeIntoIdentity(rescannedInfo, runtimeInfo))
  end

  local fallbackInfo = enrichCommandPlayerIdentity(commandHookFallbackPlayer())
  if playerCommandIdentityReady(fallbackInfo, commandName) then return attachChatRuntime(fallbackInfo, context, runtimeInfo) end

  return attachChatRuntime(enrichCommandPlayerIdentity(runtimeInfo), context, nil)
end

function registerCommandOnlyChatHook(path)
  if chatHookStatus[path] == true then return end
  if chatHookStatus[path] == false then return end
  local okHook, err = pcall(function()
    RegisterHook(path, function(context, ...)
      local hookArgs = {...}
      return guardedHookCallback("command-chat", path, function()
      local args = hookArgs
      local commandMessage = ""
      local rawMessage = ""
      for i, arg in ipairs(args) do
        if i > 8 then break end
        local text = paramText(arg)
        local candidate = chatCommandText(text)
        if candidate ~= "" then
          commandMessage = candidate
          rawMessage = text
          break
        end
      end
      if commandMessage == "" then return end

      local commandName = (splitWords(commandMessage)[1] or ""):lower()
      if commandKey(commandName) == "" then return end

      local info = resolveCommandHookPlayer(context, args, rawMessage, commandName)
      if info == nil then
        local contextKey = objectKey(context)
        local contextName = objectFullName(context)
        local argsJson = chatArgSummary(args, 8)
        local playersJson = chatPlayersSummaryJson()
        appendActionEvent("player_command", false, {}, "sender unresolved",
          '{"command":' .. js(commandName) ..
          ',"path":' .. js(path) ..
          ',"contextKey":' .. js(contextKey) ..
          ',"context":' .. js(contextName) ..
          ',"message":' .. js(commandMessage) ..
          ',"args":' .. tostring(argsJson) ..
          ',"players":' .. tostring(playersJson) ..
          ',"source":"command-only-chat-hook"}')
        return
      end
      if not shouldAcceptChatEvent(info, nil, commandMessage) then return end

      enqueueChatEventWrite(commandMessage, info.name or "", info.steam or "", "command", path)
      local queued, queueResult, depth = enqueuePlayerCommand(info, commandMessage, path, false)
      if not queued then
        appendActionEvent("player_command_queue", false, info, tostring(queueResult or "Команда не поставлена в очередь."),
          '{"command":' .. js(commandName) .. ',"depth":' .. tostring(depth or 0) .. ',"source":"command-only-chat-hook"}')
        targetMessagePlayerCommandFailure(info, commandName, tostring(queueResult or "Команда не поставлена в очередь."))
      end
      end)
    end)
  end)
  if okHook then
    chatHookStatus[path] = true
    appendLog("command-only chat hook " .. tostring(path) .. "=ok")
    return
  end
  chatHookFailures[path] = (chatHookFailures[path] or 0) + 1
  if chatHookFailures[path] >= 90 then
    chatHookStatus[path] = false
    appendLog("command-only chat hook " .. tostring(path) .. "=unavailable after " .. tostring(chatHookFailures[path]) .. " retries")
    return
  end
  if chatHookFailures[path] == 1 or (chatHookFailures[path] % 30) == 0 then
    appendLog("command-only chat hook " .. tostring(path) .. "=pending retry " .. tostring(chatHookFailures[path]) .. " (" .. tostring(err) .. ")")
  end
end

function registerChatHook(path)
  if tostring(path or ""):find("BroadcastChatMessage", 1, true) ~= nil then
    registerCommandOnlyChatHook(path)
    return
  end
  if chatHookStatus[path] == true then return end
  if chatHookStatus[path] == false then return end
  local okHook, err = pcall(function()
    RegisterHook(path, function(context, ...)
      local hookArgs = {...}
      return guardedHookCallback("chat", path, function()
      local args = hookArgs
      local message = ""
      local channel = ""
      local texts = {}
      for i, arg in ipairs(args) do
        local text = paramText(arg)
        if text ~= "" then table.insert(texts, text) end
      end
      for _, text in ipairs(texts) do
        if chatCommandText(text) ~= "" or text:sub(1, 1) == "#" then
          message = text
          break
        end
      end
      if message == "" then
        for _, text in ipairs(texts) do
          local lower = cleanText(text):lower()
          local channelToken = lower:match("^[0-4]$") ~= nil or
            lower == "local" or lower == "proximity" or lower == "vicinity" or
            lower == "squad" or lower == "team" or lower == "clan" or lower == "party" or
            lower == "global" or lower == "world" or lower == "admin" or lower == "server"
          if not channelToken then
            message = text
            break
          end
        end
      end
      if message == "" and #texts > 0 then message = texts[#texts] end
      for _, text in ipairs(texts) do
        if text ~= message and channel == "" then channel = text end
      end
      if message == "" then return end
      if message:sub(1, 1) == "#" then return end
      local commandMessage = commandTextFromHook(path, message)
      local isCommand = commandMessage ~= ""
      if tostring(path or ""):find("ProcessAdminCommand", 1, true) ~= nil and not isCommand then return end
      local info = findPlayerByChatContextCached(context, args, message)
      if isCommand then
        local commandName = (splitWords(commandMessage)[1] or ""):lower()
        info = resolveCommandHookPlayer(context, args, message, commandName)
      end
      if not shouldAcceptChatEvent(info, context, message) then return end
      local name = info and info.name or ""
      local steam = info and info.steam or ""
      enqueueChatEventWrite(message, name, steam, channel, path)
      if isCommand and info == nil then
        local commandName = (splitWords(commandMessage)[1] or ""):lower()
        chatUnresolvedCommandLogCount = (chatUnresolvedCommandLogCount or 0) + 1
        local contextKey = objectKey(context)
        local contextName = objectFullName(context)
        local argsJson = chatArgSummary(args, 6)
        local playersJson = chatPlayersSummaryJson()
        local allowDeferredResolve = configBool("bridge-safety", { "AllowDeferredChatSenderResolve", "allowDeferredChatSenderResolve" }, true)
        if allowDeferredResolve then
          local messageSnapshot = message
          local commandSnapshot = commandMessage
          deferGame(1, function()
            local resolved = enrichCommandPlayerIdentity(resolveCommandPlayerFromChatText(messageSnapshot))
            if not playerCommandIdentityReady(resolved, commandName) then
              refreshPlayerInfoCacheForCommand(commandName)
              resolved = enrichCommandPlayerIdentity(resolveCommandPlayerFromChatText(messageSnapshot))
            end
            if resolved ~= nil then
              local queued, queueResult, depth = enqueuePlayerCommand(resolved, commandSnapshot, path, false)
              if not queued then
                appendActionEvent("player_command_queue", false, resolved, tostring(queueResult or "Команда не поставлена в очередь."),
                  '{"command":' .. js(commandName) .. ',"depth":' .. tostring(depth or 0) .. ',"source":"chat-hook-deferred-resolve"}')
                targetMessagePlayerCommandFailure(resolved, commandName, tostring(queueResult or "Команда не поставлена в очередь."))
              end
              return
            end
            if chatUnresolvedCommandLogCount <= 20 or (chatUnresolvedCommandLogCount % 25) == 0 then
              appendLog("chat command sender unresolved path=" .. tostring(path) ..
                " command=" .. tostring(commandName) ..
                " contextKey=" .. tostring(contextKey) ..
                " context=" .. tostring(contextName) ..
                " args=" .. tostring(argsJson))
            end
            appendActionEvent("player_command", false, {}, "sender unresolved",
              '{"command":' .. js(commandName) ..
              ',"path":' .. js(path) ..
              ',"contextKey":' .. js(contextKey) ..
              ',"message":' .. js(message) ..
              ',"args":' .. tostring(argsJson) ..
              ',"players":' .. tostring(playersJson) ..
              ',"deferred":true}')
          end)
          return
        end
        if chatUnresolvedCommandLogCount <= 20 or (chatUnresolvedCommandLogCount % 25) == 0 then
          appendLog("chat command sender unresolved path=" .. tostring(path) ..
            " command=" .. tostring(commandName) ..
            " contextKey=" .. tostring(contextKey) ..
            " context=" .. tostring(contextName) ..
            " args=" .. tostring(argsJson) ..
            " deferred=disabled")
        end
        appendActionEvent("player_command", false, {}, "sender unresolved",
          '{"command":' .. js(commandName) ..
          ',"path":' .. js(path) ..
          ',"contextKey":' .. js(contextKey) ..
          ',"message":' .. js(message) ..
          ',"args":' .. tostring(argsJson) ..
          ',"players":' .. tostring(playersJson) ..
          ',"deferred":false}')
        return
      end
      if info ~= nil and isCommand then
        local commandName = (splitWords(commandMessage)[1] or ""):lower()
        local queued, queueResult, depth = enqueuePlayerCommand(info, commandMessage, path, true)
        if not queued then
          deferGame(1, function()
            appendActionEvent("player_command_queue", false, info, tostring(queueResult or "Команда не поставлена в очередь."),
              '{"command":' .. js(commandName) .. ',"depth":' .. tostring(depth or 0) .. ',"source":"chat-hook"}')
            targetMessagePlayerCommandFailure(info, commandName, tostring(queueResult or "Команда не поставлена в очередь."))
          end)
        end
      end
      end)
    end)
  end)
  if okHook then
    chatHookStatus[path] = true
    appendLog("chat hook " .. tostring(path) .. "=ok")
    return
  end
  chatHookFailures[path] = (chatHookFailures[path] or 0) + 1
  if chatHookFailures[path] >= 90 then
    chatHookStatus[path] = false
    appendLog("chat hook " .. tostring(path) .. "=unavailable after " .. tostring(chatHookFailures[path]) .. " retries")
    return
  end
  if chatHookFailures[path] == 1 or (chatHookFailures[path] % 30) == 0 then
    appendLog("chat hook " .. tostring(path) .. "=pending retry " .. tostring(chatHookFailures[path]) .. " (" .. tostring(err) .. ")")
  end
end

function setupChatHooks()
  local paths = {
    "/Script/SCUM.PlayerRpcChannel:Chat_Server_ProcessAdminCommand",
    "/Script/SCUM.PlayerRpcChannel:Chat_Server_BroadcastChatMessage"
  }
  if configBool("bridge-safety", { "EnableSendMessageToChatHook", "enableSendMessageToChatHook" }, false) then
    table.insert(paths, "/Script/SCUM.PlayerRpcChannel:Chat_Server_SendMessageToChat")
  end
  if configBool("bridge-safety", { "EnableLegacyConZChatHooks", "enableLegacyConZChatHooks" }, false) then
    table.insert(paths, "/Script/ConZ.PlayerRpcChannel:Chat_Server_ProcessAdminCommand")
    table.insert(paths, "/Script/ConZ.PlayerRpcChannel:Chat_Server_BroadcastChatMessage")
    if configBool("bridge-safety", { "EnableSendMessageToChatHook", "enableSendMessageToChatHook" }, false) then
      table.insert(paths, "/Script/ConZ.PlayerRpcChannel:Chat_Server_SendMessageToChat")
    end
  end
  for _, path in ipairs(paths) do registerChatHook(path) end
end

killHookStatus = {}
killHookFailures = {}
killEventDedup = {}

function registerKillHook(path)
  if killHookStatus[path] == true then return end
  if killHookStatus[path] == false then return end
  local okHook, err = pcall(function()
    RegisterHook(path, function(context, target, killer)
      return guardedHookCallback("kill", path, function()
      local victimDbId = dbIdText(target)
      local killerDbId = dbIdText(killer)
      if victimDbId == "" or killerDbId == "" or victimDbId == "0" or killerDbId == "0" then
        appendLog("kill hook unresolved ids path=" .. tostring(path) .. " target=" .. paramText(target) .. " killer=" .. paramText(killer))
        return
      end

      local now = os.time()
      local duplicateWindow = math.max(1, configNumber("server-kill-feed", { "DuplicateWindowSeconds", "duplicateWindowSeconds" }, 8))
      local dedupKey = killerDbId .. ">" .. victimDbId
      if killEventDedup[dedupKey] ~= nil and (now - killEventDedup[dedupKey]) <= duplicateWindow then return end
      killEventDedup[dedupKey] = now

      deferGame(1, function()
        local killerInfo = findPlayerByDbId(killerDbId)
        local victimInfo = findPlayerByDbId(victimDbId)
        local handled = handleKillEvent(killerInfo, victimInfo, {
          source = path,
          killerDbId = killerDbId,
          victimDbId = victimDbId
        })
        appendLog("kill hook " .. tostring(path) .. " killerDbId=" .. tostring(killerDbId) .. " victimDbId=" .. tostring(victimDbId) .. " handled=" .. tostring(handled))
      end)
      end)
    end)
  end)
  if okHook then
    killHookStatus[path] = true
    appendLog("kill hook " .. tostring(path) .. "=ok")
    return
  end
  killHookFailures[path] = (killHookFailures[path] or 0) + 1
  if killHookFailures[path] >= 90 then
    killHookStatus[path] = false
    appendLog("kill hook " .. tostring(path) .. "=unavailable after " .. tostring(killHookFailures[path]) .. " retries")
    return
  end
  if killHookFailures[path] == 1 or (killHookFailures[path] % 30) == 0 then
    appendLog("kill hook " .. tostring(path) .. "=pending retry " .. tostring(killHookFailures[path]) .. " (" .. tostring(err) .. ")")
  end
end

function registerPlayerRpcKillHook(path)
  if killHookStatus[path] == true then return end
  if killHookStatus[path] == false then return end
  local okHook, err = pcall(function()
    RegisterHook(path, function(context, victimParam, killerParam, killerProfileParam)
      return guardedHookCallback("kill-rpc", path, function()
      local victimObject = unwrapHookParam(victimParam)
      local killerObject = unwrapHookParam(killerParam)
      local victimKey = objectKey(victimObject)
      local killerKey = objectKey(killerObject)
      local killerProfileText = paramText(killerProfileParam)
      local now = os.time()
      local duplicateWindow = math.max(1, configNumber("server-kill-feed", { "DuplicateWindowSeconds", "duplicateWindowSeconds" }, 4))
      local dedupKey = "rpc:" .. tostring(killerKey) .. ">" .. tostring(victimKey)
      if dedupKey ~= "rpc:>" and killEventDedup[dedupKey] ~= nil and (now - killEventDedup[dedupKey]) <= duplicateWindow then return end
      killEventDedup[dedupKey] = now

      deferGame(1, function()
        local infos = cachedPlayerInfos(math.max(10, configNumber("bridge-safety", { "PlayerInfoCacheTtlSeconds", "playerInfoCacheTtlSeconds" }, 300))) or {}
        local victimInfo = findPlayerByLinkedObject(victimObject, infos)
        local killerInfo = findPlayerByLinkedObject(killerObject, infos)
        local handled = false
        if killerInfo ~= nil and victimInfo ~= nil and playerStateKey(killerInfo) ~= playerStateKey(victimInfo) then
          handled = handleKillEvent(killerInfo, victimInfo, { source = path, victimObjectKey = victimKey, killerObjectKey = killerKey, killerProfile = killerProfileText })
        else
          handled = handleDeathEvent(victimInfo, { source = path, victimObjectKey = victimKey, killerObjectKey = killerKey, killerProfile = killerProfileText })
        end
        appendLog("player-rpc kill hook " .. tostring(path) .. " killerKey=" .. tostring(killerKey) .. " victimKey=" .. tostring(victimKey) .. " handled=" .. tostring(handled))
      end)
      end)
    end)
  end)
  if okHook then
    killHookStatus[path] = true
    appendLog("player-rpc kill hook " .. tostring(path) .. "=ok")
    return
  end
  killHookFailures[path] = (killHookFailures[path] or 0) + 1
  if killHookFailures[path] >= 90 then
    killHookStatus[path] = false
    appendLog("player-rpc kill hook " .. tostring(path) .. "=unavailable after " .. tostring(killHookFailures[path]) .. " retries")
    return
  end
  if killHookFailures[path] == 1 or (killHookFailures[path] % 30) == 0 then
    appendLog("player-rpc kill hook " .. tostring(path) .. "=pending retry " .. tostring(killHookFailures[path]) .. " (" .. tostring(err) .. ")")
  end
end

function setupKillHooks()
  local useRuntimeHooks = configBool("server-kill-feed", { "UseRuntimeHooks", "useRuntimeHooks" }, false)
  if not useRuntimeHooks then
    if not KILL_HOOKS_DISABLED_LOGGED then
      appendLog("kill hooks disabled; server kill feed is expected to use native SaveFiles log parser")
      KILL_HOOKS_DISABLED_LOGGED = true
    end
    return
  end
  local paths = {
    "/Script/SCUM.ConZGameState:Multicast_AddToOrUpdatePrisonerKillRegistry",
    "/Script/SCUM.BP_ConZGameState_C:Multicast_AddToOrUpdatePrisonerKillRegistry",
    "/Script/ConZ.ConZGameState:Multicast_AddToOrUpdatePrisonerKillRegistry",
    "/Script/ConZ.BP_ConZGameState_C:Multicast_AddToOrUpdatePrisonerKillRegistry"
  }
  for _, path in ipairs(paths) do registerKillHook(path) end
  local rpcPaths = {
    "/Script/SCUM.PlayerRpcChannel:Misc_Server_LogKill",
    "/Script/ConZ.PlayerRpcChannel:Misc_Server_LogKill"
  }
  for _, path in ipairs(rpcPaths) do registerPlayerRpcKillHook(path) end
end

tradeHookStatus = tradeHookStatus or {}
tradeHookFailures = tradeHookFailures or {}
tradeErrorHookStatus = tradeErrorHookStatus or {}
tradeErrorHookFailures = tradeErrorHookFailures or {}
tradeInteractHookStatus = tradeInteractHookStatus or {}
tradeInteractHookFailures = tradeInteractHookFailures or {}
tradeServerDataTraceHookStatus = tradeServerDataTraceHookStatus or {}
tradeServerDataTraceHookFailures = tradeServerDataTraceHookFailures or {}

function hookParamSet(param, value)
  if param == nil then return false, "param missing" end
  if value == nil or not isValidObject(value) then return false, "value missing" end
  local okHasSet, setter = pcall(function() return param.set end)
  if not okHasSet or setter == nil then return false, "param.set missing" end
  local okSet, errSet = pcall(function() return param:set(value) end)
  if okSet then return true, "set" end
  return false, tostring(errSet)
end

function interactionTypeTextForHook(param)
  local raw = unwrapHookParam(param)
  local text = valueText(raw)
  if text ~= "" then return text end
  text = paramText(param)
  if text ~= "" then return text end
  return tostring(raw or "")
end

function interactionDataFieldValue(data, key)
  if data == nil then return nil end
  local value = safeGet(data, key)
  if value ~= nil then return runtimeCollectionUnwrap(value) end
  local okGet, prop = pcall(function()
    if data.GetPropertyValue ~= nil then return data:GetPropertyValue(key) end
    return nil
  end)
  if okGet and prop ~= nil then return runtimeCollectionUnwrap(prop) end
  return nil
end

function interactionVectorJson(value)
  value = runtimeCollectionUnwrap(value)
  if value == nil then return "null" end
  local x = tonumber(safeGet(value, "X") or safeGet(value, "x"))
  local y = tonumber(safeGet(value, "Y") or safeGet(value, "y"))
  local z = tonumber(safeGet(value, "Z") or safeGet(value, "z"))
  if x ~= nil or y ~= nil or z ~= nil then
    return '{"x":' .. tostring(x or 0) .. ',"y":' .. tostring(y or 0) .. ',"z":' .. tostring(z or 0) .. '}'
  end
  return runtimeValueJson(value)
end

function interactionDataFieldJson(label, data, key, kind)
  local value = interactionDataFieldValue(data, key)
  local valueJson = "null"
  if kind == "vector" then
    valueJson = interactionVectorJson(value)
  elseif kind == "object" and value ~= nil and isValidObject(value) then
    valueJson = nativeProbeObjectJson(label, value, "interaction-data", {})
  else
    valueJson = runtimeValueJson(value)
  end
  return '"' .. tostring(key) .. '":' .. valueJson
end

function interactionDataTraceJson(dataParam)
  local data = unwrapHookParam(dataParam)
  if data == nil then
    return '{"present":false,"paramText":' .. js(paramText(dataParam)) .. '}'
  end
  local fields = {
    interactionDataFieldJson("pointerData", data, "PointerData", "object"),
    interactionDataFieldJson("modifierPressed", data, "ModifierPressed", "value"),
    interactionDataFieldJson("integerData", data, "IntegerData", "value"),
    interactionDataFieldJson("boolData", data, "BoolData", "value"),
    interactionDataFieldJson("textData", data, "TextData", "value"),
    interactionDataFieldJson("interactionLocation", data, "InteractionLocation", "vector"),
    interactionDataFieldJson("interactionNormal", data, "InteractionNormal", "vector"),
    interactionDataFieldJson("vectorData", data, "VectorData", "vector"),
    interactionDataFieldJson("baseElementId", data, "BaseElementId", "value")
  }
  return '{"present":true,"paramText":' .. js(paramText(dataParam)) ..
    ',"rawText":' .. js(valueText(data)) ..
    ',"fields":{' .. table.concat(fields, ",") .. '}}'
end

TRADE_INTERACTION_TRACE_COUNT = TRADE_INTERACTION_TRACE_COUNT or 0
TRADE_SERVER_DATA_TRACE_COUNT = TRADE_SERVER_DATA_TRACE_COUNT or 0

function tradeInteractionTraceIfInteresting(path, kind, context, interactableParam, interactionTypeParam, interactionDataParam)
  if configBool("bridge-safety", { "EnableTradeInteractionTrace", "enableTradeInteractionTrace" }, false) ~= true then return end
  local maxCount = math.max(1, math.min(math.floor(configNumber("bridge-safety", { "TradeInteractionTraceMaxPerBoot", "tradeInteractionTraceMaxPerBoot" }, 120) or 120), 1000))
  if (TRADE_INTERACTION_TRACE_COUNT or 0) >= maxCount then return end
  local interactable = unwrapHookParam(interactableParam)
  local interactionText = interactionTypeTextForHook(interactionTypeParam)
  local lowerInteraction = tostring(interactionText or ""):lower()
  local targetText = (objectFullName(interactable) .. " " .. objectClassFullName(interactable)):lower()
  local interesting = lowerInteraction == "238" or lowerInteraction == "239" or
    lowerInteraction:find("tradebuy", 1, true) ~= nil or lowerInteraction:find("tradesell", 1, true) ~= nil or
    targetText:find("armory", 1, true) ~= nil or targetText:find("armsdealer", 1, true) ~= nil or
    targetText:find("trader", 1, true) ~= nil or targetText:find("tradepost", 1, true) ~= nil
  if not interesting then return end
  TRADE_INTERACTION_TRACE_COUNT = (TRADE_INTERACTION_TRACE_COUNT or 0) + 1
  local contextObj = unwrapHookParam(context)
  local info = directPlayerInfoFromObject(contextObj, "trade-interaction-trace") or cachedPlayerByObject(contextObj) or {}
  local data = '{"kind":' .. js(kind or "") ..
    ',"path":' .. js(path or "") ..
    ',"interactionType":' .. js(interactionText) ..
    ',"traceIndex":' .. tostring(TRADE_INTERACTION_TRACE_COUNT or 0) ..
    ',"context":' .. nativeProbeObjectJson("context", contextObj, "trade-interaction-trace", {}) ..
    ',"target":' .. nativeProbeObjectJson("target", interactable, "trade-interaction-trace", {}) ..
    ',"interactionData":' .. interactionDataTraceJson(interactionDataParam) .. '}'
  appendLog("trade interaction trace kind=" .. tostring(kind or "") ..
    " path=" .. tostring(path or "") ..
    " interactionType=" .. tostring(interactionText or "") ..
    " target=" .. objectFullName(interactable))
  appendActionEvent("trade_interaction_trace", true, info,
    "Trade interaction trace: " .. tostring(interactionText or ""),
    data)
end

function registerTradeInteractionHook(path, kind)
  if tradeInteractHookStatus[path] == true then return end
  if tradeInteractHookStatus[path] == false then return end
  local okHook, err = pcall(function()
    RegisterHook(path, function(context, interactableParam, secondParam, thirdParam, ...)
      local hookArgs = { ... }
      return guardedHookCallback("trade-interaction", path, function()
      local interactable = unwrapHookParam(interactableParam)
      local extraParams = hookArgs
      local interactionTypeParam = thirdParam
      local interactionDataParam = extraParams[1]
      if kind == "prisoner" then
        interactionTypeParam = secondParam
        interactionDataParam = thirdParam
      end
      local okTrace, traceErr = pcall(function()
        tradeInteractionTraceIfInteresting(path, kind, context, interactableParam, interactionTypeParam, interactionDataParam)
      end)
      if not okTrace then
        appendLog("trade interaction trace error path=" .. tostring(path) .. " err=" .. tostring(traceErr))
      end
      local allowProxyInteractionRedirect = configBool("bridge-safety", { "EnableFunctionalTraderProxyInteractionRedirect", "enableFunctionalTraderProxyInteractionRedirect" }, false) == true
      if configBool("bridge-safety", { "TradeHooksReadOnlyMode", "tradeHooksReadOnlyMode" }, true) == true and not allowProxyInteractionRedirect then
        return
      end
      local route, routeLookup = functionalTraderProxyRouteForObject(interactable)
      if route == nil then return end
      local interactionText = interactionTypeTextForHook(interactionTypeParam)
      local lowerInteraction = tostring(interactionText or ""):lower()
      local isTradeInteraction = lowerInteraction == "238" or lowerInteraction == "239" or
        lowerInteraction:find("tradebuy", 1, true) ~= nil or lowerInteraction:find("tradesell", 1, true) ~= nil
      if allowProxyInteractionRedirect and not isTradeInteraction then
        return
      end
      local attempts = { "lookup=" .. tostring(routeLookup) }
      local okPrepare, prepareDetail = functionalTraderProxyPrepareInteraction(route, interactable, attempts)
      local tradePost, donorDetail = functionalTraderProxyDonorTradePost(route, attempts)
      table.insert(attempts, "donorForSet=" .. tostring(donorDetail))
      local stockTrader = nil
      local stockDetail = ""
      local redirectToDonor = configBool("bridge-safety", { "FunctionalTraderProxyRedirectInteractionToDonor", "functionalTraderProxyRedirectInteractionToDonor" }, false) == true
      local redirectToStockTrader = configBool("bridge-safety", { "FunctionalTraderProxyRedirectInteractionToStockTrader", "functionalTraderProxyRedirectInteractionToStockTrader" }, true) == true
      local okSet = false
      local setDetail = "proxy kept as interactable"
      local redirectTarget = nil
      local redirectTargetKind = "proxy"
      if allowProxyInteractionRedirect and redirectToStockTrader then
        stockTrader, stockDetail = functionalTraderProxyFindStockTrader(route, attempts)
        table.insert(attempts, "stockTraderForSet=" .. tostring(stockDetail))
        if stockTrader ~= nil and isValidObject(stockTrader) and okPrepare then
          redirectTarget = stockTrader
          redirectTargetKind = "stockTrader"
        else
          setDetail = "stock trader missing or prepare failed"
        end
      elseif redirectToDonor then
        if tradePost ~= nil and isValidObject(tradePost) and okPrepare then
          redirectTarget = tradePost
          redirectTargetKind = "donorTradePost"
        else
          setDetail = "donor missing or prepare failed"
        end
      else
        table.insert(attempts, "interact redirect disabled; using proxy ATrader with stock personality")
      end
      if redirectTarget ~= nil and isValidObject(redirectTarget) then
        okSet, setDetail = hookParamSet(interactableParam, redirectTarget)
      end
      local data = '{"kind":' .. js(kind or "") ..
        ',"path":' .. js(path or "") ..
        ',"interactionType":' .. js(interactionText) ..
        ',"proxy":' .. nativeProbeObjectJson("proxy", interactable, "trade-interact-proxy", {}) ..
        ',"donorTradePost":' .. nativeProbeObjectJson("donorTradePost", tradePost, "redirect-target", {}) ..
        ',"stockTrader":' .. nativeProbeObjectJson("stockTrader", stockTrader, "redirect-target", {}) ..
        ',"redirectToDonor":' .. (redirectToDonor and "true" or "false") ..
        ',"redirectToStockTrader":' .. (redirectToStockTrader and "true" or "false") ..
        ',"redirectTargetKind":' .. js(redirectTargetKind) ..
        ',"prepared":' .. (okPrepare and "true" or "false") ..
        ',"paramSet":' .. (okSet and "true" or "false") ..
        ',"detail":' .. js(tostring(prepareDetail or "") .. "; " .. tostring(setDetail or "")) ..
        ',"attempts":' .. js(table.concat(attempts or {}, " | ")) .. '}'
      appendLog("trade interact proxy redirect kind=" .. tostring(kind or "") ..
        " okPrepare=" .. tostring(okPrepare) ..
        " okSet=" .. tostring(okSet) ..
        " targetKind=" .. tostring(redirectTargetKind) ..
        " proxy=" .. objectFullName(interactable) ..
        " donor=" .. objectFullName(tradePost) ..
        " stockTrader=" .. objectFullName(stockTrader) ..
        " attempts=" .. table.concat(attempts or {}, " | "))
      appendActionEvent("trade_proxy_interact_redirect", okPrepare and (okSet or redirectTarget == nil), nil,
        okSet and ("Trade interaction redirected to " .. tostring(redirectTargetKind) .. ".") or "Trade interaction kept on proxy ATrader.",
        data)
      end)
    end)
  end)
  if okHook then
    tradeInteractHookStatus[path] = true
    appendLog("trade interaction hook " .. tostring(path) .. "=ok")
    return
  end
  tradeInteractHookFailures[path] = (tradeInteractHookFailures[path] or 0) + 1
  if tradeInteractHookFailures[path] >= 30 then
    tradeInteractHookStatus[path] = false
    appendLog("trade interaction hook " .. tostring(path) .. "=unavailable after " .. tostring(tradeInteractHookFailures[path]) .. " retries")
    return
  end
  if tradeInteractHookFailures[path] == 1 or (tradeInteractHookFailures[path] % 10) == 0 then
    appendLog("trade interaction hook " .. tostring(path) .. "=pending retry " .. tostring(tradeInteractHookFailures[path]) .. " (" .. tostring(err) .. ")")
  end
end

function registerTradeHook(path, kind)
  if tradeHookStatus[path] == true then return end
  if tradeHookStatus[path] == false then return end
  local okHook, err = pcall(function()
    RegisterHook(path, function(context, pcParam, tradeablesParam, traderParam, ...)
      return guardedHookCallback("trade", path, function()
      local trader = unwrapHookParam(traderParam)
      local redirectAttempts = {}
      local redirected = false
      local redirectDetail = "read-only trace; proxy redirect disabled"
      local allowProxyPurchaseRedirect = configBool("bridge-safety", { "EnableFunctionalTraderProxyPurchaseRedirect", "enableFunctionalTraderProxyPurchaseRedirect" }, false) == true
      if configBool("bridge-safety", { "TradeHooksReadOnlyMode", "tradeHooksReadOnlyMode" }, true) ~= true or allowProxyPurchaseRedirect then
        local redirectRoute, redirectLookup = functionalTraderProxyRouteForObject(trader)
        redirectDetail = redirectLookup or ""
        if redirectRoute ~= nil then
          table.insert(redirectAttempts, "lookup=" .. tostring(redirectLookup))
          local stockTrader, stockDetail = functionalTraderProxyFindStockTrader(redirectRoute, redirectAttempts)
          redirectDetail = tostring(stockDetail or "")
          if stockTrader ~= nil and isValidObject(stockTrader) then
            local okSet, setDetail = hookParamSet(traderParam, stockTrader)
            table.insert(redirectAttempts, "setTrader=" .. tostring(okSet) .. ":" .. tostring(setDetail))
            if okSet then
              trader = stockTrader
              redirected = true
            end
          else
            table.insert(redirectAttempts, "stockTrader missing=" .. tostring(stockDetail))
          end
        end
      end
      local personality = traderPersonalityObject(trader)
      local data = '{"kind":' .. js(kind or "") ..
        ',"path":' .. js(path or "") ..
        ',"proxyRedirected":' .. (redirected and "true" or "false") ..
        ',"proxyRedirectDetail":' .. js(redirectDetail or "") ..
        ',"trader":' .. nativeProbeObjectJson("trader", trader, "trade-rpc", {}) ..
        ',"personality":' .. nativeProbeObjectJson("personality", personality, "_traderPersonalityDataAsset", {}) ..
        ',"persistentId":' .. js(traderPersonalityRuntimeId(personality)) ..
        ',"redirectAttempts":' .. js(table.concat(redirectAttempts or {}, " | ")) .. '}'
      appendLog("trade hook " .. tostring(kind or "") ..
        " path=" .. tostring(path) ..
        " proxyRedirected=" .. tostring(redirected) ..
        " redirectDetail=" .. tostring(redirectDetail) ..
        " trader=" .. objectFullName(trader) ..
        " class=" .. objectClassFullName(trader) ..
        " personality=" .. objectFullName(personality) ..
        " persistentId=" .. tostring(traderPersonalityRuntimeId(personality)))
      appendActionEvent("trade_rpc_" .. tostring(kind or "unknown"), true, nil,
        "Trade RPC: " .. tostring(kind or "") .. " persistentId=" .. tostring(traderPersonalityRuntimeId(personality)),
        data)
      end)
    end)
  end)
  if okHook then
    tradeHookStatus[path] = true
    appendLog("trade hook " .. tostring(path) .. "=ok")
    return
  end
  tradeHookFailures[path] = (tradeHookFailures[path] or 0) + 1
  if tradeHookFailures[path] >= 30 then
    tradeHookStatus[path] = false
    appendLog("trade hook " .. tostring(path) .. "=unavailable after " .. tostring(tradeHookFailures[path]) .. " retries")
    return
  end
  if tradeHookFailures[path] == 1 or (tradeHookFailures[path] % 10) == 0 then
    appendLog("trade hook " .. tostring(path) .. "=pending retry " .. tostring(tradeHookFailures[path]) .. " (" .. tostring(err) .. ")")
  end
end

