function tradeTraceParamJson(label, param)
  local value = unwrapHookParam(param)
  local isObject = false
  if value ~= nil then
    local okValid, valid = pcall(function() return isValidObject(value) end)
    isObject = okValid and valid == true
  end
  local text = ""
  local okText, paramTextValue = pcall(function() return paramText(param) end)
  if okText then text = tostring(paramTextValue or "") end
  local rawText = ""
  local okRaw, rawValue = pcall(function() return valueText(value) end)
  if okRaw then rawText = tostring(rawValue or "") end
  local objectJson = "null"
  if isObject then
    objectJson = nativeProbeObjectJson(label or "param", value, "trade-server-data", {})
  end
  return '{"label":' .. js(label or "") ..
    ',"text":' .. js(text) ..
    ',"rawText":' .. js(rawText) ..
    ',"isObject":' .. tostring(isObject == true) ..
    ',"object":' .. objectJson .. '}'
end

function registerTradeServerDataTraceHook(path, kind)
  if tradeServerDataTraceHookStatus[path] == true then return end
  if tradeServerDataTraceHookStatus[path] == false then return end
  if configBool("bridge-safety", { "EnableTraderServerDataTrace", "enableTraderServerDataTrace" }, false) ~= true then
    tradeServerDataTraceHookStatus[path] = false
    appendLog("trade server-data trace hook " .. tostring(path) .. "=disabled")
    return
  end
  local okHook, err = pcall(function()
    RegisterHook(path, function(context, firstParam, secondParam, thirdParam, fourthParam, ...)
      return guardedHookCallback("trade-server-data", path, function()
      local maxCount = math.max(1, math.min(math.floor(configNumber("bridge-safety", { "TradeServerDataTraceMaxPerBoot", "tradeServerDataTraceMaxPerBoot" }, 80) or 80), 1000))
      if (TRADE_SERVER_DATA_TRACE_COUNT or 0) >= maxCount then return end
      TRADE_SERVER_DATA_TRACE_COUNT = (TRADE_SERVER_DATA_TRACE_COUNT or 0) + 1
      local contextObj = unwrapHookParam(context)
      local data = '{"kind":' .. js(kind or "") ..
        ',"path":' .. js(path or "") ..
        ',"traceIndex":' .. tostring(TRADE_SERVER_DATA_TRACE_COUNT or 0) ..
        ',"context":' .. tradeTraceParamJson("context", context) ..
        ',"contextObject":' .. nativeProbeObjectJson("contextObject", contextObj, "trade-server-data-context", {}) ..
        ',"params":[' ..
          tradeTraceParamJson("p1", firstParam) .. "," ..
          tradeTraceParamJson("p2", secondParam) .. "," ..
          tradeTraceParamJson("p3", thirdParam) .. "," ..
          tradeTraceParamJson("p4", fourthParam) ..
        ']}'
      appendLog("trade server-data trace kind=" .. tostring(kind or "") ..
        " path=" .. tostring(path) ..
        " p1=" .. paramText(firstParam) ..
        " p2=" .. paramText(secondParam) ..
        " p3=" .. paramText(thirdParam) ..
        " p4=" .. paramText(fourthParam))
      appendActionEvent("trade_server_data_trace", true, nil,
        "Trade server-data RPC: " .. tostring(kind or ""),
        data)
      end)
    end)
  end)
  if okHook then
    tradeServerDataTraceHookStatus[path] = true
    appendLog("trade server-data trace hook " .. tostring(path) .. "=ok")
    return
  end
  tradeServerDataTraceHookFailures[path] = (tradeServerDataTraceHookFailures[path] or 0) + 1
  if tradeServerDataTraceHookFailures[path] >= 30 then
    tradeServerDataTraceHookStatus[path] = false
    appendLog("trade server-data trace hook " .. tostring(path) .. "=unavailable after " .. tostring(tradeServerDataTraceHookFailures[path]) .. " retries")
    return
  end
  if tradeServerDataTraceHookFailures[path] == 1 or (tradeServerDataTraceHookFailures[path] % 10) == 0 then
    appendLog("trade server-data trace hook " .. tostring(path) .. "=pending retry " .. tostring(tradeServerDataTraceHookFailures[path]) .. " (" .. tostring(err) .. ")")
  end
end

function registerEditorActorTargetHook(path, kind)
  if EDITOR_ACTOR_TARGET_HOOK_STATUS[path] == true then return end
  if EDITOR_ACTOR_TARGET_HOOK_STATUS[path] == false then return end
  local okHook, err = pcall(function()
    RegisterHook(path, function(context, firstParam, secondParam, thirdParam, fourthParam, ...)
      return guardedHookCallback("actor-editor-target", path, function()
      local okRun, runErr = pcall(function()
        if kind == "playerRpcInteract" then
          editorActorRememberTargetFromHook(path, kind, context, firstParam, secondParam, thirdParam)
          return
        end
        if kind == "prisonerInteract" then
          editorActorRememberTargetFromHook(path, kind, context, firstParam, nil, secondParam)
          return
        end
        if kind == "hovered" then
          editorActorRememberTargetFromHook(path, kind, context, nil, firstParam, nil)
          return
        end
        editorActorRememberTargetFromHook(path, kind, context, firstParam, nil, nil)
      end)
      if not okRun then
        appendLog("actor-editor target hook error kind=" .. tostring(kind or "") ..
          " path=" .. tostring(path or "") ..
          " err=" .. tostring(runErr or ""))
      end
      end)
    end)
  end)
  if okHook then
    EDITOR_ACTOR_TARGET_HOOK_STATUS[path] = true
    appendLog("actor-editor target hook " .. tostring(path) .. "=" .. tostring(kind or "") .. "=ok")
    return
  end
  EDITOR_ACTOR_TARGET_HOOK_FAILURES[path] = (EDITOR_ACTOR_TARGET_HOOK_FAILURES[path] or 0) + 1
  if EDITOR_ACTOR_TARGET_HOOK_FAILURES[path] >= 20 then
    EDITOR_ACTOR_TARGET_HOOK_STATUS[path] = false
    appendLog("actor-editor target hook " .. tostring(path) .. "=unavailable after " .. tostring(EDITOR_ACTOR_TARGET_HOOK_FAILURES[path]) .. " retries")
    return
  end
  if EDITOR_ACTOR_TARGET_HOOK_FAILURES[path] == 1 or (EDITOR_ACTOR_TARGET_HOOK_FAILURES[path] % 10) == 0 then
    appendLog("actor-editor target hook " .. tostring(path) .. "=pending retry " .. tostring(EDITOR_ACTOR_TARGET_HOOK_FAILURES[path]) .. " (" .. tostring(err) .. ")")
  end
end

function setupEditorActorTargetHooks()
  if moduleEnabled("actor-editor", true) ~= true then
    appendLog("actor-editor target hooks disabled: actor-editor module off")
    return
  end
  if configBool("bridge-safety", { "EnableActorEditorServerTargetHooks", "enableActorEditorServerTargetHooks" }, false) ~= true then
    appendLog("actor-editor target hooks disabled by bridge-safety")
    return
  end
  local paths = {
    { "/Script/SCUM.Prisoner:SetTargetOnServer", "setTargetOnServer" },
    { "/Script/SCUM.Prisoner:SetRotationTarget", "setRotationTarget" },
    { "/Script/SCUM.Prisoner:SetMeleeTarget", "setMeleeTarget" },
    { "/Script/SCUM.Prisoner:Server_SetRotationTarget", "serverSetRotationTarget" },
    { "/Script/SCUM.Prisoner:Server_SetMeleeTarget", "serverSetMeleeTarget" },
    { "/Script/SCUM.Prisoner:InteractWithObjectOnServer", "prisonerInteract" },
    { "/Script/SCUM.PlayerRpcChannel:InteractWithObjectOnServer", "playerRpcInteract" },
    { "/Script/SCUM.InteractableInterface:OnHovered", "hovered" }
  }
  for _, row in ipairs(paths) do
    registerEditorActorTargetHook(row[1], row[2])
  end
end

function setupEditorActorServerPointerHooks()
  if moduleEnabled("actor-editor", true) ~= true then
    appendLog("actor-editor server pointer hooks disabled: actor-editor module off")
    return
  end
  if configBool("bridge-safety", { "EnableActorEditorServerPointerHooks", "enableActorEditorServerPointerHooks" }, false) ~= true then
    appendLog("actor-editor server pointer hooks disabled by bridge-safety")
    return
  end
  local paths = {
    { "/Script/SCUM.PlayerRpcChannel:InteractWithObjectOnServer", "playerRpcInteract" },
    { "/Script/SCUM.Prisoner:InteractWithObjectOnServer", "prisonerInteract" },
    { "/Script/SCUM.PlayerRpcChannel:Server_RequestDoorUpdate", "serverRequestDoorUpdate" },
    { "/Script/SCUM.PlayerRpcChannel:HasOwningUser_Server_RequestStateUpdate", "owningUserStateUpdate" }
  }
  if configBool("bridge-safety", { "EnableLegacyConZActorEditorPointerHooks", "enableLegacyConZActorEditorPointerHooks" }, false) == true then
    table.insert(paths, { "/Script/ConZ.PlayerRpcChannel:InteractWithObjectOnServer", "playerRpcInteract" })
    table.insert(paths, { "/Script/ConZ.Prisoner:InteractWithObjectOnServer", "prisonerInteract" })
    table.insert(paths, { "/Script/ConZ.PlayerRpcChannel:Server_RequestDoorUpdate", "serverRequestDoorUpdate" })
    table.insert(paths, { "/Script/ConZ.PlayerRpcChannel:HasOwningUser_Server_RequestStateUpdate", "owningUserStateUpdate" })
  end
  for _, row in ipairs(paths) do
    registerEditorActorTargetHook(row[1], row[2])
  end
end

PLACEABLE_FILL_TRACE_HOOK_STATUS = PLACEABLE_FILL_TRACE_HOOK_STATUS or {}
PLACEABLE_FILL_TRACE_HOOK_FAILURES = PLACEABLE_FILL_TRACE_HOOK_FAILURES or {}
PLACEABLE_FILL_TRACE_COUNT = PLACEABLE_FILL_TRACE_COUNT or 0

function placeableFillTraceMaxCount()
  return math.max(1, math.min(math.floor(configNumber("bridge-safety", {
    "PlaceableFillTraceMaxPerBoot",
    "placeableFillTraceMaxPerBoot"
  }, 120) or 120), 1000))
end

function placeableFillTraceCanLog()
  if configBool("bridge-safety", { "EnablePlaceableFillTrace", "enablePlaceableFillTrace" }, false) ~= true then return false end
  if (PLACEABLE_FILL_TRACE_COUNT or 0) >= placeableFillTraceMaxCount() then return false end
  PLACEABLE_FILL_TRACE_COUNT = (PLACEABLE_FILL_TRACE_COUNT or 0) + 1
  return true
end

function placeableFillItemsTraceJson(itemsParam)
  local items = unwrapHookParam(itemsParam)
  if items == nil then return '{"present":false,"paramText":' .. js(paramText(itemsParam)) .. '}' end
  local count, samples, method = runtimeArrayCount(items, 8)
  local rows = {}
  for _, item in ipairs(samples or {}) do
    table.insert(rows, nativeProbeObjectJson("item", item, "Placeable_Server_FillWithItems", {}))
  end
  return '{"present":true' ..
    ',"paramText":' .. js(paramText(itemsParam)) ..
    ',"count":' .. tostring(count or -1) ..
    ',"readMethod":' .. js(method or "") ..
    ',"samples":[' .. table.concat(rows, ",") .. ']}'
end

function placeableFillTraceRecord(kind, path, contextParam, placeableParam, userParam, itemsParam, interactionTypeParam, interactionDataParam)
  if not placeableFillTraceCanLog() then return end
  local contextObj = unwrapHookParam(contextParam)
  local placeable = unwrapHookParam(placeableParam)
  local user = unwrapHookParam(userParam)
  local interactionType = interactionTypeParam ~= nil and interactionTypeTextForHook(interactionTypeParam) or ""
  local info = directPlayerInfoFromObject(contextObj, "placeable-fill-trace") or
    directPlayerInfoFromObject(user, "placeable-fill-user") or
    cachedPlayerByObject(contextObj) or
    cachedPlayerByObject(user) or {}
  local beforeBaseCount = select(1, nativePlaceableBaseCount())
  local data = '{"kind":' .. js(kind or "") ..
    ',"path":' .. js(path or "") ..
    ',"traceIndex":' .. tostring(PLACEABLE_FILL_TRACE_COUNT or 0) ..
    ',"interactionType":' .. js(interactionType) ..
    ',"context":' .. nativeProbeObjectJson("context", contextObj, "placeable-fill-trace", {}) ..
    ',"placeable":' .. nativeProbeObjectJson("placeable", placeable, "placeable-fill-trace", {}) ..
    ',"user":' .. nativeProbeObjectJson("user", user, "placeable-fill-trace", {}) ..
    ',"items":' .. placeableFillItemsTraceJson(itemsParam) ..
    ',"interactionData":' .. (interactionDataParam ~= nil and interactionDataTraceJson(interactionDataParam) or "null") ..
    ',"placeableState":' .. nativePlaceableActorStateJson(placeable) ..
    ',"baseManagerBaseCount":' .. tostring(beforeBaseCount or 0) ..
    ',"baseSnapshot":' .. nativePlaceableBaseSnapshotJson(6) .. '}'
  appendLog("placeable fill trace kind=" .. tostring(kind or "") ..
    " path=" .. tostring(path or "") ..
    " interactionType=" .. tostring(interactionType or "") ..
    " placeable=" .. objectFullName(placeable) ..
    " user=" .. objectFullName(user))
  appendActionEvent("placeable_fill_trace", true, info,
    "Placeable fill trace: " .. tostring(kind or "") .. " " .. tostring(interactionType or ""),
    data)
end

function placeableInteractionTraceIfInteresting(path, kind, context, interactableParam, userParam, interactionTypeParam, interactionDataParam)
  if configBool("bridge-safety", { "EnablePlaceableFillTrace", "enablePlaceableFillTrace" }, false) ~= true then return end
  local interactable = unwrapHookParam(interactableParam)
  local interactionText = interactionTypeTextForHook(interactionTypeParam)
  local lowerInteraction = tostring(interactionText or ""):lower()
  local targetText = (objectFullName(interactable) .. " " .. objectClassFullName(interactable)):lower()
  local interesting = lowerInteraction == "23" or lowerInteraction == "24" or lowerInteraction == "28" or lowerInteraction == "29" or lowerInteraction == "30" or
    lowerInteraction:find("godmodefill", 1, true) ~= nil or
    lowerInteraction == "fill" or
    lowerInteraction:find("craft", 1, true) ~= nil or
    targetText:find("placeableactor", 1, true) ~= nil or
    targetText:find("placeable", 1, true) ~= nil or
    targetText:find("basebuilding", 1, true) ~= nil
  if not interesting then return end
  placeableFillTraceRecord(kind, path, context, interactableParam, userParam, nil, interactionTypeParam, interactionDataParam)
end

function registerPlaceableFillTraceHook(path, kind)
  if PLACEABLE_FILL_TRACE_HOOK_STATUS[path] == true then return end
  if PLACEABLE_FILL_TRACE_HOOK_STATUS[path] == false then return end
  local okHook, err = pcall(function()
    RegisterHook(path, function(context, firstParam, secondParam, thirdParam, fourthParam, ...)
      return guardedHookCallback("placeable-fill-trace", path, function()
      local okTrace, traceErr = pcall(function()
        if kind == "fill-items" then
          placeableFillTraceRecord(kind, path, context, firstParam, secondParam, thirdParam, nil, nil)
          return
        end
        if kind == "player-rpc-interact" then
          placeableInteractionTraceIfInteresting(path, kind, context, firstParam, secondParam, thirdParam, fourthParam)
          return
        end
        if kind == "prisoner-interact" then
          placeableInteractionTraceIfInteresting(path, kind, context, firstParam, context, secondParam, thirdParam)
          return
        end
      end)
      if not okTrace then appendLog("placeable fill trace hook error path=" .. tostring(path) .. " err=" .. tostring(traceErr)) end
      end)
    end)
  end)
  if okHook then
    PLACEABLE_FILL_TRACE_HOOK_STATUS[path] = true
    appendLog("placeable fill trace hook " .. tostring(path) .. "=" .. tostring(kind or "") .. "=ok")
    return
  end
  PLACEABLE_FILL_TRACE_HOOK_FAILURES[path] = (PLACEABLE_FILL_TRACE_HOOK_FAILURES[path] or 0) + 1
  if PLACEABLE_FILL_TRACE_HOOK_FAILURES[path] >= 20 then
    PLACEABLE_FILL_TRACE_HOOK_STATUS[path] = false
    appendLog("placeable fill trace hook " .. tostring(path) .. "=unavailable after " .. tostring(PLACEABLE_FILL_TRACE_HOOK_FAILURES[path]) .. " retries")
    return
  end
  if PLACEABLE_FILL_TRACE_HOOK_FAILURES[path] == 1 or (PLACEABLE_FILL_TRACE_HOOK_FAILURES[path] % 10) == 0 then
    appendLog("placeable fill trace hook " .. tostring(path) .. "=pending retry " .. tostring(PLACEABLE_FILL_TRACE_HOOK_FAILURES[path]) .. " (" .. tostring(err) .. ")")
  end
end

function setupPlaceableFillTraceHooks()
  if configBool("bridge-safety", { "EnablePlaceableFillTrace", "enablePlaceableFillTrace" }, false) ~= true then
    appendLog("placeable fill trace hooks disabled by bridge-safety")
    return
  end
  local paths = {
    { "/Script/SCUM.PlayerRpcChannel:Placeable_Server_FillWithItems", "fill-items" },
    { "/Script/SCUM.PlayerRpcChannel:InteractWithObjectOnServer", "player-rpc-interact" },
    { "/Script/SCUM.Prisoner:InteractWithObjectOnServer", "prisoner-interact" }
  }
  if configBool("bridge-safety", { "EnableLegacyConZPlaceableFillTrace", "enableLegacyConZPlaceableFillTrace" }, false) == true then
    table.insert(paths, { "/Script/ConZ.PlayerRpcChannel:Placeable_Server_FillWithItems", "fill-items" })
    table.insert(paths, { "/Script/ConZ.PlayerRpcChannel:InteractWithObjectOnServer", "player-rpc-interact" })
    table.insert(paths, { "/Script/ConZ.Prisoner:InteractWithObjectOnServer", "prisoner-interact" })
  end
  for _, row in ipairs(paths) do registerPlaceableFillTraceHook(row[1], row[2]) end
end

