BRIDGE_LOOP_HANDLES = BRIDGE_LOOP_HANDLES or {}

  -- P4 restores the pre-P0 direct LoopAsync fallback.  P1/P2 delayed callback
  -- chains stay removed and scheduler exports remain type-checked so UE4SS
  -- boolean sentinels are never called as functions.
function bridgeLoopInterval(value, fallback)
  local parsed = tonumber(value)
  if type(parsed) ~= "number" then parsed = tonumber(fallback) or 1 end
  if parsed < 1 then parsed = 1 end
  return parsed
end

function safeLoop(name, intervalMs, fn)
  local interval = bridgeLoopInterval(intervalMs, 1)
  local function runLoopBody()
    local okLoop, err = pcall(fn)
    if not okLoop then appendLog("loop " .. tostring(name) .. " error: " .. tostring(err)) end
  end

  local loopInGameThreadWithDelay = schedulerFunction("LoopInGameThreadWithDelay")
  if loopInGameThreadWithDelay ~= nil then
    local okLoop, handleOrErr = pcall(function()
      return loopInGameThreadWithDelay(interval, runLoopBody)
    end)
    if okLoop then
      BRIDGE_LOOP_HANDLES[tostring(name)] = handleOrErr
      appendLog("loop " .. tostring(name) .. " started via LoopInGameThreadWithDelay")
      return true
    end
    appendLog("LoopInGameThreadWithDelay failed for " .. tostring(name) .. ": " .. tostring(handleOrErr))
  end

  local loopAsync = schedulerFunction("LoopAsync")
  if loopAsync == nil then
    appendLog("LoopAsync unavailable for " .. tostring(name) .. "; loop not started")
    return false
  end

  local okLoop, handleOrErr = pcall(function()
    return loopAsync(interval, function()
      runLoopBody()
      return false
    end)
  end)
  if not okLoop then
    appendLog("LoopAsync failed for " .. tostring(name) .. ": " .. tostring(handleOrErr))
    return false
  end
  BRIDGE_LOOP_HANDLES[tostring(name)] = handleOrErr
  appendLog("loop " .. tostring(name) .. " started via direct LoopAsync fallback")
  return true
end

function safeAsyncLoop(name, intervalMs, fn)
  local interval = bridgeLoopInterval(intervalMs, 1)
  local loopAsync = schedulerFunction("LoopAsync")
  if loopAsync == nil then
    appendLog("LoopAsync unavailable for async loop " .. tostring(name) .. "; loop not started")
    return false
  end

  local running = false
  local function runLoopBody()
    if running then
      appendLog("async loop " .. tostring(name) .. " skipped overlapping tick")
      return
    end
    running = true
    local okLoop, err = pcall(fn)
    running = false
    if not okLoop then appendLog("async loop " .. tostring(name) .. " error: " .. tostring(err)) end
  end

  local okLoop, handleOrErr = pcall(function()
    return loopAsync(interval, function()
      runLoopBody()
      return false
    end)
  end)
  if not okLoop then
    appendLog("LoopAsync failed for async loop " .. tostring(name) .. ": " .. tostring(handleOrErr))
    return false
  end
  BRIDGE_LOOP_HANDLES[tostring(name)] = handleOrErr
  appendLog("async loop " .. tostring(name) .. " started via guarded LoopAsync")
  return true
end

GAME_THREAD_SCHEDULER_SELFTEST = GAME_THREAD_SCHEDULER_SELFTEST or { startedAt = os.time(), ok = false, reported = false }
if configBool("bridge-safety", { "EnableGameThreadSchedulerSelfTest", "enableGameThreadSchedulerSelfTest" }, true) then
  deferGame(0, function()
    GAME_THREAD_SCHEDULER_SELFTEST.ok = true
    GAME_THREAD_SCHEDULER_SELFTEST.okAt = os.time()
    writeSchedulerState("ok", "ExecuteInGameThread callback executed")
