if configBool("bridge-safety", { "EnableGameThreadSchedulerSelfTest", "enableGameThreadSchedulerSelfTest" }, true) then
  safeAsyncLoop("game-thread-scheduler-watchdog", 5000, function()
    local probe = GAME_THREAD_SCHEDULER_SELFTEST or {}
    if probe.ok == true then return end
    local age = os.time() - (tonumber(probe.startedAt) or os.time())
    if age >= 10 and probe.reported ~= true then
      probe.reported = true
      GAME_THREAD_SCHEDULER_SELFTEST = probe
      local warning = bridgeGameThreadSchedulerWarning()
      if warning == "" then warning = "ExecuteInGameThread self-test did not run after " .. tostring(age) .. " seconds. Check UE4SS HookEngineTick/ProcessEvent scheduler settings." end
      appendLog("CRITICAL game-thread scheduler stalled: " .. warning)
      appendLog("game-thread scheduler: switching to inline execution mode; player/panel commands will run synchronously from async loops")
      writeSchedulerState("stalled-inline", warning .. " | deferGame will run inline")
      if type(appendActionEvent) == "function" then
        appendActionEvent("bridge_scheduler", false, nil, "Game-thread scheduler stalled; deferGame switched to inline mode", '{"ageSeconds":' .. tostring(age) .. ',"detail":' .. js(warning) .. ',"inlineMode":true}')
      end
    end
  end)
end

