SHOW_NAMEPLATES_ON_JOIN_LAST = SHOW_NAMEPLATES_ON_JOIN_LAST or {}
SHOW_NAMEPLATES_ON_JOIN_PENDING = SHOW_NAMEPLATES_ON_JOIN_PENDING or {}
SHOW_NAMEPLATES_ON_JOIN_CACHE_REFRESH_AT = SHOW_NAMEPLATES_ON_JOIN_CACHE_REFRESH_AT or 0

function showNameplatesOnJoinPlayerKey(info)
  local key = playerCommandQueueKey(info)
  if key ~= "" then return key end
  return tostring((info and (info.steam or info.name or info.runtimeKey)) or "")
end

function joinCommandsConfig()
  return configText("join-commands")
end

function joinCommandsEnabledFromText(text)
  text = tostring(text or "")
  if text ~= "" then
    return extractBoolAny(text, { "Enabled", "enabled" }, true) ~= false
  end
  return configBool("bridge-safety", { "EnableShowNameplatesOnJoin", "enableShowNameplatesOnJoin" }, false) == true
end

function joinCommandsNumber(text, names, fallback, bridgeNames)
  text = tostring(text or "")
  if text ~= "" then
    return extractNumberAny(text, names, fallback)
  end
  return configNumber("bridge-safety", bridgeNames or names, fallback)
end

function joinCommandsBool(text, names, fallback, bridgeNames)
  text = tostring(text or "")
  if text ~= "" then
    return extractBoolAny(text, names, fallback)
  end
  return configBool("bridge-safety", bridgeNames or names, fallback)
end

function joinCommandsConfiguredCommands(info, text)
  text = tostring(text or joinCommandsConfig() or "")
  local out = {}
  local seen = {}
  if text == "" then
    dlcAddCommand(out, seen, "ShowNameplates true", info, "")
    return out
  end
  local maxCommands = math.max(1, math.min(64, extractNumberAny(text, { "MaxCommands", "maxCommands" }, 16)))
  for _, key in ipairs({ "Commands", "commands", "AdminCommands", "adminCommands" }) do
    for _, object in ipairs(jsonObjectsInArrayForKey(text, key)) do
      dlcAddCommandFromObject(out, seen, object, info, "", maxCommands)
      if #out >= maxCommands then return out end
    end
    for _, commandText in ipairs(jsonTopLevelStringArrayForKey(text, key)) do
      dlcAddCommand(out, seen, commandText, info, "")
      if #out >= maxCommands then return out end
    end
  end
  dlcAddCommandsFromTextBlock(out, seen, extractStringAny(text, { "CommandsText", "commandsText", "AdminCommandsText", "adminCommandsText" }) or "", info, "", maxCommands)
  return out
end

function showNameplatesOnJoinTick()
  local joinText = joinCommandsConfig()
  if joinCommandsEnabledFromText(joinText) ~= true then return end
  local now = os.time()
  local cacheTtl = math.max(5, joinCommandsNumber(joinText, { "PlayerCacheTtlSeconds", "playerCacheTtlSeconds", "CacheTtlSeconds", "cacheTtlSeconds" }, 120, { "ShowNameplatesPlayerCacheTtlSeconds", "showNameplatesPlayerCacheTtlSeconds", "PlayerInfoCacheTtlSeconds", "playerInfoCacheTtlSeconds" }))
  local infos = cachedPlayerInfos(cacheTtl) or {}
  local refreshCooldown = math.max(5, joinCommandsNumber(joinText, { "CacheRefreshCooldownSeconds", "cacheRefreshCooldownSeconds" }, 20, { "ShowNameplatesCacheRefreshCooldownSeconds", "showNameplatesCacheRefreshCooldownSeconds" }))
  if (#infos == 0 or joinCommandsBool(joinText, { "AlwaysRefreshCache", "alwaysRefreshCache" }, false, { "ShowNameplatesAlwaysRefreshCache", "showNameplatesAlwaysRefreshCache" }) == true) and
    joinCommandsBool(joinText, { "RefreshCache", "refreshCache", "EnableCacheRefresh", "enableCacheRefresh" }, true, { "EnableShowNameplatesCacheRefresh", "enableShowNameplatesCacheRefresh" }) == true and
    (now - (SHOW_NAMEPLATES_ON_JOIN_CACHE_REFRESH_AT or 0)) >= refreshCooldown then
    SHOW_NAMEPLATES_ON_JOIN_CACHE_REFRESH_AT = now
    pcall(refreshPlayerInfoCache)
    infos = cachedPlayerInfos(cacheTtl) or PLAYER_INFO_CACHE or infos
  end
  local ttl = math.max(30, joinCommandsNumber(joinText, { "TtlSeconds", "ttlSeconds", "OnJoinTtlSeconds", "onJoinTtlSeconds" }, 3600, { "ShowNameplatesOnJoinTtlSeconds", "showNameplatesOnJoinTtlSeconds" }))
  local retrySeconds = math.max(10, joinCommandsNumber(joinText, { "RetrySeconds", "retrySeconds", "OnJoinRetrySeconds", "onJoinRetrySeconds" }, 60, { "ShowNameplatesOnJoinRetrySeconds", "showNameplatesOnJoinRetrySeconds" }))
  local delayMs = math.max(0, joinCommandsNumber(joinText, { "DelayMs", "delayMs", "OnJoinDelayMs", "onJoinDelayMs" }, 5000, { "ShowNameplatesOnJoinDelayMs", "showNameplatesOnJoinDelayMs" }))
  local maxPerTick = math.max(1, math.min(8, joinCommandsNumber(joinText, { "MaxPerTick", "maxPerTick", "OnJoinMaxPerTick", "onJoinMaxPerTick" }, 2, { "ShowNameplatesOnJoinMaxPerTick", "showNameplatesOnJoinMaxPerTick" })))
  local sentThisTick = 0
  for _, cached in ipairs(infos or {}) do
    if sentThisTick >= maxPerTick then break end
    local info = enrichCommandPlayerIdentity(cached) or cached
    local key = showNameplatesOnJoinPlayerKey(info)
    if key ~= "" and SHOW_NAMEPLATES_ON_JOIN_PENDING[key] ~= true then
      local last = tonumber(SHOW_NAMEPLATES_ON_JOIN_LAST[key] or 0) or 0
      if last <= 0 or (now - last) >= ttl then
        SHOW_NAMEPLATES_ON_JOIN_LAST[key] = now
        SHOW_NAMEPLATES_ON_JOIN_PENDING[key] = true
        sentThisTick = sentThisTick + 1
        deferGame(delayMs, function()
          SHOW_NAMEPLATES_ON_JOIN_PENDING[key] = nil
          local live = resolvePlayerInfo(info.steam, info.name, info, info.runtimeKey) or info
          local currentJoinText = joinCommandsConfig()
          if joinCommandsEnabledFromText(currentJoinText) ~= true then
            appendActionEvent("join_commands_on_join", false, live, "disabled before delivery", '{"disabled":true}')
            return
          end
          local commands = joinCommandsConfiguredCommands(live, currentJoinText)
          local commandDelayMs = math.max(0, joinCommandsNumber(currentJoinText, { "CommandDelayMs", "commandDelayMs", "InterCommandDelayMs", "interCommandDelayMs" }, 600, { "ShowNameplatesCommandDelayMs", "showNameplatesCommandDelayMs" }))
          local index = 1
          local okCount = 0
          local failCount = 0
          local function finishJoinCommands()
            local allOk = okCount > 0 and failCount == 0
            if not allOk then
              SHOW_NAMEPLATES_ON_JOIN_LAST[key] = os.time() - ttl + retrySeconds
            end
            appendActionEvent("join_commands_on_join", allOk, live, allOk and "ok" or "failed",
              '{"commands":' .. tostring(#commands) .. ',"ok":' .. tostring(okCount) .. ',"failed":' .. tostring(failCount) .. ',"retrySeconds":' .. tostring(retrySeconds) .. '}')
          end
          local function runNextJoinCommand()
            if index > #commands then
              finishJoinCommands()
              return
            end
            local command = commands[index]
            local sent, message = adminExec(command, live)
            appendActionEvent("join_command_on_join", sent, live, tostring(message or ""),
              '{"index":' .. tostring(index) .. ',"command":' .. js(command) .. '}')
            if sent then okCount = okCount + 1 else failCount = failCount + 1 end
            index = index + 1
            if index <= #commands and commandDelayMs > 0 then
              deferGame(commandDelayMs, runNextJoinCommand)
            else
              runNextJoinCommand()
            end
          end
          if #commands <= 0 then
            SHOW_NAMEPLATES_ON_JOIN_LAST[key] = os.time() - ttl + retrySeconds
            appendActionEvent("join_commands_on_join", false, live, "no commands configured", '{"commands":0}')
          else
            runNextJoinCommand()
          end
        end)
      end
    end
  end
end

PLAYER_INFO_REFRESH_PENDING = PLAYER_INFO_REFRESH_PENDING or false

if configBool("bridge-safety", { "EnableRuntimeCacheLoop", "enableRuntimeCacheLoop" }, false) then
  PLAYER_INFO_CACHE_INTERVAL_MS = math.max(15000, configNumber("bridge-safety", { "RuntimeCacheIntervalMs", "runtimeCacheIntervalMs" }, 30000))
  safeLoop("player-info-cache", PLAYER_INFO_CACHE_INTERVAL_MS, function()
    if PLAYER_INFO_REFRESH_PENDING then return end
    PLAYER_INFO_REFRESH_PENDING = true
    deferGame(1, function()
      local okRefresh, refreshErr = pcall(refreshPlayerInfoCache)
      PLAYER_INFO_REFRESH_PENDING = false
      if not okRefresh then appendLog("player-info-cache refresh failed: " .. tostring(refreshErr)) end
    end)
  end)
else
  appendLog("loop player-info-cache disabled by bridge-safety")
end

PLAYER_INFO_JOIN_WARMUP_LAST_LOG_AT = PLAYER_INFO_JOIN_WARMUP_LAST_LOG_AT or 0

if configBool("bridge-safety", { "EnableJoinWarmupRuntimeScan", "enableJoinWarmupRuntimeScan" }, true) then
  JOIN_WARMUP_INTERVAL_MS = math.max(1000, configNumber("bridge-safety", { "JoinWarmupIntervalMs", "joinWarmupIntervalMs" }, 1500))
  JOIN_WARMUP_WINDOW_SECONDS = math.max(5, configNumber("bridge-safety", { "JoinWarmupWindowSeconds", "joinWarmupWindowSeconds" }, 25))
  safeLoop("join-warmup-player-cache", JOIN_WARMUP_INTERVAL_MS, function()
    local joinEpoch = latestServerLogJoinEpoch()
    if joinEpoch <= 0 then return end
    local age = os.time() - joinEpoch
    if age < 0 or age > JOIN_WARMUP_WINDOW_SECONDS then return end
    local snapshot = serverLogOnlineSnapshot()
    if snapshot ~= nil and tonumber(snapshot.playerCount or -1) == 0 and snapshot.laterJoin ~= true then return end
    if PLAYER_INFO_REFRESH_PENDING then return end
    PLAYER_INFO_REFRESH_PENDING = true
    deferGame(1, function()
      local okRefresh, refreshErr = pcall(function()
        return refreshPlayerInfoCacheUnchecked("join-warmup")
      end)
      PLAYER_INFO_REFRESH_PENDING = false
      if not okRefresh then
        appendLog("join-warmup player cache refresh failed: " .. tostring(refreshErr))
      elseif (os.clock() - (PLAYER_INFO_JOIN_WARMUP_LAST_LOG_AT or 0)) > 10 then
        PLAYER_INFO_JOIN_WARMUP_LAST_LOG_AT = os.clock()
        appendLog("join-warmup player cache refreshed after join age=" .. tostring(age))
      end
    end)
  end)
else
  appendLog("loop join-warmup-player-cache disabled by bridge-safety")
end

-- P8 deliberately does not restore the old join-warmup scan.  That path could
-- reflect PlayerArray repeatedly every 1.5 seconds and, through the unchecked
-- helper, could eventually fall back to a controller FindAllOf scan.  Instead
-- we observe the already-written SCUM.log and schedule one strict
-- game-thread PlayerArray reads for a settled join.  A later join supersedes
-- the earlier one, coalescing a burst of logins into one cache seed.
POST_JOIN_CACHE_SEED_PENDING_EPOCH = POST_JOIN_CACHE_SEED_PENDING_EPOCH or 0
POST_JOIN_CACHE_SEED_LAST_HANDLED_EPOCH = POST_JOIN_CACHE_SEED_LAST_HANDLED_EPOCH or 0
POST_JOIN_CACHE_SEED_NEXT_AT = POST_JOIN_CACHE_SEED_NEXT_AT or 0
POST_JOIN_CACHE_SEED_ATTEMPTS = POST_JOIN_CACHE_SEED_ATTEMPTS or 0

if configBool("bridge-safety", { "EnablePostJoinPlayerCacheSeed", "enablePostJoinPlayerCacheSeed" }, false) then
  POST_JOIN_CACHE_SEED_INTERVAL_MS = math.max(1000, configNumber("bridge-safety", { "PostJoinPlayerCacheSeedIntervalMs", "postJoinPlayerCacheSeedIntervalMs" }, 2000))
  POST_JOIN_CACHE_SEED_DELAY_SECONDS = math.max(
    configNumber("bridge-safety", { "RuntimeScanJoinSettleSeconds", "runtimeScanJoinSettleSeconds" }, 12) + 3,
    configNumber("bridge-safety", { "PostJoinPlayerCacheSeedDelaySeconds", "postJoinPlayerCacheSeedDelaySeconds" }, 20))
  POST_JOIN_CACHE_SEED_RETRY_SECONDS = math.max(5, configNumber("bridge-safety", { "PostJoinPlayerCacheSeedRetrySeconds", "postJoinPlayerCacheSeedRetrySeconds" }, 15))
  POST_JOIN_CACHE_SEED_MAX_ATTEMPTS = 1
  POST_JOIN_CACHE_SEED_MAX_AGE_SECONDS = math.max(POST_JOIN_CACHE_SEED_DELAY_SECONDS, configNumber("bridge-safety", { "PostJoinPlayerCacheSeedMaxAgeSeconds", "postJoinPlayerCacheSeedMaxAgeSeconds" }, 180))

  appendLog("loop post-join-player-cache-seed enabled intervalMs=" .. tostring(POST_JOIN_CACHE_SEED_INTERVAL_MS) ..
    " delaySeconds=" .. tostring(POST_JOIN_CACHE_SEED_DELAY_SECONDS) ..
    " maxAttempts=" .. tostring(POST_JOIN_CACHE_SEED_MAX_ATTEMPTS) ..
    " route=GameState.PlayerArray-only")

  safeLoop("post-join-player-cache-seed", POST_JOIN_CACHE_SEED_INTERVAL_MS, function()
    -- This loop only reads SCUM.log/cache metadata.  The sole UE-object access
    -- is below and is dispatched by deferGameStrict.
    local joinEpoch = tonumber(latestServerLogJoinEpoch() or 0) or 0
    if joinEpoch <= 0 or joinEpoch == (POST_JOIN_CACHE_SEED_LAST_HANDLED_EPOCH or 0) then return end

    local now = os.time()
    if joinEpoch ~= (POST_JOIN_CACHE_SEED_PENDING_EPOCH or 0) then
      POST_JOIN_CACHE_SEED_PENDING_EPOCH = joinEpoch
      POST_JOIN_CACHE_SEED_ATTEMPTS = 0
      POST_JOIN_CACHE_SEED_NEXT_AT = now + POST_JOIN_CACHE_SEED_DELAY_SECONDS
      appendLog("post-join player cache seed scheduled joinEpoch=" .. tostring(joinEpoch) ..
        " delaySeconds=" .. tostring(POST_JOIN_CACHE_SEED_DELAY_SECONDS))
      return
    end

    local age = now - joinEpoch
    if age < 0 or age > POST_JOIN_CACHE_SEED_MAX_AGE_SECONDS then
      POST_JOIN_CACHE_SEED_LAST_HANDLED_EPOCH = joinEpoch
      POST_JOIN_CACHE_SEED_PENDING_EPOCH = 0
      appendLog("post-join player cache seed skipped stale join age=" .. tostring(age))
      return
    end
    if age < POST_JOIN_CACHE_SEED_DELAY_SECONDS or now < (POST_JOIN_CACHE_SEED_NEXT_AT or 0) then return end
    if PLAYER_INFO_REFRESH_PENDING then return end

    local snapshot = serverLogOnlineSnapshot()
    if snapshot ~= nil and tonumber(snapshot.playerCount or -1) == 0 and snapshot.laterJoin ~= true then
      POST_JOIN_CACHE_SEED_LAST_HANDLED_EPOCH = joinEpoch
      POST_JOIN_CACHE_SEED_PENDING_EPOCH = 0
      appendLog("post-join player cache seed skipped: server log reports no players")
      return
    end

    local attempt = (tonumber(POST_JOIN_CACHE_SEED_ATTEMPTS or 0) or 0) + 1
    POST_JOIN_CACHE_SEED_ATTEMPTS = attempt
    PLAYER_INFO_REFRESH_PENDING = true
    deferGameStrict(1, function()
      if joinEpoch ~= (POST_JOIN_CACHE_SEED_PENDING_EPOCH or 0) then
        PLAYER_INFO_REFRESH_PENDING = false
        appendLog("post-join player cache seed skipped: superseded by a newer join")
        return
      end

      local okRefresh, countOrErr = pcall(function()
        return refreshPlayerInfoCacheFromGameStatePlayerArrayOnly("post-join-cache-seed")
      end)
      PLAYER_INFO_REFRESH_PENDING = false
      local count = tonumber(countOrErr) or 0
      if okRefresh and count > 0 then
        POST_JOIN_CACHE_SEED_LAST_HANDLED_EPOCH = joinEpoch
        POST_JOIN_CACHE_SEED_PENDING_EPOCH = 0
        appendLog("post-join player cache seed complete players=" .. tostring(count) ..
          " attempt=" .. tostring(attempt) .. " route=GameState.PlayerArray-only")
      elseif attempt >= POST_JOIN_CACHE_SEED_MAX_ATTEMPTS then
        POST_JOIN_CACHE_SEED_LAST_HANDLED_EPOCH = joinEpoch
        POST_JOIN_CACHE_SEED_PENDING_EPOCH = 0
        appendLog("post-join player cache seed exhausted attempt=" .. tostring(attempt) ..
          " result=" .. tostring(okRefresh and "empty" or countOrErr))
      else
        POST_JOIN_CACHE_SEED_NEXT_AT = os.time() + POST_JOIN_CACHE_SEED_RETRY_SECONDS
        appendLog("post-join player cache seed retry players=" .. tostring(count) ..
          " attempt=" .. tostring(attempt) .. " retrySeconds=" .. tostring(POST_JOIN_CACHE_SEED_RETRY_SECONDS))
      end
    end, "post-join player cache seed", function(reason)
      PLAYER_INFO_REFRESH_PENDING = false
      if joinEpoch ~= (POST_JOIN_CACHE_SEED_PENDING_EPOCH or 0) then return end
      if attempt >= POST_JOIN_CACHE_SEED_MAX_ATTEMPTS then
        POST_JOIN_CACHE_SEED_LAST_HANDLED_EPOCH = joinEpoch
        POST_JOIN_CACHE_SEED_PENDING_EPOCH = 0
        appendLog("post-join player cache seed exhausted before dispatch attempt=" .. tostring(attempt) ..
          " reason=" .. tostring(reason or ""))
      else
        POST_JOIN_CACHE_SEED_NEXT_AT = os.time() + POST_JOIN_CACHE_SEED_RETRY_SECONDS
        appendLog("post-join player cache seed dispatch deferred attempt=" .. tostring(attempt) ..
          " retrySeconds=" .. tostring(POST_JOIN_CACHE_SEED_RETRY_SECONDS) ..
          " reason=" .. tostring(reason or ""))
      end
    end)
  end)
else
  appendLog("loop post-join-player-cache-seed disabled by bridge-safety")
end

