COMMAND_POLL_BUSY = COMMAND_POLL_BUSY or false
safeAsyncLoop("command-poll", math.max(500, configNumber("bridge-safety", { "CommandPollIntervalMs", "commandPollIntervalMs" }, 1500)), function()
  if COMMAND_POLL_BUSY then return end
  local text = readAll(COMMAND_FILE)
  if text ~= nil and #text > 0 then
    os.remove(COMMAND_FILE)
    COMMAND_POLL_BUSY = true
    local requestId = extractString(text, "id") or ""
    local directOk, directResult = pcall(function() return routeReadOnlyCommand(text) end)
    if directOk and directResult ~= nil then
      writeAll(RESULT_FILE, directResult)
      COMMAND_POLL_BUSY = false
      return
    end
    if not directOk then
      COMMAND_POLL_BUSY = false
      appendLog("command-poll direct readonly task failed: " .. tostring(directResult))
      writeAll(RESULT_FILE, fail("unknown", tostring(directResult), requestId))
      return
    end
    local function rejectCommand(reason)
      if COMMAND_POLL_BUSY ~= true then return end
      COMMAND_POLL_BUSY = false
      appendLog("command-poll skipped: " .. tostring(reason or "game-thread scheduler unavailable"))
      writeAll(RESULT_FILE, fail("unknown", "Команда не выполнена: " .. tostring(reason or "недоступен безопасный планировщик игрового потока"), requestId))
    end
    local queued = deferGameStrict(1, function()
      local okTask, taskErr = pcall(function()
        local okRoute, result = pcall(function() return route(text) end)
        if okRoute then
          if result ~= nil then writeAll(RESULT_FILE, result) end
        else
          appendLog("route error: " .. tostring(result))
          writeAll(RESULT_FILE, fail("unknown", tostring(result), CURRENT_BRIDGE_RESULT_ID))
        end
      end)
      COMMAND_POLL_BUSY = false
      if not okTask then
        appendLog("command-poll task failed: " .. tostring(taskErr))
        writeAll(RESULT_FILE, fail("unknown", tostring(taskErr), CURRENT_BRIDGE_RESULT_ID))
      end
    end, "command-poll", rejectCommand)
    if not queued then rejectCommand("недоступен безопасный планировщик игрового потока") end
  end
end)
